window.DQ=window.DQ||{};DQ["mekorhaim"]={"a":[["דָּנִי פָּקַח אֶת הָעֵינַיִם בַּבֹּקֶר. מָה הַמִּלָּה הָרִאשׁוֹנָה שֶׁהוּא צָרִיךְ לוֹמַר?",["מוֹדֶה אֲנִי","שָׁלוֹם","בֹּקֶר טוֹב"],0,"מִיָּד כְּשֶׁמִּתְעוֹרְרִים אוֹמְרִים ׳מוֹדֶה אֲנִי׳ וּמוֹדִים לְה׳ עַל הַנְּשָׁמָה.","פֶּרֶק א׳, הֲלָכָה ב׳","הַשְׁכָּמַת הַבֹּקֶר"],["נֹעַ רוֹצָה לָדַעַת אִם מֻתָּר לוֹמַר ׳מוֹדֶה אֲנִי׳ עוֹד לִפְנֵי שֶׁנָּטְלָה יָדַיִם. מָה הַתְּשׁוּבָה?",["כֵּן, אֲבָל רַק בַּשַּׁבָּת","כֵּן, כִּי אֵין בּוֹ שֵׁם ה׳","לֹא, חַיָּבִים לִטֹּל יָדַיִם קֹדֶם"],1,"מֻתָּר לוֹמַר ׳מוֹדֶה אֲנִי׳ לִפְנֵי נְטִילָה, כִּי בַּמִּלִּים הָאֵלֶּה לֹא מַזְכִּירִים אֶת שֵׁם ה׳.","פֶּרֶק א׳, הֲלָכָה ד׳","הַשְׁכָּמַת הַבֹּקֶר"],["תָּמָר שׁוֹאֶלֶת אֶת אִמָּא שֶׁלָּה לָמָּה צָרִיךְ לִטֹּל יָדַיִם בַּבֹּקֶר. מָה אִמָּא עוֹנָה?",["כִּי כָּךְ כָּתוּב בַּסִּפּוּר","כִּי הַיָּדַיִם נָגְעוּ בִּמְקוֹמוֹת מְכֻסִּים בַּלַּיְלָה","כִּי זֶה מְשַׂחֵק עִם מַיִם"],1,"בִּזְמַן הַשֵּׁנָה הַיָּדַיִם נוֹגְעוֹת בִּמְקוֹמוֹת מְכֻסִּים, וְלָכֵן תִּקְּנוּ חֲכָמִים לִטֹּל יָדַיִם בַּבֹּקֶר.","פֶּרֶק ב׳, הֲלָכָה א׳","הַשְׁכָּמַת הַבֹּקֶר"],["יוֹסִי נוֹטֵל יָדַיִם וְחוֹשֵׁב מָה כְּדַאי לְכַוֵּן בָּרֶגַע הַזֶּה. מָה נָכוֹן?",["אֵין צֹרֶךְ בְּשׁוּם כַּוָּנָה","לְכַוֵּן שֶׁהוּא מֵכִין עַצְמוֹ לַעֲבוֹדַת הַבּוֹרֵא","לְכַוֵּן עַל הַמִּשְׂחָק שֶׁל הַיּוֹם"],1,"רָאוּי לְכַוֵּן שֶׁאָנוּ מְכִינִים אֶת עַצְמֵנוּ לַעֲבוֹדַת ה׳, כְּמוֹ הַכֹּהֲנִים שֶׁנָּטְלוּ יָדַיִם לִפְנֵי הָעֲבוֹדָה.","פֶּרֶק ב׳, הֲלָכָה ב׳","הַשְׁכָּמַת הַבֹּקֶר"],["אוֹרִי מְסַפֵּר לְחָבֵר אֵיךְ נוֹטְלִים יָדַיִם נָכוֹן. מָה הַסֵּדֶר?",["שׁוֹפְכִים פַּעַם אַחַת עַל כָּל יָד","שׁוֹפְכִים לְסֵרוּגִין שָׁלוֹשׁ פְּעָמִים עַל כָּל יָד","שׁוֹפְכִים רַק עַל יָד יְמִין"],1,"נוֹטְלִים אֶת הַנַּטְלָה בְּיָד יְמִין, מַעֲבִירִים לִשְׂמֹאל, וְכָךְ חוֹזְרִים חֲלִיפוֹת עַד שֶׁכָּל יָד נִשְׁטֶפֶת שָׁלוֹשׁ פְּעָמִים.","פֶּרֶק ב׳, הֲלָכָה ד׳","הַשְׁכָּמַת הַבֹּקֶר"],["שִׁירָה מִתְעוֹרֶרֶת וְנִזְכֶּרֶת שֶׁה׳ רוֹאֶה אוֹתָהּ תָּמִיד. אֵיזֶה פָּסוּק מְבַטֵּא רַעְיוֹן זֶה?",["שִׁוִּיתִי ה׳ לְנֶגְדִּי תָמִיד","שְׁמַע יִשְׂרָאֵל","בְּרֵאשִׁית בָּרָא אֱלֹהִים"],0,"הַפָּסוּק ׳שִׁוִּיתִי ה׳ לְנֶגְדִּי תָמִיד׳ מְלַמֵּד שֶׁה׳ נִמְצָא לְפָנֵינוּ בְּכָל רֶגַע.","פֶּרֶק א׳, הֲלָכָה א׳","הַשְׁכָּמַת הַבֹּקֶר"],["רוֹן יָכוֹל לִבְרֵךְ מִיָּד אַחֲרֵי הַנְּטִילָה הָרִאשׁוֹנָה בַּבֹּקֶר?",["רַק בְּיוֹם שִׁשִּׁי","לֹא, כִּי עוֹד לֹא הִתְלַבֵּשׁ וְלֹא הִתְפַּנָּה","כֵּן, תָּמִיד"],1,"בְּרוֹב הַמִּקְרִים אִי אֶפְשָׁר לְבָרֵךְ מִיָּד, כִּי צָרִיךְ קֹדֶם לְהִתְפַּנּוֹת וּלְהִתְלַבֵּשׁ.","פֶּרֶק ב׳, הֲלָכָה ה׳","הַשְׁכָּמַת הַבֹּקֶר"],["לִפְנֵי שֶׁמְּבָרְכִים ׳עַל נְטִילַת יָדַיִם׳ בַּפַּעַם הַשְּׁנִיָּה, מָה עוֹד כְּדַאי לַעֲשׂוֹת?",["לָשִׁיר שִׁיר","לִשְׁטֹף אֶת הַפֶּה","לֶאֱכֹל מַשֶּׁהוּ מָתוֹק"],1,"רָאוּי לִשְׁטֹף אֶת הַפֶּה לִפְנֵי הַבְּרָכָה, כְּדֵי לְהַזְכִּיר אֶת שֵׁם ה׳ בִּקְדֻשָּׁה וּבְטָהֳרָה.","פֶּרֶק ב׳, הֲלָכָה ה׳","הַשְׁכָּמַת הַבֹּקֶר"],["אַחֲרֵי אֵיזֶה מַעֲשֶׂה מְבָרְכִים אֶת בִּרְכַּת ״אֲשֶׁר יָצַר״?",["אַחֲרֵי אֲכִילַת לֶחֶם","אַחֲרֵי יְצִיאָה מִשֵּׁרוּתִים וּנְטִילַת יָדַיִם","לִפְנֵי הֲלִיכָה לִישׁוֹן"],1,"לְאַחַר עֲשִׂיַּת הַצְּרָכִים נוֹטְלִים יָדַיִם (בְּלִי בְּרָכָה עַל הַנְּטִילָה) וּמְבָרְכִים ״אֲשֶׁר יָצַר״.","פֶּרֶק ג׳, הֲלָכָה ב׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["עַל מָה בִּכְלָל מוֹדִים בְּבִרְכַּת ״אֲשֶׁר יָצַר״?",["עַל טַעַם הַמָּזוֹן","עַל יְרִידַת הַגֶּשֶׁם","עַל כָּךְ שֶׁה׳ בָּרָא אֶת גּוּף הָאָדָם בְּחָכְמָה נִפְלָאָה"],2,"בַּבְּרָכָה אָנוּ מְשַׁבְּחִים אֶת ה׳ עַל שֶׁבָּרָא אֶת הָאָדָם בְּחָכְמָה וְנָתַן בּוֹ ״נְקָבִים נְקָבִים חֲלוּלִים חֲלוּלִים״ הַפּוֹעֲלִים כָּרָאוּי.","פֶּרֶק ג׳, הֲלָכָה א׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["בְּאֵיזֶה זְמַן בַּיּוֹם מְבָרְכִים אֶת בִּרְכַּת ״אֲשֶׁר יָצַר״?",["רַק בַּיּוֹם","גַּם בַּיּוֹם וְגַם בַּלַּיְלָה","רַק בַּלַּיְלָה"],1,"בְּרָכָה זוֹ נֶאֱמֶרֶת בְּכָל עֵת שֶׁצָּרִיךְ, בֵּין בַּיּוֹם וּבֵין בַּלַּיְלָה.","פֶּרֶק ג׳, הֲלָכָה ג׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["מִישֶׁהוּ שָׁכַח לְבָרֵךְ ״אֲשֶׁר יָצַר״ מִיָּד. עַד כַּמָּה זְמַן הוּא עֲדַיִן יָכוֹל לְבָרֵךְ?",["עַד יוֹם שָׁלֵם","אֵינוֹ יָכוֹל לְבָרֵךְ בִּכְלָל","עַד כַּחֲצִי שָׁעָה"],2,"מִי שֶׁשָּׁכַח לְבָרֵךְ מִיָּד יָכוֹל עֲדַיִן לְבָרֵךְ עַד כַּחֲצִי שָׁעָה לְאַחַר מִכֵּן.","פֶּרֶק ג׳, הֲלָכָה ד׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["אֵיזוֹ בְּרָכָה אָנוּ אוֹמְרִים לִפְנֵי שֶׁמַּתְחִילִים לִלְמֹד תּוֹרָה?",["בִּרְכַּת אֲשֶׁר יָצַר","בִּרְכוֹת הַתּוֹרָה","בִּרְכַּת הַמָּזוֹן"],1,"לִפְנֵי לִמּוּד תּוֹרָה יֵשׁ לְבָרֵךְ אֶת בִּרְכוֹת הַתּוֹרָה.","פֶּרֶק ד׳, הֲלָכָה ב׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["כַּמָּה בְּרָכוֹת יֵשׁ בְּ״בִּרְכוֹת הַתּוֹרָה״?",["שְׁתֵּי בְּרָכוֹת","שָׁלוֹשׁ בְּרָכוֹת","בְּרָכָה אַחַת בִּלְבַד"],1,"בִּרְכוֹת הַתּוֹרָה כּוֹלְלוֹת שָׁלוֹשׁ בְּרָכוֹת נִפְרָדוֹת.","פֶּרֶק ד׳, הֲלָכָה א׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["כַּמָּה פְּעָמִים בַּיּוֹם צָרִיךְ לְבָרֵךְ אֶת בִּרְכוֹת הַתּוֹרָה?",["שָׁלוֹשׁ פְּעָמִים בַּיּוֹם","פַּעַם אַחַת בַּבֹּקֶר, וְדַיי לְכָל הַיּוֹם","לִפְנֵי כָּל שִׁעוּר תּוֹרָה"],1,"מִי שֶׁבֵּרֵךְ בַּבֹּקֶר אֵינוֹ צָרִיךְ לַחֲזֹר וּלְבָרֵךְ שׁוּב בְּמֶשֶׁךְ אוֹתוֹ הַיּוֹם.","פֶּרֶק ד׳, הֲלָכָה ג׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["אֵיזוֹ בְּרָכָה אוֹמְרִים כְּשֶׁשּׁוֹמְעִים אֶת קוֹל הַתַּרְנְגוֹל?",["מַלְבִּישׁ עֲרֻמִּים","הַנּוֹתֵן לַשֶּׂכְוִי בִינָה","רוֹקַע הָאָרֶץ עַל הַמַּיִם"],1,"כְּשֶׁשּׁוֹמְעִים אֶת הַתַּרְנְגוֹל מְבָרְכִים ״הַנּוֹתֵן לַשֶּׂכְוִי בִינָה״, עַל הַבִּינָה שֶׁה׳ נָתַן לוֹ לְהַבְדִּיל בֵּין יוֹם לָלַיְלָה","פֶּרֶק ה׳, הֲלָכָה א׳","בִּרְכוֹת הַשַּׁחַר"],["אֵיזוֹ בְּרָכָה אוֹמְרִים כְּשֶׁנּוֹעֲלִים נַעֲלַיִם?",["זוֹקֵף כְּפוּפִים","שֶׁעָשָׂה לִי כָּל צָרְכִּי","עוֹטֵר יִשְׂרָאֵל בְּתִפְאָרָה"],1,"כְּשֶׁנּוֹעֲלִים נַעֲלַיִם מְבָרְכִים ״שֶׁעָשָׂה לִי כָּל צָרְכִּי״, עַל כָּל הַדְּבָרִים הַקְּטַנִּים שֶׁה׳ מְסַפֵּק לָנוּ","פֶּרֶק ה׳, הֲלָכָה א׳","בִּרְכוֹת הַשַּׁחַר"],["לָמָּה גַּם מִי שֶׁעִוֵּר מְבָרֵךְ אֶת בִּרְכַּת ״פּוֹקֵחַ עִוְרִים״?",["כִּי זוֹ הוֹדָאָה כְּלָלִית לְה׳ עַל כָּל בְּנֵי הָאָדָם","כִּי הוּא חַיָּב לְהַעֲמִיד פָּנִים שֶׁהוּא רוֹאֶה","כִּי אֵין לוֹ בְּרָכָה אַחֶרֶת לוֹמַר"],0,"בִּרְכוֹת הַשַּׁחַר אֵינָן הוֹדָאָה פְּרָטִית אֶלָּא הוֹדָאָה כְּלָלִית לְה׳ עַל שֶׁהוּא מְסַפֵּק אֶת צָרְכֵי כָּל בְּנֵי הָאָדָם","פֶּרֶק ה׳, הֲלָכָה ה׳","בִּרְכוֹת הַשַּׁחַר"],["בִּימֵינוּ, מָתַי מְבָרְכִים אֶת כָּל בִּרְכוֹת הַשַּׁחַר?",["כָּל בְּרָכָה בִּזְמַנָּהּ בַּבַּיִת","בָּרֶצֶף, אַחֲרֵי הַלְּבִישָׁה וּנְטִילַת יָדַיִם אוֹ בְּבֵית הַכְּנֶסֶת","רַק בְּסוֹף הַיּוֹם לִפְנֵי הַשֵּׁנָה"],1,"בִּימֵינוּ אֵין מְבָרְכִים כָּל בְּרָכָה בִּזְמַנָּהּ, אֶלָּא מְבָרְכִים אֶת כֻּלָּן בָּרֶצֶף, אַחֲרֵי שֶׁמִּתְלַבְּשִׁים וְנוֹטְלִים יָדַיִם אוֹ בְּבֵית הַכְּנֶסֶת","פֶּרֶק ה׳, הֲלָכָה ג׳","בִּרְכוֹת הַשַּׁחַר"],["אֵיזוֹ בְּרָכָה אוֹמְרִים כְּשֶׁיּוֹשְׁבִים לְאַחַר שֶׁקָּמִים?",["מַתִּיר אֲסוּרִים","אוֹזֵר יִשְׂרָאֵל בִּגְבוּרָה","הַמֵּכִין מִצְעֲדֵי גָבֶר"],0,"כְּשֶׁיּוֹשְׁבִים מְבָרְכִים ״מַתִּיר אֲסוּרִים״, עַל כָּךְ שֶׁהַגּוּף מְשֻׁחְרָר לָזוּז אַחֲרֵי הַשֵּׁנָה","פֶּרֶק ה׳, הֲלָכָה א׳","בִּרְכוֹת הַשַּׁחַר"],["מַדּוּעַ בְּרָכוֹת הַשַּׁחַר נִקְרָאוֹת ״נִסִּים שֶׁבְּכָל יוֹם״?",["כִּי הֵן עַל דְּבָרִים פְּשׁוּטִים שֶׁה׳ עוֹשֶׂה עִמָּנוּ כָּל יוֹם מֵחָדָשׁ","כִּי אֶפְשָׁר לִרְאוֹת אוֹתָן בָּעֵינַיִם בְּאֹפֶן מְיֻחָד","כִּי הֵן קוֹרוֹת רַק פַּעַם בַּשָּׁנָה"],0,"אַף עַל פִּי שֶׁהַבְּרָכוֹת עַל דְּבָרִים פְּשׁוּטִים, גַּם הֵם נִסִּים שֶׁה׳ עוֹשֶׂה עִמָּנוּ בְּכָל יוֹם","פֶּרֶק ה׳, הֲלָכָה ב׳","בִּרְכוֹת הַשַּׁחַר"],["כַּמָּה בְּרָכוֹת צָרִיךְ אָדָם לְבָרֵךְ בְּכָל יוֹם לְפָחוֹת?",["אֶלֶף בְּרָכוֹת","עֶשֶׂר בְּרָכוֹת","מֵאָה בְּרָכוֹת"],2,"יֵשׁ לְבָרֵךְ בְּכָל יוֹם מֵאָה בְּרָכוֹת לְפָחוֹת, וְאֶפְשָׁר לְהַגִּיעַ לְכָךְ דֶּרֶךְ כָּל הַבְּרָכוֹת שֶׁל הַיּוֹם","פֶּרֶק ה׳, הֲלָכָה ח׳","בִּרְכוֹת הַשַּׁחַר"],["מַה זוֹכֶה מִי שֶׁמַּקְדִּים לְהַגִּיעַ לְבֵית הַכְּנֶסֶת?",["אֲרִיכוּת יָמִים","חֲבֵרִים רַבִּים","כֶּסֶף רַב"],0,"אָמְרוּ חֲכָמִים שֶׁכָּל הַמַּשְׁכִּים לְבֵית הַכְּנֶסֶת זוֹכֶה לַאֲרִיכוּת יָמִים.","פֶּרֶק ו׳, הֲלָכָה א׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["כֵּיצַד הוֹלְכִים אֶל בֵּית הַכְּנֶסֶת?",["בָּרִיצָה","בַּעֲגָלָה בִּלְבַד","בִּזְחִילָה"],0,"מִצְוָה לָרוּץ לְבֵית הַכְּנֶסֶת, וְכֵן לְכָל דְּבַר מִצְוָה.","פֶּרֶק ו׳, הֲלָכָה ב׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["אֵיךְ נִכְנָסִים לְבֵית הַכְּנֶסֶת?",["בְּאֵימָה וְיִרְאָה","בָּרִיצָה הַמְּהִירָה בְּיוֹתֵר","בִּקְפִיצוֹת"],0,"אֵין נִכְנָסִים לְבֵית הַכְּנֶסֶת בְּרִיצָה, אֶלָּא הוֹלְכִים בְּאֵימָה וְיִרְאָה, כְּמוֹ בְּבֵית הַמֶּלֶךְ.","פֶּרֶק ו׳, הֲלָכָה ג׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["אֵיזֶה פָּסוּק אוֹמְרִים כְּשֶׁנִּכְנָסִים לְבֵית הַכְּנֶסֶת?",["וַאֲנִי בְּרֹב חַסְדְּךָ אָבוֹא בֵיתֶךָ","שְׁמַע יִשְׂרָאֵל","בָּרוּךְ אַתָּה בְּבֹאֶךָ"],0,"נוֹהֲגִים לִשְׁהוֹת מְעַט וְלוֹמַר ״וַאֲנִי בְּרֹב חַסְדְּךָ אָבוֹא בֵיתֶךָ אֶשְׁתַּחֲוֶה אֶל הֵיכַל קָדְשְׁךָ בְּיִרְאָתֶךָ״.","פֶּרֶק ו׳, הֲלָכָה ד׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מַה אָסוּר לַעֲשׂוֹת בְּבֵית הַכְּנֶסֶת בְּכָל זְמַן?",["לְהִתְפַּלֵּל","לִלְמֹד תּוֹרָה","שְׂחוֹק וְקַלּוּת רֹאשׁ"],2,"אָסוּר לְהִתְנַהֵג בְּבֵית הַכְּנֶסֶת בְּקַלּוּת רֹאשׁ, שְׂחוֹק וְהֵיתוּל, גַּם שֶׁלֹּא בִּשְׁעַת הַתְּפִלָּה.","פֶּרֶק ו׳, הֲלָכָה ה׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מָה מֻתָּר לִשְׁתּוֹת בְּבֵית הַכְּנֶסֶת?",["שׁוֹקוֹ","מַיִם","מִיץ מָתוֹק"],1,"אָסוּר לֶאֱכֹל וְלִשְׁתּוֹת בְּבֵית הַכְּנֶסֶת, אוּלָם מֻתָּר לִשְׁתּוֹת מַיִם.","פֶּרֶק ו׳, הֲלָכָה ו׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מַה עוֹד אָסוּר כְּמוֹ אֲכִילָה וּשְׁתִיָּה בְּבֵית הַכְּנֶסֶת?",["קְרִיאַת תְּפִלָּה","עִשּׁוּן","שִׁירָה בַּתְּפִלָּה"],1,"כְּשֵׁם שֶׁאָסוּר לֶאֱכֹל וְלִשְׁתּוֹת בְּבֵית הַכְּנֶסֶת, כָּךְ אָסוּר לְעַשֵּׁן בּוֹ.","פֶּרֶק ו׳, הֲלָכָה ז׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מָה עוֹד אָסוּר לַעֲשׂוֹת בְּבֵית הַכְּנֶסֶת, אֲפִלּוּ לִזְמַן קָצָר?",["לְהַקְשִׁיב","לֵישֵׁב","לִישֹׁן"],2,"אָסוּר לִישֹׁן בְּבֵית הַכְּנֶסֶת, אֲפִלּוּ שְׁנַת אַרְעַי.","פֶּרֶק ו׳, הֲלָכָה ח׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מָה רָאוּי לֹא לְהַכְנִיס אִתְּךָ לְבֵית הַכְּנֶסֶת?",["תַּרְמִיל וּמַקֵּל הֲלִיכָה","סִדּוּר תְּפִלָּה","כִּפָּה"],0,"רָאוּי שֶׁלֹּא לְהִכָּנֵס לְבֵית הַכְּנֶסֶת בְּמַקְלוֹ וְתַרְמִילוֹ, וּבְכָךְ מְכַבְּדִים אֶת ה׳ וְאֶת בֵּית הַכְּנֶסֶת.","פֶּרֶק ו׳, הֲלָכָה ט׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מָה חָשׁוּב לַעֲשׂוֹת לִפְנֵי הַכְּנִיסָה לְבֵית הַכְּנֶסֶת?",["לָשִׁיר בְּקוֹל רָם","לְנַקּוֹת הֵיטֵב אֶת הַנַּעֲלַיִם","לִרְקֹד בְּשִׂמְחָה"],1,"כְּבוֹד בֵּית הַכְּנֶסֶת הוּא כְּבוֹד שָׁמַיִם, וְלָכֵן יֵשׁ לְנַקּוֹת הֵיטֵב אֶת הַנַּעֲלַיִם לִפְנֵי הַכְּנִיסָה.","פֶּרֶק ו׳, הֲלָכָה י׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["כְּשֶׁיִּשְׂרָאֵל נִכְנָסִים לְבָתֵּי כְּנֵסִיּוֹת וְעוֹנִים ״יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ״, מָה קוֹרֶה?",["אֵין לְכָךְ שׁוּם מַשְׁמָעוּת","זִכְרוֹנָם עוֹלֶה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא","הֵם צָרִיךְ לָצֵאת מִבֵּית הַכְּנֶסֶת"],1,"חֲכָמִים אָמְרוּ שֶׁזִּכְרוֹנָם שֶׁל יִשְׂרָאֵל עוֹלֶה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְהוּא מִתְמַלֵּא רַחֲמִים עֲלֵיהֶם.","פֶּרֶק ח׳, הֲלָכָה א׳","פֶּרֶק ח׳: קַדִּישׁ"],["אֵיזֶה קַדִּישׁ נֶאֱמָר בְּסִיּוּם הַתְּפִלָּה?",["קַדִּישׁ תִּתְקַבֵּל","קַדִּישׁ הַגָּדוֹל","קַדִּישׁ דְּרַבָּנָן"],0,"קַדִּישׁ תִּתְקַבֵּל נֶאֱמָר בְּסִיּוּם הַתְּפִלָּה, וּבוֹ בַּקָּשָׁה שֶׁהַתְּפִלּוֹת יִתְקַבְּלוּ.","פֶּרֶק ח׳, הֲלָכָה ב׳","פֶּרֶק ח׳: קַדִּישׁ"],["מִי אוֹמֵר בְּדֶרֶךְ כְּלָל אֶת ״קַדִּישׁ יָתוֹם״?",["כָּל הַקָּהָל בְּיַחַד בְּקוֹל רָם","יֶלֶד שֶׁאָבִיו אוֹ אִמּוֹ נִפְטְרוּ, לְעִלּוּי נִשְׁמָתָם","רַק הֶחָזָּן שֶׁל בֵּית הַכְּנֶסֶת"],1,"קַדִּישׁ יָתוֹם נֶאֱמָר עַל יְדֵי יָתוֹם (אוֹ אָדָם אַחֵר) לְעִלּוּי נִשְׁמַת אָדָם שֶׁנִּפְטַר.","פֶּרֶק ח׳, הֲלָכָה ב׳","פֶּרֶק ח׳: קַדִּישׁ"],["אַחֲרֵי אֵיזֶה לִמּוּד נֶאֱמָר ״קַדִּישׁ דְּרַבָּנָן״?",["אֲרוּחַת עֶרֶב","לִמּוּד תּוֹרָה שֶׁבְּעַל פֶּה","טִיּוּל בַּשָּׂדֶה"],1,"קַדִּישׁ דְּרַבָּנָן נֶאֱמָר לְאַחַר לִמּוּד תּוֹרָה שֶׁבְּעַל פֶּה.","פֶּרֶק ח׳, הֲלָכָה ב׳","פֶּרֶק ח׳: קַדִּישׁ"],["הַאִם מֻתָּר לוֹמַר אֶת הַקַּדִּישׁ יַחַד עִם הֶחָזָּן בְּאוֹתָהּ נְקֻדָּה?",["רַק בְּיוֹם שַׁבָּת מֻתָּר","כֵּן, תָּמִיד עָדִיף יַחַד","לֹא, צָרִיךְ לִשְׁמֹעַ מֵהֶחָזָּן וְלַעֲנוֹת אַחֲרָיו"],2,"אֵין לוֹמַר אֶת הַקַּדִּישׁ יַחַד עִם הֶחָזָּן, אֶלָּא שׁוֹמְעִים מִמֶּנּוּ וְעוֹנִים אַחֲרָיו.","פֶּרֶק ח׳, הֲלָכָה ג׳","פֶּרֶק ח׳: קַדִּישׁ"],["מָה נוֹהֲגִים קְהִלּוֹת הָאַשְׁכְּנַזִּים בִּשְׁעַת אֲמִירַת הַקַּדִּישׁ?",["לַעֲמֹד","לָשֶׁבֶת","לִכְרֹעַ"],0,"מִנְהַג קְהִלּוֹת הָאַשְׁכְּנַזִּים הוּא לַעֲמֹד בִּשְׁעַת אֲמִירַת הַקַּדִּישׁ.","פֶּרֶק ח׳, הֲלָכָה ד׳","פֶּרֶק ח׳: קַדִּישׁ"],["מַה פֵּרוּשׁ הַמִּלִּים ״וְאִמְרוּ אָמֵן״ בְּסוֹף קְטָעִים בַּקַּדִּישׁ?",["הוֹרָאָה לְסַיֵּם אֶת הַתְּפִלָּה מִיָּד","שֵׁם שֶׁל אֶחָד הַמַּלְאָכִים","בַּקָּשָׁה מֵהַקָּהָל לַעֲנוֹת אָמֵן"],2,"״וְאִמְרוּ אָמֵן״ הִיא בַּקָּשָׁה מֵהַקָּהָל לַעֲנוֹת ״אָמֵן״ לְאַחַר הַמִּלִּים שֶׁל שְׁלִיחַ הַצִּבּוּר.","פֶּרֶק ח׳","פֶּרֶק ח׳: קַדִּישׁ"],["לְמָה דּוֹמָה הַצִּיצִית לְפִי הַהֲלָכָה?",["שָׁעוֹן מְעוֹרֵר","תַּמְרוּר אַזְהָרָה","מַפָּה שֶׁל עִיר"],1,"הַצִּיצִית הִיא מֵעֵין ״תַּמְרוּר אַזְהָרָה״ מִפְּנֵי עֲבֵרוֹת, וְגַם תִּזְכֹּרֶת לְקַיֵּם אֶת כָּל הַמִּצְווֹת – ״סוּר מֵרָע וַעֲשֵׂה טוֹב״.","פֶּרֶק ז׳, הֲלָכוֹת א׳-ב׳","צִיצִית – חֵלֶק א׳"],["אֵיךְ נִקְרֵאת פִּנַּת הַבֶּגֶד?",["כָּנָף","שַׁרְווּל","צַוָּארוֹן"],0,"פִּנַּת הַבֶּגֶד נִקְרֵאת ״כָּנָף״, וְהַחוּטִים שֶׁקּוֹשְׁרִים בָּהּ נִקְרָאִים ״צִיצִית״.","פֶּרֶק ז׳, הֲלָכָה ג׳","צִיצִית – חֵלֶק א׳"],["מָתַי טוֹב לִלְבֹּשׁ טַלִּית קָטָן?",["רַק בַּשַּׁבָּת","רַק בִּזְמַן הַתְּפִלָּה","בְּמֶשֶׁךְ כָּל הַיּוֹם"],2,"טוֹב לִלְבֹּשׁ טַלִּית קָטָן כָּל הַיּוֹם כְּדֵי לִזְכֹּר אֶת הַמִּצְווֹת בְּכָל רֶגַע. וּמִי שֶׁמַּקְפִּיד בְּצִיצִית זוֹכֶה וְרוֹאֶה פְּנֵי שְׁכִינָה.","פֶּרֶק ז׳, הֲלָכוֹת ד׳-ה׳","צִיצִית – חֵלֶק א׳"],["חָתָן מִתְעַטֵּף בְּטַלִּית בַּחֻפָּה בַּלַּיְלָה. מָה הַדִּין?",["מְבָרֵךְ בְּקוֹל רָם","אֵינוֹ מְבָרֵךְ","מְבָרֵךְ פַּעֲמַיִם"],1,"זְמַן מִצְוַת צִיצִית הוּא בַּיּוֹם (״וּרְאִיתֶם אֹתוֹ״), לָכֵן מִי שֶׁמִּתְעַטֵּף בַּלַּיְלָה אֵינוֹ מְבָרֵךְ.","פֶּרֶק ז׳, הֲלָכָה ו׳","צִיצִית – חֵלֶק א׳"],["אֵיזֶה בֶּגֶד פָּטוּר מִצִּיצִית?",["בֶּגֶד שֶׁלּוֹבְשִׁים רַק בַּלַּיְלָה","בֶּגֶד יוֹם עִם אַרְבַּע כְּנָפוֹת","טַלִּית גָּדוֹל"],0,"רַק בֶּגֶד שֶׁרְגִילִים לִלְבֹּשׁ בַּיּוֹם חַיָּב בְּצִיצִית. בֶּגֶד שֶׁלּוֹבְשִׁים רַק בַּלַּיְלָה פָּטוּר.","פֶּרֶק ז׳, הֲלָכָה ז׳","צִיצִית – חֵלֶק א׳"],["מָה עוֹשִׂים לִפְנֵי הַבְּרָכָה עַל הַטַּלִּית?",["מְכַבְּסִים אוֹתָהּ","בּוֹדְקִים אֶת הַחוּטִים","מְקַפְּלִים אוֹתָהּ"],1,"מְעַיְּנִים בַּחוּטִים לִרְאוֹת שֶׁהֵם שְׁלֵמִים וּכְשֵׁרִים, כְּדֵי שֶׁהַבְּרָכָה לֹא תִּהְיֶה לְבַטָּלָה. אַחַר כָּךְ מְבָרְכִים בַּעֲמִידָה וּמִתְעַטְּפִים.","פֶּרֶק ז׳, הֲלָכוֹת ח׳-ט׳","צִיצִית – חֵלֶק א׳"],["אֵיךְ צְרִיכוֹת הַצִּיצִיּוֹת לִהְיוֹת בִּזְמַן הָעֲטִיפָה?",["כֻּלָּן מִלְּפָנִים","כֻּלָּן מֵאָחוֹר","שְׁתַּיִם מִלְּפָנִים וּשְׁתַּיִם מֵאָחוֹר"],2,"מַקְפִּידִים שֶׁשְּׁתֵּי צִיצִיּוֹת יִהְיוּ מִלְּפָנִים וּשְׁתַּיִם מֵאָחוֹר, כְּדֵי שֶׁנִּהְיֶה מְסֻבָּבִים בְּמִצְווֹת.","פֶּרֶק ז׳, הֲלָכָה י׳","צִיצִית – חֵלֶק א׳"],["יֶלֶד לוֹבֵשׁ רַק טַלִּית קָטָן. אֵיזוֹ בְּרָכָה יְבָרֵךְ?",["עַל מִצְוַת צִיצִית","לְהִתְעַטֵּף בַּצִּיצִית","אֵין בְּרָכָה"],0,"מִי שֶׁלּוֹבֵשׁ רַק טַלִּית קָטָן מְבָרֵךְ ״וְצִוָּנוּ עַל מִצְוַת צִיצִית״.","פֶּרֶק ז׳, הֲלָכָה י״א","צִיצִית – חֵלֶק א׳"],["הַטַּלִּית נָפְלָה בְּטָעוּת. מְבָרְכִים שׁוּב?",["כֵּן, תָּמִיד מְבָרְכִים","לֹא, סָפֵק בְּרָכוֹת לְהָקֵל","רַק אִם נָפְלָה לָרִצְפָּה"],1,"יֵשׁ מַחֲלֹקֶת בֵּין הַפּוֹסְקִים, וּלְהֲלָכָה אֵין לְבָרֵךְ מִפְּנֵי שֶׁ״סָּפֵק בְּרָכוֹת לְהָקֵל״.","פֶּרֶק ז׳, הֲלָכָה י״ב","צִיצִית – חֵלֶק א׳"],["אֵיזֶה בֶּגֶד חַיָּב בְּצִיצִית?",["בֶּגֶד עִם שָׁלוֹשׁ כְּנָפוֹת","בֶּגֶד עִם כְּנָפוֹת עֲגֻלּוֹת","בֶּגֶד עִם אַרְבַּע כְּנָפוֹת מְרֻבָּעוֹת"],2,"״עַל אַרְבַּע כַּנְפוֹת כְּסוּתְךָ״ – רַק בֶּגֶד עִם אַרְבַּע כְּנָפוֹת חַיָּב, וְהַכְּנָפוֹת צְרִיכוֹת לִהְיוֹת מְרֻבָּעוֹת וְלֹא עֲגֻלּוֹת.","פֶּרֶק ז׳, הֲלָכוֹת י״ג-י״ד","צִיצִית – חֵלֶק א׳"],["מֵאֵיזֶה בַּד עֲשׂוּיָה טַלִּית שֶׁחַיֶּבֶת בְּצִיצִית מִן הַתּוֹרָה לְכָל הַדֵּעוֹת?",["מֶשִׁי","צֶמֶר רְחֵלִים (כְּבָשִׂים)","כֻּתְנָה"],1,"בֶּגֶד מִצֶּמֶר רְחֵלִים (כְּבָשִׂים) אוֹ מִפִּשְׁתָּן חַיָּב בְּצִיצִית מִן הַתּוֹרָה לְכָל הַדֵּעוֹת. עַל בְּגָדִים מִבַּדִּים אֲחֵרִים יֵשׁ מַחְלֹקֶת.","פֶּרֶק ז׳, הֲלָכָה ט״ו","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["אֵיזוֹ טַלִּית טוֹב לְהִתְעַטֵּף בָּהּ?",["טַלִּית אֲדֻמָּה כֻּלָּהּ","טַלִּית מְנֻקֶּדֶת בִּנְקֻדּוֹת","טַלִּית שֶׁכֻּלָּהּ לְבָנָה"],2,"טוֹב לְהִתְעַטֵּף בְּטַלִּית שֶׁכֻּלָּהּ לְבָנָה. וְיֵשׁ נוֹהֲגִים לְהִתְעַטֵּף בְּטַלִּית שֶׁשְּׁנֵי צְדָדֶיהָ מְעֻטָּרִים בְּפַסִּים שְׁחֹרִים אוֹ בִּצְבָעִים אֲחֵרִים.","פֶּרֶק ז׳, הֲלָכָה ט״ז","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["יוֹסִי קוֹנֶה צִיצִיּוֹת מוּכָנוֹת בַּחֲנוּת. מָה עָלָיו לְבָרֵר?",["שֶׁהַחוּטִים נַעֲשׂוּ לְשֵׁם מִצְוָה","שֶׁהַחוּטִים בְּצֶבַע זָהָב","שֶׁהַחֲבִילָה גְּדוֹלָה וְיָפָה"],0,"צָרִיךְ לִטְווֹת וְלִשְׁזֹר אֶת הַחוּטִים לִשְׁמָם, לְשֵׁם מִצְוַת צִיצִית. וּבִזְמַנֵּנוּ שֶׁקּוֹנִים צִיצִיּוֹת מוּכָנוֹת, צָרִיךְ לְבָרֵר שֶׁהַחוּטִים נַעֲשׂוּ לְשֵׁם מִצְוָה.","פֶּרֶק ז׳, הֲלָכָה י״ח","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["מָה עוֹשִׂים לִפְנֵי שֶׁמַּטִּילִים צִיצִיּוֹת בְּבֶגֶד?",["שָׁרִים שִׁיר שִׂמְחָה","אוֹמְרִים ״הֲרֵינִי מוּכָן לְהָטִיל צִיצִיּוֹת״","שׁוֹטְפִים אֶת הַבֶּגֶד בְּמַיִם"],1,"לִפְנֵי הֲטָלַת הַצִּיצִית בַּבֶּגֶד אוֹמְרִים: ״הֲרֵינִי מוּכָן לְהָטִיל צִיצִיּוֹת אֵלּוּ בְּאַרְבַּע כַּנְפוֹת הַבֶּגֶד הַזֶּה לְשֵׁם מִצְוַת צִיצִית״.","פֶּרֶק ז׳, הֲלָכָה י״ט","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["נִפְסַק (נִקְרַע) חוּט אֶחָד מִשְּׁמוֹנַת חוּטֵי הַצִּיצִית. מָה הַדִּין?",["הַצִּיצִית פְּסוּלָה","צָרִיךְ לִזְרֹק אֶת הַטַּלִּית","הַצִּיצִית כְּשֵׁרָה"],2,"אִם נִפְסַק אֶחָד מִשְּׁמוֹנַת חוּטֵי הַצִּיצִית – הַצִּיצִית כְּשֵׁרָה. וְיֵשׁ שֶׁמַּקְפִּידִים שֶׁלֹּא יֶחְסַר אַף חוּט אֶחָד מִשְּׁלוֹשִׁים וּשְׁנַיִם חוּטֵי הַצִּיצִית.","פֶּרֶק ז׳, הֲלָכָה כ׳","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["מָה נוֹהֲגִים הַמְדַקְדְּקִים בְּמִצְווֹת לַעֲשׂוֹת בְּחוּטֵי צִיצִית שֶׁנִּקְרְעוּ?",["גּוֹנְזִים אוֹתָם","מְשַׂחֲקִים בָּהֶם","קוֹשְׁרִים בָּהֶם חֲבִילוֹת"],0,"הַמְדַקְדְּקִים בְּמִצְווֹת נוֹהֲגִים לִגְנֹז חוּטֵי צִיצִית שֶׁנִּקְרְעוּ, וְהַמַּחְמִיר בָּזֶה תָּבוֹא עָלָיו בְּרָכָה.","פֶּרֶק ז׳, הֲלָכָה כ״ב","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["יֵשׁ לְדָוִד טַלִּית יְשָׁנָה שֶׁהִתְבַּלְּתָה. מָה אָסוּר לוֹ לַעֲשׂוֹת בָּהּ?",["לְקַפֵּל אוֹתָהּ וְלִשְׁמֹר בָּאָרוֹן","לְנַגֵּב בָּהּ אֶת הָרִצְפָּה","לְהַנִּיחַ אוֹתָהּ בְּשַׂקִּית נְקִיָּה"],1,"טַלִּיתוֹת שֶׁהִתְבַּלּוּ אֵינָן חַיָּבוֹת בִּגְנִיזָה, אֲבָל אָסוּר לְהִשְׁתַּמֵּשׁ בָּהֶן תַּשְׁמִישׁ מְגֻנֶּה, כְּמוֹ לְנַגֵּב בָּהֶן רִצְפָּה.","פֶּרֶק ז׳, הֲלָכָה כ״ג","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["עַל אֵיזוֹ טַלִּית אֶפְשָׁר לְבָרֵךְ לְכָל הַדֵּעוֹת?",["טַלִּית שֶׁשָּׁאַלְתִּי מֵחָבֵר","טַלִּית שֶׁל בֵּית הַכְּנֶסֶת לָאוֹרְחִים","מַגֶּבֶת לְבָנָה גְּדוֹלָה"],1,"לְכָל הַדֵּעוֹת מְבָרְכִים עַל טַלִּיתוֹת שֶׁל בֵּית הַכְּנֶסֶת שֶׁמְּיֻעָדוֹת לָאוֹרְחִים. עַל טַלִּית שְׁאוּלָה יֵשׁ מַחֲלֹקֶת, וְרָאוּי לְהִמָּנַע מִמֶּנָּה.","פֶּרֶק ז׳, הֲלָכָה כ״ד","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["יְהוּדִי שָׁאַל טַלִּית רַק כְּדֵי לַעֲלוֹת לַתּוֹרָה. הַאִם יְבָרֵךְ עָלֶיהָ?",["כֵּן, בְּקוֹל רָם","רַק אִם הַטַּלִּית חֲדָשָׁה","לֹא, זֶה לִכְבוֹד הַתּוֹרָה"],2,"הַשּׁוֹאֵל טַלִּית כְּדֵי לַעֲלוֹת לַתּוֹרָה אֵינוֹ מְבָרֵךְ, כִּי מַטְּרָתוֹ הִיא כְּבוֹד הַתּוֹרָה וּכְבוֹד הַצִּבּוּר.","פֶּרֶק ז׳, הֲלָכָה כ״ה","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מָתַי זְמַן מִצְוַת צִיצִית? (בִּגְלַל זֶה נָשִׁים פְּטוּרוֹת מִמֶּנָּה)",["בַּיּוֹם","בַּלַּיְלָה","רַק בְּשַׁבָּת"],0,"נָשִׁים פְּטוּרוֹת מִמִּצְוַת צִיצִית, כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ – זְמַנָּהּ בַּיּוֹם וְלֹא בַּלַּיְלָה.","פֶּרֶק ז׳, הֲלָכָה כ״ו","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מָה צָרִיךְ אַבָּא לִקְנוֹת לִילָדָיו כְּדֵי לְחַנְּכָם בְּמִצְוַת צִיצִית?",["תְּפִלִּין","טַלִּית קָטָן","סֵפֶר תּוֹרָה"],1,"הָאָב צָרִיךְ לִקְנוֹת לִילָדָיו טַלִּית קָטָן כְּדֵי לְחַנְּכָם בַּמִּצְוָה.","פֶּרֶק ז׳, הֲלָכָה כ״ז","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["לְפִי מִנְהַג הַסְּפָרַדִּים, מָתַי קוֹנִים לַיֶּלֶד טַלִּית גָּדוֹל?",["רַק אַחֲרֵי הַחֲתֻנָּה","כְּשֶׁהוּא נוֹלָד","כְּשֶׁהוּא מַתְחִיל לְהִתְפַּלֵּל"],2,"מִנְהַג קְהִלּוֹת הַסְּפָרַדִּים הַטּוֹב: מִיָּד כְּשֶׁיֶּלֶד מַתְחִיל לְהִתְפַּלֵּל קוֹנִים לוֹ טַלִּית גָּדוֹל, כְּמוֹ אָדָם בּוֹגֵר. בְּחֵלֶק מִקְּהִלּוֹת הָאַשְׁכְּנַזִּים – רַק אַחֲרֵי הַחֲתֻנָּה.","פֶּרֶק ז׳, הֲלָכָה כ״ח","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["לְמָה דּוֹמֶה צֶבַע הַתְּכֵלֶת, לְפִי רַבִּי מֵאִיר?",["לַיָּם","לָאֵשׁ","לַחוֹל"],0,"הַתְּכֵלֶת דּוֹמָה לַיָּם, וְיָם דּוֹמֶה לָרָקִיעַ, וְרָקִיעַ לְאֶבֶן סַפִּיר, וְאֶבֶן סַפִּיר לְכִסֵּא הַכָּבוֹד.","פֶּרֶק ז׳, הֲלָכָה כ״ט","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מִמָּה מְפִיקִים אֶת צֶבַע הַתְּכֵלֶת הַכָּשֵׁר?",["מִפְּרָחִים","מֵחִלָּזוֹן","מֵאֲבָנִים"],1,"״תְּכֵלֶת אֵינָהּ כְּשֵׁרָה אֶלָּא מִן הַחִלָּזוֹן. הֵבִיא שֶׁלֹּא מִן הַחִלָּזוֹן – פְּסוּלָה״ (תּוֹסֶפְתָּא).","פֶּרֶק ז׳, הֲלָכָה ל׳","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מָה הַזִּהוּי הַמְּקֻבָּל בְּיוֹתֵר כַּיּוֹם לְחִלָּזוֹן הַתְּכֵלֶת?",["דָּג זָהָב","סַרְטָן אָדֹם","אַרְגְּמוֹן קְהֵה קוֹצִים"],2,"כַּיּוֹם הַזִּהוּי הַמְּקֻבָּל בְּיוֹתֵר הוּא אַרְגְּמוֹן קְהֵה קוֹצִים, וְרַבִּים מְהַדְּרִים לְהַטִּיל פְּתִיל שֶׁצָּבוּעַ מִמֶּנּוּ.","פֶּרֶק ז׳, הֲלָכָה ל״א","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מָתַי הוּא ״עֵת רָצוֹן״, זְמַן שֶׁהַתְּפִלָּה מִתְקַבֶּלֶת יוֹתֵר?",["כְּשֶׁהַצִּבּוּר מִתְפַּלֵּל יַחַד","כְּשֶׁמִּתְפַּלְּלִים לְבַד בַּבַּיִת","כְּשֶׁמִּתְפַּלְּלִים מַהֵר מְאֹד"],0,"חֲזַ״ל לָמְדוּ: ״אֵימָתַי עֵת רָצוֹן? בְּשָׁעָה שֶׁהַצִּבּוּר מִתְפַּלְּלִין״.","פֶּרֶק ט׳, הֲלָכָה א׳","מִנְיַן עֲשָׂרָה"],["בִּתְפִלַּת שְׁמוֹנֶה עֶשְׂרֵה אוֹמְרִים ״סְלַח לָנוּ״. בְּאֵיזוֹ לָשׁוֹן הַבַּקָּשׁוֹת?",["לְשׁוֹן יָחִיד","לְשׁוֹן רַבִּים","בְּלִי מִלִּים"],1,"גַּם כְּשֶׁאָדָם מִתְפַּלֵּל עַל עַצְמוֹ, הוּא מְשַׁתֵּף אֶת הַצִּבּוּר וּמִתְפַּלֵּל בִּלְשׁוֹן רַבִּים.","פֶּרֶק ט׳, הֲלָכָה ב׳","מִנְיַן עֲשָׂרָה"],["מָה הוּא עִקַּר הַתְּפִלָּה בַּצִּבּוּר?",["לָשִׁיר יַחַד ״אֲדוֹן עוֹלָם״","לָשֶׁבֶת יַחַד בְּבֵית הַכְּנֶסֶת","לְהִתְפַּלֵּל יַחַד תְּפִלַּת עֲמִידָה"],2,"עִקַּר תְּפִלָּה בַּצִּבּוּר הוּא כְּשֶׁמִּתְפַּלְּלִים תְּפִלַּת עֲמִידָה יַחַד, וְלָכֵן מִשְׁתַּדְּלִים לְהַגִּיעַ בַּזְּמַן.","פֶּרֶק ט׳, הֲלָכָה ג׳","מִנְיַן עֲשָׂרָה"],["דָּוִד אִחֵר לְשַׁחֲרִית. מָה יַעֲשֶׂה כְּדֵי לְהַסְפִּיק תְּפִלַּת עֲמִידָה עִם הַצִּבּוּר?",["יְדַלֵּג עַל חֵלֶק מִפְּסוּקֵי דְזִמְרָה","יִתְפַּלֵּל לְאַט אֶת הַכֹּל","יֵלֵךְ הַבַּיְתָה"],0,"הַמְאַחֵר יְדַלֵּג עַל חֵלֶק מִפְּסוּקֵי דְזִמְרָה וְיֹאמַר ״בָּרוּךְ שֶׁאָמַר״, ״אַשְׁרֵי״ וְ״יִשְׁתַּבַּח״.","פֶּרֶק ט׳, הֲלָכָה ד׳","מִנְיַן עֲשָׂרָה"],["יֵשׁ תִּשְׁעָה מִתְפַּלְּלִים וְעוֹד שְׁלִיחַ צִבּוּר. כַּמָּה יֵשׁ בַּמִּנְיָן?",["תִּשְׁעָה","עֲשָׂרָה","אַחַד עָשָׂר"],1,"שְׁלִיחַ הַצִּבּוּר נֶחְשָׁב לְאֶחָד מֵעֲשֶׂרֶת הָאֲנָשִׁים, וְלָכֵן יֵשׁ מִנְיָן!","פֶּרֶק ט׳, הֲלָכָה ז׳","מִנְיַן עֲשָׂרָה"],["חֲמִשָּׁה בְּתוֹךְ בֵּית הַכְּנֶסֶת וַחֲמִשָּׁה בַּחוּץ. הַאִם הֵם מִצְטָרְפִים לְמִנְיָן?",["כֵּן, כִּי יֵשׁ עֲשָׂרָה","כֵּן, אִם הַדֶּלֶת פְּתוּחָה","לֹא, כִּי הֵם לֹא בְּמָקוֹם אֶחָד"],2,"כָּל הָעֲשָׂרָה צְרִיכִים לִהְיוֹת בְּמָקוֹם אֶחָד. חֶלְקָם בִּפְנִים וְחֶלְקָם בַּחוּץ - אֵינָם מִצְטָרְפִים.","פֶּרֶק ט׳, הֲלָכָה ח׳","מִנְיַן עֲשָׂרָה"],["מֵאֵיזֶה גִּיל נֶעֱרָף נֶחְשָׁב ״גָּדוֹל״ וּמִצְטָרֵף לְמִנְיָן?",["מִגִּיל עֶשֶׂר","מִגִּיל שְׁלוֹשָׁה עָשָׂר","מִגִּיל עֶשְׂרִים"],1,"מִי שֶׁהִגִּיעַ לְיוֹם הֻלַּדְתּוֹ הַשְּׁלוֹשָׁה עָשָׂר - גִּיל בַּר מִצְוָה - נִקְרָא גָּדוֹל וּמִצְטָרֵף לְמִנְיָן.","פֶּרֶק ט׳, הֲלָכָה ט׳","מִנְיַן עֲשָׂרָה"],["עַל אֵיזוֹ יָד שׁוֹפְכִים מַיִם רִאשׁוֹנָה?",["עַל יַד יָמִין","עַל יַד שְׂמֹאל","עַל שְׁתֵּי הַיָּדַיִם יַחַד"],0,"מַחֲזִיקִים אֶת הַנַּטְלָה בְּיַד שְׂמֹאל וְשׁוֹפְכִים עַל יַד יָמִין, וְאַחַר כָּךְ מַעֲבִירִים אֶת הַנַּטְלָה לְיַד יָמִין וְשׁוֹפְכִים עַל יַד שְׂמֹאל.","פֶּרֶק כ״ב, הֲלָכָה ד׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["מֵאֵיזֶה כְּלִי מֻתָּר לִטֹּל יָדַיִם?",["כְּלִי עִם סֶדֶק","כְּלִי שָׁלֵם","כְּלִי עִם חוֹר"],1,"הַכְּלִי שֶׁנּוֹטְלִים מִמֶּנּוּ צָרִיךְ לִהְיוֹת שָׁלֵם. אִם יֵשׁ בּוֹ חוֹר אוֹ סֶדֶק – אֵין נוֹטְלִים מִמֶּנּוּ.","פֶּרֶק כ״ב, הֲלָכָה ז׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["מָה הַסֵּדֶר הַנָּכוֹן אַחֲרֵי שֶׁנָּטַלְנוּ אֶת הַיָּדַיִם?",["קֹדֶם מְנַגְּבִים וְאַחַר כָּךְ מְבָרְכִים","מְבָרְכִים רַק לְמָחֳרָת","קֹדֶם מְבָרְכִים וְאַחַר כָּךְ מְנַגְּבִים"],2,"לְאַחַר הַנְּטִילָה מְבָרְכִים ״עַל נְטִילַת יָדַיִם״, וְרַק אַחַר כָּךְ מְנַגְּבִים אֶת הַיָּדַיִם.","פֶּרֶק כ״ב, הֲלָכָה ו׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["בְּאֵילוּ מַיִם מֻתָּר לִטֹּל יָדַיִם?",["מַיִם שֶׁהַצֶּבַע שֶׁלָּהֶם הִשְׁתַּנָּה","מַיִם צְלוּלִים וּנְקִיִּים","מַיִם שֶׁשָּׁטְפוּ בָּהֶם כֵּלִים"],1,"מַיִם שֶׁמַּרְאֵיהֶם הִשְׁתַּנָּה, וּמַיִם שֶׁנַּעֲשְׂתָה בָּהֶם מְלָאכָה (כְּמוֹ שְׁטִיפַת כֵּלִים), נִפְסְלוּ לִנְטִילָה.","פֶּרֶק כ״ב, הֲלָכָה ט׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["אֵילוּ מַיִם כְּשֵׁרִים לִנְטִילַת יָדַיִם?",["מֵי יָם מְלוּחִים","מַיִם מַסְרִיחִים","מַיִם רְגִילִים וּטְרִיִּים"],2,"מַיִם מְלוּחִים, מַסְרִיחִים אוֹ מָרִים – פְּסוּלִים לִנְטִילַת יָדַיִם.","פֶּרֶק כ״ב, הֲלָכָה י׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["אֵילוּ מַיִם חַמִּים מֻתָּרִים לִנְטִילָה?",["מַיִם חֲמִימִים שֶׁהַיָּד אֵינָהּ סוֹלֶדֶת בָּהֶם","מַיִם רוֹתְחִים שֶׁהַיָּד סוֹלֶדֶת בָּהֶם","רַק מַיִם קְפוּאִים"],0,"מֻתָּר לִטֹּל יָדַיִם בְּמַיִם חַמִּים, בִּתְנַאי שֶׁאֵין הַיָּד סוֹלֶדֶת (נִרְתַּעַת) מֵהֶם.","פֶּרֶק כ״ב, הֲלָכָה י״א","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["בַּת עוֹנֶדֶת טַבַּעַת. מָה עָלֶיהָ לַעֲשׂוֹת לִפְנֵי הַנְּטִילָה?",["לְהַשְׁאִיר אוֹתָהּ אִם הִיא רְפוּיָה","לְסוֹבֵב אוֹתָהּ תּוֹךְ כְּדֵי הַנְּטִילָה","לְהָסִיר אוֹתָהּ מֵהָאֶצְבַּע"],2,"בָּנוֹת שֶׁעוֹנְדוֹת טַבָּעוֹת צְרִיכוֹת לְהָסִיר אוֹתָן לִפְנֵי הַנְּטִילָה, אֲפִלּוּ אִם הֵן רְפוּיוֹת.","פֶּרֶק כ״ב, הֲלָכָה ג׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["כַּמָּה מַיִם צָרִיךְ לְפָחוֹת לִנְטִילַת יָדַיִם?",["רְבִיעִית – כִּמְעַט חֲצִי כּוֹס","טִפָּה אַחַת קְטַנָּה","דְּלִי שָׁלֵם"],0,"הַשִּׁעוּר הוּא רְבִיעִית (87 סמ״ק, מְעַט פָּחוֹת מֵחֲצִי כּוֹס חַד פַּעֲמִית), וְרָאוּי לְהוֹסִיף וְלִטֹּל בְּשֶׁפַע.","פֶּרֶק כ״ב, הֲלָכָה ב׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["מִשֶּׁנִּכְנַס אֲדָר מַרְבִּים בְּשִׂמְחָה. אֵיזוֹ שִׂמְחָה הִיא הַנְּכוֹנָה?",["הוֹלֵלוּת וּפְרִיעַת סֵדֶר","שִׂמְחָה שֶׁל מִצְוָה וְשֶׁבַח לַה׳","עֶצֶב וּשְׁתִיקָה"],1,"הַכַּוָּנָה הִיא לְשִׂמְחָה שֶׁל מִצְוָה וְשֶׁבַח לַה׳ עַל הַנֵּס, וְלֹא חָלִילָה לְהוֹלֵלוּת וְהֶפְקֵרוּת.","פֶּרֶק צ״ב, הֲלָכָה א׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["מָה הַטַּעַם שֶׁכָּל אֶחָד נוֹתֵן בְּדִיּוּק מַחֲצִית הַשֶּׁקֶל?",["כְּדֵי שֶׁיִּהְיֶה לְכֻלָּם חֵלֶק שָׁוֶה בַּקָּרְבָּנוֹת","כְּדֵי שֶׁהֶעָשִׁיר יִתֵּן יוֹתֵר","כְּדֵי שֶׁהֶעָנִי יִהְיֶה פָּטוּר"],0,"טַעַם הַמִּצְוָה הוּא שֶׁיִּהְיֶה לְכָל אָדָם מִיִּשְׂרָאֵל חֵלֶק שָׁוֶה בְּקָרְבְּנוֹת הַצִּבּוּר – לֹא פָּחוֹת וְלֹא יוֹתֵר.","פֶּרֶק צ״ב, הֲלָכָה ב׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["מָה עוֹשִׂים בְּאֶחָד בַּאֲדָר בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם?",["מַקְרִיבִים קָרְבְּנוֹת מִכַּסְפֵּי הַשְּׁקָלִים","גּוֹבִים אֶת הַשְּׁקָלִים מִכֻּלָּם","מַכְרִיזִים שֶׁהִגִּיעַ זְמַן הַשְּׁקָלִים"],2,"בְּא׳ בַּאֲדָר מַכְרִיזִים, בְּט״ו בַּאֲדָר מַתְחִילִים לִגְבּוֹת, וּבְרֹאשׁ חֹדֶשׁ נִיסָן מַתְחִילִים לְהַקְרִיב.","פֶּרֶק צ״ב, הֲלָכָה ג׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["כַּמָּה סִפְרֵי תּוֹרָה מוֹצִיאִים כְּשֶׁרֹאשׁ חֹדֶשׁ אֲדָר חָל בְּשַׁבָּת?",["שְׁנֵי סִפְרֵי תּוֹרָה","שְׁלוֹשָׁה סִפְרֵי תּוֹרָה","סֵפֶר תּוֹרָה אֶחָד"],1,"מוֹצִיאִים שְׁלוֹשָׁה: פָּרָשַׁת הַשָּׁבוּעַ, קְרִיאַת רֹאשׁ חֹדֶשׁ וּפָרָשַׁת שְׁקָלִים.","פֶּרֶק צ״ב, הֲלָכָה ד׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["לְאֵיזוֹ מַטָּרָה רָאוּי לָתֵת אֶת מְעוֹת ״זֵכֶר לְמַחֲצִית הַשֶּׁקֶל״?",["קְנִיַּת מַמְתַּקִּים לְעַצְמִי","קְנִיַּת צַעֲצוּעַ חָדָשׁ","חִזּוּק מוֹסְדוֹת לִמּוּד תּוֹרָה"],2,"רָאוּי לָתֵת מָעוֹת אֵלּוּ לְחִזּוּק מוֹסְדוֹת לִמּוּד תּוֹרָה, וְנִתָּן גַּם לִצְדָקָה, בִּנְיַן הָאָרֶץ וְעוֹד.","פֶּרֶק צ״ב, הֲלָכָה ה׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["מָה צָרִיךְ לוֹמַר בִּזְמַן נְתִינַת הַכֶּסֶף?",["״זֵכֶר לְמַחֲצִית הַשֶּׁקֶל״","״הִנֵּה מַחֲצִית הַשֶּׁקֶל״","״זֶה כֶּסֶף הַקֳּדָשִׁים״"],0,"אָסוּר לוֹמַר שֶׁזֶּה ״מַחֲצִית הַשֶּׁקֶל״ כִּי אָז הַכֶּסֶף נֶאֱסָר כְּכֶסֶף הַקֳּדָשִׁים, אֶלָּא אוֹמְרִים ״זֵכֶר לְמַחֲצִית הַשֶּׁקֶל״.","פֶּרֶק צ״ב, הֲלָכָה ו׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["מָה נוֹתְנִים הַמְּהַדְּרִים?",["מַטְבֵּעַ שֶׁל שֶׁקֶל אֶחָד","כֶּסֶף טָהוֹר בְּמִשְׁקַל כַּעֲשָׂרָה גְּרַם","שְׁטָר שֶׁל מֵאָה שְׁקָלִים"],1,"הַמְּהַדְּרִים נוֹתְנִים לְפִי מִשְׁקַל מַחֲצִית הַשֶּׁקֶל בִּימֵי מֹשֶׁה רַבֵּנוּ, בְּעֵרֶךְ עֲשָׂרָה גְּרַם כֶּסֶף טָהוֹר.","פֶּרֶק צ״ב, הֲלָכָה ז׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["כַּמָּה מַחֲצִיּוֹת נוֹהֲגִים חֵלֶק מֵהַנּוֹתְנִים מַחֲצִית מֵהַמַּטְבֵּעַ הַנָּהוּג?",["מַחֲצִית אַחַת","שְׁתֵּי מַחֲצִיּוֹת","שָׁלוֹשׁ מַחֲצִיּוֹת"],2,"נוֹהֲגִים לָתֵת שָׁלוֹשׁ מַחֲצִיּוֹת, כִּי בְּפָרָשַׁת שְׁקָלִים נֶאֶמְרָה הַמִּלָּה ״תְּרוּמָה״ שָׁלוֹשׁ פְּעָמִים.","פֶּרֶק צ״ב, הֲלָכָה ח׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["בְּיָמֵינוּ, עֲבוּר מִי נוֹהֲגִים לָתֵת ״זֵכֶר לְמַחֲצִית הַשֶּׁקֶל״?",["עֲבוּר כָּל בְּנֵי וּבְנוֹת הַמִּשְׁפָּחָה","רַק עֲבוּר הָאַבָּא","רַק עֲבוּר הַיְּלָדִים הַקְּטַנִּים"],0,"בְּיָמֵינוּ נוֹהֲגִים לָתֵת ״זֵכֶר לְמַחֲצִית הַשֶּׁקֶל״ עֲבוּר כָּל בְּנֵי וּבְנוֹת הַמִּשְׁפָּחָה.","פֶּרֶק צ״ב, הֲלָכָה ט׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["מָתַי קוֹרְאִים אֶת פָּרָשַׁת זָכוֹר בְּבֵית הַכְּנֶסֶת?",["בְּלֵיל הַסֵּדֶר","בַּשַּׁבָּת שֶׁלִּפְנֵי פּוּרִים","בְּרֹאשׁ הַשָּׁנָה"],1,"חֲכָמִים תִּקְּנוּ לְקַיֵּם אֶת מִצְוַת זְכִירַת עֲמָלֵק בַּשַּׁבָּת שֶׁלִּפְנֵי פּוּרִים, כִּי הָמָן הָיָה מִזַּרְעוֹ שֶׁל עֲמָלֵק.","פֶּרֶק צ״ב, הֲלָכָה י׳","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["מִי צָרִיךְ לְכַוֵּן בִּשְׁעַת קְרִיאַת פָּרָשַׁת זָכוֹר?",["רַק הַגַּבַּאי","רַק הַקּוֹרֵא","הַקּוֹרֵא וְגַם הַשּׁוֹמְעִים"],2,"הַקּוֹרֵא יְכַוֵּן לְהוֹצִיא אֶת כָּל הַשּׁוֹמְעִים יְדֵי חוֹבָתָם, וְגַם הַשּׁוֹמְעִים יְכַוְּנוּ לָצֵאת יְדֵי חוֹבָתָם.","פֶּרֶק צ״ב, הֲלָכָה י״א","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["בִּקְהִלּוֹת רַבּוֹת קוֹרְאִים שׁוּב אֶת פָּרָשַׁת זָכוֹר אַחֲרֵי הַתְּפִלָּה. בִּשְׁבִיל מִי?",["עֲבוּר הַחַזָּן בִּלְבַד","עֲבוּר אוֹרְחִים מֵחוּץ לָאָרֶץ","עֲבוּר נָשִׁים שֶׁלֹּא יָכְלוּ לָבוֹא בִּזְמַן הַתְּפִלָּה"],2,"מְקַיְּמִים לְאַחַר הַתְּפִלָּה קְרִיאָה נוֹסֶפֶת עֲבוּר נָשִׁים שֶׁאֵינָן יְכוֹלוֹת לָבוֹא לְבֵית הַכְּנֶסֶת בִּזְמַן הַתְּפִלָּה.","פֶּרֶק צ״ב, הֲלָכָה י״ב","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["מִי חִבֵּר אֶת הַפִּיּוּט ״מִי כָמוֹךָ וְאֵין כָּמוֹךָ״ שֶׁאוֹמְרִים בְּשַׁבָּת זָכוֹר?",["רַבִּי יְהוּדָה הַלֵּוִי","מֹשֶׁה רַבֵּנוּ","הַמֶּלֶךְ אֲחַשְׁוֵרוֹשׁ"],0,"בִּקְהִלּוֹת הַסְּפָרַדִּים אוֹמְרִים בְּשַׁבָּת זָכוֹר אֶת הַפִּיּוּט ״מִי כָמוֹךָ״ שֶׁחִבֵּר רַבִּי יְהוּדָה הַלֵּוִי.","פֶּרֶק צ״ב, הֲלָכָה י״ג","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["אִם י״ג בַּאֲדָר חָל בְּשַׁבָּת – מָתַי מִתְעַנִּים תַּעֲנִית אֶסְתֵּר?",["בְּשַׁבָּת עַצְמָהּ","בְּיוֹם חֲמִישִׁי","בְּיוֹם רִאשׁוֹן"],1,"אִם י״ג בַּאֲדָר חָל בְּשַׁבָּת, מַקְדִּימִים לְהִתְעַנּוֹת בְּיוֹם חֲמִישִׁי.","פֶּרֶק צ״ב, הֲלָכָה י״ד","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["אָדָם בָּרִיא – מָה יַעֲשֶׂה בְּתַעֲנִית אֶסְתֵּר?",["יֹאכַל כָּרָגִיל","יִשְׁתֶּה רַק מַיִם","יִתְעַנֶּה עִם הַצִּבּוּר"],2,"הַבְּרִיאִים יִתְעַנּוּ וְלֹא יִפְרְשׁוּ מִן הַצִּבּוּר.","פֶּרֶק צ״ב, הֲלָכָה ט״ו","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["מִי מֵאֵלֶּה פָּטוּר מִתַּעֲנִית אֶסְתֵּר?",["מוֹכֵר בַּחֲנוּת","הַמּוֹהֵל בְּיוֹם הַבְּרִית","נֶהָג אוֹטוֹבּוּס"],1,"בַּעֲלֵי בְּרִית – אֲבִי הַבֵּן, הַסַּנְדָּק וְהַמּוֹהֵל – פְּטוּרִים מִן הַתַּעֲנִית.","פֶּרֶק צ״ב, הֲלָכָה ט״ז","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["בְּשָׁנָה מְעֻבֶּרֶת – בְּאֵיזֶה חֹדֶשׁ חוֹגְגִים אֶת פּוּרִים?",["אֲדָר הַשֵּׁנִי","אֲדָר הָרִאשׁוֹן","נִיסָן"],0,"בְּשָׁנָה מְעֻבֶּרֶת מְקַיְּמִים אֶת יְמֵי הַפּוּרִים בַּאֲדָר הַשֵּׁנִי, כְּדֵי לִסְמֹךְ גְּאֻלַּת פּוּרִים לִגְאֻלַּת מִצְרַיִם.","פֶּרֶק צ״ב, הֲלָכָה י״ז","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["כַּמָּה פְּעָמִים קוֹרְאִים אֶת הַמְּגִלָּה בְּפוּרִים?",["פַּעַם אַחַת בַּבֹּקֶר","פַּעֲמַיִם: בַּלַּיְלָה וּבַיּוֹם","שָׁלוֹשׁ פְּעָמִים"],1,"קוֹרְאִים אֶת הַמְּגִלָּה פַּעֲמַיִם: פַּעַם בְּלֵיל פּוּרִים וּפַעַם בְּיוֹם פּוּרִים.","פֶּרֶק צ״ג, הֲלָכָה א׳","קְרִיאַת הַמְּגִלָּה"],["אֵיפֹה עִקַּר הַמִּצְוָה לִקְרֹא אֶת הַמְּגִלָּה?",["לְבַד בַּחֶדֶר","בַּשָּׂדֶה בְּשֶׁקֶט","בְּצִבּוּר, בְּבֵית הַכְּנֶסֶת"],2,"עִקַּר הַמִּצְוָה בְּצִבּוּר, כִּי ״בְּרֹב עָם הַדְרַת מֶלֶךְ״, וְכָךְ מִתְפַּרְסֵם הַנֵּס.","פֶּרֶק צ״ג, הֲלָכָה ב׳","קְרִיאַת הַמְּגִלָּה"],["עַל מָה כּוֹתְבִים מְגִלָּה כְּשֵׁרָה?",["עַל קְלָף, בִּדְיוֹ","עַל נְיָר, בְּעֵט","בִּדְפוּס שֶׁל מַדְפֶּסֶת"],0,"כּוֹתְבִים אֶת הַמְּגִלָּה רַק בִּדְיוֹ עַל גְּוִיל אוֹ קְלָף. עַל נְיָר אוֹ בִּדְפוּס – פְּסוּלָה.","פֶּרֶק צ״ג, הֲלָכָה ג׳","קְרִיאַת הַמְּגִלָּה"],["כַּמָּה בְּרָכוֹת מְבָרֵךְ הַקּוֹרֵא לִפְנֵי קְרִיאַת הַמְּגִלָּה?",["בְּרָכָה אַחַת","שְׁתֵּי בְּרָכוֹת","שָׁלוֹשׁ בְּרָכוֹת"],2,"לִפְנֵי הַקְּרִיאָה מְבָרְכִים שָׁלוֹשׁ בְּרָכוֹת: עַל מִקְרָא מְגִלָּה, שֶׁעָשָׂה נִסִּים, וְשֶׁהֶחֱיָנוּ.","פֶּרֶק צ״ג, הֲלָכָה ד׳","קְרִיאַת הַמְּגִלָּה"],["מָה עוֹשֶׂה הַקּוֹרֵא אַחֲרֵי קְרִיאַת הַמְּגִלָּה?",["גּוֹלֵל אֶת הַמְּגִלָּה וּמְבָרֵךְ","מַשְׁאִיר אוֹתָהּ פְּתוּחָה","קוֹרֵא אוֹתָהּ שׁוּב"],0,"אַחֲרֵי הַקְּרִיאָה גּוֹלֵל הַקּוֹרֵא אֶת הַמְּגִלָּה וּמְבָרֵךְ ״הָרָב אֶת רִיבֵנוּ״.","פֶּרֶק צ״ג, הֲלָכָה ה׳","קְרִיאַת הַמְּגִלָּה"],["מָה אוֹמְרִים בִּקְהִלּוֹת הַסְּפָרַדִּים בְּסִיּוּם הַקְּרִיאָה?",["״לְכָה דוֹדִי״","״אָרוּר הָמָן, בָּרוּךְ מָרְדְּכַי״","״שָׁנָה טוֹבָה״"],1,"בִּקְהִלּוֹת הַסְּפָרַדִּים אוֹמְרִים: אָרוּר הָמָן, בָּרוּךְ מָרְדְּכַי... וְגַם חַרְבוֹנָה זָכוּר לַטּוֹב.","פֶּרֶק צ״ג, הֲלָכָה ו׳","קְרִיאַת הַמְּגִלָּה"],["אֵיזֶה פִּיּוּט אוֹמְרִים הָאַשְׁכְּנַזִּים בַּבֹּקֶר אַחֲרֵי הַמְּגִלָּה?",["״אֲדוֹן עוֹלָם״","״מָעוֹז צוּר״","״שׁוֹשַׁנַּת יַעֲקֹב״"],2,"בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים אוֹמְרִים בַּבֹּקֶר ״שׁוֹשַׁנַּת יַעֲקֹב״.","פֶּרֶק צ״ג, הֲלָכָה ז׳","קְרִיאַת הַמְּגִלָּה"],["אֵיךְ קוֹרֵא שְׁלִיחַ הַצִּבּוּר אֶת הַמְּגִלָּה בְּבֵית הַכְּנֶסֶת?",["בַּעֲמִידָה","בִּישִׁיבָה","בִּשְׁכִיבָה"],0,"שְׁלִיחַ הַצִּבּוּר מְבָרֵךְ וְקוֹרֵא בַּעֲמִידָה, מִפְּנֵי כְּבוֹד הַצִּבּוּר.","פֶּרֶק צ״ג, הֲלָכָה ח׳","קְרִיאַת הַמְּגִלָּה"],["מָה עוֹשֶׂה בַּעַל הַקּוֹרֵא לִפְנֵי הַבְּרָכוֹת?",["מְקַפֵּל אֶת הַמְּגִלָּה לְרִבּוּעַ","פּוֹרֵשׂ אֶת כָּל הַמְּגִלָּה כְּמוֹ אִגֶּרֶת","שָׂם אֶת הַמְּגִלָּה בְּתוֹךְ תִּיק"],1,"לִפְנֵי הַבְּרָכוֹת פּוֹשֵׁט (פּוֹרֵשׂ) הַקּוֹרֵא אֶת כָּל הַמְּגִלָּה, כְּדֵי שֶׁתִּהְיֶה כְּאִגֶּרֶת.","פֶּרֶק צ״ג, הֲלָכָה ט׳","קְרִיאַת הַמְּגִלָּה"],["מִתּוֹךְ מָה צָרִיךְ לִקְרֹא כְּדֵי לְהוֹצִיא אֶת הַשּׁוֹמְעִים יְדֵי חוֹבָתָם?",["מִתּוֹךְ דַּף מֻדְפָּס","מִתּוֹךְ מְגִלָּה כְּשֵׁרָה","מִתּוֹךְ סֵפֶר סִפּוּרִים"],1,"הַקּוֹרֵא מִתּוֹךְ מְגִלָּה כְּשֵׁרָה מוֹצִיא אֶת הַשּׁוֹמְעִים, וּבִתְנַאי שֶׁהוּא עַצְמוֹ חַיָּב בַּקְּרִיאָה.","פֶּרֶק צ״ג, הֲלָכָה י׳","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["יֶלֶד לֹא שָׁמַע מִלָּה אַחַת מֵהַמְּגִלָּה. הַאִם יָצָא יְדֵי חוֹבָתוֹ?",["כֵּן, מִלָּה אַחַת לֹא מְשַׁנָּה","רַק אִם שָׁמַע אֶת הַסּוֹף","לֹא יָצָא יְדֵי חוֹבָתוֹ"],2,"אִם הַשּׁוֹמֵעַ לֹא שָׁמַע אֲפִלּוּ מִלָּה אַחַת – לֹא יָצָא יְדֵי חוֹבָתוֹ.","פֶּרֶק צ״ג, הֲלָכָה י״א","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["הָיָה רַעַשׁ וְלֹא שָׁמַעְתָּ כַּמָּה מִלִּים. מִתּוֹךְ מָה תִּקְרָא אוֹתָן בְּפִיךָ?",["מִתּוֹךְ הַחֻמָּשׁ","מִתּוֹךְ עִתּוֹן","מִתּוֹךְ מַחְבֶּרֶת"],0,"מִי שֶׁלֹּא שָׁמַע מִלִּים בִּגְלַל רַעַשׁ – קוֹרֵא אוֹתָן בְּפִיו מִתּוֹךְ הַחֻמָּשׁ.","פֶּרֶק צ״ג, הֲלָכָה י״ב","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["אֵיךְ אוֹמְרִים אֶת שְׁמוֹת עֲשֶׂרֶת בְּנֵי הָמָן?",["לְאַט, עִם הַפְסָקוֹת","בִּנְשִׁימָה אַחַת","בִּלְחִישָׁה שְׁקֵטָה"],1,"אוֹמְרִים אוֹתָם בִּנְשִׁימָה אַחַת, כְּדֵי שֶׁיֵּדְעוּ שֶׁכֻּלָּם נֶהֶרְגוּ וְנִתְלוּ כְּאֶחָד.","פֶּרֶק צ״ג, הֲלָכָה י״ג","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["מִי קוֹרֵא רִאשׁוֹן אֶת אַרְבָּעַת פְּסוּקֵי הַגְּאֻלָּה?",["רַק הַשַּׁמָּשׁ","אַף אֶחָד","כָּל הַצִּבּוּר יַחַד"],2,"כָּל הַצִּבּוּר קוֹרֵא יַחַד אַרְבָּעָה פְּסוּקִים שֶׁל גְּאֻלָּה, וְאַחַר כָּךְ חוֹזֵר עֲלֵיהֶם בַּעַל הַקּוֹרֵא.","פֶּרֶק צ״ג, הֲלָכָה י״ד","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["הַאִם נָשִׁים חַיָּבוֹת בְּמִקְרָא מְגִלָּה?",["כֵּן, הֵן חַיָּבוֹת","לֹא, הֵן פְּטוּרוֹת","רַק בְּשָׁנָה מְעֻבֶּרֶת"],0,"נָשִׁים חַיָּבוֹת בְּמִקְרָא מְגִלָּה, כִּי גַּם הֵן נִצְּלוּ, וְהַנֵּס בָּא בִּזְכוּת מְסִירוּת נַפְשָׁהּ שֶׁל אֶסְתֵּר.","פֶּרֶק צ״ג, הֲלָכָה ט״ו","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["מָה הַמִּנְהָג הַטּוֹב לְגַבֵּי יְלָדִים קְטַנִּים?",["לְהַשְׁאִיר אוֹתָם בַּבַּיִת","לְהָבִיא אוֹתָם לַקְּרִיאָה","לָתֵת לָהֶם לְהַרְעִישׁ"],1,"מִנְהָג טוֹב לְהָבִיא אֶת הַקְּטַנִּים וְהַקְּטַנּוֹת לִקְרִיאַת הַמְּגִלָּה, וּלְהַשְׁגִּיחַ שֶׁלֹּא יַפְרִיעוּ.","פֶּרֶק צ״ג, הֲלָכָה ט״ז","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["בְּאֵיזוֹ דֶּרֶךְ יוֹצְאִים יְדֵי חוֹבָה בִּשְׁמִיעַת הַמְּגִלָּה?",["בָּרַדְיוֹ","בְּהַקְלָטָה","בְּבֵית הַכְּנֶסֶת מֵהַקּוֹרֵא"],2,"אֵין יוֹצְאִים בִּשְׁמִיעָה דֶּרֶךְ רַמְקוֹל אוֹ רַדְיוֹ, אֲפִלּוּ בְּשִׁדּוּר חַי, וְכָל שֶׁכֵּן בְּהַקְלָטָה.","פֶּרֶק צ״ג, הֲלָכָה י״ז","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["בְּאֵיזוֹ בְּרָכָה בַּתְּפִלָּה מוֹסִיפִים ״עַל הַנִּסִּים״?",["בְּבִרְכַּת רְפָאֵנוּ","בְּבִרְכַּת מוֹדִים","בְּבִרְכַּת שִׁמְעַ קוֹלֵנוּ"],1,"מוֹסִיפִים ״עַל הַנִּסִּים״ בְּבִרְכַּת מוֹדִים, וּבְבִרְכַּת הַמָּזוֹן בְּבִרְכַּת הָאָרֶץ. גַּם אִם סְעוּדַת פּוּרִים נִמְשְׁכָה עַד הַלַּיְלָה, אוֹמְרִים ״עַל הַנִּסִּים״, כִּי הוֹלְכִים אַחֲרֵי תְּחִלַּת הַסְּעוּדָה.","פֶּרֶק צ״ד, הֲלָכָה א׳, י״ד","מִצְווֹת יוֹם הַפּוּרִים"],["כַּמָּה מַתָּנוֹת לָאֶבְיוֹנִים צָרִיךְ לָתֵת לְכָל הַפָּחוֹת?",["מַתָּנָה אַחַת לְעָנִי אֶחָד","שְׁתֵּי מַתָּנוֹת לִשְׁנֵי עֲנִיִּים","עֶשֶׂר מַתָּנוֹת לְעָנִי אֶחָד"],1,"בְּיוֹם הַפּוּרִים (וְלֹא בַּלַּיְלָה) חַיָּבִים לָתֵת לְפָחוֹת שְׁתֵּי מַתָּנוֹת לִשְׁנֵי עֲנִיִּים, מַתָּנָה אַחַת לְכָל עָנִי.","פֶּרֶק צ״ד, הֲלָכָה ב׳","מִצְווֹת יוֹם הַפּוּרִים"],["כַּמָּה רָאוּי שֶׁתִּהְיֶה שָׁוָה כָּל מַתָּנָה לְעָנִי?",["מַטְבֵּעַ קָטָן אֶחָד","סוּכָּרִיָּה אַחַת","כְּמוֹ אֲרוּחָה פְּשׁוּטָה, מְנַת פָלָאפֶל"],2,"רָאוּי שֶׁשּׁוֹוִי כָּל מַתָּנָה יִהְיֶה לְפָחוֹת כְּשׁוֹוִי אֲרוּחָה פְּשׁוּטָה, כִּמְנַת פָלָאפֶל וְכַדּוֹמֶה.","פֶּרֶק צ״ד, הֲלָכָה ג׳","מִצְווֹת יוֹם הַפּוּרִים"],["בְּמָה אֶפְשָׁר לָתֵת מַתָּנוֹת לָאֶבְיוֹנִים?",["בְּמַאֲכָלִים אוֹ בְּכֶסֶף","רַק בְּצַעֲצוּעִים","רַק בִּסְפָרִים"],0,"אֶפְשָׁר לְקַיֵּם אֶת הַמִּצְוָה הֵן בִּנְתִינַת מַאֲכָלִים וְהֵן בִּנְתִינַת כֶּסֶף. וְכָל מִי שֶׁפּוֹשֵׁט יָדוֹ לִטֹּל – נוֹתְנִים לוֹ.","פֶּרֶק צ״ד, הֲלָכָה ד׳, ה׳","מִצְווֹת יוֹם הַפּוּרִים"],["מִי שֶׁלֹּא יִהְיֶה בַּבַּיִת בְּפוּרִים, אֵיךְ יְקַיֵּם מַתָּנוֹת לָאֶבְיוֹנִים וּמִשְׁלוֹחַ מָנוֹת?",["יְוַתֵּר עֲלֵיהֶם הַשָּׁנָה","יְמַנֶּה מֵרֹאשׁ שָׁלִיחַ שֶׁיִּתֵּן בִּשְׁמוֹ","יִתֵּן אַחֲרֵי פּוּרִים"],1,"מִי שֶׁאֵינוֹ יָכוֹל לָתֵת בְּיוֹם הַפּוּרִים עַצְמוֹ, יָכוֹל לְמַנּוֹת מֵרֹאשׁ שָׁלִיחַ שֶׁיִּתֵּן בִּשְׁמוֹ בְּיוֹם הַפּוּרִים.","פֶּרֶק צ״ד, הֲלָכָה ו׳, ט׳","מִצְווֹת יוֹם הַפּוּרִים"],["מָה מַרְאֶה מִשְׁלוֹחַ מָנוֹת לְעֻמַּת דִּבְרֵי הָמָן שֶׁהַיְּהוּדִים ״מְפֻזָּר וּמְפֹרָד״?",["שֶׁכָּל אֶחָד דּוֹאֵג רַק לְעַצְמוֹ","שֶׁאוֹהֲבִים מַמְתַּקִּים","שֶׁעַם יִשְׂרָאֵל מְאֻחָד וּמְחֻבָּר"],2,"כְּדֵי לְהַרְאוֹת אֶת טָעוּתוֹ שֶׁל הָמָן, מַרְבִּים בְּפוּרִים אַחְדוּת וְחִבּוּר עַל יְדֵי מִשְׁלוֹחַ מָנוֹת. וְעוֹד – כְּשֶׁכֻּלָּם נוֹתְנִים זֶה לָזֶה, הָעֲנִיִּים אֵינָם מִתְבַּיְּשִׁים לְקַבֵּל.","פֶּרֶק צ״ד, הֲלָכָה ז׳","מִצְווֹת יוֹם הַפּוּרִים"],["כַּמָּה מָנוֹת שׁוֹלְחִים לְחָבֵר אֶחָד בְּמִשְׁלוֹחַ מָנוֹת?",["שְׁתֵּי מָנוֹת","מָנָה אַחַת","אֵין צֹרֶךְ בְּשׁוּם מָנָה"],0,"בְּיוֹם הַפּוּרִים שׁוֹלֵחַ כָּל אֶחָד לַחֲבֵרוֹ וְכָל אַחַת לַחֲבֶרְתָּהּ שְׁתֵּי מָנוֹת שֶׁל מַאֲכָל, וְהַמַּרְבֶּה לִשְׁלֹחַ לְרֵעִים – מְשֻׁבָּח.","פֶּרֶק צ״ד, הֲלָכָה ח׳","מִצְווֹת יוֹם הַפּוּרִים"],["מָה עוֹשִׂים לִפְנֵי שֶׁמַּתְחִילִים אֶת סְעוּדַת פּוּרִים?",["הוֹלְכִים לִישֹׁן","מִתְפַּלְּלִים מִנְחָה וְלוֹמְדִים תּוֹרָה","מְשַׂחֲקִים כַּדּוּרֶגֶל"],1,"מִתְפַּלְּלִים מִנְחָה לִפְנֵי הַסְּעוּדָה, בְּשָׁעָה מֻקְדֶּמֶת, כְּדֵי שֶׁרֹב הַסְּעוּדָה תִּהְיֶה בַּיּוֹם. וְטוֹב לַעֲסֹק בַּתּוֹרָה לִפְנֵי הַסְּעוּדָה.","פֶּרֶק צ״ד, הֲלָכָה י׳, י״א","מִצְווֹת יוֹם הַפּוּרִים"],["מָה רָאוּי לֶאֱכֹל בִּסְעוּדַת פּוּרִים?",["רַק חֲטִיפִים","רַק מָרָק","פַּת וּבָשָׂר בִּסְעוּדָה נָאָה"],2,"רָאוּי לֶאֱכֹל פַּת וּבָשָׂר וּלְהָכִין סְעוּדָה נָאָה כְּפִי הַיְּכֹלֶת, עִם מִשְׁפָּחָה אוֹ חֲבֵרִים, בְּשִׂמְחָה וּבְשִׁירָה. וְאֵין לִשְׁתּוֹת יוֹתֵר מִדַּי, שֶׁלֹּא לְהַגִּיעַ לְהוֹלֵלוּת.","פֶּרֶק צ״ד, הֲלָכָה י״ב, י״ג","מִצְווֹת יוֹם הַפּוּרִים"],["אֵיזוֹ תַּחְפֹּשֶׂת מַתְאִימָה לְפוּרִים?",["תַּחְפֹּשֶׂת צְנוּעָה וּמְשַׂמַּחַת","תַּחְפֹּשֶׂת שֶׁאֵינָהּ צְנוּעָה","תַּחְפֹּשֶׂת שֶׁמַּפְחִידָה וּמְצַעֶרֶת"],0,"נוֹהֲגִים לְהִתְחַפֵּשׂ כְּדֵי לְהַגְבִּיר שִׂמְחָה, וּכְדֵי לִזְכֹּר שֶׁבִּפְנִימִיּוּתָם יִשְׂרָאֵל נִשְׁאָרִים יְהוּדִים. יֵשׁ לְהַקְפִּיד עַל בְּגָדִים צְנוּעִים – זוֹ שִׂמְחָה שֶׁל מִצְוָה.","פֶּרֶק צ״ד, הֲלָכָה ט״ו","מִצְווֹת יוֹם הַפּוּרִים"],["מֶה עָשׂוּ הַיְּהוּדִים בְּי״ד בַּאֲדָר, לְמָחֳרַת הַמִּלְחָמָה (חוּץ מִשּׁוּשַׁן הַבִּירָה)?",["צָמוּ וְהִתְעַנּוּ כָּל הַיּוֹם","עָשׂוּ יוֹם מִשְׁתֶּה וְשִׂמְחָה","יָצְאוּ שׁוּב לְהִלָּחֵם"],1,"בְּכָל הַמְּקוֹמוֹת נִלְחֲמוּ הַיְּהוּדִים בְּי״ג בַּאֲדָר, וּלְמָחֳרָת, בְּי״ד, עָשׂוּ יוֹם מִשְׁתֶּה וְשִׂמְחָה לְהוֹדוֹת לַה׳ עַל הַנִּצָּחוֹן.","פֶּרֶק צ״ה, הֲלָכָה א׳","שְׁנֵי יְמֵי הַפּוּרִים"],["בְּאֵיזֶה תַּאֲרִיךְ מְקַיְּמִים אֶת מִצְווֹת הַפּוּרִים בְּעִיר שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ בִּן נוּן?",["ט״ו בַּאֲדָר","י״ג בַּאֲדָר","י״ד בַּאֲדָר"],0,"בְּעָרִים שֶׁהָיוּ מֻקָּפוֹת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ בִּן נוּן מְקַיְּמִים אֶת כָּל מִצְווֹת הַפּוּרִים בְּט״ו בַּאֲדָר, אֲפִלּוּ אִם כַּיּוֹם אֵין לָהֶן חוֹמָה.","פֶּרֶק צ״ה, הֲלָכָה ב׳","שְׁנֵי יְמֵי הַפּוּרִים"],["בְּעִיר רְגִילָה (״עִיר פְּרָזוֹת״) – מָתַי מְקַיְּמִים אֶת מִצְווֹת הַפּוּרִים?",["ט״ו בַּאֲדָר","ט״ז בַּאֲדָר","י״ד בַּאֲדָר"],2,"בִּשְׁאַר הַמְּקוֹמוֹת, שֶׁלֹּא הָיוּ מֻקָּפִים חוֹמָה, מְקַיְּמִים אֶת מִצְווֹת הַפּוּרִים בְּי״ד בַּאֲדָר.","פֶּרֶק צ״ה, הֲלָכָה ג׳","שְׁנֵי יְמֵי הַפּוּרִים"],["אֵיזוֹ עִיר הִיא הַיְּחִידָה בְּאֶרֶץ יִשְׂרָאֵל שֶׁמְּקַיְּמִים בָּהּ פּוּרִים בְּט״ו בַּאֲדָר בִּלְבַד?",["חֵיפָה","יְרוּשָׁלַיִם","תֵּל אָבִיב"],1,"בְּיָמֵינוּ יְרוּשָׁלַיִם הִיא הָעִיר הַיְּחִידָה שֶׁיָּדוּעַ בְּוַדָּאוּת שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ בִּן נוּן.","פֶּרֶק צ״ה, הֲלָכָה ד׳","שְׁנֵי יְמֵי הַפּוּרִים"],["בְּחֶבְרוֹן יֵשׁ סָפֵק אִם הָיְתָה מֻקֶּפֶת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ. כַּמָּה יָמִים מְקַיְּמִים בָּהּ פּוּרִים?",["יוֹם אֶחָד","שְׁלוֹשָׁה יָמִים","יוֹמַיִם"],2,"בְּעָרִים שֶׁיֵּשׁ סָפֵק אִם הָיוּ מֻקָּפוֹת חוֹמָה, כְּמוֹ חֶבְרוֹן, לוֹד, שִׁילֹה וּטְבֶרְיָה, מְקַיְּמִים אֶת מִצְווֹת הַפּוּרִים יוֹמַיִם.","פֶּרֶק צ״ה, הֲלָכָה ה׳","שְׁנֵי יְמֵי הַפּוּרִים"],["בְּפוּרִים מְשֻׁלָּשׁ בָּעִיר הַמֻּקֶּפֶת חוֹמָה – מָה עוֹשִׂים בְּיוֹם רִאשׁוֹן, ט״ז בַּאֲדָר?",["שׁוֹלְחִים מִשְׁלוֹחֵי מָנוֹת","קוֹרְאִים אֶת הַמְּגִלָּה","מוֹצִיאִים שְׁנֵי סִפְרֵי תּוֹרָה"],0,"בְּיוֹם רִאשׁוֹן, ט״ז בַּאֲדָר, שׁוֹלְחִים מִשְׁלוֹחֵי מָנוֹת וְעוֹשִׂים סְעוּדַת פּוּרִים.","פֶּרֶק צ״ה, הֲלָכָה ו׳","שְׁנֵי יְמֵי הַפּוּרִים"],["בְּפוּרִים מְשֻׁלָּשׁ – בְּאֵיזֶה יוֹם קוֹרְאִים אֶת הַמְּגִלָּה בָּעִיר הַמֻּקֶּפֶת חוֹמָה?",["בְּשַׁבָּת","בְּיוֹם שִׁשִּׁי","בְּיוֹם רִאשׁוֹן"],1,"בְּיוֹם שִׁשִּׁי, י״ד בַּאֲדָר, קוֹרְאִים אֶת הַמְּגִלָּה וְנוֹתְנִים מַתָּנוֹת לָאֶבְיוֹנִים.","פֶּרֶק צ״ה, הֲלָכָה ו׳","שְׁנֵי יְמֵי הַפּוּרִים"],["יְהוֹשֻׁעַ נִצְטַוָּה: \"לֹא יָמוּשׁ סֵפֶר הַתּוֹרָה הַזֶּה מִפִּיךָ\". מָתַי הוֹגִים בַּתּוֹרָה?",["רַק בְּשַׁבָּת","יוֹמָם וָלַיְלָה","רַק בְּחַגִּים"],1,"בְּסֵפֶר יְהוֹשֻׁעַ נֶאֱמַר: \"וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה\".","פֶּרֶק צ״ו, הֲלָכָה א׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["אֵיזוֹ מִצְוָה שְׁקוּלָה כְּנֶגֶד כָּל הַמִּצְווֹת?",["נְטִילַת יָדַיִם","הַדְלָקַת נֵרוֹת","תַּלְמוּד תּוֹרָה"],2,"תַּלְמוּד תּוֹרָה שָׁקוּל כְּנֶגֶד כָּל הַמִּצְווֹת, כִּי הַלִּמּוּד מֵבִיא לְקַיֵּם אֶת הַמִּצְווֹת.","פֶּרֶק צ״ו, הֲלָכָה ב׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["סָבָא זָקֵן מְאוֹד וְכֹחוֹ חַלָּשׁ. הַאִם הוּא עֲדַיִן חַיָּב לִלְמֹד תּוֹרָה?",["כֵּן, עַד יוֹם מוֹתוֹ","לֹא, הוּא פָּטוּר","רַק אִם הוּא עָשִׁיר"],0,"כָּל אִישׁ חַיָּב – גַּם זָקֵן שֶׁתָּשַׁשׁ כֹּחוֹ – וְהַלִּמּוּד נִמְשָׁךְ עַד יוֹם מוֹתוֹ.","פֶּרֶק צ״ו, הֲלָכוֹת ג׳, ה׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["יוֹסִי כְּבָר יוֹדֵעַ אֶת הַהֲלָכָה. הַאִם כְּדַאי לוֹ לְהַמְשִׁיךְ לִלְמֹד?",["לֹא, כְּבָר יוֹדֵעַ","רַק לִפְנֵי מִבְחָן","כֵּן, הַלִּמּוּד עַצְמוֹ מִצְוָה"],2,"מַטְּרַת הַלִּמּוּד אֵינָהּ רַק לָדַעַת אֵיךְ לְקַיֵּם – הַלִּמּוּד עַצְמוֹ נֶחְשָׁב לְמִצְוָה.","פֶּרֶק צ״ו, הֲלָכָה ד׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["הַתּוֹרָה וְתַלְמִידֵי הַחֲכָמִים נִקְרָאִים...",["אוֹרוֹ שֶׁל עוֹלָם","מֶלַח הָאָרֶץ","חוֹמַת הָעִיר"],0,"הַתּוֹרָה הִיא אוֹרוֹ שֶׁל עוֹלָם, וְגַם תַּלְמִידֵי הַחֲכָמִים – כְּאוֹר רוּחָנִי הַמַּדְרִיךְ בְּדֶרֶךְ הָאֱמֶת.","פֶּרֶק צ״ו, הֲלָכָה ו׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["אֵיזֶה כֶּתֶר מוּכָן לְכָל מִי שֶׁרוֹצֶה לִטֹּל אוֹתוֹ?",["כֶּתֶר מַלְכוּת","כֶּתֶר תּוֹרָה","כֶּתֶר כְּהֻנָּה"],1,"כְּהֻנָּה – לְאַהֲרֹן וְזַרְעוֹ, מַלְכוּת – לְדָוִד וְזַרְעוֹ, אֲבָל כֶּתֶר תּוֹרָה – לְכָל יִשְׂרָאֵל.","פֶּרֶק צ״ו, הֲלָכָה ז׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["אֶת מִי חַיָּב אָדָם לְכַבֵּד יוֹתֵר מֵאָבִיו?",["אֶת שְׁכֵנוֹ","אֶת חֲבֵרוֹ","אֶת רַבּוֹ"],2,"אָבִיו הֱבִיאוֹ לְחַיֵּי הָעוֹלָם הַזֶּה, וְרַבּוֹ מְבִיאוֹ לְחַיֵּי הָעוֹלָם הַבָּא.","פֶּרֶק צ״ו, הֲלָכָה ח׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["אִישׁ זָקֵן מֵעַל גִּיל שִׁבְעִים עוֹבֵר לְיַד דָּנִי בְּבֵית הַכְּנֶסֶת. מָה עוֹשֶׂה דָּנִי?",["מַמְשִׁיךְ לָשֶׁבֶת","קָם מִפָּנָיו","יוֹצֵא הַחוּצָה"],1,"\"מִפְּנֵי שֵׂיבָה תָּקוּם\" – וַאֲפִלּוּ בִּשְׁעַת תְּפִלָּה אוֹ לִמּוּד עוֹמְדִים.","פֶּרֶק צ״ו, הֲלָכָה ט׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["אֵיךְ פּוֹנִים בְּכָבוֹד אֶל תַּלְמִיד חָכָם?",["\"הָרַב אָמַר שֶׁ...\"","בְּשֵׁם הַפְּרָטִי","בְּכִנּוּי מַצְחִיק"],0,"אֵין לִקְרֹא לְתַלְמִיד חָכָם בִּשְׁמוֹ הַפְּרָטִי, וְיֵשׁ מְדַבְּרִים אֵלָיו בְּגוּף שְׁלִישִׁי. וְעוֹמְדִים כְּשֶׁהוּא עוֹבֵר בְּד׳ אַמּוֹת.","פֶּרֶק צ״ו, הֲלָכוֹת י׳, י״א","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["חָבֵר מְבַקֵּשׁ מִמְּךָ אֶת הַחֻמָּשׁ שֶׁעַל הַשֻּׁלְחָן. אֵיךְ תַּעֲבִיר לוֹ אוֹתוֹ?",["זוֹרְקִים לוֹ אֶת הַחֻמָּשׁ מֵרָחוֹק","מַגִּישִׁים לוֹ אֶת הַחֻמָּשׁ בַּיָּד בְּכָבוֹד","מַחְלִיקִים אֶת הַחֻמָּשׁ עַל הַשֻּׁלְחָן אֵלָיו"],1,"כַּאֲשֶׁר מַעֲבִירִים סֵפֶר קֹדֶשׁ לְאָדָם אַחֵר – עוֹשִׂים זֹאת בְּצוּרָה מְכֻבֶּדֶת וְלֹא זוֹרְקִים אֶת הַסֵּפֶר.","פֶּרֶק צ״ז, הֲלָכָה א׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["סִדּוּר נָפַל לָרִצְפָּה. מָה נוֹהֲגִים לַעֲשׂוֹת?",["מְרִימִים אוֹתוֹ וּמְנַשְּׁקִים אוֹתוֹ","מַשְׁאִירִים אוֹתוֹ עַל הָרִצְפָּה","דּוֹחֲפִים אוֹתוֹ בָּרֶגֶל הַצִּדָּה"],0,"אִם נָפַל סֵפֶר קֹדֶשׁ לָרִצְפָּה, נוֹהֲגִים לְנַשְּׁקוֹ בְּעֵת שֶׁמְּרִימִים אוֹתוֹ.","פֶּרֶק צ״ז, הֲלָכָה א׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["יֵשׁ לְךָ תְּהִלִּים קָטָן בַּכִּיס, וְאַתָּה רוֹצֶה לְהִכָּנֵס לַשֵּׁרוּתִים. מָה עוֹשִׂים לְכַתְּחִלָּה?",["נִכְנָסִים עִם הַסֵּפֶר בַּיָּד","קוֹרְאִים בּוֹ בִּפְנִים","מַנִּיחִים אֶת הַסֵּפֶר בַּחוּץ"],2,"לְכַתְּחִלָּה אֵין לְהִכָּנֵס לַשֵּׁרוּתִים עִם סֵפֶר קֹדֶשׁ קָטָן בַּכִּיס, וְלָכֵן מַנִּיחִים אוֹתוֹ בַּחוּץ.","פֶּרֶק צ״ז, הֲלָכָה ב׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["אַתָּה בְּמָקוֹם שֶׁהַסֵּפֶר עָלוּל לָלֶכֶת לְאִבּוּד, וְהוּא בְּתוֹךְ תִּיק סָגוּר. מָה הַדִּין?",["אָסוּר לְהִכָּנֵס בְּשׁוּם אֹפֶן","מֻתָּר לְהִכָּנֵס עִם הַתִּיק","צָרִיךְ לְהוֹצִיא אֶת הַסֵּפֶר מֵהַתִּיק"],1,"בִּמְקוֹם חֲשָׁשׁ מֻתָּר לְהִכָּנֵס כְּשֶׁהַסֵּפֶר מְכֻסֶּה בִּשְׁנֵי כִּסּוּיִים, וְכָל שֶׁכֵּן כְּשֶׁהוּא בְּתוֹךְ תִּיק סָגוּר.","פֶּרֶק צ״ז, הֲלָכָה ג׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["אֵיזוֹ חֻלְצָה מַתְאִימָה לְפִי הַהֲלָכָה?",["חֻלְצָה עִם פָּסוּק מֻדְפָּס","חֻלְצָה עִם חֲצִי פָּסוּק","חֻלְצָה בְּלִי פְּסוּקִים"],2,"אֵין לְהַדְפִּיס פְּסוּקִים אוֹ חֶלְקֵי פְּסוּקִים עַל חֻלְצוֹת, כִּי אָסוּר לְהִכָּנֵס אִתָּן לַשֵּׁרוּתִים.","פֶּרֶק צ״ז, הֲלָכָה ד׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["הַשִּׁעוּר נֶעֱצַר לְהַפְסָקָה אֲרֻכָּה. מָה עוֹשִׂים עִם הַגְּמָרָא?",["סוֹגְרִים אֶת הַגְּמָרָא","מַשְׁאִירִים אוֹתָהּ פְּתוּחָה","הוֹפְכִים אוֹתָהּ עַל הַפָּנִים"],0,"כְּשֶׁעוֹשִׂים הַפְסָקָה סוֹגְרִים אֶת הַסֵּפֶר, כִּי אֵין זֶה מְכֻבָּד שֶׁיִּהְיֶה פָּתוּחַ בְּלִי שֶׁלּוֹמְדִים בּוֹ.","פֶּרֶק צ״ז, הֲלָכָה ה׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["אֵיפֹה נָכוֹן לְהַנִּיחַ אֶת הַטֶּלֶפוֹן וְהַקַּלְמָר?",["עַל גַּבֵּי הַחֻמָּשׁ","עַל הַשֻּׁלְחָן לְיַד הַסְּפָרִים","עַל עֲרֵמַת סִפְרֵי הַקֹּדֶשׁ"],1,"אֵין לְהַנִּיחַ סִפְרֵי חֹל, מִשְׁקָפַיִם, קַלְמָר, טֶלֶפוֹן נַיָּד וְכַדּוֹמֶה עַל גַּבֵּי סִפְרֵי קֹדֶשׁ.","פֶּרֶק צ״ז, הֲלָכָה ו׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["אֵיזוֹ עֲרֵמָה מְסֻדֶּרֶת נָכוֹן?",["סִדּוּר לְמַעְלָה וְחֻמָּשׁ לְמַטָּה","מִשְׁנָה לְמַעְלָה וְחֻמָּשׁ לְמַטָּה","חֻמָּשׁ לְמַעְלָה וְסִדּוּר לְמַטָּה"],2,"מַנִּיחִים אֶת הַסֵּפֶר שֶׁקְּדֻשָּׁתוֹ גְּבוֹהָה יוֹתֵר מִלְמַעְלָה – וְחֻמָּשׁ קְדֻשָּׁתוֹ גְּבוֹהָה מִסִּדּוּר.","פֶּרֶק צ״ז, הֲלָכָה ז׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["מָה הַתּוֹרָה אוֹסֶרֶת לַעֲשׂוֹת לְאֶחָד מִשִּׁבְעַת שְׁמוֹת ה׳ הַכְּתוּבִים?",["לִקְרֹא אוֹתוֹ","לִמְחֹק אוֹתוֹ","לִשְׁמֹר אוֹתוֹ"],1,"אָסוּר מִן הַתּוֹרָה לִמְחֹק אֶחָד מִשִּׁבְעַת הַשֵּׁמוֹת, וְהַמְּאַבֵּד שֵׁם פּוֹגֵעַ בִּכְבוֹד שָׁמַיִם.","פֶּרֶק צ״ח, הֲלָכָה א׳","גְּנִיזָה"],["מָה הַדִּין בְּמִי שֶׁמּוֹחֵק אֲפִלּוּ אוֹת אַחַת מִשֵּׁם קָדוֹשׁ?",["עוֹבֵר בְּאִסּוּר תּוֹרָה","מֻתָּר לְגַמְרֵי","רַק מִנְהָג טוֹב לֹא לִמְחֹק"],0,"הַמּוֹחֵק אֲפִלּוּ אוֹת אַחַת מִן הַשֵּׁמוֹת הָאֲסוּרִים בִּמְחִיקָה עוֹבֵר בְּאִסּוּר תּוֹרָה.","פֶּרֶק צ״ח, הֲלָכָה ב׳","גְּנִיזָה"],["אֵיפֹה כְּדַאי לְהַקְפִּיד לֹא לִכְתֹּב שֵׁם ה׳ הָאָסוּר בִּמְחִיקָה?",["בְּסֵפֶר תּוֹרָה","בִּתְפִלִּין","בְּעִתּוֹן אוֹ מִכְתָּב"],2,"יֵשׁ לְהַקְפִּיד לֹא לִכְתֹּב שְׁמוֹת ה׳ בְּעִתּוֹנִים, מִכְתָּבִים וְדַפֵּי מְקוֹרוֹת, כִּי יֵשׁ חֲשָׁשׁ שֶׁיָּבוֹאוּ לִידֵי בִּזָּיוֹן.","פֶּרֶק צ״ח, הֲלָכָה ג׳","גְּנִיזָה"],["הַשֵּׁם ״דָּנִיֵּאל״ כָּתוּב בַּמַּחְבֶּרֶת. מֻתָּר לִמְחֹק אוֹתוֹ?",["אָסוּר לְגַמְרֵי","מֻתָּר, הוּא אֵינוֹ קָדוֹשׁ","רַק אִם הוּא כָּתוּב בְּטָעוּת"],1,"שְׁמוֹת אֲנָשִׁים וּמְקוֹמוֹת שֶׁיֵּשׁ בָּהֶם אוֹתִיּוֹת מִשֵּׁם ה׳ אֵינָם קְדוֹשִׁים. וְגַם שֵׁם שֶׁנִּכְתַּב בְּטָעוּת – מֻתָּר לִמְחֹק.","פֶּרֶק צ״ח, הֲלָכוֹת ד׳-ה׳","גְּנִיזָה"],["בַּמִּשְׁפָּט ״כְּשֶׁאֶהְיֶה גָּדוֹל אֶהְיֶה רוֹפֵא״ – יֵשׁ קְדֻשָּׁה בַּמִּלָּה ״אֶהְיֶה״?",["כֵּן, זֶה שֵׁם קָדוֹשׁ","רַק בְּשַׁבָּת","לֹא, זֶה הֶקְשֵׁר שֶׁל חֹל"],2,"כְּשֶׁמִּלִּים כָּאֵלֶּה מוֹפִיעוֹת בְּהֶקְשֵׁר חֹל – אֵין בָּהֶן קְדֻשָּׁה. וְגַם כִּנּוּיִים כְּמוֹ ׳רַחוּם׳ וְ׳חַנּוּן׳ מֻתָּר לִמְחֹק.","פֶּרֶק צ״ח, הֲלָכוֹת ו׳-ז׳","גְּנִיזָה"],["מֻתָּר לִמְחֹק כְּדֵי לְתַקֵּן טָעוּת בְּסֵפֶר קֹדֶשׁ, בְּמָקוֹם שֶׁאֵין בּוֹ שֵׁם ה׳?",["כֵּן, זֶה תִּקּוּן בְּדֶרֶךְ כָּבוֹד","לֹא, אַף פַּעַם","רַק אִם הַסֵּפֶר יָשָׁן"],0,"חֲכָמִים אָסְרוּ לְאַבֵּד פְּסוּקִים וְסִפְרֵי קֹדֶשׁ בְּדֶרֶךְ בִּזָּיוֹן, אֲבָל לֹא כְּשֶׁהַמְּחִיקָה הִיא לְצֹרֶךְ תִּקּוּן בְּדֶרֶךְ כָּבוֹד.","פֶּרֶק צ״ח, הֲלָכָה ח׳","גְּנִיזָה"],["בְּמָה מַנִּיחִים סֵפֶר תּוֹרָה שֶׁהִתְבַּלָּה לִפְנֵי שֶׁקּוֹבְרִים אוֹתוֹ?",["בְּשַׂקִּית נְיָר","בִּכְלִי חֶרֶס","בְּקֻפְסַת בַּרְזֶל"],1,"סֵפֶר תּוֹרָה שֶׁהִתְבַּלָּה אוֹ נִפְסַל – מַנִּיחִים אוֹתוֹ בִּכְלִי חֶרֶס וְקוֹבְרִים אוֹתוֹ בְּקֶבֶר תַּלְמִיד חָכָם.","פֶּרֶק צ״ח, הֲלָכָה ט׳","גְּנִיזָה"],["שַׂקִּית הַבַּד שֶׁל הַתְּפִלִּין הִתְבַּלְּתָה. לְאָן הִיא הוֹלֶכֶת?",["לַפַּח הָרָגִיל","לְמִחְזוּר בַּד","לִגְנִיזָה"],2,"רְצוּעוֹת, בָּתִּים, קֻפְסְאוֹת וְשַׂקִּית הַבַּד שֶׁל הַתְּפִלִּין שֶׁהִתְבַּלּוּ – חַיָּבִים בִּגְנִיזָה. מְכָלֵי הַגְּנִיזָה נִמְצָאִים בְּבָתֵּי כְּנֶסֶת.","פֶּרֶק צ״ח, הֲלָכוֹת י׳-י״א","גְּנִיזָה"],["מָה עוֹשִׂים בַּעֲלוֹן שַׁבָּת שֶׁאֵין בּוֹ שֵׁם ה׳ אַחֲרֵי שֶׁקָּרְאוּ אוֹתוֹ?",["עוֹטְפִים וְשָׂמִים בְּפַח לְמִחְזוּר נְיָר","קוֹבְרִים בִּכְלִי חֶרֶס","זוֹרְקִים לָרְחוֹב"],0,"אֵין צֹרֶךְ לִגְנֹז עֲלוֹנֵי שַׁבָּת, אֲבָל כִּי יֵשׁ בָּהֶם דִּבְרֵי תּוֹרָה – עוֹטְפִים אוֹתָם וְשָׂמִים בְּפַח לְמִחְזוּר נְיָר. אִם יֵשׁ שֵׁם ה׳ – גּוֹזְרִים אוֹתוֹ לַגְּנִיזָה.","פֶּרֶק צ״ח, הֲלָכוֹת י״ב-י״ג","גְּנִיזָה"],["מָה רָאוּי לְלַמֵּד אֶת הַתַּלְמִידִים לְגַבֵּי הַמַּחְבָּרוֹת שֶׁלָּהֶם?",["לִכְתֹּב רַק בְּעֵט","לֹא לִכְתֹּב בָּהֶן אֶת שִׁבְעַת הַשֵּׁמוֹת","לִגְנֹז כָּל מַחְבֶּרֶת"],1,"רָאוּי לְלַמֵּד אֶת הַתַּלְמִידִים לֹא לִכְתֹּב בְּמַחְבְּרוֹתֵיהֶם אֶת שִׁבְעַת הַשֵּׁמוֹת, וְאָז אֵין צֹרֶךְ לִגְנֹז אֶת הַמַּחְבָּרוֹת.","פֶּרֶק צ״ח, הֲלָכָה י״ד","גְּנִיזָה"],["מָה מֵבִיא קְדֻשָּׁה וְטָהֳרָה לַנֶּפֶשׁ?",["אֲכִילָה מְהִירָה שֶׁל כָּל מַאֲכָל","הַקְפָּדָה שֶׁלֹּא לֶאֱכֹל מַאֲכָלִים אֲסוּרִים","דִּלּוּג עַל אֲרוּחַת הַבֹּקֶר"],1,"חֲכָמִים לָמְדוּ מִן הַפְּסוּקִים שֶׁמִּי שֶׁמַּקְפִּיד שֶׁלֹּא לֶאֱכֹל מַאֲכָלִים אֲסוּרִים מֵבִיא קְדֻשָּׁה וְטָהֳרָה לְנַפְשׁוֹ.","פֶּרֶק צ״ט, הֲלָכָה א׳-ב׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["רָאִיתָ בַּעַל חַיִּים שֶׁאֵינְךָ מַכִּיר. מָה עוֹשִׂים לִפְנֵי שֶׁאוֹכְלִים מִבְּשָׂרוֹ?",["מְנַחֲשִׁים לְפִי הַצֶּבַע שֶׁלּוֹ","אוֹכְלִים בְּלִי לִשְׁאֹל","שׁוֹאֲלִים מֻמְחֶה"],2,"רֹב בְּנֵי הָאָדָם אֵינָם בְּקִיאִים בַּסִּימָנִים, וְלָכֵן אֵין לֶאֱכֹל מִבְּשַׂר בַּעַל חַיִּים לְלֹא שְׁאֵלַת מֻמְחֶה, חוּץ מִמִּינִים יְדוּעִים לַכֹּל כִּטְהוֹרִים.","פֶּרֶק צ״ט, הֲלָכָה ג׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["מָה צָרִיךְ לִהְיוֹת לִבְהֵמָה כְּדֵי שֶׁתִּהְיֶה כְּשֵׁרָה?",["פַּרְסָה שְׁסוּעָה וְהַעֲלָאַת גֵּרָה","כְּנָפַיִם וְנוֹצוֹת","זָנָב אָרֹךְ וּפַרְוָה"],0,"הַתּוֹרָה מַזְכִּירָה שְׁנֵי סִימָנִים: פַּרְסָה שְׁסוּעָה וְהַעֲלָאַת גֵּרָה. רַק בְּהֵמָה שֶׁיֵּשׁ לָהּ אֶת שְׁנֵיהֶם מֻתֶּרֶת בַּאֲכִילָה.","פֶּרֶק צ״ט, הֲלָכָה ד׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["אֵילוּ שְׁנֵי סִימָנִים צְרִיכִים לִהְיוֹת לְדָג כָּשֵׁר?",["זָנָב וְעֵינַיִם","סְנַפִּיר וְקַשְׂקֶשֶׂת","צֶבַע אָדֹם וּפֶה גָּדוֹל"],1,"״כֹּל אֲשֶׁר לוֹ סְנַפִּיר וְקַשְׂקֶשֶׂת... אֹתָם תֹּאכֵלוּ״.","פֶּרֶק צ״ט, הֲלָכָה ה׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["דָּג שֶׁקַּשְׂקַשָּׂיו נָשְׁרוּ כְּשֶׁנִּסָּה לְהֵחָלֵץ מֵרֶשֶׁת – מָה דִּינוֹ?",["אָסוּר לְעוֹלָם","מֻתָּר רַק בְּשַׁבָּת","מֻתָּר לֶאֱכֹל"],2,"מֻתָּר לֶאֱכֹל דָּג שֶׁקַּשְׂקַשָּׂיו נָשְׁרוּ בְּרֶשֶׁת, וְכֵן דָּג צָעִיר מִמִּין שֶׁמְּגַדֵּל קַשְׂקַשִּׂים שֶׁעֲדַיִן לֹא גִּדֵּל אוֹתָם.","פֶּרֶק צ״ט, הֲלָכָה ו׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["אֵיזֶה מַאֲכָל צָרִיךְ בְּדִיקָה יְסוֹדִית מִתּוֹלָעִים לְפִי הַהֲלָכָה?",["צִנְצֶנֶת דְּבַשׁ סְגוּרָה","מֶלַח","חַסָּה וּכְרוּב"],2,"יַרְקוֹת עָלִים כְּמוֹ חַסָּה וּכְרוּב יְדוּעִים כִּנְגוּעִים הַרְבֵּה פְּעָמִים, וְאָסוּר לְאָכְלָם בְּלִי בְּדִיקָה יְסוֹדִית. הַחֲרָקִים מִתְחַבְּאִים הֵיטֵב!","פֶּרֶק צ״ט, הֲלָכָה ז׳-ח׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["מָה עוֹשִׂים לִפְנֵי שֶׁמִּשְׁתַּמְּשִׁים בְּאֹרֶז אוֹ בְּקֶמַח יָשָׁן?",["שׁוֹפְכִים מִיָּד לַסִּיר","בּוֹרְרִים וּמְנַפִּים הֵיטֵב","מְנַעְנְעִים אֶת הַשַּׂקִּית"],1,"קִטְנִיּוֹת כְּמוֹ אֹרֶז יֵשׁ לִבְרֹר הֵיטֵב, וְקֶמַח שֶׁעָמַד זְמַן רַב יֵשׁ לְנַפּוֹת בְּנָפָה אוֹ לִקְנוֹת קֶמַח מְנֻפֶּה וְלִשְׁמֹר בְּקֵרוּר.","פֶּרֶק צ״ט, הֲלָכָה ט׳-י׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["מֵאֵיפֹה כְּדַאי לִקְנוֹת דָּגִים?",["מִמָּקוֹם מְפֻקָּח","מִכָּל מָקוֹם זוֹל","מִשְּׁלוּלִית בָּרְחוֹב"],0,"בְּחֵלֶק מֵהַדָּגִים יֵשׁ חֲשָׁשׁ לְתוֹלְעֵי מַיִם, וְלָכֵן קוֹנִים מִמְּקוֹמוֹת מְפֻקָּחִים שֶׁהַדָּגִים בָּהֶם נְקִיִּים.","פֶּרֶק צ״ט, הֲלָכָה י״א","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["רוֹצִים לִשְׁתּוֹת מֵי מַעְיָן. מָה עוֹשִׂים?",["שׁוֹתִים מַהֵר","מוֹסִיפִים סֻכָּר","מְסַנְּנִים הֵיטֵב"],2,"כְּשֶׁיֵּשׁ חֲשָׁשׁ לִשְׁרָצִים וְתוֹלָעִים, כְּמוֹ בְּמֵי מַעְיָנוֹת אוֹ מַשְׁקָאוֹת שֶׁעָמְדוּ זְמַן רַב – יֵשׁ לְסַנֵּן הֵיטֵב.","פֶּרֶק צ״ט, הֲלָכָה י״ב","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["אֵיזֶה מַאֲכָל הוּא עִקַּר הַסְּעוּדָה, וְכָל שְׁאָר הַמַּאֲכָלִים טְפֵלִים לוֹ?",["הַבָּשָׂר","הַלֶּחֶם","הַגְּבִינָה"],1,"חֲכָמִים קָבְעוּ שֶׁהַלֶּחֶם הוּא עִקַּר הַסְּעוּדָה, וּשְׁאָר הַמַּאֲכָלִים בָּאִים ״לְלַפֵּת בָּהֶם אֶת הַפַּת״.","פֶּרֶק כ״ג, הֲלָכָה ב׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["כַּמָּה לֶחֶם צָרִיךְ לֶאֱכֹל, כְּדֵי שֶׁ״הַמּוֹצִיא״ תִּפְטֹר אֶת כָּל מַאֲכְלֵי הַסְּעוּדָה?",["פֵּרוּר קָטָן אֶחָד","כִּכָּר לֶחֶם שְׁלֵמָה","כְּזַיִת, כִּפְרוּסָה דַּקָּה אַחַת"],2,"יֵשׁ לֶאֱכֹל בַּסְּעוּדָה לְפָחוֹת כְּזַיִת לֶחֶם, שֶׁהוּא כִּפְרוּסַת לֶחֶם דַּקָּה אַחַת.","פֶּרֶק כ״ג, הֲלָכָה ג׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["בְּסוֹף הַסְּעוּדָה אוֹכְלִים פֵּרוֹת לְקִנּוּחַ. אֵיךְ מְבָרְכִים עֲלֵיהֶם?",["בְּרָכָה רִאשׁוֹנָה בִּלְבַד","לֹא מְבָרְכִים כְּלָל","בְּרָכָה רִאשׁוֹנָה וּבְרָכָה אַחֲרוֹנָה"],0,"קִנּוּחַ אֵינוֹ חֵלֶק מֵעִקַּר הַסְּעוּדָה, לָכֵן מְבָרְכִים עָלָיו בְּרָכָה רִאשׁוֹנָה. בְּרָכָה אַחֲרוֹנָה לֹא מְבָרְכִים, כִּי בִּרְכַּת הַמָּזוֹן פּוֹטֶרֶת גַּם אוֹתוֹ.","פֶּרֶק כ״ג, הֲלָכָה ד׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["יוֹסִי אָכַל לֶחֶם תּוֹךְ כְּדֵי הֲלִיכָה בַּדֶּרֶךְ. אֵיךְ יְבָרֵךְ בִּרְכַּת הַמָּזוֹן?",["חַיָּב לַעֲצֹר וְלָשֶׁבֶת","יָכוֹל לְבָרֵךְ תּוֹךְ כְּדֵי הֲלִיכָה","יְבָרֵךְ רַק כְּשֶׁיַּגִּיעַ הַבַּיְתָה"],1,"בְּדֶרֶךְ כְּלָל מְבָרְכִים בִּישִׁיבָה, אֲבָל מִי שֶׁאוֹכֵל בַּהֲלִיכָה יָכוֹל לְבָרֵךְ בַּהֲלִיכָה, כִּי אִם יַעֲצֹר יִהְיֶה טָרוּד וְלֹא יְכַוֵּן כָּרָאוּי.","פֶּרֶק כ״ד, הֲלָכָה ד׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["אָבִי נִזְכַּר בְּאֶמְצַע נְסִיעָה אֲרֻכָּה שֶׁלֹּא בֵּרַךְ בִּרְכַּת הַמָּזוֹן. מָה הַדִּין?",["פָּטוּר מִלְּבָרֵךְ","חַיָּב לַחֲזֹר הַבַּיְתָה מִיָּד","יָכוֹל לְבָרֵךְ בַּמָּקוֹם שֶׁנִּזְכַּר"],2,"אִם הַחֲזָרָה הִיא טִרְחָה גְּדוֹלָה אוֹ הוֹצָאָה כַּסְפִּית גְּדוֹלָה, יָכוֹל לְבָרֵךְ בַּמָּקוֹם שֶׁנִּזְכַּר. וְאִם יִתְאַמֵּץ וְיַחֲזֹר, הֲרֵי זֶה מְשֻׁבָּח.","פֶּרֶק כ״ד, הֲלָכָה ה׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["מִי תִּקֵּן אֶת הַבְּרָכָה הָרִאשׁוֹנָה, בִּרְכַּת הַזָּן, כַּאֲשֶׁר יָרַד הַמָּן בַּמִּדְבָּר?",["מֹשֶׁה רַבֵּנוּ","דָּוִד הַמֶּלֶךְ","יְהוֹשֻׁעַ"],0,"בִּרְכַּת הַזָּן נִתְקְנָה עַל יְדֵי מֹשֶׁה רַבֵּנוּ כַּאֲשֶׁר יָרַד הַמָּן בַּמִּדְבָּר. בָּהּ מוֹדִים לַה׳ שֶׁנּוֹתֵן מִחְיָה וּמָזוֹן לְכָל בְּרִיּוֹתָיו.","פֶּרֶק כ״ד, הֲלָכָה ב׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["עַל אֵיזֶה נֵס תִּקְּנוּ חֲכָמִים אֶת הַבְּרָכָה הָרְבִיעִית, ״הַטּוֹב וְהַמֵּטִיב״?",["קְרִיעַת יַם סוּף","נֵס הֲרוּגֵי בֵּיתָר","נֵס פַּךְ הַשֶּׁמֶן"],1,"בִּרְכַּת הַטּוֹב וְהַמֵּטִיב תֻּקְּנָה בַּיּוֹם שֶׁהִתִּירוּ הָרוֹמָאִים לִקְבֹּר אֶת הֲרוּגֵי בֵּיתָר, וְנַעֲשָׂה נֵס שֶׁגּוּפוֹתֵיהֶם לֹא הִסְרִיחוּ.","פֶּרֶק כ״ד, הֲלָכָה ב׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["דָּנִי הִרְהֵר אֶת בִּרְכַּת הַמָּזוֹן בְּלִבּוֹ, בְּלִי לְהוֹצִיא מִלִּים בִּשְׂפָתָיו. הַאִם יָצָא?",["כֵּן, יָצָא","יָצָא רַק בְּשַׁבָּת","לֹא יָצָא"],2,"צָרִיךְ לְהַשְׁמִיעַ אֶת הַבְּרָכָה לָאָזְנַיִם. מִי שֶׁאָמַר בִּשְׂפָתָיו וְלֹא הִשְׁמִיעַ – יָצָא, אֲבָל מִי שֶׁרַק הִרְהֵר בְּלִבּוֹ – לֹא יָצָא.","פֶּרֶק כ״ד, הֲלָכָה ו׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["בְּהֵמָה טְהוֹרָה נִשְׁחֲטָה כַּדִּין. מָתַי מֻתָּר לֶאֱכֹל אֶת בְּשָׂרָהּ?",["רַק אַחֲרֵי שֶׁהוֹצִיאוּ מִמֶּנּוּ אֶת הַדָּם","מִיָּד אַחֲרֵי הַשְּׁחִיטָה","רַק אַחֲרֵי שָׁבוּעַ שָׁלֵם"],0,"אָסוּר לֶאֱכֹל בָּשָׂר, אֲפִלּוּ שֶׁל בְּהֵמָה טְהוֹרָה שֶׁנִּשְׁחֲטָה כַּדִּין, לִפְנֵי שֶׁהוֹצִיאוּ מִמֶּנּוּ אֶת הַדָּם.","פֶּרֶק ק׳, הֲלָכָה א׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["קוֹנִים בָּשָׂר בַּחֲנוּת. עַל מָה צָרִיךְ לָשִׂים לֵב?",["שֶׁהַמְּחִיר זוֹל","שֶׁיֵּשׁ חוֹתֶמֶת כָּשֵׁר וּמֻכְשָׁר","שֶׁהַצֶּבַע אָדֹם מְאֹד"],1,"בִּזְמַן הַקְּנִיָּה יֵשׁ לָשִׂים לֵב שֶׁיֵּשׁ עַל הַבָּשָׂר חוֹתֶמֶת הַמְּעִידָה שֶׁהוּא כָּשֵׁר וּמֻכְשָׁר.","פֶּרֶק ק׳, הֲלָכָה ב׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["כַּמָּה זְמַן מַשְׁרִים אֶת הַבָּשָׂר בְּמַיִם?",["דַּקָּה אַחַת","יוֹם שָׁלֵם","חֲצִי שָׁעָה"],2,"בִּשְׁרִיָּה מַשְׁרִים אֶת הַבָּשָׂר בְּמַיִם לְמֶשֶׁךְ חֲצִי שָׁעָה וּמְנַקִּים אוֹתוֹ הֵיטֵב.","פֶּרֶק ק׳, הֲלָכָה ג׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["מָה מְפַזְּרִים עַל הַבָּשָׂר בִּשְׁעַת הַמְּלִיחָה?",["סֻכָּר לָבָן","מֶלַח גַּס","פִּלְפֵּל שָׁחֹר"],1,"מַנִּיחִים אֶת הַבָּשָׂר עַל גַּבֵּי רֶשֶׁת וּמְפַזְּרִים עָלָיו מֶלַח גַּס (עָבֶה) לְמֶשֶׁךְ כְּשָׁעָה.","פֶּרֶק ק׳, הֲלָכָה ג׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["כַּמָּה פְּעָמִים שׁוֹטְפִים אֶת הַבָּשָׂר בַּהֲדָחָה?",["שָׁלוֹשׁ פְּעָמִים","פַּעַם אַחַת","עֶשֶׂר פְּעָמִים"],0,"בַּהֲדָחָה שׁוֹטְפִים אֶת הַמֶּלַח וּשְׁאֵרִיּוֹת הַדָּם מֵהַבָּשָׂר שָׁלוֹשׁ פְּעָמִים.","פֶּרֶק ק׳, הֲלָכָה ג׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["מָה עוֹד, חוּץ מִמֶּלַח, מַפְלִיט אֶת הַדָּם מִן הַבָּשָׂר?",["קֶרַח קַר","סֻכָּר מָתוֹק","חֹם הָאֵשׁ"],2,"כְּשֵׁם שֶׁהַמֶּלַח מַפְלִיט אֶת הַדָּם, כָּךְ גַּם חֹם הָאֵשׁ מַפְלִיט אוֹתוֹ, וְלָכֵן בָּשָׂר צָלוּי כָּרָאוּי מֻתָּר.","פֶּרֶק ק׳, הֲלָכָה ד׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["אֵיךְ מַכְשִׁירִים כָּבֵד?",["בִּמְלִיחָה בִּלְבַד","בִּצְלִיָּה","בִּשְׁרִיָּה בִּלְבַד"],1,"בַּכָּבֵד יֵשׁ דָּם רַב וְהַמֶּלַח אֵינוֹ יָכוֹל לְהוֹצִיא אֶת כֻּלּוֹ, לָכֵן מַכְשִׁירִים אוֹתוֹ בִּצְלִיָּה.","פֶּרֶק ק׳, הֲלָכָה ה׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["בְּבֵיצָה מִן הַחֲנוּת נִמְצְאָה טִפַּת דָּם. מָה עוֹשִׂים?",["מוֹצִיאִים אֶת הַדָּם וּמִשְׁתַּמְּשִׁים בַּשְּׁאָר","זוֹרְקִים אֶת כָּל הַקַּרְטוֹן","אוֹכְלִים הַכֹּל כְּמוֹ שֶׁהוּא"],0,"הַבֵּיצִים בַּחֲנוּיוֹת בָּאוֹת מִלּוּלִים בְּלִי תַּרְנְגוֹלִים זְכָרִים, לָכֵן מוֹצִיאִים אֶת הַדָּם וּמֻתָּר לְהִשְׁתַּמֵּשׁ בִּשְׁאָר הַבֵּיצָה.","פֶּרֶק ק׳, הֲלָכָה ו׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["הַאִם מֻתָּר לֶאֱכֹל בֵּיצִים קָשׁוֹת, שֶׁאִי אֶפְשָׁר לִבְדֹּק אוֹתָן?",["אָסוּר לְעוֹלָם","רַק בְּשַׁבָּת","מֻתָּר, כִּי בְּרֹב הַבֵּיצִים אֵין דָּם"],2,"מֻתָּר לֶאֱכֹל בֵּיצִים קָשׁוֹת, מִפְּנֵי שֶׁסּוֹמְכִים עַל כָּךְ שֶׁבְּרֹב הַבֵּיצִים אֵין דָּם.","פֶּרֶק ק׳, הֲלָכָה ז׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["מְבַשְּׁלִים בָּשָׂר עִם חָלָב בִּשְׁבִיל גּוֹי. הַאִם יֵשׁ בָּזֶה אִסּוּר?",["כֵּן, יֵשׁ אִסּוּר בִּשּׁוּל","אֵין שׁוּם אִסּוּר","אָסוּר רַק בְּשַׁבָּת"],0,"אִסּוּר בָּשָׂר בְּחָלָב כּוֹלֵל שְׁלוֹשָׁה אִסּוּרִים: אֲכִילָה, בִּשּׁוּל וַהֲנָאָה. אָסוּר לְבַשֵּׁל בָּשָׂר עִם חָלָב גַּם עֲבוּר גּוֹי, וְאָסוּר גַּם לִמְכֹּר לוֹ אֶת הַתַּבְשִׁיל.","פֶּרֶק ק״א, הֲלָכָה א׳","בָּשָׂר וְחָלָב"],["עַל אֵיזֶה שֻׁלְחָן אָסוּר לְהַנִּיחַ אֶת הַמַּאֲכָלִים יַחַד?",["שֻׁלְחָן עִם גְּבִינָה וְסָלָט","שֻׁלְחָן עִם קְצִיצוֹת וְאֹרֶז","שֻׁלְחָן עִם גְּבִינָה וּקְצִיצוֹת"],2,"אָסוּר לְהַנִּיחַ מַאַכְלֵי בָּשָׂר עַל שֻׁלְחָן שֶׁאוֹכְלִים עָלָיו בְּאוֹתוֹ זְמַן מַאַכְלֵי חָלָב, כְּדֵי שֶׁלֹּא יִטְעוּ לֶאֱכֹל מֵהֶם יַחַד.","פֶּרֶק ק״א, הֲלָכָה ב׳","בָּשָׂר וְחָלָב"],["שְׁנֵי חֲבֵרִים אוֹכְלִים לְיַד אוֹתוֹ שֻׁלְחָן, אֶחָד חָלָב וְאֶחָד בָּשָׂר. מָה עוֹזֵר לָהֶם?",["כּוֹס אַחַת לִשְׁנֵיהֶם","מַפָּה נִפְרֶדֶת לְכָל אֶחָד","כִּכַּר לֶחֶם מְשֻׁתֶּפֶת"],1,"עֲלֵיהֶם לַעֲשׂוֹת הֶכֵּר: כָּל אֶחָד יֹאכַל עַל מַפָּה אַחֶרֶת, אוֹ שֶׁיָּשִׂימוּ בֵּינֵיהֶם חֵפֶץ שֶׁאֵינוֹ רָגִיל עַל הַשֻּׁלְחָן. וְלֹא יִשְׁתּוּ מֵאוֹתָהּ כּוֹס וְלֹא יֹאכְלוּ מֵאוֹתָהּ כִּכַּר לֶחֶם.","פֶּרֶק ק״א, הֲלָכָה ג׳","בָּשָׂר וְחָלָב"],["כַּמָּה זְמַן מַמְתִּינִים בִּקְהִלּוֹת הַסְּפָרַדִּים אַחֲרֵי בָּשָׂר לִפְנֵי חָלָב?",["עֶשֶׂר דַּקּוֹת","חֲצִי שָׁעָה","שֵׁשׁ שָׁעוֹת"],2,"בִּקְהִלּוֹת הַסְּפָרַדִּים מַמְתִּינִים שֵׁשׁ שָׁעוֹת, וְכֵן מִנְהַג רַבּוֹת מִקְּהִלּוֹת הָאַשְׁכְּנַזִּים, וְכָךְ רָאוּי לִנְהֹג. יֵשׁ קְהִלּוֹת אַשְׁכְּנַזִּיּוֹת שֶׁנּוֹהֲגוֹת אַחֶרֶת.","פֶּרֶק ק״א, הֲלָכָה ד׳","בָּשָׂר וְחָלָב"],["עָבְרוּ שֵׁשׁ שָׁעוֹת, אֲבָל נִשְׁאַר בָּשָׂר בֵּין הַשִּׁנַּיִם. מָה עוֹשִׂים?",["אוֹכְלִים מִיָּד גְּבִינָה","מְנַקִּים הֵיטֵב אֶת הַשִּׁנַּיִם","שׁוֹתִים חָלָב כְּדֵי לִשְׁטֹף"],1,"גַּם לְאַחַר הַהַמְתָּנָה, אִם נִשְׁאַר בָּשָׂר בֵּין הַשִּׁנַּיִם - מְנַקִּים הֵיטֵב וְרַק אָז אוֹכְלִים חָלָב. וְגַם מִי שֶׁלָּעַס בָּשָׂר וְלֹא בָּלַע - צָרִיךְ לְהַמְתִּין.","פֶּרֶק ק״א, הֲלָכוֹת ה׳-ו׳","בָּשָׂר וְחָלָב"],["אַחֲרֵי שֶׁשּׁוֹתִים מְרַק עוֹף, הַאִם צָרִיךְ לְהַמְתִּין לִפְנֵי חָלָב?",["לֹא, זֶה רַק מְרָק","כֵּן, כְּמוֹ אַחֲרֵי בָּשָׂר","רַק אִם אָכַל לֶחֶם"],1,"יֵשׁ לְהַמְתִּין גַּם אַחֲרֵי תַּבְשִׁיל שֶׁל בָּשָׂר, כְּלוֹמַר מַה שֶּׁהִתְבַּשֵּׁל עִם הַבָּשָׂר, כְּמוֹ אַחֲרֵי בָּשָׂר מַמָּשׁ - וַאֲפִלּוּ אַחֲרֵי מְרַק עוֹף.","פֶּרֶק ק״א, הֲלָכָה ז׳","בָּשָׂר וְחָלָב"],["אָכַלְתָּ מַאֲכַל חָלָב וְאַתָּה רוֹצֶה בָּשָׂר מִיָּד. מָה עוֹשִׂים?",["אוֹכְלִים מִיָּד בְּלִי כְּלוּם","מַמְתִּינִים יוֹם שָׁלֵם","רוֹחֲצִים יָדַיִם וּמְצַחְצְחִים שִׁנַּיִם"],2,"מִי שֶׁאָכַל חָלָב וְרוֹצֶה בָּשָׂר - יִרְחַץ יָדַיִם וִיצַחְצֵחַ שִׁנַּיִם, אוֹ יֹאכַל מַאֲכַל פַּרְוֶה וְיִשְׁטֹף אֶת הַפֶּה בְּמַיִם, וְאָז יָכוֹל לֶאֱכֹל בָּשָׂר מִיָּד. וְיֵשׁ שֶׁנָּהֲגוּ לְהַמְתִּין חֲצִי שָׁעָה.","פֶּרֶק ק״א, הֲלָכָה ח׳","בָּשָׂר וְחָלָב"],["אַחֲרֵי אֵיזוֹ גְּבִינָה צָרִיךְ לְהַמְתִּין לִפְנֵי בָּשָׂר?",["גְּבִינָה קָשָׁה שֶׁיֻּצְּרָה שִׁשָּׁה חֳדָשִׁים","גְּבִינָה רַכָּה","אַף אַחַת מֵהֶן"],0,"אַחֲרֵי גְּבִינָה קָשָׁה (שֶׁהַיִּצּוּר שֶׁלָּהּ אָרַךְ שִׁשָּׁה חֳדָשִׁים) מַמְתִּינִים כְּמוֹ בֵּין בָּשָׂר לְחָלָב, וְאַחֲרֵי גְּבִינָה רַכָּה אֵין צָרִיךְ לְהַמְתִּין.","פֶּרֶק ק״א, הֲלָכָה ט׳","בָּשָׂר וְחָלָב"],["בְּאֵיזוֹ סַכִּין חוֹתְכִים גְּבִינָה?",["סַכִּין בְּשָׂרִית","סַכִּין חֲלָבִית","סַכִּין שֶׁחָתְכָה שְׁנִיצֶל"],1,"אָסוּר לַחְתֹּךְ גְּבִינָה, וְגַם לֶחֶם שֶׁאוֹכְלִים עִם גְּבִינָה, בְּסַכִּין בְּשָׂרִית, וּלְהֶפֶךְ. הַמִּנְהָג הוּא שֶׁיֵּשׁ בַּבַּיִת שְׁתֵּי מַעַרְכוֹת כֵּלִים, חֲלָבִית וּבְשָׂרִית.","פֶּרֶק ק״א, הֲלָכוֹת י׳-י״א","בָּשָׂר וְחָלָב"],["לְמִי נִתְּנָה אֶרֶץ יִשְׂרָאֵל כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם?",["לְשָׂרֵי הָאֻמּוֹת","לְעַם יִשְׂרָאֵל – הָעָם הַנִּבְחָר","לְמִי שֶׁיַּגִּיעַ אֵלֶיהָ רִאשׁוֹן"],1,"הָאֲרָצוֹת חֻלְּקוּ לְשָׂרֵי הָאֻמּוֹת, אֲבָל אֶרֶץ יִשְׂרָאֵל נִבְחֲרָה וְנִתְּנָה לָעָם הַנִּבְחָר – עַם יִשְׂרָאֵל.","פֶּרֶק ק״ב, הֲלָכָה א׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["מֵאֵימָתַי אֶרֶץ יִשְׂרָאֵל קְדוֹשָׁה?",["מִשְּׁעַת בְּרִיאַת הָעוֹלָם","מִזְּמַן בִּנְיַן בֵּית הַמִּקְדָּשׁ","מִיְּמֵי דָּוִד הַמֶּלֶךְ"],0,"קְדֻשָּׁתָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל הִיא כְּבָר מִשְּׁעַת בְּרִיאַת הָעוֹלָם.","פֶּרֶק ק״ב, הֲלָכָה ב׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["בַּמָּשָׁל, מָה עוֹשֶׂה בֶּן הַמְּלָכִים עִם מַאֲכָל שֶׁאֵינוֹ עוֹמֵד בְּמֵעָיו?",["שׁוֹמֵר אוֹתוֹ לְמָחָר","נוֹתֵן אוֹתוֹ לַחֲבֵרָיו","מְקִיא אוֹתוֹ"],2,"בֶּן הַמְּלָכִים מְקִיא אֶת הַמַּאֲכָל, וְכָךְ אֶרֶץ יִשְׂרָאֵל אֵינָהּ מְקַיֶּמֶת עוֹבְרֵי עֲבֵרוֹת.","פֶּרֶק ק״ב, הֲלָכָה ב׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["קְדֻשַּׁת הָאָרֶץ הִיא בְּכָךְ שֶׁהִיא קְרוֹבָה לְ...",["הַיָּם הַגָּדוֹל","מְקוֹם הַשְּׁכִינָה","הַמִּדְבָּר"],1,"קְדֻשָּׁתָהּ שֶׁל הָאָרֶץ הִיא בַּקִּרְבָה לִמְקוֹם הַשְּׁכִינָה.","פֶּרֶק ק״ב, הֲלָכָה ב׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["מָה מְצֻוֶּה עַם יִשְׂרָאֵל לַעֲשׂוֹת בְּאֶרֶץ יִשְׂרָאֵל?",["לְהַשְׁאִיר אוֹתָהּ שְׁמָמָה","לַעֲזֹב אוֹתָהּ בְּיַד הָאֻמּוֹת","לָרֶשֶׁת אוֹתָהּ וְלָשֶׁבֶת בָּהּ"],2,"נֶאֱמַר ״וִירִשְׁתֶּם אֹתָהּ וִישַׁבְתֶּם בָּהּ״ – מְצֻוִּים לָרֶשֶׁת אֶת הָאָרֶץ וְלֹא לְהַשְׁאִירָהּ שְׁמָמָה אוֹ בְּיַד הָאֻמּוֹת.","פֶּרֶק ק״ב, הֲלָכָה ג׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["לְפִי רַבּוֹתֵינוּ, יְשִׁיבַת אֶרֶץ יִשְׂרָאֵל שְׁקוּלָה כְּנֶגֶד...",["כָּל הַמִּצְווֹת","מִצְוָה אַחַת קְטַנָּה","שׁוּם דָּבָר"],0,"אָמְרוּ רַבּוֹתֵינוּ שֶׁיְּשִׁיבַת אֶרֶץ יִשְׂרָאֵל שְׁקוּלָה כְּנֶגֶד כָּל הַמִּצְווֹת.","פֶּרֶק ק״ב, הֲלָכָה ג׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["מִי חַיָּב בְּמִצְוַת יְשִׁיבַת אֶרֶץ יִשְׂרָאֵל?",["רַק מִי שֶׁגָּר בִּירוּשָׁלַיִם","כָּל אָדָם מִיִּשְׂרָאֵל, בְּכָל הַדּוֹרוֹת","רַק בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם"],1,"הַמִּצְוָה נוֹהֶגֶת בְּכָל הַדּוֹרוֹת וְכָל אָדָם מִיִּשְׂרָאֵל חַיָּב בָּהּ, גַּם בִּזְמַן הַגָּלוּת.","פֶּרֶק ק״ב, הֲלָכָה ד׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["עֵץ תַּפּוּחִים נִטַּע לִפְנֵי שְׁנָתַיִם. מָה דִּין הַפֵּרוֹת שֶׁעָלָיו?",["מֻתָּרִים מִיָּד בַּאֲכִילָה","אֲסוּרִים בַּהֲנָאָה, הֵם עָרְלָה","צָרִיךְ לִפְדּוֹת אוֹתָם בִּפְרוּטָה"],1,"כָּל הַפֵּרוֹת שֶׁגְּדֵלִים בְּשָׁלוֹשׁ הַשָּׁנִים הָרִאשׁוֹנוֹת מֵעֵת הַנְּטִיעָה אֲסוּרִים בַּהֲנָאָה.","פֶּרֶק ק״ג, הֲלָכָה א׳","עָרְלָה וְנֶטַע רְבָעִי"],["בְּאֵיזֶה צֶמַח יֵשׁ אִסּוּר עָרְלָה?",["צֶמַח בָּנָנָה","שְׂתִיל עַגְבָנִיּוֹת","עֵץ זַיִת"],2,"עָרְלָה נוֹהֶגֶת רַק בְּעֵץ שֶׁהַגֶּזַע שֶׁלּוֹ מִתְקַיֵּם שָׁלוֹשׁ שָׁנִים לְפָחוֹת. בַּבָּנָנָה הַגֶּזַע מִתְיַבֵּשׁ, וִירָקוֹת הֵם חַד שְׁנָתִיִּים.","פֶּרֶק ק״ג, הֲלָכוֹת ב׳-ג׳","עָרְלָה וְנֶטַע רְבָעִי"],["פָּפָּיָה מוֹצִיאָה פֵּרוֹת כְּבָר בַּשָּׁנָה הָרִאשׁוֹנָה. הַאִם הִיא נֶחְשֶׁבֶת ״עֵץ״ לְעִנְיַן עָרְלָה?",["כֵּן, כִּי הַגֶּזַע שֶׁלָּהּ מִתְקַיֵּם","לֹא, אֲבָל יֵשׁ מַחְמִירִים בְּכָךְ","רַק בַּשָּׁנָה הַשְּׁלִישִׁית שֶׁלָּהּ"],1,"צֶמַח שֶׁמּוֹצִיא פֵּרוֹת כְּבָר בַּשָּׁנָה הָרִאשׁוֹנָה אֵינוֹ נֶחְשָׁב עֵץ, וְלָכֵן אֵין בּוֹ עָרְלָה, וְיֵשׁ מַחְמִירִים.","פֶּרֶק ק״ג, הֲלָכָה ד׳","עָרְלָה וְנֶטַע רְבָעִי"],["מָתַי מִתְחַלֶּפֶת שְׁנַת הָעָרְלָה?",["בְּרֹאשׁ הַשָּׁנָה","בְּט״וּ בִּשְׁבָט","בְּחַג הַפֶּסַח"],0,"שְׁנוֹת הָעָרְלָה נִסְפָּרוֹת כְּמוֹ שְׁנוֹת הָעוֹלָם, וְהַשָּׁנָה מִתְחַלֶּפֶת בְּרֹאשׁ הַשָּׁנָה. וְגַם שְׁלוֹשִׁים יוֹם לִפְנֵי רֹאשׁ הַשָּׁנָה נֶחְשָׁבִים שָׁנָה (״מִקְצָתוֹ כְּכֻלּוֹ״).","פֶּרֶק ק״ג, הֲלָכוֹת ה׳-ו׳","עָרְלָה וְנֶטַע רְבָעִי"],["מָה הַיּוֹם שֶׁקּוֹבֵעַ לְאֵיזוֹ שָׁנָה שַׁיָּךְ הַפְּרִי?",["רֹאשׁ הַשָּׁנָה","חֲנֻכָּה","ט״וּ בִּשְׁבָט"],2,"הַזְּמַן הַקּוֹבֵעַ הוּא ט״וּ בִּשְׁבָט: לְפִי זְמַן חֲנָטַת הַפְּרִי, לִפְנֵי ט״וּ בִּשְׁבָט אוֹ אַחֲרָיו.","פֶּרֶק ק״ג, הֲלָכָה ז׳","עָרְלָה וְנֶטַע רְבָעִי"],["בִּזְמַן בֵּית הַמִּקְדָּשׁ, הֵיכָן אָכְלוּ אֶת פֵּרוֹת הַשָּׁנָה הָרְבִיעִית?",["בְּבֵית הַבְּעָלִים","בִּירוּשָׁלַיִם, בְּטָהֳרָה","בַּשָּׂדֶה, לְיַד הָעֵץ"],1,"הָיוּ מַעֲלִים אֶת פֵּרוֹת הַשָּׁנָה הָרְבִיעִית וְאוֹכְלִים אוֹתָם בְּטָהֳרָה בִּירוּשָׁלַיִם.","פֶּרֶק ק״ג, הֲלָכָה ח׳","עָרְלָה וְנֶטַע רְבָעִי"],["בַּמֶּה פּוֹדִים הַיּוֹם פֵּרוֹת נֶטַע רְבָעִי?",["בִּפְרוּטָה","בְּשֶׁטֶר כֶּסֶף גָּדוֹל","לֹא פּוֹדִים כְּלָל"],0,"כְּשֶׁאֵין בֵּית הַמִּקְדָּשׁ פּוֹדִים בִּפְרוּטָה, אַף שֶׁהַפֵּרוֹת שָׁוִים יוֹתֵר, וּמְבָרְכִים ״עַל פִּדְיוֹן רְבָעִי״.","פֶּרֶק ק״ג, הֲלָכוֹת ט׳-י׳","עָרְלָה וְנֶטַע רְבָעִי"],["מָה עוֹשִׂים בַּפְּרוּטָה שֶׁפָּדוּ בָּהּ פֵּרוֹת רְבָעִי?",["קוֹנִים בָּהּ מַמְתָּק","שָׂמִים אוֹתָהּ בָּאַרְנָק","מַשְׁמִידִים אוֹתָהּ"],2,"הַפְּרוּטָה מִתְקַדֶּשֶׁת, וְלָכֵן אָסוּר לְהִשְׁתַּמֵּשׁ בָּהּ לִצְרָכִים רְגִילִים, וְיֵשׁ לְהַשְׁמִיד אוֹתָהּ.","פֶּרֶק ק״ג, הֲלָכָה י״א","עָרְלָה וְנֶטַע רְבָעִי"],["עֵץ נִטַּע בְּי״ד בְּאָב תשע״ו. פְּרִי שֶׁחָנַט אַחֲרֵי ט״וּ בִּשְׁבָט תש״פ, מָה דִּינוֹ?",["עָרְלָה","פְּרִי רָגִיל","נֶטַע רְבָעִי"],1,"הַפֵּרוֹת שֶׁחָנְטוּ אַחֲרֵי ט״וּ בִּשְׁבָט שֶׁל הַשָּׁנָה הַחֲמִישִׁית (תש״פ) הֵם פֵּרוֹת רְגִילִים.","פֶּרֶק ק״ג, הֲלָכָה י״ב","עָרְלָה וְנֶטַע רְבָעִי"],["אֵיפֹה כְּדַאי לִקְנוֹת פֵּרוֹת כְּדֵי לֹא לְהִכָּשֵׁל בְּעָרְלָה?",["בַּחֲנוּת עִם תְּעוּדַת הֶכְשֵׁר","בְּדוּכָן בְּלִי שׁוּם תְּעוּדָה","בְּכָל מָקוֹם, אֵין חֲשָׁשׁ"],0,"בַּמַּטָּעִים נוֹטְעִים עֵצִים חֲדָשִׁים בְּכָל שָׁנָה, לָכֵן קוֹנִים בַּחֲנוּת שֶׁיֵּשׁ לָהּ תְּעוּדַת הֶכְשֵׁר.","פֶּרֶק ק״ג, הֲלָכָה י״ג","עָרְלָה וְנֶטַע רְבָעִי"],["לְמִי מַפְרִישִׁים תְּרוּמוֹת וּמַעַשְׂרוֹת מֵהַיְּבוּל?",["לַכֹּהֲנִים, לַלְּוִיִּים וְלָעֲנִיִּים","לַשְּׁכֵנִים הָעֲשִׁירִים","לַחֲנֻיּוֹת שֶׁבַּשּׁוּק"],0,"מַפְרִישִׁים מֵהַתְּבוּאָה עֲבוּר מְשָׁרְתֵי ה׳ – הַכֹּהֲנִים וְהַלְּוִיִּים – וְכֵן לָעֲנִיִּים, שֶׁצִּוָּה ה׳ לְסַיֵּעַ לָהֶם.","פֶּרֶק ק״ד, הֲלָכָה א׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["אֵיזֶה יְבוּל חַיָּב בִּתְרוּמוֹת וּמַעַשְׂרוֹת?",["פֵּרוֹת שֶׁל שְׁנַת הַשְּׁמִטָּה","פֵּרוֹת שֶׁגָּדְלוּ בְּאֶרֶץ יִשְׂרָאֵל וְנִשְׁמְרוּ בִּידֵי בְּעָלֵיהֶם","פֵּרוֹת הֶפְקֵר שֶׁכֻּלָּם לוֹקְחִים"],1,"מַאֲכַל אָדָם שֶׁגָּדֵל בְּאֶרֶץ יִשְׂרָאֵל, שֶׁאֵינוֹ הֶפְקֵר אֶלָּא נִשְׁמָר בִּידֵי בְּעָלָיו – חַיָּב. פֵּרוֹת שְׁנַת הַשְּׁמִטָּה פְּטוּרִים.","פֶּרֶק ק״ד, הֲלָכוֹת ב׳-ג׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["כַּמָּה שָׁנִים יֵשׁ בַּמַּחְזוֹר שֶׁצָּרִיךְ לָדַעַת כְּדֵי לְהַפְרִישׁ נָכוֹן?",["עֶשֶׂר שָׁנִים","שָׁלֹשׁ שָׁנִים","שֶׁבַע שָׁנִים"],2,"סֵדֶר הַהַפְרָשָׁה מִשְׁתַּנֶּה בֵּין הַשָּׁנִים, וְלָכֵן צָרִיךְ לָדַעַת בְּאֵיזוֹ שָׁנָה מִתּוֹךְ מַחְזוֹר שֶׁבַע הַשָּׁנִים אָנוּ נִמְצָאִים.","פֶּרֶק ק״ד, הֲלָכָה ד׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["אֵיךְ קוֹרְאִים לְפֵרוֹת שֶׁלֹּא הִפְרִישׁוּ מֵהֶם תְּרוּמוֹת וּמַעַשְׂרוֹת?",["טֶבֶל","חֻלִּין","בִּכּוּרִים"],0,"פֵּרוֹת, יְרָקוֹת, תְּבוּאָה וְקִטְנִיּוֹת שֶׁלֹּא הֻפְרְשׁוּ מֵהֶם תְּרוּמוֹת וּמַעַשְׂרוֹת נִקְרָאִים טֶבֶל, וַאֲסוּרִים בַּאֲכִילָה.","פֶּרֶק ק״ד, הֲלָכָה ה׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["מַה הַמַּתָּנָה הָרִאשׁוֹנָה שֶׁמַּפְרִישִׁים מֵהַפֵּרוֹת?",["מַעֲשַׂר עָנִי","תְּרוּמָה גְּדוֹלָה","מַעֲשֵׂר שֵׁנִי"],1,"הַמַּתָּנָה הָרִאשׁוֹנָה נִקְרֵאת תְּרוּמָה גְּדוֹלָה, וְרַק כֹּהֲנִים טְהוֹרִים מֻתָּרִים לֶאֱכֹל אוֹתָהּ. אַחֲרֶיהָ מַפְרִישִׁים מַעֲשֵׂר רִאשׁוֹן.","פֶּרֶק ק״ד, הֲלָכָה ו׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["מָה עוֹשִׂים הַיּוֹם עִם הַתְּרוּמָה שֶׁהִפְרִישׁוּ?",["אוֹכְלִים אוֹתָהּ בְּסָלָט","מוֹכְרִים אוֹתָהּ בַּשּׁוּק","עוֹטְפִים וְשָׂמִים בָּאַשְׁפָּה"],2,"הַכֹּהֵן חַיָּב לֶאֱכֹל תְּרוּמָה בְּטָהֳרָה, וּמִכֵּיוָן שֶׁכַּיּוֹם אֵין כֹּהֲנִים טְהוֹרִים – עוֹטְפִים אוֹתָהּ וְשָׂמִים בָּאַשְׁפָּה.","פֶּרֶק ק״ד, הֲלָכָה ז׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["מַה נוֹהֲגִים רַבִּים לָתֵת מֵרֹאשׁ לַלֵּוִי וְלֶעָנִי?",["הַלְוָאָה שֶׁל כֶּסֶף","עֲצִיץ פְּרָחִים","סֵפֶר תּוֹרָה"],0,"רַבִּים נוֹתְנִים מֵרֹאשׁ הַלְוָאָה לַלֵּוִי וְלֶעָנִי, וּמְסַכְּמִים שֶׁיַּרְשׁוּ לַבְּעָלִים לְהִשְׁתַּמֵּשׁ בַּפֵּרוֹת בִּמְקוֹם הֶחְזֵר הַחוֹב.","פֶּרֶק ק״ד, הֲלָכָה ח׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["בְּאֵיזוֹ חֲנוּת טוֹב לִקְנוֹת פֵּרוֹת וִירָקוֹת?",["חֲנוּת עִם שֶׁלֶט מִבְצָעִים","חֲנוּת עִם תְּעוּדַת הֶכְשֵׁר שֶׁל הָרַבָּנוּת","דּוּכָן בְּלִי שׁוּם בְּדִיקָה"],1,"טוֹב לִקְנוֹת בַּחֲנוּיוֹת שֶׁיֵּשׁ לָהֶן תְּעוּדַת הֶכְשֵׁר מִטַּעַם הָרַבָּנוּת, שֶׁכָּתוּב בָּהּ שֶׁהֻפְרְשׁוּ תְּרוּמוֹת וּמַעַשְׂרוֹת כַּדִּין.","פֶּרֶק ק״ד, הֲלָכָה ט׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["אֵיזוֹ הַפְרָשָׁה מֻתֶּרֶת?",["מִתַּפּוּחִים עַל בָּנָנוֹת","מִתַּפּוּזִים שֶׁל שָׁנָה אַחַת עַל תַּפּוּזִים שֶׁל שָׁנָה אַחֶרֶת","מִתַּפּוּחִים עַל תַּפּוּחִים שֶׁל אוֹתָהּ שָׁנָה"],2,"מַפְרִישִׁים רַק מֵאוֹתוֹ הַמִּין, וְרַק מִיְּבוּל שֶׁל אוֹתָהּ שָׁנָה. אֵין לְהַפְרִישׁ מִתַּפּוּחִים עַל בָּנָנוֹת, וְלֹא מִשָּׁנָה לְשָׁנָה.","פֶּרֶק ק״ד, הֲלָכוֹת י״א-י״ב","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["אֵין לְהַפְרִישׁ מִזֵּיתִים לְשֶׁמֶן עַל זֵיתִים... לְמָה?",["לַאֲכִילָה","יְרֻקִּים","גְּדוֹלִים"],0,"מַפְרִישִׁים רַק מִפְּרִי שֶׁנִּגְמְרָה מְלַאכְתּוֹ עַל פְּרִי שֶׁנִּגְמְרָה מְלַאכְתּוֹ, וְלָכֵן אֵין לְהַפְרִישׁ מִזֵּיתִים לְשֶׁמֶן עַל זֵיתִים לַאֲכִילָה.","פֶּרֶק ק״ד, הֲלָכָה י״ג","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["מָה אָסוּר לַעֲשׂוֹת בַּשָּׂדֶה בַּשָּׁנָה הַשְּׁבִיעִית?",["לִזְרֹעַ זְרָעִים","לָלֶכֶת בַּשָּׂדֶה","לְהִסְתַּכֵּל עַל הַפְּרָחִים"],0,"בַּשָּׁנָה הַשְּׁבִיעִית מִצְוָה לִשְׁבֹּת מֵעֲבוֹדַת הָאָרֶץ, שֶׁנֶּאֱמַר: ״שָׂדְךָ לֹא תִזְרָע״.","פֶּרֶק ק״ה, הֲלָכָה א׳","שְׁנַת הַשְּׁמִטָּה"],["מָה קוֹרֶה לַגִּדּוּלִים בַּשְּׁמִטָּה, וְכָךְ עוֹזֵר לָעֲנִיִּים?",["הֵם נִמְכָּרִים בִּמְחִיר יָקָר","הֵם הֶפְקֵר וְכֻלָּם יְכוֹלִים לֵהָנוֹת מֵהֶם","הֵם נִשְׁמָרִים בְּמַחְסָן נָעוּל"],1,"בַּשְּׁמִטָּה כָּל הַגִּדּוּלִים הֵם הֶפְקֵר, וְכָל אֶחָד יָכוֹל לֵהָנוֹת מֵהֶם – וְזוֹ דְּאָגָה לָעֲנִיִּים.","פֶּרֶק ק״ה, הֲלָכָה ב׳","שְׁנַת הַשְּׁמִטָּה"],["בַּזְּמַן שֶׁרֹב עַם יִשְׂרָאֵל אֵינוֹ בָּאָרֶץ, מִצְוַת הַשְּׁמִטָּה הִיא…",["מִן הַתּוֹרָה","מִדִּבְרֵי חֲכָמִים","אֵינָהּ נוֹהֶגֶת כְּלָל"],1,"בִּזְמַן שֶׁרֹב עַם יִשְׂרָאֵל אֵינוֹ בְּאֶרֶץ יִשְׂרָאֵל, הַשְּׁמִטָּה נוֹהֶגֶת מִדִּבְרֵי חֲכָמִים בִּלְבַד.","פֶּרֶק ק״ה, הֲלָכָה ג׳","שְׁנַת הַשְּׁמִטָּה"],["אֵיזוֹ מְלָאכָה אֲסוּרָה מִן הַתּוֹרָה בַּשְּׁבִיעִית?",["הַשְׁקָיָה כְּדֵי שֶׁהַצֶּמַח לֹא יָמוּת","שְׁטִיפַת צַלָּחוֹת","חֲרִישַׁת הַשָּׂדֶה"],2,"זְרִיעָה, זְמִירָה וַחֲרִישָׁה אֲסוּרוֹת בַּשְּׁבִיעִית מִן הַתּוֹרָה.","פֶּרֶק ק״ה, הֲלָכָה ד׳","שְׁנַת הַשְּׁמִטָּה"],["אֵיזוֹ מְלָאכָה מֻתֶּרֶת בִּשְׁנַת הַשְּׁמִטָּה?",["זְמִירַת הַכֶּרֶם","גִּזּוּם שִׂיחַ שֶׁחוֹסֵם אֶת הַמַּעֲבָר","זְרִיעַת חִטָּה"],1,"מְלָאכָה שֶׁמַּטְּרָתָהּ אֵינָהּ צִמּוּחַ, כְּמוֹ גִּזּוּם צְמָחִים שֶׁחוֹסְמִים אֶת הַמַּעֲבָר – לֹא נֶאֶסְרָה.","פֶּרֶק ק״ה, הֲלָכָה ה׳","שְׁנַת הַשְּׁמִטָּה"],["יֵשׁ אוֹמְרִים שֶׁאֲכִילַת פֵּרוֹת שְׁבִיעִית הִיא…",["מִצְוָה","אִסּוּר","רַק לַבְּהֵמוֹת"],0,"יֵשׁ אוֹמְרִים שֶׁאֲכִילַת פֵּרוֹת שְׁבִיעִית הִיא מִצְוָה, שֶׁנֶּאֱמַר: ״וְהָיְתָה שַׁבַּת הָאָרֶץ לָכֶם לְאָכְלָה״.","פֶּרֶק ק״ה, הֲלָכָה ו׳","שְׁנַת הַשְּׁמִטָּה"],["מִי מְפַרְסֶמֶת בְּכָל שְׁנַת שְׁמִטָּה מָתַי חָלָה הַקְּדֻשָּׁה עַל כָּל מִין?",["הָעִירִיָּה","בֵּית הַסֵּפֶר","הָרַבָּנוּת"],2,"זְמַן חָלוּת הַקְּדֻשָּׁה מִשְׁתַּנֶּה בֵּין הַמִּינִים, לָכֵן הָרַבָּנוּת מְפַרְסֶמֶת אֶת הַזְּמַנִּים בְּכָל שְׁנַת שְׁמִטָּה.","פֶּרֶק ק״ה, הֲלָכָה ז׳","שְׁנַת הַשְּׁמִטָּה"],["אֵיזֶה פְּרִי שְׁבִיעִית מֻתָּר לִסְחֹט?",["תַּפּוּז","רִמּוֹן","גֶּזֶר"],0,"פֵּרוֹת שֶׁרְגִילִים לִסְחֹט בִּשְׁאָר הַשָּׁנִים, כְּמוֹ תַּפּוּזִים, מֻתָּר לִסְחֹט, אֲבָל גֶּזֶר וְרִמּוֹנִים אָסוּר.","פֶּרֶק ק״ה, הֲלָכָה ח׳","שְׁנַת הַשְּׁמִטָּה"],["עַל אֵיזֶה גִּדּוּל לֹא חָל אִסּוּר סְפִיחִין?",["חַסָּה שֶׁצָּמְחָה בַּשְּׁמִטָּה","חִטָּה שֶׁצָּמְחָה בַּשְּׁמִטָּה","תַּפּוּחַ מִן הָעֵץ"],2,"חֲכָמִים גָּזְרוּ עַל גִּדּוּלִים חַד שְׁנָתִיִּים כִּירָקוֹת וּתְבוּאָה, אֲבָל אִסּוּר סְפִיחִין אֵינוֹ חָל עַל פֵּרוֹת הָעֵץ.","פֶּרֶק ק״ה, הֲלָכוֹת ט׳-י׳","שְׁנַת הַשְּׁמִטָּה"],["עַל אֵילוּ גִּדּוּלִים חָל אִסּוּר סְפִיחִין?",["מַה שֶּׁגָּדַל בְּקַרְקַע שֶׁל יִשְׂרָאֵל","מַה שֶּׁגָּדַל בְּקַרְקַע שֶׁל גּוֹי","מַה שֶּׁגָּדַל בְּכָל קַרְקַע בָּעוֹלָם"],0,"אִסּוּר סְפִיחִין חָל רַק עַל מַה שֶּׁגָּדַל בְּקַרְקַע שֶׁל יִשְׂרָאֵל, וְלֹא עַל מַה שֶּׁגָּדַל בְּקַרְקַע שֶׁל גּוֹי.","פֶּרֶק ק״ה, הֲלָכָה י״א","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["אֵילוּ גִּדּוּלִים מֻתָּר לֶאֱכֹל בִּשְׁנַת הַשְּׁמִטָּה?",["שֶׁנִּזְרְעוּ בַּשְּׁבִיעִית","שֶׁכָּל גִּדּוּלָם בַּשְּׁבִיעִית","שֶׁהִתְחִילוּ לִצְמֹחַ בַּשִּׁשִּׁית"],2,"אִסּוּר סְפִיחִין חָל רַק עַל מַה שֶּׁנִּזְרַע אוֹ גָּדַל כֻּלּוֹ בַּשְּׁבִיעִית, אֲבָל מֻתָּר לֶאֱכֹל גִּדּוּלִים שֶׁהִתְחִילוּ לִצְמֹחַ בַּשָּׁנָה הַשִּׁשִּׁית.","פֶּרֶק ק״ה, הֲלָכָה י״ב","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["מָה הַתּוֹרָה אוֹמֶרֶת לַעֲשׂוֹת בְּפֵרוֹת שְׁבִיעִית?",["לִסְחֹר בָּהֶם בַּשּׁוּק","לֶאֱכֹל אוֹתָם","לִמְכֹּר אוֹתָם בַּחֲנוּת"],1,"״לְאָכְלָה – וְלֹא לִסְחוֹרָה״: פֵּרוֹת שְׁבִיעִית נוֹעֲדוּ לַאֲכִילָה, וְאָסוּר לִסְחֹר בָּהֶם.","פֶּרֶק ק״ה, הֲלָכָה י״ג","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["לְמִי מוֹכְרִים הַחַקְלָאִים אֶת אַדְמָתָם בְּהֶתֵּר הַמְּכִירָה?",["לְגוֹי","לַשָּׁכֵן הַיְּהוּדִי","לְבֵית הַכְּנֶסֶת"],0,"בְּהֶתֵּר הַמְּכִירָה הַחַקְלָאִים מוֹכְרִים אֶת אַדְמָתָם לְגוֹי לְמֶשֶׁךְ שְׁנַת הַשְּׁמִטָּה.","פֶּרֶק ק״ה, הֲלָכָה י״ד","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["לְמִי מְיֻעָד הֶתֵּר הַמְּכִירָה?",["לְבַעַל גִּנָּה פְּרָטִית","לְיֶלֶד שֶׁיֵּשׁ לוֹ עָצִיץ","לְחַקְלַאי שֶׁמִּתְפַּרְנֵס מֵהָאֲדָמָה"],2,"הֶתֵּר הַמְּכִירָה מְיֻעָד לְחַקְלָאִים הַתְּלוּיִים בַּעֲבוֹדַת הָאֲדָמָה לְפַרְנָסָתָם, וְלֹא לְבַעֲלֵי גִּנּוֹת פְּרָטִיּוֹת.","פֶּרֶק ק״ה, הֲלָכָה ט״ו","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["בְּאוֹצַר בֵּית דִּין, עַל מָה מְשַׁלְּמִים הַקּוֹנִים?",["עַל הַפֵּרוֹת עַצְמָם","עַל הָאִסּוּף וְהָאֲרִיזָה","עַל הָאֲדָמָה"],1,"הַתַּשְׁלוּם אֵינוֹ עֲבוּר הַפֵּרוֹת, אֶלָּא רַק עֲבוּר טִרְחַת הַחַקְלַאי בְּאִסּוּף הַפֵּרוֹת, אֲרִיזָתָם וְשִׁוּוּקָם.","פֶּרֶק ק״ה, הֲלָכָה ט״ז","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["מָה קוֹרֶה לַחוֹבוֹת שֶׁזְּמַנָּם הִגִּיעַ, בְּסוֹף שְׁנַת הַשְּׁמִטָּה?",["נִמְחָקִים","מַכְפִּילִים אוֹתָם","מְשַׁלְּמִים אוֹתָם בְּפֵרוֹת"],0,"בְּרֹאשׁ הַשָּׁנָה שֶׁבְּסוֹף שְׁנַת הַשְּׁמִטָּה נִמְחָקִים הַחוֹבוֹת הַכַּסְפִּיִּים שֶׁכְּבָר הִגִּיעַ זְמַן הֶחְזֵרָם.","פֶּרֶק ק״ה, הֲלָכָה י״ז","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["מָה הוּא הַפְּרוֹזְבּוּל?",["שְׁטָר שֶׁחוֹתְמִים בִּפְנֵי בֵּית דִּין","סוּג שֶׁל פְּרִי","כְּלִי נְגִינָה בַּמִּקְדָּשׁ"],0,"הַפְּרוֹזְבּוּל הוּא שְׁטָר שֶׁהַמַּלְוֶה חוֹתֵם עָלָיו בִּפְנֵי בֵּית הַדִּין, וּמוֹסֵר לָהֶם אֶת גְּבִיַּת הַחוֹב.","פֶּרֶק ק״ה, הֲלָכָה י״ח","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["בַּמֶּה תָּקְעוּ הַכֹּהֲנִים כְּדֵי לְכַנֵּס אֶת הָעָם לְהַקְהֵל?",["בְּשׁוֹפָר","בְּפַעֲמוֹן","בַּחֲצוֹצְרוֹת"],2,"בְּהַגִּיעַ זְמַן הַמִּצְוָה הָיוּ הַכֹּהֲנִים תּוֹקְעִים בַּחֲצוֹצְרוֹת, וְהָעָם כֻּלּוֹ הִתְאַסֵּף לְבֵית הַמִּקְדָּשׁ.","פֶּרֶק ק״ה, הֲלָכָה י״ט","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["מָה עָלֵינוּ לַעֲשׂוֹת כְּדֵי לְקַיֵּם ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״?",["לְסַפֵּר בְּשִׁבְחוֹ שֶׁל הֶחָבֵר וְלִשְׁמֹר עַל מָמוֹנוֹ","לְדַבֵּר רַק עִם חֲבֵרִים קְרוֹבִים","לִשְׁמֹר רַק עַל הַחֲפָצִים שֶׁלִּי"],0,"עָלֵינוּ לְסַפֵּר בְּשִׁבְחוֹ שֶׁל הֶחָבֵר וּלְהַקְפִּיד שֶׁלֹּא יִגָּרֵם נֶזֶק לְמָמוֹנוֹ, כְּמוֹ שֶׁאָנוּ מַקְפִּידִים עַל שֶׁלָּנוּ.","פֶּרֶק ק״ו, הֲלָכָה א׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["לָמָּה ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״ הִיא כְּלָל גָּדוֹל בַּתּוֹרָה?",["כִּי הִיא הַמִּצְוָה הַקַּלָּה בְּיוֹתֵר","כִּי הִיא נוֹהֶגֶת רַק בְּשַׁבָּת","כִּי הִיא עוֹזֶרֶת לְקַיֵּם מִצְווֹת רַבּוֹת"],2,"הָאוֹהֵב אֶת חֲבֵרוֹ לֹא יִגְנֹב מִמֶּנּוּ, לֹא יַחְמֹד אֶת מָמוֹנוֹ, לֹא יְרַמֶּה אוֹתוֹ וְלֹא יְדַבֵּר עָלָיו לָשׁוֹן הָרַע.","פֶּרֶק ק״ו, הֲלָכָה ב׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אֵיזֶה מִן הַמַּעֲשִׂים הָאֵלּוּ הוּא גְּמִילוּת חֲסָדִים?",["לְשַׂחֵק כָּל הַיּוֹם בְּמַחְשֵׁב","לְבַקֵּר חוֹלֶה וּלְשַׂמֵּחַ אוֹתוֹ","לִקְנוֹת מַמְתָּקִים רַק לְעַצְמִי"],1,"בִּקּוּר חוֹלִים, נִחוּם אֲבֵלִים וְלִוּוּי אוֹרְחִים נִקְרָאִים גְּמִילוּת חֲסָדִים – כָּל דָּבָר שֶׁאָדָם עוֹשֶׂה בְּגוּפוֹ לְמַעַן אֲחֵרִים.","פֶּרֶק ק״ו, הֲלָכָה ג׳-ד׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["מִי יָכוֹל לְקַיֵּם מִצְוַת גְּמִילוּת חֲסָדִים?",["רַק אָדָם עָשִׁיר","רַק מִי שֶׁכְּבָר גָּדַל","גַּם מִי שֶׁאֵין לוֹ מָמוֹן – בְּגוּפוֹ"],2,"צְדָקָה הִיא בְּמָמוֹן, אֲבָל גְּמִילוּת חֲסָדִים הִיא גַּם בְּגוּף – וְלָכֵן גַּם מִי שֶׁאֵין לוֹ מָמוֹן יָכוֹל לְקַיְּמָהּ.","פֶּרֶק ק״ו, הֲלָכָה ה׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["שִׁמְעוֹן לֹא הִשְׁאִיל לִרְאוּבֵן אֶתְמוֹל, וְהַיּוֹם הוּא מְבַקֵּשׁ מִמֶּנּוּ. מָה צָרִיךְ רְאוּבֵן לַעֲשׂוֹת?",["לְסָרֵב, כְּדֵי לְלַמֵּד אוֹתוֹ לֶקַח","לְהַשְׁאִיל לוֹ בְּסֵבֶר פָּנִים יָפוֹת","לְהַשְׁאִיל וְלוֹמַר: אֵינִי קַמְצָן כָּמוֹךָ"],1,"לְסָרֵב – זֶה ״לֹא תִקֹּם״. לְהַשְׁאִיל וְלִלְעֹג – זֶה ״לֹא תִטֹּר״. עַל רְאוּבֵן לְהִתְגַּבֵּר עַל כַּעֲסוֹ וּלְהַשְׁאִיל בְּסֵבֶר פָּנִים יָפוֹת.","פֶּרֶק ק״ו, הֲלָכָה ו׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["מִפְּנֵי מָה חָרַב בֵּית הַמִּקְדָּשׁ הַשֵּׁנִי?",["מִפְּנֵי שִׂנְאַת חִנָּם","מִפְּנֵי שֶׁלֹּא לָמְדוּ תּוֹרָה","מִפְּנֵי שֶׁלֹּא הָיָה לָהֶם כֶּסֶף"],0,"בְּמִקְדָּשׁ שֵׁנִי עָסְקוּ בְּתוֹרָה, בְּמִצְווֹת וּבִגְמִילוּת חֲסָדִים, וְחָרַב מִפְּנֵי שֶׁהָיְתָה בּוֹ שִׂנְאַת חִנָּם.","פֶּרֶק ק״ו, הֲלָכָה ז׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["מָה עָשָׂה אַהֲרֹן כְּשֶׁרָאָה שְׁנֵי אֲנָשִׁים רָבִים?",["הִתְעַלֵּם וְהָלַךְ לְדַרְכּוֹ","צָעַק עַל שְׁנֵיהֶם בְּכַעַס","אָמַר לְכָל אֶחָד: חֲבֵרְךָ מִתְחָרֵט"],2,"אַהֲרֹן הָלַךְ לְכָל אֶחָד וְאָמַר שֶׁחֲבֵרוֹ מִתְחָרֵט וּמְבַקֵּשׁ מְחִילָה, וּכְשֶׁנִּפְגְּשׁוּ – הִתְפַּיְּסוּ.","פֶּרֶק ק״ו, הֲלָכָה ח׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אֵיךְ מְקַיְּמִים ״אַחֲרֵי ה׳ אֱ-לֹהֵיכֶם תֵּלֵכוּ״?",["הוֹלְכִים לְטַיֵּל בְּכָל יוֹם","הוֹלְכִים בְּמִדּוֹתָיו: מְבַקְּרִים חוֹלִים וּמַלְבִּישִׁים עֲרֻמִּים","הוֹלְכִים רַק אַחֲרֵי הָרַב"],1,"כְּשֵׁם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִלְבִּישׁ עֲרֻמִּים, בִּקֵּר חוֹלִים, נִחֵם אֲבֵלִים וְקָבַר מֵתִים – אַף אַתָּה עֲשֵׂה כָּךְ. הַנְּבִיאִים כִּנּוּ אוֹתוֹ בְּמִדּוֹתָיו הַטּוֹבוֹת כְּדֵי שֶׁנִּנְהַג בָּהֶן.","פֶּרֶק ק״ז, הֲלָכָה א׳-ב׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אֵיזוֹ דֶּרֶךְ הֶעֱדִיף רַבָּן יוֹחָנָן בֶּן זַכַּאי, כִּי הִיא כּוֹלֶלֶת אֶת כֻּלָּן?",["לֵב טוֹב","שָׁכֵן טוֹב","עַיִן טוֹבָה"],0,"רַבִּי אֶלְעָזָר בֶּן עֲרָךְ אָמַר ״לֵב טוֹב״, וְרַבָּן יוֹחָנָן אָמַר שֶׁבִּכְלַל דְּבָרָיו דִּבְרֵי כֻּלָּם.","פֶּרֶק ק״ז, הֲלָכָה ג׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אֵילוּ שְׁתֵּי מִצְווֹת עֲשֵׂה יֵשׁ לָנוּ כְּלַפֵּי הַהוֹרִים?",["לְשַׂחֵק אִתָּם וּלְסַפֵּר לָהֶם בְּדִיחוֹת","לְכַבֵּד אוֹתָם וְלִירֹא מִפְּנֵיהֶם","לְבַקֵּשׁ מֵהֶם מַתָּנוֹת וּמַמְתַּקִּים"],1,"כָּתוּב ״כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ״ וְכָתוּב ״אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ״. צָרִיךְ לְהַקְפִּיד בָּזֶה מְאֹד, כִּי הַתּוֹרָה הִשְׁוְתָה אֶת כְּבוֹדָם לִכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא.","פֶּרֶק ק״ח, הֲלָכוֹת א׳-ב׳","כִּבּוּד אָב וָאֵם"],["לָמָּה בְּ״כַּבֵּד״ הָאָב כָּתוּב קֹדֶם, וּבְ״תִּירָאוּ״ הָאֵם כְּתוּבָה קֹדֶם?",["כִּי הָאָב גָּדוֹל יוֹתֵר בַּשָּׁנִים","בְּלִי שׁוּם סִבָּה מְיֻחֶדֶת","כִּי בְּדֶרֶךְ כְּלָל מְכַבְּדִים יוֹתֵר אֶת הָאֵם וִירֵאִים יוֹתֵר מֵהָאָב"],2,"הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹדֵעַ שֶׁהַבֵּן מְכַבֵּד יוֹתֵר אֶת אִמּוֹ וְיָרֵא יוֹתֵר מֵאָבִיו, וְלָכֵן הִקְדִּים בְּכָל מִצְוָה אֶת מִי שֶׁפָּחוֹת מַרְגִּישִׁים כְּלַפָּיו.","פֶּרֶק ק״ח, הֲלָכָה ג׳","כִּבּוּד אָב וָאֵם"],["בְּמָה זוֹכֶה מִי שֶׁמְּכַבֵּד אֶת הוֹרָיו?",["אֲרִיכוּת יָמִים וְעוֹלָם שֶׁכֻּלּוֹ טוֹב","הַרְבֵּה כֶּסֶף וּמַשְׂכֹּרֶת גְּבוֹהָה","פְּטוֹר מִכָּל שְׁאָר הַמִּצְווֹת"],0,"בִּזְכוּת הַמִּצְוָה זוֹכֶה אָדָם בָּעוֹלָם הַזֶּה לַאֲרִיכוּת יָמִים, וּבָעוֹלָם הַבָּא לָעוֹלָם שֶׁכֻּלּוֹ טוֹב. וְהִיא גְּדוֹלָה, כִּי נִצְטַוִּינוּ עָלֶיהָ בַּעֲשֶׂרֶת הַדִּבְּרוֹת.","פֶּרֶק ק״ח, הֲלָכָה ד׳","כִּבּוּד אָב וָאֵם"],["אַבָּא מְבַקֵּשׁ שֶׁתִּקְנֶה לוֹ תְּרוּפָה. מַה תַּעֲשֶׂה?",["אֵלֵךְ בְּפָנִים זוֹעֲפוֹת וַאֲנִי מִתְלוֹנֵן","אֵלֵךְ בְּשִׂמְחָה וּבְסֵבֶר פָּנִים יָפוֹת","אֹמַר שֶׁאֵין לִי זְמַן"],1,"חוֹבָה לְמַלֵּא אֶת שְׁלִיחוּת הַהוֹרִים, וְאֶת הַכֹּל יֵשׁ לַעֲשׂוֹת בְּסֵבֶר פָּנִים יָפוֹת. עֶזְרָה בְּפָנִים זוֹעֲפוֹת אֵינָהּ כִּבּוּד הוֹרִים.","פֶּרֶק ק״ח, הֲלָכָה ה׳","כִּבּוּד אָב וָאֵם"],["בְּבֵית הַכְּנֶסֶת, הַמָּקוֹם הַקָּבוּעַ שֶׁל אַבָּא פָּנוּי כִּי הוּא עוֹד לֹא הִגִּיעַ. מֻתָּר לָשֶׁבֶת שָׁם?",["רַק אִם אֵין מָקוֹם אַחֵר","כֵּן, כִּי אַבָּא לֹא נִמְצָא","לֹא, גַּם כְּשֶׁאַבָּא לֹא נִמְצָא"],2,"אֵין לְהִתְפַּלֵּל אוֹ לָשֶׁבֶת בִּמְקוֹמָם הַקָּבוּעַ שֶׁל הַהוֹרִים, אֲפִלּוּ אִם הֵם לֹא נִמְצָאִים בַּמָּקוֹם.","פֶּרֶק ק״ח, הֲלָכָה ו׳","כִּבּוּד אָב וָאֵם"],["אֵיזֶה מַעֲשֶׂה שׁוֹמֵר עַל מוֹרָא הַהוֹרִים?",["לֹא לִקְרֹא לְאַבָּא בִּשְׁמוֹ הַפְּרָטִי","לוֹמַר לְמִי שֶׁחוֹלֵק עַל אַבָּא: אַתָּה צוֹדֵק","לַחְלֹק עַל אַבָּא בְּקוֹל רָם"],0,"אֵין לִקְרֹא לַהוֹרִים בִּשְׁמָם, וְאֵין לַחְלֹק עַל דִּבְרֵיהֶם – לֹא יְשִׁירוֹת וְלֹא בְּכָךְ שֶׁאוֹמְרִים לְמִי שֶׁחוֹלֵק עֲלֵיהֶם שֶׁדְּבָרָיו נִרְאִים יוֹתֵר.","פֶּרֶק ק״ח, הֲלָכוֹת ז׳-ח׳","כִּבּוּד אָב וָאֵם"],["אַבָּא יָשֵׁן, וְהִגִּיעַ הַזְּמַן לָלֶכֶת לְבֵית הַכְּנֶסֶת. מֻתָּר לְהָעִיר אוֹתוֹ?",["אָסוּר לְעוֹלָם","מֻתָּר, כִּי זֶה לְצֹרֶךְ מִצְוָה","מֻתָּר רַק בִּצְעָקָה"],1,"אָסוּר לְהָעִיר אֶת הַהוֹרִים אִם זֶה יְצַעֵר אוֹתָם, אֲבָל מֻתָּר לְצֹרֶךְ מִצְוָה, אוֹ כְּשֶׁיָּדוּעַ בְּבֵרוּר שֶׁהֵם רוֹצִים לָקוּם בְּשָׁעָה מְסֻיֶּמֶת.","פֶּרֶק ק״ח, הֲלָכָה ט׳","כִּבּוּד אָב וָאֵם"],["הַהוֹרִים זָרְקוּ לַיָּם כִּיס מָלֵא מַטְבְּעוֹת זָהָב שֶׁל בְּנָם. מַה יַּעֲשֶׂה?",["יִכְעַס וְיִצְעַק עֲלֵיהֶם","יִתְבַּע אוֹתָם בְּבֵית דִּין","יִשְׁתֹּק וְלֹא יַכְלִים אוֹתָם"],2,"אָמְרוּ חֲכָמִים: אֲפִלּוּ הִשְׁלִיכוּ אֶת כִּיס הַזְּהוּבִים שֶׁלּוֹ לַיָּם – לֹא יַכְלִימֵם וְלֹא יִכְעַס, אֶלָּא יִשְׁתֹּק.","פֶּרֶק ק״ח, הֲלָכָה י׳","כִּבּוּד אָב וָאֵם"],["רָאִיתָ שֶׁאַבָּא עוֹבֵר עַל דִּבְרֵי תּוֹרָה. אֵיךְ תָּעִיר לוֹ?",["אֲבַזֶּה אוֹתוֹ וְאֶצְעַק: עָבַרְתָּ עַל הַתּוֹרָה!","אֶשְׁאַל: אַבָּא, כָּתוּב בַּתּוֹרָה כָּךְ וְכָךְ?","אֶצְחַק עָלָיו לִפְנֵי הַחֲבֵרִים"],1,"אָסוּר לְהָעִיר לַהוֹרִים בְּאֹפֶן יָשִׁיר, אֶלָּא שׁוֹאֲלִים שְׁאֵלָה וְהָאַבָּא יָבִין מֵעַצְמוֹ. וְאָסוּר לְגַמְרֵי לְקַלֵּל וּלְבַזּוֹת אֶת הַהוֹרִים.","פֶּרֶק ק״ח, הֲלָכוֹת י״א-י״ב","כִּבּוּד אָב וָאֵם"],["מָה נָכוֹן?",["אֵין צֹרֶךְ לְכַבֵּד סַבָּא וְאַחִים גְּדוֹלִים","הוֹרִים צְרִיכִים לְהַקְפִּיד עַל כָּל פְּרָט בִּכְבוֹדָם","כְּבוֹד הַהוֹרִים קוֹדֵם, וְהוֹרִים יִמְחֲלוּ עַל כְּבוֹדָם"],2,"מְכַבְּדִים אַחִים גְּדוֹלִים וְסַבָּא, אֲבָל כְּבוֹד הַהוֹרִים קוֹדֵם. וְהַהוֹרִים לֹא יַכְבִּידוּ עַל יַלְדֵיהֶם, אֶלָּא יִמְחֲלוּ – וְאָב שֶׁמָּחַל עַל כְּבוֹדוֹ, כְּבוֹדוֹ מָחוּל.","פֶּרֶק ק״ח, הֲלָכוֹת י״ג-י״ד","כִּבּוּד אָב וָאֵם"],["מָה אוֹמֶרֶת הַתּוֹרָה לַעֲשׂוֹת כְּשֶׁפּוֹגְשִׁים אָח אֶבְיוֹן?",["לִפְתֹּחַ אֶת הַיָּד וְלָתֵת לוֹ","לִקְפֹּץ אֶת הַיָּד וְלִסְגֹּר אוֹתָהּ","לְהִתְעַלֵּם וְלָלֶכֶת"],0,"הַתּוֹרָה אוֹמֶרֶת: ״לֹא תִקְפֹּץ אֶת יָדְךָ... כִּי פָתֹחַ תִּפְתַּח אֶת יָדְךָ לוֹ״.","פֶּרֶק ק״ט, הֲלָכָה א׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["הַאִם אָדָם יָכוֹל לְהֵעָשׂוֹת עָנִי בִּגְלַל שֶׁנָּתַן צְדָקָה?",["כֵּן, הַכֶּסֶף שֶׁלּוֹ נִגְמָר","לְעוֹלָם לֹא, הַצְּדָקָה מְבִיאָה שָׁלוֹם","רַק אִם נָתַן הַרְבֵּה מְאֹד"],1,"לְעוֹלָם אֵין אָדָם נַעֲשֶׂה עָנִי בְּשֶׁל מִצְוַת הַצְּדָקָה, שֶׁנֶּאֱמַר: ״וְהָיָה מַעֲשֵׂה הַצְּדָקָה שָׁלוֹם״.","פֶּרֶק ק״ט, הֲלָכָה ב׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["אֵיזוֹ מִצְוָה גְּדוֹלָה יוֹתֵר?",["מִצְוַת צְדָקָה","שְׁתֵּיהֶן שָׁווֹת בְּדִיּוּק","מִצְוַת הַלְוָאָה"],2,"מִצְוַת הַלְוָאָה גְּדוֹלָה יוֹתֵר מִן הַצְּדָקָה, כִּי הִיא מוֹנַעַת מֵהָאָדָם לִפֹּל לִמְצוּקָה וְעוֹזֶרֶת לוֹ לְשַׁקֵּם אֶת חַיָּיו בְּכוֹחוֹת עַצְמוֹ.","פֶּרֶק ק״ט, הֲלָכָה ג׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["אֵיךְ צָרִיךְ לָתֵת צְדָקָה לֶעָנִי?",["בְּסֵבֶר פָּנִים יָפוֹת וּבְשִׂמְחָה","בְּפָנִים כּוֹעֲסוֹת","בְּלִי לְהִסְתַּכֵּל עָלָיו"],0,"צָרִיךְ לָתֵת צְדָקָה בְּסֵבֶר פָּנִים יָפוֹת וּבְשִׂמְחָה, וּלְנַחֵם וּלְעוֹדֵד אֶת הֶעָנִי.","פֶּרֶק ק״ט, הֲלָכָה ד׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["מִי שֶׁנָּתַן הַרְבֵּה כֶּסֶף אֲבָל בִּיֵּשׁ אֶת הֶעָנִי, מָה קִבֵּל?",["שָׂכָר גָּדוֹל מְאֹד","הִפְסִיד אֶת שְׂכַר הַמִּצְוָה","חֲצִי שָׂכָר"],1,"הַמְּבַיֵּשׁ אֶת הֶעָנִי בִּזְמַן הַנְּתִינָה, אֲפִלּוּ נָתַן כֶּסֶף רַב, אִבֵּד אֶת זְכוּת הַמִּצְוָה וְהִפְסִיד אֶת שְׂכָרָהּ.","פֶּרֶק ק״ט, הֲלָכָה ה׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["מָה שְׂכָרוֹ שֶׁל מִי שֶׁמַּשְׁפִּיעַ עַל אֲחֵרִים לָתֵת צְדָקָה?",["שְׂכָרוֹ קָטָן","אֵין לוֹ שָׂכָר","שְׂכָרוֹ גָּדוֹל מִשְּׂכַר הַנּוֹתְנִים"],2,"מִי שֶׁמַּשְׁפִּיעַ עַל אֲחֵרִים לָתֵת צְדָקָה, שְׂכָרוֹ גָּדוֹל יוֹתֵר מִשְּׂכַר הַנּוֹתְנִים עַצְמָם.","פֶּרֶק ק״ט, הֲלָכָה ו׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["מַהִי הַדֶּרֶךְ הַטּוֹבָה בְּיוֹתֵר לַעֲזֹר לְנִזְקָק?",["לַעֲזֹר לוֹ לְהִתְפַּרְנֵס בְּכוֹחוֹת עַצְמוֹ","לָתֵת לוֹ מַמְתָּק","לוֹמַר לוֹ לְחַכּוֹת"],0,"הַדֶּרֶךְ הַטּוֹבָה בְּיוֹתֵר הִיא לָתֵת מַתָּנָה אוֹ הַלְוָאָה כָּךְ שֶׁהַמְּקַבֵּל יוּכַל לְהִתְפַּרְנֵס בְּכוֹחוֹת עַצְמוֹ.","פֶּרֶק ק״ט, הֲלָכָה ז׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["מַהִי הַדֶּרֶךְ הַטּוֹבָה בְּיוֹתֵר לָתֵת כֶּסֶף לִצְדָקָה?",["לָתֵת בַּיָּד מוּל כֻּלָּם","לָשִׂים בְּקֻפַּת צְדָקָה: מַתָּן בַּסֵּתֶר","לְהַכְרִיז בְּרַמְקוֹל"],1,"הַטּוֹב בְּיוֹתֵר לָשִׂים אֶת הַכֶּסֶף בְּקֻפַּת צְדָקָה, וְכָךְ הַנּוֹתֵן אֵינוֹ יוֹדֵעַ לְמִי נָתַן וְהֶעָנִי אֵינוֹ יוֹדֵעַ מִמִּי קִבֵּל.","פֶּרֶק ק״ט, הֲלָכָה ח׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["מִי חַיָּב לָתֵת צְדָקָה?",["רַק עֲשִׁירִים","רַק מְבֻגָּרִים","כָּל אָדָם, אֲפִלּוּ עָנִי"],2,"כָּל אָדָם חַיָּב לָתֵת צְדָקָה. אֲפִלּוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה חַיָּב לָתֵת קְצָת מִמַּה שֶּׁקִּבֵּל.","פֶּרֶק ק״ט, הֲלָכָה ט׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["בְּאֵיזֶה יוֹם מוֹסִיפִים נֻסָּח מְיֻחָד בְּבִרְכַּת הַמָּזוֹן?",["בְּיוֹם שְׁלִישִׁי רָגִיל","בְּשַׁבָּת","בְּיוֹם רִאשׁוֹן רָגִיל"],1,"בְּשַׁבָּת, בְּרֹאשׁ חֹדֶשׁ, בְּיָמִים טוֹבִים, בַּחֲנֻכָּה וּבְפוּרִים מוֹסִיפִים נֻסָּח מְיֻחָד לְכָל יוֹם.","פֶּרֶק כ״ד, הֲלָכָה ט׳","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["יֶלֶד מְבָרֵךְ בִּרְכַּת הַמָּזוֹן, וְאַבָּא נִכְנַס וְאוֹמֵר ״שָׁלוֹם״. מָה עוֹשִׂים?",["עוֹנִים ״שָׁלוֹם״ וּמַמְשִׁיכִים","עוֹצְרִים וּמְסַפְּרִים לְאַבָּא עַל הַיּוֹם","מַמְשִׁיכִים לְבָרֵךְ וְלֹא מַפְסִיקִים"],2,"בִּרְכַּת הַמָּזוֹן הִיא מִן הַתּוֹרָה, וְלָכֵן אֵין לְהַפְסִיק בְּאֶמְצָעָהּ אֲפִילּוּ כְּדֵי לְהָשִׁיב ״שָׁלוֹם״ לַהוֹרִים אוֹ לָרַב.","פֶּרֶק כ״ד, הֲלָכָה י׳","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["מָה מֻתָּר לַעֲשׂוֹת בִּזְמַן בִּרְכַּת הַמָּזוֹן?",["לָשֶׁבֶת וּלְבָרֵךְ בְּרִכּוּז","לְסַדֵּר אֶת הַצַּלָּחוֹת","לִרְמֹז לְחָבֵר בָּעֵינַיִם"],0,"אָסוּר לַעֲסֹק בְּשׁוּם מְלָאכָה בִּזְמַן בִּרְכַּת הַמָּזוֹן, אֲפִילּוּ עִסּוּק קַל, וְאָסוּר לִרְמֹז בָּעֵינַיִם אוֹ בַּשְּׂפָתַיִם.","פֶּרֶק כ״ד, הֲלָכָה י״א","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["יֶלֶד שָׁכַח לְבָרֵךְ וְנִזְכַּר אַחֲרֵי חֲצִי שָׁעָה. מָה יַעֲשֶׂה?",["לֹא יְבָרֵךְ כְּלָל","יְבָרֵךְ","יְחַכֶּה לַסְּעוּדָה הַבָּאָה"],1,"אִם נִזְכַּר בְּתוֹךְ שִׁבְעִים וּשְׁתַּיִם דַּקּוֹת – יְבָרֵךְ, כִּי הַמָּזוֹן עֲדַיִן לֹא הִתְעַכֵּל.","פֶּרֶק כ״ד, הֲלָכָה י״ב","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["מָתַי הֲכִי טוֹב לְבָרֵךְ בִּרְכַּת הַמָּזוֹן?",["לִפְנֵי הַשֵּׁינָה בַּלַּיְלָה","אַחֲרֵי הַמִּשְׂחָק בַּחוּץ","מִיָּד אַחֲרֵי הַסְּעוּדָה"],2,"צָרִיךְ לְהִשְׁתַּדֵּל מְאוֹד לְבָרֵךְ מִיָּד אַחֲרֵי הַסְּעוּדָה – כָּךְ מַפְנִימִים אֶת חֲשִׁיבוּת הַבְּרָכָה וְנִמְנָעִים מִסְּפֵקוֹת.","פֶּרֶק כ״ד, הֲלָכָה י״ג","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["יֶלֶד אָכַל סְעוּדָה גְּדוֹלָה וְשָׂבַע, וְאֵינוֹ זוֹכֵר אִם בֵּרַךְ. מָה יַעֲשֶׂה?",["יְבָרֵךְ","לֹא יְבָרֵךְ","יִשְׁאַל רַק מָחָר"],0,"מִי שֶׁאָכַל וְשָׂבַע חַיָּב מִן הַתּוֹרָה, וּ״סְפֵק דְּאוֹרַיְתָא לְחֻמְרָא״ – לָכֵן יְבָרֵךְ.","פֶּרֶק כ״ד, הֲלָכָה י״ד","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["לְפִי מָה תִּנְהַג כָּל אִשָּׁה שֶׁאֵינָהּ זוֹכֶרֶת אִם בֵּרְכָה בִּרְכַּת הַמָּזוֹן?",["לְפִי מַה שֶּׁנּוֹחַ לָהּ","כְּמִנְהַג מִשְׁפַּחְתָּהּ","לְפִי מַה שֶּׁעוֹשִׂים הַשְּׁכֵנִים"],1,"יֵשׁ אוֹמְרִים שֶׁנָּשִׁים חַיָּבוֹת מִן הַתּוֹרָה וְיֵשׁ אוֹמְרִים מִדְּרַבָּנָן, וְכָל אִשָּׁה תִּנְהַג כְּמִנְהַג מִשְׁפַּחְתָּהּ.","פֶּרֶק כ״ד, הֲלָכָה ט״ז","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["לָמָּה גַּם יְלָדִים קְטַנִּים מְבָרְכִים בִּרְכַּת הַמָּזוֹן?",["כְּדֵי לְקַבֵּל פְּרָס","כְּדֵי לְהַרְשִׁים אֶת הָאוֹרְחִים","כְּדֵי לְחַנְּכָם לַמִּצְוָה"],2,"קְטַנִּים חַיָּבִים בְּבִרְכַּת הַמָּזוֹן מִדְּרַבָּנָן כְּדֵי לְחַנְּכָם.","פֶּרֶק כ״ד, הֲלָכָה י״ז","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["אֵין לְאָדָם הַרְבֵּה כֶּסֶף, וְעָנִי מְבַקֵּשׁ מִמֶּנּוּ צְדָקָה. מָה יַעֲשֶׂה?",["לֹא יִתֵּן כְּלוּם","יִתֵּן מְעַט","יִשְׁלַח אוֹתוֹ לְאָדָם אַחֵר"],1,"יֵשׁ לְהִשְׁתַּדֵּל לָתֵת לְכָל עָנִי שֶׁמְּבַקֵּשׁ, וְאִם אֵין אֶפְשָׁרוּת לָתֵת סְכוּם גָּדוֹל – יִתֵּן מְעַט.","פֶּרֶק ק״ט, הֲלָכָה י׳","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["כַּמָּה נוֹהֲגִים כַּיּוֹם לָתֵת לִצְדָקָה, לְכָל הַפָּחוֹת?",["עֲשִׂירִית מִמַּה שֶּׁהִרְוִיחַ","חֲצִי מִכָּל הַכֶּסֶף","מַטְבֵּעַ אֶחָד בְּשָׁנָה"],0,"כַּיּוֹם נוֹהֲגִים לָתֵת לְכָל הַפָּחוֹת ״מַעֲשַׂר כְּסָפִים״ – עֲשִׂירִית מִמַּה שֶּׁהִרְוִיחַ. וְהַנּוֹתֵן חֲמִישִׁית מְקַיֵּם מִצְוָה מִן הַמֻּבְחָר.","פֶּרֶק ק״ט, הֲלָכָה י״א","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["מָה עָשׂוּ גְּדוֹלֵי הַחֲכָמִים לִפְנֵי הַתְּפִלָּה?",["אָכְלוּ אֲרוּחַת בֹּקֶר","הָלְכוּ לִישֹׁן","נָתְנוּ פְּרוּטָה לְעָנִי"],2,"גְּדוֹלֵי הַחֲכָמִים נָתְנוּ פְּרוּטָה לְעָנִי לִפְנֵי הַתְּפִלָּה, שֶׁנֶּאֱמַר: ״אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךָ״.","פֶּרֶק ק״ט, הֲלָכָה י״ב","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["הַמַּלְוֶה יוֹדֵעַ שֶׁאֵין לַלּוֹוֶה כֶּסֶף. מָה נָכוֹן?",["יַעֲמֹד מוּלוֹ כָּל יוֹם","לֹא יַרְאֶה אֶת עַצְמוֹ לְפָנָיו כְּדֵי שֶׁלֹּא יִתְבַּיֵּשׁ","יִדְרֹשׁ אֶת הַכֶּסֶף בְּקוֹל רָם"],1,"אָסוּר לִתְבֹּעַ עָנִי שֶׁאֵין לוֹ לְשַׁלֵּם – ״לֹא תִהְיֶה לוֹ כְּנֹשֶׁה״. וַאֲפִלּוּ לְהַרְאוֹת אֶת עַצְמוֹ לְפָנָיו אָסוּר, כִּי הַלּוֹוֶה עָלוּל לְהִתְבַּיֵּשׁ.","פֶּרֶק ק״ט, הֲלָכָה י״ג","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["מִי שֶׁלָּוָה כֶּסֶף, עַל מָה אָסוּר לוֹ לְהוֹצִיא אוֹתוֹ, אִם יֵשׁ חֲשָׁשׁ שֶׁלֹּא יוּכַל לְשַׁלֵּם?",["עַל דְּבָרִים שֶׁאֵין בָּהֶם צֹרֶךְ","עַל אֹכֶל לְמִשְׁפַּחְתּוֹ","עַל תְּרוּפָה לְחוֹלֶה"],0,"אָסוּר לִלְווֹת וּלְבַזְבֵּז עַל דְּבָרִים מְיֻתָּרִים כְּשֶׁיֵּשׁ חֲשָׁשׁ שֶׁלֹּא יְשַׁלֵּם – ״לֹוֶה רָשָׁע וְלֹא יְשַׁלֵּם״.","פֶּרֶק ק״ט, הֲלָכָה י״ד","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["הִגִּיעַ זְמַן הֶחְזֵר הַחוֹב וְיֵשׁ לַלּוֹוֶה כֶּסֶף. מָה יַעֲשֶׂה?",["יֹאמַר ״לֵךְ וָשׁוּב מָחָר״","יִתְחַבֵּא","יַחְזִיר מִיָּד"],2,"מִי שֶׁיֵּשׁ בְּאֶפְשָׁרוּתוֹ – יַחְזִיר מִיָּד, שֶׁנֶּאֱמַר: ״אַל תֹּאמַר לְרֵעֲךָ לֵךְ וָשׁוּב וּמָחָר אֶתֵּן, וְיֵשׁ אִתָּךְ״.","פֶּרֶק ק״ט, הֲלָכָה ט״ו","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["אֵין לַלּוֹוֶה כֶּסֶף לְהַחְזִיר בַּזְּמַן. מָה נָכוֹן לַעֲשׂוֹת?",["לְבַקֵּשׁ מֵהַמַּלְוֶה לִדְחוֹת אֶת הַמּוֹעֵד","לְהַמְצִיא תֵּרוּץ שֶׁל שֶׁקֶר","לְהִתְעַלֵּם מֵהַמַּלְוֶה"],0,"יְבַקֵּשׁ מֵהַמַּלְוֶה לִדְחוֹת אֶת מוֹעֵד הַפֵּרָעוֹן, אַךְ לֹא יִדְחֶה אוֹתוֹ בְּתֵרוּצֵי שָׁוְא אוֹ בְּדִבְרֵי שֶׁקֶר.","פֶּרֶק ק״ט, הֲלָכָה ט״ז","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["הַלּוֹוֶה חוֹשֵׁב שֶׁהַמַּלְוֶה שָׁכַח מֵהַחוֹב. מָה יַעֲשֶׂה?",["יִשְׁתֹּק וְיִשְׁמֹר אֶת הַכֶּסֶף","יַחְזִיר אֶת הַחוֹב","יְחַכֶּה שֶׁיִּזְכֹּר"],1,"גַּם אִם הַלּוֹוֶה חוֹשֵׁב שֶׁהַמַּלְוֶה שָׁכַח – עָלָיו לְהָשִׁיב אֶת הַחוֹב.","פֶּרֶק ק״ט, הֲלָכָה י״ז","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["מִי שֶׁחַיָּב כֶּסֶף לַחֲבֵרוֹ – מָה צָרִיךְ לָבוֹא קֹדֶם?",["לְהַרְבּוֹת בִּצְדָקָה","לִקְנוֹת דְּבָרִים חֲדָשִׁים","לְהַחְזִיר אֶת הַחוֹב"],2,"מִי שֶׁחַיָּב לְהַחְזִיר הַלְוָאָה לֹא יַרְבֶּה בִּצְדָקָה טֶרֶם יָשִׁיב, וּבְוַדַּאי שֶׁלֹּא יְבַזְבֵּז עַל דְּבָרִים אֲחֵרִים.","פֶּרֶק ק״ט, הֲלָכָה י״ח","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["הַקָּדוֹשׁ בָּרוּךְ הוּא בִּקֵּר אֶת אַבְרָהָם כְּשֶׁהָיָה חוֹלֶה. מָה לוֹמְדִים מִזֶּה?",["גַּם אֲנַחְנוּ צְרִיכִים לְבַקֵּר חוֹלִים","צָרִיךְ לָשֶׁבֶת בְּפֶתַח הָאֹהֶל","חוֹלִים צְרִיכִים לִהְיוֹת לְבַד"],0,"כְּשֵׁם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְבַקֵּר חוֹלִים, אַף אָנוּ מְצֻוִּים לְהִדָּבֵק בִּדְרָכָיו וּלְבַקֵּר חוֹלִים.","פֶּרֶק ק״י, הֲלָכָה א׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["בִּקּוּר חוֹלִים הוּא חֵלֶק מֵאֵיזוֹ מִצְוָה?",["מִצְוַת שַׁבָּת","״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״","מִצְוַת סֻכָּה"],1,"בִּקּוּר חוֹלִים הוּא חֵלֶק מִ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״, וְאוֹכְלִים פֵּרוֹתָיו בָּעוֹלָם הַזֶּה וְהַקֶּרֶן קַיֶּמֶת לָעוֹלָם הַבָּא.","פֶּרֶק ק״י, הֲלָכוֹת ב׳ וְג׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מָה עָשָׂה רַבִּי עֲקִיבָא כְּשֶׁבִּקֵּר אֶת תַּלְמִידוֹ הַחוֹלֶה?",["הָלַךְ מִיָּד הַבַּיְתָה","נָתַן לוֹ סֵפֶר לִלְמֹד","נִקָּה אֶת הַבַּיִת שֶׁלּוֹ"],2,"רַבִּי עֲקִיבָא כִּבֵּד וְרִבֵּץ אֶת הַבַּיִת, וְהַתַּלְמִיד אָמַר: ״רַבִּי, הֶחֱיִיתַנִי״.","פֶּרֶק ק״י, הֲלָכָה ד׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["רוֹצִים לְבַקֵּר חָבֵר חוֹלֶה. מָה עוֹשִׂים קֹדֶם?",["שׁוֹאֲלִים אֶת הַמִּשְׁפָּחָה אִם הוּא רוֹצֶה בִּקּוּר","בָּאִים בְּהַפְתָּעָה עִם הַרְבֵּה רַעַשׁ","נִשְׁאָרִים אֶצְלוֹ עַד הַלַּיְלָה"],0,"עִקַּר הַבִּקּוּר הוּא לְעוֹדֵד אֶת הַחוֹלֶה, לָכֵן שׁוֹאֲלִים קֹדֶם, וּלְעִתִּים עֲדִיפָה שִׂיחַת טֶלֶפוֹן אוֹ הוֹדָעָה.","פֶּרֶק ק״י, הֲלָכוֹת ה׳ וְו׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["כַּמָּה פְּעָמִים מֻתָּר לְבַקֵּר חוֹלֶה?",["רַק פַּעַם אַחַת","אַף פַּעַם","אֲפִלּוּ כַּמָּה פְּעָמִים בַּיּוֹם"],2,"אֲפִלּוּ אָדָם גָּדוֹל מְבַקֵּר כַּמָּה פְּעָמִים בַּיּוֹם, וְכָל הַמּוֹסִיף מְשֻׁבָּח, אֲבָל לֹא מַטְרִיחִים אֶת הַחוֹלֶה.","פֶּרֶק ק״י, הֲלָכָה ז׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["כְּשֶׁמִּתְפַּלְּלִים עַל חוֹלֶה, עַל מִי עוֹד מִתְפַּלְּלִים אִתּוֹ?",["עַל כָּל חוֹלֵי יִשְׂרָאֵל","רַק עַל הַחוֹלֶה הַזֶּה","עַל הַשָּׁכֵן שֶׁלּוֹ"],0,"אוֹמְרִים: ״הַמָּקוֹם יְרַחֵם עָלֶיךָ בְּתוֹךְ חוֹלֵי יִשְׂרָאֵל״.","פֶּרֶק ק״י, הֲלָכָה ח׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["יוֹסִי חוֹלֶה. מָה הוּא צָרִיךְ לַעֲשׂוֹת?",["לְחַכּוֹת לְנֵס","לָלֶכֶת לָרוֹפֵא וּלְהִתְפַּלֵּל לַה׳","לֹא לְסַפֵּר לְאַף אֶחָד"],1,"אָסוּר לִסְמֹךְ עַל הַנֵּס; הוֹלְכִים לָרוֹפֵא, וְזוֹכְרִים שֶׁהָרְפוּאָה בִּידֵי ה׳ וְהָרוֹפְאִים שְׁלִיחָיו.","פֶּרֶק ק״י, הֲלָכוֹת ט׳ וְי׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["שְׁלֹמֹה הַמֶּלֶךְ אָמַר: ״טוֹב שָׁכֵן קָרוֹב מֵ...״",["מֶלֶךְ גָּדוֹל","אָח רָחוֹק","בַּיִת גָּדוֹל"],1,"״טוֹב שָׁכֵן קָרוֹב מֵאָח רָחוֹק״, וְרַבִּי יוֹסֵי אָמַר שֶׁהַדֶּרֶךְ הַטּוֹבָה הִיא שָׁכֵן טוֹב.","פֶּרֶק קי״א, הֲלָכָה א׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מִמִּי צָרִיךְ לְהִתְרַחֵק?",["מִשָּׁכֵן טוֹב","מִשָּׁכֵן רַע","מִכָּל הַשְּׁכֵנִים"],1,"אוֹהֲבִים אֶת הַשְּׁכֵנִים וְכָךְ אַהֲבַת הַבְּרִיּוֹת מִתְפַּשֶּׁטֶת, אֲבָל ״הַרְחֵק מִשָּׁכֵן רַע״ כִּי אֶפְשָׁר לִלְמֹד מִמֶּנּוּ.","פֶּרֶק קי״א, הֲלָכוֹת ב׳ וְג׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מָה עוֹשֶׂה שָׁכֵן טוֹב בְּחֲדַר הַמַּדְרֵגוֹת?",["מַרְעִישׁ בַּלַּיְלָה","זוֹרֵק נְיָרוֹת","שׁוֹמֵר עַל שֶׁקֶט וְנִקָּיוֹן"],2,"מִתְחַשְּׁבִים בַּשְּׁכֵנִים, וְאִם יֵשׁ בְּעָיָה מְדַבְּרִים בְּדַרְכֵי נֹעַם וְלֹא רָבִים.","פֶּרֶק קי״א, הֲלָכוֹת ד׳ וְה׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מוֹכֵר יוֹדֵעַ שֶׁהַקּוֹנֶה אֵינוֹ מַכִּיר אֶת מְחִיר הַמּוּצָר. מַה עָלָיו לַעֲשׂוֹת?",["לִמְכֹּר בִּמְחִיר מֻפְרָז","לִמְכֹּר בַּמְּחִיר הָאֲמִתִּי וְהַהוֹגֵן","לְהַסְתִּיר אֶת הַמְּחִיר"],1,"אוֹנָאָה הִיא רַמָּאוּת, וְאָסוּר מִן הַתּוֹרָה לִמְכֹּר בִּמְחִיר מֻפְרָז תּוֹךְ נִצּוּל זֶה שֶׁהַקּוֹנֶה אֵינוֹ יוֹדֵעַ.","פֶּרֶק קי״ב, הֲלָכוֹת א׳-ב׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["אֵיזֶה דּוּכַן פֵּרוֹת נוֹהֵג כַּהֲלָכָה?",["מְעָרֵב פֵּרוֹת רָעִים בֵּין הַיָּפִים","מוֹכֵר פְּרִי רָקוּב כְּאִלּוּ הוּא טָרִי","מוֹכֵר כָּל פְּרִי כְּפִי שֶׁהוּא בֶּאֱמֶת"],2,"אָסוּר לְעָרֵב פֵּרוֹת רָעִים בֵּין הַיָּפִים כְּדֵי לִמְכֹּר אוֹתָם כְּפֵרוֹת יָפִים.","פֶּרֶק קי״ב, הֲלָכָה ג׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["יֶלֶד הֶעְתִּיק שִׁעוּרֵי בַּיִת מֵחָבֵר וְהִגִּישׁ אוֹתָם כְּאִלּוּ כָּתַב בְּעַצְמוֹ. מַה זֶּה?",["גְּנֵבַת דַּעַת","עֲבוֹדָה חֲרוּצָה","עֶזְרָה לְחָבֵר"],0,"אָסוּר לְהַעֲתִיק מֵחָבֵר שִׁעוּרֵי בַּיִת וּלְהַגִּישׁ אוֹתָם כְּאִלּוּ הַמַּגִּישׁ כָּתַב אוֹתָם – זוֹ גְּנֵבַת דַּעַת.","פֶּרֶק קי״ב, הֲלָכָה ד׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["אָדָם נִכְנָס לַחֲנוּת וְשׁוֹאֵל עַל מְחִיר, וּמֵרֹאשׁ אֵין לוֹ כַּוָּנָה לִקְנוֹת. מַה הַדִּין?",["מֻתָּר, זוֹ רַק שְׁאֵלָה","אָסוּר, זוֹ אוֹנָאַת דְּבָרִים","זוֹ מִצְוָה"],1,"בָּזֶה מְפַתְּחִים אֵצֶל הַמּוֹכֵר צִפִּיַּת שָׁוְא וְגוֹרְמִים לוֹ אַכְזָבָה וְצַעַר מְיֻתָּרִים.","פֶּרֶק קי״ב, הֲלָכָה ה׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["״מִי יֵדַע אִם בֶּאֱמֶת הִתְכַּוַּנְתִּי לִקְנוֹת?״ – מִי יוֹדֵעַ?",["אַף אֶחָד","רַק הַמּוֹכֵר","ה׳ יוֹדֵעַ אֶת מַחְשְׁבוֹתֵינוּ"],2,"לָכֵן נֶאֱמַר ״וְיָרֵאתָ מֵאֱ-לֹהֶיךָ״ – ה׳ יוֹדֵעַ אֶת מַחְשְׁבוֹתֶיךָ וְאֶת כַּוָּנוֹתֶיךָ.","פֶּרֶק קי״ב, הֲלָכָה ו׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["אֵיזוֹ אוֹנָאָה חֲמוּרָה יוֹתֵר?",["אוֹנָאַת מָמוֹן","אוֹנָאַת דְּבָרִים","שְׁתֵּיהֶן שָׁווֹת"],1,"אוֹנָאַת דְּבָרִים לֹא תָּמִיד אֶפְשָׁר לְתַקֵּן, וְאִלּוּ כֶּסֶף אֶפְשָׁר לְהַחְזִיר.","פֶּרֶק קי״ב, הֲלָכָה ז׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["גֵּר צֶדֶק חָדָשׁ הִגִּיעַ לְבֵית הַכְּנֶסֶת. מַה נַּעֲשֶׂה?",["נְקָרֵב וְנֶאֱהַב אוֹתוֹ","נַזְכִּיר לוֹ אֶת עֲבָרוֹ","נִתְעַלֵּם מִמֶּנּוּ"],0,"הַתּוֹרָה צִוְּתָה ״וְגֵר לֹא תוֹנֶה״ וְגַם ״וַאֲהַבְתֶּם אֶת הַגֵּר״.","פֶּרֶק קי״ב, הֲלָכוֹת ח׳-ט׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["תַּלְמִיד טָעָה בַּתְּשׁוּבָה מוּל כָּל הַכִּתָּה. מָה רָאוּי לַעֲשׂוֹת?",["לִצְחֹק עָלָיו בְּקוֹל","לְהַצְבִּיעַ עָלָיו לִפְנֵי כֻּלָּם","לִשְׁמֹר עַל כְּבוֹדוֹ וְלֹא לְבַיְּשׁוֹ"],2,"אָסוּר לְהַלְבִּין פְּנֵי חָבֵר בָּרַבִּים, וְאָסוּר לְבַיֵּשׁ וּלְהַעֲלִיב אֲחֵרִים.","פֶּרֶק קי״ב, הֲלָכָה י׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["אֵיךְ נִקְרָא לְחָבֵר וּנְדַבֵּר אִתּוֹ?",["בְּכִנּוּי שֶׁהוּא מִתְבַּיֵּשׁ בּוֹ","בִּשְׁמוֹ וּבְלָשׁוֹן נְקִיָּה","בִּקְלָלוֹת וּמִלִּים גַּסּוֹת"],1,"אָסוּר לְכַנּוֹת חָבֵר בְּכִנּוּי שֶׁהוּא מִתְבַּיֵּשׁ בּוֹ, וְאָסוּר לְקַלֵּל וּלְנַבֵּל אֶת הַפֶּה.","פֶּרֶק קי״ב, הֲלָכוֹת י״א-י״ב","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["רָאִיתָ שֶׂה שֶׁל חָבֵר שֶׁבָּרַח. מָה אוֹמֶרֶת הַתּוֹרָה לַעֲשׂוֹת?",["לְהַחְזִיר אוֹתוֹ לִבְעָלָיו","לְהִתְעַלֵּם וּלְהַמְשִׁיךְ לָלֶכֶת","לְגָרֵשׁ אוֹתוֹ רָחוֹק"],0,"״הָשֵׁב תְּשִׁיבֵם לְאָחִיךָ״ – מִצְוָה לְהַחְזִיר אֲבֵדָה לִבְעָלֶיהָ, וְאָסוּר לְהִתְעַלֵּם מִמֶּנָּה.","פֶּרֶק קי״ג, הֲלָכָה א׳","הֲשָׁבַת אֲבֵדָה"],["לָמָּה מִצְוַת הֲשָׁבַת אֲבֵדָה מוֹעִילָה לְכֻלָּם?",["כִּי רַק אֲנָשִׁים מְעַטִּים שׁוֹכְחִים","כִּי הָאֲבֵדוֹת נִשְׁמָרוֹת בְּכָל מָקוֹם","כִּי הַמּוֹצֵא מְקַבֵּל פְּרָס"],1,"אֲנָשִׁים רַבִּים שׁוֹכְחִים דְּבָרִים, וּבִזְכוּת הַמִּצְוָה הָאֲבֵדוֹת נִשְׁמָרוֹת כְּאִלּוּ הֵן תַּחַת יַד הַבְּעָלִים.","פֶּרֶק קי״ג, הֲלָכָה ב׳","הֲשָׁבַת אֲבֵדָה"],["מָצָאתָ אַרְנָק וּבוֹ תְּעוּדַת זֶהוּת. מָה עוֹשִׂים?",["מַשְׁאִירִים בָּרְחוֹב","לוֹקְחִים לְעַצְמֵנוּ","יוֹצְרִים קֶשֶׁר עִם הַבְּעָלִים וּמְשִׁיבִים"],2,"הַמּוֹצֵא חֵפֶץ עִם פְּרָטִים מְזַהִים יִצֹּר קֶשֶׁר בְּהֶקְדֵּם עִם הַבְּעָלִים וְיָשִׁיב לוֹ.","פֶּרֶק קי״ג, הֲלָכָה ג׳","הֲשָׁבַת אֲבֵדָה"],["מְעִיל תָּלוּי בַּקַּיִץ עַל הַמִּתְלִים בְּבֵית הַכְּנֶסֶת. מָה הוּא כַּנִּרְאֶה?",["אֲבֵדָה","מְעִיל שֶׁהֻנַּח בְּכַוָּנָה לְיוֹם אֶחָד","מְעִיל שֶׁל בֵּית הַכְּנֶסֶת"],0,"מְעִיל בַּקַּיִץ – נִכָּר מִנְּסִבּוֹת הָעִנְיָן שֶׁהוּא אֲבֵדָה, וּפוֹעֲלִים לְפִי כְּלָלֵי הֲשָׁבַת אֲבֵדָה.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["אֵיךְ מְפַרְסְמִים מוֹדָעָה עַל אֲבֵדָה שֶׁמָּצָאנוּ?",["עִם כָּל הַסִּימָנִים שֶׁלָּהּ","בְּאֹפֶן כְּלָלִי, בְּלִי סִימָנִים","לֹא מְפַרְסְמִים בִּכְלָל"],1,"מְפַרְסְמִים בְּאֹפֶן כְּלָלִי וְלֹא מְפָרְטִים סִימָנִים – כָּךְ אֶפְשָׁר לְהַבְדִּיל בֵּין הַבְּעָלִים הָאֲמִתִּיִּים לַאֲחֵרִים.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["מָצָאתָ קַלְמָר בְּבֵית הַסֵּפֶר. לְאָן הֲכִי כְּדַאי לִמְסֹר אוֹתוֹ?",["לַפַּח","לַמַּזְכִּירוּת","הַבַּיְתָה"],1,"בְּמָקוֹם צִבּוּרִי מוֹסְרִים לַמַּזְכִּירוּת, כִּי שָׁם הַמְּאַבֵּד יְחַפֵּשׂ אֶת אֲבֵדָתוֹ.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["כִּסֵּא יָשָׁן מֻנָּח לְיַד פַּחֵי אַשְׁפָּה. מָה הַדִּין?",["אָסוּר לָגַעַת בּוֹ","חוֹבָה לְהוֹדִיעַ לַמִּשְׁטָרָה","מֻתָּר לָקַחַת אוֹתוֹ לְעַצְמוֹ"],2,"בְּמָקוֹם שֶׁאֲנָשִׁים מַשְׁלִיכִים אֵלָיו חֲפָצִים שֶׁאֵינָם צְרִיכִים – מֻתָּר לָקַחַת לְעַצְמוֹ.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["בְּרֹב הַמִּקְרִים, אַחֲרֵי כַּמָּה זְמַן זוֹכֶה הַמּוֹצֵא בָּאֲבֵדָה אִם הַבְּעָלִים לֹא נִמְצָא?",["שְׁלוֹשָׁה יָמִים","שְׁלוֹשָׁה חֳדָשִׁים","שָׁלוֹשׁ שָׁנִים"],1,"אִם הַבְּעָלִים לֹא נִמְצָא בַּזְּמַן שֶׁבַּחֹק (בְּרֹב הַמִּקְרִים שְׁלוֹשָׁה חֳדָשִׁים) – הַמּוֹצֵא זוֹכֶה בְּהֶתֵּר.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["מֵאַיִן אָנוּ יוֹדְעִים שֶׁאָסוּר לִגְנֹב וְלִגְזֹל?",["מֵהַתּוֹרָה – ״לֹא תִּגְנֹבוּ״ וְ״לֹא תִגְזֹל״","רַק מֵחֻקֵּי הַמְּדִינָה","זֶה רַק מִנְהָג טוֹב"],0,"כָּתוּב בַּתּוֹרָה ״לֹא תִּגְנֹבוּ״ וְ״וְלֹא תִגְזֹל״, וּמֵהֶם לוֹמְדִים אֶת הָאִסּוּר.","פֶּרֶק קי״ד, הֲלָכָה א׳","גְּנֵבָה וּגְזֵלָה"],["מִי שֶׁלּוֹקֵחַ חֵפֶץ שֶׁל אַחֵר בַּסֵּתֶר, כְּשֶׁאַף אֶחָד לֹא רוֹאֶה – אֵיךְ קוֹרְאִים לוֹ?",["גַּזְלָן","גַּנָּב","שׁוֹמֵר"],1,"גַּנָּב לוֹקֵחַ בַּסֵּתֶר, וְגַזְלָן לוֹקֵחַ בְּגָלוּי.","פֶּרֶק קי״ד, הֲלָכָה ב׳","גְּנֵבָה וּגְזֵלָה"],["הַאִם מֻתָּר לָקַחַת מֵחָבֵר מַחַק קָטָן וְזוֹל בְּלִי רְשׁוּת?",["מֻתָּר, זֶה דָּבָר קָטָן","אָסוּר, אֲפִלּוּ שְׁוֵה פְּרוּטָה","מֻתָּר אִם הוּא חָבֵר טוֹב"],1,"אָסוּר לִגְנֹב אֲפִלּוּ כָּלְשֶׁהוּ, וְהַגּוֹנֵב אֲפִלּוּ שְׁוֵה פְּרוּטָה חַיָּב לְשַׁלֵּם.","פֶּרֶק קי״ד, הֲלָכָה ג׳","גְּנֵבָה וּגְזֵלָה"],["דָּנִי הֶחְבִּיא אֶת הַכּוֹבַע שֶׁל חֲבֵרוֹ ״רַק בִּצְחוֹק״. מָה הַדִּין?",["מֻתָּר, זֶה רַק צְחוֹק","מֻתָּר אִם מַחְזִירִים מָחָר","אָסוּר, אֲפִלּוּ בִּצְחוֹק"],2,"אָסוּר לִגְנֹב אֲפִלּוּ דֶּרֶךְ צְחוֹק, וַאֲפִלּוּ עַל מְנָת לְהַחְזִיר אַחַר כָּךְ.","פֶּרֶק קי״ד, הֲלָכָה ד׳","גְּנֵבָה וּגְזֵלָה"],["מָתַי מֻתָּר לְהִשְׁתַּמֵּשׁ בָּאוֹפַנַּיִם שֶׁל הַשָּׁכֵן בְּלִי לִשְׁאֹל?",["רַק אִם יוֹדְעִים בְּוַדָּאוּת שֶׁהוּא הָיָה מַרְשֶׁה","תָּמִיד, אִם מַחְזִירִים מַהֵר","אַף פַּעַם, גַּם אִם הוּא בְּוַדַּאי הָיָה מַרְשֶׁה"],0,"אָסוּר לְהִשְׁתַּמֵּשׁ בְּחֵפֶץ שֶׁל אַחֵר בְּלִי רְשׁוּת, אֲבָל אִם יוֹדְעִים בְּוַדָּאוּת שֶׁהָיָה מַרְשֶׁה – מֻתָּר.","פֶּרֶק קי״ד, הֲלָכָה ה׳","גְּנֵבָה וּגְזֵלָה"],["מִישֶׁהוּ מַצִּיעַ לִמְכֹּר לְךָ חֵפֶץ שֶׁהוּא גָּנַב. מָה עוֹשִׂים?",["קוֹנִים, כִּי לֹא אֲנַחְנוּ גָּנַבְנוּ","לֹא קוֹנִים – זֶה עָווֹן גָּדוֹל","קוֹנִים רַק בְּמְחִיר מָלֵא"],1,"אָסוּר לִקְנוֹת מִגַּנָּב, כִּי מְחַזְּקִים אֶת יָדָיו וְגוֹרְמִים לוֹ לִגְנֹב עוֹד.","פֶּרֶק קי״ד, הֲלָכָה ו׳","גְּנֵבָה וּגְזֵלָה"],["בַּשּׁוּק מוֹכְרִים טֶלֶפוֹן חָדָשׁ בִּמְחִיר זוֹל מְאֹד מְאֹד, עַד שֶׁנִּרְאֶה שֶׁהוּא גָּנוּב. מָה הַדִּין?",["מְצִיאָה! קוֹנִים מִיָּד","מֻתָּר אִם הַמּוֹכֵר נֶחְמָד","אָסוּר לִקְנוֹת – יֵשׁ חֲשָׁד שֶׁהוּא גָּנוּב"],2,"כְּשֶׁסְּחוֹרָה זוֹלָה כָּל כָּךְ עַד שֶׁעוֹלֶה חֲשָׁד שֶׁהִיא גְּנוּבָה – אָסוּר לִקְנוֹתָהּ.","פֶּרֶק קי״ד, הֲלָכָה ז׳","גְּנֵבָה וּגְזֵלָה"],["מָה הַדִּין לְגַבֵּי הַעְתָּקַת שִׁירִים, סְרָטִים, סְפָרִים וְתָכְנוֹת?",["יֵשׁ לַיּוֹצְרִים זְכֻיּוֹת – נוֹהֲגִים לְפִי הַחֹק","הַכֹּל מֻתָּר לְהַעְתִּיק","מֻתָּר רַק בַּמַּחְשֵׁב"],0,"לַיּוֹצְרִים יֵשׁ זְכֻיּוֹת עַל יְצִירוֹתֵיהֶם, וְלָכֵן מַקְפִּידִים לְהִתְנַהֵג עַל פִּי הַחֹק.","פֶּרֶק קי״ד, הֲלָכָה ח׳","גְּנֵבָה וּגְזֵלָה"],["אֵיזֶה מִשְׁקָל צָרִיךְ לִהְיוֹת בַּמַּכֹּלֶת?",["מִשְׁקָל שֶׁמַּרְאֶה קְצָת יוֹתֵר","מִשְׁקָל מְדֻיָּק","מִשְׁקָל שֶׁמַּרְאֶה קְצָת פָּחוֹת"],1,"הַתּוֹרָה צִוְּתָה: ״מֹאזְנֵי צֶדֶק״. הַשּׁוֹקֵל בְּמִשְׁקָל לֹא מְדֻיָּק עוֹבֵר בְּלֹא תַּעֲשֶׂה.","פֶּרֶק קי״ד, הֲלָכָה ט׳","גְּנֵבָה וּגְזֵלָה"],["אֵיזֶה פָּסוּק בַּתּוֹרָה מַזְהִיר אוֹתָנוּ מֵרְכִילוּת?",["לֹא תֹאכַל חָמֵץ","לֹא תֵלֵךְ רָכִיל בְּעַמֶּיךָ","שֵׁשֶׁת יָמִים תַּעֲבֹד"],1,"הַתּוֹרָה אוֹמֶרֶת: ״לֹא תֵלֵךְ רָכִיל בְּעַמֶּיךָ״ (וַיִּקְרָא י״ט, ט״ז). יֵשׁ עוֹד פְּסוּקִים רַבִּים שֶׁמַּזְהִירִים מִלָּשׁוֹן הָרַע וּרְכִילוּת.","פֶּרֶק קט״ו, הֲלָכָה א׳","אִסּוּר לָשׁוֹן הָרַע"],["לְפִי הַמִּדְרָשׁ, בְּמָה הַכֹּל תָּלוּי?",["בַּיָּדַיִם","בָּרַגְלַיִם","בַּלָּשׁוֹן"],2,"״מָוֶת וְחַיִּים בְּיַד לָשׁוֹן״ – הַכֹּל תָּלוּי בַּלָּשׁוֹן. מִי שֶׁעוֹסֵק בַּתּוֹרָה בִּלְשׁוֹנוֹ זוֹכֶה לְחַיִּים, וְלָשׁוֹן הָרַע קָשָׁה כִּשְׁפִיכַת דָּמִים.","פֶּרֶק קט״ו, הֲלָכָה ב׳","אִסּוּר לָשׁוֹן הָרַע"],["לְמִי נָתַן ה׳ אֶת מַתְּנַת הַדִּבּוּר?",["לַבְּהֵמוֹת וְלַחַיּוֹת","רַק לִבְנֵי הָאָדָם","לַצִּפּוֹרִים בַּשָּׁמַיִם"],1,"הַדִּבּוּר הוּא מַתָּנָה מְיֻחֶדֶת שֶׁה׳ נָתַן רַק לִבְנֵי הָאָדָם, וְעָלֵינוּ לְהִשְׁתַּמֵּשׁ בָּהּ בְּצוּרָה חִיּוּבִית.","פֶּרֶק קט״ו, הֲלָכָה ג׳","אִסּוּר לָשׁוֹן הָרַע"],["מַהוּ ״רָכִיל״?",["מוֹכֵר פֵּרוֹת בַּשּׁוּק","מְחַלֵּק עִתּוֹנִים בַּבֹּקֶר","מִי שֶׁמְּסַפֵּר לְאָדָם מָה אָמְרוּ עָלָיו"],2,"רָכִיל הוֹלֵךְ כְּרוֹכֵל מֵאָדָם לְאָדָם וְאוֹמֵר: ״כָּךְ אָמַר עָלֶיךָ פְּלוֹנִי״. גַּם אִם זֶה אֱמֶת, זֶה עָלוּל לִגְרֹם לְסִכְסוּכִים, שִׂנְאָה וְכַעַס.","פֶּרֶק קט״ו, הֲלָכָה ד׳","אִסּוּר לָשׁוֹן הָרַע"],["דָּנִי סִפֵּר עַל חָבֵר דָּבָר רַע שֶׁאֵינוֹ נָכוֹן. אֵיךְ קוֹרְאִים לָזֶה?",["הוֹצָאַת שֵׁם רַע","דִּבְרֵי שֶׁבַח","דְּבַר תּוֹרָה"],0,"הוֹצָאַת שֵׁם רַע הִיא אֲמִירַת דְּבָרִים רָעִים שֶׁאֵינָם נְכוֹנִים עַל הֶחָבֵר. וְלָשׁוֹן הָרַע אָסוּר גַּם כְּשֶׁהַדְּבָרִים אֱמֶת!","פֶּרֶק קט״ו, הֲלָכוֹת ה׳-ו׳","אִסּוּר לָשׁוֹן הָרַע"],["מָה עוֹשִׂים כְּשֶׁמְּדַבְּרִים לְיָדְךָ לָשׁוֹן הָרַע?",["מַקְשִׁיבִים בְּשֶׁקֶט","עוֹזְבִים אוֹ מְבַקְּשִׁים לְהַפְסִיק","מוֹסִיפִים עוֹד סִפּוּר"],1,"אָסוּר גַּם לִשְׁמֹעַ לָשׁוֹן הָרַע, וְכָל שֶׁכֵּן לְהַאֲמִין לוֹ. צָרִיךְ לַעֲזֹב אוֹ לְבַקֵּשׁ לְהַפְסִיק, וְאִם אִי אֶפְשָׁר – לְנַסּוֹת לְשַׁנּוֹת אֶת הַנּוֹשֵׂא.","פֶּרֶק קט״ו, הֲלָכוֹת ז׳-ח׳","אִסּוּר לָשׁוֹן הָרַע"],["בְּאֵיזוֹ דֶּרֶךְ אָסוּר לְסַפֵּר לָשׁוֹן הָרַע, גַּם בְּלִי לְדַבֵּר בַּפֶּה?",["בְּצִיּוּר שֶׁל פֶּרַח","בְּשִׁיר לִכְבוֹד שַׁבָּת","בְּהוֹדָעָה כְּתוּבָה בַּטֵּלֵפוֹן"],2,"אִסּוּר לָשׁוֹן הָרַע קַיָּם גַּם בִּכְתִיבָה. בָּרְשָׁתוֹת הַחֶבְרָתִיּוֹת זֶה עָלוּל לִהְיוֹת חָמוּר יוֹתֵר, כִּי הַמֵּידָע עוֹבֵר מַהֵר לְהַרְבֵּה מְאֹד אֲנָשִׁים.","פֶּרֶק קט״ו, הֲלָכָה ט׳","אִסּוּר לָשׁוֹן הָרַע"],["מָה עוֹשִׂים כְּשֶׁיֵּשׁ מִישֶׁהוּ שֶׁמַּרְבֶּה מְאֹד בְּלָשׁוֹן הָרַע?",["מִתְרַחֲקִים מִמֶּנּוּ","יוֹשְׁבִים לְיָדוֹ וְשׁוֹמְעִים","מְבַקְּשִׁים שֶׁיְּסַפֵּר עוֹד"],0,"לַאֲנָשִׁים שֶׁמַּרְבִּים בְּלָשׁוֹן הָרַע וְאֵינָם נִזְהָרִים קָרְאוּ חֲכָמִים ״בַּעֲלֵי לָשׁוֹן הָרַע״. יֵשׁ לְהִתְרַחֵק מֵהֶם, וְכָל שֶׁכֵּן לֹא לָשֶׁבֶת עִמָּם וְלִשְׁמֹעַ.","פֶּרֶק קט״ו, הֲלָכָה י׳","אִסּוּר לָשׁוֹן הָרַע"],["לָמָּה לֹא מְשַׁבְּחִים חָבֵר יוֹתֵר מִדַּי?",["כִּי זֶה מְשַׁעְמֵם","כִּי הַשּׁוֹמְעִים עֲלוּלִים לְהַזְכִּיר אֶת גְּנוּתוֹ","כִּי אָסוּר לְדַבֵּר בִּכְלָל"],1,"זֶה ״אֲבַק לָשׁוֹן הָרַע״: מִתּוֹךְ רִבּוּי שְׁבָחִים, הַשּׁוֹמְעִים עֲלוּלִים לְהַזְכִּיר גַּם אֶת גְּנוּתוֹ, בִּמְיֻחָד אִם יֵשׁ שָׁם שׂוֹנְאִים שֶׁלּוֹ.","פֶּרֶק קט״ו, הֲלָכָה י״א","אִסּוּר לָשׁוֹן הָרַע"],["יוֹסִי יוֹדֵעַ שֶׁיְּלָדִים רוֹצִים לְהָצִיק לַחֲבֵרוֹ. מָה יַעֲשֶׂה קֹדֶם?",["יַצְטָרֵף אֲלֵיהֶם","יִשְׁתֹּק וְלֹא יַעֲשֶׂה דָּבָר","יְנַסֶּה לְשַׁכְנֵעַ אוֹתָם לְהַפְסִיק"],2,"מֻתָּר לְהַזְהִיר מִמִּי שֶׁרוֹצֶה לְהָצִיק, אֲבָל קֹדֶם מְנַסִּים לְשַׁכְנֵעַ אֶת הַמְּצִיקִים לְהַפְסִיק. רַק אִם לֹא הִצְלִיחַ – מַזְהִיר אֶת הֶחָבֵר.","פֶּרֶק קט״ו, הֲלָכוֹת י״ב-י״ג","אִסּוּר לָשׁוֹן הָרַע"],["אֵיזוֹ בְּרָכָה מְבָרְכִים לִפְנֵי אֲכִילַת לֶחֶם?",["בּוֹרֵא מִינֵי מְזוֹנוֹת","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ","שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ"],1,"בְּנֵי אָדָם רְגִילִים לִקְבֹּעַ סְעוּדָה עַל לֶחֶם, וְלָכֵן תִּקְּנוּ חֲכָמִים בְּרָכָה מְיֻחֶדֶת: ״הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ״.","פֶּרֶק כ״ה, הֲלָכָה ג׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["מָה מְבָרְכִים לִפְנֵי אֲכִילַת עוּגִיָּה עִם מִלּוּי?",["הַמּוֹצִיא","בּוֹרֵא פְּרִי הָאֲדָמָה","בּוֹרֵא מִינֵי מְזוֹנוֹת"],2,"מַאֲפֶה מִדָּגָן שֶׁמְּמֻלָּא בִּדְבַשׁ, סֻכָּר, אֱגוֹזִים וְכַדּוֹמֶה הוּא ״פַּת הַבָּאָה בְּכִסְנִין״, וּמְבָרְכִים עָלָיו ״בּוֹרֵא מִינֵי מְזוֹנוֹת״.","פֶּרֶק כ״ה, הֲלָכָה ז׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["מָה מְבָרְכִים לִפְנֵי שֶׁאוֹכְלִים פִּיצָה בִּסְעוּדָה?",["הַמּוֹצִיא","בּוֹרֵא מִינֵי מְזוֹנוֹת","שֶׁהַכֹּל"],0,"פִּיצָה הִיא מַאֲכָל שֶׁרְגִילִים לֶאֱכֹל בִּסְעוּדָה כְּדֵי לִשְׂבֹּעַ, וְלָכֵן מְבָרְכִים לְפָנֶיהָ ״הַמּוֹצִיא״ וְאַחֲרֶיהָ ״בִּרְכַּת הַמָּזוֹן״.","פֶּרֶק כ״ה, הֲלָכָה ט׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["מָה מְבָרְכִים לִפְנֵי צַלַּחַת גְּדוֹלָה שֶׁל פַּסְטָה?",["הַמּוֹצִיא","בּוֹרֵא מִינֵי מְזוֹנוֹת","בּוֹרֵא פְּרִי הָאֲדָמָה"],1,"עַל חֲמֵשֶׁת מִינֵי דָּגָן מְבֻשָּׁלִים, כְּמוֹ פַּסְטָה וְאִטְרִיּוֹת, מְבָרְכִים ״בּוֹרֵא מִינֵי מְזוֹנוֹת״, אֲפִלּוּ כְּשֶׁאוֹכְלִים הַרְבֵּה.","פֶּרֶק כ״ה, הֲלָכָה י׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["מָה מְבָרְכִים עַל גַּרְגְּרֵי חִטָּה שְׁלֵמִים וּקְלוּיִים?",["בּוֹרֵא פְּרִי הָאֲדָמָה","הַמּוֹצִיא","בּוֹרֵא מִינֵי מְזוֹנוֹת"],0,"עַל גַּרְגְּרִים שְׁלֵמִים שֶׁל חִטָּה, שִׁבֹּלֶת שׁוּעָל, כֻּסְּמִין אוֹ שִׁיפוֹן, שְׁלוּקִים אוֹ קְלוּיִים, מְבָרְכִים ״בּוֹרֵא פְּרִי הָאֲדָמָה״ וּ״בוֹרֵא נְפָשׁוֹת רַבּוֹת״.","פֶּרֶק כ״ה, הֲלָכָה י״א","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["מָה מְבָרְכִים עַל שְׂעוֹרִים חַיּוֹת אוֹ קְלוּיוֹת?",["בּוֹרֵא מִינֵי מְזוֹנוֹת","בּוֹרֵא פְּרִי הָאֲדָמָה","שֶׁהַכֹּל"],2,"עַל שְׂעוֹרִים חַיּוֹת אוֹ קְלוּיוֹת מְבָרְכִים ״שֶׁהַכֹּל״ וּ״בוֹרֵא נְפָשׁוֹת״.","פֶּרֶק כ״ה, הֲלָכָה י״ב","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["מָה מְבָרְכִים עַל קְעָרַת קְוָוקֶר מְבֻשָּׁל?",["בּוֹרֵא פְּרִי הָאֲדָמָה","בּוֹרֵא מִינֵי מְזוֹנוֹת","הַמּוֹצִיא"],1,"עַל גַּרְגְּרִים מְבֻשָּׁלִים, כְּמוֹ גְּרִיסִים, קְוָוקֶר וּבֻרְגּוּל, מְבָרְכִים ״בּוֹרֵא מִינֵי מְזוֹנוֹת״ וּ״עַל הַמִּחְיָה״.","פֶּרֶק כ״ה, הֲלָכָה י״ג","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["עַל אֵיזֶה מַאֲכָל מְבָרְכִים אַחֲרָיו ״מֵעֵין שָׁלוֹשׁ״?",["תַּפּוּחַ","עוּגָה","מְלָפְפוֹן"],1,"עַל עוּגָה מְבָרְכִים לְפָנֶיהָ ״בּוֹרֵא מִינֵי מְזוֹנוֹת״, וְאַחֲרֶיהָ ״מֵעֵין שָׁלוֹשׁ״.","פֶּרֶק כ״ו, הֲלָכָה א׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["אֵיזֶה מַאֲכָל מְבָרְכִים לְפָנָיו ״מְזוֹנוֹת״, אֲבָל אַחֲרָיו לֹא מְבָרְכִים ״מֵעֵין שָׁלוֹשׁ״?",["פַּסְטָה","עוּגִיּוֹת","אֹרֶז"],2,"אֹרֶז יוֹצֵא מִן הַכְּלָל: אַף שֶׁמְּבָרְכִים עָלָיו ״בּוֹרֵא מִינֵי מְזוֹנוֹת״, לֹא מְבָרְכִים אַחֲרָיו ״מֵעֵין שָׁלוֹשׁ״.","פֶּרֶק כ״ו, הֲלָכָה א׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["אֵיזֶה פְּרִי הוּא מִשִּׁבְעַת הַמִּינִים?",["רִמּוֹן","תַּפּוּז","אֲגַס"],0,"רִמּוֹן הוּא מִשִּׁבְעַת הַמִּינִים שֶׁכְּתוּבִים בַּתּוֹרָה, וּמְבָרְכִים אַחֲרָיו ״מֵעֵין שָׁלוֹשׁ״.","פֶּרֶק כ״ו, הֲלָכָה ב׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["עַל מָה מְבָרְכִים ״בּוֹרֵא פְּרִי הַגֶּפֶן״?",["מַיִם","יַיִן","חָלָב"],1,"לִפְנֵי שֶׁשּׁוֹתִים יַיִן מְבָרְכִים ״בּוֹרֵא פְּרִי הַגֶּפֶן״, וְאַחֲרָיו ״מֵעֵין שָׁלוֹשׁ״.","פֶּרֶק כ״ו, הֲלָכָה ד׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["עַל אֵיזֶה פְּרִי מְבָרְכִים ״בּוֹרֵא פְּרִי הָעֵץ״ וְאַחֲרָיו ״בּוֹרֵא נְפָשׁוֹת״?",["תַּפּוּחַ","תְּאֵנָה","עַגְבָנִיָּה"],0,"תַּפּוּחַ גָּדֵל עַל עֵץ שֶׁהַגֶּזַע וְהָעֲנָפִים שֶׁלּוֹ מִתְקַיְּמִים מִשָּׁנָה לְשָׁנָה. תְּאֵנָה הִיא מִשִּׁבְעַת הַמִּינִים, וְאַחֲרֶיהָ מְבָרְכִים ״מֵעֵין שָׁלוֹשׁ״.","פֶּרֶק כ״ו, הֲלָכָה ו׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["עַל אֵיזֶה פְּרִי מְבָרְכִים ״בּוֹרֵא פְּרִי הָאֲדָמָה״?",["תָּמָר","בָּנָנָה","זַיִת"],1,"הַגֶּזַע שֶׁל הַבָּנָנָה מִתְיַבֵּשׁ אַחֲרֵי הַקְּטִיף, וְגֶזַע אַחֵר יוֹצֵא מֵהַשָּׁרָשִׁים, וְלָכֵן הִיא פְּרִי הָאֲדָמָה.","פֶּרֶק כ״ו, הֲלָכָה ז׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["מָה מְבָרְכִים לְמַעֲשֶׂה עַל פַּפָּאיָה?",["בּוֹרֵא פְּרִי הָעֵץ","שֶׁהַכֹּל","בּוֹרֵא פְּרִי הָאֲדָמָה"],2,"פַּפָּאיָה מוֹצִיאָה פֵּרוֹת כְּבָר בַּשָּׁנָה הָרִאשׁוֹנָה, וְלָכֵן מְבָרְכִים עָלֶיהָ ״בּוֹרֵא פְּרִי הָאֲדָמָה״.","פֶּרֶק כ״ו, הֲלָכָה ח׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["אָכַלְתָּ תְּמָרִים שֶׁגָּדְלוּ בְּאֶרֶץ יִשְׂרָאֵל. אֵיךְ חוֹתְמִים אֶת ״מֵעֵין שָׁלוֹשׁ״?",["עַל הָאָרֶץ וְעַל פֵּרוֹתֶיהָ","עַל הָאָרֶץ וְעַל הַמָּזוֹן","עַל הָאָרֶץ וְעַל הַפֵּרוֹת"],0,"עַל פֵּרוֹת שִׁבְעַת הַמִּינִים שֶׁגָּדְלוּ בְּאֶרֶץ יִשְׂרָאֵל חוֹתְמִים ״עַל הָאָרֶץ וְעַל פֵּרוֹתֶיהָ״.","פֶּרֶק כ״ו, הֲלָכָה ג׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["עַל אֵיזֶה מַאֲכָל מְבָרְכִים ״שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ״?",["תַּפּוּחַ","דָּג","מְלָפְפוֹן"],1,"דָּג אֵינוֹ גָּדֵל מִן הָאָרֶץ, וְלָכֵן מְבָרְכִים עָלָיו ״שֶׁהַכֹּל״, כְּמוֹ עַל בָּשָׂר, גְּבִינָה, בֵּיצִים וּפִטְרִיּוֹת.","פֶּרֶק כ״ו, הֲלָכָה ט׳","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["עַל אֵיזֶה מַאֲכָל מְבָרְכִים ״בּוֹרֵא מִינֵי מְזוֹנוֹת״?",["אֹרֶז מְבֻשָּׁל","גְּבִינָה","בֵּיצָה"],0,"עַל אֹרֶז מְבֻשָּׁל מְבָרְכִים ״בּוֹרֵא מִינֵי מְזוֹנוֹת״ וְאַחֲרָיו ״בּוֹרֵא נְפָשׁוֹת״.","פֶּרֶק כ״ו, הֲלָכָה י׳","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["מִי מְבָרֵךְ בְּרָכָה אַחֲרוֹנָה?",["יֶלֶד שֶׁטָּעַם פֵּרוּר קָטָן","יֶלֶד שֶׁלִּקֵּק טִפָּה אַחַת","יֶלֶד שֶׁאָכַל כַּזַּיִת בְּתוֹךְ אַרְבַּע דַּקּוֹת"],2,"מְבָרְכִים בְּרָכָה אַחֲרוֹנָה רַק אַחֲרֵי אֲכִילַת כַּזַּיִת וּמַעְלָה בְּתוֹךְ אַרְבַּע דַּקּוֹת. מִי שֶׁאָכַל פָּחוֹת – אֵינוֹ מְבָרֵךְ.","פֶּרֶק כ״ו, הֲלָכָה י״ג","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["בְּאֵיזֶה מַצָּב מְבָרְכִים עַל שְׁתִיַּת מַיִם?",["בּוֹלֵעַ גְּלוּלָה עִם מַיִם","צָמֵא וְשׁוֹתֶה מַיִם","מְנַקֶּה אֶת הַפֶּה בְּמַיִם"],1,"עַל מַיִם מְבָרְכִים רַק כְּשֶׁשּׁוֹתִים כְּדֵי לְהַרְווֹת אֶת הַצִּמָּאוֹן. לִבְלִיעַת גְּלוּלָה אוֹ לְנִקּוּי הַפֶּה – אֵין מְבָרְכִים.","פֶּרֶק כ״ו, הֲלָכָה ט״ו","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["מָה מְבָרְכִים לִפְנֵי שְׁתִיַּת מִיץ תַּפּוּזִים?",["בּוֹרֵא פְּרִי הָעֵץ","בּוֹרֵא מִינֵי מְזוֹנוֹת","שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ"],2,"לִפְנֵי שְׁתִיַּת מַשְׁקֶה שֶׁאֵינוֹ יַיִן מְבָרְכִים ״שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ״, וְאַחֲרֶיהָ ״בּוֹרֵא נְפָשׁוֹת רַבּוֹת״.","פֶּרֶק כ״ו, הֲלָכָה י״ד","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["עַל אֵיזֶה מַשְׁקֶה בְּדֶרֶךְ כְּלָל אֵין מְבָרְכִים בְּרָכָה אַחֲרוֹנָה?",["תֵּה חַם","מִיץ קַר","מַיִם קָרִים"],0,"עַל מַשְׁקָאוֹת חַמִּים כְּמוֹ תֵּה, קָפֶה וְשׁוֹקוֹ חַם אֵין מְבָרְכִים בְּרָכָה אַחֲרוֹנָה, כִּי אֵין רְגִילִים לִשְׁתּוֹת מֵהֶם רְבִיעִית בִּזְמַן קָצָר.","פֶּרֶק כ״ו, הֲלָכָה י״ז","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["יוֹסִי רוֹצֶה לֶאֱכֹל רַק חֲתִיכָה קְטַנָּה שֶׁל גְּבִינָה. מָה עָלָיו לַעֲשׂוֹת?",["לֹא לְבָרֵךְ, כִּי זֶה מְעַט","לְבָרֵךְ בְּרָכָה רִאשׁוֹנָה","לְבָרֵךְ רַק בְּרָכָה אַחֲרוֹנָה"],1,"יֵשׁ לְבָרֵךְ בְּרָכָה רִאשׁוֹנָה אֲפִלּוּ אִם מִתְכַּוְּנִים לֶאֱכֹל מְעַט.","פֶּרֶק כ״ו, הֲלָכָה י״ב","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["אָבִי רוֹצֶה לִשְׁתּוֹת רַק לְגִימָה קְטַנָּה שֶׁל מִיץ. מָה עָלָיו לַעֲשׂוֹת?",["לְבָרֵךְ רַק אַחֲרֵי הַשְּׁתִיָּה","לֹא לְבָרֵךְ כְּלָל","לְבָרֵךְ ״שֶׁהַכֹּל״ לִפְנֵי הַשְּׁתִיָּה"],2,"יֵשׁ לְבָרֵךְ בְּרָכָה רִאשׁוֹנָה עַל מַשְׁקֶה אֲפִלּוּ אִם מִתְכַּוְּנִים לִשְׁתּוֹת מְעַט.","פֶּרֶק כ״ו, הֲלָכָה ט״ז","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["לְפָנַי עוּגָה, תַּפּוּחַ וְכוֹס מַיִם. אֵיזוֹ בְּרָכָה קוֹדֶמֶת לְכֻלָּן?",["בּוֹרֵא פְּרִי הָעֵץ","בּוֹרֵא מִינֵי מְזוֹנוֹת","שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ"],1,"בְּסֵדֶר הַבְּרָכוֹת, בְּרָכַת ״בּוֹרֵא מִינֵי מְזוֹנוֹת״ הִיא הָרִאשׁוֹנָה, וּבְרָכַת ״שֶׁהַכֹּל״ הִיא הָאַחֲרוֹנָה.","פֶּרֶק כ״ז, הֲלָכָה א׳","דִּין קְדִימָה בִּבְרָכוֹת"],["אֵיזֶה פְּרִי הוּא מִשִּׁבְעַת הַמִּינִים שֶׁהַתּוֹרָה שִׁבְּחָה בָּהֶם אֶת אֶרֶץ יִשְׂרָאֵל?",["אֲגַס","תַּפּוּחַ","רִמּוֹן"],2,"בַּפָּסוּק כָּתוּב: ״אֶרֶץ חִטָּה וּשְׂעֹרָה וְגֶפֶן וּתְאֵנָה וְרִמּוֹן, אֶרֶץ זֵית שֶׁמֶן וּדְבָשׁ״. הָרִמּוֹן הוּא מִשִּׁבְעַת הַמִּינִים.","פֶּרֶק כ״ז, הֲלָכָה ב׳","דִּין קְדִימָה בִּבְרָכוֹת"],["יֵשׁ לְפָנַי תַּפּוּחִים וַעֲנָבִים, וַאֲנִי אוֹהֵב יוֹתֵר תַּפּוּחִים. עַל מָה אֲבָרֵךְ?",["עַל הָעֲנָבִים","עַל הַתַּפּוּחִים","עַל שְׁנֵיהֶם בְּנִפְרָד"],0,"מְבָרְכִים עַל הָעֲנָבִים, שֶׁהֵם מִשִּׁבְעַת הַמִּינִים, וּפוֹטְרִים אֶת הַתַּפּוּחִים, אֲפִלּוּ אִם הַתַּפּוּחִים חֲבִיבִים יוֹתֵר.","פֶּרֶק כ״ז, הֲלָכָה ג׳","דִּין קְדִימָה בִּבְרָכוֹת"],["בַּפָּסוּק, לְיַד אֵיזוֹ מִלָּה הַקָּרוֹב אֵלֶיהָ קוֹדֵם לִבְרָכָה?",["טוֹבָה","דְּבַשׁ","אֶרֶץ"],2,"חֲכָמִים דָּרְשׁוּ שֶׁכָּל הַקָּרוֹב לַמִּלָּה ״אֶרֶץ״ בַּפָּסוּק קוֹדֵם לִבְרָכָה.","פֶּרֶק כ״ז, הֲלָכָה ד׳","דִּין קְדִימָה בִּבְרָכוֹת"],["יֵשׁ לְפָנַי זֵיתִים, עֲנָבִים וְרִמּוֹנִים. עַל מָה מְבָרְכִים רִאשׁוֹנָה?",["עֲנָבִים","זֵיתִים","רִמּוֹנִים"],1,"הַזֵּיתִים מוֹפִיעִים מִיָּד אַחֲרֵי הַמִּלָּה ״אֶרֶץ״ הַשְּׁנִיָּה, וְלָכֵן הֵם קוֹדְמִים לָעֲנָבִים וְלָרִמּוֹנִים.","פֶּרֶק כ״ז, הֲלָכָה ה׳","דִּין קְדִימָה בִּבְרָכוֹת"],["יֵשׁ לְפָנַי אֲגַסִּים, תַּפּוּחִים וְשְׁזִיפִים - אַף אֶחָד מֵהֶם אֵינוֹ מִשִּׁבְעַת הַמִּינִים. עַל מָה אֲבָרֵךְ?",["עַל הַפְּרִי הַגָּדוֹל בְּיוֹתֵר","עַל הַפְּרִי הָרִאשׁוֹן בַּצַּלַּחַת","עַל הַפְּרִי הֶחָבִיב עָלַי בְּיוֹתֵר"],2,"כְּשֶׁאוֹכְלִים כַּמָּה פֵּרוֹת שֶׁאֵינָם מִשִּׁבְעַת הַמִּינִים, מְבָרְכִים עַל הַפְּרִי הֶחָבִיב בְּיוֹתֵר.","פֶּרֶק כ״ז, הֲלָכָה ו׳","דִּין קְדִימָה בִּבְרָכוֹת"],["עַל הַשֻּׁלְחָן יַיִן, זֵיתִים וּתְמָרִים. עַל מָה מְבָרְכִים רִאשׁוֹנָה?",["עַל הַיַּיִן","עַל הַזֵּיתִים","עַל הַתְּמָרִים"],0,"הַיַּיִן קוֹדֵם לַזֵּיתִים וְלַתְּמָרִים, כִּי יֵשׁ לוֹ בְּרָכָה מְיֻחֶדֶת וַחֲשׁוּבָה - ״בּוֹרֵא פְּרִי הַגֶּפֶן״.","פֶּרֶק כ״ז, הֲלָכָה ז׳","דִּין קְדִימָה בִּבְרָכוֹת"],["בְּלֵיל שַׁבָּת עוֹשִׂים קִדּוּשׁ עַל הַיַּיִן. מָה מְכַסִּים בִּזְמַן הַקִּדּוּשׁ?",["אֶת הַנֵּרוֹת","אֶת הַחַלּוֹת","אֶת הַכּוֹס"],1,"בַּקִּדּוּשׁ מַקְדִּימִים אֶת בִּרְכַּת הַיַּיִן לְבִרְכַּת ״הַמּוֹצִיא״, וְלָכֵן מְכַסִּים אֶת הַפַּת.","פֶּרֶק כ״ז, הֲלָכָה ט׳","דִּין קְדִימָה בִּבְרָכוֹת"],["מָה רָאוּי לַעֲשׂוֹת רֶגַע לִפְנֵי שֶׁמַּתְחִילִים לְבָרֵךְ?",["לְמַהֵר וּלְבָרֵךְ בְּלִי לַחְשֹׁב","לַחְשֹׁב אֵיזוֹ בְּרָכָה מְבָרְכִים וּמָה כַּוָּנָתָהּ","לְבָרֵךְ תּוֹךְ כְּדֵי מִשְׂחָק"],1,"לִפְנֵי שֶׁמַּתְחִילִים לְבָרֵךְ יֵשׁ לַחְשֹׁב אֵיזוֹ בְּרָכָה עוֹמְדִים לְבָרֵךְ וּמָה כַּוָּנָתָהּ, וּלְבָרֵךְ תּוֹךְ הֲבָנָה שֶׁל כָּל מִלָּה.","פֶּרֶק כ״ח, הֲלָכָה א׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["אֵיזֶה יֶלֶד מְבָרֵךְ כָּרָאוּי, לֹא מִתּוֹךְ הֶסַּח הַדַּעַת?",["הַיֶּלֶד שֶׁמְּבָרֵךְ וּמַבִּיט בַּמָּסָךְ","הַיֶּלֶד שֶׁמְּבָרֵךְ וּמְדַבֵּר עִם חָבֵר","הַיֶּלֶד שֶׁמְּבָרֵךְ בְּרִכּוּז וּבְכַוָּנָה"],2,"אֵין לְבָרֵךְ אֶת הַבְּרָכוֹת כְּמִצְוַת אֲנָשִׁים מְלֻמָּדָה וּמִתּוֹךְ הֶסַּח הַדַּעַת.","פֶּרֶק כ״ח, הֲלָכָה ב׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["שִׁמְעוֹן בֵּרֵךְ בְּטָעוּת עַל תַּפּוּחַ ״בּוֹרֵא פְּרִי הָאֲדָמָה״. מָה דִּינוֹ?",["יָצָא, כִּי גַּם פֵּרוֹת הָעֵץ צוֹמְחִים מִן הָאֲדָמָה","לֹא יָצָא יְדֵי חוֹבָה","יָצָא רַק אִם אָכַל הַרְבֵּה תַּפּוּחִים"],0,"מִי שֶׁטָּעָה וּבֵרֵךְ עַל פֵּרוֹת הָעֵץ ״בּוֹרֵא פְּרִי הָאֲדָמָה״ יָצָא, שֶׁהֲרֵי גַּם פֵּרוֹת הָעֵץ צוֹמְחִים מִן הָאֲדָמָה.","פֶּרֶק כ״ח, הֲלָכָה ג׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["רְאוּבֵן בֵּרֵךְ בְּטָעוּת עַל מְלָפְפוֹן ״בּוֹרֵא פְּרִי הָעֵץ״. מָה דִּינוֹ?",["יָצָא, כִּי כָּל הַפֵּרוֹת שָׁוִים","לֹא יָצָא, כִּי הַמְּלָפְפוֹן לֹא גָּדַל עַל עֵץ","יָצָא, אִם הַמְּלָפְפוֹן טָרִי"],1,"מִי שֶׁטָּעָה וּבֵרֵךְ עַל פֵּרוֹת הָאֲדָמָה ״בּוֹרֵא פְּרִי הָעֵץ״ לֹא יָצָא, שֶׁהֲרֵי הֵם לֹא גָּדְלוּ עַל עֵץ.","פֶּרֶק כ״ח, הֲלָכָה ג׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["יַעֲקֹב בֵּרֵךְ בְּטָעוּת ״שֶׁהַכֹּל״ עַל פְּרוּסַת לֶחֶם. מָה דִּינוֹ?",["לֹא יָצָא, כִּי עַל לֶחֶם אָסוּר שֶׁהַכֹּל","יָצָא רַק אִם הַלֶּחֶם קָטָן","יָצָא, אַף שֶׁלְּכַתְּחִלָּה מְבָרְכִים הַמּוֹצִיא"],2,"מִי שֶׁטָּעָה וּבֵרֵךְ ״שֶׁהַכֹּל״ עַל מַאֲכָל שֶׁיֵּשׁ לוֹ בְּרָכָה אַחֶרֶת יָצָא, וַאֲפִלּוּ עַל פַּת וְיַיִן. אַךְ לְכַתְּחִלָּה חוֹבָה לְבָרֵךְ אֶת הַבְּרָכָה הַמְּיֻחֶדֶת.","פֶּרֶק כ״ח, הֲלָכָה ד׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["לְפָנֶיךָ פְּרִי שֶׁאֵינְךָ יוֹדֵעַ אִם בִּרְכָתוֹ ״הָעֵץ״ אוֹ ״הָאֲדָמָה״, וְאֵין אֶת מִי לִשְׁאֹל. מָה תְּבָרֵךְ?",["בּוֹרֵא פְּרִי הָאֲדָמָה","בּוֹרֵא פְּרִי הָעֵץ","לֹא אֲבָרֵךְ בִּכְלָל"],0,"מִי שֶׁאֵינוֹ יוֹדֵעַ אִם הַבְּרָכָה הִיא ״הָעֵץ״ אוֹ ״הָאֲדָמָה״ וְאֵין בְּאֶפְשָׁרוּתוֹ לְבָרֵר, יְבָרֵךְ ״בּוֹרֵא פְּרִי הָאֲדָמָה״.","פֶּרֶק כ״ח, הֲלָכָה ה׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["בְּאֵיזוֹ יָד אוֹחֲזִים אֶת הַמַּאֲכָל בִּשְׁעַת הַבְּרָכָה?",["בְּיַד שְׂמֹאל","בְּיַד יָמִין","מַשְׁאִירִים אוֹתוֹ בַּמִּטְבָּח"],1,"יֵשׁ לְבָרֵךְ רַק כַּאֲשֶׁר הַמַּאֲכָל לִפְנֵי הַמְּבָרֵךְ, וְלֶאֱחֹז אוֹתוֹ בְּיַד יָמִין דֶּרֶךְ כָּבוֹד.","פֶּרֶק כ״ח, הֲלָכָה ז׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["דָּן בֵּרֵךְ עַל תַּפּוּחַ שֶׁבְּיָדוֹ, וְאָז רָאָה תַּפּוּחַ יָפֶה יוֹתֵר. מָה יַעֲשֶׂה?",["יַחֲלִיף לַתַּפּוּחַ הַיָּפֶה","יְבָרֵךְ שׁוּב עַל הַיָּפֶה","יֹאכַל אֶת הַתַּפּוּחַ שֶׁבֵּרֵךְ עָלָיו"],2,"מִי שֶׁהֶחֱזִיק בְּיָדוֹ פְּרִי וּבֵרֵךְ עָלָיו, לֹא יַחֲלִיף אוֹתוֹ בִּפְרִי טוֹב יוֹתֵר, וַאֲפִלּוּ אִם הִתְכַּוֵּן לְכָל הַפֵּרוֹת שֶׁלְּפָנָיו.","פֶּרֶק כ״ח, הֲלָכָה ח׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["אֵיזֶה צֶמַח נֶחְשָׁב לְעֵץ, וּמְבָרְכִים עָלָיו ״בּוֹרֵא עֲצֵי בְשָׂמִים״?",["נַעְנַע","הֲדַס","נַרְקִיס"],1,"לַהֲדַס יֵשׁ גֶּזַע קָשֶׁה שֶׁנִּשְׁאָר מִשָּׁנָה לְשָׁנָה, וְלָכֵן מְבָרְכִים עָלָיו ״בּוֹרֵא עֲצֵי בְשָׂמִים״. נַעְנַע וְנַרְקִיס נֶחְשָׁבִים לִשְׂיחִים.","פֶּרֶק כ״ט, הֲלָכָה ד׳","בִּרְכַּת הָרֵיחַ"],["עַל אֵיזֶה צֶמַח מְבָרְכִים ״בּוֹרֵא עִשְׂבֵי בְשָׂמִים״?",["רוֹזְמָרִין","קִנָּמוֹן","נַעְנַע"],2,"הַנַּעְנַע נֶחְשֶׁבֶת לְשִׂיחַ, וּמְבָרְכִים עָלֶיהָ ״בּוֹרֵא עִשְׂבֵי בְשָׂמִים״. רוֹזְמָרִין וְקִנָּמוֹן נֶחְשָׁבִים לְעֵצִים.","פֶּרֶק כ״ט, הֲלָכָה ה׳","בִּרְכַּת הָרֵיחַ"],["הֵרַחְנוּ פְּרִי בַּעַל רֵיחַ טוֹב כְּדֵי לֵהָנוֹת מֵרֵיחוֹ. מָה נְבָרֵךְ?",["הַנּוֹתֵן רֵיחַ טוֹב בַּפֵּרוֹת","בּוֹרֵא עֲצֵי בְשָׂמִים","בּוֹרֵא פְּרִי הָעֵץ"],0,"עַל רֵיחַ טוֹב הַיּוֹצֵא מִפְּרִי מְבָרְכִים ״הַנּוֹתֵן רֵיחַ טוֹב בַּפֵּרוֹת״.","פֶּרֶק כ״ט, הֲלָכָה ג׳","בִּרְכַּת הָרֵיחַ"],["מָה מְבָרְכִים עַל רֵיחַ שֶׁל פְּרָחִים מֵעֵץ תַּפּוּזִים?",["בּוֹרֵא עִשְׂבֵי בְשָׂמִים","בּוֹרֵא עֲצֵי בְשָׂמִים","הַנּוֹתֵן רֵיחַ טוֹב בַּפֵּרוֹת"],1,"עַל רֵיחַ הַבָּא מִפִּרְחֵי עֲצֵי פְּרִי מְבָרְכִים ״בּוֹרֵא עֲצֵי בְשָׂמִים״.","פֶּרֶק כ״ט, הֲלָכָה י׳","בִּרְכַּת הָרֵיחַ"],["אֵיזֶה יֶלֶד צָרִיךְ לְבָרֵךְ בִּרְכַּת הָרֵיחַ?",["יֶלֶד שֶׁלּוֹקֵחַ פְּרִי כְּדֵי לֶאֱכֹל אוֹתוֹ","יֶלֶד שֶׁמֵּרִיחַ אֶת יָדוֹ אַחֲרֵי שֶׁהֶחֱזִיק בְּשָׂמִים","יֶלֶד שֶׁלּוֹקֵחַ פְּרִי רֵיחָנִי כְּדֵי לְהָרִיחַ אוֹתוֹ"],2,"מִי שֶׁלּוֹקֵחַ פְּרִי כְּדֵי לֶאֱכֹל – אֵינוֹ מְבָרֵךְ עַל הָרֵיחַ. וּמִי שֶׁנִּשְׁאַר לוֹ רֵיחַ בַּיָּד – אֵינוֹ מְבָרֵךְ, כִּי הַבְּשָׂמִים אֵינָם לְפָנָיו. רַק מִי שֶׁלּוֹקֵחַ פְּרִי כְּדֵי לְהָרִיחַ – מְבָרֵךְ.","פֶּרֶק כ״ט, הֲלָכָה י״א","בִּרְכַּת הָרֵיחַ"],["עַל מָה מְבָרְכִים בִּרְכַּת הָרֵיחַ?",["עֲנַף הֲדַס שֶׁנִּמְצָא בַּיָּד","בֶּגֶד שֶׁנִּשְׁאַר בּוֹ רֵיחַ שֶׁל בְּשָׂמִים","יָד שֶׁהֶחֱזִיקָה בְּשָׂמִים קֹדֶם"],0,"אֵין מְבָרְכִים עַל רֵיחַ שֶׁהַמָּקוֹר שֶׁלּוֹ אֵינוֹ לְפָנֵינוּ – לֹא עַל רֵיחַ שֶׁנִּשְׁאַר בְּבֶגֶד וְלֹא עַל רֵיחַ שֶׁנִּשְׁאַר בַּיָּד. עַל עֲנַף הֲדַס שֶׁלְּפָנֵינוּ – מְבָרְכִים.","פֶּרֶק כ״ט, הֲלָכָה י״ב","בִּרְכַּת הָרֵיחַ"],["עַל אֵיזֶה רֵיחַ מְבָרְכִים?",["מְטַהֵר אֲוִיר בַּשֵּׁירוּתִים","זֵר נַרְקִיסִים שֶׁמְּרִיחִים בּוֹ","בֹּשֶׂם סִינְתֶּטִי מֵהַחֲנוּת"],1,"כְּשֶׁהַמַּטָּרָה הִיא לְהַעֲבִיר רֵיחַ רַע, כְּמוֹ בַּשֵּׁירוּתִים – אֵין מְבָרְכִים. וְעַל בֹּשֶׂם סִינְתֶּטִי אֵין מְבָרְכִים. עַל נַרְקִיסִים שֶׁמְּרִיחִים בָּהֶם – מְבָרְכִים.","פֶּרֶק כ״ט, הֲלָכוֹת י״ג-י״ד","בִּרְכַּת הָרֵיחַ"],["אַחֲרֵי מָה מְבָרְכִים בְּרָכָה אַחֲרוֹנָה?",["אַחֲרֵי שֶׁהֵרַחְנוּ הֲדַס","אַחֲרֵי שֶׁהֵרַחְנוּ נַעְנַע","אַחֲרֵי אֲכִילָה וּשְׁתִיָּה"],2,"אַחֲרֵי אֲכִילָה וּשְׁתִיָּה הַגּוּף מַמְשִׁיךְ לֵהָנוֹת מֵהַשֹּׂבַע, אֲבָל הַתַּעֲנוּג שֶׁל הָרֵיחַ נִגְמָר מִיָּד, וְלָכֵן אֵין עָלָיו בְּרָכָה אַחֲרוֹנָה.","פֶּרֶק כ״ט, הֲלָכָה ב׳","בִּרְכַּת הָרֵיחַ"],["מִמָּה נֶהֱנֵית הַנְּשָׁמָה, וְהַגּוּף אֵינוֹ נֶהֱנֶה מִמֶּנּוּ?",["רֵיחַ","אֹכֶל","מַיִם"],0,"אָמְרוּ חֲכָמִים: אֵיזֶהוּ דָּבָר שֶׁהַנְּשָׁמָה נֶהֱנֵית מִמֶּנּוּ וְאֵין הַגּוּף נֶהֱנֶה מִמֶּנּוּ? זֶה הָרֵיחַ.","פֶּרֶק כ״ט, הֲלָכָה א׳","בִּרְכַּת הָרֵיחַ"],["עַל מָה מְבָרְכִים ״שֶׁהֶחֱיָנוּ״?",["עַל לֶחֶם רָגִיל שֶׁאוֹכְלִים כָּל יוֹם","עַל פְּרִי חָדָשׁ שֶׁמִּתְחַדֵּשׁ מִזְּמַן לִזְמַן","עַל כּוֹס מַיִם בְּיוֹם חַם"],1,"מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ עַל פְּרִי הַמִּתְחַדֵּשׁ מִזְּמַן לִזְמַן, כִּי זוֹ שִׂמְחָה שֶׁבָּאָה מִזְּמַן לִזְמַן.","פֶּרֶק ל׳, הֲלָכָה ב׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["מָתַי מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ כְּשֶׁרוֹאִים חָבֵר אָהוּב?",["כְּשֶׁלֹּא רָאִינוּ אוֹתוֹ שְׁלוֹשִׁים יוֹם","כְּשֶׁרָאִינוּ אוֹתוֹ אֶתְמוֹל בְּבֵית הַסֵּפֶר","בְּכָל בֹּקֶר כְּשֶׁפּוֹגְשִׁים אוֹתוֹ"],0,"מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ עַל רְאִיַּת פְּנֵי חָבֵר אָהוּב שֶׁלֹּא רָאִינוּ שְׁלוֹשִׁים יוֹם.","פֶּרֶק ל׳, הֲלָכָה ב׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["בְּאֵיזֶה זְמַן מְבָרְכִים בְּדֶרֶךְ כְּלָל ״שֶׁהֶחֱיָנוּ״ עַל יוֹם טוֹב?",["בְּסוֹף הַחַג","בִּזְמַן הַקִּדּוּשׁ","בְּאֶמְצַע הַלַּיְלָה"],1,"עַל מוֹעֲדִים וְיָמִים טוֹבִים מְבָרְכִים ״שֶׁהֶחֱיָנוּ״, וּבְדֶרֶךְ כְּלָל בִּזְמַן הַקִּדּוּשׁ.","פֶּרֶק ל׳, הֲלָכָה ב׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["לִפְנֵי אֵיזוֹ מִצְוָה מְבָרְכִים ״שֶׁהֶחֱיָנוּ״?",["נְטִילַת יָדַיִם","בִּרְכַּת הַמָּזוֹן","תְּקִיעַת שׁוֹפָר"],2,"מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ לִפְנֵי מִצְווֹת הַבָּאוֹת מִזְּמַן לִזְמַן, כְּמוֹ שׁוֹפָר, לוּלָב וְנֵר חֲנֻכָּה.","פֶּרֶק ל׳, הֲלָכָה ב׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["מִמִּי לָמְדוּ חֲכָמִים שֶׁיֵּשׁ לְבָרֵךְ עַל הַנִּסִּים?",["מִיִּתְרוֹ","מִפַּרְעֹה","מִבִּלְעָם"],0,"יִתְרוֹ שָׁמַע עַל נִסֵּי יְצִיאַת מִצְרַיִם וְאָמַר: ״בָּרוּךְ ה׳ אֲשֶׁר הִצִּיל אֶתְכֶם מִיַּד מִצְרַיִם״, וּמִכָּאן לָמְדוּ חֲכָמִים לְבָרֵךְ עַל הַנִּסִּים.","פֶּרֶק ל״א, הֲלָכָה א׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["אֵיזֶה מָקוֹם מַזְכִּיר נֵס שֶׁנַּעֲשָׂה לְכָל עַם יִשְׂרָאֵל?",["חֲנוּת צַעֲצוּעִים","מִגְרַשׁ כַּדּוּרֶגֶל","מַעֲבָרוֹת יַם סוּף"],2,"עַל מְקוֹם נֵס לְכָל יִשְׂרָאֵל, כְּמוֹ מַעֲבָרוֹת יַם סוּף וְהַיַּרְדֵּן, מְבָרְכִים ״שֶׁעָשָׂה נִסִּים לַאֲבוֹתֵינוּ בַּמָּקוֹם הַזֶּה״.","פֶּרֶק ל״א, הֲלָכָה ג׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["אָדָם נִצַּל מִבִּנְיָן שֶׁהִתְמוֹטֵט. מָה יְבָרֵךְ כְּשֶׁיַּגִּיעַ לַמָּקוֹם?",["שֶׁעָשָׂה לִי נֵס בַּמָּקוֹם הַזֶּה","שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ","בּוֹרֵא פְּרִי הָעֵץ"],0,"הַמַּגִּיעַ לְמָקוֹם שֶׁנַּעֲשָׂה לוֹ בּוֹ נֵס, כְּמוֹ הַצָּלָה מֵהִתְמוֹטְטוּת בִּנְיָן, מְבָרֵךְ ״בָּרוּךְ שֶׁעָשָׂה לִי נֵס בַּמָּקוֹם הַזֶּה״.","פֶּרֶק ל״א, הֲלָכָה ד׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["מָה צָרִיךְ לַעֲשׂוֹת נוֹסֵעַ כְּשֶׁהוּא מִתְיַשֵּׁב בַּמְּכוֹנִית?",["לַעֲמֹד עַל הַמּוֹשָׁב","לַחֲגֹר חֲגוֹרַת בְּטִיחוּת","לְהָרִים אֶת הַקּוֹל"],1,"עַל הַנּוֹסְעִים לְהַקְפִּיד לִהְיוֹת חֲגוּרִים בַּחֲגוֹרַת הַבְּטִיחוּת.","פֶּרֶק ל״ב, הֲלָכָה א׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["אֵיזֶה נַהָג נוֹהֵג כָּרָאוּי?",["נַהָג שֶׁמְּדַבֵּר בַּטֶּלֶפוֹן בִּזְמַן נְהִיגָה","נַהָג שֶׁעוֹקֵף בְּמָקוֹם אָסוּר","נַהָג שֶׁמַּבִּיט בַּכְּבִישׁ וְיָדָיו עַל הַהֶגֶה"],2,"הַנַּהָג צָרִיךְ לְהִתְרַכֵּז בַּכְּבִישׁ, וְלֹא לַעֲקֹף בְּמָקוֹם אָסוּר וְלֹא לַעֲסֹק בַּטֶּלֶפוֹן.","פֶּרֶק ל״ב, הֲלָכָה א׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["אֵיךְ צְרִיכִים הַנּוֹסְעִים לְהִתְנַהֵג בִּזְמַן הַנְּסִיעָה?",["לָשֶׁבֶת בְּשֶׁקֶט וְלֹא לְהַפְרִיעַ לַנַּהָג","לְהִשְׁתּוֹלֵל וְלִזְרֹק חֲפָצִים","לִמְשֹׁךְ אֶת הַנַּהָג בַּשַּׁרְוּוּל"],0,"עַל הַנּוֹסְעִים לְאַפְשֵׁר לַנַּהָג לְהִתְרַכֵּז, לֹא לְהָקִים רַעַשׁ וְלֹא לְהִשְׁתּוֹלֵל.","פֶּרֶק ל״ב, הֲלָכָה א׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["רָאִיתָ נַהָג שֶׁנּוֹהֵג בְּצוּרָה מְסֻכֶּנֶת. אֵיךְ מוֹכִיחִים אוֹתוֹ?",["צוֹעֲקִים עָלָיו מוּל כֻּלָּם","בְּדַרְכֵי נֹעַם וּבְלִי לְבַיֵּשׁ","לֹא אוֹמְרִים לוֹ כְּלוּם"],1,"מִצְוָה לְהוֹכִיחַ אוֹתוֹ, אַךְ בְּדַרְכֵי נֹעַם וּבְצוּרָה שֶׁלֹּא תְּבַיֵּשׁ אוֹתוֹ.","פֶּרֶק ל״ב, הֲלָכָה ב׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["מָתַי אוֹמְרִים אֶת תְּפִלַּת הַדֶּרֶךְ?",["בַּבַּיִת לִפְנֵי שֶׁיּוֹצְאִים","כְּשֶׁמַּגִּיעִים לַמָּקוֹם","מִיָּד כְּשֶׁיּוֹצְאִים מִתְּחוּמֵי הָעִיר"],2,"יֵשׁ לוֹמַר אֶת תְּפִלַּת הַדֶּרֶךְ מִיָּד כַּאֲשֶׁר יוֹצְאִים מִתְּחוּמֵי הָעִיר.","פֶּרֶק ל״ב, הֲלָכָה ה׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["בָּאוֹטוֹבּוּס שׁוֹמְעִים אֶת הַמְּבָרֵךְ רַק דֶּרֶךְ רַמְקוֹל. מָה עָדִיף לַעֲשׂוֹת?",["לְהַמְשִׁיךְ לְשַׂחֵק בְּלִי לְהַקְשִׁיב","לוֹמַר עִם הַמְּבָרֵךְ מִלָּה בְּמִלָּה","לָלֶכֶת לִישֹׁן"],1,"מִי שֶׁשּׁוֹמֵעַ אֶת הַמְּבָרֵךְ רַק בְּעֶזְרַת רַמְקוֹל, עָדִיף שֶׁיֹּאמַר אִתּוֹ אֶת הַתְּפִלָּה מִלָּה בְּמִלָּה.","פֶּרֶק ל״ב, הֲלָכָה ז׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["אַבָּא נוֹסֵעַ וְחוֹזֵר בְּאוֹתוֹ הַיּוֹם. מָה מוֹסִיף בִּתְפִלַּת הַדֶּרֶךְ?",["וְתַחֲזִירֵנוּ לְשָׁלוֹם","וְתַרְדִּימֵנוּ לְשָׁלוֹם","אֵינוֹ מוֹסִיף כְּלוּם"],0,"מִי שֶׁחוֹזֵר בְּאוֹתוֹ הַיּוֹם אוֹמֵר גַּם ״וְתַחֲזִירֵנוּ לְשָׁלוֹם״.","פֶּרֶק ל״ב, הֲלָכָה ג׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["מִי מֵהַשְּׁלוֹשָׁה צָרִיךְ לְבָרֵךְ בִּרְכַּת הַגּוֹמֵל?",["מִי שֶׁהָלַךְ לַמַּכֹּלֶת","מִי שֶׁעָלָה מִן הַיָּם לַיַּבָּשָׁה","מִי שֶׁשִּׂחֵק בַּגִּנָּה"],1,"יוֹרְדֵי הַיָּם הֵם אֶחָד מֵאַרְבָּעָה שֶׁצְּרִיכִים לְהוֹדוֹת, וּמְבָרְכִים לְאַחַר שֶׁעוֹלִים לַיַּבָּשָׁה.","פֶּרֶק ל״ג, הֲלָכָה א׳","בִּרְכַּת הַגּוֹמֵל"],["מִי מֵהֶם צָרִיךְ לְבָרֵךְ הַגּוֹמֵל?",["מִי שֶׁקָּנָה נַעֲלַיִם חֲדָשׁוֹת","מִי שֶׁקִּבֵּל מַתָּנָה","מִי שֶׁהָיָה חוֹלֶה וְנִתְרַפָּא"],2,"חוֹלֶה שֶׁנִּתְרַפָּא הוּא אֶחָד מֵאַרְבָּעָה הַצְּרִיכִים לְהוֹדוֹת לַה׳ עַל הַצָּלָתָם.","פֶּרֶק ל״ג, הֲלָכָה א׳","בִּרְכַּת הַגּוֹמֵל"],["מָה עוֹנִים הַשּׁוֹמְעִים לְמִי שֶׁבֵּרַךְ הַגּוֹמֵל?",["אָמֵן, הָאֵל אֲשֶׁר גְּמָלְךָ כָּל טוּב","מַזָּל טוֹב וּבְשָׁעָה טוֹבָה","בָּרוּךְ הַבָּא"],0,"הַשּׁוֹמְעִים עוֹנִים: אָמֵן, הָאֵל אֲשֶׁר גְּמָלְךָ כָּל טוּב, הוּא יִגְמָלְךָ כָּל טוּב סֶלָה.","פֶּרֶק ל״ג, הֲלָכָה ב׳","בִּרְכַּת הַגּוֹמֵל"],["מִי שֶׁהָיָה בְּמַצָּב שֶׁעָלוּל לְהַגִּיעַ לְסַכָּנָה, אֲבָל לֹא קָרָה לוֹ כְּלוּם — הַאִם מְבָרֵךְ?",["לֹא, רַק מִי שֶׁנִּפְגַּע","כֵּן, כִּי נִכְנַס לְמַצָּב מְסֻכָּן","רַק אִם פָּחַד מְאֹד"],1,"חֲכָמִים תִּקְּנוּ אֶת הַבְּרָכָה לְכָל מִי שֶׁנִּכְנַס לְמַצָּב שֶׁבּוֹ הוּא עָלוּל לְהַגִּיעַ לְסַכָּנָה, גַּם בְּלִי סַכָּנָה מַמָּשִׁית.","פֶּרֶק ל״ג, הֲלָכָה ד׳","בִּרְכַּת הַגּוֹמֵל"],["נְסִיעָה שֶׁל עֶשְׂרִים דַּקּוֹת בִּלְבַד — הַאִם מְבָרְכִים הַגּוֹמֵל?",["כֵּן, עַל כָּל נְסִיעָה","רַק בַּלַּיְלָה","לֹא, הַנְּסִיעָה קְצָרָה מִדַּי"],2,"בִּנְסִיעָה מְבָרְכִים רַק אִם נִמְשְׁכָה כִּזְמַן הֲלִיכַת פַּרְסָה — שִׁבְעִים וּשְׁתַּיִם דַּקּוֹת לְפָחוֹת.","פֶּרֶק ל״ג, הֲלָכָה ו׳","בִּרְכַּת הַגּוֹמֵל"],["הַהַפְלָגָה עָבְרָה בְּשָׁלוֹם בְּלִי סְעָרָה. הַאִם מְבָרְכִים?",["לֹא, רַק אַחֲרֵי סְעָרָה","כֵּן, גַּם כְּשֶׁעָבְרָה בְּשָׁלוֹם","רַק אִם הָיָה גֶּשֶׁם"],1,"יֵשׁ לְבָרֵךְ גַּם כְּשֶׁהַהַפְלָגָה עָבְרָה בְּשָׁלוֹם לְלֹא סְעָרָה.","פֶּרֶק ל״ג, הֲלָכָה ח׳","בִּרְכַּת הַגּוֹמֵל"],["מָה נוֹהֲגִים יֵשׁ לַעֲשׂוֹת אַחֲרֵי טִיסָה בְּמָטוֹס?",["לְבָרֵךְ הַגּוֹמֵל","לְבָרֵךְ עַל הַמִּחְיָה","לְבָרֵךְ שֶׁהַכֹּל"],0,"לְאַחַר טִיסָה בְּמָטוֹס יֵשׁ נוֹהֲגִים לְבָרֵךְ הַגּוֹמֵל.","פֶּרֶק ל״ג, הֲלָכָה ח׳","בִּרְכַּת הַגּוֹמֵל"],["לְמִנְהַג הָאַשְׁכְּנַזִּים, מִי שֶׁנִּצַּל מִשְּׂרֵפָה —",["אֵינוֹ מְבָרֵךְ כְּלָל","מְבָרֵךְ שֶׁהַכֹּל","מְבָרֵךְ הַגּוֹמֵל בְּשֵׁם וּמַלְכוּת"],2,"לְמִנְהַג הָאַשְׁכְּנַזִּים וְחֵלֶק מֵהַסְּפָרַדִּים, כָּל מִי שֶׁהָיָה בְּסַכָּנָה וְנִצַּל מְבָרֵךְ הַגּוֹמֵל בְּשֵׁם וּמַלְכוּת.","פֶּרֶק ל״ג, הֲלָכָה ט׳","בִּרְכַּת הַגּוֹמֵל"],["תַּיָּר מִחוּץ לָאָרֶץ מַגִּיעַ לְאֶרֶץ יִשְׂרָאֵל וְרוֹאֶה עָרִים בְּנוּיוֹת וּמְלֵאוֹת אֲנָשִׁים. אֵיזוֹ בְּרָכָה הוּא מְבָרֵךְ?",["בָּרוּךְ מַצִּיב גְּבוּל אַלְמָנָה","שֶׁעָשָׂה אֶת הַיָּם הַגָּדוֹל","שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו"],0,"הָרוֹאֶה בָּתֵּי יִשְׂרָאֵל בְּיִשּׁוּבָם מְבָרֵךְ \"בָּרוּךְ מַצִּיב גְּבוּל אַלְמָנָה\" בְּלִי שֵׁם וּמַלְכוּת. הָאַלְמָנָה הִיא אֶרֶץ יִשְׂרָאֵל, שֶׁה׳ מַחֲזִיר אֵלֶיהָ אֶת בָּנֶיהָ.","פֶּרֶק ל״ד, הֲלָכָה א׳","בִּרְכוֹת הָרְאִיָּה"],["בְּלֵיל חֹרֶף רוֹאִים בָּרָק מֵאִיר אֶת הַשָּׁמַיִם. אֵיזוֹ בְּרָכָה מְבָרְכִים?",["מַצִּיב גְּבוּל אַלְמָנָה","עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית","שֶׁנָּתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם"],1,"כַּאֲשֶׁר רוֹאִים בְּרָקִים מְבָרְכִים \"עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית\". עַל רְעָמִים מְבָרְכִים \"שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם\".","פֶּרֶק ל״ה, הֲלָכָה ב׳","בִּרְכוֹת הָרְאִיָּה"],["יְלָדִים פּוֹגְשִׁים רַב גָּדוֹל בַּתּוֹרָה. אֵיזוֹ בְּרָכָה מְבָרְכִים?",["שֶׁעָשָׂה אֶת הַיָּם הַגָּדוֹל","עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית","שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו"],2,"הָרוֹאֶה חָכָם מֵחַכְמֵי יִשְׂרָאֵל בְּחָכְמַת הַתּוֹרָה מְבָרֵךְ \"בָּרוּךְ שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו\" בְּלִי שֵׁם וּמַלְכוּת.","פֶּרֶק ל״ד, הֲלָכָה ג׳","בִּרְכוֹת הָרְאִיָּה"],["מִשְׁפָּחָה טָסָה לְחוּץ לָאָרֶץ וְרוֹאָה אֶת הָאוֹקְיָנוֹס. אֵיזוֹ בְּרָכָה מְבָרְכִים?",["שֶׁעָשָׂה אֶת הַיָּם הַגָּדוֹל","מַצִּיב גְּבוּל אַלְמָנָה","שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו"],0,"כַּאֲשֶׁר רוֹאִים אֶת הַיָּם הַגָּדוֹל – הָאוֹקְיָנוֹס – מְבָרְכִים \"בָּרוּךְ אַתָּה ה׳ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁעָשָׂה אֶת הַיָּם הַגָּדוֹל\".","פֶּרֶק ל״ה, הֲלָכָה ה׳","בִּרְכוֹת הָרְאִיָּה"],["עַל אֵיזֶה מֵהַמַּרְאוֹת הָאֵלֶּה מְבָרְכִים \"עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית\"?",["בִּנְיַן מִשְׂרָדִים גָּבוֹהַּ","הַר תָּבוֹר","גַּן מִשְׂחָקִים בַּשְּׁכוּנָה"],1,"עַל הָרִים שֶׁגְּבוֹהִים בִּמְיֻחָד מִסְּבִיבָתָם, כְּמוֹ הַר תָּבוֹר, מְבָרְכִים \"עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית\". בִּנְיָן וְגַן אֵינָם מַעֲשֵׂה בְרֵאשִׁית.","פֶּרֶק ל״ה, הֲלָכָה ד׳","בִּרְכוֹת הָרְאִיָּה"],["דָּוִד רָאָה רְעִידַת אֲדָמָה אוֹ בָּרָק. מָתַי עָלָיו לְבָרֵךְ?",["בְּסוֹף הַיּוֹם","לְמָחֳרָת בַּבֹּקֶר","מִיָּד לְאַחַר הָרְאִיָּה"],2,"בִּרְכוֹת הָרְאִיָּה מְבָרְכִים מִיָּד לְאַחַר הָרְאִיָּה.","פֶּרֶק ל״ה, הֲלָכָה ו׳","בִּרְכוֹת הָרְאִיָּה"],["רוֹאִים מַדְעָן גָּדוֹל מֵאֻמּוֹת הָעוֹלָם, שֶׁחָכְמָתוֹ בְּמַדָּעִים. אֵיזוֹ בְּרָכָה מְבָרְכִים?",["שֶׁנָּתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם","שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו","מַצִּיב גְּבוּל אַלְמָנָה"],0,"עַל חָכָם מֵאֻמּוֹת הָעוֹלָם שֶׁחָכְמָתוֹ בְּחָכְמַת הָעוֹלָם מְבָרְכִים \"בָּרוּךְ שֶׁנָּתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם\" בְּלִי שֵׁם וּמַלְכוּת.","פֶּרֶק ל״ד, הֲלָכָה ד׳","בִּרְכוֹת הָרְאִיָּה"],["רָאִיתָ אֶת הַיָּם לִפְנֵי שָׁבוּעַ, וְהַיּוֹם אַתָּה רוֹאֶה אוֹתוֹ שׁוּב. הַאִם מְבָרְכִים?",["כֵּן, בְּכָל פַּעַם שֶׁרוֹאִים מְבָרְכִים","לֹא, עוֹד לֹא עָבְרוּ שְׁלוֹשִׁים יוֹם","רַק אִם הַיָּם סוֹעֵר"],1,"עַל יַמִּים, נְהָרוֹת, הָרִים וּמִדְבָּרִיּוֹת מְבָרְכִים רַק אִם לֹא רָאוּ אוֹתָם שְׁלוֹשִׁים יָמִים רְצוּפִים.","פֶּרֶק ל״ה, הֲלָכָה ז׳","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["אֵיזוֹ בְּרָכָה אוֹמְרִים כְּשֶׁרוֹאִים קֶשֶׁת בֶּעָנָן?",["זוֹכֵר הַבְּרִית","עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית","שֶׁכָּכָה לּוֹ בְּעוֹלָמוֹ"],0,"עַל הַקֶּשֶׁת מְבָרְכִים: ״זוֹכֵר הַבְּרִית וְנֶאֱמָן בִּבְרִיתוֹ וְקַיָּם בְּמַאֲמָרוֹ״.","פֶּרֶק ל״ה, הֲלָכָה ח׳","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["יֶלֶד רוֹאֶה קֶשֶׁת יָפָה. מָה הַדֶּרֶךְ הַנְּכוֹנָה?",["לְהִסְתַּכֵּל בָּהּ זְמַן רַב","לְצַלֵּם אוֹתָהּ בְּלִי לְבָרֵךְ","לְבָרֵךְ וְלֹא לְהַרְבּוֹת לְהִסְתַּכֵּל"],2,"אָסוּר לְהִסְתַּכֵּל בַּקֶּשֶׁת יוֹתֵר מִדַּי, כִּי בַּגְּמָרָא כָּתוּב שֶׁהַמִּסְתַּכֵּל בַּקֶּשֶׁת עֵינָיו כֵּהוֹת.","פֶּרֶק ל״ה, הֲלָכָה ט׳","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["אֶתְמוֹל בֵּרַכְתָּ עַל קֶשֶׁת, וְהַיּוֹם הוֹפִיעָה קֶשֶׁת חֲדָשָׁה. מָה עוֹשִׂים?",["לֹא מְבָרְכִים, כְּבָר בֵּרַכְנוּ","מְבָרְכִים שׁוּב, זוֹ קֶשֶׁת חֲדָשָׁה","מְחַכִּים שְׁלוֹשִׁים יוֹם"],1,"בְּכָל פַּעַם שֶׁרוֹאִים קֶשֶׁת חֲדָשָׁה – חוֹזְרִים וּמְבָרְכִים.","פֶּרֶק ל״ה, הֲלָכָה י׳","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["בַּטִּיּוּל רָאִיתָ עֵצִים יָפִים וּמְיֻחָדִים בִּמְיֻחָד. מָה מְבָרְכִים?",["זוֹכֵר הַבְּרִית","עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית","בָּרוּךְ שֶׁכָּכָה לּוֹ בְּעוֹלָמוֹ"],2,"עַל אִילָנוֹת טוֹבִים וּבְרִיּוֹת נָאוֹת מְבָרְכִים בְּלִי שֵׁם וּמַלְכוּת: ״בָּרוּךְ שֶׁכָּכָה לּוֹ בְּעוֹלָמוֹ״.","פֶּרֶק ל״ה, הֲלָכָה י״א","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["בֵּרַכְתָּ עַל טַוָּס יָפֶה. אַחַר כָּךְ רָאִיתָ טַוָּס יָפֶה עוֹד יוֹתֵר. מָה עוֹשִׂים?",["מְבָרְכִים שׁוּב, כִּי הוּא נָאֶה יוֹתֵר","לֹא מְבָרְכִים שׁוּב אַף פַּעַם","מְבָרְכִים רַק אַחֲרֵי שָׁנָה"],0,"מִי שֶׁבֵּרַךְ ״שֶׁכָּכָה לּוֹ בְּעוֹלָמוֹ״ לֹא יְבָרֵךְ שׁוּב, אֶלָּא אִם כֵּן יִרְאֶה בְּרִיּוֹת נָאוֹת יוֹתֵר מֵאֵלּוּ שֶׁעֲלֵיהֶן בֵּרַךְ.","פֶּרֶק ל״ה, הֲלָכָה י״א","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["כַּמָּה פְּעָמִים מְבָרְכִים אֶת ״בִּרְכַּת הַחַמָּה״?",["פַּעַם בְּשָׁנָה","פַּעַם בְּעֶשְׂרִים וּשְׁמוֹנֶה שָׁנָה","כָּל בֹּקֶר"],1,"כְּשֶׁהַחַמָּה חוֹזֶרֶת לִמְקוֹמָהּ בִּזְמַן הַבְּרִיאָה – פַּעַם בְּעֶשְׂרִים וּשְׁמוֹנֶה שָׁנָה – מְבָרְכִים ״עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית״.","פֶּרֶק ל״ה, הֲלָכָה י״ב","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["מָתַי יָרְדָה קְדֻשַּׁת הַשַּׁבָּת לָעוֹלָם?",["כְּבָר בַּשַּׁבָּת הָרִאשׁוֹנָה שֶׁל הָעוֹלָם","רַק בְּמַתַּן תּוֹרָה","רַק כְּשֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ"],0,"מֵהַפָּסוּק ״וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ״ לוֹמְדִים שֶׁקְּדֻשַּׁת הַשַּׁבָּת יָרְדָה לָעוֹלָם כְּבָר בַּשַּׁבָּת הָרִאשׁוֹנָה, כִּי לֹא נֶעֶשְׂתָה בָּהּ מְלָאכָה.","פֶּרֶק ל״ו, הֲלָכָה א׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["מָה רָאוּ בְּנֵי יִשְׂרָאֵל בַּמִּדְבָּר בְּיוֹם הַשַּׁבָּת?",["הַמָּן יָרַד בְּשַׁבָּת כְּמוֹ בְּכָל יוֹם","הַמָּן לֹא יָרַד בְּשַׁבָּת","יָרַד גֶּשֶׁם חָזָק בַּמִּדְבָּר"],1,"בְּדוֹר הַמִּדְבָּר רָאוּ בְּנֵי יִשְׂרָאֵל בְּעֵינֵיהֶם אֶת קְדֻשַּׁת הַשַּׁבָּת: הַמָּן לֹא יָרַד בְּשַׁבָּת. גַּם הַיּוֹם, מִי שֶׁשּׁוֹמֵר שַׁבָּת מַרְגִּישׁ שֶׁבָּהּ מִתְחַדְּשִׁים הַכֹּחַ הַגּוּפָנִי וְהַכֹּחַ הַשִּׂכְלִי.","פֶּרֶק ל״ו, הֲלָכוֹת ב׳-ג׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["הַשַּׁבָּת הִיא סִימָן לְמָה?",["סִימָן שֶׁהִגִּיעַ זְמַן לָנוּחַ מֵהָעֲבוֹדָה","סִימָן לִתְחִלַּת הַחֹדֶשׁ","סִימָן לַבְּרִית בֵּין ה׳ לְעַם יִשְׂרָאֵל"],2,"בַּתּוֹרָה נֶאֱמָר: ״בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִוא לְעֹלָם״. הַשַּׁבָּת הִיא אוֹת (סִימָן) לַבְּרִית שֶׁבֵּין ה׳ לְיִשְׂרָאֵל.","פֶּרֶק ל״ו, הֲלָכָה ד׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["שְׁמִירַת הַשַּׁבָּת שְׁקוּלָה כְּנֶגֶד מָה?",["כְּנֶגֶד מִצְוָה אַחַת בִּלְבַד","כְּנֶגֶד כָּל מִצְווֹת הַתּוֹרָה","כְּנֶגֶד עֶשֶׂר מִצְווֹת"],1,"שְׁמִירַת הַשַּׁבָּת שְׁקוּלָה כְּנֶגֶד כָּל מִצְווֹת הַתּוֹרָה, וְחֲכָמִים אָמְרוּ שֶׁאִם יִשְׁמְרוּ יִשְׂרָאֵל שְׁתֵּי שַׁבָּתוֹת כְּהִלְכָתָן – מִיָּד נִגְאָלִין.","פֶּרֶק ל״ו, הֲלָכָה ה׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["הַאִם מֻתָּר לוֹמַר לְגוֹי לַעֲשׂוֹת מְלָאכָה בְּשַׁבָּת בִּשְׁבִילֵנוּ?",["לֹא, חֲכָמִים אָסְרוּ זֹאת","כֵּן, כִּי הוּא אֵינוֹ יְהוּדִי","רַק אִם הַמְּלָאכָה קְטַנָּה"],0,"חֲכָמִים אָסְרוּ לוֹמַר לְגוֹי לַעֲשׂוֹת מְלָאכָה בְּשַׁבָּת עֲבוּר יִשְׂרָאֵל: כְּדֵי שֶׁלֹּא יְזַלְזְלוּ בְּשַׁבָּת, וּכְדֵי שֶׁתִּהְיֶה מְנוּחַת הַשַּׁבָּת שְׁלֵמָה.","פֶּרֶק ל״ו, הֲלָכָה ו׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["לִכְבוֹד מִי מְכַבְּדִים וּמְעַנְּגִים אֶת הַשַּׁבָּת?",["לִכְבוֹדֵנוּ","לַהֲנָאַת הַגּוּף","לִכְבוֹד הַשַּׁבָּת"],2,"רָאוּי לְכַבֵּד וּלְעַנֵּג אֶת הַשַּׁבָּת בְּמַאֲכָל וּבְמִשְׁתֶּה, אֲבָל צָרִיךְ לִזְכֹּר שֶׁזֶּה אֵינוֹ לִכְבוֹדֵנוּ וְלַהֲנָאַת גּוּפֵנוּ, אֶלָּא לִכְבוֹד הַשַּׁבָּת.","פֶּרֶק ל״ז, הֲלָכָה א׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["שַׁמַּאי הַזָּקֵן מָצָא בְּהֵמָה נָאָה, וְאַחַר כָּךְ מָצָא נָאָה מִמֶּנָּה. מָה עָשָׂה?",["אָכַל אֶת שְׁתֵּיהֶן מִיָּד","אָכַל אֶת הָרִאשׁוֹנָה וְשָׁמַר אֶת הַשְּׁנִיָּה לְשַׁבָּת","שָׁמַר אֶת הָרִאשׁוֹנָה לְשַׁבָּת וְמָכַר אֶת הַשְּׁנִיָּה"],1,"שַׁמַּאי הַזָּקֵן אָכַל כָּל יָמָיו לִכְבוֹד שַׁבָּת: כְּשֶׁמָּצָא בְּהֵמָה נָאָה יוֹתֵר, שָׁמַר אוֹתָהּ לְשַׁבָּת וְאָכַל אֶת הָרִאשׁוֹנָה.","פֶּרֶק ל״ז, הֲלָכָה ב׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["מָה יַעֲשֶׂה לְעֹנֶג שַׁבָּת מִי שֶׁאֵין לוֹ מַסְפִּיק כֶּסֶף?",["יִלְוֶה כֶּסֶף רַב מֵאֲחֵרִים","לֹא יָכִין שׁוּם דָּבָר מְיֻחָד","יָכִין אֲפִלּוּ מַאֲכָל אֶחָד קָטָן יוֹתֵר מֵהָרָגִיל"],2,"כָּל אָדָם מְעַנֵּג אֶת הַשַּׁבָּת לְפִי מַצָּבוֹ. מִי שֶׁאֵין לוֹ כֶּסֶף – דַּי בְּמַאֲכָל אֶחָד קָטָן יוֹתֵר מֵהֶרְגֵּלוֹ, וְאֵינוֹ חַיָּב לִלְווֹת: ״עֲשֵׂה שַׁבַּתְּךָ חֹל וְאַל תִּצְטָרֵךְ לַבְּרִיּוֹת״.","פֶּרֶק ל״ז, הֲלָכוֹת ג׳-ה׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["אֵיזוֹ שִׂמְחָה יֵשׁ בְּשַׁבָּת?",["שִׂמְחָה רוּחָנִית בְּמַלְכוּת ה׳","שִׂמְחָה שֶׁל מְסִבַּת רִקּוּדִים","אֵין שִׂמְחָה בְּשַׁבָּת"],0,"לֹא כָּתוּב בַּתּוֹרָה מִצְוָה לִשְׂמֹחַ בְּשַׁבָּת כְּמוֹ בַּחַגִּים, אֲבָל יֵשׁ בָּהּ שִׂמְחָה רוּחָנִית, וְלָכֵן אוֹמְרִים ״יִשְׂמְחוּ בְמַלְכוּתְךָ שׁוֹמְרֵי שַׁבָּת״.","פֶּרֶק ל״ז, הֲלָכָה ו׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["בַּמִּדְבָּר יָרַד מָן כָּפוּל בְּיוֹם שִׁשִּׁי, וּמִכָּאן לָמַדְנוּ לְהָכִין לְשַׁבָּת. מָתַי מִצְוָה לְהַשְׁכִּים וְלִקְנוֹת אֶת צָרְכֵי הַשַּׁבָּת?",["בְּבֹקֶר יוֹם שִׁשִּׁי","בְּמוֹצָאֵי שַׁבָּת","בְּלֵיל שַׁבָּת"],0,"מֵהַפָּסוּק ״וְהֵכִינוּ אֵת אֲשֶׁר יָבִיאוּ״ לָמְדוּ עַל חוֹבַת הַהֲכָנָה לְשַׁבָּת, וּמִצְוָה לְהַשְׁכִּים בְּבֹקֶר יוֹם שִׁשִּׁי לִקְנוֹת וּלְהָכִין.","פֶּרֶק ל״ח, הֲלָכָה א׳-ב׳","מְכִינִים אֶת הַשַּׁבָּת"],["אַבָּא עָסוּק מְאוֹד בַּעֲבוֹדָתוֹ. מָה רָאוּי שֶׁיַּעֲשֶׂה לִפְנֵי הַשַּׁבָּת?",["יִשְׁלַח אֲחֵרִים וְלֹא יִטְרַח","יִטְרַח בְּעַצְמוֹ לִכְבוֹד שַׁבָּת","יָנוּחַ כָּל יוֹם שִׁשִּׁי"],1,"גַּם אָדָם עָסוּק חַיָּב לִטְרֹחַ בְּעַצְמוֹ, כִּי הַטִּרְחָה לִכְבוֹד הַשַּׁבָּת הִיא כְּבוֹדוֹ. וְגַם הַיְּלָדִים צְרִיכִים לַעֲזֹר וּלְהִשְׁתַּתֵּף בַּהֲכָנוֹת.","פֶּרֶק ל״ח, הֲלָכָה ג׳-ד׳","מְכִינִים אֶת הַשַּׁבָּת"],["מָה אוֹמֵר רֹאשׁ הַבַּיִת לִבְנֵי בֵּיתוֹ כְּשֶׁהַשַּׁבָּת מִתְקָרֶבֶת?",["לְכוּ לִישֹׁן מֻקְדָּם","בּוֹאוּ נֵצֵא לְטַיֵּל","הַדְלִיקוּ אֶת הַנֵּר!"],2,"רֹאשׁ הַבַּיִת אוֹמֵר: ״עִשַּׂרְתֶּם? עֵרַבְתֶּם? הַדְלִיקוּ אֶת הַנֵּר!״, וּמַזְכִּיר לְסַיֵּם בַּזְּמַן אֶת כָּל הַהֲכָנוֹת.","פֶּרֶק ל״ח, הֲלָכָה ה׳","מְכִינִים אֶת הַשַּׁבָּת"],["אֵילוּ בְּגָדִים לוֹבְשִׁים לִכְבוֹד הַשַּׁבָּת?",["בִּגְדֵי עֲבוֹדָה מְלֻכְלָכִים","בְּגָדִים חֲגִיגִיִּים וּנְקִיִּים","בִּגְדֵי סְפּוֹרְט"],1,"יֵשׁ לִלְבֹּשׁ לִכְבוֹד הַשַּׁבָּת בְּגָדִים חֲגִיגִיִּים וּנְקִיִּים.","פֶּרֶק ל״ח, הֲלָכָה ו׳","מְכִינִים אֶת הַשַּׁבָּת"],["בִּ״שְׁנַיִם מִקְרָא וְאֶחָד תַּרְגּוּם״ — כַּמָּה פְּעָמִים קוֹרְאִים כָּל פָּסוּק מֵהַפָּרָשָׁה?",["פַּעֲמַיִם","פַּעַם אַחַת","שָׁלוֹשׁ פְּעָמִים"],0,"כַּהֲכָנָה רוּחָנִית לְשַׁבָּת קוֹרְאִים אֶת פְּסוּקֵי הַפָּרָשָׁה פַּעֲמַיִם, וְאֶת תַּרְגּוּם אוּנְקְלוֹס פַּעַם אַחַת — גַּם מִי שֶׁשּׁוֹמֵעַ קְרִיאַת הַתּוֹרָה בְּשַׁבָּת.","פֶּרֶק ל״ט, הֲלָכָה א׳-ב׳","מְכִינִים אֶת הַשַּׁבָּת"],["מֵאֵיזוֹ תְּפִלָּה אֶפְשָׁר לְהַתְחִיל לִקְרֹא שְׁנַיִם מִקְרָא שֶׁל הַפָּרָשָׁה הַבָּאָה?",["מִנְחָה שֶׁל שַׁבָּת","שַׁחֲרִית שֶׁל רֹאשׁ חֹדֶשׁ","עַרְבִית שֶׁל לֵיל שַׁבָּת"],0,"בִּתְפִלַּת מִנְחָה שֶׁל שַׁבָּת כְּבָר מַתְחִילִים לִקְרֹא בְּפָרָשַׁת הַשָּׁבוּעַ הַבָּא, וְלָכֵן מִשָּׁם אֶפְשָׁר לְהַתְחִיל.","פֶּרֶק ל״ט, הֲלָכָה ג׳","מְכִינִים אֶת הַשַּׁבָּת"],["לְדַעַת חַכְמֵי הַקַּבָּלָה, אֵיךְ קוֹרְאִים שְׁנַיִם מִקְרָא בְּיוֹם שִׁשִּׁי אַחֲרֵי שַׁחֲרִית?",["בַּמִּטָּה לִפְנֵי הַשֵּׁנָה","בַּדֶּרֶךְ לְבֵית הַסֵּפֶר","עֲטוּפִים בְּטַלִּית וּבִתְפִלִּין"],2,"לְדַעַת חַכְמֵי הַקַּבָּלָה קוֹרְאִים בְּיוֹם שִׁשִּׁי אַחֲרֵי שַׁחֲרִית, עֲטוּפִים בְּטַלִּית וּמְעֻטָּרִים בִּתְפִלִּין. וְיֵשׁ נוֹהֲגִים לְחַלֵּק אֶת הַלִּמּוּד לְכָל יְמוֹת הַשָּׁבוּעַ.","פֶּרֶק ל״ט, הֲלָכָה ד׳","מְכִינִים אֶת הַשַּׁבָּת"],["עַד מָתַי מִצְוָה מִן הַמֻּבְחָר לְהַשְׁלִים שְׁנַיִם מִקְרָא וְאֶחָד תַּרְגּוּם?",["עַד חֲנֻכָּה","לִפְנֵי סְעוּדַת הַבֹּקֶר בְּשַׁבָּת","עַד פּוּרִים"],1,"מִצְוָה מִן הַמֻּבְחָר לְסַיֵּם לִפְנֵי סְעוּדַת הַבֹּקֶר בְּשַׁבָּת. אִם עָבַר — עַד יוֹם שְׁלִישִׁי, וְאִם גַּם זֶה עָבַר — עַד שְׁמִינִי עֲצֶרֶת.","פֶּרֶק ל״ט, הֲלָכָה ה׳","מְכִינִים אֶת הַשַּׁבָּת"],["בְּמָה אֶפְשָׁר לְהַחְלִיף אֶת קְרִיאַת הַתַּרְגּוּם?",["בְּסִפּוּר הַרְפַּתְקָאוֹת","בְּעִתּוֹן","בְּפֵרוּשׁ רָשִׁ״י"],2,"לִמּוּד הַפָּרָשָׁה עִם פֵּרוּשׁ רָשִׁ״י נֶחְשָׁב כְּמוֹ קְרִיאַת הַתַּרְגּוּם. יְרֵא שָׁמַיִם יִקְרָא אֶת שְׁנֵיהֶם, וּמִי שֶׁאֵין לוֹ פְּנַאי — עָדִיף רָשִׁ״י.","פֶּרֶק ל״ט, הֲלָכָה ו׳-ז׳","מְכִינִים אֶת הַשַּׁבָּת"],["אֵיךְ קוֹרְאִים אֶת פְּסוּקֵי הַתּוֹרָה בִּשְׁנַיִם מִקְרָא?",["בִּטְעָמִים, וּמִתְבּוֹנְנִים בַּמִּצְווֹת","בִּמְהִירוּת בְּלִי לַחְשֹׁב","בְּלִי לְהָבִין מִלָּה"],0,"יֵשׁ לְהַקְפִּיד לִקְרֹא בִּטְעָמִים, וּלְהִתְבּוֹנֵן בַּמִּצְווֹת, בַּמּוּסָר וּבַמִּדּוֹת הַטּוֹבוֹת — זוֹ מַטְּרַת הַקְּרִיאָה.","פֶּרֶק ל״ט, הֲלָכָה ח׳-ט׳","מְכִינִים אֶת הַשַּׁבָּת"],["לָמָּה חוֹבָה לְהַדְלִיק נֵר לִפְנֵי כְּנִיסַת הַשַּׁבָּת?",["כְּדֵי לְהַרְבּוֹת שְׁלוֹם בַּיִת וְעֹנֶג שַׁבָּת","כְּדֵי לְחַמֵּם אֶת הַבַּיִת","כְּדֵי לְקַשֵּׁט אֶת הַחַלּוֹן"],0,"אִם הַבַּיִת חָשׁוּךְ, בְּנֵי הַבַּיִת עֲלוּלִים לְהִתָּקֵל זֶה בָּזֶה וְלָבוֹא לִידֵי צַעַר וּמְרִיבָה. הַנֵּר מַרְבֶּה שְׁלוֹם בַּיִת וְעֹנֶג שַׁבָּת.","פֶּרֶק מ׳, הֲלָכָה א׳","נֵרוֹת שַׁבָּת"],["בַּבַּיִת יֵשׁ אוֹר חַשְׁמַל חָזָק. מָה הַדִּין לְגַבֵּי נֵרוֹת שַׁבָּת?",["אֵין צֹרֶךְ, יֵשׁ מְנוֹרוֹת חַשְׁמַל","גַּם הַיּוֹם חוֹבָה לְהַדְלִיק נֵרוֹת שַׁבָּת","מַדְלִיקִים רַק פָּנָס קָטָן"],1,"אַף בְּיָמֵינוּ שֶׁהַחַשְׁמַל מֵאִיר אֶת כָּל הַבַּיִת – חוֹבָה לְהַדְלִיק נֵרוֹת שַׁבָּת, וּבְיָמֵינוּ נִכָּר בְּיוֹתֵר שֶׁהֵם לִכְבוֹד הַשַּׁבָּת.","פֶּרֶק מ׳, הֲלָכָה ב׳","נֵרוֹת שַׁבָּת"],["כַּמָּה נֵרוֹת נָהֲגוּ לְהַדְלִיק, כְּנֶגֶד ״זָכוֹר״ וְ״שָׁמוֹר״?",["נֵר אֶחָד","שְׁנֵי נֵרוֹת","שְׁלֹשָׁה נֵרוֹת"],1,"נָהֲגוּ לְהַדְלִיק שְׁנֵי נֵרוֹת – אֶחָד כְּנֶגֶד ״זָכוֹר״ וְאֶחָד כְּנֶגֶד ״שָׁמוֹר״, כְּמוֹ הַזָּקֵן עִם שְׁנֵי עַנְפֵי הַהֲדַס.","פֶּרֶק מ׳, הֲלָכָה ג׳","נֵרוֹת שַׁבָּת"],["יֵשׁ נוֹהֲגוֹת לְהַדְלִיק שִׁבְעָה נֵרוֹת. כְּנֶגֶד מָה?",["שִׁבְעַת הַמִּינִים","שִׁבְעָה רוֹעִים","שִׁבְעַת יְמֵי הַשָּׁבוּעַ"],2,"יֵשׁ נוֹהֲגוֹת לְהַדְלִיק שִׁבְעָה נֵרוֹת כְּנֶגֶד שִׁבְעַת יְמֵי הַשָּׁבוּעַ, אוֹ עֲשָׂרָה כְּנֶגֶד עֲשֶׂרֶת הַדִּבְּרוֹת.","פֶּרֶק מ׳, הֲלָכָה ד׳","נֵרוֹת שַׁבָּת"],["מִי מְצֻוֶּה יוֹתֵר עַל הַדְלָקַת הַנֵּר בְּשַׁבָּת?",["הַנָּשִׁים – כִּי הֵן מְצוּיוֹת בַּבַּיִת","רַק הַיְּלָדִים","אַף אֶחָד אֵינוֹ חַיָּב"],0,"גַּם אֲנָשִׁים וְגַם נָשִׁים חַיָּבִים, אֲבָל הַנָּשִׁים מְצֻוּוֹת יוֹתֵר, כִּי הֵן מְצוּיוֹת בַּבַּיִת וְעוֹסְקוֹת בִּמְלֶאכֶת הַבַּיִת, וְהֵן מוֹצִיאוֹת אֶת כָּל בְּנֵי הַבַּיִת.","פֶּרֶק מ׳, הֲלָכָה ה׳","נֵרוֹת שַׁבָּת"],["הָאִשָּׁה חוֹלָה וְאֵינָהּ יְכוֹלָה לְהַדְלִיק. מָה עוֹשִׂים?",["לֹא מַדְלִיקִים נֵרוֹת","הַבַּעַל מַדְלִיק בִּבְרָכָה","הַבַּעַל מַדְלִיק בְּלִי בְּרָכָה"],1,"אִם הָאִשָּׁה חוֹלָה – יַדְלִיק בַּעֲלָהּ בִּבְרָכָה, וְכָל שֶׁכֵּן אִם אֵינָהּ בַּבַּיִת בְּשַׁבָּת.","פֶּרֶק מ׳, הֲלָכָה ו׳","נֵרוֹת שַׁבָּת"],["נָשִׁים שֶׁמַּדְלִיקוֹת קֹדֶם וּמְבָרְכוֹת אַחַר כָּךְ – מָה הֵן עוֹשׂוֹת לִפְנֵי הַבְּרָכָה?",["שָׁרוֹת שִׁיר שַׁבָּת","מְכַבּוֹת וּמַדְלִיקוֹת שׁוּב","מְכַסּוֹת אֶת הָעֵינַיִם וּמְבָרְכוֹת"],2,"כְּדֵי שֶׁהַבְּרָכָה תֵּחָשֵׁב ״עוֹבֵר לַעֲשִׂיָּתָן״, הֵן שָׂמוֹת יָדַיִם לִפְנֵי הַנֵּרוֹת אוֹ מְכַסּוֹת אֶת הָעֵינַיִם, מְבָרְכוֹת, וְרַק אַחַר כָּךְ מַבִּיטוֹת בַּנֵּרוֹת.","פֶּרֶק מ׳, הֲלָכָה ז׳","נֵרוֹת שַׁבָּת"],["אִישׁ שֶׁמַּדְלִיק נֵרוֹת שַׁבָּת – בְּאֵיזֶה סֵדֶר?",["מְבָרֵךְ וְאַחַר כָּךְ מַדְלִיק","מַדְלִיק וְאַחַר כָּךְ מְבָרֵךְ","מַדְלִיק בְּלִי בְּרָכָה"],0,"כַּאֲשֶׁר אִישׁ מַדְלִיק – לְכָל הַדֵּעוֹת יְבָרֵךְ תְּחִלָּה וְרַק אַחַר כָּךְ יַדְלִיק.","פֶּרֶק מ׳, הֲלָכָה ח׳","נֵרוֹת שַׁבָּת"],["אִישׁ הִדְלִיק נֵרוֹת שַׁבָּת לִפְנֵי מִנְחָה. הַאִם מֻתָּר לוֹ לַעֲשׂוֹת מְלָאכָה?",["אָסוּר לוֹ בִּמְלָאכָה","יָכוֹל לַעֲשׂוֹת מְלָאכָה","חַיָּב לָלֶכֶת לִישֹׁן"],1,"הָאֲנָשִׁים מְקַבְּלִים שַׁבָּת בְּדִבּוּר אַחֲרֵי מִנְחָה, וְלָכֵן בַּהַדְלָקָה אֵינוֹ מְקַבֵּל שַׁבָּת וְיָכוֹל לַעֲשׂוֹת מְלָאכָה. טוֹב שֶׁיַּתְנֶה זֹאת בְּפֵרוּשׁ.","פֶּרֶק מ׳, הֲלָכָה ט׳","נֵרוֹת שַׁבָּת"],["מָתַי מַתְחִיל זְמַן אִסּוּר הַמְּלָאכָה בְּשַׁבָּת?",["בִּשְׁקִיעַת הַחַמָּה בְּיוֹם שִׁשִּׁי","בַּחֲצוֹת הַיּוֹם בְּיוֹם שִׁשִּׁי","בְּצֵאת הַכּוֹכָבִים בְּמוֹצָאֵי שַׁבָּת"],0,"אִסּוּר הַמְּלָאכָה מַתְחִיל בִּשְׁקִיעַת הַחַמָּה בְּיוֹם שִׁשִּׁי וּמִסְתַּיֵּם בְּצֵאת הַכּוֹכָבִים בְּמוֹצָאֵי שַׁבָּת. וּמִצְוָה לְהוֹסִיף וּלְקַבֵּל אֶת הַשַּׁבָּת עוֹד לִפְנֵי הַשְּׁקִיעָה.","פֶּרֶק מ״א, הֲלָכָה א׳","קַבָּלַת שַׁבָּת"],["מַדּוּעַ בְּנֵי הָאָדָם צְרִיכִים לִשְׁבּוֹת מִמְּלָאכָה לִפְנֵי הַשְּׁקִיעָה?",["כְּדֵי לָנוּחַ יוֹתֵר זְמַן","כִּי הֵם עֲלוּלִים לִטְעוֹת בַּזְּמַן","כִּי הַשֶּׁמֶשׁ שׁוֹקַעַת מֻקְדָּם"],1,"הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹדֵעַ עִתָּיו וּרְגָעָיו, אֲבָל בְּנֵי הָאָדָם עֲלוּלִים לִטְעוֹת בַּזְּמַן הַמְּדֻיָּק שֶׁל כְּנִיסַת הַשַּׁבָּת, וְלָכֵן מוֹסִיפִים מִן הַחֹל עַל הַקֹּדֶשׁ.","פֶּרֶק מ״א, הֲלָכָה ב׳","קַבָּלַת שַׁבָּת"],["רַבִּי יַנַּאי הָיָה לוֹבֵשׁ בִּגְדֵי שַׁבָּת. מָה הָיָה אוֹמֵר?",["״שַׁבָּת שָׁלוֹם וּמְבֹרָךְ״","״שָׁלוֹם עֲלֵיכֶם״","״בּוֹאִי כַּלָּה, בּוֹאִי כַּלָּה״"],2,"רַבִּי יַנַּאי הָיָה לוֹבֵשׁ אֶת בִּגְדֵי הַשַּׁבָּת וְאוֹמֵר ״בּוֹאִי כַּלָּה, בּוֹאִי כַּלָּה״, כִּי מִצְוָה לְהַקְדִּים וּלְקַבֵּל אֶת הַשַּׁבָּת לִכְבוֹדָהּ.","פֶּרֶק מ״א, הֲלָכָה ג׳","קַבָּלַת שַׁבָּת"],["כַּמָּה זְמַן לִפְנֵי הַשְּׁקִיעָה מַדְלִיקִים נֵרוֹת שַׁבָּת בִּירוּשָׁלַיִם?",["כְּעֶשְׂרִים דַּקּוֹת","כְּאַרְבָּעִים דַּקּוֹת","כְּשָׁעָה שְׁלֵמָה"],1,"בְּרֹב הַמְּקוֹמוֹת בָּאָרֶץ מַדְלִיקִים כְּעֶשְׂרִים דַּקּוֹת לִפְנֵי הַשְּׁקִיעָה, וּבִירוּשָׁלַיִם כְּאַרְבָּעִים דַּקּוֹת. הַנָּשִׁים בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים וּבְחֵלֶק מִקְּהִלּוֹת הַסְּפָרַדִּים מְקַבְּלוֹת אֶת הַשַּׁבָּת בְּהַדְלָקָה זוֹ.","פֶּרֶק מ״א, הֲלָכָה ד׳","קַבָּלַת שַׁבָּת"],["אֵיךְ גְּבָרִים מְקַבְּלִים עַל עַצְמָם אֶת הַשַּׁבָּת?",["בַּאֲמִירָה בַּפֶּה","בְּהַדְלָקַת נֵרוֹת","בִּתְקִיעַת שׁוֹפָר"],0,"גְּבָרִים מְקַיְּמִים אֶת הַמִּצְוָה בַּאֲמִירָה בַּפֶּה: ״הֲרֵינִי מְקַבֵּל עַל עַצְמִי קְדֻשַּׁת הַשַּׁבָּת״ אוֹ ״בּוֹאִי כַּלָּה״, אַחֲרֵי שֶׁסִּיְּמוּ מִנְחָה כַּמָּה דַּקּוֹת לִפְנֵי הַשְּׁקִיעָה.","פֶּרֶק מ״א, הֲלָכָה ה׳","קַבָּלַת שַׁבָּת"],["מֵאֵיזֶה זְמַן אֶפְשָׁר לְהַקְדִּים וּלְקַבֵּל אֶת הַשַּׁבָּת?",["מִן הַבֹּקֶר","מֵחֲצוֹת הַלַּיְלָה","מִפְּלַג הַמִּנְחָה"],2,"הָרוֹצִים לְהַקְדִּים יְכוֹלִים לְקַבֵּל אֶת הַשַּׁבָּת הָחֵל מִפְּלַג הַמִּנְחָה, שָׁעָה וָרֶבַע זְמַנִּיּוֹת לִפְנֵי הַשְּׁקִיעָה.","פֶּרֶק מ״א, הֲלָכָה ו׳","קַבָּלַת שַׁבָּת"],["מִי חִבֵּר אֶת הַפִּיּוּט ״לְכָה דוֹדִי״?",["רַבִּי חֲנִינָא","רַבִּי שְׁלֹמֹה אֶלְקָבֵץ","רַבִּי יַנַּאי"],1,"לִפְנֵי יוֹתֵר מֵאַרְבַּע מֵאוֹת שָׁנָה הֵחֵלּוּ הַמְּקֻבָּלִים בִּצְפַת לוֹמַר מִזְמוֹרֵי תְּהִלִּים לִפְנֵי הַשַּׁבָּת, וְאָז חִבֵּר רַבִּי שְׁלֹמֹה אֶלְקָבֵץ אֶת ״לְכָה דוֹדִי״.","פֶּרֶק מ״א, הֲלָכָה ז׳","קַבָּלַת שַׁבָּת"],["לְאֵיזֶה צַד הוֹפְכִים אֶת הַפָּנִים בַּבַּיִת הָאַחֲרוֹן שֶׁל ״לְכָה דוֹדִי״?",["לְצַד מִזְרָח","לְצַד צָפוֹן","לְצַד מַעֲרָב"],2,"הָאֲרִ״י קִבֵּל אֶת הַשַּׁבָּת בַּשָּׂדֶה כְּשֶׁהוּא פּוֹנֶה לְמַעֲרָב, שֶׁשָּׁם הַחַמָּה שׁוֹקַעַת וּמְבַשֶּׂרֶת עַל בּוֹא הַשַּׁבָּת.","פֶּרֶק מ״א, הֲלָכָה ח׳","קַבָּלַת שַׁבָּת"],["מָה אוֹמְרִים הַנּוֹהֲגִים שֶׁלֹּא לוֹמַר אֶת הַפֶּרֶק ״בַּמֶּה מַדְלִיקִין״?",["״כְּגַוְנָא״","״אֵשֶׁת חַיִל״","״אֲדוֹן עוֹלָם״"],0,"״בַּמֶּה מַדְלִיקִין״ הוּא הַפֶּרֶק הַשֵּׁנִי שֶׁל מַסֶּכֶת שַׁבָּת. יֵשׁ אוֹמְרִים אוֹתוֹ בְּתוֹךְ קַבָּלַת שַׁבָּת, יֵשׁ אַחֲרֶיהָ, וְיֵשׁ שֶׁאֵינָם אוֹמְרִים אוֹתוֹ כְּלָל אֶלָּא אוֹמְרִים ״כְּגַוְנָא״.","פֶּרֶק מ״א, הֲלָכוֹת ט׳-י׳","קַבָּלַת שַׁבָּת"],["בִּכְנִיסַת הַשַּׁבָּת זוֹכְרִים אוֹתָהּ בְּקִדּוּשׁ. וּבִיצִיאַת הַשַּׁבָּת – בְּמָה זוֹכְרִים אוֹתָהּ?",["בְּהַדְלָקַת נֵרוֹת","בְּהַבְדָּלָה","בִּתְקִיעַת שׁוֹפָר"],1,"מִצְוָה מִן הַתּוֹרָה לִזְכֹּר אֶת הַשַּׁבָּת בְּדִבּוּר: בִּכְנִיסָתָהּ – בְּקִדּוּשׁ, וּבִיצִיאָתָהּ – בְּהַבְדָּלָה.","פֶּרֶק מ״ב, הֲלָכָה א׳","קִדּוּשׁ עַל הַיַּיִן"],["עַל מָה תִּקְּנוּ חֲכָמִים לְקַדֵּשׁ לְכַתְּחִלָּה?",["עַל הַיַּיִן","עַל כּוֹס מַיִם","עַל כּוֹס חָלָב"],0,"חֲכָמִים תִּקְּנוּ לְקַדֵּשׁ לְכַתְּחִלָּה דַּוְקָא עַל הַיַּיִן, גַּם אִם הוּא יָקָר – בַּלַּיְלָה וְגַם בַּיּוֹם.","פֶּרֶק מ״ב, הֲלָכָה ב׳","קִדּוּשׁ עַל הַיַּיִן"],["מִי חַיָּב בְּקִדּוּשׁ מִן הַתּוֹרָה?",["רַק גְּבָרִים","רַק יְלָדִים","גְּבָרִים וְגַם נָשִׁים"],2,"״זָכוֹר וְשָׁמוֹר בְּדִבּוּר אֶחָד נֶאֶמְרוּ״ – לָכֵן נָשִׁים חַיָּבוֹת בְּקִדּוּשׁ מִן הַתּוֹרָה, וְהֵן אַף יְכוֹלוֹת לְהוֹצִיא אֶת הַגְּבָרִים יְדֵי חוֹבָה.","פֶּרֶק מ״ב, הֲלָכוֹת ג׳-ד׳","קִדּוּשׁ עַל הַיַּיִן"],["חָזַרְנוּ מִבֵּית הַכְּנֶסֶת בְּלֵיל שַׁבָּת. מָה עוֹשִׂים?",["יוֹצְאִים לְטַיֵּל קְצָת","מְמַהֲרִים לְקַדֵּשׁ וְלֶאֱכֹל","מְחַכִּים שָׁעָה אֲרֻכָּה"],1,"יֵשׁ לְמַהֵר לְקַדֵּשׁ וְלֶאֱכֹל מִיָּד כַּאֲשֶׁר חוֹזְרִים מִבֵּית הַכְּנֶסֶת, לְלֹא עִכּוּבִים.","פֶּרֶק מ״ב, הֲלָכָה ה׳","קִדּוּשׁ עַל הַיַּיִן"],["כַּמָּה יַיִן צְרִיכָה כּוֹס הַקִּדּוּשׁ לְהָכִיל לְפָחוֹת?",["טִפָּה אַחַת","רְבִיעִית","בַּקְבּוּק שָׁלֵם"],1,"הַכּוֹס צְרִיכָה לְהָכִיל לְפָחוֹת רְבִיעִית (כַּחֲצִי כּוֹס חַד פְּעָמִית). הַמְּקַדֵּשׁ שׁוֹתֶה לְכַתְּחִלָּה מְלוֹא לֻגְמָיו, וּמִן הַמֻּבְחָר – רְבִיעִית שְׁלֵמָה.","פֶּרֶק מ״ב, הֲלָכוֹת ו׳-ז׳","קִדּוּשׁ עַל הַיַּיִן"],["הַמְּקַדֵּשׁ שָׁתָה מְעַט, אֲבָל אֶחָד הַמְּסֻבִּים שָׁתָה מְלוֹא לֻגְמָיו. מִי יָצָא?",["כֻּלָּם יָצְאוּ","אַף אֶחָד לֹא יָצָא","רַק הַמְּקַדֵּשׁ"],0,"אִם אֶחָד הַמְּסֻבִּים שָׁתָה מְלוֹא לֻגְמָיו – כֻּלָּם יָצְאוּ. וַאֲפִלּוּ אִם כֻּלָּם שָׁתוּ מְעַט וּבְסַךְ הַכֹּל שָׁתוּ מְלוֹא לֻגְמָיו – יָצְאוּ בְּדִיעֲבַד.","פֶּרֶק מ״ב, הֲלָכוֹת ח׳-ט׳","קִדּוּשׁ עַל הַיַּיִן"],["הַמְּקַדֵּשׁ שָׁתָה מְלוֹא לֻגְמָיו. מָה רָאוּי שֶׁיַּעֲשׂוּ שְׁאָר הַמְּסֻבִּים?",["לִשְׁפֹּךְ אֶת הַיַּיִן","לְחַכּוֹת בְּשֶׁקֶט","לִטְעֹם מֵהַכּוֹס"],2,"רָאוּי שֶׁכָּל הַמְּסֻבִּים יִטְעֲמוּ מִכּוֹס הַקִּדּוּשׁ, מִשּׁוּם חִבּוּב מִצְוָה.","פֶּרֶק מ״ב, הֲלָכָה י׳","קִדּוּשׁ עַל הַיַּיִן"],["מְקַדְּשִׁים בַּבֹּקֶר בְּבֵית הַכְּנֶסֶת, וְהַסְּעוּדָה תִּהְיֶה מְאֻחָר יוֹתֵר. מָה אוֹכְלִים שָׁם?",["כַּזַּיִת עוּגָה (מְזוֹנוֹת)","שׁוּם דָּבָר","רַק סֻכָּרִיָּה"],0,"הַנּוֹהֲגִים כָּךְ יֹאכְלוּ בַּמָּקוֹם לְפָחוֹת כַּזַּיִת מְזוֹנוֹת, וְאִם אִי אֶפְשָׁר – יִשְׁתּוּ לְפָחוֹת רְבִיעִית יַיִן.","פֶּרֶק מ״ב, הֲלָכָה י״א","קִדּוּשׁ עַל הַיַּיִן"],["שָׁתִינוּ מִיַּיִן הַקִּדּוּשׁ. הַאִם צָרִיךְ לְבָרֵךְ שׁוּב עַל הַמִּיץ שֶׁעַל הַשֻּׁלְחָן?",["כֵּן, תָּמִיד","רַק אִם הוּא קַר","לֹא, בִּרְכַּת הַיַּיִן פּוֹטֶרֶת"],2,"בִּרְכַּת הַיַּיִן שֶׁל הַקִּדּוּשׁ פּוֹטֶרֶת אֶת הַמַּשְׁקָאוֹת שֶׁעַל הַשֻּׁלְחָן וְהָרְגִילִים, בִּתְנַאי שֶׁשּׁוֹתִים מֵהַיַּיִן.","פֶּרֶק מ״ב, הֲלָכָה י״ב","קִדּוּשׁ עַל הַיַּיִן"],["אֵין יַיִן בַּבַּיִת. עַל מָה מְקַדְּשִׁים בְּלֵיל שַׁבָּת?",["עַל כּוֹס תֵּה","עַל הַפַּת","עַל עוּגִיּוֹת"],1,"מִי שֶׁאֵין לוֹ יַיִן מְקַדֵּשׁ בַּלַּיְלָה עַל הַפַּת, וּבַבֹּקֶר עַל חֲמַר מְדִינָה – מַשְׁקֶה חָשׁוּב שֶׁמְּכַבְּדִים בּוֹ אוֹרְחִים.","פֶּרֶק מ״ב, הֲלָכוֹת י״ג-י״ד","קִדּוּשׁ עַל הַיַּיִן"],["כַּמָּה סְעוּדוֹת חוֹבָה לֶאֱכֹל בְּשַׁבָּת?",["שְׁתֵּי סְעוּדוֹת","שָׁלוֹשׁ סְעוּדוֹת","אַרְבַּע סְעוּדוֹת"],1,"חוֹבָה לֶאֱכֹל שָׁלוֹשׁ סְעוּדוֹת בְּשַׁבָּת: בַּלַּיְלָה כְּנֶגֶד שַׁבַּת בְּרֵאשִׁית, בַּבֹּקֶר כְּנֶגֶד הַשַּׁבָּת שֶׁבָּהּ נִתְּנָה הַתּוֹרָה, וּבַצָּהֳרַיִם כְּנֶגֶד הַשַּׁבָּת שֶׁלֶּעָתִיד לָבֹא.","פֶּרֶק מ״ג, הֲלָכָה א׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מָה רָאוּי לַעֲשׂוֹת בִּסְעוּדַת שַׁבָּת?",["לָשִׁיר זְמִירוֹת וְלוֹמַר דִּבְרֵי תּוֹרָה","לֶאֱכֹל מַהֵר בְּלִי לְדַבֵּר","לֶאֱכֹל כָּל אֶחָד בְּחֶדֶר אַחֵר"],0,"סְעוּדוֹת הַשַּׁבָּת צְרִיכוֹת לִהְיוֹת בְּנַחַת וּבְשִׂמְחָה, וְיֵשׁ לָשִׁיר זְמִירוֹת שַׁבָּת וְשִׁירֵי קֹדֶשׁ וְלוֹמַר דִּבְרֵי תּוֹרָה מִפָּרָשַׁת הַשָּׁבוּעַ.","פֶּרֶק מ״ג, הֲלָכָה ב׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["עַל מָה מְבָרְכִים ״הַמּוֹצִיא״ בִּסְעוּדוֹת הַשַּׁבָּת?",["עַל פְּרוּסַת לֶחֶם אַחַת","עַל שְׁתֵּי כִּכָּרוֹת שְׁלֵמוֹת","עַל עוּגָה מְתוּקָה"],1,"בִּשְׁתֵּי הַסְּעוּדוֹת הָרִאשׁוֹנוֹת מְבָרְכִים עַל ״לֶחֶם מִשְׁנֶה״ – שְׁתֵּי כִּכָּרוֹת שְׁלֵמוֹת. גַּם בַּסְּעוּדָה הַשְּׁלִישִׁית יֵשׁ לְהַחְמִיר וּלְבָרֵךְ עַל לֶחֶם מִשְׁנֶה, וְיֵשׁ מְקִלִּים לְבָרֵךְ עַל לֶחֶם אֶחָד שָׁלֵם.","פֶּרֶק מ״ג, הֲלָכוֹת ג׳-ד׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מִי מֵאֵלֶּה פָּטוּר מִשָּׁלוֹשׁ סְעוּדוֹת?",["נָשִׁים","עָנִי שֶׁמִּתְפַּרְנֵס מֵהַצְּדָקָה","חוֹלֶה שֶׁקָּשֶׁה לוֹ לֶאֱכֹל"],2,"גַּם נָשִׁים חַיָּבוֹת לֶאֱכֹל שָׁלוֹשׁ סְעוּדוֹת, וַאֲפִלּוּ עָנִי שֶׁמִּתְפַּרְנֵס מֵהַצְּדָקָה חַיָּב. רַק חוֹלֶה שֶׁקָּשֶׁה לוֹ לֶאֱכֹל – פָּטוּר.","פֶּרֶק מ״ג, הֲלָכוֹת ה׳-ז׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מָה יֵשׁ לֶאֱכֹל בְּכָל שָׁלוֹשׁ סְעוּדוֹת הַשַּׁבָּת?",["פֵּרוֹת","לֶחֶם","עוּגִיּוֹת"],1,"בִּסְעוּדַת הָעֶרֶב וְהַבֹּקֶר חַיָּבִים לֶאֱכֹל לֶחֶם, רָאוּי כַּבֵּיצָה וּלְפָחוֹת כַּזַּיִת. גַּם בַּסְּעוּדָה הַשְּׁלִישִׁית יֵשׁ לֶאֱכֹל לֶחֶם, וְיֵשׁ מְקִלִּים לְמִי שֶׁקָּשֶׁה לוֹ לֶאֱכֹל ״מְזוֹנוֹת״ אוֹ לְפָחוֹת פֵּרוֹת.","פֶּרֶק מ״ג, הֲלָכוֹת ח׳-ט׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מָה נוֹהֲגִים לַעֲשׂוֹת בִּתְפִלַּת שַׁבָּת?",["לְהִתְפַּלֵּל בִּמְהִירוּת רַבָּה","לְדַלֵּג עַל הַזְּמִירוֹת","לְהַאֲרִיךְ וּלְהַנְעִים בִּזְמִירוֹת"],2,"בְּשַׁבָּת נוֹהֲגִים לְהַאֲרִיךְ וּלְהַנְעִים בִּזְמִירוֹת, כִּי כָּךְ מִתְעוֹרֶרֶת הַנֶּפֶשׁ לִתְפִלָּה. אֲבָל צָרִיךְ לְהַקְפִּיד שֶׁלֹּא יַעֲבֹר זְמַן קְרִיאַת שְׁמַע.","פֶּרֶק מ״ד, הֲלָכוֹת א׳-ב׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["אֵיזוֹ תְּפִלָּה מִתְפַּלְּלִים מִיָּד אַחֲרֵי שַׁחֲרִית בְּשַׁבָּת?",["מִנְחָה","מוּסָף","עַרְבִית"],1,"זְמַן מוּסָף מִיָּד אַחַר שַׁחֲרִית, וְיֵשׁ לְהִתְפַּלֵּל אוֹתָהּ עַד סוֹף שֶׁבַע שָׁעוֹת. וּלְמַעֲשֶׂה נָהֲגוּ לְהִתְפַּלֵּל תָּמִיד מוּסָף לִפְנֵי מִנְחָה.","פֶּרֶק מ״ד, הֲלָכוֹת ג׳, ח׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["בִּתְפִלַּת מוּסָף יֵשׁ חֲזָרַת הַשַּׁ״ץ. מָה עוֹד עוֹשִׂים בָּהּ הַכֹּהֲנִים?",["תּוֹקְעִים בְּשׁוֹפָר","נוֹשְׂאִים כַּפַּיִם","מַדְלִיקִים נֵרוֹת"],1,"גַּם בְּמוּסָף חוֹזֵר שְׁלִיחַ הַצִּבּוּר עַל הַתְּפִלָּה, וְהַכֹּהֲנִים נוֹשְׂאִים כַּפַּיִם – מְבָרְכִים אֶת בִּרְכַּת הַכֹּהֲנִים.","פֶּרֶק מ״ד, הֲלָכוֹת ד׳-ה׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["הַאִם נָשִׁים חַיָּבוֹת בִּתְפִלַּת מוּסָף?",["חַיָּבוֹת כְּמוֹ הָאֲנָשִׁים","פְּטוּרוֹת, אֲבָל רַשָּׁאִיּוֹת לְהִתְפַּלֵּל","אָסוּר לָהֶן לְהִתְפַּלֵּל"],1,"נָשִׁים פְּטוּרוֹת מִתְּפִלַּת מוּסָף, אַךְ נָשִׁים שֶׁרוֹצוֹת לְהִתְפַּלֵּל מוּסָף רַשָּׁאִיּוֹת לַעֲשׂוֹת זֹאת.","פֶּרֶק מ״ד, הֲלָכָה ו׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מֵעִקַּר הַדִּין, מָה מֻתָּר לַעֲשׂוֹת לִפְנֵי תְּפִלַּת מוּסָף?",["לְקַדֵּשׁ וְלֶאֱכֹל מְעַט","לֶאֱכֹל סְעוּדָה גְּדוֹלָה","לְדַלֵּג עַל מוּסָף"],0,"מֵעִקַּר הַדִּין מֻתָּר לְקַדֵּשׁ וְלֶאֱכֹל מְעַט לִפְנֵי מוּסָף, וְכָךְ נוֹהֲגִים בִּקְהִלּוֹת רַבּוֹת בְּיָמִים שֶׁהַתְּפִלָּה אֲרֻכָּה, אֲבָל רַבִּים נִמְנָעִים מִכָּךְ.","פֶּרֶק מ״ד, הֲלָכָה ז׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["בְּאֵילוּ יָמִים תִּקֵּן מֹשֶׁה רַבֵּנוּ לִקְרֹא בַּתּוֹרָה בְּשַׁחֲרִית?",["רַק בְּשַׁבָּת","בְּשַׁבָּת, בְּיוֹם שֵׁנִי וּבְיוֹם חֲמִישִׁי","רַק בְּיוֹם רִאשׁוֹן"],1,"מֹשֶׁה רַבֵּנוּ תִּקֵּן לִקְרֹא בְּשַׁבָּת, בְּשֵׁנִי וּבַחֲמִישִׁי, כְּדֵי שֶׁלֹּא יַעַבְרוּ שְׁלוֹשָׁה יָמִים בְּלֹא תּוֹרָה. עֶזְרָא הוֹסִיף קְרִיאָה בְּמִנְחָה שֶׁל שַׁבָּת.","פֶּרֶק מ״ה, הֲלָכָה א׳","קְרִיאַת הַתּוֹרָה"],["מִי עוֹלֶה רִאשׁוֹן לַתּוֹרָה?",["יִשְׂרָאֵל","לֵוִי","כֹּהֵן"],2,"הָרִאשׁוֹן הוּא כֹּהֵן, אַחֲרָיו לֵוִי וְאַחֲרָיו יִשְׂרָאֵל, וַאֲפִלּוּ לִפְנֵי תַּלְמִיד חָכָם גָּדוֹל.","פֶּרֶק מ״ה, הֲלָכָה ב׳","קְרִיאַת הַתּוֹרָה"],["אֵין כֹּהֵן בְּבֵית הַכְּנֶסֶת. מִי עוֹלֶה בִּמְקוֹמוֹ?",["יִשְׂרָאֵל אוֹ לֵוִי, וּמַכְרִיזִים ״בִּמְקוֹם כֹּהֵן״","אַף אֶחָד לֹא עוֹלֶה","מְבַטְּלִים אֶת הַקְּרִיאָה"],0,"יִשְׂרָאֵל אוֹ לֵוִי עוֹלֶה, וּמַכְרִיזִים ״בִּמְקוֹם כֹּהֵן״ כְּדֵי שֶׁלֹּא יִטְעוּ לַחְשֹׁב שֶׁהוּא כֹּהֵן.","פֶּרֶק מ״ה, הֲלָכָה ג׳","קְרִיאַת הַתּוֹרָה"],["אֵין לֵוִי בְּבֵית הַכְּנֶסֶת. מִי עוֹלֶה בִּמְקוֹם הַלֵּוִי?",["כֹּהֵן אַחֵר","יֶלֶד קָטָן","הַכֹּהֵן שֶׁעָלָה רִאשׁוֹן"],2,"הַכֹּהֵן שֶׁעָלָה רִאשׁוֹן עוֹלֶה שׁוּב, וְלֹא כֹּהֵן אַחֵר, כְּדֵי שֶׁלֹּא יַחְשְׁבוּ שֶׁהַכֹּהֵן הָרִאשׁוֹן פָּגוּם.","פֶּרֶק מ״ה, הֲלָכָה ד׳","קְרִיאַת הַתּוֹרָה"],["בְּאֵיזוֹ דֶּרֶךְ הוֹלֵךְ הָעוֹלֶה אֶל הַבִּימָה?",["בַּדֶּרֶךְ הָאֲרֻכָּה","בַּדֶּרֶךְ הַקְּצָרָה בְּיוֹתֵר","מִסְּבִיב לְכָל בֵּית הַכְּנֶסֶת"],1,"הוֹלְכִים לַבִּימָה בַּדֶּרֶךְ הַקְּצָרָה וְחוֹזְרִים בַּאֲרֻכָּה. אִם הַדְּרָכִים שָׁווֹת – עוֹלִים מִיָּמִין וְיוֹרְדִים מֵהַצַּד הַשֵּׁנִי.","פֶּרֶק מ״ה, הֲלָכָה ה׳","קְרִיאַת הַתּוֹרָה"],["מָה עוֹשֶׂה הָעוֹלֶה לִפְנֵי הַבְּרָכָה (בְּסֵפֶר תּוֹרָה סְפָרַדִּי)?",["נוֹגֵעַ בַּכְּתָב בְּיָד חֲשׂוּפָה","מַבִּיט בַּמָּקוֹם וּמְכַסֶּה אֶת הַכְּתָב בְּמַפָּה","סוֹגֵר אֶת הַסֵּפֶר וְהוֹלֵךְ"],1,"הָעוֹלֶה מַבִּיט בַּמָּקוֹם (יֵשׁ נוֹגְעִים בּוֹ בַּטַּלִּית – אָסוּר בְּיָד חֲשׂוּפָה), וּמְכַסֶּה בְּמַפָּה כְּדֵי שֶׁלֹּא יַחְשְׁבוּ שֶׁהַבְּרָכוֹת כְּתוּבוֹת בַּסֵּפֶר.","פֶּרֶק מ״ה, הֲלָכוֹת ו׳-ז׳","קְרִיאַת הַתּוֹרָה"],["אֵיךְ קוֹרֵא הָעוֹלֶה בִּזְמַן שֶׁבַּעַל הַקּוֹרֵא קוֹרֵא?",["בְּלַחַשׁ, מִלָּה בְּמִלָּה","בְּצְעָקָה","הוּא לֹא קוֹרֵא כְּלָל"],0,"בַּעַל הַקּוֹרֵא קוֹרֵא בְּקוֹל רָם וְהָעוֹלֶה עִמּוֹ בְּלַחַשׁ. בֵּין עוֹלֶה לְעוֹלֶה נוֹהֲגִים לִסְגֹּר אוֹ לִגְלֹל אֶת הַסֵּפֶר.","פֶּרֶק מ״ה, הֲלָכוֹת ח׳-ט׳","קְרִיאַת הַתּוֹרָה"],["מָתַי מַגְבִּיהִים אֶת סֵפֶר הַתּוֹרָה בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים?",["לִפְנֵי הַקְּרִיאָה","בְּאֶמְצַע הַבְּרָכָה","לְאַחַר הַקְּרִיאָה"],2,"הָאַשְׁכְּנַזִּים מַגְבִּיהִים לְאַחַר הַקְּרִיאָה, וְהַסְּפָרַדִּים לִפְנֵי תְּחִלַּת הַקְּרִיאָה.","פֶּרֶק מ״ה, הֲלָכָה י׳","קְרִיאַת הַתּוֹרָה"],["מָה אָסוּר לַעֲשׂוֹת בִּזְמַן קְרִיאַת הַתּוֹרָה?",["לְהַקְשִׁיב","לְדַבֵּר אוֹ לָצֵאת מִבֵּית הַכְּנֶסֶת","לַעֲמֹד בְּשֶׁקֶט"],1,"אָסוּר לְדַבֵּר, אֲפִלּוּ בֵּין עוֹלֶה לְעוֹלֶה, וְאָסוּר לָצֵאת. בֵּין עֲלִיָּה לַעֲלִיָּה מֻתָּר לָצֵאת לְצֹרֶךְ גָּדוֹל אִם נִשְׁאָרִים עֲשָׂרָה.","פֶּרֶק מ״ה, הֲלָכוֹת י״א-י״ב","קְרִיאַת הַתּוֹרָה"],["כַּמָּה עוֹלִים לַתּוֹרָה בְּשַׁבָּת בְּשַׁחֲרִית?",["שִׁבְעָה","שְׁלוֹשָׁה","אַרְבָּעָה"],0,"בְּשַׁבָּת בְּשַׁחֲרִית שִׁבְעָה וּמַפְטִירִים. בְּשֵׁנִי וַחֲמִישִׁי שְׁלוֹשָׁה, בְּרֹאשׁ חֹדֶשׁ אַרְבָּעָה, בְּיוֹם טוֹב חֲמִשָּׁה, בְּיוֹם הַכִּפּוּרִים שִׁשָּׁה.","פֶּרֶק מ״ה, הֲלָכָה י״ג","קְרִיאַת הַתּוֹרָה"],["כְּשֶׁעוֹלִים לַתּוֹרָה שְׁלוֹשָׁה אוֹ אַרְבָּעָה עוֹלִים – מָה הַדִּין?",["מוֹסִיפִים עוֹד הַרְבֵּה עוֹלִים","אֵין מוֹסִיפִים עֲלֵיהֶם","מוֹסִיפִים רַק אֶת הַחַזָּן"],1,"כְּשֶׁעוֹלִים לַתּוֹרָה שְׁלוֹשָׁה אוֹ אַרְבָּעָה – אֵין מוֹסִיפִים עֲלֵיהֶם.","פֶּרֶק מ״ה, הֲלָכָה י״ד","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["בַּמֶּה צָרִיךְ לִהְיוֹת בָּקִי הַקּוֹרֵא בַּתּוֹרָה?",["בְּשִׁירֵי שַׁבָּת","בְּשֵׁמוֹת כָּל הַמִּתְפַּלְּלִים","בַּפַּרְשִׁיּוֹת, בָּאוֹתִיּוֹת וּבַכְּתִיב"],2,"הַקּוֹרֵא צָרִיךְ לִהְיוֹת בָּקִי בַּפַּרְשִׁיּוֹת פְּתוּחוֹת וּסְתוּמוֹת, בְּצוּרַת הָאוֹתִיּוֹת וּבַכְּתִיב הַנָּכוֹן, וְאָסוּר לוֹ לִקְרֹא אֲפִלּוּ אוֹת אַחַת שֶׁלֹּא מִן הַכְּתָב.","פֶּרֶק מ״ה, הֲלָכוֹת ט״ו-ט״ז","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["אֵין בְּבֵית הַכְּנֶסֶת מִי שֶׁיּוֹדֵעַ טְעָמִים הֵיטֵב. מָה עוֹשִׂים?",["קוֹרְאִים, וְאֶחָד עוֹמֵד עִם חֻמָּשׁ לְיָדוֹ","לֹא קוֹרְאִים בַּתּוֹרָה בִּכְלָל","הוֹלְכִים הַבַּיְתָה מֻקְדָּם"],0,"קוֹרְאִים בַּתּוֹרָה בִּבְרָכָה כְּהִלְכָתָהּ, וְאֶחָד מֵהַקָּהָל עוֹמֵד עִם חֻמָּשׁ לְיַד הַקּוֹרֵא כְּדֵי לְתַקֵּן אוֹתוֹ אִם יִטְעֶה.","פֶּרֶק מ״ה, הֲלָכָה י״ז","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["מַה גָּרַם לַחֲכָמִים לְתַקֵּן אֶת קְרִיאַת הַהַפְטָרָה?",["חַג חָדָשׁ","גְּזֵרָה שֶׁלֹּא יִקְרְאוּ בַּתּוֹרָה","בַּקָּשָׁה שֶׁל הַיְלָדִים"],1,"הַמַּלְכוּת גָּזְרָה שֶׁלֹּא יִקְרְאוּ בַּתּוֹרָה, וְלֹא גָּזְרָה עַל הַנְּבִיאִים – לָכֵן תִּקְּנוּ לִקְרֹא בַּנְּבִיאִים.","פֶּרֶק מ״ה, הֲלָכָה י״ח","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["לְפִי הַהֶסְבֵּר הָרִאשׁוֹן, מָה פֵּרוּשׁ הַמִּלָּה ״הַפְטָרָה״?",["הַתְחָלָה","שִׂמְחָה","סִיּוּם"],2,"הַפְטָרָה – מִלְּשׁוֹן סִיּוּם, שֶׁבָּהּ מִסְתַּיֶּמֶת הַקְּרִיאָה.","פֶּרֶק מ״ה, הֲלָכָה י״ט","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["מָה קוֹרֵא הַמַּפְטִיר קֹדֶם, לִפְנֵי הַנָּבִיא?",["כַּמָּה פְּסוּקִים בַּתּוֹרָה","פֶּרֶק תְּהִלִּים","דַּף גְּמָרָא"],0,"כְּדֵי שֶׁהַנָּבִיא לֹא יֵרָאֶה שָׁוֶה בַּחֲשִׁיבוּתוֹ לַתּוֹרָה, הַמַּפְטִיר קוֹרֵא קֹדֶם כַּמָּה פְּסוּקִים בַּתּוֹרָה.","פֶּרֶק מ״ה, הֲלָכָה כ׳","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["מָה אוֹמְרִים אַחֲרֵי שֶׁהָעוֹלִים מְסַיְּמִים אֶת הַפָּרָשָׁה, לִפְנֵי הַמַּפְטִיר?",["קִדּוּשׁ","חֲצִי קַדִּישׁ","הַבְדָּלָה"],1,"הַמַּפְטִיר אֵינוֹ נֶחְשָׁב לְאֶחָד מֵהָעוֹלִים, לָכֵן אַחֲרֵי הַפָּרָשָׁה אוֹמְרִים חֲצִי קַדִּישׁ וְאָז עוֹלֶה הַמַּפְטִיר.","פֶּרֶק מ״ה, הֲלָכָה כ״א","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["הוֹצִיאוּ שְׁלוֹשָׁה סִפְרֵי תּוֹרָה. בְּאֵיזֶה סֵפֶר קוֹרֵא הַמַּפְטִיר?",["בָּרִאשׁוֹן","בָּאֶמְצָעִי","בָּאַחֲרוֹן"],2,"כְּשֶׁמּוֹצִיאִים שְׁנַיִם אוֹ שְׁלוֹשָׁה סִפְרֵי תּוֹרָה – הַמַּפְטִיר קוֹרֵא בַּסֵּפֶר הָאַחֲרוֹן.","פֶּרֶק מ״ה, הֲלָכָה כ״ב","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["בְּתַעֲנִית צִבּוּר – מִי הוּא הַמַּפְטִיר?",["הָעוֹלֶה הַשְּׁלִישִׁי","הָעוֹלֶה הַשְּׁבִיעִי","הָעוֹלֶה הָרִאשׁוֹן"],0,"בְּתַעֲנִית צִבּוּר וּבְמִנְחָה שֶׁל יוֹם הַכִּפּוּרִים הַמַּפְטִיר הוּא הָעוֹלֶה הַשְּׁלִישִׁי לַתּוֹרָה.","פֶּרֶק מ״ה, הֲלָכָה כ״ג","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["מַדּוּעַ מְאַחֲרִים אֶת תְּפִלַּת עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת?",["כְּדֵי לְהַסְפִּיק לִישֹׁן עוֹד","כְּדֵי לְהוֹסִיף מֵחֹל עַל הַקֹּדֶשׁ","כְּדֵי לְסַיֵּם מַהֵר אֶת הַתְּפִלָּה"],1,"מְאַחֲרִים אֶת עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת כְּדֵי לְהוֹסִיף מֵחֹל עַל הַקֹּדֶשׁ.","פֶּרֶק מ״ו, הֲלָכָה א׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["בְּאֵיזוֹ בְּרָכָה בַּעֲמִידָה אוֹמְרִים ״אַתָּה חוֹנַנְתָּנוּ״?",["״רְפָאֵנוּ״","״בָּרֵךְ עָלֵינוּ״","״חוֹנֵן הַדַּעַת״"],2,"בְּבִרְכַּת ״חוֹנֵן הַדַּעַת״ מַבְדִּילִים בֵּין קְדֻשַּׁת הַשַּׁבָּת לִימוֹת הַחֹל בַּאֲמִירַת ״אַתָּה חוֹנַנְתָּנוּ״.","פֶּרֶק מ״ו, הֲלָכָה ב׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["בְּ״וִיהִי נֹעַם״ בֵּרֵךְ מֹשֶׁה אֶת יִשְׂרָאֵל כְּשֶׁסִּיְּמוּ...",["אֶת מְלֶאכֶת הַמִּשְׁכָּן","אֶת קְרִיעַת יַם סוּף","אֶת הַכְּנִיסָה לָאָרֶץ"],0,"״וִיהִי נֹעַם״ הוּא מִזְמוֹר בְּרָכָה שֶׁבֵּרֵךְ מֹשֶׁה אֶת יִשְׂרָאֵל כְּשֶׁסִּיְּמוּ אֶת מְלֶאכֶת הַמִּשְׁכָּן.","פֶּרֶק מ״ו, הֲלָכָה ג׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים אֵין אוֹמְרִים ״וִיהִי נֹעַם״ אִם בְּאוֹתוֹ שָׁבוּעַ יָחוּל...",["רֹאשׁ חֹדֶשׁ","יוֹם טוֹב","יוֹם הֻלֶּדֶת"],1,"בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים אֵין אוֹמְרִים ״וִיהִי נֹעַם״ אִם בְּאוֹתוֹ שָׁבוּעַ יָחוּל יוֹם טוֹב, כִּי צְרִיכִים שִׁשָּׁה יְמֵי מַעֲשֶׂה.","פֶּרֶק מ״ו, הֲלָכָה ד׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["יֵשׁ נוֹהֲגִים לְהַבְדִּיל בְּבֵית הַכְּנֶסֶת בְּסִיּוּם עַרְבִית. עַל מָה מַבְדִּילִים?",["עַל הַלֶּחֶם","עַל הַמַּיִם","עַל הַיַּיִן"],2,"יֵשׁ נוֹהֲגִים לְהַבְדִּיל עַל הַיַּיִן בְּבֵית הַכְּנֶסֶת, כְּדֵי לְהוֹצִיא אֶת מִי שֶׁאֵין לוֹ יַיִן בְּבֵיתוֹ.","פֶּרֶק מ״ו, הֲלָכָה ה׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["עַד שֶׁיֵּרָאוּ מָה, אָסוּר לַעֲשׂוֹת מְלָאכָה בְּמוֹצָאֵי שַׁבָּת?",["שְׁלוֹשָׁה כּוֹכָבִים קְטַנִּים","כּוֹכָב אֶחָד גָּדוֹל","יָרֵחַ מָלֵא"],0,"אָסוּר לַעֲשׂוֹת מְלָאכָה עַד שֶׁיֵּרָאוּ שְׁלוֹשָׁה כּוֹכָבִים קְטַנִּים, רְצוּפִים וְלֹא מְפֻזָּרִים.","פֶּרֶק מ״ו, הֲלָכָה ו׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["גַּם אַחֲרֵי שֶׁנִּרְאוּ שְׁלוֹשָׁה כּוֹכָבִים, עַד מָתַי אָסוּר לַעֲשׂוֹת מְלָאכָה?",["עַד חֲצוֹת הַלַּיְלָה","עַד שֶׁמַּבְדִּילִים","עַד הַבֹּקֶר"],1,"גַּם לְאַחַר שֶׁנִּרְאוּ שְׁלוֹשָׁה כּוֹכָבִים, אָסוּר לַעֲשׂוֹת מְלָאכָה עַד שֶׁמַּבְדִּילִים.","פֶּרֶק מ״ו, הֲלָכָה ז׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["מִי שֶׁצָּרִיךְ לַעֲשׂוֹת מְלָאכָה לִפְנֵי שֶׁהִבְדִּיל בַּתְּפִלָּה, מָה יֹאמַר?",["״שַׁבָּת שָׁלוֹם״","״בֹּקֶר טוֹב״","״בָּרוּךְ הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל״"],2,"אוֹמֵר ״בָּרוּךְ הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל״, וְאַחַר כָּךְ רַשַּׁאי לַעֲשׂוֹת מְלָאכָה.","פֶּרֶק מ״ו, הֲלָכָה ח׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["נָשִׁים שֶׁאֵינָן מַבְדִּילוֹת בַּתְּפִלָּה וּצְרִיכוֹת לַעֲשׂוֹת מְלָאכָה לִפְנֵי הַהַבְדָּלָה עַל הַכּוֹס, מָה יַעֲשׂוּ?",["יֹאמְרוּ ״בָּרוּךְ הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל״","יַמְתִּינוּ עַד מָחָר","יַעֲשׂוּ מְלָאכָה בְּלִי לוֹמַר כְּלוּם"],0,"נָשִׁים שֶׁאֵינָן מַבְדִּילוֹת בַּתְּפִלָּה וּצְרִיכוֹת לַעֲשׂוֹת מְלָאכָה, יֹאמְרוּ ״בָּרוּךְ הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל״.","פֶּרֶק מ״ו, הֲלָכָה ט׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["בְּמָה מְקַדְּשִׁים אֶת הַשַּׁבָּת בִּיצִיאָתָהּ?",["בְּהַבְדָּלָה","בְּקִדּוּשׁ","בְּהַדְלָקַת נֵרוֹת שַׁבָּת"],0,"מִצְוָה מִן הַתּוֹרָה לְקַדֵּשׁ אֶת הַשַּׁבָּת בִּכְנִיסָתָהּ בְּקִדּוּשׁ, וּבִיצִיאָתָהּ בְּהַבְדָּלָה.","פֶּרֶק מ״ז, הֲלָכָה א׳","הַבְדָּלָה עַל הַכּוֹס"],["מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמִי שֶׁמַּבְדִּיל עַל הַיַּיִן?",["נוֹתֵן לוֹ מַמְתַּקִּים","קוֹרֵא לוֹ קָדוֹשׁ וְעוֹשֶׂה אוֹתוֹ סְגֻלָּה","נוֹתֵן לוֹ פְּרָס שֶׁל כֶּסֶף"],1,"הַמַּבְדִּיל עַל הַיַּיִן אוֹ שׁוֹמֵעַ מֵאֲחֵרִים – הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לוֹ ׳קָדוֹשׁ׳ וְעוֹשֶׂה אוֹתוֹ סְגֻלָּה, יָקָר וּמְיֻחָד.","פֶּרֶק מ״ז, הֲלָכָה ב׳","הַבְדָּלָה עַל הַכּוֹס"],["מָה בָּא רִאשׁוֹן בְּסֵדֶר יַבְנֶ״ה?",["נֵר","בְּשָׂמִים","יַיִן"],2,"סֵדֶר הַהַבְדָּלָה: יַיִן, בְּשָׂמִים, נֵר, הַבְדָּלָה – רָאשֵׁי תֵּבוֹת יַבְנֶ״ה. מַתְחִילִים בְּכוֹס הַיַּיִן בְּיַד יָמִין.","פֶּרֶק מ״ז, הֲלָכָה ג׳","הַבְדָּלָה עַל הַכּוֹס"],["כַּמָּה יַיִן שׁוֹתֶה הַמַּבְדִּיל לְכַתְּחִלָּה אַחֲרֵי הַבְּרָכָה?",["טִפָּה אַחַת","שִׁעוּר רְבִיעִית","בַּקְבּוּק שָׁלֵם"],1,"אַחֲרֵי ״הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל״ שׁוֹתִים שִׁעוּר רְבִיעִית, וּבְדִיעֲבַד אִם שָׁתָה מְלוֹא לֻגְמָיו – יָצָא.","פֶּרֶק מ״ז, הֲלָכָה ד׳","הַבְדָּלָה עַל הַכּוֹס"],["לְאוֹר אֵיזֶה נֵר נוֹהֲגִים לְהִסְתַּכֵּל בְּכַפּוֹת הַיָּדַיִם וּבַצִּפָּרְנַיִם?",["אֲבוּקָה עִם כַּמָּה פְּתִילוֹת","נוּרַת חַשְׁמַל","פָּנָס כִּיס"],0,"מִצְוָה מִן הַמֻּבְחָר לְבָרֵךְ עַל אֲבוּקָה שֶׁאוֹרָהּ רַב (וְטוֹב מִשַּׁעֲוָה), וּמִתְקָרְבִים אֵלֶיהָ וּמִסְתַּכְּלִים בַּיָּדַיִם וּבַצִּפָּרְנַיִם כְּדֵי לִבְחֹן שֶׁנֶּהֱנִים מֵאוֹרָהּ.","פֶּרֶק מ״ז, הֲלָכוֹת ה׳-ו׳","הַבְדָּלָה עַל הַכּוֹס"],["מָה רַבִּים נוֹהֲגִים לַעֲשׂוֹת בִּשְׁעַת הַבְּרָכָה עַל הַנֵּר?",["לְהַדְלִיק עוֹד מְנוֹרוֹת","לְכַבּוֹת אֶת אוֹר הַחַשְׁמַל","לָצֵאת הַחוּצָה"],1,"רַבִּים מְכַבִּים אֶת אוֹר הַחַשְׁמַל בִּשְׁעַת בִּרְכַּת הַנֵּר, כְּדֵי שֶׁהַהֲנָאָה מֵאוֹר הַנֵּר תִּהְיֶה נִכֶּרֶת.","פֶּרֶק מ״ז, הֲלָכָה ז׳","הַבְדָּלָה עַל הַכּוֹס"],["מִי חַיָּב בְּהַבְדָּלָה?",["רַק גְּבָרִים","גַּם גְּבָרִים וְגַם נָשִׁים","רַק יְלָדִים"],1,"נָשִׁים חַיָּבוֹת בְּהַבְדָּלָה כְּשֵׁם שֶׁהֵן חַיָּבוֹת בְּקִדּוּשׁ, וְאִשָּׁה שֶׁלֹּא שָׁמְעָה הַבְדָּלָה – חַיֶּבֶת לְהַבְדִּיל בְּעַצְמָהּ.","פֶּרֶק מ״ז, הֲלָכָה ח׳","הַבְדָּלָה עַל הַכּוֹס"],["יֶלֶד הִבְדִּיל בַּתְּפִלָּה, אֲבָל עוֹד לֹא שָׁמַע הַבְדָּלָה עַל הַכּוֹס. מָה מֻתָּר לוֹ לֶאֱכֹל?",["עוּגָה","פְּרִי","שׁוּם דָּבָר עַד הַהַבְדָּלָה עַל הַכּוֹס"],2,"אָסוּר לֶאֱכֹל וְלִשְׁתּוֹת מִשְּׁקִיעַת הַחַמָּה בְּסוֹף שַׁבָּת עַד הַהַבְדָּלָה עַל הַכּוֹס, גַּם לְמִי שֶׁהִבְדִּיל בַּתְּפִלָּה.","פֶּרֶק מ״ז, הֲלָכוֹת ט׳-י״ב","הַבְדָּלָה עַל הַכּוֹס"],["מִי שֶׁהִתְחִיל סְעוּדָה שְׁלִישִׁית לִפְנֵי הַשְּׁקִיעָה – מָה יָכוֹל לַעֲשׂוֹת?",["לְהַמְשִׁיךְ לֶאֱכֹל","לְהַפְסִיק מִיָּד","לָלֶכֶת לִישֹׁן"],0,"מִי שֶׁהִתְחִיל סְעוּדָה שְׁלִישִׁית לִפְנֵי הַשְּׁקִיעָה יָכוֹל לְהַמְשִׁיךְ גַּם אַחֲרֶיהָ, וְטוֹב לְמַהֵר לְסַיֵּם. וּמַיִם לִפְנֵי הַהַבְדָּלָה – מֻתָּר, אַךְ נָהֲגוּ לְהַחְמִיר.","פֶּרֶק מ״ז, הֲלָכוֹת י׳-י״א","הַבְדָּלָה עַל הַכּוֹס"],["בַּבַּיִת יֵשׁ יַיִן. עַל מָה צָרִיךְ לְהַבְדִּיל?",["עַל כּוֹס מַיִם","עַל כּוֹס חָלָב","עַל כּוֹס יַיִן"],2,"מִי שֶׁיֵּשׁ לוֹ יַיִן אוֹ מִיץ עֲנָבִים חַיָּב לְהַבְדִּיל דַּוְקָא עֲלֵיהֶם.","פֶּרֶק מ״ז, הֲלָכָה י״ג","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["מָה זֶה ״חֲמַר מְדִינָה״?",["מַיִם מִן הַבֶּרֶז","מַשְׁקֶה חָשׁוּב שֶׁמְּכַבְּדִים בּוֹ אוֹרְחִים","מַשְׁקֶה שֶׁאַף אֶחָד אֵינוֹ שׁוֹתֶה"],1,"חֲמַר מְדִינָה הוּא מַשְׁקֶה חָשׁוּב שֶׁבְּנֵי הָעִיר רְגִילִים לִשְׁתּוֹתוֹ וּלְכַבֵּד בּוֹ אוֹרְחִים.","פֶּרֶק מ״ז, הֲלָכָה י״ד","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["אֵיךְ אוֹמְרִים אֶת הַהַבְדָּלָה, בִּישִׁיבָה אוֹ בַּעֲמִידָה?",["רַק בִּשְׁכִיבָה","רַק בְּרִיצָה","כָּל אֶחָד כְּמִנְהַג אֲבוֹתָיו"],2,"יֵשׁ נוֹהֲגִים לְהַבְדִּיל בִּישִׁיבָה וְיֵשׁ נוֹהֲגִים בַּעֲמִידָה, וְכָל אֶחָד יִנְהַג כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק מ״ז, הֲלָכָה ט״ו","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["מָה עוֹשִׂים בְּנֵר הַהַבְדָּלָה אַחֲרֵי הַהַבְדָּלָה?",["מְכַבִּים אוֹתוֹ בִּמְעַט יַיִן","מַשְׁאִירִים אוֹתוֹ לִקְרִיאָה","מְבַשְּׁלִים עָלָיו אֹכֶל"],0,"שׁוֹפְכִים מְעַט יַיִן מֵהַכּוֹס וּמְכַבִּים בּוֹ אֶת הַנֵּר, לְהַדְגִּישׁ שֶׁהֻדְלַק לְמִצְוָה וְלֹא לְשִׁמּוּשׁ אַחֵר.","פֶּרֶק מ״ז, הֲלָכָה ט״ז","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["יֵשׁ נוֹהֲגִים לָשִׂים מְעַט מִן הַיַּיִן שֶׁכִּבּוּ בּוֹ אֶת הַנֵּר. עַל מָה?",["עַל הַנַּעֲלַיִם","עַל הָעֵינַיִם","עַל הַשֻּׁלְחָן"],1,"יֵשׁ נוֹהֲגִים לָשִׂים מְעַט מֵהַיַּיִן עַל הָעֵינַיִם מִשּׁוּם חִבּוּב מִצְוָה.","פֶּרֶק מ״ז, הֲלָכָה י״ז","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["אֶת מִי מַזְכִּירִים בְּשִׁירִים בְּמוֹצָאֵי שַׁבָּת?",["אֶת אֵלִיָּהוּ הַנָּבִיא","אֶת נֹחַ וְהַתֵּבָה","אֶת יוֹנָה וְהַדָּג"],0,"נוֹהֲגִים לָשִׁיר וּלְהַזְכִּיר אֶת אֵלִיָּהוּ הַנָּבִיא, כִּי הוּא עָתִיד לְבַשֵּׂר אֶת הַגְּאֻלָּה.","פֶּרֶק מ״ז, הֲלָכָה י״ח","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["אֵיזוֹ סְעוּדָה אוֹכְלִים בְּמוֹצָאֵי שַׁבָּת?",["אֲרוּחַת בֹּקֶר","סְעוּדַת מְלַוֶּה מַלְכָּה","סְעוּדַת פּוּרִים"],1,"בְּמוֹצָאֵי שַׁבָּת סוֹעֲדִים סְעוּדָה רְבִיעִית, סְעוּדַת מְלַוֶּה מַלְכָּה, לְכַבֵּד אֶת הַשַּׁבָּת בִּיצִיאָתָהּ.","פֶּרֶק מ״ז, הֲלָכָה י״ט","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["קָשֶׁה לוֹ לֶאֱכֹל לֶחֶם בִּמְלַוֶּה מַלְכָּה. מָה יֹאכַל?",["רַק סֻכָּרִיּוֹת","שׁוּם דָּבָר","מַאֲכָל שֶׁבִּרְכָתוֹ מְזוֹנוֹת"],2,"מִי שֶׁקָּשֶׁה לוֹ לֶאֱכֹל לֶחֶם, יֹאכַל מַאֲכָלִים שֶׁבִּרְכָתָם מְזוֹנוֹת.","פֶּרֶק מ״ז, הֲלָכָה כ׳","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["שָׁכַח לְהַבְדִּיל בְּמוֹצָאֵי שַׁבָּת. עַד מָתַי יָכוֹל לְהַבְדִּיל?",["עַד סוֹף יוֹם שְׁלִישִׁי","עַד חֲצוֹת הַלַּיְלָה בִּלְבַד","עַד הַשַּׁבָּת הַבָּאָה"],0,"מִי שֶׁלֹּא הִבְדִּיל בְּמוֹצָאֵי שַׁבָּת, יָכוֹל לְהַבְדִּיל עַד סוֹף יוֹם שְׁלִישִׁי בַּשָּׁבוּעַ.","פֶּרֶק מ״ז, הֲלָכָה כ״א","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["מֹשֶׁה הִקְדִּים אֶת צִוּוּי הַשַּׁבָּת לְצִוּוּי בְּנִיַּת הַמִּשְׁכָּן. מָה לָמַדְנוּ מִכָּךְ?",["בּוֹנִים אֶת הַמִּשְׁכָּן גַּם בְּשַׁבָּת","אֶת הַמִּשְׁכָּן בּוֹנִים רַק בַּלַּיְלָה","בְּנִיַּת הַמִּשְׁכָּן אֵינָהּ דּוֹחָה אֶת הַשַּׁבָּת"],2,"חֲכָמִים הִסְבִּירוּ שֶׁבְּכָךְ שֶׁהִקְדִּים מֹשֶׁה אֶת הַשַּׁבָּת לַמִּשְׁכָּן, לִמֵּד שֶׁבְּנִיַּת הַמִּשְׁכָּן אֵינָהּ דּוֹחָה אֶת הַשַּׁבָּת.","פֶּרֶק מ״ח, הֲלָכָה ב׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["בַּמִּשְׁכָּן כָּתְבוּ סִימָנִים עַל הַקְּרָשִׁים. כַּמָּה אֲבוֹת מְלָאכָה מָנוּ חֲכָמִים בַּעֲשִׂיַּת הַמִּשְׁכָּן?",["שְׁלוֹשִׁים וָתֵשַׁע","עֶשֶׂר","שִׁבְעִים"],0,"הַמְּלָאכוֹת שֶׁנַּעֲשׂוּ בַּמִּשְׁכָּן אֲסוּרוֹת בְּשַׁבָּת, כְּמוֹ כְּתִיבַת סִימָנִים עַל הַקְּרָשִׁים. חֲכָמִים מָנוּ שְׁלוֹשִׁים וָתֵשַׁע: ל״ט אֲבוֹת מְלָאכָה.","פֶּרֶק מ״ח, הֲלָכוֹת ג׳-ד׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["חֲכָמִים אָסְרוּ דָּבָר אֶחָד בְּשַׁבָּת כְּדֵי שֶׁלֹּא יִתְלְשׁוּ עָלִים. מָהוּ?",["לָשֶׁבֶת בְּצֵל הָעֵץ","לְהִסְתַּכֵּל עַל הָעֵץ","לַעֲלוֹת עַל הָעֵץ"],2,"הַתּוֹלֵשׁ עָלִים מֵעֵץ עוֹבֵר עַל מְלֶאכֶת קוֹצֵר, וַחֲכָמִים אָסְרוּ אֲפִלּוּ לַעֲלוֹת עַל עֵץ, שֶׁמָּא יִתְלֹשׁ.","פֶּרֶק מ״ח, הֲלָכָה ו׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["אֵיזוֹ פְּעֻלָּה הִיא מְלֶאכֶת חוֹרֵשׁ?",["מִלּוּי גּוּמָא בָּאֲדָמָה","קְרִיאָה בְּסֵפֶר בַּגִּנָּה","הֲלִיכָה עַל שְׁבִיל"],0,"הַחוֹפֵר בַּקַּרְקַע, וְגַם מִי שֶׁמְּיַשֵּׁר אֶת הַקַּרְקַע עַל יְדֵי מִלּוּי גּוּמָא אוֹ סִלּוּק גַּבְשׁוּשִׁית, נִקְרָא ״חוֹרֵשׁ״.","פֶּרֶק מ״ח, הֲלָכָה ז׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["אֵיזוֹ פְּעֻלָּה אֲסוּרָה מִשּׁוּם זוֹרֵעַ?",["הֲרָחַת פְּרָחִים","גִּזּוּם עֲנָפֵי הָעֵץ","יְשִׁיבָה עַל הַדֶּשֶׁא"],1,"כָּל פְּעֻלָּה שֶׁמַּטְּרָתָהּ לְהַצְמִיחַ אֲסוּרָה מִשּׁוּם זוֹרֵעַ. הַגִּזּוּם גּוֹרֵם לִשְׁאָר חֶלְקֵי הָעֵץ לִצְמֹחַ הֵיטֵב.","פֶּרֶק מ״ח, הֲלָכָה ח׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["בְּאֵיזֶה מָקוֹם אָסוּר לִשְׁפֹּךְ מַיִם בְּשַׁבָּת?",["בַּכִּיּוֹר בַּמִּטְבָּח","בְּתוֹךְ הַכּוֹס","בַּגִּנָּה עַל הַצְּמָחִים"],2,"אָסוּר לִשְׁפֹּךְ מַיִם בַּגִּנָּה אוֹ בְּכָל מָקוֹם שֶׁיֵּשׁ בּוֹ צְמָחִים, מִפְּנֵי שֶׁהַדָּבָר מַשְׁקֶה אֶת הַצְּמָחִים וּמוֹעִיל לִצְמִיחָתָם.","פֶּרֶק מ״ח, הֲלָכָה ט׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["אֵיזוֹ פְּעֻלָּה הִיא תּוֹלָדָה שֶׁל מְלֶאכֶת תּוֹפֵר?",["הַדְבָּקַת שְׁנֵי נְיָרוֹת זֶה לָזֶה","קִפּוּל מַגֶּבֶת","פְּתִיחַת סֵפֶר"],0,"הַתּוֹפֵר שְׁנֵי בַּדִּים עוֹבֵר עַל אַב הַמְּלָאכָה ״תּוֹפֵר״, וְהַדְבָּקַת נְיָרוֹת אוֹ בַּדִּים זֶה לָזֶה הִיא תּוֹלָדָה שֶׁל תּוֹפֵר וַאֲסוּרָה מֵהַתּוֹרָה.","פֶּרֶק מ״ח, הֲלָכָה י״א","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["הַאִם מֻתָּר לְחַזֵּק בֶּגֶד בְּסִכַּת בִּטָּחוֹן בְּשַׁבָּת?",["מֻתָּר, זֶה דּוֹמֶה לִסְגִירַת כַּפְתּוֹרִים","אָסוּר בְּכָל מִקְרֶה","מֻתָּר רַק בְּבֶגֶד יָשָׁן"],0,"מֻתָּר לְהִשְׁתַּמֵּשׁ בְּסִכַּת בִּטָּחוֹן, כִּי בְּסִיּוּם לְבִישַׁת הַבֶּגֶד מוֹרִידִים אוֹתָהּ, וְהַדָּבָר דּוֹמֶה לִסְגִירַת רוֹכְסָן אוֹ כַּפְתּוֹרִים.","פֶּרֶק מ״ח, הֲלָכָה י״ב","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מָתַי עוֹבְרִים עַל מְלֶאכֶת ״קוֹרֵעַ״?",["כְּשֶׁנּוֹגְעִים בִּנְיָר","כְּשֶׁקּוֹרְעִים קְרִיעָה שֶׁיֵּשׁ בָּהּ תִּקּוּן","רַק כְּשֶׁקּוֹרְעִים בֶּגֶד"],1,"מִי שֶׁקּוֹרֵעַ קְרִיעָה שֶׁיֵּשׁ בָּהּ תִּקּוּן (תּוֹעֶלֶת) עוֹבֵר עַל אַב הַמְּלָאכָה ״קוֹרֵעַ״.","פֶּרֶק מ״ח, הֲלָכָה י״ג","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["שְׁנֵי נְיָרוֹת נִדְבְּקוּ זֶה לָזֶה. הַאִם מֻתָּר לְהַפְרִיד אוֹתָם בְּשַׁבָּת?",["מֻתָּר","מֻתָּר רַק בְּשִׁנּוּי","אָסוּר, זוֹ קְרִיעָה לְצֹרֶךְ תִּקּוּן"],2,"אָסוּר לְהַפְרִיד נְיָרוֹת דְּבוּקִים, מִפְּנֵי שֶׁזּוֹ פְּעֻלַּת קְרִיעָה לְצֹרֶךְ תִּקּוּן.","פֶּרֶק מ״ח, הֲלָכָה י״ד","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["אֵיזֶה סֵפֶר מֻתָּר לִפְתֹּחַ בְּשַׁבָּת?",["סֵפֶר שֶׁדַּפָּיו נִדְבְּקוּ מִלִּכְלוּךְ","סֵפֶר חָדָשׁ שֶׁדַּפָּיו לֹא נֶחְתְּכוּ","אַף סֵפֶר"],0,"אָסוּר לִקְרֹעַ דַּפֵּי סֵפֶר חָדָשׁ שֶׁלֹּא נֶחְתְּכוּ בִּמְכוֹנַת הַדְּפוּס, אֲבָל מֻתָּר לִפְתֹּחַ סֵפֶר שֶׁדַּפָּיו נִדְבְּקוּ עַל יְדֵי לִכְלוּכִים.","פֶּרֶק מ״ח, הֲלָכָה ט״ו","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מָה כְּדַאי לְהָכִין לִפְנֵי שַׁבָּת בַּשֵּׁרוּתִים?",["מִסְפָּרַיִם","גְּלִיל נְיָר חָדָשׁ","נְיַר טוּאָלֶט חָתוּךְ"],2,"אָסוּר לִקְרֹעַ נְיַר טוּאָלֶט בְּשַׁבָּת, וְלָכֵן צָרִיךְ לְהָכִין כַּמּוּת נְיָר חָתוּךְ שֶׁתַּסְפִּיק לְכָל הַשַּׁבָּת, וּכְדַאי לְהָסִיר אֶת הַגְּלִיל מִמְּקוֹמוֹ.","פֶּרֶק מ״ח, הֲלָכָה ט״ז","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["הַאִם מֻתָּר לִקְרֹעַ אֲרִיזָה שֶׁל חֲטִיף בְּשַׁבָּת?",["אָסוּר מִשּׁוּם קוֹרֵעַ","מֻתָּר, כְּמוֹ קְלִפַּת פְּרִי","מֻתָּר רַק בַּמַּרְפֵּקִים"],1,"מֻתָּר לִקְרֹעַ אֲרִיזוֹת שֶׁל מַאֲכָלִים, כִּי אֵין לָהֶן חֲשִׁיבוּת בִּפְנֵי עַצְמָן, וְהֵן דּוֹמוֹת לִקְלִפַּת פְּרִי שֶׁמְּסִירִים כְּדֵי לְהַגִּיעַ לָאֹכֶל.","פֶּרֶק מ״ח, הֲלָכָה י״ז","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["הַאִם מֻתָּר לְהוֹרִיד דֶּלֶת שֶׁל בַּיִת מִמְּקוֹמָהּ בְּשַׁבָּת?",["אָסוּר, מִשּׁוּם בּוֹנֶה וְסוֹתֵר","מֻתָּר","מֻתָּר רַק לְהַחְזִיר"],0,"אָסוּר לְהוֹרִיד אוֹ לְהַחְזִיר דֶּלֶת וְחַלּוֹן שֶׁל בַּיִת בְּשַׁבָּת, מִשּׁוּם בּוֹנֶה וְסוֹתֵר.","פֶּרֶק מ״ח, הֲלָכָה י״ח","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מָה מֻתָּר לַעֲשׂוֹת בְּשַׁבָּת?",["לְהַחְזִיר רֶגֶל לְכִסֵּא","לִפְתֹּחַ שֻׁלְחָן מִתְקַפֵּל","לְהַרְכִּיב מִטָּה"],1,"אָסוּר לְהַרְכִּיב כִּסֵּא, שֻׁלְחָן אוֹ מִטָּה, וְאָסוּר לְהַחְזִיר רֶגֶל שֶׁהִתְפָּרְקָה. אֲבָל מֻתָּר לִפְתֹּחַ וְלִסְגֹּר שֻׁלְחָן מִתְקַפֵּל וְכִסְאוֹת מִתְקַפְּלִים.","פֶּרֶק מ״ח, הֲלָכָה י״ט","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["הַאִם מֻתָּר לִפְתֹּחַ וְלִסְגֹּר מִכְסֶה מֻבְרָג שֶׁל קֻפְסָה בְּשַׁבָּת?",["אָסוּר","מֻתָּר רַק לִפְתֹּחַ","מֻתָּר לִפְתֹּחַ וְלִסְגֹּר"],2,"כְּלִי שֶׁדֶּרֶךְ שִׁמּוּשׁוֹ הִיא בִּפְתִיחָה וּסְגִירָה שֶׁל הַבְרָגָה, כְּמוֹ מִכְסֶה שֶׁל קֻפְסָה, מֻתָּר לִפְתֹּחַ וְלִסְגֹּר בְּשַׁבָּת.","פֶּרֶק מ״ח, הֲלָכָה כ׳","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["יֵשׁ בַּקְבּוּק יַיִן חָדָשׁ עִם פְּקַק מַתֶּכֶת. מָתַי רָאוּי לִפְתֹּחַ אוֹתוֹ?",["בְּשַׁבָּת בַּבֹּקֶר","בְּיוֹם שִׁשִּׁי","בְּאֶמְצַע סְעוּדַת שַׁבָּת"],1,"יֵשׁ אוֹמְרִים שֶׁפְּתִיחַת פְּקַק מַתֶּכֶת בַּפַּעַם הָרִאשׁוֹנָה אֲסוּרָה מִשּׁוּם מְתַקֵּן כְּלִי, וְלָכֵן רָאוּי לִפְתֹּחַ אֶת הַבַּקְבּוּקִים בְּיוֹם שִׁשִּׁי.","פֶּרֶק מ״ח, הֲלָכָה כ״א","צָד, כּוֹתֵב וּמוֹחֵק"],["אֵיזֶה מִשְׂחָק מֻתָּר בְּשַׁבָּת?",["מִשְׂחָק עַל אֲדָמָה בַּגִּנָּה","בְּנִיַּת מִגְדָּל מִלֶּגוֹ","גֻּלּוֹת עַל קַרְקַע לֹא מְרֻצֶּפֶת"],1,"מֻתָּר לְשַׂחֵק בְּלֶגוֹ וּקְלִיקְס כִּי רְגִילִים לְהַרְכִּיבָם וּלְפָרְקָם. אֲבָל עַל קַרְקַע שֶׁאֵינָהּ מְרֻצֶּפֶת אָסוּר, שֶׁמָּא יְיַשְּׁרוּ גֻּמּוֹת – וְזֶה בּוֹנֶה.","פֶּרֶק מ״ח, הֲלָכוֹת כ״ב-כ״ג","צָד, כּוֹתֵב וּמוֹחֵק"],["מָה אָסוּר לַעֲשׂוֹת בְּשַׁבָּת?",["לְהַבִּיט בְּצָב בַּגִּנָּה","לִקְרֹא סֵפֶר עַל צַבִּים","לִתְפֹּס צָב בַּיָּדַיִם"],2,"אָסוּר לָצוּד בְּשַׁבָּת בַּעֲלֵי חַיִּים כְּמוֹ צַבִּים וַחֲתוּלִים – גַּם בַּיָּדַיִם וְגַם עַל יְדֵי סְגִירָתָם בְּמָקוֹם שֶׁאֵין לָהֶם יְצִיאָה.","פֶּרֶק מ״ח, הֲלָכָה כ״ד","צָד, כּוֹתֵב וּמוֹחֵק"],["חַיַּת מַחְמָד מְסָרֶבֶת לְהִכָּנֵס לַכְּלוּב. מָה אָסוּר?",["לְהַכְנִיס אוֹתָהּ בְּכֹחַ","לְחַכּוֹת שֶׁתִּכָּנֵס לְבַד","לְהַשְׁאִיר אוֹתָהּ בַּחֲצֵר"],0,"מֻתָּר לְהַכְנִיס חַיּוֹת מַחְמָד שֶׁאֵינָן רְגִילוֹת לִבְרֹחַ, אֲבָל אִם הֵן מְסָרְבוֹת – אָסוּר לְהַכְנִיסָן בְּכֹחַ. וּלְגַבֵּי קְשִׁירַת כֶּלֶב לִרְצוּעָה: מֻתָּר, וְיֵשׁ מַחְמִירִים.","פֶּרֶק מ״ח, הֲלָכָה כ״ה","צָד, כּוֹתֵב וּמוֹחֵק"],["אֵיזֶה עוֹף מֻתָּר לְהַכְנִיס לִכְלוּב בְּשַׁבָּת?",["תֻּכִּי חָדָשׁ שֶׁעוֹד לֹא רָגִיל","תֻּכִּי צַיְתָן שֶׁבָּא כְּשֶׁקּוֹרְאִים לוֹ","יוֹנָה שֶׁעָפָה בָּרְחוֹב"],1,"מֻתָּר לְהַכְנִיס לִכְלוּב עוֹפוֹת צַיְתָנִים שֶׁנִּשְׁמָעִים לַבְּעָלִים, אֲבָל לֹא עוֹפוֹת חֲדָשִׁים שֶׁאֵינָם רְגִילִים לִכְלוּב.","פֶּרֶק מ״ח, הֲלָכָה כ״ו","צָד, כּוֹתֵב וּמוֹחֵק"],["יֶלֶד רוֹצֶה לִכְתֹּב אֶת שְׁמוֹ בַּחוֹל בְּשַׁבָּת. מָה הַדִּין?",["מֻתָּר, כִּי זֶה רַק חוֹל","מֻתָּר רַק בְּאֶצְבַּע","אָסוּר, גַּם בַּחוֹל אָסוּר לִכְתֹּב"],2,"אָסוּר לִכְתֹּב בְּשַׁבָּת גַּם בִּדְבָרִים שֶׁלֹּא רְגִילִים לִכְתֹּב בָּהֶם, כְּמוֹ מַשְׁקִים אוֹ חוֹל.","פֶּרֶק מ״ח, הֲלָכָה כ״ז","צָד, כּוֹתֵב וּמוֹחֵק"],["עוּגִיָּה שֶׁסֵּמֶל הַחֶבְרָה מֻטְבָּע בְּגוּפָהּ. הַאִם מֻתָּר לַחְתֹּךְ אוֹתָהּ?",["מֻתָּר","אָסוּר","רַק בְּמוֹצָאֵי שַׁבָּת"],0,"כַּאֲשֶׁר הַכְּתִיבָה הִיא בְּגוּף הַמַּאֲכָל, כְּמוֹ סֵמֶל מֻטְבָּע בְּעוּגִיָּה – מֻתָּר לַחְתֹּךְ. עַל עוּגָה שֶׁכָּתְבוּ עָלֶיהָ בְּסֻכָּרִיּוֹת יֵשׁ מַחֲלֹקֶת.","פֶּרֶק מ״ח, הֲלָכָה ל׳","צָד, כּוֹתֵב וּמוֹחֵק"],["פּוֹתְחִים חֲבִילַת בִּיסְקְוִיטִים בְּשַׁבָּת. אֵיפֹה כְּדַאי לִקְרֹעַ?",["דֶּרֶךְ הָאוֹתִיּוֹת","בְּמָקוֹם שֶׁאֵין בּוֹ אוֹתִיּוֹת","דֶּרֶךְ שֵׁם הַחֶבְרָה"],1,"אָסוּר לִקְרֹעַ נְיָר שֶׁמֻּדְפָּסוֹת עָלָיו אוֹתִיּוֹת מִשּׁוּם מוֹחֵק, וְלָכֵן נִזְהָרִים כְּשֶׁפּוֹתְחִים אֲרִיזָה. וְיֵשׁ מַתִּירִים כְּשֶׁאֵין כַּוָּנָה לִמְחֹק.","פֶּרֶק מ״ח, הֲלָכָה ל״א","צָד, כּוֹתֵב וּמוֹחֵק"],["אֵיזוֹ דֶּרֶךְ לְהַפְרִיד אֹכֶל מִפְּסֹלֶת מֻתֶּרֶת בְּשַׁבָּת?",["מְסַנְּנִים בְּמִסְנֶנֶת וְשׁוֹמְרִים לְמָחָר","מוֹצִיאִים אֶת הַפְּסֹלֶת מִתּוֹךְ הָאֹכֶל","לוֹקְחִים אֶת הָאֹכֶל בַּיָּד וְאוֹכְלִים מִיָּד"],2,"בּוֹרֵר הִיא אַחַת מִל״ט הַמְּלָאכוֹת, וּמֻתָּר לְהַפְרִיד רַק כְּשֶׁלּוֹקְחִים אֹכֶל מִתּוֹךְ פְּסֹלֶת, בַּיָּד, וְאוֹכְלִים מִיָּד.","פֶּרֶק מ״ט, הֲלָכוֹת א׳-ב׳","בּוֹרֵר בְּשַׁבָּת"],["בַּשַּׂקִּית יֵשׁ אֱגוֹזֵי קַשְׁיוֹ וּמְעַט פִּיסְטוּקִים, וַאֲנִי רוֹצֶה רַק קַשְׁיוֹ. מָה עוֹשִׂים?",["מוֹצִיאִים אֶת הַפִּיסְטוּקִים","מוֹצִיאִים אֶת אֱגוֹזֵי הַקַּשְׁיוֹ","שׁוֹפְכִים הַכֹּל לְמִסְנֶנֶת"],1,"״אֹכֶל״ הוּא מַה שֶּׁאֲנַחְנוּ מְעֻנְיָנִים בּוֹ כָּרֶגַע, וְלָכֵן מוֹצִיאִים אֶת הַקַּשְׁיוֹ וְלֹא אֶת הַפִּיסְטוּקִים.","פֶּרֶק מ״ט, הֲלָכָה ג׳","בּוֹרֵר בְּשַׁבָּת"],["בְּמָה מֻתָּר לְהוֹצִיא יְרָקוֹת מִתּוֹךְ הַמָּרָק בְּשַׁבָּת?",["בְּכַף עִם חֹרִים","בְּמִסְנֶנֶת","בְּמַזְלֵג אוֹ בְּכַף רְגִילָה"],2,"כְּלִי הַמְּיֻעָד לִבְרִירָה אָסוּר, אֲבָל סַכּוּ״ם הוּא כְּמוֹ ״יָד אֲרֻכָּה״ וּמֻתָּר.","פֶּרֶק מ״ט, הֲלָכוֹת ד׳-ה׳","בּוֹרֵר בְּשַׁבָּת"],["בָּרַרְתִּי אֹכֶל מִתּוֹךְ פְּסֹלֶת בַּיָּד. מָתַי צָרִיךְ לֶאֱכֹל אוֹתוֹ?",["מִיָּד, עַכְשָׁו","מָחָר בַּבֹּקֶר","בְּמוֹצָאֵי שַׁבָּת"],0,"בּוֹרְרִים רַק לְשִׁמּוּשׁ ״לְאַלְתַּר״, וְאָסוּר לְהָנִיחַ לְשִׁמּוּשׁ מְאֻחָר יוֹתֵר, אֲפִלּוּ בְּתוֹךְ הַשַּׁבָּת.","פֶּרֶק מ״ט, הֲלָכָה ו׳","בּוֹרֵר בְּשַׁבָּת"],["מָתַי מֻתָּר לִבְרֹר אֶת כָּל מַה שֶּׁצָּרִיךְ לַסְּעוּדָה?",["שָׁעוֹת רַבּוֹת לִפְנֵי הַסְּעוּדָה","סָמוּךְ לִתְחִלַּת הַסְּעוּדָה","בְּסוֹף הַסְּעוּדָה, לַסְּעוּדָה הַבָּאָה"],1,"מֻתָּר לִבְרֹר אֶת כָּל הַנִּצְרָךְ לַסְּעוּדָה, אֲפִלּוּ אִם תִּמָּשֵׁךְ כַּמָּה שָׁעוֹת, אַךְ רַק סָמוּךְ לִתְחִלָּתָהּ.","פֶּרֶק מ״ט, הֲלָכָה ז׳","בּוֹרֵר בְּשַׁבָּת"],["אֵיזֶה פְּרִי מֻתָּר לְקַלֵּף בְּמַקְלֵף, אֲפִלּוּ כְּדֵי לֶאֱכֹל אוֹתוֹ אַחַר כָּךְ?",["בָּנָנָה","תַּפּוּז","תַּפּוּחַ"],2,"תַּפּוּחַ רְגִילִים לֶאֱכֹל עִם הַקְּלִפָּה, וְלָכֵן מֻתָּר לְקַלְּפוֹ בְּמַקְלֵף אֲפִלּוּ לְאַחַר זְמַן.","פֶּרֶק מ״ט, הֲלָכָה ח׳","בּוֹרֵר בְּשַׁבָּת"],["אֵיךְ מֻתָּר לְקַלֵּף תַּפּוּז בְּשַׁבָּת?",["בַּיָּד, סָמוּךְ לַאֲכִילָה","בְּמַקְלֵף, כְּדֵי לֶאֱכֹל מָחָר","בִּכְלִי מְיֻחָד לִקְלִפּוֹת תַּפּוּזִים"],0,"תַּפּוּז אֵין רְגִילִים לֶאֱכֹל עִם הַקְּלִפָּה, וְלָכֵן מְקַלְּפִים אוֹתוֹ בַּיָּד אוֹ בְּסַכִּין, סָמוּךְ לַאֲכִילָה.","פֶּרֶק מ״ט, הֲלָכָה ט׳","בּוֹרֵר בְּשַׁבָּת"],["מָה הַדִּין בִּשְׁטִיפַת פֵּרוֹת וִירָקוֹת בְּמַיִם בְּשַׁבָּת?",["אָסוּר לִשְׁטֹף בְּכָל אֹפֶן","מֻתָּר לִשְׁטֹף בְּמַיִם","מֻתָּר רַק בְּמוֹצָאֵי שַׁבָּת"],1,"מֻתָּר לִשְׁטֹף פֵּרוֹת וִירָקוֹת בְּמַיִם.","פֶּרֶק מ״ט, הֲלָכָה י׳","בּוֹרֵר בְּשַׁבָּת"],["חֲלָקִים שֶׁל שְׁנֵי מִשְׂחָקִים הִתְעַרְבְּבוּ, וַאֲנִי רוֹצֶה לְשַׂחֵק בְּאֶחָד. מָה עוֹשִׂים?",["מוֹצִיאִים אֶת הַחֲלָקִים שֶׁלֹּא רוֹצִים","מְמַיְּנִים הַכֹּל לִשְׁתֵּי קֻפְסָאוֹת","לוֹקְחִים אֶת חֶלְקֵי הַמִּשְׂחָק שֶׁרוֹצִים"],2,"גַּם בִּדְבָרִים שֶׁאֵינָם מַאֲכָלִים יֵשׁ בּוֹרֵר: לוֹקְחִים אֶת מַה שֶּׁרוֹצִים (הָ״אֹכֶל״) וְלֹא אֶת הַשְּׁאָר (הַ״פְּסֹלֶת״). כָּךְ גַּם בִּבְגָדִים וּבְסַכּוּ״ם.","פֶּרֶק מ״ט, הֲלָכָה י״א","בּוֹרֵר בְּשַׁבָּת"],["מָתַי טוֹב לְסַיֵּם לְבַשֵּׁל אֶת כָּל מַאַכְלֵי הַשַּׁבָּת?",["בְּעֶרֶב שַׁבָּת","בְּשַׁבָּת בַּבֹּקֶר","בְּשַׁבָּת לִפְנֵי הַסְּעֻדָּה"],0,"אָסוּר לְבַשֵּׁל בְּשַׁבָּת, לָכֵן טוֹב שֶׁכָּל הַמַּאֲכָלִים יִהְיוּ מְבֻשָּׁלִים כָּל צָרְכָּם כְּבָר מֵעֶרֶב שַׁבָּת.","פֶּרֶק נ׳, הֲלָכָה א׳","בִּשּׁוּל בְּשַׁבָּת"],["נָפַל הַמִּכְסֶה מִסִּיר שֶׁהַמַּאֲכָל בּוֹ עוֹד לֹא מְבֻשָּׁל כָּל צָרְכּוֹ. מָה עוֹשִׂים?",["מַחְזִירִים אֶת הַמִּכְסֶה מִיָּד","לֹא מַחְזִירִים אֶת הַמִּכְסֶה","מַעֲבִירִים לְמָקוֹם חַם יוֹתֵר"],1,"אָסוּר לְהַחְזִיר אֶת הַמִּכְסֶה, כִּי זֶה גּוֹרֵם לַמַּאֲכָל לְהִתְבַּשֵּׁל מַהֵר יוֹתֵר. וְגַם אָסוּר לְהַעֲבִיר אֶת הַסִּיר לְמָקוֹם חַם יוֹתֵר.","פֶּרֶק נ׳, הֲלָכָה ב׳","בִּשּׁוּל בְּשַׁבָּת"],["מֵאֵיזֶה מַכְשִׁיר מֻתָּר לָקַחַת מַיִם חַמִּים בְּשַׁבָּת?",["מִתְקַן מַיִם חַמִּים הַמְּחֻבָּר לַצַּנֶּרֶת","קֻמְקוּם שֶׁמַּדְלִיקִים בְּשַׁבָּת","מֵחַם חַשְׁמַלִּי עַל מַצַּב שַׁבָּת"],2,"מַשְׁאִירִים מֵחַם עַל מַצַּב ״שַׁבָּת״ אוֹ מַיִם עַל פְּלָטָה. מִתְקַן הַמְּחֻבָּר לַצַּנֶּרֶת אָסוּר, כִּי נִכְנָסִים אֵלָיו מַיִם קָרִים שֶׁמִּתְבַּשְּׁלִים.","פֶּרֶק נ׳, הֲלָכוֹת ג׳-ד׳","בִּשּׁוּל בְּשַׁבָּת"],["מָה מֻתָּר לְחַמֵּם עַל הַפְּלָטָה בְּשַׁבָּת, אִם הִתְבַּשֵּׁל כָּל צָרְכּוֹ לִפְנֵי שַׁבָּת?",["שְׁנִיצֶל מְבֻשָּׁל","מָרָק שֶׁהִתְקָרֵר","מַיִם שֶׁהִתְקָרְרוּ"],0,"״אֵין בִּשּׁוּל אַחַר בִּשּׁוּל בְּיָבֵשׁ״ – מֻתָּר לְחַמֵּם שְׁנִיצֶל. אֲבָל ״יֵשׁ בִּשּׁוּל אַחַר בִּשּׁוּל בְּלַח״ – אָסוּר לְהַרְתִּיחַ מָרָק אוֹ מַיִם שֶׁהִתְקָרְרוּ.","פֶּרֶק נ׳, הֲלָכוֹת ה׳-ו׳","בִּשּׁוּל בְּשַׁבָּת"],["סִיר מָרָק חַם הוּרַד מֵהַפְּלָטָה. מֻתָּר לְהוֹסִיף לְתוֹכוֹ תַּבְלִינִים?",["כֵּן, הוּא כְּבָר לֹא עַל הָאֵשׁ","רַק מְעַט תַּבְלִינִים","לֹא, הוּא כְּלִי רִאשׁוֹן וּמְבַשֵּׁל"],2,"כְּלִי רִאשׁוֹן מְבַשֵּׁל כָּל עוֹד הוּא חַם בְּחֹם שֶׁהַיָּד סוֹלֶדֶת בּוֹ, אֲפִלּוּ אַחֲרֵי שֶׁהוֹרִידוּ אוֹתוֹ מֵהָאֵשׁ.","פֶּרֶק נ׳, הֲלָכָה ז׳","בִּשּׁוּל בְּשַׁבָּת"],["שׁוֹפְכִים מַיִם רוֹתְחִים מִכְּלִי רִאשׁוֹן עַל דָּבָר שֶׁאֵינוֹ מְבֻשָּׁל. מָה קוֹרֶה?",["הַחֵלֶק הַחִיצוֹנִי מִתְבַּשֵּׁל","שׁוּם דָּבָר לֹא מִתְבַּשֵּׁל","רַק הַמַּיִם מִתְקָרְרִים"],0,"״עֵרוּי מִכְּלִי רִאשׁוֹן מְבַשֵּׁל כְּדֵי קְלִפָּה״ – הַחֵלֶק הַחִיצוֹנִי מִתְבַּשֵּׁל, וְלָכֵן אָסוּר.","פֶּרֶק נ׳, הֲלָכָה ח׳","בִּשּׁוּל בְּשַׁבָּת"],["מָזְגוּ מָרָק מֵהַסִּיר לִקְעָרָה, וּמֵהַקְּעָרָה לְכוֹס. אֵיזֶה מֵהֶם הוּא כְּלִי שֵׁנִי?",["הַסִּיר","הַקְּעָרָה","הַכּוֹס"],1,"הַסִּיר הוּא כְּלִי רִאשׁוֹן, הַקְּעָרָה כְּלִי שֵׁנִי, וְהַכּוֹס כְּלִי שְׁלִישִׁי. לְדַעַת רֹב הַפּוֹסְקִים כְּלִי שְׁלִישִׁי אֵינוֹ מְבַשֵּׁל כְּלָל.","פֶּרֶק נ׳, הֲלָכוֹת ט׳-י׳","בִּשּׁוּל בְּשַׁבָּת"],["אֵיךְ ״יֵשׁ נוֹהֲגִים״ לְהָכִין תֵּה בְּשַׁבָּת?",["שַׂקִּית בְּכוֹס וְשׁוֹפְכִים עָלֶיהָ מֵהַמֵּחַם","שָׂמִים שַׂקִּית יְשִׁירוֹת בַּמֵּחַם","מֵהַמֵּחַם לְכוֹס, לְכוֹס נוֹסֶפֶת, וְאָז שַׂקִּית"],2,"שׁוֹפְכִים מֵהַמֵּחַם לְכוֹס, מֵהַכּוֹס לְכוֹס נוֹסֶפֶת, וְרַק אָז שָׂמִים אֶת הַשַּׂקִּית. אָסוּר לִשְׁפֹּךְ מֵהַמֵּחַם עַל עֲלֵי תֵּה.","פֶּרֶק נ׳, הֲלָכָה י״א׳","בִּשּׁוּל בְּשַׁבָּת"],["לְפִי הַמַּחְמִירִים, מָתַי שָׂמִים סֻכָּר אוֹ אַבְקַת שׁוֹקוֹ?",["לִפְנֵי שֶׁשּׁוֹפְכִים אֶת הַמַּיִם","אַחֲרֵי שֶׁשּׁוֹפְכִים אֶת הַמַּיִם לַכּוֹס","בְּתוֹךְ הַמֵּחַם עַצְמוֹ"],1,"יֵשׁ אוֹמְרִים שֶׁמֻּתָּר לִשְׁפֹּךְ יְשִׁירוֹת, וְיֵשׁ מַחְמִירִים: קֹדֶם מַיִם לַכּוֹס וְאַחַר כָּךְ הַסֻּכָּר אוֹ הָאַבְקָה. וְהַמַּחְמִיר תָּבוֹא עָלָיו בְּרָכָה.","פֶּרֶק נ׳, הֲלָכָה י״ב׳","בִּשּׁוּל בְּשַׁבָּת"],["מָה מֻתָּר לְהוֹסִיף לְכוֹס שֶׁיֵּשׁ בָּהּ מַשְׁקֶה חַם?",["עֲלֵי תֵּה יְבֵשִׁים","חָלָב","אֹרֶז לֹא מְבֻשָּׁל"],1,"מֻתָּר לְהוֹסִיף חָלָב אוֹ מַיִם קָרִים לְתוֹךְ כּוֹס שֶׁיֵּשׁ בָּהּ מַשְׁקֶה חַם.","פֶּרֶק נ׳, הֲלָכָה י״ג׳","בִּשּׁוּל בְּשַׁבָּת"],["מָה אָסוּר לַעֲשׂוֹת בְּשַׁבָּת, לְפִי ״מִמְּצוֹא חֶפְצְךָ״?",["לַעֲסֹק בְּעִסְקֵי מִסְחָר","לִלְמֹד תּוֹרָה","לְהִתְפַּלֵּל בְּבֵית הַכְּנֶסֶת"],0,"חֲפָצֶיךָ (עִסּוּקֶיךָ) אֲסוּרִים, וְלָכֵן אָסוּר לַעֲסֹק בְּשַׁבָּת בְּצָרְכֵי חֹל כְּמוֹ מִסְחָר, כְּדֵי שֶׁנִּהְיֶה פְּנוּיִים לְכַבֵּד אֶת הַשַּׁבָּת.","פֶּרֶק נ״א, הֲלָכָה א׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["אֵיזֶה שָׂכָר אָסוּר לְשַׁלֵּם?",["שָׂכָר עַל עֲבוֹדָה בְּיוֹם רִאשׁוֹן","שָׂכָר עַל עֲבוֹדָה שֶׁנַּעֲשְׂתָה בְּשַׁבָּת","שָׂכָר עַל עֲבוֹדָה בְּיוֹם שֵׁנִי"],1,"אָסוּר לְשַׁלֵּם ״שְׂכַר שַׁבָּת״, כְּלוֹמַר שָׂכָר הַנִּתָּן עַל עֲבוֹדָה שֶׁנַּעֲשְׂתָה בְּשַׁבָּת.","פֶּרֶק נ״א, הֲלָכָה ב׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["מֶלְצַר בְּמָלוֹן עוֹבֵד גַּם בְּשַׁבָּת. אֵיךְ מֻתָּר לְשַׁלֵּם לוֹ?",["תַּשְׁלוּם נִפְרָד רַק עַל הַשַּׁבָּת","לָתֵת לוֹ כֶּסֶף בְּתוֹךְ הַשַּׁבָּת","בְּהַבְלָעָה עִם שְׂכַר יְמֵי הַחֹל"],2,"מְשַׁלְּמִים לוֹ בְּבַת אַחַת עַל יְמֵי הַחֹל וְעַל הַשַּׁבָּת, וּשְׂכַר הַשַּׁבָּת ״נִבְלָע״ בִּשְׂכַר הָעֲבוֹדָה הַכּוֹלֵל.","פֶּרֶק נ״א, הֲלָכָה ג׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["לְמִי מֻתָּר לְשַׁלֵּם שְׂכַר שַׁבָּת?",["לְמוֹכֵר בַּחֲנוּת","לְחַזָּן וּלְתוֹקֵעַ בַּשּׁוֹפָר","לְנַגָּר שֶׁבּוֹנֶה אָרוֹן"],1,"מֻתָּר לְשַׁלֵּם שְׂכַר שַׁבָּת עַל דְּבַר מִצְוָה, כְּמוֹ לְחַזָּנִים וְתוֹקְעִים, וְגַם לְרוֹפְאִים וּלְאַנְשֵׁי בִּטָּחוֹן שֶׁעוֹסְקִים בְּהַצָּלַת נְפָשׁוֹת.","פֶּרֶק נ״א, הֲלָכוֹת ד׳-ה׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["אֵיזוֹ מַתָּנָה מֻתָּר לָתֵת בְּשַׁבָּת?",["כַּדּוּר חָדָשׁ לְמִשְׂחָק","מְכוֹנִית צַעֲצוּעַ","סִדּוּר אוֹ חֻמָּשׁ"],2,"מַתָּנָה אֲסוּרָה כִּי הִיא דּוֹמָה לְמִקָּח וּמִמְכָּר, אֲבָל מַתָּנָה לְצֹרֶךְ מִצְוָה (סִדּוּר, חֻמָּשׁ) אוֹ לְצֹרֶךְ הַשַּׁבָּת מֻתֶּרֶת.","פֶּרֶק נ״א, הֲלָכָה ו׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["רוֹצִים לָתֵת לְחָבֵר מַתָּנָה רְגִילָה בְּשַׁבָּת. מָה עוֹשִׂים?",["מְזַכִּים לוֹ אוֹתָהּ דֶּרֶךְ אָדָם אַחֵר בְּיוֹם שִׁשִּׁי","נוֹתְנִים לוֹ בְּשַׁבָּת בַּבֹּקֶר","מַשְׁאִירִים לוֹ פֶּתֶק בְּשַׁבָּת"],0,"בְּיוֹם שִׁשִּׁי נוֹתְנִים אֶת הַמַּתָּנָה לְאָדָם אַחֵר שֶׁמֵּרִים אוֹתָהּ טֶפַח וְזוֹכֶה בָּהּ עֲבוּר הֶחָבֵר, וְכָךְ הִיא שֶׁלּוֹ כְּבָר לִפְנֵי שַׁבָּת.","פֶּרֶק נ״א, הֲלָכָה ז׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["עַל מָה מֻתָּר לְדַבֵּר בְּשַׁבָּת?",["מְחִיר שֶׁל אוֹפַנַּיִם חֲדָשִׁים","מְכִירַת עֲלִיּוֹת לַתּוֹרָה","תִּכְנוּן קְנִיּוֹת לְמָחָר"],1,"מֻתָּר לְדַבֵּר בְּחֶפְצֵי שָׁמַיִם, כְּמוֹ צְדָקָה, שִׁדּוּכִים, הַתְרָמָה לְמוֹסְדוֹת תּוֹרָה וּמְכִירַת עֲלִיּוֹת לַתּוֹרָה.","פֶּרֶק נ״א, הֲלָכָה ח׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["אֵיזֶה מִשְׁפָּט אָסוּר לוֹמַר בְּשַׁבָּת?",["״שַׁבַּת שָׁלוֹם!״","״בּוֹאוּ נִלְמַד פָּרָשָׁה״","״מָחָר אֶקְנֶה דָּבָר זֶה״"],2,"״לֹא יִהְיֶה דִּבּוּרְךָ בְּשַׁבָּת כְּדִבּוּרְךָ בְּחֹל״, לָכֵן אָסוּר לְתַכְנֵן מִשַּׁבָּת לְחֹל. הִרְהוּר בַּלֵּב בִּלְבַד מֻתָּר, אַךְ רָאוּי לְהִמָּנַע גַּם מִמֶּנּוּ.","פֶּרֶק נ״א, הֲלָכוֹת ט׳-י׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["בַּמֶּה רָאוּי לְהַרְבּוֹת בְּשַׁבָּת?",["בְּלִמּוּד תּוֹרָה וּפִרְקֵי תְּהִלִּים","בִּקְרִיאַת עִתּוֹנִים","בְּשִׂיחָה בְּטֵלָה"],0,"הַשַּׁבָּת הִיא יוֹם מְנוּחָה וּקְדֻשָּׁה, וְרָאוּי לְהַרְבּוֹת בָּהּ בְּתוֹרָה, בְּפָרָשַׁת הַשָּׁבוּעַ וּבִתְהִלִּים. וְהַנִּמְנָע מֵעִתּוֹנִים וְלוֹמֵד תּוֹרָה – תָּבוֹא עָלָיו בְּרָכָה.","פֶּרֶק נ״א, הֲלָכוֹת י״א-י״ב","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["מֵאֵיפֹה לָמַדְנוּ שֶׁאָסוּר לְהוֹצִיא מֵרְשׁוּת לִרְשׁוּת בְּשַׁבָּת?",["מֵהַתְּרוּמוֹת לַמִּשְׁכָּן שֶׁהוּעֲבְרוּ מֵהָאֹהָלִים לְמַחֲנֵה לְוִיָּה","מֵהַמָּן שֶׁיָּרַד בַּמִּדְבָּר","מִבְּנִיַּת בֵּית הַמִּקְדָּשׁ בִּירוּשָׁלַיִם"],0,"הַתּוֹרְמִים הֶעֱבִירוּ אֶת הַתְּרוּמוֹת מֵהָאֹהָלִים שֶׁלָּהֶם (רְשׁוּת הַיָּחִיד) לְמַחֲנֵה לְוִיָּה (רְשׁוּת הָרַבִּים), וְכָל מְלָאכָה שֶׁהָיְתָה בַּמִּשְׁכָּן נֶאֶסְרָה בְּשַׁבָּת.","פֶּרֶק נ״ב, הֲלָכָה א׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["לָמָּה נֶאֱסַר לְהוֹצִיא מֵרְשׁוּת לִרְשׁוּת?",["כְּדֵי שֶׁנְּמַהֵר לְבֵית הַכְּנֶסֶת","כְּדֵי שֶׁכָּל אֶחָד יִשְׁבֹּת בְּבֵיתוֹ עִם מִשְׁפַּחְתּוֹ","כְּדֵי שֶׁלֹּא יִתְעַיְּפוּ הַיְּלָדִים"],1,"הָאִסּוּר נוֹעָד שֶׁכָּל אָדָם יִשְׁבֹּת בְּבֵיתוֹ עִם בְּנֵי מִשְׁפַּחְתּוֹ, וְכָךְ מִתְחַזְּקִים יְסוֹדוֹת הַמִּשְׁפָּחָה וְלִמּוּד הַתּוֹרָה.","פֶּרֶק נ״ב, הֲלָכָה ב׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["אֵיזֶה מָקוֹם הוּא רְשׁוּת הַיָּחִיד?",["רְחוֹב רָחָב וּפָתוּחַ","שְׂפַת הַיָּם","חָצֵר מֻקֶּפֶת גָּדֵר"],2,"בַּיִת וְחָצֵר עִם גָּדֵר הֵם רְשׁוּת הַיָּחִיד. גַּם בּוֹר עָמֹק אוֹ תֵּל גָּבוֹהַּ בְּשִׁעוּר עֲשָׂרָה טְפָחִים וְרֹחַב אַרְבָּעָה עַל אַרְבָּעָה נֶחְשָׁבִים רְשׁוּת הַיָּחִיד.","פֶּרֶק נ״ב, הֲלָכוֹת ג׳-ה׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָה מֵאֵלֶּה הוּא רְשׁוּת הָרַבִּים?",["שׁוּק רָחָב בְּלִי תִּקְרָה וּבְלִי חוֹמָה","חֶדֶר בַּבַּיִת","בּוֹר עָמֹק"],0,"רְשׁוּת הָרַבִּים הִיא רְחוֹב, שׁוּק אוֹ רְחָבָה בְּרֹחַב שֵׁשׁ עֶשְׂרֵה אַמּוֹת, שֶׁאֵין לָהֶם תִּקְרָה וְאֵין סְבִיבָם חוֹמָה.","פֶּרֶק נ״ב, הֲלָכָה ו׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["אֵיזֶה מָקוֹם הוּא כַּרְמְלִית?",["בַּיִת","בִּקְעָה פְּתוּחָה","פַּח אַשְׁפָּה קָטָן"],1,"כַּרְמְלִית אֵינָהּ רְשׁוּת הַיָּחִיד וְלֹא רְשׁוּת הָרַבִּים, כְּמוֹ יָם וּבִקְעָה. מִן הַתּוֹרָה אָסוּר לְהוֹצִיא מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים, וַחֲכָמִים אָסְרוּ גַּם מִכַּרְמְלִית.","פֶּרֶק נ״ב, הֲלָכוֹת ז׳, ט׳, י׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָה מֵאֵלֶּה הוּא מְקוֹם פְּטוּר בָּרְחוֹב?",["פַּח אַשְׁפָּה צַר וְגָבוֹהַּ","מִגְרָשׁ גָּדוֹל","חָצֵר עִם גָּדֵר"],0,"דָּבָר בִּרְשׁוּת הָרַבִּים אוֹ בְּכַרְמְלִית, גָּבוֹהַּ שְׁלוֹשָׁה טְפָחִים וְצַר מֵאַרְבָּעָה עַל אַרְבָּעָה, כְּמוֹ פַּח אַשְׁפָּה, הוּא מְקוֹם פְּטוּר. מֻתָּר לְהוֹצִיא אֵלָיו וּמִמֶּנּוּ.","פֶּרֶק נ״ב, הֲלָכוֹת ח׳, י״א","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["יֶלֶד הוֹלֵךְ בִּרְשׁוּת הָרַבִּים בְּלִי עֵרוּב. מָה אָסוּר לוֹ לָשֵׂאת?",["אֶת הַכִּפָּה שֶׁעַל רֹאשׁוֹ","אֶת הַחֻלְצָה שֶׁהוּא לוֹבֵשׁ","מַפְתֵּחַ אוֹ פִּצּוּחִים בַּכִּיס"],2,"אָסוּר מֵהַתּוֹרָה לְהַעֲבִיר חֵפֶץ בִּרְשׁוּת הָרַבִּים אַרְבַּע אַמּוֹת אוֹ יוֹתֵר, כְּמוֹ מַפְתֵּחַ אוֹ פִּצּוּחִים. מִדִּבְרֵי חֲכָמִים הָאִסּוּר קַיָּם גַּם בְּכַרְמְלִית.","פֶּרֶק נ״ב, הֲלָכוֹת י״ב-י״ג","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["עִם מָה מֻתָּר לָלֶכֶת בָּרְחוֹב בְּלִי עֵרוּב?",["סֵפֶר","מִשְׁקְפֵי רְאִיָּה עַל הָעֵינַיִם","כַּדּוּר"],1,"דְּבָרִים שֶׁבְּטֵלִים לְגוּף הָאָדָם, כְּמוֹ בְּגָדִים וּמִשְׁקְפֵי רְאִיָּה, אֵינָם בָּאִסּוּר. וּבִרְשׁוּת הַיָּחִיד מֻתָּר לְהַעֲבִיר חֲפָצִים בְּלִי מִגְבֶּלַת מֶרְחָק.","פֶּרֶק נ״ב, הֲלָכוֹת י״ד-ט״ו","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָה עוֹשִׂים כְּדֵי לַהֲפֹךְ עִיר לִרְשׁוּת הַיָּחִיד גְּדוֹלָה?",["סוֹגְרִים אֶת כָּל הַחֲנֻיּוֹת","מַקִּיפִים אוֹתָהּ בְּעַמּוּדִים וְחוּטִים","שׁוֹתְלִים עֵצִים בָּרְחוֹבוֹת"],1,"מַקִּיפִים אֶת הָעִיר בְּעַמּוּדִים וְחוּטִים, וְזוֹ ״צוּרַת הַפֶּתַח״, וּבִלְשׁוֹן הָעָם: ״עֵרוּב״.","פֶּרֶק נ״ב, הֲלָכָה ט״ז","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["עַד כַּמָּה מֻתָּר לְהִתְרַחֵק מֵהָעִיר בְּשַׁבָּת מִדִּבְרֵי חֲכָמִים?",["עֶשֶׂר אַמּוֹת","מֵאָה קִילוֹמֶטְרִים","אַלְפַּיִם אַמָּה"],2,"מִדִּבְרֵי חֲכָמִים אָסוּר לָצֵאת מֵהָעִיר יוֹתֵר מֵאַלְפַּיִם אַמָּה (כִּ־960 מֶטְרִים). מֵהַתּוֹרָה הָאִסּוּר הוּא יוֹתֵר מִשְּׁנֵים עָשָׂר מִיל.","פֶּרֶק נ״ב, הֲלָכָה י״ז","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָה פֵּרוּשׁ הַמִּלָּה ״מֻקְצֶה״?",["מְרֻחָק וּמֻפְרָשׁ","מוּכָן וּמְזֻמָּן","יָקָר וְחָשׁוּב"],0,"בֵּאוּר הַמִּלָּה ״מֻקְצֶה״ הוּא מְרֻחָק וּמֻפְרָשׁ – דָּבָר שֶׁלֹּא מִשְׁתַּמְּשִׁים בּוֹ בְּשַׁבָּת, וְאָסוּר לְטַלְטְלוֹ.","פֶּרֶק נ״ג, הֲלָכָה א׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["לָמָּה אָסְרוּ חֲכָמִים לְטַלְטֵל מֻקְצֶה בְּשַׁבָּת?",["כְּדֵי שֶׁהַבַּיִת יִהְיֶה נָקִי","שֶׁלֹּא תִּהְיֶה הַשַּׁבָּת כְּיוֹם חֹל","כְּדֵי שֶׁלֹּא נִתְעַיֵּף מֵהַלִּמּוּד"],1,"״שֶׁלֹּא יְהֵא טִלְטוּלְךָ שֶׁל שַׁבָּת כְּטִלְטוּלְךָ שֶׁל חֹל״ – שֶׁלֹּא נִטְרַח כָּל הַיּוֹם בְּהַעֲבָרַת כֵּלִים, וְתִבָּטֵל מְנוּחַת הַשַּׁבָּת.","פֶּרֶק נ״ג, הֲלָכָה ב׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["אֵיזֶה מֵאֵלֶּה הוּא ״כְּלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר״?",["כּוֹס","כַּף","מִסְפָּרַיִם"],2,"״כְּלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר״ הוּא הַסּוּג הָרִאשׁוֹן בִּרְשִׁימַת סוּגֵי הַמֻּקְצֶה. זֶה כְּלִי שֶׁמִּשְׁתַּמְּשִׁים בּוֹ בְּדֶרֶךְ כְּלָל לִמְלָאכָה הָאֲסוּרָה בְּשַׁבָּת, כְּמוֹ פַּטִּישׁ, עֵט וּמִסְפָּרַיִם.","פֶּרֶק נ״ג, הֲלָכוֹת ג׳-ד׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["פַּטִּישׁ נִשְׁאַר בֶּחָצֵר, וְהִתְחִיל לָרֶדֶת גֶּשֶׁם. אֵיךְ מֻתָּר לְהַכְנִיס אוֹתוֹ, בִּמְקוֹם צֹרֶךְ?",["בַּיָּדַיִם, כָּרָגִיל","בְּשִׁנּוּי, בְּעֶזְרַת הַמַּרְפֵּקִים","אָסוּר בְּשׁוּם אֹפֶן"],1,"אָסוּר לְטַלְטֵל בַּיָּדַיִם כְּלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר כְּדֵי לִשְׁמֹר עָלָיו מִגְּשָׁמִים. בִּמְקוֹם צֹרֶךְ, מֻתָּר לְטַלְטְלוֹ בְּשִׁנּוּי – בְּעֶזְרַת הַמַּרְפֵּקִים וְכַדּוֹמֶה.","פֶּרֶק נ״ג, הֲלָכָה ה׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["פַּטִּישׁ מֻנָּח עַל הַסַּפָּה, וְרוֹצִים לָשֶׁבֶת עָלֶיהָ. מָה עוֹשִׂים?",["מֻתָּר לְהָזִיז אוֹתוֹ בַּיָּדַיִם","יוֹשְׁבִים עַל הַפַּטִּישׁ","אָסוּר לָשֶׁבֶת עַל הַסַּפָּה"],0,"זֶה טִלְטוּל לְצֹרֶךְ מְקוֹמוֹ, וְלָכֵן מֻתָּר לְהָזִיז אֶת הַפַּטִּישׁ כָּרָגִיל, וּלְהַחְזִיק אוֹתוֹ בַּיָּדַיִם עַד שֶׁמַּגִּיעִים לַמָּקוֹם שֶׁבּוֹ רוֹצִים לְהָנִיחוֹ.","פֶּרֶק נ״ג, הֲלָכוֹת ו׳-ז׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["סַכִּין מְיֻחֶדֶת לְחִתּוּךְ אָמָּנוּתִי – מֻתָּר לַחְתֹּךְ בָּהּ יְרָקוֹת בְּשַׁבָּת?",["כֵּן, בְּלִי שׁוּם בְּעָיָה","רַק יְרָקוֹת קְטַנִּים","לֹא, הִיא מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס"],2,"מַקְפִּידִים שֶׁלֹּא לְהִשְׁתַּמֵּשׁ בְּסַכִּין כָּזוֹ לְשׁוּם שִׁמּוּשׁ אַחֵר, וְלָכֵן הִיא מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס, וַאֲסוּרָה אֲפִלּוּ לְצֹרֶךְ גּוּפָהּ וּמְקוֹמָהּ.","פֶּרֶק נ״ג, הֲלָכָה ח׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["יֵשׁ בַּבַּיִת אָרוֹן כָּבֵד. מָה מֻתָּר לַעֲשׂוֹת בּוֹ בְּשַׁבָּת?",["לְהָזִיז אֶת הָאָרוֹן מִמְּקוֹמוֹ","לִפְתֹּחַ וְלִסְגֹּר אֶת דַּלְתוֹתָיו","לִגְרֹר אוֹתוֹ לְחֶדֶר אַחֵר"],1,"אָרוֹן כָּבֵד שֶׁמַּקְפִּידִים לֹא לְהָזִיזוֹ מִמְּקוֹמוֹ הוּא מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס. אָסוּר לְהָזִיזוֹ, אַךְ מֻתָּר לִפְתֹּחַ וְלִסְגֹּר אֶת דַּלְתוֹתָיו.","פֶּרֶק נ״ג, הֲלָכָה ט׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["מֻתָּר לְבַעַל חֲנוּת כֵּלִים לִשְׁתּוֹת בְּשַׁבָּת מִכּוֹס שֶׁעוֹמֶדֶת לִמְכִירָה?",["לֹא, הִיא מֻקְצֶה","כֵּן, אִם יִשְׁטֹף אוֹתָהּ","כֵּן, אֲבָל רַק בַּסְּעוּדָה"],0,"סְחוֹרָה שֶׁעוֹמֶדֶת לִמְכִירָה, שֶׁמַּקְפִּידִים לֹא לְהִשְׁתַּמֵּשׁ בָּהּ, הִיא מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס – אֲפִלּוּ לִסְעוּדַת הַשַּׁבָּת.","פֶּרֶק נ״ג, הֲלָכָה י׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["מָה נִקְרָא ״מֻקְצֶה מֵחֲמַת גּוּפוֹ״?",["תַּפּוּחַ לַאֲכִילָה","כִּסֵּא לִישִׁיבָה","דָּבָר שֶׁאֵינוֹ כְּלִי וְאֵינוֹ מַאֲכָל"],2,"כָּל דָּבָר שֶׁאֵינוֹ כְּלִי הָרָאוּי לְשִׁמּוּשׁ, וְגַם אֵינוֹ רָאוּי לְמַאֲכַל אָדָם אוֹ בְּהֵמָה, הוּא מֻקְצֶה מֵחֲמַת גּוּפוֹ. אָסוּר לְטַלְטְלוֹ בַּיָּדַיִם, וּבִשְׁעַת הַצֹּרֶךְ מֻתָּר בְּשִׁנּוּי.","פֶּרֶק נ״ג, הֲלָכוֹת י״א-י״ב","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["כּוֹס נִשְׁבְּרָה לִשְׁבָרִים שֶׁאֵינָם רְאוּיִים לְשׁוּם שִׁמּוּשׁ. מֻתָּר לְטַלְטְלָם?",["כֵּן, תָּמִיד","לֹא, אָסוּר לְטַלְטְלָם","רַק מִי שֶׁשָּׁבַר אוֹתָהּ"],1,"שִׁבְרֵי כֵּלִים מֻתָּרִים בְּטִלְטוּל רַק אִם הֵם רְאוּיִים לְשִׁמּוּשׁ כָּלְשֶׁהוּ. אִם אֵינָם רְאוּיִים לְשׁוּם שִׁמּוּשׁ – אָסוּר לְטַלְטְלָם.","פֶּרֶק נ״ג, הֲלָכָה י״ג","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["כּוֹס זְכוּכִית נִשְׁבְּרָה בַּמִּסְדְּרוֹן בְּשַׁבָּת. מָה עוֹשִׂים?",["מַשְׁאִירִים אֶת הַשְּׁבָרִים עַד מוֹצָאֵי שַׁבָּת","מְסַלְּקִים אוֹתָם, וְעָדִיף בְּלִי לָגַעַת בָּהֶם יְשִׁירוֹת","אָסוּר בִּכְלָל לְהִתְקָרֵב אֲלֵיהֶם"],1,"מֻתָּר לְסַלֵּק שִׁבְרֵי כֵּלִים שֶׁעֲלוּלִים לְהַזִּיק, וּכְשֶׁאֶפְשָׁר – עָדִיף בְּלִי לָגַעַת בָּהֶם יְשִׁירוֹת.","פֶּרֶק נ״ג, הֲלָכָה י״ד","מֻקְצֶה – חֵלֶק ב׳"],["בְּמָה מֻתָּר לִילָדִים לְשַׂחֵק בְּשַׁבָּת?",["בְּאֲבָנִים מֵהֶחָצֵר שֶׁלֹּא הֻכְנוּ","בְּחֹל שֶׁל אֲתַר בְּנִיָּה","בְּאַרְגַּז חֹל"],2,"אֶת חֹל אַרְגַּז הַחֹל יִחֲדוּ לְמִשְׂחָק לִפְנֵי שַׁבָּת. אֲבָנִים שֶׁלֹּא הֻכְנוּ וְחֹל שֶׁל אֲתַר בְּנִיָּה – מֻקְצֶה.","פֶּרֶק נ״ג, הֲלָכוֹת ט״ו-ט״ז","מֻקְצֶה – חֵלֶק ב׳"],["אֵיזֶה מֵהַדְּבָרִים הָאֵלֶּה הוּא מֻקְצֶה בְּשַׁבָּת?",["דָּג לֹא מְבֻשָּׁל וּמַטְבְּעוֹת","עוּגָה אֲפוּיָה","סֵפֶר תְּהִלִּים"],0,"מַטְבְּעוֹת הֵם מֻקְצֶה גַּם אִם יִחֲדוּ אוֹתָם, וּמַאֲכָל שֶׁצָּרִיךְ בִּשּׁוּל (כְּמוֹ דָּג חַי) מֻקְצֶה לִפְנֵי הַבִּשּׁוּל.","פֶּרֶק נ״ג, הֲלָכוֹת י״ז-י״ח","מֻקְצֶה – חֵלֶק ב׳"],["בִּסְעוּדַת שַׁבָּת נִשְׁאֲרוּ עֲצָמוֹת. אֵיךְ נָכוֹן לְפַנּוֹת אוֹתָן?",["לְהָרִים כָּל עֶצֶם בַּיָּד","לְהַנִּיחַ בַּצַּלַּחַת וּלְהַעֲבִיר אֶת הַצַּלַּחַת לַפַּח","לְהַשְׁאִיר עַל הַשֻּׁלְחָן עַד מוֹצָאֵי שַׁבָּת"],1,"מַנִּיחִים אֶת הַשְּׁאֵרִיּוֹת בַּצַּלָּחוֹת, וְאָז מֻתָּר לְהַעֲבִיר אוֹתָן וְלִזְרֹק אֶת הַפְּסֹלֶת. אִם הֵן עַל הַשֻּׁלְחָן – גּוֹרְרִים בְּסַכִּין אוֹ מַזְלֵג.","פֶּרֶק נ״ג, הֲלָכוֹת י״ט-כ׳","מֻקְצֶה – חֵלֶק ב׳"],["אֵיזֶה שָׁעוֹן מֻתָּר לְטַלְטֵל בְּשַׁבָּת?",["שָׁעוֹן מְקֻלְקָל","שָׁעוֹן שֶׁפּוֹעֵל","אַף אֶחָד מֵהֶם"],1,"שְׁעוֹן יַד שֶׁפּוֹעֵל אֵינוֹ מֻקְצֶה, וְשָׁעוֹן מְקֻלְקָל – מֻקְצֶה.","פֶּרֶק נ״ג, הֲלָכָה כ״א","מֻקְצֶה – חֵלֶק ב׳"],["פָּמוֹטוֹת יְקָרִים נִשְׁאֲרוּ עַל הַשֻּׁלְחָן כִּי שָׁכְחוּ לְהָזִיז אוֹתָם לִפְנֵי שַׁבָּת. מָה מֻתָּר?",["לְהַטּוֹת אֶת הַשֻּׁלְחָן כְּדֵי לְהַפִּיל אוֹתָם","לְהָרִים אוֹתָם בַּיָּדַיִם","לְהַזִּיז אֶת הַשֻּׁלְחָן עִם הַפָּמוֹטוֹת"],0,"שֻׁלְחָן שֶׁמֻּקְצֶה עָלָיו הוּא בָּסִיס לְדָבָר הָאָסוּר, אֲבָל אִם תִּכְנְנוּ לְהָזִיז וְשָׁכְחוּ – מֻתָּר לְהַטּוֹת אוֹתוֹ וּלְהַפִּיל אֶת הַמֻּקְצֶה.","פֶּרֶק נ״ג, הֲלָכוֹת כ״ב-כ״ג","מֻקְצֶה – חֵלֶק ב׳"],["נֵר הַשַּׁבָּת כָּבָה. הַאִם מֻתָּר לְהָזִיז אֶת הַפָּמוֹט?",["כֵּן, כִּי הַנֵּר כְּבָר כָּבָה","רַק אִם הוּא קַל","לֹא, כִּי הוּא בָּסִיס לַנֵּר"],2,"הַפָּמוֹט הוּא בָּסִיס לַנֵּר, וְהַנֵּר בָּסִיס לַשַּׁלְהֶבֶת – וְלָכֵן אָסוּר לְטַלְטְלוֹ גַּם אַחֲרֵי שֶׁכָּבָה.","פֶּרֶק נ״ג, הֲלָכָה כ״ד","מֻקְצֶה – חֵלֶק ב׳"],["אֵיזֶה מֵאֵלֶּה הוּא נוֹלָד גָּמוּר?",["כְּלִי שֶׁנִּשְׁבַּר וְרָאוּי לְשִׁמּוּשׁ אַחֵר","אֵפֶר מֵעֵצִים שֶׁנִּשְׂרְפוּ","כּוֹס מַיִם מֵהַבֶּרֶז"],1,"אֵפֶר וּמַיִם שֶׁנָּטְפוּ מֵהַמַּזְגָּן הֵם נוֹלָד גָּמוּר. כְּלִי שֶׁנִּשְׁבַּר הוּא נוֹלָד לֹא גָּמוּר – מֻתָּר בְּשַׁבָּת.","פֶּרֶק נ״ג, הֲלָכָה כ״ה","מֻקְצֶה – חֵלֶק ב׳"],["בְּאֵיזוֹ כּוֹס כָּל הַדֵּעוֹת מַתִּירוֹת לָשִׂים קֻבִּיַּת קֶרַח בְּשַׁבָּת?",["כּוֹס רֵיקָה","כּוֹס עִם מִיץ","אַף כּוֹס"],1,"לְכָל הַדֵּעוֹת מֻתָּר לָשִׂים קֶרַח בְּכוֹס עִם מַשְׁקֶה, כִּי הַמַּיִם שֶׁמַּפְשִׁירִים אֵינָם נִכָּרִים. בְּכוֹס רֵיקָה – יֵשׁ מַחֲלֹקֶת.","פֶּרֶק נ״ג, הֲלָכָה כ״ו","מֻקְצֶה – חֵלֶק ב׳"],["לְפִי רַבִּים, מָה מֻתָּר לְהַכְנִיס לַמַּקְפִּיא בְּשַׁבָּת?",["תַּבְנִית קֶרַח עִם מַיִם","רַק מַקְפִּיא רֵיק","שׁוּם דָּבָר"],0,"רַבִּים מַתִּירִים, כִּי הַקֶּרַח אֵינוֹ נֶחְשָׁב נוֹלָד – כְּשֶׁיּוֹצִיאוּ אוֹתוֹ הוּא יַפְשִׁיר מִיָּד. (יֵשׁ אוֹמְרִים שֶׁאֵין לְהַכְנִיס.)","פֶּרֶק נ״ג, הֲלָכָה כ״ז","מֻקְצֶה – חֵלֶק ב׳"],["אֵיזוֹ מִצְוָה הָיְתָה הַמִּצְוָה הָרִאשׁוֹנָה שֶׁנִּצְטַוּוּ בָּהּ יִשְׂרָאֵל?",["קִדּוּשׁ הַחֹדֶשׁ","הַדְלָקַת נֵרוֹת חֲנֻכָּה","תְּקִיעַת שׁוֹפָר"],0,"הַמִּצְוָה הָרִאשׁוֹנָה הִיא לְקַדֵּשׁ אֶת הַחֹדֶשׁ עַל פִּי רְאִיַּת הַלְּבָנָה. הַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לְמֹשֶׁה אֶת הַלְּבָנָה וְאָמַר לוֹ: ״כָּזֶה רְאֵה וְקַדֵּשׁ״.","פֶּרֶק נ״ד, הֲלָכָה א׳","רֹאשׁ חֹדֶשׁ"],["מָה מַקְרִיבִים בְּרֹאשׁ חֹדֶשׁ בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם?",["סְעוּדַת פּוּרִים","קָרְבַּן מוּסָף","שְׁתֵּי הַלֶּחֶם שֶׁל שָׁבוּעוֹת"],1,"בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם מַקְרִיבִים בְּרֹאשׁ חֹדֶשׁ קָרְבַּן מוּסָף, וּבְחֵלֶק מֵהַתְּקוּפוֹת הָיָה רֹאשׁ חֹדֶשׁ מֵעֵין יוֹם טוֹב.","פֶּרֶק נ״ד, הֲלָכָה ב׳","רֹאשׁ חֹדֶשׁ"],["בִּזְמַן שֶׁמְּקַדְּשִׁים עַל פִּי הָרְאִיָּה, מָה צְרִיכִים הָעֵדִים לִרְאוֹת?",["יָרֵחַ חָדָשׁ דַּק","יָרֵחַ מָלֵא וְעָגֹל","שֶׁמֶשׁ זוֹרַחַת"],0,"בִּתְחִלַּת הַחֹדֶשׁ הָאוֹר עַל הַיָּרֵחַ דַּק, וּבְאֶמְצַע הַחֹדֶשׁ הוּא מָלֵא. שְׁנֵי עֵדִים שֶׁרָאוּ אֶת הַמּוֹלָד, חִדּוּשׁ הָאוֹר, מֵעִידִים בְּבֵית הַדִּין, וְהַחֹדֶשׁ הוּא בֶּן 29 אוֹ 30 יָמִים.","פֶּרֶק נ״ד, הֲלָכוֹת ג׳-ד׳","רֹאשׁ חֹדֶשׁ"],["אֵיזֶה חֹדֶשׁ מוֹסִיפִים בְּשָׁנָה מְעֻבֶּרֶת?",["תִּשְׁרֵי","אֲדָר","חֶשְׁוָן"],1,"הַחֹדֶשׁ שֶׁמּוֹסִיפִים הוּא תָּמִיד חֹדֶשׁ אֲדָר, וְכָךְ דּוֹחִים אֶת נִיסָן כְּדֵי שֶׁחַג הַפֶּסַח יָחוּל בָּאָבִיב.","פֶּרֶק נ״ד, הֲלָכָה ה׳","רֹאשׁ חֹדֶשׁ"],["מָה עוֹשִׂים בִּסְעוּדַת רֹאשׁ חֹדֶשׁ?",["מַרְבִּים בְּמַאֲכָלִים","צָמִים כָּל הַיּוֹם","אוֹכְלִים רַק לֶחֶם יָבֵשׁ"],0,"מִצְוָה לְהַרְבּוֹת מַאֲכָלִים בִּסְעוּדַת רֹאשׁ חֹדֶשׁ. וּכְשֶׁרֹאשׁ חֹדֶשׁ חָל בְּשַׁבָּת, מְכִינִים מָנָה נוֹסֶפֶת בִּסְעוּדַת הַשַּׁבָּת לִכְבוֹד רֹאשׁ חֹדֶשׁ.","פֶּרֶק נ״ד, הֲלָכוֹת ו׳-ז׳","רֹאשׁ חֹדֶשׁ"],["אֵיךְ רָאוּי לְהִתְלַבֵּשׁ בְּרֹאשׁ חֹדֶשׁ?",["בִּגְדֵי עֲבוֹדָה מְלֻכְלָכִים","לְבוּשׁ נָאֶה","בְּגָדִים קְרוּעִים"],1,"רָאוּי לְכַבֵּד אֶת רָאשֵׁי הֶחֳדָשִׁים בִּלְבוּשׁ נָאֶה, וְיֵשׁ נוֹהֲגִים לְהַרְבּוֹת בְּהַדְלָקַת נֵרוֹת לִכְבוֹד רֹאשׁ חֹדֶשׁ.","פֶּרֶק נ״ד, הֲלָכָה ח׳","רֹאשׁ חֹדֶשׁ"],["בְּאֵיזוֹ בְּרָכָה בְּבִרְכַּת הַמָּזוֹן אוֹמְרִים ״יַעֲלֶה וְיָבוֹא״?",["בּוֹרֵא פְּרִי הָעֵץ","שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ","בּוֹנֵה יְרוּשָׁלַיִם"],2,"בְּבִרְכַּת הַמָּזוֹן אוֹמְרִים ״יַעֲלֶה וְיָבוֹא״ בְּבִרְכַּת ״בּוֹנֵה יְרוּשָׁלַיִם״.","פֶּרֶק נ״ד, הֲלָכָה ט׳","רֹאשׁ חֹדֶשׁ"],["שָׁכַח ״יַעֲלֶה וְיָבוֹא״ בְּבִרְכַּת הַמָּזוֹן, וְנִזְכַּר לִפְנֵי ״הַטּוֹב וְהַמֵּטִיב״. מָה יַעֲשֶׂה?",["יֹאמַר ״בָּרוּךְ שֶׁנָּתַן רָאשֵׁי חֳדָשִׁים״","יֹאכַל שׁוּב לֶחֶם","לֹא יֹאמַר כְּלוּם"],0,"אִם נִזְכַּר לִפְנֵי שֶׁהִתְחִיל ״הַטּוֹב וְהַמֵּטִיב״ יֹאמַר: ״בָּרוּךְ שֶׁנָּתַן רָאשֵׁי חֳדָשִׁים לְעַמּוֹ יִשְׂרָאֵל לְזִכָּרוֹן״.","פֶּרֶק נ״ד, הֲלָכָה י׳","רֹאשׁ חֹדֶשׁ"],["בְּאֵילוּ תְּפִלּוֹת אוֹמְרִים ״יַעֲלֶה וְיָבוֹא״ בְּבִרְכַּת ״רְצֵה״?",["רַק בְּשַׁחֲרִית","עַרְבִית, שַׁחֲרִית וּמִנְחָה","רַק בְּמִנְחָה"],1,"בְּעַרְבִית, בְּשַׁחֲרִית וּבְמִנְחָה אוֹמְרִים ״יַעֲלֶה וְיָבוֹא״ בְּבִרְכַּת ״רְצֵה״.","פֶּרֶק נ״ד, הֲלָכָה י״א","רֹאשׁ חֹדֶשׁ"],["מִי שֶׁשָּׁכַח ״יַעֲלֶה וְיָבוֹא״ – בְּאֵיזוֹ תְּפִלָּה הוּא אֵינוֹ חוֹזֵר?",["בְּשַׁחֲרִית","בְּעַרְבִית","בְּמִנְחָה"],1,"בְּעַרְבִית אֵינוֹ חוֹזֵר, כִּי בֵּית הַדִּין מְקַדֵּשׁ אֶת הַחֹדֶשׁ רַק בַּיּוֹם. בְּשַׁחֲרִית וּבְמִנְחָה – חוֹזֵר לְפִי הַכְּלָלִים.","פֶּרֶק נ״ד, הֲלָכוֹת י״ב-י״ג","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["מִי שֶׁאֵינוֹ זוֹכֵר אִם אָמַר ״יַעֲלֶה וְיָבוֹא״ – מָה דִּינוֹ?",["כְּמִי שֶׁאָמַר","כְּמִי שֶׁלֹּא אָמַר","יִשְׁאַל אֶת הַחַזָּן"],1,"דִּינוֹ כְּמִי שֶׁלֹּא אָמַר, כִּי כְּכָל הַנִּרְאֶה אָמַר אֶת הַנֹּסַח הָרָגִיל, שֶׁאֵין בּוֹ ״יַעֲלֶה וְיָבוֹא״.","פֶּרֶק נ״ד, הֲלָכָה י״ד","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["מָה מִתְחַדֵּשׁ בְּרֹאשׁ חֹדֶשׁ וְרוֹמֵז לִגְאֻלַּת יִשְׂרָאֵל?",["הַשֶּׁמֶשׁ","הַכּוֹכָבִים","הַלְּבָנָה"],2,"הַלְּבָנָה הַמִּתְחַדֶּשֶׁת רוֹמֶזֶת לְהִתְחַדְּשׁוּת עַם יִשְׂרָאֵל וְלִגְאֻלָּתוֹ – וְלָכֵן אוֹמְרִים הַלֵּל.","פֶּרֶק נ״ד, הֲלָכָה ט״ו","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["אֵיךְ קוֹרְאִים אֶת הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ?",["בְּדִלּוּג","פַּעֲמַיִם","בַּלַּיְלָה"],0,"קְרִיאַת הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ הִיא מִנְהָג, וְלָכֵן קוֹרְאִים אוֹתוֹ בְּדִלּוּג.","פֶּרֶק נ״ד, הֲלָכָה ט״ז","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים – מְבָרְכִים עַל הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ?",["מְבָרְכִים תָּמִיד","רַק הַיָּחִיד מְבָרֵךְ","לֹא מְבָרְכִים"],2,"בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים לֹא מְבָרְכִים, לֹא בְּצִבּוּר וְלֹא בְּיָחִיד, כִּי אֵין מְבָרְכִים עַל הַמִּנְהָג.","פֶּרֶק נ״ד, הֲלָכָה י״ז","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים – מָה נוֹהֲגִים בְּבִרְכַּת הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ?",["מְבָרְכִים","לֹא מְבָרְכִים","מְבָרְכִים רַק בְּשַׁבָּת"],0,"בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים נוֹהֲגִים לְבָרֵךְ עַל הַהַלֵּל, בֵּין בְּצִבּוּר וּבֵין בְּיָחִיד.","פֶּרֶק נ״ד, הֲלָכָה י״ח","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["מָה הַדִּין הַבְּסִיסִי שֶׁל נָשִׁים בִּקְרִיאַת הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ?",["אֲסוּרוֹת","פְּטוּרוֹת","חַיָּבוֹת"],1,"נָשִׁים פְּטוּרוֹת, כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ. אַךְ כַּיּוֹם נָשִׁים נוֹהֲגוֹת לוֹמַר אֶת הַהַלֵּל.","פֶּרֶק נ״ד, הֲלָכָה י״ט","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["בְּאֵיזוֹ תְּנוּחָה קוֹרְאִים אֶת הַהַלֵּל?",["בִּישִׁיבָה","בְּשְׁכִיבָה","בַּעֲמִידָה"],2,"קוֹרְאִים אֶת הַהַלֵּל בַּעֲמִידָה, כִּי הוּא עֵדוּת עַל הַנִּסִּים, וְעֵדוּת נַעֲשֵׂית בַּעֲמִידָה.","פֶּרֶק נ״ד, הֲלָכָה כ׳","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["כַּמָּה עוֹלִים קוֹרְאִים לַתּוֹרָה בְּרֹאשׁ חֹדֶשׁ?",["שְׁלֹשָׁה","אַרְבָּעָה","שִׁבְעָה"],1,"בְּרֹאשׁ חֹדֶשׁ קוֹרְאִים לְאַרְבָּעָה עוֹלִים בְּפָרָשַׁת קָרְבַּן רֹאשׁ חֹדֶשׁ, וּמִצְוָה לְהִשְׁתַּדֵּל לַעֲלוֹת לַתּוֹרָה.","פֶּרֶק נ״ד, הֲלָכָה כ״א","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["בְּבִרְכַּת הַלְּבָנָה חוֹתְמִים ״מְחַדֵּשׁ חֳדָשִׁים״. עַל מָה אָנוּ מְשַׁבְּחִים אֶת ה׳?",["עַל הַגֶּשֶׁם שֶׁיּוֹרֵד בַּחֹרֶף","עַל הַסֵּדֶר שֶׁבַּבְּרִיאָה וְחִדּוּשׁ הַלְּבָנָה","עַל פְּרִי הָעֵץ הַמָּתוֹק"],1,"אָנוּ מְשַׁבְּחִים אֶת ה׳ עַל הַסֵּדֶר שֶׁבַּבְּרִיאָה, שֶׁמִּתְבַּטֵּא בְּחִדּוּשׁ הַלְּבָנָה. וּכְמוֹ שֶׁהַלְּבָנָה מִתְחַדֶּשֶׁת, כָּךְ עַם יִשְׂרָאֵל יִתְחַדֵּשׁ וְיִגָּאֵל.","פֶּרֶק נ״ה, הֲלָכוֹת א׳-ב׳","בִּרְכַּת הַלְּבָנָה"],["הֵיכָן נוֹהֲגִים לְבָרֵךְ אֶת בִּרְכַּת הַלְּבָנָה?",["בְּתוֹךְ הַבַּיִת, מִתַּחַת לַגַּג","בְּתוֹךְ הַמְּכוֹנִית","בַּחוּץ, תַּחַת כִּפַּת הַשָּׁמַיִם"],2,"יוֹצְאִים לִקְרַאת הַלְּבָנָה, כִּי הַבְּרָכָה הִיא כְּקַבָּלַת פְּנֵי הַשְּׁכִינָה, וְאֵין זֶה מְכֻבָּד לְקַבֵּל אוֹתָהּ מִתַּחַת לַגַּג.","פֶּרֶק נ״ה, הֲלָכָה ג׳","בִּרְכַּת הַלְּבָנָה"],["אֵיךְ מְבָרְכִים אֶת בִּרְכַּת הַלְּבָנָה?",["בַּעֲמִידָה וּבְרַגְלַיִם יְשָׁרוֹת","בִּישִׁיבָה עַל כִּסֵּא","בִּשְׁכִיבָה עַל הַדֶּשֶׁא"],0,"קֹדֶם מִסְתַּכְּלִים עַל הַלְּבָנָה וְנֶהֱנִים מֵאוֹרָהּ, וְאַחַר כָּךְ מְבָרְכִים בַּעֲמִידָה וּבְרַגְלַיִם יְשָׁרוֹת, בְּלִי לְהִסְתַּכֵּל בָּהּ בִּשְׁעַת הַבְּרָכָה.","פֶּרֶק נ״ה, הֲלָכָה ד׳","בִּרְכַּת הַלְּבָנָה"],["מָה נוֹהֲגִים לוֹמַר אַחֲרֵי בִּרְכַּת הַלְּבָנָה?",["״שָׁנָה טוֹבָה וּמְתוּקָה״","״דָּוִד מֶלֶךְ יִשְׂרָאֵל חַי וְקַיָּם״","״לַיְלָה טוֹב וְחָלוֹם נָעִים״"],1,"אוֹמְרִים ״דָּוִד מֶלֶךְ יִשְׂרָאֵל חַי וְקַיָּם״, כִּי מַלְכוּתוֹ נִמְשְׁלָה לַלְּבָנָה וַעֲתִידָה לְהִתְחַדֵּשׁ כְּמוֹתָהּ.","פֶּרֶק נ״ה, הֲלָכָה ה׳","בִּרְכַּת הַלְּבָנָה"],["מָתַי מְבָרְכִים אֶת בִּרְכַּת הַלְּבָנָה?",["בַּצָּהֳרַיִם, כְּשֶׁהַשֶּׁמֶשׁ חַמָּה","בִּזְרִיחַת הַשֶּׁמֶשׁ","בַּלַּיְלָה, כְּשֶׁהַלְּבָנָה זוֹרַחַת"],2,"מְבָרְכִים בַּלַּיְלָה, בְּעֵת שֶׁהַלְּבָנָה זוֹרַחַת וְנֶהֱנִים מֵאוֹרָהּ, וְאֶפְשָׁר לְבָרֵךְ כָּל הַלַּיְלָה, אֲפִלּוּ אַחַר חֲצוֹת.","פֶּרֶק נ״ה, הֲלָכָה ו׳","בִּרְכַּת הַלְּבָנָה"],["לְפִי מִנְהַג קְהִלּוֹת הַסְּפָרַדִּים, כַּמָּה יָמִים מְחַכִּים מִמּוֹלַד הַלְּבָנָה עַד שֶׁמְּבָרְכִים?",["שִׁבְעָה יָמִים","יוֹם אֶחָד","שְׁלוֹשִׁים יוֹם"],0,"הַסְּפָרַדִּים מְבָרְכִים אַחֲרֵי שִׁבְעָה יָמִים מִן הַמּוֹלָד, וְרֹב הָאַשְׁכְּנַזִּים כְּבָר אַחֲרֵי שְׁלוֹשָׁה יָמִים, כִּי אָז כְּבָר נֶהֱנִים מֵאוֹרָהּ.","פֶּרֶק נ״ה, הֲלָכָה ז׳","בִּרְכַּת הַלְּבָנָה"],["עַד מָתַי אֶפְשָׁר לְבָרֵךְ עַל הַלְּבָנָה?",["רַק בַּלַּיְלָה הָרִאשׁוֹן","עַד הַלַּיְלָה הַשִּׁשָּׁה עָשָׂר, כְּשֶׁהִיא עוֹד גְּדֵלָה","עַד סוֹף הַחֹדֶשׁ"],1,"בְּמֶשֶׁךְ חֲמִשָּׁה עָשָׂר יָמִים הַלְּבָנָה הוֹלֶכֶת וּגְדֵלָה, וּמֵאָז הִיא פּוֹחֶתֶת. לָכֵן מְבָרְכִים עַד הַלַּיְלָה הַשִּׁשָּׁה עָשָׂר, לֹא כּוֹלֵל.","פֶּרֶק נ״ה, הֲלָכָה ח׳","בִּרְכַּת הַלְּבָנָה"],["מָתַי נוֹהֲגִים לְקַדֵּשׁ אֶת הַלְּבָנָה, וּבְאֵילוּ בְּגָדִים?",["בְּעֶרֶב שַׁבָּת, בְּבִגְדֵי עֲבוֹדָה","בְּמוֹצָאֵי שַׁבָּת, בִּבְגָדִים נָאִים","בְּיוֹם רִאשׁוֹן בַּבֹּקֶר, בְּפִיגָ׳מָה"],1,"נוֹהֲגִים לְקַדֵּשׁ בְּמוֹצָאֵי שַׁבָּת כִּי אָז לְבוּשִׁים בִּבְגָדִים נָאִים, וְגַם בְּיוֹם חֹל רָאוּי לִלְבֹּשׁ בְּגָדִים נָאִים. בְּתִשְׁרֵי מְבָרְכִים בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים וּבְאָב בְּמוֹצָאֵי תִּשְׁעָה בְּאָב.","פֶּרֶק נ״ה, הֲלָכוֹת ט׳-י׳","בִּרְכַּת הַלְּבָנָה"],["עַל אֵיזוֹ לְבָנָה מְבָרְכִים לְפִי כָּל הַמִּנְהָגִים?",["לְבָנָה שֶׁלֹּא מְכֻסָּה בַּעֲנָנִים כְּלָל","לְבָנָה מֻסְתֶּרֶת לְגַמְרֵי בַּעֲנָנִים עָבִים","לַיְלָה שֶׁאֵין בּוֹ לְבָנָה בִּכְלָל"],0,"יֵשׁ נוֹהֲגִים לְבָרֵךְ רַק כְּשֶׁאֵין עַל הַלְּבָנָה עֲנָנִים כְּלָל, וְיֵשׁ שֶׁמְּבָרְכִים גַּם עִם עֲנָנִים דַּקִּים, בִּתְנַאי שֶׁנֶּהֱנִים מֵאוֹרָהּ.","פֶּרֶק נ״ה, הֲלָכָה י״א","בִּרְכַּת הַלְּבָנָה"],["מִי פְּטוּרוֹת מִבִּרְכַּת הַלְּבָנָה, וְאֶת מִי טוֹב לְחַנֵּךְ לְבָרֵךְ?",["כֻּלָּם פְּטוּרִים מִן הַבְּרָכָה","הַקְּטַנִּים פְּטוּרִים וְאֵין לְחַנְּכָם","נָשִׁים פְּטוּרוֹת, וְאֶת הַקְּטַנִּים טוֹב לְחַנֵּךְ"],2,"נָשִׁים פְּטוּרוֹת, כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ, וְנָהֲגוּ שֶׁלֹּא לְבָרֵךְ עָלֶיהָ. וְאֶת הַקְּטַנִּים טוֹב לְחַנֵּךְ לְבָרֵךְ.","פֶּרֶק נ״ה, הֲלָכוֹת י״ב-י״ג","בִּרְכַּת הַלְּבָנָה"],["בְּמָה עוֹסֶקֶת פָּרָשַׁת הַחֹדֶשׁ, הַפָּרָשָׁה הָרְבִיעִית?",["בְּהִטַּהֲרוּת מִטֻּמְאַת מֵת","בְּהִלְכוֹת הַפֶּסַח","בְּמַתַּן תּוֹרָה בְּהַר סִינַי"],1,"פָּרָשַׁת הַחֹדֶשׁ עוֹסֶקֶת בְּהִלְכוֹת הַפֶּסַח, וּפָרָשַׁת פָּרָה עוֹסֶקֶת בְּהִטַּהֲרוּת מִטֻּמְאַת מֵת.","פֶּרֶק נ״ו, הֲלָכָה א׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["מָה הוּקַם בְּאֶחָד בְּנִיסָן, וּבִגְלָלוֹ הַיָּמִים הָרִאשׁוֹנִים שֶׁל נִיסָן הֵם יְמֵי שִׂמְחָה?",["הַמִּשְׁכָּן","חוֹמַת הָעִיר","אֹהֶל לַחֲתֻנָּה"],0,"בְּאֶחָד בְּנִיסָן הוּקַם הַמִּשְׁכָּן, וּשְׁנֵים עָשָׂר הַנְּשִׂיאִים הִקְרִיבוּ קָרְבָּנָם, יוֹם לְכָל שֵׁבֶט. וְכֵיוָן שֶׁרֹב הַחֹדֶשׁ עָבַר בְּשִׂמְחָה וּבִקְדֻשָּׁה, כָּל הַחֹדֶשׁ נֶחְשָׁב יְמֵי שִׂמְחָה.","פֶּרֶק נ״ו, הֲלָכוֹת ב׳-ג׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["מָה אֵין עוֹשִׂים בְּחֹדֶשׁ נִיסָן?",["קוֹרְאִים בַּתּוֹרָה","מִתְפַּלְּלִים שַׁחֲרִית","אוֹמְרִים תַּחֲנוּן"],2,"בְּחֹדֶשׁ נִיסָן אֵין אוֹמְרִים תַּחֲנוּן, אֵין מַסְפִּידִים וְאֵין מִתְעַנִּים, כִּי הוּא חֹדֶשׁ שֶׁל שִׂמְחָה.","פֶּרֶק נ״ו, הֲלָכָה ד׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["מָה נוֹהֲגִים לִקְרֹא בְּיוֹם י״ג בְּנִיסָן?",["אֶת פְּסוּקֵי הַדְלָקַת הַמְּנוֹרָה","אֶת שִׁירַת הַיָּם","אֶת מְגִלַּת אֶסְתֵּר"],0,"מֵא׳ וְעַד י״ב בְּנִיסָן קוֹרְאִים אֶת פָּרָשַׁת הַנָּשִׂיא שֶׁל אוֹתוֹ יוֹם, וּבְי״ג בְּנִיסָן קוֹרְאִים מִפָּרָשַׁת בְּהַעֲלֹתְךָ אֶת פְּסוּקֵי הַדְלָקַת הַמְּנוֹרָה.","פֶּרֶק נ״ו, הֲלָכָה ה׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["מָה לָקְחָה כָּל מִשְׁפָּחָה בְּשַׁבָּת הַגָּדוֹל בְּמִצְרַיִם?",["עֵגֶל","שֶׂה","יוֹנָה"],1,"בְּשַׁבָּת הַגָּדוֹל לָקְחָה כָּל מִשְׁפָּחָה שֶׂה לְפֶסַח מִצְרַיִם, וְאַף שֶׁעָמְדוּ לִשְׁחֹט אֶת אֱלֹהֵי מִצְרַיִם – הַמִּצְרִים לֹא יָכְלוּ לַעֲשׂוֹת לָהֶם דָּבָר. זֶה הַנֵּס הַגָּדוֹל!","פֶּרֶק נ״ו, הֲלָכָה ו׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["מִי דּוֹרֵשׁ לַצִּבּוּר בְּשַׁבָּת הַגָּדוֹל?",["הַגַּבַּאי","הַחַזָּן","הָרַב"],2,"בְּשַׁבָּת הַגָּדוֹל הָרַב דּוֹרֵשׁ לַצִּבּוּר בְּרֹב עַם, בְּהִלְכוֹת הַפֶּסַח, בִּגְדֻלַּת הֶחָג וּבְנִסֵּי יְצִיאַת מִצְרַיִם.","פֶּרֶק נ״ו, הֲלָכָה ז׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["עַל אֵיזֶה עֵץ מְבָרְכִים בִּרְכַּת הָאִילָנוֹת?",["עֵץ סְרָק גָּבוֹהַּ","עֵץ פְּרִי פּוֹרֵחַ","עֵץ עָרֹם בַּחֹרֶף"],1,"כְּשֶׁרוֹאִים בְּנִיסָן אִילָנוֹת פְּרִי מְלַבְלְבִים (פּוֹרְחִים) מְבָרְכִים ״שֶׁלֹּא חִסַּר בְּעוֹלָמוֹ כְּלוּם״. עַל אִילָנוֹת סְרָק לֹא מְבָרְכִים.","פֶּרֶק נ״ו, הֲלָכוֹת ח׳-ט׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["דָּנִי רוֹאֶה שְׁנֵי עֲצֵי תַּפּוּחַ עִם פְּרָחִים. הַאִם יְבָרֵךְ?",["כֵּן, אֲפִלּוּ שֶׁהֵם מֵאוֹתוֹ מִין","לֹא, צָרִיךְ שְׁנֵי מִינִים שׁוֹנִים","לֹא, צָרִיךְ לְחַכּוֹת לְפֵרוֹת"],0,"מְבָרְכִים עַל שְׁנֵי אִילָנוֹת פּוֹרְחִים, אֲפִלּוּ מֵאוֹתוֹ מִין. לְכַתְּחִלָּה מְבָרְכִים כְּשֶׁרוֹאִים אֶת הַפֶּרַח עַל הָעֵץ, וּבְדִיעֲבַד אֶפְשָׁר גַּם בִּשְׁלַב הַחֲנָטָה.","פֶּרֶק נ״ו, הֲלָכוֹת י׳-י״א","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["הַצִּבּוּר מְאַחֵר לְבָרֵךְ, וְהַפְּרִיחָה עוֹמֶדֶת לְהִגָּמֵר. מָה יַעֲשֶׂה יוֹסִי?",["יְחַכֶּה לַצִּבּוּר","יְוַתֵּר עַל הַבְּרָכָה","יְבָרֵךְ לְבַדּוֹ"],2,"נוֹהֲגִים שֶׁהַצִּבּוּר מְבָרֵךְ יַחַד בְּרֹב עַם, אֲבָל אִם הַצִּבּוּר מְאַחֵר – יְבָרֵךְ לְבַדּוֹ וְלֹא יַמְתִּין.","פֶּרֶק נ״ו, הֲלָכָה י״ב","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["בְּרָכָה זוֹ נֶאֱמֶרֶת פַּעַם אַחַת בְּשָׁנָה. מִי שֶׁלֹּא בֵּרֵךְ בְּנִיסָן – מָתַי יְבָרֵךְ?",["בְּאִיָּר, בְּלִי שֵׁם וּמַלְכוּת","רַק בְּנִיסָן שֶׁל שָׁנָה הַבָּאָה","בְּסֻכּוֹת, עִם הַלּוּלָב"],0,"בִּרְכַּת הָאִילָנוֹת נֶאֱמֶרֶת רַק פַּעַם אַחַת בְּשָׁנָה. מִי שֶׁלֹּא בֵּרֵךְ בְּנִיסָן יְבָרֵךְ בְּאִיָּר לְלֹא הַזְכָּרַת שֵׁם וּמַלְכוּת.","פֶּרֶק נ״ו, הֲלָכוֹת י״ג-י״ד","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["לָמָּה צִוָּה עָלֵינוּ ה׳ לֶאֱכֹל מַצָּה וְלֹא לֶאֱכֹל חָמֵץ בְּפֶסַח?",["לִזְכֹּר אֶת מַתַּן תּוֹרָה","לִזְכֹּר אֶת יְצִיאַת מִצְרַיִם","לִזְכֹּר אֶת בְּרִיאַת הָעוֹלָם"],1,"כְּדֵי לִזְכֹּר אֶת יְצִיאַת מִצְרַיִם וְאֶת הַנִּסִּים הַגְּדוֹלִים שֶׁעָשָׂה עִמָּנוּ ה׳.","פֶּרֶק נ״ז, הֲלָכָה א׳","אִסּוּר חָמֵץ"],["אָדָם מָצָא חָמֵץ בְּאֶמְצַע הַפֶּסַח. מָה עָלָיו לַעֲשׂוֹת?",["לִמְכֹּר אוֹתוֹ לְגוֹי","לִשְׁמֹר אוֹתוֹ לְאַחַר הַחַג","לְבַעֵר אוֹתוֹ מֵהָעוֹלָם"],2,"אָסוּר לֵהָנוֹת מֵחָמֵץ בְּפֶסַח, וְלָכֵן אָסוּר לִמְכֹּר אוֹתוֹ, אֶלָּא עָלָיו לְבַעֵר אֶת הֶחָמֵץ מֵהָעוֹלָם.","פֶּרֶק נ״ז, הֲלָכָה א׳","אִסּוּר חָמֵץ"],["מֻתָּר לְהַשְׁאִיר חָמֵץ בַּבַּיִת בְּפֶסַח אִם לֹא אוֹכְלִים מִמֶּנּוּ?",["אָסוּר לְהַשְׁאִיר אוֹתוֹ","מֻתָּר אִם הוּא בָּאָרוֹן","מֻתָּר אִם הוּא מְעַט"],0,"אָסוּר לְהַשְׁאִיר חָמֵץ בִּרְשׁוּתֵנוּ אֲפִלּוּ אִם לֹא אוֹכְלִים מִמֶּנּוּ – ״בַּל יֵרָאֶה״ וּ״בַל יִמָּצֵא״.","פֶּרֶק נ״ז, הֲלָכָה א׳","אִסּוּר חָמֵץ"],["מָה מֻבְטָח לְמִי שֶׁנִּזְהָר מֵחָמֵץ אֲפִלּוּ בְּמַשֶּׁהוּ?",["מַתָּנָה גְּדוֹלָה","שָׁנָה טוֹבָה","חֻפְשָׁה אֲרֻכָּה"],1,"הַנִּזְהָר מֵחָמֵץ בְּפֶסַח אֲפִלּוּ בְּמַשֶּׁהוּ – בָּטוּחַ הוּא שֶׁתִּהְיֶה לוֹ שָׁנָה טוֹבָה.","פֶּרֶק נ״ז, הֲלָכָה ב׳","אִסּוּר חָמֵץ"],["אֵיזֶה מֵהֵם הוּא אֶחָד מֵחֲמֵשֶׁת מִינֵי דָּגָן?",["תִּירָס","תַּפּוּחַ","שִׁיפוֹן"],2,"חֲמֵשֶׁת מִינֵי דָּגָן הֵם: חִטָּה, שְׂעוֹרָה, שִׁבֹּלֶת שׁוּעָל, שִׁיפוֹן וְכֻסְמִין.","פֶּרֶק נ״ז, הֲלָכָה ג׳","אִסּוּר חָמֵץ"],["בְּקְבּוּק בִּירָה עֲשׂוּיָה מִשְּׂעוֹרִים – מָה עוֹשִׂים בּוֹ לִפְנֵי פֶּסַח?",["מְבַעֲרִים אוֹתוֹ","שׁוֹמְרִים בַּמְּקָרֵר","שׁוֹתִים בַּסֵּדֶר"],0,"גַּם מַשְׁקֶה שֶׁמְּעֹרָב בּוֹ חָמֵץ, כְּמוֹ בִּירָה הָעֲשׂוּיָה מִשְּׂעוֹרִים, חַיָּבִים לְבַעֵר.","פֶּרֶק נ״ז, הֲלָכָה ד׳","אִסּוּר חָמֵץ"],["מָה צָרִיךְ לִהְיוֹת עַל מִצְרְכֵי הַמָּזוֹן שֶׁמִּשְׁתַּמְּשִׁים בָּהֶם בְּפֶסַח?",["מַדְבֵּקַת מְחִיר","כַּשְׁרוּת לְפֶסַח","תְּמוּנָה צִבְעוֹנִית"],1,"צְרִיכָה לִהְיוֹת כַּשְׁרוּת מְיֻחֶדֶת לְפֶסַח, כְּדֵי שֶׁנֵּדַע שֶׁהִקְפִּידוּ שֶׁאֵין בָּהֶם תַּעֲרֹבֶת חָמֵץ.","פֶּרֶק נ״ז, הֲלָכָה ה׳","אִסּוּר חָמֵץ"],["בְּדִין קִטְנִיּוֹת בְּפֶסַח – כְּמִנְהַג מִי נוֹהֵג כָּל אֶחָד?",["כְּמִנְהַג הַשָּׁכֵן","כְּמִנְהַג הַחָבֵר","כְּמִנְהַג מִשְׁפַּחְתּוֹ"],2,"יֵשׁ חֲלֻקַּת מִנְהָגִים בֵּין הַסְּפָרַדִּים לָאַשְׁכְּנַזִּים בְּדִין קִטְנִיּוֹת, וְכָל אֶחָד יִנְהַג כְּמִנְהַג מִשְׁפַּחְתּוֹ.","פֶּרֶק נ״ז, הֲלָכָה ו׳","אִסּוּר חָמֵץ"],["אֵיךְ מְקַיְּמִים אֶת מִצְוַת הַשְׁבָּתַת הֶחָמֵץ?",["בְּבִטּוּל הֶחָמֵץ וּבְבִעוּרוֹ","בַּאֲכִילַת הַרְבֵּה לֶחֶם","בְּהַחְבָּאַת הֶחָמֵץ בָּאָרוֹן"],0,"מִצְוַת עֲשֵׂה מִן הַתּוֹרָה לְהַשְׁבִּית אֶת הֶחָמֵץ, וּמְקַיְּמִים אוֹתָהּ בְּבִטּוּל הֶחָמֵץ (הַחְשָׁבָתוֹ כְּעָפָר) וּבְבִעוּרוֹ מֵהָעוֹלָם.","פֶּרֶק נ״ח, הֲלָכָה א׳-ב׳","בְּדִיקַת חָמֵץ"],["מָה עוֹשִׂים בַּבַּיִת לִפְנֵי בְּדִיקַת חָמֵץ?",["מְשַׂחֲקִים בֶּחָצֵר","מְטַאטְאִים וּמְנַקִּים הֵיטֵב","קוֹנִים עוּגוֹת חֲדָשׁוֹת"],1,"נָהֲגוּ לְנַקּוֹת אֶת הַבַּיִת בִּיסוֹדִיּוּת לִקְרַאת פֶּסַח, כִּי אִי אֶפְשָׁר לִבְדֹּק הֵיטֵב לְלֹא נִקּוּי יְסוֹדִי.","פֶּרֶק נ״ח, הֲלָכָה ג׳-ד׳","בְּדִיקַת חָמֵץ"],["כַּחֲצִי שָׁעָה לִפְנֵי לֵיל י״ד בְּנִיסָן - מָה אָסוּר לַעֲשׂוֹת?",["לֶאֱכֹל אֲכִילַת קֶבַע","לִשְׁתּוֹת כּוֹס מַיִם","לִלְבֹּשׁ מְעִיל"],0,"אֵין לְהַתְחִיל מְלָאכָה וְאָסוּר לֶאֱכֹל אֲכִילַת קֶבַע (יוֹתֵר מִשְּׁתֵּי פְּרוּסוֹת לֶחֶם), שֶׁמָּא יִשְׁכְּחוּ לִבְדֹּק אֶת הֶחָמֵץ.","פֶּרֶק נ״ח, הֲלָכָה ה׳","בְּדִיקַת חָמֵץ"],["אֵיזֶה לִמּוּד מֻתָּר לִפְנֵי בְּדִיקַת חָמֵץ?",["לִמּוּד לְבַד בַּחֶדֶר","לִמּוּד יְחִידִי בַּסִּפְרִיָּה","שִׁעוּר קָבוּעַ בְּבֵית הַכְּנֶסֶת"],2,"אֵין לִלְמֹד בִּיחִידוּת שֶׁמָּא יִשְׁכַּח לִבְדֹּק, אֲבָל שִׁעוּר קָבוּעַ בְּבֵית הַכְּנֶסֶת מֻתָּר, כִּי יַזְכִּירוּ זֶה לָזֶה לִבְדֹּק.","פֶּרֶק נ״ח, הֲלָכָה ו׳","בְּדִיקַת חָמֵץ"],["בְּלֵיל י״ד בְּנִיסָן, אַחֲרֵי עַרְבִית, מְבָרְכִים ״עַל בִּעוּר חָמֵץ״. מָה עוֹשִׂים מִיָּד אַחַר כָּךְ?",["מַתְחִילִים מִיָּד לִבְדֹּק","מְסַפְּרִים סִפּוּר אָרֹךְ","הוֹלְכִים לִישֹׁן"],0,"בּוֹדְקִים לְאוֹר הַנֵּר אַחֲרֵי עַרְבִית. הַבּוֹדֵק מְבָרֵךְ וּמַתְחִיל מִיָּד, וְאִם דִּבֵּר דְּבָרִים אֲחֵרִים - מְבָרֵךְ שֵׁנִית.","פֶּרֶק נ״ח, הֲלָכָה ז׳-ח׳","בְּדִיקַת חָמֵץ"],["הַאִם צָרִיךְ לִבְדֹּק חָמֵץ גַּם בַּחֲדַר הַשֵּׁנָה?",["לֹא, רַק בַּמִּטְבָּח","כֵּן, גַּם שָׁם","רַק אִם יֵשׁ שָׁם מְקָרֵר"],1,"בּוֹדְקִים בַּחֹרִים וּבַסְּדָקִים וּבְכָל מָקוֹם שֶׁיֵּשׁ סִכּוּי שֶׁהִכְנִיסוּ אֵלָיו חָמֵץ, וְלָכֵן גַּם בְּחַדְרֵי שֵׁנָה.","פֶּרֶק נ״ח, הֲלָכָה ט׳","בְּדִיקַת חָמֵץ"],["אֵיזֶה מָקוֹם צָרִיךְ בְּדִיקַת חָמֵץ?",["הָרְחוֹב שֶׁל הָעִיר","הַחֲנוּת שֶׁל הַשָּׁכֵן","הַמְּכוֹנִית שֶׁאוֹכְלִים בָּהּ"],2,"כָּל אָדָם בּוֹדֵק אֶת הַמְּקוֹמוֹת שֶׁבִּרְשׁוּתוֹ, וְלָכֵן מַחְסָן שֶׁנִּכְנָסִים אֵלָיו עִם אֹכֶל וּמְכוֹנִית שֶׁאוֹכְלִים בָּהּ חַיָּבִים בִּבְדִיקָה.","פֶּרֶק נ״ח, הֲלָכָה י׳","בְּדִיקַת חָמֵץ"],["אֵילוּ מְקוֹמוֹת צְרִיכִים גַּם הֵם בְּדִיקַת חָמֵץ?",["בֵּית הַכְּנֶסֶת וַחֲדַר הַמַּדְרֵגוֹת","רַק הַמִּטְבָּח","רַק הַסָּלוֹן"],0,"בָּתֵּי כְּנֶסֶת צְרִיכִים בְּדִיקָה, וְהַחוֹבָה עַל הַגַּבָּאִים. גַּם רְכוּשׁ מְשֻׁתָּף כְּמוֹ חֲדַר מַדְרֵגוֹת - וְוַעַד הַבַּיִת דּוֹאֵג לְכָךְ.","פֶּרֶק נ״ח, הֲלָכָה י״א-י״ב","בְּדִיקַת חָמֵץ"],["בְּמָה בּוֹדְקִים אֶת הֶחָמֵץ?",["אוֹר הַשֶּׁמֶשׁ בַּצָּהֳרַיִם","נֵר שַׁעֲוָה אוֹ פָּנָס","אוֹר שֶׁל זִקּוּקִים"],1,"בּוֹדְקִים לְאוֹר הַנֵּר, וְנָהֲגוּ בְּנֵר שַׁעֲוָה שֶׁאוֹרוֹ יָפֶה. אֶפְשָׁר לִבְדֹּק בִּבְרָכָה גַּם בְּעֶזְרַת פָּנָס.","פֶּרֶק נ״ח, הֲלָכָה י״ג-י״ד","בְּדִיקַת חָמֵץ"],["לָמָּה מַנִּיחִים עֲשָׂרָה פְּתִיתֵי חָמֵץ לִפְנֵי הַבְּדִיקָה?",["כְּדֵי לְהַאֲכִיל צִפּוֹרִים","שֶׁלֹּא תִּהְיֶה בְּרָכָה לְבַטָּלָה","כְּדֵי לְקַשֵּׁט אֶת הַבַּיִת"],1,"נוֹהֲגִים לְהָנִיחַ עֲשָׂרָה פְּתִיתִים עֲטוּפִים, שֶׁלֹּא תְּהֵא הַבְּרָכָה לְבַטָּלָה אִם לֹא יִמָּצֵא חָמֵץ.","פֶּרֶק נ״ח, הֲלָכָה ט״ו","בְּדִיקַת חָמֵץ"],["אַחֲרֵי הַבְּדִיקָה, מָה עוֹשִׂים עִם הֶחָמֵץ שֶׁנִּמְצָא?",["שׁוֹמְרִים הֵיטֵב שֶׁלֹּא יִתְפַּזֵּר בַּבַּיִת","מְפַזְּרִים אוֹתוֹ בַּחֲדָרִים","מַשְׁאִירִים אוֹתוֹ עַל הָרִצְפָּה"],0,"אַחֲרֵי הַבְּדִיקָה יֵשׁ לִשְׁמֹר הֵיטֵב שֶׁהֶחָמֵץ שֶׁנִּמְצָא, אוֹ שֶׁנִּשְׁמַר לִסְעוּדַת הָעֶרֶב וְהַבֹּקֶר, לֹא יִתְפַּזֵּר בַּבַּיִת.","פֶּרֶק נ״ח, הֲלָכָה ט״ז","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מָתַי מְבַטְּלִים אֶת הֶחָמֵץ, וּבְאֵיזוֹ שָׂפָה?",["בְּאֶמְצַע הַפֶּסַח, בְּשָׂפָה זָרָה","מִיָּד אַחֲרֵי הַבְּדִיקָה, בְּשָׂפָה שֶׁמְּבִינִים","לִפְנֵי הַבְּדִיקָה, בְּלִי לוֹמַר דָּבָר"],1,"מִיָּד אַחֲרֵי הַבְּדִיקָה מְבַטְּלִים אֶת הֶחָמֵץ, וְאוֹמְרִים אֶת הַבִּטּוּל בְּשָׂפָה שֶׁמְּבִינִים – כִּי אִם לֹא מְבִינִים, אֵין עֵרֶךְ לַבִּטּוּל.","פֶּרֶק נ״ח, הֲלָכוֹת י״ז-י״ח","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מִי שֶׁבִּטֵּל אֶת הֶחָמֵץ וּמָצָא אַחַר כָּךְ פֵּרוּר – אֵיךְ הוּא מִתְיַחֵס אֵלָיו?",["כְּמוֹ אוֹצָר יָקָר","כְּמוֹ מַתָּנָה לַחֲבֵרִים","כְּמוֹ לִכְלוּךְ – זוֹרְקִים מִיָּד לָאַשְׁפָּה"],2,"הַמְּבַטֵּל מַחְשִׁיב אֶת הֶחָמֵץ כַּעֲפַר הָאָרֶץ, וְחוֹשֵׁב שֶׁאִם יִמְצָא חָמֵץ יַשְׁלִיכֶנּוּ מִיָּד לָאַשְׁפָּה, כְּאִלּוּ מָצָא לִכְלוּךְ עַל הָרִצְפָּה.","פֶּרֶק נ״ח, הֲלָכָה י״ט","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["אֵיזֶה חָמֵץ לֹא מְבַטְּלִים בַּבִּטּוּל שֶׁל הָעֶרֶב?",["חָמֵץ שֶׁלֹּא רָאִינוּ","הֶחָמֵץ שֶׁמְּתַכְנְנִים לֶאֱכֹל עַד הַשְּׂרֵפָה","פֵּרוּרִים שֶׁנִּשְׁאֲרוּ מִתַּחַת לַסַּפָּה"],1,"אֶת הֶחָמֵץ שֶׁמְּתַכְנְנִים לֶאֱכֹל בָּעֶרֶב וּבַבֹּקֶר, עַד זְמַן הַשְּׂרֵפָה, לֹא מְבַטְּלִים – שֶׁהֲרֵי בִּרְצוֹנֵנוּ לֶאֱכֹל אוֹתוֹ.","פֶּרֶק נ״ח, הֲלָכָה כ׳","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["עַד מָתַי אוֹכְלִים חָמֵץ בְּעֶרֶב פֶּסַח, וּמָה עוֹד עוֹשִׂים?",["עַד סוֹף הַשָּׁעָה הָרְבִיעִית, וּמְנַקִּים הֵיטֵב אֶת הַשִּׁנַּיִם","עַד הַצָּהֳרַיִם, וְהוֹלְכִים לִישֹׁן","עַד לֵיל הַסֵּדֶר, וּמְנַקִּים אֶת הַשֻּׁלְחָן"],0,"יֵשׁ לְסַיֵּם אֶת סְעוּדַת הַבֹּקֶר וּלְנַקּוֹת הֵיטֵב אֶת הַשִּׁנַּיִם לִפְנֵי סוֹף הַשָּׁעָה הָרְבִיעִית (זְמַנִּית) מֵהַזְּרִיחָה. הַזְּמַן מִתְפַּרְסֵם בְּלוּחוֹת הַשָּׁנָה.","פֶּרֶק נ״ח, הֲלָכָה כ״א","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["עַד סוֹף הַשָּׁעָה הַחֲמִישִׁית מְבַעֲרִים אֶת הֶחָמֵץ. מָה מִנְהַג רֹב יִשְׂרָאֵל?",["קוֹבְרִים אוֹתוֹ בַּגִּנָּה","שׂוֹרְפִים אוֹתוֹ בָּאֵשׁ","נוֹתְנִים אוֹתוֹ לַשָּׁכֵן"],1,"מְבַעֲרִים אֶת הֶחָמֵץ עַד סוֹף הַשָּׁעָה הַחֲמִישִׁית. מִנְהַג רֹב יִשְׂרָאֵל לִשְׂרֹף אוֹתוֹ, וּמִי שֶׁאֵינוֹ יָכוֹל – זוֹרֵק לַיָּם, מְפוֹרֵר לָרוּחַ אוֹ לָאַסְלָה, אוֹ שׁוֹפֵךְ עָלָיו חֹמֶר שֶׁפּוֹסֵל אוֹתוֹ מֵאֲכִילָה.","פֶּרֶק נ״ח, הֲלָכוֹת כ״ב-כ״ג","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מִי שׂוֹרֵף אֶת הֶחָמֵץ מִן הַמֻּבְחָר, וּמָה יֵשׁ נוֹהֲגִים לְהוֹסִיף לָאֵשׁ?",["תָּמִיד שָׁלִיחַ, וּמוֹסִיפִים עַנְפֵי אֹרֶן","הַשָּׁכֵן, וּמוֹסִיפִים עִתּוֹנִים יְשָׁנִים","בַּעַל הֶחָמֵץ בְּעַצְמוֹ, וּמוֹסִיפִים אֶת הַלּוּלָב"],2,"מִצְוָה מִן הַמֻּבְחָר שֶׁבַּעַל הֶחָמֵץ יִשְׂרֹף בְּעַצְמוֹ (וּמִי שֶׁקָּשֶׁה לוֹ – מְמַנֶּה שָׁלִיחַ). יֵשׁ נוֹהֲגִים לִשְׂרֹף עִם הַחָמֵץ אֶת הַלּוּלָב, הַהֲדַסִּים וְהָעֲרָבוֹת, כְּדֵי לְקַיֵּם בָּהֶם מִצְוָה נוֹסֶפֶת.","פֶּרֶק נ״ח, הֲלָכוֹת כ״ד-כ״ה","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מָה עוֹשִׂים אַחֲרֵי שֶׁשּׂוֹרְפִים אֶת הֶחָמֵץ?",["מְבַטְּלִים אוֹתוֹ בַּשֵּׁנִית","בּוֹדְקִים שׁוּב אֶת כָּל הַבַּיִת בְּנֵר","אוֹכְלִים פַּת חָמֵץ אַחֲרוֹנָה"],0,"לְאַחַר הַשְּׂרֵפָה מְבַטְּלִים בַּשֵּׁנִית כָּל חָמֵץ שֶׁנִּשְׁאַר בְּבַעֲלוּתֵנוּ – ״דַּחֲזִיתֵיהּ וּדְלָא חֲזִיתֵיהּ״, שֶׁרְאִיתִיו וְשֶׁלֹּא רְאִיתִיו.","פֶּרֶק נ״ח, הֲלָכָה כ״ו","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["לְבַעַל חֲנוּת יֵשׁ הַרְבֵּה מְאוֹד חָמֵץ. מָה הוּא יָכוֹל לַעֲשׂוֹת?",["לְהַסְתִּיר אוֹתוֹ בַּמַּחְסָן","לִמְכֹּר אוֹתוֹ לְגוֹי דֶּרֶךְ רַב הָעִיר","לְהַשְׁאִיר אוֹתוֹ עַל הַמַּדָּפִים"],1,"לְמִי שֶׁיֵּשׁ כַּמֻּיּוֹת גְּדוֹלוֹת שֶׁל חָמֵץ תִּקְּנוּ חֲכָמִים מְכִירַת חָמֵץ לְגוֹי. חוֹתְמִים עַל שְׁטָר שֶׁמְּמַנֶּה אֶת רַב הָעִיר לְשָׁלִיחַ לִמְכִירָה.","פֶּרֶק נ״ח, הֲלָכוֹת כ״ז-כ״ח","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["הֶחָמֵץ שֶׁנִּמְכַּר לְגוֹי נִשְׁאַר בַּבַּיִת. מָה עוֹשִׂים בּוֹ?",["אוֹכְלִים מִמֶּנּוּ בְּחֹל הַמּוֹעֵד","מְעַרְבְּבִים אוֹתוֹ עִם מַאַכְלֵי הַפֶּסַח","סוֹגְרִים בְּאָרוֹן מְסֻמָּן, וְאַחַר הַפֶּסַח מַמְתִּינִים מְעַט"],2,"סוֹגְרִים אֶת הֶחָמֵץ הַמָּכוּר בְּאָרוֹן וּמְסַמְּנִים אוֹתוֹ, כִּי הוּא רְכוּשׁ הַגּוֹי וְשֶׁלֹּא יִתְעָרֵב בְּמַאַכְלֵי הַפֶּסַח. אַחַר הַפֶּסַח מַמְתִּינִים עַד שֶׁאֶפְשָׁר לְשַׁעֵר שֶׁהָרַבָּנוּת קָנְתָה אוֹתוֹ בַּחֲזָרָה.","פֶּרֶק נ״ח, הֲלָכוֹת כ״ט-ל׳","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מָה קוֹרֶה אִם מְבַשְּׁלִים לְפֶסַח בְּסִיר שֶׁל כָּל הַשָּׁנָה בְּלִי לְהַכְשִׁיר אוֹתוֹ?",["הָאֹכֶל נַעֲשֶׂה מָתוֹק יוֹתֵר","הָאֹכֶל בּוֹלֵעַ טַעַם חָמֵץ וְנֶאֱסָר","אֵין שׁוּם בְּעָיָה"],1,"בְּדָפְנוֹת הַסִּיר בָּלוּעַ טַעַם חָמֵץ, וְהָאֹכֶל יִבְלַע אוֹתוֹ וְיֵאָסֵר בַּאֲכִילָה.","פֶּרֶק נ״ט, הֲלָכָה א׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["כְּלִי שֶׁמְּבַשְּׁלִים בּוֹ יְשִׁירוֹת עַל הָאֵשׁ – בַּמֶּה מַכְשִׁירִים אוֹתוֹ?",["בְּמַיִם קָרִים","בְּחוֹל","בָּאֵשׁ"],2,"כְּבוֹלְעוֹ כָּךְ פּוֹלְטוֹ: כְּלִי שֶׁבָּלַע עַל הָאֵשׁ – מַכְשִׁירִים אוֹתוֹ בָּאֵשׁ.","פֶּרֶק נ״ט, הֲלָכָה ב׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["מָה כְּדַאי לַעֲשׂוֹת מִי שֶׁיֵּשׁ בִּיכָלְתּוֹ?",["לִקְנוֹת כֵּלִים מְיֻחָדִים לְפֶסַח","לֹא לְבַשֵּׁל בְּפֶסַח בִּכְלָל","לְבַשֵּׁל בְּסִירֵי כָּל הַשָּׁנָה"],0,"מִי שֶׁיָּכוֹל – יִשְׁתַּדֵּל לִרְכֹּשׁ כֵּלִים מְיֻחָדִים לְפֶסַח, וְלֹא יִצְטָרֵךְ לְהַכְשִׁיר.","פֶּרֶק נ״ט, הֲלָכָה ג׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["מָהוּ ״לִבּוּן״?",["הַכְשָׁרָה בְּמַיִם קָרִים","הַכְשָׁרָה בְּעֶזְרַת הָאֵשׁ","שְׁטִיפָה בְּסַבּוֹן"],1,"לִבּוּן הוּא הַכְשָׁרָה בְּעֶזְרַת הָאֵשׁ.","פֶּרֶק נ״ט, הֲלָכָה ד׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["כְּלִי שֶׁיֵּשׁ לוֹ כַּמָּה שִׁמּוּשִׁים – לְפִי מָה רָאוּי לְהַכְשִׁיר אוֹתוֹ לְכַתְּחִלָּה?",["לְפִי הַשִּׁמּוּשׁ הַקַּל","לְפִי הַצֶּבַע שֶׁלּוֹ","לְפִי הַשִּׁמּוּשׁ הֶחָמוּר"],2,"יֵשׁ אוֹמְרִים לְפִי הַשִּׁמּוּשׁ הָעִקָּרִי, וְיֵשׁ אוֹמְרִים לְפִי הֶחָמוּר – וְכָךְ נוֹהֲגִים לְכַתְּחִלָּה.","פֶּרֶק נ״ט, הֲלָכָה ה׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["בְּאֵיזֶה כְּלִי נוֹהֲגִים שֶׁלֹּא לְהִשְׁתַּמֵּשׁ בְּפֶסַח?",["אַרְגָּז לְאִחְסוּן לֶחֶם","קַעֲרַת סָלָט מְנֻקָּה","כּוֹס חֲדָשָׁה"],0,"כֵּלִים שֶׁכָּל שִׁמּוּשָׁם לֶחָמֵץ, כְּמוֹ אַרְגָּז לֶחֶם – נוֹהֲגִים שֶׁלֹּא לְהִשְׁתַּמֵּשׁ בָּהֶם בְּפֶסַח.","פֶּרֶק נ״ט, הֲלָכָה ו׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["כְּלִי שֶׁרֹב שִׁמּוּשׁוֹ לְקַר, וְלִפְעָמִים שָׂמִים בּוֹ חָמֵץ חַם – מָה הַדִּין?",["אָסוּר לִנְגֹּעַ בּוֹ","יֵשׁ מַחֲלֹקֶת: נִקּוּי אוֹ הַגְעָלָה","מַסְפִּיק לְנַגֵּב"],1,"יֵשׁ אוֹמְרִים שֶׁמַּסְפִּיק נִקּוּי יְסוֹדִי, וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ הַגְעָלָה.","פֶּרֶק נ״ט, הֲלָכָה ז׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["אֵיךְ מַגְעִילִים סִירִים, כַּפִּיּוֹת וּמַזְלְגוֹת?",["בִּכְלִי עִם מַיִם רוֹתְחִים עַל הָאֵשׁ","בַּמְּקָרֵר","בְּשֶׁמֶשׁ חַמָּה"],0,"מַכְנִיסִים אוֹתָם לִכְלִי עִם מַיִם רוֹתְחִים שֶׁנִּמְצָא עַל הָאֵשׁ.","פֶּרֶק נ״ט, הֲלָכוֹת ח׳-ט׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["מָה עוֹד צָרִיךְ לְהַגְעִיל מִלְּבַד גּוּף הַסִּיר?",["אֶת הַכִּירַיִם בִּלְבַד","אֶת הַמַּפָּה","אֶת הַמִּכְסֶה וְהַיָּדִיּוֹת"],2,"צָרִיךְ לְהַכְשִׁיר גַּם אֶת הַיָּדִיּוֹת וְאֶת הַמִּכְסִים, כִּי גַּם אֲלֵיהֶם מַגִּיעִים הָאֵדִים.","פֶּרֶק נ״ט, הֲלָכָה י׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["מָהוּ הַשָּׁלָב הָרִאשׁוֹן בְּהַגְעָלַת כְּלִי?",["נִקּוּי יְסוֹדִי שֶׁל הַכְּלִי","צְבִיעַת הַכְּלִי בְּצֶבַע חָדָשׁ","שְׁבִירַת הַיָּדִיּוֹת שֶׁל הַכְּלִי"],0,"לִפְנֵי הַהַגְעָלָה יֵשׁ לְשַׁפְשֵׁף אֶת הַכְּלִי הֵיטֵב וּלְהוֹרִיד מִמֶּנּוּ אֶת כָּל הַלִּכְלוּךְ וְהַחֲלוּדָה.","פֶּרֶק נ״ט, הֲלָכָה י״א","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["מָה נוֹהֲגִים לְהוֹסִיף לַמַּיִם בְּהַגְעָלָה צִבּוּרִית?",["מֶלַח גַּס","סֻכָּר לָבָן","סַבּוֹן"],2,"מוֹסִיפִים סַבּוֹן לַמַּיִם, כְּדֵי שֶׁאִם יִפָּלֵט טַעַם אִסּוּר הוּא יִפָּגֵם לִפְנֵי שֶׁיִּבָּלַע בַּכֵּלִים הָאֲחֵרִים.","פֶּרֶק נ״ט, הֲלָכָה י״ב","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["לְפִי הַנִּסָּיוֹן, אֵיפֹה הַהַגְעָלָה הָרְאוּיָה וְהַטּוֹבָה בְּיוֹתֵר?",["בְּבֵיתוֹ שֶׁל הָאָדָם","בְּתוֹךְ נָהָר זוֹרֵם","בַּחֲנוּת הַמַּכֹּלֶת"],0,"הַנִּסָּיוֹן מַרְאֶה שֶׁהַגְעָלָה שֶׁאָדָם עוֹשֶׂה בְּבֵיתוֹ הִיא הָרְאוּיָה וְהַטּוֹבָה בְּיוֹתֵר.","פֶּרֶק נ״ט, הֲלָכָה י״ג","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["אֵיזֶה כְּלִי צָרִיךְ לִבּוּן חָמוּר?",["מַפִּית בַּד","שִׁפּוּד לִצְלִיַּת בָּשָׂר","סֵפֶר לִימוּד"],1,"כֵּלִים שֶׁמִּשְׁתַּמְּשִׁים בָּהֶם עַל יְדֵי הָאֵשׁ, כְּמוֹ שִׁפּוּדִים וּרְשָׁתוֹת לִצְלִיַּת בָּשָׂר, צְרִיכִים לִבּוּן חָמוּר.","פֶּרֶק נ״ט, הֲלָכָה י״ד","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["אֵיךְ נִרְאֶה כְּלִי שֶׁעָבַר לִבּוּן חָמוּר?",["הוּא קַר כְּמוֹ קֶרַח","הוּא רָטֹב מִמַּיִם","הוּא מַאֲדִים מֵרֹב חֹם"],2,"בְּלִבּוּן חָמוּר מְחַמְּמִים אֶת הַכְּלִי עַד שֶׁיִּנָּתְזוּ מִמֶּנּוּ נִיצוֹצוֹת אוֹ שֶׁיַּאֲדִים מֵרֹב חֹם.","פֶּרֶק נ״ט, הֲלָכָה ט״ו","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["מָה הַדִּין בְּתַבְנִית שֶׁל תַּנּוּר חַשְׁמַלִּי?",["אֵין לְהַכְשִׁירָהּ לְפֶסַח כְּלָל","מַגְעִילִים אוֹתָהּ בְּמַיִם קָרִים","שׁוֹטְפִים בְּסַבּוֹן וְדַי"],0,"תַּבְנִית שֶׁל תַּנּוּר חַשְׁמַלִּי צְרִיכָה לִבּוּן חָמוּר, וְחוֹשְׁשִׁים שֶׁלֹּא יְלַבְּנוּ אוֹתָהּ כָּרָאוּי מִפַּחַד שֶׁתֵּהָרֵס – לָכֵן אֵין לְהַכְשִׁירָהּ כְּלָל.","פֶּרֶק נ״ט, הֲלָכָה ט״ז","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["כְּלִי שֶׁמַּסְפִּיק לוֹ הַגְעָלָה אֲבָל קָשֶׁה לְנַקּוֹתוֹ הֵיטֵב – אֵיזֶה לִבּוּן מַסְפִּיק לוֹ?",["לִבּוּן חָמוּר בִּלְבַד","לִבּוּן קַל","אֵין צֹרֶךְ בְּכָל לִבּוּן"],1,"כֵּלִים שֶׁמֵּעִקַּר הַדִּין מַסְפִּיקָה לָהֶם הַגְעָלָה, וּמְלַבְּנִים אוֹתָם רַק כִּי קָשֶׁה לְנַקּוֹתָם – מַסְפִּיק לִבּוּן קַל.","פֶּרֶק נ״ט, הֲלָכָה י״ז","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["אֵיךְ בּוֹדְקִים שֶׁהַכְּלִי חֻמַּם מַסְפִּיק בְּלִבּוּן קַל?",["הַכְּלִי מַתְחִיל לְצַלְצֵל","קֶרַח נִמֵּס עָלָיו","נְיָר בַּצַּד הַשֵּׁנִי נִשְׂרָף"],2,"בְּלִבּוּן קַל מְחַמְּמִים אֶת הַכְּלִי עַד שֶׁקַּשׁ אוֹ נְיָר שֶׁבַּצַּד הַשֵּׁנִי שֶׁל הַכְּלִי יִשָּׂרֵף.","פֶּרֶק נ״ט, הֲלָכָה י״ח","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["כְּלִי שֶׁיֵּשׁ סָפֵק אִם צָרִיךְ לִבּוּן אוֹ שֶׁהַגְעָלָה מַסְפִּיקָה – מָה עוֹשִׂים?",["שׁוֹבְרִים אֶת הַכְּלִי","מֻתָּר לְהָקֵל בְּלִבּוּן קַל","אָסוּר לְהַכְשִׁירוֹ כְּלָל"],1,"כֵּלִים שֶׁיֵּשׁ סָפֵק אִם חַיָּבִים בְּלִבּוּן – נִתָּן לְהָקֵל וּלְהִסְתַּפֵּק בְּלִבּוּן קַל, וְאֵין חוֹבָה בְּלִבּוּן חָמוּר.","פֶּרֶק נ״ט, הֲלָכָה י״ט","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["מָה נוֹהֲגִים לַעֲשׂוֹת בַּסַּכִּינִים, בַּכַּפּוֹת וּבַמַּזְלְגוֹת לִפְנֵי פֶּסַח?",["מְנַקִּים הֵיטֵב וּמַגְעִילִים בְּמַיִם רוֹתְחִים","מְנַגְּבִים בְּמַגֶּבֶת בִּלְבַד","מַכְנִיסִים לַמְּקָרֵר"],0,"נוֹהֲגִים לְנַקּוֹת אֶת הַסַּכּוּ״ם הֵיטֵב וּלְהַגְעִיל אוֹתוֹ בְּמַיִם רוֹתְחִים.","פֶּרֶק ס׳, הֲלָכָה א׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["אֹכֶל נָפַל עַל מִשְׁטַח הַכִּירַיִם בְּפֶסַח. מָה הַדִּין?",["מֻתָּר לְאָכְלוֹ מִיָּד","אֵין לְאָכְלוֹ","מֻתָּר לְאָכְלוֹ אַחֲרֵי שְׁטִיפָה"],1,"אִם נוֹפֵל אֹכֶל עַל מִשְׁטַח הַכִּירַיִם בְּפֶסַח, אֵין לְאָכְלוֹ.","פֶּרֶק ס׳, הֲלָכָה ב׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["כֵּיצַד מַכְשִׁירִים פְּלָטָה חַשְׁמַלִּית?",["מַכְנִיסִים אוֹתָהּ לְאַמְבַּטְיָה","מְכַסִּים בְּמַגֶּבֶת","מְנַקִּים וּמַפְעִילִים עַד שִׂיא הַחֹם"],2,"מְנַקִּים אֶת הַפְּלָטָה הֵיטֵב וּמַפְעִילִים אוֹתָהּ עַד שֶׁתַּגִּיעַ לְשִׂיא הַחֹם.","פֶּרֶק ס׳, הֲלָכָה ג׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["אֵיךְ רָצוּי לְהִשְׁתַּמֵּשׁ בַּפְּלָטָה בִּימֵי הַפֶּסַח?",["כְּשֶׁהִיא מְכֻסָּה בִּנְיַר כֶּסֶף","כְּשֶׁהִיא רְטֻבָּה","כְּשֶׁהִיא כְּבוּיָה"],0,"רָצוּי לְהִשְׁתַּמֵּשׁ בַּפְּלָטָה בְּפֶסַח כַּאֲשֶׁר הִיא מְכֻסָּה בִּנְיַר כֶּסֶף.","פֶּרֶק ס׳, הֲלָכָה ד׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["מָה אָסוּר לַעֲשׂוֹת לִפְלָטָה חַשְׁמַלִּית מִפְּנֵי הַסַּכָּנָה?",["לְנַקּוֹת אוֹתָהּ בִּסְמַרְטוּט","לִשְׁפֹּךְ עָלֶיהָ מַיִם רוֹתְחִים","לְהַפְעִיל אוֹתָהּ"],1,"אֵין לִשְׁפֹּךְ מַיִם רוֹתְחִים עַל פְּלָטָה חַשְׁמַלִּית כִּי יֵשׁ בָּזֶה סַכָּנָה.","פֶּרֶק ס׳, הֲלָכָה ה׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["מָה צָרִיךְ לַעֲשׂוֹת בְּמַדְּפֵי הַמְּקָרֵר?",["לְהַגְעִיל בְּמַיִם רוֹתְחִים","לְלַבֵּן בָּאֵשׁ","לְנַקּוֹת הֵיטֵב מִכָּל פֵּרוּר"],2,"מְנַקִּים אֶת הַמְּקָרֵר וְאֶת כָּל הַמַּדָּפִים הֵיטֵב, וְאֵין צֹרֶךְ לְהַגְעִיל אֶת הַמַּדָּפִים.","פֶּרֶק ס׳, הֲלָכָה ו׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["כַּמָּה זְמַן מַמְתִּינִים לִפְנֵי שֶׁמַּכְשִׁירִים אֶת הַמִּיקְרוֹגַל?",["שָׁעָה אַחַת","עֶשְׂרִים וְאַרְבַּע שָׁעוֹת","שָׁבוּעַ שָׁלֵם"],1,"מַמְתִּינִים עֶשְׂרִים וְאַרְבַּע שָׁעוֹת כְּדֵי שֶׁהַטַּעַם הַבָּלוּעַ בַּדְּפָנוֹת יִפָּגֵם.","פֶּרֶק ס׳, הֲלָכָה ז׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["לָמָּה יֵשׁ נוֹהֲגִים לְעָרוֹת מַיִם רוֹתְחִים עַל הַשֻּׁלְחָנוֹת?",["כִּי לִפְעָמִים נִשְׁפָּךְ עֲלֵיהֶם מָרָק רוֹתֵחַ","כְּדֵי שֶׁיַּבְרִיקוּ","כְּדֵי לְקָרֵר אוֹתָם"],0,"יֵשׁ נוֹהֲגִים לְעָרוֹת מַיִם רוֹתְחִים עַל הַשֻּׁלְחָנוֹת כִּי לִפְעָמִים נִשְׁפָּךְ עֲלֵיהֶם מָרָק רוֹתֵחַ.","פֶּרֶק ס׳, הֲלָכָה ח׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["מָה נָהֲגוּ לִפְרֹשׂ עַל הַשֻּׁלְחָן כָּל יְמֵי הֶחָג?",["עִתּוֹן","שְׂמִיכָה","מַפָּה"],2,"נָהֲגוּ לִפְרֹשׂ עַל הַשֻּׁלְחָן מַפָּה שֶׁתַּחְצֹץ בֵּינוֹ לְבֵין הַכֵּלִים כָּל יְמֵי הֶחָג.","פֶּרֶק ס׳, הֲלָכָה ט׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["שֻׁלְחַן אֹכֶל שֶׁיֵּשׁ עָלָיו מַפָּה כָּל הַשָּׁנָה – מָה צָרִיךְ לַעֲשׂוֹת לוֹ לִפְנֵי פֶּסַח?",["רַק לְנַקּוֹת הֵיטֵב מִפֵּרוּרֵי חָמֵץ","לְלַבֵּן אוֹתוֹ בָּאֵשׁ","לְהַחְלִיף אֶת הַשֻּׁלְחָן"],0,"שֻׁלְחָן שֶׁיֵּשׁ עָלָיו מַפָּה כָּל הַשָּׁנָה אֵינוֹ צָרִיךְ הֶכְשֵׁר, אֲבָל צָרִיךְ לְנַקּוֹתוֹ הֵיטֵב שֶׁלֹּא יִשָּׁאֲרוּ פֵּרוּרֵי חָמֵץ.","פֶּרֶק ס׳, הֲלָכָה י׳","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["כֵּיצַד מַכְשִׁירִים מַפַּת שֻׁלְחָן מִבַּד?",["שׂוֹרְפִים אוֹתָהּ","מְכַבְּסִים אוֹתָהּ","מַשְׁרִים אוֹתָהּ בְּמַיִם קָרִים שְׁלֹשָׁה יָמִים"],1,"מַפּוֹת שֻׁלְחָן מִבַּד יֵשׁ לְכַבֵּס, וּבָזֶה הֵן מֻכְשָׁרוֹת.","פֶּרֶק ס׳, הֲלָכָה י״א","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["מַחֲבַת טֶפְלוֹן שֶׁמִּשְׁתַּמְּשִׁים בָּהּ בְּלִי נוֹזְלִים – מָה הַדִּין לְפֶסַח?",["מְלַבְּנִים אוֹתָהּ לִבּוּן קַל","מַגְעִילִים אוֹתָהּ בְּמַיִם רוֹתְחִים","אֵין לְהַכְשִׁיר אוֹתָהּ כְּלָל"],2,"מַחֲבַת טֶפְלוֹן צְרִיכָה לִבּוּן חָמוּר, וּמִפְּנֵי שֶׁהִיא עֲלוּלָה לְהֵהָרֵס בּוֹ – אֵין לְהַכְשִׁיר אוֹתָהּ כְּלָל.","פֶּרֶק ס׳, הֲלָכָה י״ב","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["אַחֲרֵי שֶׁמְּנַקִּים הֵיטֵב אֶת הַתַּנּוּר – כַּמָּה זְמַן מְחַכִּים לִפְנֵי שֶׁמַּפְעִילִים אוֹתוֹ בַּחֹם הַמֵּרַבִּי?",["עֶשְׂרִים וְאַרְבַּע שָׁעוֹת","שָׁעָה אַחַת","שָׁבוּעַ שָׁלֵם"],0,"מְנַקִּים אֶת הַתַּנּוּר, מְחַכִּים עֶשְׂרִים וְאַרְבַּע שָׁעוֹת וּמַפְעִילִים אוֹתוֹ בַּחֹם הַמֵּרַבִּי כְּשָׁעָה.","פֶּרֶק ס׳, הֲלָכָה י״ג","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["כֵּיצַד מַכְשִׁירִים תַּנּוּר פִּירוֹלִיטִי שֶׁמְּנַקֶּה אֶת עַצְמוֹ?",["מְנַקִּים הֵיטֵב וּמְחַכִּים יוֹמַיִם","מַפְעִילִים אֶת תָּכְנִית הַנִּקּוּי","שׁוֹפְכִים בּוֹ מַיִם רוֹתְחִים"],1,"בְּתַנּוּר פִּירוֹלִיטִי מַפְעִילִים אֶת תָּכְנִית הַנִּקּוּי (כַּ-500 מַעֲלוֹת), וְאֵין צֹרֶךְ לְנַקּוֹתוֹ לִפְנֵי כֵן.","פֶּרֶק ס׳, הֲלָכָה י״ד","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["כֵּיצַד מַכְשִׁירִים אֶת הַכִּיּוֹר לְפֶסַח?",["מְכַסִּים אוֹתוֹ בִּשְׂמִיכָה","מַשְׁרִים אוֹתוֹ בְּמַיִם קָרִים","מְנַקִּים וּמְעָרִים עָלָיו מַיִם רוֹתְחִים"],2,"יֵשׁ לְנַקּוֹת אֶת הַכִּיּוֹר הֵיטֵב וּלְעָרוֹת עָלָיו מַיִם רוֹתְחִים.","פֶּרֶק ס׳, הֲלָכָה ט״ו","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["מָה עוֹשִׂים בְּפֶסַח עִם כְּלֵי חֶרֶס וּפוֹרְצֶלָן שֶׁל כָּל הַשָּׁנָה?",["מַגְעִילִים אוֹתָם","שׁוֹטְפִים אוֹתָם בְּמַיִם קָרִים","לֹא מִשְׁתַּמְּשִׁים בָּהֶם בְּפֶסַח"],2,"נוֹהֲגִים שֶׁלֹּא לְהִשְׁתַּמֵּשׁ בְּפֶסַח כְּלָל בִּכְלֵי חֶרֶס וּפוֹרְצֶלָן שֶׁל כָּל הַשָּׁנָה, אֲפִלּוּ אִם הֵם רַק לִדְבָרִים קָרִים.","פֶּרֶק ס׳, הֲלָכָה ט״ז","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["כַּיּוֹם, כֵּיצַד אֶפְשָׁר לְהַכְשִׁיר כּוֹס זְכוּכִית שֶׁהִשְׁתַּמְּשׁוּ בָּהּ רַק לִדְבָרִים קָרִים?",["בְּעֵרוּי מַיִם רוֹתְחִים","בְּלִבּוּן חָמוּר בָּאֵשׁ","אִי אֶפְשָׁר, שׁוֹבְרִים אוֹתָהּ"],0,"רֹב כְּלֵי הַזְּכוּכִית הַיּוֹם יְכוֹלִים לַעֲמֹד בְּחֹם, וְלָכֵן אֶפְשָׁר לְהַכְשִׁיר אוֹתָם גַּם בְּעֵרוּי מַיִם רוֹתְחִים.","פֶּרֶק ס׳, הֲלָכָה י״ז","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["לְפִי מִנְהַג הָאַשְׁכְּנַזִּים, מָה הַדִּין בִּכְלֵי זְכוּכִית שֶׁמִּשְׁתַּמְּשִׁים בָּהֶם לְחָמֵץ רוֹתֵחַ?",["מַכְשִׁירִים בְּנִקּוּי בִּלְבַד","לֹא נִתָּן לְהַכְשִׁירָם לְפֶסַח","מַשְׁרִים אוֹתָם יוֹם אֶחָד"],1,"מִנְהַג הָאַשְׁכְּנַזִּים (וְגַם חֵלֶק מֵהַסְּפָרַדִּים): כְּלֵי זְכוּכִית שֶׁל חָמֵץ רוֹתֵחַ – אֵין לְהַכְשִׁירָם לְפֶסַח.","פֶּרֶק ס׳, הֲלָכָה י״ח","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["לָמָּה מַשְׁכִּימִים לִתְפִלַּת שַׁחֲרִית בְּעֶרֶב פֶּסַח?",["כְּדֵי לִישֹׁן בַּצָּהֳרַיִם","כְּדֵי לְסַיֵּם לֶאֱכֹל חָמֵץ בַּזְּמַן","כְּדֵי לִקְנוֹת לֶחֶם חָדָשׁ"],1,"מַשְׁכִּימִים כְּדֵי לְהַסְפִּיק לְסַיֵּם אֶת אֲכִילַת הֶחָמֵץ לִפְנֵי סוֹף הַשָּׁעָה הָרְבִיעִית, וְגַם כְּדֵי שֶׁיִּהְיֶה זְמַן לְהָכִין אֶת כָּל הַדָּרוּשׁ לְלֵיל הַסֵּדֶר.","פֶּרֶק ס״א, הֲלָכָה א׳","עֶרֶב פֶּסַח"],["אֵיזֶה מִזְמוֹר אֵין אוֹמְרִים בְּעֶרֶב פֶּסַח בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים וּבְחֵלֶק מִקְּהִלּוֹת הַסְּפָרַדִּים?",["אַשְׁרֵי","מִזְמוֹר לְתוֹדָה","שִׁיר הַשִּׁירִים"],1,"\"מִזְמוֹר לְתוֹדָה\" הוּא כְּנֶגֶד קָרְבַּן תּוֹדָה, וְעִם קָרְבַּן תּוֹדָה מְבִיאִים גַּם חַלּוֹת חָמֵץ, לָכֵן לֹא מַקְרִיבִים אוֹתוֹ בְּעֶרֶב פֶּסַח.","פֶּרֶק ס״א, הֲלָכָה ב׳","עֶרֶב פֶּסַח"],["בְּכוֹרָה: הַאִם הִיא מִתְעַנָּה בְּעֶרֶב פֶּסַח?",["תָּמִיד חַיֶּבֶת לְהִתְעַנּוֹת","תִּנְהַג כְּמִנְהַג מִשְׁפַּחְתָּהּ","אָסוּר לָהּ לְהִתְעַנּוֹת"],1,"יֵשׁ אוֹמְרִים שֶׁגַּם בְּכוֹרָה מִתְעַנָּה וְיֵשׁ חוֹלְקִים, וְכָל בְּכוֹרָה תִּנְהַג כְּמִנְהַג מִשְׁפַּחְתָּהּ.","פֶּרֶק ס״א, הֲלָכָה ג׳","עֶרֶב פֶּסַח"],["הַבְּכוֹר עוֹד לֹא הִגִּיעַ לְגִיל מִצְווֹת. מִי מִתְעַנֶּה בִּמְקוֹמוֹ?",["הָאָב","הַסַּבָּא","הַשָּׁכֵן"],0,"נוֹהֲגִים שֶׁעַד שֶׁהַבְּכוֹר מַגִּיעַ לְגִיל מִצְווֹת מִתְעַנֶּה הָאָב בִּמְקוֹמוֹ, וְאִם הָאָב בְּכוֹר בְּעַצְמוֹ תִּתְעַנֶּה הָאֵם.","פֶּרֶק ס״א, הֲלָכָה ד׳","עֶרֶב פֶּסַח"],["בְּיָמֵינוּ, אֵיךְ פּוֹטְרִים הַבְּכוֹרוֹת אֶת עַצְמָם מֵהַתַּעֲנִית?",["בְּמִשְׂחַק כַּדּוּר","בִּשְׁמִיעַת שִׁיר","בְּסִיּוּם מַסֶּכֶת"],2,"הַבְּכוֹרוֹת מִשְׁתַּתְּפִים בְּסִיּוּם מַסֶּכֶת וְטוֹעֲמִים מִסְּעֻדַּת הַמִּצְוָה, וְכָךְ פּוֹטְרִים עַצְמָם מֵחוֹבַת הַתַּעֲנִית.","פֶּרֶק ס״א, הֲלָכָה ה׳","עֶרֶב פֶּסַח"],["מָה אָסְרוּ חֲכָמִים לֶאֱכֹל בְּעֶרֶב פֶּסַח, כְּדֵי שֶׁבַּלַּיְלָה יִהְיֶה נִכָּר שֶׁאוֹכְלִים לְשֵׁם מִצְוָה?",["מַצָּה","תַּפּוּחַ","מָרָק"],0,"אָסְרוּ חֲכָמִים לֶאֱכֹל מַצָּה בְּעֶרֶב פֶּסַח, כְּדֵי שֶׁבְּלֵיל הַפֶּסַח יִהְיֶה נִכָּר שֶׁאוֹכְלִים אֶת הַמַּצָּה לְשֵׁם מִצְוָה.","פֶּרֶק ס״א, הֲלָכָה ז׳","עֶרֶב פֶּסַח"],["מִמָּה עוֹשִׂים מַצָּה עֲשִׁירָה?",["קֶמַח עִם מַיִם בִּלְבַד","קֶמַח עִם יַיִן אוֹ מֵי פֵּרוֹת","אֹרֶז עִם סֻכָּר"],1,"מַצָּה עֲשִׁירָה עֲשׂוּיָה מִקֶּמַח שֶׁלָּשׁוּ עִם מַשְׁקָאוֹת שֶׁאֵינָם מַיִם, כְּמוֹ יַיִן, מֵי פֵּרוֹת, דְּבַשׁ, חָלָב, שֶׁמֶן אוֹ בֵּיצִים. לַנּוֹהֲגִים לְאָכְלָהּ בְּפֶסַח מֻתָּר לְאָכְלָהּ גַּם בְּעֶרֶב פֶּסַח.","פֶּרֶק ס״א, הֲלָכָה ח׳","עֶרֶב פֶּסַח"],["לְמִי מֻתָּר לָתֵת לֶאֱכֹל מַצָּה בְּעֶרֶב פֶּסַח?",["לְבַר מִצְוָה","לִבְכוֹר שֶׁמִּתְעַנֶּה","לְיֶלֶד קָטָן שֶׁאֵינוֹ מֵבִין"],2,"מֻתָּר לָתֵת לְיֶלֶד קָטָן שֶׁאֵינוֹ מֵבִין כְּלָל אֶת סִפּוּר יְצִיאַת מִצְרַיִם לֶאֱכֹל מַצָּה בְּעֶרֶב פֶּסַח.","פֶּרֶק ס״א, הֲלָכָה ט׳","עֶרֶב פֶּסַח"],["יֵשׁ נוֹהֲגִים שֶׁלֹּא לֶאֱכֹל מַצָּה כְּבָר מֵאֵיזֶה יוֹם?",["מֵרֹאשׁ חֹדֶשׁ נִיסָן","מֵחֲנֻכָּה","מִשָּׁבוּעוֹת"],0,"יֵשׁ נוֹהֲגִים שֶׁלֹּא לֶאֱכֹל מַצָּה כְּבָר מֵרֹאשׁ חֹדֶשׁ נִיסָן.","פֶּרֶק ס״א, הֲלָכָה י׳","עֶרֶב פֶּסַח"],["אַחֲרֵי תְּחִלַּת הַשָּׁעָה הָעֲשִׂירִית בְּעֶרֶב פֶּסַח, מָה מֻתָּר לֶאֱכֹל?",["מַצָּה עֲשִׁירָה","מְעַט פֵּרוֹת אוֹ יְרָקוֹת","אֲרוּחָה גְּדוֹלָה מְאוֹד"],1,"מֻתָּר לֶאֱכֹל מְעַט פֵּרוֹת אוֹ יְרָקוֹת, אֲבָל לֹא בְּכַמּוּת גְּדוֹלָה מִדַּי. מַצָּה עֲשִׁירָה אֲסוּרָה מֵהַשָּׁעָה הָעֲשִׂירִית, כְּדֵי לֶאֱכֹל מַצָּה בַּלַּיְלָה לְתֵאָבוֹן.","פֶּרֶק ס״א, הֲלָכָה י״ב","עֶרֶב פֶּסַח"],["עַד אֵיזוֹ שָׁעָה מֻתָּר בְּכָל מָקוֹם לַעֲסֹק בִּסְחוֹרָה בְּעֶרֶב פֶּסַח?",["עַד חֲצוֹת הַיּוֹם","רַק עַד הַבֹּקֶר","עַד צֵאת הַכּוֹכָבִים"],0,"בְּכָל מָקוֹם מֻתָּר לַעֲסֹק בִּסְחוֹרָה בְּעֶרֶב פֶּסַח עַד חֲצוֹת הַיּוֹם.","פֶּרֶק ס״א, הֲלָכָה י״ד","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["לָמָּה אָסוּר לַעֲשׂוֹת מְלָאכָה בְּעֶרֶב פֶּסַח מֵחֲצוֹת הַיּוֹם?",["כִּי אָז בּוֹדְקִים חָמֵץ","כִּי אָז מַתְחִיל צוֹם","כִּי אָז מַקְרִיבִים אֶת קָרְבַּן הַפֶּסַח"],2,"בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם מַקְרִיבִים אֶת קָרְבַּן הַפֶּסַח מֵחֲצוֹת יוֹם י״ד בְּנִיסָן, וְלָכֵן אָסוּר אָז לַעֲשׂוֹת מְלָאכָה, כְּמוֹ בְּחֹל הַמּוֹעֵד.","פֶּרֶק ס״א, הֲלָכָה ט״ו","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מָה מִצְוָה לַעֲשׂוֹת לַיְּלָדִים בְּצָהֳרֵי עֶרֶב פֶּסַח?",["לְשַׂחֵק בַּחוּץ","לְהַשְׁכִּיב אוֹתָם לִישׁוֹן","לָלֶכֶת לַשּׁוּק"],1,"מִצְוָה לְהַשְׁכִּיב אֶת הַיְּלָדִים לִישׁוֹן בַּצָּהֳרַיִם, כְּדֵי שֶׁיִּהְיוּ עֵרָנִיִּים וּקְשׁוּבִים בְּלֵיל הַסֵּדֶר לְסִפּוּר הַהַגָּדָה.","פֶּרֶק ס״א, הֲלָכָה ט״ז","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["אֵיזוֹ מַצָּה מִצְוָה לֶאֱכֹל בְּלֵיל הַסֵּדֶר?",["מַצָּה שְׁמוּרָה מִשְּׁעַת קְצִירָה","לֶחֶם רַךְ","עוּגִיּוֹת"],0,"בְּלֵיל הַסֵּדֶר יֵשׁ לֶאֱכֹל דַּוְקָא מַצָּה שְׁמוּרָה מִשְּׁעַת קְצִירָה, שֶׁנֶּאֱמַר: ״וּשְׁמַרְתֶּם אֶת הַמַּצּוֹת״.","פֶּרֶק ס״א, הֲלָכָה י״ז","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מָתַי הַמְּהַדְּרִים אוֹפִים מַצּוֹת לְלֵיל הַסֵּדֶר?",["בְּעֶרֶב פֶּסַח בַּבֹּקֶר","בְּעֶרֶב פֶּסַח אַחֲרֵי חֲצוֹת","אַחֲרֵי הַפֶּסַח"],1,"הַמְּהַדְּרִים אוֹפִים מַצּוֹת בְּעֶרֶב פֶּסַח אַחֲרֵי חֲצוֹת, כִּי בִּזְמַן זֶה הִקְרִיבוּ אֶת קָרְבַּן הַפֶּסַח.","פֶּרֶק ס״א, הֲלָכָה י״ח","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["אֵיזֶה יָרָק אוֹכְלִים לְמָרוֹר, וְצָרִיךְ לִבְדֹּק אוֹתוֹ הֵיטֵב מִתּוֹלָעִים?",["חַסָּה","גֶּזֶר","תַּפּוּחַ אֲדָמָה"],0,"הַמָּרוֹר הוּא חַסָּה (״חֲזֶרֶת״), וּבַעֲלֶיהָ מְצוּיוֹת תּוֹלָעִים יְרֻקּוֹת, לָכֵן חוֹבָה לִבְדֹּק אוֹתָהּ הֵיטֵב אוֹ לִקְנוֹת חַסָּה נְקִיָּה.","פֶּרֶק ס״א, הֲלָכָה י״ט-כ׳","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["הַחֲרֹסֶת, שֶׁאִם שָׁכְחוּ אֶפְשָׁר לְהָכִין אוֹתָהּ גַּם בְּיוֹם טוֹב, הִיא זֵכֶר לְמָה?",["לְשֶׁלֶג","לְמַיִם","לְטִיט"],2,"הַחֲרֹסֶת הִיא זֵכֶר לַטִּיט שֶׁעָבְדוּ בּוֹ בְּמִצְרַיִם. מְכִינִים אוֹתָהּ לִפְנֵי פֶּסַח, וְאִם שָׁכְחוּ מֻתָּר בְּיוֹם טוֹב אֲבָל לֹא בְּשַׁבָּת.","פֶּרֶק ס״א, הֲלָכָה כ״א-כ״ב","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מָה בִּקְעָרַת הַסֵּדֶר הוּא זֵכֶר לְקָרְבַּן חֲגִיגָה?",["זְרוֹעַ צְלוּיָה","בֵּיצָה מְבֻשֶּׁלֶת","חַסָּה"],1,"הַבֵּיצָה (שֶׁיֵּשׁ לְבַשֵּׁל) הִיא זֵכֶר לְקָרְבַּן חֲגִיגָה, וְהַזְּרוֹעַ הַצְּלוּיָה הִיא זֵכֶר לְקָרְבַּן פֶּסַח.","פֶּרֶק ס״א, הֲלָכָה כ״ג-כ״ד","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מָה אָסוּר לֶאֱכֹל בְּלֵיל פֶּסַח?",["אֶת הַזְּרוֹעַ","אֶת הַמַּצָּה","אֶת הַחֲרֹסֶת"],0,"הַזְּרוֹעַ הִיא זֵכֶר לְקָרְבַּן הַפֶּסַח, וְלָכֵן אָסוּר לֶאֱכֹל אוֹתָהּ בְּלֵיל פֶּסַח.","פֶּרֶק ס״א, הֲלָכָה כ״ה","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["בַּמֶּה טוֹבְלִים אֶת הַכַּרְפַּס?",["בִּדְבַשׁ","בְּשֶׁמֶן","בְּמֵי מֶלַח"],2,"מְכִינִים מֵי מֶלַח לִטְבֹּל בָּהֶם אֶת הַכַּרְפַּס, לִפְנֵי כְּנִיסַת הֶחָג.","פֶּרֶק ס״א, הֲלָכָה כ״ו","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["בְּשָׁנָה שֶׁעֶרֶב פֶּסַח חָל בְּשַׁבָּת, מָתַי דּוֹרֵשׁ הָרַב אֶת דְּרָשַׁת שַׁבָּת הַגָּדוֹל?",["בְּלֵיל הַסֵּדֶר","בַּשַּׁבָּת שֶׁלְּפָנֶיהָ, ז׳ בְּנִיסָן","בְּחֹל הַמּוֹעֵד"],1,"מַקְדִּימִים אֶת דְּרָשַׁת שַׁבָּת הַגָּדוֹל לַשַּׁבָּת שֶׁלְּפָנֶיהָ, ז׳ בְּנִיסָן.","פֶּרֶק ס״ב, הֲלָכָה א׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["מָתַי בּוֹדְקִים חָמֵץ כְּשֶׁי״ד בְּנִיסָן חָל בְּשַׁבָּת?",["בְּמוֹצָאֵי שַׁבָּת","בְּלֵיל שַׁבָּת","בְּלֵיל י״ג, יוֹם חֲמִישִׁי בָּעֶרֶב"],2,"אִי אֶפְשָׁר לִבְדֹּק וְלִשְׂרֹף בְּשַׁבָּת, וְלָכֵן בּוֹדְקִים בְּלֵיל י״ג בְּנִיסָן, כְּלוֹמַר בְּיוֹם חֲמִישִׁי בָּעֶרֶב, עִם בְּרָכָה וּבִטּוּל.","פֶּרֶק ס״ב, הֲלָכָה ב׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["לָמָּה מַשְׁכִּימִים לִתְפִלַּת שַׁחֲרִית בְּשַׁבָּת זוֹ?",["כְּדֵי לְסַיֵּם אֶת הַסְּעוּדָה לִפְנֵי סוֹף זְמַן אֲכִילַת חָמֵץ","כְּדֵי לִשְׂרֹף אֶת הֶחָמֵץ","כְּדֵי לַעֲרֹךְ אֶת שֻׁלְחַן הַסֵּדֶר"],0,"מַשְׁכִּימִים לְהִתְפַּלֵּל כְּדֵי לְהַסְפִּיק לְסַיֵּם אֶת סְעוּדַת הַשַּׁבָּת לִפְנֵי סוֹף זְמַן אֲכִילַת חָמֵץ.","פֶּרֶק ס״ב, הֲלָכָה ג׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["בְּאֵילוּ כֵּלִים מְכִינִים אֶת הַמַּאֲכָלִים לְשַׁבָּת זוֹ?",["בִּכְלֵי חָמֵץ","בִּכְלֵי פֶּסַח","בְּלִי כֵּלִים כְּלָל"],1,"מְכִינִים מַאֲכָלִים כְּשֵׁרִים לְפֶסַח בִּכְלֵי הַפֶּסַח, כִּי קָשֶׁה לְנַקּוֹת הֵיטֵב בְּשַׁבָּת כֵּלִים שֶׁדָּבוּק לָהֶם חָמֵץ.","פֶּרֶק ס״ב, הֲלָכָה ד׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["אֵיךְ אוֹכְלִים פַּת בְּשַׁבָּת זוֹ בְּלִי לְפַזֵּר חָמֵץ בַּבַּיִת?",["בְּכָל חַדְרֵי הַבַּיִת","עַל שֻׁלְחַן הַפֶּסַח הַגָּדוֹל","עַל שֻׁלְחָן קָטָן בְּפִנַּת הַחֶדֶר"],2,"אוֹכְלִים אֶת הַפַּת עַל שֻׁלְחָן קָטָן בְּפִנָּה, מוֹצִיאִים מִיָּד אֶת הַפֵּרוּרִים עִם הַמַּפָּה, וְנִזְהָרִים מְאוֹד שֶׁלֹּא יִתְפַּזְּרוּ פֵּרוּרִים.","פֶּרֶק ס״ב, הֲלָכָה ה׳-ו׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["מָה עוֹשִׂים בְּשַׁבָּת בְּחָמֵץ שֶׁנִּשְׁאַר?",["זוֹרְקִים לְפַח הָאַשְׁפָּה שֶׁבָּרְחוֹב","שׂוֹרְפִים בְּאֵשׁ","מַחְבִּיאִים בָּאָרוֹן"],0,"מְפַזְּרִים בָּרוּחַ, זוֹרְקִים לָאַסְלָה, אוֹ מַשְׁלִיכִים לְפַח שֶׁבָּרְחוֹב, עַד סוֹף הַשָּׁעָה הַחֲמִישִׁית. אַחַר כָּךְ אוֹמְרִים אֶת נֹסַח בִּטּוּל הֶחָמֵץ.","פֶּרֶק ס״ב, הֲלָכָה ז׳-ח׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["מָה יָכוֹל לֶאֱכֹל בַּסְּעוּדָה הַשְּׁלִישִׁית מִי שֶׁלֹּא נוֹהֵג לֶאֱכֹל מַצָּה עֲשִׁירָה?",["לֶחֶם","מַצָּה רְגִילָה","פֵּרוֹת וִירָקוֹת"],2,"בַּסְּעוּדָה הַשְּׁלִישִׁית אָסוּר לֶאֱכֹל חָמֵץ וְגַם מַצָּה רְגִילָה, וְלָכֵן אוֹכְלִים פֵּרוֹת וִירָקוֹת אוֹ בָּשָׂר וְדָגִים.","פֶּרֶק ס״ב, הֲלָכָה ט׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["לָמָּה אוֹכְלִים אֶת הַסְּעוּדָה הַשְּׁלִישִׁית לִפְנֵי הַשָּׁעָה הָעֲשִׂירִית?",["כְּדֵי לֶאֱכֹל מַצָּה בַּסֵּדֶר לְתֵאָבוֹן","כְּדֵי לִישֹׁן לִפְנֵי הַסֵּדֶר","כְּדֵי לִשְׂרֹף חָמֵץ"],0,"אוֹכְלִים לִפְנֵי תְּחִלַּת הַשָּׁעָה הָעֲשִׂירִית (זְמַנִּית), כְּדֵי לֶאֱכֹל אֶת הַמַּצָּה בְּלֵיל הַסֵּדֶר לְתֵאָבוֹן.","פֶּרֶק ס״ב, הֲלָכָה י׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["מָתַי עוֹרְכִים אֶת שֻׁלְחַן לֵיל הַסֵּדֶר?",["בְּשַׁבָּת אַחַר הַצָּהֳרַיִם","בְּיוֹם שִׁשִּׁי אוֹ בְּמוֹצָאֵי שַׁבָּת","בְּשַׁבָּת בַּבֹּקֶר"],1,"אֵין לַעֲרֹךְ בְּשַׁבָּת אֶת שֻׁלְחַן הַסֵּדֶר, כִּי אָסוּר לְהָכִין מִשַּׁבָּת לְיוֹם טוֹב. מְסַדְּרִים בְּיוֹם שִׁשִּׁי אוֹ מַמְתִּינִים לְצֵאת הַשַּׁבָּת.","פֶּרֶק ס״ב, הֲלָכָה י״א","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["מָה עוֹשׂוֹת מִשְׁפְּחוֹת יִשְׂרָאֵל בְּלֵיל הַסֵּדֶר?",["מִתְכַּנְּסוֹת יַחַד וּמְסַפְּרוֹת בְּנִסֵּי יְצִיאַת מִצְרַיִם","יוֹצְאוֹת לְטִיּוּל אָרֹךְ בַּלַּיְלָה","הוֹלְכוֹת לִישֹׁן מֻקְדָּם מִן הָרָגִיל"],0,"לֵיל הַסֵּדֶר הוּא לַיְלָה מְיֻחָד: הַמִּשְׁפָּחוֹת מִתְכַּנְּסוֹת וּמְסַפְּרוֹת בְּנִסֵּי ה׳ בִּיצִיאַת מִצְרַיִם, שֶׁבָּהּ הָפַכְנוּ לְעַם ה׳.","פֶּרֶק ס״ג, הֲלָכָה א׳","לֵיל הַסֵּדֶר"],["כַּמָּה מַצָּה מִצְוָה לֶאֱכֹל בְּלֵיל הַסֵּדֶר?",["פֵּרוּר קָטָן בִּלְבַד","כַּזַּיִת מַצָּה","אַרְבַּע מַצּוֹת שְׁלֵמוֹת"],1,"מִצְוָה מִן הַתּוֹרָה לֶאֱכֹל בְּלֵיל הַסֵּדֶר כַּזַּיִת מַצָּה, וּבְסוֹף הַסְּעוּדָה אוֹכְלִים עוֹד כַּזַּיִת – אֲפִיקוֹמָן.","פֶּרֶק ס״ג, הֲלָכָה ב׳","לֵיל הַסֵּדֶר"],["לָמָּה אוֹכְלִים כַּרְפַּס טָבוּל בְּמֵי מֶלַח אַחֲרֵי הַקִּדּוּשׁ?",["כִּי זֶה הַמַּאֲכָל הֲכִי טָעִים","כְּדֵי לְסַיֵּם אֶת הַסֵּדֶר מַהֵר","כְּדֵי שֶׁהַיְּלָדִים יִרְאוּ שִׁנּוּי וְיִשְׁאֲלוּ"],2,"עוֹשִׂים שִׁנּוּי כְּדֵי שֶׁהַבָּנִים יִשְׁאֲלוּ ׳מַה נִּשְׁתַּנָּה׳. רָאוּי לְהוֹסִיף שִׁנּוּיִים, כְּמוֹ פְּרָסִים וּמַמְתַּקִּים.","פֶּרֶק ס״ג, הֲלָכָה ג׳","לֵיל הַסֵּדֶר"],["אֵיפֹה כְּדַאי שֶׁיֵּשְׁבוּ הַיְּלָדִים בְּלֵיל הַסֵּדֶר?",["בְּחֶדֶר אַחֵר","לְיַד אֲבִיהֶם","בְּסוֹף הַשֻּׁלְחָן הָרָחוֹק"],1,"יֵשׁ לִדְאֹג שֶׁהַיְּלָדִים יֵשְׁבוּ לְיַד אֲבִיהֶם, וְכָךְ יְקַיֵּם ׳וְהִגַּדְתָּ לְבִנְךָ׳ בְּצוּרָה מְהֻדֶּרֶת.","פֶּרֶק ס״ג, הֲלָכָה ד׳","לֵיל הַסֵּדֶר"],["מָתַי מְכִינִים אֶת קַעֲרַת הַסֵּדֶר?",["בְּאֶמְצַע אֲמִירַת הַהַגָּדָה","אַחֲרֵי הַסְּעוּדָה","מִבְּעוֹד יוֹם, לִפְנֵי הַלַּיְלָה"],2,"עוֹרְכִים אֶת הַשֻּׁלְחָן וּמְכִינִים אֶת הַקְּעָרָה מִבְּעוֹד יוֹם, כְּדֵי לְהַתְחִיל אֶת הַסֵּדֶר מִיָּד אַחֲרֵי עַרְבִית. כָּל אֶחָד מְסַדֵּר כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק ס״ג, הֲלָכָה ה׳","לֵיל הַסֵּדֶר"],["לְאֵיזֶה צַד מַטִּים אֶת הַגּוּף בַּהֲסָבָה?",["לְצַד יָמִין","לְצַד שְׂמֹאל","קָדִימָה אֶל הַשֻּׁלְחָן"],1,"מְסִבִּים דֶּרֶךְ חֵרוּת, בְּהַטָּיַת הַגּוּף לְצַד שְׂמֹאל. גַּם בֵּן שֶׁנִּמְצָא אֵצֶל אָבִיו חַיָּב לֶאֱכֹל וְלִשְׁתּוֹת בַּהֲסָבָה.","פֶּרֶק ס״ג, הֲלָכוֹת ו׳, ח׳","לֵיל הַסֵּדֶר"],["הַאִם גַּם נָשִׁים חַיָּבוֹת בְּאַרְבַּע כּוֹסוֹת?",["כֵּן, גַּם נָשִׁים חַיָּבוֹת","לֹא, רַק גְּבָרִים חַיָּבִים","רַק אִם יֵשׁ יַיִן אָדֹם"],0,"גַּם נָשִׁים חַיָּבוֹת בְּאַרְבַּע כּוֹסוֹת וּבְכָל מִצְווֹת הַלַּיְלָה. לְגַבֵּי הֲסָבָה יֵשׁ מַחֲלֹקֶת, וְכָל אִשָּׁה נוֹהֶגֶת כְּמִנְהַג מִשְׁפַּחְתָּהּ.","פֶּרֶק ס״ג, הֲלָכוֹת ז׳, י״ג","לֵיל הַסֵּדֶר"],["מָתַי שׁוֹתִים אֶת הַכּוֹס הָרִאשׁוֹנָה?",["לְאַחַר אֲמִירַת הַהַלֵּל","לְאַחַר בִּרְכַּת הַמָּזוֹן","לְאַחַר הַקִּדּוּשׁ"],2,"כּוֹס רִאשׁוֹנָה – אַחַר הַקִּדּוּשׁ, שְׁנִיָּה – בְּסוֹף הַמַּגִּיד, שְׁלִישִׁית – אַחַר בִּרְכַּת הַמָּזוֹן, רְבִיעִית – אַחַר הַהַלֵּל.","פֶּרֶק ס״ג, הֲלָכָה ט׳","לֵיל הַסֵּדֶר"],["אֵיךְ שׁוֹתִים אֶת הַיַּיִן שֶׁבַּכּוֹס?",["טִפָּה אַחַת בִּלְבַד","בְּבַת אַחַת, לְפָחוֹת רֹב רְבִיעִית","לְאַט, לְאֹרֶךְ כָּל הַסֵּדֶר"],1,"בַּכּוֹס יֵשׁ לְפָחוֹת רְבִיעִית, שׁוֹתִים אֶת כֻּלָּהּ אוֹ לְפָחוֹת רֹב רְבִיעִית, בְּבַת אַחַת. מְהַדְּרִים בְּיַיִן אָדֹם, אֲבָל גַּם לָבָן כָּשֵׁר לַמִּצְוָה.","פֶּרֶק ס״ג, הֲלָכוֹת י׳-י״ב","לֵיל הַסֵּדֶר"],["מָה נוֹתְנִים לְיֶלֶד שֶׁהִגִּיעַ לְגִיל חִנּוּךְ בְּלֵיל הַסֵּדֶר?",["כּוֹס מִשֶּׁלּוֹ","רַק לְהִסְתַּכֵּל בַּכּוֹסוֹת","אֶת הַכּוֹס שֶׁל אַבָּא"],0,"מִצְוָה לָתֵת לְכָל יֶלֶד בְּגִיל חִנּוּךְ כּוֹס מִשֶּׁלּוֹ. וַאֲפִלּוּ עָנִי לֹוֶה בִּשְׁבִיל אַרְבַּע כּוֹסוֹת, וְהַצִּבּוּר מְצֻוֶּה לַעֲזֹר לוֹ.","פֶּרֶק ס״ג, הֲלָכוֹת י״ד-ט״ו","לֵיל הַסֵּדֶר"],["לָמָּה חִבְּרוּ חֲכָמִים אֶת הַשִּׁיר ״קַדֵּשׁ וּרְחַץ״?",["כְּדֵי לִזְכֹּר אֶת הַהֲלָכוֹת הַמְּרֻבּוֹת","כְּדֵי לְשַׂמֵּחַ אֶת הַשְּׁכֵנִים","כְּדֵי לְהַאֲרִיךְ אֶת הַסְּעוּדָה"],0,"חֲכָמִים קַדְמוֹנִים חִבְּרוּ שִׁיר בַּחֲרוּזִים כְּדֵי לְהָקֵל עַל זְכִירַת הַהֲלָכוֹת הַמְּרֻבּוֹת שֶׁבְּלֵיל הַסֵּדֶר.","פֶּרֶק ס״ד, הֲלָכָה א׳","סִימָנֵי הַסֵּדֶר"],["מָתַי מְקַדְּשִׁים בְּלֵיל הַסֵּדֶר?",["לִפְנֵי הַשְּׁקִיעָה","אַחֲרֵי צֵאת הַכּוֹכָבִים","בַּחֲצוֹת הַלַּיְלָה"],1,"אַף שֶׁיֵּשׁ לְמַהֵר כְּדֵי שֶׁהַיְּלָדִים לֹא יֵרָדְמוּ, אֵין לְקַדֵּשׁ לִפְנֵי צֵאת הַכּוֹכָבִים.","פֶּרֶק ס״ד, הֲלָכָה ב׳","סִימָנֵי הַסֵּדֶר"],["מִי מוֹזֵג אֶת כּוֹס הַקִּדּוּשׁ לַמְּקַדֵּשׁ?",["הַמְּקַדֵּשׁ מוֹזֵג לְעַצְמוֹ","אֵין מוֹזְגִים כְּלָל","מוֹזְגִים לוֹ, כְּמוֹ לְמֶלֶךְ"],2,"מוֹזְגִים לַמְּקַדֵּשׁ דֶּרֶךְ חֵרוּת, כְּמוֹ מֶלֶךְ שֶׁמּוֹזְגִים לוֹ וְאֵינוֹ מוֹזֵג לְעַצְמוֹ. מְכַוְּנִים לְמִצְוַת קִדּוּשׁ וְגַם לְמִצְוַת אַרְבַּע כּוֹסוֹת.","פֶּרֶק ס״ד, הֲלָכָה ג׳","סִימָנֵי הַסֵּדֶר"],["מָה פּוֹטֶרֶת בִּרְכַּת ״שֶׁהֶחֱיָנוּ״ שֶׁבַּקִּדּוּשׁ?",["רַק אֶת הַיַּיִן","רַק אֶת הַבֶּגֶד הֶחָדָשׁ","גַּם אֶת הַמַּצָּה וּמִצְווֹת הַלַּיְלָה"],2,"״שֶׁהֶחֱיָנוּ״ הִיא עַל הֶחָג עַצְמוֹ, וְהַמְּקַדֵּשׁ מִתְכַּוֵּן לִפְטֹר גַּם אֶת הַמַּצָּה וּשְׁאַר מִצְווֹת לֵיל הַסֵּדֶר.","פֶּרֶק ס״ד, הֲלָכָה ד׳","סִימָנֵי הַסֵּדֶר"],["בְּמָה צָרִיךְ הֲסָבָה?",["בִּשְׁתִיַּת כּוֹס הַקִּדּוּשׁ","בַּאֲכִילַת הַכַּרְפַּס","בִּנְטִילַת הַיָּדַיִם"],0,"שׁוֹתִים אֶת יֵין הַקִּדּוּשׁ בַּהֲסָבָה (וְאֵין מְבָרְכִים בְּרָכָה אַחֲרוֹנָה), אֲבָל בַּאֲכִילַת הַכַּרְפַּס אֵין צָרִיךְ לְהָסֵב.","פֶּרֶק ס״ד, הֲלָכוֹת ה׳, י׳","סִימָנֵי הַסֵּדֶר"],["מָה עוֹשִׂים בְּ״וּרְחַץ״?",["נוֹטְלִים יָדַיִם עִם בְּרָכָה","נוֹטְלִים יָדַיִם בְּלִי בְּרָכָה","רוֹחֲצִים אֶת הַפָּנִים"],1,"לִפְנֵי אֲכִילַת דָּבָר שֶׁמַּטְבִּילִים בְּמַשְׁקֶה נוֹטְלִים יָדַיִם, וְלָכֵן לִפְנֵי הַכַּרְפַּס נוֹטְלִים בְּלִי בְּרָכָה. בִּנְטִילָה זוֹ נָהֲגוּ כֻּלָּם.","פֶּרֶק ס״ד, הֲלָכָה ו׳","סִימָנֵי הַסֵּדֶר"],["לָמָּה אוֹכְלִים כַּרְפַּס?",["כְּדֵי לִשְׂבֹּעַ לִפְנֵי הַהַגָּדָה","כְּדֵי שֶׁהַיְּלָדִים יִשְׁאֲלוּ","כִּי זוֹ מִצְוָה בִּפְנֵי עַצְמָהּ"],1,"אוֹכְלִים פָּחוֹת מִכַּזַּיִת כַּרְפַּס בְּמֵי מֶלַח אוֹ חֹמֶץ כְּדֵי לַעֲשׂוֹת שִׁנּוּי שֶׁיִּשְׁאֲלוּ הַיְּלָדִים. זוֹ לֹא מִצְוָה בִּפְנֵי עַצְמָהּ, וְלָכֵן רַבִּים אוֹכְלִים יְרָקוֹת אֲחֵרִים.","פֶּרֶק ס״ד, הֲלָכוֹת ז׳-ח׳","סִימָנֵי הַסֵּדֶר"],["מָה פּוֹטֶרֶת בִּרְכַּת ״בּוֹרֵא פְּרִי הָאֲדָמָה״ שֶׁל הַכַּרְפַּס?",["גַּם אֶת הַמָּרוֹר","גַּם אֶת הַיַּיִן","גַּם אֶת הַמַּצָּה"],0,"בְּבִרְכַּת ״בּוֹרֵא פְּרִי הָאֲדָמָה״ עַל הַכַּרְפַּס מִתְכַּוְּנִים לִפְטֹר גַּם אֶת הַמָּרוֹר.","פֶּרֶק ס״ד, הֲלָכָה ט׳","סִימָנֵי הַסֵּדֶר"],["אֵיזֶה חֵלֶק מֵהַמַּצָּה הָאֶמְצָעִית שׁוֹמְרִים לָאֲפִיקוֹמָן?",["הַחֵלֶק הַקָּטָן","הַחֵלֶק הַגָּדוֹל","מַצָּה שְׁלֵמָה"],1,"בְּ״יַחַץ״ בּוֹצְעִים אֶת הַמַּצָּה הָאֶמְצָעִית. הַחֵלֶק הַגָּדוֹל נִשְׁמָר בְּמָקוֹם מֻסְתָּר לָאֲפִיקוֹמָן, וְהַקָּטָן חוֹזֵר בֵּין הַמַּצּוֹת. חוֹצִים לִפְנֵי הַהַגָּדָה, כְּדֵי לוֹמַר ״הָא לַחְמָא עַנְיָא״ עַל מַצָּה פְּרוּסָה.","פֶּרֶק ס״ד, הֲלָכָה י״א","סִימָנֵי הַסֵּדֶר"],["מָה עוֹשִׂים בִּתְחִלַּת הַ״מַּגִּיד״?",["מְכַסִּים אֶת הַמַּצּוֹת וְשׁוֹתִים","אוֹכְלִים אֶת הָאֲפִיקוֹמָן","מַגְבִּיהִים קְעָרָה וּמוֹזְגִים כּוֹס שְׁנִיָּה"],2,"מַגְבִּיהִים אֶת הַקְּעָרָה, מְגַלִּים אֶת הַמַּצּוֹת וְאוֹמְרִים ״הָא לַחְמָא עַנְיָא״ (וּמַסְבִּירִים בְּשָׂפָה מוּבֶנֶת). מוֹזְגִים כּוֹס שְׁנִיָּה כְּדֵי שֶׁהַיְּלָדִים יִשְׁאֲלוּ ״מַה נִּשְׁתַּנָּה״.","פֶּרֶק ס״ד, הֲלָכוֹת י״ב-י״ג","סִימָנֵי הַסֵּדֶר"],["מָה עוֹנִים אַחֲרֵי שֶׁשּׁוֹאֲלִים ״מַה נִּשְׁתַּנָּה״?",["אֶחָד מִי יוֹדֵעַ","עֲבָדִים הָיִינוּ","חַד גַּדְיָא"],1,"עוֹנִים ״עֲבָדִים הָיִינוּ״, כִּי זוֹ הַסִּבָּה לְכָל הַשִּׁנּוּיִים: הָיִינוּ עֲבָדִים לְפַרְעֹה בְּמִצְרַיִם, וּבְלַיְלָה זֶה יָצָאנוּ מִשָּׁם.","פֶּרֶק ס״ד, הֲלָכָה י״ד","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מָה עוֹשִׂים בַּמַּצּוֹת כְּשֶׁמַּגְבִּיהִים אֶת כּוֹס הַיַּיִן?",["מְכַסִּים אוֹתָן","אוֹכְלִים מֵהֶן","מַחְבִּיאִים אוֹתָן בַּחֶדֶר"],0,"מְכַסִּים אֶת הַמַּצּוֹת מִפְּנֵי ׳בֹּשֶׁת הַפַּת׳: הָיָה רָאוּי לְבָרֵךְ עַל הַמַּצּוֹת לִפְנֵי הַיַּיִן, וּמִכֵּיוָן שֶׁלֹּא עוֹשִׂים כָּךְ, מְכַסִּים אוֹתָן.","פֶּרֶק ס״ד, הֲלָכָה ט״ו","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["לְפִי מִנְהַג הַסְּפָרַדִּים, מָה עוֹשִׂים בַּיַּיִן שֶׁנִּשְׁאַר בַּכּוֹס אַחֲרֵי שְׁפִיכַת הַמַּכּוֹת?",["שׁוֹתִים אוֹתוֹ מִיָּד","נוֹתְנִים אוֹתוֹ לַיְּלָדִים","לֹא שׁוֹתִים, שׁוֹטְפִים וּמְמַלְּאִים יַיִן אַחֵר"],2,"לֹא שׁוֹתִים מִמֶּנּוּ, כִּי יַיִן זֶה סִמֵּל אֶת מַכּוֹת מִצְרַיִם. שׁוֹטְפִים אֶת הַכּוֹס וּמְמַלְּאִים אוֹתָהּ בְּיַיִן אַחֵר.","פֶּרֶק ס״ד, הֲלָכָה ט״ז","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["כְּשֶׁאוֹמְרִים ״פֶּסַח שֶׁהָיוּ אֲבוֹתֵינוּ אוֹכְלִים״ – מָה עוֹשִׂים עִם הַזְּרוֹעַ?",["מַגְבִּיהִים אוֹתָהּ","מִסְתַּכְּלִים עָלֶיהָ וְלֹא נוֹגְעִים","אוֹכְלִים אוֹתָהּ"],1,"לֹא נוֹגְעִים בַּזְּרוֹעַ, כִּי זֶה עָלוּל לְהֵרָאוֹת כְּאִלּוּ מַקְדִּישִׁים אוֹתָהּ לְקָרְבַּן פֶּסַח. רַק מִסְתַּכְּלִים עָלֶיהָ.","פֶּרֶק ס״ד, הֲלָכָה י״ז","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מָה אוֹמְרִים בְּסִיּוּם הַ״מַּגִּיד״, לִפְנֵי הַכּוֹס הַשְּׁנִיָּה?",["שְׁנֵי הַמִּזְמוֹרִים הָרִאשׁוֹנִים שֶׁל הַהַלֵּל","אֶת כָּל סֵפֶר תְּהִלִּים","קְרִיאַת שְׁמַע"],0,"אוֹמְרִים ״הַלְלוּיָהּ הַלְלוּ עַבְדֵי ה׳״ וּ״בְּצֵאת יִשְׂרָאֵל מִמִּצְרָיִם״, מְבָרְכִים ״אֲשֶׁר גְּאָלָנוּ״ וְשׁוֹתִים בַּהֲסָבָה. אֶת שְׁאָר הַהַלֵּל אוֹמְרִים אַחֲרֵי בִּרְכַּת הַמָּזוֹן.","פֶּרֶק ס״ד, הֲלָכָה י״ח","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["לִפְנֵי אֲכִילַת הַמַּצָּה נוֹטְלִים יָדַיִם שׁוּב. מָה מְבָרְכִים?",["בּוֹרֵא פְּרִי הָאֲדָמָה","עַל נְטִילַת יָדַיִם","לֹא מְבָרְכִים כְּלוּם"],1,"בַּנְּטִילָה שֶׁלִּפְנֵי הַכַּרְפַּס לֹא מְבָרְכִים, אֲבָל בַּנְּטִילָה שֶׁלִּפְנֵי הַמַּצָּה מְבָרְכִים ״עַל נְטִילַת יָדַיִם״.","פֶּרֶק ס״ד, הֲלָכָה י״ט","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["כַּמָּה מַצּוֹת אוֹחֵז עוֹרֵךְ הַסֵּדֶר בְּבִרְכַּת ״הַמּוֹצִיא״?",["מַצָּה אַחַת","שְׁתֵּי מַצּוֹת","שָׁלוֹשׁ מַצּוֹת"],2,"אוֹחֲזִים שָׁלוֹשׁ מַצּוֹת: הַפְּרוּסָה בֵּין שְׁתֵּי הַשְּׁלֵמוֹת. אַחַר כָּךְ מַנִּיחִים אֶת הַתַּחְתּוֹנָה וּמְבָרְכִים ״עַל אֲכִילַת מַצָּה״, וּמְכַוְּנִים לְקַיֵּם אֶת הַמִּצְוָה וְלִזְכֹּר אֶת יְצִיאַת מִצְרַיִם.","פֶּרֶק ס״ד, הֲלָכוֹת כ׳-כ״ב","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["אֵין מַסְפִּיק מַצָּה מֵהַקְּעָרָה לְכָל הַמְּסֻבִּים. מָה עוֹשִׂים?",["מוֹסִיפִים מַצָּה מֵחֲבִילָה שֶׁעַל הַשֻּׁלְחָן","רַק עוֹרֵךְ הַסֵּדֶר אוֹכֵל","אוֹכְלִים לֶחֶם"],0,"נוֹתְנִים לְכָל אֶחָד חֲתִיכָה קְטַנָּה מֵהַמַּצּוֹת שֶׁבֵּרְכוּ עֲלֵיהֶן, וּמוֹסִיפִים לוֹ שִׁעוּר שְׁנֵי כְּזֵיתִים מֵחֲבִילַת מַצּוֹת. שִׁעוּר כַּזַּיִת – כָּל אֶחָד לְפִי מִנְהַג אֲבוֹתָיו.","פֶּרֶק ס״ד, הֲלָכוֹת כ״א-כ״ג","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["עַד מָתַי לְכַתְּחִלָּה אוֹכְלִים מַצָּה וּמָרוֹר?",["עַד הַשְּׁקִיעָה","עַד הַבֹּקֶר","עַד חֲצוֹת הַלַּיְלָה"],2,"לְכַתְּחִלָּה אוֹכְלִים עַד חֲצוֹת הַלַּיְלָה. וּמִבִּרְכַּת ״עַל אֲכִילַת מַצָּה״ עַד סוֹף הַ״כּוֹרֵךְ״ לֹא מַפְסִיקִים בְּשִׂיחָה שֶׁאֵינָהּ מֵעִנְיַן הַסְּעוּדָה.","פֶּרֶק ס״ד, הֲלָכוֹת כ״ד-כ״ה","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["בְּמָה טוֹבְלִים אֶת הַמָּרוֹר?",["בְּמֵי מֶלַח","בַּחֲרֹסֶת","בִּדְבַשׁ"],1,"טוֹבְלִים כַּזַּיִת מָרוֹר בַּחֲרֹסֶת, לֹא מַשְׁהִים אוֹתוֹ, וּמְנַעֲרִים אֶת הַחֲרֹסֶת כְּדֵי שֶׁלֹּא תְּבַטֵּל אֶת מְרִירוּתוֹ. אוֹכְלִים בְּלִי הֲסָבָה.","פֶּרֶק ס״ד, הֲלָכָה כ״ו","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מָה עוֹשִׂים בְּ״כוֹרֵךְ״?",["כּוֹרְכִים מַצָּה וּמָרוֹר יַחַד","אוֹכְלִים רַק מַצָּה לְבַדָּהּ","שׁוֹתִים כּוֹס יַיִן"],0,"נוֹטְלִים כַּזַּיִת מֵהַמַּצָּה הַתַּחְתּוֹנָה, כּוֹרְכִים יַחַד עִם כַּזַּיִת מָרוֹר, טוֹבְלִים בַּחֲרֹסֶת וְאוֹכְלִים בַּהֲסָבָה – כְּמוֹ שֶׁעָשָׂה הִלֵּל.","פֶּרֶק ס״ד, הֲלָכָה כ״ז","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["אֵיךְ אוֹכְלִים אֶת סְעוּדַת הֶחָג בְּ״שֻׁלְחָן עוֹרֵךְ״?",["אוֹכְלִים הַרְבֵּה מְאוֹד עַד שֶׁאִי אֶפְשָׁר עוֹד","אוֹכְלִים בְּמִדָּה וּמַשְׁאִירִים מָקוֹם לָאֲפִיקוֹמָן","מְדַלְּגִים עַל הַסְּעוּדָה"],1,"אֵין לֶאֱכֹל וְלִשְׁתּוֹת יוֹתֵר מִדַּי, כְּדֵי שֶׁלֹּא יֹאכְלוּ אֶת הָאֲפִיקוֹמָן בַּאֲכִילָה גַּסָּה.","פֶּרֶק ס״ד, הֲלָכָה כ״ח","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מֵאֵיזוֹ מַצָּה אוֹכְלִים בְּ״צָפוּן״?",["מַצָּה שְׁלֵמָה חֲדָשָׁה","פְּרוּסַת לֶחֶם","חֲצִי הַמַּצָּה שֶׁהֻצְפְּנָה בְּ״יַחַץ״"],2,"אוֹכְלִים בַּהֲסָבָה כַּזַּיִת מֵהַמַּצָּה הַפְּרוּסָה שֶׁעוֹרֵךְ הַסֵּדֶר חָצָה בְּ״יַחַץ״ וְהִצְפִּין, זֵכֶר לְקָרְבַּן פֶּסַח.","פֶּרֶק ס״ד, הֲלָכָה כ״ט","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה מֻתָּר לִשְׁתּוֹת אַחֲרֵי אֲכִילַת הָאֲפִיקוֹמָן (חוּץ מִן הַכּוֹסוֹת)?",["מִיץ מָתוֹק","מַיִם","שׁוֹקוֹ"],1,"מִן הָרָאוּי לְהִמָּנַע מִשְּׁתִיָּה (חוּץ מֵהַכּוֹס הַשְּׁלִישִׁית וְהָרְבִיעִית), אֲבָל מֻתָּר לִשְׁתּוֹת מַיִם, מִפְּנֵי שֶׁאֵין בָּהֶם טַעַם.","פֶּרֶק ס״ד, הֲלָכָה ל׳","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה מְבָרְכִים עַל הַכּוֹס הַשְּׁלִישִׁית?",["בִּרְכַּת הַמָּזוֹן","קִדּוּשׁ","הַבְדָּלָה"],0,"מוֹזְגִים כּוֹס שְׁלִישִׁית וּמְבָרְכִים עָלֶיהָ בִּרְכַּת הַמָּזוֹן, וְאַחַר כָּךְ ״בּוֹרֵא פְּרִי הַגֶּפֶן״ וְשׁוֹתִים בַּהֲסָבָה.","פֶּרֶק ס״ד, הֲלָכָה ל״א-ל״ב","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה מוֹסִיפִים בְּבִרְכַּת הַמָּזוֹן בְּלֵיל הַסֵּדֶר?",["״יַעֲלֶה וְיָבוֹא״","״עַל הַנִּסִּים״","״עֲנֵנוּ״"],0,"בְּבִרְכַּת הַמָּזוֹן יֵשׁ לְהַזְכִּיר ״יַעֲלֶה וְיָבוֹא״, וּמִי שֶׁשָּׁכַח – חוֹזֵר.","פֶּרֶק ס״ד, הֲלָכָה ל״ג","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה יֵשׁ נוֹהֲגִים לַעֲשׂוֹת אַחֲרֵי שְׁתִיַּת הַכּוֹס הַשְּׁלִישִׁית?",["לְכַבּוֹת אֶת הָאוֹר","לִסְגֹּר אֶת הַחַלּוֹנוֹת","לִפְתֹּחַ אֶת דֶּלֶת הַבַּיִת"],2,"יֵשׁ נוֹהֲגִים לִפְתֹּחַ אֶת דֶּלֶת הַבַּיִת – לְחִזּוּק הָאֱמוּנָה בְּגִלּוּי אֵלִיָּהוּ הַנָּבִיא וּבַגְּאֻלָּה הַשְּׁלֵמָה, וְאוֹמְרִים ״שְׁפֹךְ חֲמָתְךָ״.","פֶּרֶק ס״ד, הֲלָכָה ל״ד","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה גּוֹמְרִים עַל הַכּוֹס הָרְבִיעִית?",["מְגִלַּת אֶסְתֵּר","הַהַלֵּל","סְלִיחוֹת"],1,"מוֹזְגִים כּוֹס רְבִיעִית וְגוֹמְרִים עָלֶיהָ אֶת הַהַלֵּל, וְיֵשׁ לְהִשְׁתַּדֵּל לְסַיֵּם לִפְנֵי חֲצוֹת הַלַּיְלָה.","פֶּרֶק ס״ד, הֲלָכָה ל״ה-ל״ו","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["אֵיזֶה פִּיּוּט נוֹהֲגִים לָשִׁיר בְּסוֹף הַסֵּדֶר?",["״מָעוֹז צוּר״","״לְכָה דוֹדִי״","״חַד גַּדְיָא״"],2,"יְדוּעִים הַמִּנְהָגִים לוֹמַר פִּיּוּטִים – ״אֶחָד מִי יוֹדֵעַ״, ״חַד גַּדְיָא״ וְעוֹד – וְשִׁיר הַשִּׁירִים.","פֶּרֶק ס״ד, הֲלָכָה ל״ז-ל״ח","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה חַיָּב אָדָם לַעֲשׂוֹת אַחֲרֵי סִיּוּם הַסֵּדֶר?",["לְשַׂחֵק בְּמִשְׂחָקִים","לְסַפֵּר בִּיצִיאַת מִצְרַיִם עַד שֶׁיֵּרָדֵם","לְנַקּוֹת אֶת הַבַּיִת"],1,"חַיָּב אָדָם לַעֲסֹק בְּהִלְכוֹת הַפֶּסַח וּבִיצִיאַת מִצְרַיִם עַד שֶׁתַּחְטְפֶנּוּ שֵׁינָה, וְקוֹרְאִים קְרִיאַת שְׁמַע עַל הַמִּטָּה.","פֶּרֶק ס״ד, הֲלָכָה ל״ט","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה מַתְחִילִים לוֹמַר בִּתְפִלַּת הָעֲמִידָה מֵהַיּוֹם הָרִאשׁוֹן שֶׁל פֶּסַח?",["מַשִּׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם","מוֹרִיד הַטַּל","מוֹרִיד הַשֶּׁלֶג"],1,"בַּיּוֹם הָרִאשׁוֹן שֶׁל פֶּסַח מַפְסִיקִים לוֹמַר ״מַשִּׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם״ וּמַתְחִילִים לוֹמַר ״מוֹרִיד הַטַּל״. לִפְנֵי מוּסָף אוֹמֵר שְׁלִיחַ הַצִּבּוּר ״תִּקּוּן הַטַּל״.","פֶּרֶק ס״ה, הֲלָכָה א׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מָה מוֹסִיפִים בִּתְפִלַּת שַׁחֲרִית שֶׁל חֹל הַמּוֹעֵד?",["עַל הַנִּסִּים","עֲנֵנוּ","יַעֲלֶה וְיָבוֹא"],2,"בְּחֹל הַמּוֹעֵד אוֹמְרִים ״יַעֲלֶה וְיָבוֹא״ בְּבִרְכַּת ״רְצֵה״ בְּעַרְבִית, שַׁחֲרִית וּמִנְחָה (וְלֹא בְּמוּסָף). מִי שֶׁשָּׁכַח – חוֹזֵר.","פֶּרֶק ס״ה, הֲלָכָה ב׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["אֵיזֶה הַלֵּל אוֹמְרִים בִּשְׁאָר יְמֵי הַפֶּסַח, אַחֲרֵי הַיּוֹם הָרִאשׁוֹן?",["הַלֵּל בְּדִלּוּג, כְּמוֹ בְּרֹאשׁ חֹדֶשׁ","הַלֵּל שָׁלֵם","לֹא אוֹמְרִים הַלֵּל כְּלָל"],0,"רַק בַּיּוֹם הָרִאשׁוֹן אוֹמְרִים הַלֵּל שָׁלֵם. בִּשְׁבִיעִי שֶׁל פֶּסַח טָבְעוּ הַמִּצְרִים, וְ״בִנְפֹל אוֹיִבְךָ אַל תִּשְׂמָח״, וְלָכֵן גַּם בְּחֹל הַמּוֹעֵד אוֹמְרִים הַלֵּל בְּדִלּוּג.","פֶּרֶק ס״ה, הֲלָכָה ג׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["בְּלֵיל שְׁבִיעִי שֶׁל פֶּסַח, שֶׁהוּא יוֹם טוֹב – מָה לֹא אוֹמְרִים בַּקִּדּוּשׁ?",["בּוֹרֵא פְּרִי הַגָּפֶן","שֶׁהֶחֱיָנוּ","מְקַדֵּשׁ יִשְׂרָאֵל וְהַזְּמַנִּים"],1,"הַיּוֹם הַשְּׁבִיעִי וְהָאַחֲרוֹן שֶׁל פֶּסַח הוּא יוֹם טוֹב, אֲבָל אֵין אוֹמְרִים בּוֹ ״שֶׁהֶחֱיָנוּ״ בַּקִּדּוּשׁ.","פֶּרֶק ס״ה, הֲלָכוֹת ד׳-ה׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["אֵיזוֹ פָּרָשָׁה קוֹרְאִים בַּתּוֹרָה בִּשְׁבִיעִי שֶׁל פֶּסַח?",["מַתַּן תּוֹרָה","בְּרִיאַת הָעוֹלָם","קְרִיעַת יַם סוּף וְשִׁירַת הַיָּם"],2,"בְּיוֹם זֶה, בְּאַשְׁמֹרֶת הַבֹּקֶר, נַעֲשָׂה נֵס קְרִיעַת יַם סוּף, וְלָכֵן קוֹרְאִים אֶת הַפָּרָשָׁה הַזּוֹ וְאֶת שִׁירַת הַיָּם.","פֶּרֶק ס״ה, הֲלָכָה ו׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["יְהוּדֵי מָרוֹקוֹ חוֹגְגִים מִימוּנָה בְּמוֹצָאֵי הַפֶּסַח. מָה עוֹשִׂים בָּהּ?",["צָמִים כָּל הַיּוֹם","מְאָרְחִים אִישׁ אֶת רֵעֵהוּ וּמְכַבְּדִים בִּמְגָדִים","בּוֹנִים סֻכָּה"],1,"בַּמִּימוּנָה נָהֲגוּ לָשִׁיר, לוֹמַר דִּבְרֵי תּוֹרָה עַל אֱמוּנַת יִשְׂרָאֵל, וּלְאָרֵחַ אִישׁ אֶת רֵעֵהוּ בְּמִינֵי מְגָדִים – כְּדֵי לְהַרְבּוֹת שָׁלוֹם וְאַהֲבָה.","פֶּרֶק ס״ה, הֲלָכָה ז׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מָה קוֹנִים לַנָּשִׁים לִכְבוֹד הֶחָג כְּדֵי לְשַׂמְּחָן?",["סְפָרִים","כְּלֵי עֲבוֹדָה","בְּגָדִים וְתַכְשִׁיטִים נָאִים"],2,"כָּל אֶחָד חַיָּב לִשְׂמֹחַ בַּחַג: לַקְּטַנִּים נוֹתְנִים מַמְתַּקִּים, לַנָּשִׁים קוֹנִים בְּגָדִים וְתַכְשִׁיטִים, וְהָאֲנָשִׁים אוֹכְלִים בָּשָׂר וְשׁוֹתִים יַיִן.","פֶּרֶק ס״ו, הֲלָכָה א׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["כַּמָּה מִן הַיּוֹם טוֹב מַקְדִּישִׁים לַאֲכִילָה וּשְׁתִיָּה?",["כָּל הַיּוֹם כֻּלּוֹ","חֶצְיוֹ לַה׳ וְחֶצְיוֹ לָכֶם","לֹא אוֹכְלִים כְּלָל"],1,"אֵין לֶאֱכֹל וְלִשְׁתּוֹת כָּל הַיּוֹם – ״חֶצְיוֹ לַה׳ וְחֶצְיוֹ לָכֶם״. וּמִדַּת הַחֲסִידִים לְשַׁבֵּחַ אֶת ה׳ בְּעֵת שִׂמְחָתָם.","פֶּרֶק ס״ו, הֲלָכוֹת ב׳, ה׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["עַל כַּמָּה כִּכָּרוֹת מְבָרְכִים בִּסְעוּדַת הַחַג?",["שְׁתֵּי כִּכָּרוֹת שְׁלֵמוֹת","כִּכָּר אַחַת","שָׁלוֹשׁ כִּכָּרוֹת"],0,"כְּמוֹ ״לֶחֶם מִשְׁנֶה״ בְּשַׁבָּת – שְׁתֵּי כִּכָּרוֹת שְׁלֵמוֹת. וּמִצְוָה גְּדוֹלָה לְהַזְמִין לַסְּעוּדָה יְתוֹמִים וַעֲנִיִּים.","פֶּרֶק ס״ו, הֲלָכוֹת ג׳-ד׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["אֵילוּ בְּגָדִים לוֹבְשִׁים בְּיוֹם טוֹב?",["בְּגָדִים יוֹתֵר טוֹבִים מִבִּגְדֵי הַשַּׁבָּת","בִּגְדֵי חֹל רְגִילִים","בִּגְדֵי עֲבוֹדָה"],0,"בִּגְדֵי הַחַג יִהְיוּ טוֹבִים יוֹתֵר מִבִּגְדֵי הַשַּׁבָּת. וְגַם בְּדִבּוּר – אָסוּר לְהַרְבּוֹת בְּשִׂיחַת חֹל בְּיוֹם טוֹב.","פֶּרֶק ס״ו, הֲלָכוֹת ו׳-ז׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["בְּאֵיזֶה יוֹם אָסְרָה הַתּוֹרָה לַעֲשׂוֹת מְלֶאכֶת עֲבוֹדָה?",["חֲנֻכָּה","חַג הַשָּׁבוּעוֹת","פּוּרִים"],1,"חַג הַשָּׁבוּעוֹת הוּא אֶחָד מִשִּׁשָּׁה הַיָּמִים הַטּוֹבִים שֶׁבָּהֶם אָסְרָה הַתּוֹרָה מְלֶאכֶת עֲבוֹדָה: רִאשׁוֹן וּשְׁבִיעִי שֶׁל פֶּסַח, שָׁבוּעוֹת, רֹאשׁ הַשָּׁנָה, רִאשׁוֹן שֶׁל סֻכּוֹת וּשְׁמִינִי עֲצֶרֶת.","פֶּרֶק ס״ז, הֲלָכָה א׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["אֵיזוֹ מְלָאכָה מֻתֶּרֶת בְּיוֹם טוֹב?",["בִּשּׁוּל מָרָק לַסְּעֻדָּה","כְּתִיבָה בְּמַחְבֶּרֶת","תְּפִירַת בֶּגֶד"],0,"כָּל הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת אֲסוּרוֹת גַּם בְּיוֹם טוֹב, חוּץ מִמְּלֶאכֶת אֹכֶל נֶפֶשׁ – כְּמוֹ בִּשּׁוּל מָרָק – וְכֵן הוֹצָאָה וְהַבְעָרַת אֵשׁ.","פֶּרֶק ס״ז, הֲלָכָה ב׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["אֵיךְ מֻתָּר לְהַשִּׂיג אֵשׁ בְּיוֹם טוֹב?",["מַצִּיתִים גַּפְרוּר חָדָשׁ מִן הַקֻּפְסָה","לוֹחֲצִים עַל מַצָּת חַשְׁמַלִּי","מַעֲבִירִים אֵשׁ מִנֵּר שֶׁדָּלַק מֵעֶרֶב יוֹם טוֹב"],2,"אָסוּר לְהַדְלִיק אֵשׁ חֲדָשָׁה בְּיוֹם טוֹב, וְלָכֵן מַשְׁאִירִים מֵעֶרֶב יוֹם טוֹב נֵר שֶׁיִּדְלֹק כָּל הַחַג, וּמַעֲבִירִים מִמֶּנּוּ אֵשׁ בִּשְׁעַת הַצֹּרֶךְ.","פֶּרֶק ס״ז, הֲלָכָה ג׳-ד׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["הִדְלַקְתִּי אֵשׁ בְּגַפְרוּר. מָה עוֹשִׂים בּוֹ אַחֲרֵי הַשִּׁמּוּשׁ?",["זוֹרְקִים אוֹתוֹ לַפַּח","מַנִּיחִים אוֹתוֹ בַּעֲדִינוּת וְהוּא כָּבֶה מֵעַצְמוֹ","מְכַבִּים אוֹתוֹ בִּנְשִׁיפָה"],1,"אָסוּר לְכַבּוֹת אֵשׁ בְּיוֹם טוֹב, וְלָכֵן לֹא זוֹרְקִים אֶת הַגַּפְרוּר, אֶלָּא מַנִּיחִים אוֹתוֹ בַּעֲדִינוּת וְהוּא יִכְבֶּה מֵעַצְמוֹ.","פֶּרֶק ס״ז, הֲלָכָה ה׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["הִדְלִיקוּ אֶת הַגָּז בְּגַפְרוּר מִן הַנֵּר, אֲבָל הָאֵשׁ חֲזָקָה וְהָאֹכֶל עָלוּל לְהִשָּׂרֵף. מָה עוֹשִׂים קֹדֶם?",["מְכַבִּים אֶת הָאֵשׁ","מַשְׁאִירִים וְהָאֹכֶל נִשְׂרָף","מַעֲבִירִים אֶת הַסִּיר לְלֶהָבָה חַלָּשָׁה יוֹתֵר"],2,"מֻתָּר לְהַדְלִיק כִּירֵי גָּז בְּגַפְרוּר שֶׁהֻצַּת מִנֵּר שֶׁדָּלַק מֵעֶרֶב יוֹם טוֹב. אִם הָאֵשׁ חֲזָקָה, מַעֲבִירִים אֶת הַסִּיר לְלֶהָבָה חַלָּשָׁה יוֹתֵר, וְרַק בִּשְׁעַת הַדְּחָק מֻתָּר לְהַנְמִיךְ אֶת הָאֵשׁ.","פֶּרֶק ס״ז, הֲלָכָה ו׳-ז׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["מָה הַפִּתְרוֹן לַמְּהַדְּרִין לְכִבּוּי הָאֵשׁ בְּסוֹף הַבִּשּׁוּל?",["שָׁעוֹן לְכִבּוּי גָּז","סִבּוּב הַבֶּרֶז","שְׁפִיכַת מַיִם בַּיָּד"],0,"אָסוּר לְכַבּוֹת אֶת הָאֵשׁ בְּסִבּוּב הַבֶּרֶז. הַשָּׁעוֹן לְכִבּוּי גָּז מְכֻוָּן מֵרֹאשׁ, וְהָאֵשׁ נִכְבֵּית מֵעַצְמָהּ. כְּשֶׁאֵין שָׁעוֹן וְיֵשׁ צֹרֶךְ גָּדוֹל, מַנִּיחִים סִיר מָלֵא מַיִם עַד שֶׁיִּגְלְשׁוּ, וּמִשְׁתַּמְּשִׁים בַּמַּיִם לְתֵה אוֹ קָפֶה.","פֶּרֶק ס״ז, הֲלָכָה ח׳-ט׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["מָה מִכָּל אֵלֶּה אָסוּר לַעֲשׂוֹת בְּיוֹם טוֹב?",["לֶאֱכֹל סְעֻדַּת חַג","לָשֶׁבֶת בְּבֵית הַכְּנֶסֶת","לְהַדְלִיק אֶת הָאוֹר בַּמֶּתֶג"],2,"אָסוּר לְהַדְלִיק תְּאוּרַת חַשְׁמַל אוֹ מַכְשִׁירִים חַשְׁמַלִּיִּים בְּיוֹם טוֹב.","פֶּרֶק ס״ז, הֲלָכָה י׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["בְּיוֹם הָרִאשׁוֹן שֶׁל רֹאשׁ הַשָּׁנָה – לְאֵיזֶה זְמַן מֻתָּר לְבַשֵּׁל?",["לַיּוֹם הַשֵּׁנִי שֶׁל הֶחָג","לְאוֹתוֹ הַיּוֹם","לְכָל הַשָּׁבוּעַ"],1,"מֻתָּר לְבַשֵּׁל בְּיוֹם טוֹב רַק לְצֹרֶךְ אוֹתוֹ הַיּוֹם, וַאֲפִלּוּ מִיּוֹם רִאשׁוֹן שֶׁל רֹאשׁ הַשָּׁנָה לַיּוֹם הַשֵּׁנִי אָסוּר. מִיּוֹם טוֹב שֶׁחָל בְּשִׁשִּׁי לְשַׁבָּת מֻתָּר רַק אִם עָשׂוּ עֵרוּב תַּבְשִׁילִין.","פֶּרֶק ס״ז, הֲלָכָה י״א-י״ב","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["מָה מֻתָּר בְּיוֹם טוֹב גַּם בְּמָקוֹם שֶׁאֵין בּוֹ עֵרוּב?",["לִשְׁחֹט עוֹף לַסְּעֻדָּה","לְהַדְלִיק אוֹר בַּחֶדֶר","לְהַעֲבִיר מַאֲכָלִים לְבֵית הַשָּׁכֵן"],2,"הוֹצָאָה מֵרְשׁוּת לִרְשׁוּת הֻתְּרָה בְּיוֹם טוֹב גַּם בְּלִי עֵרוּב, כְּדֵי לְהַרְבּוֹת שִׂמְחָה. וְאִלּוּ מִשְּׁחִיטָה נִמְנָעִים בְּכָל קְהִלּוֹת יִשְׂרָאֵל, אַף עַל פִּי שֶׁמֵּעִקַּר הַדִּין הִיא מֻתֶּרֶת.","פֶּרֶק ס״ז, הֲלָכָה ט״ו-ט״ז","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["מָה חוֹבָה עַל כָּל אָדָם בִּימֵי חֹל הַמּוֹעֵד?",["לִהְיוֹת שָׂמֵחַ","לְהִתְעַנּוֹת","לִשְׁתֹּק כָּל הַיּוֹם"],0,"יְמֵי חֹל הַמּוֹעֵד הֵם יְמֵי מוֹעֵד, וְלָכֵן חַיָּב כָּל אָדָם לִהְיוֹת שָׂמֵחַ בָּהֶם, הוּא וְכָל בְּנֵי בֵּיתוֹ.","פֶּרֶק ס״ח, הֲלָכָה א׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["אֵיזֶה לְבוּשׁ מַתְאִים לִימֵי חֹל הַמּוֹעֵד?",["בִּגְדֵי עֲבוֹדָה מְלֻכְלָכִים","לְבוּשׁ חֲגִיגִי וְנָקִי","בִּגְדֵי שֵׁנָה"],1,"חוֹבָה לְכַבֵּד אֶת יְמֵי חֹל הַמּוֹעֵד בְּמַאֲכָל וּמִשְׁתֶּה וּכְסוּת נְקִיָּה – לְבוּשׁ חֲגִיגִי וְנָקִי, שֶׁלֹּא כְּמוֹ בִּימֵי הַחֹל.","פֶּרֶק ס״ח, הֲלָכָה ב׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["מָה יֵשׁ לַעֲשׂוֹת בִּימֵי חֹל הַמּוֹעֵד כְּפִי הַיְּכֹלֶת?",["לִישֹׁן כָּל הַיּוֹם","לְשַׂחֵק בְּלִי הֲפָסָקָה","לִלְמֹד תּוֹרָה"],2,"יֵשׁ לִלְמֹד תּוֹרָה בִּימֵי חֹל הַמּוֹעֵד כְּפִי הַיְּכֹלֶת, וּבְכָךְ הַמּוֹעֲדִים הֵם ״מוֹעֲדֵי ה׳״.","פֶּרֶק ס״ח, הֲלָכָה ג׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["הַאִם מֻתָּר לַעֲשׂוֹת כָּל מְלָאכָה בְּחֹל הַמּוֹעֵד?",["כָּל מְלָאכָה מֻתֶּרֶת","חֵלֶק מֵהַמְּלָאכוֹת אֲסוּרוֹת","כָּל מְלָאכָה אֲסוּרָה"],1,"יְמֵי חֹל הַמּוֹעֵד הֵם גַּם ״חֹל״ וְגַם ״מוֹעֵד״, וְלָכֵן נֶאֶסְרָה בָּהֶם עֲשִׂיַּת חֵלֶק מֵהַמְּלָאכוֹת.","פֶּרֶק ס״ח, הֲלָכָה ד׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["הַצְּמָחִים בַּשָּׂדֶה עֲלוּלִים לְהִתְיַבֵּשׁ בְּחֹל הַמּוֹעֵד. מָה הַדִּין בְּהַשְׁקָיָתָם?",["אָסוּר לְגַמְרֵי","מֻתָּר רַק אַחֲרֵי הַחַג","מֻתָּר, זֶה דָּבָר הָאָבֵד"],2,"מְלָאכָה שֶׁאִם לֹא תֵּעָשֶׂה בַּמּוֹעֵד יַפְסִיד הָאָדָם הֶפְסֵד מַשְׁמָעוּתִי הִיא ״דָּבָר הָאָבֵד״, וּמֻתָּר לַעֲשׂוֹתָהּ.","פֶּרֶק ס״ח, הֲלָכָה ה׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["אֵיזֶה בְּגָדִים מֻתָּר לְכַבֵּס בְּחֹל הַמּוֹעֵד אִם זְקוּקִים לָהֶם?",["מַגָּבוֹת וְגַרְבַּיִם","סְתָם בְּגָדִים כְּשֶׁיֵּשׁ הַרְבֵּה נְקִיִּים","בְּגָדִים שֶׁכְּבָר נְקִיִּים לְגַמְרֵי"],0,"מֻתָּר לְכַבֵּס בְּגָדִים שֶׁמִּתְלַכְלְכִים הַרְבֵּה, כְּמוֹ מַגָּבוֹת, גַּרְבַּיִם וּבִגְדֵי יְלָדִים קְטַנִּים, אִם זְקוּקִים לָהֶם.","פֶּרֶק ס״ח, הֲלָכָה ז׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["מָה מֻתָּר לַעֲשׂוֹת בִּבְגָדִים בְּחֹל הַמּוֹעֵד?",["לִתְפֹּר בְּגָדִים חֲדָשִׁים","לְגַהֵץ בְּגָדִים","לְכַבֵּס סְתָם בְּגָדִים"],1,"מֻתָּר לְגַהֵץ בְּגָדִים בְּחֹל הַמּוֹעֵד, אֲבָל אֶת הַכִּבּוּס אָסְרוּ חֲכָמִים (חוּץ מִמִּקְרִים מְיֻחָדִים).","פֶּרֶק ס״ח, הֲלָכָה ח׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["לָמָּה אָסְרוּ חֲכָמִים לְהִסְתַּפֵּר וּלְכַבֵּס בְּחֹל הַמּוֹעֵד?",["כִּי הַמִּסְפָּרָה סְגוּרָה","שֶׁלֹּא יִכָּנְסוּ לַמּוֹעֵד מְגֻדְּלֵי שֵׂעָר וּמְלֻכְלָכִים","כִּי הַמַּיִם יְקָרִים"],1,"חֲכָמִים חָשְׁשׁוּ שֶׁאֲנָשִׁים יִדְחוּ אֶת הַתִּסְפֹּרֶת וְהַכִּבּוּס לְחֹל הַמּוֹעֵד, וִיבַזּוּ אֶת הַמּוֹעֵד בְּכָךְ שֶׁיִּכָּנְסוּ אֵלָיו מְגֻדְּלֵי שֵׂעָר וּבִבְגָדִים מְלֻכְלָכִים.","פֶּרֶק ס״ח, הֲלָכָה ט׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["מָה נוֹהֲגִים בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים בִּגְזִיזַת צִפָּרְנַיִם בְּחֹל הַמּוֹעֵד?",["אָסוּר לְגַמְרֵי","גּוֹזְזִים רַק אַחֲרֵי הַחַג","גּוֹזְזִים כָּרָגִיל"],2,"בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים נוֹהֲגִים לִגְזֹז צִפָּרְנַיִם בְּחֹל הַמּוֹעֵד כָּרָגִיל. בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים מַחְמִירִים.","פֶּרֶק ס״ח, הֲלָכָה י׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["מָה מֻתָּר לַעֲשׂוֹת בְּחֹל הַמּוֹעֵד?",["לִנְסֹעַ בְּרֶכֶב לְטִיּוּל","לִבְנוֹת קִיר חָדָשׁ","לִפְתֹּחַ חֲנוּת רְגִילָה"],0,"מֻתָּר לִנְסֹעַ בְּרֶכֶב בְּחֹל הַמּוֹעֵד.","פֶּרֶק ס״ח, הֲלָכָה י״א","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["אֵיזֶה תִּקּוּן בָּרֶכֶב מֻתָּר לְצֹרֶךְ טִיּוּל בַּמּוֹעֵד?",["תִּקּוּן מָנוֹעַ בַּמּוּסָךְ","הַחְלָפַת גַּלְגַּל","צְבִיעַת הָרֶכֶב כֻּלּוֹ"],1,"מֻתָּר תִּקּוּן פָּשׁוּט כְּמוֹ הַחְלָפַת גַּלְגַּל לְצֹרֶךְ נְסִיעוֹת הַמּוֹעֵד, אֲבָל לֹא תִּקּוּנִים שֶׁדּוֹרְשִׁים מוּסָךְ.","פֶּרֶק ס״ח, הֲלָכָה י״ב","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["אַבָּא רוֹצֶה לַעֲבֹר מִדִּירָה פְּשׁוּטָה לְדִירָה נָאָה. מָתַי יַעֲבֹר?",["בְּחֹל הַמּוֹעֵד","אַחֲרֵי הַחַג","בְּיוֹם טוֹב"],1,"אֵין לַעֲבֹר דִּירָה בְּחֹל הַמּוֹעֵד, אֲפִלּוּ מִדִּירָה פְּשׁוּטָה לְדִירָה נָאָה.","פֶּרֶק ס״ח, הֲלָכָה י״ג","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["מָתַי מֻתָּר לִמְכֹּר סְחוֹרָה בְּחֹל הַמּוֹעֵד?",["כְּשֶׁרוֹצִים לְהַרְוִיחַ יוֹתֵר","אַף פַּעַם, בְּשׁוּם מַצָּב","כְּשֶׁיַּפְסִיד מֵהַקֶּרֶן"],2,"אִם לֹא יִמְכֹּר וְיַפְסִיד מֵהַקֶּרֶן – מֻתָּר, כִּי זֶה דָּבָר הָאָבֵד.","פֶּרֶק ס״ח, הֲלָכָה י״ד","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["מוֹכֵר חוֹשֵׁשׁ לְהַפְסִיד לָקוֹחוֹת קְבוּעִים. מָה יַעֲשֶׂה?",["יִשְׁאַל חָכָם","יִפְתַּח בְּלִי לִשְׁאֹל","יִסְגֹּר לְתָמִיד"],0,"יִשְׁאַל שְׁאֵלַת חָכָם כֵּיצַד לִנְהֹג.","פֶּרֶק ס״ח, הֲלָכָה ט״ו","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["עוֹבֵד שֶׁיֵּשׁ לוֹ יְמֵי חֻפְשָׁה – מָתַי יִשְׁתַּדֵּל לְנַצֵּל אוֹתָם?",["בְּאֶמְצַע הַחֹרֶף","לֹא לְנַצֵּל כְּלָל","בְּחֹל הַמּוֹעֵד"],2,"עוֹבֵד שָׂכִיר יַעֲשֶׂה מַאֲמָץ לְנַצֵּל אֶת יְמֵי הַחֻפְשָׁה בְּחֹל הַמּוֹעֵד.","פֶּרֶק ס״ח, הֲלָכָה ט״ז","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["מָה מֻתָּר לִמְכֹּר בְּחֹל הַמּוֹעֵד?",["רָהִיטִים","יְרָקוֹת וְדָגִים","מְכוֹנִיּוֹת"],1,"מֻתָּר לִמְכֹּר מִצְרְכֵי מָזוֹן כְּמוֹ יְרָקוֹת, דָּגִים וּבָשָׂר.","פֶּרֶק ס״ח, הֲלָכָה י״ז","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["אֵיזוֹ עֲבוֹדָה עֲשׂוּיָה לִהְיוֹת מֻתֶּרֶת בַּמּוֹעֵד?",["תִּקּוּן נְזִילָה בַּצַּנֶּרֶת","בְּנִיַּת חֶדֶר נוֹסָף","הוֹסָפַת קוֹמָה"],0,"בִּנְיָן אָסוּר, אֲבָל עֲבוֹדוֹת דְּחוּפוֹת כְּמוֹ תִּקּוּן נְזִילָה מֻתָּרוֹת בְּתְנָאִים מְסֻיָּמִים.","פֶּרֶק ס״ח, הֲלָכָה י״ח","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["מָה מֻתָּר לְתַקֵּן בְּבֶגֶד בְּחֹל הַמּוֹעֵד?",["תְּפִירַת חֲלִיפָה חֲדָשָׁה","שִׁנּוּי מִקְצוֹעִי שֶׁל מְעִיל","תְּפִירַת כַּפְתּוֹר שֶׁנָּפַל"],2,"מֻתָּר תִּקּוּן פָּשׁוּט כְּמוֹ כַּפְתּוֹר, אָסוּר תִּקּוּן שֶׁדּוֹרֵשׁ יֶדַע מִקְצוֹעִי.","פֶּרֶק ס״ח, הֲלָכָה י״ט","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["מִן הַתּוֹרָה, לְאֵיזֶה יוֹם מֻתָּר לְבַשֵּׁל בְּיוֹם טוֹב?",["לְיוֹם חֹל רָגִיל","לְשַׁבָּת","לְשָׁבוּעַ שָׁלֵם"],1,"מִן הַתּוֹרָה מֻתָּר לְבַשֵּׁל מִיּוֹם טוֹב לְשַׁבָּת, אֲבָל אָסוּר לְבַשֵּׁל מִיּוֹם טוֹב לְחֹל.","פֶּרֶק ס״ט, הֲלָכָה א׳","עֵרוּב תַּבְשִׁילִין"],["מָה הָעֵרוּב עוֹזֵר לָנוּ לִזְכֹּר כְּשֶׁמְּכִינִים אֶת צָרְכֵי הֶחָג?",["שֶׁלְּמָחֳרָת מַגִּיעָה הַשַּׁבָּת","שֶׁצָּרִיךְ לִקְנוֹת מַתָּנוֹת","שֶׁצָּרִיךְ לְנַקּוֹת אֶת הֶחָצֵר"],0,"טַעַם נוֹסָף לָעֵרוּב: כְּשֶׁמְּכִינִים אֶת צָרְכֵי הֶחָג זוֹכְרִים שֶׁלְּמָחֳרָת מַגִּיעָה הַשַּׁבָּת, וְטוֹרְחִים גַּם עֲבוּרָהּ.","פֶּרֶק ס״ט, הֲלָכָה ב׳","עֵרוּב תַּבְשִׁילִין"],["בַּמֶּה עוֹשִׂים אֶת עֵרוּב הַתַּבְשִׁילִין?",["בְּפֵרוֹת וְסֻכָּרִיּוֹת","בְּמַיִם וּמֶלַח","בְּפַת וּבְתַבְשִׁיל"],2,"אֶת הָעֵרוּב עוֹשִׂים בְּפַת וּבְתַבְשִׁיל. כַּיּוֹם נוֹהֲגִים בְּכִכָּר שְׁלֵמָה, וּבַחֲתִיכַת בָּשָׂר אוֹ דָּג אוֹ בֵּיצָה מְבֻשֶּׁלֶת.","פֶּרֶק ס״ט, הֲלָכָה ג׳","עֵרוּב תַּבְשִׁילִין"],["אֵיזוֹ בְּרָכָה מְבָרְכִים עַל עֵרוּב תַּבְשִׁילִין?",["שֶׁהֶחֱיָנוּ","עַל מִצְוַת עֵרוּב","בּוֹרֵא פְּרִי הָעֵץ"],1,"מַחְזִיקִים אֶת הַפַּת וְאֶת הַתַּבְשִׁיל וּמְבָרְכִים ״וְצִוָּנוּ עַל מִצְוַת עֵרוּב״, וּמוֹסִיפִים ״בָּעֵרוּב הַזֶּה יְהֵא מֻתָּר לָנוּ...״.","פֶּרֶק ס״ט, הֲלָכָה ד׳","עֵרוּב תַּבְשִׁילִין"],["עַד מָתַי צָרִיךְ לַעֲשׂוֹת אֶת הָעֵרוּב?",["עַד סוֹף יוֹם טוֹב","עַד שַׁבָּת בַּבֹּקֶר","בְּעֶרֶב יוֹם טוֹב עַד הַשְּׁקִיעָה"],2,"אֶת הָעֵרוּב עוֹשִׂים בְּעֶרֶב יוֹם טוֹב עַד הַשְּׁקִיעָה. מִי שֶׁשָּׁכַח – יָכוֹל לְעָרֵב בִּבְרָכָה גַּם בְּבֵין הַשְּׁמָשׁוֹת.","פֶּרֶק ס״ט, הֲלָכָה ה׳","עֵרוּב תַּבְשִׁילִין"],["מִי שֶׁהָעֵרוּב שֶׁלּוֹ אָבַד – עַל מָה הוּא יָכוֹל לִסְמֹךְ?",["עַל הָעֵרוּב שֶׁל רַב הָעִיר","עַל עֵרוּב מִשָּׁנָה שֶׁעָבְרָה","עַל עֵרוּב שֶׁיַּעֲשֶׂה בַּחַג"],0,"רַב הָעִיר מְעָרֵב עֵרוּב תַּבְשִׁילִין עֲבוּר כָּל בְּנֵי הָעִיר. לְכַתְּחִלָּה כָּל אָדָם מְעָרֵב בְּעַצְמוֹ, אֲבָל מִי שֶׁעֵרוּבוֹ אָבַד יָכוֹל לִסְמֹךְ עַל עֵרוּב הָרַב.","פֶּרֶק ס״ט, הֲלָכָה ז׳","עֵרוּב תַּבְשִׁילִין"],["בְּמָקוֹם שֶׁאֵין בּוֹ רַב שֶׁמְּעָרֵב, וְיוֹסִי לֹא עָשָׂה עֵרוּב. מָה הַדִּין?",["יְבַשֵּׁל כָּרָגִיל","יְבַשֵּׁל רַק בַּלַּיְלָה","אֵינוֹ יָכוֹל לְבַשֵּׁל לְשַׁבָּת"],2,"מִי שֶׁגָּר בְּמָקוֹם שֶׁאֵין בּוֹ רַב שֶׁמְּעָרֵב, וְלֹא עָשָׂה עֵרוּב אוֹ שֶׁעֵרוּבוֹ נֶאֱכַל אוֹ אָבַד – אֵינוֹ יָכוֹל לְבַשֵּׁל בְּיוֹם טוֹב עֲבוּר הַשַּׁבָּת.","פֶּרֶק ס״ט, הֲלָכָה ח׳","עֵרוּב תַּבְשִׁילִין"],["מָתַי טוֹב לֶאֱכֹל אֶת הָעֵרוּב?",["בְּעֶרֶב יוֹם טוֹב","בִּסְעוּדָה שְׁלִישִׁית בְּשַׁבָּת","בְּיוֹם רִאשׁוֹן בַּבֹּקֶר"],1,"מֻתָּר לֶאֱכֹל אֶת הָעֵרוּב בְּיוֹם טוֹב אַחֲרֵי הֲכָנַת צָרְכֵי הַשַּׁבָּת, אֲבָל טוֹב לְאָכְלוֹ בִּסְעוּדָה שְׁלִישִׁית, וְכָךְ מְקַיְּמִים בּוֹ שְׁתֵּי מִצְווֹת.","פֶּרֶק ס״ט, הֲלָכָה ט׳","עֵרוּב תַּבְשִׁילִין"],["מָתַי כְּדַאי לְסַיֵּם בְּיוֹם טוֹב אֶת הַבִּשּׁוּל לְשַׁבָּת?",["כַּמָּה שֶׁיּוֹתֵר מֻקְדָּם","מַמָּשׁ לִפְנֵי הַשְּׁקִיעָה","בְּשַׁבָּת עַצְמָהּ"],0,"יֵשׁ לְהִשְׁתַּדֵּל לְסַיֵּם אֶת הַבִּשּׁוּל בְּיוֹם טוֹב לְשַׁבָּת כַּמָּה שֶׁיּוֹתֵר מֻקְדָּם.","פֶּרֶק ס״ט, הֲלָכָה י׳","עֵרוּב תַּבְשִׁילִין"],["בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם, עַד מָתַי אָסוּר לֶאֱכֹל תְּבוּאָה חֲדָשָׁה?",["עַד הַקְרָבַת מִנְחַת הָעֹמֶר","עַד רֹאשׁ הַשָּׁנָה","עַד חַג הַסֻּכּוֹת"],0,"עַד הַקְרָבַת מִנְחַת הָעֹמֶר בְּט״ז בְּנִיסָן אָסוּר לֶאֱכֹל תְּבוּאָה חֲדָשָׁה מֵחֲמֵשֶׁת מִינֵי הַדָּגָן. בְּיָמֵינוּ חֲכָמִים גָּזְרוּ שֶׁלֹּא לֶאֱכֹל מִמֶּנָּה עַד סוֹף יוֹם ט״ז בְּנִיסָן.","פֶּרֶק ע׳, הֲלָכָה א׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["בְּאֵיזֶה מוּצָר צָרִיךְ לָשִׂים לֵב לַחֲשַׁשׁ חָדָשׁ?",["תַּפּוּחִים מֵהָעֵץ שֶׁבַּגִּנָּה","דִּגְנֵי בֹּקֶר מְיֻבָּאִים מִחוּץ לָאָרֶץ","יָרָקוֹת טְרִיִּים מֵהַשּׁוּק"],1,"אִסּוּר חָדָשׁ נוֹהֵג גַּם בִּתְבוּאָה שֶׁגָּדְלָה בְּחוּץ לָאָרֶץ וְגַם בִּתְבוּאָה שֶׁל גּוֹי (וְיֵשׁ נוֹהֲגִים לְהָקֵל בִּתְבוּאַת חוּץ לָאָרֶץ). לָכֵן בְּמוּצָרִים מְיֻבָּאִים בֵּין חֶשְׁוָן לְפֶסַח יֵשׁ לָשִׂים לֵב. בִּדְגָנִים שֶׁגָּדְלוּ בָּאָרֶץ אֵין חֲשָׁשׁ, כִּי הֵם אֵינָם מַבְשִׁילִים לִפְנֵי פֶּסַח.","פֶּרֶק ע׳, הֲלָכוֹת ב׳-ג׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["כַּמָּה שָׁבוּעוֹת סוֹפְרִים מִפֶּסַח עַד חַג הַשָּׁבוּעוֹת?",["שְׁלֹשָׁה שָׁבוּעוֹת","עֲשָׂרָה שָׁבוּעוֹת","שִׁבְעָה שָׁבוּעוֹת"],2,"מִצְוָה לִסְפֹּר שֶׁבַע שַׁבָּתוֹת (שָׁבוּעוֹת) תְּמִימוֹת, וְסוֹפְרִים גַּם אֶת הַשָּׁבוּעוֹת וְגַם אֶת הַיָּמִים. בַּיּוֹם הַחֲמִשִּׁים מַקְרִיבִים אֶת מִנְחַת שְׁתֵּי הַלֶּחֶם.","פֶּרֶק ע׳, הֲלָכוֹת ד׳-ה׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["מָה עוֹשִׂים מִיָּד לִפְנֵי סְפִירַת הָעֹמֶר?",["תּוֹקְעִים בְּשׁוֹפָר","מְבָרְכִים עַל סְפִירַת הָעֹמֶר","אוֹכְלִים כְּזַיִת מַצָּה"],1,"לִפְנֵי הַסְּפִירָה מְבָרְכִים: ״אֲשֶׁר קִדְּשָׁנוּ בְּמִצְו‍ֹתָיו וְצִוָּנוּ עַל סְפִירַת הָעֹמֶר״, וְאַחַר כָּךְ סוֹפְרִים.","פֶּרֶק ע׳, הֲלָכָה ו׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["מָתַי סוֹפְרִים אֶת הָעֹמֶר?",["בַּצָּהֳרַיִם","לִפְנֵי הַשְּׁקִיעָה","אַחֲרֵי צֵאת הַכּוֹכָבִים"],2,"סוֹפְרִים אַחֲרֵי צֵאת הַכּוֹכָבִים, וְרָצוּי מִיָּד בִּתְחִלַּת הַלַּיְלָה. מִי שֶׁשָּׁכַח יָכוֹל לִסְפֹּר בִּבְרָכָה כָּל הַלַּיְלָה.","פֶּרֶק ע׳, הֲלָכוֹת ז׳-ח׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["בְּאֵיזוֹ תְּנוּחָה צָרִיךְ לִסְפֹּר אֶת הָעֹמֶר?",["בַּעֲמִידָה","בִּשְׁכִיבָה","בַּהֲלִיכָה"],0,"מִצְוָה עַל כָּל אָדָם לִסְפֹּר בְּעַצְמוֹ, וְצָרִיךְ לִסְפֹּר בַּעֲמִידָה. מִי שֶׁסָּפַר בִּישִׁיבָה יָצָא יְדֵי חוֹבָה.","פֶּרֶק ע׳, הֲלָכָה ט׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["אוֹרֵחַ שֶׁאֵינוֹ מֵבִין עִבְרִית רוֹצֶה לִסְפֹּר. אֵיךְ יִסְפֹּר?",["רַק בְּעִבְרִית","בְּשָׂפָה שֶׁהוּא מֵבִין","לֹא יִסְפֹּר כְּלָל"],1,"מִי שֶׁאֵינוֹ מֵבִין לְשׁוֹן הַקֹּדֶשׁ יִסְפֹּר דַּוְקָא בְּשָׂפָה שֶׁהוּא מֵבִין, כִּי אִי אֶפְשָׁר לִסְפֹּר בְּלִי לְהָבִין.","פֶּרֶק ע׳, הֲלָכָה י׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["אַחֲרֵי הַשְּׁקִיעָה חָבֵר שׁוֹאֵל: ״כַּמָּה לָעֹמֶר הַלַּיְלָה?״ מָה עוֹנִים?",["״אֶתְמוֹל הָיָה כָּךְ וְכָךְ״","״הַיּוֹם כָּךְ וְכָךְ״","לֹא עוֹנִים לוֹ כְּלָל"],0,"אִם יַעֲנֶה ״הַיּוֹם כָּךְ וְכָךְ״ יֵצֵא יְדֵי חוֹבַת הַסְּפִירָה וְלֹא יוּכַל לִסְפֹּר בִּבְרָכָה. לָכֵן עוֹנִים ״אֶתְמוֹל הָיָה כָּךְ וְכָךְ״. בְּלֵיל לַ״ג בָּעֹמֶר מֻתָּר לוֹמַר ״הַיּוֹם לַ״ג בָּעֹמֶר״, כִּי הַכַּוָּנָה לְשֵׁם הַיּוֹם הַטּוֹב.","פֶּרֶק ע׳, הֲלָכָה י״א","בֵּין פֶּסַח לַעֲצֶרֶת"],["מָה הַדִּין שֶׁל נָשִׁים בִּסְפִירַת הָעֹמֶר?",["חַיָּבוֹת בְּדִיּוּק כְּמוֹ גְּבָרִים","אָסוּר לָהֶן לִסְפֹּר","פְּטוּרוֹת, וְרַשָּׁאִיּוֹת לִסְפֹּר"],2,"נָשִׁים פְּטוּרוֹת כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ. אִם רוֹצוֹת לִסְפֹּר רַשָּׁאִיּוֹת, וּלְמִנְהַג הָאַשְׁכְּנַזִּים אַף רַשָּׁאִיּוֹת לְבָרֵךְ.","פֶּרֶק ע׳, הֲלָכָה י״ב","בֵּין פֶּסַח לַעֲצֶרֶת"],["שָׁכַח לִסְפֹּר בַּלַּיְלָה וְנִזְכַּר בַּבֹּקֶר. מָה יַעֲשֶׂה?",["יַפְסִיק לִסְפֹּר לְגַמְרֵי","יִסְפֹּר בַּיּוֹם בְּלִי בְּרָכָה","יִסְפֹּר פַּעֲמַיִם בַּלַּיְלָה הַבָּא"],1,"מִי שֶׁשָּׁכַח לִסְפֹּר בַּלַּיְלָה יִסְפֹּר בַּיּוֹם בְּלֹא בְּרָכָה, וּבִשְׁאַר הַלֵּילוֹת יְבָרֵךְ. וּמִי שֶׁסָּפַר מִסְפָּר מֻטְעֶה, דִּינוֹ כְּמִי שֶׁלֹּא סָפַר כְּלָל.","פֶּרֶק ע׳, הֲלָכוֹת י״ג-י״ד","בֵּין פֶּסַח לַעֲצֶרֶת"],["יוֹסִי לֹא זוֹכֵר אִם סָפַר אֶתְמוֹל סְפִירַת הָעֹמֶר. מָה יַעֲשֶׂה הַיּוֹם?",["יַפְסִיק לִסְפֹּר לְגַמְרֵי","יַמְשִׁיךְ לִסְפֹּר בִּבְרָכָה","יַתְחִיל לִסְפֹּר מֵהַהַתְחָלָה"],1,"מִי שֶׁאֵינוֹ זוֹכֵר אִם סָפַר בְּיוֹם מְסֻיָּם, יָכוֹל לְהַמְשִׁיךְ וְלִסְפֹּר בִּשְׁאַר הַיָּמִים בִּבְרָכָה.","פֶּרֶק ע׳, הֲלָכָה ט״ו׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["לְפִי מִנְהַג הַסְּפָרַדִּים, מֵאֵיזֶה יוֹם עוֹרְכִים חֲתֻנּוֹת אַחֲרֵי פֶּסַח?",["מִיּוֹם ל״ד בָּעֹמֶר","מִיּוֹם ב׳ בְּנִיסָן","רַק אַחֲרֵי סֻכּוֹת"],0,"הַסְּפָרַדִּים לֹא מִתְחַתְּנִים מִפֶּסַח עַד לַ״ג בָּעֹמֶר, כִּי אָז מֵתוּ תַּלְמִידֵי רַבִּי עֲקִיבָא. מִיּוֹם ל״ד וָאֵילָךְ עוֹרְכִים חֲתֻנּוֹת.","פֶּרֶק ע׳, הֲלָכָה ט״ז׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["לַ״ג בָּעֹמֶר חָל בְּיוֹם שִׁשִּׁי. מַדּוּעַ מֻתָּר לַסְּפָרַדִּים לְהִסְתַּפֵּר בּוֹ?",["כִּי קַר בַּחוּץ","כִּי זֶה יוֹם הֻלֶּדֶת","מִפְּנֵי כְּבוֹד הַשַּׁבָּת"],2,"הַסְּפָרַדִּים מִסְתַּפְּרִים רַק בְּיוֹם ל״ד בַּבֹּקֶר, אֲבָל אִם לַ״ג בָּעֹמֶר בְּיוֹם שִׁשִּׁי מֻתָּר לְהִסְתַּפֵּר מִפְּנֵי כְּבוֹד הַשַּׁבָּת.","פֶּרֶק ע׳, הֲלָכָה י״ז׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["מָה נוֹהֲגִים חֲלַק מֵהָאֲנָשִׁים לֶאֱכֹל בְּפֶסַח שֵׁנִי, י״ד בְּאִיָּר?",["סֻפְגָּנִיָּה","מַצָּה","תַּפּוּחַ בִּדְבַשׁ"],1,"פֶּסַח שֵׁנִי הוּא יוֹם שֶׁל קְצָת קְדֻשָּׁה וְשִׂמְחָה, וְיֵשׁ נוֹהֲגִים לֶאֱכֹל בּוֹ מַצָּה. בִּזְמַן הַמִּקְדָּשׁ הִקְרִיבוּ בּוֹ קָרְבַּן פֶּסַח מִי שֶׁהָיָה טָמֵא אוֹ רָחוֹק בְּנִיסָן.","פֶּרֶק ע׳, הֲלָכוֹת י״ח-י״ט","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["לְדַעַת חַכְמֵי הָאֱמֶת, לַ״ג בָּעֹמֶר הוּא יוֹם הַהִלּוּלָא שֶׁל מִי?",["רַבִּי שִׁמְעוֹן בַּר יוֹחַאי","יְהוּדָה הַמַּכַּבִּי","מֹשֶׁה רַבֵּנוּ"],0,"לַ״ג בָּעֹמֶר הוּא יוֹם הַהִלּוּלָא שֶׁל רַשְׁבִּ״י. ׳הִלּוּלָא׳ פֵּרוּשָׁהּ שִׂמְחָה, כִּי שְׂמֵחִים עַל דִּבְרֵי הַתּוֹרָה שֶׁהִשְׁאִיר לָנוּ.","פֶּרֶק ע׳, הֲלָכָה כ׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["לְאָן נוֹהֲגִים לַעֲלוֹת בְּלַ״ג בָּעֹמֶר לְקִבְרוֹ שֶׁל רַשְׁבִּ״י?",["לְאֵילַת","לְחֶבְרוֹן","לְמֵירוֹן"],2,"יֵשׁ שֶׁנָּהֲגוּ לַעֲלוֹת לְמֵירוֹן לְקִבְרוֹ שֶׁל רַשְׁבִּ״י וְלִלְמֹד שָׁם מִתּוֹרָתוֹ, וְשָׁם מַדְלִיקִים אֲבוּקוֹת לִכְבוֹדוֹ.","פֶּרֶק ע׳, הֲלָכוֹת כ״א-כ״ב","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["בְּאֵיזֶה תַּאֲרִיךְ חָל יוֹם הָעַצְמָאוּת?",["ה׳ בְּאִיָּר","ט״ו בִּשְׁבָט","כ״ה בְּכִסְלֵו"],0,"הָרַבָּנוּת הָרָאשִׁית קָבְעָה אֶת ה׳ בְּאִיָּר לְיוֹם הַלֵּל וְהוֹדָיָה. כְּשֶׁהוּא חָל בְּשִׁשִּׁי, שַׁבָּת אוֹ שֵׁנִי - מַקְדִּימִים אוֹ מְאַחֲרִים אוֹתוֹ כְּדֵי לִמְנֹעַ חִלּוּל שַׁבָּת.","פֶּרֶק ע׳, הֲלָכוֹת כ״ג-כ״ד","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["יוֹם כ״ח בְּאִיָּר הוּא יוֹם שִׁחְרוּר שֶׁל אֵיזוֹ עִיר?",["תֵּל אָבִיב","יְרוּשָׁלַיִם","חֵיפָה"],1,"כ״ח בְּאִיָּר הוּא יוֹם שִׁחְרוּר יְרוּשָׁלַיִם, יְהוּדָה, שׁוֹמְרוֹן וְרָמַת הַגּוֹלָן, יוֹם הַלֵּל וְהוֹדָיָה עַל נִסֵּי מִלְחֶמֶת שֵׁשֶׁת הַיָּמִים.","פֶּרֶק ע׳, הֲלָכָה כ״ה׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["מָה אוֹמְרִים בִּתְפִלַּת שַׁחֲרִית בְּיוֹם הָעַצְמָאוּת?",["סְלִיחוֹת","קִינוֹת","הַלֵּל"],2,"בְּיוֹם הָעַצְמָאוּת וּבְיוֹם שִׁחְרוּר יְרוּשָׁלַיִם אוֹמְרִים הַלֵּל שָׁלֵם בִּבְרָכָה, וְיֵשׁ אוֹמְרִים הַלֵּל לְלֹא בְּרָכָה.","פֶּרֶק ע׳, הֲלָכָה כ״ו׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["מָה נוֹהֲגִים לַעֲשׂוֹת בְּיוֹם הָעַצְמָאוּת?",["לָצוּם כָּל הַיּוֹם","לְהִסְתַּפֵּר וְלַעֲשׂוֹת סְעוּדַת מִצְוָה","לָשֶׁבֶת עַל הָרִצְפָּה"],1,"נוֹהֲגִים לְהַרְבּוֹת בִּסְעוּדַת מִצְוָה וּלְסַפֵּר בַּנִּסִּים, וְנוֹהֲגִים לְהִסְתַּפֵּר וּלְהִתְגַּלֵּחַ בְּיוֹם הָעַצְמָאוּת.","פֶּרֶק ע׳, הֲלָכוֹת כ״ז-כ״ח","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["לָמָּה נִקְרָא חַג הַשָּׁבוּעוֹת ״חַג הַקָּצִיר״?",["כִּי יוֹשְׁבִים בּוֹ בַּסֻּכָּה","כִּי הוּא חָל בִּתְקוּפַת הַקָּצִיר","כִּי אוֹכְלִים בּוֹ מַצּוֹת"],1,"הַחַג נִקְרָא בַּתּוֹרָה חַג הַקָּצִיר, מִפְּנֵי שֶׁהוּא חָל בִּתְקוּפַת הַקָּצִיר.","פֶּרֶק ע״א, הֲלָכָה א׳","חַג הַשָּׁבוּעוֹת"],["מָתַי מְקַדְּשִׁים בְּלֵיל חַג הַשָּׁבוּעוֹת?",["לְאַחַר צֵאת הַכּוֹכָבִים","בַּצָּהֳרַיִם","לִפְנֵי שְׁקִיעַת הַחַמָּה"],0,"אֵין לְקַדֵּשׁ לִפְנֵי צֵאת הַכּוֹכָבִים, כְּדֵי שֶׁשֶּׁבַע הַשַּׁבָּתוֹת יִהְיוּ תְּמִימוֹת – שְׁלֵמוֹת.","פֶּרֶק ע״א, הֲלָכָה ב׳","חַג הַשָּׁבוּעוֹת"],["מָה נוֹהֲגִים לַעֲשׂוֹת בְּלֵיל שָׁבוּעוֹת?",["לָלֶכֶת לִישֹׁן מֻקְדָּם","לְטַיֵּל בַּפַּארְק","לִהְיוֹת עֵרִים וְלַעֲסֹק בַּתּוֹרָה"],2,"נוֹהֲגִים לִהְיוֹת עֵרִים כָּל הַלַּיְלָה וְלִלְמֹד תּוֹרָה, וּבְכָךְ מְתַקְּנִים אֶת מָה שֶׁיִּשְׂרָאֵל יָשְׁנוּ בַּלַּיְלָה שֶׁלִּפְנֵי מַתַּן תּוֹרָה.","פֶּרֶק ע״א, הֲלָכָה ג׳","חַג הַשָּׁבוּעוֹת"],["מִי שֶׁיּוֹדֵעַ שֶׁלֹּא יוּכַל לְהִתְפַּלֵּל שַׁחֲרִית כָּרָאוּי – מָה עָדִיף לוֹ?",["לְהִתְפַּלֵּל מַהֵר וּבְלִי כַּוָּנָה","לִישֹׁן כְּשֶׁמִּתְעַיֵּף וּלְהִתְפַּלֵּל כָּרָאוּי בַּבֹּקֶר","לְדַלֵּג עַל תְּפִלַּת שַׁחֲרִית"],1,"רָאוּי לְהִתְאַמֵּץ לִהְיוֹת עֵרָנִיִּים בִּתְפִלַּת שַׁחֲרִית. מִי שֶׁיּוֹדֵעַ שֶׁלֹּא יוּכַל, עָדִיף שֶׁיֵּלֵךְ לִישֹׁן וְיִתְפַּלֵּל בַּבֹּקֶר כָּרָאוּי.","פֶּרֶק ע״א, הֲלָכָה ד׳","חַג הַשָּׁבוּעוֹת"],["מָה נָהֲגוּ בְּחֵלֶק מֵהַקְּהִלּוֹת בִּשְׁעַת קְרִיאַת עֲשֶׂרֶת הַדִּבְּרוֹת?",["לַעֲמֹד, כְּמוֹ בְּמַעֲמַד מַתַּן תּוֹרָה","לָשֶׁבֶת עַל הָרִצְפָּה","לָצֵאת מִבֵּית הַכְּנֶסֶת"],0,"בְּחֵלֶק מֵהַקְּהִלּוֹת נָהֲגוּ לַעֲמֹד בִּשְׁעַת קְרִיאַת עֲשֶׂרֶת הַדִּבְּרוֹת, כְּמוֹ בְּמַעֲמַד מַתַּן תּוֹרָה.","פֶּרֶק ע״א, הֲלָכָה ה׳","חַג הַשָּׁבוּעוֹת"],["מָה עוֹשִׂים בְּיוֹם חַג הַשָּׁבוּעוֹת?",["מִתְעַנִּים כָּל הַיּוֹם","רַק אוֹכְלִים, בְּלִי לִלְמֹד","שְׂמֵחִים בְּמַאֲכָל וּמוֹסִיפִים בְּלִמּוּד תּוֹרָה"],2,"מִצְוָה לִשְׂמֹחַ בְּמַאֲכָל וּבְמִשְׁתֶּה בְּיוֹם שֶׁנִּתְּנָה בּוֹ תּוֹרָה, וְיֵשׁ לְהִתְאַמֵּץ גַּם לְהוֹסִיף בְּלִמּוּד הַתּוֹרָה.","פֶּרֶק ע״א, הֲלָכוֹת ו׳, ח׳","חַג הַשָּׁבוּעוֹת"],["אֵילוּ מַאֲכָלִים נָהֲגוּ יִשְׂרָאֵל לֶאֱכֹל בְּשָׁבוּעוֹת?",["מַצּוֹת","מַאַכְלֵי חָלָב","סֻפְגָּנִיּוֹת"],1,"נָהֲגוּ לֶאֱכֹל מַאַכְלֵי חָלָב, כִּי הַתּוֹרָה נִמְשְׁלָה לְחָלָב: ״דְּבַשׁ וְחָלָב תַּחַת לְשׁוֹנֵךְ״.","פֶּרֶק ע״א, הֲלָכָה ז׳","חַג הַשָּׁבוּעוֹת"],["אֵילוּ סְפָרִים, הַקְּשׁוּרִים לְדָוִד הַמֶּלֶךְ, נוֹהֲגִים לִלְמֹד וְלִקְרֹא בְּשָׁבוּעוֹת?",["סֵפֶר תְּהִלִּים וּמְגִלַּת רוּת","מְגִלַּת אֶסְתֵּר","הַגָּדָה שֶׁל פֶּסַח"],0,"לוֹמְדִים תְּהִלִּים כִּי זֶה יוֹם פְּטִירַת דָּוִד הַמֶּלֶךְ, וְקוֹרְאִים מְגִלַּת רוּת כִּי נִזְכַּר בָּהּ יִחוּסוֹ שֶׁל דָּוִד.","פֶּרֶק ע״א, הֲלָכוֹת ט׳, י׳","חַג הַשָּׁבוּעוֹת"],["כְּשֶׁחַג הַשָּׁבוּעוֹת חָל בְּשַׁבָּת, מָתַי מַקְרִיבִים אֶת עוֹלַת הָרְאִיָּה?",["בְּעֶרֶב הַחַג","בְּשַׁבָּת עַצְמָהּ","לְמָחֳרַת הַחַג"],2,"כְּשֶׁבֵּית הַמִּקְדָּשׁ קַיָּם, עוֹלִים לָרֶגֶל וּמַקְרִיבִים עוֹלַת רְאִיָּה. כְּשֶׁהַחַג חָל בְּשַׁבָּת – מַקְרִיבִים אוֹתָהּ לְמָחֳרַת הַחַג.","פֶּרֶק ע״א, הֲלָכָה י״א","חַג הַשָּׁבוּעוֹת"],["מָה רָאוּי לַעֲשׂוֹת בְּיוֹם אִסְרוּ חַג?",["לְהִתְעַנּוֹת וּלְהַסְפִּיד","לֶאֱכֹל וְלִשְׁתּוֹת, וְלֹא לְהִתְעַנּוֹת","לֹא לֶאֱכֹל בָּשָׂר"],1,"״אִסְרוּ חַג״ – קוֹשְׁרִים אֶת הַחַג לִימֵי הַחֹל. אֵין מִתְעַנִּים וְאֵין מַסְפִּידִים בּוֹ, וְהָעוֹשֶׂה אִסּוּר לַחַג בַּאֲכִילָה וּשְׁתִיָּה – כְּאִלּוּ בָּנָה מִזְבֵּחַ וְהִקְרִיב עָלָיו קָרְבָּן.","פֶּרֶק ע״א, הֲלָכוֹת י״ב-י״ד","חַג הַשָּׁבוּעוֹת"],["מָה קָרָה בְּתִשְׁעָה בְּאָב?",["נְבוּכַדְנֶצַּר הִקִּיף אֶת יְרוּשָׁלַיִם","בֵּית הַמִּקְדָּשׁ חָרַב","נִרְצַח גְּדַלְיָה בֶּן אֲחִיקָם"],1,"בְּתִשְׁעָה בְּאָב חָרְבוּ בֵּית הַמִּקְדָּשׁ הָרִאשׁוֹן וּבֵית הַמִּקְדָּשׁ הַשֵּׁנִי. הַמָּצוֹר הָיָה בַּעֲשָׂרָה בְּטֵבֵת, וּגְדַלְיָה נִרְצַח בִּשְׁלִישִׁי בְּתִשְׁרֵי.","פֶּרֶק ע״ב, הֲלָכָה א׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["הַאִם גַּם בְּיָמֵינוּ צָמִים בְּצוֹמוֹת הַחֻרְבָּן?",["לֹא, כְּבָר אֵין צֹרֶךְ","כֵּן, עַד שֶׁיָּבוֹא מָשִׁיחַ","רַק בְּתִשְׁעָה בְּאָב"],1,"גַּם בְּיָמֵינוּ, יְמֵי רֵאשִׁית צְמִיחַת גְּאֻלָּתֵנוּ, מְחֻיָּבִים בְּכָל הַצּוֹמוֹת עַד שֶׁיָּבוֹא מְשִׁיחַ צִדְקֵנוּ וּבֵית הַמִּקְדָּשׁ יִבָּנֶה.","פֶּרֶק ע״ב, הֲלָכָה ב׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["לָמָּה מִתְעַנִּים בְּיָמִים אֵלּוּ?",["כְּדֵי לְעוֹרֵר אֶת הַלְּבָבוֹת לִתְשׁוּבָה","כְּדֵי לִשְׁמֹר עַל הַבְּרִיאוּת","כְּדֵי לַחְסֹךְ אֹכֶל"],0,"מִתְעַנִּים מִפְּנֵי הַצָּרוֹת שֶׁאֵרְעוּ בְּיָמִים אֵלּוּ, כְּדֵי לְעוֹרֵר אֶת הַלְּבָבוֹת לִתְשׁוּבָה.","פֶּרֶק ע״ב, הֲלָכָה ג׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["בְּצוֹם גְּדַלְיָה, מָתַי מַתְחִילִים לְהִתְעַנּוֹת?",["מֵהָעֶרֶב","בַּבֹּקֶר","בַּצָּהֳרַיִם"],1,"בְּצוֹם גְּדַלְיָה, עֲשָׂרָה בְּטֵבֵת וְי״ז בְּתַמּוּז מַתְחִילִים לְהִתְעַנּוֹת בַּבֹּקֶר בִּלְבַד, וּמֻתָּרִים בִּרְחִיצָה וּבִנְעִילַת הַסַּנְדָּל.","פֶּרֶק ע״ב, הֲלָכָה ד׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["כַּמָּה זְמַן נִמְשָׁכִים יְמֵי בֵּין הַמְּצָרִים?",["שָׁבוּעַ אֶחָד","חֹדֶשׁ שָׁלֵם","שְׁלֹשָׁה שָׁבוּעוֹת"],2,"שְׁלֹשֶׁת הַשָּׁבוּעוֹת שֶׁבֵּין י״ז בְּתַמּוּז לְתִשְׁעָה בְּאָב נִקְרָאִים יְמֵי בֵּין הַמְּצָרִים, וְנוֹהֲגִים בָּהֶם מִנְהֲגֵי אֲבֵלוּת.","פֶּרֶק ע״ב, הֲלָכָה ה׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["עַל מָה טוֹב שֶׁלֹּא לְבָרֵךְ שֶׁהֶחֱיָנוּ בְּבֵין הַמְּצָרִים?",["בֶּגֶד חָדָשׁ","לֶחֶם","כּוֹס מַיִם"],0,"בִּימֵי בֵּין הַמְּצָרִים טוֹב שֶׁלֹּא לְבָרֵךְ שֶׁהֶחֱיָנוּ עַל פְּרִי אוֹ בֶּגֶד חָדָשׁ, כִּי אֵיךְ יְבָרֵךְ שֶׁזָּכָה לַזְּמַן הַזֶּה?","פֶּרֶק ע״ב, הֲלָכָה ו׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["בְּאֵיזֶה אֵרוּעַ מְבָרְכִים שֶׁהֶחֱיָנוּ גַּם בְּבֵין הַמְּצָרִים?",["מְסִבַּת יוֹם הֻלֶּדֶת","קְנִיַּת כֵּלִים","בְּרִית מִילָה"],2,"בִּבְרִית מִילָה וּבְפִדְיוֹן הַבֵּן מְבָרְכִים שֶׁהֶחֱיָנוּ גַּם בִּימֵי בֵּין הַמְּצָרִים.","פֶּרֶק ע״ב, הֲלָכָה ז׳-ח׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["מָה נֶאֱסַר בִּימֵי בֵּין הַמְּצָרִים?",["לִקְרֹא סֵפֶר","רִקּוּדִים וּמְחוֹלוֹת","לָלֶכֶת לְבֵית הַכְּנֶסֶת"],1,"רִקּוּדִים וּמְחוֹלוֹת נֶאֶסְרוּ בְּיָמִים אֵלּוּ, וְיֵשׁ מַחְמִירִים שֶׁלֹּא לִשְׁמֹעַ כְּלֵי זֶמֶר. בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים גַּם לֹא מִסְתַּפְּרִים.","פֶּרֶק ע״ב, הֲלָכָה ט׳-י׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["מָה נוֹהֲגִים שֶׁלֹּא לַעֲשׂוֹת בִּימֵי בֵּין הַמְּצָרִים?",["לְהִתְחַתֵּן","לְהִתְפַּלֵּל","לִלְמֹד תּוֹרָה"],0,"נוֹהֲגִים שֶׁלֹּא לְהִתְחַתֵּן בִּימֵי בֵּין הַמְּצָרִים.","פֶּרֶק ע״ב, הֲלָכָה י״א","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["מִשֶּׁנִּכְנַס אָב מְמַעֲטִין בְּשִׂמְחָה. אֵיזוֹ עֲבוֹדַת בִּנְיָן מֻתֶּרֶת בְּכָל זֹאת?",["שִׁפּוּץ הַבַּיִת לְנוֹחוּת","תִּקּוּן קִיר שֶׁעָלוּל לִפֹּל","בְּנִיַּת בֵּית חַתְנוּת"],1,"מְמַעֲטִים בְּבִנְיָן שֶׁל שִׂמְחָה, אֲבָל אִם יֵשׁ הֶכְרֵחַ, כְּמוֹ קִיר שֶׁעָלוּל לִפֹּל, מֻתָּר לְתַקֵּן אוֹתוֹ.","פֶּרֶק ע״ב, הֲלָכוֹת י״ב-י״ג","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["אֵיךְ נִקְרֵאת הַשַּׁבָּת שֶׁלִּפְנֵי תִּשְׁעָה בְּאָב?",["שַׁבַּת זָכוֹר","שַׁבַּת שׁוּבָה","שַׁבַּת חֲזוֹן"],2,"הִיא נִקְרֵאת שַׁבַּת ״חֲזוֹן״ עַל שֵׁם הַמִּלִּים הַפּוֹתְחוֹת אֶת הַהַפְטָרָה: ״חֲזוֹן יְשַׁעְיָהוּ בֶן אָמוֹץ״.","פֶּרֶק ע״ב, הֲלָכָה י״ד","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["תִּשְׁעָה בְּאָב חָל בְּיוֹם רִאשׁוֹן. מָתַי נוֹהֲגִים דִּינֵי הַשָּׁבוּעַ?",["רַק בְּיוֹם הַתַּעֲנִית עַצְמוֹ","שִׁבְעָה יָמִים לִפְנֵי כֵן","חֲמִשָּׁה יָמִים לִפְנֵי כֵן"],0,"הַשָּׁבוּעַ מַתְחִיל בְּמוֹצָאֵי שַׁבַּת חֲזוֹן, וְלָכֵן כְּשֶׁהַתַּעֲנִית בְּיוֹם רִאשׁוֹן, הַדִּינִים נוֹהֲגִים בְּיוֹם הַתַּעֲנִית בִּלְבַד.","פֶּרֶק ע״ב, הֲלָכָה ט״ו","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["בַּשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב, מָה אָסוּר לַעֲשׂוֹת בַּחֲנוּת הַבְּגָדִים?",["לְהִסְתַּכֵּל בַּחַלּוֹן הָרַאֲוָה","לִקְנוֹת בְּגָדִים חֲדָשִׁים","לַעֲבֹר לְיַד הַחֲנוּת"],1,"אָסוּר לִקְנוֹת בְּגָדִים חֲדָשִׁים, אֲפִלּוּ אִם רוֹצִים לִלְבֹּשׁ אוֹתָם רַק אַחֲרֵי תִּשְׁעָה בְּאָב.","פֶּרֶק ע״ב, הֲלָכָה ט״ז","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["בַּשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב, מָה אָסוּר?",["לְכַבֵּס בְּגָדִים בִּמְכוֹנָה","לְסַדֵּר אֶת הָאָרוֹן","לְקַפֵּל בְּגָדִים יְשָׁנִים"],0,"אָסוּר לְכַבֵּס, וְגַם אָסוּר לִלְבֹּשׁ בְּגָדִים מְכֻבָּסִים וּלְהִשְׁתַּמֵּשׁ בְּמַגָּבוֹת וּמַצָּעִים מְכֻבָּסִים.","פֶּרֶק ע״ב, הֲלָכוֹת י״ז-י״ח","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["לְפִי מִנְהַג הָאַשְׁכְּנַזִּים, מֵאֵימָתַי מַחְמִירִים בְּדִינֵי הַבְּגָדִים וְהַכְּבִיסָה?",["מִפֶּסַח","מֵרֹאשׁ חֹדֶשׁ אָב","מִט״וּ בְּאָב"],1,"מִנְהַג קְהִלּוֹת הָאַשְׁכְּנַזִּים וְחֵלֶק מִקְּהִלּוֹת הַסְּפָרַדִּים לְהַחְמִיר מֵרֹאשׁ חֹדֶשׁ אָב וְעַד אַחֲרֵי הַתַּעֲנִית.","פֶּרֶק ע״ב, הֲלָכָה י״ט","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["בְּאֶרֶץ יִשְׂרָאֵל חַם מְאוֹד. מָה עוֹשִׂים כְּדֵי שֶׁיִּהְיֶה אֶפְשָׁר לְהַחְלִיף בְּגָדִים?",["מְכַבְּסִים בַּשָּׁבוּעַ הַזֶּה","לוֹבְשִׁים אוֹתָם שָׁעָה קַלָּה לִפְנֵי כֵן","לֹא מַחְלִיפִים בְּגָדִים בִּכְלָל"],1,"לוֹבְשִׁים אֶת הַבְּגָדִים לְשָׁעָה קַלָּה לִפְנֵי זְמַן הָאִסּוּר, וְאָז מֻתָּר לִלְבֹּשׁ אוֹתָם בִּימֵי הָאֲבֵלוּת.","פֶּרֶק ע״ב, הֲלָכָה כ׳","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["אֵיזֶה בְּגָדִים נוֹהֲגִים לְהָקֵל וּלְכַבֵּס בַּיָּמִים הָאֵלֶּה?",["בִּגְדֵי שַׁבָּת","בִּגְדֵי יְלָדִים קְטַנִּים","בְּגָדִים שֶׁל אַבָּא"],1,"נוֹהֲגִים לְהָקֵל וּלְכַבֵּס בִּגְדֵי יְלָדִים קְטַנִּים, כִּי הֵם מִתְלַכְלְכִים בִּתְדִירוּת גְּבוֹהָה.","פֶּרֶק ע״ב, הֲלָכָה כ״א","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["מָה אֵין שׁוֹתִים מֵרֹאשׁ חֹדֶשׁ אָב וְעַד הַתַּעֲנִית?",["מַיִם","יַיִן","חָלָב"],1,"מֵרֹאשׁ חֹדֶשׁ אָב וְעַד הַתַּעֲנִית אֵין אוֹכְלִים בָּשָׂר וְאֵין שׁוֹתִים יַיִן (וּמִיץ עֲנָבִים), וְכָל אֶחָד יִנְהַג כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק ע״ב, הֲלָכָה כ״ג","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["אֵיזֶה מַאֲכָל מֻתָּר לֶאֱכֹל בַּיָּמִים שֶׁאָסוּר בָּהֶם בָּשָׂר?",["עוֹף צָלוּי","סְטֵייק בָּקָר","דָּג"],2,"הָאִסּוּר כּוֹלֵל בְּשַׂר בְּהֵמָה וּבְשַׂר עוֹף, אַךְ מֻתָּר לֶאֱכֹל דָּגִים.","פֶּרֶק ע״ב, הֲלָכָה כ״ד","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["מַיִם שֶׁל מְרַק עוֹף בַּיָּמִים הָאֵלּוּ – מָה הַדִּין?",["כָּל אֶחָד כְּמִנְהַג אֲבוֹתָיו","מֻתָּר לְכֻלָּם בְּלִי סָפֵק","אָסוּר לְכֻלָּם בְּלִי סָפֵק"],0,"יֵשׁ אוֹמְרִים שֶׁמֻּתָּר לֶאֱכֹל תַּבְשִׁיל שֶׁהִתְבַּשֵּׁל עִם בָּשָׂר, וְיֵשׁ אוֹמְרִים שֶׁגַּם הוּא אָסוּר – וְכָל אֶחָד יִנְהַג כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק ע״ב, הֲלָכָה כ״ה","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["מָה הַדִּין בְּיֵין הַהַבְדָּלָה בַּיָּמִים הָאֵלּוּ?",["שׁוֹפְכִים אוֹתוֹ לַכִּיּוֹר","מֻתָּר לִשְׁתּוֹתוֹ","מַבְדִּילִים בְּלִי כּוֹס"],1,"מֻתָּר לִשְׁתּוֹת אֶת הַיַּיִן שֶׁל הַהַבְדָּלָה, וְיֵשׁ נוֹהֲגִים לָתֵת לִילָדִים קְטַנִּים לִשְׁתּוֹת אוֹתוֹ.","פֶּרֶק ע״ב, הֲלָכָה כ״ו","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["בְּאֵיזוֹ סְעוּדָה מֻתָּר לֶאֱכֹל בָּשָׂר בַּיָּמִים הָאֵלּוּ?",["סְעוּדַת יוֹם הֻלֶּדֶת","סְעוּדַת סִיּוּם מַסֶּכֶת","סְעוּדַת טִיּוּל"],1,"בִּסְעוּדַת מִצְוָה, כְּמוֹ בְּרִית מִילָה, פִּדְיוֹן הַבֵּן וְסִיּוּם מַסֶּכֶת, מֻתָּר לְכָל הַמִּשְׁתַּתְּפִים לֶאֱכֹל בָּשָׂר וְלִשְׁתּוֹת יַיִן.","פֶּרֶק ע״ב, הֲלָכָה כ״ז","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["חוֹלֶה שֶׁצָּרִיךְ בָּשָׂר – מָה עָדִיף שֶׁיֹּאכַל?",["בְּשַׂר בְּהֵמָה","בְּשַׂר עוֹף","נַקְנִיק"],1,"חוֹלֶה, וּמִי שֶׁמִּסִּבּוֹת בְּרִיאוּתִיּוֹת צָרִיךְ בָּשָׂר – עָדִיף שֶׁיֹּאכַל בְּשַׂר עוֹף וְלֹא בְּשַׂר בְּהֵמָה.","פֶּרֶק ע״ב, הֲלָכָה כ״ח","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["לִכְבוֹד מָה מֻתָּר לְהִתְרַחֵץ גַּם בְּמַיִם חַמִּים?",["לִכְבוֹד שַׁבָּת","לִכְבוֹד טִיּוּל","לִכְבוֹד מִשְׂחָק"],0,"רְחִיצָה לְתַעֲנוּג אֲסוּרָה בַּיָּמִים הָאֵלּוּ, אֲבָל לִכְבוֹד שַׁבָּת מֻתָּר לְהִתְרַחֵץ גַּם בְּמַיִם חַמִּים.","פֶּרֶק ע״ב, הֲלָכָה כ״ט-ל׳","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["שְׂחִיָּה בַּיָּם לְשֵׁם הֲנָאָה – מֵאֵימָתַי הִיא אֲסוּרָה?",["מִתִּשְׁעָה בְּאָב","מֵרֹאשׁ חֹדֶשׁ אָב","מֵרֹאשׁ הַשָּׁנָה"],1,"שְׂחִיָּה שֶׁמַּטְּרָתָהּ הֲנָאָה וּבִלּוּי אֲסוּרָה מֵרֹאשׁ חֹדֶשׁ.","פֶּרֶק ע״ב, הֲלָכָה ל״א","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["מָה לוֹבְשִׁים בְּשַׁבַּת ״חֲזוֹן״ לְפִי מִנְהַג רֹב הַקְּהִלּוֹת?",["בִּגְדֵי חֹל","בִּגְדֵי שַׁבָּת","בִּגְדֵי אֵבֶל"],1,"מִנְהַג רֹב קְהִלּוֹת יִשְׂרָאֵל לִלְבֹּשׁ בִּגְדֵי שַׁבָּת וּלְהִתְפַּלֵּל בִּנְעִימָה גַּם בְּשַׁבְּתוֹת בֵּין הַמְּצָרִים, וַאֲפִלּוּ בְּשַׁבַּת ״חֲזוֹן״, שֶׁבָּהּ מַפְטִירִים בַּ״חֲזוֹן יְשַׁעְיָהוּ״.","פֶּרֶק ע״ב, הֲלָכָה ל״ב-ל״ג","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["כַּמָּה תַּבְשִׁילִים אוֹכְלִים בַּסְּעוּדָה הַמַּפְסֶקֶת?",["תַּבְשִׁיל אֶחָד בִּלְבַד","שְׁנֵי תַּבְשִׁילִים","כָּל הַתַּבְשִׁילִים שֶׁרוֹצִים"],0,"בַּסְּעוּדָה הַמַּפְסֶקֶת אוֹכְלִים רַק תַּבְשִׁיל אֶחָד, אֲבָל פֵּרוֹת, יְרָקוֹת וּגְבִינוֹת מֻתָּרִים בְּלִי הַגְבָּלָה. יֵשׁ שֶׁנָּהֲגוּ לֶאֱכֹל עֲדָשִׁים אוֹ בֵּיצִים, סִימָן לַאֲבֵלוּת.","פֶּרֶק ע״ג, הֲלָכָה א׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["אֵיךְ יוֹשְׁבִים בַּסְּעוּדָה הַמַּפְסֶקֶת?",["עַל כִּסְאוֹת גְּבוֹהִים סְבִיב שֻׁלְחָן","עַל הַקַּרְקַע, וְלֹא שְׁלוֹשָׁה יַחַד","עַל הַמִּטָּה"],1,"נָהֲגוּ לָשֶׁבֶת עַל הַקַּרְקַע, וְלֹא יֵשְׁבוּ שְׁלוֹשָׁה אֲנָשִׁים בְּאוֹתוֹ מָקוֹם כְּדֵי שֶׁלֹּא יִתְחַיְּבוּ בְּזִמּוּן. כָּל אֶחָד אוֹכֵל בְּמָקוֹם אַחֵר וּמְבָרֵךְ לְעַצְמוֹ.","פֶּרֶק ע״ג, הֲלָכָה ב׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["אָכְלוּ בְּעֶרֶב תִּשְׁעָה בְּאָב לִפְנֵי חֲצוֹת הַיּוֹם. אֵיךְ אוֹכְלִים בַּסְּעוּדָה הַזֹּאת?",["רַק תַּבְשִׁיל אֶחָד","כָּרָגִיל","רַק לֶחֶם עִם אֵפֶר"],1,"רַק סְעוּדָה שֶׁאַחֲרֵי חֲצוֹת הַיּוֹם, שֶׁאֵין אַחֲרֶיהָ עוֹד סְעוּדָה, הִיא הַסְּעוּדָה הַמַּפְסֶקֶת. לִפְנֵי חֲצוֹת מֻתָּר לֶאֱכֹל כָּרָגִיל.","פֶּרֶק ע״ג, הֲלָכָה ג׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["מָה נָהֲגוּ לִלְמֹד אַחֲרֵי חֲצוֹת יוֹם שְׁמִינִי בְּאָב?",["כָּל מָה שֶׁרוֹצִים","לֹא לוֹמְדִים כְּלָל","רַק מָה שֶׁמֻּתָּר לִלְמֹד בְּתִשְׁעָה בְּאָב"],2,"לְאַחַר חֲצוֹת יוֹם שְׁמִינִי בְּאָב נָהֲגוּ לִלְמֹד רַק דְּבָרִים שֶׁמֻּתָּר לִלְמֹד בְּתִשְׁעָה בְּאָב עַצְמוֹ.","פֶּרֶק ע״ג, הֲלָכָה ד׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["כַּמָּה עִנּוּיִים יֵשׁ בְּתִשְׁעָה בְּאָב?",["חֲמִשָּׁה","שְׁלוֹשָׁה","אֶחָד"],0,"בְּתִשְׁעָה בְּאָב יֵשׁ חֲמִשָּׁה עִנּוּיִים: אֲכִילָה וּשְׁתִיָּה, רְחִיצָה, סִיכָה, נְעִילַת הַסַּנְדָּל וְתַשְׁמִישׁ הַמִּטָּה. לָכֵן הוּא חָמוּר מִשְּׁאָר תַּעֲנִיּוֹת הַחֻרְבָּן.","פֶּרֶק ע״ג, הֲלָכָה ה׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["יוֹלֶדֶת (עַד חֹדֶשׁ לְאַחַר הַלֵּדָה) – מָה דִּינָהּ בְּתַעֲנִית תִּשְׁעָה בְּאָב?",["חַיֶּבֶת לָצוּם כָּל הַיּוֹם","צָמָה רַק חֲצִי יוֹם","פְּטוּרָה מֵהַתַּעֲנִית"],2,"יוֹלֶדֶת עַד חֹדֶשׁ פְּטוּרָה, כִּי יֵשׁ חֲשָׁשׁ שֶׁתְּסַכֵּן אֶת עַצְמָהּ אוֹ אֶת הַתִּינוֹק. וְיֵשׁ אוֹמְרִים שֶׁאַחֲרֵי שָׁבוּעַ, אִם הִיא מַרְגִּישָׁה חֲזָקָה, רַשָּׁאִית לָצוּם.","פֶּרֶק ע״ג, הֲלָכָה ו׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["סָבָא זָקֵן שֶׁהַתַּעֲנִית גּוֹרֶמֶת לוֹ צַעַר גָּדוֹל – מָה עוֹשֶׂה?",["צָם עַד הַלַּיְלָה","אֵינוֹ מִתְעַנֶּה כְּלָל","צָם, וְאָסוּר לוֹ לִבְלֹעַ תְּרוּפוֹת"],1,"זְקֵנִים וּתְשׁוּשֵׁי כֹּחַ שֶׁהַצּוֹם קָשֶׁה לָהֶם מְאֹד אֵינָם מִתְעַנִּים כְּלָל, וּמֻתָּר לָהֶם לִבְלֹעַ תְּרוּפוֹת. חוֹלִים פְּטוּרִים מֵעִקַּר הַדִּין, אֲבָל נוֹהֲגִים לְהִתְעַנּוֹת כְּפִי יְכָלְתָּם בְּלִי לְהַזִּיק לְגוּפָם.","פֶּרֶק ע״ג, הֲלָכָה ז׳-ח׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["יֶלֶד בְּכִתָּה ד׳ – אֵיךְ הוּא נוֹהֵג בְּתִשְׁעָה בְּאָב?",["מִתְעַנֶּה מִסְפַּר שָׁעוֹת בִּלְבַד","צָם כָּל הַיּוֹם כְּמוֹ גָּדוֹל","אוֹכֵל כָּרָגִיל בְּלִי שׁוּם חִנּוּךְ"],0,"קְטַנִּים פְּטוּרִים, אֲבָל מְחַנְּכִים אוֹתָם לְהִתְעַנּוֹת מִסְפַּר שָׁעוֹת כְּדֵי שֶׁלֹּא יַגִּיעוּ לִידֵי סַכָּנָה. מְעֻבָּרוֹת וּמְנִיקוֹת צְרִיכוֹת לְהִתְעַנּוֹת, וְאִם יֵשׁ חֲשַׁשׁ סַכָּנָה יִתְיַעֲצוּ עִם תַּלְמִיד חָכָם.","פֶּרֶק ע״ג, הֲלָכָה ט׳-י׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["אֵיךְ נוֹטְלִים יָדַיִם בַּבֹּקֶר שֶׁל תִּשְׁעָה בְּאָב?",["רוֹחֲצִים אֶת כָּל הַגּוּף","עַד הַמַּרְפֵּק","רַק עַד קִשְׁרֵי הָאֶצְבָּעוֹת"],2,"אָסוּר לִרְחֹץ בְּתִשְׁעָה בְּאָב, אֲפִלּוּ רַק יָדַיִם אוֹ פָּנִים. בַּבֹּקֶר וּבִיצִיאָה מֵהַשֵּׁרוּתִים נוֹטְלִים רַק עַד קִשְׁרֵי הָאֶצְבָּעוֹת. כְּדֵי לְהָסִיר לִכְלוּךְ מֻתָּר לִרְחֹץ.","פֶּרֶק ע״ג, הֲלָכָה י״א-י״ג","תַּעֲנִית תִּשְׁעָה בְּאָב"],["אֵיזוֹ נַעַל מֻתֶּרֶת בְּתִשְׁעָה בְּאָב?",["נַעַל עוֹר","נַעַל בַּד אוֹ גּוּמִי","סַנְדָּל עוֹר"],1,"אָסוּר לִנְעֹל נַעֲלַיִם אוֹ סַנְדָּלִים מֵעוֹר, וּמֻתָּר לִנְעֹל נַעֲלֵי גּוּמִי, בַּד אוֹ חֹמֶר אַחֵר. וּמֵהַסְּעוּדָה הַמַּפְסֶקֶת עַד חֲצוֹת תִּשְׁעָה בְּאָב יוֹשְׁבִים עַל הַקַּרְקַע אוֹ עַל כִּסֵּא נָמוּךְ, כְּמוֹ אֲבֵלִים.","פֶּרֶק ע״ג, הֲלָכָה י״ד-ט״ו","תַּעֲנִית תִּשְׁעָה בְּאָב"],["חָבֵר אָמַר לְךָ ״שָׁלוֹם״ בְּתִשְׁעָה בְּאָב. אֵיךְ תָּשִׁיב לוֹ?",["בְּקוֹל רָם וּבִצְחוֹק גָּדוֹל","בְּשָׂפָה רָפָה וּבְכֹבֶד רֹאשׁ","בִּלְחִיצַת יָד וּבְשִׁירָה"],1,"אֵין שׁוֹאֲלִים שָׁלוֹם בְּתִשְׁעָה בְּאָב, וּמִי שֶׁשָּׁאֲלוּ בִּשְׁלוֹמוֹ מֵשִׁיב בְּשָׂפָה רָפָה וּבְכֹבֶד רֹאשׁ.","פֶּרֶק ע״ג, הֲלָכָה ט״ז","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["מָה נֶאֱמַר עַל מִי שֶׁעוֹשֶׂה מְלָאכָה בְּתִשְׁעָה בְּאָב?",["רוֹאֶה בְּרָכָה גְּדוֹלָה","אֵין לוֹ שׁוּם הֶבְדֵּל","אֵינוֹ רוֹאֶה סִימַן בְּרָכָה"],2,"כָּל הָעוֹשֶׂה מְלָאכָה בְּתִשְׁעָה בְּאָב אֵינוֹ רוֹאֶה סִימַן בְּרָכָה מֵאוֹתָהּ מְלָאכָה.","פֶּרֶק ע״ג, הֲלָכָה י״ז","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["אֵיזֶה סֵפֶר מֻתָּר לִלְמֹד בְּתִשְׁעָה בְּאָב?",["מְגִלַּת אֵיכָה וְדִבְרֵי חֻרְבָּן","סֵפֶר תְּהִלִּים שֶׁל שִׂמְחָה","גְּמָרָא בְּעִנְיַן חַג הַסֻּכּוֹת"],0,"לִמּוּד תּוֹרָה אָסוּר מִפְּנֵי שֶׁהוּא מְשַׂמֵּחַ, אֲבָל מֻתָּר לִלְמֹד דְּבָרִים שֶׁקְּשׁוּרִים לַתַּעֲנִית אוֹ לַחֻרְבָּן.","פֶּרֶק ע״ג, הֲלָכָה י״ח","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים, בְּאֵיזוֹ תְּפִלָּה מְנִיחִים תְּפִלִּין בְּתִשְׁעָה בְּאָב, אַחֲרֵי שֶׁבַּלַּיְלָה קָרְאוּ אֵיכָה?",["בְּעַרְבִית","בְּמִנְחָה","בְּשַׁחֲרִית"],1,"בְּלֵיל תִּשְׁעָה בְּאָב קוֹרְאִים אֵיכָה וְאוֹמְרִים קִינוֹת. בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים וּבְחֵלֶק מִקְּהִלּוֹת הַסְּפָרַדִּים מְנִיחִים טַלִּית וּתְפִלִּין רַק בְּמִנְחָה, וּבְחֵלֶק מִקְּהִלּוֹת הַסְּפָרַדִּים – כְּבָר בְּשַׁחֲרִית.","פֶּרֶק ע״ג, הֲלָכוֹת י״ט-כ׳","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["תִּשְׁעָה בְּאָב חָל בְּשַׁבָּת וְנִדְחָה לְיוֹם רִאשׁוֹן. מָה מֻתָּר בַּסְּעוּדָה הַמַּפְסֶקֶת?",["רַק לֶחֶם וּמַיִם","בָּשָׂר וְיַיִן עַד הַשְּׁקִיעָה","שׁוּם אֲכִילָה"],1,"מֻתָּר לֶאֱכֹל בָּשָׂר וְיַיִן, אֲפִלּוּ כִּסְעוּדַת שְׁלֹמֹה הַמֶּלֶךְ, אַךְ יֵשׁ לְהַפְסִיק לִפְנֵי שְׁקִיעַת הַחַמָּה.","פֶּרֶק ע״ג, הֲלָכָה כ״א","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["בְּמוֹצָאֵי שַׁבָּת שֶׁהוּא לֵיל תִּשְׁעָה בְּאָב – עַל מָה מְבָרְכִים אַחֲרֵי עַרְבִית?",["עַל הַבְּשָׂמִים","עַל כּוֹס יַיִן","עַל הַנֵּר"],2,"בְּצֵאת הַשַּׁבָּת אוֹמְרִים ״הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל״, חוֹלְצִים נַעֲלֵי עוֹר, וּלְאַחַר עַרְבִית מְבָרְכִים עַל הַנֵּר ״בּוֹרֵא מְאוֹרֵי הָאֵשׁ״.","פֶּרֶק ע״ג, הֲלָכוֹת כ״ב-כ״ג","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["בְּמוֹצָאֵי הַתַּעֲנִית שֶׁנִּדְחֲתָה – עַל מָה מַבְדִּילִים?",["עַל הַכּוֹס","עַל הַנֵּר","עַל הַבְּשָׂמִים"],0,"בְּמוֹצָאֵי הַתַּעֲנִית מַבְדִּילִים עַל הַכּוֹס (וּמֻתָּר לִשְׁתּוֹת), אַךְ אֵין מְבָרְכִים עַל הַנֵּר וְעַל הַבְּשָׂמִים.","פֶּרֶק ע״ג, הֲלָכָה כ״ד","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["מָה קָרָה לְבֵית הַמִּקְדָּשׁ הָרִאשׁוֹן בָּעֲשִׂירִי בְּאָב, שֶׁבִּגְלָלוֹ לֹא אוֹכְלִים בּוֹ בָּשָׂר?",["נִבְנָה מֵחָדָשׁ","הָיָה נִשְׂרָף כָּל הַיּוֹם","נִפְתַּח לִתְפִלָּה"],1,"בְּתִשְׁעָה בְּאָב לִפְנוֹת עֶרֶב הִצִּיתוּ בּוֹ אֵשׁ, וְהָיָה נִשְׂרָף בְּמֶשֶׁךְ כָּל יוֹם עֲשִׂירִי בְּאָב. לָכֵן נָהֲגוּ שֶׁלֹּא לֶאֱכֹל בָּשָׂר וְלֹא לִשְׁתּוֹת יַיִן בָּעֲשִׂירִי בְּאָב.","פֶּרֶק ע״ג, הֲלָכוֹת כ״ה-כ״ו","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["עֲשִׂירִי בְּאָב חָל בְּיוֹם שִׁשִּׁי. מֵאֵימָתַי הַכֹּל מֻתָּר (גַּם לְמִי שֶׁמַּחְמִיר בְּמִנְהֲגֵי אֲבֵלוּת)?",["מִבֹּקֶר עֲשִׂירִי בְּאָב","רַק בְּמוֹצָאֵי שַׁבָּת","רַק בַּלַּיְלָה"],0,"יֵשׁ מַחְמִירִים בִּשְׁאַר מִנְהֲגֵי הָאֲבֵלוּת וְכָל אֶחָד לְפִי מִנְהַג אֲבוֹתָיו, אֲבָל כְּשֶׁיֵּשׁ חֲשָׁשׁ לִפְגִיעָה בַּהֲכָנוֹת לְשַׁבָּת – הַכֹּל מֻתָּר כְּבָר מִבֹּקֶר עֲשִׂירִי בְּאָב.","פֶּרֶק ע״ג, הֲלָכוֹת כ״ז-כ״ח","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["הַתַּעֲנִית נִדְחֲתָה לָעֲשִׂירִי בְּאָב. מָתַי מֻתָּר לֶאֱכֹל בָּשָׂר?",["מִיָּד בְּמוֹצָאֵי הַתַּעֲנִית","אַחֲרֵי שָׁבוּעַ","בְּבֹקֶר אַחַד עָשָׂר בְּאָב"],2,"מֻתָּר לֶאֱכֹל בָּשָׂר וְלִשְׁתּוֹת יַיִן מִיָּד בְּבֹקֶר אַחַד עָשָׂר בְּאָב, וּשְׁאַר מִנְהֲגֵי הָאֲבֵלוּת מִסְתַּיְּמִים מִיָּד בְּמוֹצָאֵי הַתַּעֲנִית.","פֶּרֶק ע״ג, הֲלָכָה כ״ט","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["בְּאֵיזֶה יוֹם עָלָה מֹשֶׁה רַבֵּנוּ לְהַר סִינַי בַּפַּעַם הַשְּׁנִיָּה, וּמָה נִשְׁמַע אָז בַּמַּחֲנֶה?",["בְּי״ז בְּתַמּוּז – קוֹל שִׁירָה","בְּא׳ בֶּאֱלוּל – קוֹל שׁוֹפָר","בְּי׳ בְּתִשְׁרֵי – קוֹל פַּעֲמוֹנִים"],1,"בְּא׳ בֶּאֱלוּל עָלָה מֹשֶׁה לְאַרְבָּעִים יָמִים, עַד י׳ בְּתִשְׁרֵי, וְעָבַר קוֹל שׁוֹפָר בַּמַּחֲנֶה שֶׁלֹּא יִטְעוּ עוֹד בַּעֲבוֹדָה זָרָה. לָכֵן תּוֹקְעִים מֵרֹאשׁ חֹדֶשׁ אֱלוּל.","פֶּרֶק ע״ד, הֲלָכוֹת א׳-ב׳","חֹדֶשׁ אֱלוּל"],["מָה עִקַּר הַסְּלִיחוֹת?",["אֲמִירַת י״ג הַמִּדּוֹת","אֲכִילַת תַּפּוּחַ בִּדְבַשׁ","נְטִילַת לוּלָב"],0,"עִקַּר הַסְּלִיחוֹת הוּא אֲמִירַת שְׁלוֹשׁ עֶשְׂרֵה הַמִּדּוֹת. ה׳ הֶרְאָה לְמֹשֶׁה סֵדֶר תְּפִלָּה וְאָמַר: יַעֲשׂוּ לְפָנַי כַּסֵּדֶר הַזֶּה וַאֲנִי מוֹחֵל לָהֶם.","פֶּרֶק ע״ד, הֲלָכָה ג׳","חֹדֶשׁ אֱלוּל"],["אֵיךְ אוֹמְרִים אֶת י״ג הַמִּדּוֹת?",["בִּשְׁכִיבָה וּבִמְהִירוּת","בְּרִיצָה בֵּין הַסַּפְסָלִים","בַּעֲמִידָה, בְּכַוָּנָה, וְשׁוֹחִים קְצָת"],2,"אוֹמְרִים בְּנַחַת וּבְכַוָּנָה, עוֹמְדִים וְשׁוֹחִים (מִתְכּוֹפְפִים) קְצָת, וּמַפְסִיקִים מְעַט בֵּין ״בְּשֵׁם״ לְשֵׁם ה׳ וּבֵין שֵׁם ה׳ הָרִאשׁוֹן לַשֵּׁנִי.","פֶּרֶק ע״ד, הֲלָכוֹת ד׳-ה׳","חֹדֶשׁ אֱלוּל"],["אֵיפֹה אוֹמְרִים אֶת י״ג הַמִּדּוֹת כִּתְפִלָּה וּבַקָּשַׁת רַחֲמִים?",["רַק בְּמִנְיָן","לְבַד בַּחֶדֶר","בְּטִיּוּל בַּגִּנָּה"],0,"י״ג הַמִּדּוֹת הֵן דָּבָר שֶׁבִּקְדֻשָּׁה, וְכִתְפִלָּה אוֹמְרִים אוֹתָן רַק בְּמִנְיָן. יָחִיד יָכוֹל לְאָמְרָן כְּקוֹרֵא בַּתּוֹרָה, וְעַל פִּי הַקַּבָּלָה רָאוּי לְהִמָּנַע.","פֶּרֶק ע״ד, הֲלָכָה ו׳","חֹדֶשׁ אֱלוּל"],["מָתַי אוֹמְרִים סְלִיחוֹת בִּקְהִלּוֹת הַסְּפָרַדִּים, וּמָה עוֹשִׂים אִם הַשּׁוֹפָר מַפְרִיעַ לַשְּׁכֵנִים?",["בַּצָּהֳרַיִם, וְתוֹקְעִים חָזָק יוֹתֵר","בְּאַשְׁמֹרֶת הַבֹּקֶר, וְתוֹקְעִים אַחֲרֵי שַׁחֲרִית","בַּעֶרֶב, וְלֹא תּוֹקְעִים כְּלָל"],1,"הַסְּפָרַדִּים וְהַתֵּימָנִים קָמִים בְּאַשְׁמֹרֶת הַבֹּקֶר מִב׳ בֶּאֱלוּל עַד יוֹם הַכִּפּוּרִים. אִם הַתְּקִיעוֹת מַפְרִיעוֹת לַשְּׁכֵנִים – מְבַטְּלִים אוֹתָן וְתוֹקְעִים אַחֲרֵי שַׁחֲרִית.","פֶּרֶק ע״ד, הֲלָכוֹת ז׳-ח׳","חֹדֶשׁ אֱלוּל"],["מָה נוֹהֲגִים בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים?",["תּוֹקְעִים רַק בְּרֹאשׁ הַשָּׁנָה","אוֹמְרִים סְלִיחוֹת מִב׳ בֶּאֱלוּל","תּוֹקְעִים בְּסוֹף הַתְּפִלָּה עַד כ״ח בֶּאֱלוּל"],2,"הָאַשְׁכְּנַזִּים תּוֹקְעִים בְּסִיּוּם הַתְּפִלָּה מֵרֹאשׁ חֹדֶשׁ עַד כ״ח בֶּאֱלוּל, וּמַתְחִילִים סְלִיחוֹת בְּמוֹצָאֵי הַשַּׁבָּת שֶׁלִּפְנֵי רֹאשׁ הַשָּׁנָה (וְאִם ר״ה בְּיוֹם ב׳ אוֹ ג׳ – בַּשַּׁבָּת הַקּוֹדֶמֶת).","פֶּרֶק ע״ד, הֲלָכוֹת ט׳-י׳","חֹדֶשׁ אֱלוּל"],["מָתַי אָסוּר לוֹמַר סְלִיחוֹת?",["לִפְנֵי חֲצוֹת הַלַּיְלָה","אַחַר חֲצוֹת הַלַּיְלָה","בַּבֹּקֶר"],0,"אֵין לוֹמַר סְלִיחוֹת לִפְנֵי חֲצוֹת הַלַּיְלָה. מִי שֶׁאֵינוֹ יָכוֹל אַחַר חֲצוֹת – יֹאמַר אוֹתָן בַּבֹּקֶר.","פֶּרֶק ע״ד, הֲלָכָה י״א׳","חֹדֶשׁ אֱלוּל"],["אֶת מִי בּוֹחֲרִים לִשְׁלִיחַ צִבּוּר בַּיָּמִים הַנּוֹרָאִים?",["יֶלֶד קָטָן","הָגוּן, גָּדוֹל בַּתּוֹרָה, מֵעַל שְׁלוֹשִׁים וְנָשׂוּי","מִי שֶׁקּוֹלוֹ הֲכִי חָזָק"],1,"בּוֹחֲרִים אֶת הֶהָגוּן וְהַגָּדוֹל בַּתּוֹרָה וּבְמַעֲשִׂים טוֹבִים, מֵעַל גִּיל שְׁלוֹשִׁים וְנָשׂוּי. אִם אֵין – כָּל אֶחָד מִיִּשְׂרָאֵל כָּשֵׁר, וּבִלְבַד שֶׁיִּהְיֶה רָצוּי לַקָּהָל.","פֶּרֶק ע״ד, הֲלָכָה י״ב׳","חֹדֶשׁ אֱלוּל"],["אֵיזֶה מִזְמוֹר מוֹסִיפִים הָאַשְׁכְּנַזִּים מֵרֹאשׁ חֹדֶשׁ אֱלוּל עַד הוֹשַׁעְנָא רַבָּה?",["לְדָוִד ה׳ אוֹרִי וְיִשְׁעִי","הַלֵּל","מְגִלַּת אֶסְתֵּר"],0,"אוֹמְרִים מִזְמוֹר כ״ז: ״ה׳ אוֹרִי״ – בְּרֹאשׁ הַשָּׁנָה, ״וְיִשְׁעִי״ – בְּיוֹם הַכִּפּוּרִים.","פֶּרֶק ע״ד, הֲלָכָה י״ג׳","חֹדֶשׁ אֱלוּל"],["מָה נוֹהֲגִים לַעֲשׂוֹת בְּחֹדֶשׁ אֱלוּל?",["לִבְנוֹת סֻכָּה","לְהַדְלִיק נֵרוֹת חֲנֻכָּה","לְבָרֵךְ ״לְשָׁנָה טוֹבָה״ וְלִבְדֹּק תְּפִלִּין וּמְזוּזוֹת"],2,"בְּמִכְתָּב מְבָרְכִים ״לְשָׁנָה טוֹבָה תִּכָּתֵב וְתֵחָתֵם״, וְיֵשׁ נוֹהֲגִים לִבְדֹּק תְּפִלִּין וּמְזוּזוֹת אֵצֶל סוֹפֵר מֻמְחֶה וִירֵא שָׁמַיִם.","פֶּרֶק ע״ד, הֲלָכוֹת י״ד׳-ט״ו׳","חֹדֶשׁ אֱלוּל"],["מָה נוֹהֲגִים לוֹמַר בְּעֶרֶב רֹאשׁ הַשָּׁנָה?",["סֵדֶר הַתָּרַת נְדָרִים","הַגָּדָה שֶׁל פֶּסַח","מְגִלַּת אֶסְתֵּר"],0,"בְּעֶרֶב רֹאשׁ הַשָּׁנָה נוֹהֲגִים לוֹמַר אֶת סֵדֶר ״הַתָּרַת נְדָרִים וּקְלָלוֹת״ כַּמֻּדְפָּס בַּמַּחְזוֹרִים.","פֶּרֶק ע״ה, הֲלָכָה א׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["אֵילוּ נְדָרִים מְבַטְּלִים בְּהַתָּרַת הַנְּדָרִים?",["רַק שֶׁל הַשָּׁנָה שֶׁעָבְרָה","שֶׁל הֶעָבָר וְגַם שֶׁל הֶעָתִיד","רַק שֶׁל הַשָּׁנָה הַבָּאָה"],1,"מַתִּירִים אֶת נִדְרֵי הֶעָבָר וְגַם מְבַטְּלִים מֵרֹאשׁ אֶת כָּל נִדְרֵי הֶעָתִיד.","פֶּרֶק ע״ה, הֲלָכָה א׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["מִי שֶׁזּוֹכֵר הֵיטֵב שֶׁנָּדַר נֶדֶר – לְאָן יִפְנֶה?",["לַחֲבֵרִים בַּכִּתָּה","לַחֲנוּת הַסְּפָרִים","לְחָכָם, לִשְׁאֹל כֵּיצַד לִנְהֹג"],2,"מִי שֶׁזּוֹכֵר הֵיטֵב שֶׁנָּדַר אוֹ נִשְׁבַּע יִפְנֶה לְחָכָם, כִּי יֵשׁ בִּנְדָרִים דִּינִים סְבוּכִים, וְלֹא יִסְמֹךְ עַל הַתָּרַת עֶרֶב רֹאשׁ הַשָּׁנָה.","פֶּרֶק ע״ה, הֲלָכָה ב׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["מָה לֹא עוֹשִׂים בְּעֶרֶב רֹאשׁ הַשָּׁנָה, אַף שֶׁעָשׂוּ כָּל חֹדֶשׁ אֱלוּל?",["תּוֹקְעִים בַּשּׁוֹפָר","מִתְפַּלְּלִים מִנְחָה","מִסְתַּפְּרִים"],0,"בְּעֶרֶב רֹאשׁ הַשָּׁנָה לֹא תּוֹקְעִים, כְּדֵי לְהַפְסִיק בֵּין תְּקִיעוֹת הָרְשׁוּת שֶׁל אֱלוּל לִתְקִיעוֹת הַחוֹבָה שֶׁל רֹאשׁ הַשָּׁנָה.","פֶּרֶק ע״ה, הֲלָכָה ג׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["מָה מִשְׁתַּדְּלִים לַעֲשׂוֹת בְּעֶרֶב רֹאשׁ הַשָּׁנָה כְּדֵי לְהַרְאוֹת בִּטָּחוֹן?",["לִקְנוֹת מִשְׂחָק חָדָשׁ","לְהִסְתַּפֵּר","לָצֵאת לְטִיּוּל"],1,"מִסְתַּפְּרִים כְּדֵי לְהַרְאוֹת אֶת בִּטְחוֹנֵנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹצִיא אֶת דִּינֵנוּ לָאוֹר, לְחַיִּים טוֹבִים וּלְשָׁלוֹם.","פֶּרֶק ע״ה, הֲלָכָה ד׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["אֵיזוֹ תְּפִלָּה הִיא הָאַחֲרוֹנָה שֶׁל הַשָּׁנָה?",["שַׁחֲרִית שֶׁל רֹאשׁ הַשָּׁנָה","מוּסָף שֶׁל שַׁבָּת","מִנְחָה שֶׁל עֶרֶב רֹאשׁ הַשָּׁנָה"],2,"מִנְחָה שֶׁל עֶרֶב רֹאשׁ הַשָּׁנָה הִיא הַתְּפִלָּה הָאַחֲרוֹנָה שֶׁל הַשָּׁנָה, וְלָכֵן מִתְפַּלְּלִים אוֹתָהּ בְּכַוָּנָה רַבָּה.","פֶּרֶק ע״ה, הֲלָכָה ה׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["רֹאשׁ הַשָּׁנָה חָל בַּחֲמִישִׁי וְשִׁשִּׁי. מָה עוֹשִׂים בְּיוֹם רְבִיעִי?",["עֵרוּב תַּבְשִׁילִין","בְּדִיקַת חָמֵץ","הַדְלָקַת נֵר חֲנֻכָּה"],0,"עוֹשִׂים עֵרוּב תַּבְשִׁילִין בְּיוֹם רְבִיעִי, כְּדֵי שֶׁאֶפְשָׁר יִהְיֶה לְבַשֵּׁל בְּיוֹם שִׁשִּׁי לִכְבוֹד הַשַּׁבָּת.","פֶּרֶק ע״ה, הֲלָכָה ו׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["בְּאֵיזֶה חֹדֶשׁ חָל רֹאשׁ הַשָּׁנָה?",["נִיסָן","תִּשְׁרֵי","אֲדָר"],1,"הַיּוֹם הָרִאשׁוֹן בַּחֹדֶשׁ הַשְּׁבִיעִי – תִּשְׁרֵי – הוּא יוֹם טוֹב וְיוֹם תְּרוּעָה.","פֶּרֶק ע״ו, הֲלָכָה א׳","לֵיל רֹאשׁ הַשָּׁנָה"],["כַּמָּה יָמִים נוֹהֵג רֹאשׁ הַשָּׁנָה?",["שְׁנֵי יָמִים","יוֹם אֶחָד","שִׁבְעָה יָמִים"],0,"מֵהַתּוֹרָה – רַק א׳ בְּתִשְׁרֵי, וּמִדִּבְרֵי חֲכָמִים – גַּם ב׳ בְּתִשְׁרֵי. וְהוּא יוֹם דִּין לְכָל בָּאֵי הָעוֹלָם.","פֶּרֶק ע״ו, הֲלָכוֹת ב׳-ג׳","לֵיל רֹאשׁ הַשָּׁנָה"],["אֵיךְ מִתְנַהֲגִים בְּלֵיל רֹאשׁ הַשָּׁנָה?",["כּוֹעֲסִים וּמִתְוַכְּחִים","יְשֵׁנִים כָּל הָעֶרֶב","בְּשִׂמְחָה וּבְנַחַת"],2,"כָּל הַתְחָלָה בְּסִימָן טוֹב מְבִיאָה תִּקְוָה לְהֶמְשֵׁךְ טוֹב, לָכֵן מִשְׁתַּדְּלִים לֹא לִכְעֹס כְּלָל, אֲפִלּוּ בַּלֵּב.","פֶּרֶק ע״ו, הֲלָכָה ד׳","לֵיל רֹאשׁ הַשָּׁנָה"],["בְּמָה נוֹהֲגִים לִטְבֹּל אֶת הַפַּת בְּרֹאשׁ הַשָּׁנָה?",["חֹמֶץ","דְּבַשׁ","שֶׁמֶן"],1,"יֵשׁ נוֹהֲגִים לֶאֱכֹל אֶת הַפַּת עִם סֻכָּר אוֹ דְּבַשׁ, וְיֵשׁ מַמְשִׁיכִים כָּךְ עַד שִׂמְחַת תּוֹרָה.","פֶּרֶק ע״ו, הֲלָכוֹת ה׳-ו׳","לֵיל רֹאשׁ הַשָּׁנָה"],["אֵיזֶה סִימָן מַזְכִּיר ״שֶׁנִּהְיֶה לְרֹאשׁ וְלֹא לְזָנָב״?",["רֹאשׁ דָּג","תַּפּוּחַ","רִמּוֹן"],0,"רֹאשׁ כֶּבֶשׂ אוֹ דָּג – ״שֶׁנִּהְיֶה לְרֹאשׁ וְלֹא לְזָנָב״.","פֶּרֶק ע״ו, הֲלָכָה ז׳","לֵיל רֹאשׁ הַשָּׁנָה"],["מָה עוֹשִׂים רִאשׁוֹן בִּסְעוּדַת לֵיל רֹאשׁ הַשָּׁנָה?",["אֲכִילַת הַדָּג","בִּרְכַּת הַמָּזוֹן","קִדּוּשׁ עַל יַיִן"],2,"הַסֵּדֶר הַמֻּבְחָר: קִדּוּשׁ, נְטִילַת יָדַיִם וּפַת, פְּרִי הָעֵץ, שְׁאָר הַסִּימָנִים, וּמַאַכְלֵי הַחַג.","פֶּרֶק ע״ו, הֲלָכָה ח׳","לֵיל רֹאשׁ הַשָּׁנָה"],["אֵיזוֹ בְּרָכָה פּוֹטֶרֶת אֶת הַסִּימָנִים מִבְּרָכָה אַחֲרוֹנָה?",["בּוֹרֵא נְפָשׁוֹת","בִּרְכַּת הַמָּזוֹן","בִּרְכַּת הַלְּבָנָה"],1,"בִּרְכַּת הַמָּזוֹן פּוֹטֶרֶת גַּם אֶת הַסִּימָנִים מִבְּרָכָה אַחֲרוֹנָה.","פֶּרֶק ע״ו, הֲלָכָה ט׳","לֵיל רֹאשׁ הַשָּׁנָה"],["בְּאֶפְשָׁרוּת א׳, מָה אוֹמְרִים לִפְנֵי בִּרְכַּת הַפְּרִי?",["יְהִי רָצוֹן","הַמּוֹצִיא","הַבְדָּלָה"],0,"בְּאֶפְשָׁרוּת א׳ אוֹמְרִים יְהִי רָצוֹן, מְבָרְכִים וְאוֹכְלִים – כְּדֵי שֶׁלֹּא יִהְיֶה הֶפְסֵק בֵּין הַבְּרָכָה לָאֲכִילָה.","פֶּרֶק ע״ו, הֲלָכָה י׳","לֵיל רֹאשׁ הַשָּׁנָה"],["מָתַי מַתְחִילִים לְהָכִין אֶת סְעוּדַת הַלַּיְלָה הַשֵּׁנִי?",["בַּצָּהֳרַיִם שֶׁל הַיּוֹם הָרִאשׁוֹן","אַחֲרֵי צֵאת הַכּוֹכָבִים","בַּבֹּקֶר שֶׁל הַיּוֹם הָרִאשׁוֹן"],1,"אָסוּר לְהָכִין מֵהַיּוֹם הָרִאשׁוֹן לַשֵּׁנִי, אֲפִלּוּ לַעֲרֹךְ שֻׁלְחָן. מַמְתִּינִים לְצֵאת הַכּוֹכָבִים.","פֶּרֶק ע״ו, הֲלָכָה י״א","לֵיל רֹאשׁ הַשָּׁנָה"],["מָה נָהֲגוּ לְהָבִיא לַשֻּׁלְחָן בַּלַּיְלָה הַשֵּׁנִי?",["לוּלָב","נֵר חֲנֻכָּה","פְּרִי חָדָשׁ"],2,"מְבָרְכִים שֶׁהֶחֱיָנוּ גַּם בַּלַּיְלָה הַשֵּׁנִי, וְנָהֲגוּ לְהָבִיא פְּרִי חָדָשׁ. וְיֵשׁ נוֹהֲגִים לֶאֱכֹל שׁוּב אֶת הַסִּימָנִים.","פֶּרֶק ע״ו, הֲלָכוֹת י״ב-י״ג","לֵיל רֹאשׁ הַשָּׁנָה"],["בְּאֵיזֶה יוֹם שֶׁל רֹאשׁ הַשָּׁנָה תְּקִיעַת הַשּׁוֹפָר הִיא מֵהַתּוֹרָה, וּבְאֵיזֶה יוֹם הִיא מִדְּרַבָּנָן?",["יוֹם רִאשׁוֹן מֵהַתּוֹרָה, יוֹם שֵׁנִי מִדְּרַבָּנָן","שְׁנֵי הַיָּמִים מֵהַתּוֹרָה","יוֹם שֵׁנִי מֵהַתּוֹרָה, יוֹם רִאשׁוֹן מִדְּרַבָּנָן"],0,"מִצְוַת עֲשֵׂה מֵהַתּוֹרָה לִשְׁמֹעַ קוֹל שׁוֹפָר ״בְּאֶחָד לַחֹדֶשׁ״, וּבַיּוֹם הַשֵּׁנִי זוֹ מִצְוָה מִדְּרַבָּנָן.","פֶּרֶק ע״ז, הֲלָכוֹת א׳-ב׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["רֹאשׁ הַשָּׁנָה חָל בְּשַׁבָּת. מָתַי תּוֹקְעִים בַּשּׁוֹפָר?",["בִּשְׁנֵי הַיָּמִים","רַק בַּיּוֹם הַשֵּׁנִי","לֹא תּוֹקְעִים כְּלָל"],1,"חֲכָמִים תִּקְּנוּ שֶׁלֹּא לִתְקֹעַ בַּשַּׁבָּת, וְתוֹקְעִים רַק בַּיּוֹם הַשֵּׁנִי, שֶׁהוּא יוֹם רִאשׁוֹן בַּשָּׁבוּעַ.","פֶּרֶק ע״ז, הֲלָכָה ג׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["לְפִי הָרַמְבָּ״ם, מָה הָרֶמֶז שֶׁבִּתְקִיעַת הַשּׁוֹפָר?",["הִגִּיעַ זְמַן הַסְּעוּדָה","צְאוּ לְטַיֵּל בַּשָּׂדֶה","עוּרוּ מִשְּׁנַתְכֶם וְחִזְרוּ בִּתְשׁוּבָה"],2,"״עוּרוּ יְשֵׁנִים מִשְּׁנַתְכֶם... וְחַפְּשׂוּ בְּמַעֲשֵׂיכֶם וְחִזְרוּ בִּתְשׁוּבָה!״ (רַמְבָּ״ם הִלְכוֹת תְּשׁוּבָה ג, ד).","פֶּרֶק ע״ז, הֲלָכָה ד׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["תּוֹקְעִים בְּשׁוֹפָר שֶׁל אַיִל. אֶת מָה הוּא מַזְכִּיר?",["עֲקֵדַת יִצְחָק","קְרִיעַת יַם סוּף","תֵּבַת נֹחַ"],0,"רַב סְעַדְיָה גָּאוֹן כָּתַב שֶׁשּׁוֹפָר שֶׁל אַיִל מַזְכִּיר אֶת זְכוּת עֲקֵדַת יִצְחָק וְאֶת הָאַיִל שֶׁהֻקְרַב בִּמְקוֹם יִצְחָק.","פֶּרֶק ע״ז, הֲלָכָה ה׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["מִי נוֹהֵג לַעֲמֹד לְיַד הַתּוֹקֵעַ וְלוֹמַר לוֹ כֵּיצַד לִנְהֹג?",["הַשַּׁמָּשׁ","הָרַב","הַחַזָּן"],1,"הַתּוֹקֵעַ חַיָּב לִלְמֹד הֵיטֵב אֶת הַהֲלָכוֹת, וְנוֹהֲגִים שֶׁהָרַב עוֹמֵד לְיָדוֹ וְאוֹמֵר לוֹ כֵּיצַד לִנְהֹג.","פֶּרֶק ע״ז, הֲלָכָה ו׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["אֵיזוֹ קֶרֶן פְּסוּלָה לְשׁוֹפָר?",["קֶרֶן אַיִל כְּפוּפָה","קֶרֶן אַיִל יְשָׁרָה","קֶרֶן שֶׁל פָּרָה"],2,"קֶרֶן פָּרָה פְּסוּלָה כִּי הִיא מַזְכִּירָה אֶת חֵטְא הָעֵגֶל, וְ״אֵין קָטֵגוֹר נַעֲשֶׂה סָנֵגוֹר״. גַּם קֶרֶן מֵעֶצֶם אַחַת פְּסוּלָה.","פֶּרֶק ע״ז, הֲלָכָה ז׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["אֵיזֶה שׁוֹפָר הוּא מִצְוָה מִן הַמֻּבְחָר?",["שׁוֹפָר שֶׁל אַיִל כָּפוּף","שׁוֹפָר סָדוּק עִם חֹר","שׁוֹפָר מִפְּלַסְטִיק"],0,"מִצְוָה מִן הַמֻּבְחָר לִתְקֹעַ בְּקֶרֶן אַיִל כְּפוּפָה. שׁוֹפָר שֶׁנִּסְדַּק אוֹ שֶׁיֵּשׁ בּוֹ נֶקֶב – שׁוֹאֲלִים שְׁאֵלַת חָכָם, וְלַצִּבּוּר רָאוּי לְהַשִּׂיג שׁוֹפָר מְהֻדָּר.","פֶּרֶק ע״ז, הֲלָכוֹת ח׳-ט׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["מָה קוֹרְאִים בַּתּוֹרָה בַּיּוֹם הָרִאשׁוֹן שֶׁל רֹאשׁ הַשָּׁנָה?",["קְרִיעַת יַם סוּף","״וַה׳ פָּקַד אֶת שָׂרָה״","בְּרִיאַת הָעוֹלָם"],1,"קוֹרְאִים ״וַה׳ פָּקַד אֶת שָׂרָה״ וּמַפְטִירִים בִּפְקִידַת חַנָּה, כִּי שְׁתֵּיהֶן נִפְקְדוּ בְּרֹאשׁ הַשָּׁנָה. בַּיּוֹם הַשֵּׁנִי קוֹרְאִים עֲקֵדַת יִצְחָק.","פֶּרֶק ע״ז, הֲלָכָה י׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["אַחֲרֵי קְרִיאַת הַתּוֹרָה תּוֹקְעִים תְּקִיעוֹת רִאשׁוֹנוֹת. אֵיזֶה קוֹל שָׁבוּר לִשְׁלוֹשָׁה חֲלָקִים?",["תְּקִיעָה","שְׁבָרִים","תְּרוּעָה"],1,"תְּקִיעָה – קוֹל פָּשׁוּט וְאָרֹךְ; שְׁבָרִים – שְׁלוֹשָׁה חֲלָקִים; תְּרוּעָה – תִּשְׁעָה חֲלָקִים קְצָרִים. בַּתְּקִיעוֹת הָרִאשׁוֹנוֹת תּוֹקְעִים תַּשְׁרַ״ת, תַּשַׁ״ת וְתַרַ״ת, אַחֲרֵי הַבְּרָכוֹת.","פֶּרֶק ע״ז, הֲלָכוֹת י״א-י״ב","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["בְּחֵלֶק מֵהַקְּהִלּוֹת עוֹמֵד אָדָם לְיַד הַתּוֹקֵעַ. מָה הוּא עוֹשֶׂה?",["מַכְרִיז אֵיזֶה קוֹל תּוֹקְעִים עַכְשָׁו","מַחֲזִיק לַתּוֹקֵעַ אֶת הַסִּדּוּר","שָׁר שִׁיר לִפְנֵי כָּל תְּקִיעָה"],0,"בְּחֵלֶק מֵהַקְּהִלּוֹת עוֹמֵד אָדָם לְיַד הַתּוֹקֵעַ וּמַכְרִיז לִפְנֵי כָּל תְּקִיעָה אֵיזֶה קוֹל עוֹמְדִים לְהַשְׁמִיעַ, כְּדֵי לִמְנֹעַ בִּלְבּוּל.","פֶּרֶק ע״ז, הֲלָכָה י״ג","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["בְּאֵיזוֹ קְהִלָּה מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ לִפְנֵי הַתְּקִיעוֹת גַּם בַּיּוֹם הַשֵּׁנִי שֶׁל רֹאשׁ הַשָּׁנָה?",["קְהִלּוֹת הַסְּפָרַדִּים","קְהִלּוֹת הָאַשְׁכְּנַזִּים","אַף קְהִלָּה לֹא מְבָרֶכֶת"],1,"בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ גַּם בַּיּוֹם הַשֵּׁנִי. בִּקְהִלּוֹת הַסְּפָרַדִּים לֹא מְבָרְכִים, אֶלָּא אִם כֵּן הַיּוֹם הָרִאשׁוֹן הָיָה שַׁבָּת.","פֶּרֶק ע״ז, הֲלָכָה י״ד","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["מָתַי מֻתָּר שׁוּב לְדַבֵּר בְּבֵית הַכְּנֶסֶת בְּרֹאשׁ הַשָּׁנָה?",["אַחֲרֵי הַתְּקִיעוֹת הָרִאשׁוֹנוֹת","בְּאֶמְצַע הַתְּקִיעוֹת, בְּשֶׁקֶט","אַחֲרֵי הַתְּקִיעוֹת שֶׁלְּאַחַר חֲזָרַת שְׁלִיחַ הַצִּבּוּר"],2,"הַבְּרָכוֹת שֶׁלִּפְנֵי הַתְּקִיעוֹת הָרִאשׁוֹנוֹת חָלוֹת עַל כָּל הַתְּקִיעוֹת, וְלָכֵן אֵין לְדַבֵּר עַד סוֹף הַתְּקִיעוֹת שֶׁלְּאַחַר חֲזָרַת שְׁלִיחַ הַצִּבּוּר.","פֶּרֶק ע״ז, הֲלָכָה ט״ו","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["אָדָם שֶׁכְּבָר שָׁמַע שׁוֹפָר תּוֹקֵעַ לְחוֹלֶה בְּבֵיתוֹ. מִי מְבָרֵךְ?",["הַשּׁוֹמֵעַ מְבָרֵךְ","אַף אֶחָד לֹא מְבָרֵךְ","הַשָּׁכֵן מְבָרֵךְ"],0,"כְּשֶׁמִּי שֶׁכְּבָר יָצָא תּוֹקֵעַ עֲבוּר אַחֵר – הַשּׁוֹמֵעַ מְבָרֵךְ. וְאִם הַשּׁוֹמֵעַ אֵינוֹ יוֹדֵעַ לְבָרֵךְ, הַתּוֹקֵעַ יָכוֹל לְבָרֵךְ עֲבוּרוֹ.","פֶּרֶק ע״ז, הֲלָכָה ט״ז","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["עַל מָה מְדַבֶּרֶת בִּרְכַּת ״זִכְרוֹנוֹת״ בִּתְפִלַּת מוּסָף?",["מַתַּן תּוֹרָה בְּהַר סִינַי","ה׳ זוֹכֵר אֶת הָעוֹלָם וּמַשְׁגִּיחַ עָלָיו","שְׁמוֹת כָּל הַמִּתְפַּלְּלִים"],1,"בִּרְכַּת ״זִכְרוֹנוֹת״ מְבַסֶּסֶת אֶת הָאֱמוּנָה שֶׁה׳ זוֹכֵר אֶת הָעוֹלָם שֶׁבָּרָא וּמַשְׁגִּיחַ עָלָיו. ״מַלְכֻיּוֹת״ – עַל מַלְכוּת ה׳, ״שׁוֹפָרוֹת״ – עַל מַתַּן תּוֹרָה וְהַגְּאֻלָּה.","פֶּרֶק ע״ז, הֲלָכָה י״ז","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["בְּכָל בְּרָכָה מִשָּׁלוֹשׁ הַבְּרָכוֹת הָאֶמְצָעִיּוֹת אוֹמְרִים עֲשָׂרָה פְּסוּקִים. מָה עוֹשִׂים בְּסִיּוּם הַבְּרָכָה?",["שׁוֹתִים מַיִם","מַדְלִיקִים נֵר","תּוֹקְעִים בַּשּׁוֹפָר"],2,"בְּכָל בְּרָכָה אוֹמְרִים עֲשָׂרָה פְּסוּקִים (אוֹ יוֹתֵר): אַרְבָּעָה מֵהַתּוֹרָה, שְׁלוֹשָׁה מֵהַנְּבִיאִים וּשְׁלוֹשָׁה מֵהַכְּתוּבִים, וּבְסִיּוּמָהּ תּוֹקְעִים בַּשּׁוֹפָר.","פֶּרֶק ע״ז, הֲלָכוֹת י״ח-י״ט","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["לְכַמָּה קוֹלוֹת שֶׁל שׁוֹפָר מַגִּיעִים בְּסַךְ הַכֹּל?",["מֵאָה","עֲשָׂרָה","שְׁלֹשִׁים"],0,"לְאַחַר חֲזָרַת שְׁלִיחַ הַצִּבּוּר תּוֹקְעִים עוֹד תְּקִיעוֹת, וּבְסַךְ הַכֹּל מַגִּיעִים לְמֵאָה קוֹלוֹת.","פֶּרֶק ע״ז, הֲלָכָה כ׳","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["נָשִׁים נָהֲגוּ לִשְׁמֹעַ שׁוֹפָר. מָה עוֹשִׂים כְּשֶׁאִשָּׁה לֹא יְכוֹלָה לָבוֹא לְבֵית הַכְּנֶסֶת?",["שׁוֹלְחִים לָהּ סִדּוּר בִּמְקוֹם שׁוֹפָר","תּוֹקְעִים לָהּ בַּבַּיִת אוֹ אַחֲרֵי הַתְּפִלָּה","אֵין מָה לַעֲשׂוֹת"],1,"מֵעִקַּר הַדִּין נָשִׁים פְּטוּרוֹת, כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ, אַךְ נָהֲגוּ לִשְׁמֹעַ. אִשָּׁה שֶׁלֹּא יְכוֹלָה לָבוֹא – תּוֹקְעִים לָהּ בַּבַּיִת אוֹ בְּבֵית הַכְּנֶסֶת לְאַחַר הַתְּפִלָּה.","פֶּרֶק ע״ז, הֲלָכוֹת כ״א-כ״ב","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["הַיּוֹם הָרִאשׁוֹן שֶׁל רֹאשׁ הַשָּׁנָה חָל בְּשַׁבָּת, וְאֵין עֵרוּב. מָתַי וְאֵיפֹה אוֹמְרִים תַּשְׁלִיךְ?",["בַּיּוֹם הָרִאשׁוֹן, בְּתוֹךְ הַבַּיִת","בַּיּוֹם הַשֵּׁנִי, בְּרֹאשׁ הַר גָּבוֹהַּ","בַּיּוֹם הַשֵּׁנִי, לְיַד מְקוֹם מַיִם"],2,"אוֹמְרִים תַּשְׁלִיךְ לְיַד מְקוֹם מַיִם, עַל שֵׁם ״וְתַשְׁלִיךְ בִּמְצֻלוֹת יָם״. כְּשֶׁהַיּוֹם הָרִאשׁוֹן בְּשַׁבָּת וְאֵין עֵרוּב – גַּם הַסְּפָרַדִּים אוֹמְרִים בַּיּוֹם הַשֵּׁנִי.","פֶּרֶק ע״ז, הֲלָכוֹת כ״ג-כ״ד","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["עַל מָה צָרִיךְ לַעֲשׂוֹת תְּשׁוּבָה?",["רַק עַל מִצְווֹת עֲשֵׂה","גַּם עַל מַעֲשִׂים וְגַם עַל מִדּוֹת רָעוֹת כְּכַעַס","רַק עַל מַעֲשִׂים, לֹא עַל מִדּוֹת"],1,"מִי שֶׁעָבַר עַל מִצְוַת עֲשֵׂה אוֹ לֹא תַּעֲשֶׂה מְצֻוֶּה לָשׁוּב, וְהַתְּשׁוּבָה הִיא גַּם עַל מִדּוֹת רָעוֹת כְּכַעַס וְגַאֲוָה.","פֶּרֶק ע״ח, הֲלָכוֹת א׳-ב׳","מִצְוַת הַתְּשׁוּבָה"],["מָה מִתּוֹךְ אֵלֶּה הוּא חֵלֶק מִמִּצְוַת הַתְּשׁוּבָה?",["לְהַמְשִׁיךְ לַחְטֹא בַּסֵּתֶר","לִשְׁכֹּחַ מִן הַחֵטְא בְּלִי לוֹמַר כְּלוּם","וִדּוּי וַחֲרָטָה"],2,"הַתְּשׁוּבָה כּוֹלֶלֶת שְׁלוֹשָׁה חֲלָקִים: עֲזִיבַת הַחֵטְא, וִדּוּי וַחֲרָטָה, וְקַבָּלָה לֶעָתִיד.","פֶּרֶק ע״ח, הֲלָכָה ג׳","מִצְוַת הַתְּשׁוּבָה"],["בַּזְּמַן שֶׁאֵין בֵּית הַמִּקְדָּשׁ, מָה מְכַפֵּר עַל הָעֲבֵרוֹת?",["מַתָּנוֹת לַחֲבֵרִים","הַתְּשׁוּבָה","שֵׁנָה אֲרֻכָּה"],1,"בַּזְּמַן הַזֶּה, כְּשֶׁאֵין קָרְבָּנוֹת, יֵשׁ לָנוּ אֶת הַתְּשׁוּבָה שֶׁמְּכַפֶּרֶת עַל כָּל הָעֲבֵרוֹת.","פֶּרֶק ע״ח, הֲלָכָה ד׳","מִצְוַת הַתְּשׁוּבָה"],["אֵיךְ נֶחְשָׁב הַחוֹטֵא אַחֲרֵי שֶׁעָשָׂה תְּשׁוּבָה?",["רָחוֹק מֵה׳","כְּמוֹ שֶׁהָיָה, בְּלִי שִׁנּוּי","אָהוּב וְקָרוֹב לַה׳"],2,"הַתְּשׁוּבָה מְקָרֶבֶת אֶת הָאָדָם לַה׳: לְפָנֶיהָ הָיָה רָחוֹק, וְאַחֲרֶיהָ הוּא אָהוּב וְנֶחְמָד, קָרוֹב וְיָדִיד.","פֶּרֶק ע״ח, הֲלָכָה ה׳","מִצְוַת הַתְּשׁוּבָה"],["מָתַי נַעֲשֵׂית חֲתִימַת הַדִּין?",["בְּיוֹם הַכִּפּוּרִים","בְּרֹאשׁ הַשָּׁנָה","בְּפֶסַח"],0,"בְּרֹאשׁ הַשָּׁנָה ה׳ כּוֹתֵב אֶת הַדִּין, וְהַחֲתִימָה בְּיוֹם הַכִּפּוּרִים. בַּעֲשֶׂרֶת יְמֵי תְּשׁוּבָה הַתְּשׁוּבָה מִתְקַבֶּלֶת מִיָּד, אַף שֶׁהִיא מוֹעִילָה בְּכָל הַשָּׁנָה.","פֶּרֶק ע״ח, הֲלָכוֹת ו׳-ז׳","מִצְוַת הַתְּשׁוּבָה"],["יֶלֶד לָקַח מֵחֲנוּת, הֶחְזִיר, וּבְהִזְדַּמְּנוּת נוֹסֶפֶת לֹא לָקַח. מָה זֶה?",["תְּשׁוּבָה שֶׁאֵינָהּ מוֹעִילָה","אֵין זוֹ תְּשׁוּבָה כְּלָל","תְּשׁוּבָה שְׁלֵמָה"],2,"מִי שֶׁהָיְתָה לוֹ הִזְדַּמְּנוּת לַחְטֹא שׁוּב וּפָרַשׁ מִפְּנֵי שֶׁשָּׁב – זוֹ תְּשׁוּבָה גְּמוּרָה. גַּם מִי שֶׁשָּׁב בְּזִקְנָתוֹ נֶחְשָׁב בַּעַל תְּשׁוּבָה.","פֶּרֶק ע״ח, הֲלָכָה ח׳","מִצְוַת הַתְּשׁוּבָה"],["יֶלֶד שָׁבַר אֶת הָאוֹפַנַּיִם שֶׁל חֲבֵרוֹ. מָה עָלָיו לַעֲשׂוֹת כְּדֵי שֶׁיּוֹם הַכִּפּוּרִים יְכַפֵּר?",["לְפַיֵּס אֶת חֲבֵרוֹ וּלְשַׁלֵּם לוֹ","רַק לְהִתְפַּלֵּל בְּיוֹם הַכִּפּוּרִים","לֹא לְסַפֵּר לְאַף אֶחָד"],0,"בְּחֵטְא שֶׁבֵּין אָדָם לַחֲבֵרוֹ, יוֹם הַכִּפּוּרִים אֵינוֹ מְכַפֵּר עַד שֶׁיְּפַיֵּס אֶת חֲבֵרוֹ וִישַׁלֵּם לוֹ אֶת מַה שֶּׁמַּגִּיעַ לוֹ.","פֶּרֶק ע״ח, הֲלָכָה ט׳","מִצְוַת הַתְּשׁוּבָה"],["חָבֵר מְבַקֵּשׁ מִמְּךָ מְחִילָה. מָה תַּעֲשֶׂה?",["אֶתְעַלֵּם מִמֶּנּוּ","אֶסְלַח בְּלֵב שָׁלֵם","אֶכְעַס עָלָיו עוֹד"],1,"מִי שֶׁמְּבַקְּשִׁים מִמֶּנּוּ מְחִילָה – עָלָיו לִהְיוֹת רַחְמָן וְלִסְלֹחַ בְּלֵב שָׁלֵם.","פֶּרֶק ע״ח, הֲלָכָה י׳","מִצְוַת הַתְּשׁוּבָה"],["הֶחָבֵר לֹא מוֹחֵל. כַּמָּה אֲנָשִׁים שׁוֹלְחִים אֵלָיו שֶׁיְּבַקְּשׁוּ מְחִילָה?",["אִישׁ אֶחָד","עֲשָׂרָה אֲנָשִׁים","שְׁלוֹשָׁה אֲנָשִׁים"],2,"שׁוֹלְחִים שְׁלוֹשָׁה בְּנֵי אָדָם, עַד שָׁלוֹשׁ פְּעָמִים. אִם לֹא מָחַל – הוּא הַחוֹטֵא. וְאִם זֶה רַבּוֹ – מְנַסִּים אֲפִלּוּ אֶלֶף פְּעָמִים.","פֶּרֶק ע״ח, הֲלָכָה י״א","מִצְוַת הַתְּשׁוּבָה"],["בְּאֵיזוֹ בְּרָכָה מוֹסִיפִים ״זָכְרֵנוּ לְחַיִּים״?",["בְּבִרְכַּת הוֹדָאָה","בְּבִרְכַּת אָבוֹת","בְּבִרְכַּת שִׂים שָׁלוֹם"],1,"״זָכְרֵנוּ״ מוֹסִיפִים בְּבִרְכַּת אָבוֹת, ״מִי כָמוֹךָ״ בִּגְבוּרוֹת, ״וּכְתֹב״ בְּהוֹדָאָה וּ״בְּסֵפֶר חַיִּים״ בְּשִׂים שָׁלוֹם.","פֶּרֶק ע״ט, הֲלָכָה א׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["יוֹסִי שָׁכַח לוֹמַר ״וּכְתֹב״ וּכְבָר אָמַר אֶת שֵׁם ה׳ בְּסוֹף הַבְּרָכָה. מָה עָלָיו לַעֲשׂוֹת?",["חוֹזֵר לְרֹאשׁ הַבְּרָכָה","מַמְשִׁיךְ וְאֵינוֹ חוֹזֵר","חוֹזֵר לְרֹאשׁ הַתְּפִלָּה"],1,"מִי שֶׁשָּׁכַח אֶת הַבַּקָּשׁוֹת וְהִזְכִּיר אֶת שֵׁם ה׳ שֶׁבְּסוֹף הַבְּרָכָה – אָסוּר לוֹ לַחְזֹר. אִם נִזְכַּר לִפְנֵי כֵן – יָכוֹל לַחְזֹר.","פֶּרֶק ע״ט, הֲלָכָה א׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מָה אוֹמְרִים בְּסוֹף הָעֲמִידָה וּבְסוֹף הַקַּדִּישׁ בַּעֲשֶׂרֶת יְמֵי תְּשׁוּבָה?",["עוֹשֶׂה שָׁלוֹם","שִׂים שָׁלוֹם","עוֹשֶׂה הַשָּׁלוֹם"],2,"בְּסִיּוּם הָעֲמִידָה וּבְסִיּוּם הַקַּדִּישׁ אוֹמְרִים ״עוֹשֶׂה הַשָּׁלוֹם״ בִּמְקוֹם ״עוֹשֶׂה שָׁלוֹם״.","פֶּרֶק ע״ט, הֲלָכוֹת ב׳, י״ב","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["בַּיָּמִים הָאֵלֶּה מְשַׁנִּים סִיּוּם שֶׁל שְׁתֵּי בְּרָכוֹת וּמַזְכִּירִים בָּהֶן אֶת ה׳ בְּתוֹר...",["מֶלֶךְ","רוֹפֵא","גּוֹאֵל"],0,"אוֹמְרִים ״הַמֶּלֶךְ הַקָּדוֹשׁ״ (מִפְּנֵי שֶׁבַּיָּמִים אֵלּוּ נִכֶּרֶת מַלְכוּת ה׳), וּבִימוֹת הַחֹל גַּם ״הַמֶּלֶךְ הַמִּשְׁפָּט״.","פֶּרֶק ע״ט, הֲלָכוֹת ג׳, ז׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["דָּנִי אָמַר ״הָאֵ-ל הַקָּדוֹשׁ״ וּכְבָר הִתְחִיל אֶת הַבְּרָכָה הַבָּאָה. מָה דִּינוֹ?",["חוֹזֵר לְרֹאשׁ הַתְּפִלָּה","אֵינוֹ צָרִיךְ לַחְזֹר","חוֹזֵר לַבְּרָכָה הַבָּאָה"],0,"חוֹזֵר לְרֹאשׁ הַתְּפִלָּה, כִּי שָׁלוֹשׁ הַבְּרָכוֹת הָרִאשׁוֹנוֹת נֶחְשָׁבוֹת כִּבְרָכָה אַחַת. אִם תִּקֵּן תּוֹךְ כְּדֵי דִּבּוּר – אֵינוֹ צָרִיךְ לַחְזֹר.","פֶּרֶק ע״ט, הֲלָכוֹת ד׳, ה׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מִי שֶׁאֵינוֹ זוֹכֵר אִם אָמַר ״הַמֶּלֶךְ הַקָּדוֹשׁ״ – דִּינוֹ כְּמִי...",["שֶׁאָמַר נָכוֹן","שֶׁאָמַר ״הָאֵ-ל הַקָּדוֹשׁ״","שֶׁלֹּא הִתְפַּלֵּל כְּלָל"],1,"סָבִיר לְהָנִיחַ שֶׁאָמַר אֶת מַה שֶּׁהוּא רָגִיל כָּל הַשָּׁנָה. וְכֵן בְּסָפֵק בְּ״הַמֶּלֶךְ הַמִּשְׁפָּט״ – דִּינוֹ כְּמִי שֶׁטָּעָה.","פֶּרֶק ע״ט, הֲלָכוֹת ו׳, י׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["אַשְׁכְּנַזִּי שֶׁאָמַר ״מֶלֶךְ אוֹהֵב צְדָקָה וּמִשְׁפָּט״ וְהִמְשִׁיךְ לַבְּרָכָה הַבָּאָה – מָה דִּינוֹ?",["חוֹזֵר לְ״הָשִׁיבָה שׁוֹפְטֵינוּ״","חוֹזֵר לְרֹאשׁ הַתְּפִלָּה","אֵינוֹ חוֹזֵר"],2,"לְמִנְהַג הָאַשְׁכְּנַזִּים אֵינוֹ חוֹזֵר, כִּי גַּם בַּנֹּסַח הָרָגִיל מֻזְכֶּרֶת הַמִּלָּה ״מֶלֶךְ״. לְמִנְהַג רֹב הַסְּפָרַדִּים חוֹזֵר לְ״הָשִׁיבָה שׁוֹפְטֵינוּ״.","פֶּרֶק ע״ט, הֲלָכוֹת ח׳, ט׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מָה מוֹסִיפִים הָאַשְׁכְּנַזִּים בַּקַּדִּישׁ בַּעֲשֶׂרֶת יְמֵי תְּשׁוּבָה?",["״לְעֵלָּא וּלְעֵלָּא״","״אָמֵן אָמֵן״","״בָּרוּךְ הוּא״"],0,"הָאַשְׁכְּנַזִּים אוֹמְרִים ״לְעֵלָּא וּלְעֵלָּא מִכָּל בִּרְכָתָא״ בִּמְקוֹם ״לְעֵלָּא מִן כָּל בִּרְכָתָא״.","פֶּרֶק ע״ט, הֲלָכָה י״א","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מָה נוֹהֲגִים לְהוֹסִיף אַחֲרֵי חֲזָרַת הַשַּׁ״ץ בְּשַׁחֲרִית וּבְמִנְחָה?",["הַלֵּל","אָבִינוּ מַלְכֵּנוּ","תְּקִיעַת שׁוֹפָר"],1,"בַּעֲשֶׂרֶת יְמֵי תְּשׁוּבָה נוֹהֲגִים לְהוֹסִיף ״אָבִינוּ מַלְכֵּנוּ״ אַחֲרֵי חֲזָרַת הַשַּׁ״ץ בְּשַׁחֲרִית וּבְמִנְחָה.","פֶּרֶק ע״ט, הֲלָכָה י״ג","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["אַחֲרֵי ״יִשְׁתַּבַּח״ רַבִּים מוֹסִיפִים מִזְמוֹר מִסֵּפֶר...",["בְּרֵאשִׁית","אֶסְתֵּר","תְּהִלִּים"],2,"רַבִּים מוֹסִיפִים אֶת מִזְמוֹר ק״ל בִּתְהִלִּים, ״שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים״.","פֶּרֶק ע״ט, הֲלָכָה י״ד","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מָה מִצְוָה לַעֲשׂוֹת בְּעֶרֶב יוֹם הַכִּפּוּרִים?",["לְהִתְעַנּוֹת כָּל הַיּוֹם","לֶאֱכֹל וְלִשְׁתּוֹת וּלְהַרְבּוֹת בִּסְעוּדָה","לִישֹׁן כָּל הַיּוֹם"],1,"מִצְוָה לֶאֱכֹל וְלִשְׁתּוֹת בְּעֶרֶב יוֹם הַכִּפּוּרִים וּלְהַרְבּוֹת בִּסְעוּדָה, וְאָסוּר לְהִתְעַנּוֹת בּוֹ. אַחַד הַטְּעָמִים: כְּדֵי שֶׁהַתַּעֲנִית לֹא תַּזִּיק לְיִשְׂרָאֵל.","פֶּרֶק פ׳, הֲלָכָה א׳-ב׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מָתַי אוֹמְרִים וִדּוּי לִפְנֵי הַסְּעוּדָה הַמַּפְסֶקֶת?",["בִּתְפִלַּת שַׁחֲרִית","בִּזְמַן הַסְּעוּדָה","בִּתְפִלַּת מִנְחָה"],2,"מִתְוַדִּים בִּתְפִלַּת מִנְחָה לִפְנֵי הַסְּעוּדָה הַמַּפְסֶקֶת, כְּדֵי שֶׁאִם תִּקְרֶה תַּקָּלָה, לְפָחוֹת אָמַר וִדּוּי פַּעַם אַחַת.","פֶּרֶק פ׳, הֲלָכָה ג׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["אֵילוּ מַאֲכָלִים אוֹכְלִים בַּסְּעוּדָה הַמַּפְסֶקֶת?",["מַאֲכָלִים קַלִּים לְעִכּוּל","מַאֲכָלִים כְּבֵדִים וְשׁוֹמְנִים","רַק מַמְתַּקִּים"],0,"בַּסְּעוּדָה הַמַּפְסֶקֶת אוֹכְלִים רַק מַאֲכָלִים קַלִּים לְעִכּוּל, כְּדֵי שֶׁלֹּא נִהְיֶה שְׂבֵעִים וּמִתְגָּאִים בִּזְמַן הַתְּפִלָּה.","פֶּרֶק פ׳, הֲלָכָה ד׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["בְּמָה נוֹהֲגִים לִטְבֹּל אֶת פְּרוּסַת הַמּוֹצִיא בְּעֶרֶב יוֹם הַכִּפּוּרִים?",["בְּחֹמֶץ","בְּסֻכָּר אוֹ בִּדְבַשׁ","בְּשֶׁמֶן"],1,"נוֹהֲגִים לִטְבֹּל אֶת פְּרוּסַת הַמּוֹצִיא בְּסֻכָּר אוֹ בִּדְבַשׁ בְּכָל סְעוּדוֹת הַיּוֹם.","פֶּרֶק פ׳, הֲלָכָה ה׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מָתַי צָרִיךְ לְסַיֵּם אֶת הַסְּעוּדָה הַמַּפְסֶקֶת?",["בַּחֲצוֹת הַלַּיְלָה","שָׁעָה אַחֲרֵי הַשְּׁקִיעָה","כַּמָּה דַּקּוֹת לִפְנֵי הַשְּׁקִיעָה"],2,"מְסַיְּמִים כַּמָּה דַּקּוֹת לִפְנֵי הַשְּׁקִיעָה, כִּי חוֹבָה לְהוֹסִיף מֵהַחֹל עַל הַקֹּדֶשׁ.","פֶּרֶק פ׳, הֲלָכָה ו׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מִמִּי חָשׁוּב בְּיוֹתֵר לְבַקֵּשׁ מְחִילָה לִפְנֵי יוֹם הַכִּפּוּרִים?",["מֵהַהוֹרִים","מֵהַשָּׁכֵן שֶׁבְּעִיר אַחֶרֶת","מֵהַחֲתוּל"],0,"מְבַקְּשִׁים מְחִילָה מֵהַחֲבֵרִים, וְעַל אַחַת כַּמָּה וְכַמָּה מֵהַהוֹרִים, כִּי מִתּוֹךְ הַקִּרְבָה הַיּוֹם יוֹמִית בְּוַדַּאי פָּגַמְנוּ בִּכְבוֹדָם. וְאִם לֹא בִּקְּשׁוּ – הַהוֹרִים מוֹחֲלִים לִפְנִים מִשּׁוּרַת הַדִּין.","פֶּרֶק פ׳, הֲלָכָה ז׳-ח׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["לְמִי נוֹתְנִים אֶת בְּשַׂר הַכַּפָּרוֹת?",["לַחֲנוּת","לָעֲנִיִּים","לְבַעֲלֵי הַחַיִּים"],1,"אֶת הַבָּשָׂר נוֹתְנִים לָעֲנִיִּים כְּדֵי שֶׁיִּהְיֶה לָהֶם מָה לֶאֱכֹל. רַבִּים אָמְרוּ שֶׁעָדִיף לָתֵת כֶּסֶף לִצְדָקָה, וְכָל אֶחָד נוֹהֵג כְּמִנְהַג מִשְׁפַּחְתּוֹ.","פֶּרֶק פ׳, הֲלָכָה ט׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["לְאָן נָהֲגוּ רַבִּים לָלֶכֶת בְּעֶרֶב יוֹם הַכִּפּוּרִים כְּדֵי לְהִטַּהֵר?",["לַבְּרֵכָה","לַיָּם","לַמִּקְוֶה"],2,"רַבִּים נָהֲגוּ לִטְבֹּל בַּמִּקְוֶה כְּדֵי לְטַהֵר אֶת עַצְמָם לִפְנֵי הַיּוֹם הַקָּדוֹשׁ.","פֶּרֶק פ׳, הֲלָכָה י׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["אֵיזֶה בְּגָדִים יֵשׁ שֶׁנּוֹהֲגִים לִלְבֹּשׁ בְּיוֹם הַכִּפּוּרִים?",["בְּגָדִים לְבָנִים וּנְקִיִּים","בִּגְדֵי עֲבוֹדָה","בִּגְדֵי סְפּוֹרְט"],0,"מְכַבְּדִים אֶת יוֹם הַכִּפּוּרִים בִּכְסוּת נְקִיָּה וּבְמַפָּה נָאָה, וְיֵשׁ שֶׁלּוֹבְשִׁים לָבָן כִּי בְּיוֹם זֶה אָנוּ דּוֹמִים לְמַלְאֲכֵי הַשָּׁרֵת.","פֶּרֶק פ׳, הֲלָכָה י״א-י״ב","עֶרֶב יוֹם הַכִּפּוּרִים"],["מָה עוֹשִׂים לִפְנֵי כְּנִיסַת יוֹם הַכִּפּוּרִים, כְּמוֹ בְּשַׁבָּת?",["מַדְלִיקִים מְדוּרָה","מַדְלִיקִים נֵרוֹת וּמְבָרְכִים","מְכַבִּים אֶת כָּל הָאוֹרוֹת"],1,"מַדְלִיקִים נֵרוֹת וּמְבָרְכִים \"לְהַדְלִיק נֵר שֶׁל יוֹם הַכִּפּוּרִים\", וּבִקְהִלּוֹת הָאַשְׁכְּנַזִּים מְבָרְכִים גַּם \"שֶׁהֶחֱיָנוּ\".","פֶּרֶק פ׳, הֲלָכָה י״ג","עֶרֶב יוֹם הַכִּפּוּרִים"],["מָה מִן הַדְּבָרִים הָאֵלֶּה הוּא אֶחָד מֵחֲמֵשֶׁת הָעִנּוּיִים שֶׁל יוֹם הַכִּפּוּרִים?",["לְהִמָּנַע מֵאֲכִילָה וּשְׁתִיָּה","לְהִמָּנַע מִשֵּׁנָה","לְהִמָּנַע מִדִּבּוּר"],0,"הָעִנּוּי בְּיוֹם הַכִּפּוּרִים כּוֹלֵל חֲמִשָּׁה אִסּוּרִים: אֲכִילָה וּשְׁתִיָּה, רְחִיצָה, סִיכָה, נְעִילַת הַסַּנְדָּל וְתַשְׁמִישׁ הַמִּטָּה. וְהַיּוֹם מַתְחִיל מֵהָעֶרֶב, ״מֵעֶרֶב עַד עֶרֶב״.","פֶּרֶק פ״א, הֲלָכוֹת א׳-ב׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["אֵיזֶה מִין יוֹם הוּא יוֹם הַכִּפּוּרִים לְעַם יִשְׂרָאֵל?",["יוֹם אֵבֶל וָעֶצֶב","יוֹם שִׂמְחָה שֶׁל כַּפָּרָה","יוֹם רָגִיל כְּמוֹ כָּל יוֹם"],1,"חֲכָמִים אָמְרוּ: ״לֹא הָיוּ יָמִים טוֹבִים לְיִשְׂרָאֵל כַּחֲמִשָּׁה עָשָׂר בְּאָב וּכְיוֹם הַכִּפּוּרִים״, כִּי בּוֹ ה׳ מְכַפֵּר עַל הַחֲטָאִים.","פֶּרֶק פ״א, הֲלָכָה ג׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["מָה אָסוּר לַעֲשׂוֹת בְּיוֹם הַכִּפּוּרִים, כְּמוֹ בְּשַׁבָּת?",["לִקְרֹא בְּמַחֲזוֹר","לְהִתְפַּלֵּל","לִכְתֹּב בְּעֵט"],2,"״וְכָל מְלָאכָה לֹא תַעֲשׂוּ בְּעֶצֶם הַיּוֹם הַזֶּה״ - בְּיוֹם הַכִּפּוּרִים אָסוּר לַעֲשׂוֹת מְלָאכָה כְּמוֹ בְּשַׁבָּת, וּכְתִיבָה הִיא מְלָאכָה.","פֶּרֶק פ״א, הֲלָכָה ד׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["בַּבֹּקֶר שֶׁל יוֹם הַכִּפּוּרִים, עַד הֵיכָן נוֹטְלִים אֶת הַיָּדַיִם?",["עַד סוֹף קִשְׁרֵי הָאֶצְבָּעוֹת","עַד הַמַּרְפֵּק","רוֹחֲצִים אֶת כָּל הַגּוּף"],0,"בְּיוֹם הַכִּפּוּרִים אָסוּר לִרְחֹץ אֲפִלּוּ אֵיבָר אֶחָד, וְלָכֵן נוֹטְלִים אֶת הַיָּדַיִם רַק עַד סוֹף קִשְׁרֵי הָאֶצְבָּעוֹת.","פֶּרֶק פ״א, הֲלָכוֹת ה׳-ו׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["יֶלֶד הִתְלַכְלֵךְ בְּבֹץ בְּיוֹם הַכִּפּוּרִים. מָה מֻתָּר לוֹ לַעֲשׂוֹת?",["לִמְרֹחַ קְרֵם עַל הַיָּדַיִם","לִשְׁטֹף רַק אֶת הַלִּכְלוּךְ","לְהִכָּנֵס לְאַמְבַּטְיָה חַמָּה"],1,"שְׁטִיפָה כְּדֵי לְהָסִיר לִכְלוּךְ אוֹ רֵיחַ רַע מֻתֶּרֶת, כִּי אֵינָהּ לְשֵׁם תַּעֲנוּג. אֲבָל סִיכָה - מְרִיחַת שֶׁמֶן אוֹ קְרֵם - אֲסוּרָה אֲפִלּוּ עַל מָקוֹם קָטָן.","פֶּרֶק פ״א, הֲלָכוֹת ז׳-ח׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["אֵיזוֹ נַעַל מֻתֶּרֶת בְּיוֹם הַכִּפּוּרִים?",["נַעַל עוֹר","סַנְדָּל עוֹר","נַעַל בַּד"],2,"אָסוּר לִנְעֹל סַנְדָּלִים אוֹ נַעֲלַיִם מֵעוֹר, אֲבָל מֻתָּר לִנְעֹל נַעֲלַיִם מִגּוּמִי, בַּד אוֹ חֳמָרִים אֲחֵרִים.","פֶּרֶק פ״א, הֲלָכָה ט׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["יֶלֶד בֶּן שֶׁבַע בְּיוֹם הַכִּפּוּרִים:",["אוֹכֵל וְלֹא מִתְעַנֶּה כְּלָל","צָם כָּל הַיּוֹם","צָם עַד חֲצוֹת"],0,"יְלָדִים שֶׁלֹּא מָלְאוּ לָהֶם תֵּשַׁע שָׁנִים לֹא מִתְעַנִּים כְּלָל, גַּם אִם רוֹצִים, כִּי גּוּפָם חַלָּשׁ. מִגִּיל תֵּשַׁע מִתְעַנִּים ״תַּעֲנִית שָׁעוֹת״ - מְאַחֲרִים אֶת הָאֲרוּחָה.","פֶּרֶק פ״א, הֲלָכוֹת י׳-י״א","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["יֶלֶד בֶּן שְׁלוֹשׁ עֶשְׂרֵה בְּיוֹם הַכִּפּוּרִים:",["פָּטוּר מִן הַתַּעֲנִית","צָם רַק תַּעֲנִית שָׁעוֹת","חַיָּב לְהִתְעַנּוֹת כְּגָדוֹל"],2,"יַלְדָּה בַּת שְׁתֵּים עֶשְׂרֵה וְיֶלֶד בֶּן שְׁלוֹשׁ עֶשְׂרֵה הֵם כִּגְדוֹלִים לְכָל הַמִּצְווֹת וְחַיָּבִים בְּתַעֲנִית. בְּגִיל אַחַת עֶשְׂרֵה מִתְעַנִּים מִדְּרַבָּנָן לְשֵׁם חִנּוּךְ.","פֶּרֶק פ״א, הֲלָכוֹת י״ב-י״ג","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["אָדָם הִתְעַלֵּף בְּיוֹם הַכִּפּוּרִים וְיֵשׁ סַכָּנָה לְחַיָּיו. מָה עוֹשִׂים?",["מְחַכִּים לְמוֹצָאֵי הַיּוֹם","מַזְעִיקִים מִיָּד אַמְבּוּלַנְס","מַמְשִׁיכִים לְהִתְפַּלֵּל"],1,"פִּקּוּחַ נֶפֶשׁ דּוֹחֶה אֶת כָּל הַמִּצְווֹת, וְחוֹבָה לַעֲשׂוֹת כָּל מָה שֶׁצָּרִיךְ לְהַצָּלַת חַיִּים: נְסִיעָה לְבֵית חוֹלִים, הַזְעָקַת גּוֹרְמֵי רְפוּאָה וְעוֹד.","פֶּרֶק פ״א, הֲלָכָה י״ד","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["חוֹלֶה שֶׁצָּרִיךְ לֶאֱכֹל בְּיוֹם הַכִּפּוּרִים - אֵיךְ מַאֲכִילִים אוֹתוֹ?",["כַּמֻּיּוֹת קְטַנּוֹת מִדֵּי כַּמָּה דַּקּוֹת","אֲרוּחָה גְּדוֹלָה אַחַת","רַק בְּסוֹף הַיּוֹם"],0,"מַאֲכִילִים וּמַשְׁקִים אֶת הַחוֹלֶה ״לְשִׁעוּרִים״ - כַּמֻּיּוֹת קְטַנּוֹת מִדֵּי כַּמָּה דַּקּוֹת, וּמִתְיַעֲצִים עִם תַּלְמִיד חָכָם וְעִם הָרוֹפֵא. חוֹלֶה שֶׁאֵין בּוֹ סַכָּנָה צָרִיךְ לְהִתְעַנּוֹת.","פֶּרֶק פ״א, הֲלָכוֹת ט״ו-ט״ז","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["מָה קוֹרְאִים בַּתּוֹרָה בְּיוֹם הַכִּפּוּרִים, כְּשֶׁאֵין לָנוּ אֶת עֲבוֹדַת הַכֹּהֵן הַגָּדוֹל?",["פָּרָשַׁת קְרִיעַת יַם סוּף","פָּרָשַׁת עֲבוֹדַת הַכֹּהֵן הַגָּדוֹל","פָּרָשַׁת בְּרִיאַת הָעוֹלָם"],1,"בְּיָמֵינוּ קוֹרְאִים אֶת פָּרָשַׁת עֲבוֹדַת הַכֹּהֵן הַגָּדוֹל מִסֵּפֶר וַיִּקְרָא (פֶּרֶק ט״ז), וְאוֹמְרִים בְּמוּסָף פִּיּוּטִים עַל סֵדֶר הָעֲבוֹדָה.","פֶּרֶק פ״ב, הֲלָכָה א׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["לְפִי הַמִּדְרָשׁ, מָה מְכַפֵּר עָלֵינוּ הַיּוֹם בִּמְקוֹם הַשָּׂעִיר הַמִּשְׁתַּלֵּחַ?",["הַתְּפִלָּה","מַתָּנוֹת יְקָרוֹת","שִׁירֵי שִׂמְחָה"],0,"הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר שֶׁהַתְּפִלָּה חֲבִיבָה עָלָיו כְּמוֹ הַשָּׂעִיר הַמִּשְׁתַּלֵּחַ. וְהָעִקָּר בָּהּ הוּא כַּוָּנַת הַלֵּב, לֹא הַנִּגּוּנִים.","פֶּרֶק פ״ב, הֲלָכָה ב׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["מָתַי צָרִיךְ לְהִתְעַטֵּף בְּטַלִּית בְּעֶרֶב יוֹם הַכִּפּוּרִים?",["אַחֲרֵי צֵאת הַכּוֹכָבִים","בְּחֲצוֹת הַלַּיְלָה","לִפְנֵי שְׁקִיעַת הַחַמָּה"],2,"מַקְפִּידִים לְהִתְעַטֵּף לִפְנֵי הַשְּׁקִיעָה, כְּדֵי שֶׁאֶפְשָׁר יִהְיֶה לְבָרֵךְ עַל הַטַּלִּית.","פֶּרֶק פ״ב, הֲלָכָה ג׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["בְּאֵיזֶה פִּיּוּט פּוֹתְחִים קְהִלּוֹת הַסְּפָרַדִּים אֶת תְּפִלּוֹת יוֹם הַכִּפּוּרִים?",["״אֲדוֹן עוֹלָם״","״לְךָ אֵ-לִי״","״מָעוֹז צוּר״"],1,"הַסְּפָרַדִּים פּוֹתְחִים בַּ״לְךָ אֵ-לִי״ שֶׁל רַבִּי יְהוּדָה הַלֵּוִי, שֶׁכֻּלּוֹ וִדּוּי, וְהָאַשְׁכְּנַזִּים אוֹמְרִים ״תְּפִלָּה זַכָּה״ מֵאוֹתוֹ טַעַם.","פֶּרֶק פ״ב, הֲלָכָה ד׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["עַל מָה מְבַקְּשִׁים בִּתְפִלַּת ״כָּל נִדְרֵי״, וּמָה מְבָרְכִים בְּסוֹפָהּ?",["הַתָּרַת נְדָרִים, וּבִרְכַּת ״שֶׁהֶחֱיָנוּ״","גֶּשֶׁם, וּבִרְכַּת ״הַמּוֹצִיא״","בְּרִיאוּת, וּבִרְכַּת ״בּוֹרֵא פְּרִי הַגֶּפֶן״"],0,"״כָּל נִדְרֵי״ הִיא בַּקָּשָׁה לְהַתָּרַת נְדָרִים, כִּי מִי שֶׁיֵּשׁ בּוֹ עֲווֹן נְדָרִים אֵין תְּפִלָּתוֹ נִשְׁמַעַת. בְּסִיּוּמָהּ מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ עַל שֶׁזָּכִינוּ לְהַגִּיעַ לְיוֹם הַכִּפּוּרִים.","פֶּרֶק פ״ב, הֲלָכוֹת ה׳-ו׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["יוֹם הַכִּפּוּרִים חָל בְּשַׁבָּת. מָה אוֹמְרִים אַחֲרֵי עֲמִידַת עַרְבִית?",["הַבְדָּלָה","״וַיְכֻלּוּ״","הַלֵּל"],1,"אַחֲרֵי כָּל נִדְרֵי אוֹמְרִים קַבָּלַת שַׁבָּת מְקֻצֶּרֶת, וְאַחֲרֵי הָעֲמִידָה ״וַיְכֻלּוּ״ וּבִרְכַּת ״מֵעֵין שֶׁבַע״.","פֶּרֶק פ״ב, הֲלָכָה ז׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["אֵיךְ אוֹמְרִים ״בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ״ בְּיוֹם הַכִּפּוּרִים?",["בְּלַחַשׁ","לֹא אוֹמְרִים כְּלָל","בְּקוֹל רָם"],2,"אוֹמְרִים בְּקוֹל רָם, כִּי בְּיוֹם זֶה יִשְׂרָאֵל דּוֹמִים לַמַּלְאָכִים, וְהַמַּלְאָכִים אוֹמְרִים מִלִּים אֵלּוּ בְּקוֹל רָם.","פֶּרֶק פ״ב, הֲלָכָה ח׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["הִתְוַדֵּינוּ כְּבָר בְּמִנְחָה שֶׁל עֶרֶב יוֹם הַכִּפּוּרִים. מָתַי מִתְוַדִּים שׁוּב?",["בְּכָל תְּפִלּוֹת הַיּוֹם","רַק בִּנְעִילָה","לֹא מִתְוַדִּים שׁוּב"],0,"חוֹזְרִים וּמִתְוַדִּים בְּעַרְבִית, בְּשַׁחֲרִית, בְּמוּסָף, בְּמִנְחָה וּבִנְעִילָה. וְהַוִּדּוּי מוֹעִיל רַק אִם מִתְחָרְטִים וּמְקַבְּלִים לֹא לַחְזֹר עַל הַחֵטְא.","פֶּרֶק פ״ב, הֲלָכָה ט׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["אֵיךְ אוֹמְרִים אֶת הַוִּדּוּי?",["יוֹשְׁבִים וּמוֹחֲאִים כַּפַּיִם","עוֹמְדִים וּמַכִּים מְעַט עַל הַלֵּב","שׁוֹכְבִים עַל הָרִצְפָּה"],1,"אֶת הַוִּדּוּי אוֹמְרִים בַּעֲמִידָה, וּבְכָל חֵטְא מַכִּים מְעַט עַל הַלֵּב, כְּאִלּוּ אוֹמְרִים לוֹ: אַתָּה גָּרַמְתָּ לָנוּ לַחְטֹא.","פֶּרֶק פ״ב, הֲלָכוֹת י׳-י״א","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["הַאִם מִתְוַדִּים גַּם עַל חֲטָאִים שֶׁכְּבָר שַׁבְנוּ מֵהֶם, וְגַם עַל חֲטָאִים שֶׁלֹּא עָשִׂינוּ?",["לֹא, רַק עַל מַה שֶּׁעָשִׂינוּ הַשָּׁנָה","רַק הַחַזָּן מִתְוַדֶּה עֲלֵיהֶם","כֵּן, אוֹמְרִים אֶת כָּל סֵדֶר הַוִּדּוּי"],2,"מְשֻׁבָּח לְהִתְוַדּוֹת גַּם עַל חֲטָאִים שֶׁשַּׁבְנוּ מֵהֶם, שֶׁנֶּאֱמַר ״וְחַטָּאתִי נֶגְדִּי תָמִיד״. וְאוֹמְרִים אֶת כָּל הַוִּדּוּי, כִּי כָּל יִשְׂרָאֵל עֲרֵבִים זֶה לָזֶה, וּכְדֵי שֶׁמִּי שֶׁחָטָא לֹא יִתְבַּיֵּשׁ.","פֶּרֶק פ״ב, הֲלָכוֹת י״ב-י״ג","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["בִּתְפִלַּת מִנְחָה שֶׁל יוֹם הַכִּפּוּרִים מַפְטִירִים בְּאֵיזֶה סֵפֶר?",["סֵפֶר יוֹנָה","מְגִלַּת אֶסְתֵּר","מְגִלַּת רוּת"],0,"מַפְטִירִים בְּסֵפֶר יוֹנָה, שֶׁמִּמֶּנּוּ לוֹמְדִים שֶׁאִי אֶפְשָׁר לִבְרֹחַ מִלִּפְנֵי ה׳, וְאֶת כֹּחָהּ שֶׁל הַתְּשׁוּבָה.","פֶּרֶק פ״ב, הֲלָכָה י״ד","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מָתַי מִתְפַּלְּלִים נְעִילָה – הַתְּפִלָּה שֶׁבָּהּ רָאוּי לְהִתְאַמֵּץ מְאֹד?",["בַּבֹּקֶר, כְּשֶׁהַשֶּׁמֶשׁ זוֹרַחַת","כְּשֶׁהַחַמָּה בְּרָאשֵׁי הָאִילָנוֹת","בַּחֲצוֹת הַלַּיְלָה"],1,"נְעִילָה הִיא בְּסִיּוּם הַיּוֹם, כַּחֲצִי שָׁעָה לִפְנֵי הַשְּׁקִיעָה. מִתְאַמְּצִים בָּהּ מְאֹד, כִּי הַכֹּל הוֹלֵךְ אַחַר הַחִתּוּם.","פֶּרֶק פ״ב, הֲלָכָה ט״ו-ט״ז","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["בִּנְעִילָה, בִּמְקוֹם ״כָּתְבֵנוּ״ אוֹמְרִים...",["קְרָאֵנוּ","כָּתְבֵנוּ","חָתְמֵנוּ"],2,"בִּנְעִילָה אוֹמְרִים ״חָתְמֵנוּ״ וַ״חֲתֹם״, מִפְּנֵי שֶׁזֶּהוּ זְמַן חֲתִימַת הַדִּין.","פֶּרֶק פ״ב, הֲלָכָה י״ז","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["בִּרְכַּת כֹּהֲנִים שֶׁל נְעִילָה חֲבִיבָה מְאֹד. מָה נָהֲגוּ הַסְּפָרַדִּים בִּירוּשָׁלַיִם לַעֲשׂוֹת לְמֵי הַנְּטִילָה שֶׁל הַכֹּהֲנִים?",["לְבַשֵּׂם אֶת הַמַּיִם","לְחַמֵּם אֶת הַמַּיִם","לִצְבֹּעַ אֶת הַמַּיִם"],0,"מִתּוֹךְ חֲבִיבוּת נְשִׂיאַת כַּפַּיִם שֶׁל נְעִילָה – שֶׁמִּשְׁתַּדְּלִים לְהַגִּיעַ אֵלֶיהָ לִפְנֵי הַשְּׁקִיעָה – נָהֲגוּ לְבַשֵּׂם אֶת הַמַּיִם.","פֶּרֶק פ״ב, הֲלָכָה י״ח-י״ט","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["אַחֲרֵי שֶׁבַע פְּעָמִים ״ה׳ הוּא הָאֱ-לֹהִים״, מָה עוֹשִׂים?",["מְנַעְנְעִים לוּלָב","תּוֹקְעִים בַּשּׁוֹפָר","מְצַלְצְלִים בְּפַעֲמוֹן"],1,"אוֹמְרִים שְׁמַע יִשְׂרָאֵל, בָּרוּךְ שֵׁם, שֶׁבַע פְּעָמִים ״ה׳ הוּא הָאֱ-לֹהִים״ – וְתוֹקְעִים בַּשּׁוֹפָר (לְאַחַר צֵאת הַכּוֹכָבִים).","פֶּרֶק פ״ב, הֲלָכָה כ׳","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים קוֹרְאִים בְּסוֹף נְעִילָה: ״לַשָּׁנָה הַבָּאָה בְּ...״",["בַּמִּדְבָּר","עַל שְׂפַת הַיָּם","יְרוּשָׁלַיִם הַבְּנוּיָה"],2,"מְסַיְּמִים בַּפָּסוּק ״לֵךְ אֱכֹל בְּשִׂמְחָה לַחְמֶךָ״, וּבִקְהִלּוֹת הָאַשְׁכְּנַזִּים קוֹרְאִים: ״לַשָּׁנָה הַבָּאָה בִּירוּשָׁלַיִם הַבְּנוּיָה!״","פֶּרֶק פ״ב, הֲלָכָה כ״א","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מָה נוֹהֲגִים לְקַדֵּשׁ אַחֲרֵי עַרְבִית שֶׁל מוֹצָאֵי יוֹם הַכִּפּוּרִים?",["אֶת הַלְּבָנָה","אֶת הַחַמָּה","אֶת הַכּוֹכָבִים"],0,"מְקַדְּשִׁים אֶת הַלְּבָנָה, מִפְּנֵי שֶׁמּוֹצָאֵי יוֹם הַכִּפּוּרִים הוּא זְמַן שִׂמְחָה.","פֶּרֶק פ״ב, הֲלָכָה כ״ב","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["בְּהַבְדָּלָה, לִפְנֵי שֶׁאוֹכְלִים וּשְׂמֵחִים – עַל אֵיזֶה נֵר מְבָרְכִים?",["נֵר חָדָשׁ שֶׁהֻדְלַק עַכְשָׁו","נֵר שֶׁשָּׁבַת, שֶׁדָּלַק מֵעֶרֶב הַחַג","פַּנָּס חַשְׁמַלִּי"],1,"מְבָרְכִים עַל הַגֶּפֶן וְעַל נֵר שֶׁשָּׁבַת, וְלֹא עַל בְּשָׂמִים. אַחַר כָּךְ אוֹכְלִים וּשְׂמֵחִים, מִתּוֹךְ בִּטָּחוֹן שֶׁה׳ קִבֵּל אֶת תְּפִלּוֹתֵינוּ.","פֶּרֶק פ״ב, הֲלָכָה כ״ג-כ״ד","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מָה נוֹהֲגִים לְהַתְחִיל לִבְנוֹת בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים?",["אַרְמוֹן חוֹל","אִישׁ שֶׁלֶג","סֻכָּה"],2,"מַתְחִילִים לִבְנוֹת אֶת הַסֻּכָּה, כְּדֵי לָצֵאת מִמִּצְוָה לְמִצְוָה.","פֶּרֶק פ״ב, הֲלָכָה כ״ה","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["לְפִי רַבִּי עֲקִיבָא, בְּמָה יָשְׁבוּ בְּנֵי יִשְׂרָאֵל בַּמִּדְבָּר?",["בְּבָתֵּי אֶבֶן","בְּסֻכּוֹת מַמָּשׁ","בְּאָרְמוֹנוֹת"],1,"רַבִּי עֲקִיבָא אוֹמֵר שֶׁהָיוּ אֵלּוּ סֻכּוֹת מַמָּשׁ, וְרַבִּי אֱלִיעֶזֶר אוֹמֵר שֶׁהַכַּוָּנָה לְעַנְנֵי הַכָּבוֹד.","פֶּרֶק פ״ג, הֲלָכָה א׳","בְּנִיַּת הַסֻּכָּה"],["לָמָּה מִצְוַת הַסֻּכָּה כָּל כָּךְ חֲבִיבָה?",["מְקַיְּמִים אוֹתָהּ בְּכָל הַגּוּף","הִיא קְטַנָּה וְקַלָּה","יֵשׁ בָּהּ הַרְבֵּה צְבָעִים"],0,"בַּסֻּכָּה אָנוּ אוֹכְלִים, יְשֵׁנִים וְנִמְצָאִים כָּל הַזְּמַן בְּמָקוֹם קָדוֹשׁ, בְּ״צֵל הָאֱמוּנָה״.","פֶּרֶק פ״ג, הֲלָכָה ב׳","בְּנִיַּת הַסֻּכָּה"],["אֵיפֹה מֻתָּר לִבְנוֹת סֻכָּה?",["מִתַּחַת לְעֵץ גָּדוֹל","מִתַּחַת לְמִרְפֶּסֶת","תַּחַת כִּפַּת הַשָּׁמַיִם"],2,"הַסֻּכָּה צְרִיכָה לִהְיוֹת תַּחַת כִּפַּת הַשָּׁמַיִם, וְלֹא מִתַּחַת לְבַיִת, מִרְפֶּסֶת מְקֹרָה אוֹ עַנְפֵי עֵץ.","פֶּרֶק פ״ג, הֲלָכָה ג׳","בְּנִיַּת הַסֻּכָּה"],["מָה בּוֹנִים קֹדֶם בַּסֻּכָּה?",["אֶת הַסְּכָךְ","אֶת הַדְּפָנוֹת","אֶת הַקִּשּׁוּטִים"],1,"בּוֹנִים קֹדֶם דְּפָנוֹת וְרַק אַחַר כָּךְ סְכָךְ. מִי שֶׁטָּעָה, יַגְבִּיהַּ אֶת הַסְּכָךְ וְיַנִּיחֶנּוּ שׁוּב לְשֵׁם מִצְוַת סֻכָּה.","פֶּרֶק פ״ג, הֲלָכָה ד׳-ה׳","בְּנִיַּת הַסֻּכָּה"],["מִמָּה אָסוּר לַעֲשׂוֹת דְּפָנוֹת לַסֻּכָּה?",["מִקְּרָשִׁים שֶׁל עֵץ","מִבַּד חָזָק וּמָתוּחַ","מִדָּבָר שֶׁרֵיחוֹ רַע"],2,"דְּפָנוֹת יְכוֹלוֹת לִהְיוֹת מִכָּל חֹמֶר, אֲבָל לֹא מִדָּבָר שֶׁרֵיחוֹ רַע אוֹ שֶׁעָלוּל לְהִתְיַבֵּשׁ בַּחַג.","פֶּרֶק פ״ג, הֲלָכָה ו׳","בְּנִיַּת הַסֻּכָּה"],["מָה הַגֹּבַהּ הַקָּטָן בְּיוֹתֵר שֶׁל דֹּפֶן כְּשֵׁרָה?",["שְׁמוֹנִים ס״מ","עֶשְׂרִים ס״מ","חֲמִשָּׁה ס״מ"],0,"גֹּבַהּ הַדֹּפֶן לְפָחוֹת עֲשָׂרָה טְפָחִים, שֶׁהֵם שְׁמוֹנִים ס״מ, וּלְהִדּוּר מִצְוָה מֶטֶר.","פֶּרֶק פ״ג, הֲלָכָה ז׳","בְּנִיַּת הַסֻּכָּה"],["אֵיזוֹ דֹּפֶן שֶׁל חֲבָלִים כְּשֵׁרָה?",["חֶבֶל אֶחָד לְמַטָּה","חֲבָלִים קְרוֹבִים זֶה לָזֶה","חֲבָלִים רְחוֹקִים מְאֹד"],1,"דִּין ״לָבוּד״: אִם הָרֶוַח בֵּין הַחֲבָלִים פָּחוֹת מִשְּׁלוֹשָׁה טְפָחִים, הֵם נֶחְשָׁבִים מְחֻבָּרִים.","פֶּרֶק פ״ג, הֲלָכָה ח׳","בְּנִיַּת הַסֻּכָּה"],["מִי יָכוֹל לַעֲבֹר מִתַּחַת לְדֹפֶן מֻגְבַּהַת וּלְפָסֹל אוֹתָהּ?",["פִּיל","סוּס","גְּדִי"],2,"דֹּפֶן שֶׁמֻּגְבַּהַת שְׁלוֹשָׁה טְפָחִים מֵהַקַּרְקַע פְּסוּלָה, כִּי גְּדָיִים יְכוֹלִים לַעֲבֹר מִתַּחְתֶּיהָ.","פֶּרֶק פ״ג, הֲלָכָה ט׳","בְּנִיַּת הַסֻּכָּה"],["אֵיזוֹ דֹּפֶן בַּד טוֹבָה יוֹתֵר?",["בַּד מָתוּחַ וְקָשׁוּר הֵיטֵב","בַּד רָפוּי שֶׁמִּתְנַפְנֵף","בַּד קָרוּעַ"],0,"הַדְּפָנוֹת צְרִיכוֹת לַעֲמֹד בְּרוּחַ מְצוּיָה, לָכֵן יֵשׁ לִמְתֹּחַ אֶת הַבַּד וְלִקְשֹׁר אוֹתוֹ הֵיטֵב.","פֶּרֶק פ״ג, הֲלָכָה י׳-י״א","בְּנִיַּת הַסֻּכָּה"],["בְּמָה מֻתָּר לְסַכֵּךְ אֶת הַסֻּכָּה?",["מוֹטוֹת בַּרְזֶל","עַנְפֵי עֵצִים","כִּסֵּא עֵץ יָשָׁן"],1,"סְכָךְ כָּשֵׁר גָּדֵל מִן הָאָרֶץ, תָּלוּשׁ, וְאֵינוֹ מְקַבֵּל טֻמְאָה. בַּרְזֶל וְרָהִיטִים מֵעֵץ מְקַבְּלִים טֻמְאָה.","פֶּרֶק פ״ג, הֲלָכָה י״ב","סְכָךְ וְנוֹי סֻכָּה"],["אֵיזֶה סְכָךְ אֵין לְהָנִיחַ עַל הַסֻּכָּה?",["עָנָף שֶׁעָלָיו נוֹשְׁרִים","מַחְצֶלֶת קָנִים","קְרָשִׁים פְּשׁוּטִים"],0,"סְכָךְ שֶׁרֵיחוֹ רַע אוֹ שֶׁעָלָיו נוֹשְׁרִים – אֵין לְסַכֵּךְ בּוֹ אֶת הַסֻּכָּה.","פֶּרֶק פ״ג, הֲלָכָה י״ג","סְכָךְ וְנוֹי סֻכָּה"],["בְּסֻכָּה עִם מִסְגֶּרֶת בַּרְזֶל – מָה מַנִּיחִים תְּחִלָּה עַל הַבַּרְזִלִּים, לִפְנֵי הַסְּכָךְ?",["שְׂמִיכָה","שַׁרְשֶׁרֶת בַּרְזֶל","קְרָשֵׁי עֵץ אֲרֻכִּים"],2,"אֵין לְהַעֲמִיד סְכָךְ עַל דָּבָר הַמְּקַבֵּל טֻמְאָה, לָכֵן מַנִּיחִים קְרָשֵׁי עֵץ עַל הַבַּרְזִלִּים, וַעֲלֵיהֶם אֶת הַסְּכָךְ.","פֶּרֶק פ״ג, הֲלָכָה י״ד","סְכָךְ וְנוֹי סֻכָּה"],["לְשֵׁם מָה מֻתָּר לְחַבֵּר אֶת עֲצֵי הַסְּכָךְ בַּחֲבָלִים אוֹ בְּמַסְמְרִים?",["כְּדֵי שֶׁלֹּא יָעוּפוּ בָּרוּחַ","כְּדֵי שֶׁיִּהְיֶה יָפֶה","כְּדֵי שֶׁלֹּא יִכָּנְסוּ צִפּוֹרִים"],0,"מֻתָּר לְחַבֵּר אֶת עֲצֵי הַסְּכָךְ בְּמַסְמְרִים אוֹ בַּחֲבָלִים כְּדֵי שֶׁלֹּא יָעוּפוּ בָּרוּחַ, וְיֵשׁ מַחְמִירִים בָּזֶה.","פֶּרֶק פ״ג, הֲלָכָה ט״ו","סְכָךְ וְנוֹי סֻכָּה"],["אֵיזוֹ סֻכָּה עֲשׂוּיָה כָּרָאוּי לְכַתְּחִלָּה?",["סֻכָּה שֶׁרֻבָּהּ שֶׁמֶשׁ","סֻכָּה מוּצֶלֶת שֶׁרוֹאִים דַּרְכָּהּ כּוֹכָבִים","סֻכָּה צְפוּפָה שֶׁגֶּשֶׁם לֹא חוֹדֵר"],1,"הַצֵּל בַּסֻּכָּה צָרִיךְ לִהְיוֹת מְרֻבֶּה מֵהַשֶּׁמֶשׁ, וּלְכַתְּחִלָּה הַכּוֹכָבִים הַגְּדוֹלִים יֵרָאוּ דֶּרֶךְ הַסְּכָךְ. סְכָךְ צָפוּף שֶׁגֶּשֶׁם לֹא חוֹדֵר – יֵשׁ פּוֹסְלִים.","פֶּרֶק פ״ג, הֲלָכָה ט״ז-י״ז","סְכָךְ וְנוֹי סֻכָּה"],["אֵיךְ נָהֲגוּ יַלְדֵי יִשְׂרָאֵל לְקַשֵּׁט אֶת הַסֻּכָּה?",["בַּעֲלֵי עֵץ יְבֵשִׁים","בִּבְגָדִים יְשָׁנִים","בְּשַׁרְשְׁרָאוֹת נְיָר צִבְעוֹנִי"],2,"מִ״זֶּה אֵ-לִי וְאַנְוֵהוּ״ לָמְדוּ לְקַיֵּם מִצְווֹת בְּצוּרָה נָאָה, וְיַלְדֵי יִשְׂרָאֵל נָהֲגוּ לְהָכִין שַׁרְשְׁרָאוֹת נְיָר צִבְעוֹנִי לַסֻּכָּה.","פֶּרֶק פ״ג, הֲלָכָה י״ח","סְכָךְ וְנוֹי סֻכָּה"],["תַּחַת אֵיזֶה קִשּׁוּט מֻתָּר לָשֶׁבֶת בַּסֻּכָּה?",["קִשּׁוּט שֶׁתָּלוּי צָמוּד לַסְּכָךְ","קִשּׁוּט שֶׁתָּלוּי נָמוּךְ מְאֹד","קִשּׁוּט שֶׁתָּלוּי רָחוֹק מֵהַסְּכָךְ"],0,"קִשּׁוּט שֶׁקָּרוֹב לַסְּכָךְ פָּחוֹת מֵאַרְבָּעָה טְפָחִים בָּטֵל לַסְּכָךְ, וּמֻתָּר לָשֶׁבֶת תַּחְתָּיו. אִם הוּא רָחוֹק יוֹתֵר – אֵין לָשֶׁבֶת תַּחְתָּיו.","פֶּרֶק פ״ג, הֲלָכָה י״ט","סְכָךְ וְנוֹי סֻכָּה"],["יוֹרֵד גֶּשֶׁם עַל הַסֻּכָּה בַּחַג. מָה מֻתָּר לַעֲשׂוֹת עִם הַקִּשּׁוּטִים?",["לְהַכְנִיס וְלִתְלוֹת שׁוּב אַחֲרֵי הַגֶּשֶׁם","לִזְרֹק אוֹתָם לַפַּח","לְשַׂחֵק בָּהֶם בַּבַּיִת"],0,"בִּימֵי הַחַג אָסוּר לְהִשְׁתַּמֵּשׁ בְּקִשּׁוּטֵי הַסֻּכָּה, אֲבָל כְּשֶׁיּוֹרֵד גֶּשֶׁם מֻתָּר לְטַלְטֵל אוֹתָם כְּדֵי לִתְלוֹתָם שׁוּב אַחֲרֵי שֶׁיִּפָּסֵק.","פֶּרֶק פ״ג, הֲלָכָה כ׳-כ״א","סְכָךְ וְנוֹי סֻכָּה"],["מָה אוֹמְרִים בְּשָׁעַת תְּלִיַּת הַפֵּרוֹת, כְּדֵי שֶׁיֻּתַּר לֶאֱכֹל מֵהֶם בַּחַג?",["בִּרְכַּת הַמָּזוֹן","תְּנַאי שֶׁאוּכַל לְהִשְׁתַּמֵּשׁ בָּהֶם","שִׁיר לְחַג הַסֻּכּוֹת"],1,"הָרוֹצֶה לֶאֱכֹל מִפֵּרוֹת הַסֻּכָּה אוֹמֵר בְּשָׁעַת הַתְּלִיָּה: ״אֲנִי תּוֹלֶה... בִּתְנַאי שֶׁאוּכַל לְהִשְׁתַּמֵּשׁ בָּהֶם כְּשֶׁאֶרְצֶה״.","פֶּרֶק פ״ג, הֲלָכָה כ״ב","סְכָךְ וְנוֹי סֻכָּה"],["אֵיפֹה אוֹכְלִים אֲרוּחָה בְּשִׁבְעַת יְמֵי חַג הַסֻּכּוֹת?",["בַּסֻּכָּה","בַּסָּלוֹן","בַּמִּרְפֶּסֶת בְּלִי סְכָךְ"],0,"״תֵּשְׁבוּ – כְּעֵין תָּדוּרוּ״: בְּכָל שִׁבְעַת יְמֵי הַחַג הַסֻּכָּה הִיא כְּבֵיתֵנוּ, וְחַיָּבִים לֶאֱכֹל וְלִשְׁתּוֹת בָּהּ בַּיּוֹם וּבַלַּיְלָה.","פֶּרֶק פ״ד, הֲלָכָה א׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["יוֹסִי עָיֵף בְּחֹל הַמּוֹעֵד וְרוֹצֶה לִישֹׁן קְצָת. אֵיפֹה יִישַׁן?",["בַּמִּטָּה בַּחֶדֶר","עַל הַסַּפָּה בַּבַּיִת","בַּסֻּכָּה"],2,"הַסֻּכָּה הִיא כְּבֵיתוֹ שֶׁל הָאָדָם, לָכֵן אָסוּר לִישֹׁן מִחוּץ לַסֻּכָּה אֲפִלּוּ שְׁנַת עֲרַאי.","פֶּרֶק פ״ד, הֲלָכָה ב׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["מָה מַתְאִים לַעֲשׂוֹת בִּזְמַן הַיְּשִׁיבָה בַּסֻּכָּה?",["לְרַכֵּל עַל חֲבֵרִים","לִלְמֹד תּוֹרָה","לְדַבֵּר לָשׁוֹן הָרַע"],1,"בַּסֻּכָּה מִשְׁתַּדְּלִים לַעֲסֹק בְּדִבְרֵי תּוֹרָה וּקְדֻשָּׁה. לָשׁוֹן הָרַע וּרְכִילוּת אֲסוּרִים בְּכָל מָקוֹם, וְקַל וָחֹמֶר בַּסֻּכָּה.","פֶּרֶק פ״ד, הֲלָכָה ג׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["עֶרֶב סֻכּוֹת, אַחֲרֵי חֲצוֹת הַיּוֹם. מָה מֻתָּר לֶאֱכֹל?",["מְעַט פֵּרוֹת","אֲרוּחָה גְּדוֹלָה","מַגַּשׁ פִּיצָה שָׁלֵם"],0,"כְּדֵי שֶׁנֹּאכַל בַּסֻּכָּה לְתֵאָבוֹן בְּלֵיל הַחַג, אָסוּר לֶאֱכֹל אֲרוּחָה גְּדוֹלָה מֵחֲצוֹת הַיּוֹם, אֲבָל מֻתָּר מְעַט פֵּרוֹת אוֹ יְרָקוֹת.","פֶּרֶק פ״ד, הֲלָכָה ד׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["בַּמֶּה כְּדַאי לְהַרְבּוֹת בְּעֶרֶב סֻכּוֹת?",["בְּמִשְׂחָקִים","בְּשֵׁנָה","בִּצְדָקָה לָעֲנִיִּים"],2,"בְּעֶרֶב סֻכּוֹת מַרְבִּים בִּצְדָקָה לָעֲנִיִּים כְּדֵי לְשַׂמְּחָם בַּחַג, שֶׁנֶּאֱמַר: ״וְשָׂמַחְתָּ בְּחַגֶּךָ״.","פֶּרֶק פ״ד, הֲלָכָה ה׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["אֵיזוֹ בְּרָכָה מְיֻחֶדֶת אוֹמְרִים בְּקִדּוּשׁ לֵיל חַג הַסֻּכּוֹת?",["לֵישֵׁב בַּסֻּכָּה","הַמּוֹצִיא לֶחֶם","בּוֹרֵא נְפָשׁוֹת"],0,"סֵדֶר הַקִּדּוּשׁ: בִּרְכַּת הַיַּיִן, קִדּוּשׁ הַיּוֹם, ״לֵישֵׁב בַּסֻּכָּה״ וְ״שֶׁהֶחֱיָנוּ״. מִי שֶׁשָּׁכַח ״שֶׁהֶחֱיָנוּ״ – יָכוֹל לְבָרֵךְ כָּל שִׁבְעַת יְמֵי הַחַג.","פֶּרֶק פ״ד, הֲלָכָה ו׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["מָתַי מַתְחִילִים לֶאֱכֹל בַּסֻּכָּה בְּלֵיל הַחַג הָרִאשׁוֹן?",["בַּצָּהֳרַיִם","אַחֲרֵי צֵאת הַכּוֹכָבִים","בִּשְׁעַת הַשְּׁקִיעָה"],1,"אֲכִילָה בַּסֻּכָּה בַּלַּיְלָה הָרִאשׁוֹן הִיא חוֹבָה מֵהַתּוֹרָה, לָכֵן אוֹכְלִים רַק אַחֲרֵי צֵאת הַכּוֹכָבִים, לְפָחוֹת כַּזַּיִת פַּת.","פֶּרֶק פ״ד, הֲלָכָה ח׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["אֶת מִי מַזְמִינִים לַסֻּכָּה כָּאֻשְׁפִּיזִין?",["אֶת כָּל הַשְּׁכֵנִים","אַבְרָהָם, יִצְחָק, יַעֲקֹב וְעוֹד","אֶת חַבְרֵי הַכִּתָּה"],1,"הָאֻשְׁפִּיזִין הֵם אַבְרָהָם, יִצְחָק, יַעֲקֹב, מֹשֶׁה, אַהֲרֹן, יוֹסֵף וְדָוִד. בְּכָל לַיְלָה אֶחָד מֵהֶם הוּא הָעִקָּרִי.","פֶּרֶק פ״ד, הֲלָכָה ט׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["דָּנִי רוֹצֶה לֶאֱכֹל סְעוּדַת קֶבַע עִם לֶחֶם בְּחֹל הַמּוֹעֵד. אֵיפֹה יֹאכַל?",["בַּמִּטְבָּח","בַּגִּנָּה לְיַד הַסֻּכָּה","בַּסֻּכָּה"],2,"אָסוּר לֶאֱכֹל אֲכִילַת קֶבַע מִחוּץ לַסֻּכָּה, וְלִפְנֵי אֲכִילַת קֶבַע מְבָרְכִים ״לֵישֵׁב בַּסֻּכָּה״. אֲכִילַת עֲרַאי מֻתֶּרֶת בַּחוּץ, וְהַמְּהַדֵּר – מְשֻׁבָּח.","פֶּרֶק פ״ד, הֲלָכָה י״א","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["לָמָּה כְּדַאי לְהִשְׁתַּדֵּל לִבְנוֹת סֻכָּה גְּדוֹלָה?",["כְּדֵי שֶׁיִּהְיֶה מָקוֹם לְמִשְׂחָקִים","כְּדֵי שֶׁכָּל בְּנֵי הַבַּיִת יֵשְׁבוּ בָּהּ","כְּדֵי לְהַרְאוֹת לַשְּׁכֵנִים"],1,"נָשִׁים פְּטוּרוֹת מִן הַסֻּכָּה כִּי הִיא מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ, וְאִם הֵן יוֹשְׁבוֹת בָּהּ יֵשׁ לָהֶן שָׂכָר. לָכֵן יִשְׁתַּדֵּל כָּל אָדָם לִבְנוֹת סֻכָּה גְּדוֹלָה, שֶׁיֵּשְׁבוּ בָּהּ הוּא, אִשְׁתּוֹ וְכָל בְּנֵי בֵּיתוֹ, וְיִזְכּוּ לְהִסְתּוֹפֵף ״בְּצֵל הָאֱמוּנָה״.","פֶּרֶק פ״ה, הֲלָכָה א׳","מִי חַיָּב בַּסֻּכָּה?"],["מֵאֵיזֶה גִּיל יֶלֶד חַיָּב בַּסֻּכָּה כְּדֵי לְחַנְּכוֹ?",["מִגִּיל שְׁתֵּים עֶשְׂרֵה","מִגִּיל שָׁנָה","מִגִּיל חָמֵשׁ אוֹ שֵׁשׁ"],2,"יֶלֶד קָטָן מִגִּיל חָמֵשׁ-שֵׁשׁ חַיָּב בַּסֻּכָּה מִדִּבְרֵי סוֹפְרִים (חֲכָמִים), כְּדֵי לְחַנְּכוֹ בְּמִצְווֹת.","פֶּרֶק פ״ה, הֲלָכָה ב׳","מִי חַיָּב בַּסֻּכָּה?"],["מִי מֻתָּר לוֹ לָצֵאת מֵהַסֻּכָּה וּלְהִכָּנֵס לַבַּיִת?",["מִי שֶׁסּוֹבֵל מֵהַרְבֵּה יַתּוּשִׁים","מִי שֶׁקְּצָת מִשְׁתַּעֲמֵם","מִי שֶׁרוֹצֶה לְשַׂחֵק בַּבַּיִת"],0,"״הַמִּצְטַעֵר פָּטוּר מִן הַסֻּכָּה״. מֻתָּר לָצֵאת מִפְּנֵי דְּבָרִים הַמְּצַעֲרִים אֶת הַיּוֹשֵׁב בַּסֻּכָּה, כְּמוֹ שָׁרָב, קֹר גָּדוֹל, רֵיחַ רַע, יַתּוּשִׁים וְרַעַשׁ.","פֶּרֶק פ״ה, הֲלָכָה ג׳","מִי חַיָּב בַּסֻּכָּה?"],["בְּלֵיל שַׁבָּת כָּבָה הָאוֹר בַּסֻּכָּה. מָה הַדִּין?",["חַיָּב לָלֶכֶת לְסֻכַּת חֲבֵרוֹ","פָּטוּר, וּמֻתָּר לֶאֱכֹל בַּבַּיִת","מַדְלִיקִים אֶת הָאוֹר בְּשַׁבָּת"],1,"מִי שֶׁכָּבָה לוֹ אוֹר הַחַשְׁמַל בַּסֻּכָּה בְּלֵיל הַחַג אוֹ בְּלֵיל שַׁבָּת – מִצְטַעֵר וּפָטוּר, וְאֵינוֹ חַיָּב לָלֶכֶת לְסֻכַּת חֲבֵרוֹ. אֲבָל בַּלַּיְלָה הָרִאשׁוֹן חוֹבָה לֶאֱכֹל כַּזַּיִת בַּסֻּכָּה אֲפִלּוּ בַּחֲשֵׁכָה.","פֶּרֶק פ״ה, הֲלָכָה ד׳","מִי חַיָּב בַּסֻּכָּה?"],["אֵיפֹה נָכוֹן לִבְנוֹת אֶת הַסֻּכָּה?",["לְיַד פַּח אַשְׁפָּה מַסְרִיחַ","לְיַד בִּיב עִם רֵיחַ רַע","בְּחָצֵר נְקִיָּה וּשְׁקֵטָה"],2,"אֵין לִבְנוֹת סֻכָּה בְּמָקוֹם שֶׁיָּדוּעַ מֵרֹאשׁ שֶׁיִּגָּרֵם בּוֹ צַעַר, כְּמוֹ רֵיחַ רַע בִּקְבִיעוּת. רַק אִם הִתְבָּרֵר הַדָּבָר אַחֲרֵי שֶׁהַסֻּכָּה נִבְנְתָה – פְּטוּרִים.","פֶּרֶק פ״ה, הֲלָכָה ה׳","מִי חַיָּב בַּסֻּכָּה?"],["אֵיךְ יוֹצְאִים מֵהַסֻּכָּה כְּשֶׁיּוֹרֵד גֶּשֶׁם שֶׁמְּקַלְקֵל אֶת הָאֹכֶל?",["בְּהַכְנָעָה, כְּעֶבֶד לִפְנֵי רַבּוֹ","בִּצְחוֹק וּבְרִקּוּדִים","בְּכַעַס וּבִטְרִיקַת דֶּלֶת"],0,"כְּשֶׁהַגֶּשֶׁם יָכוֹל לְקַלְקֵל אֶת הַמַּאֲכָלִים מֻתָּר לְהִכָּנֵס לַבַּיִת וְלֹא צָרִיךְ לַחְזֹר גַּם אִם פָּסַק. גֶּשֶׁם בַּחַג הוּא סִימַן קְלָלָה, כְּעֶבֶד שֶׁמָּזַג כּוֹס לְרַבּוֹ וְרַבּוֹ שָׁפַךְ אוֹתָהּ עַל פָּנָיו – לָכֵן יוֹצְאִים בְּהַכְנָעָה.","פֶּרֶק פ״ה, הֲלָכָה ו׳","מִי חַיָּב בַּסֻּכָּה?"],["בַּלַּיְלָה הָרִאשׁוֹן שֶׁל סֻכּוֹת יוֹרֵד גֶּשֶׁם. אֵיפֹה מְקַדְּשִׁים?",["בַּבַּיִת בִּלְבַד","בַּסֻּכָּה, וְאוֹכְלִים בָּהּ כַּזַּיִת פַּת","לֹא מְקַדְּשִׁים בִּכְלָל"],1,"בַּלַּיְלָה הָרִאשׁוֹן שֶׁל חַג הַסֻּכּוֹת חַיָּבִים לְקַדֵּשׁ בַּסֻּכָּה וְלֶאֱכֹל בָּהּ כַּזַּיִת פַּת – גַּם אִם יוֹרְדִים גְּשָׁמִים.","פֶּרֶק פ״ה, הֲלָכָה ז׳","מִי חַיָּב בַּסֻּכָּה?"],["נַעַר יָשֵׁן בַּסֻּכָּה וְהִתְחִיל לָרֶדֶת גֶּשֶׁם. מָה מֻתָּר לוֹ?",["לַחְזֹר לַסֻּכָּה כָּל כַּמָּה דַּקּוֹת","לְהִשָּׁאֵר לִישֹׁן בַּגֶּשֶׁם","לְהִכָּנֵס לַבַּיִת וְלִישֹׁן שָׁם עַד שֶׁיִּתְעוֹרֵר"],2,"אִם יָרְדוּ גְּשָׁמִים בִּזְמַן הַשֵּׁנָה מֻתָּר לְהִכָּנֵס מִיָּד, כִּי גַּם מְעַט גֶּשֶׁם מַקְשֶׁה מְאֹד עַל הַשֵּׁנָה. וְאַף אִם פָּסְקוּ הַגְּשָׁמִים, אֵין חוֹבָה לַחְזֹר עַד שֶׁמִּתְעוֹרְרִים.","פֶּרֶק פ״ה, הֲלָכָה ח׳","מִי חַיָּב בַּסֻּכָּה?"],["מִי מֵאֵלֶּה פָּטוּר מִן הַסֻּכָּה?",["רוֹפֵא בְּמִשְׁמֶרֶת בְּבֵית חוֹלִים","יֶלֶד שֶׁרוֹצֶה לְשַׂחֵק בַּבַּיִת","אִישׁ שֶׁלֹּא מִתְחַשֵּׁק לוֹ"],0,"חוֹלִים וּמְשַׁמְּשֵׁיהֶם פְּטוּרִים – הַמְּשַׁמֵּשׁ רַק בִּזְמַן שֶׁהַחוֹלֶה צָרִיךְ אוֹתוֹ, כִּי הָעוֹסֵק בְּמִצְוָה פָּטוּר מִן הַמִּצְוָה. רוֹפְאִים בְּבֵית חוֹלִים פְּטוּרִים בְּמֶשֶׁךְ הַמִּשְׁמֶרֶת, וְכֵן שׁוֹטְרִים וְחַיָּלִים בְּתַפְקִיד.","פֶּרֶק פ״ה, הֲלָכָה ט׳-י״ב","מִי חַיָּב בַּסֻּכָּה?"],["יוֹצְאִים לְטִיּוּל בְּחֹל הַמּוֹעֵד לְמָקוֹם בְּלִי סֻכָּה. מָה אוֹכְלִים בַּדֶּרֶךְ?",["סְעוּדָה גְּדוֹלָה עִם לֶחֶם","פֵּרוֹת, יְרָקוֹת וּמְעַט מְזוֹנוֹת","לֹא אוֹכְלִים כְּלוּם כָּל הַיּוֹם"],1,"הוֹלְכֵי דְּרָכִים פְּטוּרִים מִן הַסֻּכָּה. הַיּוֹצֵא לְטִיּוּל יְתַכְנֵן לֶאֱכֹל וְלִישֹׁן בַּסֻּכָּה, וּבַדֶּרֶךְ לֹא יֹאכַל אֲרוּחַת קֶבַע אֶלָּא פֵּרוֹת, יְרָקוֹת וּמְעַט מְזוֹנוֹת. וְיֵשׁ אוֹמְרִים שֶׁמְּטַיְּלִים פְּטוּרִים, אֲבָל גַּם לְדַעְתָּם רָאוּי לְהִשְׁתַּדֵּל בַּמִּצְוָה.","פֶּרֶק פ״ה, הֲלָכָה י״ג-ט״ו","מִי חַיָּב בַּסֻּכָּה?"],["מָה מְבַטֵּאת מִצְוַת נְטִילַת אַרְבַּעַת הַמִּינִים?",["צַעַר וְאֵבֶל עַל הַחֻרְבָּן","שִׂמְחָה לִפְנֵי ה׳ בְּחַג אֲסִיף הַתְּבוּאָה","בַּקָּשַׁת גֶּשֶׁם בִּשְׁנַת בַּצֹּרֶת"],1,"נְטִילַת אַרְבַּעַת הַמִּינִים מְבַטֵּאת אֶת שִׂמְחָתֵנוּ לִפְנֵי ה׳ בְּחַג אֲסִיף הַתְּבוּאָה, כִּי ה׳ בֵּרֵךְ אוֹתָנוּ בְּכָל הַתְּבוּאָה.","פֶּרֶק פ״ו, הֲלָכָה א׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["הֵיכָן קוֹנִים רֹב הָאֲנָשִׁים בְּיָמֵינוּ אֶת אַרְבַּעַת הַמִּינִים?",["בִּשְׂדֵה פְּרָא בְּלִי שׁוּם בְּדִיקָה","מֵעֵץ שֶׁל שָׁכֵן בְּלִי רְשׁוּת","בְּדוּכָן שֶׁיֵּשׁ בּוֹ הַשְׁגָּחַת כַּשְׁרוּת"],2,"רֹב הָאֲנָשִׁים קוֹנִים בְּדוּכָנִים עִם הַשְׁגָּחַת כַּשְׁרוּת, וְהַמַּשְׁגִּיחִים בּוֹדְקִים מַרְאֶה, חֲשַׁשׁ גֶּזֶל וְעָרְלָה, תְּרוּמוֹת וּמַעַשְׂרוֹת וְעוֹד.","פֶּרֶק פ״ו, הֲלָכָה ב׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["מָה רָאוּי שֶׁכָּל אָדָם יַעֲשֶׂה לִקְרַאת הַחַג?",["לִלְמֹד אֶת הִלְכוֹת אַרְבַּעַת הַמִּינִים הָעִקָּרִיּוֹת","לִקְנוֹת אֶת הַלּוּלָב הַגָּדוֹל בְּיוֹתֵר בְּלִי לִבְדֹּק","לִסְמֹךְ רַק עַל הַמַּרְאֶה וְלֹא לִשְׁאֹל אַף פַּעַם"],0,"רָאוּי שֶׁכָּל אָדָם יִלְמַד אֶת הַהֲלָכוֹת הָעִקָּרִיּוֹת, כְּדֵי שֶׁיֵּדַע לְהַבְחִין אִם נִפְסְלוּ, וּבְמִקְרֵה הַצֹּרֶךְ יִשְׁאַל תַּלְמִיד חָכָם.","פֶּרֶק פ״ו, הֲלָכָה ג׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["בְּאֵיזֶה לוּלָב שָׁמְרוּ כָּרָאוּי עַל הֶעָלֶה הַמֶּרְכָּזִי הָעֶלְיוֹן?",["לוּלָב שֶׁרֹב הֶעָלֶה הַמֶּרְכָּזִי שֶׁלּוֹ נִפְתַּח","לוּלָב שֶׁהֶעָלֶה הַמֶּרְכָּזִי שֶׁלּוֹ סָגוּר וְשָׁלֵם","לוּלָב שֶׁרֹאשׁ הֶעָלֶה הַמֶּרְכָּזִי שֶׁלּוֹ נֶחְתַּךְ"],1,"יֵשׁ לְהַקְפִּיד שֶׁהֶעָלֶה הַמֶּרְכָּזִי לֹא יִפָּתַח כְּלָל (וְלָכֵן נוֹהֲגִים לִקְשֹׁר אֶת הָעָלִים), וְשֶׁחֶלְקוֹ הָעֶלְיוֹן לֹא יִקָּטֵם.","פֶּרֶק פ״ו, הֲלָכוֹת ד׳-ה׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["אֵיזֶה לוּלָב טוֹב לְהַדֵּר וְלִקְנוֹת?",["לוּלָב עָקוּם לַצְּדָדִים כְּמוֹ מַגָּל","לוּלָב עָקוּם לַצַּד הָרָחוֹק מֵהַשִּׁדְרָה","לוּלָב יָשָׁר"],2,"בְּיָמֵינוּ יֵשׁ מִבְחָר גָּדוֹל, וְלָכֵן טוֹב לִקְנוֹת לוּלָב יָשָׁר. לוּלָב עָקוּם לַצְּדָדִים אוֹ לַצַּד הָרָחוֹק מֵהַשִּׁדְרָה עַד שֶׁנַּעֲשָׂה כְּמַגָּל – פָּסוּל.","פֶּרֶק פ״ו, הֲלָכָה ו׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["מָה הָאֹרֶךְ הַקָּטָן בְּיוֹתֵר שֶׁל שִׁדְרַת הַלּוּלָב?",["אַרְבָּעָה טְפָחִים","טֶפַח אֶחָד","חֲצִי טֶפַח"],0,"אֹרֶךְ שִׁדְרַת הַלּוּלָב צָרִיךְ לִהְיוֹת לְפָחוֹת אַרְבָּעָה טְפָחִים (32 ס״מ, וְיֵשׁ אוֹמְרִים 40 ס״מ).","פֶּרֶק פ״ו, הֲלָכָה ז׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["אֵיזֶה עָנָף הוּא הֲדַס עָבֹת כָּשֵׁר?",["שְׁנֵי עָלִים יַחַד וְהַשְּׁלִישִׁי בִּמְקוֹם אַחֵר","עָלִים דְּלִילִים שֶׁהֶעָנָף נִרְאֶה בֵּינֵיהֶם","שְׁלוֹשָׁה עָלִים בְּגֹבַהּ שָׁוֶה שֶׁמְּכַסִּים אֶת הֶעָנָף"],2,"הֲדַס עָבֹת הוּא מְשֻׁלָּשׁ: כָּל שְׁלוֹשָׁה עָלִים יוֹצְאִים בְּגֹבַהּ שָׁוֶה, וְהָעָלִים מְכַסִּים אֶת הֶעָנָף עַד הֶעָלִים שֶׁמֵּעֲלֵיהֶם.","פֶּרֶק פ״ו, הֲלָכוֹת ח׳-ט׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["נֶחְתַּךְ רֹאשׁוֹ שֶׁל הַהֲדַס. מָה דִּינוֹ?",["כָּשֵׁר בִּשְׁעַת הַדְּחָק","מְהֻדָּר בְּיוֹתֵר","צָרִיךְ לְהַדְבִּיק אֶת הָרֹאשׁ"],0,"אִם נִקְטַם רֹאשׁוֹ שֶׁל הַהֲדַס, הַדָּבָר שָׁנוּי בְּמַחְלֹקֶת, וּבִשְׁעַת הַדְּחָק הַהֲדַס כָּשֵׁר.","פֶּרֶק פ״ו, הֲלָכָה י׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["מָה הָאֹרֶךְ הַקָּטָן בְּיוֹתֵר שֶׁל הַהֲדַס?",["טֶפַח אֶחָד","שְׁלוֹשָׁה טְפָחִים","עֲשָׂרָה טְפָחִים"],1,"אֹרֶךְ הַהֲדַס לְפָחוֹת שְׁלוֹשָׁה טְפָחִים (24 ס״מ, וְיֵשׁ אוֹמְרִים 30 ס״מ). לְהִדּוּר – כָּל הַטְּפָחִים מְשֻׁלָּשִׁים, וּבְדִיעֲבַד מַסְפִּיק רֻבָּם.","פֶּרֶק פ״ו, הֲלָכָה י״ב","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["אֵיזֶה הֲדַס שָׁמְרוּ עָלָיו כָּרָאוּי?",["הֲדַס יָבֵשׁ וְחוּם","הֲדַס רַעֲנָן שֶׁעָלָיו לֹא נָשְׁרוּ","הֲדַס שֶׁעָלָיו נָשְׁרוּ בָּאֲגִידָה"],1,"הֲדַס יָבֵשׁ פָּסוּל, וְלָכֵן שׁוֹמְרִים אוֹתוֹ בִּתְנָאִים מַתְאִימִים; וּכְשֶׁאוֹגְדִים אֶת הַמִּינִים נִזְהָרִים שֶׁלֹּא יִנְשְׁרוּ מִמֶּנּוּ עָלִים.","פֶּרֶק פ״ו, הֲלָכוֹת י״א, י״ג","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["יוֹסִי צָרִיךְ עֲרָבוֹת לַחַג. מֵאֵיפֹה מֻתָּר לוֹ לְהָבִיא אוֹתָן?",["לִקְטֹף עֲרָבוֹת בַּגַּן הַצִּבּוּרִי בְּלִי לִשְׁאֹל","לִקְנוֹת עֲרָבוֹת מֵאָדָם נֶאֱמָן","לִקְטֹף מֵחֲצַר הַשָּׁכֵן כְּשֶׁהוּא אֵינוֹ בַּבַּיִת"],1,"הֲדַס וַעֲרָבָה גְּזוּלִים פְּסוּלִים, לָכֵן אֵין לִקְטֹף בְּלִי רְשׁוּת מְפֹרֶשֶׁת, וְאֵין לִקְנוֹת אֶלָּא מֵאָדָם נֶאֱמָן.","פֶּרֶק פ״ו, הֲלָכוֹת י״ד, י״ח","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["אֵיזֶה עָנָף מַתְאִים לְסִימָנֵי הָעֲרָבָה שֶׁנָּתְנוּ חֲכָמִים?",["עָלֶה עָגֹל וְגִבְעוֹל יָרֹק","עָלֶה מְשֻׁנָּן כְּמוֹ מַסּוֹר","עָלֶה אָרֹךְ, שָׂפָה חֲלָקָה וְקָנֶה אָדֹם"],2,"סִימָנֵי הָעֲרָבָה: עָלֶה מָשׁוּךְ כְּנַחַל (אָרֹךְ), פִּיהָ חָלָק, וְהַקָּנֶה שֶׁלָּהּ אָדֹם.","פֶּרֶק פ״ו, הֲלָכָה ט״ו","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["מָה הָאֹרֶךְ הַמִּינִימָלִי שֶׁל עֲרָבָה כְּשֵׁרָה?",["שְׁלוֹשָׁה טְפָחִים","טֶפַח אֶחָד","אֵין שִׁעוּר כְּלָל"],0,"אֹרֶךְ הָעֲרָבָה צָרִיךְ לִהְיוֹת לְפָחוֹת שְׁלוֹשָׁה טְפָחִים.","פֶּרֶק פ״ו, הֲלָכָה ט״ז","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["אֵיזוֹ עֲרָבָה כְּשֵׁרָה לַמִּצְוָה?",["עֲרָבָה יְבֵשָׁה","עֲרָבָה שֶׁנִּקְטַם רֹאשָׁהּ","עֲרָבָה רַעֲנַנָּה עִם רֹב עָלֶיהָ"],2,"עֲרָבָה שֶׁהִתְיַבְּשָׁה, שֶׁנָּשְׁרוּ רֹב עָלֶיהָ אוֹ שֶׁנִּקְטַם רֹאשָׁהּ – פְּסוּלָה.","פֶּרֶק פ״ו, הֲלָכָה י״ז","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["אֵיזֶה אֶתְרוֹג כְּדַאי לִקְנוֹת?",["אֶתְרוֹג עִם הֶכְשֵׁר שֶׁמֵּעִיד שֶׁאֵינוֹ מֻרְכָּב","אֶתְרוֹג מֵעֵץ שֶׁהֻרְכַּב עַל לִימוֹן","אֶתְרוֹג בְּלִי שׁוּם בְּדִיקָה מִכָּל דּוּכָן"],0,"לֹא כָּל אָדָם בָּקִי בְּדִינֵי הָאֶתְרוֹג, וּלְדַעַת רֹב הַפּוֹסְקִים אֶתְרוֹג מֻרְכָּב פָּסוּל – לָכֵן קוֹנִים עִם הֶכְשֵׁר.","פֶּרֶק פ״ו, הֲלָכוֹת י״ט, כ׳","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["אֵיזֶה אֶתְרוֹג קָטָן מִדַּי לַמִּצְוָה?",["אֶתְרוֹג גָּדוֹל שֶׁאוֹחֲזִים בִּשְׁתֵּי יָדַיִם","אֶתְרוֹג קָטָן מִבֵּיצָה","אֶתְרוֹג בְּגֹדֶל רָגִיל מֵהַשּׁוּק"],1,"גֹּדֶל הָאֶתְרוֹג צָרִיךְ לִהְיוֹת לְפָחוֹת כַּבֵּיצָה, וַאֲפִלּוּ אֶתְרוֹג גָּדוֹל מְאֹד כָּשֵׁר.","פֶּרֶק פ״ו, הֲלָכוֹת כ״א, כ״ב","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["אֶתְרוֹג שֶׁהַפִּטָּם שֶׁלּוֹ נָשַׁר כְּשֶׁהָיָה עוֹד קָטָן מְאֹד עַל הָעֵץ – מַה דִּינוֹ?",["פָּסוּל לְגַמְרֵי","כָּשֵׁר רַק בְּחֹל הַמּוֹעֵד","כָּשֵׁר לְכַתְּחִלָּה"],2,"בְּרֹב הָאֶתְרוֹגִים הַפִּטָּם מִתְיַבֵּשׁ וְנוֹשֵׁר כְּשֶׁהֵם קְטַנִּים מְאֹד, וְהֵם כְּשֵׁרִים לְכַתְּחִלָּה.","פֶּרֶק פ״ו, הֲלָכָה כ״ג","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["נִטַּל כָּל הָעֹקֶץ וְנֶחְסַר מְעַט מִבְּשַׂר הָאֶתְרוֹג. מָתַי הוּא פָּסוּל?",["בַּיּוֹם הָרִאשׁוֹן שֶׁל הַחַג","בְּכָל יְמֵי הַחַג","אַף פַּעַם"],0,"אִם נִטַּל כָּל הָעֹקֶץ וְנֶחְסַר מִבְּשַׂר הָאֶתְרוֹג – פָּסוּל בַּיּוֹם הָרִאשׁוֹן, וּבִשְׁאַר הַיָּמִים כָּשֵׁר.","פֶּרֶק פ״ו, הֲלָכָה כ״ד","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["אֶתְרוֹג נִפְגַּע מִקּוֹץ, וְלֹא בָּרוּר אִם נֶחְסַר מִמֶּנּוּ חֵלֶק. מַה דִּינוֹ בַּיּוֹם הָרִאשׁוֹן?",["פָּסוּל","כָּשֵׁר","צָרִיךְ לִזְרֹק אוֹתוֹ"],1,"אִם יֵשׁ סָפֵק אִם נֶחְסַר חֵלֶק מֵהָאֶתְרוֹג בִּגְלַל קוֹץ – הוּא כָּשֵׁר גַּם בַּיּוֹם הָרִאשׁוֹן.","פֶּרֶק פ״ו, הֲלָכָה כ״ה","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["אֵיזֶה אֶתְרוֹג כָּשֵׁר?",["אֶתְרוֹג שֶׁנִּקַּב וְנֶחְסַר, בַּיּוֹם הָרִאשׁוֹן","אֶתְרוֹג קָטָן מִכַּבֵּיצָה","אֶתְרוֹג עִם כְּתָמִים חוּמִים מִמַּגַּע עָלִים"],2,"כְּתָמִים צְהֻבִּים, אֲפֹרִים אוֹ חוּמִים (״בְּלָאטְלֶעךְ״) אֵינָם פּוֹסְלִים, וְהֵם נִגְרָמִים מִמַּגַּע עָלִים וַעֲנָפִים.","פֶּרֶק פ״ו, הֲלָכָה כ״ו","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["בִּזְמַן שֶׁאֵין בֵּית הַמִּקְדָּשׁ קַיָּם, בְּאֵיזֶה יוֹם שֶׁל סֻכּוֹת אֵין נוֹטְלִים לוּלָב?",["בְּיוֹם רִאשׁוֹן בַּשָּׁבוּעַ","בְּשַׁבָּת","בְּיוֹם שְׁלִישִׁי"],1,"רַבָּן יוֹחָנָן בֶּן זַכַּאי תִּקֵּן לִטֹּל לוּלָב כָּל שִׁבְעַת יְמֵי הַחַג זֵכֶר לַמִּקְדָּשׁ, אַךְ בְּשַׁבָּת אֵין נוֹטְלִים לוּלָב אֲפִלּוּ בַּיּוֹם הָרִאשׁוֹן.","פֶּרֶק פ״ז, הֲלָכָה א׳","נְטִילַת לוּלָב"],["עַל שֵׁם אֵיזֶה מִין נִקְרֵאת הַמִּצְוָה ״נְטִילַת לוּלָב״?",["הָאֶתְרוֹג","הָעֲרָבָה","הַלּוּלָב, כִּי הוּא הַגָּבוֹהַּ מִכֻּלָּם"],2,"הַלּוּלָב הוּא הַגָּבוֹהַּ מִבֵּין אַרְבַּעַת הַמִּינִים, וְלָכֵן הַמִּצְוָה וְהַבְּרָכָה נִקְרָאוֹת עַל שְׁמוֹ.","פֶּרֶק פ״ז, הֲלָכָה ב׳","נְטִילַת לוּלָב"],["כַּמָּה עַנְפֵי הֲדַס לוֹקְחִים לְפִי הַמִּנְהָג הַנָּפוֹץ?",["שְׁלוֹשָׁה","אֶחָד","שְׁנַיִם"],0,"הַמִּנְהָג הַנָּפוֹץ: לוּלָב אֶחָד, שְׁלוֹשָׁה עַנְפֵי הֲדַס, שְׁנֵי עַנְפֵי עֲרָבָה וְאֶתְרוֹג אֶחָד.","פֶּרֶק פ״ז, הֲלָכָה ג׳","נְטִילַת לוּלָב"],["מָתַי רָאוּי לֶאֱגֹד אֶת הַלּוּלָב עִם הַהֲדַסִּים וְהָעֲרָבוֹת?",["בְּאֶמְצַע הַהַלֵּל","לִפְנֵי כְּנִיסַת הַחַג","בְּמוֹצָאֵי הַחַג"],1,"רָאוּי לֶאֱגֹד לִפְנֵי כְּנִיסַת הַחַג, כְּדֵי שֶׁאֶפְשָׁר יִהְיֶה לִקְשֹׁר אוֹתָם הֵיטֵב.","פֶּרֶק פ״ז, הֲלָכָה ד׳","נְטִילַת לוּלָב"],["יֵשׁ נוֹהֲגִים לָשִׂים אֶת שְׁלֹשֶׁת הַהֲדַסִּים בְּצַד אֶחָד. בְּאֵיזֶה צַד?",["מִשְּׂמֹאל לַלּוּלָב","מִיָּמִין לַלּוּלָב","מֵעַל הַלּוּלָב"],1,"יֵשׁ נוֹהֲגִים לָשִׂים אֶת שְׁלֹשֶׁת הַהֲדַסִּים מִיָּמִין לַלּוּלָב וְאֶת שְׁתֵּי הָעֲרָבוֹת מִשְּׂמֹאל. וְיֵשׁ נוֹהֲגִים לְסַדֵּר אַחֶרֶת.","פֶּרֶק פ״ז, הֲלָכָה ה׳","נְטִילַת לוּלָב"],["בְּמָה נוֹהֲגִים לֶאֱגֹד אֶת הַמִּינִים? (וְיֵשׁ גַּם הַמְּחַבְּרִים בְּאוֹגְדָן)",["בַּעֲלֵי לוּלָב","בְּדֶבֶק","בְּמַסְמְרִים"],0,"נוֹהֲגִים לֶאֱגֹד בַּעֲלֵי לוּלָב, וּמֻתָּר גַּם בְּחוּט אַחֵר. מִי שֶׁמְּחַבֵּר בְּאוֹגְדָן (״קוֹיְשֶׁעקְלַךְ״) אֵינוֹ חַיָּב לִקְשֹׁר מַמָּשׁ.","פֶּרֶק פ״ז, הֲלָכוֹת ו׳-ח׳","נְטִילַת לוּלָב"],["שִׁדְרַת הַלּוּלָב צְרִיכָה לִהְיוֹת...",["נְמוּכָה מֵהַהֲדַסִּים","בְּדִיּוּק בְּגֹבַהּ הָעֲרָבוֹת","גְּבוֹהָה לְפָחוֹת טֶפַח מֵעַל הַהֲדַסִּים"],2,"יֵשׁ לְהַקְפִּיד שֶׁשִּׁדְרַת הַלּוּלָב תִּהְיֶה גְּבוֹהָה לְפָחוֹת טֶפַח (שְׁמוֹנָה ס״מ) מֵעַל הַהֲדַסִּים וְהָעֲרָבוֹת.","פֶּרֶק פ״ז, הֲלָכָה ז׳","נְטִילַת לוּלָב"],["מָתַי זְמַן נְטִילַת לוּלָב?",["בַּלַּיְלָה","בַּיּוֹם","רַק בַּחֲצוֹת"],1,"הַזְּמַן הוּא בַּיּוֹם, מֵהַזְּרִיחָה וְעַד הַשְּׁקִיעָה. מִי שֶׁיּוֹצֵא לַדֶּרֶךְ יָכוֹל לִטֹּל כְּבָר מֵעֲלוֹת הַשַּׁחַר.","פֶּרֶק פ״ז, הֲלָכוֹת ט׳-י׳","נְטִילַת לוּלָב"],["בְּאֵיזֶה יָד מַחְזִיקִים אֶת הַלּוּלָב הָאָגוּד?",["בְּיַד שְׂמֹאל","מַנִּיחִים עַל הַשֻּׁלְחָן","בְּיַד יָמִין"],2,"נוֹטְלִים אֶת הַלּוּלָב הָאָגוּד בְּיַד יָמִין, וְאֶת הָאֶתְרוֹג בְּיַד שְׂמֹאל. יֵשׁ הַמְּבָרְכִים בַּסֻּכָּה וְיֵשׁ בְּבֵית הַכְּנֶסֶת – כָּל אֶחָד כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק פ״ז, הֲלָכוֹת י״א-י״ב","נְטִילַת לוּלָב"],["בְּאֵיזֶה מָקוֹם מַחְזִיקִים אֶת הַלּוּלָב?",["בְּרֹאשׁ הַלּוּלָב, לְיַד הֶעָלִים","בַּמָּקוֹם שֶׁבּוֹ אֲגוּדִים הַמִּינִים","בִּקְצֵה הָעֲרָבוֹת בִּלְבַד"],1,"מַחְזִיקִים בַּמָּקוֹם שֶׁבּוֹ אֲגוּדִים הַלּוּלָב, הַהֲדַסִּים וְהָעֲרָבוֹת, כְּדֵי שֶׁיִּהְיוּ שְׁלֹשֶׁת הַמִּינִים בְּיַד הַנּוֹטֵל.","פֶּרֶק פ״ז, הֲלָכָה י״ג","נְטִילַת לוּלָב – חֵלֶק ב׳"],["אִטֵּר (שֶׁעוֹשֶׂה רֹב פְּעֻלּוֹתָיו בְּיַד שְׂמֹאל) רוֹצֶה לִטֹּל לוּלָב. מָה עָלָיו לַעֲשׂוֹת?",["לֹא לִטֹּל לוּלָב כְּלָל","לְהַחְזִיק אֶת שְׁנֵיהֶם בְּיָד אַחַת","לְבָרֵר אֶת מִנְהַג מִשְׁפַּחְתּוֹ וְלִנְהֹג בּוֹ"],2,"יֵשׁ אוֹמְרִים שֶׁאִטֵּר יַחְזִיק לוּלָב בִּשְׂמֹאל, וְיֵשׁ אוֹמְרִים בְּיָמִין. כָּל אִטֵּר יְבָרֵר אֶת מִנְהַג מִשְׁפַּחְתּוֹ וְיִנְהַג בּוֹ.","פֶּרֶק פ״ז, הֲלָכָה י״ד","נְטִילַת לוּלָב – חֵלֶק ב׳"],["מָתַי עִקַּר מִצְוַת הַלּוּלָב?",["בִּשְׁעַת אֲמִירַת הַהַלֵּל","בִּשְׁעַת הַסְּעוּדָה בַּסֻּכָּה","בִּשְׁעַת קְרִיאַת הַתּוֹרָה"],0,"בְּכָל יְמֵי חַג הַסֻּכּוֹת גּוֹמְרִים אֶת הַהַלֵּל, וְעִקַּר מִצְוַת הַלּוּלָב הוּא בִּשְׁעַת אֲמִירַת הַהַלֵּל.","פֶּרֶק פ״ז, הֲלָכָה ט״ו","נְטִילַת לוּלָב – חֵלֶק ב׳"],["בְּאֵיזֶה פָּסוּק בַּהַלֵּל מְנַעְנְעִים, וּמָתַי עוֹצְרִים?",["בְּכָל מִלָּה שֶׁל הַהַלֵּל, בְּלִי לַעֲצֹר","בְּ״הוֹדוּ לַה׳ כִּי טוֹב״, וְעוֹצְרִים בְּשֵׁם ה׳","רַק בְּסוֹף הַתְּפִלָּה, אַחֲרֵי עָלֵינוּ"],1,"מְנַעְנְעִים בְּ״הוֹדוּ לַה׳ כִּי טוֹב״ וּבְ״אָנָּא ה׳ הוֹשִׁיעָה נָּא״. כְּשֶׁמַּזְכִּירִים אֶת שֵׁם ה׳ לֹא מְנַעְנְעִים, כִּי צָרִיךְ לַעֲמֹד וּלְכַוֵּן.","פֶּרֶק פ״ז, הֲלָכוֹת ט״ז, כ״א","נְטִילַת לוּלָב – חֵלֶק ב׳"],["כֵּיצַד מַחְזִיקִים אֶת הָאֶתְרוֹג בִּזְמַן הַנִּעְנוּעִים?",["מַרְחִיקִים אוֹתוֹ מִן הַלּוּלָב","מַנִּיחִים אוֹתוֹ עַל הַשֻּׁלְחָן","מַצְמִידִים אוֹתוֹ לַלּוּלָב"],2,"צָרִיךְ לְהַצְמִיד אֶת הָאֶתְרוֹג לִשְׁאָר הַמִּינִים, לְהוֹלִיךְ קָדִימָה וּלְהַחְזִיר אֶל הַגּוּף – שָׁלוֹשׁ פְּעָמִים לְכָל כִּוּוּן.","פֶּרֶק פ״ז, הֲלָכוֹת י״ז, י״ט","נְטִילַת לוּלָב – חֵלֶק ב׳"],["לְפִי מִנְהַג הַסְּפָרַדִּים, לְאֵיזֶה כִּוּוּן מְנַעְנְעִים רִאשׁוֹן?",["דָּרוֹם","מִזְרָח","מַעֲרָב"],0,"לְפִי מִנְהַג הַסְּפָרַדִּים (עַל פִּי הָאֲרִ״י זַ״ל): דָּרוֹם, צָפוֹן, מִזְרָח, מַעְלָה, מַטָּה, מַעֲרָב.","פֶּרֶק פ״ז, הֲלָכָה י״ח","נְטִילַת לוּלָב – חֵלֶק ב׳"],["מָה זֶה ״לְכַסְכֵּס״ בַּלּוּלָב, כְּמִנְהַג הָאַשְׁכְּנַזִּים?",["לִדְפֹּק בַּלּוּלָב עַל הַשֻּׁלְחָן","לִיצֹר רַחַשׁ קַל בֶּעָלִים","לָשִׁיר בְּקוֹל רָם"],1,"לְכַסְכֵּס – לִיצֹר עַל יְדֵי הַנִּעְנוּעִים רַחַשׁ קַל בֶּעָלִים שֶׁבְּרֹאשׁ הַלּוּלָב.","פֶּרֶק פ״ז, הֲלָכָה כ׳","נְטִילַת לוּלָב – חֵלֶק ב׳"],["הַאִם נָשִׁים חַיָּבוֹת בְּמִצְוַת נְטִילַת לוּלָב?",["כֵּן, כְּמוֹ גְּבָרִים","אָסוּר לָהֶן לִגְעֹת בַּלּוּלָב","פְּטוּרוֹת, אַךְ אִם נוֹטְלוֹת מְקַבְּלוֹת שָׂכָר"],2,"נָשִׁים פְּטוּרוֹת כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ, אַךְ אִם נוֹטְלוֹת – מְקַבְּלוֹת שָׂכָר, וּלְמִנְהַג הָאַשְׁכְּנַזִּים אַף רַשָּׁאִיּוֹת לְבָרֵךְ.","פֶּרֶק פ״ז, הֲלָכָה כ״ב","נְטִילַת לוּלָב – חֵלֶק ב׳"],["יֶלֶד שֶׁכְּבָר הוֹלֵךְ לְהִתְפַּלֵּל בְּבֵית הַכְּנֶסֶת – מָה נָכוֹן שֶׁאָבִיו יַעֲשֶׂה?",["יִקְנֶה לוֹ אַרְבָּעָה מִינִים מִשֶּׁלּוֹ","יַשְׁאִיר אוֹתוֹ בַּבַּיִת","יִתֵּן לוֹ רַק לְהִסְתַּכֵּל"],0,"אָבִיו חַיָּב לְחַנְּכוֹ, וְנָכוֹן שֶׁיִּקְנֶה לוֹ אַרְבָּעָה מִינִים מִשֶּׁלּוֹ כְּדֵי שֶׁיּוּכַל לְנַעְנֵעַ בַּמְּקוֹמוֹת שֶׁתִּקְּנוּ חֲכָמִים.","פֶּרֶק פ״ז, הֲלָכָה כ״ג","נְטִילַת לוּלָב – חֵלֶק ב׳"],["מָה מְנַסְּכִים עַל הַמִּזְבֵּחַ רַק בִּימֵי חַג הַסֻּכּוֹת?",["מַיִם","שֶׁמֶן","חָלָב"],0,"בְּכָל יוֹם מְנַסְּכִים יַיִן, וּבְחַג הַסֻּכּוֹת מְנַסְּכִים גַּם מַיִם, כְּדֵי שֶׁיִּתְבָּרְכוּ גִּשְׁמֵי הַשָּׁנָה.","פֶּרֶק פ״ח, הֲלָכָה א׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["לְאָן יָצְאוּ בְּתַהֲלוּכָה בַּבֹּקֶר כְּדֵי לִשְׁאֹב מַיִם?",["הַיָּם הַגָּדוֹל","מַעְיַן הַשִּׁילוֹחַ","נְהַר הַיַּרְדֵּן"],1,"בַּבֹּקֶר הָיוּ יוֹצְאִים בְּתַהֲלוּכָה לְמַעְיַן הַשִּׁילוֹחַ וְשׁוֹאֲבִים מִשָּׁם מַיִם לְנִסּוּךְ הַמַּיִם.","פֶּרֶק פ״ח, הֲלָכָה ב׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["מָה נָהֲגוּ לַעֲשׂוֹת בְּלֵיל הוֹשַׁעְנָא רַבָּה?",["לְהַדְלִיק נֵרוֹת חֲנֻכָּה","לִישֹׁן מֻקְדָּם","לִלְמֹד תּוֹרָה"],2,"נָהֲגוּ לִלְמֹד בְּלַיְלָה זֶה ״תִּקּוּן לֵיל הוֹשַׁעְנָא רַבָּה״, וְיֵשׁ מְקַיְּמִים שִׁעוּרֵי תּוֹרָה.","פֶּרֶק פ״ח, הֲלָכָה ג׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["אֵילוּ עֲנָפִים גְּדוֹלִים זָקְפוּ בְּצִדֵּי הַמִּזְבֵּחַ?",["עַנְפֵי זַיִת","עַנְפֵי עֲרָבָה","עַנְפֵי דֶּקֶל"],1,"בְּכָל שִׁבְעַת יְמֵי הַחַג הֵבִיאוּ עַנְפֵי עֲרָבָה גְּדוֹלִים וְזָקְפוּ אוֹתָם בְּצִדֵּי הַמִּזְבֵּחַ.","פֶּרֶק פ״ח, הֲלָכָה ד׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["מָה מַקִּיפִים הַיּוֹם בְּבֵית הַכְּנֶסֶת עִם אַרְבַּעַת הַמִּינִים?",["אֶת הַסֻּכָּה","אֶת הֶחָצֵר","אֶת הַבִּימָה"],2,"כְּשֶׁאֵין בֵּית הַמִּקְדָּשׁ קַיָּם מַקִּיפִים אֶת בִּימַת בֵּית הַכְּנֶסֶת וְאוֹמְרִים הוֹשַׁעְנוֹת, זֵכֶר לַמִּקְדָּשׁ.","פֶּרֶק פ״ח, הֲלָכָה ה׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["עַל מָה חוֹבְטִים אֶת הָעֲרָבָה בְּהוֹשַׁעְנָא רַבָּה?",["עַל הַקַּרְקַע","עַל הַשֻּׁלְחָן","עַל הַקִּיר"],0,"הַנְּבִיאִים הִנְהִיגוּ לַחְבֹּט אֶת הָעֲרָבָה בַּקַּרְקַע, וְנוֹהֲגִים כָּךְ גַּם הַיּוֹם בְּלִי בְּרָכָה.","פֶּרֶק פ״ח, הֲלָכָה ו׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["כַּמָּה עַנְפֵי עֲרָבָה לוֹקְחִים לַחֲבָטָה?",["שְׁנַיִם","חֲמִשָּׁה","עֲשָׂרָה"],1,"לוֹקְחִים חֲמִשָּׁה עַנְפֵי עֲרָבָה וְחוֹבְטִים אוֹתָם חָמֵשׁ פְּעָמִים עַל הַקַּרְקַע.","פֶּרֶק פ״ח, הֲלָכָה ז׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["אֵיךְ נוֹהֲגִים בָּעֲרָבוֹת וּבָאַרְבָּעָה מִינִים אַחֲרֵי הוֹשַׁעְנָא רַבָּה?",["זוֹרְקִים לַפַּח","מְשַׂחֲקִים בָּהֶם","שׁוֹמְרִים בְּכָבוֹד"],2,"נוֹהֲגִים בָּהֶם בְּצוּרָה מְכֻבֶּדֶת וְלֹא מְזַלְזְלִים בָּהֶם, כִּי נֶעֶשְׂתָה בָּהֶם מִצְוָה.","פֶּרֶק פ״ח, הֲלָכָה ח׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["בְּאֵיזוֹ סֻכָּה מִתְפַּלְּלִים לָשֶׁבֶת כְּשֶׁיּוֹצְאִים מִן הַסֻּכָּה בַּפַּעַם הָאַחֲרוֹנָה?",["סֻכָּה שֶׁל לִוְיָתָן","סֻכָּה עַל הַגַּג","סֻכָּה בַּמִּדְבָּר"],0,"אוֹמְרִים: ״יְהִי רָצוֹן שֶׁנִּזְכֶּה לֵישֵׁב בְּסֻכָּה שֶׁל לִוְיָתָן״.","פֶּרֶק פ״ח, הֲלָכָה ט׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["הֵיכָן אוֹכְלִים אֶת סְעוּדַת שְׁמִינִי עֲצֶרֶת?",["רַק בְּתוֹךְ הַסֻּכָּה","בַּבַּיִת, וְלֹא בַּסֻּכָּה","בַּחֲצַר בֵּית הַכְּנֶסֶת"],1,"שְׁמִינִי עֲצֶרֶת הוּא רֶגֶל בִּפְנֵי עַצְמוֹ, וְלָכֵן אֵין יוֹשְׁבִים בּוֹ בַּסֻּכָּה.","פֶּרֶק פ״ט, הֲלָכָה א׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָה מְסַיְּמִים בִּשְׁמִינִי עֲצֶרֶת וּמַתְחִילִים מֵחָדָשׁ?",["סֵפֶר תְּהִלִּים","מַסֶּכֶת בְּרָכוֹת","קְרִיאַת הַתּוֹרָה"],2,"חֲכָמִים תִּקְּנוּ לְסַיֵּם בִּשְׁמִינִי עֲצֶרֶת אֶת קְרִיאַת הַתּוֹרָה וּלְהַתְחִיל מֵחָדָשׁ, וְלָכֵן הוּא נִקְרָא ״שִׂמְחַת תּוֹרָה״.","פֶּרֶק פ״ט, הֲלָכָה ב׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["בְּאֵיזֶה מֵהֵם מַזְכִּירִים ״יוֹם שְׁמִינִי עֲצֶרֶת״ לְפִי הַהֲלָכָה?",["בַּקִּדּוּשׁ עַל הַכּוֹס","בְּבִרְכַּת הַלְּבָנָה","בִּקְרִיאַת שְׁמַע שֶׁעַל הַמִּטָּה"],0,"בַּתְּפִלּוֹת, בַּקִּדּוּשׁ וּבְבִרְכַּת הַמָּזוֹן מַזְכִּירִים אֶת יוֹם שְׁמִינִי עֲצֶרֶת.","פֶּרֶק פ״ט, הֲלָכָה ג׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["אֵיזוֹ בְּרָכָה מוֹסִיפִים בַּקִּדּוּשׁ שֶׁל שְׁמִינִי עֲצֶרֶת?",["לֵישֵׁב בַּסֻּכָּה","בּוֹרֵא מְאוֹרֵי הָאֵשׁ","שֶׁהֶחֱיָנוּ"],2,"מוֹסִיפִים ״שֶׁהֶחֱיָנוּ״ מִפְּנֵי שֶׁשְּׁמִינִי עֲצֶרֶת הוּא רֶגֶל בִּפְנֵי עַצְמוֹ.","פֶּרֶק פ״ט, הֲלָכָה ד׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָה מַקִּיפִים בַּהַקָּפוֹת?",["אֶת הַסֻּכָּה עִם לוּלָב","אֶת הַתֵּבָה עִם סִפְרֵי תּוֹרָה","אֶת אֲרוֹן הַסְּפָרִים עִם סִדּוּרִים"],1,"נָהֲגוּ לְהַקִּיף אֶת הַתֵּבָה עִם סִפְרֵי תּוֹרָה.","פֶּרֶק פ״ט, הֲלָכָה ה׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָה עוֹשִׂים עִם יְלָדִים שֶׁעוֹד לֹא יוֹדְעִים לְבָרֵךְ?",["מַכְנִיסִים אוֹתָם מִתַּחַת לַטַּלִּית","שׁוֹלְחִים אוֹתָם הַבַּיְתָה","נוֹתְנִים לָהֶם סֻכָּרִיּוֹת בִּלְבַד"],0,"אֶת הַיְּלָדִים שֶׁאֵינָם יוֹדְעִים לְבָרֵךְ מַכְנִיסִים מִתַּחַת לַטַּלִּית, וּמְבָרְכִים אוֹתָם בִּפְסוּקִים.","פֶּרֶק פ״ט, הֲלָכָה ו׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מִי עוֹלֶה לַתּוֹרָה מִיָּד אַחֲרֵי ״חֲתַן תּוֹרָה״?",["הַחַזָּן","בַּר הַמִּצְוָה","חֲתַן בְּרֵאשִׁית"],2,"מִיָּד אַחֲרֵי חֲתַן תּוֹרָה קוֹרְאִים לַ״חֲתַן בְּרֵאשִׁית״ וּמַתְחִילִים אֶת הַתּוֹרָה מֵחָדָשׁ.","פֶּרֶק פ״ט, הֲלָכָה ז׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָה מַתְחִילִים לוֹמַר בְּמוּסָף שֶׁל שְׁמִינִי עֲצֶרֶת?",["הַלֵּל הַגָּדוֹל","מַשִּׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם","תְּקִיעוֹת שׁוֹפָר"],1,"בְּמוּסָף שֶׁל שְׁמִינִי עֲצֶרֶת מַתְחִילִים לוֹמַר ״מַשִּׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם״.","פֶּרֶק פ״ט, הֲלָכָה ח׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָתַי עוֹרְכִים ״הַקָּפוֹת שְׁנִיּוֹת״?",["בְּעֶרֶב הַחַג","בְּמוֹצָאֵי הַחַג","בְּחֹל הַמּוֹעֵד"],1,"בְּמוֹצָאֵי הַחַג עוֹרְכִים הַקָּפוֹת שְׁנִיּוֹת בְּשִׁירָה וּבִכְלֵי נְגִינָה.","פֶּרֶק פ״ט, הֲלָכָה ט׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מִי גָּבְרוּ עַל הַיְּוָנִים וְהוֹשִׁיעוּ אֶת יִשְׂרָאֵל?",["חַיָּלֵי רוֹמִי","בְּנֵי חַשְׁמוֹנַאי הַכֹּהֲנִים","מַלְכֵי בָּבֶל"],1,"מַלְכֵי יָוָן גָּזְרוּ גְּזֵרוֹת עַל יִשְׂרָאֵל, וּבְנֵי חַשְׁמוֹנַאי, הַכֹּהֲנִים הַגְּדוֹלִים, גָּבְרוּ עֲלֵיהֶם וְהוֹשִׁיעוּ אֶת יִשְׂרָאֵל.","פֶּרֶק צ׳, הֲלָכָה א׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["מָה מָצְאוּ בַּמִּקְדָּשׁ כְּשֶׁנִּכְנְסוּ לַהֵיכָל?",["פַּךְ אֶחָד שֶׁל שֶׁמֶן טָהוֹר","חָבִית גְּדוֹלָה מְלֵאָה שֶׁמֶן","סַל מָלֵא נֵרוֹת שַׁעֲוָה"],0,"מָצְאוּ רַק פַּךְ אֶחָד שֶׁהִסְפִּיק לְיוֹם אֶחָד, וְנַעֲשָׂה נֵס וְהִדְלִיקוּ מִמֶּנּוּ שְׁמוֹנָה יָמִים.","פֶּרֶק צ׳, הֲלָכָה ב׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["לָמָּה צָרִיךְ לְהַקְפִּיד מְאֹד בְּמִצְוַת נֵר חֲנֻכָּה?",["כְּדֵי שֶׁהַבַּיִת יִהְיֶה מוּאָר","כְּדֵי לְחַמֵּם אֶת הַבַּיִת","כְּדֵי לְפַרְסֵם אֶת הַנֵּס"],2,"מִצְוַת נֵר חֲנֻכָּה חֲבִיבָה מְאֹד, וּמַקְפִּידִים בָּהּ כְּדֵי לְפַרְסֵם אֶת הַנֵּס וּלְהוֹדוֹת לָאֵ-ל.","פֶּרֶק צ׳, הֲלָכָה ג׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["מָתַי עִקַּר מִצְוַת הַדְלָקַת נֵר חֲנֻכָּה?",["בַּבֹּקֶר","בִּתְחִלַּת הַלַּיְלָה","בַּצָּהֳרַיִם"],1,"עִקַּר הַמִּצְוָה לְהַדְלִיק בִּתְחִלַּת הַלַּיְלָה: יֵשׁ נוֹהֲגִים בְּצֵאת הַכּוֹכָבִים, וְיֵשׁ אַשְׁכְּנַזִּים שֶׁנּוֹהֲגִים סָמוּךְ לַשְּׁקִיעָה.","פֶּרֶק צ׳, הֲלָכָה ד׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["כַּמָּה זְמַן צְרִיכִים הַנֵּרוֹת לִדְלֹק לְכָל הַפָּחוֹת?",["דַּקָּה אַחַת","יוֹם שָׁלֵם","חֲצִי שָׁעָה"],2,"שָׂמִים שֶׁמֶן שֶׁיַּסְפִּיק לַחֲצִי שָׁעָה אַחַר צֵאת הַכּוֹכָבִים. וְהַמַּדְלִיק מְאֻחָר יַדְלִיק כְּשֶׁבְּנֵי הַבַּיִת מְקֻבָּצִים יַחַד.","פֶּרֶק צ׳, הֲלָכוֹת ה׳-ו׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["אַבָּא חָזַר מְאֻחָר, וּשְׁנַיִם מִבְּנֵי הַבַּיִת עֲדַיִן עֵרִים. מָה יַעֲשֶׂה?",["יַדְלִיק בִּבְרָכָה","לֹא יַדְלִיק כְּלָל","יַדְלִיק רַק בַּבֹּקֶר"],0,"אִם שְׁנַיִם מִבְּנֵי הַבַּיִת עֵרִים, מַדְלִיק בִּבְרָכָה גַּם בְּשָׁעָה מְאֻחֶרֶת. וּבִשְׁעַת הַצֹּרֶךְ אֶפְשָׁר לְהַקְדִּים מִפְּלַג הַמִּנְחָה.","פֶּרֶק צ׳, הֲלָכוֹת ז׳-ח׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["בְּאֵיזֶה צַד שֶׁל הַפֶּתַח מַנִּיחִים אֶת הַחֲנֻכִּיָּה?",["מִצַּד יָמִין, עִם הַמְּזוּזָה","מִצַּד שְׂמֹאל, מוּל הַמְּזוּזָה","בְּתוֹךְ הַמִּטְבָּח"],1,"מַנִּיחִים לְיַד הַפֶּתַח מִצַּד שְׂמֹאל, מְזוּזָה מִיָּמִין וְנֵר חֲנֻכָּה מִשְּׂמֹאל. כְּדֵי שֶׁלֹּא יִכְבּוּ, שָׂמִים אוֹתָם בְּקֻפְסַת זְכוּכִית.","פֶּרֶק צ׳, הֲלָכוֹת ט׳-י׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["יוֹסִי גָּר בְּקוֹמָה עֶלְיוֹנָה, וְאֵין לוֹ פֶּתַח לָרְחוֹב. אֵיפֹה יַנִּיחַ אֶת הַנֵּרוֹת?",["בַּחֲדַר הַשֵּׁנָה","בַּמַּרְתֵּף","בְּחַלּוֹן הַפּוֹנֶה לָרְחוֹב"],2,"מִי שֶׁגָּר בַּעֲלִיָּה מַנִּיחַ בְּחַלּוֹן אוֹ בְּמִרְפֶּסֶת הַפּוֹנִים לָרְחוֹב. בְּפֶתַח רָגִיל מַנִּיחִים מֵעַל שְׁלוֹשָׁה טְפָחִים וּפָחוֹת מֵעֲשָׂרָה.","פֶּרֶק צ׳, הֲלָכוֹת י״א-י״ב","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["בִּשְׁעַת סַכָּנָה, אֵיפֹה מַנִּיחִים אֶת נֵרוֹת הַחֲנֻכָּה?",["עַל הַשֻּׁלְחָן בְּתוֹךְ הַבַּיִת","עַל הַגַּג","בָּרְחוֹב"],0,"בִּשְׁעַת סַכָּנָה מַנִּיחִים אֶת הַנֵּרוֹת עַל הַשֻּׁלְחָן, וּמְפַרְסְמִים אֶת הַנֵּס לִבְנֵי הַבַּיִת.","פֶּרֶק צ׳, הֲלָכָה י״ג","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["לְפִי מִנְהַג הַסְּפָרַדִּים, מִי יָכוֹל לְהַדְלִיק אֶת הַשַּׁמָּשׁ?",["רַק בַּעַל הַבַּיִת","אֲפִלּוּ יֶלֶד קָטָן","אַף אֶחָד"],1,"בַּעַל הַבַּיִת מַדְלִיק אֶת נֵר הַחִיּוּב, הַיְּלָדִים בְּגִיל חִנּוּךְ אֶת שְׁאָר הַנֵּרוֹת, וְאֶת הַשַּׁמָּשׁ אֲפִלּוּ יְלָדִים קְטַנִּים. אֵצֶל הָאַשְׁכְּנַזִּים כָּל אֶחָד מַדְלִיק בְּעַצְמוֹ.","פֶּרֶק צ׳, הֲלָכוֹת י״ד-ט״ו","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["מָתַי מְבָרְכִים אֶת בִּרְכוֹת נֵר חֲנֻכָּה?",["לִפְנֵי שֶׁמַּדְלִיקִים אֶת הַנֵּרוֹת","אַחֲרֵי שֶׁכָּל הַנֵּרוֹת כְּבָר דּוֹלְקִים","רַק כְּשֶׁהַנֵּרוֹת כָּבִים"],0,"עַל כָּל הַמִּצְווֹת מְבָרְכִים ״עוֹבֵר לַעֲשִׂיָּתָן״ – לִפְנֵי הָעֲשִׂיָּה. וּמִי שֶׁשָּׁכַח ״שֶׁהֶחֱיָנוּ״ בַּלַּיְלָה הָרִאשׁוֹן – יְבָרֵךְ בַּלַּיְלָה הַשֵּׁנִי אוֹ בְּכָל לַיְלָה שֶׁיִּזָּכֵר.","פֶּרֶק צ׳, הֲלָכוֹת ט״ז–י״ז","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["אֵיזֶה נֵר מַדְלִיקִים בַּלַּיְלָה הָרִאשׁוֹן שֶׁל חֲנֻכָּה?",["הַנֵּר הַשְּׂמָאלִי בְּיוֹתֵר","הַנֵּר הַיְּמָנִי בְּיוֹתֵר","הַנֵּר הָאֶמְצָעִי"],1,"בַּלַּיְלָה הָרִאשׁוֹן מַדְלִיקִים אֶת הַנֵּר הַיְּמָנִי בְּיוֹתֵר, וּבְכָל לַיְלָה מוֹסִיפִים נֵר מִשְּׂמֹאלוֹ וּמַתְחִילִים מִמֶּנּוּ, כְּדֵי שֶׁהַמַּדְלִיק יִפְנֶה יָמִינָה.","פֶּרֶק צ׳, הֲלָכָה י״ח","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["מִי חַיָּב בְּהַדְלָקַת נֵר חֲנֻכָּה?",["רַק גְּבָרִים","גַּם נָשִׁים, כִּי אַף הֵן הָיוּ בְּאוֹתוֹ הַנֵּס","רַק יְלָדִים קְטַנִּים"],1,"אַף שֶׁזּוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ, נָשִׁים חַיָּבוֹת בְּנֵר חֲנֻכָּה, שֶׁאַף הֵן הָיוּ בְּאוֹתוֹ הַנֵּס. לָכֵן אִשָּׁה יְכוֹלָה לְהַדְלִיק וּלְהוֹצִיא יְדֵי חוֹבָה אֶת בַּעֲלָהּ וִילָדֶיהָ.","פֶּרֶק צ׳, הֲלָכָה י״ט","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["מָה נוֹהֲגוֹת הַנָּשִׁים בִּזְמַן שֶׁהַנֵּרוֹת דּוֹלְקִים?",["מְכַבְּסוֹת וְתוֹפְרוֹת כָּרָגִיל","מְזִיזוֹת אֶת הַחֲנֻכִּיָּה לְמָקוֹם אַחֵר","לֹא עוֹשׂוֹת מְלָאכָה כַּחֲצִי שָׁעָה"],2,"הַנָּשִׁים נוֹהֲגוֹת שֶׁלֹּא לַעֲשׂוֹת מְלָאכָה בְּעוֹד הַנֵּרוֹת דּוֹלְקִים, וְיֵשׁ אוֹמְרִים שֶׁגַּם אֲנָשִׁים. הַזְּמַן הוּא חֲצִי שָׁעָה.","פֶּרֶק צ׳, הֲלָכָה כ׳","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["לְפִי מִנְהַג הָאַשְׁכְּנַזִּים, מָה עוֹשֶׂה יֶלֶד שֶׁהִגִּיעַ לְגִיל חִנּוּךְ?",["מַדְלִיק וּמְבָרֵךְ כְּכָל בְּנֵי הַבַּיִת","רַק מִסְתַּכֵּל בַּנֵּרוֹת","מוֹצִיא אֶת הַגְּדוֹלִים יְדֵי חוֹבָה"],0,"לְפִי מִנְהַג הָאַשְׁכְּנַזִּים כָּל אֶחָד מַדְלִיק לְעַצְמוֹ, וְקָטָן בְּגִיל חִנּוּךְ מַדְלִיק וּמְבָרֵךְ, אֲבָל אֵינוֹ מוֹצִיא אֶת הַגְּדוֹלִים.","פֶּרֶק צ׳, הֲלָכָה כ״א","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["אֵיפֹה מַדְלִיקִים אֶת נֵרוֹת הַחֲנֻכָּה?",["לְיַד הַמִּטָּה, וְאָז מַעֲבִירִים לַחַלּוֹן","בַּמָּקוֹם שֶׁבּוֹ הֵם מֻנָּחִים","בַּמִּטְבָּח, וְאָז מַזִּיזִים לַפֶּתַח"],1,"מַדְלִיקִים בַּמָּקוֹם שֶׁבּוֹ הַנֵּרוֹת מֻנָּחִים וְאֵין לַהֲזִיזָם אַחַר כָּךְ. וְאִם בַּעַל הַבַּיִת חוֹלֶה בְּמִטָּתוֹ – יְמַנֶּה שָׁלִיחַ שֶׁיַּדְלִיק בִּמְקוֹם הַנָּחָתָם.","פֶּרֶק צ׳, הֲלָכוֹת כ״ב–כ״ג","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["בְּמָה מִצְוָה מִן הַמֻּבְחָר לְהַדְלִיק נֵר חֲנֻכָּה?",["נוּרָה חַשְׁמַלִּית","פָּנָס עַל סוֹלְלוֹת","שֶׁמֶן זַיִת"],2,"מִצְוָה מִן הַמֻּבְחָר בְּשֶׁמֶן זַיִת, וְגַם שְׁאָר שְׁמָנִים וּנְרוֹת שַׁעֲוָה כְּשֵׁרִים. בְּנֵרוֹת חַשְׁמַלִּיִּים אֵין יוֹצְאִים יְדֵי חוֹבָה.","פֶּרֶק צ׳, הֲלָכוֹת כ״ד–כ״ה","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["לָמָּה מַדְלִיקִים נֵר נוֹסָף שֶׁנִּקְרָא שַׁמָּשׁ?",["כְּדֵי שֶׁאִם יִשְׁתַּמְּשׁוּ בָּאוֹר בְּטָעוּת – יִהְיֶה זֶה לְאוֹרוֹ","כְּדֵי שֶׁהַחֲנֻכִּיָּה תִּהְיֶה יָפָה יוֹתֵר","כְּדֵי לִלְמֹד תּוֹרָה לְאוֹר כָּל הַנֵּרוֹת"],0,"אָסוּר לְהִשְׁתַּמֵּשׁ בְּאוֹר נֵרוֹת חֲנֻכָּה, אֲפִלּוּ לְלִמּוּד תּוֹרָה. הַשַּׁמָּשׁ מֻנָּח רָחוֹק מֵהֶם אוֹ בְּגֹבַהּ אַחֵר, וְאִם יִשְׁתַּמְּשׁוּ בָּאוֹר בְּטָעוּת – זֶה לְאוֹרוֹ.","פֶּרֶק צ׳, הֲלָכָה כ״ו","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["הַנֵּרוֹת כָּבוּ כִּי הִדְלִיקוּ אוֹתָם בְּמָקוֹם שֶׁיֵּשׁ בּוֹ רוּחַ. מָה עוֹשִׂים?",["לֹא צָרִיךְ לַעֲשׂוֹת דָּבָר","חוֹזְרִים וּמַדְלִיקִים בְּמָקוֹם שֶׁאֵין בּוֹ רוּחַ","מַדְלִיקִים לְמָחֳרָת פַּעֲמַיִם"],1,"מִי שֶׁהִדְלִיק בְּמָקוֹם שֶׁהָרוּחַ מְצוּיָה וְכָבוּ – חוֹזֵר וּמַדְלִיק בְּמָקוֹם מוּגָן, בְּלִי בְּרָכָה, כִּי כְּבָר מֵרֹאשׁ הָיָה בָּרוּר שֶׁלֹּא יִדְלְקוּ חֲצִי שָׁעָה.","פֶּרֶק צ׳, הֲלָכָה כ״ז","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["אֵיפֹה מַנִּיחִים אֶת נֵרוֹת הַחֲנֻכָּה בְּבֵית הַכְּנֶסֶת?",["לְיַד דֶּלֶת הַכְּנִיסָה","בַּקִּיר הַצְּפוֹנִי","בַּקִּיר הַדְּרוֹמִי"],2,"בְּבֵית הַכְּנֶסֶת מַנִּיחִים אֶת הַנֵּרוֹת בַּקִּיר הַדְּרוֹמִי כְּמוֹ הַמְּנוֹרָה בַּמִּקְדָּשׁ. מַדְלִיקִים בֵּין מִנְחָה לְעַרְבִית בִּבְרָכָה, וּבִירוּשָׁלַיִם גַּם בַּבֹּקֶר בְּלִי בְּרָכָה. וְצָרִיךְ לְהַדְלִיק שׁוּב בַּבַּיִת.","פֶּרֶק צ׳, הֲלָכוֹת כ״ח–ל׳","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["בְּבֵית הַכְּנֶסֶת מַדְלִיקִים נֵרוֹת חֲנֻכָּה. מָתַי מְבָרְכִים עַל הַהַדְלָקָה?",["כְּשֶׁיֵּשׁ רַק שְׁנֵי אֲנָשִׁים","רַק אִם יֵשׁ שָׁם מִנְיָן","אַף פַּעַם לֹא מְבָרְכִים"],1,"מְבָרְכִים עַל הַדְלָקַת הַנֵּרוֹת בְּבֵית הַכְּנֶסֶת רַק אִם יֵשׁ שָׁם מִנְיָן.","פֶּרֶק צ׳, הֲלָכָה ל״א","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["בְּעֶרֶב שַׁבָּת מַדְלִיקִים נֵר חֲנֻכָּה לִפְנֵי נֵרוֹת שַׁבָּת. וּבְמוֹצָאֵי שַׁבָּת בַּבַּיִת – מָה עוֹשִׂים קֹדֶם?",["מַבְדִּילִים, וְאַחַר כָּךְ מַדְלִיקִים","מַדְלִיקִים, וְאַחַר כָּךְ מַבְדִּילִים","מַבְדִּילִים עַל נֵר הַחֲנֻכָּה"],0,"בְּעֶרֶב שַׁבָּת מַדְלִיקִים נֵר חֲנֻכָּה וְאַחֲרָיו נֵרוֹת שַׁבָּת, עִם הַרְבֵּה שֶׁמֶן שֶׁיִּדְלֹק עַד חֲצִי שָׁעָה אַחֲרֵי צֵאת הַכּוֹכָבִים. בְּמוֹצָאֵי שַׁבָּת בַּבַּיִת מַבְדִּילִים תְּחִלָּה וְאַחַר כָּךְ מַדְלִיקִים. אָסוּר לְהַבְדִּיל עַל נֵר חֲנֻכָּה, כִּי אָסוּר לֵהָנוֹת מֵאוֹרוֹ.","פֶּרֶק צ׳, הֲלָכָה ל״ב-ל״ג","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["אַבָּא נָסַע וְאֵינוֹ בַּבַּיִת בַּחֲנֻכָּה, וְאִמָּא נִמְצֵאת בַּבַּיִת. מָה הַדִּין?",["אַבָּא חַיָּב לַחֲזֹר הַבַּיְתָה","לֹא מַדְלִיקִים בַּבַּיִת בִּכְלָל","אִמָּא מַדְלִיקָה, וְאַבָּא יוֹצֵא בָּזֶה"],2,"אָדָם נָשׂוּי שֶׁאֵינוֹ בְּבֵיתוֹ וְאִשְׁתּוֹ בַּבַּיִת – הָאִשָּׁה מַדְלִיקָה וְהוּא יוֹצֵא בָּזֶה יְדֵי חוֹבָתוֹ.","פֶּרֶק צ׳, הֲלָכָה ל״ד","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["אִישׁ שֶׁגָּר לְבַדּוֹ מִתְאָרֵחַ בְּבֵית מָלוֹן, וְאָסוּר לְהַדְלִיק שָׁם בַּחֲדָרִים. מָה יַעֲשֶׂה?",["פָּטוּר מֵהַדְלָקָה","יַדְלִיק בַּחֲדַר הָאֹכֶל בִּבְרָכָה","יַדְלִיק בַּחֲדַר הַשֵּׁנָה בְּסֵתֶר"],1,"בְּמָקוֹם שֶׁאֵין מַדְלִיקִים בּוֹ נֵרוֹת, כְּמוֹ מָלוֹן – חַיָּב לְהַדְלִיק. אִם אָסוּר בַּחֲדָרִים, יַדְלִיק בַּחֲדַר הָאֹכֶל אוֹ בַּמְּבוֹאָה בִּבְרָכָה. וְאוֹרֵחַ בְּבַיִת פְּרָטִי שֶׁאֵינוֹ יָכוֹל לְהַדְלִיק – נוֹתֵן לְבַעַל הַבַּיִת מְעַט כֶּסֶף וְנַעֲשֶׂה שֻׁתָּף בַּנֵּרוֹת.","פֶּרֶק צ׳, הֲלָכָה ל״ה-ל״ו","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["אֵיפֹה מוֹסִיפִים ״עַל הַנִּסִּים״ בַּתְּפִלָּה?",["בְּבִרְכַּת ״מוֹדִים״","בִּקְרִיאַת שְׁמַע","בְּסוֹף אֲדוֹן עוֹלָם"],0,"כָּל שְׁמוֹנַת יְמֵי חֲנֻכָּה מוֹסִיפִים ״עַל הַנִּסִּים״ בְּבִרְכַּת ״מוֹדִים״. מִי שֶׁשָּׁכַח אֵינוֹ חוֹזֵר, אֲבָל אִם נִזְכַּר לִפְנֵי שֵׁם ה׳ בְּסִיּוּם הַבְּרָכָה – חוֹזֵר.","פֶּרֶק צ׳, הֲלָכָה ל״ז","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["יֶלֶד שָׁכַח ״עַל הַנִּסִּים״ בְּבִרְכַּת הַמָּזוֹן. מָה יַעֲשֶׂה?",["יְבָרֵךְ שׁוּב מֵהַתְּחָלָה","לֹא יֹאמַר כְּלוּם","יוֹסִיף בְּ״הָרַחֲמָן״ בַּקָּשָׁה עַל נִסִּים"],2,"גַּם בַּתְּפִלָּה וְגַם בְּבִרְכַּת הַמָּזוֹן, מִי שֶׁשָּׁכַח מוֹסִיף: ״הָרַחֲמָן הוּא יַעֲשֶׂה לָנוּ נִסִּים...״. בַּתְּפִלָּה אוֹמְרִים זֹאת בְּסִיּוּמָהּ, לִפְנֵי ״יִהְיוּ לְרָצוֹן״.","פֶּרֶק צ׳, הֲלָכָה ל״ח-ל״ט","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["בַּחֲנֻכָּה קוֹרְאִים בַּתּוֹרָה בְּכָל יוֹם. בְּאֵיזוֹ פָּרָשָׁה?",["חֲנֻכַּת הַמִּזְבֵּחַ וְקָרְבְּנוֹת הַנְּשִׂיאִים","קְרִיעַת יַם סוּף","מַתַּן תּוֹרָה בְּהַר סִינַי"],0,"בְּכָל יוֹם קוֹרְאִים בְּפָרָשַׁת חֲנֻכַּת הַמִּזְבֵּחַ וְקָרְבְּנוֹת הַנְּשִׂיאִים (בְּמִדְבַּר פֶּרֶק ז). וּבְשַׁחֲרִית אוֹמְרִים הַלֵּל שָׁלֵם בִּבְרָכָה.","פֶּרֶק צ׳, הֲלָכָה מ׳-מ״א","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["מִשְׁפָּחָה אוֹכֶלֶת סְעוּדָה בַּחֲנֻכָּה וְשָׁרָה זְמִירוֹת וְאוֹמֶרֶת דִּבְרֵי תּוֹרָה. מַה הִיא הַסְּעוּדָה?",["סְעוּדָה אֲסוּרָה","סְעוּדַת מִצְוָה","סְעוּדָה שֶׁל חוֹבָה גְּמוּרָה"],1,"אֵין חוֹבָה לִקְבֹּעַ סְעוּדָה בַּחֲנֻכָּה, אֲבָל אִם אוֹמְרִים זְמִירוֹת וְדִבְרֵי תּוֹרָה – הִיא נֶחְשֶׁבֶת סְעוּדַת מִצְוָה.","פֶּרֶק צ׳, הֲלָכָה מ״ב","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["בִּמְסִבַּת חֲנֻכָּה מַדְלִיקִים נֵרוֹת. מָתַי מֻתָּר לְבָרֵךְ עֲלֵיהֶם?",["תָּמִיד","אַף פַּעַם","אִם מִתְפַּלְּלִים שָׁם עַרְבִית"],2,"אֵין מְבָרְכִים עַל נֵרוֹת בִּמְסִבּוֹת חֲנֻכָּה, אֲבָל אִם מִתְפַּלְּלִים שָׁם תְּפִלַּת עַרְבִית – נִתָּן לְהַדְלִיק בִּבְרָכָה.","פֶּרֶק צ׳, הֲלָכָה מ״ג","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["מָה אָסוּר לַעֲשׂוֹת בִּימֵי הַחֲנֻכָּה?",["לְהִתְעַנּוֹת וּלְהַסְפִּיד","לֶאֱכֹל סֻפְגָּנִיּוֹת","לָשִׁיר מָעוֹז צוּר"],0,"בִּימֵי הַחֲנֻכָּה אָסוּר לְהַסְפִּיד וְאָסוּר לְהִתְעַנּוֹת.","פֶּרֶק צ׳, הֲלָכָה מ״ד","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["ט״וּ בִּשְׁבָט הוּא רֹאשׁ הַשָּׁנָה שֶׁל מִי?",["שֶׁל הַבְּהֵמוֹת","שֶׁל הָאִילָנוֹת","שֶׁל הַדָּגִים"],1,"חֲכָמִים קָבְעוּ שֶׁט״וּ בִּשְׁבָט הוּא רֹאשׁ הַשָּׁנָה לָאִילָנוֹת.","פֶּרֶק צ״א, הֲלָכָה א׳","ט״וּ בִּשְׁבָט"],["מָה קוֹרֶה לָאִילָנוֹת בִּתְקוּפַת ט״וּ בִּשְׁבָט?",["מַשִּׁירִים אֶת כָּל הֶעָלִים","מִתְכַּסִּים בְּשֶׁלֶג וְנִרְדָּמִים","מַתְחִילִים לְהוֹצִיא עָלִים וּפְרָחִים"],2,"אַחֲרֵי תַּרְדֵּמַת הַחֹרֶף מַתְחִילִים הָאִילָנוֹת לְהִתְחַדֵּשׁ וּלְהוֹצִיא עָלִים וּפְרָחִים.","פֶּרֶק צ״א, הֲלָכָה א׳","ט״וּ בִּשְׁבָט"],["אֵיזוֹ תְּפִלָּה לֹא אוֹמְרִים בְּט״וּ בִּשְׁבָט?",["תַּחֲנוּן","קְרִיאַת שְׁמַע","בִּרְכַּת הַמָּזוֹן"],0,"מִפְּנֵי שֶׁהוּא רֹאשׁ הַשָּׁנָה לָאִילָנוֹת, שׂוֹמְחִים בּוֹ קְצָת וְאֵין אוֹמְרִים בּוֹ תַּחֲנוּן.","פֶּרֶק צ״א, הֲלָכָה ב׳","ט״וּ בִּשְׁבָט"],["אֵילוּ פֵּרוֹת הֵם מִשִּׁבְעַת הַמִּינִים?",["תַּפּוּחֵי אֲדָמָה וְגֶזֶר","תְּאֵנִים וְרִמּוֹנִים","תִּירָס וּבָצָל"],1,"הַמְּקֻבָּלִים הִנְהִיגוּ לֶאֱכֹל בְּמִיֻחָד פֵּרוֹת שִׁבְעַת הַמִּינִים שֶׁנִּשְׁתַּבְּחָה בָּהֶם אֶרֶץ יִשְׂרָאֵל, כְּמוֹ תְּאֵנִים וְרִמּוֹנִים.","פֶּרֶק צ״א, הֲלָכָה ג׳","ט״וּ בִּשְׁבָט"],["אֵילוּ פֵּרוֹת כְּדַאי לְהַעֲדִיף בְּט״וּ בִּשְׁבָט?",["פֵּרוֹת שֶׁגָּדְלוּ בְּאֶרֶץ יִשְׂרָאֵל","פֵּרוֹת מִפְּלַסְטִיק לְקִשּׁוּט","פֵּרוֹת שֶׁגָּדְלוּ רַק בְּאֶרֶץ רְחוֹקָה"],0,"יֵשׁ לְהַעֲדִיף פֵּרוֹת שֶׁגָּדְלוּ בְּאֶרֶץ יִשְׂרָאֵל.","פֶּרֶק צ״א, הֲלָכָה ג׳","ט״וּ בִּשְׁבָט"],["מָה עָשָׂה רַבִּי אֶלְעָזָר כְּדֵי לֶאֱכֹל מִכָּל פְּרִי פַּעַם בְּשָׁנָה?",["קָנָה צַעֲצוּעַ","חָסַךְ כֶּסֶף","יָשַׁן כָּל הַיּוֹם"],1,"רַבִּי אֶלְעָזָר הָיָה חוֹסֵךְ כֶּסֶף עַל מְנַת שֶׁיּוּכַל לֶאֱכֹל מִכָּל פְּרִי פַּעַם אַחַת בְּשָׁנָה.","פֶּרֶק צ״א, הֲלָכָה ד׳","ט״וּ בִּשְׁבָט"],["מָה נוֹהֲגִים לוֹמַר כְּשֶׁאוֹכְלִים אֶת הַפֵּרוֹת?",["בְּדִיחוֹת וְסִפּוּרִים מַצְחִיקִים","שְׁמוֹת שֶׁל כָּל הַחֲנֻיּוֹת","פְּסוּקִים וּדְבָרִים מֵהַמִּדְרָשִׁים וּמֵהַזֹּהַר"],2,"נוֹהֲגִים לוֹמַר פְּסוּקִים וּקְטָעִים מֵהַמִּדְרָשִׁים וּמֵהַזֹּהַר שֶׁקְּשׁוּרִים לַפֵּרוֹת, וּבָזֶה מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא.","פֶּרֶק צ״א, הֲלָכָה ד׳","ט״וּ בִּשְׁבָט"],["יֵשׁ לְפָנֶיךָ הַרְבֵּה פֵּרוֹת שׁוֹנִים. מָה כְּדַאי לִלְמֹד לִפְנֵי שֶׁמְּבָרְכִים?",["אֵיזֶה פְּרִי הֲכִי מָתוֹק","סֵדֶר הַקְּדִימוּת בַּבְּרָכוֹת","כַּמָּה פֵּרוֹת יֵשׁ בַּצַּלַּחַת"],1,"סֵדֶר הַקְּדִימוּת בְּבִרְכוֹת הַפֵּרוֹת הַשּׁוֹנִים מְפֹרָט בְּפֶרֶק כ״ז.","פֶּרֶק צ״א, הֲלָכָה ה׳","ט״וּ בִּשְׁבָט"]],"b":[["אֵיתָן מִתְעוֹרֵר בַּבֹּקֶר וְחוֹשֵׁב: ׳אִם אַף אֶחָד לֹא רוֹאֶה אוֹתִי, אֲנִי יָכוֹל לַעֲשׂוֹת מָה שֶׁאֲנִי רוֹצֶה.׳ מָה הַתְּשׁוּבָה הַנְּכוֹנָה לְפִי הַהֲלָכָה?",["רַק בְּבֵית הַכְּנֶסֶת יֵשׁ מִי שֶׁרוֹאֶה אֶת הַיְּלָדִים","ה׳ רוֹאֶה אוֹתָנוּ תָּמִיד גַּם בְּלִי אַף אֶחָד אַחֵר","זֶה נָכוֹן, כָּל עוֹד אַף אֶחָד אַחֵר לֹא רוֹאֶה","זֶה נָכוֹן, אֲבָל רַק בְּשָׁעוֹת הַלַּיְלָה הַחֲשׁוּכוֹת"],1,"ה׳ מַשְׁגִּיחַ עָלֵינוּ תָּמִיד וְרוֹאֶה אֶת כָּל מַעֲשֵׂינוּ, גַּם כְּשֶׁאֵין אִישׁ אַחֵר לְיָדֵנוּ.","פֶּרֶק א׳, הֲלָכָה א׳","הַשְׁכָּמַת הַבֹּקֶר"],["דָּנִי קָם בַּבֹּקֶר אֲבָל נִשְׁאָר שׁוֹכֵב עוֹד חֲצִי שָׁעָה מֵרֹב עַצְלוּת. מָה חֲכָמֵינוּ הָיוּ אוֹמְרִים לוֹ?",["זֶה בְּסֵדֶר, אֵין בְּכָךְ כְּלוּם","עֲדִיף לָקוּם רַק בְּשָׁעוֹת הַצָּהֳרַיִם הַמְּאֻחֲרוֹת","צָרִיךְ לָקוּם כְּמוֹ אַרְיֵה וְלֹא לְהִתְעַצֵּל","מֻתָּר לְהַמְתִּין עַד שֶׁמִּישֶׁהוּ יָעִיר אוֹתוֹ"],2,"חֲכָמֵינוּ לִמְּדוּ לְהִתְגַּבֵּר כָּאֲרִי וְלָקוּם בִּזְרִיזוּת לַעֲבוֹדַת הַבּוֹרֵא, לֹא לְהִתְמַהְמֵהַּ.","פֶּרֶק א׳, הֲלָכָה ב׳","הַשְׁכָּמַת הַבֹּקֶר"],["נֹעַ אוֹמֵר ׳מוֹדֶה אֲנִי׳ מַהֵר מְאוֹד בְּלִי שׁוּם הַפְסָקָה בֵּין הַמִּלִּים. מָה אֶפְשָׁר לְהַצִּיעַ לוֹ?",["לוֹמַר אֶת זֶה רַק בְּיוֹם שַׁבָּת","לַעֲצֹר קְצָת בֵּין ׳בְּחֶמְלָה׳ לְ׳רַבָּה אֱמוּנָתֶךָ׳","לְדַלֵּג עַל כָּל הַמִּשְׁפָּט הַשֵּׁנִי","לְהַמְשִׁיךְ כָּכָה, זֶה בְּסֵדֶר גָּמוּר"],1,"יֵשׁ לְהַפְסִיק מְעַט בֵּין שְׁנֵי חֶלְקֵי הַמִּשְׁפָּט כְּדֵי לוֹמַר אוֹתָם בְּכַוָּנָה וּבְיִשּׁוּב הַדַּעַת.","פֶּרֶק א׳, הֲלָכָה ג׳","הַשְׁכָּמַת הַבֹּקֶר"],["תָּמָר שׁוֹאֶלֶת: ׳אִם עוֹד לֹא נָטַלְתִּי יָדַיִם, מֻתָּר לִי לוֹמַר מוֹדֶה אֲנִי?׳ מָה הַתְּשׁוּבָה?",["כֵּן, אֲבָל רַק אִם יֵשׁ מַיִם קָרִים בַּחֶדֶר","כֵּן, כִּי אֵין בַּנֻּסָּח הַזֶּה אֶת שֵׁם ה׳","לֹא, כִּי צָרִיךְ לְהִתְלַבֵּשׁ קֹדֶם","לֹא, חַיָּבִים לִטֹּל יָדַיִם קֹדֶם לְכָל דָּבָר"],1,"מֻתָּר לוֹמַר ׳מוֹדֶה אֲנִי׳ לִפְנֵי נְטִילָה, שֶׁהֲרֵי אֵין בּוֹ הַזְכָּרַת שֵׁם ה׳.","פֶּרֶק א׳, הֲלָכָה ד׳","הַשְׁכָּמַת הַבֹּקֶר"],["יוֹנָתָן שׁוֹטֵף יָדַיִם רַק פַּעַם אַחַת עַל כָּל יָד בַּבֹּקֶר וְחוֹשֵׁב שֶׁזֶּה מַסְפִּיק. מָה הַטָּעוּת שֶׁלּוֹ?",["אֵין טָעוּת, פַּעַם אַחַת מַסְפִּיקָה","צָרִיךְ לִשְׁפֹּךְ עַל כָּל יָד שָׁלוֹשׁ פְּעָמִים לְסֵרוּגִין","צָרִיךְ לִשְׁפֹּךְ רַק עַל יָד שְׂמֹאל","צָרִיךְ לִשְׁפֹּךְ חָמֵשׁ פְּעָמִים נוֹסָפוֹת עַל כָּל יָד"],1,"נְטִילַת הַבֹּקֶר נַעֲשֵׂית לְסֵרוּגִין, שָׁלוֹשׁ פְּעָמִים עַל כָּל יָד, חֲלִיפוֹת בֵּין הַיָּדַיִם.","פֶּרֶק ב׳, הֲלָכָה ד׳","הַשְׁכָּמַת הַבֹּקֶר"],["רוֹנִי רוֹצֶה לְבָרֵךְ ׳עַל נְטִילַת יָדַיִם׳ מִיָּד אַחֲרֵי שֶׁקָּם, עוֹד לִפְנֵי שֶׁהִתְלַבֵּשׁ וְהִתְפַּנָּה. מָה עָדִיף שֶׁיַּעֲשֶׂה?",["לְבָרֵךְ בְּקוֹל שָׁקֵט בִּלְבַד תָּמִיד","לְהִתְפַּנּוֹת וּלְהִתְלַבֵּשׁ קֹדֶם וְאַחַר כָּךְ לִטֹּל וּלְבָרֵךְ","לְדַלֵּג עַל הַבְּרָכָה הַזֹּאת לְגַמְרֵי","לְבָרֵךְ מִיָּד, אֵין צֹרֶךְ לְהַמְתִּין"],1,"בְּדֶרֶךְ כְּלָל אִי אֶפְשָׁר לְבָרֵךְ מִיָּד מִפְּנֵי שֶׁצָּרִיךְ לְהִתְפַּנּוֹת וּלְהִתְלַבֵּשׁ קֹדֶם בְּכָבוֹד הָרָאוּי.","פֶּרֶק ב׳, הֲלָכָה ה׳","הַשְׁכָּמַת הַבֹּקֶר"],["אוֹר נוֹטֵל יָדַיִם בְּחֶדֶר אַמְבַּטְיָה שֶׁאֵין בּוֹ שֵׁרוּתִים. הַאִם מֻתָּר לוֹ לְבָרֵךְ שָׁם מִיָּד?",["לֹא, יֵשׁ לְבָרֵךְ רַק אַחֲרֵי שֶׁיּוֹצֵא מֵהַחֶדֶר","כֵּן, אֲבָל רַק בְּלַחַשׁ וּבְצִנְעָה","לֹא, אָסוּר לִטֹּל שָׁם בִּכְלָל","כֵּן, אֶפְשָׁר לְבָרֵךְ בְּכָל מָקוֹם"],0,"מֻתָּר לִטֹּל יָדַיִם בְּחֶדֶר אַמְבַּטְיָה בְּלִי שֵׁרוּתִים, אַךְ הַבְּרָכָה נֶאֱמֶרֶת רַק לְאַחַר הַיְּצִיאָה מִמֶּנּוּ.","פֶּרֶק ב׳, הֲלָכָה ו׳","הַשְׁכָּמַת הַבֹּקֶר"],["מַדּוּעַ אָנוּ מוֹדִים לַה׳ בְּבִרְכַּת ״אֲשֶׁר יָצַר״ דַּוְקָא עַל ״נְקָבִים חֲלוּלִים״ בַּגּוּף?",["כִּי הֵם מְסַמְּלִים אֶת יְצִיאַת מִצְרַיִם וְהַגְּאֻלָּה הָעֲתִידָה","כִּי אִם יִסָּתֵם אוֹ יִפָּתֵחַ אֶחָד מֵהֶם, לֹא נוּכַל לִחְיוֹת","כִּי הֵם מוּזְכָּרִים בָּעֲשֶׂרֶת הַדִּבְּרוֹת שֶׁבְּהַר סִינַי","כִּי כָּךְ תִּקְּנוּ חַכְמֵי הַמִּשְׁנָה לְזֵכֶר בֵּית הַמִּקְדָּשׁ"],1,"הַנּוּסָח מַדְגִּישׁ שֶׁהַגּוּף פּוֹעֵל בְּדִיּוּק מֻפְלָא, וְכָל שִׁבּוּשׁ קָטָן הָיָה מְסַכֵּן אֶת הַחַיִּים.","פֶּרֶק ג׳, הֲלָכָה א׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["מָה הַדִּין בְּמִי שֶׁשָּׁכַח לְבָרֵךְ ״אֲשֶׁר יָצַר״, וְאַחַר כָּךְ נִזְקַק שׁוּב לְצְרָכָיו לִפְנֵי שֶׁהִסְפִּיק לְבָרֵךְ?",["הוּא מְבָרֵךְ שְׁתֵּי בְּרָכוֹת נִפְרָדוֹת, אַחַת עַל כָּל פַּעַם","הוּא מְבָרֵךְ רַק פַּעַם אַחַת עַל שְׁתֵּי הַפְּעָמִים יַחַד","הוּא פָּטוּר מִלְּבָרֵךְ כְּלָל מִפְּנֵי שֶׁשָּׁכַח","הוּא מַמְתִּין עַד יוֹם הַמָּחֳרָת וְאָז מְבָרֵךְ"],1,"כְּשֶׁחָזַר וְנִזְקַק שׁוּב לִפְנֵי שֶׁבֵּרֵךְ עַל הַפַּעַם הָרִאשׁוֹנָה, דַּי לוֹ בִּבְרָכָה אַחַת.","פֶּרֶק ג׳, הֲלָכָה ה׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["מַדּוּעַ אָסוּר לוֹמַר פְּסוּקִים, אֲפִלּוּ כְּתַחֲנוּנִים, לִפְנֵי שֶׁמְּבָרְכִים בִּרְכוֹת הַתּוֹרָה?",["כִּי אָסוּר לְהַזְכִּיר אֶת שֵׁם ה׳ לִפְנֵי שֶׁמְּנַקִּים יָדַיִם","כִּי אָמִירַת פְּסוּקִים נֶחְשֶׁבֶת לְעִסּוּק בְּתוֹרָה הַטָּעוּן בְּרָכָה קוֹדֶם","כִּי פְּסוּקִים נֶאֱמָרִים רַק בְּבֵית הַכְּנֶסֶת","כִּי הַתַּחֲנוּנִים נֶאֱמָרִים רַק אַחֲרֵי הַתְּפִלָּה"],1,"לִמּוּד תּוֹרָה, גַּם בְּצוּרַת תַּחֲנוּנִים, טָעוּן בְּרָכָה לִפְנֵי כֵן, וְלָכֵן אָסוּר לוֹמַר פְּסוּקִים קֹדֶם הַבְּרָכוֹת.","פֶּרֶק ד׳, הֲלָכָה ב׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["מַדּוּעַ אֵין צֹרֶךְ לַחֲזֹר וּלְבָרֵךְ בִּרְכוֹת הַתּוֹרָה בְּכָל פַּעַם שֶׁמַּתְחִילִים לִלְמֹד בְּאוֹתוֹ הַיּוֹם?",["מִפְּנֵי שֶׁחֲכָמִים בִּטְּלוּ אֶת הַחֲזָרָה עַל הַבְּרָכָה כְּבָר בִּימֵי הַתַּלְמוּד","מִפְּנֵי שֶׁהַבְּרָכָה חָלָה רַק עַל סְפָרִים שֶׁכְּבָר נִפְתְּחוּ בַּבֹּקֶר","מִפְּנֵי שֶׁמִּצְוַת הַתּוֹרָה נִמְשֶׁכֶת תָּמִיד, וּמַדְרִיכָה אֶת הָאָדָם בְּכָל מַעֲשָׂיו","מִפְּנֵי שֶׁהַבְּרָכָה נֶאֱמֶרֶת רַק פַּעַם אַחַת בְּכָל שָׁבוּעַ שָׁלֵם"],2,"נֶאֱמַר ״וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה״, כְּלוֹמַר מִצְוַת הַתּוֹרָה נִמְשֶׁכֶת כָּל הַיּוֹם, גַּם בְּלִי לִמּוּד בְּפֹעַל.","פֶּרֶק ד׳, הֲלָכָה ג׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["מַדּוּעַ מִי שֶׁשָּׁכַח לְבָרֵךְ בִּרְכוֹת הַתּוֹרָה וְכְבָר אָמַר ״אַהֲבַת עוֹלָם״ – אֵינוֹ חוֹזֵר וּמְבָרֵךְ?",["מִפְּנֵי שֶׁיֵּשׁ אוֹמְרִים שֶׁיָּצָא יְדֵי חוֹבָה בַּמִּלִּים עַל לִמּוּד וְהֶאָרַת הַתּוֹרָה","מִפְּנֵי שֶׁבִּרְכַּת אַהֲבַת עוֹלָם חֲשׁוּבָה הַרְבֵּה יוֹתֵר מִבִּרְכוֹת הַתּוֹרָה","מִפְּנֵי שֶׁהַתְּפִלָּה כְּבָר הִסְתַּיְּמָה וְאֵין בָּהּ מָקוֹם לְהוֹסִיף דָּבָר","מִפְּנֵי שֶׁאָסוּר לְבָרֵךְ שְׁתֵּי בְּרָכוֹת דּוֹמוֹת בְּתוֹךְ אוֹתָהּ תְּפִלָּה"],0,"לְדֵעַת חֵלֶק מִפּוֹסְקֵי הַהֲלָכָה, הַמִּלִּים ״תֵּן בְּלִבֵּנוּ בִּינָה... וְהָאֵר עֵינֵינוּ בְּתוֹרָתֶךָ״ מְמַלְּאוֹת אֶת מְקוֹם הַבְּרָכָה.","פֶּרֶק ד׳, הֲלָכָה ד׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["מָה אוֹמֶרֶת הַהֲלָכָה בְּעִנְיַן חִיּוּב בָּנוֹת בְּבִרְכוֹת הַתּוֹרָה?",["הַבָּנוֹת פְּטוּרוֹת לְגַמְרֵי מֵהַבְּרָכָה הַזֹּאת בְּכָל מָקוֹם","גַּם הַבָּנוֹת חַיָּבוֹת לְבָרֵךְ בִּרְכוֹת הַתּוֹרָה בְּכָל בֹּקֶר","הַבָּנוֹת מְבָרְכוֹת רַק כְּשֶׁהֵן לוֹמְדוֹת תּוֹרָה בְּעַצְמָן בְּפֹעַל","הַבָּנוֹת מְבָרְכוֹת רַק בְּשַׁבָּת וּבְחַגִּים שֶׁל הַשָּׁנָה"],1,"הַהֲלָכָה קוֹבַעַת בְּפֵרוּשׁ כִּי נָשִׁים חַיָּבוֹת בְּבִרְכוֹת הַתּוֹרָה, כְּמוֹ הַבָּנִים.","פֶּרֶק ד׳, הֲלָכָה ה׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["בְּאֵיזֶה חֵלֶק מִבִּרְכוֹת הַתּוֹרָה מוּמְלָץ לַהוֹרִים לְכַוֵּן בְּמְיֻחָד עַל יְלָדֵיהֶם?",["בַּמִּלִּים ״אֲשֶׁר בָּחַר בָּנוּ מִכָּל הָעַמִּים הַקְּדוֹשִׁים וְנָתַן לָנוּ״","בַּמִּלִּים ״וְנִהְיֶה אֲנַחְנוּ וְצֶאֱצָאֵינוּ כֻּלָּנוּ יוֹדְעֵי שְׁמֶךָ וְלוֹמְדֵי תוֹרָתְךָ״","בַּמִּלִּים ״בָּרוּךְ אַתָּה ה׳, אֲשֶׁר נוֹתֵן אֶת הַתּוֹרָה״","בַּמִּלִּים ״רוֹפֵא כָל בָּשָׂר וּמַפְלִיא לַעֲשׂוֹת כָּל יוֹם״"],1,"בַּמִּלִּים הָאֵלֶּה רָאוּי שֶׁהַהוֹרִים יִתְפַּלְּלוּ שֶׁיִּהְיוּ יְלָדֵיהֶם לוֹמְדֵי תוֹרָה וְצַדִּיקִים.","פֶּרֶק ד׳, הֲלָכָה ו׳","חִידוֹן מְקוֹר חַיִּים – בִּרְכַּת אֲשֶׁר יָצַר וּבִרְכוֹת הַתּוֹרָה"],["דָּוִד הֵזִיז אֶת רַגְלָיו מֵהַמִּטָּה אֶל הָרִצְפָּה בַּבֹּקֶר. אֵיזוֹ בְּרָכָה הוּא אָמוּר לוֹמַר בְּאוֹתוֹ רֶגַע?",["הַמֵּכִין מִצְעֲדֵי גָבֶר, עַל הַיְּכֹלֶת לָלֶכֶת בָּרְחוֹב","זוֹקֵף כְּפוּפִים, עַל כָּךְ שֶׁהוּא יָכוֹל לַעֲמֹד זָקוּף וְגָבוֹהַ בְּקוֹמָתוֹ","רוֹקַע הָאָרֶץ עַל הַמַּיִם, עַל כָּךְ שֶׁה׳ בָּרָא אֶת הָעוֹלָם","מַלְבִּישׁ עֲרֻמִּים, עַל הַבְּגָדִים שֶׁהוּא לוֹבֵשׁ כָּעֵת"],2,"כְּשֶׁמַּנִּיחִים רַגְלַיִם עַל הָאָרֶץ מְבָרְכִים ״רוֹקַע הָאָרֶץ עַל הַמַּיִם״","פֶּרֶק ה׳, הֲלָכָה א׳","בִּרְכוֹת הַשַּׁחַר"],["שִׁמְעוֹן חוֹלֶה וְשׁוֹכֵב בְּמִטָּתוֹ כָּל הַיּוֹם וְאֵינוֹ יָכוֹל לָקוּם כְּלָל. מָה הַדִּין לְגַבֵּי בִּרְכוֹת הַשַּׁחַר?",["הוּא מְבָרֵךְ רַק אֶת ״אֱלֹהַי נְשָׁמָה״ וְשׁוֹתֵק בְּכָל הַשְּׁאָר","הוּא מְחַכֶּה שֶׁיַּבְרִיא וְאָז יְבָרֵךְ אֶת כָּל הַבְּרָכוֹת בְּבַת אַחַת","הוּא פָּטוּר מִכָּל הַבְּרָכוֹת כִּי הוּא לֹא עוֹשֶׂה אֶת הַפְּעֻלּוֹת בְּעַצְמוֹ","הוּא מְבָרֵךְ אֶת כָּל בִּרְכוֹת הַשַּׁחַר, כִּי זוֹ הוֹדָאָה כְּלָלִית לָאָדָם"],3,"בִּרְכוֹת הַשַּׁחַר הֵן הוֹדָאָה כְּלָלִית לְה׳ עַל שֶׁהוּא מְסַפֵּק אֶת צָרְכֵי בְּנֵי הָאָדָם, לָכֵן גַּם חוֹלֶה שֶׁאֵינוֹ קָם מְבָרֵךְ אֶת כֻּלָּן","פֶּרֶק ה׳, הֲלָכָה ה׳","בִּרְכוֹת הַשַּׁחַר"],["יוֹסֵף שָׁכַח לְבָרֵךְ אֶת בִּרְכוֹת הַשַּׁחַר לִפְנֵי הַתְּפִלָּה. מָה עָלָיו לַעֲשׂוֹת?",["לְבָרֵךְ אוֹתָן אַחֲרֵי הַתְּפִלָּה, חוּץ מִבִּרְכוֹת הַתּוֹרָה וּבִרְכַּת ״אֱלֹהַי נְשָׁמָה״","לְחַכּוֹת עַד הַיּוֹם הַבָּא כְּדֵי לְבָרֵךְ אוֹתָן בְּיַחַד וּבְשִׂמְחָה גְּדוֹלָה מְאוֹד","לְבָרֵךְ רַק אֶת בִּרְכַּת ״הַמֵּכִין מִצְעֲדֵי גָבֶר״ בִּלְבַד","לְוַתֵּר עַל כָּל הַבְּרָכוֹת הָאֵלֶּה לְגַמְרֵי בְּאוֹתוֹ יוֹם"],0,"מִי שֶׁשָּׁכַח לְבָרֵךְ בִּרְכוֹת הַשַּׁחַר יְבָרֵךְ אוֹתָן אַחֲרֵי הַתְּפִלָּה, חוּץ מִבִּרְכוֹת הַתּוֹרָה שֶׁנִּפְטָרוֹת בְּ״אַהֲבַת עוֹלָם״ וּמִבִּרְכַּת ״אֱלֹהַי נְשָׁמָה״ שֶׁנִּפְטֶרֶת בִּ״מְחַיֵּה הַמֵּתִים״","פֶּרֶק ה׳, הֲלָכָה ז׳","בִּרְכוֹת הַשַּׁחַר"],["בְּלֵיל חַג הַשָּׁבוּעוֹת יֵשׁ יְלָדִים שֶׁנִּשְׁאָרִים עֵרִים כָּל הַלַּיְלָה. מָה אוֹמֶרֶת הֲלָכָה ו׳ עַל דִּינָם?",["חַיָּבִים לִישֹׁן לְפָחוֹת שָׁעָה אַחַת כְּדֵי שֶׁיּוּכְלוּ לְבָרֵךְ בַּבֹּקֶר","קַיָּמִים מִנְהָגִים שׁוֹנִים לְגַבֵּי בִּרְכוֹת נְטִילַת יָדַיִם וּבִרְכוֹת הַתּוֹרָה וּבִרְכוֹת הַשַּׁחַר","אֵין שׁוּם הֶבְדֵּל בֵּינוֹ לְבֵין מִי שֶׁיָּשַׁן כָּרָגִיל בְּלֵילוֹת אֲחֵרִים","כָּל מִי שֶׁעֵר בַּלַּיְלָה פָּטוּר לְגַמְרֵי מִכָּל הַבְּרָכוֹת הָאֵלֶּה לְמָחֳרָת בַּבֹּקֶר"],1,"יֵשׁ מִנְהָגִים שׁוֹנִים בֵּין קְהִלּוֹת לְגַבֵּי מִי שֶׁהָיָה עֵר כָּל הַלַּיְלָה, הֵן לְעִנְיַן נְטִילַת יָדַיִם, הֵן לְעִנְיַן בִּרְכוֹת הַתּוֹרָה וְהֵן לְעִנְיַן בִּרְכוֹת הַשַּׁחַר","פֶּרֶק ה׳, הֲלָכָה ו׳","בִּרְכוֹת הַשַּׁחַר"],["רוּת יְשֵׁנָה בְּשֶׁקֶט בְּצָהֳרֵי עֶרֶב חַג הַשָּׁבוּעוֹת כְּדֵי שֶׁיִּהְיֶה לָהּ כֹּחַ לְהִשָּׁאֵר עֵרָה בַּלַּיְלָה. מָה הַדִּין שֶׁלָּהּ לְגַבֵּי בִּרְכוֹת הַתּוֹרָה?",["הִיא חַיֶּבֶת לְהַמְתִּין עַד הָעֶרֶב הַבָּא כְּדֵי לְבָרֵךְ","הִיא חַיֶּבֶת לִשְׁמֹעַ אוֹתָן דַּוְקָא מֵאָדָם אַחֵר","הִיא פְּטוּרָה מִבִּרְכוֹת הַתּוֹרָה לְגַמְרֵי בְּאוֹתוֹ יוֹם","הִיא יְכוֹלָה לְבָרֵךְ אֶת בִּרְכוֹת הַתּוֹרָה בְּעַצְמָהּ בְּעֲלוֹת הַשַּׁחַר"],3,"לְכָל הַדֵּעוֹת, מִי שֶׁיָּשַׁן בַּיּוֹם הַקּוֹדֵם יָכוֹל לְבָרֵךְ בְּעַצְמוֹ אֶת בִּרְכוֹת הַתּוֹרָה גַּם אִם הָיָה עֵר כָּל הַלַּיְלָה","פֶּרֶק ה׳, הֲלָכָה ו׳","בִּרְכוֹת הַשַּׁחַר"],["בְּשַׁבָּת וּבְיוֹם טוֹב יֵשׁ פָּחוֹת בְּרָכוֹת בִּתְפִלַּת הָעֲמִידָה מִבִּימוֹת הַחֹל. אֵיךְ מַשְׁלִימִים אֶת מֵאָה הַבְּרָכוֹת בְּיָמִים אֵלּוּ?",["מְוַתְּרִים עַל הַהַשְׁלָמָה כִּי אִי אֶפְשָׁר לְהַגִּיעַ לְמֵאָה","מְבָרְכִים אֶת בִּרְכַּת הַמָּזוֹן פַּעֲמַיִם עַל כָּל סְעוּדָה אַחַת בִּלְבַד","מַרְבִּים בַּאֲכִילַת פֵּרוֹת וּבַהֲרָחַת בְּשָׂמִים כְּדֵי לְהַשְׁלִים אֶת הַבְּרָכוֹת הַחֲסֵרוֹת","אוֹכְלִים פָּחוֹת סְעֻדּוֹת כְּדֵי לְצַמְצֵם אֶת הַצֹּרֶךְ בִּבְרָכוֹת"],2,"בְּשַׁבָּתוֹת וְיָמִים טוֹבִים, שֶׁיֵּשׁ בָּהֶם פָּחוֹת בְּרָכוֹת בַּתְּפִלָּה, נוֹהֲגִים לְהַרְבּוֹת בַּאֲכִילַת פֵּרוֹת וּבַהֲרָחַת בְּשָׂמִים","פֶּרֶק ה׳, הֲלָכָה ח׳","בִּרְכוֹת הַשַּׁחַר"],["בְּכַמָּה מִשְׁפָּחוֹת נוֹהֲגִים לְסַדֵּר אֶת בִּרְכוֹת הַשַּׁחַר בְּסֵדֶר קְצָת שׁוֹנֶה זֶה מִזֶּה. מָה הַהוֹרָאָה בַּעִנְיָן זֶה?",["אֵין בִּכְלָל חֲשִׁיבוּת לַסֵּדֶר וְאֶפְשָׁר לְשַׁנּוֹת בְּכָל פַּעַם","כָּל אֶחָד יִנְהַג כְּמִנְהַג אֲבוֹתָיו כִּי יֵשׁ מִנְהָגִים שׁוֹנִים בְּסֵדֶר הַבְּרָכוֹת","צָרִיךְ לִשְׁאֹל אֶת הָרַב לִפְנֵי כָּל בֹּקֶר אֵיךְ לְסַדֵּר","חוֹבָה עַל כֻּלָּם לִנְהֹג בְּדִיּוּק בְּאוֹתוֹ הַסֵּדֶר בְּלִי שׁוּם שִׁנּוּי קָטָן"],1,"יֵשׁ מִנְהָגִים שׁוֹנִים בְּסֵדֶר הַבְּרָכוֹת, וְכָל אֶחָד יִנְהַג כְּמִנְהַג אֲבוֹתָיו","פֶּרֶק ה׳, הֲלָכָה ד׳","בִּרְכוֹת הַשַּׁחַר"],["מָה אוֹמְרִים חֲכָמִים עַל מִי שֶׁמַּשְׁכִּים לְבֵית הַכְּנֶסֶת?",["שֶׁהוּא יְקַבֵּל מָקוֹם מְיֻחָד בַּבַּיִת","שֶׁהוּא זוֹכֶה לַאֲרִיכוּת יָמִים בִּזְכוּת הַשְׁכָּמָתוֹ","שֶׁהוּא פָּטוּר מִלְּהִתְפַּלֵּל בְּכָל יוֹם","שֶׁהוּא צָרִיךְ לְלַמֵּד אֶת כָּל הַקָּהָל"],1,"זוֹהִי אַחַת הַמִּצְווֹת שֶׁאָדָם אוֹכֵל פֵּרוֹתֵיהֶן בָּעוֹלָם הַזֶּה וְהַקֶּרֶן קַיֶּמֶת לוֹ לָעוֹלָם הַבָּא.","פֶּרֶק ו׳, הֲלָכָה א׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מַדּוּעַ מֻתָּר וְרָצוּי לָרוּץ אֶל בֵּית הַכְּנֶסֶת אַךְ אָסוּר לָרוּץ מִמֶּנּוּ?",["כִּי אָסוּר לָרוּץ בִּרְחוֹב בִּכְלָל אַף פַּעַם","כִּי הָרִיצָה גּוֹרֶמֶת לְעַיֵּפוּת גְּדוֹלָה מְאוֹד","כִּי הֲלִיכָה מְהִירָה לִדְבַר מִצְוָה הִיא עַצְמָהּ מִצְוָה","כִּי חוֹשְׁשִׁים שֶׁמִּישֶׁהוּ יִפֹּל בַּדֶּרֶךְ"],2,"מִצְוָה לָרוּץ לְכָל דְּבַר מִצְוָה, אַךְ בְּיָצִיאָה מִבֵּית הַכְּנֶסֶת הוֹלְכִים בְּמָתוּן.","פֶּרֶק ו׳, הֲלָכָה ב׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["אֵיךְ נָכוֹן לְהִתְנַהֵג בִּכְנִיסָה לְבֵית הַכְּנֶסֶת, לְפִי הַהַשְׁוָאָה שֶׁל חֲכָמִים?",["לְהִכָּנֵס בִּמְהִירוּת כְּדֵי לֹא לְאַחֵר","לְהִכָּנֵס בְּשֶׁקֶט מֻחְלָט בְּלִי לְדַבֵּר כְּלָל","לְהִכָּנֵס בְּשִׂמְחָה גְּדוֹלָה וּבְצִיּוּחִים שְׁמֵחִים","לְהִכָּנֵס בְּאֵימָה וְיִרְאָה כְּמוֹ בְּבֵית הַמֶּלֶךְ"],3,"אֵין נִכְנָסִים בְּרִיצָה, אֶלָּא הוֹלְכִים כְּמוֹ שֶׁהוֹלְכִים בְּבֵית הַמֶּלֶךְ.","פֶּרֶק ו׳, הֲלָכָה ג׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מָה עוֹשִׂים לְפִי הַהֲלָכָה מִיָּד כְּשֶׁנִּכְנָסִים לְבֵית הַכְּנֶסֶת?",["מְחַפְּשִׂים מִיָּד אֶת הַמָּקוֹם הַקָּבוּעַ שֶׁלָּנוּ","שׁוֹהִים מְעַט וְאוֹמְרִים פְּסוּקִים מְיֻחָדִים","מַמְתִּינִים לְמִישֶׁהוּ שֶׁיִּקְרָא לָנוּ פְּנִימָה","פּוֹנִים יָשָׁר לְדַבֵּר עִם הֶחָבֵר הַטּוֹב"],1,"נוֹהֲגִים לוֹמַר ״וַאֲנִי בְּרֹב חַסְדְּךָ אָבוֹא בֵיתֶךָ״ וְכֵן ״בְּבֵית אֱלֹהִים נְהַלֵּךְ בְּרָגֶשׁ״.","פֶּרֶק ו׳, הֲלָכָה ד׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מַדּוּעַ אָסוּר לְהִתְבַּדֵּחַ בְּבֵית הַכְּנֶסֶת אֲפִלּוּ כְּשֶׁאֵין תְּפִלָּה?",["כִּי קְדֻשַּׁת הַמָּקוֹם וְהַכָּבוֹד קַיֶּמֶת בְּכָל זְמַן","כִּי צְחוֹק גּוֹרֵם לְרַעַשׁ רַב מִדַּי בַּבִּנְיָן","כִּי הַגַּבַּאי תָּמִיד נִמְצָא וְשׁוֹמֵעַ הַכֹּל","כִּי אָסוּר לִצְחֹק בְּשׁוּם מָקוֹם בָּעוֹלָם"],0,"הָאִסּוּר עַל קַלּוּת רֹאשׁ וְשִׂיחָה בְּטֵלָה חָל כָּל הַזְּמַן, לֹא רַק בִּשְׁעַת הַתְּפִלָּה וְהַקְּרִיאָה.","פֶּרֶק ו׳, הֲלָכָה ה׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["בְּאֵילוּ מַצָּבִים נָהֲגוּ בְּכָל זֹאת לֶאֱכֹל וְלִשְׁתּוֹת בְּבֵית הַכְּנֶסֶת?",["בִּסְעוּדַת סִיּוּם מַסֶּכֶת, לֵיל שָׁבוּעוֹת וְיוֹם הַיָּארְצַייט","בְּכָל פַּעַם שֶׁיֵּשׁ אֵיזֶה חֹג קָטָן בַּשָּׁנָה","בְּכָל יוֹם שִׁשִּׁי בְּסוֹף הַתְּפִלָּה הָעַרְבִית","בְּכָל בֹּקֶר אַחֲרֵי תְּפִלַּת שַׁחֲרִית הַקְּבוּעָה"],0,"אַף שֶׁבְּדֶרֶךְ כְּלָל אָסוּר לֶאֱכֹל וְלִשְׁתּוֹת, בַּזְּמַנִּים הַמְּיֻחָדִים הָאֵלֶּה נָהֲגוּ הֶתֵּר.","פֶּרֶק ו׳, הֲלָכָה ו׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מַדּוּעַ אָסוּר לְעַשֵּׁן בְּבֵית הַכְּנֶסֶת וּבְבֵית הַמִּדְרָשׁ?",["כִּי עָשָׁן גּוֹרֵם לְאַזְעָקַת כַּבָּאִים מִיָּד","כִּי אֵין בְּאַף בֵּית כְּנֶסֶת חַלּוֹנוֹת פְּתוּחִים","כִּי הַדִּין שָׁוֶה לְאִסּוּר הָאֲכִילָה וְהַשְּׁתִיָּה בָּהֶם","כִּי רַק הַגַּבַּאי רַשַּׁאי לְעַשֵּׁן בִּפְנִים"],2,"כְּשֵׁם שֶׁאָסוּר לֶאֱכֹל וְלִשְׁתּוֹת בְּבֵית הַכְּנֶסֶת, כָּךְ אָסוּר גַּם לְעַשֵּׁן בּוֹ.","פֶּרֶק ו׳, הֲלָכָה ז׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מָה הַדִּין לְגַבֵּי שֵׁנָה בְּבֵית הַכְּנֶסֶת, גַּם אִם הִיא קְצָרָה מְאוֹד?",["מֻתֶּרֶת לְמִי שֶׁעָיֵף מְאוֹד מֵהַיּוֹם שֶׁעָבַר","אֲפִלּוּ שְׁנַת אַרְעַי קְצָרָה אֲסוּרָה בְּבֵית הַכְּנֶסֶת","מֻתֶּרֶת שֵׁנָה לַיְּלָדִים הַקְּטַנִּים בִּלְבַד תָּמִיד","מֻתֶּרֶת שֵׁנָה קְצָרָה בִּלְבַד בִּזְמַן הַקְּרִיאָה"],1,"הַהֲלָכָה קוֹבַעַת שֶׁאָסוּר לִישֹׁן בְּבֵית הַכְּנֶסֶת, אֲפִלּוּ שְׁנַת אַרְעַי קְצָרָה.","פֶּרֶק ו׳, הֲלָכָה ח׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מָה הַהֶבְדֵּל בֵּין אָדָם בָּרִיא לְאָדָם חוֹלֶה בְּעִנְיַן כְּנִיסָה עִם מַקֵּל?",["לְאִישׁ אַף פַּעַם לֹא מֻתָּר לְהִכָּנֵס עִם מַקֵּל","לְבָרִיא מֻתָּר וְלַחוֹלֶה דַּוְקָא אָסוּר","אֵין שׁוּם הֶבְדֵּל כְּלָל בֵּין שְׁנֵי הַמִּקְרִים","לְזָקֵן וְחוֹלֶה מֻתָּר לְהִכָּנֵס עִם מַקֵּל הֲלִיכָה"],3,"רָאוּי שֶׁלֹּא לְהִכָּנֵס בְּמַקֵּל וְתַרְמִיל, אַךְ לְחוֹלֶה אוֹ זָקֵן מֻתָּר לְהִכָּנֵס עִם מַקֵּל הֲלִיכָה.","פֶּרֶק ו׳, הֲלָכָה ט׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מָה הַדִּין בְּבֵית כְּנֶסֶת שֶׁיֵּשׁ לוֹ שְׁנֵי פְּתָחִים, וְאָדָם נִכְנַס לְצֹרֶךְ תְּפִלָּה?",["אָסוּר לִפְתֹּחַ שְׁנֵי פְּתָחִים בְּבֵית כְּנֶסֶת אֶחָד","חַיָּב תָּמִיד לָצֵאת בְּאוֹתוֹ פֶּתַח שֶׁבּוֹ נִכְנַס","מִי שֶׁהִתְפַּלֵּל בִּפְנִים יָכוֹל לָצֵאת בַּפֶּתַח הַשֵּׁנִי","מֻתָּר לְהִכָּנֵס וְלָצֵאת רַק דֶּרֶךְ חַלּוֹנוֹת"],2,"אָסוּר לְקַצֵּר דֶּרֶךְ דֶּרֶךְ שְׁנֵי פְּתָחִים, אַךְ מִי שֶׁנִּכְנַס לְצֹרֶךְ מִצְוָה וְהִתְפַּלֵּל רַשַּׁאי לָצֵאת בַּשֵּׁנִי.","פֶּרֶק ו׳, הֲלָכָה י׳","הַשְׁכָּמַת בֵּית הַכְּנֶסֶת וּקְדֻשָּׁתוֹ"],["מָה אָמְרוּ חֲכָמִים עַל מִי שֶׁעוֹנֶה ״אָמֵן, יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ״ בְּכָל כֹּחַ כַּוָּנָתוֹ?",["שֶׁהוּא זוֹכֶה מִיָּד לְעַלְיָה לַתּוֹרָה","שֶׁהוּא נֶחְשָׁב תָּמִיד לְשָׁלִיחַ צִבּוּר","שֶׁהוּא פָּטוּר לְגַמְרֵי וּמִיָּד מִתְּפִלַּת מִנְחָה","שֶׁקּוֹרְעִים לוֹ אֶת גְּזַר הַדִּין שֶׁלּוֹ"],3,"חֲכָמִים אָמְרוּ שֶׁכָּל הָעוֹנֶה כֵּן בְּכָל כֹּחַ כַּוָּנָתוֹ קוֹרְעִים לוֹ גְּזַר דִּינוֹ.","פֶּרֶק ח׳, הֲלָכָה א׳","פֶּרֶק ח׳: קַדִּישׁ"],["מָה קוֹרֶה, לְפִי הַפְּסִיקְתָּא, כְּשֶׁיִּשְׂרָאֵל אוֹמְרִים ״יְהֵא שְׁמֵיהּ רַבָּא״ בְּקוֹל רָם בְּבָתֵּי כְּנֵסִיּוֹת?",["הֶחָזָּן מְקַבֵּל שָׂכָר גָּדוֹל מֵהַשָּׁמַיִם","הֵם פְּטוּרִים לְגַמְרֵי מִתְּפִלַּת עַרְבִית","נִבְנֶה מִיָּד בֵּית הַמִּקְדָּשׁ הַשָּׁלִישִׁי","מִתְבַּטְּלוֹת מֵהֶם כָּל הַגְּזֵרוֹת הַקָּשׁוֹת"],3,"כְּשֶׁיִּשְׂרָאֵל אוֹמְרִים זֹאת בְּקוֹל רָם, מִתְבַּטְּלוֹת מֵהֶם גְּזֵרוֹת קָשׁוֹת.","פֶּרֶק ח׳, הֲלָכָה א׳","פֶּרֶק ח׳: קַדִּישׁ"],["אֵיזֶה קַדִּישׁ כּוֹלֵל גַּם בַּקָּשָׁה מְיֻחֶדֶת לְהַצְלָחַת לוֹמְדֵי הַתּוֹרָה?",["קַדִּישׁ הַגָּדוֹל, הַנֶּאֱמָר בְּבֵית הַקְּבָרוֹת","קַדִּישׁ דְּרַבָּנָן, הַנֶּאֱמָר אַחֲרֵי לִמּוּד תּוֹרָה שֶׁבְּעַל פֶּה","קַדִּישׁ יָתוֹם, הַנֶּאֱמָר עַל נִפְטָר","קַדִּישׁ תִּתְקַבֵּל, הַנֶּאֱמָר בְּסוֹף הַתְּפִלָּה"],1,"קַדִּישׁ דְּרַבָּנָן נֶאֱמָר לְאַחַר לִמּוּד תּוֹרָה שֶׁבְּעַל פֶּה, וְכוֹלֵל בַּקָּשָׁה לְהַצְלָחַת לוֹמְדֵי הַתּוֹרָה.","פֶּרֶק ח׳, הֲלָכָה ב׳","פֶּרֶק ח׳: קַדִּישׁ"],["אֵיפֹה וּמָתַי נֶאֱמָר ״קַדִּישׁ הַגָּדוֹל״, לְפִי הַהֲלָכָה?",["בִּזְמַן עֲלִיַּת הָעוֹלִים אֶל הַתּוֹרָה","בְּכָל יוֹם בְּסוֹף תְּפִלַּת שַׁחֲרִית בִּלְבַד","רַק בְּבֵית הַכְּנֶסֶת בְּעֶרֶב שַׁבָּת","בְּבֵית הַקְּבָרוֹת וּבְסִיּוּם מַסֶּכֶת, וּמַזְכִּירִים תְּחִיַּת הַמֵּתִים"],3,"קַדִּישׁ הַגָּדוֹל נֶאֱמָר בְּבֵית הַקְּבָרוֹת וּבְסִיּוּם מַסֶּכֶת, וּבוֹ מַזְכִּירִים אֶת תְּחִיַּת הַמֵּתִים וּבִנְיַן בֵּית הַמִּקְדָּשׁ.","פֶּרֶק ח׳, הֲלָכָה ב׳","פֶּרֶק ח׳: קַדִּישׁ"],["לָמָּה חָשׁוּב לֹא לוֹמַר אֶת הַקַּדִּישׁ יַחַד עִם שְׁלִיחַ הַצִּבּוּר?",["כִּי הַקַּדִּישׁ נֶאֱמָר רַק בְּלַחַשׁ","כִּי אָסוּר לַעֲנוֹת אָמֵן יוֹתֵר מִפַּעַם אַחַת","כִּי הַקַּדִּישׁ טָעוּן רְשׁוּת מְיֻחֶדֶת מֵהֶחָזָּן","כִּי צָרִיךְ לִשְׁמֹעַ אוֹתוֹ וְלַעֲנוֹת בְּמָקוֹם הַמַּתְאִים"],3,"שׁוֹמְעִים אֶת הַקַּדִּישׁ מֵהֶחָזָּן וְעוֹנִים אַחֲרָיו בַּמְּקוֹמוֹת הַמַּתְאִימִים, וְלֹא אוֹמְרִים אוֹתוֹ יַחַד אִתּוֹ.","פֶּרֶק ח׳, הֲלָכָה ג׳","פֶּרֶק ח׳: קַדִּישׁ"],["מַה בִּמְיֻחָד צָרִיךְ לְהִזָּהֵר מִמֶּנּוּ כְּשֶׁשְּׁלִיחַ הַצִּבּוּר שָׁר אֶת הַקַּדִּישׁ בְּנִגּוּן?",["שֶׁלֹּא יִסָּחֲפוּ אַחֲרָיו וְיֹאמְרוּ יַחַד אִתּוֹ","שֶׁלֹּא יִתְבַּלְבְּלוּ בְּנִגּוּן הַתְּפִלָּה הַיָּפֶה","שֶׁלֹּא יִצְאוּ מִבֵּית הַכְּנֶסֶת בְּאֶמְצַע הַתְּפִלָּה","שֶׁלֹּא יָשִׁירוּ בְּקוֹל רָם מִדַּי"],0,"יֵשׁ לְהַקְפִּיד בִּמְיֻחָד כְּשֶׁשְּׁלִיחַ הַצִּבּוּר שָׁר אֶת הַקַּדִּישׁ, שֶׁלֹּא יִסָּחֲפוּ אַחֲרָיו מֵחֲמַת הַשִּׁירָה.","פֶּרֶק ח׳, הֲלָכָה ג׳","פֶּרֶק ח׳: קַדִּישׁ"],["מָה הֵם הַמִּנְהָגִים הַשּׁוֹנִים לְגַבֵּי עֲמִידָה אוֹ יְשִׁיבָה בִּשְׁעַת הַקַּדִּישׁ?",["שְׁנֵי הַמִּנְהָגִים מְחַיְּבִים יְשִׁיבָה גְּמוּרָה","אֵין שׁוּם הֶבְדֵּל בֵּין קְהִלּוֹת יִשְׂרָאֵל","סְפָרַדִּים יוֹשְׁבִים וְאַשְׁכְּנַזִּים עוֹמְדִים בִּשְׁעַת הַקַּדִּישׁ","שְׁנֵי הַמִּנְהָגִים מְחַיְּבִים עֲמִידָה גְּמוּרָה"],2,"בִּקְהִלּוֹת הַסְּפָרַדִּים נוֹהֲגִים לָשֶׁבֶת, וּבִקְהִלּוֹת הָאַשְׁכְּנַזִּים נוֹהֲגִים לַעֲמֹד בִּשְׁעַת הַקַּדִּישׁ.","פֶּרֶק ח׳, הֲלָכָה ד׳","פֶּרֶק ח׳: קַדִּישׁ"],["מָה הַדִּין בִּקְהִלּוֹת הַסְּפָרַדִּים לְמִי שֶׁעָמַד כְּשֶׁהֶחָזָּן הִתְחִיל אֶת הַקַּדִּישׁ?",["עָלָיו לָצֵאת מִבֵּית הַכְּנֶסֶת מִיָּד","לֹא יֵשֵׁב עַד לְאַחַר ״דַּאֲמִירָן בְּעָלְמָא״","עָלָיו לָשֶׁבֶת מִיָּד כְּמִנְהַג הַקָּהָל","אֵין לְכָךְ שׁוּם הַנְחָיָה בַּהֲלָכָה"],1,"מִי שֶׁעָמַד כְּשֶׁהִתְחִיל שְׁלִיחַ הַצִּבּוּר לוֹמַר קַדִּישׁ, לֹא יֵשֵׁב עַד לְאַחַר הַמִּלִּים ״דַּאֲמִירָן בְּעָלְמָא״.","פֶּרֶק ח׳, הֲלָכָה ד׳","פֶּרֶק ח׳: קַדִּישׁ"],["לְפִי הַהֲלָכָה, מָה צָרִיךְ לַעֲשׂוֹת כְּדֵי שֶׁהַצִּיצִית תַּזְכִּיר לְקַיֵּם מִצְווֹת?",["לִלְבֹּשׁ אוֹתָהּ לְשֵׁם הַמִּצְוָה וְלֹא מִתּוֹךְ הֶרְגֵּל","לִלְבֹּשׁ אוֹתָהּ רַק בְּיָמִים טוֹבִים וּבְשַׁבָּתוֹת","לִקְשֹׁר אֶת הַחוּטִים בְּצֶבַע חָדָשׁ כָּל שָׁבוּעַ","לְהַסְתִּיר אוֹתָהּ תָּמִיד מִתַּחַת לִשְׁאָר הַבְּגָדִים"],0,"כְּדֵי שֶׁהַצִּיצִית תַּזְכִּיר אֶת הַמִּצְווֹת וְתַעֲזֹר לְהִמָּנַע מֵעֲבֵרוֹת, יֵשׁ לִלְבֹּשׁ אוֹתָהּ לְשֵׁם הַמִּצְוָה, וְלֹא כְּמִצְוַת אֲנָשִׁים מְלֻמָּדָה.","פֶּרֶק ז׳, הֲלָכוֹת א׳-ב׳","צִיצִית – חֵלֶק א׳"],["מָה פֵּרוּשׁ הַמִּלָּה ״טַלִּית״?",["חוּטִים שֶׁקּוֹשְׁרִים לְכָל אַחַת מֵהַכְּנָפוֹת","פִּנָּה שֶׁל בֶּגֶד שֶׁיֵּשׁ לוֹ אַרְבַּע כְּנָפוֹת","פֵּרוּשׁ הַמִּלָּה טַלִּית הוּא פָּשׁוּט בֶּגֶד","כִּסּוּי רֹאשׁ מְיֻחָד שֶׁלּוֹבְשִׁים רַק בִּתְפִלָּה"],2,"״טַלִּית״ פֵּרוּשָׁהּ בֶּגֶד. הַחוּטִים נִקְרָאִים ״צִיצִית״, וּפִנַּת הַבֶּגֶד נִקְרֵאת ״כָּנָף״.","פֶּרֶק ז׳, הֲלָכָה ג׳","צִיצִית – חֵלֶק א׳"],["מָה זוֹכֶה מִי שֶׁמַּקְפִּיד בְּמִצְוַת צִיצִית?",["הוּא פָּטוּר מִכָּל שְׁאָר הַמִּצְווֹת","הוּא זוֹכֶה לִהְיוֹת עָשִׁיר מְאוֹד","הוּא זוֹכֶה שֶׁלֹּא יִצְטָרֵךְ לְהִתְפַּלֵּל יוֹתֵר","הוּא זוֹכֶה וְרוֹאֶה פְּנֵי שְׁכִינָה"],3,"מִי שֶׁמַּקְפִּיד בְּמִצְוַת צִיצִית זוֹכֶה וְרוֹאֶה פְּנֵי שְׁכִינָה. לָכֵן טוֹב לִלְבֹּשׁ טַלִּית קָטָן כָּל הַיּוֹם.","פֶּרֶק ז׳, הֲלָכוֹת ד׳-ה׳","צִיצִית – חֵלֶק א׳"],["שְׁלִיחַ צִבּוּר מִתְעַטֵּף בְּטַלִּית בִּתְפִלַּת עַרְבִית. מָה הַדִּין?",["מְבָרֵךְ כְּרָגִיל, כִּי הוּא שְׁלִיחַ הַצִּבּוּר","אֵינוֹ מְבָרֵךְ, כִּי זְמַן הַצִּיצִית הוּא בַּיּוֹם","מְבָרֵךְ רַק אִם הַטַּלִּית חֲדָשָׁה לְגַמְרֵי","מְבָרֵךְ שְׁתֵּי בְּרָכוֹת, אַחַת לְכָל צַד"],1,"מִ״וּרְאִיתֶם אֹתוֹ״ לָמְדוּ שֶׁזְּמַן הַמִּצְוָה בַּיּוֹם, לָכֵן הַמִּתְעַטֵּף בַּלַּיְלָה אֵינוֹ מְבָרֵךְ.","פֶּרֶק ז׳, הֲלָכָה ו׳","צִיצִית – חֵלֶק א׳"],["מָה לָמְדוּ חֲכָמִים מִ״וּרְאִיתֶם אֹתוֹ״ עַל בֶּגֶד לַיְלָה?",["בֶּגֶד שֶׁלּוֹבְשִׁים רַק בַּלַּיְלָה חַיָּב בִּשְׁתֵּי צִיצִיּוֹת","בֶּגֶד שֶׁלּוֹבְשִׁים רַק בַּלַּיְלָה פָּטוּר מִצִּיצִית","כָּל בֶּגֶד חַיָּב בְּצִיצִית, בַּיּוֹם וּבַלַּיְלָה","בֶּגֶד לַיְלָה חַיָּב רַק אִם הוּא לָבָן"],1,"רַק בֶּגֶד שֶׁרְגִילִים לִלְבֹּשׁ בַּיּוֹם חַיָּב בְּצִיצִית, וּבֶגֶד שֶׁלּוֹבְשִׁים רַק בַּלַּיְלָה פָּטוּר.","פֶּרֶק ז׳, הֲלָכָה ז׳","צִיצִית – חֵלֶק א׳"],["לָמָּה מְעַיְּנִים בַּחוּטִים לִפְנֵי הַבְּרָכָה עַל הַטַּלִּית?",["כְּדֵי לִבְדֹּק שֶׁהֵם שְׁלֵמִים, שֶׁהַבְּרָכָה לֹא תִּהְיֶה לְבַטָּלָה","כְּדֵי לִסְפֹּר כַּמָּה חוּטִים יֵשׁ בְּכָל אַחַת מֵהַכְּנָפוֹת","כְּדֵי לְהַרְאוֹת לַחֲבֵרִים שֶׁהַטַּלִּית יָפָה וַחֲדָשָׁה","כְּדֵי לְהַחְלִיט בְּאֵיזֶה צַד לְהַתְחִיל לְהִתְעַטֵּף"],0,"בּוֹדְקִים שֶׁהַחוּטִים שְׁלֵמִים וּכְשֵׁרִים כְּדֵי שֶׁהַבְּרָכָה לֹא תִּהְיֶה לְבַטָּלָה. אַחַר כָּךְ מְבָרְכִים בַּעֲמִידָה ״לְהִתְעַטֵּף בַּצִּיצִית״.","פֶּרֶק ז׳, הֲלָכוֹת ח׳-ט׳","צִיצִית – חֵלֶק א׳"],["לָמָּה מַקְפִּידִים שֶׁשְּׁתֵּי צִיצִיּוֹת יִהְיוּ מִלְּפָנִים וּשְׁתַּיִם מֵאָחוֹר?",["כְּדֵי שֶׁהַטַּלִּית לֹא תִּפֹּל בִּזְמַן הַתְּפִלָּה","כְּדֵי שֶׁנִּהְיֶה מְסֻבָּבִים בְּמִצְווֹת מִכָּל הַצְּדָדִים","כְּדֵי שֶׁיִּהְיֶה נוֹחַ יוֹתֵר לָלֶכֶת","כְּדֵי שֶׁכֻּלָּם יִרְאוּ אֶת הַצִּיצִיּוֹת שֶׁלָּנוּ"],1,"שְׁתַּיִם מִלְּפָנִים וּשְׁתַּיִם מֵאָחוֹר – כְּדֵי שֶׁנִּהְיֶה מְסֻבָּבִים בְּמִצְווֹת.","פֶּרֶק ז׳, הֲלָכָה י׳","צִיצִית – חֵלֶק א׳"],["מָה מְכַוְּנִים בִּזְמַן הַבְּרָכָה עַל הַטַּלִּית גָּדוֹל?",["לְהָסִיר אֶת הַטַּלִּית קָטָן לִפְנֵי הַתְּפִלָּה","לִפְטֹר אֶת כָּל הַבְּרָכוֹת שֶׁל הַתְּפִלָּה","לְבָרֵךְ שׁוּב אַחֲרֵי הַתְּפִלָּה עַל הַטַּלִּית קָטָן","לִפְטֹר גַּם אֶת הַטַּלִּית קָטָן שֶׁלּוֹבְשִׁים"],3,"בִּבְרָכַת הַטַּלִּית גָּדוֹל מְכַוְּנִים לִפְטֹר גַּם אֶת הַטַּלִּית קָטָן. מִי שֶׁלּוֹבֵשׁ רַק טַלִּית קָטָן מְבָרֵךְ ״עַל מִצְוַת צִיצִית״.","פֶּרֶק ז׳, הֲלָכָה י״א","צִיצִית – חֵלֶק א׳"],["רְאוּבֵן הוֹרִיד אֶת הַטַּלִּית וְתִכְנֵן לַחֲזֹר לְהִתְעַטֵּף מִיָּד. מָה יַעֲשֶׂה?",["יְבָרֵךְ שׁוּב, כִּי הַטַּלִּית יָרְדָה מִגּוּפוֹ","לֹא יְבָרֵךְ עָלֶיהָ שֵׁנִית כְּשֶׁיַּחֲזֹר לְהִתְעַטֵּף","יְבָרֵךְ רַק אִם עָבַר יוֹתֵר מִשָּׁעָה","יַחְלִיף לְטַלִּית אַחֶרֶת וִיבָרֵךְ עָלֶיהָ"],1,"מִי שֶׁהוֹרִיד אֶת הַטַּלִּית וְתִכְנֵן לַחֲזֹר לְהִתְעַטֵּף מִיָּד – לֹא יְבָרֵךְ שֵׁנִית. וְאִם נָפְלָה בְּטָעוּת – אֵין לְבָרֵךְ, כִּי ״סָפֵק בְּרָכוֹת לְהָקֵל״.","פֶּרֶק ז׳, הֲלָכָה י״ב","צִיצִית – חֵלֶק א׳"],["אֵיזֶה בֶּגֶד חַיָּב בְּצִיצִית לְפִי ״אַרְבַּע כַּנְפוֹת כְּסוּתְךָ״?",["בֶּגֶד שֶׁיֵּשׁ לוֹ שָׁלוֹשׁ כְּנָפוֹת מְרֻבָּעוֹת","בֶּגֶד שֶׁיֵּשׁ לוֹ אַרְבַּע כְּנָפוֹת עֲגֻלּוֹת","בֶּגֶד שֶׁיֵּשׁ לוֹ אַרְבַּע כְּנָפוֹת מְרֻבָּעוֹת","כָּל בֶּגֶד, גַּם בְּלִי כְּנָפוֹת בִּכְלָל"],2,"בֶּגֶד עִם אַרְבַּע כְּנָפוֹת חַיָּב בְּצִיצִית, וּבֶגֶד עִם שָׁלוֹשׁ אוֹ פָּחוֹת פָּטוּר. וְהַכְּנָפוֹת צְרִיכוֹת לִהְיוֹת מְרֻבָּעוֹת וְלֹא עֲגֻלּוֹת.","פֶּרֶק ז׳, הֲלָכוֹת י״ג-י״ד","צִיצִית – חֵלֶק א׳"],["מִי שֶׁלּוֹבֵשׁ טַלִּית קָטָן מִבַּד שֶׁאֵינוֹ צֶמֶר וְאֵינוֹ פִּשְׁתָּן – הַאִם יָכוֹל לְבָרֵךְ?",["לֹא, כִּי מְבָרְכִים רַק עַל מִצְווֹת מִן הַתּוֹרָה","רַק אִם חוּטֵי הַצִּיצִית עֲשׂוּיִים מִצֶּמֶר","כֵּן, כִּי מְבָרְכִים גַּם עַל מִצְווֹת מִדְּרַבָּנָן","רַק אִם הַטַּלִּית לְבָנָה לְגַמְרֵי"],2,"לְכָל הַדֵּעוֹת, גַּם מִי שֶׁמִּתְעַטֵּף בְּטַלִּית אוֹ לוֹבֵשׁ טַלִּית קָטָן מִבַּד אַחֵר יָכוֹל לְבָרֵךְ, מִפְּנֵי שֶׁמְּבָרְכִים גַּם עַל מִצְווֹת מִדְּרַבָּנָן.","פֶּרֶק ז׳, הֲלָכָה ט״ו","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["מָה פֵּרוּשׁ הַכְּלָל ״תַּעֲשֶׂה – וְלֹא מִן הֶעָשׂוּי״?",["אֶפְשָׁר לְהַכְשִׁיר אֶת הַצִּיצִית אַחֲרֵי שֶׁהִיא כְּבָר קְשׁוּרָה","צָרִיךְ לִקְנוֹת צִיצִית רַק מֵחֲנוּת שֶׁל תַּלְמִיד חָכָם","בִּשְׁעַת הֲכָנַת הַצִּיצִית הִיא צְרִיכָה כְּבָר לִהְיוֹת כְּשֵׁרָה","מֻתָּר לְהִשְׁתַּמֵּשׁ רַק בְּטַלִּית חֲדָשָׁה שֶׁלֹּא לָבְשׁוּ אוֹתָהּ"],2,"מֵהַפָּסוּק ״גְּדִלִים תַּעֲשֶׂה לָּךְ״ לָמְדוּ חֲכָמִים שֶׁבְּשָׁעָה שֶׁמְּכִינִים אֶת הַצִּיצִית עָלֶיהָ לִהְיוֹת כְּשֵׁרָה, וְלֹא שֶׁלְּאַחַר מִכֵּן יַעֲשׂוּ מַעֲשֶׂה שֶׁיַּכְשִׁיר אוֹתָהּ.","פֶּרֶק ז׳, הֲלָכָה י״ז","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["חוּט נִקְרַע בַּחֵלֶק שֶׁמְּחֻבָּר לַכָּנָף. מָה הַדִּין?",["קוֹשְׁרִים אֶת הַחוּט שֶׁנִּקְרַע וְהַצִּיצִית כְּשֵׁרָה","הַצִּיצִית פְּסוּלָה, וְאִי אֶפְשָׁר לְתַקֵּן אוֹתָהּ בִּקְשִׁירָה","הַצִּיצִית כְּשֵׁרָה גַּם בְּלִי לְתַקֵּן אֶת הַחוּט","מְבַקְּשִׁים מֵחָבֵר לִקְשֹׁר אֶת הַחוּט בִּמְקוֹמְךָ"],1,"אִם אֶחָד הַחוּטִים נִקְרַע בַּחֵלֶק שֶׁמְּחֻבָּר לַכָּנָף – הַצִּיצִית פְּסוּלָה, וְאִי אֶפְשָׁר לְתַקְּנָהּ בְּקְשִׁירָה, מִשּׁוּם ״תַּעֲשֶׂה וְלֹא מִן הֶעָשׂוּי״.","פֶּרֶק ז׳, הֲלָכָה כ״א","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["נִפְסְקוּ שְׁנַיִם מִשְּׁמוֹנַת חוּטֵי הַצִּיצִית. מָה עוֹשִׂים?",["הַצִּיצִית תָּמִיד כְּשֵׁרָה, וְאֵין צֹרֶךְ לִשְׁאֹל","הַצִּיצִית תָּמִיד פְּסוּלָה, וְצָרִיךְ לְהַחְלִיף מִיָּד","מְדַבְּקִים אֶת הַחוּטִים בְּדֶבֶק וּמַמְשִׁיכִים לִלְבֹּשׁ","פּוֹנִים לְחָכָם, כִּי הַדִּין תָּלוּי בְּאֹפֶן הַקְּשִׁירָה"],3,"אִם נִפְסְקוּ שְׁנֵי חוּטִים אוֹ יוֹתֵר מִתּוֹךְ הַשְּׁמוֹנָה, יֵשׁ לִפְנוֹת בִּשְׁאֵלָה לְחָכָם, מִפְּנֵי שֶׁהַדִּין תָּלוּי בָּאֹפֶן שֶׁבּוֹ קָשְׁרוּ אֶת חוּטֵי הַצִּיצִית.","פֶּרֶק ז׳, הֲלָכָה כ׳","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["מָה צָרִיךְ לְבָרֵר כְּשֶׁקּוֹנִים צִיצִיּוֹת מוּכָנוֹת?",["לְבָרֵר שֶׁהַחוּטִים נַעֲשׂוּ לְשֵׁם מִצְוַת צִיצִית","לִבְחֹר אֶת הַחוּטִים הַלְּבָנִים וְהַחֲזָקִים בְּיוֹתֵר","לִקְנוֹת רַק צִיצִיּוֹת שֶׁעוֹלוֹת הֲכִי הַרְבֵּה כֶּסֶף","לִשְׁאֹל אִם הַחוּטִים נִטְווּ בִּמְכוֹנָה חֲדָשָׁה"],0,"צָרִיךְ לִטְווֹת וְלִשְׁזֹר אֶת הַחוּטִים לִשְׁמָם, וּבִזְמַנֵּנוּ שֶׁקּוֹנִים צִיצִיּוֹת מוּכָנוֹת, צָרִיךְ לְבָרֵר שֶׁהַחוּטִים נַעֲשׂוּ לְשֵׁם מִצְוָה.","פֶּרֶק ז׳, הֲלָכָה י״ח","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["מָה דִּינָן שֶׁל טַלִּיתוֹת שֶׁהִתְבַּלּוּ (הִתְיַשְּׁנוּ)?",["חַיָּבִים לִגְנֹז אוֹתָן מִיָּד, כְּמוֹ סִפְרֵי קֹדֶשׁ","מֻתָּר לְהִשְׁתַּמֵּשׁ בָּהֶן לְכָל דָּבָר שֶׁרוֹצִים","אֵינָן חַיָּבוֹת גְּנִיזָה, אֲבָל אָסוּר תַּשְׁמִישׁ מְגֻנֶּה בָּהֶן","צָרִיךְ לְהַחְזִיר אוֹתָן לַחֲנוּת שֶׁבָּהּ קָנוּ אוֹתָן"],2,"טַלִּיתוֹת שֶׁהִתְבַּלּוּ אֵינָן חַיָּבוֹת בִּגְנִיזָה, אֲבָל אָסוּר לְהִשְׁתַּמֵּשׁ בָּהֶן תַּשְׁמִישׁ מְגֻנֶּה.","פֶּרֶק ז׳, הֲלָכָה כ״ג","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["מִי שֶׁרוֹצֶה לָצֵאת יְדֵי חוֹבָה מִן הַתּוֹרָה לְכָל הַדֵּעוֹת – בְּאֵיזוֹ טַלִּית יִתְעַטֵּף?",["טַלִּית מִכָּל בַּד שֶׁהוּא, אִם הִיא יָפָה","טַלִּית מִבַּד סִינְתֶטִי עִם חוּטִים צִבְעוֹנִיִּים","טַלִּית מִמֶּשִׁי, כִּי הוּא הַבַּד הַיָּקָר בְּיוֹתֵר","טַלִּית מִצֶּמֶר רְחֵלִים, וְגַם חוּטֵי הַצִּיצִית מִצֶּמֶר"],3,"מִי שֶׁרוֹצֶה לְקַיֵּם אֶת הַמִּצְוָה בְּאֹפֶן שֶׁיּוֹצְאִים בּוֹ יְדֵי חוֹבָה מִן הַתּוֹרָה לְכָל הַדֵּעוֹת, צָרִיךְ לְהִתְעַטֵּף בְּטַלִּית מִצֶּמֶר רְחֵלִים, וְגַם חוּטֵי הַצִּיצִית יִהְיוּ מִצֶּמֶר.","פֶּרֶק ז׳, הֲלָכָה ט״ו","הַטַּלִּית וְחוּטֵי הַצִּיצִית"],["מַדּוּעַ רָאוּי לְהִמָּנַע מִלְּהִתְעַטֵּף בְּטַלִּית שְׁאוּלָה?",["כִּי אָסוּר בְּשׁוּם אֹפֶן לָגַעַת בְּטַלִּית שֶׁל חָבֵר","כִּי טַלִּית שְׁאוּלָה תָּמִיד קְטַנָּה מִדַּי","כְּדֵי לֹא לְהִכָּנֵס לִסְפֵק בְּרָכָה לְבַטָּלָה","כִּי הֶחָבֵר עָלוּל לְהִתְחָרֵט וּלְבַקֵּשׁ אוֹתָהּ"],2,"מֵעִקַּר הַדִּין אֶפְשָׁר לְבָרֵךְ עַל טַלִּית שְׁאוּלָה, אֲבָל לְדַעַת חֵלֶק מֵהַפּוֹסְקִים אֵין לְבָרֵךְ, וְלָכֵן רָאוּי לְהִמָּנַע מִסְּפֵק בְּרָכָה לְבַטָּלָה.","פֶּרֶק ז׳, הֲלָכָה כ״ד","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["הַשּׁוֹאֵל טַלִּית כְּדֵי לַעֲלוֹת לַתּוֹרָה – מַה דִּינוֹ?",["מְבָרֵךְ פַּעֲמַיִם, פַּעַם לַטַּלִּית וּפַעַם לַתּוֹרָה","אֵינוֹ מְבָרֵךְ, כִּי זֶה לִכְבוֹד הַתּוֹרָה וְהַצִּבּוּר","מְבָרֵךְ רַק אִם הַטַּלִּית שַׁיֶּכֶת לְבֵית הַכְּנֶסֶת","אָסוּר לוֹ לַעֲלוֹת לַתּוֹרָה בְּטַלִּית שְׁאוּלָה"],1,"מַטְּרָתוֹ אֵינָהּ לָצֵאת יְדֵי חוֹבַת צִיצִית אֶלָּא לִכְבוֹד הַתּוֹרָה וּכְבוֹד הַצִּבּוּר, וְלָכֵן אֵינוֹ מְבָרֵךְ. כָּךְ גַּם הָעוֹלֶה לַדּוּכָן.","פֶּרֶק ז׳, הֲלָכָה כ״ה","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מַדּוּעַ נָשִׁים פְּטוּרוֹת מִמִּצְוַת צִיצִית?",["כִּי הַטַּלִּית כְּבֵדָה מִדַּי לִלְבֹּשׁ כָּל הַיּוֹם","כִּי הַמִּצְוָה נִתְּנָה רַק לַכֹּהֲנִים בַּמִּקְדָּשׁ","כִּי זוֹ מִצְוָה שֶׁמְּקַיְּמִים רַק בַּלַּיְלָה","כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ"],3,"צִיצִית הִיא מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ – זְמַנָּהּ בַּיּוֹם וְלֹא בַּלַּיְלָה – וְנָשִׁים פְּטוּרוֹת מִמִּצְווֹת כָּאֵלֶּה.","פֶּרֶק ז׳, הֲלָכָה כ״ו","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מֵאֵיזֶה גִּיל מְחַנְּכִים יֶלֶד לְמִצְוַת צִיצִית?",["מִגִּיל שֵׁשׁ אוֹ שֶׁבַע, וְיֵשׁ נוֹהֲגִים מִגִּיל שָׁלוֹשׁ","רַק מִגִּיל בַּר מִצְוָה, כְּשֶׁהוּא כְּבָר גָּדוֹל","מִגִּיל עֶשֶׂר בְּדִיּוּק, לְלֹא קֶשֶׁר לְהִתְפַּתְּחוּתוֹ","רַק אַחֲרֵי שֶׁהוּא לוֹמֵד לִקְרֹא בַּתּוֹרָה הֵיטֵב"],0,"גִּיל הַחִנּוּךְ הוּא מִגִּיל שֵׁשׁ אוֹ שֶׁבַע לְפִי הִתְפַּתְּחוּת הַיֶּלֶד, וְיֵשׁ נוֹהֲגִים לְחַנֵּךְ כְּבָר מִגִּיל שָׁלוֹשׁ.","פֶּרֶק ז׳, הֲלָכָה כ״ז","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מָה הַמִּנְהָג הַטּוֹב שֶׁל קְהִלּוֹת הַסְּפָרַדִּים?",["מִתְעַטְּפִים בְּטַלִּית גָּדוֹל רַק אַחֲרֵי הַחֲתֻנָּה","מִתְעַטְּפִים בְּטַלִּית גָּדוֹל רַק בְּרֹאשׁ הַשָּׁנָה","קוֹנִים טַלִּית גָּדוֹל לַיֶּלֶד כְּשֶׁהוּא מַתְחִיל לְהִתְפַּלֵּל","הַיֶּלֶד לוֹבֵשׁ רַק טַלִּית קָטָן עַד גִּיל עֶשְׂרִים"],2,"טוֹב מִנְהַג הַסְּפָרַדִּים שֶׁמִּיָּד כְּשֶׁיֶּלֶד מַתְחִיל לְהִתְפַּלֵּל קוֹנִים לוֹ טַלִּית גָּדוֹל. בְּחֵלֶק מִקְּהִלּוֹת הָאַשְׁכְּנַזִּים מִתְעַטְּפִים רַק אַחֲרֵי הַחֲתֻנָּה.","פֶּרֶק ז׳, הֲלָכָה כ״ח","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["עַל מָה מְרַמֵּז צֶבַע הַתְּכֵלֶת לְפִי רַבִּי מֵאִיר?",["עַל עֲשָׂבִים יְרֻקִּים שֶׁגְּדֵלִים בַּשָּׂדוֹת בָּאָבִיב","עַל כִּסֵּא הַכָּבוֹד, דֶּרֶךְ הַיָּם, הָרָקִיעַ וְאֶבֶן סַפִּיר","עַל הָאֵשׁ שֶׁבָּעֲרָה עַל הַמִּזְבֵּחַ בַּמִּקְדָּשׁ","עַל הַחוֹל הַזָּהֹב שֶׁל מִדְבַּר סִינַי הַגָּדוֹל"],1,"הַתְּכֵלֶת דּוֹמָה לַיָּם, הַיָּם לָרָקִיעַ, הָרָקִיעַ לְאֶבֶן סַפִּיר, וְאֶבֶן סַפִּיר לְכִסֵּא הַכָּבוֹד (חֻלִּין פ״ט, א).","פֶּרֶק ז׳, הֲלָכָה כ״ט","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מַדּוּעַ אֶפְשָׁר לְקַיֵּם מִצְוַת צִיצִית גַּם בְּלִי תְּכֵלֶת?",["כִּי הַתְּכֵלֶת בְּטֵלָה לְגַמְרֵי בִּזְמַן הַגָּלוּת","כִּי חוּט לָבָן אֶחָד שָׁוֶה לִשְׁנֵי חוּטֵי תְּכֵלֶת","כִּי מֻתָּר לִצְבֹּעַ כָּל חוּט בְּכָל צֶבַע כָּחֹל","כִּי הַתְּכֵלֶת אֵינָהּ מְעַכֶּבֶת אֶת הַלָּבָן"],3,"חֲכָמִים קָבְעוּ (מִשְׁנָה מְנָחוֹת ד, א) שֶׁ״הַתְּכֵלֶת אֵינָהּ מְעַכֶּבֶת אֶת הַלָּבָן״, וְלָכֵן קִיְּמוּ אֶת הַמִּצְוָה גַּם בְּלִי פְּתִיל תְּכֵלֶת.","פֶּרֶק ז׳, הֲלָכָה ל׳","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["מַהוּ הַזִּהוּי הַמְּקֻבָּל בְּיוֹתֵר לְחִלָּזוֹן הַתְּכֵלֶת כַּיּוֹם?",["דָּג כָּחֹל גָּדוֹל שֶׁחַי בְּמַעֲמַקֵּי הַיָּם","פֶּרַח כָּחֹל שֶׁגָּדֵל רַק בְּהָרֵי הַגָּלִיל","אַרְגְּמוֹן קְהֵה קוֹצִים, וּמִי שֶׁמַּטִּיל מִמֶּנּוּ – מְהַדֵּר","חִלָּזוֹן שֶׁכָּל הַפּוֹסְקִים מַסְכִּימִים שֶׁחוֹבָה לְהַטִּיל מִמֶּנּוּ"],2,"הַזִּהוּי הַמְּקֻבָּל בְּיוֹתֵר הוּא אַרְגְּמוֹן קְהֵה קוֹצִים. לֹא כָּל הַפּוֹסְקִים מַסְכִּימִים, וְלָכֵן אֵין חוֹבָה אֶלָּא הִדּוּר.","פֶּרֶק ז׳, הֲלָכָה ל״א","טַלִּית שְׁאוּלָה וּפְתִיל תְּכֵלֶת"],["לְפִי הָרַמְבַּ״ם, מַדּוּעַ כְּדַאי לְהִתְפַּלֵּל דַּוְקָא עִם הַצִּבּוּר?",["כִּי בְּבֵית הַכְּנֶסֶת אֶפְשָׁר לְהִתְפַּלֵּל מַהֵר יוֹתֵר","כִּי תְּפִלַּת הָרַבִּים נִשְׁמַעַת תָּמִיד לִפְנֵי ה׳","כִּי יָחִיד אָסוּר לוֹ לְהִתְפַּלֵּל בְּכָל מַצָּב","כִּי רַק בַּצִּבּוּר מֻתָּר לוֹמַר תְּפִלַּת שְׁמוֹנֶה עֶשְׂרֵה"],1,"הָרַמְבַּ״ם כּוֹתֵב: תְּפִלַּת הַצִּבּוּר נִשְׁמַעַת תָּמִיד, וְאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹאֵס בִּתְפִלָּתָן שֶׁל רַבִּים.","פֶּרֶק ט׳, הֲלָכָה א׳","מִנְיַן עֲשָׂרָה"],["הַמְאַחֵר לְשַׁחֲרִית וּמְדַלֵּג - מָה הוּא אוֹמֵר לִפְנֵי תְּפִלַּת הָעֲמִידָה?",["רַק אֶת תְּפִלַּת הָעֲמִידָה, וְאֶת כָּל הַשְּׁאָר יְדַלֵּג","אֶת כָּל פְּסוּקֵי דְזִמְרָה, וִידַלֵּג עַל קְרִיאַת שְׁמַע","יַתְחִיל מִיָּד בְּקַדִּישׁ וְיִשְׁמַע אֶת הַחַזָּן בִּלְבַד","בָּרוּךְ שֶׁאָמַר, אַשְׁרֵי, יִשְׁתַּבַּח וּקְרִיאַת שְׁמַע וּבִרְכוֹתֶיהָ"],3,"הוּא אוֹמֵר בִּרְכוֹת הַשַּׁחַר, ״בָּרוּךְ שֶׁאָמַר״, ״אַשְׁרֵי״, ״יִשְׁתַּבַּח״ (וּבְשַׁבָּת גַּם ״נִשְׁמַת כָּל חַי״), קְרִיאַת שְׁמַע וּבִרְכוֹתֶיהָ.","פֶּרֶק ט׳, הֲלָכָה ד׳","מִנְיַן עֲשָׂרָה"],["אֵיפֹה מִתְבָּאֵר דִּין הַמְאַחֵר לִתְפִלַּת עַרְבִית?",["בְּפֶרֶק כ״א, הֲלָכָה ט׳, וְלָכֵן לֹא כָּאן","בְּפֶרֶק ט׳, מִיָּד אַחֲרֵי דִּין הַמְאַחֵר לְשַׁחֲרִית","אֵין לוֹ דִּין, כִּי עַרְבִית אֵינָהּ חוֹבָה כְּלָל","בְּפֶרֶק א׳, בְּתוֹךְ דִּינֵי הַשְׁכָּמַת הַבֹּקֶר"],0,"הַסֵּפֶר מְצַיֵּן שֶׁדִּין הַמְאַחֵר לְעַרְבִית יִתְבָּאֵר בְּפֶרֶק כ״א הֲלָכָה ט׳.","פֶּרֶק ט׳, הֲלָכָה ה׳","מִנְיַן עֲשָׂרָה"],["מֵאֵיזֶה פָּסוּק לָמְדוּ שֶׁדָּבָר שֶׁבִּקְדֻשָּׁה לֹא יִהְיֶה פָּחוֹת מֵעֲשָׂרָה?",["וַאֲנִי תְפִלָּתִי לְךָ ה׳ עֵת רָצוֹן, מִתְּהִלִּים","קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה׳ צְבָאוֹת, מִסֵּפֶר יְשַׁעְיָהוּ","וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל, מִסֵּפֶר וַיִּקְרָא","שְׁמַע יִשְׂרָאֵל ה׳ אֱלֹקֵינוּ ה׳ אֶחָד"],2,"רַב אַדָּא בַּר אַהֲבָה לָמַד מֵ״וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל״ (וַיִּקְרָא כ״ב, ל״ב) שֶׁכָּל דָּבָר שֶׁבִּקְדֻשָּׁה בַּעֲשָׂרָה.","פֶּרֶק ט׳, הֲלָכָה ו׳","מִנְיַן עֲשָׂרָה"],["אֵילוּ דְּבָרִים אֵין אוֹמְרִים בְּלִי מִנְיָן?",["בִּרְכוֹת הַשַּׁחַר, אַשְׁרֵי, וּקְרִיאַת שְׁמַע בְּלִי בְּרָכוֹת","קַדִּישׁ, בָּרְכוּ, קְדֻשָּׁה, בִּרְכַּת כֹּהֲנִים וּקְרִיאַת הַתּוֹרָה","תְּפִלַּת שְׁמוֹנֶה עֶשְׂרֵה בְּלַחַשׁ וּפְסוּקֵי דְזִמְרָה כֻּלָּם","בִּרְכַּת הַמָּזוֹן, בִּרְכוֹת הַנֶּהֱנִין וּבִרְכוֹת הַשַּׁחַר"],1,"בְּלִי עֲשָׂרָה אֵין אוֹמְרִים קַדִּישׁ, בָּרְכוּ, קְדֻשָּׁה, חֲזָרַת הַשַּׁ״ץ, בִּרְכַּת כֹּהֲנִים, י״ג מִדּוֹת וּקְרִיאַת הַתּוֹרָה.","פֶּרֶק ט׳, הֲלָכָה ו׳","מִנְיַן עֲשָׂרָה"],["יוֹסֵף לוֹמֵד בְּחֶדֶר סָמוּךְ, וְשׁוֹמֵעַ שֶׁהַצִּבּוּר אוֹמֵר קַדִּישׁ. מָה יַעֲשֶׂה?",["לֹא יַעֲנֶה, כִּי הוּא אֵינוֹ בְּתוֹךְ בֵּית הַכְּנֶסֶת","יַעֲנֶה רַק אִם יִרְאֶה אֶת הַחַזָּן בְּעֵינָיו","יַעֲנֶה עִם הַצִּבּוּר, אַף שֶׁהוּא בְּחֶדֶר אַחֵר","יַמְתִּין שֶׁיִּגָּמֵר הַקַּדִּישׁ וְאָז יִכָּנֵס לְהִתְפַּלֵּל"],2,"מִי שֶׁשּׁוֹמֵעַ קַדִּישׁ וּקְדֻשָּׁה יַעֲנֶה עִמָּהֶם, אֲפִלּוּ בְּחֶדֶר אַחֵר אוֹ מִחוּץ לְבֵית הַכְּנֶסֶת.","פֶּרֶק ט׳, הֲלָכָה י׳","מִנְיַן עֲשָׂרָה"],["אֶחָד מֵהָעֲשָׂרָה בְּאֶמְצַע שְׁמוֹנֶה עֶשְׂרֵה וְאֵינוֹ יָכוֹל לַעֲנוֹת. מוּתָּר לוֹמַר קַדִּישׁ?",["מֻתָּר, כִּי הַשְּׁכִינָה שׁוֹרָה בְּכָל מָקוֹם שֶׁיֵּשׁ עֲשָׂרָה","אָסוּר, כִּי צָרִיךְ שֶׁכָּל הָעֲשָׂרָה יַעֲנוּ אָמֵן","מֻתָּר רַק אִם הוּא יַפְסִיק אֶת תְּפִלָּתוֹ וְיַעֲנֶה","אָסוּר, וּצְרִיכִים לְחַכּוֹת עַד שֶׁכֻּלָּם יְסַיְּמוּ לְגַמְרֵי"],0,"מֻתָּר לְצָרְפוֹ, כִּי הַשְּׁכִינָה שׁוֹרָה בְּכָל מָקוֹם שֶׁיֵּשׁ עֲשָׂרָה. רַק בַּחֲזָרַת הַשַּׁ״ץ צְרִיכִים שֶׁכֻּלָּם יַעֲנוּ, וְרָאוּי לְהַמְתִּין לָעֲשִׂירִי.","פֶּרֶק ט׳, הֲלָכָה י״א","מִנְיַן עֲשָׂרָה"],["מַדּוּעַ תִּקְּנוּ חֲכָמִים שֶׁכָּל יִשְׂרָאֵל יִטְּלוּ יָדַיִם גַּם לִפְנֵי אֲכִילַת חֻלִּין?",["כְּדֵי שֶׁהַלֶּחֶם יִהְיֶה טָעִים יוֹתֵר בַּסְּעוּדָה","כְּדֵי לְהַרְגִּיל אֶת הַכֹּהֲנִים לִטֹּל לִפְנֵי אֲכִילַת תְּרוּמָה","כִּי מֵי הַנְּטִילָה מְרַפְּאִים אֶת כָּל הַגּוּף","כְּדֵי לְהַרְאוֹת לַחֲבֵרִים שֶׁאָנוּ שׁוֹמְרִים מְאֹד עַל נִקָּיוֹן"],1,"חֲכָמִים תִּקְּנוּ זֹאת כְּדֵי לְהַרְגִּיל אֶת הַכֹּהֲנִים לִטֹּל לִפְנֵי תְּרוּמָה, וְלֹא בִּטְּלוּ זֹאת כְּדֵי שֶׁנִּהְיֶה רְגִילִים כְּשֶׁיִּבָּנֶה הַמִּקְדָּשׁ.","פֶּרֶק כ״ב, הֲלָכָה א׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["מָה זוֹכֶה מִי שֶׁנּוֹטֵל יָדַיִם בְּשֶׁפַע, יוֹתֵר מֵרְבִיעִית?",["נִזְכֶּה לַאֲרִיכוּת יָמִים וּלְבָרִיאוּת טוֹבָה","נִזְכֶּה לְחָכְמָה רַבָּה וּלְהַצְלָחָה בַּלִּמּוּדִים","נִזְכֶּה לְעֹשֶׁר, כְּמוֹ שֶׁאָמַר רַב חִסְדָּא","נִזְכֶּה שֶׁהָאֹכֶל יַסְפִּיק לָנוּ לְכָל הַשָּׁבוּעַ"],2,"רַב חִסְדָּא אָמַר: ״אֲנִי נָטַלְתִּי יָדַי מְלוֹא חָפְנַיִם מַיִם, וְנָתְנוּ לִי מְלוֹא חָפְנֵי טוֹבָה״.","פֶּרֶק כ״ב, הֲלָכָה ב׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["לְיֶלֶד יֵשׁ תַּחְבֹּשֶׁת שֶׁמְּכַסָּה אֶת רֹב הַיָּד. מָה יַעֲשֶׂה כְּשֶׁהוּא רוֹצֶה לֶאֱכֹל לֶחֶם?",["יוֹרִיד אֶת הַתַּחְבֹּשֶׁת לְרֶגַע וְיִטֹּל אֶת כָּל הַיָּד","יִשְׁפֹּךְ מַיִם עַל הַתַּחְבֹּשֶׁת עַצְמָהּ וִיבָרֵךְ כָּרָגִיל","לֹא יֹאכַל לֶחֶם כְּלָל עַד שֶׁתַּחְלִים הַיָּד","יִכְרֹךְ אֶת יָדוֹ בְּמַפָּה נְקִיָּה וְיֹאכַל בְּלִי לָגַעַת בַּלֶּחֶם"],3,"תַּחְבֹּשֶׁת עַל מִעוּט הַיָּד אֵינָהּ חוֹצֶצֶת, אֲבָל אִם הִיא עַל רֹב הַיָּד – יִכְרֹךְ אֶת יָדוֹ בְּמַפָּה נְקִיָּה וְיֹאכַל בְּלִי לָגַעַת בַּלֶּחֶם.","פֶּרֶק כ״ב, הֲלָכָה ג׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["יֵשׁ כֶּתֶם צֶבַע עַל חֵלֶק קָטָן מֵהַיָּד. מָה הַדִּין בַּנְּטִילָה?",["חוֹצֵץ, כִּי רֹב בְּנֵי הָאָדָם מַקְפִּידִים לְהָסִיר צֶבַע","אֵינוֹ חוֹצֵץ, כִּי הוּא רַק עַל מִעוּט הַיָּד","חוֹצֵץ רַק אִם הַצֶּבַע עֲדַיִן רָטֹב וְדָבִיק","אֵינוֹ חוֹצֵץ, אִם נוֹטְלִים שָׁלֹשׁ פְּעָמִים בְּכָל יָד"],0,"צֶבַע וְסִיד חוֹצְצִים אֲפִלּוּ עַל מִעוּט הַיָּד, מִפְּנֵי שֶׁרֹב בְּנֵי הָאָדָם מַקְפִּידִים לְהָסִירָם (חוּץ מִמִּי שֶׁאֵין דַּרְכּוֹ לְהַקְפִּיד, כְּמוֹ צַבָּע).","פֶּרֶק כ״ב, הֲלָכָה ג׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["מָה הַדִּין בִּנְטִילַת יָדַיִם יְשִׁירוֹת מֵהַבֶּרֶז?",["כְּשֵׁרָה לְכַתְּחִלָּה, וְזוֹ הַדֶּרֶךְ הַטּוֹבָה בְּיוֹתֵר לִטֹּל","כְּשֵׁרָה בִּשְׁעַת הַדְּחָק, אִם פּוֹתְחִים וְסוֹגְרִים לְכָל יָד","פְּסוּלָה תָּמִיד, גַּם כְּשֶׁאֵין שׁוּם כְּלִי בַּבַּיִת","כְּשֵׁרָה רַק אִם הַמַּיִם מֵהַבֶּרֶז חַמִּים מְאֹד מְאֹד"],1,"לֹא טוֹב עוֹשִׂים הַנּוֹטְלִים מֵהַבֶּרֶז, וְסוֹמְכִים עַל זֶה רַק בִּשְׁעַת הַדְּחָק – וּבִתְנַאי שֶׁפּוֹתְחִים וְסוֹגְרִים אֶת הַבֶּרֶז עֲבוּר כָּל יָד.","פֶּרֶק כ״ב, הֲלָכָה ח׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["לְמִישֶׁהוּ יֵשׁ רַק מַיִם שֶׁהַצֶּבַע שֶׁלָּהֶם הִשְׁתַּנָּה. מָה יַעֲשֶׂה?",["יִטֹּל בָּהֶם וִיבָרֵךְ כְּמוֹ בְּמַיִם רְגִילִים","לֹא יִטֹּל כְּלָל וְיֹאכַל בְּלִי נְטִילָה","יְחַכֶּה עַד שֶׁהַמַּיִם יַחְזְרוּ לִהְיוֹת צְלוּלִים","יִטֹּל בַּמַּיִם הָאֵלֶּה, אֲבָל לֹא יְבָרֵךְ"],3,"מַיִם שֶׁמַּרְאֵיהֶם הִשְׁתַּנָּה נִפְסְלוּ לִנְטִילָה, וּמִי שֶׁאֵין לוֹ מַיִם אֲחֵרִים – יִטֹּל בָּהֶם בְּלֹא בְּרָכָה.","פֶּרֶק כ״ב, הֲלָכָה ט׳","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["מִי שֶׁאוֹכֵל לֶחֶם יוֹתֵר מִכְּזַיִת אֲבָל פָּחוֹת מִכְּבֵיצָה – מָה דִּינוֹ?",["יִטֹּל אֶת יָדָיו, אֲבָל לֹא יְבָרֵךְ","יִטֹּל אֶת יָדָיו וִיבָרֵךְ עַל נְטִילַת יָדַיִם","אֵינוֹ צָרִיךְ לִטֹּל אֶת יָדָיו בִּכְלָל","יְנַגֵּב אֶת יָדָיו בְּמַגֶּבֶת נְקִיָּה בִּלְבַד"],0,"מִי שֶׁאוֹכֵל פָּחוֹת מִכְּבֵיצָה (56 סמ״ק, כִּשְׁתֵּי פְּרוּסוֹת דַּקּוֹת) – יִטֹּל יָדָיו וְלֹא יְבָרֵךְ.","פֶּרֶק כ״ב, הֲלָכָה י״ב","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["מָה עוֹשִׂים הַמְדַקְדְּקִים בְּמִצְווֹת כְּשֶׁהֵם אוֹכְלִים לֶחֶם?",["אוֹכְלִים תָּמִיד פָּחוֹת מִכְּזַיִת, כְּדֵי לֹא לְהִתְחַיֵּב בִּנְטִילָה","נוֹטְלִים יָדַיִם רַק אַחֲרֵי שֶׁסִּיְּמוּ לֶאֱכֹל אֶת הַלֶּחֶם","מַקְפִּידִים לֶאֱכֹל כְּבֵיצָה לֶחֶם כְּדֵי לְבָרֵךְ לְפִי כָּל הַדֵּעוֹת","מְבָרְכִים עַל הַנְּטִילָה פַּעֲמַיִם, לִפְנֵי וְאַחֲרֵי הַסְּעוּדָה"],2,"הַמְדַקְדְּקִים מַקְפִּידִים לֶאֱכֹל לֶחֶם בְּשִׁעוּר כְּבֵיצָה, וְכָךְ יְכוֹלִים לִטֹּל וּלְבָרֵךְ לְפִי כָּל הַדֵּעוֹת.","פֶּרֶק כ״ב, הֲלָכָה י״ב","נְטִילַת יָדַיִם לִפְנֵי הַסְּעוּדָה"],["מָה הַכַּוָּנָה בַּמִּלִּים ״מַרְבִּים בְּשִׂמְחָה״ בְּחֹדֶשׁ אֲדָר?",["לַעֲשׂוֹת כָּל מָה שֶׁרוֹצִים בְּלִי שׁוּם גְּבוּל","לְהַרְבּוֹת בְּמִשְׂחָקִים וּבִצְחוֹק בִּמְקוֹם תְּפִלָּה וְלִמּוּד","שִׂמְחָה שֶׁל מִצְוָה וְשֶׁבַח לַה׳ עַל הַנֵּס","לִשְׂמֹחַ רַק בְּיוֹם הַפּוּרִים עַצְמוֹ וְלֹא לְפָנָיו"],2,"מִשֶּׁנִּכְנַס אֲדָר מַרְבִּים בְּשִׂמְחָה שֶׁל מִצְוָה וְשֶׁבַח לַה׳ עַל הַנֵּס, וְלֹא בְּהוֹלֵלוּת וְהֶפְקֵרוּת.","פֶּרֶק צ״ב, הֲלָכָה א׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["הַאִם עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה חַיָּב בְּמַחֲצִית הַשֶּׁקֶל?",["כֵּן, שֶׁנֶּאֱמַר ״וְהַדַּל לֹא יַמְעִיט״","לֹא, כִּי אֵין לוֹ כֶּסֶף מִשֶּׁלּוֹ","רַק אִם הוּא מְקַבֵּל הַרְבֵּה צְדָקָה","הוּא נוֹתֵן רֶבַע שֶׁקֶל בִּלְבַד"],0,"אֲפִלּוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה חַיָּב, שֶׁנֶּאֱמַר: ״הֶעָשִׁיר לֹא יַרְבֶּה וְהַדַּל לֹא יַמְעִיט״.","פֶּרֶק צ״ב, הֲלָכָה ב׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["לָמָּה מַשְׁמִיעִים עַל הַשְּׁקָלִים דַּוְקָא בְּאֶחָד בַּאֲדָר?",["כִּי בַּאֲדָר יֵשׁ לָאֲנָשִׁים הַרְבֵּה כֶּסֶף פָּנוּי","כִּי בַּאֲדָר נִבְנָה בֵּית הַמִּקְדָּשׁ הָרִאשׁוֹן","כִּי בַּאֲדָר מַתְחִילִים לְהַקְרִיב אֶת הַקָּרְבָּנוֹת","שֶׁשִּׁקְלֵי יִשְׂרָאֵל יַקְדִּימוּ אֶת שִׁקְלֵי הָמָן הָרָשָׁע"],3,"הַקָּדוֹשׁ בָּרוּךְ הוּא יָדַע שֶׁהָמָן יִשְׁקֹל עֲשֶׂרֶת אֲלָפִים כִּכַּר כֶּסֶף לַאֲחַשְׁוֵרוֹשׁ, וְהִקְדִּים אֶת שִׁקְלֵי יִשְׂרָאֵל כְּדֵי שֶׁיְּכַפְּרוּ עֲלֵיהֶם.","פֶּרֶק צ״ב, הֲלָכָה ג׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["כְּשֶׁרֹאשׁ חֹדֶשׁ אֲדָר חָל בְּשַׁבָּת, מָה קוֹרְאִים בְּסֵפֶר הַתּוֹרָה הַשְּׁלִישִׁי?",["אֶת פָּרָשַׁת הַשָּׁבוּעַ שֶׁל אוֹתָהּ שַׁבָּת","אֶת פָּרָשַׁת שְׁקָלִים מִתְּחִלַּת ״כִּי תִשָּׂא״","אֶת הַקְּרִיאָה הַמְיֻחֶדֶת שֶׁל רֹאשׁ חֹדֶשׁ","אֶת פָּרָשַׁת זָכוֹר שֶׁל לִפְנֵי פּוּרִים"],1,"בָּרִאשׁוֹן קוֹרְאִים אֶת פָּרָשַׁת הַשָּׁבוּעַ, בַּשֵּׁנִי אֶת קְרִיאַת רֹאשׁ חֹדֶשׁ וּבַשְּׁלִישִׁי אֶת פָּרָשַׁת שְׁקָלִים.","פֶּרֶק צ״ב, הֲלָכָה ד׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["מָתַי נוֹהֲגִים לָתֵת ״זֵכֶר לְמַחֲצִית הַשֶּׁקֶל״?",["בְּרֹאשׁ חֹדֶשׁ נִיסָן, לִפְנֵי חַג הַפֶּסַח","בַּחֲנֻכָּה, בְּיַחַד עִם דְּמֵי חֲנֻכָּה","בְּתַעֲנִית אֶסְתֵּר, וְיֵשׁ נוֹהֲגִים לָתֵת בְּפוּרִים","בְּט״ו בִּשְׁבָט, כְּשֶׁאוֹכְלִים פֵּרוֹת הָאָרֶץ"],2,"נוֹהֲגִים לָתֵת ״זֵכֶר לְמַחֲצִית הַשֶּׁקֶל״ בְּתַעֲנִית אֶסְתֵּר, וְיֵשׁ נוֹהֲגִים לָתֵת בְּפוּרִים.","פֶּרֶק צ״ב, הֲלָכָה ה׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["לָמָּה אָסוּר לוֹמַר שֶׁנּוֹתְנִים אֶת הַכֶּסֶף ״כְּמַחֲצִית הַשֶּׁקֶל״?",["כִּי זֶה שֶׁקֶר, הַסְּכוּם קָטָן מִדַּי","כִּי אָסוּר לְהַזְכִּיר אֶת הַמִּקְדָּשׁ בְּפוּרִים","כִּי אָז צָרִיךְ לָתֵת אֶת הַכֶּסֶף לַכֹּהֵן","כִּי אָז הַכֶּסֶף נֶאֱסָר כְּכֶסֶף הַקֳּדָשִׁים"],3,"אִם אוֹמְרִים ״מַחֲצִית הַשֶּׁקֶל״ הַכֶּסֶף נֶאֱסָר לְשִׁמּוּשׁ כְּכֶסֶף הַקֳּדָשִׁים, וְלָכֵן אוֹמְרִים ״זֵכֶר לְמַחֲצִית הַשֶּׁקֶל״.","פֶּרֶק צ״ב, הֲלָכָה ו׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["מִי שֶׁאֵין בִּיכָלְתּוֹ לָתֵת אֶת הַסְּכוּם שֶׁל הַמְּהַדְּרִים, מָה יִתֵּן?",["הוּא פָּטוּר לְגַמְרֵי וְאֵינוֹ נוֹתֵן כְּלוּם","מַחֲצִית מֵהַמַּטְבֵּעַ הַנָּהוּג בִּמְקוֹמוֹ, כְּמוֹ חֲצִי ש״ח","יִלְוֶה כֶּסֶף מֵחֲבֵרָיו וְיִתֵּן אֶת הַסְּכוּם","יִתֵּן אֶת הַכֶּסֶף רַק בְּשָׁנָה הַבָּאָה"],1,"יִתֵּן מַחֲצִית מֵהַמַּטְבֵּעַ הַנָּהוּג בִּמְקוֹמוֹ, שֶׁהֲרֵי נְתִינָה זוֹ הִיא זֵכֶר לַמִּצְוָה וְלֹא קִיּוּם הַמִּצְוָה עַצְמָהּ.","פֶּרֶק צ״ב, הֲלָכָה ח׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם, מָה דִּין נָשִׁים בְּמַחֲצִית הַשֶּׁקֶל?",["חַיָּבוֹת לָתֵת מַחֲצִית שֶׁקֶל כְּמוֹ הָאֲנָשִׁים","חַיָּבוֹת לָתֵת שֶׁקֶל שָׁלֵם בְּכָל שָׁנָה","אֵינָן חַיָּבוֹת, וּבְיָמֵינוּ נוֹתְנִים זֵכֶר גַּם עֲבוּרָן","חַיָּבוֹת רַק מִגִּיל עֶשְׂרִים שָׁנָה וָמַעְלָה"],2,"נָשִׁים וִילָדִים קְטַנִּים אֵינָם חַיָּבִים בַּמִּצְוָה, וּבְיָמֵינוּ נוֹהֲגִים לָתֵת ״זֵכֶר לְמַחֲצִית הַשֶּׁקֶל״ עֲבוּר כָּל בְּנֵי וּבְנוֹת הַמִּשְׁפָּחָה.","פֶּרֶק צ״ב, הֲלָכָה ט׳","חֹדֶשׁ אֲדָר וּמַחֲצִית הַשֶּׁקֶל"],["מַדּוּעַ קוֹרְאִים אֶת פָּרָשַׁת זָכוֹר דַּוְקָא בַּשַּׁבָּת שֶׁלִּפְנֵי פּוּרִים?",["כִּי בְּשַׁבָּת זוֹ יָצְאוּ מִמִּצְרַיִם לְפִי הַמָּסֹרֶת","כִּי אָז מַתְחִילִים לְהָכִין אֶת מַטְבְּעוֹת הַשְּׁקָלִים","כִּי הָמָן הָיָה מִזַּרְעוֹ שֶׁל עֲמָלֵק","כִּי אֶסְתֵּר קָרְאָה אוֹתָהּ לַמֶּלֶךְ בְּשַׁבָּת"],2,"מִפְּנֵי שֶׁהָמָן הָיָה מִזַּרְעוֹ שֶׁל עֲמָלֵק, תִּקְּנוּ חֲכָמִים לְקַיֵּם אֶת מִצְוַת זְכִירַת עֲמָלֵק בַּשַּׁבָּת שֶׁלִּפְנֵי פּוּרִים.","פֶּרֶק צ״ב, הֲלָכָה י׳","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["מָה צְרִיכִים לְכַוֵּן בִּשְׁעַת קְרִיאַת פָּרָשַׁת זָכוֹר?",["הַקּוֹרֵא מְכַוֵּן לְהוֹצִיא, וְהַשּׁוֹמְעִים מְכַוְּנִים לָצֵאת","רַק הַקּוֹרֵא צָרִיךְ לְכַוֵּן, הַשּׁוֹמְעִים פְּטוּרִים","רַק הַשּׁוֹמְעִים מְכַוְּנִים, הַקּוֹרֵא אֵינוֹ צָרִיךְ לְכַוֵּן","אֵין צֹרֶךְ בְּכַוָּנָה, מַסְפִּיק לִשְׁמֹעַ אֶת הַמִּלִּים"],0,"בִּקְרִיאָה זוֹ מְקַיְּמִים מִצְוָה מִן הַתּוֹרָה, וְלָכֵן הַקּוֹרֵא יְכַוֵּן לְהוֹצִיא אֶת הַשּׁוֹמְעִים, וְהַשּׁוֹמְעִים יְכַוְּנוּ לָצֵאת יְדֵי חוֹבָתָם.","פֶּרֶק צ״ב, הֲלָכָה י״א","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["מָה הַדִּין לְגַבֵּי חִיּוּב נָשִׁים לִשְׁמֹעַ אֶת פָּרָשַׁת זָכוֹר?",["כֻּלָּם מַסְכִּימִים שֶׁנָּשִׁים פְּטוּרוֹת לְגַמְרֵי מִלִּשְׁמֹעַ","נָשִׁים חַיָּבוֹת לִקְרֹא בְּעַצְמָן מִתּוֹךְ סֵפֶר תּוֹרָה","נָשִׁים שׁוֹמְעוֹת רַק אִם הַשַּׁבָּת חָלָה בְּפוּרִים","יֵשׁ אוֹמְרִים שֶׁחַיָּבוֹת, וְיֵשׁ אוֹמְרִים שֶׁאֵינָן חַיָּבוֹת"],3,"יֵשׁ אוֹמְרִים שֶׁנָּשִׁים חַיָּבוֹת וְיֵשׁ אוֹמְרִים שֶׁאֵינָן חַיָּבוֹת, וּבִקְהִלּוֹת רַבּוֹת נוֹהֲגוֹת הַנָּשִׁים לָבוֹא לִשְׁמֹעַ.","פֶּרֶק צ״ב, הֲלָכָה י״ב","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["בְּמָה עוֹסֵק רֹב הַפִּיּוּט ״מִי כָמוֹךָ וְאֵין כָּמוֹךָ״?",["בְּדִינֵי מִשְׁלוֹחַ מָנוֹת וּמַתָּנוֹת לָאֶבְיוֹנִים בְּפוּרִים","בְּסִפּוּר הַמְּגִלָּה, בְּחֶלְקֵי פְּסוּקִים וּבְרַעְיוֹנוֹת מֵהַמִּדְרָשִׁים","בְּסִפּוּר קְרִיעַת יַם סוּף וְשִׁירַת מֹשֶׁה רַבֵּנוּ","בְּשִׁבְחֵי אֶרֶץ יִשְׂרָאֵל וּבְבִנְיַן בֵּית הַמִּקְדָּשׁ"],1,"רֹב הַפִּיּוּט עוֹסֵק בְּסִפּוּר הַמְּגִלָּה, תּוֹךְ שִׁמּוּשׁ בְּחֶלְקֵי פְּסוּקִים מִכָּל הַתָּנָ״ךְ וּבְשִׁלּוּב רַעְיוֹנוֹת מֵהַמִּדְרָשִׁים.","פֶּרֶק צ״ב, הֲלָכָה י״ג","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["לְפִי הַטַּעַם הַשֵּׁנִי, מַדּוּעַ הִתְעַנּוּ הַיְּהוּדִים בְּי״ג בַּאֲדָר?",["כִּי בְּיוֹם זֶה נִתְלָה הָמָן עַל הָעֵץ","כִּי בְּיוֹם זֶה הִכְתִּירוּ אֶת אֶסְתֵּר לְמַלְכָּה","כִּי בְּיוֹם זֶה נִלְחֲמוּ הַיְּהוּדִים בְּאוֹיְבֵיהֶם וְהִתְפַּלְּלוּ","כִּי בְּיוֹם זֶה נִבְנָה בֵּית הַמִּקְדָּשׁ הַשֵּׁנִי"],2,"בְּי״ג בַּאֲדָר נִלְחֲמוּ הַיְּהוּדִים בְּאוֹיְבֵיהֶם, וּמִי שֶׁלֹּא הִשְׁתַּתֵּף בַּמִּלְחָמָה הִתְעַנָּה וְהִתְפַּלֵּל.","פֶּרֶק צ״ב, הֲלָכָה י״ד","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["מִי מֵאֵלֶּה יָכוֹל לְהָקֵל וְלֹא לְהִתְעַנּוֹת בְּתַעֲנִית אֶסְתֵּר?",["רַק חוֹלֶה שֶׁיֵּשׁ בּוֹ סַכָּנָה מַמָּשִׁית","כָּל מִי שֶׁקָּשֶׁה לוֹ לְהִתְעַנּוֹת","חוֹלֶה, אֲפִלּוּ אִם אֵין בּוֹ סַכָּנָה","אִישׁ בָּרִיא שֶׁרוֹצֶה לְהַרְגִּישׁ טוֹב"],2,"חוֹלִים, אֲפִלּוּ אִם אֵין בָּהֶם סַכָּנָה, יְכוֹלִים לְהָקֵל בְּתַעֲנִית זוֹ. אֲבָל הַבְּרִיאִים יִתְעַנּוּ וְלֹא יִפְרְשׁוּ מִן הַצִּבּוּר.","פֶּרֶק צ״ב, הֲלָכָה ט״ו","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["מִי מִבַּעֲלֵי הַבְּרִית פָּטוּר מִתַּעֲנִית אֶסְתֵּר?",["כָּל הָאוֹרְחִים שֶׁהִגִּיעוּ לִסְעוּדַת הַבְּרִית","רַק הַתִּינוֹק וּבְנֵי מִשְׁפַּחְתּוֹ הַקְּרוֹבִים","הַחַזָּן וְהַגַּבַּאי שֶׁל בֵּית הַכְּנֶסֶת","אֲבִי הַבֵּן, הַסַּנְדָּק וְהַמּוֹהֵל בְּיוֹם הַבְּרִית"],3,"בַּעֲלֵי בְּרִית – אֲבִי הַבֵּן, הַסַּנְדָּק וְהַמּוֹהֵל – פְּטוּרִים מִן הַתַּעֲנִית. וְכֵן חָתָן וְכַלָּה בְּשִׁבְעַת יְמֵי חֻפָּתָם.","פֶּרֶק צ״ב, הֲלָכָה ט״ז","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["מַדּוּעַ בְּשָׁנָה מְעֻבֶּרֶת חוֹגְגִים אֶת פּוּרִים בַּאֲדָר הַשֵּׁנִי?",["כִּי בַּאֲדָר הָרִאשׁוֹן אָסוּר לִשְׂמֹחַ כְּלָל","כְּדֵי לִסְמֹךְ גְּאֻלַּת פּוּרִים לִגְאֻלַּת מִצְרַיִם","כְּדֵי שֶׁיִּהְיֶה זְמַן לְהָכִין מִשְׁלוֹחֵי מָנוֹת","כִּי הָמָן הִפִּיל אֶת הַפּוּר בַּאֲדָר הַשֵּׁנִי"],1,"מְקַיְּמִים אֶת יְמֵי הַפּוּרִים בַּאֲדָר הַשֵּׁנִי כְּדֵי לִסְמֹךְ אֶת הַשִּׂמְחָה עַל גְּאֻלַּת פּוּרִים לִגְאֻלַּת מִצְרַיִם.","פֶּרֶק צ״ב, הֲלָכָה י״ז","חֹדֶשׁ אֲדָר – פָּרָשַׁת זָכוֹר וְתַעֲנִית אֶסְתֵּר"],["מָה הַזְּמַן שֶׁל קְרִיאַת הַמְּגִלָּה בַּיּוֹם?",["רַק בְּשָׁעָה הָרִאשׁוֹנָה שֶׁל הַבֹּקֶר","רַק אַחֲרֵי שֶׁיּוֹצְאִים הַכּוֹכָבִים בָּעֶרֶב","מֵהָנֵץ הַחַמָּה וְעַד סוֹף הַיּוֹם","רַק בִּשְׁעוֹת הַצָּהֳרַיִם, אַחֲרֵי הַסְּעוּדָה"],2,"זְמַן קְרִיאַת הַיּוֹם מֵהָנֵץ הַחַמָּה עַד סוֹף הַיּוֹם, וּמִי שֶׁקָּרָא אַחֲרֵי עֲלוֹת הַשַּׁחַר יָצָא.","פֶּרֶק צ״ג, הֲלָכָה א׳","קְרִיאַת הַמְּגִלָּה"],["לָמָּה גַּם תַּלְמִידֵי חֲכָמִים מְבַטְּלִים שִׁעוּר וּבָאִים לְבֵית הַכְּנֶסֶת?",["כִּי אָסוּר לִלְמֹד תּוֹרָה כְּלָל בְּיוֹם פּוּרִים","כִּי בְּבֵית הַכְּנֶסֶת מְחַלְּקִים מִשְׁלוֹחַ מָנוֹת לְכֻלָּם","כִּי הָרַב שֶׁלָּהֶם הוֹלֵךְ לַמְּסִבָּה בְּבֵית הַכְּנֶסֶת","כִּי בְּרֹב עָם הַדְרַת מֶלֶךְ, וְהַנֵּס מִתְפַּרְסֵם"],3,"עִקַּר הַמִּצְוָה בְּצִבּוּר, כִּי ״בְּרֹב עָם הַדְרַת מֶלֶךְ״ וְהַנֵּס מִתְפַּרְסֵם בְּיוֹתֵר.","פֶּרֶק צ״ג, הֲלָכָה ב׳","קְרִיאַת הַמְּגִלָּה"],["מָה הַדִּין שֶׁל מְגִלָּה מֻדְפֶּסֶת עַל קְלָף?",["הִיא פְּסוּלָה, וְאָסוּר לְהַדְפִּיס מְגִלָּה עַל קְלָף","הִיא כְּשֵׁרָה, כִּי הִיא עַל קְלָף","הִיא כְּשֵׁרָה רַק בִּשְׁבִיל קְרִיאַת הַלַּיְלָה","הִיא כְּשֵׁרָה אִם הַדְּיוֹ שֶׁלָּהּ שָׁחֹר"],0,"מְגִלָּה מֻדְפֶּסֶת פְּסוּלָה אֲפִלּוּ עַל קְלָף, וְאָסוּר לְהַדְפִּיס כָּךְ כְּדֵי שֶׁלֹּא יִטְעוּ שֶׁהִיא כְּשֵׁרָה.","פֶּרֶק צ״ג, הֲלָכָה ג׳","קְרִיאַת הַמְּגִלָּה"],["מָתַי מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ עַל הַמְּגִלָּה בִּקְהִלּוֹת הַסְּפָרַדִּים?",["רַק בִּקְרִיאַת הַיּוֹם, וְלֹא בַּלַּיְלָה","רַק בִּקְרִיאַת הַלַּיְלָה, וְלֹא בַּיּוֹם","גַּם בַּלַּיְלָה וְגַם בַּיּוֹם, פַּעֲמַיִם","אֵינָם מְבָרְכִים שֶׁהֶחֱיָנוּ עַל הַמְּגִלָּה כְּלָל"],1,"הַסְּפָרַדִּים מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ רַק בַּלַּיְלָה, וְהָאַשְׁכְּנַזִּים גַּם בַּיּוֹם.","פֶּרֶק צ״ג, הֲלָכָה ד׳","קְרִיאַת הַמְּגִלָּה"],["מָה עוֹשֶׂה הַקּוֹרֵא מִיָּד כְּשֶׁהוּא גּוֹמֵר לִקְרֹא?",["מְבָרֵךְ שֶׁהֶחֱיָנוּ וּמַשְׁאִיר אֶת הַמְּגִלָּה פְּתוּחָה","מְנַשֵּׁק אֶת הַמְּגִלָּה וְהוֹלֵךְ מִיָּד הַבַּיְתָה","גּוֹלֵל אֶת הַמְּגִלָּה וּמְבָרֵךְ הָרָב אֶת רִיבֵנוּ","מַתְחִיל לִקְרֹא שׁוּב אֶת הַמְּגִלָּה מֵהַהַתְחָלָה"],2,"אַחֲרֵי הַקְּרִיאָה גּוֹלֵל הַקּוֹרֵא אֶת הַמְּגִלָּה וּמְבָרֵךְ ״הָרָב אֶת רִיבֵנוּ״.","פֶּרֶק צ״ג, הֲלָכָה ה׳","קְרִיאַת הַמְּגִלָּה"],["בִּקְהִלּוֹת הַסְּפָרַדִּים, עַל מִי אוֹמְרִים בְּסוֹף הַקְּרִיאָה ״זָכוּר לַטּוֹב״?",["זֶרֶשׁ, שֶׁאוֹמְרִים עָלֶיהָ זְכוּרָה לַטּוֹב","אֲחַשְׁוֵרוֹשׁ הַמֶּלֶךְ, שֶׁאוֹמְרִים עָלָיו זָכוּר לַטּוֹב","הָמָן הָרָשָׁע, שֶׁאוֹמְרִים עָלָיו זָכוּר לַטּוֹב","חַרְבוֹנָה, שֶׁאוֹמְרִים עָלָיו זָכוּר לַטּוֹב"],3,"בְּסִיּוּם הַקְּרִיאָה אוֹמְרִים הַסְּפָרַדִּים: ״וְגַם חַרְבוֹנָה זָכוּר לַטּוֹב״.","פֶּרֶק צ״ג, הֲלָכָה ו׳","קְרִיאַת הַמְּגִלָּה"],["מָה מוֹסִיפִים הָאַשְׁכְּנַזִּים בְּלֵיל פּוּרִים אַחֲרֵי הַמְּגִלָּה?",["אֶת הַפִּיּוּט אֲשֶׁר הֵנִיא, וּמְסַיְּמִים שׁוֹשַׁנַּת יַעֲקֹב","אֶת הַפִּיּוּט לְכָה דוֹדִי, וּמְסַיְּמִים אֲדוֹן עוֹלָם","אֶת הַהַלֵּל הַשָּׁלֵם, וּמְסַיְּמִים בְּקַדִּישׁ יָתוֹם","אֶת שִׁירַת הַיָּם, וּמְסַיְּמִים בִּתְקִיעַת שׁוֹפָר"],0,"בְּלֵיל פּוּרִים מוֹסִיפִים הָאַשְׁכְּנַזִּים ״אֲשֶׁר הֵנִיא״ וּמְסַיְּמִים ״שׁוֹשַׁנַּת יַעֲקֹב״.","פֶּרֶק צ״ג, הֲלָכָה ז׳","קְרִיאַת הַמְּגִלָּה"],["לָמָּה שְׁלִיחַ הַצִּבּוּר קוֹרֵא אֶת הַמְּגִלָּה בַּעֲמִידָה?",["כִּי אָסוּר לִקְרֹא מְגִלָּה בִּישִׁיבָה לְעוֹלָם","מִפְּנֵי כְּבוֹד הַצִּבּוּר שֶׁבְּבֵית הַכְּנֶסֶת","כְּדֵי שֶׁיִּרְאוּ אוֹתוֹ טוֹב מִכָּל הַמְּקוֹמוֹת","כִּי הַמְּגִלָּה כְּבֵדָה וְקָשֶׁה לְהַחְזִיק אוֹתָהּ"],1,"מֻתָּר לִקְרֹא גַּם בִּישִׁיבָה, אֲבָל שְׁלִיחַ הַצִּבּוּר עוֹמֵד מִפְּנֵי כְּבוֹד הַצִּבּוּר.","פֶּרֶק צ״ג, הֲלָכָה ח׳","קְרִיאַת הַמְּגִלָּה"],["לָמָּה פּוֹרְשִׂים אֶת כָּל הַמְּגִלָּה לִפְנֵי הַבְּרָכוֹת?",["כְּדֵי לִבְדֹּק שֶׁאֵין אָבָק עַל הַקְּלָף","כְּדֵי שֶׁהַקּוֹרֵא יִזְכֹּר מָתַי לְהַפְסִיק","כְּדֵי שֶׁהַמְּגִלָּה תִּהְיֶה פְּרוּשָׂה כְּמוֹ אִגֶּרֶת","כְּדֵי שֶׁהַצִּבּוּר יִרְאֶה אֶת הַקְּלָף מֵרָחוֹק"],2,"בַּעַל הַקּוֹרֵא פּוֹשֵׁט אֶת כָּל הַמְּגִלָּה כְּדֵי שֶׁתִּהְיֶה כְּאִגֶּרֶת, וְרַק אָז מְבָרֵךְ וְקוֹרֵא.","פֶּרֶק צ״ג, הֲלָכָה ט׳","קְרִיאַת הַמְּגִלָּה"],["מִי מוֹצִיא אֶת הַשּׁוֹמְעִים יְדֵי חוֹבָתָם בִּקְרִיאַת הַמְּגִלָּה?",["כָּל מִי שֶׁקּוֹרֵא בְּקוֹל רָם מִתּוֹךְ סֵפֶר","רַק מִי שֶׁיּוֹדֵעַ אֶת כָּל הַמְּגִלָּה בְּעַל פֶּה","מִי שֶׁקּוֹרֵא מִמְּגִלָּה כְּשֵׁרָה וְהוּא חַיָּב בַּקְּרִיאָה","כָּל יֶלֶד שֶׁלּוֹמֵד בְּכִתָּה וּמַכִּיר אֶת הַטְּעָמִים"],2,"הַקּוֹרֵא מִתּוֹךְ מְגִלָּה כְּשֵׁרָה מוֹצִיא אֶת הַשּׁוֹמְעִים, וּבִתְנַאי שֶׁהוּא חַיָּב בִּקְרִיאַת הַמְּגִלָּה.","פֶּרֶק צ״ג, הֲלָכָה י׳","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["מָה הַדִּין אִם הַשּׁוֹמֵעַ לֹא שָׁמַע מִלָּה אַחַת מֵהַמְּגִלָּה?",["יָצָא יְדֵי חוֹבָתוֹ, כִּי מִלָּה אַחַת אֵינָהּ חֲשׁוּבָה","לֹא יָצָא יְדֵי חוֹבָתוֹ, כִּי חָסְרָה לוֹ מִלָּה","יָצָא רַק אִם שָׁמַע אֶת רֹב הַפְּסוּקִים","צָרִיךְ לִשְׁמֹעַ שׁוּב רַק אֶת הַפֶּרֶק הָרִאשׁוֹן"],1,"אִם הַקּוֹרֵא הֶחְסִיר אוֹ הַשּׁוֹמֵעַ לֹא שָׁמַע אֲפִלּוּ מִלָּה אַחַת – לֹא יָצָא יְדֵי חוֹבָתוֹ.","פֶּרֶק צ״ג, הֲלָכָה י״א","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["הָיָה רַעַשׁ בְּבֵית הַכְּנֶסֶת וְלֹא שָׁמַעְתָּ כַּמָּה מִלִּים. מָה עוֹשִׂים?",["מְוַתְּרִים עַל הַמִּלִּים, כִּי לֹא אֲנַחְנוּ אֲשֵׁמִים","מְבַקְּשִׁים מֵהַקּוֹרֵא לְהַתְחִיל אֶת כָּל הַמְּגִלָּה מֵחָדָשׁ","מְחַכִּים לְשָׁנָה הַבָּאָה וְשׁוֹמְעִים אָז בְּיֶתֶר קַשָּׁב","קוֹרְאִים בַּפֶּה אֶת הַמִּלִּים הָאֵלּוּ מִתּוֹךְ הַחֻמָּשׁ"],3,"מִי שֶׁלֹּא שָׁמַע מִלִּים בִּגְלַל רַעַשׁ – קוֹרֵא בְּפִיו אֶת הַמִּלִּים שֶׁלֹּא שָׁמַע מִתּוֹךְ הַחֻמָּשׁ.","פֶּרֶק צ״ג, הֲלָכָה י״ב","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["לָמָּה אוֹמְרִים אֶת שְׁמוֹת עֲשֶׂרֶת בְּנֵי הָמָן בִּנְשִׁימָה אַחַת?",["כְּדֵי שֶׁיֵּדְעוּ שֶׁכֻּלָּם נֶהֶרְגוּ וְנִתְלוּ כְּאֶחָד","כְּדֵי לְסַיֵּם מַהֵר אֶת קְרִיאַת הַמְּגִלָּה","כְּדֵי שֶׁהַיְּלָדִים לֹא יַרְעִישׁוּ בְּאֶמְצַע","כְּדֵי לְהַרְאוֹת שֶׁהַקּוֹרֵא חָזָק וּמְאֹמָּן"],0,"אוֹמְרִים אֶת הַשְּׁמוֹת בִּנְשִׁימָה אַחַת כְּדֵי שֶׁיֵּדְעוּ שֶׁכֻּלָּם נֶהֶרְגוּ וְנִתְלוּ כְּאֶחָד.","פֶּרֶק צ״ג, הֲלָכָה י״ג","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["מָה נוֹהֲגִים לַעֲשׂוֹת בְּאַרְבָּעָה פְּסוּקִים שֶׁל גְּאֻלָּה?",["מְדַלְּגִים עֲלֵיהֶם כְּדֵי שֶׁהַקְּרִיאָה תִּהְיֶה קְצָרָה יוֹתֵר","רַק הַגַּבַּאי קוֹרֵא אוֹתָם בְּשֶׁקֶט גָּמוּר לְיַד הַבִּימָה","כָּל הַצִּבּוּר קוֹרֵא יַחַד, וְאַחַר כָּךְ בַּעַל הַקּוֹרֵא","שָׁרִים אוֹתָם בְּסוֹף הַתְּפִלָּה בְּמַנְגִּינָה מְיֻחֶדֶת וּשְׂמֵחָה"],2,"כָּל הַצִּבּוּר קוֹרֵא יַחַד אַרְבָּעָה פְּסוּקִים שֶׁל גְּאֻלָּה, וְאַחֲרָיו חוֹזֵר עֲלֵיהֶם בַּעַל הַקּוֹרֵא.","פֶּרֶק צ״ג, הֲלָכָה י״ד","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["לָמָּה נָשִׁים חַיָּבוֹת בְּמִקְרָא מְגִלָּה?",["כִּי הֵן אוֹהֲבוֹת לִשְׁמֹעַ סִפּוּרִים יָפִים","כִּי גַּם הֵן נִצְּלוּ, וְהַנֵּס בָּא בְּעֶזְרַת אֶסְתֵּר","כִּי פּוּרִים הוּא חַג שֶׁל מִשְׁלוֹחַ מָנוֹת","כִּי כָּךְ הֶחְלִיט אֲחַשְׁוֵרוֹשׁ הַמֶּלֶךְ בְּשׁוּשַׁן הַבִּירָה"],1,"נָשִׁים חַיָּבוֹת כִּי גַּם הֵן נִצְּלוּ מִגְּזֵרַת הָמָן, וְהַנֵּס הִגִּיעַ בְּעֶזְרַת מְסִירוּת נַפְשָׁהּ שֶׁל אֶסְתֵּר הַמַּלְכָּה. הֵן חַיָּבוֹת גַּם בְּכָל שְׁאָר מִצְווֹת הַפּוּרִים.","פֶּרֶק צ״ג, הֲלָכָה ט״ו","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["מָה הַמִּנְהָג הַטּוֹב לְגַבֵּי יְלָדִים קְטַנִּים בִּקְרִיאַת הַמְּגִלָּה?",["לְהַשְׁאִיר אוֹתָם בַּבַּיִת כְּדֵי שֶׁיִּהְיֶה שֶׁקֶט","לְהָבִיא רַק אֶת הַבָּנִים, וְלֹא אֶת הַבָּנוֹת","לָתֵת לָהֶם לְהַרְעִישׁ כַּמָּה שֶׁהֵם רוֹצִים","לְהָבִיא אוֹתָם, וּלְהַשְׁגִּיחַ שֶׁלֹּא יַפְרִיעוּ לַקְּרִיאָה"],3,"מִנְהָג טוֹב לְהָבִיא אֶת הַקְּטַנִּים וְהַקְּטַנּוֹת לְהַרְגִּילָם בַּמִּצְוָה, אַךְ יֵשׁ לְהַשְׁגִּיחַ שֶׁלֹּא יַפְרִיעוּ.","פֶּרֶק צ״ג, הֲלָכָה ט״ז","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["הַאִם יוֹצְאִים יְדֵי חוֹבָה בִּשְׁמִיעַת מְגִלָּה בָּרַדְיוֹ בְּשִׁדּוּר חַי?",["לֹא, וְכָל שֶׁכֵּן שֶׁלֹּא יוֹצְאִים בְּהַקְלָטָה","כֵּן, כִּי שׁוֹמְעִים אֶת הַקּוֹרֵא בִּזְמַן אֲמִתִּי","כֵּן, אֲבָל רַק אִם הָרַדְיוֹ חָזָק מְאֹד","לֹא, אֲבָל בְּהַקְלָטָה יוֹצְאִים יְדֵי חוֹבָה"],0,"אֵין יוֹצְאִים בְּרַמְקוֹל, רַדְיוֹ אוֹ כָּל אֶמְצָעִי תִּקְשֹׁרֶת, אֲפִלּוּ בְּשִׁדּוּר חַי, וְכָל שֶׁכֵּן בְּהַקְלָטָה.","פֶּרֶק צ״ג, הֲלָכָה י״ז","קְרִיאַת הַמְּגִלָּה (הֶמְשֵׁךְ)"],["סְעוּדַת פּוּרִים נִמְשְׁכָה עַד הַלַּיְלָה. הַאִם אוֹמְרִים ״עַל הַנִּסִּים״ בְּבִרְכַּת הַמָּזוֹן?",["לֹא אוֹמְרִים, כִּי כְּבָר הִגִּיעַ הַלַּיְלָה","אוֹמְרִים רַק אִם הִתְחִילוּ לֶאֱכֹל בַּלַּיְלָה","אוֹמְרִים, כִּי הוֹלְכִים אַחֲרֵי תְּחִלַּת הַסְּעוּדָה","לֹא אוֹמְרִים, כִּי פּוּרִים נִגְמַר בַּשְּׁקִיעָה"],2,"אוֹמְרִים ״עַל הַנִּסִּים״ (בְּבִרְכַּת הָאָרֶץ) גַּם אִם הַסְּעוּדָה נִמְשְׁכָה עַד הַלַּיְלָה, מִפְּנֵי שֶׁהוֹלְכִים אַחֲרֵי תְּחִלַּת הַסְּעוּדָה.","פֶּרֶק צ״ד, הֲלָכָה א׳, י״ד","מִצְווֹת יוֹם הַפּוּרִים"],["מָה הַשִּׁעוּר הַמִּינִימָלִי שֶׁל מַתָּנוֹת לָאֶבְיוֹנִים?",["מַתָּנָה אַחַת גְּדוֹלָה לְעָנִי אֶחָד בִּלְבַד","שְׁתֵּי מַתָּנוֹת לִשְׁנֵי עֲנִיִּים, אַחַת לְכָל עָנִי","שְׁתֵּי מַתָּנוֹת לְעָנִי אֶחָד, בַּיּוֹם אוֹ בַּלַּיְלָה","שָׁלֹשׁ מַתָּנוֹת לִשְׁלֹשָׁה עֲנִיִּים בְּלֵיל פּוּרִים"],1,"בְּיוֹם הַפּוּרִים (וְלֹא בַּלַּיְלָה) נוֹתְנִים לְפָחוֹת שְׁתֵּי מַתָּנוֹת לִשְׁנֵי עֲנִיִּים. וְטוֹב לְהַרְבּוֹת בְּמַתָּנוֹת לָאֶבְיוֹנִים יוֹתֵר מִבַּסְּעוּדָה וּבְמִשְׁלוֹחַ מָנוֹת.","פֶּרֶק צ״ד, הֲלָכָה ב׳","מִצְווֹת יוֹם הַפּוּרִים"],["כַּמָּה רָאוּי שֶׁתִּהְיֶה שָׁוָה כָּל מַתָּנָה לְאֶבְיוֹן?",["מַסְפִּיק מַטְבֵּעַ קָטָן אֶחָד, כָּל סְכוּם שֶׁהוּא","לְפָחוֹת כְּשׁוֹוִי בֶּגֶד חָדָשׁ לְחַג הַפּוּרִים","בְּדִיּוּק כְּמוֹ הַמְּחִיר שֶׁל מִשְׁלוֹחַ מָנוֹת","לְפָחוֹת כְּשׁוֹוִי אֲרוּחָה פְּשׁוּטָה, כְּמוֹ מְנַת פָלָאפֶל"],3,"רָאוּי שֶׁשּׁוֹוִי כָּל מַתָּנָה יִהְיֶה לְפָחוֹת כְּשׁוֹוִי אֲרוּחָה פְּשׁוּטָה, כִּמְנַת פָלָאפֶל וְכַדּוֹמֶה.","פֶּרֶק צ״ד, הֲלָכָה ג׳","מִצְווֹת יוֹם הַפּוּרִים"],["מָה נָכוֹן לְגַבֵּי נְתִינַת מַתָּנוֹת לָאֶבְיוֹנִים?",["אֶפְשָׁר לָתֵת אֹכֶל אוֹ כֶּסֶף, וּלְכָל מִי שֶׁפּוֹשֵׁט יָד","רַק כֶּסֶף מְזֻמָּן, וְרַק לְעָנִי שֶׁבּוֹדְקִים שֶׁהוּא בֶּאֱמֶת עָנִי","רַק מַאֲכָלִים מוּכָנִים, וְרַק לַעֲנִיִּים שֶׁמַּכִּירִים הֵיטֵב מֵרֹאשׁ","רַק דִּבְרֵי מְתִיקָה, וְרַק לִילָדִים קְטַנִּים מִן הַשְּׁכוּנָה"],0,"אֶפְשָׁר לְקַיֵּם אֶת הַמִּצְוָה בְּמַאֲכָלִים אוֹ בְּכֶסֶף, וּבְפוּרִים כָּל מִי שֶׁפּוֹשֵׁט יָדוֹ לִטֹּל – נוֹתְנִים לוֹ.","פֶּרֶק צ״ד, הֲלָכָה ד׳, ה׳","מִצְווֹת יוֹם הַפּוּרִים"],["מִשְׁפָּחָה טָסָה וְלֹא תּוּכַל לָתֵת מַתָּנוֹת וּמִשְׁלוֹחַ מָנוֹת בְּפוּרִים עַצְמוֹ. מָה יַעֲשׂוּ?",["יִתְּנוּ בַּלַּיְלָה שֶׁלִּפְנֵי פּוּרִים, וְזֶה מַסְפִּיק לְגַמְרֵי","יִתְּנוּ אַחֲרֵי פּוּרִים, בַּשָּׁבוּעַ שֶׁאַחֲרֵי הֶחָג","יְמַנּוּ מֵרֹאשׁ שָׁלִיחַ שֶׁיִּתֵּן בִּשְׁמָם בְּיוֹם הַפּוּרִים","פְּטוּרִים לְגַמְרֵי מִן הַמִּצְווֹת הָאֵלֶּה הַשָּׁנָה"],2,"מִי שֶׁאֵינוֹ יָכוֹל לָתֵת בְּיוֹם הַפּוּרִים עַצְמוֹ, יְמַנֶּה מֵרֹאשׁ שָׁלִיחַ שֶׁיִּתֵּן בִּשְׁמוֹ בְּיוֹם הַפּוּרִים – גַּם מַתָּנוֹת לָאֶבְיוֹנִים וְגַם מִשְׁלוֹחַ מָנוֹת.","פֶּרֶק צ״ד, הֲלָכָה ו׳, ט׳","מִצְווֹת יוֹם הַפּוּרִים"],["לָמָּה תִּקְּנוּ חֲכָמִים מִשְׁלוֹחַ מָנוֹת?",["כְּדֵי שֶׁלֹּא יִשָּׁאֵר אֹכֶל מְיֻתָּר בַּבַּיִת אַחֲרֵי הֶחָג","כְּדֵי לְהַרְאוֹת לְכֻלָּם כַּמָּה יָפֶה אֲנַחְנוּ יוֹדְעִים לֶאֱרֹז","כְּדֵי לִזְכֹּר אֶת הַסְּעוּדוֹת שֶׁל הַמֶּלֶךְ אֲחַשְׁוֵרוֹשׁ","כְּדֵי לְהַרְבּוֹת אַחְדוּת, וּכְדֵי שֶׁעֲנִיִּים לֹא יִתְבַּיְּשׁוּ לְקַבֵּל"],3,"הָמָן אָמַר שֶׁיִּשְׂרָאֵל ״מְפֻזָּר וּמְפֹרָד״, וְאָנוּ מַרְבִּים אַחְדוּת. וְעוֹד – כְּשֶׁכֻּלָּם נוֹתְנִים זֶה לָזֶה, הָעֲנִיִּים אֵינָם מִתְבַּיְּשִׁים כָּל כָּךְ לְקַבֵּל, וּלְכֻלָּם יֵשׁ מָה לֶאֱכֹל בַּסְּעוּדָה.","פֶּרֶק צ״ד, הֲלָכָה ז׳","מִצְווֹת יוֹם הַפּוּרִים"],["מִי שׁוֹלֵחַ מִשְׁלוֹחַ מָנוֹת, וּמָה שׁוֹלְחִים?",["רַק אַבָּא שׁוֹלֵחַ, וּמָנָה אַחַת לְכָל מִשְׁפָּחָה","כָּל אֶחָד לַחֲבֵרוֹ וְכָל אַחַת לַחֲבֶרְתָּהּ, שְׁתֵּי מָנוֹת","רַק הַיְּלָדִים הַקְּטַנִּים שׁוֹלְחִים, מַמְתָּק אֶחָד לְכָל חָבֵר","רַק הָרַב שׁוֹלֵחַ, שְׁתֵּי מָנוֹת לְכָל הַקְּהִלָּה"],1,"שׁוֹלֵחַ כָּל אֶחָד לַחֲבֵרוֹ וְכָל אַחַת לַחֲבֶרְתָּהּ (גַּם בָּנוֹת וְנָשִׁים) שְׁתֵּי מָנוֹת שֶׁל מַאֲכָל, בַּיּוֹם וְלֹא בַּלַּיְלָה.","פֶּרֶק צ״ד, הֲלָכָה ח׳","מִצְווֹת יוֹם הַפּוּרִים"],["אֵיךְ רָאוּי לְקַיֵּם אֶת סְעוּדַת פּוּרִים?",["לְבַד בַּחֶדֶר, בְּשֶׁקֶט, בְּלִי לָשִׁיר בִּכְלָל","לִשְׁתּוֹת הַרְבֵּה מְאֹד עַד שֶׁמִּתְנַהֲגִים בְּהוֹלֵלוּת וּבִזָּיוֹן","עִם מִשְׁפָּחָה אוֹ חֲבֵרִים, בְּשִׁירָה, בְּפַת וּבָשָׂר","רַק פֵּרוֹת וִירָקוֹת, בְּלִי פַּת וּבְלִי בָּשָׂר"],2,"מַרְבִּים בְּשִׂמְחָה וּבְשִׁירָה עִם מִשְׁפָּחָה אוֹ חֲבֵרִים, אוֹכְלִים פַּת וּבָשָׂר בִּסְעוּדָה נָאָה, וְאֵין לִשְׁתּוֹת יוֹתֵר מִדַּי כְּדֵי שֶׁלֹּא לְהַגִּיעַ לְהוֹלֵלוּת וּבִזָּיוֹן.","פֶּרֶק צ״ד, הֲלָכָה י״ב, י״ג","מִצְווֹת יוֹם הַפּוּרִים"],["מָה הַטְּעָמִים לְמִנְהַג הַתַּחְפּוֹשׂוֹת בְּפוּרִים?",["כְּדֵי שֶׁלֹּא יַכִּירוּ אוֹתָנוּ כְּשֶׁאֲנַחְנוּ עוֹשִׂים שְׁטֻיּוֹת","כְּדֵי לְהַפְחִיד אֶת הַשְּׁכֵנִים וְאֶת הַיְּלָדִים הַקְּטַנִּים","כִּי בְּפוּרִים מֻתָּר לִלְבֹּשׁ כָּל בֶּגֶד שֶׁרוֹצִים","כְּדֵי לְשַׂמֵּחַ, וּכְדֵי לִזְכֹּר שֶׁבִּפְנִים נִשְׁאָרִים יְהוּדִים"],3,"הַהוֹפָעָה הַמְּשֻׁנָּה מַצְחִיקָה וּמַגְבִּירָה שִׂמְחָה, וְעוֹד – גַּם כְּשֶׁיִּשְׂרָאֵל נִרְאִים כְּגוֹיִים, בִּפְנִימִיּוּתָם הֵם יְהוּדִים. וְיֵשׁ לְהַקְפִּיד עַל בְּגָדִים צְנוּעִים.","פֶּרֶק צ״ד, הֲלָכָה ט״ו","מִצְווֹת יוֹם הַפּוּרִים"],["לָמָּה בְּשׁוּשַׁן הַבִּירָה עָשׂוּ יוֹם מִשְׁתֶּה וְשִׂמְחָה בְּט״ו בַּאֲדָר?",["כִּי הַמֶּלֶךְ אֲחַשְׁוֵרוֹשׁ צִוָּה לְחַכּוֹת יוֹם","כִּי בְּשׁוּשַׁן הַמְּגִלָּה הִגִּיעָה מְאֻחָר יוֹתֵר","כִּי שָׁם נִמְשְׁכָה הַמִּלְחָמָה יוֹם נוֹסָף","כִּי בְּי״ד בַּאֲדָר הָיְתָה שָׁם שַׁבָּת"],2,"בְּשׁוּשַׁן הַבִּירָה נִלְחֲמוּ הַיְּהוּדִים בְּי״ג וּבְי״ד בַּאֲדָר, וּלְמָחֳרָת, בְּט״ו, עָשׂוּ יוֹם מִשְׁתֶּה וְשִׂמְחָה.","פֶּרֶק צ״ה, הֲלָכָה א׳","שְׁנֵי יְמֵי הַפּוּרִים"],["לָמָּה קָבְעוּ אֶת הַחוֹמָה לְפִי יְמוֹת יְהוֹשֻׁעַ בִּן נוּן וְלֹא לְפִי יְמֵי מָרְדְּכַי וְאֶסְתֵּר?",["מִפְּנֵי כְּבוֹדָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל שֶׁהָיְתָה אָז חֲרֵבָה","כִּי בִּימֵי מָרְדְּכַי לֹא הָיוּ עָרִים מֻקָּפוֹת כְּלָל","כִּי יְהוֹשֻׁעַ בִּן נוּן נִלְחַם בַּעֲמָלֵק בְּאוֹתָהּ עִיר","כִּי חוֹמוֹת מִימֵי יְהוֹשֻׁעַ גְּבוֹהוֹת וַחֲזָקוֹת יוֹתֵר"],0,"בִּימֵי מָרְדְּכַי וְאֶסְתֵּר אֶרֶץ יִשְׂרָאֵל הָיְתָה חֲרֵבָה, וּמִפְּנֵי כְּבוֹדָהּ קָבְעוּ לְפִי הֶעָרִים שֶׁהָיוּ מֻקָּפוֹת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ.","פֶּרֶק צ״ה, הֲלָכָה א׳","שְׁנֵי יְמֵי הַפּוּרִים"],["עִיר שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ, וְהַיּוֹם אֵין לָהּ חוֹמָה – מָה דִּינָהּ?",["מְקַיְּמִים בָּהּ פּוּרִים בְּי״ד, כִּי הַחוֹמָה נֶהֶרְסָה","מְקַיְּמִים בָּהּ פּוּרִים יוֹמַיִם, מִפְּנֵי הַסָּפֵק","אֵין מְקַיְּמִים בָּהּ פּוּרִים עַד שֶׁיִּבְנוּ חוֹמָה","מְקַיְּמִים בָּהּ פּוּרִים בְּט״ו, גַּם בְּלִי חוֹמָה"],3,"בְּעָרִים שֶׁהָיוּ מֻקָּפוֹת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ מְקַיְּמִים פּוּרִים בְּט״ו, אֲפִלּוּ אִם כַּיּוֹם אֵין לָהֶן חוֹמָה, וַאֲפִלּוּ בְּחוּץ לָאָרֶץ.","פֶּרֶק צ״ה, הֲלָכָה ב׳","שְׁנֵי יְמֵי הַפּוּרִים"],["מָקוֹם הַסָּמוּךְ לְעִיר מֻקֶּפֶת חוֹמָה אוֹ נִרְאֶה עִמָּהּ – מָתַי מְקַיְּמִים בּוֹ פּוּרִים?",["בְּי״ד בַּאֲדָר, כִּי הוּא מִחוּץ לַחוֹמָה","בְּט״ו בַּאֲדָר, כְּמוֹ הָעִיר הַמֻּקֶּפֶת עַצְמָהּ","בְּי״ג בַּאֲדָר, יוֹם הַמִּלְחָמָה בָּאוֹיְבִים","בְּט״ז בַּאֲדָר, יוֹם אַחֲרֵי הָעִיר"],1,"גַּם בִּמְקוֹמוֹת הַנִּרְאִים עִם הֶעָרִים הַמֻּקָּפוֹת אוֹ סְמוּכִים לָהֶן מְקַיְּמִים פּוּרִים בְּט״ו בַּאֲדָר.","פֶּרֶק צ״ה, הֲלָכָה ב׳","שְׁנֵי יְמֵי הַפּוּרִים"],["לָמָּה בִּירוּשָׁלַיִם מְקַיְּמִים אֶת מִצְווֹת הַפּוּרִים רַק בְּט״ו בַּאֲדָר?",["כִּי בָּהּ נִמְשְׁכָה הַמִּלְחָמָה בִּימֵי מָרְדְּכַי וְאֶסְתֵּר","כִּי הִיא הָעִיר הַגְּדוֹלָה בְּיוֹתֵר בְּאֶרֶץ יִשְׂרָאֵל","כִּי יָדוּעַ בְּוַדָּאוּת שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה בִּימֵי יְהוֹשֻׁעַ","כִּי יֵשׁ לָהּ גַּם הַיּוֹם חוֹמָה גְּבוֹהָה וַחֲזָקָה"],2,"יְרוּשָׁלַיִם הִיא הָעִיר הַיְּחִידָה בְּאֶרֶץ יִשְׂרָאֵל שֶׁיָּדוּעַ בְּוַדָּאוּת שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ בִּן נוּן.","פֶּרֶק צ״ה, הֲלָכָה ד׳","שְׁנֵי יְמֵי הַפּוּרִים"],["בִּטְבֶרְיָה מְקַיְּמִים פּוּרִים יוֹמַיִם מִפְּנֵי הַסָּפֵק. מָתַי מְבָרְכִים שָׁם עַל קְרִיאַת הַמְּגִלָּה?",["רַק בְּט״ו בַּאֲדָר, כְּמוֹ בְּעִיר יְרוּשָׁלַיִם","בִּשְׁנֵי הַיָּמִים מְבָרְכִים, כִּי שְׁנֵיהֶם חוֹבָה","לֹא מְבָרְכִים כְּלָל, מִפְּנֵי שֶׁיֵּשׁ סָפֵק","רַק בְּי״ד בַּאֲדָר, וְכֵן אוֹמְרִים אָז עַל הַנִּסִּים"],3,"בִּמְקוֹמוֹת הַמְסֻפָּקִים מְבָרְכִים עַל קְרִיאַת הַמְּגִלָּה רַק בְּי״ד בַּאֲדָר, וְכֵן אוֹמְרִים ״עַל הַנִּסִּים״ רַק בְּי״ד.","פֶּרֶק צ״ה, הֲלָכָה ה׳","שְׁנֵי יְמֵי הַפּוּרִים"],["בְּפוּרִים מְשֻׁלָּשׁ – מָה קוֹרְאִים בְּשַׁבָּת בְּסֵפֶר הַתּוֹרָה הַשֵּׁנִי?",["אֶת ״וַיָּבֹא עֲמָלֵק״, קְרִיאַת הַתּוֹרָה לְפוּרִים","אֶת מְגִלַּת אֶסְתֵּר כֻּלָּהּ מִתּוֹךְ סֵפֶר תּוֹרָה","אֶת פָּרָשַׁת הַשָּׁבוּעַ פַּעַם נוֹסֶפֶת בְּקוֹל","אֶת פָּרָשַׁת ״זָכוֹר״ שֶׁקּוֹרְאִים לִפְנֵי פּוּרִים"],0,"בְּשַׁבָּת ט״ו בַּאֲדָר מוֹצִיאִים שְׁנֵי סִפְרֵי תּוֹרָה: בָּרִאשׁוֹן פָּרָשַׁת הַשָּׁבוּעַ, וּבַשֵּׁנִי ״וַיָּבֹא עֲמָלֵק״ (שְׁמוֹת י״ז, ח׳-ט״ז).","פֶּרֶק צ״ה, הֲלָכָה ו׳","שְׁנֵי יְמֵי הַפּוּרִים"],["בְּעִיר שֶׁלֹּא הָיְתָה מֻקֶּפֶת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ וְאֵין בָּהּ סָפֵק – מָתַי חוֹגְגִים?",["בְּט״ו בַּאֲדָר, כְּמוֹ שׁוּשַׁן הַבִּירָה","בְּי״ד בַּאֲדָר, כְּמוֹ רֹב הַמְּקוֹמוֹת","בִּשְׁנֵי הַיָּמִים, י״ד וְט״ו, מִסָּפֵק","בְּי״ג בַּאֲדָר, בְּיוֹם הַמִּלְחָמָה עַצְמוֹ"],1,"בִּשְׁאַר הַמְּקוֹמוֹת מְקַיְּמִים אֶת מִצְווֹת הַפּוּרִים בְּי״ד בַּאֲדָר.","פֶּרֶק צ״ה, הֲלָכָה ג׳","שְׁנֵי יְמֵי הַפּוּרִים"],["בְּאֵיזֶה סֵפֶר נֶאֱמַר: \"לֹא יָמוּשׁ סֵפֶר הַתּוֹרָה הַזֶּה מִפִּיךָ\"?",["בְּסֵפֶר בְּרֵאשִׁית, בְּסִפּוּר בְּרִיאַת הָעוֹלָם","בְּסֵפֶר יְהוֹשֻׁעַ, שֶׁנִּכְתַּב אַחֲרֵי הַתּוֹרָה","בְּסֵפֶר תְּהִלִּים, בְּמִזְמוֹר שֶׁל דָּוִד","בְּסֵפֶר שְׁמוֹת, בְּמַעֲמַד הַר סִינַי"],1,"הַפָּסוּק מוּבָא מִסֵּפֶר יְהוֹשֻׁעַ (א׳, ח׳), לְצַד פְּסוּקִים רַבִּים בְּסֵפֶר דְּבָרִים.","פֶּרֶק צ״ו, הֲלָכָה א׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["לָמָּה תַּלְמוּד תּוֹרָה שָׁקוּל כְּנֶגֶד כָּל הַמִּצְווֹת?",["כִּי לוֹמְדִים אוֹתָהּ רַק בְּבֵית הַכְּנֶסֶת בְּשַׁבָּת","כִּי הִיא הַמִּצְוָה הָרִאשׁוֹנָה שֶׁנִּכְתְּבָה בְּתוֹךְ הַתּוֹרָה כֻּלָּהּ","כִּי הַלִּמּוּד מֵבִיא אֶת הָאָדָם לְקַיֵּם אֶת הַמִּצְווֹת","כִּי מִי שֶׁלּוֹמֵד פָּטוּר מִכָּל שְׁאָר הַמִּצְווֹת"],2,"לִמּוּד הַתּוֹרָה מֵבִיא אֶת הָאָדָם לְקַיֵּם אֶת מִצְווֹתֶיהָ.","פֶּרֶק צ״ו, הֲלָכָה ב׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["מַה מַּטְּרַת לִמּוּד הַתּוֹרָה?",["רַק כְּדֵי לָדַעַת כֵּיצַד לְקַיֵּם אֶת הַמִּצְווֹת","רַק כְּדֵי לְהַצְלִיחַ בַּמִּבְחָנִים שֶׁל בֵּית הַסֵּפֶר","הַלִּמּוּד עַצְמוֹ הוּא מִצְוָה, לֹא רַק הַכָּנָה","רַק כְּדֵי שֶׁיִּקְרְאוּ לוֹ תַּלְמִיד חָכָם"],2,"הַמַּטָּרָה אֵינָהּ רַק לָדַעַת לְקַיֵּם – הַלִּמּוּד עַצְמוֹ נֶחְשָׁב לְמִצְוָה.","פֶּרֶק צ״ו, הֲלָכָה ד׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["לְפִי הָרַמְבָּ״ם, מִי חַיָּב בְּתַלְמוּד תּוֹרָה, וְעַד מָתַי?",["רַק עֲשִׁירִים, וְרַק עַד גִּיל הַזִּקְנָה","כָּל אִישׁ, עָנִי אוֹ עָשִׁיר, עַד יוֹם מוֹתוֹ","רַק בְּרִיאִים, וְרַק בִּשְׁנוֹת הַיַּלְדוּת","רַק מִי שֶׁאֵין לוֹ אִשָּׁה וּבָנִים"],1,"כָּל אִישׁ מִיִּשְׂרָאֵל חַיָּב – עָנִי וְעָשִׁיר, בָּרִיא וּבַעַל יִסּוּרִין, בָּחוּר וְזָקֵן – וְעַד יוֹם מוֹתוֹ.","פֶּרֶק צ״ו, הֲלָכוֹת ג׳, ה׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["לָמָּה תַּלְמִידֵי הַחֲכָמִים נִקְרָאִים \"אוֹרוֹ שֶׁל עוֹלָם\"?",["כִּי הֵם כְּאוֹר רוּחָנִי הַמַּדְרִיךְ בְּדֶרֶךְ הָאֱמֶת","כִּי הֵם מַדְלִיקִים נֵרוֹת בְּבֵית הַכְּנֶסֶת","כִּי הֵם לוֹמְדִים רַק בְּשָׁעוֹת הַיּוֹם","כִּי הֵם תָּמִיד לוֹבְשִׁים בְּגָדִים לְבָנִים וּמְאִירִים"],0,"הֵם כְּאוֹר רוּחָנִי הַמַּדְרִיךְ אֶת הָאָדָם בְּדֶרֶךְ הָאֱמֶת.","פֶּרֶק צ״ו, הֲלָכָה ו׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["לְמִי נִתַּן כֶּתֶר תּוֹרָה?",["רַק לְאַהֲרֹן הַכֹּהֵן וּלְכָל זַרְעוֹ","רַק לְדָוִד הַמֶּלֶךְ וּלְכָל זַרְעוֹ","רַק לַמִּשְׁפָּחוֹת שֶׁל רַבָּנִים וְרָאשֵׁי יְשִׁיבוֹת","לְכָל עַם יִשְׂרָאֵל, כָּל מִי שֶׁרוֹצֶה"],3,"כֶּתֶר תּוֹרָה נִתַּן לְכָל יִשְׂרָאֵל – כָּל מִי שֶׁרוֹצֶה, יָבוֹא וְיִטֹּל.","פֶּרֶק צ״ו, הֲלָכָה ז׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["לָמָּה חַיָּב אָדָם בִּכְבוֹד רַבּוֹ יוֹתֵר מִשֶּׁל אָבִיו?",["כִּי הָרַב תָּמִיד מְבֻגָּר יוֹתֵר מֵהָאָב","כִּי הָרַב נִמְצָא אִתּוֹ יוֹתֵר שָׁעוֹת","רַבּוֹ מְבִיאוֹ לְחַיֵּי הָעוֹלָם הַבָּא","כִּי הָאָב לֹא לָמַד תּוֹרָה בִּכְלָל"],2,"אָבִיו הֱבִיאוֹ לָעוֹלָם הַזֶּה, וְרַבּוֹ לָעוֹלָם הַבָּא. \"מוֹרָא רַבְּךָ כְּמוֹרָא שָׁמַיִם\".","פֶּרֶק צ״ו, הֲלָכָה ח׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["תַּלְמִיד חָכָם צָעִיר נִכְנַס, וְדָנִי מֵעוֹלָם לֹא לָמַד אֶצְלוֹ. מָה הַדִּין?",["כֵּן, מִצְוָה לָקוּם גַּם אִם לֹא לָמַד מִמֶּנּוּ","לֹא, קָמִים רַק בִּפְנֵי הָרַב הַפְּרָטִי שֶׁלּוֹ","לֹא, קָמִים רַק בִּפְנֵי חָכָם זָקֵן בְּשָׁנִים","כֵּן, אֲבָל רַק אִם הוּא רַב הָעִיר"],0,"מִצְוַת עֲשֵׂה לָקוּם מִפְּנֵי כָּל תַּלְמִיד חָכָם, אֲפִלּוּ אֵינוֹ זָקֵן וַאֲפִלּוּ לֹא לָמַד מִמֶּנּוּ.","פֶּרֶק צ״ו, הֲלָכָה ט׳","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["רַב בֵּית הַכְּנֶסֶת עוֹבֵר בְּסָמוּךְ. מַה נָּכוֹן לַעֲשׂוֹת?",["קָמִים אֲפִלּוּ כְּשֶׁהוּא בַּצַּד הַשֵּׁנִי שֶׁל הָרְחוֹב","קוֹרְאִים לוֹ בִּשְׁמוֹ הַפְּרָטִי, כְּדֵי לְהַרְאוֹת קִרְבָה","לֹא קָמִים, וּמְדַבְּרִים עָלָיו כְּמוֹ עַל חָבֵר","קָמִים כְּשֶׁעוֹבֵר בְּאַרְבַּע אַמּוֹת, וְלֹא קוֹרְאִים בִּשְׁמוֹ"],3,"חוֹבָה לַעֲמֹד כְּשֶׁעוֹבֵר בְּד׳ אַמּוֹת (כִּשְׁנֵי מֶטְרִים), וְאֵין לִקְרֹא לְתַלְמִיד חָכָם בִּשְׁמוֹ הַפְּרָטִי.","פֶּרֶק צ״ו, הֲלָכוֹת י׳, י״א","תַּלְמוּד תּוֹרָה וּכְבוֹד רַבּוֹ"],["סֵפֶר קֹדֶשׁ מֻנָּח עַל כִּסֵּא. מָה הַדִּין?",["מֻתָּר לָשֶׁבֶת עָלָיו אִם יוֹשְׁבִים בִּזְהִירוּת רַבָּה מְאוֹד","מֻתָּר לָשֶׁבֶת עָלָיו רַק אִם הַסֵּפֶר סָגוּר הֵיטֵב","אָסוּר לָשֶׁבֶת עַל הַכִּסֵּא כָּל עוֹד הַסֵּפֶר עָלָיו","אָסוּר בִּכְלָל לְהַנִּיחַ סֵפֶר קֹדֶשׁ עַל שׁוּם כִּסֵּא"],2,"אֵין לָשֶׁבֶת עַל כִּסֵּא שֶׁמֻּנָּח עָלָיו סֵפֶר קֹדֶשׁ, אַךְ כְּשֶׁלֹּא יוֹשְׁבִים עָלָיו מֻתָּר לְהַנִּיחַ עָלָיו סֵפֶר.","פֶּרֶק צ״ז, הֲלָכָה א׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["אֵין מָקוֹם מֻגְבָּהּ, וְצָרִיךְ לְהַנִּיחַ סְפָרִים לְמַטָּה. מָה עוֹשִׂים?",["מַנִּיחִים אוֹתָם יְשִׁירוֹת עַל הָרִצְפָּה, אֵין בְּרֵרָה","מַנִּיחִים אוֹתָם הֲפוּכִים כְּדֵי שֶׁלֹּא יִתְלַכְלְכוּ","מַחֲזִיקִים אוֹתָם בַּיָּד עַד סוֹף הַיּוֹם כֻּלּוֹ","מַנִּיחִים דָּבָר שֶׁיַּחְצֹץ בֵּין הַסְּפָרִים לָרִצְפָּה"],3,"אֵין לְהַנִּיחַ סִפְרֵי קֹדֶשׁ עַל הָרִצְפָּה, וְאִם אֵין מָקוֹם מֻגְבָּהּ מַנִּיחִים דְּבַר מָה שֶׁיַּחְצֹץ. וְגַם אָסוּר לְהַנִּיחַ סֵפֶר הָפוּךְ.","פֶּרֶק צ״ז, הֲלָכָה א׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["נָפְלוּ כַּמָּה סִפְרֵי קֹדֶשׁ לָרִצְפָּה. מָה הַסֵּדֶר הַנָּכוֹן?",["מְרִימִים סֵפֶר אֶחָד, מְנַשְּׁקִים אוֹתוֹ, וְאָז אֶת הַבָּא","מְרִימִים מַהֵר אֶת כֻּלָּם, וְרַק אַחַר כָּךְ מְנַשְּׁקִים","מְנַשְּׁקִים אֶת הַסְּפָרִים עוֹד כְּשֶׁהֵם מֻנָּחִים עַל הָרִצְפָּה","מְרִימִים רַק אֶת הַסֵּפֶר הֶחָשׁוּב בְּיוֹתֵר מִכֻּלָּם"],1,"אִם נָפְלוּ כַּמָּה סְפָרִים, מִזְדָּרְזִים לְהָרִים אֶת כֻּלָּם, וְרַק אַחַר כָּךְ מְנַשְּׁקִים אוֹתָם.","פֶּרֶק צ״ז, הֲלָכָה א׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["דָּנִי רוֹצֶה לְהִכָּנֵס לַשֵּׁרוּתִים, וּבְכִיסוֹ תְּהִלִּים קָטָן. מָה נָכוֹן לְכַתְּחִלָּה?",["לְהַנִּיחַ אֶת הַסֵּפֶר בַּחוּץ לִפְנֵי שֶׁנִּכְנָסִים","לְהַחֲזִיק אֶת הַסֵּפֶר בַּיָּד כְּדֵי שֶׁלֹּא יִפֹּל","לְהִכָּנֵס וְלִקְרֹא בּוֹ כְּדֵי לְנַצֵּל אֶת הַזְּמַן","לְהַשְׁאִיר אוֹתוֹ בַּכִּיס, כִּי בַּכִּיס תָּמִיד מֻתָּר"],0,"לְכַתְּחִלָּה אֵין לְהִכָּנֵס לַשֵּׁרוּתִים עִם סֵפֶר קֹדֶשׁ קָטָן בַּכִּיס, וּמַנִּיחִים אוֹתוֹ בַּחוּץ.","פֶּרֶק צ״ז, הֲלָכָה ב׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["מַדּוּעַ בִּמְקוֹם חֲשָׁשׁ מֻתָּר לְהִכָּנֵס כְּשֶׁהַסֵּפֶר בְּכִיס הַבֶּגֶד?",["כִּי סֵפֶר קָטָן אֵין בּוֹ קְדֻשָּׁה כְּלָל","כִּי בַּכִּיס אַף אֶחָד לֹא רוֹאֶה אֶת הַסֵּפֶר","כִּי בִּשְׁעַת חֲשָׁשׁ אֵין צֹרֶךְ בְּשׁוּם כִּסּוּי","כִּי הַכְּרִיכָה הִיא כִּסּוּי אֶחָד, וְהַכִּיס כִּסּוּי שֵׁנִי"],3,"צָרִיךְ שְׁנֵי כִּסּוּיִים, וּכְרִיכַת הַסֵּפֶר נֶחְשֶׁבֶת לְאֶחָד מֵהֶם – לָכֵן בַּכִּיס מֻתָּר.","פֶּרֶק צ״ז, הֲלָכָה ג׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["מַדּוּעַ אֵין לְהַדְפִּיס פְּסוּקִים עַל חֻלְצוֹת?",["כִּי הַדְּיוֹ שֶׁל הַהַדְפָּסָה יָקָר מְאוֹד","כִּי מֻתָּר לִכְתֹּב פְּסוּקִים רַק עַל נְיָר","כִּי אָסוּר לְהִכָּנֵס עִם חֻלְצוֹת כָּאֵלֶּה לַשֵּׁרוּתִים","כִּי חֻלְצוֹת עִם כְּתָב אֲסוּרוֹת לִלְבֹּשׁ בְּבֵית סֵפֶר"],2,"אֵין לְהַדְפִּיס פְּסוּקִים אוֹ חֶלְקֵי פְּסוּקִים עַל חֻלְצוֹת, כִּי אָסוּר לְהִכָּנֵס אִתָּן לַשֵּׁרוּתִים.","פֶּרֶק צ״ז, הֲלָכָה ד׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["יוֹסִי לוֹמֵד גְּמָרָא וְיוֹצֵא לְשִׂיחַת טֶלֶפוֹן קְצָרָה. מָה עִם הַסֵּפֶר?",["אֵין צֹרֶךְ לִסְגֹּר, כִּי יוֹצֵא לִזְמַן קָצָר","חַיָּב לִסְגֹּר, גַּם לְרֶגַע אֶחָד בִּלְבַד","צָרִיךְ לְהַחֲזִיר אֶת הַסֵּפֶר לָאָרוֹן מִיָּד","צָרִיךְ לְבַקֵּשׁ מֵחָבֵר לִשְׁמֹר עַל הַסֵּפֶר הַפָּתוּחַ"],0,"בְּהַפְסָקָה סוֹגְרִים אֶת הַסֵּפֶר, אֲבָל כְּשֶׁיּוֹצְאִים לִזְמַן קָצָר (כְּמוֹ שִׂיחַת טֶלֶפוֹן קְצָרָה) אֵין צֹרֶךְ לִסְגֹּר.","פֶּרֶק צ״ז, הֲלָכָה ה׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["אֵיפֹה נָכוֹן לְהַנִּיחַ אֶת הַמִּשְׁקָפַיִם בִּזְמַן הַלִּמּוּד?",["עַל הַגְּמָרָא הַסְּגוּרָה, כְּדֵי שֶׁלֹּא יֵלְכוּ לְאִבּוּד","עַל הַשֻּׁלְחָן, וְלֹא עַל גַּבֵּי הַגְּמָרָא","עַל הַחֻמָּשׁ, כִּי הוּא הַסֵּפֶר הֶחָשׁוּב בְּיוֹתֵר","עַל עֲרֵמַת הַסְּפָרִים, אִם יֵשׁ בָּהּ מָקוֹם פָּנוּי"],1,"אֵין לְהַנִּיחַ מִשְׁקָפַיִם, קַלְמָר, טֶלֶפוֹן נַיָּד אוֹ סִפְרֵי חֹל עַל גַּבֵּי סִפְרֵי קֹדֶשׁ.","פֶּרֶק צ״ז, הֲלָכָה ו׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["רוֹצִים לְהַנִּיחַ חֻמָּשׁ, סִדּוּר וּמִשְׁנָה בַּעֲרֵמָה אַחַת. אֵיזֶה סֵדֶר נָכוֹן?",["הַמִּשְׁנָה לְמַעְלָה, אַחֲרֶיהָ הַסִּדּוּר, וְהַחֻמָּשׁ לְמַטָּה","הַסִּדּוּר לְמַעְלָה, אַחֲרָיו הַחֻמָּשׁ, וְהַמִּשְׁנָה לְמַטָּה","הַחֻמָּשׁ לְמַעְלָה, אַחֲרָיו הַסִּדּוּר, וְהַמִּשְׁנָה לְמַטָּה","אֵין שׁוּם הֶבְדֵּל, מֻתָּר לְסַדֵּר אוֹתָם בְּכָל סֵדֶר"],2,"הַסֵּפֶר שֶׁקְּדֻשָּׁתוֹ גְּבוֹהָה יוֹתֵר לְמַעְלָה: אֵין לְהַנִּיחַ סִדּוּר עַל חֻמָּשׁ, וְאֵין לְהַנִּיחַ סִפְרֵי תּוֹרָה שֶׁבְּעַל פֶּה עַל סִדּוּר.","פֶּרֶק צ״ז, הֲלָכָה ז׳","כָּבוֹד לְסִפְרֵי הַקֹּדֶשׁ"],["מֵאֵיזֶה פָּסוּק לוֹמְדִים שֶׁאָסוּר לִמְחֹק שֵׁם ה׳?",["וְאָהַבְתָּ אֵת ה׳ אֱ-לֹהֶיךָ בְּכָל לְבָבְךָ","לֹא תִשָּׂא אֶת שֵׁם ה׳ לַשָּׁוְא","לֹא תַעֲשׂוּן כֵּן לַה׳ אֱ-לֹהֵיכֶם","כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ"],2,"לְגַבֵּי עֲבוֹדָה זָרָה נֶאֱמַר ״וְאִבַּדְתֶּם אֶת שְׁמָם״, וּלְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא נֶאֱמַר ״לֹא תַעֲשׂוּן כֵּן״.","פֶּרֶק צ״ח, הֲלָכָה א׳","גְּנִיזָה"],["מָה הַדִּין בְּמִי שֶׁמּוֹחֵק אוֹת אַחַת מִשֵּׁם קָדוֹשׁ?",["מֻתָּר, כִּי רַק שֵׁם שָׁלֵם הוּא קָדוֹשׁ","אָסוּר רַק מִדִּבְרֵי חֲכָמִים וְלֹא מִן הַתּוֹרָה","מֻתָּר אִם מוֹחֵק אוֹתָהּ בְּעִפָּרוֹן וְלֹא בְּעֵט","עוֹבֵר בְּאִסּוּר תּוֹרָה, כְּמוֹ מוֹחֵק שֵׁם שָׁלֵם"],3,"הַמּוֹחֵק אֲפִלּוּ אוֹת אַחַת מִן הַשֵּׁמוֹת הָאֲסוּרִים בִּמְחִיקָה עוֹבֵר בְּאִסּוּר תּוֹרָה.","פֶּרֶק צ״ח, הֲלָכָה ב׳","גְּנִיזָה"],["לָמָּה לֹא כּוֹתְבִים שֵׁם ה׳ בְּעִתּוֹנִים וּבְמִכְתָּבִים?",["כִּי יֵשׁ חֲשָׁשׁ שֶׁיָּבוֹאוּ לִידֵי בִּזָּיוֹן","כִּי אָסוּר לִכְתֹּב שֵׁם ה׳ בִּכְלָל","כִּי רַק סוֹפֵר סְתָ״ם רַשַּׁאי לִכְתֹּב אוֹתוֹ","כִּי עִתּוֹנִים נִכְתָּבִים בְּשָׂפָה שֶׁאֵינָהּ עִבְרִית"],0,"עִתּוֹנִים, מִכְתָּבִים וְדַפֵּי מְקוֹרוֹת עֲלוּלִים לְהִזָּרֵק, וְלָכֵן יֵשׁ חֲשָׁשׁ שֶׁשֵּׁם ה׳ יָבוֹא לִידֵי בִּזָּיוֹן.","פֶּרֶק צ״ח, הֲלָכָה ג׳","גְּנִיזָה"],["מָה דִּינוֹ שֶׁל הַשֵּׁם ׳כַּרְמִיאֵל׳ הַכָּתוּב בְּמַחְבֶּרֶת?",["קָדוֹשׁ, כִּי יֵשׁ בּוֹ אוֹתִיּוֹת מִשֵּׁם ה׳","אֵינוֹ קָדוֹשׁ וּמֻתָּר לִמְחֹק אוֹתוֹ","אָסוּר לִמְחֹק אוֹתוֹ, רַק לִגְנֹז בִּכְלִי חֶרֶס","מֻתָּר לִמְחֹק רַק אֶת חֲצִי הַמִּלָּה"],1,"שְׁמוֹת מְקוֹמוֹת וַאֲנָשִׁים שֶׁיֵּשׁ בָּהֶם אוֹתִיּוֹת מִשֵּׁם ה׳ אֵינָם קְדוֹשִׁים. וְכֵן שֵׁם שֶׁנִּכְתַּב בְּטָעוּת – אֵין בּוֹ קְדֻשָּׁה.","פֶּרֶק צ״ח, הֲלָכוֹת ד׳-ה׳","גְּנִיזָה"],["הַמִּלָּה ׳רַחוּם׳ נִכְתְּבָה כְּשֶׁבַח לַקָּדוֹשׁ בָּרוּךְ הוּא. מָה דִּינָהּ?",["הִיא אַחַת מִשִּׁבְעַת הַשֵּׁמוֹת הַקְּדוֹשִׁים","אָסוּר לִמְחֹק אוֹתָהּ מִן הַתּוֹרָה, כְּמוֹ שֵׁם","הִיא כִּנּוּי, אֵינָהּ קְדוֹשָׁה וּמֻתָּר לִמְחֹק","מֻתָּר לִמְחֹק רַק אִם כָּתוּב בְּאַנְגְּלִית"],2,"הַכִּנּוּיִים שֶׁמְּשַׁבְּחִים בָּהֶם אֶת ה׳, כְּמוֹ חַנּוּן, רַחוּם, הַגָּדוֹל – אֵינָם קְדוֹשִׁים. וְגַם מִלִּים בְּהֶקְשֵׁר חֹל אֵין בָּהֶן קְדֻשָּׁה.","פֶּרֶק צ״ח, הֲלָכוֹת ו׳-ז׳","גְּנִיזָה"],["תַּלְמִיד צָרִיךְ לְתַקֵּן טָעוּת בְּסֵפֶר קֹדֶשׁ, בְּמָקוֹם בְּלִי שֵׁם ה׳. מֻתָּר?",["מֻתָּר, כִּי זוֹ מְחִיקָה לְצֹרֶךְ תִּקּוּן בְּדֶרֶךְ כָּבוֹד","אָסוּר, כִּי אָסוּר לִמְחֹק שׁוּם דָּבָר בְּסֵפֶר","מֻתָּר רַק אִם הַסֵּפֶר כְּבָר יָשָׁן וּבָלוּי","אָסוּר, וְצָרִיךְ לִגְנֹז אֶת כָּל הַסֵּפֶר מִיָּד"],0,"חֲכָמִים אָסְרוּ לְאַבֵּד פְּסוּקִים בְּדֶרֶךְ בִּזָּיוֹן, אֲבָל מְחִיקָה לְצֹרֶךְ תִּקּוּן בְּדֶרֶךְ כָּבוֹד מֻתֶּרֶת.","פֶּרֶק צ״ח, הֲלָכָה ח׳","גְּנִיזָה"],["מָה עוֹשִׂים בְּסֵפֶר תּוֹרָה שֶׁנִּפְסַל וְאִי אֶפְשָׁר לְתַקְּנוֹ?",["מַשְׁאִירִים אוֹתוֹ בָּאָרוֹן וּמַמְשִׁיכִים לִקְרֹא בּוֹ","מַנִּיחִים בִּכְלִי חֶרֶס וְקוֹבְרִים בְּקֶבֶר תַּלְמִיד חָכָם","שׂוֹרְפִים אוֹתוֹ בְּכָבוֹד בְּחָצַר בֵּית הַכְּנֶסֶת","שָׂמִים אוֹתוֹ בְּפַח לְמִחְזוּר נְיָר עָטוּף"],1,"סֵפֶר תּוֹרָה שֶׁהִתְבַּלָּה אוֹ נִפְסַל מַנִּיחִים בִּכְלִי חֶרֶס וְקוֹבְרִים בְּקֶבֶר תַּלְמִיד חָכָם.","פֶּרֶק צ״ח, הֲלָכָה ט׳","גְּנִיזָה"],["אֵיזֶה מֵאֵלּוּ חַיָּב בִּגְנִיזָה כְּשֶׁהִתְבַּלָּה?",["עֲלוֹן שַׁבָּת שֶׁאֵין בּוֹ שֵׁם ה׳","מַחְבֶּרֶת חֶשְׁבּוֹן יְשָׁנָה שֶׁל תַּלְמִיד","עִתּוֹן יוֹמִי שֶׁיֵּשׁ בּוֹ רַק חֲדָשׁוֹת","קֻפְסַת הַפְּלַסְטִיק וְשַׂקִּית הַבַּד שֶׁל הַתְּפִלִּין"],3,"בָּתֵּי תְּפִלִּין, רְצוּעוֹת, קֻפְסְאוֹת הַפְּלַסְטִיק וְשַׂקִּית הַבַּד שֶׁהִתְבַּלּוּ – חַיָּבִים בִּגְנִיזָה, וּמַנִּיחִים אוֹתָם בִּמְכַל הַגְּנִיזָה.","פֶּרֶק צ״ח, הֲלָכוֹת י׳-י״א","גְּנִיזָה"],["בַּעֲלוֹן שַׁבָּת נִמְצָא שֵׁם ה׳ הָאָסוּר בִּמְחִיקָה. מָה עוֹשִׂים?",["חַיָּבִים לִגְנֹז אֶת כָּל הֶעָלוֹן כֻּלּוֹ","זוֹרְקִים אֶת כָּל הֶעָלוֹן לַפַּח הָרָגִיל","גּוֹזְרִים אֶת הַשֵּׁם לַגְּנִיזָה, וְאֶת הַשְּׁאָר עוֹטְפִים לְמִחְזוּר","מוֹחֲקִים אֶת הַשֵּׁם בְּטוּשׁ שָׁחֹר וְזוֹרְקִים"],2,"אֵין צֹרֶךְ לִגְנֹז אֶת כָּל הֶעָלוֹן: גּוֹזְרִים אֶת שֵׁם ה׳ לַגְּנִיזָה, וְאֶת שְׁאָר דִּבְרֵי הַתּוֹרָה עוֹטְפִים וְשָׂמִים בְּפַח לְמִחְזוּר נְיָר.","פֶּרֶק צ״ח, הֲלָכוֹת י״ב-י״ג","גְּנִיזָה"],["תַּלְמִיד הִקְפִּיד לֹא לִכְתֹּב שֵׁמוֹת קְדוֹשִׁים בַּמַּחְבֶּרֶת. מָה יַעֲשֶׂה בָּהּ בְּסוֹף הַשָּׁנָה?",["יַעֲטֹף אוֹתָהּ וְיָשִׂים בְּפַח לְמִחְזוּר נְיָר","חַיָּב לְהַנִּיחַ אוֹתָהּ בִּמְכַל הַגְּנִיזָה","יִקְבֹּר אוֹתָהּ בִּכְלִי חֶרֶס בְּבֵית הַקְּבָרוֹת","יִזְרֹק אוֹתָהּ כְּמוֹ שֶׁהִיא לַפַּח הָרָגִיל"],0,"אִם הִקְפִּידוּ – אֵין צֹרֶךְ לִגְנֹז, אֲבָל אֵין לִנְהֹג בַּמַּחְבֶּרֶת בִּזָּיוֹן: עוֹטְפִים וְשָׂמִים בְּפַח לְמִחְזוּר נְיָר.","פֶּרֶק צ״ח, הֲלָכָה י״ד","גְּנִיזָה"],["מָה לָמְדוּ חֲכָמִים מִן הַפְּסוּקִים עַל קְדֻשַּׁת יִשְׂרָאֵל?",["אֲכִילָה אֵינָהּ קְשׁוּרָה בִּכְלָל לִקְדֻשַּׁת הַנֶּפֶשׁ","קְדֻשָּׁה בָּאָה רַק בִּזְמַן תְּפִלָּה בְּבֵית הַכְּנֶסֶת","קְדֻשָּׁה בָּאָה בְּהַקְפָּדָה שֶׁלֹּא לֶאֱכֹל מַאֲכָלִים אֲסוּרִים","קְדֻשָּׁה תְּלוּיָה רַק בַּבְּגָדִים שֶׁלּוֹבְשִׁים בְּכָל יוֹם"],2,"קְדֻשַּׁת עַם יִשְׂרָאֵל בָּאָה לִידֵי בִּטּוּי בְּהַקְפָּדָה שֶׁלֹּא לֶאֱכֹל מַאֲכָלִים אֲסוּרִים, וּמִי שֶׁאוֹכֵל אוֹתָם מְטַמֵּא אֶת נַפְשׁוֹ.","פֶּרֶק צ״ט, הֲלָכָה א׳-ב׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["מַדּוּעַ אֵין לֶאֱכֹל בְּשַׂר בַּעַל חַיִּים לְלֹא שְׁאֵלַת מֻמְחֶה?",["כִּי אָסוּר לֶאֱכֹל בָּשָׂר בִּכְלָל בִּימֵי חֹל","כִּי הַסִּימָנִים בַּתּוֹרָה נִשְׁכְּחוּ לְגַמְרֵי מִן הָעוֹלָם","כִּי רַק מֻמְחִים מֻתָּרִים לִקְנוֹת בָּשָׂר בַּחֲנוּת","כִּי רֹב בְּנֵי הָאָדָם אֵינָם בְּקִיאִים בַּסִּימָנִים"],3,"בַּתּוֹרָה יֵשׁ סִימָנִים, אַךְ רֹב בְּנֵי הָאָדָם אֵינָם בְּקִיאִים בָּהֶם, וְלָכֵן שׁוֹאֲלִים מֻמְחֶה – חוּץ מִמִּינִים מְפֻרְסָמִים כִּטְהוֹרִים.","פֶּרֶק צ״ט, הֲלָכָה ג׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["מָהִי הַעֲלָאַת גֵּרָה?",["צְעָקָה חֲזָקָה שֶׁהַבְּהֵמָה מַשְׁמִיעָה כְּשֶׁהִיא רְעֵבָה","עִכּוּל בִּשְׁלַבִּים, הַמָּזוֹן חוֹזֵר לַפֶּה וְנִלְעָס שׁוּב","גִּלּוּי שֶׁהַבְּהֵמָה עוֹלָה עַל הָהָר לְבַדָּהּ","שְׁתִיַּת מַיִם רַבִּים מִן הַנַּחַל בְּכָל בֹּקֶר"],1,"הַמָּזוֹן מַגִּיעַ לַכֶּרֶס, עוֹלֶה דֶּרֶךְ בֵּית הַכּוֹסוֹת חֲזָרָה לַפֶּה, נִלְעָס הֵיטֵב, וּמַמְשִׁיךְ לְהֶמְסֵס וּלְקֵבַת הַמִּיצִים. בְּהֵמָה כְּשֵׁרָה צְרִיכָה גַּם פַּרְסָה שְׁסוּעָה.","פֶּרֶק צ״ט, הֲלָכָה ד׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["אֵיךְ יוֹדְעִים שֶׁקַּשְׂקֶשֶׂת שֶׁל דָּג הִיא כְּשֵׁרָה?",["אֶפְשָׁר לְהָסִיר אוֹתָהּ בְּלִי לִתְלֹשׁ מֵעוֹר הַדָּג","הִיא מְחֻבֶּרֶת חָזָק וְאִי אֶפְשָׁר לְהוֹרִיד אוֹתָהּ","הִיא צְבוּעָה בְּצֶבַע כָּסֹף נוֹצֵץ וּמַבְרִיק","הִיא יוֹרֶדֶת רַק יַחַד עִם חֲתִיכַת עוֹר"],0,"הַקַּשְׂקֶשֶׂת הִיא מַלְבּוּשׁ הַדָּג: כְּמוֹ בֶּגֶד, מְסִירִים אוֹתָהּ בַּיָּד אוֹ בִּכְלִי בְּלִי לִתְלֹשׁ מִן הָעוֹר. אִם אִי אֶפְשָׁר – הַדָּג אֵינוֹ כָּשֵׁר.","פֶּרֶק צ״ט, הֲלָכָה ה׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["דָּג צָעִיר מִמִּין שֶׁמְּגַדֵּל קַשְׂקַשִּׂים, שֶׁעֲדַיִן אֵין לוֹ קַשְׂקַשִּׂים – מָה דִּינוֹ?",["אָסוּר לְאָכְלוֹ עַד שֶׁיִּגְדַּל וְיִהְיֶה זָקֵן","מֻתָּר לְאָכְלוֹ רַק אִם בִּשְּׁלוּ אוֹתוֹ הֵיטֵב","מֻתָּר לְאָכְלוֹ, כִּי הוּא מִמִּין שֶׁמְּגַדֵּל קַשְׂקַשִּׂים","אָסוּר לְאָכְלוֹ כִּי אֵין לוֹ קַשְׂקַשִּׂים עַכְשָׁו"],2,"מֻתָּר לֶאֱכֹל דָּג צָעִיר מִמִּין שֶׁמְּגַדֵּל קַשְׂקַשִּׂים, וְכֵן דָּג שֶׁקַּשְׂקַשָּׂיו נָשְׁרוּ בְּרֶשֶׁת הַדַּיָּגִים.","פֶּרֶק צ״ט, הֲלָכָה ו׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["מָה עוֹשִׂים לִפְנֵי אֲכִילַת יַרְקוֹת עָלִים כְּמוֹ חַסָּה?",["שׁוֹטְפִים אוֹתָם מַהֵר בְּמַיִם וְאוֹכְלִים מִיָּד","אוֹכְלִים בְּלִי בְּדִיקָה כִּי חֲרָקִים תָּמִיד נִרְאִים","מְבַשְּׁלִים אוֹתָם וְאָז אֵין צֹרֶךְ לִבְדֹּק כְּלָל","בּוֹדְקִים בְּדִיקָה יְסוֹדִית אוֹ קוֹנִים מִגִּדּוּל מְפֻקָּח"],3,"אִסּוּר שְׁרָצִים חָמוּר וּמְפֹרָשׁ בַּתּוֹרָה בְּכַמָּה מְקוֹמוֹת. הַחֲרָקִים מִתְחַבְּאִים וּמַסְוִים אֶת עַצְמָם, וְלָכֵן בּוֹדְקִים הֵיטֵב אוֹ קוֹנִים מִגִּדּוּל מְיֻחָד וּמְפֻקָּח.","פֶּרֶק צ״ט, הֲלָכָה ז׳-ח׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["מָה עוֹשִׂים בְּאֹרֶז וּבְקֶמַח יָשָׁן לִפְנֵי הַשִּׁמּוּשׁ?",["בּוֹרְרִים אֶת הָאֹרֶז וּמְנַפִּים אֶת הַקֶּמַח הֵיטֵב","זוֹרְקִים אוֹתָם תָּמִיד לַפַּח וְקוֹנִים חֲדָשִׁים","מְחַמְּמִים אוֹתָם בַּתַּנּוּר וּמְשַׁמְּשִׁים מִיָּד","מוֹסִיפִים לָהֶם מַיִם וּמְעַרְבְּבִים בְּכַף"],0,"קִטְנִיּוֹת כְּמוֹ אֹרֶז וּגְרִיסִים בּוֹרְרִים הֵיטֵב. קֶמַח שֶׁעָמַד זְמַן רַב מְנַפִּים בְּנָפָה, אוֹ קוֹנִים קֶמַח מְנֻפֶּה וְשׁוֹמְרִים בְּקֵרוּר.","פֶּרֶק צ״ט, הֲלָכָה ט׳-י׳","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["מַדּוּעַ קוֹנִים דָּגִים מִמְּקוֹמוֹת מְפֻקָּחִים?",["כִּי שָׁם הַדָּגִים תָּמִיד זוֹלִים יוֹתֵר מִבְּכָל מָקוֹם","כִּי אָסוּר לִדּוֹג דָּגִים לְבַד בַּיָּם","כִּי בְּחֵלֶק מֵהַדָּגִים יֵשׁ חֲשָׁשׁ לְתוֹלְעֵי מַיִם","כִּי רַק שָׁם מוֹכְרִים דָּגִים גְּדוֹלִים וּטְרִיִּים"],2,"בְּחֵלֶק מֵהַדָּגִים יֵשׁ חֲשָׁשׁ לְתוֹלְעֵי מַיִם, וּבִמְקוֹמוֹת מְפֻקָּחִים הַדָּגִים הַנִּמְכָּרִים נְקִיִּים מִתּוֹלָעִים.","פֶּרֶק צ״ט, הֲלָכָה י״א","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["מָה עוֹשִׂים כְּשֶׁשּׁוֹתִים מֵי מַעְיָן שֶׁיֵּשׁ בָּהֶם חֲשָׁשׁ?",["שׁוֹתִים מַהֵר כְּדֵי שֶׁהַתּוֹלָעִים לֹא יַרְגִּישׁוּ","מְסַנְּנִים אֶת הַמַּיִם הֵיטֵב לִפְנֵי שֶׁשּׁוֹתִים","מוֹסִיפִים סֻכָּר כְּדֵי שֶׁהַטַּעַם יִהְיֶה טוֹב","שׁוֹתִים רַק בַּלַּיְלָה כְּשֶׁאֵין רוֹאִים כְּלוּם"],1,"כְּשֶׁיֵּשׁ חֲשָׁשׁ לִשְׁרָצִים וְתוֹלָעִים, כְּמוֹ בְּמֵי מַעְיָנוֹת אוֹ מַשְׁקָאוֹת שֶׁעָמְדוּ זְמַן רַב – מְסַנְּנִים הֵיטֵב.","פֶּרֶק צ״ט, הֲלָכָה י״ב","כַּשְׁרוּת בַּעֲלֵי חַיִּים"],["אֵיךְ תִּרְגֵּם יוֹנָתָן בֶּן עֻזִּיאֵל אֶת הַמִּלָּה ״לֶחֶם״ בַּפָּסוּק ״בְּזֵעַת אַפֶּיךָ תֹּאכַל לֶחֶם״?",["פִּתָּא, כִּי הַלֶּחֶם נֶאֱפֶה תָּמִיד בַּתַּנּוּר","מְזוֹנָא, כִּי הַלֶּחֶם הוּא עִקַּר הַמָּזוֹן","חִטָּה, כִּי הַלֶּחֶם עָשׂוּי מִן הַחִטָּה","מַתָּנָה, כִּי הַלֶּחֶם יוֹרֵד מִן הַשָּׁמַיִם"],1,"יוֹנָתָן בֶּן עֻזִּיאֵל תִּרְגֵּם ״מְזוֹנָא״ – כְּלוֹמַר הַלֶּחֶם הוּא עִקַּר הַמָּזוֹן, וְכָל מָה שֶׁנֶּאֱכָל אִתּוֹ טָפֵל אֵלָיו.","פֶּרֶק כ״ג, הֲלָכָה א׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["מָה הַמִּנְהָג שֶׁל יֵשׁ נוֹהֲגִים בְּעִנְיַן הַקִּנּוּחַ?",["אוֹכְלִים אֶת הַקִּנּוּחַ לִפְנֵי שֶׁאוֹכְלִים אֶת הַלֶּחֶם","אוֹכְלִים קִנּוּחַ בְּאֶמְצַע הַסְּעוּדָה בְּלִי שׁוּם בְּרָכָה","מְבָרְכִים בִּרְכַּת הַמָּזוֹן, וְאַחַר כָּךְ אוֹכְלִים אֶת הַקִּנּוּחַ","לֹא אוֹכְלִים קִנּוּחַ בְּכָל יְמֵי הַשָּׁנָה לְעוֹלָם"],2,"יֵשׁ נוֹהֲגִים שֶׁלֹּא לֶאֱכֹל שׁוּם קִנּוּחַ לִפְנֵי בִּרְכַּת הַמָּזוֹן, אֶלָּא מְבָרְכִים תְּחִלָּה בִּרְכַּת הַמָּזוֹן וְאַחַר כָּךְ בְּרָכָה רִאשׁוֹנָה עַל הַקִּנּוּחַ.","פֶּרֶק כ״ג, הֲלָכָה ה׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["מָתַי חַיָּבִים לְבָרֵךְ בִּרְכַּת הַמָּזוֹן מִן הַתּוֹרָה?",["לְאַחַר שֶׁשּׁוֹתִים כּוֹס מַיִם קָרִים","רַק כְּשֶׁאוֹכְלִים בָּשָׂר בְּיוֹם שַׁבָּת","לִפְנֵי שֶׁמַּתְחִילִים לֶאֱכֹל אֶת הַלֶּחֶם","לְאַחַר שֶׁאוֹכְלִים לֶחֶם וּשְׂבֵעִים מִמֶּנּוּ"],3,"מִן הַתּוֹרָה חַיָּבִים לְבָרֵךְ אַחֲרֵי אֲכִילַת לֶחֶם וּשְׂבִיעָה, שֶׁנֶּאֱמַר ״וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ״. חֲכָמִים הוֹסִיפוּ שֶׁמְּבָרְכִים גַּם עַל כְּזַיִת, אֲפִלּוּ בְּלִי שֹׂבַע.","פֶּרֶק כ״ד, הֲלָכָה א׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["מִי תִּקֵּן אֶת הַבְּרָכָה הַשְּׁנִיָּה, בִּרְכַּת הָאָרֶץ, וּמָתַי?",["יְהוֹשֻׁעַ, לְאַחַר הַכְּנִיסָה לְאֶרֶץ יִשְׂרָאֵל","מֹשֶׁה רַבֵּנוּ, כַּאֲשֶׁר יָרַד הַמָּן","דָּוִד הַמֶּלֶךְ, כְּשֶׁבָּנָה אֶת יְרוּשָׁלַיִם","חַכְמֵי יִשְׂרָאֵל, אַחֲרֵי חֻרְבַּן בֵּיתָר"],0,"בִּרְכַּת הָאָרֶץ נִתְקְנָה עַל יְדֵי יְהוֹשֻׁעַ לְאַחַר הַכְּנִיסָה לָאָרֶץ. בָּהּ מוֹדִים עַל אֶרֶץ יִשְׂרָאֵל, בְּרִית הַמִּילָה וְהַתּוֹרָה.","פֶּרֶק כ״ד, הֲלָכָה ב׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["מָה מְבַקְּשִׁים בַּבְּרָכָה הַשְּׁלִישִׁית, ״בּוֹנֵה יְרוּשָׁלַיִם״, מֵאָז הַחֻרְבָּן?",["שֶׁה׳ יִתֵּן לָנוּ גְּשָׁמִים בְּעִתָּם","שֶׁה׳ יִשְׁלַח לָנוּ מָן מִן הַשָּׁמַיִם","שֶׁה׳ יִבְנֶה בְּרַחֲמָיו אֶת יְרוּשָׁלַיִם","שֶׁה׳ יִתֵּן לָנוּ הַרְבֵּה לֶחֶם טָעִים"],2,"בִּזְמַן הַמִּקְדָּשׁ הוֹדוּ בַּבְּרָכָה עַל בְּחִירַת יְרוּשָׁלַיִם, הַמִּקְדָּשׁ וּמַלְכוּת בֵּית דָּוִד (תִּקְּנוּהָ דָּוִד וּשְׁלֹמֹה). לְאַחַר הַחֻרְבָּן מְבַקְּשִׁים שֶׁה׳ יִבְנֶה בְּרַחֲמָיו אֶת יְרוּשָׁלַיִם.","פֶּרֶק כ״ד, הֲלָכָה ב׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["אֵילוּ מִבִּרְכוֹת הַמָּזוֹן הֵן מִן הַתּוֹרָה?",["כָּל אַרְבַּע הַבְּרָכוֹת הֵן מִן הַתּוֹרָה","שָׁלֹשׁ הָרִאשׁוֹנוֹת, וְאֶת הָרְבִיעִית תִּקְּנוּ חֲכָמִים","רַק הַבְּרָכָה הָרִאשׁוֹנָה, וְכָל הַשְּׁאָר תִּקְּנוּ חֲכָמִים","אַף אַחַת, כֻּלָּן תִּקְּנוּ חֲכָמִים"],1,"שָׁלֹשׁ הַבְּרָכוֹת הָרִאשׁוֹנוֹת הֵן מִן הַתּוֹרָה, וְאֶת הַבְּרָכָה הָרְבִיעִית, ״הַטּוֹב וְהַמֵּטִיב״, תִּקְּנוּ חֲכָמִים.","פֶּרֶק כ״ד, הֲלָכָה ג׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["מָה חַיָּבִים לְהַזְכִּיר בַּבְּרָכָה הַשְּׁנִיָּה שֶׁל בִּרְכַּת הַמָּזוֹן?",["אֶת הַמָּן שֶׁיָּרַד לַאֲבוֹתֵינוּ בַּמִּדְבָּר","אֶת חֻרְבַּן בֵּיתָר וְאֶת הַנֵּס שֶׁנַּעֲשָׂה","אֶת שְׁמוֹת כָּל הַמַּאֲכָלִים שֶׁאָכַלְנוּ בַּסְּעוּדָה","אֶרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה, וְגַם בְּרִית וְתוֹרָה"],3,"בַּבְּרָכָה הַשְּׁנִיָּה חַיָּבִים לְהַזְכִּיר ״אֶרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה״ וְ״בְרִית וְתוֹרָה״, שֶׁהֵם עִקַּר הַבְּרָכָה.","פֶּרֶק כ״ד, הֲלָכָה ז׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["מִי שֶׁשָּׁכַח לְבָרֵךְ בִּרְכַּת הַמָּזוֹן וְיָצָא מִמְּקוֹם הָאֲכִילָה, מָה עָלָיו לַעֲשׂוֹת?",["לַחֲזֹר לִמְקוֹם הָאֲכִילָה, אִם הַמָּזוֹן עוֹד לֹא הִתְעַכֵּל","לֶאֱכֹל שׁוּב לֶחֶם, וְרַק אָז לְבָרֵךְ","אֵינוֹ צָרִיךְ לְבָרֵךְ כְּלָל, כִּי כְּבָר יָצָא","לְחַכּוֹת וּלְבָרֵךְ רַק בַּסְּעוּדָה הַבָּאָה שֶׁלּוֹ"],0,"יֵשׁ לְבָרֵךְ בִּמְקוֹם הָאֲכִילָה, וּמִי שֶׁשָּׁכַח – חוֹזֵר לְשָׁם וּמְבָרֵךְ, בִּתְנַאי שֶׁיָּכוֹל לַחֲזֹר לִפְנֵי שֶׁהַמָּזוֹן יִתְעַכֵּל בַּגּוּף.","פֶּרֶק כ״ד, הֲלָכָה ה׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["מַדּוּעַ בִּרְכַּת ״הַמּוֹצִיא״ פּוֹטֶרֶת אֶת שְׁאָר הַמַּאֲכָלִים שֶׁבַּסְּעוּדָה?",["כִּי הֵם תָּמִיד קְטַנִּים יוֹתֵר מִן הַלֶּחֶם","כִּי אָסוּר לְבָרֵךְ יוֹתֵר מִבְּרָכָה אַחַת","כִּי הֵם בָּאִים לְלַפֵּת בָּהֶם אֶת הַפַּת","כִּי הַבָּשָׂר וְהַדָּגִים אֵינָם צְרִיכִים בְּרָכָה"],2,"שְׁאָר הַמַּאֲכָלִים, כְּמוֹ בָּשָׂר, דָּגִים, בֵּיצִים, יְרָקוֹת וּגְבִינָה, בָּאִים ״לְלַפֵּת בָּהֶם אֶת הַפַּת״, וְלָכֵן הֵם טְפֵלִים לַלֶּחֶם.","פֶּרֶק כ״ג, הֲלָכָה ב׳","הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן"],["מָה לוֹמְדִים מִן הַפְּסוּקִים ״כָּל חֵלֶב וְכָל דָּם לֹא תֹאכֵלוּ״ וְ״רַק חֲזַק לְבִלְתִּי אֲכֹל הַדָּם״?",["מֻתָּר לֶאֱכֹל דָּם רַק בִּימֵי חַג וּמוֹעֵד","הַדָּם אָסוּר רַק בְּבָשָׂר שֶׁל בְּהֵמָה טְמֵאָה","אָסוּר לֶאֱכֹל בָּשָׂר לִפְנֵי שֶׁהוֹצִיאוּ מִמֶּנּוּ אֶת הַדָּם","מֻתָּר לֶאֱכֹל בָּשָׂר מִיָּד אַחֲרֵי הַשְּׁחִיטָה"],2,"מִפְּסוּקִים אֵלּוּ לוֹמְדִים שֶׁאָסוּר לֶאֱכֹל בָּשָׂר, אֲפִלּוּ שֶׁל בְּהֵמָה טְהוֹרָה שֶׁנִּשְׁחֲטָה כַּדִּין, לִפְנֵי שֶׁהוֹצִיאוּ מִמֶּנּוּ אֶת הַדָּם.","פֶּרֶק ק׳, הֲלָכָה א׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["מָה פֵּרוּשׁ הַמִּלָּה ״מֻכְשָׁר״ עַל בָּשָׂר?",["שֶׁהַבְּהֵמָה נִשְׁחֲטָה בִּידֵי שׁוֹחֵט מֻמְחֶה וְיָרֵא","שֶׁהוֹצִיאוּ מִן הַבָּשָׂר אֶת הַדָּם","שֶׁהַבָּשָׂר נִשְׁמַר הַרְבֵּה זְמַן בְּתוֹךְ הַמְּקָרֵר","שֶׁהַבָּשָׂר נִקְנָה בַּחֲנוּת שֶׁל אֲנָשִׁים טוֹבִים"],1,"״כָּשֵׁר״ – מִבַּעַל חַיִּים טָהוֹר שֶׁנִּשְׁחַט כַּהֲלָכָה. ״מֻכְשָׁר״ – הוֹצִיאוּ מִמֶּנּוּ אֶת הַדָּם.","פֶּרֶק ק׳, הֲלָכָה ב׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["מַדּוּעַ מִשְׁתַּמְּשִׁים דַּוְקָא בְּמֶלַח כְּדֵי לְהוֹצִיא אֶת הַדָּם?",["הוּא מוֹסִיף לַבָּשָׂר טַעַם טוֹב וּמָלוּחַ","הוּא שׁוֹמֵר עַל הַבָּשָׂר מִלְּהִתְקַלְקֵל מַהֵר מְאֹד","הוּא חוֹדֵר לַמַּאֲכָל וּמַפְלִיט מִמֶּנּוּ אֶת הַנּוֹזְלִים","הוּא מְקָרֵר אֶת הַבָּשָׂר וּמַקְשֶׁה אוֹתוֹ הֵיטֵב"],2,"כֹּחוֹ שֶׁל הַמֶּלַח הוּא שֶׁהוּא חוֹדֵר לְתוֹךְ הַמַּאֲכָלִים וּמַפְלִיט מֵהֶם אֶת הַנּוֹזְלִים.","פֶּרֶק ק׳, הֲלָכָה ג׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["מָהוּ הַסֵּדֶר הַנָּכוֹן שֶׁל הַכְשָׁרַת הַבָּשָׂר בְּמֶלַח?",["מְלִיחָה, אַחֲרֶיהָ שְׁרִיָּה, וּבַסּוֹף הֲדָחָה פַּעַם אַחַת","הֲדָחָה, אַחֲרֶיהָ מְלִיחָה, וּבַסּוֹף שְׁרִיָּה בְּמַיִם חַמִּים","מְלִיחָה בִּלְבַד, בְּלִי שְׁרִיָּה וּבְלִי הֲדָחָה כְּלָל","שְׁרִיָּה, אַחֲרֶיהָ מְלִיחָה, וּבַסּוֹף הֲדָחָה שָׁלוֹשׁ פְּעָמִים"],3,"שְׁרִיָּה בְּמַיִם חֲצִי שָׁעָה, מְלִיחָה בְּמֶלַח גַּס כְּשָׁעָה, וַהֲדָחָה שָׁלוֹשׁ פְּעָמִים.","פֶּרֶק ק׳, הֲלָכָה ג׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["מָהִי ״חֲלִיטָה״, הַשָּׁלָב הַנּוֹסָף בְּחֵלֶק מִקְּהִלּוֹת הַתֵּימָנִים?",["מַכְנִיסִים אֶת הַבָּשָׂר לְתוֹךְ מַיִם רוֹתְחִים בְּסִיר","מַקְפִּיאִים אֶת הַבָּשָׂר בַּמַּקְפִּיא לְמֶשֶׁךְ יוֹם שָׁלֵם","מְפַזְּרִים עַל הַבָּשָׂר סֻכָּר לְמֶשֶׁךְ שָׁעָה","מְיַבְּשִׁים אֶת הַבָּשָׂר בַּשֶּׁמֶשׁ לְמֶשֶׁךְ שָׁעָה"],0,"בַּחֲלִיטָה מַרְתִּיחִים מַיִם בְּסִיר וּמַכְנִיסִים לְתוֹכָם אֶת הַבָּשָׂר, וְרַק אַחַר כָּךְ מְבַשְּׁלִים וְאוֹכְלִים.","פֶּרֶק ק׳, הֲלָכָה ג׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["לָמָּה בָּשָׂר שֶׁנִּצְלָה כָּרָאוּי מֻתָּר בַּאֲכִילָה?",["צְלִיָּה מֻתֶּרֶת רַק אַחֲרֵי שְׁרִיָּה שֶׁל יוֹם שָׁלֵם","חֹם הָאֵשׁ מַפְלִיט אֶת הַדָּם כְּמוֹ הַמֶּלַח","הָאֵשׁ צוֹבַעַת אֶת הַדָּם וְלָכֵן הוּא לֹא נִרְאֶה","בָּשָׂר צָלוּי אָסוּר תָּמִיד, כִּי הַדָּם נִשְׁאָר"],1,"כְּשֵׁם שֶׁהַמֶּלַח מַפְלִיט אֶת הַדָּם, כָּךְ גַּם חֹם הָאֵשׁ מַפְלִיט אוֹתוֹ, כְּשֶׁצּוֹלִים עַד שֶׁהַבָּשָׂר רָאוּי לַאֲכִילָה.","פֶּרֶק ק׳, הֲלָכָה ד׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["מַדּוּעַ מַכְשִׁירִים אֶת הַכָּבֵד בִּצְלִיָּה וְלֹא בִּמְלִיחָה?",["הַכָּבֵד קָשֶׁה מִדַּי וְהַמֶּלַח לֹא נִדְבָּק אֵלָיו","אֵין בּוֹ דָּם כְּלָל, וְלָכֵן אֵין צֹרֶךְ בִּמְלִיחָה","יֵשׁ בּוֹ דָּם רַב וְהַמֶּלַח לֹא מוֹצִיא אֶת כֻּלּוֹ","כָּךְ הוּא טָעִים יוֹתֵר לַאֲכִילָה בִּימֵי חַג וְשַׁבָּת"],2,"הַכָּבֵד הוּא אֵיבָר שֶׁיֵּשׁ בּוֹ דָּם רַב, וְאֵין הַמֶּלַח יָכוֹל לְהוֹצִיא אֶת כֻּלּוֹ. אֶת פְּרָטֵי הַצְּלִיָּה יֵשׁ לְבָרֵר לְפִי מִנְהַג כָּל עֵדָה.","פֶּרֶק ק׳, הֲלָכָה ה׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["לָמָּה בֵּיצָה מִן הַחֲנוּת שֶׁנִּמְצָא בָּהּ דָּם אֵינָהּ אֲסוּרָה כֻּלָּהּ?",["כִּי הַבֵּיצִים בַּחֲנוּת נִבְדְּקוּ בִּידֵי רַב","כִּי טִפַּת דָּם קְטַנָּה אֵינָהּ נֶחְשֶׁבֶת דָּם כְּלָל","כִּי בֵּיצִים אֵינָן בָּשָׂר וְאֵין בָּהֶן אִסּוּר דָּם","בַּלּוּלִים אֵין תַּרְנְגוֹלִים זְכָרִים, וְאֵין חֲשָׁשׁ אֶפְרוֹחַ"],3,"הַבֵּיצִים הַמְּשֻׁוָּקוֹת מַגִּיעוֹת מִלּוּלִים בְּלִי תַּרְנְגוֹלִים זְכָרִים, וְאֵין חֲשָׁשׁ לִתְחִלַּת אֶפְרוֹחַ. לָכֵן מוֹצִיאִים אֶת הַדָּם וְהַשְּׁאָר מֻתָּר.","פֶּרֶק ק׳, הֲלָכָה ו׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["לָמָּה מֻתָּר לֶאֱכֹל בֵּיצִים קָשׁוֹת אַף שֶׁאִי אֶפְשָׁר לִבְדֹּק אוֹתָן?",["בּוֹדְקִים אוֹתָן בְּאוֹר חָזָק לִפְנֵי הַבִּשּׁוּל","סוֹמְכִים עַל כָּךְ שֶׁבְּרֹב הַבֵּיצִים אֵין דָּם","הַבִּשּׁוּל מַפְלִיט אֶת כָּל הַדָּם מִן הַבֵּיצָה","בֵּיצִים קָשׁוֹת מֻתָּרוֹת רַק לִילָדִים קְטַנִּים"],1,"כְּשֶׁמְּבַשְּׁלִים בֵּיצִים שְׁלֵמוֹת אִי אֶפְשָׁר לִבְדֹּק אוֹתָן, אֲבָל סוֹמְכִים עַל כָּךְ שֶׁבְּרֹב הַבֵּיצִים אֵין דָּם.","פֶּרֶק ק׳, הֲלָכָה ז׳","אִסּוּר דָּם בְּבָשָׂר וּבְבֵיצִים"],["כַּמָּה פְּעָמִים מוֹפִיעַ בַּתּוֹרָה הַפָּסוּק ״לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ״, וּמָה לָמְדוּ מִכָּךְ?",["פַּעַם אַחַת, וּמִכָּאן לָמְדוּ אִסּוּר אֲכִילָה בִּלְבַד","שְׁתֵּי פְּעָמִים, וּמִכָּאן לָמְדוּ אֲכִילָה וּבִשּׁוּל","שָׁלוֹשׁ פְּעָמִים, וּמִכָּאן לָמְדוּ שְׁלוֹשָׁה אִסּוּרִים","אַרְבַּע פְּעָמִים, וּמִכָּאן לָמְדוּ אַרְבָּעָה אִסּוּרִים"],2,"הַפָּסוּק מוֹפִיעַ שָׁלוֹשׁ פְּעָמִים, וּמִכָּאן לָמְדוּ חֲכָמִים שְׁלוֹשָׁה אִסּוּרִים: אִסּוּר אֲכִילָה, אִסּוּר בִּשּׁוּל וְאִסּוּר הֲנָאָה.","פֶּרֶק ק״א, הֲלָכָה א׳","בָּשָׂר וְחָלָב"],["מַדּוּעַ אָסוּר לְהַנִּיחַ מַאַכְלֵי בָּשָׂר עַל שֻׁלְחָן שֶׁאוֹכְלִים עָלָיו מַאַכְלֵי חָלָב?",["כִּי הָרֵיחַ שֶׁל הַבָּשָׂר מְקַלְקֵל אֶת הֶחָלָב","כִּי הַשֻּׁלְחָן נֶחְשָׁב כְּמוֹ סִיר בִּשּׁוּל","כִּי אָסוּר לִרְאוֹת בָּשָׂר בִּזְמַן אֲרוּחַת חָלָב","כְּדֵי שֶׁלֹּא יִטְעוּ לֶאֱכֹל מֵהֶם יַחַד"],3,"הַטַּעַם הוּא כְּדֵי שֶׁלֹּא יִטְעוּ לֶאֱכֹל מֵהֶם יַחַד.","פֶּרֶק ק״א, הֲלָכָה ב׳","בָּשָׂר וְחָלָב"],["שְׁנֵי חֲבֵרִים יוֹשְׁבִים לְיַד שֻׁלְחָן אֶחָד, אֶחָד אוֹכֵל חָלָב וְהַשֵּׁנִי בָּשָׂר. מָה עֲלֵיהֶם לַעֲשׂוֹת?",["לִשְׁתּוֹת מֵאוֹתָהּ כּוֹס כְּדֵי לַחְסֹךְ בִּכְלִים","לָשִׂים בֵּינֵיהֶם חֵפֶץ שֶׁאֵינוֹ רָגִיל עַל הַשֻּׁלְחָן","לֶאֱכֹל מֵאוֹתָהּ כִּכַּר לֶחֶם שֶׁעַל הַשֻּׁלְחָן","אֵין צֹרֶךְ בְּשׁוּם הֶכֵּר, כִּי הֵם מַכִּירִים"],1,"דַּוְקָא מִפְּנֵי שֶׁהֵם מַכִּירִים יֵשׁ חֲשָׁשׁ שֶׁיִּטְעֲמוּ זֶה מִזֶּה, וְלָכֵן עוֹשִׂים הֶכֵּר: מַפָּה נִפְרֶדֶת אוֹ חֵפֶץ שֶׁאֵינוֹ רָגִיל עַל הַשֻּׁלְחָן. וְלֹא שׁוֹתִים מֵאוֹתָהּ כּוֹס וְלֹא אוֹכְלִים מֵאוֹתָהּ כִּכָּר.","פֶּרֶק ק״א, הֲלָכָה ג׳","בָּשָׂר וְחָלָב"],["אֵיזֶה מִנְהָג הַמְתָּנָה בֵּין בָּשָׂר לְחָלָב כָּתוּב שֶׁכָּךְ רָאוּי לִנְהֹג?",["לְהַמְתִּין שֵׁשׁ שָׁעוֹת, כְּמִנְהַג קְהִלּוֹת הַסְּפָרַדִּים","לְהַמְתִּין חֲצִי שָׁעָה בִּלְבַד אַחֲרֵי הַבָּשָׂר","לְהַמְתִּין עֶשְׂרִים וְאַרְבַּע שָׁעוֹת, יוֹם שָׁלֵם","אֵין צֹרֶךְ לְהַמְתִּין כְּלָל אַחֲרֵי בְּשַׂר עוֹף"],0,"בִּקְהִלּוֹת הַסְּפָרַדִּים וּבְרַבּוֹת מִקְּהִלּוֹת הָאַשְׁכְּנַזִּים מַמְתִּינִים שֵׁשׁ שָׁעוֹת, וְכָךְ רָאוּי לִנְהֹג - גַּם אַחֲרֵי בְּשַׂר עוֹף.","פֶּרֶק ק״א, הֲלָכָה ד׳","בָּשָׂר וְחָלָב"],["יוֹסִי לָעַס חֲתִיכַת בָּשָׂר וְלֹא בָּלַע אוֹתָהּ. מָה הַדִּין לְגַבֵּי אֲכִילַת חָלָב?",["מֻתָּר לוֹ לֶאֱכֹל חָלָב מִיָּד, כִּי לֹא בָּלַע","צָרִיךְ לְהַמְתִּין רַק חֲצִי שָׁעָה וְזֶהוּ","צָרִיךְ לְהַמְתִּין לִפְנֵי חָלָב, אֲפִלּוּ שֶׁלֹּא בָּלַע","מַסְפִּיק שֶׁיִּשְׁתֶּה מַיִם, וְאָז יֹאכַל חָלָב"],2,"לְאַחַר שֶׁלּוֹעֲסִים בָּשָׂר צָרִיךְ לְהַמְתִּין אֲפִלּוּ אִם לֹא בּוֹלְעִים. וְגַם אַחֲרֵי הַהַמְתָּנָה - אִם נִשְׁאַר בָּשָׂר בֵּין הַשִּׁנַּיִם, מְנַקִּים הֵיטֵב לִפְנֵי חָלָב.","פֶּרֶק ק״א, הֲלָכוֹת ה׳-ו׳","בָּשָׂר וְחָלָב"],["מָה הַדִּין בְּמִי שֶׁאָכַל רַק תַּפּוּחֵי אֲדָמָה שֶׁהִתְבַּשְּׁלוּ עִם בָּשָׂר?",["אֵינוֹ צָרִיךְ לְהַמְתִּין, כִּי לֹא אָכַל בָּשָׂר","צָרִיךְ לְהַמְתִּין כְּמוֹ אַחֲרֵי בָּשָׂר מַמָּשׁ","צָרִיךְ לְהַמְתִּין רַק אִם אָכַל גַּם מָרָק","מַסְפִּיק לִרְחֹץ יָדַיִם, וּמֻתָּר לֶאֱכֹל חָלָב"],1,"מִי שֶׁאָכַל תַּבְשִׁיל שֶׁל בָּשָׂר - מַה שֶּׁהִתְבַּשֵּׁל עִם הַבָּשָׂר, גַּם בְּלִי הַבָּשָׂר עַצְמוֹ - מַמְתִּין כְּמוֹ אַחֲרֵי בָּשָׂר מַמָּשׁ.","פֶּרֶק ק״א, הֲלָכָה ז׳","בָּשָׂר וְחָלָב"],["אָבִי אָכַל מַאֲכַל חָלָב וְרוֹצֶה לֶאֱכֹל בָּשָׂר מִיָּד. מָה יַעֲשֶׂה?",["יַמְתִּין שֵׁשׁ שָׁעוֹת, כְּמוֹ אַחֲרֵי אֲכִילַת בָּשָׂר","יִשְׁתֶּה כּוֹס חָלָב נוֹסֶפֶת לִפְנֵי הַבָּשָׂר","אֵין שׁוּם דֶּרֶךְ, אָסוּר לוֹ בָּשָׂר הַיּוֹם","יֹאכַל מַאֲכַל פַּרְוֶה וְיִשְׁטֹף אֶת הַפֶּה בְּמַיִם"],3,"אֶפְשָׁר לִרְחֹץ יָדַיִם וּלְצַחְצֵחַ שִׁנַּיִם, אוֹ לֶאֱכֹל מַאֲכַל פַּרְוֶה וְלִשְׁטֹף אֶת הַפֶּה בְּמַיִם, וְאָז לֶאֱכֹל בָּשָׂר מִיָּד. וְיֵשׁ שֶׁנָּהֲגוּ לְהַמְתִּין לְפָחוֹת חֲצִי שָׁעָה.","פֶּרֶק ק״א, הֲלָכָה ח׳","בָּשָׂר וְחָלָב"],["מָה הַהֶבְדֵּל בֵּין גְּבִינָה קָשָׁה לִגְבִינָה רַכָּה לְעִנְיַן הַמְתָּנָה?",["אַחֲרֵי רַכָּה מַמְתִּינִים, וְאַחֲרֵי קָשָׁה אֵין צֹרֶךְ","אַחֲרֵי שְׁתֵּיהֶן צָרִיךְ לְהַמְתִּין שֵׁשׁ שָׁעוֹת","אַחֲרֵי קָשָׁה מַמְתִּינִים, וְאַחֲרֵי רַכָּה אֵין צֹרֶךְ","אַחֲרֵי שְׁתֵּיהֶן אֵין צֹרֶךְ לְהַמְתִּין כְּלָל"],2,"אַחֲרֵי גְּבִינָה קָשָׁה (שֶׁיִּצּוּרָהּ אָרַךְ שִׁשָּׁה חֳדָשִׁים) מַמְתִּינִים כְּמוֹ בֵּין בָּשָׂר לְחָלָב, וְאַחֲרֵי גְּבִינָה רַכָּה אֵין צָרִיךְ לְהַמְתִּין.","פֶּרֶק ק״א, הֲלָכָה ט׳","בָּשָׂר וְחָלָב"],["מָה מִנְהַג הַמְּדַקְדְּקִים בְּעִנְיַן סַכִּינִים בַּבַּיִת?",["שָׁלוֹשׁ סַכִּינִים: לְבָשָׂר, לִגְבִינָה וּלְלֶחֶם","סַכִּין אַחַת לַכֹּל, וּמְנַקִּים אוֹתָהּ הֵיטֵב","שְׁתֵּי סַכִּינִים: אַחַת לְבָשָׂר וְאַחַת לְלֶחֶם","אַרְבַּע סַכִּינִים, אַחַת לְכָל אֶחָד בַּבַּיִת"],0,"הַמִּנְהָג שֶׁיֵּשׁ שְׁתֵּי מַעַרְכוֹת כֵּלִים, חֲלָבִית וּבְשָׂרִית, וְלַמְּדַקְדְּקִים שָׁלוֹשׁ סַכִּינִים: לְבָשָׂר, לִגְבִינָה וּלְלֶחֶם - וּמִנְהָג נָכוֹן הוּא. וּמִי שֶׁאָכַל גְּבִינָה וְרוֹצֶה בָּשָׂר מַחְלִיף מַפָּה וּמֵסִיר שְׁאֵרִיּוֹת לֶחֶם.","פֶּרֶק ק״א, הֲלָכוֹת י׳-י״א","בָּשָׂר וְחָלָב"],["מָה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יִשְׂרָאֵל וְעַל הָאָרֶץ?",["הָאָרֶץ תִּהְיֶה שֶׁל מִי שֶׁיָּבוֹא אֵלֶיהָ רִאשׁוֹן","כָּל הָאֻמּוֹת יֵשְׁבוּ יַחַד בָּאָרֶץ הַזֹּאת","יָבוֹאוּ יִשְׂרָאֵל שֶׁבָּאוּ לְחֶלְקִי וְיִנְחֲלוּ אֶת הָאָרֶץ","שָׂרֵי הָאֻמּוֹת יִנְחֲלוּ אֶת הָאָרֶץ לְעוֹלָם וָעֶד"],2,"״יָבוֹאוּ יִשְׂרָאֵל שֶׁבָּאוּ לְחֶלְקִי וְיִנְחֲלוּ אֶת הָאָרֶץ שֶׁבָּאָה לְחֶלְקִי״ – הָעָם הַנִּבְחָר בָּאָרֶץ הַנִּבְחֶרֶת.","פֶּרֶק ק״ב, הֲלָכָה א׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["בַּמֶּה מִתְבַּטֵּאת קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל לְפִי הַמָּקוֹר?",["בַּקִּרְבָה לַשְּׁכִינָה וּבְכָךְ שֶׁאֵינָהּ סוֹבֶלֶת עוֹבְרֵי עֲבֵרוֹת","בְּכָךְ שֶׁהִיא הָאֶרֶץ הַגְּדוֹלָה בְּיוֹתֵר בָּעוֹלָם כֻּלּוֹ","בְּכָךְ שֶׁיֵּשׁ בָּהּ הַרְבֵּה זָהָב וָכֶסֶף","בְּכָךְ שֶׁכָּל הָאֻמּוֹת רוֹצוֹת לָגוּר בָּהּ תָּמִיד"],0,"קְדֻשָּׁתָהּ הִיא בַּקִּרְבָה לִמְקוֹם הַשְּׁכִינָה, וּבְכָךְ שֶׁאֵינָהּ סוֹבֶלֶת עוֹבְרֵי עֲבֵרוֹת.","פֶּרֶק ק״ב, הֲלָכָה ב׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["מָה לוֹמְדִים מִמְּשַׁל בֶּן הַמְּלָכִים?",["שֶׁבֶּן מְלָכִים צָרִיךְ לֶאֱכֹל רַק מַאֲכָלִים מְיֻחָדִים וּטְעִימִים","שֶׁהָאָרֶץ אֵינָהּ מְקַיֶּמֶת עוֹבְרֵי עֲבֵרוֹת אֶלָּא מְקִיאָה אוֹתָם","שֶׁהָאָרֶץ מַצְמִיחָה פֵּרוֹת רַק בִּשְׁנַת שָׁלוֹם","שֶׁאָסוּר לֶאֱכֹל הַרְבֵּה מְאוֹד בִּסְעוּדָה אַחַת"],1,"כְּמוֹ שֶׁבֶּן מְלָכִים מְקִיא מַאֲכָל שֶׁאֵינוֹ עוֹמֵד בְּמֵעָיו, כָּךְ הָאָרֶץ אֵינָהּ מְקַיֶּמֶת עוֹבְרֵי עֲבֵרוֹת, כְּמוֹ שֶׁנֶּאֱמַר ״וְלֹא תָקִיא הָאָרֶץ אֶתְכֶם״.","פֶּרֶק ק״ב, הֲלָכָה ב׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["מָה לָמְדוּ מֵהַפָּסוּק ״וִירִשְׁתֶּם אֹתָהּ וִישַׁבְתֶּם בָּהּ״?",["שֶׁמֻּתָּר לְהַשְׁאִיר אֶת הָאָרֶץ שְׁמָמָה בְּלִי יוֹשְׁבִים","שֶׁאֶפְשָׁר לָתֵת אֶת הָאָרֶץ לְאֻמּוֹת אֲחֵרוֹת","שֶׁרַק הַכֹּהֲנִים וְהַלְוִיִּם צְרִיכִים לָגוּר בָּאָרֶץ הַזֹּאת","שֶׁעַם יִשְׂרָאֵל מְצֻוֶּה לָרֶשֶׁת אֶת הָאָרֶץ וְלָשֶׁבֶת בָּהּ"],3,"מִכָּאן שֶׁעַם יִשְׂרָאֵל מְצֻוֶּה לָרֶשֶׁת אֶת הָאָרֶץ, וְלֹא לַעֲזֹב אוֹתָהּ בְּיַד הָאֻמּוֹת אוֹ לְהַשְׁאִיר אוֹתָהּ שְׁמָמָה.","פֶּרֶק ק״ב, הֲלָכָה ג׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["לְפִי רַבּוֹתֵינוּ, יְשִׁיבַת אֶרֶץ יִשְׂרָאֵל שְׁקוּלָה כְּנֶגֶד מָה?",["שְׁקוּלָה רַק כְּנֶגֶד מִצְוַת צִיצִית","שְׁקוּלָה כְּנֶגֶד חֲצִי מִן הַמִּצְווֹת","הִיא שְׁקוּלָה כְּנֶגֶד כָּל הַמִּצְווֹת","אֵינָהּ מִצְוָה כְּלָל, רַק מִנְהָג טוֹב"],2,"אָמְרוּ רַבּוֹתֵינוּ שֶׁיְּשִׁיבַת אֶרֶץ יִשְׂרָאֵל שְׁקוּלָה כְּנֶגֶד כָּל הַמִּצְווֹת.","פֶּרֶק ק״ב, הֲלָכָה ג׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["הַאִם מִצְוַת יְשִׁיבַת הָאָרֶץ נוֹהֶגֶת גַּם בִּזְמַן הַגָּלוּת?",["כֵּן, הִיא נוֹהֶגֶת בְּכָל הַדּוֹרוֹת וְכָל אָדָם חַיָּב","לֹא, הִיא נָהֲגָה רַק בִּימֵי יְהוֹשֻׁעַ בִּן נוּן","לֹא, רַק כְּשֶׁבֵּית הַמִּקְדָּשׁ עוֹמֵד עַל מְקוֹמוֹ","רַק אִם הַמֶּלֶךְ שֶׁל הָאֻמּוֹת מַרְשֶׁה זֹאת"],0,"מִצְוַת יְשִׁיבַת אֶרֶץ יִשְׂרָאֵל נוֹהֶגֶת בְּכָל הַדּוֹרוֹת וְכָל אָדָם מִיִּשְׂרָאֵל חַיָּב בָּהּ, גַּם בִּזְמַן הַגָּלוּת.","פֶּרֶק ק״ב, הֲלָכָה ד׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["לְדַעַת פּוֹסְקִים רַבִּים, מָה דִּין מִי שֶׁיָּכוֹל לַעֲלוֹת לָאָרֶץ וְאֵינוֹ עוֹלֶה?",["אֵין בְּכָךְ שׁוּם בְּעָיָה, כִּי זוֹ רְשׁוּת בִּלְבַד","עוֹבֵר עַל הַמִּצְוָה רַק פַּעַם אַחַת בְּשָׁנָה","עוֹבֵר עַל הַמִּצְוָה רַק בְּיוֹם הֻלַּדְתּוֹ","עוֹבֵר עַל מִצְוַת עֲשֵׂה זוֹ בְּכָל יוֹם"],3,"לְדַעַת פּוֹסְקֵי הֲלָכָה רַבִּים, מִי שֶׁיָּכוֹל לַעֲלוֹת וְאֵין דָּבָר שֶׁמְּעַכֵּב אוֹתוֹ, עוֹבֵר עַל מִצְוַת עֲשֵׂה זוֹ בְּכָל יוֹם שֶׁהוּא נִשְׁאָר בְּחוּץ לָאָרֶץ.","פֶּרֶק ק״ב, הֲלָכָה ד׳","קְדֻשַּׁת אֶרֶץ יִשְׂרָאֵל"],["כַּמָּה שָׁנִים מֵעֵת הַנְּטִיעָה אֲסוּרִים פֵּרוֹת הָעֵץ?",["שָׁנָה אַחַת, וְאַחַר כָּךְ מֻתָּר לֶאֱכֹל","שֶׁבַע שָׁנִים, כְּמוֹ מִנְיַן שְׁנוֹת הַשְּׁמִטָּה","שָׁלוֹשׁ שָׁנִים, וְהַפֵּרוֹת אֲסוּרִים גַּם בַּהֲנָאָה","שְׁתֵּי שָׁנִים, וְרַק אֲכִילָה אֲסוּרָה בָּהֶם"],2,"סוֹפְרִים שָׁלוֹשׁ שָׁנִים מֵעֵת הַנְּטִיעָה, וְכָל הַפֵּרוֹת שֶׁגְּדֵלִים בָּהֶן אֲסוּרִים בַּהֲנָאָה.","פֶּרֶק ק״ג, הֲלָכָה א׳","עָרְלָה וְנֶטַע רְבָעִי"],["מַדּוּעַ אֵין אִסּוּר עָרְלָה בְּצֶמַח בָּנָנָה?",["כִּי הַגֶּזַע מִתְיַבֵּשׁ וְגֶזַע אַחֵר יוֹצֵא מֵהַשָּׁרָשִׁים","כִּי הַבָּנָנָה גְּדֵלָה רַק מִחוּץ לְאֶרֶץ יִשְׂרָאֵל","כִּי פְּרִי הַבָּנָנָה אֵינוֹ נֶחְשָׁב פְּרִי מַאֲכָל","כִּי הַבָּנָנָה נוֹתֶנֶת פֵּרוֹת רַק אַחֲרֵי עֶשֶׂר שָׁנִים"],0,"עָרְלָה נוֹהֶגֶת רַק בְּעֵץ שֶׁגִּזְעוֹ מִתְקַיֵּם שָׁלוֹשׁ שָׁנִים. בַּבָּנָנָה הַגֶּזַע מִתְיַבֵּשׁ אַחֲרֵי הַקְּטִיף וְיוֹצֵא גֶּזַע חָדָשׁ.","פֶּרֶק ק״ג, הֲלָכוֹת ב׳-ג׳","עָרְלָה וְנֶטַע רְבָעִי"],["מָה הַדִּין בְּפָּסִיפְלוֹרָה, שֶׁמּוֹצִיאָה פֵּרוֹת כְּבָר בַּשָּׁנָה הָרִאשׁוֹנָה?",["הִיא עֵץ לְכָל דָּבָר, וְכֻלָּם אוֹסְרִים","אֲסוּרָה רַק אִם הַגֶּזַע שֶׁלָּהּ גָּבוֹהַּ","מֻתֶּרֶת רַק אַחֲרֵי פִּדְיוֹן בִּפְרוּטָה אַחַת","אֵינָהּ נֶחְשֶׁבֶת עֵץ, וְיֵשׁ מַחְמִירִים בְּכָךְ"],3,"צֶמַח שֶׁמּוֹצִיא פֵּרוֹת בַּשָּׁנָה הָרִאשׁוֹנָה אֵינוֹ נֶחְשָׁב עֵץ, אֲפִלּוּ אִם גִּזְעוֹ מִתְקַיֵּם כַּמָּה שָׁנִים, וְיֵשׁ מַחְמִירִים.","פֶּרֶק ק״ג, הֲלָכָה ד׳","עָרְלָה וְנֶטַע רְבָעִי"],["עֵץ נִטַּע לִפְנֵי ט״ז בְּאָב. כַּמָּה זְמַן עֲשׂוּיוֹת לִהְיוֹת שְׁנוֹת הָעָרְלָה שֶׁלּוֹ?",["שָׁלוֹשׁ שָׁנִים שְׁלֵמוֹת מִיּוֹם הַנְּטִיעָה","שְׁנָתַיִם וְאַרְבָּעִים וְאַרְבָּעָה יָמִים בִּלְבַד","אַרְבַּע שָׁנִים, כִּי הַשָּׁנָה הָרִאשׁוֹנָה לֹא נִסְפֶּרֶת","שָׁנָה אַחַת וּשְׁלוֹשִׁים יָמִים בִּלְבַד"],1,"לְפִי הַכְּלָל ״מִקְצָתוֹ כְּכֻלּוֹ״ הַמ״ד יָמִים עַד רֹאשׁ הַשָּׁנָה נֶחְשָׁבִים שָׁנָה (14 יְמֵי הַשְׁרָשָׁה וְעוֹד 30 יוֹם), וְאַחֲרֵיהֶם עוֹד שְׁנָתַיִם שְׁלֵמוֹת.","פֶּרֶק ק״ג, הֲלָכוֹת ה׳-ו׳","עָרְלָה וְנֶטַע רְבָעִי"],["פְּרִי חָנַט לִפְנֵי ט״וּ בִּשְׁבָט שֶׁל הַשָּׁנָה הָרְבִיעִית. מָה דִּינוֹ?",["שַׁיָּךְ לַשָּׁנָה הָרְבִיעִית וְצָרִיךְ פִּדְיוֹן בִּפְרוּטָה","פְּרִי רָגִיל לְגַמְרֵי וּמֻתָּר מִיָּד בַּאֲכִילָה","שַׁיָּךְ לַשָּׁנָה הַשְּׁלִישִׁית וְאָסוּר בַּהֲנָאָה","אָסוּר בַּאֲכִילָה אֲבָל מֻתָּר לִמְכֹּר אוֹתוֹ"],2,"ט״וּ בִּשְׁבָט קוֹבֵעַ לְאֵיזוֹ שָׁנָה שַׁיָּךְ הַפְּרִי, וּפְרִי שֶׁחָנַט לְפָנָיו שַׁיָּךְ עֲדַיִן לַשָּׁנָה הַשְּׁלִישִׁית.","פֶּרֶק ק״ג, הֲלָכָה ז׳","עָרְלָה וְנֶטַע רְבָעִי"],["לָמָּה הַגָּרִים רָחוֹק מִירוּשָׁלַיִם פָּדוּ אֶת פֵּרוֹת הַשָּׁנָה הָרְבִיעִית?",["כְּדֵי שֶׁהַפֵּרוֹת לֹא יִתְקַלְקְלוּ בַּדֶּרֶךְ הָאֲרֻכָּה","כְּדֵי שֶׁלֹּא יִצְטָרְכוּ לַעֲלוֹת לִירוּשָׁלַיִם כְּלָל","כִּי אָסוּר הָיָה לְהַכְנִיס פֵּרוֹת לְתוֹךְ הָעִיר","כְּדֵי לְחַלֵּק אֶת הַכֶּסֶף לָעֲנִיִּים בְּעִירָם"],0,"פָּדוּ אֶת הַפֵּרוֹת בְּשָׁוְיָם וְעוֹד חֹמֶשׁ כְּדֵי שֶׁלֹּא יִתְקַלְקְלוּ, וּבַכֶּסֶף קָנוּ מַאֲכָל וְאָכְלוּ בְּטָהֳרָה בִּירוּשָׁלַיִם.","פֶּרֶק ק״ג, הֲלָכָה ח׳","עָרְלָה וְנֶטַע רְבָעִי"],["מָה אוֹמְרִים בְּשָׁעַת פִּדְיוֹן פֵּרוֹת נֶטַע רְבָעִי, אַחֲרֵי הַבְּרָכָה?",["הַפֵּרוֹת הָאֵלֶּה מֻתָּרִים מֵעַכְשָׁיו לְכָל אָדָם בְּחִנָּם","הַפֵּרוֹת הַלָּלוּ, הֵם וְחֻמְשָׁם, פְּדוּיִים בִּפְרוּטָה זֹאת","הֲרֵי הַפֵּרוֹת הָאֵלֶּה שַׁיָּכִים לַכֹּהֵן שֶׁבָּעִיר","הַפֵּרוֹת הָאֵלֶּה יִשָּׁאֲרוּ עַל הָעֵץ עַד שָׁנָה הַבָּאָה"],1,"אַחֲרֵי הַבְּרָכָה ״עַל פִּדְיוֹן רְבָעִי״ אוֹמְרִים: ״הַפֵּרוֹת הַלָּלוּ, הֵם וְחֻמְשָׁם, פְּדוּיִים בִּפְרוּטָה זֹאת״.","פֶּרֶק ק״ג, הֲלָכוֹת ט׳-י׳","עָרְלָה וְנֶטַע רְבָעִי"],["מָה הָאֶפְשָׁרוּת הַנּוֹסֶפֶת לְפִדְיוֹן, בִּמְקוֹם מַטְבֵּעַ?",["לִפְדּוֹת בְּסֵפֶר קָדוֹשׁ וּלְהַחְזִיר אוֹתוֹ לַמַּדָּף","לִפְדּוֹת בְּמַטְבֵּעַ גָּדוֹל וְלָתֵת אוֹתוֹ לִצְדָקָה","לִפְדּוֹת בְּפֵרוֹת אֲחֵרִים וְלֶאֱכֹל אוֹתָם מִיָּד","לִפְדּוֹת בִּפְרִי שֶׁשָּׁוֶה פְּרוּטָה וְלִזְרֹק אוֹתוֹ בְּכָבוֹד"],3,"אֶפְשָׁר לִפְדּוֹת בִּפְרִי שֶׁשָּׁוֶה פְּרוּטָה, וְאַחַר כָּךְ לִזְרֹק אֶת הַפְּרִי בְּצוּרָה מְכֻבֶּדֶת.","פֶּרֶק ק״ג, הֲלָכָה י״א","עָרְלָה וְנֶטַע רְבָעִי"],["עֵץ נִטַּע בְּי״ד בְּאָב תשע״ו. מָה הֵם הַפֵּרוֹת שֶׁחָנְטוּ בֵּין ט״וּ בִּשְׁבָט תשע״ט לְט״וּ בִּשְׁבָט תש״פ?",["עָרְלָה, וַאֲסוּרִים בַּהֲנָאָה עַד תש״פ","פֵּרוֹת רְגִילִים לְגַמְרֵי, בְּלִי שׁוּם דִּין","נֶטַע רְבָעִי, וְצָרִיךְ לִפְדּוֹת אוֹתָם","שַׁיָּכִים עֲדַיִן לַשָּׁנָה הַשְּׁלִישִׁית, שְׁנַת תשע״ח"],2,"תשע״ו, תשע״ז וְתשע״ח הֵן שְׁנוֹת עָרְלָה. מִט״וּ בִּשְׁבָט תשע״ט עַד ט״וּ בִּשְׁבָט תש״פ הַפֵּרוֹת הֵם נֶטַע רְבָעִי וְצָרִיךְ לִפְדּוֹת אוֹתָם.","פֶּרֶק ק״ג, הֲלָכָה י״ב","עָרְלָה וְנֶטַע רְבָעִי"],["מַדּוּעַ צָרִיךְ לִבְדֹּק תְּעוּדַת הֶכְשֵׁר גַּם כְּשֶׁקּוֹנִים פֵּרוֹת?",["כִּי פֵּרוֹת יְשָׁנִים אֵינָם טְעִימִים כְּמוֹ חֲדָשִׁים","כִּי בַּמַּטָּעִים נוֹטְעִים עֵצִים חֲדָשִׁים בְּכָל שָׁנָה","כִּי כָּל הַפֵּרוֹת בַּחֲנֻיּוֹת הֵם תָּמִיד עָרְלָה","כִּי אָסוּר לִקְנוֹת פֵּרוֹת בְּלִי חֶשְׁבּוֹנִית"],1,"בְּכָל שָׁנָה נוֹטְעִים עֵצִים חֲדָשִׁים, לָכֵן קוֹנִים בַּחֲנוּת עִם הֶכְשֵׁר שֶׁכָּתוּב בּוֹ שֶׁהַפֵּרוֹת אֵינָם עָרְלָה, וְכָךְ גַּם בְּקֻפְסְאוֹת שִׁמּוּרִים.","פֶּרֶק ק״ג, הֲלָכָה י״ג","עָרְלָה וְנֶטַע רְבָעִי"],["לְשֵׁם מָה בָּאָה מִצְוַת תְּרוּמוֹת וּמַעַשְׂרוֹת?",["כְּדֵי שֶׁהַשָּׂדֶה יַצְמִיחַ פֵּרוֹת גְּדוֹלִים וְטוֹבִים יוֹתֵר בַּשָּׁנָה הַבָּאָה","כְּדֵי לְהַקְטִין אֶת כַּמּוּת הַפֵּרוֹת הַנִּמְכָּרִים בַּשּׁוּק","כְּדֵי שֶׁהָאָדָם יַרְגִּישׁ שֶׁהוּא הָאָדוֹן הַבִּלְעָדִי עַל שָׂדֵהוּ","לְהַזְכִּיר שֶׁהַצְלָחַת הָאָדָם בָּאָה מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא"],3,"הַמִּצְוָה מַזְכִּירָה לָאָדָם שֶׁאֵין הוּא הָאָדוֹן הַבִּלְעָדִי עַל שָׂדֵהוּ, אֶלָּא הַצְלָחָתוֹ מֵאֵת ה׳, וְלָכֵן עָלָיו לְהוֹדוֹת לוֹ.","פֶּרֶק ק״ד, הֲלָכָה א׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["לְפִי הַדֻּגְמָה בַּסֵּפֶר, אֵיזוֹ שָׁנָה הָיְתָה שְׁנַת שְׁמִטָּה?",["שְׁנַת תשע״ו הָיְתָה שְׁנַת הַשְּׁמִטָּה בַּמַּחְזוֹר","שְׁנַת תשפ״ב הָיְתָה שְׁנַת הַשְּׁמִטָּה בַּמַּחְזוֹר","שְׁנַת תש״פ הָיְתָה שְׁנַת הַשְּׁמִטָּה בַּמַּחְזוֹר","שְׁנַת תשפ״ג הָיְתָה שְׁנַת הַשְּׁמִטָּה בַּמַּחְזוֹר"],1,"תשע״ו – שָׁנָה רִאשׁוֹנָה, וְכָךְ הָלְאָה עַד תשפ״ב – שְׁנַת שְׁמִטָּה. תשפ״ג שׁוּב שָׁנָה רִאשׁוֹנָה.","פֶּרֶק ק״ד, הֲלָכָה ד׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["מַהוּ טֶבֶל?",["פֵּרוֹת שֶׁגָּדְלוּ בְּחוּץ לָאָרֶץ וּמֻתָּרִים בַּאֲכִילָה לְכֻלָּם","הַחֵלֶק שֶׁמַּפְרִישִׁים מֵהַפֵּרוֹת וְנוֹתְנִים אוֹתוֹ לַכֹּהֵן הַטָּהוֹר","פֵּרוֹת שֶׁלֹּא הֻפְרְשׁוּ מֵהֶם תְּרוּמוֹת וּמַעַשְׂרוֹת וַאֲסוּרִים בַּאֲכִילָה","פֵּרוֹת שֶׁכְּבָר הֻפְרְשׁוּ מֵהֶם כָּל הַתְּרוּמוֹת וְהַמַּעַשְׂרוֹת"],2,"פֵּרוֹת, יְרָקוֹת, תְּבוּאָה וְקִטְנִיּוֹת מֵאֶרֶץ יִשְׂרָאֵל שֶׁלֹּא הֻפְרְשׁוּ מֵהֶם תְּרוּמוֹת וּמַעַשְׂרוֹת – נִקְרָאִים טֶבֶל וַאֲסוּרִים בַּאֲכִילָה.","פֶּרֶק ק״ד, הֲלָכָה ה׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["מָתַי יֵשׁ לְהַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת?",["לְאַחַר שֶׁקּוֹצְרִים אוֹ אוֹסְפִים וְנִגְמְרָה מְלַאכְתָּם","מִיָּד כְּשֶׁהַפְּרִי מַתְחִיל לִצְמֹחַ עַל הָעֵץ","רַק לִפְנֵי שֶׁזּוֹרְעִים אֶת הַשָּׂדֶה בַּשָּׁנָה","רַק לְאַחַר שֶׁהַפֵּרוֹת נִרְקְבוּ וְהִתְקַלְקְלוּ לְגַמְרֵי"],0,"לְאַחַר שֶׁקּוֹצְרִים אֶת הַתְּבוּאָה אוֹ אוֹסְפִים אֶת פֵּרוֹת הָאִילָן וְנִגְמְרָה מְלַאכְתָּם – מַפְרִישִׁים: תְּרוּמָה גְּדוֹלָה, מַעֲשֵׂר רִאשׁוֹן, תְּרוּמַת מַעֲשֵׂר, וּמַעֲשֵׂר שֵׁנִי אוֹ מַעֲשַׂר עָנִי.","פֶּרֶק ק״ד, הֲלָכָה ו׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["מַה נוֹהֲגִים רַבִּים לַעֲשׂוֹת כְּדֵי לְהִשְׁתַּמֵּשׁ בַּמַּעֲשֵׂר הָרִאשׁוֹן?",["נוֹתְנִים לַלֵּוִי הַלְוָאָה מֵרֹאשׁ וּמְסַכְּמִים שֶׁיַּרְשֶׁה לְהִשְׁתַּמֵּשׁ בַּפֵּרוֹת","שׂוֹרְפִים אֶת הַמַּעֲשֵׂר הָרִאשׁוֹן בָּאֵשׁ לִפְנֵי שֶׁיִּתְקַלְקֵל","מוֹכְרִים אֶת הַמַּעֲשֵׂר בַּשּׁוּק וְנוֹתְנִים אֶת הַכֶּסֶף לַכֹּהֵן","שׁוֹמְרִים אֶת הַמַּעֲשֵׂר בַּמַּחְסָן עַד שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ"],0,"אֶת הַמַּעֲשֵׂר הָרִאשׁוֹן נוֹתְנִים לַלֵּוִי, וְרַבִּים נוֹתְנִים לוֹ מֵרֹאשׁ הַלְוָאָה וּמְסַכְּמִים שֶׁהַבְּעָלִים יִשְׁתַּמְּשׁוּ בַּפֵּרוֹת בִּמְקוֹם הֶחְזֵר הַחוֹב.","פֶּרֶק ק״ד, הֲלָכוֹת ז׳-ח׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["הֵיכָן טוֹב לִקְנוֹת פֵּרוֹת וִירָקוֹת?",["בַּחֲנוּת שֶׁהַפֵּרוֹת בָּהּ הֲכִי זוֹלִים וְהֲכִי יָפִים","בְּכָל חֲנוּת, כִּי אֵין צֹרֶךְ לִבְדֹּק דָּבָר","בַּחֲנוּת שֶׁיֵּשׁ לָהּ תְּעוּדַת הֶכְשֵׁר שֶׁל הָרַבָּנוּת עַל הַהַפְרָשָׁה","רַק בַּחֲנוּת שֶׁהַמּוֹכֵר בָּהּ הוּא כֹּהֵן אוֹ לֵוִי"],2,"טוֹב לִקְנוֹת רַק בַּחֲנוּיוֹת עִם תְּעוּדַת הֶכְשֵׁר מִטַּעַם הָרַבָּנוּת שֶׁכָּתוּב בָּהּ שֶׁהֻפְרְשׁוּ תְּרוּמוֹת וּמַעַשְׂרוֹת כַּדִּין.","פֶּרֶק ק״ד, הֲלָכָה ט׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["קִבַּלְנוּ יְרָקוֹת וְיֵשׁ סָפֵק אִם הִפְרִישׁוּ מֵהֶם. מָה עוֹשִׂים?",["מַפְרִישִׁים כַּדִּין וּמְבָרְכִים כְּמוֹ עַל טֶבֶל וַדַּאי","אֵין צָרִיךְ לְהַפְרִישׁ כְּלָל, כִּי זֶה רַק סָפֵק","זוֹרְקִים אֶת כָּל הַיְּרָקוֹת לָאַשְׁפָּה מִיָּד","מַפְרִישִׁים כַּדִּין אֲבָל אֵין מְבָרְכִים עַל הַהַפְרָשָׁה"],3,"מִי שֶׁקָּנָה אוֹ קִבֵּל פֵּרוֹת בְּסָפֵק – חַיָּב לְהַפְרִישׁ כַּדִּין, אֶלָּא שֶׁאֵין לְבָרֵךְ עַל הַפְרָשָׁה זוֹ.","פֶּרֶק ק״ד, הֲלָכָה י׳","תְּרוּמוֹת וּמַעַשְׂרוֹת"],["מֵאֵיזֶה פָּסוּק לְמֵדִים שֶׁצָּרִיךְ לְהַפְקִיר אֶת גִּדּוּלֵי הַשְּׁבִיעִית?",["שָׂדְךָ לֹא תִזְרָע וְכַרְמְךָ לֹא תִזְמֹר","אֵת סְפִיחַ קְצִירְךָ לֹא תִקְצוֹר","וְהַשְּׁבִיעִת תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ, וְאָכְלוּ אֶבְיֹנֵי עַמֶּךָ","וְשֵׁשׁ שָׁנִים תִּזְרַע אֶת אַרְצֶךָ"],2,"מְצֻוִּים לְהַפְקִיר אֶת גִּדּוּלֵי הַשְּׁבִיעִית, שֶׁנֶּאֱמַר: ״וְהַשְּׁבִיעִת תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ, וְאָכְלוּ אֶבְיֹנֵי עַמֶּךָ״.","פֶּרֶק ק״ה, הֲלָכָה א׳","שְׁנַת הַשְּׁמִטָּה"],["אֵיזוֹ מִדָּה מְחַזֵּק הָאָדָם בְּלִבּוֹ כְּשֶׁהוּא שׁוֹבֵת שָׁנָה שְׁלֵמָה?",["אֶת מִדַּת הַוַּתְרָנוּת, כִּי הָאָרֶץ הִיא לַה׳","אֶת מִדַּת הַגַּאֲוָה, כִּי הוּא אֲדוֹן הַשָּׂדֶה","אֶת מִדַּת הַקִּנְאָה בַּשְּׁכֵנִים שֶׁיֵּשׁ לָהֶם יוֹתֵר","אֶת מִדַּת הָעַצְלוּת, כִּי אֵין לוֹ מַה לַּעֲשׂוֹת"],0,"הַשּׁוֹבֵת זוֹכֵר שֶׁאֵין הוּא אָדוֹן עַל הָאָרֶץ אֶלָּא הִיא לַה׳, וּמְחַזֵּק בְּלִבּוֹ אֶת מִדַּת הַוַּתְרָנוּת.","פֶּרֶק ק״ה, הֲלָכָה ב׳","שְׁנַת הַשְּׁמִטָּה"],["מַדּוּעַ הַשְּׁמִטָּה בִּזְמַנֵּנוּ הִיא מִדִּבְרֵי חֲכָמִים וְלֹא מִן הַתּוֹרָה?",["כִּי אֵין הַיּוֹם שָׂדוֹת וּכְרָמִים בְּאֶרֶץ יִשְׂרָאֵל","כִּי רֹב עַם יִשְׂרָאֵל אֵינוֹ בְּאֶרֶץ יִשְׂרָאֵל","כִּי הַתּוֹרָה צִוְּתָה רַק עַל הַכֹּהֲנִים בַּמִּקְדָּשׁ","כִּי הָאֲדָמָה כְּבָר נָחָה מַסְפִּיק בַּשָּׁנִים הַקּוֹדְמוֹת"],1,"בִּזְמַן שֶׁרֹב עַם יִשְׂרָאֵל אֵינוֹ בְּאֶרֶץ יִשְׂרָאֵל, הַשְּׁמִטָּה נוֹהֶגֶת מִדִּבְרֵי חֲכָמִים בִּלְבַד.","פֶּרֶק ק״ה, הֲלָכָה ג׳","שְׁנַת הַשְּׁמִטָּה"],["כַּמָּה מֻתָּר לִקְטֹף מִפֵּרוֹת הַשְּׁבִיעִית לְצֹרֶךְ הַבַּיִת?",["כַּמּוּת גְּדוֹלָה כְּדֵי לִמְכֹּר אוֹתָהּ בַּשּׁוּק","כָּל מַה שֶּׁרוֹצִים, בְּלִי שׁוּם הַגְבָּלָה בִּכְלָל","אָסוּר לִקְטֹף אֲפִלּוּ פְּרִי אֶחָד מִן הָעֵץ","כַּמּוּת שֶׁמַּסְפִּיקָה לְכַמָּה יָמִים לִצְרָכִים בֵּיתִיִּים"],3,"מֻתָּר לִקְטֹף לִצְרָכִים בֵּיתִיִּים כַּמּוּת שֶׁמַּסְפִּיקָה לְכַמָּה יָמִים, אֲבָל לְמִסְחָר אָסוּר אֲפִלּוּ מְעַט.","פֶּרֶק ק״ה, הֲלָכָה ד׳","שְׁנַת הַשְּׁמִטָּה"],["מַדּוּעַ מֻתָּר לְהַשְׁקוֹת צְמָחִים בִּשְׁנַת הַשְּׁמִטָּה?",["כִּי הַהַשְׁקָיָה שׁוֹמֶרֶת עַל הַקַּיָּם שֶׁהַצְּמָחִים לֹא יָמוּתוּ","כִּי מַיִם אֵינָם נֶחְשָׁבִים לַעֲבוֹדָה בְּשׁוּם מָקוֹם","כִּי הַהַשְׁקָיָה נוֹעֲדָה לְהַגְדִּיל אֶת הַיְּבוּל בְּשֶׁפַע רַב","כִּי בַּשְּׁמִטָּה מֻתָּר לַעֲשׂוֹת כָּל מְלֶאכֶת קַרְקַע"],0,"מְלָאכוֹת שֶׁנּוֹעֲדוּ לִשְׁמֹר עַל הַקַּיָּם, כְּהַשְׁקָיָה כְּדֵי שֶׁהַצְּמָחִים לֹא יָמוּתוּ – לֹא נֶאֶסְרוּ.","פֶּרֶק ק״ה, הֲלָכָה ה׳","שְׁנַת הַשְּׁמִטָּה"],["מֵאֵיזֶה לָשׁוֹן בַּפָּסוּק לָמְדוּ שֶׁאֲכִילַת פֵּרוֹת שְׁבִיעִית הִיא מִצְוָה?",["מֵהַמִּלִּים ״לֹא תִזְרָע״ שֶׁנֶּאֶמְרוּ עַל הַשָּׂדֶה","מֵהַמִּלִּים ״לֹא תִבְצֹר״ שֶׁנֶּאֶמְרוּ עַל הָעֲנָבִים","מֵהַמִּלִּים ״לָכֶם לְאָכְלָה״ שֶׁנֶּאֶמְרוּ עַל שַׁבַּת הָאָרֶץ","מֵהַמִּלִּים ״וְאָסַפְתָּ אֶת תְּבוּאָתָהּ״ שֶׁנֶּאֶמְרוּ עַל שֵׁשׁ שָׁנִים"],2,"יֵשׁ אוֹמְרִים שֶׁזּוֹ מִצְוָה, שֶׁנֶּאֱמַר: ״וְהָיְתָה שַׁבַּת הָאָרֶץ לָכֶם לְאָכְלָה״.","פֶּרֶק ק״ה, הֲלָכָה ו׳","שְׁנַת הַשְּׁמִטָּה"],["מַדּוּעַ הָרַבָּנוּת מְפַרְסֶמֶת זְמַנִּים בְּכָל שְׁנַת שְׁמִטָּה?",["כִּי צָרִיךְ לָדַעַת מָתַי מַתְחִילִים לִזְרֹעַ אֶת הַשָּׂדוֹת","כִּי זְמַן חָלוּת הַקְּדֻשָּׁה מִשְׁתַּנֶּה בֵּין מִינֵי הַפֵּרוֹת","כִּי הַקְּדֻשָּׁה חָלָה רַק עַל פֵּרוֹת חוּץ לָאָרֶץ","כִּי בְּכָל שָׁנָה מַחְלִיטִים מֵחָדָשׁ אִם יֵשׁ שְׁמִטָּה"],1,"הַזְּמַן שֶׁבּוֹ חָלָה הַקְּדֻשָּׁה מִשְׁתַּנֶּה בֵּין הַמִּינִים, לָכֵן הָרַבָּנוּת מְפַרְסֶמֶת אֶת הַזְּמַנִּים.","פֶּרֶק ק״ה, הֲלָכָה ז׳","שְׁנַת הַשְּׁמִטָּה"],["מָה עוֹשִׂים בִּשְׁאֵרִיּוֹת פֵּרוֹת שְׁבִיעִית שֶׁאִי אֶפְשָׁר לְסַיֵּם?",["זוֹרְקִים מִיָּד לָאַשְׁפָּה הָרְגִילָה יַחַד עִם שְׁאָר הַפְּסֹלֶת","נוֹתְנִים אוֹתָם לַכְּלָבִים וְלַחֲתוּלִים שֶׁבַּשְּׁכוּנָה לֶאֱכֹל מִיָּד","קוֹבְרִים אוֹתָם בָּאֲדָמָה כְּדֵי לִזְרֹעַ מֵהֶם עֵצִים חֲדָשִׁים","מַנִּיחִים בְּשַׂקִּית נִפְרֶדֶת עַד שֶׁיֵּרָקְבוּ, וְאַחַר כָּךְ זוֹרְקִים"],3,"אֵין לִזְרֹק אוֹתָם לָאַשְׁפָּה מִיָּד, אֶלָּא מַנִּיחִים בְּשַׂקִּית אוֹ כְּלִי נִפְרָד עַד שֶׁיֵּרָקְבוּ מֵעַצְמָם.","פֶּרֶק ק״ה, הֲלָכָה ח׳","שְׁנַת הַשְּׁמִטָּה"],["מַדּוּעַ גָּזְרוּ חֲכָמִים אִסּוּר סְפִיחִין עַל יְרָקוֹת שֶׁצָּמְחוּ בַּשְּׁמִטָּה?",["שֶׁלֹּא יִזְרְעוּ בַּסֵּתֶר וְיֹאמְרוּ שֶׁגָּדְלוּ מֵאֲלֵיהֶם","כִּי יְרָקוֹת שֶׁצּוֹמְחִים מֵאֲלֵיהֶם אֵינָם טְעִימִים בִּכְלָל","כִּי הַיְּרָקוֹת שַׁיָּכִים רַק לְחַיּוֹת הַשָּׂדֶה","כְּדֵי שֶׁהָאֲדָמָה תָּנוּחַ וְלֹא יִהְיוּ בָּהּ צְמָחִים"],0,"נוֹצַר חֲשָׁשׁ שֶׁאֲנָשִׁים יִזְרְעוּ בַּסֵּתֶר וְיֹאמְרוּ שֶׁגָּדְלוּ מֵאֲלֵיהֶם; עַל פֵּרוֹת הָעֵץ הָאִסּוּר אֵינוֹ חָל.","פֶּרֶק ק״ה, הֲלָכוֹת ט׳-י׳","שְׁנַת הַשְּׁמִטָּה"],["בְּשָׂדֶה שֶׁל גּוֹי בְּאֶרֶץ יִשְׂרָאֵל צָמְחוּ יְרָקוֹת בַּשְּׁבִיעִית. מָה דִּינָם?",["אָסוּר לֶאֱכֹל אוֹתָם, כְּמוֹ כָּל סְפִיחִין שֶׁל שְׁבִיעִית","אֵין עֲלֵיהֶם אִסּוּר סְפִיחִין, כִּי הַקַּרְקַע שֶׁל גּוֹי","מֻתָּר לֶאֱכֹל רַק אִם הַגּוֹי מַסְכִּים בִּכְתָב","אָסוּר לֶאֱכֹל אוֹתָם רַק בְּתוֹךְ יְרוּשָׁלַיִם"],1,"אִסּוּר סְפִיחִין אֵינוֹ חָל עַל מַה שֶּׁגָּדַל בְּקַרְקַע שֶׁל גּוֹי.","פֶּרֶק ק״ה, הֲלָכָה י״א","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["עַגְבָנִיָּה הִתְחִילָה לִצְמֹחַ בַּשָּׁנָה הַשִּׁשִּׁית וְנִקְטְפָה בַּשְּׁבִיעִית. הַאִם מֻתָּר לְאָכְלָהּ?",["לֹא, כִּי הִיא נִקְטְפָה בְּתוֹךְ שְׁנַת הַשְּׁמִטָּה","לֹא, כִּי כָּל עַגְבָנִיָּה אֲסוּרָה בַּשְּׁבִיעִית","כֵּן, כִּי הִיא הִתְחִילָה לִצְמֹחַ בַּשָּׁנָה הַשִּׁשִּׁית","כֵּן, אֲבָל רַק אַחֲרֵי שֶׁנִּגְמֶרֶת הַשָּׁנָה"],2,"מֻתָּר לֶאֱכֹל גִּדּוּלִים שֶׁהִתְחִילוּ לִצְמֹחַ בַּשָּׁנָה הַשִּׁשִּׁית.","פֶּרֶק ק״ה, הֲלָכָה י״ב","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["מֵאֵיפֹה לָמְדוּ חֲכָמִים שֶׁאָסוּר לִסְחֹר בְּפֵרוֹת שְׁבִיעִית?",["מִן הַפָּסוּק ״לֹא תִגְנֹב״ שֶׁבַּעֲשֶׂרֶת הַדִּבְּרוֹת","מִן הַמִּלָּה ״שַׁבָּת״ – שֶׁאָסוּר לַעֲבֹד בַּשּׁוּק","מִן הַפָּסוּק עַל מְכִירַת שָׂדוֹת בִּשְׁנַת הַיּוֹבֵל","מִן הַמִּלָּה ״לְאָכְלָה״ – לֶאֱכֹל וְלֹא לִסְחוֹרָה"],3,"״וְהָיְתָה שַׁבַּת הָאָרֶץ לָכֶם לְאָכְלָה״ – וְדָרְשׁוּ חֲכָמִים: ״לְאָכְלָה – וְלֹא לִסְחוֹרָה״.","פֶּרֶק ק״ה, הֲלָכָה י״ג","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["מָה הָיָה אֶחָד הַחֲשָׁשׁוֹת שֶׁבִּגְלָלָם הִנְהִיגוּ אֶת הֶתֵּר הַמְּכִירָה?",["שֶׁאִם הַחַקְלָאִים לֹא יַעַבְדוּ, יִהְיֶה מַחְסוֹר בְּמָזוֹן","שֶׁהַגּוֹיִים יִכְעֲסוּ אִם לֹא יִמְכְּרוּ לָהֶם אֲדָמָה","שֶׁהָאֲדָמָה תִּתְיַבֵּשׁ לְגַמְרֵי אִם לֹא יַשְׁקוּ אוֹתָהּ","שֶׁלֹּא יִהְיוּ מַסְפִּיק פֵּרוֹת לְבֵית הַמִּקְדָּשׁ"],0,"חָשְׁשׁוּ שֶׁאִם הַחַקְלָאִים לֹא יַעַבְדוּ יִהְיֶה מַחְסוֹר בְּמָזוֹן, וְשֶׁיְּהוּדִים לֹא יִרְצוּ לַעֲבֹד בְּחַקְלָאוּת בִּגְלַל הַקֹּשִׁי הַכַּלְכָּלִי.","פֶּרֶק ק״ה, הֲלָכָה י״ד","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["לְיוֹסִי יֵשׁ גִּנָּה פְּרָטִית קְטַנָּה לְיַד הַבַּיִת. הַאִם הֶתֵּר הַמְּכִירָה מְיֻעָד לוֹ?",["כֵּן, הֶתֵּר הַמְּכִירָה מְיֻעָד לְכָל מִי שֶׁיֵּשׁ לוֹ אֲדָמָה","לֹא, עָלָיו לִשְׁמֹר אֶת כָּל דִּינֵי הַשְּׁמִטָּה בְּגִנָּתוֹ","כֵּן, אִם הוּא מוֹכֵר אֶת הַגִּנָּה לִשְׁכֵנוֹ הַיְּהוּדִי","לֹא, אֲבָל מֻתָּר לוֹ לִזְרֹעַ בָּהּ כְּרָגִיל"],1,"הֶתֵּר הַמְּכִירָה אֵינוֹ מְיֻעָד לְבַעֲלֵי גִּנּוֹת פְּרָטִיּוֹת, וַעֲלֵיהֶם לִשְׁמֹר אֶת כָּל דִּינֵי הַשְּׁמִטָּה.","פֶּרֶק ק״ה, הֲלָכָה ט״ו","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["בְּאוֹצַר בֵּית דִּין, עֲבוּר מָה מְשַׁלֵּם הַקּוֹנֶה בַּחֲנוּת?",["עֲבוּר הַפֵּרוֹת עַצְמָם, כְּמוֹ בְּכָל שָׁנָה רְגִילָה","עֲבוּר הָאֲדָמָה שֶׁבָּהּ גָּדְלוּ הַפֵּרוֹת","עֲבוּר טִרְחַת הַחַקְלַאי בָּאִסּוּף, בָּאֲרִיזָה וּבַשִּׁוּוּק","לֹא מְשַׁלְּמִים כְּלוּם, וְכָל אֶחָד לוֹקֵחַ כְּפִי רְצוֹנוֹ"],2,"הַתַּשְׁלוּם אֵינוֹ עֲבוּר הַפֵּרוֹת אֶלָּא עֲבוּר טִרְחַת הַחַקְלַאי, וְכָךְ הוּא שׁוֹמֵר שְׁמִטָּה וְגַם מִתְפַּרְנֵס.","פֶּרֶק ק״ה, הֲלָכָה ט״ז","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["מָה טַעַם מִצְוַת שְׁמִטַּת כְּסָפִים?",["כְּדֵי שֶׁהַמַּלְוִים יִלְמְדוּ לֹא לְהַלְווֹת כֶּסֶף","כְּדֵי לְהַעֲנִישׁ אֶת מִי שֶׁמְּאַחֵר לְשַׁלֵּם","כְּדֵי שֶׁיִּהְיֶה כֶּסֶף לְבִנְיַן בֵּית הַמִּקְדָּשׁ","לִדְאֹג לָעֲנִיִּים וְלָתֵת לָהֶם הִזְדַּמְּנוּת כַּלְכָּלִית חֲדָשָׁה"],3,"פַּעַם בְּשֶׁבַע שָׁנִים מְוַתְּרִים לָעֲנִיִּים עַל חוֹבוֹתֵיהֶם, כְּדֵי לָתֵת לָהֶם הִזְדַּמְּנוּת כַּלְכָּלִית חֲדָשָׁה.","פֶּרֶק ק״ה, הֲלָכָה י״ז","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["לָמָּה תִּקֵּן הִלֵּל אֶת הַפְּרוֹזְבּוּל?",["כִּי אֲנָשִׁים נִמְנְעוּ מִלְּהַלְווֹת לָעֲנִיִּים מֵחֲשַׁשׁ הַשְּׁמִטָּה","כִּי הָעֲנִיִּים בִּקְּשׁוּ לְהַחְזִיר אֶת חוֹבוֹתֵיהֶם מֻקְדָּם","כִּי בֵּית הַדִּין רָצָה לְבַטֵּל אֶת הַשְּׁמִטָּה","כִּי הַמַּלְוִים רָצוּ לִגְבּוֹת רִבִּית מֵהַלֹּווִים"],0,"אֲנָשִׁים פָּחֲדוּ שֶׁכַּסְפָּם יֹאבַד בַּשְּׁמִטָּה וְהִפְסִיקוּ לְהַלְווֹת, וְכָךְ נִפְגְּעוּ הָעֲנִיִּים; לָכֵן תִּקֵּן הִלֵּל אֶת הַפְּרוֹזְבּוּל.","פֶּרֶק ק״ה, הֲלָכָה י״ח","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["מִי חַיָּב לְהִשְׁתַּתֵּף בְּמַעֲמַד הַקְהֵל?",["רַק הַגְּבָרִים, וְהַנָּשִׁים וְהַיְּלָדִים פְּטוּרִים מִן הַמִּצְוָה","אֲנָשִׁים, נָשִׁים וִילָדִים – גַּם קְטַנִּים שֶׁאֵינָם בְּגִיל חִנּוּךְ","גְּבָרִים וְנָשִׁים בִּלְבַד, אֲבָל לֹא יְלָדִים קְטַנִּים","רַק הַכֹּהֲנִים וְהַלְּוִיִּים שֶׁעוֹבְדִים בְּבֵית הַמִּקְדָּשׁ"],1,"כֻּלָּם חַיָּבִים בְּהַקְהֵל: אֲנָשִׁים, נָשִׁים וִילָדִים, גַּם בְּגִיל חִנּוּךְ וְגַם קְטַנִּים מִזֶּה.","פֶּרֶק ק״ה, הֲלָכָה י״ט","שְׁנַת הַשְּׁמִטָּה – חֵלֶק ב׳"],["לָמָּה עָלֵינוּ לְהַקְפִּיד שֶׁלֹּא יִגָּרֵם נֶזֶק לְמָמוֹן הֶחָבֵר?",["כִּי כָּךְ נְקַבֵּל מִמֶּנּוּ מַתָּנָה גְּדוֹלָה","רַק אִם הוּא חָבֵר שֶׁלָּנוּ בַּכִּתָּה","כִּי אַחֶרֶת הַמּוֹרֶה יַעֲנִישׁ אוֹתָנוּ מְאֹד","כְּמוֹ שֶׁאָנוּ מַקְפִּידִים עַל הַמָּמוֹן שֶׁלָּנוּ"],3,"מִצְוַת ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״ מְחַיֶּבֶת לָחוּס עַל מָמוֹן הֶחָבֵר כְּשֵׁם שֶׁאָנוּ מַקְפִּידִים עַל הַמָּמוֹן וְהַכָּבוֹד שֶׁלָּנוּ.","פֶּרֶק ק״ו, הֲלָכָה א׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["אֵיךְ מִצְוַת וְאָהַבְתָּ לְרֵעֲךָ מְסַיַּעַת בְּמִצְווֹת אֲחֵרוֹת?",["הִיא מַחְלִיפָה אֶת כָּל שְׁאָר הַמִּצְווֹת","הָאוֹהֵב חֲבֵרוֹ לֹא יִגְנֹב וְלֹא יְרַמֶּה","הִיא פּוֹטֶרֶת אוֹתָנוּ מִמִּצְוַת צְדָקָה לָעֲנִיִּים","הִיא נוֹהֶגֶת רַק בְּשַׁבָּת וּבְיָמִים טוֹבִים"],1,"רַבִּי עֲקִיבָא אָמַר שֶׁזֶּה כְּלָל גָּדוֹל בַּתּוֹרָה: הָאוֹהֵב אֶת חֲבֵרוֹ לֹא יִגְנֹב, לֹא יַחְמֹד, לֹא יְרַמֶּה, לֹא יַזִּיק וְלֹא יְדַבֵּר לָשׁוֹן הָרַע.","פֶּרֶק ק״ו, הֲלָכָה ב׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["בִּקּוּר חוֹלִים הוּא מִדִּבְרֵי חֲכָמִים. אֵיךְ הוּא כָּלוּל בְּמִצְוַת הַתּוֹרָה?",["הֵן כְּתוּבוֹת בְּפֵרוּשׁ בַּתּוֹרָה בְּסֵפֶר וַיִּקְרָא","הֵן נוֹגְעוֹת רַק לַכֹּהֲנִים בְּבֵית הַמִּקְדָּשׁ","מָה שֶׁאָדָם רוֹצֶה לְעַצְמוֹ יַעֲשֶׂה לַאֲחֵרִים","הֵן אֵינָן כְּלוּלוֹת, הֵן רַק מִנְהָג"],2,"כָּל הַדְּבָרִים שֶׁאָדָם רוֹצֶה שֶׁיַּעֲשׂוּ עֲבוּרוֹ אִם יִזְדַּקֵּק לָהֶם – הוּא מְצֻוֶּה לַעֲשׂוֹת עֲבוּר אֲחֵרִים. גְּמִילוּת חֲסָדִים הִיא כָּל דָּבָר שֶׁאָדָם עוֹשֶׂה בְּגוּפוֹ לְמַעַן אֲחֵרִים.","פֶּרֶק ק״ו, הֲלָכָה ג׳-ד׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["בַּמָּה גְּדוֹלָה גְּמִילוּת חֲסָדִים מִן הַצְּדָקָה?",["הִיא גַּם בְּגוּף, גַּם לָעֲשִׁירִים וְלַמֵּתִים","הִיא נִתֶּנֶת רַק לָעֲנִיִּים הַגְּדוֹלִים בְּיוֹתֵר","הִיא נַעֲשֵׂית רַק בְּכֶסֶף וּבְזָהָב","הִיא נוֹהֶגֶת רַק בְּאֶרֶץ יִשְׂרָאֵל"],0,"צְדָקָה – בְּמָמוֹן, לָעֲנִיִּים וְלַחַיִּים. גְּמִילוּת חֲסָדִים – בְּגוּף וּבְמָמוֹן, לָעֲנִיִּים וְלָעֲשִׁירִים, לַחַיִּים וְלַמֵּתִים.","פֶּרֶק ק״ו, הֲלָכָה ה׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["רְאוּבֵן סֵרֵב לְהַשְׁאִיל לְשִׁמְעוֹן, כִּנְקָמָה עַל שֶׁשִּׁמְעוֹן סֵרֵב לוֹ אֶתְמוֹל. עַל מָה עָבַר?",["עַל אִסּוּר לֹא תִטֹּר שֶׁבַּתּוֹרָה","לֹא עָבַר, כִּי שִׁמְעוֹן הִתְחִיל","עַל אִסּוּר לָשׁוֹן הָרַע בִּלְבַד","עַל אִסּוּר לֹא תִקֹּם שֶׁבַּתּוֹרָה"],3,"מִי שֶׁמְּסָרֵב כִּנְקָמָה עוֹבֵר עַל ״לֹא תִקֹּם״. מִי שֶׁמַּשְׁאִיל אַךְ לוֹעֵג עוֹבֵר עַל ״לֹא תִטֹּר״ – שְׁנֵי אִסּוּרִים נִפְרָדִים.","פֶּרֶק ק״ו, הֲלָכָה ו׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["מָה לְמֵדִים מֵחֻרְבַּן בֵּית הַמִּקְדָּשׁ הַשֵּׁנִי?",["בְּבַיִת שֵׁנִי לֹא עָסְקוּ כְּלָל בַּתּוֹרָה","הוּא חָרַב רַק בִּגְלַל עֲבוֹדָה זָרָה קָשָׁה","שִׂנְאַת חִנָּם גָּרְמָה לְגָלוּת שֶׁקִּצָּהּ לֹא נִתְגַּלָּה","הַגָּלוּת הַשְּׁנִיָּה נִמְשְׁכָה שִׁבְעִים שָׁנָה בִּלְבַד"],2,"הַבַּיִת הָרִאשׁוֹן חָרַב בִּגְלַל עֲבֵרוֹת חֲמוּרוֹת וְנִגְאֲלוּ אַחֲרֵי שִׁבְעִים שָׁנָה, וְאִלּוּ בַּגָּלוּת שֶׁנִּגְרְמָה מִשִּׂנְאַת חִנָּם – לֹא נִתְגַּלָּה הַקֵּץ.","פֶּרֶק ק״ו, הֲלָכָה ז׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["כֵּיצַד קֵרֵב אַהֲרֹן לַתּוֹרָה אָדָם שֶׁעָבַר עֲבֵרָה?",["הִתְרַחֵק מִמֶּנּוּ עַד שֶׁיַּחְזֹר בִּתְשׁוּבָה","הִתְקָרֵב אֵלָיו וְהֶרְאָה לוֹ פָּנִים שְׂמֵחוֹת","סִפֵּר לְכָל הָעָם עַל מַעֲשָׂיו","כָּעַס עָלָיו וְגָעַר בּוֹ בְּקוֹל"],1,"הָאָדָם הִתְבַּיֵּשׁ וְאָמַר: אִלּוּ יָדַע צַדִּיק זֶה עַל מַעֲשַׂי – הָיָה מִתְרַחֵק מִמֶּנִּי, וּמִתּוֹךְ כָּךְ תִּקֵּן אֶת מַעֲשָׂיו.","פֶּרֶק ק״ו, הֲלָכָה ח׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["לָמָּה קָרְאוּ הַנְּבִיאִים לַה׳ בְּכִנּוּיִים כְּמוֹ רַב חֶסֶד וְצַדִּיק?",["כְּדֵי שֶׁנֵּדַע לִנְהֹג בַּדְּרָכִים הַטּוֹבוֹת הָאֵלּוּ","כְּדֵי שֶׁנֵּדַע מָה לוֹמַר בַּתְּפִלָּה בִּלְבַד","כִּי כָּךְ קָרְאוּ לַמְּלָכִים בִּימֵיהֶם","כְּדֵי לְהַבְדִּיל בֵּין נָבִיא לְנָבִיא"],0,"״אַחֲרֵי ה׳ אֱ-לֹהֵיכֶם תֵּלֵכוּ״ – הוֹלְכִים אַחַר מִדּוֹתָיו: כְּשֵׁם שֶׁהוּא חַנּוּן וְרַחוּם, אַף אַתָּה הֱיֵה חַנּוּן וְרַחוּם.","פֶּרֶק ק״ז, הֲלָכָה א׳-ב׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["לָמָּה הֶעֱדִיף רַבָּן יוֹחָנָן בֶּן זַכַּאי אֶת ״לֵב טוֹב״?",["כִּי רַבִּי אֶלְעָזָר הָיָה הַתַּלְמִיד הַגָּדוֹל","כִּי לֵב טוֹב קַל יוֹתֵר מֵעַיִן טוֹבָה","כִּי שְׁאָר הַתְּשׁוּבוֹת הָיוּ שְׁגוּיוֹת לְגַמְרֵי","כִּי לֵב טוֹב כּוֹלֵל אֶת כָּל הַמִּדּוֹת"],3,"בַּעַל לֵב טוֹב כּוֹלֵל בְּכָךְ אֶת כָּל הַתְּכוּנוֹת הַטּוֹבוֹת: עַיִן טוֹבָה, אַהֲבַת הַבְּרִיּוֹת וְכָל מִדָּה טוֹבָה אַחֶרֶת.","פֶּרֶק ק״ז, הֲלָכָה ג׳","וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],["מֵאֵיזֶה פָּסוּק לוֹמְדִים מוֹרָא הוֹרִים, שֶׁהַתּוֹרָה הִשְׁוְתָה לְמוֹרָא ה׳?",["וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ, בְּסֵפֶר וַיִּקְרָא","שְׁמַע יִשְׂרָאֵל ה׳ אֱ-לֹהֵינוּ ה׳ אֶחָד","אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, בְּסֵפֶר וַיִּקְרָא","לֹא תִשָּׂא אֶת שֵׁם ה׳ לַשָּׁוְא"],2,"״אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ״ – מִצְוַת עֲשֵׂה לִירֹא מֵהַהוֹרִים. וְנֶאֱמַר גַּם ״אֶת ה׳ אֱ-לֹהֶיךָ תִּירָא״ – הַתּוֹרָה הִשְׁוְתָה אֶת כְּבוֹדָם לִכְבוֹד הַמָּקוֹם.","פֶּרֶק ק״ח, הֲלָכוֹת א׳-ב׳","כִּבּוּד אָב וָאֵם"],["מָה נָכוֹן לְגַבֵּי כָּבוֹד בַּמִּשְׁפָּחָה?",["אֵין שׁוּם חוֹבָה לְכַבֵּד אַחִים גְּדוֹלִים בִּכְלָל","הוֹרִים צְרִיכִים לְדַקְדֵּק מְאֹד בְּכָל פְּרָט שֶׁל כְּבוֹדָם","אָב שֶׁמָּחַל עַל כְּבוֹדוֹ, אֵין מְחִילָתוֹ מוֹעִילָה","כְּבוֹד הַהוֹרִים קוֹדֵם לִכְבוֹד הַסַּבָּא וְהָאַחִים הַגְּדוֹלִים"],3,"יֵשׁ לְכַבֵּד אַחִים גְּדוֹלִים וְסַבָּא וְסָבְתָא, אַךְ כְּבוֹד הַהוֹרִים קוֹדֵם. וְהַהוֹרִים לֹא יְדַקְדְּקוּ בִּכְבוֹדָם יוֹתֵר מִדַּי – אָב שֶׁמָּחַל עַל כְּבוֹדוֹ, כְּבוֹדוֹ מָחוּל.","פֶּרֶק ק״ח, הֲלָכוֹת י״ג-י״ד","כִּבּוּד אָב וָאֵם"],["לָמָּה בְּמִצְוַת הַמּוֹרָא הִקְדִּימָה הַתּוֹרָה אֶת הָאֵם?",["כִּי הָאֵם נִזְכֶּרֶת רִאשׁוֹנָה בְּכָל מָקוֹם בַּתּוֹרָה","כִּי בְּדֶרֶךְ הָעוֹלָם הַבֵּן יָרֵא מֵאָבִיו יוֹתֵר","כִּי הָאֵם תָּמִיד חֲשׁוּבָה יוֹתֵר מֵהָאָב בַּבַּיִת","כִּי אֵין לַדָּבָר סִבָּה וְזֶה סְתָם מִקְרֶה"],1,"גָּלוּי וְיָדוּעַ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהַבֵּן יָרֵא מֵאָבִיו יוֹתֵר, וְלָכֵן הִקְדִּים אֶת הַחוֹבָה לִירֹא מֵהָאֵם.","פֶּרֶק ק״ח, הֲלָכָה ג׳","כִּבּוּד אָב וָאֵם"],["מַדּוּעַ גְּדוֹלָה מִצְוַת כִּבּוּד אָב וָאֵם?",["כִּי מְקַיְּמִים אוֹתָהּ רַק פַּעַם אַחַת בַּשָּׁנָה","כִּי הִיא הַמִּצְוָה הָאַחֲרוֹנָה שֶׁנִּתְּנָה בַּתּוֹרָה","כִּי נִצְטַוּוּ עָלֶיהָ יִשְׂרָאֵל בַּעֲשֶׂרֶת הַדִּבְּרוֹת","כִּי רַק כֹּהֲנִים חַיָּבִים בָּהּ בְּבֵית הַמִּקְדָּשׁ"],2,"גְּדוֹלָה הַמִּצְוָה שֶׁהֲרֵי נִצְטַוּוּ עָלֶיהָ בַּעֲשֶׂרֶת הַדִּבְּרוֹת, וּבִזְכוּתָהּ זוֹכִים לַאֲרִיכוּת יָמִים, וְגַם עַם יִשְׂרָאֵל מַאֲרִיךְ יָמִים בְּאַרְצוֹ.","פֶּרֶק ק״ח, הֲלָכָה ד׳","כִּבּוּד אָב וָאֵם"],["הַיְּלָדִים מַאֲכִילִים אֶת הַהוֹרִים מַאֲכָלִים מְשֻׁבָּחִים, אֲבָל בְּפָנִים זוֹעֲפוֹת. מַה הַדִּין?",["אֵין זֶה כִּבּוּד הוֹרִים, כִּי צָרִיךְ סֵבֶר פָּנִים יָפוֹת","זֶה כִּבּוּד הוֹרִים מְצֻיָּן, כִּי הָאֹכֶל טָעִים וְיָקָר מְאֹד","זֶה בְּסֵדֶר, הָעִקָּר שֶׁהַהוֹרִים לֹא נִשְׁאֲרִים רְעֵבִים","זֶה כִּבּוּד הוֹרִים רַק אִם עוֹשִׂים זֹאת כָּל יוֹם"],0,"אֲפִלּוּ מַאֲכִילִים אֶת הַהוֹרִים כָּל יוֹם מַאֲכָלִים מְשֻׁבָּחִים, אִם עוֹשִׂים זֹאת בְּפָנִים זוֹעֲפוֹת – אֵין זֶה כִּבּוּד הוֹרִים.","פֶּרֶק ק״ח, הֲלָכָה ה׳","כִּבּוּד אָב וָאֵם"],["מָה אָסוּר לַעֲשׂוֹת בַּמָּקוֹם הַקָּבוּעַ שֶׁל הַהוֹרִים?",["לָשֶׁבֶת שָׁם רַק כְּשֶׁהַהוֹרִים נִמְצָאִים בְּאוֹתוֹ חֶדֶר","לָשֶׁבֶת אוֹ לְהִתְפַּלֵּל שָׁם, גַּם כְּשֶׁהֵם אֵינָם","אֵין שׁוּם אִסּוּר, מֻתָּר לָשֶׁבֶת שָׁם תָּמִיד","רַק לֶאֱכֹל שָׁם, אֲבָל לָשֶׁבֶת מֻתָּר"],1,"אֵין לְהִתְפַּלֵּל בִּמְקוֹמָם שֶׁל הַהוֹרִים בְּבֵית הַכְּנֶסֶת וְאֵין לָשֶׁבֶת בִּמְקוֹמָם הַקָּבוּעַ, אֲפִלּוּ כְּשֶׁהֵם לֹא נִמְצָאִים.","פֶּרֶק ק״ח, הֲלָכָה ו׳","כִּבּוּד אָב וָאֵם"],["מָה מִן הַדְּבָרִים הַבָּאִים מֻתָּר לְפִי דִּינֵי מוֹרָא?",["לוֹמַר לְמִי שֶׁחוֹלֵק עַל אַבָּא שֶׁדְּבָרָיו נִרְאִים יוֹתֵר","לִקְרֹא לְאַבָּא בִּשְׁמוֹ הַפְּרָטִי אַחֲרֵי שֶׁהוּא כְּבָר נִפְטַר","לַחְלֹק עַל דִּבְרֵי אַבָּא בְּפָנָיו בִּשְׁעַת וִכּוּחַ סוֹעֵר","לִקְרֹא לְאָדָם אַחֵר בְּשֵׁם מְקֻבָּל כְּשֵׁם אַבָּא, שֶׁלֹּא בְּפָנָיו"],3,"אֵין לַחְלֹק עַל הַהוֹרִים, וְאֵין לִקְרֹא לָהֶם בִּשְׁמָם גַּם אַחֲרֵי מוֹתָם. אֲבָל לִקְרֹא לְאַחֵר שֶׁשְּׁמוֹ כְּשֵׁם אַבָּא – מֻתָּר שֶׁלֹּא בְּפָנָיו, אִם זֶה שֵׁם מְקֻבָּל וְיָדוּעַ.","פֶּרֶק ק״ח, הֲלָכוֹת ז׳-ח׳","כִּבּוּד אָב וָאֵם"],["מָתַי מֻתָּר לְהָעִיר אֶת הַהוֹרִים מִשְּׁנָתָם?",["בְּכָל פַּעַם שֶׁמִּשְׁתַּעְמְמִים וְרוֹצִים לְשַׂחֵק אִתָּם","אַף פַּעַם, גַּם לֹא לְצֹרֶךְ מִצְוָה","לְצֹרֶךְ מִצְוָה, אוֹ כְּשֶׁיָּדוּעַ שֶׁהֵם רוֹצִים לָקוּם","רַק בְּשַׁבָּת וּבְחַגִּים, וְלֹא בִּימֵי חֹל"],2,"אָסוּר לְהָעִיר אֶת הַהוֹרִים אִם זֶה יְצַעֵר אוֹתָם, אַךְ מֻתָּר לְצֹרֶךְ מִצְוָה אוֹ כְּשֶׁיָּדוּעַ בְּבֵרוּר שֶׁהֵם רוֹצִים לָקוּם בְּשָׁעָה מְסֻיֶּמֶת.","פֶּרֶק ק״ח, הֲלָכָה ט׳","כִּבּוּד אָב וָאֵם"],["בֵּן חָשׁוּב יוֹשֵׁב בְּרֹאשׁ הַקָּהָל, וְהוֹרָיו בָּאוּ וְקָרְעוּ אֶת בְּגָדָיו. מַה יַּעֲשֶׂה?",["יִשְׁתֹּק וְלֹא יַכְלִים אוֹתָם, וְיִירָא מִמֶּלֶךְ מַלְכֵי הַמְּלָכִים","יַעֲנֶה לָהֶם בְּחֻצְפָּה כְּדֵי לְהַצִּיל אֶת כְּבוֹדוֹ הָאִישִׁי","יֵצֵא מִבֵּית הַכְּנֶסֶת וְלֹא יְדַבֵּר אִתָּם שׁוּב","יְבַקֵּשׁ מֵהַקָּהָל לְהוֹצִיא אֶת הוֹרָיו מִן הַמָּקוֹם"],0,"אָמְרוּ חֲכָמִים: לֹא יַכְלִים אוֹתָם, אֶלָּא יִשְׁתֹּק וְיִירָא מִמֶּלֶךְ מַלְכֵי הַמְּלָכִים שֶׁצִּוָּה אוֹתוֹ כָּךְ.","פֶּרֶק ק״ח, הֲלָכָה י׳","כִּבּוּד אָב וָאֵם"],["רָאִיתָ שֶׁאַבָּא עוֹבֵר עַל דִּבְרֵי תּוֹרָה. מַה תַּעֲשֶׂה?",["אֹמַר לוֹ: אַבָּא, עָבַרְתָּ עַל דִּבְרֵי תּוֹרָה","אֶשְׁאַל אוֹתוֹ: אַבָּא, כָּתוּב בַּתּוֹרָה כָּךְ וְכָךְ?","אֲבַזֶּה אוֹתוֹ בִּפְנֵי כֻּלָּם כְּדֵי שֶׁיִּלְמַד לֶקַח","אֲסַפֵּר לְכָל הַשְּׁכֵנִים מָה אַבָּא עָשָׂה"],1,"אָסוּר לְהָעִיר לַהוֹרִים בְּאֹפֶן יָשִׁיר; שׁוֹאֲלִים כְּשׁוֹאֵל שְׁאֵלָה, וְהָאַבָּא יָבִין מֵעַצְמוֹ וְלֹא יִתְבַּיֵּשׁ. וְאָסוּר לְקַלֵּל וּלְבַזּוֹת אֶת הַהוֹרִים.","פֶּרֶק ק״ח, הֲלָכוֹת י״א-י״ב","כִּבּוּד אָב וָאֵם"],["מָה מַבְטִיחָה הַתּוֹרָה לְמִי שֶׁנּוֹתֵן לֶעָנִי בְּלֵב טוֹב?",["שֶׁלֹּא יִצְטָרֵךְ לָתֵת צְדָקָה שׁוּב לְעוֹלָם","ה׳ יְבָרֵךְ אוֹתוֹ בְּכָל מַעֲשָׂיו וּבְכָל עֲבוֹדָתוֹ","שֶׁכָּל הָעֲנִיִּים בָּעוֹלָם יִהְיוּ עֲשִׁירִים מִיָּד","שֶׁיְּקַבֵּל אֶת כָּל הַכֶּסֶף בַּחֲזָרָה כָּפוּל"],1,"״וְלֹא יֵרַע לְבָבְךָ בְּתִתְּךָ לוֹ, כִּי בִּגְלַל הַדָּבָר הַזֶּה יְבָרֶכְךָ ה׳ אֱ-לֹהֶיךָ בְּכָל מַעֲשֶׂךָ וּבְכֹל מִשְׁלַח יָדֶךָ״.","פֶּרֶק ק״ט, הֲלָכָה א׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["מָה קוֹרֶה לְמִי שֶׁמְּרַחֵם עַל הָעֲנִיִּים?",["הוּא נַעֲשֶׂה עָנִי בְּעַצְמוֹ בְּמֶשֶׁךְ הַזְּמַן","אֲנָשִׁים רַבִּים יְבַקְּשׁוּ מִמֶּנּוּ כֶּסֶף כָּל יוֹם","הוּא פָּטוּר מִכָּל שְׁאָר הַמִּצְווֹת שֶׁבַּתּוֹרָה","גַּם עָלָיו מְרַחֲמִים מִן הַשָּׁמַיִם בְּוַדַּאי"],3,"כָּל הַמְּרַחֵם עַל הָעֲנִיִּים מְרַחֲמִים עָלָיו מִן הַשָּׁמַיִם, וְאֵין דָּבָר רַע נִגְרָם מִן הַצְּדָקָה.","פֶּרֶק ק״ט, הֲלָכָה ב׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["לָמָּה מִצְוַת הַלְוָאָה גְּדוֹלָה יוֹתֵר מִן הַצְּדָקָה?",["הִיא עוֹזֶרֶת לוֹ לְשַׁקֵּם אֶת חַיָּיו בְּכוֹחוֹת עַצְמוֹ","כִּי הַמַּלְוֶה מְקַבֵּל רִבִּית גְּדוֹלָה עַל כַּסְפּוֹ בַּסּוֹף","כִּי מַלְוִים רַק לַאֲנָשִׁים עֲשִׁירִים וַחֲשׁוּבִים מְאֹד","כִּי אֶת הַהַלְוָאָה אֵין צָרִיךְ לְהַחְזִיר לְעוֹלָם"],0,"הַהַלְוָאָה מוֹנַעַת לְעִתִּים קְרוֹבוֹת אֶת נְפִילַת הָאָדָם לִמְצוּקָה, וּמְאַפְשֶׁרֶת לוֹ לְשַׁקֵּם אֶת חַיָּיו וּלְהַפְסִיק לִהְיוֹת תָּלוּי בַּאֲחֵרִים. וּמִצְוָה לְהַלְווֹת לְכָל מִי שֶׁזָּקוּק, אֲפִלּוּ אֵינוֹ עָנִי.","פֶּרֶק ק״ט, הֲלָכָה ג׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["מָה צָרִיךְ לַעֲשׂוֹת כְּשֶׁאֵין לְךָ כֶּסֶף לָתֵת לֶעָנִי?",["לְהִתְרַחֵק מִמֶּנּוּ מַהֵר כְּדֵי שֶׁלֹּא יִתְבַּיֵּשׁ","לוֹמַר לוֹ שֶׁיִּפְנֶה מִיָּד לְמִישֶׁהוּ אַחֵר","לְנַחֵם אוֹתוֹ עַל מַצָּבוֹ וּלְעוֹדֵד אוֹתוֹ","לֹא צָרִיךְ לַעֲשׂוֹת שׁוּם דָּבָר בִּכְלָל"],2,"יֵשׁ לְהִשְׁתַּדֵּל לְנַחֵם אֶת הֶעָנִי וּלְעוֹדֵד אוֹתוֹ, וְאַף אִם אֵין לָאָדָם אֶפְשָׁרוּת לָתֵת לוֹ כֶּסֶף.","פֶּרֶק ק״ט, הֲלָכָה ד׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["יוֹסִי נָתַן לֶעָנִי סְכוּם גָּדוֹל, אֲבָל לָעַג לוֹ בִּשְׁעַת הַנְּתִינָה. מָה הַדִּין?",["קִיֵּם מִצְוָה גְּדוֹלָה כִּי נָתַן הַרְבֵּה כֶּסֶף","אִבֵּד אֶת זְכוּת הַמִּצְוָה וְהִפְסִיד אֶת שְׂכָרָהּ","קִבֵּל חֲצִי שָׂכָר כִּי חֲצִי הָיָה טוֹב","אֵין בְּעָיָה כִּי הֶעָנִי קִבֵּל אֶת הַכֶּסֶף"],1,"הַנּוֹתֵן צְדָקָה וּמְבַיֵּשׁ אֶת הֶעָנִי, אֲפִלּוּ נָתַן כֶּסֶף רַב, אִבֵּד אֶת זְכוּת הַמִּצְוָה וְהִפְסִיד אֶת שְׂכָרָהּ.","פֶּרֶק ק״ט, הֲלָכָה ה׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["אָבִי שִׁכְנֵעַ אֶת חֲבֵרָיו לִתְרֹם לִצְדָקָה. מָה שְׂכָרוֹ?",["אֵין לוֹ שָׂכָר כִּי לֹא נָתַן בְּעַצְמוֹ","שְׂכָרוֹ קָטָן יוֹתֵר מִשְּׂכַר הַחֲבֵרִים שֶׁנָּתְנוּ","שְׂכָרוֹ שָׁוֶה בְּדִיּוּק לִשְׂכַר כָּל אֶחָד מֵהֶם","שְׂכָרוֹ גָּדוֹל יוֹתֵר מִשְּׂכַר הַנּוֹתְנִים עַצְמָם"],3,"אָדָם שֶׁמַּשְׁפִּיעַ עַל אֲחֵרִים לָתֵת צְדָקָה, שְׂכָרוֹ גָּדוֹל יוֹתֵר מִשְּׂכַר הַנּוֹתְנִים עַצְמָם.","פֶּרֶק ק״ט, הֲלָכָה ו׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["לְשֵׁם מָה קַיָּמוֹת קֻפּוֹת גְּמַ״ח?",["כְּדֵי לָתֵת הַלְוָאוֹת רַק לְמַכָּרִים וְלִקְרוֹבִים","כְּדֵי לְהַרְוִיחַ כֶּסֶף מֵרִבִּית עַל הַהַלְוָאוֹת","לְהַלְווֹת לְנִזְקָקִים בְּלִי רִבִּית, בְּסוֹדִיּוּת וּבְכָבוֹד","כְּדֵי שֶׁכֻּלָּם יֵדְעוּ מִי צָרִיךְ עֶזְרָה"],2,"קֻפּוֹת גְּמַ״ח מַלְווֹת לְנִזְקָקִים לְלֹא רִבִּית וּבִתְנָאֵי הֶחְזֵר נוֹחִים, וְהַכֹּל נַעֲשֶׂה בְּסוֹדִיּוּת וּבִשְׁמִירָה עַל כְּבוֹד הַמְּבַקֵּשׁ.","פֶּרֶק ק״ט, הֲלָכָה ז׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["מַהוּ ״מַתָּן בַּסֵּתֶר״?",["הַנּוֹתֵן וְהַמְּקַבֵּל אֵינָם יוֹדְעִים זֶה עַל זֶה","נוֹתְנִים לֶעָנִי בַּיָּד מוּל כָּל הַחֲבֵרִים","מַחְבִּיאִים אֶת הַכֶּסֶף בַּבַּיִת וְלֹא נוֹתְנִים אוֹתוֹ","נוֹתְנִים צְדָקָה רַק בַּלַּיְלָה כְּשֶׁחֹשֶׁךְ בַּחוּץ"],0,"כְּשֶׁשָּׂמִים כֶּסֶף בְּקֻפַּת צְדָקָה, הַנּוֹתֵן אֵינוֹ יוֹדֵעַ לְמִי נָתַן וְהֶעָנִי אֵינוֹ יוֹדֵעַ מִמִּי קִבֵּל. וְנוֹתְנִים רַק לְקֻפָּה שֶׁהַמְּמֻנֶּה עָלֶיהָ יָשָׁר וְנֶאֱמָן.","פֶּרֶק ק״ט, הֲלָכָה ח׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["הַאִם עָנִי שֶׁמִּתְפַּרְנֵס מִן הַצְּדָקָה חַיָּב לָתֵת צְדָקָה?",["לֹא, עָנִי פָּטוּר לְגַמְרֵי מִמִּצְוַת צְדָקָה","כֵּן, חַיָּב לָתֵת קְצָת מִמַּה שֶּׁקִּבֵּל","רַק אִם נִשְׁאַר לוֹ כֶּסֶף בְּסוֹף הַשָּׁנָה","רַק בְּחַגִּים וּבְשַׁבָּתוֹת וְלֹא בִּשְׁאָר הַיָּמִים"],1,"כָּל אָדָם חַיָּב לָתֵת צְדָקָה. אֲפִלּוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה חַיָּב לָתֵת קְצָת מִמַּה שֶּׁאֲחֵרִים נָתְנוּ לוֹ.","פֶּרֶק ק״ט, הֲלָכָה ט׳","מִצְוַת צְדָקָה וּמִצְוַת הַלְוָאָה"],["לָמָּה אֵין לְהַפְסִיק בְּבִרְכַּת הַמָּזוֹן אֲפִילּוּ כְּדֵי לְהָשִׁיב ״שָׁלוֹם״ לַהוֹרִים?",["כִּי אָסוּר לְדַבֵּר בִּזְמַן אֲכִילַת הַסְּעוּדָה","כִּי הַהוֹרִים אֵינָם צְרִיכִים לִשְׁמֹעַ תְּשׁוּבָה","כִּי חוֹבַת בִּרְכַּת הַמָּזוֹן הִיא מִן הַתּוֹרָה","כִּי מְבָרְכִים תָּמִיד רַק בְּלַחַשׁ וּבְשֶׁקֶט גָּמוּר"],2,"כֵּיוָן שֶׁהַחוֹבָה לְבָרֵךְ הִיא מִן הַתּוֹרָה, אֵין לְהַפְסִיק אֲפִילּוּ לְהוֹרִים אוֹ לָרַב שֶׁחַיָּבִים בִּכְבוֹדָם.","פֶּרֶק כ״ד, הֲלָכָה י׳","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["שׁוֹמְעִים קַדִּישׁ בְּאֶמְצַע בִּרְכַּת הַמָּזוֹן. מָה עוֹשִׂים?",["עוֹנִים אָמֵן בְּקוֹל וְאַחַר כָּךְ מַמְשִׁיכִים","שׁוֹתְקִים וּמַמְשִׁיכִים, וְלֹא עוֹנִים כְּלָל","מַפְסִיקִים וּמַתְחִילִים אֶת הַבְּרָכָה מֵהַהַתְחָלָה","עוֹנִים רַק לְקַדִּישׁ, אֲבָל לֹא לִקְדֻשָּׁה"],1,"אִם שׁוֹמְעִים קַדִּישׁ, קְדֻשָּׁה וּבָרְכוּ בְּאֶמְצַע בִּרְכַּת הַמָּזוֹן – לֹא עוֹנִים אֶלָּא שׁוֹתְקִים.","פֶּרֶק כ״ד, הֲלָכָה י׳","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["מָה אָסוּר לַעֲשׂוֹת בִּזְמַן שֶׁמְּבָרְכִים בִּרְכַּת הַמָּזוֹן?",["רַק מְלָאכָה קָשָׁה, אֲבָל עִסּוּק קַל מֻתָּר","רַק לְדַבֵּר, אֲבָל לִרְמֹז בָּעֵינַיִם מֻתָּר","רַק לָקוּם מֵהַשֻּׁלְחָן, וְכָל הַשְּׁאָר מֻתָּר","לַעֲסֹק בְּכָל מְלָאכָה, אֲפִילּוּ קַלָּה, וְלִרְמֹז בָּעֵינַיִם"],3,"אָסוּר לַעֲסֹק בְּשׁוּם מְלָאכָה, אֲפִילּוּ עִסּוּק קַל, וְאָסוּר לִרְמֹז בָּעֵינַיִם אוֹ בַּשְּׂפָתַיִם.","פֶּרֶק כ״ד, הֲלָכָה י״א","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["יֶלֶד נִזְכַּר שֶׁלֹּא בֵּרַךְ, וְעָבְרוּ כְּבָר שְׁעָתַיִם מֵהָאֲכִילָה. מָה יַעֲשֶׂה?",["לֹא יְבָרֵךְ, כִּי עָבְרוּ שִׁבְעִים וּשְׁתַּיִם דַּקּוֹת","יִבְדֹּק אֶת עַצְמוֹ: אִם עֲדַיִן שָׂבֵעַ – יְבָרֵךְ","יְבָרֵךְ תָּמִיד, גַּם אִם כְּבָר רָעֵב מְאוֹד","יֹאכַל שׁוּב לֶחֶם וְרַק אָז יְבָרֵךְ"],1,"אַחֲרֵי שִׁבְעִים וּשְׁתַּיִם דַּקּוֹת בּוֹדְקִים: אִם עֲדַיִן שָׂבֵעַ – יְבָרֵךְ, וְאִם הִתְחִיל לִהְיוֹת רָעֵב – לֹא יְבָרֵךְ.","פֶּרֶק כ״ד, הֲלָכָה י״ב","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["מַדּוּעַ צָרִיךְ לְהִשְׁתַּדֵּל לְבָרֵךְ מִיָּד אַחֲרֵי הַסְּעוּדָה?",["כְּדֵי לְסַיֵּם מַהֵר וְלָלֶכֶת לְשַׂחֵק בַּחוּץ","כְּדֵי שֶׁהָאֹכֶל לֹא יִתְקָרֵר עַל הַשֻּׁלְחָן","כְּדֵי לְהַפְנִים אֶת חֲשִׁיבוּת הַבְּרָכָה וּלְהִמָּנַע מִסְּפֵקוֹת","כְּדֵי שֶׁלֹּא יִצְטָרְכוּ לִשְׁטֹף שׁוּב אֶת הַיָּדַיִם"],2,"בְּכָךְ מַפְנִימִים אֶת הַחוֹבָה לְהוֹדוֹת לַה׳ עַל הַמָּזוֹן, וְנִמְנָעִים מִסְּפֵקוֹת אִם שׁוֹכְחִים וְנִזְכָּרִים מְאֻחָר.","פֶּרֶק כ״ד, הֲלָכָה י״ג","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["מִי שֶׁאָכַל וְשָׂבַע וּמְסֻפָּק אִם בֵּרַךְ – לָמָּה עָלָיו לְבָרֵךְ?",["כִּי תָּמִיד עָדִיף לְבָרֵךְ שׁוּב לְמַעַן הַבִּטָּחוֹן","כִּי חִיּוּבוֹ מִן הַתּוֹרָה, וּסְפֵק דְּאוֹרַיְתָא לְחֻמְרָא","כִּי חִיּוּבוֹ מִדְּרַבָּנָן, וּסְפֵק דְּרַבָּנָן לְקֻלָּא","כִּי מִי שֶׁשָּׂבֵעַ מְבָרֵךְ פַּעֲמַיִם בְּכָל סְעוּדָה"],1,"מִי שֶׁשָּׂבַע חַיָּב בְּבִרְכַּת הַמָּזוֹן מִן הַתּוֹרָה, וּ״סְפֵק דְּאוֹרַיְתָא לְחֻמְרָא״.","פֶּרֶק כ״ד, הֲלָכָה י״ד","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["מִי שֶׁאָכַל מְעַט וְלֹא שָׂבַע, וּמְסֻפָּק אִם בֵּרַךְ – מָה דִּינוֹ?",["יְבָרֵךְ, כִּי סְפֵק דְּאוֹרַיְתָא לְחֻמְרָא","יְבָרֵךְ רַק אֶת הַבְּרָכָה הָרִאשׁוֹנָה","יֹאכַל עוֹד עַד שֶׁיִּשְׂבַּע וִיבָרֵךְ","לֹא יְבָרֵךְ, כִּי סְפֵק דְּרַבָּנָן לְקֻלָּא"],3,"מִי שֶׁלֹּא שָׂבַע חַיָּב רַק מִדְּרַבָּנָן, וּ״סְפֵק דְּרַבָּנָן לְקֻלָּא״ – לָכֵן לֹא יְבָרֵךְ.","פֶּרֶק כ״ד, הֲלָכָה ט״ו","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["מַה דִּינָם שֶׁל יְלָדִים קְטַנִּים בְּבִרְכַּת הַמָּזוֹן?",["קְטַנִּים חַיָּבִים מִן הַתּוֹרָה כְּמוֹ גְּדוֹלִים","קְטַנִּים פְּטוּרִים לְגַמְרֵי מִבִּרְכַּת הַמָּזוֹן","קְטַנִּים חַיָּבִים מִדְּרַבָּנָן כְּדֵי לְחַנְּכָם","קְטַנִּים מְבָרְכִים רַק בְּשַׁבָּת וּבְיָמִים טוֹבִים"],2,"קְטַנִּים חַיָּבִים בְּבִרְכַּת הַמָּזוֹן מִדְּרַבָּנָן כְּדֵי לְחַנְּכָם.","פֶּרֶק כ״ד, הֲלָכָה י״ז","בִּרְכַּת הַמָּזוֹן – חֵלֶק ב׳"],["עָשִׁיר פּוֹגֵשׁ עָנִי שֶׁמְּבַקֵּשׁ צְדָקָה. כַּמָּה עָלָיו לָתֵת?",["פְּרוּטָה אַחַת בִּלְבַד, כְּמוֹ כָּל אָדָם","אֵינוֹ צָרִיךְ לָתֵת, כִּי עֲנִיִּים רַבִּים","סְכוּם גָּבוֹהַּ, כְּפִי שֶׁיֵּשׁ בִּיכָלְתּוֹ לָתֵת","רַק אִם הֶעָנִי מְבַקֵּשׁ פַּעֲמַיִם"],2,"מִי שֶׁאֵין לוֹ הַרְבֵּה – יִתֵּן מְעַט, אֲבָל הֶעָשִׁיר יִתֵּן סְכוּם גָּבוֹהַּ כְּפִי יְכָלְתּוֹ.","פֶּרֶק ק״ט, הֲלָכָה י׳","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["מָה נוֹהֲגִים כַּיּוֹם לָתֵת לִצְדָקָה, לְכָל הַפָּחוֹת?",["חֲצִי מִכָּל מַה שֶּׁיֵּשׁ לוֹ","עֲשִׂירִית מִמַּה שֶּׁהִרְוִיחַ – מַעֲשַׂר כְּסָפִים","רַק כַּמָּה מַטְבְּעוֹת בְּחַגִּים וּבְמוֹעֲדִים","אֵין שׁוּם מִנְהָג קָבוּעַ בְּעִנְיָן זֶה"],1,"נוֹהֲגִים לָתֵת לְכָל הַפָּחוֹת מַעֲשַׂר כְּסָפִים. וְהַנּוֹתֵן חֲמִישִׁית (20%) מְקַיֵּם מִצְוָה מִן הַמֻּבְחָר.","פֶּרֶק ק״ט, הֲלָכָה י״א","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["מָה עָשׂוּ גְּדוֹלֵי הַחֲכָמִים לִפְנֵי שֶׁהִתְפַּלְּלוּ?",["אָכְלוּ אֲרוּחָה גְּדוֹלָה כְּדֵי לְהִתְפַּלֵּל בְּכֹחַ","סָפְרוּ אֶת הַכֶּסֶף שֶׁהָיָה לָהֶם בַּכִּיס","קָרְאוּ סֵפֶר שָׁלֵם לִפְנֵי כָּל תְּפִלָּה","נָתְנוּ פְּרוּטָה לְעָנִי, וְרַק אַחַר כָּךְ הִתְפַּלְּלוּ"],3,"שֶׁנֶּאֱמַר: ״אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךָ״ – הַצְּדָקָה מְכִינָה אֶת הָאָדָם לִתְפִלָּה.","פֶּרֶק ק״ט, הֲלָכָה י״ב","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["מַלְוֶה יוֹדֵעַ שֶׁלַּלּוֹוֶה אֵין כֶּסֶף לְשַׁלֵּם. מָה אָסוּר לוֹ?",["לַעֲבֹר לְפָנָיו, אֲפִלּוּ רַק לְהֵרָאוֹת","לְהַלְווֹת לוֹ שׁוּב כֶּסֶף בֶּעָתִיד","לָתֵת לוֹ צְדָקָה כְּשֶׁהוּא מְבַקֵּשׁ","לְדַבֵּר אִתּוֹ עַל דִּבְרֵי תּוֹרָה"],0,"״לֹא תִהְיֶה לוֹ כְּנֹשֶׁה״ – וַאֲפִלּוּ בְּלִי לִתְבֹּעַ בִּמְפֹרָשׁ, אָסוּר לְהַרְאוֹת אֶת עַצְמוֹ, כִּי הַלּוֹוֶה עָלוּל לְהִתְבַּיֵּשׁ.","פֶּרֶק ק״ט, הֲלָכָה י״ג","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["מִי שֶׁלֹּוֶה כֶּסֶף לִדְבָרִים מְיֻתָּרִים וְאֵין לוֹ מֵהֵיכָן לְשַׁלֵּם – אֵיךְ הוּא נֶחְשָׁב?",["נֶחְשָׁב לְחָכָם שֶׁיּוֹדֵעַ לְהִסְתַּדֵּר הֵיטֵב","אֵין בְּזֶה שׁוּם בְּעָיָה, זֶה מֻתָּר","נֶחְשָׁב לְרָשָׁע, כְּמוֹ שֶׁכָּתוּב לֹוֶה רָשָׁע","נֶחְשָׁב לְצַדִּיק כִּי עָזַר לַמַּלְוֶה"],2,"״לֹוֶה רָשָׁע וְלֹא יְשַׁלֵּם״, וַחֲכָמִים אָמְרוּ: ״יְהִי מָמוֹן חֲבֵרְךָ חָבִיב עָלֶיךָ כְּשֶׁלְּךָ״.","פֶּרֶק ק״ט, הֲלָכָה י״ד","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["הִגִּיעַ זְמַן הֶחְזֵר הַחוֹב, וְיֵשׁ לַלּוֹוֶה כֶּסֶף. מָה יַעֲשֶׂה?",["יֹאמַר לַמַּלְוֶה לָבוֹא שׁוּב בַּשָּׁבוּעַ הַבָּא","יַחְזִיר מִיָּד, וְלֹא יֹאמַר לֵךְ וָשׁוּב","יְחַכֶּה עַד שֶׁהַמַּלְוֶה יְבַקֵּשׁ פַּעַם שְׁלִישִׁית","יִתֵּן רַק חֵצִי וְאֶת הַשְּׁאָר אַחַר כָּךְ"],1,"״אַל תֹּאמַר לְרֵעֲךָ לֵךְ וָשׁוּב וּמָחָר אֶתֵּן, וְיֵשׁ אִתָּךְ״ – כְּשֶׁיֵּשׁ לוֹ, יַחְזִיר מִיָּד.","פֶּרֶק ק״ט, הֲלָכָה ט״ו","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["אֵין לַלּוֹוֶה כֶּסֶף לְהַחְזִיר בַּזְּמַן. מָה עָלָיו לַעֲשׂוֹת?",["יַמְצִיא תֵּרוּץ טוֹב כְּדֵי שֶׁהַמַּלְוֶה יַמְתִּין","יִתְחַבֵּא מֵהַמַּלְוֶה עַד שֶׁיִּהְיֶה לוֹ כֶּסֶף","יֹאמַר שֶׁכְּבָר הֶחְזִיר אֶת כָּל הַחוֹב","יְבַקֵּשׁ מֵהַמַּלְוֶה לִדְחוֹת אֶת מוֹעֵד הַפֵּרָעוֹן"],3,"יְבַקֵּשׁ דְּחִיָּה בְּיֹשֶׁר, אַךְ לֹא יִדְחֶה אֶת הַמַּלְוֶה בְּתֵרוּצֵי שָׁוְא אוֹ בְּדִבְרֵי שֶׁקֶר.","פֶּרֶק ק״ט, הֲלָכָה ט״ז","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["הַלּוֹוֶה חוֹשֵׁב שֶׁהַמַּלְוֶה שָׁכַח אֶת הַחוֹב. מָה הַדִּין?",["עָלָיו לְהָשִׁיב, גַּם אִם שָׁכַח","הַחוֹב נִמְחָק, כִּי הַמַּלְוֶה כְּבָר שָׁכַח","יַחְזִיר רַק אִם הַמַּלְוֶה יִזְכֹּר וִיבַקֵּשׁ","יִתֵּן אֶת הַכֶּסֶף לִצְדָקָה בִּמְקוֹם לַמַּלְוֶה"],0,"גַּם אִם הַלּוֹוֶה חוֹשֵׁב שֶׁהַמַּלְוֶה שָׁכַח – עָלָיו לְהָשִׁיב אֶת הַחוֹב.","פֶּרֶק ק״ט, הֲלָכָה י״ז","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["מִי שֶׁחַיָּב לְהַחְזִיר הַלְוָאָה – מָה הַדִּין לְגַבֵּי צְדָקָה?",["יַרְבֶּה בִּצְדָקָה כְּדֵי שֶׁיִּהְיֶה לוֹ כֶּסֶף","יִתֵּן אֶת כָּל כַּסְפּוֹ לָעֲנִיִּים קֹדֶם","לֹא יַרְבֶּה בִּצְדָקָה לִפְנֵי שֶׁיָּשִׁיב אֶת הַחוֹב","צְדָקָה וְחוֹב הֵם עִנְיָנִים שׁוֹנִים לְגַמְרֵי"],2,"לֹא יַרְבֶּה בִּצְדָקָה טֶרֶם יָשִׁיב אֶת הַחוֹב, וּבְוַדַּאי שֶׁלֹּא יְבַזְבֵּז עַל דְּבָרִים אֲחֵרִים.","פֶּרֶק ק״ט, הֲלָכָה י״ח","צְדָקָה וְהַלְוָאָה – הֶמְשֵׁךְ"],["מִי בָּא לְבַקֵּר אֶת אַבְרָהָם כְּשֶׁהָיָה חוֹלֶה?",["הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְבַקֵּר אוֹתוֹ אַחֲרֵי הַמִּילָה","שְׁלֹשָׁה מַלְאָכִים בָּאוּ רַק כְּדֵי לְבַשֵּׂר עַל יִצְחָק","לוֹט בֶּן אָחִיו בָּא מִסְּדֹם לְבַקֵּר אוֹתוֹ","אֱלִיעֶזֶר עַבְדּוֹ בָּא עִם תְּרוּפוֹת מִן הָעִיר"],0,"חֲכָמִים דָּרְשׁוּ שֶׁה׳ בִּקֵּר אֶת אַבְרָהָם אַחֲרֵי בְּרִית הַמִּילָה, וְאָנוּ הוֹלְכִים בִּדְרָכָיו.","פֶּרֶק ק״י, הֲלָכָה א׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["בִּקּוּר חוֹלִים הוּא חֵלֶק מֵאֵיזוֹ מִצְוָה, וּמָה שְׂכָרוֹ?",["מִמִּצְוַת כִּבּוּד אָב וָאֵם, וּשְׂכָרָהּ רַק בָּעוֹלָם הַזֶּה","מִ״וְאָהַבְתָּ לְרֵעֲךָ״, פֵּרוֹת בָּעוֹלָם הַזֶּה וְהַקֶּרֶן לָעוֹלָם הַבָּא","מִמִּצְוַת צְדָקָה, וּשְׂכָרָהּ רַק בָּעוֹלָם הַבָּא","מִמִּצְוַת הַשַּׁבָּת, וְאֵין עָלֶיהָ שָׂכָר מְיֻחָד"],1,"בִּקּוּר חוֹלִים הוּא חֵלֶק מִ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״, וְאוֹכְלִים פֵּרוֹתָיו כָּאן וְהַקֶּרֶן קַיֶּמֶת לָעוֹלָם הַבָּא.","פֶּרֶק ק״י, הֲלָכוֹת ב׳ וְג׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מָה עָשָׂה רַבִּי עֲקִיבָא כְּשֶׁתַּלְמִידוֹ חָלָה וְאִישׁ לֹא בָּא?",["שָׁלַח אֵלָיו מִכְתָּב וְלֹא נִכְנַס לְבֵיתוֹ","בִּקֵּשׁ מִשְּׁאָר הַתַּלְמִידִים לָלֶכֶת בִּמְקוֹמוֹ","נִכְנַס לְבַקְּרוֹ, וְנִקָּה וְרִבֵּץ אֶת הַבַּיִת","הִמְתִּין עַד שֶׁהַתַּלְמִיד יַבְרִיא וְיָבוֹא לַיְשִׁיבָה"],2,"הַתַּלְמִיד אָמַר ״הֶחֱיִיתַנִי״, וְרַבִּי עֲקִיבָא דָּרַשׁ: מִי שֶׁאֵינוֹ מְבַקֵּר חוֹלִים כְּאִלּוּ שׁוֹפֵךְ דָּמִים.","פֶּרֶק ק״י, הֲלָכָה ד׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מָה צָרִיךְ לַעֲשׂוֹת לִפְנֵי שֶׁהוֹלְכִים לְבַקֵּר חוֹלֶה?",["לְהַגִּיעַ בְּהַפְתָּעָה וּלְהִשָּׁאֵר אֶצְלוֹ כַּמָּה שָׁעוֹת","לִשְׁאֹל אֶת הַמִּשְׁפָּחָה אִם הַחוֹלֶה מְעֻנְיָן בְּבִקּוּר כָּעֵת","לְהָבִיא אִתָּנוּ הַרְבֵּה חֲבֵרִים כְּדֵי לְהַרְעִישׁ וּלְשַׂמֵּחַ","לְהַחְלִיט לְבַד, בְּלִי לִשְׁאֹל אַף אֶחָד"],1,"עִקַּר הַבִּקּוּר לְעוֹדֵד אֶת הַחוֹלֶה וְלֹא לְהַטְרִיחַ אוֹתוֹ; לְעִתִּים עֲדִיפָה שִׂיחַת טֶלֶפוֹן אוֹ פְּרָחִים.","פֶּרֶק ק״י, הֲלָכוֹת ה׳ וְו׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["הַאִם גַּם אָדָם גָּדוֹל וּמְכֻבָּד צָרִיךְ לְבַקֵּר חוֹלִים?",["לֹא, אָדָם מְכֻבָּד פָּטוּר מִמִּצְוַת בִּקּוּר חוֹלִים","רַק פַּעַם אַחַת בְּשָׁנָה, וְלֹא יוֹתֵר מִזֶּה","רַק אִם הַחוֹלֶה הוּא קָרוֹב מִשְׁפָּחָה שֶׁלּוֹ","כֵּן, אֲפִלּוּ כַּמָּה פְּעָמִים בַּיּוֹם, בְּלִי לְהַטְרִיחַ"],3,"גַּם אָדָם גָּדוֹל מְצֻוֶּה, וְכָל הַמּוֹסִיף מְשֻׁבָּח, אֲבָל מַקְפִּידִים לֹא לְהַטְרִיחַ אֶת הַחוֹלֶה.","פֶּרֶק ק״י, הֲלָכָה ז׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מָה אוֹמְרִים בְּשַׁבָּת כְּשֶׁמִּתְפַּלְּלִים עַל חוֹלֶה?",["״שַׁבָּת הִיא מִלִּזְעֹק וּרְפוּאָה קְרוֹבָה לָבוֹא״","בְּשַׁבָּת אָסוּר בִּכְלָל לְהִתְפַּלֵּל עַל חוֹלִים","רַק שַׁבָּת שָׁלוֹם, וְלֹא מַזְכִּירִים אֶת הַחוֹלֶה","מַמְתִּינִים לְמוֹצָאֵי שַׁבָּת וְאָז אוֹמְרִים הַכֹּל"],0,"בְּחוֹל אוֹמְרִים ״הַמָּקוֹם יְרַחֵם עָלֶיךָ בְּתוֹךְ חוֹלֵי יִשְׂרָאֵל״, וּבְשַׁבָּת ״שַׁבָּת הִיא מִלִּזְעֹק...״.","פֶּרֶק ק״י, הֲלָכָה ח׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מָה עַל הַחוֹלֶה לַעֲשׂוֹת כְּדֵי לְהַבְרִיא?",["לִסְמֹךְ עַל הַנֵּס וְלֹא לָלֶכֶת לָרוֹפֵא","לָלֶכֶת לָרוֹפֵא וְלִבְטֹחַ בַּה׳ שֶׁיִּשְׁלַח רְפוּאָה עַל יָדוֹ","לָלֶכֶת לָרוֹפֵא, וְלֹא צָרִיךְ לְהִתְפַּלֵּל בִּכְלָל","לְחַכּוֹת בַּבַּיִת עַד שֶׁהַמַּחֲלָה תַּעֲבֹר מֵעַצְמָהּ"],1,"אָסוּר לִסְמֹךְ עַל הַנֵּס. הַכֹּחַ לְרַפֵּא בִּידֵי ה׳, וְהָרוֹפְאִים שְׁלִיחָיו.","פֶּרֶק ק״י, הֲלָכוֹת ט׳ וְי׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מָה עָנָה רַבִּי יוֹסֵי לְרַבָּן יוֹחָנָן בֶּן זַכַּאי עַל הַדֶּרֶךְ הַטּוֹבָה?",["עַיִן טוֹבָה, לִרְאוֹת תָּמִיד אֶת הַטּוֹב","חָבֵר טוֹב שֶׁלּוֹמְדִים אִתּוֹ תּוֹרָה כָּל יוֹם","לֵב טוֹב שֶׁאוֹהֵב אֶת כָּל הָאֲנָשִׁים","שָׁכֵן טוֹב, כְּמוֹ שֶׁכָּתוּב: ״טוֹב שָׁכֵן קָרוֹב״"],3,"רַבִּי יוֹסֵי עָנָה: שָׁכֵן טוֹב, וְכָךְ אָמַר שְׁלֹמֹה: ״טוֹב שָׁכֵן קָרוֹב מֵאָח רָחוֹק״.","פֶּרֶק קי״א, הֲלָכָה א׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["שְׁכֵנוּת טוֹבָה מְבִיאָה לְאַהֲבַת הַבְּרִיּוֹת. לָמָּה אוֹמְרִים ״אוֹי לָרָשָׁע אוֹי לִשְׁכֵנוֹ״?",["כִּי הָאָדָם עָלוּל לִלְמֹד מִשְּׁכֵנוֹ הָרַע","כִּי הַשָּׁכֵן חַיָּב לְשַׁלֵּם עַל הָרָשָׁע","כִּי הָרָשָׁע תָּמִיד גָּר לְיַד בֵּית כְּנֶסֶת","כִּי לָרָשָׁע אֵין שְׁכֵנִים בִּכְלָל"],0,"שָׁכֵן רַע עָלוּל לְהָצִיק וּלְדַרְדֵּר אֶת הִתְנַהֲגוּתֵנוּ, וְלָכֵן מְבַקְּשִׁים ״וְתַצִּילֵנוּ מִשָּׁכֵן רַע״.","פֶּרֶק קי״א, הֲלָכוֹת ב׳ וְג׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["שָׁכֵן מַרְעִישׁ וּמַפְרִיעַ לְכֻלָּם. מָה עוֹשִׂים?",["צוֹעֲקִים עָלָיו בַּחֲדַר הַמַּדְרֵגוֹת לִפְנֵי כָּל הַשְּׁכֵנִים","מַרְעִישִׁים בַּחֲזָרָה בַּלַּיְלָה כְּדֵי שֶׁיָּבִין","מְדַבְּרִים אִתּוֹ בְּנֹעַם וּמְנַסִּים לְהַגִּיעַ לְפִתְרוֹן מֻסְכָּם","מַפְסִיקִים לְדַבֵּר אִתּוֹ לְתָמִיד וְלֹא עוֹנִים לוֹ"],2,"מִתְחַשְּׁבִים בַּשְּׁכֵנִים, וְכְּשֶׁיֵּשׁ בְּעָיָה מְדַבְּרִים בְּדַרְכֵי נֹעַם וְלֹא יוֹצְרִים מַחֲלֹקֶת.","פֶּרֶק קי״א, הֲלָכוֹת ד׳ וְה׳","בִּקּוּר חוֹלִים וּשְׁכֵנוּת טוֹבָה"],["מַה פֵּרוּשׁ הַמִּלָּה ״אוֹנָאָה״, וּמָה הַטַּעַם לָאִסּוּר?",["רַמָּאוּת; כָּל אֶחָד יִזְכֶּה בַּעֲמָלוֹ בֶּאֱמֶת וּבְיֹשֶׁר","הַלְוָאָה; כְּדֵי שֶׁיִּהְיֶה לְכֻלָּם כֶּסֶף רַב","מַתָּנָה; כְּדֵי לְהַרְבּוֹת אַהֲבָה בֵּין הַבְּרִיּוֹת בָּעוֹלָם","שְׁמִירָה; כְּדֵי שֶׁהַסְּחוֹרָה לֹא תִּתְקַלְקֵל בַּחֲנוּת"],0,"אוֹנָאָה הִיא רַמָּאוּת. אָסוּר לָקַחַת מָמוֹן בְּשֶׁקֶר, וְכָל אֶחָד יִזְכֶּה בַּעֲמָלוֹ בֶּאֱמֶת וּבְיֹשֶׁר – וְכָךְ גַּם אֲחֵרִים לֹא יְרַמּוּ אוֹתָנוּ.","פֶּרֶק קי״ב, הֲלָכָה א׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["מוֹכֵר אֵינוֹ יוֹדֵעַ שֶׁהַחֵפֶץ שֶׁלּוֹ שָׁוֶה הַרְבֵּה. מַה דִּין הַקּוֹנֶה?",["מֻתָּר לִקְנוֹת בְּזוֹל, זוֹ הִזְדַּמְּנוּת טוֹבָה","אָסוּר לִקְנוֹת מִמֶּנּוּ בִּמְחִיר זוֹל מִדַּי","מֻתָּר, רַק אִם הַקּוֹנֶה עָנִי מְאֹד","מֻתָּר, אִם הַקּוֹנֶה מְשַׁלֵּם בִּמְזֻמָּן"],1,"אָסוּר לִקְנוֹת בִּמְחִיר זוֹל מִדַּי אִם הַמּוֹכֵר אֵינוֹ מוּדָע לִמְחִירוֹ הָאֲמִתִּי שֶׁל הַמּוּצָר.","פֶּרֶק קי״ב, הֲלָכָה ב׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["מוֹכֵר מְכוֹנִית מְשֻׁמֶּשֶׁת בִּמְחִיר הוֹגֵן, וְיוֹדֵעַ עַל פְּגָם שֶׁאֵינוֹ נִרְאֶה לָעַיִן. מַה עָלָיו לַעֲשׂוֹת?",["מַסְפִּיק שֶׁהַמְּחִיר הוֹגֵן, אֵין צֹרֶךְ לְסַפֵּר","לְסַפֵּר רַק אִם הַקּוֹנֶה שׁוֹאֵל אוֹתוֹ","לְהַצִּיג אוֹתָהּ כַּחֲדָשָׁה כְּדֵי שֶׁתִּמָּכֵר מַהֵר","חַיָּב לְהוֹדִיעַ לַקּוֹנֶה עַל הַפְּגָם"],3,"חַיָּב לְהוֹדִיעַ עַל הַפְּגָם, וְעוֹבֵר עַל הָאִסּוּר אֲפִלּוּ אִם הַמְּחִיר הָיָה הוֹגֵן.","פֶּרֶק קי״ב, הֲלָכָה ג׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["חָבֵר בִּקֵּשׁ מִמְּךָ עֶזְרָה, וְאֵין בְּכַוָּנָתְךָ לַעֲזֹר. מָה אָסוּר לְךָ לַעֲשׂוֹת?",["לְהַבְטִיחַ שֶׁתְּנַסֶּה לַעֲזֹר, כִּי זוֹ גְּנֵבַת דַּעַת","לוֹמַר לוֹ בְּכֵנוּת שֶׁאֵינְךָ יָכוֹל לַעֲזֹר","לְהַפְנוֹת אוֹתוֹ לְמִישֶׁהוּ אַחֵר שֶׁיּוּכַל לַעֲזֹר","לְהַסְבִּיר לוֹ בְּנַחַת מַדּוּעַ אֵינְךָ פָּנוּי עַכְשָׁו"],0,"אָסוּר לְהַבְטִיחַ שֶׁיְּנַסֶּה לַעֲזֹר אִם אֵין בְּכַוָּנָתוֹ לַעֲשׂוֹת זֹאת – זוֹ גְּנֵבַת דַּעַת.","פֶּרֶק קי״ב, הֲלָכָה ד׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["מַדּוּעַ אָסוּר לוֹמַר לְבַעַל תְּשׁוּבָה ״זְכֹר מַעֲשֶׂיךָ הָרִאשׁוֹנִים״?",["כִּי זֶה לָשׁוֹן הָרָע עַל אָדָם אַחֵר","כִּי הַזְכָּרַת עֲבָרוֹ כְּחוֹטֵא מְצַעֶרֶת אוֹתוֹ","כִּי אָסוּר לְדַבֵּר עִם בַּעֲלֵי תְּשׁוּבָה","כִּי הוּא כְּבָר שָׁכַח אֶת מַעֲשָׂיו"],1,"כַּאֲשֶׁר מַזְכִּירִים לְאָדָם אֶת עֲבָרוֹ כְּחוֹטֵא אוֹ כְּגוֹי, הַדָּבָר מְצַעֵר אוֹתוֹ – וְזוֹ אוֹנָאַת דְּבָרִים.","פֶּרֶק קי״ב, הֲלָכָה ה׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["מַדּוּעַ נֶאֱמַר בְּאוֹנָאַת דְּבָרִים ״וְיָרֵאתָ מֵאֱ-לֹהֶיךָ״?",["כִּי ה׳ יוֹדֵעַ אֶת מַחְשְׁבוֹתֶיךָ וְאֶת כַּוָּנוֹתֶיךָ","כִּי הַמּוֹכֵר יָכוֹל לְהַעֲנִישׁ אוֹתְךָ בְּעַצְמוֹ","כִּי בֵּית הַדִּין יִקְנֹס אֶת הַמְּדַבֵּר","כִּי כָּל הַשְּׁכֵנִים יִשְׁמְעוּ אֶת דְּבָרֶיךָ"],0,"מִצְוָה זוֹ מְסוּרָה לַלֵּב – הַמּוֹכֵר אֵינוֹ יוֹדֵעַ מָה הִתְכַּוַּנְתָּ, אֲבָל ה׳ יוֹדֵעַ, וּמִמֶּנּוּ עָלֶיךָ לִירֹא.","פֶּרֶק קי״ב, הֲלָכָה ו׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["מַדּוּעַ אוֹנָאַת דְּבָרִים חֲמוּרָה יוֹתֵר מֵאוֹנָאַת מָמוֹן?",["כִּי הִיא קוֹרֵית רַק בְּיָמִים טוֹבִים","כִּי בְּמָמוֹן אֶפְשָׁר לְהַחְזִיר, וּבִדְבָרִים לֹא תָּמִיד","כִּי מִלִּים עוֹלוֹת כֶּסֶף רַב יוֹתֵר","כִּי עָלֶיהָ אֵין שׁוּם אֶפְשָׁרוּת לִסְלִיחָה בִּכְלָל"],1,"בְּאוֹנָאַת מָמוֹן הָרַמַּאי יָכוֹל לְהַחְזִיר אֶת הַכֶּסֶף, וְאִלּוּ אוֹנָאַת דְּבָרִים לֹא תָּמִיד נִתָּן לְתַקֵּן.","פֶּרֶק קי״ב, הֲלָכָה ז׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["אֵילוּ מִצְווֹת מְקַיֵּם מִי שֶׁאוֹהֵב אֶת הַגֵּר וּמְקָרְבוֹ?",["רַק אֶת מִצְוַת ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״","״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״ וְגַם אֶת מִצְוַת אַהֲבַת הַגֵּר","שׁוּם מִצְוָה, רַק מִנְהָג טוֹב וְיָפֶה","רַק אֶת מִצְוַת ״וְגֵר לֹא תוֹנֶה״ בִּלְבַד"],1,"הַמְּקָרֵב אֶת הַגֵּר מְקַיֵּם גַּם ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״ וְגַם ״וַאֲהַבְתֶּם אֶת הַגֵּר״. וְצָרִיךְ לְהַקְפִּיד בִּמְיֻחָד שֶׁלֹּא לְצַעֲרוֹ, שֶׁנֶּאֱמַר ״וְגֵר לֹא תוֹנֶה״.","פֶּרֶק קי״ב, הֲלָכוֹת ח׳-ט׳","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["אֵיזֶה מִן הַדְּבָרִים הַבָּאִים מֻתָּר?",["לְהַלְבִּין פְּנֵי חָבֵר בָּרַבִּים כְּשֶׁהוּא טוֹעֶה","לְכַנּוֹת חָבֵר בְּכִנּוּי שֶׁהוּא מִתְבַּיֵּשׁ בּוֹ","לְקַלֵּל וּלְנַבֵּל אֶת הַפֶּה כְּשֶׁכּוֹעֲסִים מְאֹד","לְדַבֵּר עִם חָבֵר בִּלְשׁוֹן כָּבוֹד וּנְקִיָּה"],3,"אָסוּר לְהַלְבִּין פָּנִים בָּרַבִּים, אָסוּר לְכַנּוֹת בְּכִנּוּי מְבַיֵּשׁ, וְאָסוּר לְנַבֵּל אֶת הַפֶּה – ״בַּעֲווֹן נִבּוּל פֶּה צָרוֹת רַבּוֹת מִתְחַדְּשׁוֹת״.","פֶּרֶק קי״ב, הֲלָכוֹת י׳-י״ב","אוֹנָאָה, גְּנֵבַת דַּעַת וְהַלְבָּנַת פָּנִים"],["כַּמָּה מִצְווֹת יֵשׁ בַּפְּסוּקִים עַל הֲשָׁבַת אֲבֵדָה?",["רַק מִצְוַת עֲשֵׂה אַחַת, בְּלִי אִסּוּר","רַק אִסּוּר לֹא תַעֲשֶׂה אֶחָד בִּלְבַד","מִצְוַת עֲשֵׂה אַחַת וְלֹא תַעֲשֶׂה אַחַת","שָׁלוֹשׁ מִצְווֹת עֲשֵׂה וְאֵין שׁוּם לָאו"],2,"מִצְוַת עֲשֵׂה – ״הָשֵׁב תְּשִׁיבֵם״, וּמִצְוַת לֹא תַעֲשֶׂה – ״לֹא תוּכַל לְהִתְעַלֵּם״.","פֶּרֶק קי״ג, הֲלָכָה א׳","הֲשָׁבַת אֲבֵדָה"],["מָה קוֹרֶה בְּאַרְצֵנוּ בִּזְכוּת מִצְוַת הֲשָׁבַת אֲבֵדָה?",["הָאֲבֵדוֹת שְׁמוּרוֹת כְּאִלּוּ הֵן בְּיַד בְּעָלֵיהֶן","אֲנָשִׁים מַפְסִיקִים לְגַמְרֵי לִשְׁכֹּחַ דְּבָרִים בְּכָל מָקוֹם","הַמִּשְׁטָרָה מְקַבֶּלֶת אֶת כָּל הָאֲבֵדוֹת לְעַצְמָהּ","כָּל מוֹצֵא מְקַבֵּל שָׂכָר כַּסְפִּי גָּדוֹל"],0,"בִּזְכוּת הַמִּצְוָה הָאֲבֵדוֹת נִשְׁמָרוֹת בְּכָל מָקוֹם בְּאַרְצֵנוּ, כְּאִלּוּ הֵן תַּחַת יַד הַבְּעָלִים.","פֶּרֶק קי״ג, הֲלָכָה ב׳","הֲשָׁבַת אֲבֵדָה"],["מָה עוֹשִׂים כְּשֶׁיֵּשׁ פְּרָטִים מְזַהִים אֲבָל אִי אֶפְשָׁר לְאַתֵּר אֶת הַבְּעָלִים?",["זוֹרְקִים אֶת הַחֵפֶץ לְפַח הָאַשְׁפָּה הַקָּרוֹב","לוֹקְחִים אוֹתוֹ מִיָּד לְעַצְמֵנוּ בְּלִי לְחַכּוֹת","מַחְזִירִים אוֹתוֹ לַמָּקוֹם שֶׁבּוֹ נִמְצָא","פּוֹנִים לַמִּשְׁטָרָה כְּדֵי שֶׁתַּעֲזֹר בַּהֲשָׁבָה"],3,"כַּאֲשֶׁר אֵין אֶפְשָׁרוּת לְאַתֵּר אֶת הַבְּעָלִים – יֵשׁ לִפְנוֹת לַמִּשְׁטָרָה.","פֶּרֶק קי״ג, הֲלָכָה ג׳","הֲשָׁבַת אֲבֵדָה"],["לָמָּה אָסוּר לָגַעַת בְּחֵפֶץ שֶׁנִּמְצָא בְּמָקוֹם שָׁמוּר?",["כִּי חֲפָצִים בְּמָקוֹם שָׁמוּר תָּמִיד שַׁיָּכִים לַמָּקוֹם","כִּי כַּנִּרְאֶה בְּעָלָיו הִנִּיחוּ אוֹתוֹ שָׁם בְּכַוָּנָה","כִּי אָסוּר לְהַכְנִיס יָד לְמָקוֹם שָׁמוּר","כִּי הַמִּשְׁטָרָה כְּבָר יוֹדַעַת עַל הַחֵפֶץ"],1,"יֵשׁ סִכּוּי גָּבוֹהַּ שֶׁהַבְּעָלִים הִנִּיחַ אוֹתוֹ בְּכַוָּנָה וְיָבוֹא בְּקָרוֹב לְקַחְתּוֹ – זוֹ אֵינָהּ אֲבֵדָה.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["עַל אֵיזוֹ אֲבֵדָה צָרִיךְ לְהוֹדִיעַ לַמִּשְׁטָרָה לְפִי הַחֹק?",["רַק עַל אֲבֵדָה שֶׁשָּׁוְיָהּ מֵעַל אֶלֶף שְׁקָלִים","רַק עַל חֲפָצִים שֶׁיֵּשׁ עֲלֵיהֶם שֵׁם","עַל שׁוּם אֲבֵדָה, הַמִּשְׁטָרָה אֵינָהּ מְטַפֶּלֶת בָּזֶה","סְכוּם כֶּסֶף הַגָּדוֹל מֵעֶשְׂרִים וַחֲמִשָּׁה שְׁקָלִים"],3,"מוֹדִיעִים עַל אֲבֵדָה שֶׁשָּׁוְיָהּ מֵעַל 50 שְׁקָלִים, כֶּסֶף מֵעַל 25 שְׁקָלִים, תַּכְשִׁיט מֵעַל 25 שְׁקָלִים, אוֹ חֵפֶץ בַּעַל עֵרֶךְ מְיֻחָד.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["מָה נֶחְשָׁב ״סִימָן״ בַּאֲבֵדָה?",["פְּרָט מְיֻחָד שֶׁרַק הַמְּאַבֵּד יָכוֹל לָדַעַת","הַצֶּבַע הַכְּלָלִי שֶׁל חֵפֶץ שֶׁיֵּשׁ לְכֻלָּם","הַמְּחִיר שֶׁשִּׁלְּמוּ עַל הַחֵפֶץ בַּחֲנוּת","הַשָּׁעָה שֶׁבָּהּ פִּרְסְמוּ אֶת הַמּוֹדָעָה"],0,"סִימָן הוּא פְּרָט יִחוּדִי – שְׂרִיטָה עַל סֵפֶר, סְכוּם מְדֻיָּק בָּאַרְנָק, שַׂקִּית קְשׁוּרָה בְּאֹפֶן מְיֻחָד.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["מָתַי הַמּוֹצֵא אֵינוֹ זוֹכֶה בָּאֲבֵדָה גַּם אַחֲרֵי הַזְּמַן שֶׁבַּחֹק?",["כְּשֶׁהָאֲבֵדָה יָפָה מְאוֹד וְיָקָרָה בְּמִיּוּחָד","כְּשֶׁהַמּוֹצֵא הוּא יֶלֶד שֶׁעוֹד לוֹמֵד","כְּשֶׁהַמִּשְׁטָרָה צְרִיכָה אוֹתָהּ כִּרְאָיָה בַּחֲקִירָה","כְּשֶׁהַמּוֹצֵא שָׁכַח לִכְתֹּב אֶת הַתַּאֲרִיךְ"],2,"הַמּוֹצֵא לֹא זוֹכֶה אִם הַמִּשְׁטָרָה צְרִיכָה אֶת הָאֲבֵדָה כִּרְאָיָה, אוֹ שֶׁהַחֵפֶץ מְסֻכָּן לְשְׁלוֹם הַצִּבּוּר.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["מָצָאתָ שָׁעוֹן בְּמֶרְכָּז מִסְחָרִי. מָה הַדֶּרֶךְ הַטּוֹבָה בְּיוֹתֵר?",["לְהַשְׁאִיר אוֹתוֹ עַל הָרִצְפָּה בְּמֶרְכַּז הַמַּעֲבָר","לִמְסֹר אוֹתוֹ לַמּוֹדִיעִין, שָׁם הַמְּאַבֵּד יְחַפֵּשׂ","לָקַחַת אוֹתוֹ הַבַּיְתָה וּלְחַכּוֹת שָׁנָה שְׁלֵמָה","לָתֵת אוֹתוֹ לָאָדָם הָרִאשׁוֹן שֶׁעוֹבֵר"],1,"בְּמָקוֹם צִבּוּרִי מוֹסְרִים לַמּוֹכֵר, לַמַּזְכִּירוּת אוֹ לַמּוֹדִיעִין – שָׁם הַמְּאַבֵּד יְחַפֵּשׂ.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["מָתַי אֵין לָגַעַת בַּחֵפֶץ, גַּם אִם הוּא אֲבֵדָה?",["כְּשֶׁהַחֵפֶץ קָטָן וְזוֹל וְאֵין לוֹ עֵרֶךְ","כְּשֶׁאֵין לַמּוֹצֵא זְמַן לְטַפֵּל בַּחֵפֶץ","כְּשֶׁסָּבִיר שֶׁהַמְּאַבֵּד יַחְזֹר וְיִמְצָא אוֹתוֹ בִּמְקוֹמוֹ","כְּשֶׁהַחֵפֶץ נִמְצָא בְּיוֹם חֹל רָגִיל"],2,"כְּשֶׁנִּרְאֶה שֶׁהַסִּכּוּי הַטּוֹב בְּיוֹתֵר הוּא שֶׁהַמְּאַבֵּד יִמְצָא אֶת הַחֵפֶץ בִּמְקוֹמוֹ – אֵין לָגַעַת בּוֹ.","פֶּרֶק קי״ג, הֲלָכָה ד׳","הֲשָׁבַת אֲבֵדָה"],["מַדּוּעַ אָמְרוּ חֲכָמִים שֶׁהַגְּנֵבָה חֲמוּרָה יוֹתֵר מִן הַגֶּזֶל?",["כִּי הַגַּנָּב לוֹקֵחַ תָּמִיד דְּבָרִים יְקָרִים יוֹתֵר","כִּי הַגַּזְלָן מַחְזִיר בְּדֶרֶךְ כְּלָל אֶת מָה שֶׁלָּקַח","כִּי הוּא חוֹשֵׁשׁ מֵאֲנָשִׁים, אֲבָל לֹא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא","כִּי הַגַּנָּב גּוֹנֵב תָּמִיד בַּלַּיְלָה, וְהַגַּזְלָן רַק בְּשָׁעוֹת הַיּוֹם"],2,"הַגַּנָּב חוֹשֵׁשׁ מִבְּנֵי אָדָם וְגוֹנֵב בַּסֵּתֶר, אַךְ אֵינוֹ חוֹשֵׁשׁ מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁרוֹאֶה אוֹתוֹ.","פֶּרֶק קי״ד, הֲלָכָה ב׳","גְּנֵבָה וּגְזֵלָה"],["מֵאֵילוּ פְּסוּקִים לוֹמְדִים אֶת אִסּוּר הַגְּנֵבָה וְהַגְּזֵלָה?",["מֵהַפְּסוּקִים ״לֹא תִּגְנֹבוּ״ וְ״לֹא תִגְזֹל״ בְּסֵפֶר וַיִּקְרָא","רַק מִדִּבְרֵי חֲכָמִים, וְלֹא מִן הַתּוֹרָה עַצְמָהּ","מִפָּסוּק בְּסֵפֶר תְּהִלִּים שֶׁאָמַר דָּוִד הַמֶּלֶךְ","מִסִּפּוּר עַל גַּנָּב שֶׁנִּמְצָא בְּסֵפֶר בְּרֵאשִׁית"],0,"כָּתוּב בְּוַיִּקְרָא י״ט: ״לֹא תִּגְנֹבוּ״ וְ״וְלֹא תִגְזֹל״.","פֶּרֶק קי״ד, הֲלָכָה א׳","גְּנֵבָה וּגְזֵלָה"],["מִמָּה הַגּוֹנֵב עוֹבֵר עַל הָאִסּוּר וְחַיָּב לְשַׁלֵּם?",["רַק אִם גָּנַב דָּבָר שֶׁשָּׁוֶה הַרְבֵּה כֶּסֶף","רַק אִם הַבְּעָלִים שָׂמוּ לֵב שֶׁהַחֵפֶץ חָסֵר","רַק אִם גָּנַב יוֹתֵר מִפַּעַם אַחַת","אֲפִלּוּ שְׁוֵה פְּרוּטָה – עוֹבֵר עַל הָאִסּוּר וְחַיָּב לְשַׁלֵּם"],3,"אָסוּר לִגְנֹב אֲפִלּוּ כָּלְשֶׁהוּ, וְהַגּוֹנֵב אֲפִלּוּ שְׁוֵה פְּרוּטָה חַיָּב לְשַׁלֵּם.","פֶּרֶק קי״ד, הֲלָכָה ג׳","גְּנֵבָה וּגְזֵלָה"],["יוֹסִי הֶחְבִּיא אֶת הַקַּלְמָר שֶׁל חֲבֵרוֹ ״רַק בִּצְחוֹק״, וְהִתְכַּוֵּן לְהַחְזִיר. מָה הַדִּין?",["מֻתָּר, כִּי הוּא הִתְכַּוֵּן לְהַחְזִיר אֶת הַקַּלְמָר","אָסוּר, אֲפִלּוּ בִּצְחוֹק וְעַל מְנָת לְהַחְזִיר אַחַר כָּךְ","מֻתָּר, כִּי מַטְּרָתוֹ הָיְתָה רַק לְשַׂמֵּחַ אֶת כֻּלָּם","אָסוּר רַק אִם הֶחָבֵר נֶעֱלַב וּבָכָה"],1,"אָסוּר לִגְנֹב אֲפִלּוּ דֶּרֶךְ צְחוֹק אוֹ כְּדֵי לְצַעֵר, וַאֲפִלּוּ עַל מְנָת לְהַחְזִיר.","פֶּרֶק קי״ד, הֲלָכָה ד׳","גְּנֵבָה וּגְזֵלָה"],["מָתַי מֻתָּר לְהִשְׁתַּמֵּשׁ בְּחֵפֶץ שֶׁל אָדָם אַחֵר בְּלִי לְבַקֵּשׁ רְשׁוּת?",["תָּמִיד, כָּל עוֹד מַחְזִירִים אֶת הַחֵפֶץ שָׁלֵם","כְּשֶׁבַּעַל הַחֵפֶץ לֹא נִמְצָא כָּרֶגַע בַּבַּיִת","כְּשֶׁיּוֹדְעִים בְּוַדָּאוּת שֶׁבַּעַל הַחֵפֶץ הָיָה מַרְשֶׁה","כְּשֶׁמִּשְׁתַּמְּשִׁים בַּחֵפֶץ רַק לִזְמַן קָצָר מְאֹד"],2,"הַמִּשְׁתַּמֵּשׁ בְּלִי רְשׁוּת עוֹבֵר עַל אִסּוּר גְּנֵבָה, אֶלָּא אִם יוֹדְעִים בְּוַדָּאוּת שֶׁהָיָה מַרְשֶׁה.","פֶּרֶק קי״ד, הֲלָכָה ה׳","גְּנֵבָה וּגְזֵלָה"],["לָמָּה הַקּוֹנֶה חֵפֶץ גָּנוּב מִגַּנָּב עוֹשֶׂה עָווֹן גָּדוֹל?",["כִּי מְחַזְּקִים אֶת יָדָיו וְגוֹרְמִים לוֹ לִגְנֹב עוֹד","כִּי הַחֵפֶץ הַגָּנוּב מִתְקַלְקֵל מַהֵר יוֹתֵר מֵחֵפֶץ חָדָשׁ","כִּי הַגַּנָּב תָּמִיד מְבַקֵּשׁ מְחִיר יָקָר מִדַּי","כִּי אָסוּר לְדַבֵּר עִם אָדָם שֶׁגָּנַב פַּעַם"],0,"בְּזֶה שֶׁקּוֹנִים מֵהַגַּנָּב מְחַזְּקִים אֶת יָדָיו וְגוֹרְמִים לוֹ לִגְנֹב דְּבָרִים נוֹסָפִים.","פֶּרֶק קי״ד, הֲלָכָה ו׳","גְּנֵבָה וּגְזֵלָה"],["סְחוֹרָה נִמְכֶּרֶת בִּמְחִיר זוֹל כָּל כָּךְ, עַד שֶׁנִּרְאֶה שֶׁהִיא גְּנוּבָה. מָה הַדִּין?",["אֶפְשָׁר לִקְנוֹת, כִּי מְחִיר זוֹל הוּא מְצִיאָה טוֹבָה","מֻתָּר לִקְנוֹת, אִם הַמּוֹכֵר מַבְטִיחַ שֶׁהַסְּחוֹרָה טוֹבָה","מֻתָּר לִקְנוֹת רַק אִם קוֹנִים כַּמּוּת קְטַנָּה","אָסוּר לִקְנוֹת, כִּי עוֹלֶה חֲשָׁד שֶׁהַסְּחוֹרָה גְּנוּבָה"],3,"כַּאֲשֶׁר הַמְּחִיר זוֹל עַד שֶׁעוֹלֶה חֲשָׁד שֶׁהַסְּחוֹרָה גְּנוּבָה – אָסוּר לִקְנוֹת אוֹתָהּ.","פֶּרֶק קי״ד, הֲלָכָה ז׳","גְּנֵבָה וּגְזֵלָה"],["מָה הַדִּין לְגַבֵּי שִׁירִים, סְרָטִים, סְפָרִים וְתָכְנוֹת שֶׁל אֲחֵרִים?",["מֻתָּר לְהַעְתִּיק הַכֹּל, כִּי שִׁירִים וּסְרָטִים שַׁיָּכִים לְכֻלָּם","יֵשׁ לְיוֹצְרִים זְכֻיּוֹת, וְצָרִיךְ לְהִתְנַהֵג לְפִי הַחֹק","אָסוּר רַק לְהַעְתִּיק סְפָרִים, אֲבָל שִׁירִים מֻתָּר","מֻתָּר לְהַעְתִּיק, אִם מְשַׁתְּפִים רַק עִם חֲבֵרִים קְרוֹבִים"],1,"לַיּוֹצְרִים יֵשׁ זְכֻיּוֹת עַל יְצִירוֹתֵיהֶם, וּמַקְפִּידִים לְהִתְנַהֵג עַל פִּי הַחֹק.","פֶּרֶק קי״ד, הֲלָכָה ח׳","גְּנֵבָה וּגְזֵלָה"],["סוֹחֵר מַחְזִיק בְּבֵיתוֹ מִשְׁקָל לֹא מְדֻיָּק, אֲבָל אֵינוֹ מִשְׁתַּמֵּשׁ בּוֹ. הַאִם הוּא עוֹבֵר בְּאִסּוּר?",["לֹא, הָאִסּוּר הוּא רַק כְּשֶׁמּוֹכְרִים בָּהֶם בַּשּׁוּק","לֹא, מֻתָּר לְהַחְזִיק אוֹתָם כְּקִשּׁוּט יָפֶה בַּבַּיִת","כֵּן, גַּם הַמַּחְזִיק אוֹתָם בְּבֵיתוֹ עוֹבֵר בָּאִסּוּר","כֵּן, אֲבָל רַק אִם הֵם גְּדוֹלִים מְאֹד"],2,"מִפְּנֵי חֻמְרַת הָאִסּוּר, גַּם הַמַּחְזִיק בְּבֵיתוֹ כְּלֵי מְדִידָה לֹא מְדֻיָּקִים עוֹבֵר, שֶׁנֶּאֱמַר: ״לֹא יִהְיֶה לְךָ בְּבֵיתְךָ אֵיפָה וְאֵיפָה״.","פֶּרֶק קי״ד, הֲלָכָה ט׳","גְּנֵבָה וּגְזֵלָה"],["אֵיזֶה מַעֲשֶׂה מְצַוָּה הַתּוֹרָה לִזְכֹּר, כְּדֵי לְהִזָּהֵר מִלָּשׁוֹן הָרַע?",["אֶת קְרִיעַת יַם סוּף לִפְנֵי כָּל הָעָם","מָה שֶׁעָשָׂה ה׳ לְמִרְיָם בַּדֶּרֶךְ מִמִּצְרַיִם","אֶת בִּנְיַן הַמִּשְׁכָּן עַל יְדֵי בְּנֵי יִשְׂרָאֵל","אֶת מַתַּן הַתּוֹרָה בְּהַר סִינַי בַּמִּדְבָּר"],1,"״זָכוֹר אֵת אֲשֶׁר עָשָׂה ה׳ אֱ-לֹהֶיךָ לְמִרְיָם בַּדֶּרֶךְ בְּצֵאתְכֶם מִמִּצְרָיִם״ (דְּבָרִים כ״ד, ט) – פָּסוּק שֶׁמַּזְהִיר אוֹתָנוּ מִלָּשׁוֹן הָרַע.","פֶּרֶק קט״ו, הֲלָכָה א׳","אִסּוּר לָשׁוֹן הָרַע"],["לְפִי הַמִּדְרָשׁ, לְמָה דּוֹמֶה חֻמְרַת לָשׁוֹן הָרַע?",["כְּמוֹ אֲכִילַת מַאֲכָל שֶׁאֵינוֹ כָּשֵׁר בִּכְלָל","כְּמוֹ אִחוּר קָטָן לַתְּפִלָּה שֶׁל בֵּית הַכְּנֶסֶת","כִּשְׁפִיכַת דָּמִים, כִּי הוּא מְחַיֵּב אֶת הָאָדָם","כְּמוֹ שִׁכְחַת בְּרָכָה אַחֲרֵי הָאֹכֶל בַּבַּיִת"],2,"הַמִּדְרָשׁ אוֹמֵר: ״מִתְחַיֵּב בְּנַפְשׁוֹ לָמוּת, שֶׁקָּשָׁה לָשׁוֹן הָרַע כִּשְׁפִיכַת דָּמִים״. וּמִי שֶׁעוֹסֵק בַּתּוֹרָה בִּלְשׁוֹנוֹ – זוֹכֶה לְחַיִּים.","פֶּרֶק קט״ו, הֲלָכָה ב׳","אִסּוּר לָשׁוֹן הָרַע"],["מָה קוֹרֶה כְּשֶׁמְּשַׁתְּמְשִׁים בַּדִּבּוּר כְּדֵי לְסַיֵּעַ לַחֲבֵרִים?",["מְקַבְּלִים פְּרָס מְיֻחָד מֵהַמּוֹרֶה בְּסוֹף הַשָּׁנָה","זֶה אֵינוֹ מִצְוָה, רַק מִנְהָג טוֹב וְיָפֶה","הַחֲבֵרִים חַיָּבִים לְהַחְזִיר לָנוּ טוֹבָה מִיָּד","מַגְבִּירִים אַהֲבָה וּמְקַיְּמִים וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ"],3,"כְּשֶׁמְּשַׁתְּמְשִׁים בַּדִּבּוּר כְּדֵי לְסַיֵּעַ לַחֲבֵרִים, מַגְבִּירִים אֶת הָאַהֲבָה וּמְקַיְּמִים אֶת מִצְוַת ״וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ״.","פֶּרֶק קט״ו, הֲלָכָה ג׳","אִסּוּר לָשׁוֹן הָרַע"],["מַדּוּעַ אָסוּר לִהְיוֹת רָכִיל, גַּם כְּשֶׁהַדְּבָרִים אֱמֶת?",["כִּי דְּבָרָיו עֲלוּלִים לִגְרֹם לְסִכְסוּכִים, שִׂנְאָה וְכַעַס","כִּי רַק מְבֻגָּרִים מֻתָּרִים לְסַפֵּר עַל אֲחֵרִים","כִּי אָסוּר לְדַבֵּר עִם אֲנָשִׁים בַּהַפְסָקָה","רָכִיל מֻתָּר אִם אֵין לוֹ כַּוָּנָה רָעָה"],0,"גַּם אִם הַדְּבָרִים אֱמֶת וְגַם אִם אֵין כַּוָּנָה לְהַזִּיק – דִּבּוּרֵי רְכִילוּת עֲלוּלִים לִגְרֹם לְסִכְסוּכִים, לְשִׂנְאָה אוֹ לְכַעַס.","פֶּרֶק קט״ו, הֲלָכָה ד׳","אִסּוּר לָשׁוֹן הָרַע"],["מָה הַהֶבְדֵּל בֵּין לָשׁוֹן הָרַע לְהוֹצָאַת שֵׁם רַע?",["לָשׁוֹן הָרַע הוּא תָּמִיד שֶׁקֶר, וְשֵׁם רַע תָּמִיד אֱמֶת","לָשׁוֹן הָרַע יָכוֹל לִהְיוֹת אֱמֶת, וְשֵׁם רַע אֵינוֹ נָכוֹן","אֵין שׁוּם הֶבְדֵּל, שְׁנֵיהֶם אוֹתוֹ דָּבָר בְּדִיּוּק","לָשׁוֹן הָרַע מֻתָּר אִם אוֹמְרִים אוֹתוֹ בְּשֶׁקֶט"],1,"לָשׁוֹן הָרַע הוּא דִּבְרֵי גְּנַאי גַּם אִם הֵם אֱמֶת (וְגַם דִּבּוּר שֶׁגּוֹרֵם נֶזֶק, צַעַר, בּוּשָׁה אוֹ פַּחַד). הוֹצָאַת שֵׁם רַע הִיא דְּבָרִים רָעִים שֶׁאֵינָם נְכוֹנִים.","פֶּרֶק קט״ו, הֲלָכוֹת ה׳-ו׳","אִסּוּר לָשׁוֹן הָרַע"],["מָה עוֹשֶׂה מִי שֶׁשּׁוֹמֵעַ לָשׁוֹן הָרַע וְאֵינוֹ יָכוֹל לַעֲזֹב אוֹ לְבַקֵּשׁ לְהַפְסִיק?",["לְהַקְשִׁיב הֵיטֵב אֲבָל לֹא לְהַאֲמִין לַדְּבָרִים","לְהַמְשִׁיךְ לִשְׁמֹעַ כִּי אֵין לוֹ שׁוּם בְּרֵרָה","לְנַסּוֹת לְשַׁנּוֹת אֶת הַנּוֹשֵׂא שֶׁל הַשִּׂיחָה","לְסַפֵּר לְכֻלָּם מָה שָׁמַע בְּאוֹתָהּ שִׂיחָה"],2,"אָסוּר לִשְׁמֹעַ לָשׁוֹן הָרַע. אִם אִי אֶפְשָׁר לַעֲזֹב אוֹ לְבַקֵּשׁ לְהַפְסִיק, צָרִיךְ לְנַסּוֹת לְשַׁנּוֹת אֶת הַנּוֹשֵׂא כְּדֵי שֶׁהַדִּבּוּרִים יִפָּסְקוּ.","פֶּרֶק קט״ו, הֲלָכוֹת ז׳-ח׳","אִסּוּר לָשׁוֹן הָרַע"],["לָמָּה פִּרְסוּם דָּבָר רַע בָּרְשָׁתוֹת הַחֶבְרָתִיּוֹת עָלוּל לִהְיוֹת חָמוּר יוֹתֵר?",["כִּי בָּרְשָׁתוֹת אֵין בִּכְלָל אִסּוּר לָשׁוֹן הָרַע","כִּי כְּתִיבָה אֲרֻכָּה יוֹתֵר מִדִּבּוּר בַּפֶּה","כִּי טֵלֵפוֹנִים עוֹלִים הַרְבֵּה כֶּסֶף לַהוֹרִים","כִּי הַמֵּידָע עוֹבֵר מַהֵר לְהַרְבֵּה מְאֹד אֲנָשִׁים"],3,"בַּפֶּה מְסַפְּרִים לִמְעַטִּים, אֲבָל בָּרְשָׁתוֹת הַמֵּידָע עוֹבֵר בִּמְהִירוּת לִתְפוּצָה רְחָבָה מְאֹד, וְעָלוּל לִגְרֹם בּוּשָׁה גְּדוֹלָה וּנְזָקִים חֲמוּרִים.","פֶּרֶק קט״ו, הֲלָכָה ט׳","אִסּוּר לָשׁוֹן הָרַע"],["מִי נִקְרָא בְּפִי חֲכָמִים ״בַּעַל לָשׁוֹן הָרַע״?",["מִי שֶׁמַּרְבֶּה בְּלָשׁוֹן הָרַע וּכְלָל אֵינוֹ נִזְהָר","כָּל מִי שֶׁנִּכְשַׁל פַּעַם אַחַת בְּדִבּוּר גְּנַאי","מִי שֶׁמְּדַבֵּר הַרְבֵּה מְאֹד בְּכָל שָׁעוֹת הַיּוֹם","מִי שֶׁשּׁוֹכֵחַ לְסַפֵּר דְּבָרִים טוֹבִים עַל אֲחֵרִים"],0,"כִּמְעַט כָּל אָדָם נִכְשָׁל לִפְעָמִים, אֲבָל ״בַּעֲלֵי לָשׁוֹן הָרַע״ הֵם מִי שֶׁמַּרְבִּים בְּכָךְ וְאֵינָם מְנַסִּים לְהִזָּהֵר. יֵשׁ לְהִתְרַחֵק מֵהֶם.","פֶּרֶק קט״ו, הֲלָכָה י׳","אִסּוּר לָשׁוֹן הָרַע"],["מַהוּ ״אֲבַק לָשׁוֹן הָרַע״?",["לָשׁוֹן הָרַע שֶׁנֶּאֱמַר בְּשֶׁקֶט, וְלָכֵן הוּא מֻתָּר","דְּבָרִים שֶׁעֲלוּלִים לִגְרֹם לְלָשׁוֹן הָרַע, וַאֲסוּרִים מִדִּבְרֵי חֲכָמִים","דִּבְרֵי שֶׁבַח, שֶׁתָּמִיד מֻתָּר לְהַרְבּוֹת בָּהֶם","לָשׁוֹן הָרַע עַל אָדָם שֶׁגָּר בְּעִיר רְחוֹקָה מְאֹד"],1,"אֲבַק לָשׁוֹן הָרַע – לְמָשָׁל: שֶׁבַח מֻגְזָם, ״אֵינִי רוֹצֶה לְסַפֵּר מָה הָיָה עִם פְּלוֹנִי״, אוֹ שֶׁבַח שֶׁגּוֹרֵם לַחָבֵר הֶפְסֵד.","פֶּרֶק קט״ו, הֲלָכָה י״א","אִסּוּר לָשׁוֹן הָרַע"],["מָתַי מֻתָּר לְסַפֵּר לָשׁוֹן הָרַע לְתוֹעֶלֶת?",["תָּמִיד, אִם הַסִּפּוּר מְעַנְיֵן אֶת הַשּׁוֹמְעִים","אַף פַּעַם, גַּם לֹא כְּדֵי לְהַזְהִיר אָדָם","רַק אִם אֵין בְּרֵרָה אַחֶרֶת לִמְנֹעַ אֶת הַנֶּזֶק","רַק כְּשֶׁמּוֹסִיפִים פְּרָטִים כְּדֵי שֶׁיַּאֲמִינוּ לָנוּ"],2,"מֻתָּר לְהַזְהִיר (לְמָשָׁל מִנּוֹכֵל), אֲבָל קֹדֶם מְנַסִּים לִמְנֹעַ אֶת הַנֶּזֶק בְּדֶרֶךְ אַחֶרֶת, מְסַפְּרִים רַק מָה שֶׁחִיּוּנִי, וְלֹא מַגְזִימִים.","פֶּרֶק קט״ו, הֲלָכוֹת י״ב-י״ג","אִסּוּר לָשׁוֹן הָרַע"],["לָמָּה קָבְעוּ חֲכָמִים לְבָרֵךְ לִפְנֵי הָאֲכִילָה וְאַחֲרֶיהָ?",["כְּדֵי שֶׁהָאֹכֶל יִהְיֶה טָעִים וּמָתוֹק יוֹתֵר בַּפֶּה","כְּדֵי שֶׁנֹּאכַל לְאַט וְלֹא נְמַהֵר בַּסְּעוּדָה","כִּי אָסוּר לֵיהָנוֹת מִן הָעוֹלָם הַזֶּה בְּלִי בְּרָכָה","רַק כְּדֵי לְהַרְגִּיל אֶת הַיְּלָדִים לְדַבֵּר יָפֶה"],2,"אָמְרוּ חֲכָמִים: ״אָסוּר לוֹ לְאָדָם שֶׁיֵּהָנֶה מִן הָעוֹלָם הַזֶּה בְּלֹא בְּרָכָה״, וְלָכֵן קָבְעוּ בְּרָכָה רִאשׁוֹנָה וּבְרָכָה אַחֲרוֹנָה.","פֶּרֶק כ״ה, הֲלָכָה א׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["מָה הִיא הַבְּרָכָה הָרִאשׁוֹנָה שֶׁמְּבָרְכִים לִפְנֵי הָאֲכִילָה?",["תּוֹדָה לַה׳ עַל הָאֹכֶל שֶׁכְּבָר אָכַלְנוּ קֹדֶם","כְּמוֹ בַּקָּשַׁת רְשׁוּת מֵה׳ לֶאֱכֹל אֶת הַמַּאֲכָל","תְּפִלָּה שֶׁהָאֹכֶל יַסְפִּיק לְכָל בְּנֵי הַבַּיִת","סִימָן לַחֲבֵרִים שֶׁאֶפְשָׁר לְהַתְחִיל לֶאֱכֹל עַכְשָׁו"],1,"בְּרָכָה רִאשׁוֹנָה הִיא כְּבַקָּשַׁת רְשׁוּת מֵה׳ לֶאֱכֹל, וּבְרָכָה אַחֲרוֹנָה הִיא הוֹדָאָה לַה׳ אַחֲרֵי הָאֲכִילָה.","פֶּרֶק כ״ה, הֲלָכָה א׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["אַחֲרֵי שֶׁאָכַלְתִּי פְּרוּסַת לֶחֶם דַּקָּה (כְּזַיִת), מָה אֲבָרֵךְ?",["עַל הַמִּחְיָה, כִּי זוֹ רַק פְּרוּסָה קְטַנָּה","בּוֹרֵא נְפָשׁוֹת, כִּי לֹא אָכַלְתִּי הַרְבֵּה לֶחֶם","לֹא מְבָרְכִים כְּלָל עַל פְּרוּסָה אַחַת בִּלְבַד","בִּרְכַּת הַמָּזוֹן, כִּי אָכַלְתִּי כְּזַיִת לֶחֶם"],3,"לְאַחַר אֲכִילַת כְּזַיִת לֶחֶם (כִּפְרוּסַת לֶחֶם דַּקָּה) אוֹ יוֹתֵר מְבָרְכִים בִּרְכַּת הַמָּזוֹן.","פֶּרֶק כ״ה, הֲלָכָה ד׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["לָמָּה לְ״פַת הַבָּאָה בְּכִסְנִין״ יֵשׁ פָּחוֹת חֲשִׁיבוּת מִלֶּחֶם רָגִיל?",["כִּי לֹא רְגִילִים לִקְבֹּעַ עָלֶיהָ סְעוּדָה","כִּי הִיא אֵינָהּ עֲשׂוּיָה מֵחֲמֵשֶׁת מִינֵי דָּגָן","כִּי אוֹפִים אוֹתָהּ רַק בִּימֵי חֹל","כִּי הִיא קְטַנָּה מִדַּי וְלֹא מַשְׂבִּיעָה"],0,"מֵחֲמֵשֶׁת מִינֵי דָּגָן מְכִינִים גַּם מַאֲפִים שֶׁלֹּא רְגִילִים לִקְבֹּעַ עֲלֵיהֶם סְעוּדָה, וּמִפְּנֵי כָּךְ יֵשׁ לָהֶם פָּחוֹת חֲשִׁיבוּת. הֵם נִקְרָאִים ״פַּת הַבָּאָה בְּכִסְנִין״.","פֶּרֶק כ״ה, הֲלָכָה ה׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["אָכַלְתִּי כְּזַיִת עוּגִיּוֹת. אֵיזוֹ בְּרָכָה אַחֲרוֹנָה אֲבָרֵךְ?",["בִּרְכַּת הַמָּזוֹן, כְּמוֹ אַחֲרֵי לֶחֶם רָגִיל","בּוֹרֵא נְפָשׁוֹת רַבּוֹת, כְּמוֹ אַחֲרֵי פֵּרוֹת","עַל הַמִּחְיָה, הַנִּקְרֵאת גַּם ״בִּרְכַּת מֵעֵין שָׁלֹשׁ״","אֵין צֹרֶךְ לְבָרֵךְ אַחֲרֵי עוּגִיּוֹת בִּכְלָל"],2,"לִפְנֵי פַּת הַבָּאָה בְּכִסְנִין מְבָרְכִים ״בּוֹרֵא מִינֵי מְזוֹנוֹת״, וְאַחֲרֵי כְּזַיִת אוֹ יוֹתֵר מְבָרְכִים ״עַל הַמִּחְיָה״, הַנִּקְרֵאת גַּם ״בִּרְכַּת מֵעֵין שָׁלֹשׁ״.","פֶּרֶק כ״ה, הֲלָכָה ו׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["יוֹסִי אָכַל הַרְבֵּה בּוּרֵקַס, כַּשִּׁעוּר שֶׁבְּנֵי אָדָם קוֹבְעִים עָלָיו סְעוּדָה, אֲבָל הוּא מַרְגִּישׁ שֶׁלֹּא שָׂבַע. מָה הַדִּין?",["מְבָרֵךְ מְזוֹנוֹת, כִּי הוּא מַרְגִּישׁ שֶׁלֹּא שָׂבַע","מְבָרֵךְ הַמּוֹצִיא וּבִרְכַּת הַמָּזוֹן, גַּם אִם לֹא שָׂבַע","הַכֹּל תָּלוּי בַּהַרְגָּשָׁה שֶׁלּוֹ, אִם שָׂבַע אוֹ לֹא","מְבָרֵךְ בּוֹרֵא פְּרִי הָאֲדָמָה וּבוֹרֵא נְפָשׁוֹת"],1,"כְּשֶׁאוֹכְלִים פַּת הַבָּאָה בְּכִסְנִין בְּשִׁעוּר קְבִיעוּת סְעוּדָה מְבָרְכִים ״הַמּוֹצִיא״ וּבִרְכַּת הַמָּזוֹן. הַדָּבָר אֵינוֹ תָּלוּי בְּהַרְגָּשַׁת הָאוֹכֵל, אֶלָּא בְּשִׁעוּר קְבִיעוּת סְעוּדָה אֵצֶל רֹב בְּנֵי הָאָדָם.","פֶּרֶק כ״ה, הֲלָכָה ח׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["לְפִי מַה שֶּׁנּוֹהֲגִים בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים, מָה שִׁעוּר קְבִיעוּת סְעוּדָה?",["כְּבֵיצָה אַחַת, בְּעֵרֶךְ שְׁתֵּי פְּרוּסוֹת לֶחֶם","כְּזַיִת אֶחָד, בְּעֵרֶךְ פְּרוּסַת לֶחֶם דַּקָּה","כְּעֶשֶׂר בֵּיצִים, בְּעֵרֶךְ עֶשְׂרִים פְּרוּסוֹת לֶחֶם דַּקּוֹת","כְּאַרְבַּע בֵּיצִים, בְּעֵרֶךְ שְׁמוֹנֶה פְּרוּסוֹת לֶחֶם דַּקּוֹת"],3,"יֵשׁ אוֹמְרִים שֶׁשִּׁעוּר קְבִיעוּת סְעוּדָה קָבוּעַ: כְּאַרְבַּע בֵּיצִים (224 סמ״ק, כִּשְׁמוֹנֶה פְּרוּסוֹת לֶחֶם דַּקּוֹת), וְכָךְ נוֹהֲגִים בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים.","פֶּרֶק כ״ה, הֲלָכָה ח׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["לָשׁוּ בָּצֵק עִם מְעַט שֶׁמֶן, אֲבָל טַעַם הַמַּאֲפֶה דּוֹמֶה לְלֶחֶם רָגִיל. מָה מְבָרְכִים?",["הַמּוֹצִיא, כִּי הַשֶּׁמֶן אֵינוֹ מַשְׁפִּיעַ עַל הַטַּעַם","מְזוֹנוֹת, כִּי כָּל תּוֹסֶפֶת שֶׁמֶן הוֹפֶכֶת לְעוּגָה","שֶׁהַכֹּל, כִּי הַמַּאֲפֶה כְּבָר אֵינוֹ לֶחֶם רָגִיל","בּוֹרֵא פְּרִי הָאֲדָמָה, כִּי הוּא עָשׂוּי מִדָּגָן"],0,"מַאֲפֶה שֶׁעֵרְבוּ בּוֹ שֶׁמֶן אוֹ דְּבַשׁ שֶׁמַּשְׁפִּיעִים עַל טַעְמוֹ הוּא פַּת הַבָּאָה בְּכִסְנִין, אֲבָל אִם הַתּוֹסֶפֶת אֵינָהּ מַשְׁפִּיעָה וְטַעְמוֹ דּוֹמֶה לְלֶחֶם רָגִיל, מְבָרְכִים ״הַמּוֹצִיא״.","פֶּרֶק כ״ה, הֲלָכָה ז׳","בִּרְכַּת חֲמֵשֶׁת מִינֵי דָּגָן"],["לָמָּה נִקְרֵאת הַבְּרָכָה בְּשֵׁם ״מֵעֵין שָׁלוֹשׁ״?",["כִּי אוֹמְרִים אוֹתָהּ רַק עַל שְׁלוֹשָׁה סוּגֵי מַאֲכָלִים בִּלְבַד","כִּי צָרִיךְ לֶאֱכֹל שָׁלוֹשׁ פְּעָמִים לִפְנֵי שֶׁמְּבָרְכִים אוֹתָהּ","כִּי רְמוּזוֹת בָּהּ שָׁלוֹשׁ הַבְּרָכוֹת הָרִאשׁוֹנוֹת שֶׁל בִּרְכַּת הַמָּזוֹן","כִּי חֲכָמִים קָבְעוּ לְבָרֵךְ אוֹתָהּ שָׁלוֹשׁ פְּעָמִים בַּיּוֹם"],2,"רְמוּזוֹת בָּהּ שָׁלוֹשׁ הַבְּרָכוֹת הָרִאשׁוֹנוֹת שֶׁל בִּרְכַּת הַמָּזוֹן, שֶׁהֵן מִן הַתּוֹרָה, וְגַם הַבְּרָכָה הָרְבִיעִית שֶׁהִיא מִדִּבְרֵי חֲכָמִים.","פֶּרֶק כ״ו, הֲלָכָה א׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["לָמָּה קָבְעוּ חֲכָמִים בְּרָכָה אַחֲרוֹנָה מְיֻחֶדֶת לְפֵרוֹת שִׁבְעַת הַמִּינִים?",["כִּי הֵם הַפֵּרוֹת הַמְּתוּקִים וְהַיְּקָרִים בְּיוֹתֵר בָּעוֹלָם","כִּי נִשְׁתַּבְּחָה בָּהֶם אֶרֶץ יִשְׂרָאֵל, וְהֵם חֲשׁוּבִים מְאֹד","כִּי אוֹכְלִים אוֹתָם רַק בְּשַׁבָּתוֹת וּבְחַגִּים","כִּי הֵם גְּדֵלִים רַק בְּאֶרֶץ יִשְׂרָאֵל"],1,"אֵלּוּ פֵּרוֹת שֶׁנִּשְׁתַּבְּחָה בָּהֶם אֶרֶץ יִשְׂרָאֵל, וּמִפְּנֵי חֲשִׁיבוּתָם קָבְעוּ לָהֶם חֲכָמִים בְּרָכָה אַחֲרוֹנָה מְיֻחֶדֶת.","פֶּרֶק כ״ו, הֲלָכָה ב׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["אָכַלְתָּ תְּאֵנִים שֶׁגָּדְלוּ בְּחוּץ לָאָרֶץ. אֵיךְ תַּחְתֹּם אֶת ״מֵעֵין שָׁלוֹשׁ״?",["בָּרוּךְ אַתָּה ה׳ עַל הָאָרֶץ וְעַל פֵּרוֹתֶיהָ","בָּרוּךְ אַתָּה ה׳ עַל הָאָרֶץ וְעַל הַמִּחְיָה","בָּרוּךְ אַתָּה ה׳ בּוֹרֵא נְפָשׁוֹת רַבּוֹת","בָּרוּךְ אַתָּה ה׳ עַל הָאָרֶץ וְעַל הַפֵּרוֹת"],3,"עַל פֵּרוֹת שִׁבְעַת הַמִּינִים שֶׁגָּדְלוּ בְּחוּץ לָאָרֶץ חוֹתְמִים ״עַל הָאָרֶץ וְעַל הַפֵּרוֹת״.","פֶּרֶק כ״ו, הֲלָכָה ג׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["שָׁתִיתָ יַיִן מֵעֲנָבִים שֶׁגָּדְלוּ בְּאֶרֶץ יִשְׂרָאֵל. אֵיךְ תַּחְתֹּם?",["בָּרוּךְ אַתָּה ה׳ עַל הָאָרֶץ וְעַל פְּרִי גַפְנָהּ","בָּרוּךְ אַתָּה ה׳ עַל הָאָרֶץ וְעַל פְּרִי הַגֶּפֶן","בָּרוּךְ אַתָּה ה׳ עַל הָאָרֶץ וְעַל פֵּרוֹתֶיהָ","בָּרוּךְ אַתָּה ה׳ עַל הָאָרֶץ וְעַל הַמִּחְיָה"],0,"עַל יַיִן מֵעֲנָבִים שֶׁגָּדְלוּ בְּאֶרֶץ יִשְׂרָאֵל חוֹתְמִים ״עַל הָאָרֶץ וְעַל פְּרִי גַפְנָהּ״, וְעַל יַיִן מִחוּץ לָאָרֶץ ״עַל פְּרִי הַגֶּפֶן״.","פֶּרֶק כ״ו, הֲלָכָה ד׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["אָכַלְתָּ פַּסְטָה וּתְמָרִים וְשָׁתִיתָ יַיִן. מָה עוֹשִׂים?",["מְבָרְכִים רַק עַל הַיַּיִן, כִּי הוּא הַחָשׁוּב בְּיוֹתֵר","מְבָרְכִים ״מֵעֵין שָׁלוֹשׁ״ שָׁלוֹשׁ פְּעָמִים, פַּעַם עַל כָּל מַאֲכָל","מְבָרְכִים ״מֵעֵין שָׁלוֹשׁ״ אַחַת וּמַזְכִּירִים בָּהּ אֶת כָּל הַדְּבָרִים","מְבָרְכִים בִּרְכַּת הַמָּזוֹן, כִּי אָכְלוּ כַּמָּה מַאֲכָלִים שׁוֹנִים"],2,"מְבָרְכִים פַּעַם אַחַת ״מֵעֵין שָׁלוֹשׁ״ וּמְשַׁלְּבִים בַּנֻּסָּח אֶת הַכֹּל: ״עַל הָאָרֶץ וְעַל הַמִּחְיָה וְעַל פְּרִי גַפְנָהּ וְעַל פֵּרוֹתֶיהָ״.","פֶּרֶק כ״ו, הֲלָכָה ה׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["מָתַי צֶמַח נֶחְשָׁב לְעֵץ, וּמְבָרְכִים עַל פֵּרוֹתָיו ״בּוֹרֵא פְּרִי הָעֵץ״?",["כְּשֶׁהוּא גָּבוֹהַּ יוֹתֵר מֵאָדָם מְבֻגָּר","כְּשֶׁהַפֵּרוֹת שֶׁלּוֹ גְּדֵלִים קָרוֹב לָאֲדָמָה","כְּשֶׁיֵּשׁ לוֹ הַרְבֵּה עָלִים יְרֻקִּים וּגְדוֹלִים","כְּשֶׁהַגֶּזַע וְהָעֲנָפִים שֶׁלּוֹ מִתְקַיְּמִים מִשָּׁנָה לְשָׁנָה"],3,"צֶמַח שֶׁהַגֶּזַע וְהָעֲנָפִים שֶׁלּוֹ מִתְקַיְּמִים מִשָּׁנָה לְשָׁנָה נֶחְשָׁב לְעֵץ, וּמְבָרְכִים ״בּוֹרֵא פְּרִי הָעֵץ״ וְ״בוֹרֵא נְפָשׁוֹת״.","פֶּרֶק כ״ו, הֲלָכָה ו׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["לָמָּה מְבָרְכִים עַל בָּנָנָה ״בּוֹרֵא פְּרִי הָאֲדָמָה״?",["כִּי הַבָּנָנָה רַכָּה מְאֹד וּמְקַלְּפִים אוֹתָהּ לִפְנֵי הָאֲכִילָה","כִּי הַגֶּזַע מִתְיַבֵּשׁ אַחֲרֵי הַקְּטִיף, וְגֶזַע חָדָשׁ יוֹצֵא מֵהַשָּׁרָשִׁים","כִּי הַבָּנָנָה גְּדֵלָה בַּמְּדִינוֹת הַחַמּוֹת וְלֹא בְּכָל מָקוֹם","כִּי הַבָּנָנָה צְהֻבָּה כְּמוֹ הַרְבֵּה יְרָקוֹת אֲחֵרִים"],1,"הַגֶּזַע שֶׁל הַבָּנָנָה מִתְיַבֵּשׁ אַחֲרֵי שֶׁקּוֹטְפִים אֶת הַפֵּרוֹת, וּבִמְקוֹמוֹ יוֹצֵא גֶּזַע אַחֵר מֵהַשָּׁרָשִׁים.","פֶּרֶק כ״ו, הֲלָכָה ז׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["לָמָּה מְבָרְכִים לְמַעֲשֶׂה עַל פְּסִיפְלוֹרָה ״בּוֹרֵא פְּרִי הָאֲדָמָה״?",["כִּי הִיא נוֹתֶנֶת פֵּרוֹת כְּבָר בַּשָּׁנָה הָרִאשׁוֹנָה, וְסָפֵק בְּרָכוֹת לְהָקֵל","כִּי הִיא גְּדֵלָה עַל שִׂיחַ נָמוּךְ וְלֹא עַל עֵץ","כִּי הַגֶּזַע שֶׁלָּהּ נֶעֱקָר מִן הָאֲדָמָה בְּכָל חֹרֶף","כִּי הַפְּרִי שֶׁלָּהּ חָמוּץ וְאֵין בּוֹ הַרְבֵּה מָתוֹק"],0,"צֶמַח שֶׁמּוֹצִיא פֵּרוֹת כְּבָר בַּשָּׁנָה הָרִאשׁוֹנָה אֵינוֹ נֶחְשָׁב עֵץ. וְאַף שֶׁיֵּשׁ אוֹמְרִים שֶׁהוּא עֵץ, ״סָפֵק בְּרָכוֹת לְהָקֵל״.","פֶּרֶק כ״ו, הֲלָכָה ח׳","מֵעֵין שָׁלוֹשׁ וּפְרִי הָעֵץ"],["מָה מְבָרְכִים לִפְנֵי וְאַחֲרֵי אֲכִילַת פִּטְרִיּוֹת?",["בּוֹרֵא פְּרִי הָאֲדָמָה וְאַחַר כָּךְ בּוֹרֵא נְפָשׁוֹת","בּוֹרֵא פְּרִי הָאֲדָמָה וְאַחַר כָּךְ עַל הַמִּחְיָה","שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ וְאַחַר כָּךְ בּוֹרֵא נְפָשׁוֹת","שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ וְאַחַר כָּךְ אֵין בְּרָכָה"],2,"פִּטְרִיּוֹת אֵינָן גְּדֵלוֹת מִן הָאָרֶץ, וְלָכֵן מְבָרְכִים עֲלֵיהֶן ״שֶׁהַכֹּל״ וְ״בוֹרֵא נְפָשׁוֹת״.","פֶּרֶק כ״ו, הֲלָכָה ט׳","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["מָה הַבְּרָכוֹת עַל אֹרֶז מְבֻשָּׁל?",["בּוֹרֵא מִינֵי מְזוֹנוֹת וְאַחַר כָּךְ בּוֹרֵא נְפָשׁוֹת","בּוֹרֵא מִינֵי מְזוֹנוֹת וְאַחַר כָּךְ עַל הַמִּחְיָה","בּוֹרֵא פְּרִי הָאֲדָמָה וְאַחַר כָּךְ בּוֹרֵא נְפָשׁוֹת","שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ וְאַחַר כָּךְ בּוֹרֵא נְפָשׁוֹת"],0,"עַל אֹרֶז מְבֻשָּׁל מְבָרְכִים ״בּוֹרֵא מִינֵי מְזוֹנוֹת״, וְאַחֲרָיו ״בּוֹרֵא נְפָשׁוֹת״.","פֶּרֶק כ״ו, הֲלָכָה י׳","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["דָּנִי רוֹצֶה לֶאֱכֹל פְּרִיכִיַּת אֹרֶז. אֵיזוֹ בְּרָכָה רִאשׁוֹנָה יְבָרֵךְ?",["תָּמִיד שֶׁהַכֹּל, כִּי אֵין לָהּ בְּרָכָה אַחֶרֶת","תָּמִיד בּוֹרֵא מִינֵי מְזוֹנוֹת, כָּךְ נוֹהֲגִים כֻּלָּם","אֵין צָרִיךְ לְבָרֵךְ עָלֶיהָ כְּלָל, כִּי הִיא יְבֵשָׁה","יֵשׁ כַּמָּה מִנְהָגִים, וְיִנְהַג כְּמִנְהַג בֵּית הוֹרָיו"],3,"עַל פְּרִיכִיּוֹת אֹרֶז יֵשׁ מְבָרְכִים ״מְזוֹנוֹת״, יֵשׁ ״הָאֲדָמָה״ וְיֵשׁ ״שֶׁהַכֹּל״. כָּל אֶחָד יְבָרֵר מָה מִנְהַג הוֹרָיו וְיַעֲשֶׂה כֵּן.","פֶּרֶק כ״ו, הֲלָכָה י״א","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["וּמָה מְבָרְכִים אַחֲרֵי אֲכִילַת פְּרִיכִיּוֹת אֹרֶז?",["תָּלוּי בַּבְּרָכָה הָרִאשׁוֹנָה שֶׁבֵּרַכְתָּ עֲלֵיהֶן קֹדֶם","לְכָל הַדֵּעוֹת מְבָרְכִים אַחֲרֵיהֶן בּוֹרֵא נְפָשׁוֹת","לְכָל הַדֵּעוֹת מְבָרְכִים אַחֲרֵיהֶן עַל הַמִּחְיָה","אֵין מְבָרְכִים אַחֲרֵיהֶן שׁוּם בְּרָכָה אַחֲרוֹנָה"],1,"אַף שֶׁיֵּשׁ כַּמָּה דֵּעוֹת בַּבְּרָכָה הָרִאשׁוֹנָה, לְכָל הַדֵּעוֹת מְבָרְכִים אַחֲרֵי פְּרִיכִיּוֹת אֹרֶז ״בּוֹרֵא נְפָשׁוֹת״.","פֶּרֶק כ״ו, הֲלָכָה י״א","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["כַּמָּה צָרִיךְ לֶאֱכֹל כְּדֵי לְבָרֵךְ בְּרָכָה אַחֲרוֹנָה?",["כְּבֵיצָה שְׁלֵמָה, בְּתוֹךְ חֲצִי שָׁעָה לְכָל הַיּוֹתֵר","כָּל כַּמּוּת שֶׁהִיא, אֲפִלּוּ פֵּרוּר קָטָן מְאוֹד","כַּזַּיִת, כְּמוֹ פְּרוּסַת לֶחֶם דַּקָּה, בְּתוֹךְ אַרְבַּע דַּקּוֹת","צַלַּחַת מְלֵאָה, בְּלִי שׁוּם הַגְבָּלַת זְמַן"],2,"מְבָרְכִים בְּרָכָה אַחֲרוֹנָה רַק אַחֲרֵי אֲכִילַת כַּזַּיִת (28 סמ״ק, כְּמוֹ פְּרוּסַת לֶחֶם דַּקָּה) בְּתוֹךְ אַרְבַּע דַּקּוֹת.","פֶּרֶק כ״ו, הֲלָכָה י״ג","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["אָבִי רוֹצֶה לִטְעֹם רַק לְגִימָה קְטַנָּה מִמִּיץ. מָה הַדִּין?",["אֵינוֹ מְבָרֵךְ, כִּי הוּא שׁוֹתֶה מְעַט מְאוֹד","מְבָרֵךְ שֶׁהַכֹּל לְפָנָיו, אֲבָל לֹא בְּרָכָה אַחֲרוֹנָה","מְבָרֵךְ שֶׁהַכֹּל לְפָנָיו וּבוֹרֵא נְפָשׁוֹת לְאַחֲרָיו","מְבָרֵךְ רַק בּוֹרֵא נְפָשׁוֹת אַחֲרֵי הַשְּׁתִיָּה"],1,"בְּרָכָה רִאשׁוֹנָה מְבָרְכִים אֲפִלּוּ עַל מְעַט. בְּרָכָה אַחֲרוֹנָה עַל מַשְׁקֶה מְבָרְכִים רַק אַחֲרֵי רְבִיעִית, וּלְגִימָה קְטַנָּה הִיא פָּחוֹת מִזֶּה.","פֶּרֶק כ״ו, הֲלָכָה ט״ז","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["לָמָּה עַל מִיץ מְבָרְכִים גַּם כְּשֶׁשּׁוֹתִים אוֹתוֹ כְּדֵי לִבְלֹעַ גְּלוּלָה?",["כִּי מִיץ עָשׂוּי מִפֵּרוֹת, וְעַל פֵּרוֹת תָּמִיד מְבָרְכִים","כִּי שׁוֹתִים מִמֶּנּוּ תָּמִיד כַּמּוּת גְּדוֹלָה מְאוֹד","כִּי כָּל מַשְׁקֶה צָרִיךְ בְּרָכָה, גַּם מַיִם","כִּי יֵשׁ לוֹ טַעַם שֶׁהַגָּרוֹן נֶהֱנֶה מִמֶּנּוּ"],3,"עַל מַשְׁקָאוֹת שֶׁאֵינָם מַיִם מְבָרְכִים גַּם שֶׁלֹּא לְהַרְווֹת צִמָּאוֹן, כִּי יֵשׁ לָהֶם טַעַם שֶׁהַגָּרוֹן נֶהֱנֶה מִמֶּנּוּ. עַל מַיִם – רַק כְּשֶׁצְּמֵאִים.","פֶּרֶק כ״ו, הֲלָכָה ט״ו","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["לָמָּה אֵין מְבָרְכִים בְּרָכָה אַחֲרוֹנָה עַל כּוֹס תֵּה חַם?",["כִּי לֹא שׁוֹתִים מִמֶּנּוּ רְבִיעִית בִּזְמַן קָצָר","כִּי מַשְׁקֶה חַם אֵינוֹ חָשׁוּב כְּמוֹ מַאֲכָל","כִּי עַל תֵּה מְבָרְכִים רַק בְּרָכָה רִאשׁוֹנָה תָּמִיד","כִּי בְּרָכָה אַחֲרוֹנָה הִיא רַק עַל מַאֲכָלִים"],0,"בְּרָכָה אַחֲרוֹנָה עַל מַשְׁקֶה מְבָרְכִים רַק אַחֲרֵי רְבִיעִית בְּתוֹךְ כַּמָּה שְׁנִיּוֹת, וּמַשְׁקֶה חַם שׁוֹתִים לְאַט. הָרוֹצֶה לְהַדֵּר יִשְׁתֶּה רְבִיעִית מִמַּשְׁקֶה אַחֵר אוֹ יֹאכַל כַּזַּיִת וִיבָרֵךְ.","פֶּרֶק כ״ו, הֲלָכָה י״ז","שֶׁהַכֹּל, מְזוֹנוֹת וּמַשְׁקָאוֹת"],["אֵיזוֹ בְּרָכָה הִיא הָאַחֲרוֹנָה בְּסֵדֶר הַקְּדִימָה?",["בְּרָכַת בּוֹרֵא פְּרִי הָעֵץ, כִּי הִיא עַל פֵּרוֹת","בְּרָכַת שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ, שֶׁהִיא אַחֲרוֹנָה בַּסֵּדֶר","בְּרָכַת בּוֹרֵא פְּרִי הָאֲדָמָה, שֶׁבָּאָה אַחֲרֵי הָעֵץ","בְּרָכַת בּוֹרֵא מִינֵי מְזוֹנוֹת, שֶׁהִיא לְכַעֲכִים"],1,"הַסֵּדֶר: מְזוֹנוֹת, גֶּפֶן, עֵץ, אֲדָמָה, וּבָאַחֲרוֹנָה ״שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ״.","פֶּרֶק כ״ז, הֲלָכָה א׳","דִּין קְדִימָה בִּבְרָכוֹת"],["מָה הַסִּימָן שֶׁעוֹזֵר לִזְכֹּר אֶת סֵדֶר הַבְּרָכוֹת?",["אֵ״שׁ מַגָּ״ע, וְהַבְּרָכָה הָרִאשׁוֹנָה הִיא שֶׁהַכֹּל","עֵ״ג מָ״שׁ, לְפִי הַבְּרָכָה הַחֲבִיבָה עַל הָאוֹכֵל","מַגָּ״ע אֵ״שׁ, רָאשֵׁי תֵבוֹת שֶׁל חָמֵשׁ הַבְּרָכוֹת","אֵין סִימָן, צָרִיךְ לִזְכֹּר אֶת הַסֵּדֶר בְּעַל פֶּה"],2,"מַגָּ״ע אֵ״שׁ: מְזוֹנוֹת, גֶּפֶן, עֵץ, אֲדָמָה, שֶׁהַכֹּל.","פֶּרֶק כ״ז, הֲלָכָה א׳","דִּין קְדִימָה בִּבְרָכוֹת"],["מִנַּיִן לָמְדוּ שֶׁשִּׁבְעַת הַמִּינִים חֲבִיבִים בְּיוֹתֵר?",["מִפְּנֵי שֶׁהֵם הַפֵּרוֹת הַמְּתוּקִים וְהַטְּעִימִים בְּיוֹתֵר בָּעוֹלָם","מִפְּנֵי שֶׁהֵם גְּדֵלִים בְּכָל אֶרֶץ וְאֶרֶץ בָּעוֹלָם","מִפְּנֵי שֶׁהֵם הַפֵּרוֹת הַיְּקָרִים בְּיוֹתֵר בַּשּׁוּק","מִן הַפָּסוּק שֶׁבּוֹ שִׁבְּחָה הַתּוֹרָה אֶת אֶרֶץ יִשְׂרָאֵל בְּפֵרוֹתֶיהָ"],3,"הַתּוֹרָה שִׁבְּחָה אֶת אֶרֶץ יִשְׂרָאֵל: ״אֶרֶץ חִטָּה וּשְׂעֹרָה וְגֶפֶן וּתְאֵנָה וְרִמּוֹן, אֶרֶץ זֵית שֶׁמֶן וּדְבָשׁ״, וּמִכָּאן שֶׁהֵם חֲבִיבִים בְּיוֹתֵר.","פֶּרֶק כ״ז, הֲלָכָה ב׳","דִּין קְדִימָה בִּבְרָכוֹת"],["לִפְנֵי יוֹסִי תַּפּוּחִים וַעֲנָבִים, וְהַתַּפּוּחִים חֲבִיבִים עָלָיו יוֹתֵר. מָה יַעֲשֶׂה?",["יְבָרֵךְ עַל הָעֲנָבִים וְיִפְטֹר אֶת הַתַּפּוּחִים מִבְּרָכָה","יְבָרֵךְ עַל הַתַּפּוּחִים, כִּי הֵם חֲבִיבִים עָלָיו יוֹתֵר","יְבָרֵךְ שְׁתֵּי בְּרָכוֹת, אַחַת עַל כָּל פְּרִי","יְבָרֵךְ עַל הַפְּרִי הַגָּדוֹל מִבֵּין שְׁנֵי הַפֵּרוֹת"],0,"שְׁנֵיהֶם ״בּוֹרֵא פְּרִי הָעֵץ״, וְהָעֲנָבִים מִשִּׁבְעַת הַמִּינִים - לָכֵן מְבָרְכִים עֲלֵיהֶם וּפוֹטְרִים אֶת הַתַּפּוּחִים.","פֶּרֶק כ״ז, הֲלָכָה ג׳","דִּין קְדִימָה בִּבְרָכוֹת"],["מָה דָּרְשׁוּ חֲכָמִים מִסֵּדֶר הַמִּלִּים בַּפָּסוּק ״אֶרֶץ חִטָּה וּשְׂעֹרָה״?",["כָּל הַפֵּרוֹת שֶׁבַּפָּסוּק שָׁוִים, וְאֵין בֵּינֵיהֶם קְדִימָה","כָּל הָרָחוֹק מִן הַמִּלָּה אֶרֶץ, קוֹדֵם לִבְרָכָה","כָּל הַקָּרוֹב לַמִּלָּה אֶרֶץ בַּפָּסוּק, קוֹדֵם לִבְרָכָה","מְבָרְכִים קֹדֶם עַל הַפְּרִי הָאַחֲרוֹן שֶׁבַּפָּסוּק"],2,"דָּרְשׁוּ חֲכָמִים שֶׁכָּל הַקָּרוֹב לַמִּלָּה ״אֶרֶץ״ קוֹדֵם לִבְרָכָה.","פֶּרֶק כ״ז, הֲלָכָה ד׳","דִּין קְדִימָה בִּבְרָכוֹת"],["לִפְנֵי דָּוִד זֵיתִים, עֲנָבִים וְרִמּוֹנִים. עַל מָה יְבָרֵךְ רִאשׁוֹנָה?",["עַל הָעֲנָבִים, כִּי הַגֶּפֶן הִיא הַחֲשׁוּבָה בַּפָּסוּק","עַל הַזֵּיתִים, כִּי הֵם קְרוֹבִים יוֹתֵר לַמִּלָּה אֶרֶץ","עַל הָרִמּוֹנִים, כִּי הֵם הַפְּרִי הַיָּפֶה מִכֻּלָּם","עַל מָה שֶׁרוֹצִים, כִּי כֻּלָּם מִשִּׁבְעַת הַמִּינִים"],1,"זֵיתִים וּתְמָרִים מוֹפִיעִים מִיָּד אַחֲרֵי ״אֶרֶץ״ הַשְּׁנִיָּה, וְלָכֵן קוֹדְמִים לָעֲנָבִים, לַתְּאֵנִים וְלָרִמּוֹנִים.","פֶּרֶק כ״ז, הֲלָכָה ה׳","דִּין קְדִימָה בִּבְרָכוֹת"],["זֵיתִים קוֹדְמִים לָעֲנָבִים. מַדּוּעַ בְּכָל זֹאת הַיַּיִן קוֹדֵם לַזֵּיתִים וְלַתְּמָרִים?",["כִּי הַיַּיִן נִשְׁתֶּה, וּמַשְׁקֶה תָּמִיד קוֹדֵם לְמַאֲכָל","כִּי הַגֶּפֶן כְּתוּבָה בַּפָּסוּק קָרוֹב יוֹתֵר לְאֶרֶץ","כִּי הַיַּיִן חָבִיב עַל רֹב הָאֲנָשִׁים יוֹתֵר מִכֻּלָּם","כִּי יֵשׁ לוֹ בְּרָכָה מְיֻחֶדֶת וַחֲשׁוּבָה, בּוֹרֵא פְּרִי הַגֶּפֶן"],3,"הַקְּדִימָה שֶׁל זֵיתִים הִיא רַק כְּשֶׁאוֹכְלִים אוֹתָם כְּמוֹת שֶׁהֵם. לַיַּיִן בְּרָכָה מְיֻחֶדֶת, וְהִיא חֲשׁוּבָה מִ״בּוֹרֵא פְּרִי הָעֵץ״.","פֶּרֶק כ״ז, הֲלָכָה ז׳","דִּין קְדִימָה בִּבְרָכוֹת"],["מַדּוּעַ ״בּוֹרֵא מִינֵי מְזוֹנוֹת״ קוֹדֶמֶת לְ״בוֹרֵא פְּרִי הַגֶּפֶן״?",["כִּי שְׁתֵּיהֶן מְיֻחָדוֹת, אֲבָל חִטָּה וּשְׂעֹרָה קְרוֹבוֹת יוֹתֵר לַמִּלָּה אֶרֶץ","כִּי מִינֵי מְזוֹנוֹת מַשְׂבִּיעִים הַרְבֵּה יוֹתֵר מִן הַיַּיִן הָאָדֹם שֶׁבַּכּוֹס","כִּי בְּרָכַת הַגֶּפֶן אֵינָהּ בְּרָכָה מְיֻחֶדֶת, וּמְזוֹנוֹת כֵּן","כִּי תָּמִיד אוֹכְלִים לֶחֶם וְעוּגוֹת לִפְנֵי שֶׁשּׁוֹתִים יַיִן"],0,"גַּם ״מְזוֹנוֹת״ הִיא בְּרָכָה מְיֻחֶדֶת כְּמוֹ בִּרְכַּת הַיַּיִן, אֲבָל הַחִטָּה וְהַשְּׂעֹרָה קְרוֹבוֹת יוֹתֵר לַמִּלָּה ״אֶרֶץ״ בַּפָּסוּק.","פֶּרֶק כ״ז, הֲלָכָה ח׳","דִּין קְדִימָה בִּבְרָכוֹת"],["מָה מַרְוִיחִים כְּשֶׁחוֹשְׁבִים לִפְנֵי הַבְּרָכָה עַל מַשְׁמָעוּתָהּ?",["מְסַיְּמִים אֶת הַבְּרָכָה מַהֵר יוֹתֵר מִכֻּלָּם","יְכוֹלִים לְדַלֵּג עַל חֵלֶק מִמִּלּוֹת הַבְּרָכָה","מוֹדִים לַה׳ וְנִמְנָעִים מִסְּפֵקוֹת וּמִבְּרָכוֹת לְבַטָּלָה","אֵין צֹרֶךְ לְבָרֵךְ אַחַר כָּךְ בְּרָכָה אַחֲרוֹנָה"],2,"בְּדֶרֶךְ זוֹ זוֹכִים לְהוֹדוֹת לַה׳ עַל מָה שֶׁהוּא נוֹתֵן לָנוּ, וְאַף נִמְנָעִים מִמַּצְּבֵי סָפֵק וּמִבְּרָכוֹת לְבַטָּלָה.","פֶּרֶק כ״ח, הֲלָכָה א׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["כֵּיצַד אָסוּר לְבָרֵךְ אֶת הַבְּרָכוֹת?",["בְּקוֹל רָם וּבָרוּר שֶׁכֻּלָּם יוּכְלוּ לִשְׁמֹעַ","כְּשֶׁהַמַּאֲכָל מוּנָח לְפָנֵינוּ עַל הַשֻּׁלְחָן","תּוֹךְ כְּדֵי הֲבָנָה שֶׁל כָּל מִלָּה","כְּמִצְוַת אֲנָשִׁים מְלֻמָּדָה וּמִתּוֹךְ הֶסַּח הַדַּעַת"],3,"אֵין לְבָרֵךְ אֶת הַבְּרָכוֹת כְּמִצְוַת אֲנָשִׁים מְלֻמָּדָה וּמִתּוֹךְ הֶסַּח הַדַּעַת.","פֶּרֶק כ״ח, הֲלָכָה ב׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["מַדּוּעַ מִי שֶׁבֵּרֵךְ ״הָעֵץ״ עַל פְּרִי הָאֲדָמָה לֹא יָצָא, וּבְטָעוּת הַהֲפוּכָה יָצָא?",["כִּי פֵּרוֹת הָאֲדָמָה חֲשׁוּבִים יוֹתֵר, וְלָכֵן צְרִיכִים בְּרָכָה מְיֻחֶדֶת מִשֶּׁלָּהֶם","פֵּרוֹת הָעֵץ צוֹמְחִים מִן הָאֲדָמָה, וּפֵרוֹת הָאֲדָמָה לֹא גָּדְלוּ עַל עֵץ","כִּי מִי שֶׁטּוֹעֶה בְּנֹסַח הַבְּרָכָה אַף פַּעַם אֵינוֹ יוֹצֵא יְדֵי חוֹבָה","כִּי אֵין הֶבְדֵּל, וּבִשְׁנֵי הַמִּקְרִים הַמְּבָרֵךְ יָצָא יְדֵי חוֹבָתוֹ"],1,"גַּם פֵּרוֹת הָעֵץ צוֹמְחִים מִן הָאֲדָמָה, וְלָכֵן ״הָאֲדָמָה״ עַל פְּרִי הָעֵץ מוֹעִילָה. אֲבָל פֵּרוֹת הָאֲדָמָה לֹא גָּדְלוּ עַל עֵץ, וְלָכֵן ״הָעֵץ״ עֲלֵיהֶם לֹא מוֹעִילָה.","פֶּרֶק כ״ח, הֲלָכָה ג׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["מִי שֶׁבֵּרֵךְ בְּטָעוּת ״שֶׁהַכֹּל״ עַל פַּת, מָה דִּינוֹ?",["יָצָא, אֲבָל לְכַתְּחִלָּה צָרִיךְ לְבָרֵךְ אֶת הַבְּרָכָה הַמְּיֻחֶדֶת","לֹא יָצָא, כִּי עַל פַּת אִי אֶפְשָׁר לְבָרֵךְ שֶׁהַכֹּל","יָצָא, וּמֵעַכְשָׁיו מֻתָּר לוֹ לְבָרֵךְ תָּמִיד רַק שֶׁהַכֹּל","יָצָא רַק עַל פֵּרוֹת, אֲבָל עַל פַּת וְיַיִן לֹא"],0,"מִי שֶׁטָּעָה וּבֵרֵךְ ״שֶׁהַכֹּל״ יָצָא, וַאֲפִלּוּ עַל פַּת וְיַיִן. אַךְ לְכַתְּחִלָּה חוֹבָה לְבָרֵךְ עַל כָּל מַאֲכָל וּמַשְׁקֶה אֶת בִּרְכָתוֹ הַמְּיֻחֶדֶת.","פֶּרֶק כ״ח, הֲלָכָה ד׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["יוֹסֵף אֵינוֹ יוֹדֵעַ אִם בִּרְכַּת הַפְּרִי ״הָעֵץ״ אוֹ ״הָאֲדָמָה״, וְאֵין לוֹ אֵיךְ לְבָרֵר. מָה יְבָרֵךְ?",["יְבָרֵךְ ״בּוֹרֵא פְּרִי הָעֵץ״, כִּי זוֹ בְּרָכָה חֲשׁוּבָה יוֹתֵר","לֹא יְבָרֵךְ בִּכְלָל וְיֹאכַל אֶת הַפְּרִי בְּלִי בְּרָכָה","יְבָרֵךְ ״בּוֹרֵא פְּרִי הָאֲדָמָה״, שֶׁמַּתְאִים גַּם לְפֵרוֹת הָעֵץ","יְבָרֵךְ שְׁתֵּי בְּרָכוֹת, גַּם ״הָעֵץ״ וְגַם ״הָאֲדָמָה״"],2,"מִי שֶׁאֵינוֹ יוֹדֵעַ אִם הַבְּרָכָה ״הָעֵץ״ אוֹ ״הָאֲדָמָה״ וְאֵינוֹ יָכוֹל לְבָרֵר, יְבָרֵךְ ״בּוֹרֵא פְּרִי הָאֲדָמָה״, שֶׁהֲרֵי גַּם פֵּרוֹת הָעֵץ צוֹמְחִים מִן הָאֲדָמָה.","פֶּרֶק כ״ח, הֲלָכָה ה׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["מָה רָאוּי לַעֲשׂוֹת כְּדֵי לֹא לְהַגִּיעַ לְסָפֵק אִם לְבָרֵךְ ״שֶׁהַכֹּל״ אוֹ בְּרָכָה אַחֶרֶת?",["תָּמִיד לְבָרֵךְ ״שֶׁהַכֹּל״ עַל כָּל מַאֲכָל, וְכָךְ אֵין סָפֵק","לֶאֱכֹל רַק מַאֲכָלִים שֶׁאֲנַחְנוּ כְּבָר מַכִּירִים אֶת בִּרְכָתָם הֵיטֵב","לְנַחֵשׁ אֶת הַבְּרָכָה לְפִי הַצֶּבַע וְהַצּוּרָה שֶׁל הַמַּאֲכָל","לִלְמֹד מֵרֹאשׁ בְּסִפְרֵי הֲלָכָה אֵיזוֹ בְּרָכָה מְבָרְכִים עַל כָּל מַאֲכָל"],3,"בִּשְׁעַת סָפֵק מְבָרְכִים ״שֶׁהַכֹּל״, אֲבָל צָרִיךְ לִלְמֹד אֵיזוֹ בְּרָכָה מְבָרְכִים עַל כָּל מַאֲכָל וְלֹא לְהַגִּיעַ לְמַצְּבֵי סָפֵק. כַּיּוֹם אֶפְשָׁר לִמְצֹא זֹאת בְּקַלּוּת בְּסִפְרֵי הֲלָכָה וּבְאַתְרֵי אִינְטֶרְנֶט.","פֶּרֶק כ״ח, הֲלָכָה ו׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["אֵיךְ מְבָרְכִים עַל מַאֲכָל אוֹ מַשְׁקֶה כָּרָאוּי וְדֶרֶךְ כָּבוֹד?",["כְּשֶׁהוּא עֲדַיִן בַּמִּטְבָּח, וְאַחַר כָּךְ מְבִיאִים אוֹתוֹ","כְּשֶׁהוּא לְפָנַי, וַאֲנִי אוֹחֵז אוֹתוֹ בְּיַד יָמִין","כְּשֶׁהוּא מֻנָּח בַּצַּד, וְהַיָּדַיִם מֻנָּחוֹת בַּכִּיסִים","כְּשֶׁאֲנִי אוֹחֵז אוֹתוֹ בְּיַד שְׂמֹאל בִּלְבַד"],1,"יֵשׁ לְבָרֵךְ עַל אֹכֶל וְעַל מַשְׁקֶה רַק כַּאֲשֶׁר הֵם לִפְנֵי הַמְּבָרֵךְ, וְלֶאֱחֹז אוֹתָם בְּיַד יָמִין בִּשְׁעַת הַבְּרָכָה דֶּרֶךְ כָּבוֹד.","פֶּרֶק כ״ח, הֲלָכָה ז׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["דָּוִד בֵּרֵךְ עַל תַּפּוּחַ שֶׁבְּיָדוֹ וְהִתְכַּוֵּן לְכָל הַפֵּרוֹת. עַכְשָׁיו רָאָה אֲגָס טוֹב יוֹתֵר. מָה יַעֲשֶׂה?",["יֹאכַל אֶת הַתַּפּוּחַ שֶׁבֵּרֵךְ עָלָיו, וְלֹא יַחֲלִיף אוֹתוֹ","יַנִּיחַ אֶת הַתַּפּוּחַ וְיֹאכַל מִיָּד אֶת הָאֲגָס הַטּוֹב","יַחֲלִיף, כִּי בִּשְׁעַת הַבְּרָכָה הִתְכַּוֵּן לְכָל הַפֵּרוֹת","יְבָרֵךְ שׁוּב עַל הָאֲגָס וְיֹאכַל רַק אוֹתוֹ"],0,"מִי שֶׁהֶחֱזִיק בְּיָדוֹ פְּרִי וּבֵרֵךְ עָלָיו, לֹא יַחֲלִיף אוֹתוֹ בִּפְרִי טוֹב יוֹתֵר, וַאֲפִלּוּ אִם בִּזְמַן הַבְּרָכָה הִתְכַּוֵּן לְכָל הַפֵּרוֹת שֶׁלְּפָנָיו.","פֶּרֶק כ״ח, הֲלָכָה ח׳","מְכַוְּנִים אֶת הַלֵּב בַּבְּרָכָה"],["לָמָּה הַפָּסוּק ״כֹּל הַנְּשָׁמָה תְּהַלֵּל יָ-ה״ מְלַמֵּד עַל בִּרְכַּת הָרֵיחַ?",["כִּי הָרֵיחַ מַשְׂבִּיעַ אֶת הַגּוּף כְּמוֹ אֹכֶל טוֹב","כִּי הַגּוּף נֶהֱנֶה מֵהָרֵיחַ יוֹתֵר מִן הַנְּשָׁמָה","כִּי הַנְּשָׁמָה נֶהֱנֵית מֵהָרֵיחַ, וְהַגּוּף אֵינוֹ נֶהֱנֶה מִמֶּנּוּ","כִּי בְּכָל נְשִׁימָה צָרִיךְ לְבָרֵךְ בְּרָכָה חֲדָשָׁה"],2,"הָרֵיחַ הוּא הַדָּבָר שֶׁהַנְּשָׁמָה נֶהֱנֵית מִמֶּנּוּ וְהַגּוּף אֵינוֹ נֶהֱנֶה, וְלָכֵן הַפָּסוּק אוֹמֵר שֶׁהַנְּשָׁמָה תְּהַלֵּל – עַל הָרֵיחַ.","פֶּרֶק כ״ט, הֲלָכָה א׳","בִּרְכַּת הָרֵיחַ"],["לָמָּה אֵין מְבָרְכִים בְּרָכָה אַחֲרוֹנָה עַל הָרֵיחַ?",["כִּי הָרֵיחַ אֵינוֹ חָשׁוּב כְּמוֹ אֹכֶל","כִּי מְבָרְכִים עַל הָרֵיחַ רַק בְּשַׁבָּת","כִּי אִי אֶפְשָׁר לָדַעַת כַּמָּה הֵרַחְנוּ","כִּי הַתַּעֲנוּג נִגְמָר מִיָּד כְּשֶׁמַּפְסִיקִים לְהָרִיחַ"],3,"מִיָּד אַחֲרֵי שֶׁמַּפְסִיקִים לְהָרִיחַ הַתַּעֲנוּג נִגְמָר, וְאִלּוּ אַחֲרֵי אֲכִילָה וּשְׁתִיָּה הַגּוּף מַמְשִׁיךְ לֵהָנוֹת מִן הַשֹּׂבַע וְהָרְוָיָה.","פֶּרֶק כ״ט, הֲלָכָה ב׳","בִּרְכַּת הָרֵיחַ"],["דָּנִי קִבֵּל בַּקְבּוּק בֹּשֶׂם רָגִיל מֵהַחֲנוּת, וְאֵין יָדוּעַ מִמָּה הוּא עָשׂוּי. הַאִם יְבָרֵךְ עָלָיו?",["לֹא, כִּי רֹב הַבְּשָׂמִים בַּשּׁוּק עֲשׂוּיִים מֵחֳמָרִים סִינְתֶּטִיִּים","כֵּן, וִיבָרֵךְ בּוֹרֵא מִינֵי בְשָׂמִים עַל כָּל בֹּשֶׂם","כֵּן, וִיבָרֵךְ בּוֹרֵא עֲצֵי בְשָׂמִים תָּמִיד","לֹא, כִּי עַל רֵיחַ אֵין מְבָרְכִים בִּכְלָל"],0,"רֹב הַבְּשָׂמִים הַנִּמְכָּרִים בַּשּׁוּק עֲשׂוּיִים מֵחֳמָרִים סִינְתֶּטִיִּים, וְלָכֵן אֵין מְבָרְכִים עֲלֵיהֶם – אֶלָּא אִם כֵּן יָדוּעַ שֶׁהֵם עֲשׂוּיִים מִתַּמְצִית אֲמִיתִּית שֶׁל צְמָחִים.","פֶּרֶק כ״ט, הֲלָכָה י״ג","בִּרְכַּת הָרֵיחַ"],["עַל צֶמַח שֶׁיֵּשׁ לוֹ גִּבְעוֹל רַךְ שֶׁנִּשְׁאָר מִשָּׁנָה לְשָׁנָה – מָה מְבָרְכִים?",["בּוֹרֵא עֲצֵי בְשָׂמִים, כִּי הַגִּבְעוֹל נִשְׁאָר כָּל הַשָּׁנִים","בּוֹרֵא מִינֵי בְשָׂמִים, כִּי יֵשׁ סָפֵק אִם הוּא עֵץ אוֹ עֵשֶׂב","בּוֹרֵא עִשְׂבֵי בְשָׂמִים, כִּי הַגִּבְעוֹל שֶׁלּוֹ רַךְ וְלֹא קָשֶׁה","אֵין מְבָרְכִים עָלָיו כְּלָל, כִּי אֵינוֹ עֵץ וְאֵינוֹ עֵשֶׂב"],1,"בְּצֶמַח כָּזֶה יֵשׁ סָפֵק אִם הוּא נֶחְשָׁב לְעֵץ אוֹ לְעֵשֶׂב, וְלָכֵן מְבָרְכִים עָלָיו ״בּוֹרֵא מִינֵי בְשָׂמִים״.","פֶּרֶק כ״ט, הֲלָכָה ו׳","בִּרְכַּת הָרֵיחַ"],["יוֹסִי הֵרִיחַ הֲדַס וּבֵרֵךְ בְּטָעוּת ״בּוֹרֵא עִשְׂבֵי בְשָׂמִים״. מָה הַדִּין?",["יָצָא יְדֵי חוֹבָתוֹ, כִּי גַּם הַהֲדַס הוּא צֶמַח רֵיחָנִי וְטוֹב","יָצָא, כִּי כָּל בִּרְכוֹת הָרֵיחַ שָׁווֹת לְגַמְרֵי זוֹ לָזוֹ","לֹא יָצָא יְדֵי חוֹבָתוֹ, כִּי הַהֲדַס הוּא עֵץ וְלֹא עֵשֶׂב","לֹא יָצָא, וְאָסוּר לוֹ לְהָרִיחַ אֶת הַהֲדַס כָּל הַיּוֹם"],2,"מִי שֶׁבֵּרֵךְ ״עִשְׂבֵי בְשָׂמִים״ עַל דָּבָר שֶׁבִּרְכָתוֹ ״עֲצֵי בְשָׂמִים״ (אוֹ לְהֶפֶךְ) – לֹא יָצָא יְדֵי חוֹבָתוֹ.","פֶּרֶק כ״ט, הֲלָכָה ז׳","בִּרְכַּת הָרֵיחַ"],["אָבִי הֵרִיחַ רוֹזְמָרִין וּבֵרֵךְ בְּטָעוּת ״בּוֹרֵא מִינֵי בְשָׂמִים״. מָה הַדִּין?",["לֹא יָצָא, וְעָלָיו לְבָרֵךְ שׁוּב בּוֹרֵא עֲצֵי בְשָׂמִים","לֹא יָצָא, כִּי רוֹזְמָרִין הוּא עֵשֶׂב וְלֹא עֵץ","יָצָא רַק אִם הוּא הֵרִיחַ אֶת הָרוֹזְמָרִין פַּעַם שְׁנִיָּה","יָצָא, כִּי גַּם עֲצֵי בְשָׂמִים הֵם מִינֵי בְשָׂמִים"],3,"מִי שֶׁבֵּרֵךְ ״מִינֵי בְשָׂמִים״ עַל דָּבָר שֶׁבִּרְכָתוֹ ״עֲצֵי בְשָׂמִים״ אוֹ ״עִשְׂבֵי בְשָׂמִים״ – יָצָא, שֶׁהֲרֵי גַּם הֵם ׳מִינֵי׳ בְשָׂמִים.","פֶּרֶק כ״ט, הֲלָכָה ח׳","בִּרְכַּת הָרֵיחַ"],["מָצָאנוּ צֶמַח רֵיחָנִי, וְאֵין לָנוּ דֶּרֶךְ לְבָרֵר אִם הוּא עֵץ אוֹ עֵשֶׂב. מָה נְבָרֵךְ?",["בּוֹרֵא עִשְׂבֵי בְשָׂמִים, כִּי הוּא גָּדֵל מִן הָאֲדָמָה","בּוֹרֵא מִינֵי בְשָׂמִים, כִּי זוֹ הַבְּרָכָה כְּשֶׁיֵּשׁ סָפֵק","בּוֹרֵא עֲצֵי בְשָׂמִים, כִּי רֹב הַצְּמָחִים הֵם עֵצִים","לֹא נְבָרֵךְ כְּלָל עַד שֶׁנִּשְׁאַל אֶת כָּל הַשְּׁכֵנִים"],1,"כַּאֲשֶׁר יֵשׁ סָפֵק לְגַבֵּי הַבְּרָכָה וְאִי אֶפְשָׁר לְבָרֵר – מְבָרְכִים ״בּוֹרֵא מִינֵי בְשָׂמִים״.","פֶּרֶק כ״ט, הֲלָכָה ט׳","בִּרְכַּת הָרֵיחַ"],["מָתַי צֶמַח רֵיחָנִי נֶחְשָׁב לְעֵץ, וּמְבָרְכִים עָלָיו ״בּוֹרֵא עֲצֵי בְשָׂמִים״?",["כְּשֶׁהֶעָלִים שֶׁלּוֹ יוֹצְאִים יְשִׁירוֹת מִן הַשָּׁרָשִׁים בְּכָל שָׁנָה וְשָׁנָה","כְּשֶׁהוּא גָּבוֹהַּ יוֹתֵר מִמֶּטֶר, גַּם אִם הוּא גָּדֵל רַק שָׁנָה אַחַת","כְּשֶׁיֵּשׁ לוֹ גֶּזַע קָשֶׁה שֶׁנִּשְׁאָר מִשָּׁנָה לְשָׁנָה, וְהֶעָלִים יוֹצְאִים מִמֶּנּוּ","כְּשֶׁיֵּשׁ לוֹ גִּבְעוֹל רַךְ שֶׁיּוֹצֵא מֵחָדָשׁ מִן הַשֹּׁרֶשׁ כָּל שָׁנָה"],2,"צֶמַח שֶׁיֵּשׁ לוֹ גֶּזַע קָשֶׁה שֶׁנִּשְׁאָר מִשָּׁנָה לְשָׁנָה, וְהֶעָלִים יוֹצְאִים מִן הַגֶּזַע אוֹ מִן הָעֲנָפִים וְלֹא יְשִׁירוֹת מִן הַשָּׁרָשִׁים – נֶחְשָׁב לְעֵץ. לְמָשָׁל: הֲדַס, רוֹזְמָרִין, שִׁיבָה, יַעְרָה, קִנָּמוֹן וְלוּאִיזָה.","פֶּרֶק כ״ט, הֲלָכָה ד׳","בִּרְכַּת הָרֵיחַ"],["עַל רֵיחַ טוֹב שֶׁאֵינוֹ בָּא מֵעֵץ, מֵעֵשֶׂב אוֹ מִפְּרִי – מָה מְבָרְכִים?",["הַנּוֹתֵן רֵיחַ טוֹב בַּפֵּרוֹת, כִּי זוֹ בְּרָכָה כְּלָלִית","בּוֹרֵא עֲצֵי בְשָׂמִים, כִּי כָּל רֵיחַ בָּא מִן הָעֵץ","אֵין מְבָרְכִים עַל רֵיחַ כָּזֶה בְּשׁוּם אֹפֶן","בּוֹרֵא מִינֵי בְשָׂמִים, הַבְּרָכָה עַל שְׁאָר הַדְּבָרִים"],3,"חֲכָמִים תִּקְּנוּ בְּרָכָה לְכָל סוּג רֵיחַ: עֵץ – ״עֲצֵי בְשָׂמִים״, עֵשֶׂב – ״עִשְׂבֵי בְשָׂמִים״, פְּרִי – ״הַנּוֹתֵן רֵיחַ טוֹב בַּפֵּרוֹת״, וְעַל שְׁאָר הַדְּבָרִים – ״בּוֹרֵא מִינֵי בְשָׂמִים״.","פֶּרֶק כ״ט, הֲלָכָה ג׳","בִּרְכַּת הָרֵיחַ"],["עַל מָה נִתְקְנָה בִּרְכַּת ״שֶׁהֶחֱיָנוּ״?",["עַל הַצַּעַר שֶׁל אָדָם שֶׁהִפְסִיד כֶּסֶף רַב","עַל כָּל דָּבָר שֶׁאָדָם רוֹאֶה בְּכָל יוֹם וָיוֹם","עַל שִׂמְחַת הַלֵּב, שֶׁהִיא חֵלֶק חָשׁוּב בַּעֲבוֹדַת ה׳","רַק עַל אֲכִילַת לֶחֶם בִּסְעוּדַת שַׁבָּת קֹדֶשׁ"],2,"בִּרְכַּת ״שֶׁהֶחֱיָנוּ״ נִתְקְנָה עַל שִׂמְחַת הַלֵּב, שֶׁהִיא חֵלֶק חָשׁוּב בַּעֲבוֹדַת ה׳.","פֶּרֶק ל׳, הֲלָכָה א׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["מָה עָשָׂה רַבִּי אֶלְעָזָר כְּדֵי לְבָרֵךְ ״שֶׁהֶחֱיָנוּ״?",["קָנָה בְּכָל שָׁבוּעַ בֶּגֶד חָדָשׁ וְיָקָר מְאוֹד","חָסַךְ פְּרוּטָה לִפְרוּטָה כְּדֵי לִקְנוֹת פֵּרוֹת חֲדָשִׁים","נָסַע לְכָל מָקוֹם שֶׁנַּעֲשָׂה בּוֹ נֵס","הִמְתִּין שָׁנָה שְׁלֵמָה בְּלִי לֶאֱכֹל פֵּרוֹת"],1,"רַבִּי אֶלְעָזָר הָיָה חוֹסֵךְ פְּרוּטָה לִפְרוּטָה כְּדֵי לִקְנוֹת פֵּרוֹת חֲדָשִׁים וּלְבָרֵךְ עֲלֵיהֶם ״שֶׁהֶחֱיָנוּ״ (יְרוּשַׁלְמִי, סוֹף קִדּוּשִׁין).","פֶּרֶק ל׳, הֲלָכָה א׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["לָמָּה הִתְקִינוּ רַבּוֹתֵינוּ לְבָרֵךְ עַל הַנִּסִּים?",["כְּדֵי שֶׁנִּזְכֹּר אֶת כָּל הַמְּקוֹמוֹת בָּעוֹלָם","כְּדֵי שֶׁיִּהְיֶה לָנוּ מָה לוֹמַר בַּטִּיּוּל","כְּדֵי לְהַרְאוֹת לַחֲבֵרִים שֶׁאָנוּ חֲכָמִים מְאוֹד","כְּדֵי לְחַזֵּק בְּלִבֵּנוּ שֶׁה׳ מַשְׁגִּיחַ עַל בְּרוּאָיו"],3,"מְבָרְכִים עַל הַנִּסִּים כְּדֵי לְחַזֵּק בְּלִבֵּנוּ שֶׁה׳ מַשְׁגִּיחַ עַל בְּרוּאָיו, וּגְנַאי הוּא לְמִי שֶׁנַּעֲשָׂה לוֹ נֵס וְאֵינוֹ מְשַׁבֵּחַ אֶת בּוֹרְאוֹ.","פֶּרֶק ל״א, הֲלָכָה ב׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["אֵיךְ מְבָרְכִים עַל נֵס שֶׁיּוֹצֵא מִגִּדְרֵי הַטֶּבַע?",["מְבָרְכִים בְּשֵׁם וּמַלְכוּת: ״שֶׁעָשָׂה לִי נֵס בַּמָּקוֹם הַזֶּה״","לֹא מְבָרְכִים כְּלָל, כִּי זֶה רַק מִקְרֶה","מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ בְּכָל פַּעַם שֶׁנִּזְכָּרִים בַּנֵּס","מְבָרְכִים בְּלִי שֵׁם וּמַלְכוּת, וְרַק בְּלַחַשׁ שָׁקֵט מְאוֹד"],0,"עַל נֵס שֶׁיּוֹצֵא מִגִּדְרֵי הַטֶּבַע מְבָרְכִים בְּשֵׁם וּמַלְכוּת: ״בָּרוּךְ אַתָּה ה׳ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁעָשָׂה לִי נֵס בַּמָּקוֹם הַזֶּה״.","פֶּרֶק ל״א, הֲלָכָה ה׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["נֵס שֶׁאֵינוֹ יוֹצֵא מִגִּדְרֵי הַטֶּבַע – מָה הַדִּין לְמַעֲשֶׂה?",["מְבָרְכִים בְּשֵׁם וּמַלְכוּת, כְּמוֹ עַל כָּל נֵס גָּדוֹל","אָסוּר לְהַזְכִּיר אֶת הַנֵּס בִּכְלָל, אֲפִלּוּ בְּשִׂיחָה","מְבָרְכִים בְּלִי שֵׁם וּמַלְכוּת, כִּי סְפֵק בְּרָכוֹת לְהָקֵל","מְבָרְכִים רַק אִם הָיוּ שָׁם עֲשָׂרָה אֲנָשִׁים"],2,"יֵשׁ אוֹמְרִים שֶׁצָּרִיךְ לְבָרֵךְ וְיֵשׁ אוֹמְרִים שֶׁאֵין לְבָרֵךְ, וּמִפְּנֵי שֶׁסְּפֵק בְּרָכוֹת לְהָקֵל – מְבָרְכִים ״בָּרוּךְ שֶׁעָשָׂה לִי נֵס בַּמָּקוֹם הַזֶּה״ בְּלִי שֵׁם וּמַלְכוּת.","פֶּרֶק ל״א, הֲלָכָה ו׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["דָּנִי נוֹלַד לִפְנֵי שֶׁנַּעֲשָׂה נֵס לְאַבָּא שֶׁלּוֹ. הַאִם גַּם הוּא מְבָרֵךְ?",["לֹא, רַק יְלָדִים שֶׁנּוֹלְדוּ אַחֲרֵי הַנֵּס מְבָרְכִים","כֵּן, גַּם יְלָדִים שֶׁנּוֹלְדוּ לִפְנֵי הַנֵּס חַיָּבִים לְבָרֵךְ","לֹא, רַק מִי שֶׁהָיָה בְּעַצְמוֹ בַּמָּקוֹם מְבָרֵךְ","כֵּן, אֲבָל רַק אִם אַבָּא שֶׁלּוֹ נִמְצָא אִתּוֹ שָׁם"],1,"גַּם צֶאֱצָאָיו שֶׁל מִי שֶׁנַּעֲשָׂה לוֹ נֵס מְבָרְכִים: ״בָּרוּךְ שֶׁעָשָׂה נֵס לְאָבִי בַּמָּקוֹם הַזֶּה״, וְגַם הַיְּלָדִים שֶׁנּוֹלְדוּ לִפְנֵי הַנֵּס.","פֶּרֶק ל״א, הֲלָכָה ז׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["הַאִם הוֹרִים מְבָרְכִים עַל נֵס שֶׁנַּעֲשָׂה לִילָדֵיהֶם?",["כֵּן, הוֹרִים מְבָרְכִים תָּמִיד עַל כָּל נֵס שֶׁל יַלְדֵיהֶם","כֵּן, אֲבָל רַק אִם הַיֶּלֶד עֲדַיִן קָטָן","לֹא, אֲבָל אֶחָיו וְאַחְיוֹתָיו שֶׁל הַיֶּלֶד מְבָרְכִים","לֹא, רַק צֶאֱצָאָיו שֶׁל מִי שֶׁנַּעֲשָׂה לוֹ נֵס מְבָרְכִים"],3,"רַק צֶאֱצָאָיו שֶׁל מִי שֶׁנַּעֲשָׂה לוֹ נֵס מְבָרְכִים. שְׁאָר הַקְּרוֹבִים לֹא יְבָרְכוּ: לֹא בַּעַל עַל אִשְׁתּוֹ וּלְהֵפֶךְ, וְלֹא הוֹרִים עַל יַלְדֵיהֶם.","פֶּרֶק ל״א, הֲלָכָה ח׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["יוֹסִי רָאָה אֶת מְקוֹם הַנֵּס שֶׁלּוֹ וּבֵרַךְ. מָתַי יְבָרֵךְ שׁוּב בַּמָּקוֹם?",["כְּשֶׁעָבְרוּ שְׁלוֹשִׁים יוֹם, וִימֵי הָרְאִיָּה אֵינָם נִסְפָּרִים","בְּכָל פַּעַם שֶׁהוּא עוֹבֵר שָׁם, אֲפִלּוּ בְּאוֹתוֹ יוֹם","רַק אַחֲרֵי שֶׁעָבְרָה שָׁנָה שְׁלֵמָה מִן הָרְאִיָּה","לְעוֹלָם לֹא, מְבָרְכִים רַק פַּעַם אַחַת בַּחַיִּים"],0,"מְבָרְכִים ״שֶׁעָשָׂה לִי נֵס״ רַק אִם עָבְרוּ שְׁלוֹשִׁים יוֹם בֵּין רְאִיָּה לִרְאִיָּה, וִימֵי הָרְאִיָּה אֵינָם חֵלֶק מִסְּפִירַת שְׁלוֹשִׁים הַיָּמִים.","פֶּרֶק ל״א, הֲלָכָה ט׳","שֶׁהֶחֱיָנוּ וּבִרְכוֹת הַנִּסִּים"],["מִי שֶׁאֵינוֹ מַקְפִּיד עַל כְּלָלֵי הַזְּהִירוּת בַּנְּסִיעָה, עַל מָה הוּא עוֹבֵר?",["עוֹבֵר רַק עַל מִנְהָג טוֹב שֶׁל זְהִירוּת","אֵינוֹ עוֹבֵר עַל שׁוּם דָּבָר, זוֹ בְּחִירָה שֶׁלּוֹ","עוֹבֵר עַל אִסּוּר וְלֹא תָשִׂים דָּמִים בְּבֵיתֶךָ","עוֹבֵר רַק אִם קָרְתָה תְּאוּנָה בַּדֶּרֶךְ"],2,"הַחוֹבָה לִשְׁמֹר עַל הַנֶּפֶשׁ הִיא מִן הַתּוֹרָה, וּמִי שֶׁאֵינוֹ מַקְפִּיד עוֹבֵר עַל ״וְלֹא תָשִׂים דָּמִים בְּבֵיתֶךָ״.","פֶּרֶק ל״ב, הֲלָכָה א׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["רָאִיתָ נַהָג שֶׁנּוֹהֵג בְּצוּרָה מְסֻכֶּנֶת. מָה הַדִּין?",["מִצְוַת עֲשֵׂה לְהוֹכִיחַ אוֹתוֹ בְּדַרְכֵי נֹעַם וּבְלִי לְבַיֵּשׁ","אָסוּר לְהַגִּיד לוֹ דָּבָר, כִּי זֶה לֹא עִנְיָנֵנוּ","צָרִיךְ לְהוֹכִיחַ אוֹתוֹ בְּקוֹל רָם לִפְנֵי כָּל הָאֲנָשִׁים","מֻתָּר לְהוֹכִיחַ רַק אִם הוּא חָבֵר קָרוֹב שֶׁלָּנוּ"],0,"נֶאֱמַר ״הוֹכֵחַ תּוֹכִיחַ אֶת עֲמִיתֶךָ״, אַךְ עוֹשִׂים זֹאת בְּדַרְכֵי נֹעַם וּבְלִי לְבַיֵּשׁ.","פֶּרֶק ל״ב, הֲלָכָה ב׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["לְפִי רֹב קְהִלּוֹת הַסְּפָרַדִּים, מָתַי מְבָרְכִים תְּפִלַּת הַדֶּרֶךְ עִם שֵׁם ה׳?",["בְּכָל נְסִיעָה שֶׁיּוֹצֵאת מִן הָעִיר, גַּם קְצָרָה מְאֹד","כְּשֶׁנּוֹסְעִים בְּסַךְ הַכֹּל יוֹתֵר מִשִּׁבְעִים וּשְׁתַּיִם דַּקּוֹת","רַק בִּנְסִיעָה שֶׁאוֹרֶכֶת יוֹתֵר מֵעֶשֶׂר שָׁעוֹת רְצוּפוֹת","רַק כְּשֶׁנּוֹסְעִים בַּלַּיְלָה, וְלֹא בִּשְׁעוֹת הַיּוֹם"],1,"בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים מְבָרְכִים עִם שֵׁם ה׳ רַק עַל נְסִיעָה (אוֹ כַּמָּה נְסִיעוֹת בַּיּוֹם) שֶׁל יוֹתֵר מִשִּׁבְעִים וּשְׁתַּיִם דַּקּוֹת, וְעַל קְצָרָה מִזּוֹ בְּלִי שֵׁם ה׳.","פֶּרֶק ל״ב, הֲלָכָה ד׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["יוֹסִי נוֹסֵעַ בְּאוֹתוֹ יוֹם שָׁלֹשׁ נְסִיעוֹת. מָתַי יְבָרֵךְ?",["יְבָרֵךְ מֵחָדָשׁ בְּכָל אַחַת מִשָּׁלֹשׁ הַנְּסִיעוֹת","יְבָרֵךְ רַק בַּנְּסִיעָה הָאַחֲרוֹנָה, כְּשֶׁחוֹזֵר הַבַּיְתָה בָּעֶרֶב","יְבָרֵךְ רַק בַּנְּסִיעָה הָאֲרֻכָּה בְּיוֹתֵר מִבֵּין כֻּלָּן","יְבָרֵךְ פַּעַם אַחַת בִּלְבַד, בַּנְּסִיעָה הָרִאשׁוֹנָה שֶׁל הַיּוֹם"],3,"כַּאֲשֶׁר נוֹסְעִים כַּמָּה פְּעָמִים בְּיוֹם אֶחָד, מְבָרְכִים רַק בַּנְּסִיעָה הָרִאשׁוֹנָה.","פֶּרֶק ל״ב, הֲלָכָה ו׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["דָּנִי שָׁכַח לוֹמַר תְּפִלַּת הַדֶּרֶךְ כְּשֶׁיָּצְאוּ מֵהָעִיר. מָה יַעֲשֶׂה?",["כְּבָר אִי אֶפְשָׁר לוֹמַר, כִּי עָבַר הַזְּמַן","יֹאמַר אוֹתָהּ רַק כְּשֶׁיַּגִּיעַ לַמָּקוֹם שֶׁאֵלָיו נָסַע","יֹאמַר מִיָּד כְּשֶׁיִּזָּכֵר, אִם נִשְׁאֲרָה עוֹד דֶּרֶךְ מַסְפֶּקֶת","יַחֲזֹר אֶל הָעִיר וְיֵצֵא מִמֶּנָּה שׁוּב כְּדֵי לְבָרֵךְ"],2,"מִי שֶׁשָּׁכַח אוֹמֵר מִיָּד כְּשֶׁנִּזְכַּר, בִּתְנַאי שֶׁנִּשְׁאֲרָה לְפָנָיו עוֹד דֶּרֶךְ בָּאֹרֶךְ שֶׁאוֹמְרִים עָלָיו תְּפִלַּת הַדֶּרֶךְ.","פֶּרֶק ל״ב, הֲלָכָה ה׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["בְּאֵיזוֹ חֲתִימָה מְסַיְּמִים אֶת תְּפִלַּת הַדֶּרֶךְ?",["בָּרוּךְ אַתָּה ה׳, עוֹשֵׂה שָׁלוֹם","בָּרוּךְ אַתָּה ה׳, הַמּוֹלִיךְ לְשָׁלוֹם","בָּרוּךְ אַתָּה ה׳, שׁוֹמֵר הַדְּרָכִים","בָּרוּךְ אַתָּה ה׳, שׁוֹמֵעַ תְּפִלָּה"],3,"הַתְּפִלָּה מִסְתַּיֶּמֶת ״כִּי אֵל שׁוֹמֵעַ תְּפִלָּה וְתַחֲנוּן אָתָּה, בָּרוּךְ אַתָּה ה׳, שׁוֹמֵעַ תְּפִלָּה״.","פֶּרֶק ל״ב, הֲלָכָה ג׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["בָּאוֹטוֹבּוּס אֶחָד מְבָרֵךְ כְּדֵי לְהוֹצִיא אֶת כֻּלָּם. מָה צְרִיכִים הַשּׁוֹמְעִים?",["אֵין צֹרֶךְ לִשְׁמֹעַ, מַסְפִּיק שֶׁהוּא מְבָרֵךְ בָּאוֹטוֹבּוּס","לִשְׁמֹעַ אֶת קוֹלוֹ, וּבְרַמְקוֹל עָדִיף לוֹמַר מִלָּה בְּמִלָּה","כָּל אֶחָד חַיָּב לְבָרֵךְ לְבַד בְּקוֹל רָם","רַק מִי שֶׁיּוֹשֵׁב לְיַד הַנַּהָג יוֹצֵא יְדֵי חוֹבָה"],1,"הַשּׁוֹמְעִים צְרִיכִים לִשְׁמֹעַ אֶת קוֹל הַמְּבָרֵךְ, וּמִי שֶׁשּׁוֹמֵעַ רַק בְּרַמְקוֹל עָדִיף שֶׁיֹּאמַר אִתּוֹ מִלָּה בְּמִלָּה.","פֶּרֶק ל״ב, הֲלָכָה ז׳","תְּפִלַּת הַדֶּרֶךְ וּזְהִירוּת בַּדְּרָכִים"],["בְּאֵיזוֹ מִלָּה נִרְמָזִים אַרְבָּעָה הַצְּרִיכִים לְהוֹדוֹת?",["בַּמִּלָּה תּוֹדָה: תְּפִלָּה, וִדּוּי, דֶּרֶךְ, הַצָּלָה","בַּמִּלָּה שָׁלוֹם: שְׁמִירָה, לֵב, וְהַצָּלָה, מַיִם","בַּמִּלָּה חַיִּים: חָבוּשׁ, יִסּוּרִים, יָם, מִדְבָּר","בַּמִּלָּה בְּרָכָה: בַּיִת, רְפוּאָה, כְּבִישׁ, הֲלִיכָה"],2,"״וְכָל הַחַיִּים יוֹדוּךָ סֶלָה״ — חַיִּים רָאשֵׁי תֵּבוֹת: חָבוּשׁ, יִסּוּרִים (חוֹלֶה), יָם, מִדְבָּר.","פֶּרֶק ל״ג, הֲלָכָה א׳","בִּרְכַּת הַגּוֹמֵל"],["מָה נוֹהֲגִים בִּקְהִלּוֹת הַסְּפָרַדִּים לוֹמַר לִפְנֵי בִּרְכַּת הַגּוֹמֵל?",["הוֹדוּ לַה׳ כִּי טוֹב כִּי לְעוֹלָם חַסְדּוֹ","שִׁיר הַמַּעֲלוֹת אֶשָּׂא עֵינַי אֶל הֶהָרִים","מִזְמוֹר לְתוֹדָה הָרִיעוּ לַה׳ כָּל הָאָרֶץ","אוֹדֶה ה׳ בְּכָל לֵבָב בְּסוֹד יְשָׁרִים וְעֵדָה"],3,"בִּקְהִלּוֹת הַסְּפָרַדִּים אוֹמְרִים לִפְנֵי הַבְּרָכָה: ״אוֹדֶה ה׳ בְּכָל לֵבָב בְּסוֹד יְשָׁרִים וְעֵדָה״ (תְּהִלִּים קי״א, א׳).","פֶּרֶק ל״ג, הֲלָכָה ג׳","בִּרְכַּת הַגּוֹמֵל"],["לָמָּה מְבָרְכִים הַגּוֹמֵל גַּם כְּשֶׁלֹּא הָיְתָה סַכָּנָה מַמָּשִׁית?",["כִּי כָּל נְסִיעָה הִיא סַכָּנָה מַמָּשִׁית וּגְדוֹלָה","כִּי נִכְנַס לְמַצָּב שֶׁבּוֹ עָלוּל לְהַגִּיעַ לְסַכָּנָה","כִּי הַבְּרָכָה נֶאֱמֶרֶת רַק עַל דְּבָרִים שְׂמֵחִים","כִּי חֲכָמִים רָצוּ שֶׁנְּבָרֵךְ פַּעַם בְּכָל יוֹם"],1,"חֲכָמִים תִּקְּנוּ אֶת הַבְּרָכָה לְכָל מִי שֶׁנִּכְנַס לְמַצָּב שֶׁבּוֹ הוּא עָלוּל לְהַגִּיעַ לְסַכָּנָה.","פֶּרֶק ל״ג, הֲלָכָה ד׳","בִּרְכַּת הַגּוֹמֵל"],["לְפִי מִנְהַג הָאַשְׁכְּנַזִּים, אֵילוּ הוֹלְכִים בַּדֶּרֶךְ מְבָרְכִים הַגּוֹמֵל?",["כָּל מִי שֶׁנּוֹסֵעַ מֵעִיר לְעִיר בְּכָל דֶּרֶךְ","רַק מִי שֶׁנּוֹסֵעַ בִּכְבִישׁ שֶׁיֵּשׁ בּוֹ תְּנוּעָה","רַק הַהוֹלְכִים בַּמִּדְבָּר, שֶׁדְּרָכָיו מְסֻכָּנוֹת בִּמְיֻחָד","אַף אֶחָד, כִּי לֹא מְבָרְכִים עַל דְּרָכִים"],2,"לְמִנְהַג הָאַשְׁכְּנַזִּים דַּוְקָא הַהוֹלְכִים בַּמִּדְבָּר, הַמְּסֻכָּן מִפְּנֵי חַיּוֹת רָעוֹת וְלִסְטִים, מְבָרְכִים.","פֶּרֶק ל״ג, הֲלָכָה ה׳","בִּרְכַּת הַגּוֹמֵל"],["כַּמָּה זְמַן צְרִיכָה לְהִמָּשֵׁךְ נְסִיעָה בְּרֶכֶב כְּדֵי לְבָרֵךְ?",["לְפָחוֹת עֶשֶׂר דַּקּוֹת, כִּזְמַן הֲלִיכַת מִיל","לְפָחוֹת שָׁלוֹשׁ שָׁעוֹת שְׁלֵמוֹת שֶׁל נְסִיעָה","אֵין שִׁעוּר, מְבָרְכִים עַל כָּל נְסִיעָה","לְפָחוֹת שִׁבְעִים וּשְׁתַּיִם דַּקּוֹת, כִּזְמַן הֲלִיכַת פַּרְסָה"],3,"מְבָרְכִים רַק אִם הַנְּסִיעָה נִמְשְׁכָה כִּזְמַן הֲלִיכַת פַּרְסָה — שִׁבְעִים וּשְׁתַּיִם דַּקּוֹת לְפָחוֹת.","פֶּרֶק ל״ג, הֲלָכָה ו׳","בִּרְכַּת הַגּוֹמֵל"],["הַנּוֹהֲגִים לְבָרֵךְ בִּנְסִיעָה מֵעִיר לְעִיר — מָתַי יְבָרְכוּ?",["מִיָּד כְּשֶׁמַּגִּיעִים לָעִיר הָאַחֶרֶת, לִפְנֵי כָּל דָּבָר","רַק כְּשֶׁחוֹזְרִים הַבַּיְתָה, וְלֹא כְּשֶׁמַּגִּיעִים לָעִיר הָאַחֶרֶת","לִפְנֵי שֶׁיּוֹצְאִים מֵהַבַּיִת, כְּדֵי לְהִשָּׁמֵר בַּדֶּרֶךְ","בְּכָל עִיר שֶׁעוֹבְרִים בָּהּ בְּאֶמְצַע הַדֶּרֶךְ"],1,"לֹא יְבָרְכוּ בְּהַגִּיעָם לָעִיר הָאַחֶרֶת אֶלָּא בַּחֲזָרָתָם לְבֵיתָם; וְאִם מִתְעַכְּבִים שָׁם כַּמָּה יָמִים — רַשָּׁאִים לְבָרֵךְ גַּם שָׁם.","פֶּרֶק ל״ג, הֲלָכָה ז׳","בִּרְכַּת הַגּוֹמֵל"],["אֳנִיָּה עוֹגֶנֶת בִּנְמַלִּים בַּדֶּרֶךְ. מָתַי מְבָרֵךְ הַנּוֹסֵעַ?",["בְּכָל נָמָל שֶׁהָאֳנִיָּה עוֹגֶנֶת בּוֹ בַּדֶּרֶךְ","רַק אִם הָיְתָה סְעָרָה גְּדוֹלָה בַּיָּם","רַק כְּשֶׁיַּגִּיעַ לִמְחוֹז חֶפְצוֹ, בְּסוֹף הַהַפְלָגָה","לִפְנֵי שֶׁהָאֳנִיָּה יוֹצֵאת מֵהַנָּמָל הָרִאשׁוֹן"],2,"גַּם אִם הָאֳנִיָּה עוֹגֶנֶת יוֹם אוֹ יוֹמַיִם בִּנְמַלִּים, מְבָרְכִים רַק כְּשֶׁמַּגִּיעִים לִמְחוֹז הַחֵפֶץ.","פֶּרֶק ל״ג, הֲלָכָה ח׳","בִּרְכַּת הַגּוֹמֵל"],["לְפִי מִנְהַג חֵלֶק מֵהַסְּפָרַדִּים, מִי שֶׁנִּצַּל מִתְּאוּנַת דְּרָכִים —",["מְבָרֵךְ הַגּוֹמֵל בְּלִי הַזְכָּרַת שֵׁם וּמַלְכוּת","אֵינוֹ מְבָרֵךְ כְּלָל, כִּי זוֹ לֹא סַכָּנָה","מְבָרֵךְ שְׁתֵּי בְּרָכוֹת שֶׁל הַגּוֹמֵל בְּשֵׁם וּמַלְכוּת","מְבָרֵךְ שֶׁהֶחֱיָנוּ בִּמְקוֹם בִּרְכַּת הַגּוֹמֵל"],0,"לְמִנְהָג זֶה רַק אַרְבַּעַת הַחִיּוּבִים מְבָרְכִים בְּשֵׁם וּמַלְכוּת, וְעַל שְׁאָר הַהַצָּלוֹת מְבָרְכִים בְּלִי שֵׁם וּמַלְכוּת.","פֶּרֶק ל״ג, הֲלָכָה ט׳","בִּרְכַּת הַגּוֹמֵל"],["בַּבְּרָכָה \"מַצִּיב גְּבוּל אַלְמָנָה\" – מִי הִיא הָאַלְמָנָה?",["עִיר יְרוּשָׁלַיִם בִּלְבַד, שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה גְּבוֹהָה מְאוֹד","אֶרֶץ יִשְׂרָאֵל, שֶׁהָיְתָה בּוֹדֶדֶת בְּלִי בָּנֶיהָ בִּזְמַן הַחֻרְבָּן","כָּל עִיר עַתִּיקָה בָּעוֹלָם שֶׁאֵין בָּהּ תּוֹשָׁבִים כְּלָל","הַמִּדְבָּר הַגָּדוֹל שֶׁבּוֹ הָלְכוּ בְּנֵי יִשְׂרָאֵל אַרְבָּעִים שָׁנָה"],1,"בְּתְקוּפַת הַחֻרְבָּן הָיְתָה אֶרֶץ יִשְׂרָאֵל כְּאַלְמָנָה בּוֹדֶדֶת בְּלִי בָּנֶיהָ. כְּשֶׁיִּשְׂרָאֵל שָׁבִים, ה׳ מַצִּיב מֵחָדָשׁ אֶת גְּבוּלָהּ.","פֶּרֶק ל״ד, הֲלָכָה א׳","בִּרְכוֹת הָרְאִיָּה"],["יוֹסֵף גָּר בִּירוּשָׁלַיִם וְנָסַע לַגָּלִיל, שֶׁלֹּא רָאָה שְׁלוֹשִׁים יוֹם. מָה דִּינוֹ?",["חַיָּב לְבָרֵךְ מַצִּיב גְּבוּל אַלְמָנָה עִם שֵׁם וּמַלְכוּת","אֵינוֹ מְבָרֵךְ, כִּי תּוֹשָׁבֵי הָאָרֶץ לְעוֹלָם לֹא מְבָרְכִים","יָכוֹל לְבָרֵךְ מַצִּיב גְּבוּל אַלְמָנָה, בְּלִי שֵׁם וּמַלְכוּת","מְבָרֵךְ עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית עַל נוֹף הַגָּלִיל"],2,"תּוֹשָׁבֵי הָאָרֶץ אֵינָם חַיָּבִים, אֲבָל מִי שֶׁרוֹאֶה מָקוֹם שֶׁאֵינוֹ מְקוֹם מְגוּרָיו וְלֹא רָאָהוּ שְׁלוֹשִׁים יוֹם – יָכוֹל לְבָרֵךְ בְּלִי שֵׁם וּמַלְכוּת.","פֶּרֶק ל״ד, הֲלָכָה ב׳","בִּרְכוֹת הָרְאִיָּה"],["פְּרוֹפֶסוֹר יְהוּדִי מְפֻרְסָם, גָּאוֹן בִּרְפוּאָה וּבְמַדָּעִים, אַךְ אֵינוֹ חָכָם בַּתּוֹרָה. הַאִם מְבָרְכִים \"שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו\"?",["מְבָרְכִים שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו, כִּי הוּא יְהוּדִי חָכָם מְאוֹד","מְבָרְכִים עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית, כִּי הוּא יוֹדֵעַ מַדָּעִים רַבִּים","מְבָרְכִים שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו, רַק אִם הוּא גַּם רוֹפֵא","אֵין מְבָרְכִים בְּרָכָה זוֹ, כִּי הִיא רַק עַל חָכְמַת הַתּוֹרָה"],3,"בְּרָכָה זוֹ נֶאֱמֶרֶת דַּוְקָא עַל חֲכָמִים בְּחָכְמַת הַתּוֹרָה. עַל יְהוּדִים הַחֲכָמִים בְּחָכְמוֹת אֲחֵרוֹת אֵין מְבָרְכִים בְּרָכָה זוֹ.","פֶּרֶק ל״ד, הֲלָכָה ג׳","בִּרְכוֹת הָרְאִיָּה"],["הִרְגַּשְׁנוּ רְעִידַת אֲדָמָה. מָה הַמִּנְהָג לְבָרֵךְ?",["שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם, וְאָסוּר לְבָרֵךְ בְּרָכָה אַחֶרֶת","עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית, אַף שֶׁאֶפְשָׁר גַּם שֶׁכֹּחוֹ וּגְבוּרָתוֹ","מַצִּיב גְּבוּל אַלְמָנָה, בְּלִי הַזְכָּרַת שֵׁם וּמַלְכוּת","שֶׁעָשָׂה אֶת הַיָּם הַגָּדוֹל, כִּי הָאֲדָמָה רוֹעֶדֶת כְּמוֹ גַּלִּים"],1,"עַל זִיקִים, רְעִידַת אֲדָמָה וְרוּחוֹת סְעָרָה אֶפְשָׁר לְבָרֵךְ שְׁתֵּי הַבְּרָכוֹת, אַךְ הַמִּנְהָג הוּא לְבָרֵךְ \"עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית\".","פֶּרֶק ל״ה, הֲלָכָה א׳","בִּרְכוֹת הָרְאִיָּה"],["בַּבֹּקֶר הָיְתָה סְעָרָה עִם בְּרָקִים וּבֵרַכְנוּ. אַחַר כָּךְ הִתְפַּזְּרוּ הָעֲנָנִים, וּבָעֶרֶב בָּאוּ עַנְנֵי גֶּשֶׁם חֲדָשִׁים עִם בְּרָקִים. מָה עוֹשִׂים?",["לֹא מְבָרְכִים, כִּי מְבָרְכִים עַל בְּרָקִים רַק פַּעַם בְּשָׁנָה","מְבָרְכִים עַל כָּל בָּרָק וּבָרָק, גַּם בְּאוֹתָהּ סְעָרָה","חוֹזְרִים וּמְבָרְכִים, כִּי בָּאוּ עֲנָנִים חֲדָשִׁים אַחֲרֵי שֶׁהִתְפַּזְּרוּ","לֹא מְבָרְכִים, כִּי כְּבָר בֵּרְכוּ עַל בְּרָקִים בַּבֹּקֶר"],2,"בְּדֶרֶךְ כְּלָל מְבָרְכִים עַל בְּרָקִים וּרְעָמִים פַּעַם אַחַת בַּיּוֹם, אֲבָל אִם הִתְפַּזְּרוּ הֶעָנָנִים וּבָאוּ עַנְנֵי גֶּשֶׁם חֲדָשִׁים – חוֹזְרִים וּמְבָרְכִים.","פֶּרֶק ל״ה, הֲלָכָה ג׳","בִּרְכוֹת הָרְאִיָּה"],["בִּסְעָרָה רוֹאִים בָּרָק וְשׁוֹמְעִים רַעַם. מָה מְבָרְכִים עַל כָּל אֶחָד?",["עַל בָּרָק שֶׁכֹּחוֹ וּגְבוּרָתוֹ, וְעַל רַעַם עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית","עַל שְׁנֵיהֶם מְבָרְכִים שֶׁעָשָׂה אֶת הַיָּם הַגָּדוֹל","עַל שְׁנֵיהֶם מְבָרְכִים מַצִּיב גְּבוּל אַלְמָנָה בְּלִי שֵׁם","עַל בָּרָק עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית, וְעַל רַעַם שֶׁכֹּחוֹ וּגְבוּרָתוֹ"],3,"רוֹאִים בָּרָק – \"עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית\". שׁוֹמְעִים רַעַם – \"שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם\".","פֶּרֶק ל״ה, הֲלָכָה ב׳","בִּרְכוֹת הָרְאִיָּה"],["בְּטִיּוּל בְּמִדְבַּר יְהוּדָה רוֹאִים אֶת מְצוּק הָהַעְתָּקִים. מָה מְבָרְכִים?",["שֶׁעָשָׂה אֶת הַיָּם הַגָּדוֹל, כִּי הַמָּקוֹם קָרוֹב לַיָּם","עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית, כְּמוֹ עַל גְּבָעוֹת וּמִדְבָּרִיּוֹת","מַצִּיב גְּבוּל אַלְמָנָה, כִּי הַמִּדְבָּר נִמְצָא בְּאֶרֶץ יִשְׂרָאֵל","אֵין מְבָרְכִים כְּלָל עַל נוֹף שֶׁל מִדְבָּר"],1,"עַל יַמִּים, נְהָרוֹת, הָרִים, גְּבָעוֹת (כְּמוֹ מְצוּק הָהַעְתָּקִים) וּמִדְבָּרִיּוֹת (כְּמוֹ מִדְבַּר יְהוּדָה) מְבָרְכִים \"עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית\".","פֶּרֶק ל״ה, הֲלָכָה ד׳","בִּרְכוֹת הָרְאִיָּה"],["מָה מְבָרְכִים עַל מַדְעָן גָּדוֹל מֵאֻמּוֹת הָעוֹלָם?",["שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו, בְּלִי הַזְכָּרַת שֵׁם וּמַלְכוּת","אֵין מְבָרְכִים עַל חֲכָמִים שֶׁאֵינָם מֵעַם יִשְׂרָאֵל","שֶׁנָּתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם, בְּלִי שֵׁם וּמַלְכוּת","שֶׁנָּתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם, עִם שֵׁם וּמַלְכוּת מְלֵאִים"],2,"עַל חָכָם מֵאֻמּוֹת הָעוֹלָם בְּחָכְמַת הָעוֹלָם מְבָרְכִים \"בָּרוּךְ שֶׁנָּתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם\" – בְּלִי הַזְכָּרַת שֵׁם וּמַלְכוּת.","פֶּרֶק ל״ד, הֲלָכָה ד׳","בִּרְכוֹת הָרְאִיָּה"],["מָה הַתְּנַאי כְּדֵי לְבָרֵךְ עַל הַר אוֹ נָהָר?",["שֶׁיִּרְאֶה אוֹתָם יַחַד עִם עֲשָׂרָה אֲנָשִׁים לְפָחוֹת","שֶׁיִּהְיֶה זֶה בְּיוֹם שַׁבָּת אוֹ חַג בִּלְבַד","שֶׁלֹּא רָאָה אוֹתָם שְׁלוֹשִׁים יָמִים רְצוּפִים קֹדֶם","שֶׁיִּרְאֶה אוֹתָם לְפָחוֹת שָׁלוֹשׁ פְּעָמִים בְּשָׁנָה אַחַת"],2,"מְבָרְכִים עַל יַמִּים, נְהָרוֹת, הָרִים וְגִבְעוֹת רַק אִם לֹא רָאוּ אוֹתָם שְׁלוֹשִׁים יָמִים רְצוּפִים (לֹא כּוֹלֵל יְמֵי הָרְאִיָּה).","פֶּרֶק ל״ה, הֲלָכָה ז׳","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["רְאוּבֵן רָאָה אֶת הַנָּהָר בְּרֹאשׁ חֹדֶשׁ, וְשׁוּב אַחֲרֵי עֶשְׂרִים יוֹם. מָה דִּינוֹ?",["יְבָרֵךְ שׁוּב, כִּי זֶה יוֹם אַחֵר לְגַמְרֵי","יְבָרֵךְ רַק אִם יָבוֹא עִם חֲבֵרִים נוֹסָפִים","יְבָרֵךְ בְּלִי שֵׁם וּמַלְכוּת עַל הַנָּהָר הַגָּדוֹל","לֹא יְבָרֵךְ, כִּי לֹא עָבְרוּ שְׁלוֹשִׁים יָמִים"],3,"עֶשְׂרִים יוֹם אֵינָם מַסְפִּיקִים – צָרִיךְ שֶׁלֹּא יִרְאֶה אֶת הַנָּהָר שְׁלוֹשִׁים יָמִים רְצוּפִים.","פֶּרֶק ל״ה, הֲלָכָה ז׳","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["מַהוּ סִיּוּם הַבְּרָכָה עַל הַקֶּשֶׁת?",["עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית וְזוֹכֵר אֶת בְּרִיתוֹ","זוֹכֵר הַבְּרִית וְנֶאֱמָן בִּבְרִיתוֹ וְקַיָּם בְּמַאֲמָרוֹ","שֶׁכָּכָה לּוֹ בְּעוֹלָמוֹ וְנֶאֱמָן בְּמַאֲמָרוֹ","שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם וְקַיָּם לָעַד"],1,"עַל הַקֶּשֶׁת מְבָרְכִים: ״בָּרוּךְ אַתָּה ה׳ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם זוֹכֵר הַבְּרִית וְנֶאֱמָן בִּבְרִיתוֹ וְקַיָּם בְּמַאֲמָרוֹ״.","פֶּרֶק ל״ה, הֲלָכָה ח׳","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["מַדּוּעַ אָסוּר לְהִסְתַּכֵּל בַּקֶּשֶׁת יוֹתֵר מִדַּי?",["כִּי הַגְּמָרָא אוֹמֶרֶת שֶׁהַמִּסְתַּכֵּל בָּהּ עֵינָיו כֵּהוֹת","כִּי זֶה מַפְרִיעַ לַאֲנָשִׁים אֲחֵרִים לִרְאוֹת אוֹתָהּ","כִּי הַקֶּשֶׁת נֶעֱלֶמֶת מַהֵר כְּשֶׁמִּסְתַּכְּלִים עָלֶיהָ הַרְבֵּה","כִּי צָרִיךְ לְמַהֵר וּלְבָרֵךְ לִפְנֵי שֶׁתֵּעָלֵם"],0,"בַּגְּמָרָא (חֲגִיגָה ט״ז ע״א) כָּתוּב שֶׁהַמִּסְתַּכֵּל בַּקֶּשֶׁת עֵינָיו כֵּהוֹת – רְאִיָּתוֹ נִפְגַּעַת.","פֶּרֶק ל״ה, הֲלָכָה ט׳","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["דָּוִד בֵּרַךְ עַל קֶשֶׁת בַּשָּׁבוּעַ שֶׁעָבַר, וְהַיּוֹם הוֹפִיעָה קֶשֶׁת חֲדָשָׁה. מָה יַעֲשֶׂה?",["לֹא יְבָרֵךְ עַד שֶׁיַּעַבְרוּ שְׁלוֹשִׁים יָמִים מֵהַקֶּשֶׁת הַקּוֹדֶמֶת","לֹא יְבָרֵךְ, כִּי מְבָרְכִים פַּעַם אַחַת בִּלְבַד בַּחַיִּים","יְבָרֵךְ שׁוּב, כִּי עַל כָּל קֶשֶׁת חֲדָשָׁה מְבָרְכִים","יְבָרֵךְ רַק אִם הַקֶּשֶׁת יָפָה יוֹתֵר מֵהַקּוֹדֶמֶת"],2,"בְּכָל פַּעַם שֶׁרוֹאִים קֶשֶׁת חֲדָשָׁה חוֹזְרִים וּמְבָרְכִים – גַּם אִם בֵּרְכוּ לֹא מִזְּמַן.","פֶּרֶק ל״ה, הֲלָכָה י׳","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["בַּמֶּה שׁוֹנָה הַבְּרָכָה ״שֶׁכָּכָה לּוֹ בְּעוֹלָמוֹ״ מִבְּרָכוֹת אֲחֵרוֹת בַּפֶּרֶק?",["מְבָרְכִים אוֹתָהּ רַק בְּצִבּוּר שֶׁל עֲשָׂרָה","מְבָרְכִים אוֹתָהּ רַק בַּלַּיְלָה אַחֲרֵי צֵאת הַכּוֹכָבִים","מְבָרְכִים אוֹתָהּ רַק פַּעַם בִּשְׁלוֹשִׁים יוֹם","מְבָרְכִים אוֹתָהּ בְּלִי הַזְכָּרַת שֵׁם וּמַלְכוּת"],3,"עַל אִילָנוֹת טוֹבִים וּבְרִיּוֹת נָאוֹת מְבָרְכִים בְּלִי הַזְכָּרַת שֵׁם וּמַלְכוּת: ״בָּרוּךְ שֶׁכָּכָה לּוֹ בְּעוֹלָמוֹ״.","פֶּרֶק ל״ה, הֲלָכָה י״א","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["יוֹסִי בֵּרַךְ ״שֶׁכָּכָה לּוֹ בְּעוֹלָמוֹ״ עַל עֵצִים יָפִים בַּגַּן. מָתַי יְבָרֵךְ שׁוּב?",["בְּכָל פַּעַם שֶׁיַּחֲזֹר לַגַּן וְיִרְאֶה אוֹתָם","רַק כְּשֶׁיִּרְאֶה עֵצִים נָאִים יוֹתֵר מֵאֵלּוּ שֶׁבֵּרַךְ","אַחֲרֵי שְׁלוֹשִׁים יָמִים שֶׁלֹּא רָאָה אוֹתָם","רַק כְּשֶׁיָּבוֹא הָאָבִיב הַבָּא וְהֵם יִפְרְחוּ"],1,"מִי שֶׁבֵּרַךְ בְּרָכָה זוֹ לֹא יְבָרֵךְ שֵׁנִית, אֶלָּא אִם כֵּן יִרְאֶה אִילָנוֹת אוֹ בְּרִיּוֹת נָאִים יוֹתֵר מֵאֵלּוּ שֶׁעֲלֵיהֶם בֵּרַךְ.","פֶּרֶק ל״ה, הֲלָכָה י״א","קֶשֶׁת, אִילָנוֹת וְחַמָּה"],["מֵהֵיכָן לוֹמְדִים שֶׁקְּדֻשַּׁת הַשַּׁבָּת יָרְדָה כְּבָר בַּשַּׁבָּת הָרִאשׁוֹנָה?",["מִסִּפּוּר הַמָּן שֶׁיָּרַד בַּמִּדְבָּר בְּכָל יוֹם","מִדִּבְרֵי הַנְּבִיאִים עַל בִּנְיַן בֵּית הַמִּקְדָּשׁ","מִפָּסוּק בְּחֻמַּשׁ בְּרֵאשִׁית, שֶׁבָּהּ לֹא נֶעֶשְׂתָה מְלָאכָה","מִמִּנְהַג שֶׁנָּהֲגוּ הָאָבוֹת בְּאֶרֶץ כְּנַעַן"],2,"בְּחֻמַּשׁ בְּרֵאשִׁית נֶאֱמָר ״וַיִּשְׁבֹּת בַּיּוֹם הַשְּׁבִיעִי מִכָּל מְלַאכְתּוֹ״ – כְּבָר בַּשַּׁבָּת הָרִאשׁוֹנָה לֹא נֶעֶשְׂתָה מְלָאכָה, וּקְדֻשָּׁתָהּ יָרְדָה לָעוֹלָם.","פֶּרֶק ל״ו, הֲלָכָה א׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["מָה מִתְחַדֵּשׁ בָּאָדָם בְּיוֹם הַשַּׁבָּת, וּמִי מַרְגִּישׁ זֹאת?",["רַק הַכֹּחַ הַגּוּפָנִי, וְכָל אָדָם מַרְגִּישׁ זֹאת","רַק הַכֹּחַ הַשִּׂכְלִי, וְרַק תַּלְמִידֵי חֲכָמִים מַרְגִּישִׁים","שׁוּם דָּבָר אֵינוֹ מִתְחַדֵּשׁ, זֶה יוֹם רָגִיל","הַכֹּחַ הַגּוּפָנִי וְהַשִּׂכְלִי, וְרַק שׁוֹמֵר שַׁבָּת מַרְגִּישׁ"],3,"בְּשַׁבָּת מִתְחַדְּשִׁים הַכֹּחַ הַגּוּפָנִי וְהַכֹּחַ הַשִּׂכְלִי, וְרַק שׁוֹמֵר שַׁבָּת מַרְגִּישׁ זֹאת. וּבַמִּדְבָּר רָאוּ אֶת קְדֻשַּׁת הַשַּׁבָּת בָּעֵינַיִם – הַמָּן לֹא יָרַד בְּשַׁבָּת.","פֶּרֶק ל״ו, הֲלָכוֹת ב׳-ג׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["מָה מַרְאֶה עַם יִשְׂרָאֵל כְּשֶׁהוּא שׁוֹמֵר אֶת הַשַּׁבָּת?",["שֶׁהוּא עָיֵף מְאוֹד מֵעֲבוֹדַת כָּל הַשָּׁבוּעַ","אֶת הַקֶּשֶׁר הַמְּיֻחָד שֶׁלּוֹ עִם ה׳","שֶׁהוּא אוֹהֵב לֶאֱכֹל מַאֲכָלִים טְעִימִים","שֶׁהוּא מְחַקֶּה אֶת מִנְהֲגֵי שְׁאָר הָעַמִּים"],1,"ה׳ הֶעֱנִיק אֶת יוֹם מְנוּחָתוֹ דַּוְקָא לְעַם יִשְׂרָאֵל, וּבִשְׁמִירַת הַשַּׁבָּת מַרְאֶה עַם יִשְׂרָאֵל אֶת הַקֶּשֶׁר הַמְּיֻחָד שֶׁלּוֹ עִם ה׳.","פֶּרֶק ל״ו, הֲלָכָה ד׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["מָה אָמַר רַבִּי לֵוִי עַל שְׁמִירַת שַׁבָּת אַחַת כָּרָאוּי?",["אִם יִשְׂרָאֵל יִשְׁמְרוּ אוֹתָהּ, בֶּן דָּוִד יָבוֹא","אִם יִשְׂרָאֵל יִשְׁמְרוּ אוֹתָהּ, הַמָּן יֵרֵד שׁוּב","שַׁבָּת אַחַת אֵינָהּ מַסְפִּיקָה, צָרִיךְ מֵאָה שַׁבָּתוֹת","אִם יִשְׁמְרוּ אוֹתָהּ, יַצְלִיחוּ בְּכָל הַמִּלְחָמוֹת"],0,"רַבִּי לֵוִי אָמַר: אִם מְשַׁמְּרִים יִשְׂרָאֵל אֶת הַשַּׁבָּת כָּרָאוּי אֲפִלּוּ פַּעַם אַחַת – בֶּן דָּוִד (הַמָּשִׁיחַ) בָּא.","פֶּרֶק ל״ו, הֲלָכָה ה׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["מַדּוּעַ מִי שֶׁגּוֹי עוֹשֶׂה אֶת מְלַאכְתּוֹ בְּשַׁבָּת אֵין מְנוּחָתוֹ שְׁלֵמָה?",["כִּי הַגּוֹי מַרְעִישׁ לְיַד בֵּיתוֹ כָּל הַיּוֹם","כִּי עָלָיו לְשַׁלֵּם לַגּוֹי בְּיוֹם הַשַּׁבָּת","כִּי הוּא צָרִיךְ לַעֲזֹר לַגּוֹי בַּעֲבוֹדָה","כִּי הוּא טָרוּד אִם הַגּוֹי עוֹשֶׂה כָּרָאוּי"],3,"מִי שֶׁמְּלַאכְתּוֹ נַעֲשֵׂית בְּשַׁבָּת עַל יְדֵי גּוֹי טָרוּד בַּשְּׁאֵלָה הַאִם הַגּוֹי מְבַצֵּעַ אוֹתָהּ כָּרָאוּי, וּמְנוּחָתוֹ אֵינָהּ שְׁלֵמָה. וְעוֹד – כְּדֵי שֶׁלֹּא יְזַלְזְלוּ בְּשַׁבָּת.","פֶּרֶק ל״ו, הֲלָכָה ו׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["מָה צָרִיךְ לִזְכֹּר כְּשֶׁמְּעַנְּגִים אֶת הַשַּׁבָּת בְּמַאֲכָל וּבְמִשְׁתֶּה?",["שֶׁצָּרִיךְ לֶאֱכֹל כַּמָּה שֶׁיּוֹתֵר עַד שֶׁנִּשְׂבָּע מְאוֹד","שֶׁהַמַּאֲכָלִים צְרִיכִים לִהְיוֹת יְקָרִים יוֹתֵר מִשֶּׁל הַשְּׁכֵנִים","שֶׁהָעֹנֶג אֵינוֹ לַהֲנָאַת גּוּפֵנוּ אֶלָּא לִכְבוֹד הַשַּׁבָּת","שֶׁהָעֹנֶג הוּא כְּדֵי שֶׁהָאוֹרְחִים יְשַׁבְּחוּ אוֹתָנוּ"],2,"מִצְוָה מִדִּבְרֵי חֲכָמִים לְכַבֵּד וּלְעַנֵּג אֶת הַשַּׁבָּת, אַךְ זֶה אֵינוֹ לִכְבוֹדֵנוּ וַהֲנָאַת גּוּפֵנוּ – אֶלָּא לִכְבוֹד הַשַּׁבָּת.","פֶּרֶק ל״ז, הֲלָכָה א׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["אֵיזוֹ מִצְוָה מְקַיֵּם מִי שֶׁשּׁוֹמֵר מַאֲכָל מְשֻׁבָּח לְשַׁבָּת?",["מִצְוַת שִׂמְחַת יוֹם טוֹב שֶׁכְּתוּבָה בַּתּוֹרָה בִּמְפֹרָשׁ","זָכוֹר אֶת יוֹם הַשַּׁבָּת – לִזְכֹּר אוֹתָהּ בִּימוֹת הַחֹל","מִצְוַת צְדָקָה, כִּי הוּא נוֹתֵן מִמַּאֲכָלוֹ לַעֲנִיִּים","מִצְוַת כִּבּוּד אָב וָאֵם שֶׁאָהֲבוּ מַאֲכָלִים טוֹבִים"],1,"כְּמוֹ שַׁמַּאי הַזָּקֵן: מִי שֶׁשּׁוֹמֵר מַאֲכָל מְשֻׁבָּח לְשַׁבָּת מְכַבֵּד אֶת הַשַּׁבָּת, וּמְקַיֵּם ״זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ״ – זוֹכֵר אוֹתָהּ גַּם בִּימוֹת הַחֹל.","פֶּרֶק ל״ז, הֲלָכָה ב׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["מָה הַדִּין לְמִי שֶׁאֵין לוֹ מַסְפִּיק כֶּסֶף לְמַאַכְלֵי שַׁבָּת?",["דַּי שֶׁיָּכִין מַאֲכָל אֶחָד קָטָן יוֹתֵר מֵהֶרְגֵּלוֹ","חַיָּב לִלְווֹת כֶּסֶף כְּדֵי לְהַרְבּוֹת בְּמַאֲכָלִים","חַיָּב לְבַקֵּשׁ צְדָקָה מִבְּנֵי אָדָם לִכְבוֹד שַׁבָּת","פָּטוּר לְגַמְרֵי, וְאֵין לוֹ שׁוּם מִצְוַת עֹנֶג"],0,"כָּל אֶחָד מְעַנֵּג אֶת הַשַּׁבָּת לְפִי מַצָּבוֹ. מִי שֶׁאֵין לוֹ – דַּי בְּמַאֲכָל אֶחָד קָטָן יוֹתֵר מֵהֶרְגֵּלוֹ, וְאֵינוֹ חַיָּב לִלְווֹת: ״עֲשֵׂה שַׁבַּתְּךָ חֹל וְאַל תִּצְטָרֵךְ לַבְּרִיּוֹת״.","פֶּרֶק ל״ז, הֲלָכוֹת ג׳-ה׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["לָמָּה תִּקְּנוּ לוֹמַר בַּתְּפִלָּה ״יִשְׂמְחוּ בְמַלְכוּתְךָ שׁוֹמְרֵי שַׁבָּת״?",["כִּי כָּתוּב בַּתּוֹרָה בִּמְפֹרָשׁ לִשְׂמֹחַ בְּשַׁבָּת","כְּדֵי לִשְׂמֹחַ בְּשַׁבָּת בְּדִיּוּק כְּמוֹ בַּחַגִּים","כִּי בְּשַׁבָּת יֵשׁ שִׂמְחָה רוּחָנִית בְּמַלְכוּת ה׳","כְּדֵי לְהַזְכִּיר אֶת מִצְוַת הַשִּׂמְחָה בְּיוֹם טוֹב"],2,"בַּתּוֹרָה לֹא נִכְתְּבָה מִצְוַת שִׂמְחָה בְּשַׁבָּת כְּמוֹ בְּיָמִים טוֹבִים, אֲבָל יֵשׁ בָּהּ שִׂמְחָה רוּחָנִית – שִׂמְחָה בְּמַלְכוּת ה׳.","פֶּרֶק ל״ז, הֲלָכָה ו׳","גְּדֻלַּת הַשַּׁבָּת וּכְבוֹדָהּ"],["מָה עוֹשִׂים אִם יֵשׁ חֲשָׁשׁ שֶׁדָּבָר מְסֻיָּם לֹא יִהְיֶה אֶפְשָׁר לִקְנוֹת בְּיוֹם שִׁשִּׁי?",["טוֹב יוֹתֵר לִקְנוֹת אוֹתוֹ כְּבָר בְּיוֹם חֲמִישִׁי","מְוַתְּרִים עָלָיו כִּי קוֹנִים רַק בְּיוֹם שִׁשִּׁי","קוֹנִים אוֹתוֹ בְּשַׁבָּת עַצְמָהּ בַּבֹּקֶר הַמֻּקְדָּם","מְחַכִּים וְקוֹנִים אוֹתוֹ רַק בְּמוֹצָאֵי שַׁבָּת"],0,"מִצְוָה לְהַשְׁכִּים בְּיוֹם שִׁשִּׁי לִקְנוֹת — כְּמוֹ הַמָּן הַכָּפוּל שֶׁיָּרַד בְּיוֹם שִׁשִּׁי. אֲבָל דָּבָר שֶׁחוֹשְׁשִׁים שֶׁלֹּא יִמָּצֵא, טוֹב לִקְנוֹת כְּבָר בְּיוֹם חֲמִישִׁי.","פֶּרֶק ל״ח, הֲלָכָה א׳-ב׳","מְכִינִים אֶת הַשַּׁבָּת"],["לָמָּה גַּם אָדָם עָסוּק, שֶׁאֵין דַּרְכּוֹ לַעֲשׂוֹת קְנִיּוֹת, צָרִיךְ לִטְרֹחַ בְּעַצְמוֹ לִכְבוֹד שַׁבָּת?",["כִּי אָסוּר לְשַׁלֵּם לַאֲחֵרִים עַל עֲבוֹדָה","כִּי הַטִּרְחָה לִכְבוֹד שַׁבָּת הִיא כְּבוֹדוֹ","כִּי בְּיוֹם שִׁשִּׁי כָּל הַחֲנֻיּוֹת סְגוּרוֹת","כִּי רַק כָּךְ הָאֹכֶל יִהְיֶה טָעִים"],1,"הַטִּרְחָה לִכְבוֹד הַשַּׁבָּת הִיא כְּבוֹדוֹ שֶׁל הָאָדָם — וְגַם חֲכָמִים גְּדוֹלִים הֵבִיאוּ עֵצִים, מָלְחוּ בָּשָׂר וְהֵכִינוּ פְּתִילוֹת. גַּם הַיְּלָדִים צְרִיכִים לַעֲזֹר.","פֶּרֶק ל״ח, הֲלָכָה ג׳-ד׳","מְכִינִים אֶת הַשַּׁבָּת"],["מָה צָרִיךְ רֹאשׁ הַבַּיִת לְהַזְכִּיר לִבְנֵי בֵּיתוֹ בְּהִתְקָרֵב הַשַּׁבָּת?",["לָלֶכֶת לִישֹׁן מֻקְדָּם כְּדֵי לָקוּם לַתְּפִלָּה","לְהַזְמִין אוֹרְחִים רַבִּים לִסְעוּדַת לֵיל שַׁבָּת","לְסַיֵּם בַּזְּמַן הֲכָנוֹת, שֶׁלֹּא יַעֲשׂוּ מְלָאכָה אַחַר הַשְּׁקִיעָה","לִקְנוֹת מַתָּנוֹת לְכָל אֶחָד מִבְּנֵי הַמִּשְׁפָּחָה"],2,"רֹאשׁ הַבַּיִת אוֹמֵר ״עִשַּׂרְתֶּם? עֵרַבְתֶּם? הַדְלִיקוּ אֶת הַנֵּר!״, וּמַזְכִּיר לְסַיֵּם בַּזְּמַן, שֶׁחָלִילָה לֹא יַעֲשׂוּ מְלָאכוֹת אֲסוּרוֹת אַחַר הַשְּׁקִיעָה.","פֶּרֶק ל״ח, הֲלָכָה ה׳","מְכִינִים אֶת הַשַּׁבָּת"],["יְהוּדָה רוֹצֶה לְכַבֵּד אֶת הַשַּׁבָּת גַּם בַּלְּבוּשׁ. מָה עָלָיו לִלְבֹּשׁ?",["אֶת הַבְּגָדִים שֶׁלָּבַשׁ כָּל הַשָּׁבוּעַ בַּמִּשְׂחָק","בִּגְדֵי סְפּוֹרְט נוֹחִים כְּדֵי לָנוּחַ הֵיטֵב","בְּגָדִים יְשָׁנִים כְּדֵי שֶׁלֹּא יִתְלַכְלְכוּ הַחֲדָשִׁים","בְּגָדִים חֲגִיגִיִּים וּנְקִיִּים לִכְבוֹד הַשַּׁבָּת"],3,"יֵשׁ לִלְבֹּשׁ לִכְבוֹד הַשַּׁבָּת בְּגָדִים חֲגִיגִיִּים וּנְקִיִּים.","פֶּרֶק ל״ח, הֲלָכָה ו׳","מְכִינִים אֶת הַשַּׁבָּת"],["גַּם מִי שֶׁשּׁוֹמֵעַ קְרִיאַת הַתּוֹרָה בְּשַׁבָּת קוֹרֵא בְּעַצְמוֹ. מָה פֵּרוּשׁ ״שְׁנַיִם מִקְרָא וְאֶחָד תַּרְגּוּם״?",["פְּסוּקִים פַּעֲמַיִם, וְתַרְגּוּם אוּנְקְלוֹס פַּעַם אַחַת","פְּסוּקִים פַּעַם אַחַת, וְתַרְגּוּם אוּנְקְלוֹס פַּעֲמַיִם","שְׁנֵי אֲנָשִׁים קוֹרְאִים, וְאֶחָד מְתַרְגֵּם לְכֻלָּם","קוֹרְאִים שְׁתֵּי פָּרָשִׁיּוֹת וּמְתַרְגְּמִים רַק אַחַת"],0,"כַּהֲכָנָה רוּחָנִית לְשַׁבָּת — שֶׁהִיא תַּעֲנוּג הַגּוּף וְגַם הַנֶּפֶשׁ — קוֹרְאִים כָּל פָּסוּק פַּעֲמַיִם וְאֶת תַּרְגּוּם אוּנְקְלוֹס פַּעַם אַחַת.","פֶּרֶק ל״ט, הֲלָכָה א׳-ב׳","מְכִינִים אֶת הַשַּׁבָּת"],["מִמָּתַי אֶפְשָׁר לְהַתְחִיל לִקְרֹא שְׁנַיִם מִקְרָא שֶׁל פָּרָשַׁת הַשָּׁבוּעַ הַבָּא?",["רַק מִבֹּקֶר יוֹם רִאשׁוֹן שֶׁל הַשָּׁבוּעַ הֶחָדָשׁ","מִתְּפִלַּת מִנְחָה שֶׁל שַׁבָּת, שֶׁבָּהּ מַתְחִילִים אוֹתָהּ","רַק מִיּוֹם רְבִיעִי, בְּאֶמְצַע הַשָּׁבוּעַ הַבָּא","רַק בְּיוֹם שִׁשִּׁי, אַחֲרֵי חֲצוֹת הַיּוֹם"],1,"בִּתְפִלַּת מִנְחָה שֶׁל שַׁבָּת מַתְחִילִים לִקְרֹא בְּפָרָשַׁת הַשָּׁבוּעַ הַבָּא, וְלָכֵן מִשָּׁם כְּבָר אֶפְשָׁר לְהַתְחִיל.","פֶּרֶק ל״ט, הֲלָכָה ג׳","מְכִינִים אֶת הַשַּׁבָּת"],["יֵשׁ נוֹהֲגִים לְחַלֵּק אֶת לִמּוּד שְׁנַיִם מִקְרָא לְכָל יְמוֹת הַשָּׁבוּעַ. מָה הַסִּבָּה?",["כִּי אָסוּר לִקְרֹא הַכֹּל בְּיוֹם אֶחָד","כִּי בְּיוֹם שִׁשִּׁי אֵין זְמַן בִּכְלָל","כְּדֵי לִלְמֹד אֶת הַפָּרָשָׁה בִּמְתִינוּת וַהֲבָנָה","כְּדֵי לְסַיֵּם מַהֵר לִפְנֵי כָּל הַחֲבֵרִים"],2,"לְדַעַת חַכְמֵי הַקַּבָּלָה קוֹרְאִים בְּיוֹם שִׁשִּׁי אַחֲרֵי שַׁחֲרִית בְּטַלִּית וּתְפִלִּין, וְיֵשׁ נוֹהֲגִים לְחַלֵּק לְכָל הַשָּׁבוּעַ כְּדֵי לִלְמֹד בִּמְתִינוּת וַהֲבָנָה.","פֶּרֶק ל״ט, הֲלָכָה ד׳","מְכִינִים אֶת הַשַּׁבָּת"],["דָּוִד לֹא הִסְפִּיק לְסַיֵּם שְׁנַיִם מִקְרָא לִפְנֵי סְעוּדַת הַבֹּקֶר בְּשַׁבָּת. מָה יַעֲשֶׂה?",["יְוַתֵּר עַל הַפָּרָשָׁה הַזֹּאת לְגַמְרֵי","יִקְרָא אוֹתָהּ רַק בְּשַׁבָּת שֶׁל שָׁנָה הַבָּאָה","יִקְרָא פַּעַם אַחַת בִּלְבַד בְּלִי תַּרְגּוּם","יִשְׁתַּדֵּל לְסַיֵּם עַד יוֹם שְׁלִישִׁי שֶׁאַחֲרֵי"],3,"מִצְוָה מִן הַמֻּבְחָר לְסַיֵּם לִפְנֵי סְעוּדַת הַבֹּקֶר. אִם עָבַר — יִשְׁתַּדֵּל עַד יוֹם שְׁלִישִׁי, וְאִם גַּם זֶה עָבַר — עַד שְׁמִינִי עֲצֶרֶת.","פֶּרֶק ל״ט, הֲלָכָה ה׳","מְכִינִים אֶת הַשַּׁבָּת"],["מִי שֶׁאֵין לוֹ פְּנַאי לִקְרֹא גַּם תַּרְגּוּם וְגַם פֵּרוּשׁ רָשִׁ״י — מָה עָדִיף לוֹ?",["לִקְרֹא רַק אֶת הַפְּסוּקִים, בְּלִי שׁוּם פֵּרוּשׁ","לִלְמֹד אֶת הַפָּרָשָׁה עִם פֵּרוּשׁ רָשִׁ״י","לִקְרֹא אֶת הַתַּרְגּוּם שָׁלוֹשׁ פְּעָמִים בִּמְקוֹם הַמִּקְרָא","לְדַלֵּג עַל הַפָּרָשָׁה וְלִשְׁמֹעַ רַק בְּבֵית הַכְּנֶסֶת"],1,"לִמּוּד עִם פֵּרוּשׁ רָשִׁ״י נֶחְשָׁב כְּמוֹ תַּרְגּוּם. יְרֵא שָׁמַיִם קוֹרֵא אֶת שְׁנֵיהֶם, וּמִי שֶׁאֵין לוֹ פְּנַאי — טוֹב יוֹתֵר שֶׁיִּלְמַד עִם רָשִׁ״י.","פֶּרֶק ל״ט, הֲלָכָה ו׳-ז׳","מְכִינִים אֶת הַשַּׁבָּת"],["קוֹרְאִים אֶת פְּסוּקֵי הַתּוֹרָה בִּטְעָמִים. וּמָהִי מַטְּרַת הַקְּרִיאָה מֵעִקָּרָהּ?",["לְסַיֵּם כַּמָּה שֶׁיּוֹתֵר פְּסוּקִים בְּכָל דַּקָּה","לְהַרְשִׁים אֶת כָּל הַמִּשְׁפָּחָה בִּקְרִיאָה יָפָה","לְהִתְבּוֹנֵן בַּמִּצְווֹת, בַּמּוּסָר וּבַמִּדּוֹת הַטּוֹבוֹת שֶׁבַּפְּסוּקִים","לְהִתְאַמֵּן בִּקְרִיאָה מְהִירָה לִקְרַאת הַמִּבְחָן"],2,"יֵשׁ לְהַקְפִּיד עַל קְרִיאָה בִּטְעָמִים, וּמַטְּרַת הַקְּרִיאָה מֵעִקָּרָהּ הִיא לְהִתְבּוֹנֵן בַּמִּצְווֹת, בְּדִבְרֵי הַמּוּסָר וּבַמִּדּוֹת הַטּוֹבוֹת.","פֶּרֶק ל״ט, הֲלָכָה ח׳-ט׳","מְכִינִים אֶת הַשַּׁבָּת"],["מָה עִקַּר מִצְוַת הַנֵּר בְּשַׁבָּת?",["שֶׁיִּהְיֶה אוֹר בַּחַלּוֹן כְּדֵי שֶׁיִּרְאוּ הַשְּׁכֵנִים","שֶׁיִּהְיֶה אוֹר דּוֹלֵק בַּבַּיִת כָּל הַלַּיְלָה","שֶׁהַנֵּר יִדְלַק רַק בְּשָׁעַת הַבְּרָכָה עַצְמָהּ","שֶׁיִּדְלְקוּ נֵרוֹת רַק בַּמִּטְבָּח בִּזְמַן הַבִּשּׁוּל"],1,"עִקַּר הַמִּצְוָה שֶׁיִּהְיֶה אוֹר דּוֹלֵק כָּל הַלַּיְלָה בַּבַּיִת, וּבִמְיֻחָד בִּמְקוֹם הַסְּעוּדָה וּבִזְמַנָּהּ, כִּי הָאוֹכֵל בַּחֲשֵׁכָה אֵינוֹ שָׂבֵעַ.","פֶּרֶק מ׳, הֲלָכָה א׳","נֵרוֹת שַׁבָּת"],["בְּאֵיזֶה סֵדֶר נוֹהֲגִים לְהַדְלִיק אוֹר בְּעֶרֶב שַׁבָּת?",["מַדְלִיקִים רַק חַשְׁמַל, וּמְבָרְכִים עָלָיו בִּמְקוֹם נֵרוֹת","קֹדֶם נֵרוֹת בִּבְרָכָה, אַחַר כָּךְ חַשְׁמַל בִּבְרָכָה","קֹדֶם חַשְׁמַל בְּלִי בְּרָכָה, אַחַר כָּךְ נֵרוֹת בִּבְרָכָה","אֵין מַדְלִיקִים חַשְׁמַל כְּלָל בְּעֶרֶב שַׁבָּת"],2,"נוֹהֲגִים לְהַדְלִיק תְּחִלָּה אֶת הַחַשְׁמַל בַּחֲדָרִים וּבַפְּרוֹזְדוֹר לְלֹא בְּרָכָה, וְאַחַר כָּךְ מַדְלִיקִים אֶת נֵרוֹת הַשַּׁבָּת בִּמְקוֹם הַסְּעוּדָה בִּבְרָכָה.","פֶּרֶק מ׳, הֲלָכָה ב׳","נֵרוֹת שַׁבָּת"],["מָה עָנָה הַזָּקֵן לְרַבִּי שִׁמְעוֹן בַּר יוֹחַאי עַל שְׁנֵי הַהֲדַסִּים?",["אֶחָד לִי וְאֶחָד לְבֵית הַכְּנֶסֶת שֶׁבָּעִיר","אֶחָד לְשַׁבָּת וְאֶחָד לְיוֹם טוֹב הַקָּרוֹב","כִּי הֲדַס אֶחָד לֹא מֵרִיחַ מַסְפִּיק טוֹב","אֶחָד כְּנֶגֶד זָכוֹר וְאֶחָד כְּנֶגֶד שָׁמוֹר"],3,"הַזָּקֵן אָמַר: ״אֶחָד כְּנֶגֶד ׳זָכוֹר׳ וְאֶחָד כְּנֶגֶד ׳שָׁמוֹר׳״, וְרַבִּי שִׁמְעוֹן אָמַר: ״רְאֵה כַּמָּה חֲבִיבוֹת מִצְווֹת עַל יִשְׂרָאֵל!״. מִכָּאן הַמִּנְהָג לְהַדְלִיק שְׁנֵי נֵרוֹת.","פֶּרֶק מ׳, הֲלָכָה ג׳","נֵרוֹת שַׁבָּת"],["יֵשׁ נוֹהֲגוֹת לְהַדְלִיק עֲשָׂרָה נֵרוֹת. כְּנֶגֶד מָה?",["כְּנֶגֶד עֲשֶׂרֶת הַדִּבְּרוֹת שֶׁנִּתְּנוּ בְּסִינַי","כְּנֶגֶד עֶשֶׂר הַמַּכּוֹת שֶׁהָיוּ בְּמִצְרַיִם","כְּנֶגֶד עֲשָׂרָה אֲנָשִׁים שֶׁל מִנְיָן","כְּנֶגֶד עֲשָׂרָה יְמֵי תְּשׁוּבָה בַּשָּׁנָה"],0,"יֵשׁ נוֹהֲגוֹת לְהַדְלִיק עֲשָׂרָה נֵרוֹת כְּנֶגֶד עֲשֶׂרֶת הַדִּבְּרוֹת, שִׁבְעָה כְּנֶגֶד יְמֵי הַשָּׁבוּעַ, אוֹ כְּמִסְפַּר בְּנֵי הַבַּיִת.","פֶּרֶק מ׳, הֲלָכָה ד׳","נֵרוֹת שַׁבָּת"],["לָמָּה הַנָּשִׁים מְצֻוּוֹת עַל נֵר שַׁבָּת יוֹתֵר מִן הָאֲנָשִׁים?",["כִּי הָאֲנָשִׁים פְּטוּרִים לְגַמְרֵי מִנֵּר שֶׁל שַׁבָּת","כִּי הֵן מְצוּיוֹת בַּבַּיִת וְעוֹסְקוֹת בִּמְלֶאכֶת הַבַּיִת","כִּי רַק נָשִׁים יוֹדְעוֹת לְהַדְלִיק נֵרוֹת כָּרָאוּי","כִּי כָּךְ הֶחְלִיטוּ בְּנֵי הַבַּיִת בְּכָל שָׁבוּעַ"],1,"גַּם אֲנָשִׁים חַיָּבִים בְּנֵר בְּבֵיתָם, אֲבָל הַנָּשִׁים מְצֻוּוֹת יוֹתֵר כִּי הֵן מְצוּיוֹת בַּבַּיִת וְעוֹסְקוֹת בִּמְלַאכְתּוֹ, וְהֵן מוֹצִיאוֹת אֶת בְּנֵי הַבַּיִת יְדֵי חוֹבָתָם.","פֶּרֶק מ׳, הֲלָכָה ה׳","נֵרוֹת שַׁבָּת"],["הָאִשָּׁה אֵינָהּ בַּבַּיִת בְּשַׁבָּת. מָה הַדִּין?",["בַּעֲלָהּ מַדְלִיק אֶת הַנֵּרוֹת אֲבָל בְּלִי בְּרָכָה","לֹא מַדְלִיקִים נֵרוֹת כְּלָל עַד שֶׁהִיא חוֹזֶרֶת","סוֹמְכִים עַל אוֹר הַחַשְׁמַל וְלֹא מַדְלִיקִים נֵרוֹת","בַּעֲלָהּ מַדְלִיק אֶת הַנֵּרוֹת וּמְבָרֵךְ עֲלֵיהֶם"],3,"אִם הָאִשָּׁה חוֹלָה – יַדְלִיק בַּעֲלָהּ בִּבְרָכָה, וְכָל שֶׁכֵּן אִם אֵינָהּ בַּבַּיִת בְּשַׁבָּת.","פֶּרֶק מ׳, הֲלָכָה ו׳","נֵרוֹת שַׁבָּת"],["לָמָּה נָשִׁים רַבּוֹת מַדְלִיקוֹת קֹדֶם וּמְבָרְכוֹת רַק אַחַר כָּךְ?",["כִּי בַּבְּרָכָה הֵן מְקַבְּלוֹת אֶת הַשַּׁבָּת עַל עַצְמָן","כִּי אָסוּר לְבָרֵךְ עַל מִצְוָה לִפְנֵי שֶׁעוֹשִׂים אוֹתָהּ","כִּי צָרִיךְ לִרְאוֹת אֶת הָאוֹר לִפְנֵי שֶׁמְּבָרְכִים","כִּי כָּךְ הַנֵּרוֹת דּוֹלְקִים זְמַן אָרֹךְ יוֹתֵר"],0,"בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים וּבְחֵלֶק מִקְּהִלּוֹת הַסְּפָרַדִּים מְקַבְּלוֹת אֶת הַשַּׁבָּת בַּבְּרָכָה, וְאִם יְבָרְכוּ קֹדֶם – לֹא יוּכְלוּ לְהַדְלִיק. לָכֵן מַדְלִיקוֹת קֹדֶם, מְכַסּוֹת עֵינַיִם וּמְבָרְכוֹת.","פֶּרֶק מ׳, הֲלָכָה ז׳","נֵרוֹת שַׁבָּת"],["אִישׁ שֶׁמַּדְלִיק נֵרוֹת שַׁבָּת – מָה הַסֵּדֶר?",["מַדְלִיק תְּחִלָּה, מְכַסֶּה עֵינַיִם וְאַחַר כָּךְ מְבָרֵךְ","מַדְלִיק בְּלִי בְּרָכָה כִּי הַמִּצְוָה שֶׁל הַנָּשִׁים","לְכָל הַדֵּעוֹת מְבָרֵךְ תְּחִלָּה וְאַחַר כָּךְ מַדְלִיק","מְבָרֵךְ רַק אִם יֵשׁ בַּבַּיִת יוֹתֵר מִשְּׁנֵי נֵרוֹת"],2,"כַּאֲשֶׁר אִישׁ מַדְלִיק – לְכָל הַדֵּעוֹת יְבָרֵךְ תְּחִלָּה וְרַק אַחַר כָּךְ יַדְלִיק, ״עוֹבֵר לַעֲשִׂיָּתָן״.","פֶּרֶק מ׳, הֲלָכָה ח׳","נֵרוֹת שַׁבָּת"],["מָה טוֹב שֶׁיַּעֲשֶׂה אִישׁ לִפְנֵי שֶׁהוּא מַדְלִיק נֵרוֹת שַׁבָּת?",["יְקַבֵּל עָלָיו אֶת הַשַּׁבָּת כְּדֵי שֶׁלֹּא יִשְׁכַּח","יַתְנֶה שֶׁאֵינוֹ מְקַבֵּל עָלָיו אֶת הַשַּׁבָּת בַּהַדְלָקָה","יִתְפַּלֵּל עַרְבִית כְּדֵי שֶׁיּוּכַל לְהַדְלִיק בִּבְרָכָה","יְסַיֵּם אֶת כָּל הַמְּלָאכוֹת שֶׁלּוֹ לִפְנֵי מִנְחָה"],1,"הָאֲנָשִׁים מְקַבְּלִים שַׁבָּת בְּדִבּוּר אַחֲרֵי מִנְחָה, וְלָכֵן הַהַדְלָקָה אֵינָהּ קַבָּלַת שַׁבָּת וּמֻתָּר לוֹ בִּמְלָאכָה. אֲבָל טוֹב יַעֲשֶׂה אִם יַתְנֶה זֹאת בְּפֵרוּשׁ לִפְנֵי הַהַדְלָקָה.","פֶּרֶק מ׳, הֲלָכָה ט׳","נֵרוֹת שַׁבָּת"],["מַדּוּעַ מְקַבְּלִים אֶת הַשַּׁבָּת עוֹד לִפְנֵי שְׁקִיעַת הַחַמָּה?",["כִּי הַשַּׁבָּת מַתְחִילָה בַּחֲצוֹת יוֹם שִׁשִּׁי","כִּי אָסוּר לֶאֱכֹל אַחֲרֵי שְׁקִיעַת הַחַמָּה","כִּי מִצְוָה לְהוֹסִיף מֵהַחֹל עַל הַקֹּדֶשׁ","כִּי כָּךְ קַל יוֹתֵר לְהָכִין אֶת הַסְּעוּדָה"],2,"מִצְוָה לְהוֹסִיף מֵהַחֹל עַל הַקֹּדֶשׁ, וּמֵרֶגַע שֶׁאָדָם קִבֵּל עָלָיו אֶת הַשַּׁבָּת אָסוּר לוֹ לַעֲשׂוֹת מְלָאכָה. זוֹ ״תּוֹסֶפֶת שַׁבָּת״.","פֶּרֶק מ״א, הֲלָכָה א׳","קַבָּלַת שַׁבָּת"],["לְפִי רַבִּי שִׁמְעוֹן, מַדּוּעַ בָּשָׂר וָדָם צָרִיךְ לְהוֹסִיף מֵחֹל עַל הַקֹּדֶשׁ?",["כִּי הוּא עָיֵף מְאוֹד בְּסוֹף הַשָּׁבוּעַ","כִּי הוּא אֵינוֹ יוֹדֵעַ עִתָּיו וּרְגָעָיו","כִּי כָּךְ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּבְּרִיאָה","כִּי הַלּוּחוֹת שֶׁל הַזְּמַנִּים אֵינָם מְדֻיָּקִים"],1,"בָּשָׂר וָדָם אֵינוֹ יוֹדֵעַ עִתָּיו וּרְגָעָיו, וְלָכֵן מוֹסִיף. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹדֵעַ, וְנִכְנַס בַּיּוֹם הַשְּׁבִיעִי כְּחוּט הַשַּׂעֲרָה.","פֶּרֶק מ״א, הֲלָכָה ב׳","קַבָּלַת שַׁבָּת"],["מָה לְמֵדִים מֵרַבִּי חֲנִינָא שֶׁהָיָה יוֹצֵא לִקְרַאת שַׁבָּת הַמַּלְכָּה?",["לְחַכּוֹת בַּבַּיִת עַד שֶׁהַשַּׁבָּת תִּכָּנֵס מֵעַצְמָהּ","לְהִתְפַּלֵּל עַרְבִית מֻקְדָּם בְּכָל יְמוֹת הַשָּׁבוּעַ","לָלֶכֶת לְטַיֵּל בַּשָּׂדֶה הַגָּדוֹל בְּכָל עֶרֶב שַׁבָּת","לְהַקְדִּים וּלְקַבֵּל אֶת הַשַּׁבָּת כְּמוֹ אוֹרֵחַ חָשׁוּב"],3,"מִי שֶׁמְּקַבֵּל אוֹרֵחַ חָשׁוּב יוֹצֵא לִקְרָאתוֹ וְאֵינוֹ מְחַכֶּה שֶׁיִּכָּנֵס. כָּךְ מַקְדִּימִים וּמְקַבְּלִים אֶת הַשַּׁבָּת לִכְבוֹדָהּ.","פֶּרֶק מ״א, הֲלָכָה ג׳","קַבָּלַת שַׁבָּת"],["אִשָּׁה מִקְּהִלּוֹת הַסְּפָרַדִּים שֶׁאֵינָהּ מְקַבֶּלֶת שַׁבָּת בְּהַדְלָקַת הַנֵּרוֹת — מָה עָלֶיהָ לַעֲשׂוֹת?",["לְקַבֵּל אֶת הַשַּׁבָּת רַק אַחֲרֵי שְׁקִיעַת הַחַמָּה הַמְּלֵאָה","הִיא פְּטוּרָה לְגַמְרֵי מִמִּצְוַת תּוֹסֶפֶת שַׁבָּת","לוֹמַר בַּפֶּה ״בּוֹאִי כַּלָּה״ כַּמָּה דַּקּוֹת לִפְנֵי הַשְּׁקִיעָה","לְהַדְלִיק נֵרוֹת נוֹסָפִים אַחֲרֵי צֵאת הַכּוֹכָבִים"],2,"נָשִׁים אֵלּוּ חַיָּבוֹת בְּתוֹסֶפֶת שַׁבָּת, וּמְקַיְּמוֹת אוֹתָהּ לְכָל הַמְּאֻחָר כַּמָּה דַּקּוֹת לִפְנֵי הַשְּׁקִיעָה בַּאֲמִירָה: ״הֲרֵינִי מְקַבֶּלֶת עַל עַצְמִי אֶת קְדֻשַּׁת הַשַּׁבָּת״ אוֹ ״בּוֹאִי כַּלָּה״.","פֶּרֶק מ״א, הֲלָכָה ד׳","קַבָּלַת שַׁבָּת"],["עַד מָתַי צְרִיכִים הַגְּבָרִים לְסַיֵּם אֶת תְּפִלַּת מִנְחָה בְּעֶרֶב שַׁבָּת?",["כַּמָּה דַּקּוֹת לִפְנֵי הַשְּׁקִיעָה לְכָל הַמְּאֻחָר","עַד צֵאת הַכּוֹכָבִים בְּלֵיל הַשַּׁבָּת","עַד חֲצוֹת הַלַּיְלָה שֶׁל לֵיל שַׁבָּת","שָׁעָה שְׁלֵמָה אַחֲרֵי שְׁקִיעַת הַחַמָּה בְּיוֹם שִׁשִּׁי"],0,"גְּבָרִים מְקַבְּלִים שַׁבָּת בַּאֲמִירָה, וְלָכֵן מַקְפִּידִים לְסַיֵּם מִנְחָה כַּמָּה דַּקּוֹת לִפְנֵי הַשְּׁקִיעָה, וְאָז אוֹמְרִים ״הֲרֵינִי מְקַבֵּל עַל עַצְמִי קְדֻשַּׁת הַשַּׁבָּת״.","פֶּרֶק מ״א, הֲלָכָה ה׳","קַבָּלַת שַׁבָּת"],["מֵאֵיזֶה זְמַן אֶפְשָׁר לְהַקְדִּים וּלְקַבֵּל אֶת קְדֻשַּׁת הַשַּׁבָּת?",["מִזְּמַן תְּפִלַּת שַׁחֲרִית שֶׁל יוֹם שִׁשִּׁי","מִפְּלַג הַמִּנְחָה, שָׁעָה וָרֶבַע זְמַנִּיּוֹת לִפְנֵי הַשְּׁקִיעָה","רַק בְּדִיּוּק בְּרֶגַע שְׁקִיעַת הַחַמָּה עַצְמָהּ","מִיּוֹם חֲמִישִׁי בָּעֶרֶב, לִפְנֵי שֶׁהַשָּׁבוּעַ נִגְמָר"],1,"הָרוֹצִים לְהַקְדִּים יְכוֹלִים לְקַבֵּל שַׁבָּת הָחֵל מִפְּלַג הַמִּנְחָה, שֶׁהוּא שָׁעָה וָרֶבַע זְמַנִּיּוֹת לִפְנֵי הַשְּׁקִיעָה.","פֶּרֶק מ״א, הֲלָכָה ו׳","קַבָּלַת שַׁבָּת"],["מִי חִבֵּר אֶת הַפִּיּוּט ״לְכָה דוֹדִי״ שֶׁאוֹמְרִים בְּקַבָּלַת שַׁבָּת?",["רַבִּי חֲנִינָא, שֶׁהָיָה יוֹצֵא לִקְרַאת שַׁבָּת הַמַּלְכָּה","רַבִּי יַנַּאי, שֶׁהָיָה לוֹבֵשׁ בִּגְדֵי שַׁבָּת","רַבִּי שְׁלֹמֹה אֶלְקָבֵץ, שֶׁחַי בִּתְקוּפַת מְקֻבָּלֵי צְפַת","רַבִּי שִׁמְעוֹן, שֶׁלִּמֵּד עַל תּוֹסֶפֶת שַׁבָּת"],2,"בִּתְקוּפַת הַמְּקֻבָּלִים בִּצְפַת חַי רַבִּי שְׁלֹמֹה אֶלְקָבֵץ, וְחִבֵּר אֶת ״לְכָה דוֹדִי״. הַמִּנְהָג הוּא לְאָמְרוֹ לִפְנֵי ״מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת״.","פֶּרֶק מ״א, הֲלָכָה ז׳","קַבָּלַת שַׁבָּת"],["מַדּוּעַ הוֹפְכִים אֶת הַפָּנִים לְצַד מַעֲרָב בַּבַּיִת הָאַחֲרוֹן שֶׁל ״לְכָה דוֹדִי״?",["כִּי שָׁם יוֹשְׁבִים הַחַזָּנִים בִּזְמַן הַתְּפִלָּה","כִּי כָּךְ מִסְתַּכְּלִים עַל הַכּוֹכָבִים הָרִאשׁוֹנִים","כִּי בְּצַד מַעֲרָב נִמְצֵאת תָּמִיד דֶּלֶת בֵּית הַכְּנֶסֶת","כִּי שָׁם שְׁקִיעַת הַשֶּׁמֶשׁ הַמְּבַשֶּׂרֶת עַל בּוֹא הַשַּׁבָּת"],3,"הָאֲרִ״י קִבֵּל שַׁבָּת בַּשָּׂדֶה כְּשֶׁהוּא פּוֹנֶה לְמַעֲרָב, מְקוֹם שְׁקִיעַת הַחַמָּה הַמְּבַשֶּׂרֶת עַל בּוֹא הַשַּׁבָּת. בִּקְהִלּוֹת הַסְּפָרַדִּים פּוֹנִים לְמַעֲרָב מִ״מִּזְמוֹר לְדָוִד״ עַד סוֹף ״לְכָה דוֹדִי״.","פֶּרֶק מ״א, הֲלָכָה ח׳","קַבָּלַת שַׁבָּת"],["לָמָּה יֵשׁ נוֹהֲגִים לוֹמַר בְּעֶרֶב שַׁבָּת אֶת הַפֶּרֶק ״בַּמֶּה מַדְלִיקִין״?",["כְּדֵי לְהַאֲרִיךְ אֶת הַתְּפִלָּה עַד שֶׁיַּחְשִׁיךְ לְגַמְרֵי","כְּדֵי לִזְכֹּר אֶת שְׁלוֹשֶׁת הַדְּבָרִים שֶׁאוֹמְרִים בְּעֶרֶב שַׁבָּת","כִּי זֶה הַפֶּרֶק הָרִאשׁוֹן שֶׁל מַסֶּכֶת בְּרָכוֹת","כְּדֵי לִלְמֹד אֵיךְ מַדְלִיקִים נֵרוֹת חֲנֻכָּה בְּתוֹךְ הַבַּיִת"],1,"״בַּמֶּה מַדְלִיקִין״ הוּא הַפֶּרֶק הַשֵּׁנִי שֶׁל מַסֶּכֶת שַׁבָּת, וְאוֹמְרִים אוֹתוֹ כְּדֵי לִזְכֹּר אֶת שְׁלוֹשֶׁת הַדְּבָרִים שֶׁאָדָם אוֹמֵר בְּבֵיתוֹ לִקְרַאת הַחֲשֵׁכָה. יֵשׁ אוֹמְרִים אוֹתוֹ בְּתוֹךְ קַבָּלַת שַׁבָּת, יֵשׁ אַחֲרֶיהָ, וְיֵשׁ אוֹמְרִים ״כְּגַוְנָא״ בִּמְקוֹמוֹ.","פֶּרֶק מ״א, הֲלָכוֹת ט׳-י׳","קַבָּלַת שַׁבָּת"],["מֵאֵיפֹה לְמֵדִים שֶׁמִּצְוָה לְקַדֵּשׁ אֶת הַשַּׁבָּת?",["מֵהַפָּסוּק זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ","רַק מִמִּנְהַג יִשְׂרָאֵל, וְאֵין לָזֶה מָקוֹר","מִתַּקָּנַת חֲכָמִים בִּלְבַד, לֹא מֵהַתּוֹרָה","מִסִּפּוּר בְּרִיאַת הָעוֹלָם בְּסֵפֶר בְּרֵאשִׁית"],0,"מִצְוַת עֲשֵׂה מֵהַתּוֹרָה: ״זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ״ – בְּקִדּוּשׁ בִּכְנִיסָתוֹ וּבְהַבְדָּלָה בִּיצִיאָתוֹ.","פֶּרֶק מ״ב, הֲלָכָה א׳","קִדּוּשׁ עַל הַיַּיִן"],["לְפִי תַּקָּנַת חֲכָמִים, עַל מָה מְקַדְּשִׁים לְכַתְּחִלָּה, גַּם אִם הוּא יָקָר?",["עַל לֶחֶם, כִּי הוּא זוֹל וּפָשׁוּט יוֹתֵר","עַל כּוֹס מַיִם קָרִים מִן הַבֶּרֶז","דַּוְקָא עַל הַיַּיִן, בַּלַּיְלָה וְגַם בַּיּוֹם","עַל כָּל מַשְׁקֶה שֶׁיֵּשׁ בַּבַּיִת"],2,"חֲכָמִים תִּקְּנוּ לְקַדֵּשׁ לְכַתְּחִלָּה דַּוְקָא עַל הַיַּיִן, וְגַם אִם הוּא יָקָר – מְקַדְּשִׁים עָלָיו קִדּוּשׁ הַלַּיְלָה וְקִדּוּשׁ הַיּוֹם.","פֶּרֶק מ״ב, הֲלָכָה ב׳","קִדּוּשׁ עַל הַיַּיִן"],["מָה הַדִּין שֶׁל נָשִׁים בְּמִצְוַת הַקִּדּוּשׁ?",["פְּטוּרוֹת, כִּי זוֹ מִצְוָה שֶׁהַזְּמַן גְּרָמָהּ","חַיָּבוֹת מִן הַתּוֹרָה וִיכוֹלוֹת לְהוֹצִיא אֶת הַגְּבָרִים","חַיָּבוֹת, אֲבָל אֵינָן יְכוֹלוֹת לְהוֹצִיא גְּבָרִים","חַיָּבוֹת רַק מִדְּרַבָּנָן, כְּמִנְהַג בְּעָלְמָא"],1,"״זָכוֹר וְשָׁמוֹר בְּדִבּוּר אֶחָד נֶאֶמְרוּ״ – מִי שֶׁחַיָּב בִּשְׁמִירַת הַשַּׁבָּת חַיָּב גַּם בִּזְכִירָתָהּ. לָכֵן נָשִׁים חַיָּבוֹת מִן הַתּוֹרָה, וִיכוֹלוֹת לְהוֹצִיא אֶת הַגְּבָרִים.","פֶּרֶק מ״ב, הֲלָכוֹת ג׳-ד׳","קִדּוּשׁ עַל הַיַּיִן"],["מָה עוֹשִׂים כְּשֶׁחוֹזְרִים בְּלֵיל שַׁבָּת מִבֵּית הַכְּנֶסֶת?",["מְחַכִּים שָׁעָה אֲרֻכָּה וְרַק אָז מְקַדְּשִׁים","קוֹרְאִים קֹדֶם סֵפֶר וְאַחַר כָּךְ מְקַדְּשִׁים","מְמַהֲרִים לְקַדֵּשׁ וְלֶאֱכֹל מִיָּד, בְּלִי עִכּוּבִים","הוֹלְכִים לִישֹׁן וּמְקַדְּשִׁים רַק בַּבֹּקֶר"],2,"יֵשׁ לְמַהֵר לְקַדֵּשׁ וְלֶאֱכֹל מִיָּד כְּשֶׁחוֹזְרִים מִבֵּית הַכְּנֶסֶת, לְלֹא עִכּוּבִים.","פֶּרֶק מ״ב, הֲלָכָה ה׳","קִדּוּשׁ עַל הַיַּיִן"],["כַּמָּה יַיִן צָרִיךְ הַמְּקַדֵּשׁ לִשְׁתּוֹת לְכַתְּחִלָּה?",["מְלוֹא לֻגְמָיו, וּמִן הַמֻּבְחָר רְבִיעִית שְׁלֵמָה","טִפָּה אַחַת קְטַנָּה בִּלְבַד מִן הַכּוֹס","אֶת כָּל הַבַּקְבּוּק עַד הַסּוֹף מַמָּשׁ","אֵין צֹרֶךְ לִשְׁתּוֹת, מַסְפִּיק לְהָרִיחַ"],0,"הַכּוֹס מְכִילָה לְפָחוֹת רְבִיעִית. הַמְּקַדֵּשׁ שׁוֹתֶה מְלוֹא לֻגְמָיו (כְּרֹב רְבִיעִית), וּמִצְוָה מִן הַמֻּבְחָר לִשְׁתּוֹת רְבִיעִית שְׁלֵמָה.","פֶּרֶק מ״ב, הֲלָכוֹת ו׳-ז׳","קִדּוּשׁ עַל הַיַּיִן"],["הַמְּקַדֵּשׁ שָׁתָה מְעַט, וְכָל מְסֻבָּה שָׁתָה מְעַט, וּבְסַךְ הַכֹּל שָׁתוּ מְלוֹא לֻגְמָיו. מָה הַדִּין?",["לֹא יָצְאוּ, וְצָרִיךְ לַחֲזֹר עַל הַקִּדּוּשׁ","רַק הַמְּקַדֵּשׁ יָצָא, וְהַשְּׁאָר לֹא יָצְאוּ","רַק מִי שֶׁשָּׁתָה רִאשׁוֹן יָצָא יְדֵי חוֹבָה","בְּדִיעֲבַד כֻּלָּם יָצְאוּ יְדֵי חוֹבַת הַקִּדּוּשׁ"],3,"אִם אֶחָד הַמְּסֻבִּים שָׁתָה מְלוֹא לֻגְמָיו – כֻּלָּם יָצְאוּ. וְאִם כָּל אֶחָד שָׁתָה מְעַט וּבְסַךְ הַכֹּל מְלוֹא לֻגְמָיו – יָצְאוּ בְּדִיעֲבַד.","פֶּרֶק מ״ב, הֲלָכוֹת ח׳-ט׳","קִדּוּשׁ עַל הַיַּיִן"],["אִם הַמְּקַדֵּשׁ שָׁתָה מְלוֹא לֻגְמָיו, לָמָּה רָאוּי שֶׁכֻּלָּם יִטְעֲמוּ?",["כְּדֵי שֶׁלֹּא יִשָּׁאֵר יַיִן בַּכּוֹס","מִשּׁוּם חִבּוּב מִצְוָה, כִּי הַמִּצְוָה חֲבִיבָה","כִּי בְּלִי זֶה אַף אֶחָד לֹא יָצָא","כְּדֵי לִבְדֹּק שֶׁהַיַּיִן טָעִים וּמָתוֹק"],1,"גַּם כְּשֶׁהַמְּקַדֵּשׁ שׁוֹתֶה כְּשִׁעוּר, רָאוּי שֶׁכֻּלָּם יִטְעֲמוּ מִכּוֹס הַקִּדּוּשׁ – מִשּׁוּם חִבּוּב מִצְוָה.","פֶּרֶק מ״ב, הֲלָכָה י׳","קִדּוּשׁ עַל הַיַּיִן"],["מִי שֶׁעוֹשֶׂה קִדּוּשׁ בַּבֹּקֶר בְּבֵית הַכְּנֶסֶת, וְהַסְּעוּדָה מְאֻחֶרֶת – מָה יַקְפִּיד?",["לָלֶכֶת הַבַּיְתָה מִיָּד בְּלִי לֶאֱכֹל כְּלוּם","לִשְׁמֹעַ אֶת הַקִּדּוּשׁ וְלֹא לִטְעֹם מִמֶּנּוּ","לֶאֱכֹל שָׁם כַּזַּיִת מְזוֹנוֹת, אוֹ לִשְׁתּוֹת רְבִיעִית יַיִן","לֶאֱכֹל רַק פֵּרוֹת וִירָקוֹת בְּבֵית הַכְּנֶסֶת"],2,"הַנּוֹהֲגִים לְקַדֵּשׁ וְלֶאֱכֹל אַחַר כָּךְ יֹאכְלוּ בִּמְקוֹם הַקִּדּוּשׁ לְפָחוֹת כַּזַּיִת מְזוֹנוֹת, וְאִם אִי אֶפְשָׁר – יִשְׁתּוּ לְפָחוֹת רְבִיעִית יַיִן.","פֶּרֶק מ״ב, הֲלָכָה י״א","קִדּוּשׁ עַל הַיַּיִן"],["בִּרְכַּת הַגֶּפֶן שֶׁל הַקִּדּוּשׁ פּוֹטֶרֶת אֵילוּ מַשְׁקָאוֹת?",["רַק אֶת הַמַּיִם שֶׁבַּכּוֹס הַקְּטַנָּה","אֶת כָּל הַמַּשְׁקָאוֹת הָרְגִילִים, בִּתְנַאי שֶׁשּׁוֹתִים מֵהַיַּיִן","שׁוּם מַשְׁקֶה, צָרִיךְ לְבָרֵךְ עַל כָּל אֶחָד","רַק מַשְׁקָאוֹת שֶׁנִּקְנוּ לִכְבוֹד שַׁבָּת קֹדֶשׁ"],1,"הִיא פּוֹטֶרֶת אֶת הַמַּשְׁקָאוֹת שֶׁעַל הַשֻּׁלְחָן וְאֶת הַמַּשְׁקָאוֹת שֶׁרְגִילִים לִשְׁתּוֹת, גַּם אִם לֹא הָיוּ עַל הַשֻּׁלְחָן – בִּתְנַאי שֶׁשּׁוֹתִים מֵהַיַּיִן.","פֶּרֶק מ״ב, הֲלָכָה י״ב","קִדּוּשׁ עַל הַיַּיִן"],["אֵין יַיִן וְאֵין מִיץ עֲנָבִים. עַל מָה מְקַדְּשִׁים?",["אֵין עוֹשִׂים קִדּוּשׁ כְּלָל בְּאוֹתָהּ שַׁבָּת","בַּלַּיְלָה עַל תֵּה, וּבַבֹּקֶר עַל מַשְׁקֶה קַל","בַּלַּיְלָה עַל מַיִם, וּבַבֹּקֶר עַל עוּגָה","בַּלַּיְלָה עַל הַפַּת, וּבַבֹּקֶר עַל חֲמַר מְדִינָה"],3,"בַּלַּיְלָה מְקַדְּשִׁים עַל הַפַּת, וּבַבֹּקֶר עַל חֲמַר מְדִינָה וּמְבָרְכִים ״שֶׁהַכֹּל״. חֲמַר מְדִינָה הוּא מַשְׁקֶה חָשׁוּב – לֹא תֵּה וְלֹא מַשְׁקֶה קַל.","פֶּרֶק מ״ב, הֲלָכוֹת י״ג-י״ד","קִדּוּשׁ עַל הַיַּיִן"],["כְּנֶגֶד מָה הַסְּעוּדָה הַשְּׁלִישִׁית בְּצָהֳרֵי הַשַּׁבָּת?",["הִיא כְּנֶגֶד הַשַּׁבָּת שֶׁבָּהּ נִתְּנָה הַתּוֹרָה","הִיא כְּנֶגֶד הַשַּׁבָּת שֶׁל יְצִיאַת מִצְרַיִם","הִיא כְּנֶגֶד הַשַּׁבָּת שֶׁלֶּעָתִיד לָבֹא","הִיא כְּנֶגֶד שַׁבַּת בְּרֵאשִׁית הָרִאשׁוֹנָה"],2,"הַסְּעוּדָה הָרִאשׁוֹנָה כְּנֶגֶד שַׁבַּת בְּרֵאשִׁית, הַשְּׁנִיָּה כְּנֶגֶד הַשַּׁבָּת שֶׁבָּהּ נִתְּנָה הַתּוֹרָה, וְהַשְּׁלִישִׁית כְּנֶגֶד הַשַּׁבָּת שֶׁלֶּעָתִיד לָבֹא.","פֶּרֶק מ״ג, הֲלָכָה א׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["אֵיךְ צְרִיכוֹת לִהְיוֹת סְעוּדוֹת הַשַּׁבָּת?",["בִּמְהִירוּת, כְּדֵי לְהַסְפִּיק לָלֶכֶת לָנוּחַ","בְּשֶׁקֶט גָּמוּר, בְּלִי שִׁירָה וּבְלִי דִּבּוּר","רַק עִם לֶחֶם, בְּלִי שׁוּם מַאֲכָל אַחֵר","בְּנַחַת וּבְשִׂמְחָה, עִם זְמִירוֹת וְדִבְרֵי תּוֹרָה"],3,"סְעוּדוֹת הַשַּׁבָּת צְרִיכוֹת לִהְיוֹת בְּנַחַת וּבְשִׂמְחָה, עִם זְמִירוֹת שַׁבָּת, שִׁירֵי קֹדֶשׁ וְדִבְרֵי תּוֹרָה מִפָּרָשַׁת הַשָּׁבוּעַ.","פֶּרֶק מ״ג, הֲלָכָה ב׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["עַל מָה מְבָרְכִים ״הַמּוֹצִיא״ בַּסְּעוּדָה הַשְּׁלִישִׁית?",["יֵשׁ לְהַחְמִיר בְּלֶחֶם מִשְׁנֶה, וְיֵשׁ מְקִלִּים בְּלֶחֶם אֶחָד","רַק עַל פְּרוּסַת לֶחֶם, כִּי זוֹ סְעוּדָה קְטַנָּה","עַל שָׁלוֹשׁ כִּכָּרוֹת, כְּנֶגֶד שָׁלוֹשׁ הַסְּעוּדוֹת שֶׁל שַׁבָּת","בַּסְּעוּדָה הַשְּׁלִישִׁית אֵין מְבָרְכִים כְּלָל ״הַמּוֹצִיא״"],0,"בִּשְׁתֵּי הַסְּעוּדוֹת הָרִאשׁוֹנוֹת מְבָרְכִים עַל לֶחֶם מִשְׁנֶה. בַּשְּׁלִישִׁית יֵשׁ לְהַחְמִיר וּלְבָרֵךְ עַל לֶחֶם מִשְׁנֶה, וְיֵשׁ מְקִלִּים לְבָרֵךְ עַל לֶחֶם אֶחָד שָׁלֵם.","פֶּרֶק מ״ג, הֲלָכוֹת ג׳-ד׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מִי מֵאֵלֶּה פָּטוּר מִשָּׁלוֹשׁ סְעוּדוֹת בְּשַׁבָּת?",["נָשִׁים, כִּי הֵן פְּטוּרוֹת מִסְּעוּדוֹת שַׁבָּת","אָדָם חוֹלֶה שֶׁקָּשֶׁה לוֹ לֶאֱכֹל","מִי שֶׁאֵין לוֹ זְמַן לָשֶׁבֶת לֶאֱכֹל","עָנִי שֶׁמִּתְפַּרְנֵס מִן הַצְּדָקָה שֶׁנּוֹתְנִים לוֹ"],1,"חוֹלֶה שֶׁקָּשֶׁה לוֹ לֶאֱכֹל פָּטוּר. אֲבָל גַּם נָשִׁים חַיָּבוֹת, וַאֲפִלּוּ עָנִי שֶׁמִּתְפַּרְנֵס מֵהַצְּדָקָה חַיָּב לִסְעֹד שָׁלוֹשׁ סְעוּדוֹת.","פֶּרֶק מ״ג, הֲלָכוֹת ה׳-ז׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מָה נָכוֹן לְגַבֵּי אֲכִילַת לֶחֶם בִּסְעוּדוֹת הַשַּׁבָּת?",["רַק בִּסְעוּדַת הָעֶרֶב חַיָּבִים לֶאֱכֹל לֶחֶם, וְלֹא בַּבֹּקֶר","בְּשַׁבָּת אֵין חוֹבָה לֶאֱכֹל לֶחֶם בְּשׁוּם סְעוּדָה","בָּעֶרֶב וּבַבֹּקֶר חוֹבָה, וְגַם בַּשְּׁלִישִׁית יֵשׁ לֶאֱכֹל לֶחֶם","בַּסְּעוּדָה הַשְּׁלִישִׁית אָסוּר לֶאֱכֹל לֶחֶם, רַק פֵּרוֹת"],2,"בָּעֶרֶב וּבַבֹּקֶר חַיָּבִים לֶאֱכֹל לֶחֶם (רָאוּי כַּבֵּיצָה, וּלְמִי שֶׁקָּשֶׁה – כַּזַּיִת). גַּם בַּשְּׁלִישִׁית יֵשׁ לֶאֱכֹל לֶחֶם, וְהֶחָכָם לֹא יֹאכַל יוֹתֵר מִדַּי בַּסְּעוּדָה הַשְּׁנִיָּה כְּדֵי שֶׁיּוּכַל לֶאֱכֹל לֶחֶם בַּשְּׁלִישִׁית.","פֶּרֶק מ״ג, הֲלָכוֹת ח׳-ט׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["בְּשַׁבָּת נוֹהֲגִים לְהַאֲרִיךְ בְּנִגּוּנִים. מָה עוֹשִׂים אִם זְמַן קְרִיאַת שְׁמַע עוֹמֵד לַעֲבֹר?",["מְחַכִּים לַצִּבּוּר, גַּם אִם הַזְּמַן כְּבָר יַעֲבֹר","מְדַלְּגִים עַל קְרִיאַת שְׁמַע בְּאוֹתָהּ שַׁבָּת","מְבַקְּשִׁים מֵהַחַזָּן לְהַפְסִיק אֶת כָּל הַנִּגּוּנִים","קוֹרְאִים בְּיָחִיד בְּלִי בְּרָכוֹת, וְשׁוּב עִם הַצִּבּוּר"],3,"הַנִּגּוּן בַּתְּפִלָּה מְעוֹרֵר אֶת הַנֶּפֶשׁ, אֲבָל אִם זְמַן קְרִיאַת שְׁמַע עוֹמֵד לַעֲבֹר – קוֹרְאִים אוֹתָהּ בְּיָחִיד בְּלִי בִּרְכוֹתֶיהָ, וְכְשֶׁהַצִּבּוּר מַגִּיעַ לִקְרִיאַת שְׁמַע אוֹמְרִים אוֹתָהּ שֵׁנִית עִם בִּרְכוֹתֶיהָ.","פֶּרֶק מ״ד, הֲלָכוֹת א׳-ב׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מָה נָכוֹן לְגַבֵּי זְמַן תְּפִלַּת מוּסָף?",["רַק לִפְנֵי שַׁחֲרִית, כְּדֵי לְהַקְדִּים אֶת הַתְּפִלָּה הַחֲשׁוּבָה","עַד סוֹף שֶׁבַע שָׁעוֹת, וּמִתְפַּלְּלִים אוֹתָהּ תָּמִיד לִפְנֵי מִנְחָה","אַחֲרֵי שֶׁבַע שָׁעוֹת אֵין יוֹצְאִים בָּהּ יְדֵי חוֹבָה כְּלָל","תָּמִיד אַחֲרֵי מִנְחָה, כִּי מִנְחָה תְּדִירָה וּמְצוּיָה יוֹתֵר"],1,"מוּסָף מִיָּד אַחַר שַׁחֲרִית וְעַד סוֹף שֶׁבַע שָׁעוֹת; מִי שֶׁאִחֵר לֹא נָהַג כָּרָאוּי אַךְ יָצָא, כִּי בְּדִיעֲבַד זְמַנָּהּ כָּל הַיּוֹם. וּלְמַעֲשֶׂה נָהֲגוּ לְהִתְפַּלֵּל תָּמִיד מוּסָף לִפְנֵי מִנְחָה.","פֶּרֶק מ״ד, הֲלָכוֹת ג׳, ח׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מָה נוֹהֵג בִּתְפִלַּת מוּסָף שֶׁל שַׁבָּת?",["אֵין חֲזָרַת הַשַּׁ״ץ, כִּי כְּבָר הָיְתָה בְּשַׁחֲרִית","הַכֹּהֲנִים אֵינָם נוֹשְׂאִים כַּפַּיִם בִּתְפִלַּת מוּסָף","יֵשׁ חֲזָרַת הַשַּׁ״ץ, וְהַכֹּהֲנִים נוֹשְׂאִים כַּפַּיִם","כָּל אֶחָד מִתְפַּלֵּל לְבַד, בְּלִי שְׁלִיחַ צִבּוּר"],2,"גַּם בְּמוּסָף חוֹזֵר שְׁלִיחַ הַצִּבּוּר עַל הַתְּפִלָּה כְּמוֹ בִּשְׁאָר הַתְּפִלּוֹת, וְהַכֹּהֲנִים נוֹשְׂאִים כַּפַּיִם גַּם בִּתְפִלַּת מוּסָף.","פֶּרֶק מ״ד, הֲלָכוֹת ד׳-ה׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מָה הַדִּין לְגַבֵּי נָשִׁים וּתְפִלַּת מוּסָף?",["פְּטוּרוֹת, אֲבָל אִם רוֹצוֹת לְהִתְפַּלֵּל רַשָּׁאִיּוֹת","חַיָּבוֹת בָּהּ בְּדִיּוּק כְּמוֹ הָאֲנָשִׁים","אָסוּר לָהֶן לְהִתְפַּלֵּל מוּסָף בְּשׁוּם אֹפֶן","חַיָּבוֹת רַק כְּשֶׁהֵן נִמְצָאוֹת בְּבֵית הַכְּנֶסֶת"],0,"נָשִׁים פְּטוּרוֹת מִתְּפִלַּת מוּסָף, אַךְ נָשִׁים שֶׁרוֹצוֹת לְהִתְפַּלֵּל מוּסָף רַשָּׁאִיּוֹת לַעֲשׂוֹת זֹאת.","פֶּרֶק מ״ד, הֲלָכָה ו׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["מָה הַדִּין בַּאֲכִילָה לִפְנֵי תְּפִלַּת מוּסָף?",["אָסוּר לְגַמְרֵי, וְאֵין שׁוּם קְהִלָּה שֶׁנּוֹהֶגֶת כָּךְ","חוֹבָה לֶאֱכֹל סְעוּדָה שְׁלֵמָה לִפְנֵי מוּסָף","מֻתָּר רַק לִשְׁתּוֹת מַיִם, בְּלִי לְקַדֵּשׁ","מֻתָּר לְקַדֵּשׁ וְלֶאֱכֹל מְעַט, אַךְ רַבִּים נִמְנָעִים"],3,"מֵעִקַּר הַדִּין נִתָּן לְקַדֵּשׁ וְלֶאֱכֹל מְעַט לִפְנֵי מוּסָף, וְכָךְ נוֹהֲגִים קְהִלּוֹת רַבּוֹת בְּיָמִים שֶׁהַתְּפִלָּה אֲרֻכָּה, כְּמוֹ רֹאשׁ הַשָּׁנָה, אֲבָל רַבִּים נִמְנָעִים מִכָּךְ.","פֶּרֶק מ״ד, הֲלָכָה ז׳","שָׁלוֹשׁ סְעוּדוֹת וּתְפִלַּת מוּסָף"],["לָמָּה תִּקֵּן מֹשֶׁה רַבֵּנוּ לִקְרֹא בַּתּוֹרָה בְּשֵׁנִי וּבַחֲמִישִׁי?",["כִּי בְּיָמִים אֵלּוּ נִתְּנוּ הַלּוּחוֹת לְמֹשֶׁה בְּהַר סִינַי","כְּדֵי שֶׁלֹּא יַעַבְרוּ שְׁלוֹשָׁה יָמִים בְּלִי שְׁמִיעַת תּוֹרָה","כְּדֵי שֶׁיַּסְפִּיקוּ לְסַיֵּם אֶת כָּל הַתּוֹרָה בְּחֹדֶשׁ אֶחָד","כִּי בִּשְׁאָר הַיָּמִים בֵּית הַכְּנֶסֶת הָיָה סָגוּר"],1,"כָּךְ אֵין שְׁלוֹשָׁה יָמִים בְּלֹא תּוֹרָה. עֶזְרָא תִּקֵּן שֶׁבְּשֵׁנִי וַחֲמִישִׁי יַעֲלוּ שְׁלוֹשָׁה וְיִקְרְאוּ לְפָחוֹת עֲשָׂרָה פְּסוּקִים.","פֶּרֶק מ״ה, הֲלָכָה א׳","קְרִיאַת הַתּוֹרָה"],["לָמָּה הַכֹּהֵן וְהַלֵּוִי אֵינָם רַשָּׁאִים לִמְחֹל עַל כְּבוֹדָם?",["כִּי אָסוּר לְיִשְׂרָאֵל לַעֲלוֹת לַתּוֹרָה בְּשׁוּם מַצָּב","כִּי רַק כֹּהֵן וְלֵוִי יוֹדְעִים לְבָרֵךְ אֶת בִּרְכוֹת הַתּוֹרָה","כִּי תַּלְמִיד חָכָם אֵינוֹ צָרִיךְ לַעֲלוֹת לַתּוֹרָה כְּלָל","כְּדֵי שֶׁלֹּא תִּהְיֶה מַחֲלֹקֶת מִי גָּדוֹל מַסְפִּיק לְכָךְ"],3,"אִם הָיוּ מוֹחֲלִים, הָיְתָה מִתְעוֹרֶרֶת מַחֲלֹקֶת מִי גָּדוֹל מַסְפִּיק שֶׁרָאוּי לִמְחֹל עֲבוּרוֹ.","פֶּרֶק מ״ה, הֲלָכָה ב׳","קְרִיאַת הַתּוֹרָה"],["אֵין כֹּהֵן, וְיִשְׂרָאֵל עוֹלֶה רִאשׁוֹן. לָמָּה מַכְרִיזִים ״בִּמְקוֹם כֹּהֵן״?",["כְּדֵי שֶׁלֹּא יִטְעוּ לַחְשֹׁב שֶׁהָעוֹלֶה הוּא כֹּהֵן","כְּדֵי שֶׁהַכֹּהֲנִים בְּבָתֵּיהֶם יִשְׁמְעוּ וְיָבוֹאוּ מַהֵר","כִּי כָּךְ הָעוֹלֶה מְקַבֵּל דִּין שֶׁל כֹּהֵן לְתָמִיד","כְּדֵי שֶׁהַקָּהָל יַעֲנֶה ״אָמֵן״ בְּקוֹל רָם יוֹתֵר"],0,"הַהַכְרָזָה מוֹנַעַת טָעוּת, שֶׁלֹּא יַחְשְׁבוּ שֶׁהָעוֹלֶה כֹּהֵן.","פֶּרֶק מ״ה, הֲלָכָה ג׳","קְרִיאַת הַתּוֹרָה"],["אֵין לֵוִי בְּבֵית הַכְּנֶסֶת. מָה עוֹשִׂים?",["כֹּהֵן אַחֵר עוֹלֶה בִּמְקוֹם הַלֵּוִי, כְּדֵי לְכַבֵּד אוֹתוֹ","מְדַלְּגִים עַל הָעֲלִיָּה הַשְּׁנִיָּה וּמַמְשִׁיכִים לְיִשְׂרָאֵל","הַכֹּהֵן שֶׁעָלָה רִאשׁוֹן עוֹלֶה שׁוּב בִּמְקוֹם הַלֵּוִי","מְחַכִּים עַד שֶׁיַּגִּיעַ לֵוִי, וְרַק אָז מַמְשִׁיכִים"],2,"לֹא מַעֲלִים כֹּהֵן אַחֵר, כְּדֵי שֶׁלֹּא יַחְשְׁבוּ שֶׁהַכֹּהֵן הָרִאשׁוֹן פָּגוּם.","פֶּרֶק מ״ה, הֲלָכָה ד׳","קְרִיאַת הַתּוֹרָה"],["בְּאֵיזוֹ דֶּרֶךְ הוֹלֵךְ הָעוֹלֶה לַבִּימָה, וּבְאֵיזוֹ חוֹזֵר?",["בַּדֶּרֶךְ הָאֲרֻכָּה הוֹלֵךְ, וּבַדֶּרֶךְ הַקְּצָרָה חוֹזֵר","בַּדֶּרֶךְ הַקְּצָרָה הוֹלֵךְ, וּבַדֶּרֶךְ הָאֲרֻכָּה יוֹתֵר חוֹזֵר","תָּמִיד בְּאוֹתָהּ דֶּרֶךְ, גַּם בַּהֲלִיכָה וְגַם בַּחֲזָרָה","תָּמִיד מִצַּד שְׂמֹאל, כְּדֵי לֹא לְהַפְרִיעַ לַקָּהָל"],1,"מְמַהֲרִים אֶל הַתּוֹרָה וּמִתְעַכְּבִים בַּחֲזָרָה. אִם הַדְּרָכִים שָׁווֹת – עוֹלִים מִיָּמִין.","פֶּרֶק מ״ה, הֲלָכָה ה׳","קְרִיאַת הַתּוֹרָה"],["לָמָּה מְכַסִּים אֶת הַכְּתָב אוֹ גּוֹלְלִים לִפְנֵי הַבְּרָכָה?",["כְּדֵי שֶׁהָעוֹלֶה יוּכַל לָגַעַת בַּכְּתָב בְּיָד חֲשׂוּפָה","כְּדֵי שֶׁהַקְּלָף לֹא יִתְיַבֵּשׁ מֵהָאוֹר שֶׁבְּבֵית הַכְּנֶסֶת","כְּדֵי שֶׁבַּעַל הַקּוֹרֵא לֹא יִרְאֶה אֶת הַמָּקוֹם","כְּדֵי שֶׁלֹּא יַחְשְׁבוּ שֶׁהַבְּרָכוֹת כְּתוּבוֹת בְּסֵפֶר הַתּוֹרָה"],3,"כָּךְ לֹא יִטְעוּ שֶׁנֹּסַח הַבְּרָכוֹת כָּתוּב בַּסֵּפֶר. וְזָכוּר: אָסוּר לָגַעַת בַּסֵּפֶר בְּיָד חֲשׂוּפָה, וְיֵשׁ נוֹגְעִים בַּטַּלִּית.","פֶּרֶק מ״ה, הֲלָכוֹת ו׳-ז׳","קְרִיאַת הַתּוֹרָה"],["מָה עוֹשֶׂה הָעוֹלֶה בִּזְמַן שֶׁבַּעַל הַקּוֹרֵא קוֹרֵא?",["קוֹרֵא עִמּוֹ אֶת הַפְּסוּקִים מִלָּה בְּמִלָּה בְּלַחַשׁ","שׁוֹמֵעַ בְּשֶׁקֶט, וְאֵינוֹ מַבִּיט בְּסֵפֶר הַתּוֹרָה כְּלָל","קוֹרֵא אֶת הַפְּסוּקִים בְּקוֹל רָם יַחַד עִם הַקָּהָל","חוֹזֵר לִמְקוֹמוֹ וּמְחַכֶּה לְסוֹף הַקְּרִיאָה"],0,"בַּעַל הַקּוֹרֵא בְּקוֹל רָם וְהָעוֹלֶה בְּלַחַשׁ. אַחַר כָּךְ סוֹגֵר אוֹ מְכַסֶּה וּמְבָרֵךְ, וּבֵין עוֹלֶה לְעוֹלֶה נוֹהֲגִים לִסְגֹּר אוֹ לִגְלֹל.","פֶּרֶק מ״ה, הֲלָכוֹת ח׳-ט׳","קְרִיאַת הַתּוֹרָה"],["מָתַי מַגְבִּיהִים אֶת סֵפֶר הַתּוֹרָה בִּקְהִלּוֹת הַסְּפָרַדִּים?",["רַק לְאַחַר שֶׁמְּסַיְּמִים אֶת כָּל הַקְּרִיאָה בַּתּוֹרָה","בֵּין כָּל עוֹלֶה וְעוֹלֶה, שֶׁבַע פְּעָמִים בְּשַׁבָּת","לִפְנֵי תְּחִלַּת הַקְּרִיאָה, וּמַרְאִים לַצִּבּוּר אֶת הַכְּתָב","לְעוֹלָם לֹא מַגְבִּיהִים, אֶלָּא רַק פּוֹתְחִים אֶת הַתִּיק"],2,"הַסְּפָרַדִּים מַגְבִּיהִים לִפְנֵי הַקְּרִיאָה, וְהָאַשְׁכְּנַזִּים לְאַחַר הַקְּרִיאָה.","פֶּרֶק מ״ה, הֲלָכָה י׳","קְרִיאַת הַתּוֹרָה"],["מָה מֻתָּר לַעֲשׂוֹת בֵּין עֲלִיָּה לַעֲלִיָּה?",["לְדַבֵּר עַל כָּל דָּבָר, כִּי הַקְּרִיאָה הִפְסִיקָה","לָצֵאת לְכָל צֹרֶךְ, גַּם אִם לֹא נִשְׁאַר מִנְיָן","לָצֵאת רַק מִי שֶׁכְּבָר שָׁמַע אֶת הַקְּרִיאָה","לָצֵאת לְצֹרֶךְ גָּדוֹל, אִם נִשְׁאָרִים עֲשָׂרָה אֲנָשִׁים"],3,"בֵּין עֲלִיָּה לַעֲלִיָּה מֻתָּר לָצֵאת לְצֹרֶךְ גָּדוֹל אִם נִשְׁאָרִים עֲשָׂרָה. דִּבּוּר אָסוּר (וְיֵשׁ מַתִּירִים דִּבְרֵי תּוֹרָה).","פֶּרֶק מ״ה, הֲלָכוֹת י״א-י״ב","קְרִיאַת הַתּוֹרָה"],["כַּמָּה עוֹלִים לַתּוֹרָה בְּרֹאשׁ חֹדֶשׁ, וְהַאִם מַפְטִירִים?",["שְׁלוֹשָׁה עוֹלִים, וּמַפְטִירִים אַחֲרֵיהֶם בַּנָּבִיא","אַרְבָּעָה עוֹלִים, וְאֵין מַפְטִירִים בַּנָּבִיא","שִׁבְעָה עוֹלִים, כְּמוֹ בְּשַׁבָּת בַּבֹּקֶר","חֲמִשָּׁה עוֹלִים, וּמַפְטִירִים בַּנָּבִיא כְּמוֹ בְּיוֹם טוֹב"],1,"בְּרֹאשׁ חֹדֶשׁ וּבְחֹל הַמּוֹעֵד אַרְבָּעָה וְאֵין מַפְטִירִים.","פֶּרֶק מ״ה, הֲלָכָה י״ג","קְרִיאַת הַתּוֹרָה"],["כְּשֶׁעוֹלִים לַתּוֹרָה שְׁלוֹשָׁה אוֹ אַרְבָּעָה – מַה הַדִּין לְגַבֵּי הוֹסָפַת עוֹלִים?",["מוֹסִיפִים כַּמָּה עוֹלִים שֶׁרוֹצִים בְּלִי הַגְבָּלָה","אֵין מוֹסִיפִים עֲלֵיהֶם עוֹלִים נוֹסָפִים כְּלָל","מוֹסִיפִים רַק עוֹלֶה אֶחָד הַנִּקְרָא אַחֲרוֹן","מוֹסִיפִים רַק אִם מוֹכְרִים אֶת הָעֲלִיּוֹת"],1,"בְּשַׁבָּת מֻתָּר לְהוֹסִיף עוֹלִים, אֲבָל כְּשֶׁעוֹלִים שְׁלוֹשָׁה אוֹ אַרְבָּעָה – אֵין מוֹסִיפִים עֲלֵיהֶם.","פֶּרֶק מ״ה, הֲלָכָה י״ד","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["מַה נִּדְרָשׁ מִשְּׁלִיחַ הַצִּבּוּר הַקּוֹרֵא בַּתּוֹרָה?",["לָדַעַת אֶת כָּל הַהַפְטָרוֹת שֶׁל הַשָּׁנָה בְּעַל פֶּה","לִקְרֹא מַהֵר כְּדֵי שֶׁהַצִּבּוּר לֹא יִטְרַח","לִהְיוֹת הַזָּקֵן בְּיוֹתֵר מִכָּל הַמִּתְפַּלְּלִים בְּבֵית הַכְּנֶסֶת","לִהְיוֹת בָּקִי בַּפַּרְשִׁיּוֹת, בְּצוּרַת הָאוֹתִיּוֹת וּבַכְּתִיב"],3,"הַקּוֹרֵא צָרִיךְ לִהְיוֹת בָּקִי בַּפַּרְשִׁיּוֹת הַפְּתוּחוֹת וְהַסְּתוּמוֹת, בְּצוּרַת הָאוֹתִיּוֹת וּבַכְּתִיב, כִּי אָסוּר לִקְרֹא אֲפִלּוּ אוֹת אַחַת שֶׁלֹּא מִן הַכְּתָב.","פֶּרֶק מ״ה, הֲלָכוֹת ט״ו-ט״ז","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["אֵין בְּבֵית הַכְּנֶסֶת מִי שֶׁיּוֹדֵעַ לִקְרֹא בְּדִקְדּוּק וּבִטְעָמִים. מָה עוֹשִׂים?",["מְבַטְּלִים אֶת קְרִיאַת הַתּוֹרָה בְּאוֹתָהּ שַׁבָּת לְגַמְרֵי","קוֹרְאִים מִתּוֹךְ חֻמָּשׁ מֻדְפָּס בִּמְקוֹם סֵפֶר תּוֹרָה","קוֹרְאִים בִּבְרָכָה, וְאֶחָד עוֹמֵד לְיָדוֹ עִם חֻמָּשׁ","קוֹרְאִים בַּתּוֹרָה בְּלִי בְּרָכָה כְּלָל, רַק בְּשֶׁקֶט"],2,"קוֹרְאִים בַּתּוֹרָה בִּבְרָכָה כְּהִלְכָתָהּ, וְאֶחָד מֵהַקָּהָל עוֹמֵד עִם חֻמָּשׁ כְּדֵי לְהַחְזִיר אֶת הַקּוֹרֵא אִם יִטְעֶה.","פֶּרֶק מ״ה, הֲלָכָה י״ז","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["מַדּוּעַ תִּקְּנוּ חֲכָמִים לִקְרֹא בַּנְּבִיאִים?",["כִּי הַמַּלְכוּת גָּזְרָה שֶׁלֹּא יִקְרְאוּ בַּתּוֹרָה","כִּי לֹא הָיוּ מַסְפִּיק סִפְרֵי תּוֹרָה בַּדּוֹר","כִּי הַנְּבִיאִים בִּקְּשׁוּ שֶׁיִּקְרְאוּ אֶת דִּבְרֵיהֶם","כְּדֵי לְקַצֵּר אֶת הַתְּפִלָּה בְּשַׁבָּתוֹת וּבְמוֹעֲדִים"],0,"הַמַּלְכוּת גָּזְרָה שֶׁלֹּא יִקְרְאוּ בַּתּוֹרָה וְלֹא גָּזְרָה עַל הַנְּבִיאִים. גַּם אַחֲרֵי שֶׁבָּטְלָה הַגְּזֵרָה הִמְשִׁיכוּ, וְתִקְּנוּ בְּרָכָה אַחַת לְפָנֶיהָ וְאַרְבַּע אַחֲרֶיהָ.","פֶּרֶק מ״ה, הֲלָכָה י״ח","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["לְפִי הַהֶסְבֵּר הָרִאשׁוֹן, לָמָּה נִקְרֵאת הַקְּרִיאָה בַּנָּבִיא ״הַפְטָרָה״?",["מִלְּשׁוֹן פְּתִיחָה, כִּי בָּהּ מַתְחִילָה הַתְּפִלָּה","עַל שֵׁם נָבִיא שֶׁקָּרְאוּ לוֹ הַפְטָר","מִלְּשׁוֹן שִׂמְחָה, כִּי שָׁרִים אוֹתָהּ בְּנִגּוּן","מִלְּשׁוֹן סִיּוּם, כִּי בָּהּ מִסְתַּיֶּמֶת הַקְּרִיאָה"],3,"הַפְטָרָה – מִלְּשׁוֹן סִיּוּם. וְיֵשׁ אוֹמְרִים: כִּי בִּזְמַן הַגְּזֵרָה הָיוּ נִפְטָרִים בָּהּ מֵחוֹבַת הַקְּרִיאָה בַּתּוֹרָה.","פֶּרֶק מ״ה, הֲלָכָה י״ט","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["לָמָּה הַמַּפְטִיר קוֹרֵא קֹדֶם כַּמָּה פְּסוּקִים בַּתּוֹרָה?",["כְּדֵי שֶׁיִּהְיֶה לוֹ זְמַן לְהִתְכּוֹנֵן לַהַפְטָרָה","כְּדֵי שֶׁהַנָּבִיא לֹא יֵרָאֶה שָׁוֶה בַּחֲשִׁיבוּתוֹ לַתּוֹרָה","כְּדֵי שֶׁיּוּכְלוּ לִשְׁמֹעַ אֶת כָּל הַפָּרָשָׁה פַּעֲמַיִם","כְּדֵי שֶׁהַקּוֹרֵא הַקָּבוּעַ יָנוּחַ מְעַט בָּאֶמְצַע"],1,"כָּךְ יִהְיֶה בָּרוּר שֶׁקְּרִיאַת הַנָּבִיא אֵינָהּ שָׁוָה בַּחֲשִׁיבוּתָהּ לַקְּרִיאָה בַּתּוֹרָה.","פֶּרֶק מ״ה, הֲלָכָה כ׳","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["בְּשַׁבָּת, מָה עוֹשִׂים אַחֲרֵי שֶׁהָעוֹלִים מְסַיְּמִים אֶת הַפָּרָשָׁה?",["שָׁרִים שִׁיר שֶׁל שַׁבָּת וְאוֹמְרִים קִדּוּשׁ","מַחְזִירִים אֶת הַסֵּפֶר לָאָרוֹן וְאוֹמְרִים קַדִּישׁ שָׁלֵם","הַמַּפְטִיר קוֹרֵא מִיָּד בַּנָּבִיא בְּלִי לַעֲלוֹת","אוֹמְרִים חֲצִי קַדִּישׁ, וְאַחַר כָּךְ עוֹלֶה הַמַּפְטִיר"],3,"בְּשַׁבָּתוֹת וּמוֹעֲדִים הַמַּפְטִיר אֵינוֹ נֶחְשָׁב לְאֶחָד מֵהָעוֹלִים, לָכֵן אוֹמְרִים חֲצִי קַדִּישׁ, וְאָז הוּא קוֹרֵא כַּמָּה פְּסוּקִים בַּתּוֹרָה וְאַחַר כָּךְ אֶת הַהַפְטָרָה.","פֶּרֶק מ״ה, הֲלָכָה כ״א","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["הוֹצִיאוּ שְׁנֵי סִפְרֵי תּוֹרָה. בְּאֵיזֶה סֵפֶר קוֹרֵא הַמַּפְטִיר?",["קוֹרֵא בַּסֵּפֶר הָרִאשׁוֹן שֶׁהוֹצִיאוּ מִן הָאָרוֹן","קוֹרֵא בַּסֵּפֶר הָאַחֲרוֹן מִבֵּין הַסְּפָרִים שֶׁהוֹצִיאוּ","קוֹרֵא בְּכָל הַסְּפָרִים שֶׁהוֹצִיאוּ, זֶה אַחַר זֶה","קוֹרֵא בַּסֵּפֶר הַגָּדוֹל וְהַיָּפֶה בְּיוֹתֵר"],1,"כְּשֶׁמּוֹצִיאִים שְׁנַיִם אוֹ שְׁלוֹשָׁה סִפְרֵי תּוֹרָה – הַמַּפְטִיר קוֹרֵא בַּסֵּפֶר הָאַחֲרוֹן.","פֶּרֶק מ״ה, הֲלָכָה כ״ב","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["בְּמִנְחָה שֶׁל יוֹם הַכִּפּוּרִים – מִי הוּא הַמַּפְטִיר?",["הָעוֹלֶה הַשְּׁבִיעִי, כְּמוֹ בְּשַׁבָּת רְגִילָה","עוֹלֶה מְיֻחָד אַחֲרֵי חֲצִי קַדִּישׁ, כְּמוֹ בְּשַׁבָּת","הָעוֹלֶה הַשְּׁלִישִׁי לַתּוֹרָה, וְלֹא עוֹלֶה נוֹסָף","הַכֹּהֵן, שֶׁהוּא הָעוֹלֶה הָרִאשׁוֹן לַתּוֹרָה"],2,"בְּתַעֲנִית צִבּוּר וּבְמִנְחָה שֶׁל יוֹם הַכִּפּוּרִים הַמַּפְטִיר הוּא הָעוֹלֶה הַשְּׁלִישִׁי לַתּוֹרָה.","פֶּרֶק מ״ה, הֲלָכָה כ״ג","קְרִיאַת הַתּוֹרָה וְהַהַפְטָרָה"],["מָה הַטַּעַם שֶׁמְּאַחֲרִים אֶת עַרְבִית בְּמוֹצָאֵי שַׁבָּת?",["כְּדֵי שֶׁכֻּלָּם יַסְפִּיקוּ לְהַגִּיעַ מִן הַבַּיִת","כְּדֵי לְהַמְתִּין לַחַזָּן שֶׁיָּבוֹא בְּאִחוּר","כְּדֵי לְהוֹסִיף מֵחֹל עַל הַקֹּדֶשׁ","כְּדֵי לְקַצֵּר אֶת זְמַן סְעֻדָּה שְׁלִישִׁית"],2,"מְאַחֲרִים אֶת עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת כְּדֵי לְהוֹסִיף מֵחֹל עַל הַקֹּדֶשׁ.","פֶּרֶק מ״ו, הֲלָכָה א׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["בֵּין מָה לְמָה מַבְדִּילִים בִּתְפִלַּת ״אַתָּה חוֹנַנְתָּנוּ״?",["בֵּין יוֹם רִאשׁוֹן לְיוֹם שֵׁנִי בִּלְבַד","בֵּין בֹּקֶר לְעֶרֶב וּבֵין קַיִץ לְחֹרֶף","בֵּין שֻׁלְחָן לְכִסֵּא וּבֵין בַּיִת לְחָצֵר","בֵּין קֹדֶשׁ לְחֹל וּבֵין אוֹר לְחֹשֶׁךְ"],3,"בְּ״אַתָּה חוֹנַנְתָּנוּ״ אוֹמְרִים: ״לְהַבְדִּיל בֵּין קֹדֶשׁ לְחֹל וּבֵין אוֹר לְחֹשֶׁךְ וּבֵין יִשְׂרָאֵל לָעַמִּים וּבֵין יוֹם הַשְּׁבִיעִי לְשֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה״.","פֶּרֶק מ״ו, הֲלָכָה ב׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["מִי בֵּרֵךְ אֶת יִשְׂרָאֵל בְּ״וִיהִי נֹעַם״, וּמָתַי?",["מֹשֶׁה, כְּשֶׁסִּיְּמוּ אֶת מְלֶאכֶת הַמִּשְׁכָּן","אַהֲרֹן, כְּשֶׁיָּצְאוּ מִמִּצְרַיִם בְּיָד חֲזָקָה","דָּוִד, כְּשֶׁהֵבִיא אֶת הָאָרוֹן לִירוּשָׁלַיִם","יְהוֹשֻׁעַ, כְּשֶׁנִּכְנְסוּ כֻּלָּם לְאֶרֶץ יִשְׂרָאֵל"],0,"״וִיהִי נֹעַם״ הוּא מִזְמוֹר בְּרָכָה שֶׁבֵּרֵךְ מֹשֶׁה אֶת יִשְׂרָאֵל כְּשֶׁסִּיְּמוּ אֶת מְלֶאכֶת הַמִּשְׁכָּן, וְאַחֲרָיו אוֹמְרִים ״וְאַתָּה קָדוֹשׁ״.","פֶּרֶק מ״ו, הֲלָכָה ג׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["מַדּוּעַ הָאַשְׁכְּנַזִּים אֵינָם אוֹמְרִים ״וִיהִי נֹעַם״ כְּשֶׁיָּחוּל יוֹם טוֹב בַּשָּׁבוּעַ?",["כִּי בְּיוֹם טוֹב מִתְפַּלְּלִים תְּפִלָּה אֲרֻכָּה מְאֹד","כִּי צְרִיכִים שֶׁיִּהְיוּ לְפָנֵינוּ שִׁשָּׁה יְמֵי מַעֲשֶׂה","כִּי הַחַזָּן צָרִיךְ לָנוּחַ לִפְנֵי הֶחָג","כִּי הַמִּזְמוֹר נֶאֱמַר רַק בְּחֹדֶשׁ נִיסָן"],1,"אוֹמְרִים בּוֹ ״וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ״, וּצְרִיכִים שֶׁיִּהְיוּ לְפָנֵינוּ שִׁשָּׁה יְמֵי מַעֲשֶׂה - יְמֵי חֹל וְלֹא קֹדֶשׁ.","פֶּרֶק מ״ו, הֲלָכָה ד׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["מָה אוֹמְרִים בְּחֵלֶק מִקְּהִלּוֹת הַסְּפָרַדִּים בְּמוֹצָאֵי שַׁבָּתוֹת אֵלּוּ?",["רַק ״שִׁיר הַמַּעֲלוֹת״ וְאֶת ״אַשְׁרֵי יוֹשְׁבֵי בֵיתֶךָ״","אֵינָם אוֹמְרִים שׁוּם מִזְמוֹר וְשׁוּם פָּסוּק","רַק ״אֹרֶךְ יָמִים אַשְׂבִּיעֵהוּ״ וְאֶת ״וְאַתָּה קָדוֹשׁ״","אוֹמְרִים אֶת כָּל סֵפֶר תְּהִלִּים פַּעֲמַיִם"],2,"רֹב קְהִלּוֹת הַסְּפָרַדִּים אוֹמְרִים תָּמִיד ״וִיהִי נֹעַם״, וּבְחֵלֶק מֵהֶן אוֹמְרִים בְּשַׁבָּתוֹת אֵלּוּ רַק ״אֹרֶךְ יָמִים אַשְׂבִּיעֵהוּ וְאַרְאֵהוּ בִּישׁוּעָתִי״ וְאֶת ״וְאַתָּה קָדוֹשׁ״.","פֶּרֶק מ״ו, הֲלָכָה ד׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["לָמָּה יֵשׁ נוֹהֲגִים לְהַבְדִּיל עַל הַיַּיִן בְּבֵית הַכְּנֶסֶת?",["כְּדֵי שֶׁהַחַזָּן יִשְׁתֶּה אֶת כָּל הַיַּיִן","כְּדֵי שֶׁלֹּא יַבְדִּילוּ כְּלָל בַּבַּיִת אַחַר כָּךְ","כְּדֵי לְקַצֵּר אֶת תְּפִלַּת עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת","כְּדֵי לְהוֹצִיא אֶת מִי שֶׁאֵין לוֹ יַיִן בְּבֵיתוֹ"],3,"מַבְדִּילִים עַל הַיַּיִן בְּבֵית הַכְּנֶסֶת כְּדֵי לְהוֹצִיא יְדֵי חוֹבַת הַבְדָּלָה אֶת מִי שֶׁאֵין לוֹ יַיִן בְּבֵיתוֹ.","פֶּרֶק מ״ו, הֲלָכָה ה׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["מָתַי נִרְאִים שְׁלוֹשָׁה כּוֹכָבִים קְטַנִּים, לְפִי לוּחוֹת הַזְּמַנִּים?",["עֶשֶׂר דַּקּוֹת בְּדִיּוּק אַחֲרֵי הַשְּׁקִיעָה","שְׁלוֹשִׁים וּשְׁתַּיִם דַּקּוֹת אַחֲרֵי הַשְּׁקִיעָה","שָׁעָה שְׁלֵמָה לִפְנֵי שְׁקִיעַת הַחַמָּה","בְּדִיּוּק בְּאוֹתוֹ רֶגַע שֶׁהַשֶּׁמֶשׁ שׁוֹקַעַת"],1,"זְמַן צֵאת שְׁלוֹשָׁה כּוֹכָבִים הוּא שְׁלוֹשִׁים וּשְׁתַּיִם דַּקּוֹת אַחֲרֵי הַשְּׁקִיעָה. הָרוֹצֶה לְהַחְמִיר כְּרַבֵּנוּ תָּם, מַמְתִּין שָׁעָה וָחֵצִי.","פֶּרֶק מ״ו, הֲלָכָה ו׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["מִי שֶׁהִבְדִּיל בַּתְּפִלָּה וְעוֹד לֹא הִבְדִּיל עַל הַכּוֹס, מָה דִּינוֹ?",["אָסוּר לוֹ בִּמְלָאכָה עַד מָחָר בַּבֹּקֶר","מֻתָּר לוֹ רַק לְהַדְלִיק אוֹר בַּבַּיִת","מֻתָּר לוֹ לַעֲשׂוֹת מְלָאכָה כְּבָר עַכְשָׁו","אָסוּר לוֹ בִּמְלָאכָה עַד חֲצוֹת הַלַּיְלָה"],2,"לְאַחַר הַהַבְדָּלָה בַּתְּפִלָּה מֻתָּר לַעֲשׂוֹת מְלָאכָה, גַּם לִפְנֵי הַהַבְדָּלָה עַל הַכּוֹס.","פֶּרֶק מ״ו, הֲלָכָה ז׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["מָה עוֹשׂוֹת נָשִׁים שֶׁאֵינָן מַבְדִּילוֹת בַּתְּפִלָּה וּצְרִיכוֹת לַעֲשׂוֹת מְלָאכָה?",["מַמְתִּינוֹת עַד שֶׁיִּסְתַּיֵּם הַלַּיְלָה כֻּלּוֹ","אוֹמְרוֹת ״בָּרוּךְ הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל״","עוֹשׂוֹת מְלָאכָה מִיָּד בְּלִי לוֹמַר דָּבָר","שׁוֹתוֹת מְעַט יַיִן לִפְנֵי הַמְּלָאכָה"],1,"נָשִׁים שֶׁבְּדֶרֶךְ כְּלָל אֵינָן מַבְדִּילוֹת בַּתְּפִלָּה, יֹאמְרוּ ״בָּרוּךְ הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל״ לִפְנֵי שֶׁעוֹשׂוֹת מְלָאכָה. כָּךְ גַּם כָּל מִי שֶׁצָּרִיךְ לַעֲשׂוֹת מְלָאכָה לִפְנֵי שֶׁהִבְדִּיל בַּתְּפִלָּה.","פֶּרֶק מ״ו, הֲלָכָה ט׳","עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת וְהַבְדָּלָה בַּתְּפִלָּה"],["מָתַי מְקַדְּשִׁים אֶת הַשַּׁבָּת בְּדִבּוּר לְפִי הַתּוֹרָה?",["רַק בִּכְנִיסַת הַשַּׁבָּת בְּקִדּוּשׁ עַל הַיַּיִן","בִּכְנִיסַת הַשַּׁבָּת בְּקִדּוּשׁ וּבִיצִיאָתָהּ בְּהַבְדָּלָה","רַק בִּיצִיאַת הַשַּׁבָּת בְּהַבְדָּלָה עַל הַכּוֹס","בְּאֶמְצַע יוֹם הַשַּׁבָּת בִּשְׁעַת הַסְּעוּדָה"],1,"״זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ״ – בִּכְנִיסָתוֹ בְּקִדּוּשׁ וּבִיצִיאָתוֹ בְּהַבְדָּלָה. וַחֲכָמִים קָבְעוּ לְהַבְדִּיל גַּם בַּתְּפִלָּה וְגַם עַל הַכּוֹס.","פֶּרֶק מ״ז, הֲלָכָה א׳","הַבְדָּלָה עַל הַכּוֹס"],["מָה הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לַמַּבְדִּיל עַל הַיַּיִן?",["קוֹרֵא לוֹ חָכָם וְנוֹתֵן לוֹ עֹשֶׁר","קוֹרֵא לוֹ גִּבּוֹר וּמַאֲרִיךְ אֶת יָמָיו","קוֹרֵא לוֹ קָדוֹשׁ וְעוֹשֶׂה אוֹתוֹ סְגֻלָּה","אֵין לוֹ שׁוּם מַעֲלָה מְיֻחֶדֶת בִּכְלָל"],2,"הַמַּבְדִּיל עַל הַיַּיִן (אוֹ שׁוֹמֵעַ מֵאֲחֵרִים) נִקְרָא ׳קָדוֹשׁ׳ וְנַעֲשֶׂה סְגֻלָּה, כִּי הוּא נִפְרָד מִקְּדֻשַּׁת הַשַּׁבָּת בְּכָבוֹד.","פֶּרֶק מ״ז, הֲלָכָה ב׳","הַבְדָּלָה עַל הַכּוֹס"],["מָה הַסֵּדֶר הַנָּכוֹן שֶׁל הַהַבְדָּלָה?",["נֵר, יַיִן, בְּשָׂמִים, וְאַחַר כָּךְ הַבְדָּלָה","בְּשָׂמִים, נֵר, יַיִן, וְאַחַר כָּךְ הַבְדָּלָה","הַבְדָּלָה, יַיִן, נֵר, וְאַחַר כָּךְ בְּשָׂמִים","יַיִן, בְּשָׂמִים, נֵר, וְאַחַר כָּךְ הַבְדָּלָה"],3,"יַבְנֶ״ה: יַיִן, בְּשָׂמִים, נֵר, הַבְדָּלָה. אֶת הַכּוֹס וְאֶת הַבְּשָׂמִים אוֹחֲזִים בְּיַד יָמִין.","פֶּרֶק מ״ז, הֲלָכָה ג׳","הַבְדָּלָה עַל הַכּוֹס"],["כַּמָּה יַיִן צָרִיךְ לִשְׁתּוֹת אַחֲרֵי בִּרְכַּת הַמַּבְדִּיל?",["שִׁעוּר רְבִיעִית, וּבְדִיעֲבַד מְלוֹא לֻגְמָיו מַסְפִּיק","טִפָּה אַחַת קְטַנָּה בִּלְבַד, וְזֶה מַסְפִּיק","אֶת כָּל הַבַּקְבּוּק שֶׁעַל הַשֻּׁלְחָן כֻּלּוֹ","אָסוּר לִשְׁתּוֹת מִיֵּין הַהַבְדָּלָה בִּכְלָל"],0,"לְכַתְּחִלָּה שׁוֹתִים רְבִיעִית, וּבְדִיעֲבַד מִי שֶׁשָּׁתָה מְלוֹא לֻגְמָיו יָצָא יְדֵי חוֹבָה.","פֶּרֶק מ״ז, הֲלָכָה ד׳","הַבְדָּלָה עַל הַכּוֹס"],["מָה נָכוֹן לְגַבֵּי נֵר הַהַבְדָּלָה?",["מְבָרְכִים עַל נֵר קָטָן וְעוֹמְדִים רָחוֹק מִמֶּנּוּ","מְבָרְכִים עַל אֲבוּקָה וּמִתְקָרְבִים כְּדֵי לֵהָנוֹת מֵאוֹרָהּ","מְבָרְכִים עַל נוּרַת חַשְׁמַל וְסוֹגְרִים אֶת הָעֵינַיִם","אֵין צֹרֶךְ בְּנֵר כְּלָל בִּשְׁעַת הַהַבְדָּלָה"],1,"מִצְוָה מִן הַמֻּבְחָר לְבָרֵךְ עַל אֲבוּקָה שֶׁאוֹרָהּ רַב, וּמִתְקָרְבִים כָּךְ שֶׁאֶפְשָׁר לְהַבְחִין לְאוֹרָהּ בֵּין מַטְבְּעוֹת וּלְהִסְתַּכֵּל בַּיָּדַיִם וּבַצִּפָּרְנַיִם.","פֶּרֶק מ״ז, הֲלָכוֹת ה׳-ו׳","הַבְדָּלָה עַל הַכּוֹס"],["לָמָּה רַבִּים מְכַבִּים אֶת הַחַשְׁמַל בִּשְׁעַת בִּרְכַּת הַנֵּר?",["כְּדֵי לַחְסֹךְ בְּחַשְׁמַל בְּמוֹצָאֵי הַשַּׁבָּת","כְּדֵי שֶׁהַיְּלָדִים יֵלְכוּ מַהֵר לִישֹׁן","כִּי אָסוּר לְהַדְלִיק חַשְׁמַל כָּל הַלַּיְלָה","כְּדֵי שֶׁהַהֲנָאָה מֵאוֹר הַנֵּר תִּהְיֶה נִכֶּרֶת"],3,"כְּשֶׁהַחַשְׁמַל כָּבוּי, רוֹאִים הֵיטֵב שֶׁנֶּהֱנִים דַּוְקָא מֵאוֹר הַנֵּר.","פֶּרֶק מ״ז, הֲלָכָה ז׳","הַבְדָּלָה עַל הַכּוֹס"],["מָה דִּין אִשָּׁה שֶׁלֹּא שָׁמְעָה הַבְדָּלָה?",["הִיא פְּטוּרָה, כִּי זוֹ מִצְוָה לַגְּבָרִים בִּלְבַד","חַיֶּבֶת לְהַבְדִּיל בְּעַצְמָהּ, כִּי נָשִׁים חַיָּבוֹת בְּהַבְדָּלָה","תַּבְדִּיל רַק בַּשַּׁבָּת הַבָּאָה, בְּמוֹצָאֵי הַשַּׁבָּת","מַסְפִּיק שֶׁתַּדְלִיק נֵר וְלֹא תְּבָרֵךְ"],1,"נָשִׁים חַיָּבוֹת בְּהַבְדָּלָה כְּשֵׁם שֶׁהֵן חַיָּבוֹת בְּקִדּוּשׁ, לָכֵן מִי שֶׁלֹּא שָׁמְעָה – מַבְדִּילָה בְּעַצְמָהּ.","פֶּרֶק מ״ז, הֲלָכָה ח׳","הַבְדָּלָה עַל הַכּוֹס"],["מִי שֶׁהִבְדִּיל בַּתְּפִלָּה, מָתַי מֻתָּר לוֹ לֶאֱכֹל?",["רַק אַחֲרֵי שֶׁיַּבְדִּיל גַּם עַל הַכּוֹס","מִיָּד אַחֲרֵי הַתְּפִלָּה, כִּי כְּבָר הִבְדִּיל","מֻתָּר לוֹ לֶאֱכֹל כְּבָר מֵהַשְּׁקִיעָה","רַק לְמָחֳרָת בַּבֹּקֶר, אַחֲרֵי תְּפִלַּת שַׁחֲרִית"],0,"מִשְּׁקִיעַת הַחַמָּה אָסוּר לֶאֱכֹל וְלִשְׁתּוֹת עַד הַהַבְדָּלָה עַל הַכּוֹס – גַּם לְמִי שֶׁהִבְדִּיל בַּתְּפִלָּה אוֹ אָמַר ״בָּרוּךְ הַמַּבְדִּיל״.","פֶּרֶק מ״ז, הֲלָכוֹת ט׳-י״ב","הַבְדָּלָה עַל הַכּוֹס"],["מִי שֶׁהִתְחִיל סְעוּדָה שְׁלִישִׁית לִפְנֵי הַשְּׁקִיעָה, מָה דִּינוֹ?",["חַיָּב לְהַפְסִיק מִיָּד כְּשֶׁהַשֶּׁמֶשׁ שׁוֹקַעַת","חַיָּב לְהַבְדִּיל עַל הַכּוֹס בְּאֶמְצַע הַסְּעוּדָה","יָכוֹל לְהַמְשִׁיךְ לֶאֱכֹל גַּם אַחֲרֵי הַשְּׁקִיעָה","מֻתָּר לוֹ לִשְׁתּוֹת רַק מַיִם"],2,"הוּא יָכוֹל לְהַמְשִׁיךְ אֲפִלּוּ אַחֲרֵי צֵאת הַכּוֹכָבִים, וְטוֹב לְמַהֵר לְסַיֵּם. וּמַיִם לִפְנֵי הַהַבְדָּלָה – מֻתָּר, אַךְ נָהֲגוּ לְהַחְמִיר וְלֹא לִשְׁתּוֹת.","פֶּרֶק מ״ז, הֲלָכוֹת י׳-י״א","הַבְדָּלָה עַל הַכּוֹס"],["מִי שֶׁיֵּשׁ לוֹ מִיץ עֲנָבִים, הַאִם יָכוֹל לְהַבְדִּיל עַל בִּירָה?",["כֵּן, בִּירָה עֲדִיפָה תָּמִיד עַל מִיץ עֲנָבִים","כֵּן, מֻתָּר לִבְחֹר כָּל מַשְׁקֶה שֶׁהוּא רוֹצֶה","לֹא, חַיָּב לְהַבְדִּיל דַּוְקָא עַל מִיץ הָעֲנָבִים","לֹא, מִיץ עֲנָבִים פָּסוּל לְגַמְרֵי לְהַבְדָּלָה"],2,"מִי שֶׁיֵּשׁ לוֹ יַיִן אוֹ מִיץ עֲנָבִים חַיָּב לְהַבְדִּיל דַּוְקָא עֲלֵיהֶם. רַק מִי שֶׁאֵין לוֹ, מַבְדִּיל עַל חֲמַר מְדִינָה.","פֶּרֶק מ״ז, הֲלָכָה י״ג","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["לְפִי הַמִּנְהָג בִּקְהִלּוֹת הַסְּפָרַדִּים, אֵיזֶה מַשְׁקֶה נֶחְשָׁב חֲמַר מְדִינָה?",["גַּם מִיץ טִבְעִי וְגַם קָפֶה חַם","רַק מַשְׁקֶה מְשַׁכֵּר, כְּמוֹ בִּירָה אוֹ וִיסְקִי","כָּל מַשְׁקֶה קַל, כְּמוֹ תֵּה אוֹ גָּזוֹז","רַק מַיִם קָרִים מִן הַמַּעְיָן שֶׁבָּעִיר"],1,"יֵשׁ אוֹמְרִים שֶׁרַק מַשְׁקֶה מְשַׁכֵּר כְּמוֹ בִּירָה, וִיסְקִי וְכַדּוֹמֶה נֶחְשָׁב חֲמַר מְדִינָה, וְכָךְ נוֹהֲגִים בִּקְהִלּוֹת הַסְּפָרַדִּים.","פֶּרֶק מ״ז, הֲלָכָה י״ד","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["מַדּוּעַ יֵשׁ נוֹהֲגִים לְהַבְדִּיל בַּעֲמִידָה?",["כִּי הַהַבְדָּלָה כְּעֵין לִוּוּי לַשַּׁבָּת, וּמְלַוִּים בַּעֲמִידָה","כִּי אָסוּר לָשֶׁבֶת כְּלָל בְּמוֹצָאֵי הַשַּׁבָּת","כִּי כָּךְ רוֹאִים טוֹב יוֹתֵר אֶת הַנֵּר","כִּי הַיַּיִן נִשְׁפָּךְ כְּשֶׁיּוֹשְׁבִים לְיַד הַשֻּׁלְחָן"],0,"הַנּוֹהֲגִים לְהַבְדִּיל בַּעֲמִידָה, עוֹשִׂים כֵּן כִּי הַהַבְדָּלָה הִיא כְּעֵין לִוּוּי לַשַּׁבָּת, וְאֵין מְלַוִּים אֶלָּא בַּעֲמִידָה.","פֶּרֶק מ״ז, הֲלָכָה ט״ו","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["לָמָּה מְכַבִּים אֶת הַנֵּר בַּיַּיִן שֶׁל הַהַבְדָּלָה?",["כְּדֵי שֶׁהַיַּיִן יִהְיֶה מָתוֹק יוֹתֵר לִשְׁתִיָּה","לְהַדְגִּישׁ שֶׁהַנֵּר הֻדְלַק לְמִצְוָה וְלֹא לְשִׁמּוּשׁ אַחֵר","כִּי אָסוּר לְכַבּוֹת נֵר בְּמַיִם רְגִילִים","כִּי כָּךְ חוֹסְכִים אֶת הַשַּׁעֲוָה לְשָׁבוּעַ הַבָּא"],1,"מְכַבִּים אֶת הַנֵּר בַּיַּיִן כְּדֵי לְהַדְגִּישׁ שֶׁהִדְלִיקוּ אוֹתוֹ לְקַיֵּם בּוֹ אֶת מִצְוַת הַהַבְדָּלָה וְלֹא לְשִׁמּוּשׁ אַחֵר.","פֶּרֶק מ״ז, הֲלָכָה ט״ז","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["מַדּוּעַ יֵשׁ נוֹהֲגִים לָשִׂים מֵהַיַּיִן עַל הָעֵינַיִם?",["כְּדֵי לְרַפֵּא אֶת הָעֵינַיִם מִכָּל כְּאֵב","כִּי כָּךְ אֵין צֹרֶךְ לִשְׁתּוֹת מֵהַכּוֹס","כְּדֵי לְהִתְעוֹרֵר מֵהַשֵּׁינָה שֶׁל שַׁבָּת אַחַר הַצָּהֳרַיִם","מִשּׁוּם חִבּוּב מִצְוָה, כִּי הַיַּיִן שִׁמֵּשׁ לְמִצְוָה"],3,"יֵשׁ נוֹהֲגִים לָשִׂים מְעַט מֵהַיַּיִן שֶׁכִּבּוּ בּוֹ אֶת הַנֵּר עַל הָעֵינַיִם מִשּׁוּם חִבּוּב מִצְוָה.","פֶּרֶק מ״ז, הֲלָכָה י״ז","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["מַדּוּעַ מַזְכִּירִים אֶת אֵלִיָּהוּ הַנָּבִיא דַּוְקָא בְּמוֹצָאֵי שַׁבָּת?",["כִּי אֵלִיָּהוּ הַנָּבִיא נוֹלַד בְּמוֹצָאֵי שַׁבָּת לִפְנֵי שָׁנִים רַבּוֹת","כִּי הוּא בָּא לְבַקֵּר בְּכָל בַּיִת בְּעֶרֶב שַׁבָּת","כִּי עָבְרָה הַשַּׁבָּת, וְעַכְשָׁו הוּא יָכוֹל לְבַשֵּׂר גְּאֻלָּה","כִּי הוּא חִבֵּר אֶת כָּל שִׁירֵי הַהַבְדָּלָה שֶׁאָנוּ שָׁרִים"],2,"מֻבְטָח לְיִשְׂרָאֵל שֶׁאֵין אֵלִיָּהוּ בָּא בְּעַרְבֵי שַׁבָּתוֹת וְיָמִים טוֹבִים, לָכֵן כְּשֶׁעָבְרָה הַשַּׁבָּת מִתְפַּלְּלִים שֶׁיָּבוֹא וִיבַשֵּׂר אֶת הַגְּאֻלָּה.","פֶּרֶק מ״ז, הֲלָכָה י״ח","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["לָמָּה סוֹעֲדִים סְעוּדַת מְלַוֶּה מַלְכָּה?",["כְּדֵי לְסַיֵּם אֶת כָּל הָאֹכֶל שֶׁנִּשְׁאַר","כִּי אָסוּר לִישֹׁן בְּלִי לֶאֱכֹל בַּלַּיְלָה","כְּדֵי לְכַבֵּד אֶת הַשַּׁבָּת גַּם בִּזְמַן יְצִיאָתָהּ","כִּי בְּשַׁבָּת לֹא אָכְלוּ מַסְפִּיק סְעוּדוֹת שְׂבֵעוֹת"],2,"סוֹעֲדִים סְעוּדָה רְבִיעִית בְּמוֹצָאֵי שַׁבָּת כְּדֵי לְכַבֵּד אֶת הַשַּׁבָּת בִּיצִיאָתָהּ, וּמַעֲלָה גְּדוֹלָה יֵשׁ בָּהּ.","פֶּרֶק מ״ז, הֲלָכָה י״ט","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["מִי שֶׁקָּשֶׁה לוֹ לֶאֱכֹל לֶחֶם בִּמְלַוֶּה מַלְכָּה, מָה יַעֲשֶׂה?",["יְוַתֵּר עַל הַסְּעוּדָה וְיֵלֵךְ מִיָּד לִישֹׁן","יֹאכַל מַאֲכָלִים שֶׁבִּרְכָתָם בּוֹרֵא מִינֵי מְזוֹנוֹת","יֹאכַל אֶת הַסְּעוּדָה בְּיוֹם רִאשׁוֹן בַּבֹּקֶר","יִשְׁתֶּה רַק כּוֹס מַיִם וְיִסְתַּפֵּק בְּכָךְ"],1,"מִי שֶׁקָּשֶׁה לוֹ לֶאֱכֹל לֶחֶם בִּסְעוּדַת מְלַוֶּה מַלְכָּה, יֹאכַל מַאֲכָלִים שֶׁבִּרְכָתָם מְזוֹנוֹת.","פֶּרֶק מ״ז, הֲלָכָה כ׳","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["מִי שֶׁשָּׁכַח לְהַבְדִּיל וּמַבְדִּיל בְּיוֹם שֵׁנִי, עַל מָה יְבָרֵךְ?",["רַק עַל הַגֶּפֶן וְעַל הַמַּבְדִּיל, בְּלִי בְּשָׂמִים וָנֵר","עַל הַגֶּפֶן, הַבְּשָׂמִים, הַנֵּר וְגַם הַמַּבְדִּיל","רַק עַל הַנֵּר וְעַל הַבְּשָׂמִים, בְּלִי כּוֹס","אֵינוֹ מְבָרֵךְ כְּלוּם, כִּי עָבַר זְמַן הַהַבְדָּלָה"],0,"הַמַּבְדִּיל אַחֲרֵי מוֹצָאֵי שַׁבָּת (עַד סוֹף יוֹם שְׁלִישִׁי) מְבָרֵךְ ״בּוֹרֵא פְּרִי הַגֶּפֶן״ וְ״הַמַּבְדִּיל״, אֲבָל לֹא עַל הַבְּשָׂמִים וְעַל הַנֵּר.","פֶּרֶק מ״ז, הֲלָכָה כ״א","הַבְדָּלָה וּמְלַוֶּה מַלְכָּה"],["מָה כּוֹלֶלֶת הַמִּצְוָה ״שָׁמוֹר אֶת יוֹם הַשַּׁבָּת״?",["אֶת הַמִּצְוָה לְקַדֵּשׁ עַל הַיַּיִן בְּלֵיל שַׁבָּת","אֶת הַמִּצְוָה לְהִתְפַּלֵּל תְּפִלּוֹת מְיֻחָדוֹת בְּיוֹם הַשַּׁבָּת","אֶת הָאִסּוּר לַעֲשׂוֹת מְלָאכָה בְּיוֹם הַשַּׁבָּת","אֶת הַמִּצְוָה לֶאֱכֹל שָׁלֹשׁ סְעוּדוֹת בְּיוֹם הַשַּׁבָּת"],2,"״שָׁמוֹר״ כּוֹלֵל אֶת הָאִסּוּר לַעֲשׂוֹת מְלָאכָה, וְהוּא מִצְוַת לֹא תַעֲשֶׂה. ״זָכוֹר״ הוּא מִצְוַת עֲשֵׂה וְכוֹלֵל אֶת הַקִּדּוּשׁ וְהַתְּפִלָּה.","פֶּרֶק מ״ח, הֲלָכָה א׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["מָה לִמֵּד מֹשֶׁה אֶת הָעָם כְּשֶׁהִקְדִּים אֶת הַשַּׁבָּת לְצִוּוּי בְּנִיַּת הַמִּשְׁכָּן?",["שֶׁמֻּתָּר לִבְנוֹת אֶת הַמִּשְׁכָּן גַּם בְּיוֹם הַשַּׁבָּת","שֶׁבְּנִיַּת הַמִּשְׁכָּן אֵינָהּ דּוֹחָה אֶת הַשַּׁבָּת","שֶׁהַשַּׁבָּת חֲשׁוּבָה פָּחוֹת מִבְּנִיַּת הַמִּשְׁכָּן הַקָּדוֹשׁ","שֶׁבְּנִיַּת הַמִּשְׁכָּן צְרִיכָה לְהִסְתַּיֵּם לִפְנֵי הַשַּׁבָּת הָרִאשׁוֹנָה"],1,"חֲכָמִים הִסְבִּירוּ שֶׁבְּכָךְ שֶׁהִקְדִּים מֹשֶׁה אֶת הַצִּוּוּי עַל הַשַּׁבָּת, לִמֵּד שֶׁבְּנִיַּת הַמִּשְׁכָּן אֵינָהּ דּוֹחָה אֶת הַשַּׁבָּת.","פֶּרֶק מ״ח, הֲלָכָה ב׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["מִנַּיִן לָמְדוּ חֲכָמִים אֵילוּ מְלָאכוֹת אֲסוּרוֹת בְּשַׁבָּת?",["מִמְּלָאכוֹת שֶׁעָשׂוּ בְּנֵי יִשְׂרָאֵל בְּמִצְרַיִם, עֶשֶׂר מְלָאכוֹת","מִמְּלָאכוֹת הַשָּׂדֶה שֶׁעָשׂוּ הָאָבוֹת, שֶׁבַע מְלָאכוֹת בִּלְבַד","מִמְּלָאכוֹת בֵּית הַמִּקְדָּשׁ בִּירוּשָׁלַיִם, מֵאָה מְלָאכוֹת שׁוֹנוֹת","מֵהַמְּלָאכוֹת שֶׁנַּעֲשׂוּ בְּבִנְיַת הַמִּשְׁכָּן, ל״ט אֲבוֹת מְלָאכָה"],3,"הַמְּלָאכוֹת שֶׁנַּעֲשׂוּ בַּמִּשְׁכָּן אֲסוּרוֹת בְּשַׁבָּת, לְמָשָׁל כְּתִיבַת סִימָנִים עַל הַקְּרָשִׁים. חֲכָמִים מָנוּ שְׁלוֹשִׁים וָתֵשַׁע אֲבוֹת מְלָאכָה.","פֶּרֶק מ״ח, הֲלָכוֹת ג׳-ד׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["לָמָּה חִתּוּךְ יְרָקוֹת קָצוּץ הוּא תּוֹלָדַת טוֹחֵן?",["כִּי מְחַלְּקִים דָּבָר שָׁלֵם לַחֲלָקִים קְטַנִּים לְמַאֲכָל","כִּי מִשְׁתַּמְּשִׁים בְּסַכִּין חַדָּה שֶׁדּוֹמָה לְאֶבֶן רֵחַיִם","כִּי הַיְּרָקוֹת גְּדֵלִים בָּאֲדָמָה כְּמוֹ הַחִטִּים בַּשָּׂדֶה","כִּי מְכִינִים מֵהַיְּרָקוֹת סָלָט כְּמוֹ שֶׁמְּכִינִים לֶחֶם"],0,"טְחִינָה הִיא חֲלוּקַת גּוּף אֶחָד לַחֲלָקִים קְטַנִּים. הַחוֹתֵךְ יְרָקוֹת לוֹקֵחַ דָּבָר שָׁלֵם וּמְחַלֵּק אוֹתוֹ כְּדֵי שֶׁיִּהְיֶה רָאוּי יוֹתֵר לְמַאֲכָל. הַדִּין תָּלוּי בַּכְּלִי, בְּגֹדֶל הַחֲתִיכוֹת וּבִזְמַן הַחִתּוּךְ.","פֶּרֶק מ״ח, הֲלָכוֹת ה׳, י׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["לָמָּה אָסְרוּ חֲכָמִים לַעֲלוֹת עַל עֵץ בְּשַׁבָּת?",["כִּי הָעֲלִיָּה עַל הָעֵץ הִיא מְלֶאכֶת בּוֹנֶה","כִּי הָעֵץ עָלוּל לְהִשָּׁבֵר וּלְהַזִּיק לָאָדָם","שֶׁמָּא יִתְלֹשׁ עָלִים וְיַעֲבֹר עַל מְלֶאכֶת קוֹצֵר","כִּי הָעֲלִיָּה עַל הָעֵץ הִיא מְלֶאכֶת חוֹרֵשׁ"],2,"חֲכָמִים חָשְׁשׁוּ שֶׁהָעוֹלֶה עַל עֵץ יִגָּרֵר לִתְלֹשׁ עָלִים, וְהַתּוֹלֵשׁ עָלִים מֵעֵץ עוֹבֵר עַל מְלֶאכֶת קוֹצֵר.","פֶּרֶק מ״ח, הֲלָכָה ו׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["מִי שֶׁמְּמַלֵּא גּוּמָא בֶּחָצֵר בְּשַׁבָּת, עַל אֵיזוֹ מְלָאכָה הוּא עוֹבֵר?",["עַל מְלֶאכֶת בּוֹנֶה, כִּי הוּא מוֹסִיף עָפָר לַבַּיִת","עַל מְלֶאכֶת חוֹרֵשׁ, כִּי הוּא מְיַשֵּׁר אֶת הַקַּרְקַע","עַל מְלֶאכֶת זוֹרֵעַ, כִּי הֶעָפָר עוֹזֵר לַצְּמָחִים","עַל מְלֶאכֶת טוֹחֵן, כִּי הוּא מְפוֹרֵר אֶת הֶעָפָר"],1,"מִי שֶׁמְּיַשֵּׁר אֶת פְּנֵי הַקַּרְקַע עַל יְדֵי מִלּוּי גּוּמָא (בּוֹר קָטָן) אוֹ סִלּוּק גַּבְשׁוּשִׁית נִקְרָא ״חוֹרֵשׁ״.","פֶּרֶק מ״ח, הֲלָכָה ז׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["לָמָּה אָסוּר לִגְזֹם עֵצִים בְּשַׁבָּת?",["כִּי הָעֲנָפִים הַגְּזוּמִים נוֹפְלִים וּמְלַכְלְכִים אֶת הֶחָצֵר","כִּי הַגִּזּוּם עוֹשֶׂה רַעַשׁ גָּדוֹל שֶׁמַּפְרִיעַ לַשְּׁכֵנִים","כִּי אָסוּר לָגַעַת בָּעֵצִים בְּשַׁבָּת בְּשׁוּם אֹפֶן","כִּי הַגִּזּוּם גּוֹרֵם לִשְׁאָר חֶלְקֵי הָעֵץ לִצְמֹחַ הֵיטֵב"],3,"כָּל פְּעֻלָּה שֶׁמַּטְּרָתָהּ לְהַצְמִיחַ אֲסוּרָה מִשּׁוּם זוֹרֵעַ, וּמַטְּרַת הַגִּזּוּם הִיא שֶׁשְּׁאָר חֶלְקֵי הָעֵץ יִצְמְחוּ הֵיטֵב.","פֶּרֶק מ״ח, הֲלָכָה ח׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["לָמָּה אָסוּר לִשְׁפֹּךְ מַיִם בַּגִּנָּה בְּשַׁבָּת?",["כִּי הַמַּיִם מַשְׁקִים אֶת הַצְּמָחִים וּמוֹעִילִים לִצְמִיחָתָם","כִּי הַמַּיִם מְלַכְלְכִים אֶת הַגִּנָּה וְיוֹצְרִים בֹּץ רַב","כִּי אָסוּר לְהִשְׁתַּמֵּשׁ בְּמַיִם בְּשׁוּם מָקוֹם בְּשַׁבָּת","כִּי שְׁפִיכַת הַמַּיִם הִיא מְלֶאכֶת חוֹרֵשׁ בַּגִּנָּה"],0,"אָסוּר לִשְׁפֹּךְ מַיִם בַּגִּנָּה אוֹ בְּכָל מָקוֹם שֶׁיֵּשׁ בּוֹ צְמָחִים, מִפְּנֵי שֶׁהַדָּבָר מַשְׁקֶה אֶת הַצְּמָחִים וּמוֹעִיל לִצְמִיחָתָם.","פֶּרֶק מ״ח, הֲלָכָה ט׳","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["מָה הַדִּין בְּהַדְבָּקַת שְׁנֵי נְיָרוֹת זֶה לָזֶה בְּשַׁבָּת?",["הִיא מֻתֶּרֶת, כִּי אֵין בָּהּ חוּט וּמַחַט","הִיא אֲסוּרָה רַק מִדְּרַבָּנָן, מִשּׁוּם גְּזֵרַת חֲכָמִים","הִיא תּוֹלֶדֶת תּוֹפֵר, וַאֲסוּרָה מִן הַתּוֹרָה","הִיא מְלֶאכֶת כּוֹתֵב, וַאֲסוּרָה רַק בִּכְתִיבָה"],2,"הַתּוֹפֵר שְׁנֵי בַּדִּים עוֹבֵר עַל אַב הַמְּלָאכָה ״תּוֹפֵר״, וְהַדְבָּקַת נְיָרוֹת אוֹ בַּדִּים זֶה לָזֶה הִיא תּוֹלָדָה שֶׁל תּוֹפֵר וַאֲסוּרָה מֵהַתּוֹרָה.","פֶּרֶק מ״ח, הֲלָכָה י״א","הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת"],["מַדּוּעַ מֻתָּר לְהִשְׁתַּמֵּשׁ בְּסִכַּת בִּטָּחוֹן לְחִזּוּק בֶּגֶד בְּשַׁבָּת?",["כִּי סִכָּה קְטַנָּה אֵינָהּ נֶחְשֶׁבֶת כְּלָל לִכְלִי","כִּי מוֹרִידִים אוֹתָהּ בְּסִיּוּם לְבִישַׁת הַבֶּגֶד","כִּי מֻתָּר לִתְפֹּר בְּשַׁבָּת לְצֹרֶךְ כְּבוֹד הַבְּרִיּוֹת","כִּי הַבֶּגֶד כְּבָר הָיָה תָּפוּר לִפְנֵי שַׁבָּת"],1,"בְּסִיּוּם לְבִישַׁת הַבֶּגֶד מוֹרִידִים מִמֶּנּוּ אֶת סִכַּת הַבִּטָּחוֹן, וְלָכֵן הַדָּבָר דּוֹמֶה לִסְגִירַת רוֹכְסָן אוֹ כַּפְתּוֹרִים.","פֶּרֶק מ״ח, הֲלָכָה י״ב","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מִי עוֹבֵר עַל אַב הַמְּלָאכָה ״קוֹרֵעַ״?",["מִי שֶׁקּוֹרֵעַ דָּבָר כָּלְשֶׁהוּ בְּלִי שׁוּם מַטָּרָה","רַק מִי שֶׁקּוֹרֵעַ בֶּגֶד שָׁלֵם לִשְׁנֵי חֲלָקִים","מִי שֶׁפּוֹתֵחַ אֲרִיזָה שֶׁל מַאֲכָל לִפְנֵי הַסְּעוּדָה","מִי שֶׁקּוֹרֵעַ קְרִיעָה שֶׁיֵּשׁ בָּהּ תִּקּוּן וְתוֹעֶלֶת"],3,"מִי שֶׁקּוֹרֵעַ קְרִיעָה שֶׁיֵּשׁ בָּהּ תִּקּוּן (תּוֹעֶלֶת) עוֹבֵר עַל אַב הַמְּלָאכָה ״קוֹרֵעַ״.","פֶּרֶק מ״ח, הֲלָכָה י״ג","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מַדּוּעַ אָסוּר לְהַפְרִיד נְיָרוֹת דְּבוּקִים בְּשַׁבָּת?",["כִּי זוֹ פְּעֻלַּת קְרִיעָה לְצֹרֶךְ תִּקּוּן","כִּי הַנְּיָרוֹת הֵם מֻקְצֶה וְאָסוּר לָגַעַת בָּהֶם","כִּי אוּלַי יִכְתְּבוּ עַל הַנְּיָרוֹת אַחַר כָּךְ","כִּי זוֹ מְלֶאכֶת בּוֹנֶה שֶׁאֲסוּרָה בְּשַׁבָּת"],0,"הַפְרָדַת נְיָרוֹת דְּבוּקִים הִיא פְּעֻלַּת קְרִיעָה לְצֹרֶךְ תִּקּוּן, וְלָכֵן הִיא אֲסוּרָה.","פֶּרֶק מ״ח, הֲלָכָה י״ד","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מָה מֻתָּר לַעֲשׂוֹת כְּשֶׁאֵין נְיַר טוּאָלֶט חָתוּךְ בְּשַׁבָּת?",["לַחְתֹּךְ כָּרָגִיל בַּיָּדַיִם בְּדִיּוּק עַל קַוֵּי הַחִתּוּךְ","לַחְתֹּךְ בְּשִׁנּוּי, בְּעֶזְרַת הַמַּרְפֵּקִים וְלֹא בַּיָּדַיִם","לְבַקֵּשׁ מִשְּׁכֵנִים מִסְפָּרַיִם וְלַחְתֹּךְ אֶת הַנְּיָר","אָסוּר בְּשׁוּם אֹפֶן לְהִשְׁתַּמֵּשׁ בִּנְיָר הַגְּלִיל"],1,"מִפְּנֵי כְּבוֹד הַבְּרִיּוֹת מֻתָּר לַחְתֹּךְ בְּשִׁנּוּי, בְּעֶזְרַת הַמַּרְפֵּקִים וְלֹא בַּיָּדַיִם, וּמִשְׁתַּדְּלִים שֶׁלֹּא לַחְתֹּךְ עַל קַוֵּי הַחִתּוּךְ.","פֶּרֶק מ״ח, הֲלָכָה ט״ז","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מַדּוּעַ מֻתָּר לִקְרֹעַ אֲרִיזוֹת שֶׁל מַאֲכָלִים בְּשַׁבָּת?",["כִּי בְּשַׁבָּת מֻתָּר לִקְרֹעַ כָּל סוּג שֶׁל נְיָר","כִּי הָאֲרִיזוֹת נִקְנוּ בִּמְיֻחָד לִכְבוֹד יוֹם הַשַּׁבָּת","כִּי לְצֹרֶךְ אֹכֶל מֻתָּר לַעֲשׂוֹת כָּל מְלָאכָה","כִּי הֵן דּוֹמוֹת לִקְלִפַּת פְּרִי שֶׁמְּסִירִים כְּדֵי לֶאֱכֹל"],3,"אֵין לָאֲרִיזוֹת חֲשִׁיבוּת בִּפְנֵי עַצְמָן, וְהֵן דּוֹמוֹת לִקְלִפַּת פְּרִי שֶׁצָּרִיךְ לַהֲסִירָהּ כְּדֵי לְהַגִּיעַ לָאֹכֶל.","פֶּרֶק מ״ח, הֲלָכָה י״ז","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מָה הַדִּין לְהוֹרִיד דֶּלֶת שֶׁל בַּיִת בְּשַׁבָּת?",["אָסוּר לְהוֹרִיד וּלְהַחְזִיר, מִשּׁוּם בּוֹנֶה וְסוֹתֵר","מֻתָּר לְהוֹרִיד, אֲבָל אָסוּר לְהַחְזִיר אוֹתָהּ","מֻתָּר, כִּי זוֹ אֵינָהּ מְלָאכָה שֶׁל קוֹרֵעַ","מֻתָּר רַק אִם הַדֶּלֶת הַזֹּאת נִשְׁבְּרָה"],0,"אָסוּר לְהוֹרִיד אוֹ לְהַחְזִיר דֶּלֶת וְחַלּוֹן שֶׁל בַּיִת בְּשַׁבָּת, מִשּׁוּם בּוֹנֶה וְסוֹתֵר.","פֶּרֶק מ״ח, הֲלָכָה י״ח","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מָה מֻתָּר לַעֲשׂוֹת בְּשַׁבָּת עִם רָהִיטִים?",["לְהַחְזִיר רֶגֶל שֶׁהִתְפָּרְקָה מִסַּפְסָל אוֹ מִכִּסֵּא","לְהַרְכִּיב מִטָּה חֲדָשָׁה לָאוֹרְחִים שֶׁבָּאוּ לְשַׁבָּת","לִפְתֹּחַ וְלִסְגֹּר שֻׁלְחָן מִתְקַפֵּל וְכִסְאוֹת מִתְקַפְּלִים","לְהַרְכִּיב כִּסֵּא חָדָשׁ שֶׁקִּבַּלְנוּ בְּמַתָּנָה"],2,"אָסוּר לְהַרְכִּיב כִּסֵּא, שֻׁלְחָן אוֹ מִטָּה, וְאָסוּר לְהַחְזִיר רֶגֶל שֶׁהִתְפָּרְקָה. אֲבָל מֻתָּר לִפְתֹּחַ וְלִסְגֹּר שֻׁלְחָן מִתְקַפֵּל וְכִסְאוֹת מִתְקַפְּלִים.","פֶּרֶק מ״ח, הֲלָכָה י״ט","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["הַאִם מֻתָּר לִפְתֹּחַ מִכְסֶה מֻבְרָג שֶׁל קֻפְסָה בְּשַׁבָּת?",["אָסוּר, כִּי הַבְרָגָה הִיא תָּמִיד מְלֶאכֶת בּוֹנֶה","מֻתָּר, כִּי זוֹ דֶּרֶךְ הַשִּׁמּוּשׁ הָרְגִילָה בַּכְּלִי","מֻתָּר לִפְתֹּחַ, אֲבָל אָסוּר לִסְגֹּר אוֹתוֹ שׁוּב","מֻתָּר רַק אִם הַקֻּפְסָה נִפְתְּחָה לִפְנֵי שַׁבָּת"],1,"כְּלִי שֶׁדֶּרֶךְ שִׁמּוּשׁוֹ הִיא בִּפְתִיחָה וּסְגִירָה שֶׁל הַבְרָגָה, כְּמוֹ מִכְסֶה שֶׁל קֻפְסָה, מֻתָּר לִפְתֹּחַ וְלִסְגֹּר בְּשַׁבָּת.","פֶּרֶק מ״ח, הֲלָכָה כ׳","קוֹרֵעַ, בּוֹנֶה וְסוֹתֵר בְּשַׁבָּת"],["מַדּוּעַ רָאוּי לִפְתֹּחַ בַּקְבּוּקֵי יַיִן עִם פְּקַק מַתֶּכֶת בְּיוֹם שִׁשִּׁי?",["כִּי הַיַּיִן מִתְקַלְקֵל אִם פּוֹתְחִים אוֹתוֹ בְּשַׁבָּת","כִּי יֵשׁ אוֹמְרִים שֶׁהַפְּתִיחָה אֲסוּרָה מִשּׁוּם מְתַקֵּן כְּלִי","כִּי אָסוּר לִשְׁתּוֹת יַיִן חָדָשׁ בִּסְעוּדַת שַׁבָּת","כִּי פְּתִיחַת בַּקְבּוּק נֶחְשֶׁבֶת מְלֶאכֶת בּוֹרֵר בְּשַׁבָּת"],1,"בִּפְתִיחָה רִאשׁוֹנָה נִתֶּקֶת טַבַּעַת מֵהַפְּקָק, וְיֵשׁ אוֹמְרִים שֶׁזֶּה מְתַקֵּן כְּלִי. אִם שָׁכְחוּ – יֵשׁ אוֹמְרִים לַעֲשׂוֹת חֹר תְּחִלָּה, יֵשׁ אוֹמְרִים לִפְתֹּחַ וְלִזְרֹק אֶת הַפְּקָק, וְיֵשׁ מַתִּירִים כָּרָגִיל.","פֶּרֶק מ״ח, הֲלָכָה כ״א","צָד, כּוֹתֵב וּמוֹחֵק"],["מָה הַדִּין לְשַׂחֵק בְּשַׁבָּת בְּלֶגוֹ, וּלְשַׂחֵק עַל אֲדָמָה לֹא מְרֻצֶּפֶת?",["שְׁנֵיהֶם מֻתָּרִים, כִּי מְדֻבָּר בְּמִשְׂחֲקֵי יְלָדִים בִּלְבַד","שְׁנֵיהֶם אֲסוּרִים, כִּי הַמִּשְׂחָק נֶחְשָׁב מְלָאכָה בְּשַׁבָּת","לֶגוֹ אָסוּר, וְעַל קַרְקַע שֶׁאֵינָהּ מְרֻצֶּפֶת מֻתָּר","לֶגוֹ מֻתָּר, וְעַל קַרְקַע שֶׁאֵינָהּ מְרֻצֶּפֶת אָסוּר"],3,"לֶגוֹ וּקְלִיקְס מֻתָּרִים כִּי רְגִילִים לְהַרְכִּיבָם וּלְפָרְקָם. עַל קַרְקַע לֹא מְרֻצֶּפֶת חוֹשְׁשִׁים שֶׁיְּיַשְּׁרוּ גֻּמּוֹת – וְזֶה אָסוּר מִשּׁוּם בּוֹנֶה.","פֶּרֶק מ״ח, הֲלָכוֹת כ״ב-כ״ג","צָד, כּוֹתֵב וּמוֹחֵק"],["מָה הַדִּין לִגְרֹם לְחָתוּל לְהִכָּנֵס לְחֶדֶר וְלִסְגֹּר אֶת הַדֶּלֶת?",["מֻתָּר, כִּי לֹא תּוֹפְסִים אוֹתוֹ בַּיָּדַיִם","אָסוּר, כִּי גַּם זוֹ צֵידָה בְּשַׁבָּת","מֻתָּר, כִּי חָתוּל אֵינוֹ בַּעַל חַיִּים שֶׁצָּדִים","אָסוּר רַק אִם הֶחָתוּל קָטָן וְחַלָּשׁ מְאוֹד"],1,"צֵידָה אֲסוּרָה גַּם כְּשֶׁלֹּא תּוֹפְסִים בַּיָּדַיִם, אֶלָּא גּוֹרְמִים לְבַעַל הַחַיִּים לְהִכָּנֵס לְמָקוֹם שֶׁאֵינוֹ יָכוֹל לָצֵאת וְסוֹגְרִים אֶת הַפֶּתַח.","פֶּרֶק מ״ח, הֲלָכָה כ״ד","צָד, כּוֹתֵב וּמוֹחֵק"],["חַיַּת מַחְמָד שֶׁאֵינָהּ בּוֹרַחַת מְסָרֶבֶת לְהִכָּנֵס לַכְּלוּב. מָה הַדִּין?",["אָסוּר לְהַכְנִיס אוֹתָהּ לַכְּלוּב בְּכֹחַ בְּשַׁבָּת","מֻתָּר לִדְחֹף אוֹתָהּ פְּנִימָה בְּכֹחַ כִּי הִיא שֶׁלָּנוּ","מֻתָּר לְהַכְנִיס אוֹתָהּ בְּכֹחַ אִם הִיא קְטַנָּה","מֻתָּר בְּכֹחַ, אֲבָל רַק בְּעֶזְרַת אָדָם מְבֻגָּר"],0,"חַיּוֹת מַחְמָד שֶׁאֵינָן בּוֹרְחוֹת מֻתָּר לְהַכְנִיס, אֲבָל אִם הֵן מְסָרְבוֹת – אָסוּר בְּכֹחַ. כֶּלֶב מְשֻׁחְרָר מֻתָּר לִקְשֹׁר לִרְצוּעָה, וְיֵשׁ מַחְמִירִים.","פֶּרֶק מ״ח, הֲלָכָה כ״ה","צָד, כּוֹתֵב וּמוֹחֵק"],["תֻּכִּי חָדָשׁ, שֶׁעֲדַיִן אֵינוֹ רָגִיל לַכְּלוּב, נִכְנַס לְבַד. מָה הַדִּין?",["מֻתָּר לִנְעֹל אֶת הַדֶּלֶת, כִּי נִכְנַס מֵעַצְמוֹ","מֻתָּר לִנְעֹל רַק אִם הַכְּלוּב נִמְצָא בַּבַּיִת","אָסוּר לִנְעֹל אֶת הַדֶּלֶת בְּפָנָיו בְּשַׁבָּת","חוֹבָה לִנְעֹל כְּדֵי שֶׁלֹּא יִבְרַח מֵהַבַּיִת"],2,"עוֹפוֹת חֲדָשִׁים אָסוּר לְהַכְנִיס לִכְלוּב, וְאִם נִכְנְסוּ מֵעַצְמָם – אָסוּר לִנְעֹל אֶת הַדֶּלֶת בִּפְנֵיהֶם. עוֹפוֹת צַיְתָנִים מֻתָּר לְהַכְנִיס.","פֶּרֶק מ״ח, הֲלָכָה כ״ו","צָד, כּוֹתֵב וּמוֹחֵק"],["יֶלֶד כּוֹתֵב אוֹת בְּמִיץ שֶׁנִּשְׁפַּךְ עַל הַשֻּׁלְחָן. מָה הַדִּין?",["מֻתָּר, כִּי לֹא כּוֹתְבִים בְּדֶרֶךְ כְּלָל בְּמִיץ","אָסוּר, כִּי גַּם כְּתִיבָה בְּמַשְׁקֶה אֲסוּרָה בְּשַׁבָּת","מֻתָּר, כִּי הָאוֹת תִּתְיַבֵּשׁ וְתֵעָלֵם מַהֵר","אָסוּר רַק אִם כּוֹתְבִים מִלָּה שְׁלֵמָה וַאֲרֻכָּה"],1,"אָסוּר לִכְתֹּב וְלִמְחֹק בְּשַׁבָּת, גַּם בִּדְבָרִים שֶׁלֹּא רְגִילִים לִכְתֹּב בָּהֶם כְּמוֹ מַשְׁקִים אוֹ חוֹל.","פֶּרֶק מ״ח, הֲלָכָה כ״ז","צָד, כּוֹתֵב וּמוֹחֵק"],["מָה הַדִּין לְקָרֵב כַּרְטִיסֵי אוֹתִיּוֹת בְּ״שַׁבֵּץ נָא״ וּלְהַרְכִּיב פַּאזֶל?",["שְׁנֵיהֶם מֻתָּרִים, כְּשֶׁהַחִבּוּר אֵינוֹ חָזָק וְנִתָּן לְפָרֵק","שְׁנֵיהֶם אֲסוּרִים, כִּי הֵם נֶחְשָׁבִים כְּתִיבָה וְצִיּוּר","שַׁבֵּץ נָא אָסוּר, וּפַאזֶל מֻתָּר תָּמִיד בְּשַׁבָּת","מֻתָּרִים, גַּם אִם מַדְבִּיקִים אֶת הַחֲלָקִים בְּדֶבֶק"],0,"מֻתָּר לְקָרֵב אוֹתִיּוֹת עַל כַּרְטִיסִים וּלְצָרֵף קִטְעֵי תְּמוּנָה, כְּשֶׁאֵינָם מְחֻבָּרִים הֵיטֵב וְנִתָּן לְפָרְקָם. אֲבָל צִיּוּר אָסוּר כִּי הוּא תּוֹלָדָה שֶׁל כּוֹתֵב.","פֶּרֶק מ״ח, הֲלָכוֹת כ״ח-כ״ט","צָד, כּוֹתֵב וּמוֹחֵק"],["מָה הַדִּין לַחְתֹּךְ עוּגִיָּה שֶׁסֵּמֶל הַחֶבְרָה מֻטְבָּע בְּגוּפָהּ?",["אָסוּר, כִּי הַחִתּוּךְ מוֹחֵק אֶת הַסֵּמֶל שֶׁעָלֶיהָ","יֵשׁ אוֹמְרִים אָסוּר, וְיֵשׁ אוֹמְרִים מֻתָּר","מֻתָּר, כִּי הַכְּתִיבָה הִיא בְּגוּף הַמַּאֲכָל עַצְמוֹ","מֻתָּר רַק לְמִי שֶׁלֹּא רוֹאֶה אֶת הַסֵּמֶל"],2,"כְּשֶׁהַכְּתִיבָה בְּגוּף הַמַּאֲכָל – מֻתָּר לַחְתֹּךְ. הַמַּחֲלֹקֶת הִיא בְּמַאֲכָל שֶׁכָּתְבוּ עָלָיו, כְּמוֹ עוּגַת יוֹם הֻלֶּדֶת עִם מִסְפָּר מִסֻּכָּרִיּוֹת.","פֶּרֶק מ״ח, הֲלָכָה ל׳","צָד, כּוֹתֵב וּמוֹחֵק"],["פּוֹתְחִים אֲרִיזַת חֲטִיף בְּשַׁבָּת. לְמָה צָרִיךְ לְהִזָּהֵר?",["שֶׁלֹּא לִקְרֹעַ אֶת הָאוֹתִיּוֹת הַמֻּדְפָּסוֹת עַל הָאֲרִיזָה","שֶׁלֹּא לִפְתֹּחַ אוֹתָהּ לִפְנֵי קִדּוּשׁ שֶׁל שַׁבָּת","שֶׁלֹּא לִשְׁפֹּךְ פֵּרוּרִים עַל הָרִצְפָּה שֶׁל הַבַּיִת","שֶׁלֹּא לִזְרֹק אֶת הָאֲרִיזָה לְפַח הַמִּחְזוּר"],0,"קְרִיעַת נְיָר שֶׁמֻּדְפָּסוֹת עָלָיו אוֹתִיּוֹת אֲסוּרָה מִשּׁוּם מוֹחֵק, וְלָכֵן נִזְהָרִים גַּם בִּפְתִיחַת אֲרִיזוֹת וּבַקְבּוּקִים. וְיֵשׁ מַתִּירִים כְּשֶׁאֵין כַּוָּנָה לִמְחֹק.","פֶּרֶק מ״ח, הֲלָכָה ל״א","צָד, כּוֹתֵב וּמוֹחֵק"],["מָה מֵהַבָּאִים אֵינוֹ אֶחָד מִתְּנָאֵי הַבְּרִירָה הַמֻּתֶּרֶת בְּשַׁבָּת?",["לָקַחַת אֶת הָאֹכֶל מִתּוֹךְ הַפְּסֹלֶת","לִבְרֹר בַּיָּד וְלֹא בִּכְלִי מְיֻחָד","לֶאֱכֹל אֶת מַה שֶּׁבָּרַרְנוּ מִיָּד","לִבְרֹר רַק אַחֲרֵי נְטִילַת יָדַיִם"],3,"שְׁלוֹשָׁה תְּנָאִים: אֹכֶל מִתּוֹךְ פְּסֹלֶת, בַּיָּד, וּמִיָּד. נְטִילַת יָדַיִם אֵינָהּ אֶחָד מֵהֶם. בּוֹרֵר הִיא מִל״ט הַמְּלָאכוֹת, וְרַבִּים נִכְשָׁלִים בָּהּ.","פֶּרֶק מ״ט, הֲלָכוֹת א׳-ב׳","בּוֹרֵר בְּשַׁבָּת"],["אֶלְעָד רוֹצֶה רַק אֱגוֹזֵי קַשְׁיוֹ מִשַּׂקִּית מְעֹרֶבֶת. מָה יַעֲשֶׂה?",["יוֹצִיא אֶת הַפִּיסְטוּקִים וְיֹאכַל אֶת הַשְּׁאָר","יוֹצִיא אֶת אֱגוֹזֵי הַקַּשְׁיוֹ וְיֹאכַל אוֹתָם","יְנַעֵר אֶת הַשַּׂקִּית עַד שֶׁהַפִּיסְטוּקִים יִפְּלוּ","יִשְׁפֹּךְ הַכֹּל לְמִסְנֶנֶת וְיַפְרִיד בֵּינֵיהֶם"],1,"לוֹקְחִים אֶת מַה שֶּׁמְּעֻנְיָנִים בּוֹ כָּרֶגַע (הַקַּשְׁיוֹ) מִתּוֹךְ מַה שֶּׁלֹּא מְעֻנְיָנִים בּוֹ, אֲפִלּוּ שֶׁהַפִּיסְטוּקִים הֵם אֹכֶל בְּעַצְמָם.","פֶּרֶק מ״ט, הֲלָכָה ג׳","בּוֹרֵר בְּשַׁבָּת"],["מַדּוּעַ מֻתָּר לְהוֹצִיא יְרָקוֹת מִן הַמָּרָק בְּמַזְלֵג?",["כִּי הַיְּרָקוֹת אֵינָם נֶחְשָׁבִים אֹכֶל כְּלָל","כִּי מָרָק אֵינוֹ נֶחְשָׁב תַּעֲרֹבֶת בִּכְלָל","כִּי הַמַּזְלֵג מְשַׁמֵּשׁ כְּמוֹ יָד אֲרֻכָּה","כִּי מֻתָּר לִבְרֹר בְּכָל כְּלִי שֶׁהוּא"],2,"הַסַּכּוּ״ם אֵינוֹ מְסַיֵּעַ לַבְּרִירָה אֶלָּא הוּא כְּ״יָד אֲרֻכָּה״. אֲבָל כְּלִי הַמְּיֻעָד לִבְרִירָה, כְּמוֹ מִסְנֶנֶת אוֹ כַּף עִם חֹרִים – אָסוּר.","פֶּרֶק מ״ט, הֲלָכוֹת ד׳-ה׳","בּוֹרֵר בְּשַׁבָּת"],["בְּלֵיל שַׁבָּת בָּרַר יוֹסִי עֲנָבִים לַאֲרוּחַת הַבֹּקֶר. מָה הַדִּין?",["מֻתָּר, כִּי זֶה עֲדַיִן בְּתוֹךְ הַשַּׁבָּת","מֻתָּר, כִּי הוּא לָקַח אֹכֶל מִפְּסֹלֶת","אָסוּר, כִּי אָסוּר לֶאֱכֹל עֲנָבִים בְּשַׁבָּת","אָסוּר, כִּי בּוֹרְרִים רַק לְשִׁמּוּשׁ מִיָּדִי"],3,"בּוֹרְרִים רַק לְשִׁמּוּשׁ ״לְאַלְתַּר״ אוֹ לַסְּעוּדָה הַסְּמוּכָה. אָסוּר לְהָנִיחַ לְשִׁמּוּשׁ מְאֻחָר יוֹתֵר, אֲפִלּוּ בְּתוֹךְ הַשַּׁבָּת.","פֶּרֶק מ״ט, הֲלָכָה ו׳","בּוֹרֵר בְּשַׁבָּת"],["הַסְּעוּדָה תִּמָּשֵׁךְ שָׁלֹשׁ שָׁעוֹת. מָתַי מֻתָּר לִבְרֹר לְכֻלָּהּ?",["סָמוּךְ לִתְחִלַּת הַסְּעוּדָה, אֶת כָּל הַנִּצְרָךְ","רַק מְעַט מְעַט, בְּכָל פַּעַם מָנָה","בַּבֹּקֶר הַמֻּקְדָּם, הַרְבֵּה לִפְנֵי הַסְּעוּדָה","אַחֲרֵי שֶׁהַסְּעוּדָה מִסְתַּיֶּמֶת, לַסְּעוּדָה הַבָּאָה"],0,"מֻתָּר לִבְרֹר אֶת כָּל הַנִּצְרָךְ לַסְּעוּדָה אֲפִלּוּ אִם תִּמָּשֵׁךְ כַּמָּה שָׁעוֹת, אַךְ סָמוּךְ לִתְחִלָּתָהּ וְלֹא לִפְנֵי כֵן.","פֶּרֶק מ״ט, הֲלָכָה ז׳","בּוֹרֵר בְּשַׁבָּת"],["מַדּוּעַ מֻתָּר לְקַלֵּף מַנְגּוֹ בְּמַקְלֵף אֲפִלּוּ לְאַחַר זְמַן?",["כִּי מַנְגּוֹ אֵינוֹ נֶחְשָׁב פְּרִי בִּכְלָל","כִּי מֻתָּר לְקַלֵּף כָּל פְּרִי בְּמַקְלֵף","כִּי מַנְגּוֹ אוֹכְלִים תָּמִיד עִם הַקְּלִפָּה","כִּי הַקְּלִפָּה שֶׁלּוֹ דְּבוּקָה אֵלָיו מְאֹד"],3,"פְּרִי שֶׁקְּלִפָּתוֹ דְּבוּקָה אֵלָיו מְאֹד, עַד שֶׁאִי אֶפְשָׁר לְקַלְּפוֹ בְּלִי לְהוֹרִיד חֵלֶק מֵהַפְּרִי (מַנְגּוֹ, מֶלוֹן, צְנוֹן) – מֻתָּר לְקַלְּפוֹ בְּמַקְלֵף אֲפִלּוּ לְאַחַר זְמַן.","פֶּרֶק מ״ט, הֲלָכָה ח׳","בּוֹרֵר בְּשַׁבָּת"],["כֵּיצַד מֻתָּר לְקַלֵּף בָּצָל בְּשַׁבָּת?",["בְּמַקְלֵף מְיֻחָד, וְאֶפְשָׁר גַּם לְמָחָר","בַּיָּד אוֹ בְּסַכִּין, סָמוּךְ לַאֲכִילָה","אָסוּר לְקַלֵּף בָּצָל בְּשַׁבָּת בְּשׁוּם אֹפֶן","רַק בְּמַקְלֵף, כְּדֵי שֶׁלֹּא יִתְלַכְלְכוּ הַיָּדַיִם"],1,"בָּצָל אֵין רְגִילִים לֶאֱכֹל עִם הַקְּלִפָּה, וְאֶפְשָׁר לְקַלְּפוֹ בְּלִי לְהוֹרִיד מֵהַפְּרִי – לָכֵן מְקַלְּפִים בַּיָּד אוֹ בְּסַכִּין, וְלֹא בִּכְלִי הַמְּיֻעָד לְכָךְ, סָמוּךְ לַאֲכִילָה.","פֶּרֶק מ״ט, הֲלָכָה ט׳","בּוֹרֵר בְּשַׁבָּת"],["בָּאָרוֹן הַבְּגָדִים מֻנָּחִים בְּבַלָּגָן. מָה מֻתָּר בְּלֵיל שַׁבָּת?",["לְהוֹצִיא חֻלְצָה לְמָחָר בַּבֹּקֶר, כְּבָר עַכְשָׁו","לְהוֹצִיא אֶת כָּל הַבְּגָדִים שֶׁלֹּא צְרִיכִים","לְהוֹצִיא בֶּגֶד כְּדֵי לִלְבֹּשׁ אוֹתוֹ מִיָּד","לְמַיֵּן אֶת כָּל הַבְּגָדִים לְפִי סוּגִים"],2,"אִסּוּר בּוֹרֵר קַיָּם גַּם בִּבְגָדִים: מֻתָּר לָקַחַת בֶּגֶד כְּדֵי לִלְבֹּשׁ מִיָּד, אַךְ לֹא בְּלֵיל שַׁבָּת בִּשְׁבִיל הַבֹּקֶר. אִם הַבְּגָדִים מְסֻדָּרִים – מֻתָּר גַּם שֶׁלֹּא לְשִׁמּוּשׁ מִיָּדִי.","פֶּרֶק מ״ט, הֲלָכָה י״א","בּוֹרֵר בְּשַׁבָּת"],["לָמָּה טוֹב לְסַיֵּם לְבַשֵּׁל אֶת כָּל מַאַכְלֵי הַשַּׁבָּת כְּבָר מֵעֶרֶב שַׁבָּת?",["כְּדֵי שֶׁהָאֹכֶל יִהְיֶה טָעִים וְחַם יוֹתֵר","כְּדֵי שֶׁלֹּא לְהִכָּשֵׁל בְּבִשּׁוּל בְּשַׁבָּת עַצְמָהּ","כְּדֵי שֶׁהַפְּלָטָה לֹא תִּתְקַלְקֵל בְּמֶשֶׁךְ הַשַּׁבָּת","כְּדֵי לַחְסֹךְ בְּחַשְׁמַל בְּיוֹם הַשַּׁבָּת"],1,"אָסוּר לֶאֱפוֹת וּלְבַשֵּׁל בְּשַׁבָּת, וְלָכֵן מְסַיְּמִים לְבַשֵּׁל מֵעֶרֶב שַׁבָּת כְּדֵי שֶׁלֹּא לְהִכָּשֵׁל.","פֶּרֶק נ׳, הֲלָכָה א׳","בִּשּׁוּל בְּשַׁבָּת"],["סִיר עִם מַאֲכָל שֶׁאֵינוֹ מְבֻשָּׁל כָּל צָרְכּוֹ עוֹמֵד עַל הַפְּלָטָה בְּשַׁבָּת. מָה אָסוּר?",["לְהַשְׁאִיר אוֹתוֹ עַל הַפְּלָטָה עַד הַסְּעֻדָּה","לְהַשְׁאִיר עָלָיו אֶת הַמִּכְסֶה שֶׁהָיָה עָלָיו","לֹא לָגַעַת בּוֹ עַד שֶׁיִּתְבַּשֵּׁל לְגַמְרֵי","לְהַעֲבִירוֹ לְמָקוֹם חַם יוֹתֵר עַל הַפְּלָטָה"],3,"אָסוּר לְהַעֲבִיר אוֹתוֹ לְמָקוֹם חַם יוֹתֵר, כִּי זֶה גּוֹרֵם לוֹ לְהִתְבַּשֵּׁל מַהֵר יוֹתֵר. וְגַם אִם הֵרִימוּ אוֹתוֹ אֲפִלּוּ לְרֶגַע – אָסוּר לְהַחְזִירוֹ.","פֶּרֶק נ׳, הֲלָכָה ב׳","בִּשּׁוּל בְּשַׁבָּת"],["לָמָּה אָסוּר לְהִשְׁתַּמֵּשׁ בְּשַׁבָּת בְּמִתְקַן מַיִם חַמִּים הַמְּחֻבָּר לַצַּנֶּרֶת?",["כִּי הַמַּיִם שֶׁבּוֹ חַמִּים מִדַּי לִשְׁתִיָּה","כִּי אָסוּר לִשְׁתּוֹת מַיִם חַמִּים בְּשַׁבָּת","כִּי נִכְנָסִים אֵלָיו מַיִם קָרִים שֶׁמִּתְבַּשְּׁלִים בְּשַׁבָּת","כִּי הוּא עָלוּל לְהִתְקַלְקֵל בְּאֶמְצַע הַשַּׁבָּת"],2,"כְּשֶׁמּוֹצִיאִים מִמֶּנּוּ מַיִם חַמִּים, נִכְנָסִים מִיָּד מַיִם קָרִים וּמִתְבַּשְּׁלִים. לָכֵן מַשְׁאִירִים מַיִם עַל פְּלָטָה אוֹ מֵחַם עַל מַצַּב ״שַׁבָּת״.","פֶּרֶק נ׳, הֲלָכוֹת ג׳-ד׳","בִּשּׁוּל בְּשַׁבָּת"],["מָה הַהֶבְדֵּל בֵּין מָרָק לִשְׁנִיצֶל שֶׁהִתְבַּשְּׁלוּ לִפְנֵי שַׁבָּת וְהִתְקָרְרוּ?",["אֶת הַשְּׁנִיצֶל מֻתָּר לְחַמֵּם, אֶת הַמָּרָק אָסוּר","אֶת הַמָּרָק מֻתָּר לְחַמֵּם, אֶת הַשְּׁנִיצֶל אָסוּר","שְׁנֵיהֶם מֻתָּרִים לְחִמּוּם כִּי הִתְבַּשְּׁלוּ לִפְנֵי שַׁבָּת","שְׁנֵיהֶם אֲסוּרִים לְחִמּוּם עַל הַפְּלָטָה בְּשַׁבָּת"],0,"״יֵשׁ בִּשּׁוּל אַחַר בִּשּׁוּל בְּלַח״ – אָסוּר לְהַרְתִּיחַ מָרָק. ״אֵין בִּשּׁוּל אַחַר בִּשּׁוּל בְּיָבֵשׁ״ – מֻתָּר לְחַמֵּם שְׁנִיצֶל. וְיֵשׁ אוֹסְרִים לְהָנִיחַ סִיר יְשִׁירוֹת עַל הַפְּלָטָה, וּמַפְרִידִים בְּצַלַּחַת הֲפוּכָה.","פֶּרֶק נ׳, הֲלָכוֹת ה׳-ו׳","בִּשּׁוּל בְּשַׁבָּת"],["מָהוּ ״כְּלִי רִאשׁוֹן״?",["הַכְּלִי הָרִאשׁוֹן שֶׁשָּׂמִים עַל הַשֻּׁלְחָן בַּסְּעֻדָּה","הַכְּלִי שֶׁבּוֹ הִתְבַּשֵּׁל הַמַּאֲכָל אוֹ הַתַּבְשִׁיל","הַכּוֹס שֶׁאֵלֶיהָ מוֹזְגִים מַיִם מֵהַמֵּחַם","הַצַּלַּחַת שֶׁשָּׂמִים הֲפוּכָה עַל הַפְּלָטָה"],1,"כְּלִי רִאשׁוֹן הוּא הַכְּלִי שֶׁבּוֹ הִתְבַּשֵּׁל הַמַּאֲכָל, וְהוּא מְבַשֵּׁל כָּל מַה שֶּׁמַּכְנִיסִים לְתוֹכוֹ כָּל עוֹד הַיָּד סוֹלֶדֶת בּוֹ – גַּם אַחֲרֵי שֶׁהוֹרִידוּ אוֹתוֹ מֵהָאֵשׁ.","פֶּרֶק נ׳, הֲלָכָה ז׳","בִּשּׁוּל בְּשַׁבָּת"],["מָה פֵּרוּשׁ ״עֵרוּי מִכְּלִי רִאשׁוֹן מְבַשֵּׁל כְּדֵי קְלִפָּה״?",["מַיִם רוֹתְחִים שֶׁנִּשְׁפָּכִים אֵינָם מְבַשְּׁלִים שׁוּם דָּבָר","מַיִם רוֹתְחִים מְבַשְּׁלִים רַק פֵּרוֹת שֶׁיֵּשׁ לָהֶם קְלִפָּה","צָרִיךְ לְקַלֵּף אֶת הַפְּרִי לִפְנֵי שֶׁשּׁוֹפְכִים עָלָיו","מַיִם רוֹתְחִים שֶׁנִּשְׁפָּכִים מְבַשְּׁלִים אֶת הַחֵלֶק הַחִיצוֹנִי"],3,"כְּשֶׁשּׁוֹפְכִים מַיִם רוֹתְחִים מִכְּלִי רִאשׁוֹן עַל דָּבָר שֶׁאֵינוֹ מְבֻשָּׁל, הַחֵלֶק הַחִיצוֹנִי שֶׁלּוֹ מִתְבַּשֵּׁל – וְלָכֵן אָסוּר.","פֶּרֶק נ׳, הֲלָכָה ח׳","בִּשּׁוּל בְּשַׁבָּת"],["מָה נָכוֹן לְגַבֵּי כְּלִי שֵׁנִי וּכְלִי שְׁלִישִׁי?",["שְׁנֵיהֶם מְבַשְּׁלִים כָּל דָּבָר בְּדִיּוּק כְּמוֹ כְּלִי רִאשׁוֹן","שְׁנֵיהֶם אֵינָם מְבַשְּׁלִים כְּלָל, וּמֻתָּר לָשִׂים בָּהֶם הַכֹּל","כְּלִי שֵׁנִי מְבַשֵּׁל קַלֵּי בִּשּׁוּל, וּשְׁלִישִׁי לְרֹב הַפּוֹסְקִים לֹא","כְּלִי שְׁלִישִׁי מְבַשֵּׁל יוֹתֵר מִכְּלִי שֵׁנִי, כִּי הוּא קָטָן"],2,"כְּלִי שֵׁנִי מְבַשֵּׁל ״קַלֵּי הַבִּשּׁוּל״, וּמִכֵּיוָן שֶׁאֵין יוֹדְעִים בְּוַדָּאוּת מָה הֵם – לֹא מַכְנִיסִים לְתוֹכוֹ שׁוּם דָּבָר שֶׁאֵינוֹ מְבֻשָּׁל. כְּלִי שְׁלִישִׁי לְדַעַת רֹב הַפּוֹסְקִים אֵינוֹ מְבַשֵּׁל כְּלָל, וְיֵשׁ מַחְמִירִים.","פֶּרֶק נ׳, הֲלָכוֹת ט׳-י׳","בִּשּׁוּל בְּשַׁבָּת"],["אֵיךְ ״יֵשׁ מַחְמִירִים״ מְכִינִים תֵּה בְּשַׁבָּת?",["מְבַשְּׁלִים תַּמְצִית בְּשִׁשִּׁי, וּמוֹזְגִים אוֹתָהּ לְמַיִם בְּשַׁבָּת","שָׂמִים שַׂקִּית בְּכוֹס וְשׁוֹפְכִים עָלֶיהָ מַיִם מֵהַמֵּחַם","שָׂמִים עֲלֵי תֵּה יְשִׁירוֹת בְּתוֹךְ הַמֵּחַם הַחַם","מוֹזְגִים מַיִם לְכוֹס וּמִיָּד שָׂמִים בָּהּ עֲלֵי תֵּה"],0,"הַמַּחְמִירִים מְבַשְּׁלִים אֶת עֲלֵי הַתֵּה בְּיוֹם שִׁשִּׁי, וּבְשַׁבָּת שׁוֹפְכִים קֹדֶם מַיִם לַכּוֹס וְאַחַר כָּךְ מוֹזְגִים אֶת הַתַּמְצִית.","פֶּרֶק נ׳, הֲלָכָה י״א׳","בִּשּׁוּל בְּשַׁבָּת"],["לָמָּה ״יֵשׁ אוֹמְרִים״ שֶׁמֻּתָּר לִשְׁפֹּךְ מֵהַמֵּחַם יְשִׁירוֹת עַל אַבְקַת שׁוֹקוֹ?",["כִּי אַבְקַת שׁוֹקוֹ אֵינָהּ נֶחְשֶׁבֶת אֹכֶל כְּלָל","כִּי הַמַּיִם בַּמֵּחַם אֵינָם חַמִּים מַסְפִּיק","כִּי בְּשַׁבָּת מֻתָּר לְבַשֵּׁל דְּבָרִים מְתוּקִים","כִּי הִיא כְּבָר בֻּשְּׁלָה בְּתַהֲלִיךְ הַיִּצּוּר בַּמִּפְעָל"],3,"הִיא עָבְרָה בִּשּׁוּל בְּתַהֲלִיךְ הַיִּצּוּר, וְ״אֵין בִּשּׁוּל אַחַר בִּשּׁוּל בְּיָבֵשׁ״. וְיֵשׁ אוֹמְרִים שֶׁזֶּה נִרְאֶה כִּמְבַשֵּׁל, וּמַחְמִירִים לִשְׁפֹּךְ קֹדֶם מַיִם לַכּוֹס.","פֶּרֶק נ׳, הֲלָכָה י״ב׳","בִּשּׁוּל בְּשַׁבָּת"],["מָה דָּרְשׁוּ חֲכָמִים עַל ״מִמְּצוֹא חֶפְצְךָ״?",["כָּל דִּבּוּר בְּשַׁבָּת אָסוּר, גַּם בְּדִבְרֵי תּוֹרָה","מֻתָּר לַעֲסֹק בְּמִסְחָר, אִם הוּא קָטָן מְאוֹד","חֲפָצֶיךָ אֲסוּרִים, וְחֶפְצֵי שָׁמַיִם מֻתָּרִים בְּשַׁבָּת","צָרִיךְ לִמְצֹא חֲפָצִים אֲבוּדִים וּלְהַחֲזִירָם בְּשַׁבָּת"],2,"חֲכָמִים דָּרְשׁוּ: חֲפָצֶיךָ (עִסּוּקֶיךָ) אֲסוּרִים, חֶפְצֵי שָׁמַיִם מֻתָּרִים. מִכָּאן שֶׁאָסוּר לַעֲסֹק בְּשַׁבָּת בְּצָרְכֵי חֹל כְּמִסְחָר.","פֶּרֶק נ״א, הֲלָכָה א׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["מָהוּ ״שְׂכַר שַׁבָּת״ שֶׁאָסוּר לְשַׁלֵּם?",["שָׂכָר הַנִּתָּן עַל עֲבוֹדָה שֶׁנַּעֲשְׂתָה בְּשַׁבָּת","מַתָּנָה שֶׁנּוֹתְנִים לַמּוֹרֶה לִכְבוֹד יוֹם שַׁבָּת","כֶּסֶף שֶׁקּוֹנִים בּוֹ יַיִן לִסְעוּדַת שַׁבָּת","מַס שֶׁמְּשַׁלְּמִים לַמֶּלֶךְ פַּעַם בְּכָל שָׁבוּעַ"],0,"״שְׂכַר שַׁבָּת״ הוּא שָׂכָר הַנִּתָּן עַל עֲבוֹדָה שֶׁנֶּעֶשְׂתָה בְּשַׁבָּת, וְאָסוּר לְשַׁלֵּם אוֹתוֹ.","פֶּרֶק נ״א, הֲלָכָה ב׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["מֶלְצָרִים בְּמָלוֹן עוֹבְדִים גַּם בְּשַׁבָּת. כֵּיצַד מֻתָּר לְשַׁלֵּם לָהֶם?",["בְּתַשְׁלוּם נִפְרָד וּמְיֻחָד רַק עַל יוֹם הַשַּׁבָּת","אָסוּר לְשַׁלֵּם לָהֶם כְּלָל עַל שׁוּם עֲבוֹדָה","מְשַׁלְּמִים לָהֶם בְּתוֹךְ הַשַּׁבָּת, מִיָּד אַחֲרֵי הָעֲבוֹדָה","בְּהַבְלָעָה, יַחַד עִם שְׂכַר הָעֲבוֹדָה בִּימֵי הַחֹל"],3,"מְשַׁלְּמִים בְּבַת אַחַת עַל יְמֵי הַחֹל וְעַל הַשַּׁבָּת, וְכָךְ שְׂכַר הַשַּׁבָּת ״נִבְלָע״ בִּשְׂכַר הָעֲבוֹדָה הַכּוֹלֵל.","פֶּרֶק נ״א, הֲלָכָה ג׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["חַזָּן וְרוֹפֵא עוֹבְדִים בְּשַׁבָּת. מַדּוּעַ מֻתָּר לְשַׁלֵּם לָהֶם?",["כִּי עֲבוֹדָתָם קָשָׁה וְהֵם עֲיֵפִים בְּסוֹף הַשָּׁבוּעַ","כִּי הֵם אֵינָם יְכוֹלִים לִשְׁמֹר שַׁבָּת בְּשׁוּם מָקוֹם","כִּי זוֹ מִצְוָה, וְרוֹפְאִים עוֹסְקִים בְּהַצָּלַת נְפָשׁוֹת","כִּי הַמְּדִינָה מְשַׁלֶּמֶת לָהֶם וְלֹא אָדָם פְּרָטִי"],2,"מֻתָּר לְשַׁלֵּם שְׂכַר שַׁבָּת עַל דְּבַר מִצְוָה (חַזָּנִים, קוֹרְאִים, תּוֹקְעִים, מַעֲבִירֵי שִׁעוּרִים), וּלְרוֹפְאִים וְאַנְשֵׁי בִּטָּחוֹן – כִּי אֵין מִצְוָה גְּדוֹלָה מֵהַצָּלַת נְפָשׁוֹת. וְהַמַּחְמִיר לְהַבְלִיעַ – תָּבוֹא עָלָיו בְּרָכָה.","פֶּרֶק נ״א, הֲלָכוֹת ד׳-ה׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["מַדּוּעַ אָסוּר לָתֵת מַתָּנָה רְגִילָה בְּשַׁבָּת?",["כִּי אָסוּר לִשְׂמֹחַ יוֹתֵר מִדַּי בְּיוֹם הַשַּׁבָּת","כִּי עֲטִיפַת הַמַּתָּנָה בִּנְיָר הִיא תָּמִיד מְלָאכָה","כִּי מַתָּנוֹת נוֹתְנִים רַק בְּיוֹם הֻלֶּדֶת אוֹ בְּחַג","כִּי זֶה דּוֹמֶה לְמִקָּח וּמִמְכָּר, הַחֵפֶץ עוֹבֵר לְאַחֵר"],3,"מַתָּנָה דּוֹמָה לְמִקָּח וּמִמְכָּר, שֶׁהֲרֵי הַחֵפֶץ עוֹבֵר מֵאָדָם לְאָדָם. אֲבָל מַתָּנָה לְצֹרֶךְ שַׁבָּת אוֹ מִצְוָה מֻתֶּרֶת.","פֶּרֶק נ״א, הֲלָכָה ו׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["כֵּיצַד אֶפְשָׁר שֶׁמַּתָּנָה רְגִילָה תִּהְיֶה שֶׁל הֶחָבֵר בְּשַׁבָּת?",["בְּיוֹם שִׁשִּׁי, אָדָם אַחֵר זוֹכֶה בָּהּ בִּשְׁבִילוֹ וּמַגְבִּיהַּ טֶפַח","נוֹתְנִים אוֹתָהּ בְּשַׁבָּת, אֲבָל בְּלִי לוֹמַר אַף מִלָּה","מַנִּיחִים אוֹתָהּ בְּשַׁבָּת עַל הַשֻּׁלְחָן וְהוּא לוֹקֵחַ לְבַד","שׁוֹלְחִים אוֹתָהּ עִם יֶלֶד קָטָן בְּשַׁבָּת אַחַר הַצָּהֳרַיִם"],0,"בְּיוֹם שִׁשִּׁי אוֹמְרִים לְאָדָם אַחֵר ״זְכֵה בְּחֵפֶץ זֶה בִּשְׁבִיל פְּלוֹנִי״, וְהוּא מֵרִים אוֹתוֹ טֶפַח לְפָחוֹת – וְכָךְ הַמַּתָּנָה שַׁיֶּכֶת לֶחָבֵר כְּבָר לִפְנֵי שַׁבָּת.","פֶּרֶק נ״א, הֲלָכָה ז׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["עַל אֵיזֶה עִנְיָן כַּסְפִּי מֻתָּר לְדַבֵּר בְּשַׁבָּת?",["מְחִיר הַדִּירָה שֶׁרוֹצִים לִקְנוֹת בַּשָּׁבוּעַ","כַּמָּה תַּרְוִיחַ הַחֲנוּת בְּיוֹם רִאשׁוֹן","עִנְיְנֵי צְדָקָה וּמְכִירַת עֲלִיּוֹת לַתּוֹרָה","הַמִּבְצָעִים בַּשּׁוּק לִקְרַאת הַשָּׁבוּעַ הַבָּא"],2,"מֻתָּר לְדַבֵּר בְּחֶפְצֵי שָׁמַיִם: צְדָקָה, שִׁדּוּכִים, הַתְרָמָה לְמוֹסְדוֹת תּוֹרָה וָחֶסֶד וּמְכִירַת עֲלִיּוֹת לַתּוֹרָה.","פֶּרֶק נ״א, הֲלָכָה ח׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["מָה הַדִּין לְגַבֵּי תִּכְנוּן דִּבְרֵי חֹל בְּשַׁבָּת?",["מֻתָּר לְדַבֵּר, אֲבָל אָסוּר לַחְשֹׁב עֲלֵיהֶם בַּלֵּב","אָסוּר לְדַבֵּר עֲלֵיהֶם, וְהִרְהוּר בַּלֵּב בִּלְבַד מֻתָּר","מֻתָּר גַּם לְדַבֵּר וְגַם לַחְשֹׁב בְּלִי שׁוּם הַגְבָּלָה","אָסוּר רַק לִכְתֹּב אוֹתָם, אֲבָל לוֹמַר מֻתָּר"],1,"״לֹא יִהְיֶה דִּבּוּרְךָ בְּשַׁבָּת כְּדִבּוּרְךָ בְּחֹל״ – אָסוּר לוֹמַר ״מָחָר אֶקְנֶה דָּבָר זֶה״. הִרְהוּר בַּלֵּב בִּלְבַד מֻתָּר, וְרָאוּי לְהִמָּנַע גַּם מִמֶּנּוּ.","פֶּרֶק נ״א, הֲלָכוֹת ט׳-י׳","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["הַשַּׁבָּת נִתְּנָה לְתוֹרָה. מָה כָּתוּב עַל קְרִיאַת עִתּוֹנִים בְּשַׁבָּת?",["כֻּלָּם מַסְכִּימִים שֶׁמֻּתָּר, וְכָךְ רָאוּי לְבַלּוֹת אֶת כָּל הַיּוֹם","כֻּלָּם מַסְכִּימִים שֶׁאָסוּר, וְהַקּוֹרֵא עִתּוֹן חַיָּב לְהָבִיא קָרְבָּן","מֻתָּר לִקְרֹא רַק עִתּוֹן שֶׁיָּצָא לָאוֹר לִפְנֵי שָׁבוּעַ","יֵשׁ מַתִּירִים וְיֵשׁ אוֹסְרִים, וְהַנִּמְנָע וְלוֹמֵד תּוֹרָה תָּבוֹא עָלָיו בְּרָכָה"],3,"רָאוּי לְהַרְבּוֹת בְּשַׁבָּת בְּתוֹרָה, בְּפָרָשַׁת הַשָּׁבוּעַ וּבִתְהִלִּים. בְּעִתּוֹנִים יֵשׁ אוֹמְרִים שֶׁמֻּתָּר וְיֵשׁ אוֹמְרִים שֶׁאָסוּר, וְהַנִּמְנָע וּמַקְדִּישׁ אֶת הַיּוֹם לְתוֹרָה – תָּבוֹא עָלָיו בְּרָכָה.","פֶּרֶק נ״א, הֲלָכוֹת י״א-י״ב","מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר"],["כֵּיצַד קְשׁוּרָה מְלֶאכֶת הַהוֹצָאָה לַמִּשְׁכָּן?",["הַתּוֹרְמִים הֶעֱבִירוּ תְּרוּמוֹת מֵאָהֳלֵיהֶם לְמַחֲנֵה לְוִיָּה","הַכֹּהֲנִים הוֹצִיאוּ אֶת הָאֵפֶר מִן הַמִּזְבֵּחַ","הָעָם הוֹצִיא אֶת הַמָּן מֵהַמַּחֲנֶה הַחוּצָה","מֹשֶׁה הוֹצִיא אֶת הַלּוּחוֹת מֵהָהָר לַמַּחֲנֶה"],0,"הַתּוֹרְמִים הֶעֱבִירוּ אֶת הַתְּרוּמוֹת מֵרְשׁוּת הַיָּחִיד (אָהֳלֵיהֶם) לִרְשׁוּת הָרַבִּים (מַחֲנֵה לְוִיָּה), וְלָכֵן נֶאֶסְרָה הַהוֹצָאָה בְּשַׁבָּת.","פֶּרֶק נ״ב, הֲלָכָה א׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָה מַרְוִיחִים מֵאִסּוּר הַהוֹצָאָה מֵרְשׁוּת לִרְשׁוּת?",["שֶׁהָרְחוֹבוֹת נִשְׁאָרִים נְקִיִּים וּשְׁקֵטִים כָּל הַשַּׁבָּת","מִתְחַזְּקִים יְסוֹדוֹת הַמִּשְׁפָּחָה וְלִמּוּד הַתּוֹרָה","שֶׁאֵין צֹרֶךְ לִקְנוֹת דְּבָרִים חֲדָשִׁים לַשַּׁבָּת","שֶׁהַשְּׁכֵנִים אֵינָם מַפְרִיעִים זֶה לָזֶה בִּכְלָל"],1,"כָּל אֶחָד שׁוֹבֵת בְּבֵיתוֹ עִם מִשְׁפַּחְתּוֹ, וְעַל יְדֵי כָּךְ מִתְחַזְּקִים יְסוֹדוֹת הַמִּשְׁפָּחָה וְלִמּוּד הַתּוֹרָה.","פֶּרֶק נ״ב, הֲלָכָה ב׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["אֵיזֶה מֵהַמְּקוֹמוֹת הַבָּאִים נֶחְשָׁב לִרְשׁוּת הַיָּחִיד?",["רְחוֹב רָחָב שֶׁאֵין סְבִיבוֹ חוֹמָה","בִּקְעָה פְּתוּחָה וּגְדוֹלָה מִחוּץ לָעִיר","בּוֹר בְּעֹמֶק עֲשָׂרָה טְפָחִים וְרֹחַב אַרְבָּעָה","פַּח אַשְׁפָּה צַר הָעוֹמֵד בָּרְחוֹב"],2,"בּוֹר בְּעֹמֶק עֲשָׂרָה טְפָחִים וְרֹחַב אַרְבָּעָה עַל אַרְבָּעָה, וְכֵן תֵּל כָּזֶה, בַּיִת וְחָצֵר עִם גָּדֵר, הֵם רְשׁוּת הַיָּחִיד.","פֶּרֶק נ״ב, הֲלָכוֹת ג׳-ה׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָה צָרִיךְ כְּדֵי שֶׁרְחוֹב יֵחָשֵׁב רְשׁוּת הָרַבִּים?",["שֶׁיִּהְיֶה מְרֻצָּף וְיִהְיוּ בּוֹ חֲנֻיּוֹת רַבּוֹת","שֶׁיִּהְיֶה מְקוֹרֶה וּמֻקָּף חוֹמָה גְּבוֹהָה","רֹחַב שֵׁשׁ עֶשְׂרֵה אַמּוֹת, בְּלִי תִּקְרָה וּבְלִי חוֹמָה","שֶׁיַּעַבְרוּ בּוֹ לְפָחוֹת עֶשֶׂר מְכוֹנִיּוֹת"],2,"רְשׁוּת הָרַבִּים הִיא רְחוֹב, שׁוּק אוֹ רְחָבָה בְּרֹחַב שֵׁשׁ עֶשְׂרֵה אַמּוֹת בְּלִי תִּקְרָה וּבְלִי חוֹמָה. וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ גַּם שֶׁיַּעַבְרוּ בּוֹ שִׁשִּׁים רִבּוֹא אֲנָשִׁים.","פֶּרֶק נ״ב, הֲלָכָה ו׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָה הַדִּין בְּהוֹצָאָה מִכַּרְמְלִית לִרְשׁוּת הַיָּחִיד?",["מֻתָּר לְגַמְרֵי, כִּי כַּרְמְלִית הִיא מְקוֹם פְּטוּר","אָסוּר מִן הַתּוֹרָה, כְּמוֹ מֵרְשׁוּת הָרַבִּים","מֻתָּר רַק אִם הַחֵפֶץ קַל מְאֹד","חֲכָמִים אָסְרוּ לְהוֹצִיא גַּם מִכַּרְמְלִית"],3,"מִן הַתּוֹרָה אָסוּר לְהוֹצִיא מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים וּלְהֶפֶךְ, וַחֲכָמִים אָסְרוּ גַּם מִכַּרְמְלִית, כְּמוֹ יָם אוֹ בִּקְעָה.","פֶּרֶק נ״ב, הֲלָכוֹת ז׳, ט׳, י׳","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["פַּח אַשְׁפָּה צַר וְגָבוֹהַּ עוֹמֵד בָּרְחוֹב. מָה דִּינוֹ?",["הוּא רְשׁוּת הַיָּחִיד, כִּי יֵשׁ לוֹ דְּפָנוֹת","הוּא מְקוֹם פְּטוּר, וּמֻתָּר לְהוֹצִיא אֵלָיו וּמִמֶּנּוּ","הוּא כַּרְמְלִית, וְאָסוּר לְהַנִּיחַ עָלָיו דָּבָר","הוּא רְשׁוּת הָרַבִּים כְּמוֹ הָרְחוֹב שֶׁסְּבִיבוֹ"],1,"דָּבָר גָּבוֹהַּ שְׁלוֹשָׁה טְפָחִים וְצַר מֵאַרְבָּעָה עַל אַרְבָּעָה הוּא מְקוֹם פְּטוּר, וּמֻתָּר לְהוֹצִיא אֵלָיו מֵרְשׁוּת הַיָּחִיד אוֹ מֵרְשׁוּת הָרַבִּים וּלְהֶפֶךְ.","פֶּרֶק נ״ב, הֲלָכוֹת ח׳, י״א","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָה אָסוּר לַעֲשׂוֹת בִּרְשׁוּת הָרַבִּים בְּשַׁבָּת?",["לָלֶכֶת בָּרְחוֹב יוֹתֵר מֵאַרְבַּע אַמּוֹת בְּכָל מִקְרֶה","לָשֶׁבֶת עַל סַפְסָל צִבּוּרִי לְיַד הַבַּיִת","לְהַעֲבִיר מַפְתֵּחַ בַּכִּיס אַרְבַּע אַמּוֹת אוֹ יוֹתֵר","לְדַבֵּר בְּקוֹל רָם עִם חֲבֵרִים בָּרְחוֹב"],2,"אָסוּר מֵהַתּוֹרָה לְהַעֲבִיר חֵפֶץ בִּרְשׁוּת הָרַבִּים, בַּיָּד אוֹ בַּכִּיס, אַרְבַּע אַמּוֹת אוֹ יוֹתֵר. מִדִּבְרֵי חֲכָמִים זֶה אָסוּר גַּם בְּכַרְמְלִית.","פֶּרֶק נ״ב, הֲלָכוֹת י״ב-י״ג","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["אֵיזֶה דָּבָר מֻתָּר לָצֵאת אִתּוֹ לִרְשׁוּת הָרַבִּים?",["מִמְחָטָה מִנְּיָר שֶׁמֻּנַּחַת בְּתוֹךְ הַכִּיס","מַכְשִׁיר שְׁמִיעָה הַבָּטֵל לְגוּפוֹ שֶׁל הָאָדָם","פִּצּוּחִים לֶאֱכֹל בַּדֶּרֶךְ לְבֵית הַכְּנֶסֶת","סֵפֶר תְּהִלִּים קָטָן שֶׁמַּחְזִיקִים בַּיָּד"],1,"דְּבָרִים הַבְּטֵלִים לְגוּף הָאָדָם, כְּמוֹ בְּגָדִים, מִשְׁקְפַיִם, טַלִּית לְבוּשָׁה וּמַכְשִׁיר שְׁמִיעָה, אֵינָם בָּאִסּוּר. וּבִרְשׁוּת הַיָּחִיד מֻתָּר לְהַעֲבִיר בְּלִי מִגְבֶּלַת מֶרְחָק.","פֶּרֶק נ״ב, הֲלָכוֹת י״ד-ט״ו","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מַהִי ״צוּרַת הַפֶּתַח״ שֶׁל הָעֵרוּב?",["שְׁנֵי עַמּוּדִים בִּשְׁנֵי צְדָדִים, וְקָנֶה עַל גַּבָּם","שַׁעַר בַּרְזֶל כָּבֵד שֶׁנִּנְעָל בְּכָל עֶרֶב שַׁבָּת","שֶׁלֶט גָּדוֹל שֶׁכָּתוּב עָלָיו שֶׁיֵּשׁ עֵרוּב","חוֹמַת אֲבָנִים גְּבוֹהָה סְבִיב כָּל הָעִיר"],0,"צוּרַת הַפֶּתַח עֲשׂוּיָה מִשְּׁנֵי עַמּוּדִים וְקָנֶה עַל גַּבָּם, וְהַקָּנֶה יָכוֹל לִהְיוֹת בָּאֲוִיר מֵעֲלֵיהֶם. כָּךְ הַמָּקוֹם נַעֲשֶׂה רְשׁוּת הַיָּחִיד גְּדוֹלָה. יֵשׁ הַמַּחְמִירִים שֶׁאֵינָם מִשְׁתַּמְּשִׁים בְּהֶתֵּר זֶה.","פֶּרֶק נ״ב, הֲלָכָה ט״ז","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָה הַטַּעַם לְאִסּוּר תְּחוּם שַׁבָּת?",["כְּדֵי שֶׁלֹּא נִתְעֶה בַּדֶּרֶךְ בַּחֹשֶׁךְ","שֶׁנָּנוּחַ בְּמָקוֹם אֶחָד וְנִזְכֹּר שֶׁה׳ נָח","כְּדֵי שֶׁנַּסְפִּיק לֶאֱכֹל אֶת כָּל הַסְּעוּדוֹת","כִּי בְּשַׁבָּת אֵין תַּחְבּוּרָה צִבּוּרִית בַּדְּרָכִים"],1,"כְּדֵי שֶׁנִּזְכֹּר שֶׁה׳ בָּרָא אֶת הָעוֹלָם בְּשִׁשָּׁה יָמִים וְנָח בַּשְּׁבִיעִי, רָאוּי שֶׁנָּנוּחַ בְּמָקוֹם אֶחָד וְנֵלֵךְ רַק בִּדְרָכִים קְצָרוֹת שֶׁל תַּעֲנוּג וְנַחַת.","פֶּרֶק נ״ב, הֲלָכָה י״ז","אַרְבַּע רְשֻׁיּוֹת הַשַּׁבָּת"],["מָתַי נִקְרָא דָּבָר ״מֻקְצֶה״ בְּשַׁבָּת?",["כְּשֶׁהוּא כָּבֵד מְאוֹד וְקָשֶׁה לְהָרִים","כְּשֶׁלֹּא מִשְׁתַּמְּשִׁים בּוֹ בְּשַׁבָּת, וְלָכֵן מַרְחִיקִים אוֹתוֹ","כְּשֶׁהוּא שַׁיָּךְ לְאָדָם אַחֵר וְלֹא לָנוּ","כְּשֶׁהוּא מֻנָּח מִחוּץ לַבַּיִת בֶּחָצֵר"],1,"כָּל דָּבָר שֶׁאָדָם מַחְלִיט לְהַרְחִיקוֹ וְלֹא לְהִשְׁתַּמֵּשׁ בּוֹ הוּא ״מֻקְצֶה״, וְלָכֵן דָּבָר שֶׁלֹּא מִשְׁתַּמְּשִׁים בּוֹ בְּשַׁבָּת אָסוּר בְּטִלְטוּל.","פֶּרֶק נ״ג, הֲלָכָה א׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["אֵיזֶה מֵאֵלֶּה הוּא אֶחָד הַטְּעָמִים לְאִסּוּר טִלְטוּל מֻקְצֶה?",["כְּדֵי שֶׁהַכֵּלִים בַּבַּיִת לֹא יִתְלַכְלְכוּ בְּיוֹם הַשַּׁבָּת","כְּדֵי שֶׁלֹּא יִשָּׁבְרוּ כֵּלִים יְקָרִים בְּשַׁבָּת","כְּדֵי שֶׁיִּהְיֶה שֶׁקֶט בַּבַּיִת בִּשְׁעַת הַמְּנוּחָה","כְּדֵי לִשְׁמֹר שֶׁלֹּא נִגָּרֵר לַעֲשׂוֹת מְלָאכָה אֲסוּרָה"],3,"חֲכָמִים חָשְׁשׁוּ שֶׁאִם יִהְיֶה מֻתָּר לְטַלְטֵל כָּל כְּלִי, עֲלוּלִים לְהִגָּרֵר לַעֲשִׂיַּת מְלָאכָה אֲסוּרָה בְּכֵלִים אֵלּוּ.","פֶּרֶק נ״ג, הֲלָכָה ב׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["מָהוּ ״כְּלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר״, הַסּוּג הָרִאשׁוֹן שֶׁל מֻקְצֶה?",["כְּלִי שֶׁמִּשְׁתַּמְּשִׁים בּוֹ רַק בַּסְּעוּדָה שֶׁל שַׁבָּת","כְּלִי שֶׁנִּשְׁבַּר וְאֵין בּוֹ שׁוּם שִׁמּוּשׁ","כְּלִי שֶׁמְּשַׁמֵּשׁ בְּדֶרֶךְ כְּלָל לִמְלָאכָה הָאֲסוּרָה בְּשַׁבָּת","כְּלִי יָקָר מְאוֹד שֶׁשּׁוֹמְרִים עָלָיו בָּאָרוֹן"],2,"כְּלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר הוּא חֵפֶץ שֶׁמִּשְׁתַּמְּשִׁים בּוֹ בְּדֶרֶךְ כְּלָל בִּימוֹת הַחֹל לִמְלָאכָה הָאֲסוּרָה בְּשַׁבָּת, כְּמוֹ פַּטִּישׁ, עֵט וּמִסְפָּרַיִם.","פֶּרֶק נ״ג, הֲלָכוֹת ג׳-ד׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["דָּנִי רוֹצֶה לְהַכְנִיס פַּטִּישׁ מֵהֶחָצֵר כְּדֵי שֶׁלֹּא יִגָּנֵב. מָה הַדִּין?",["מֻתָּר לְהַכְנִיס בַּיָּדַיִם, כִּי זֶה לְצֹרֶךְ שְׁמִירָה","אָסוּר בַּיָּדַיִם; בִּמְקוֹם צֹרֶךְ מֻתָּר בְּעֶזְרַת הַמַּרְפֵּקִים","אָסוּר לְהַכְנִיס בְּשׁוּם אֹפֶן, גַּם לֹא בְּשִׁנּוּי","מֻתָּר רַק אִם מַחֲזִירִים אוֹתוֹ מִיָּד לֶחָצֵר"],1,"טִלְטוּל כְּדֵי לִשְׁמֹר עַל הַכְּלִי שֶׁלֹּא יִגָּנֵב אָסוּר בַּיָּדַיִם. בִּמְקוֹם צֹרֶךְ מֻתָּר בְּשִׁנּוּי – בְּעֶזְרַת הַמַּרְפֵּקִים וְכַדּוֹמֶה.","פֶּרֶק נ״ג, הֲלָכָה ה׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["מֻתָּר לְהַכּוֹת בְּפַטִּישׁ עַל אֱגוֹז בְּשַׁבָּת?",["אָסוּר, כִּי פַּטִּישׁ הוּא תָּמִיד מֻקְצֶה גָּמוּר","מֻתָּר רַק בְּשִׁנּוּי, בְּעֶזְרַת הַמַּרְפֵּקִים וְכַדּוֹמֶה","מֻתָּר רַק אִם הָאֱגוֹז שַׁיָּךְ לְאוֹרְחִים","מֻתָּר, כִּי זֶה טִלְטוּל לְצֹרֶךְ גּוּפוֹ שֶׁל הַכְּלִי"],3,"שִׁמּוּשׁ בְּגוּף הַכְּלִי לִמְלָאכָה מֻתֶּרֶת הוּא ״לְצֹרֶךְ גּוּפוֹ״, וּמֻתָּר כָּרָגִיל. מֻתָּר גַּם לְהַחְזִיק אֶת הַפַּטִּישׁ בַּיָּדַיִם עַד שֶׁמַּגִּיעִים לַמָּקוֹם שֶׁבּוֹ רוֹצִים לְהָנִיחוֹ.","פֶּרֶק נ״ג, הֲלָכוֹת ו׳-ז׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["סַכִּין מְיֻחֶדֶת לְחִתּוּךְ אָמָּנוּתִי מֻנַּחַת עַל כִּסֵּא. מָה הַדִּין?",["אָסוּר לְהָזִיזָהּ בַּיָּדַיִם, וּבִשְׁעַת הַצֹּרֶךְ מֻתָּר בְּשִׁנּוּי","מֻתָּר לְהָזִיזָהּ בַּיָּדַיִם, כִּי צָרִיךְ אֶת הַכִּסֵּא","מֻתָּר לְהָזִיזָהּ, וְגַם לַחְתֹּךְ בָּהּ יְרָקוֹת לַסְּעוּדָה","אָסוּר לָשֶׁבֶת עַל הַכִּסֵּא עַד מוֹצָאֵי שַׁבָּת"],0,"מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס אָסוּר אֲפִלּוּ לְצֹרֶךְ גּוּפוֹ וּמְקוֹמוֹ. בִּשְׁעַת הַצֹּרֶךְ מֻתָּר לְהָזִיז אֶת הַסַּכִּין בְּשִׁנּוּי – בְּעֶזְרַת הַמַּרְפֵּקִים וְכַדּוֹמֶה.","פֶּרֶק נ״ג, הֲלָכָה ח׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["אֵילוּ חֲפָצִים נֶחְשָׁבִים מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס, כְּמוֹ אָרוֹן כָּבֵד?",["חֲפָצִים קַלִּים שֶׁמַּעֲבִירִים מֵחֶדֶר לְחֶדֶר כָּל יוֹם","חֲפָצִים שֶׁמִּשְׁתַּמְּשִׁים בָּהֶם רַק בִּימוֹת הַחֹל","חֲפָצִים בִּמְקוֹם קָבוּעַ, שֶׁמַּקְפִּידִים לֹא לְהָזִיזָם","חֲפָצִים שֶׁקָּנוּ אוֹתָם בְּיוֹם שִׁשִּׁי לִפְנֵי שַׁבָּת"],2,"חֲפָצִים שֶׁיֵּשׁ לָהֶם מָקוֹם קָבוּעַ, וּמַקְפִּידִים לֹא לְהָזִיזָם כְּדֵי שֶׁלֹּא יִנָּזְקוּ, הֵם מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס.","פֶּרֶק נ״ג, הֲלָכָה ט׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["בַּעַל חֲנוּת רוֹצֶה לְהִשְׁתַּמֵּשׁ בְּכוֹסוֹת הַחֲנוּת בִּסְעוּדַת שַׁבָּת. מָה הַדִּין?",["מֻתָּר, כִּי זֶה לְצֹרֶךְ סְעוּדַת הַשַּׁבָּת","מֻתָּר, אִם יַחֲזִיר אוֹתָן מִיָּד לַחֲנוּת","מֻתָּר רַק לִשְׁתּוֹת מַיִם, לֹא יַיִן","אָסוּר, כִּי הֵן סְחוֹרָה הָעוֹמֶדֶת לִמְכִירָה"],3,"סְחוֹרָה לִמְכִירָה שֶׁמַּקְפִּידִים לֹא לְהִשְׁתַּמֵּשׁ בָּהּ, כְּדֵי שֶׁלֹּא לִפְגֹּעַ בְּשָׁוְיָהּ, אֲסוּרָה בְּטִלְטוּל – גַּם לְצֹרֶךְ גּוּפָהּ וְגַם לְצֹרֶךְ מְקוֹמָהּ.","פֶּרֶק נ״ג, הֲלָכָה י׳","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["מָה נִקְרָא ״מֻקְצֶה מֵחֲמַת גּוּפוֹ״, וּמָה דִּינוֹ?",["דָּבָר שֶׁאֵינוֹ כְּלִי וְאֵינוֹ מַאֲכָל; אָסוּר בַּיָּדַיִם","כְּלִי יָקָר שֶׁשּׁוֹמְרִים עָלָיו בָּאָרוֹן; מֻתָּר לְצֹרֶךְ מְקוֹמוֹ","מַאֲכָל שֶׁנִּשְׁאַר מֵהַסְּעוּדָה; אָסוּר לְהַחְזִירוֹ לַמְּקָרֵר","כְּלִי לִמְלָאכָה אֲסוּרָה; מֻתָּר לְצֹרֶךְ גּוּפוֹ וּמְקוֹמוֹ"],0,"דָּבָר שֶׁאֵינוֹ כְּלִי רָאוּי וְאֵינוֹ מַאֲכַל אָדָם אוֹ בְּהֵמָה הוּא מֻקְצֶה מֵחֲמַת גּוּפוֹ. אָסוּר לְטַלְטְלוֹ בַּיָּדַיִם אֲפִלּוּ לְצֹרֶךְ גּוּפוֹ וּמְקוֹמוֹ, וּבִשְׁעַת הַצֹּרֶךְ מֻתָּר בְּשִׁנּוּי.","פֶּרֶק נ״ג, הֲלָכוֹת י״א-י״ב","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["צַלַּחַת נִשְׁבְּרָה, וְהַשְּׁבָרִים רְאוּיִים לְשִׁמּוּשׁ כָּלְשֶׁהוּ. מָה הַדִּין?",["אָסוּר לְטַלְטֵל, כִּי כָּל כְּלִי שָׁבוּר מֻקְצֶה","מֻתָּר לְטַלְטֵל רַק בְּשִׁנּוּי, בְּעֶזְרַת הַמַּרְפֵּקִים","מֻתָּר לְטַלְטֵל, כִּי הַשְּׁבָרִים רְאוּיִים לְשִׁמּוּשׁ","מֻתָּר רַק אִם הַצַּלַּחַת נִשְׁבְּרָה בְּשַׁבָּת עַצְמָהּ"],2,"מֻתָּר לְטַלְטֵל כֵּלִים שֶׁנִּשְׁבְּרוּ אִם הַשְּׁבָרִים רְאוּיִים לְשִׁמּוּשׁ כָּלְשֶׁהוּ. אִם אֵינָם רְאוּיִים לְשׁוּם שִׁמּוּשׁ – אָסוּר.","פֶּרֶק נ״ג, הֲלָכָה י״ג","מֻקְצֶה בְּשַׁבָּת – חֵלֶק א׳"],["מָה הַדֶּרֶךְ הָעֲדִיפָה לְסַלֵּק שִׁבְרֵי זְכוּכִית מֵהַדֶּרֶךְ בְּשַׁבָּת?",["אָסוּר לְסַלֵּק אוֹתָם עַד צֵאת הַשַּׁבָּת","לְבַקֵּשׁ מִשָּׁכֵן לְסַלֵּק אוֹתָם בִּמְקוֹמֵנוּ","בְּלִי לָגַעַת בַּשְּׁבָרִים יְשִׁירוֹת, כְּשֶׁהַדָּבָר אֶפְשָׁרִי","לְהָרִים כָּל שֶׁבֶר בַּיָּדַיִם וְלִזְרֹק לַפַּח"],2,"מֻתָּר לְסַלֵּק שְׁבָרִים שֶׁעֲלוּלִים לְהַזִּיק, וְעָדִיף בְּלִי לָגַעַת בָּהֶם יְשִׁירוֹת.","פֶּרֶק נ״ג, הֲלָכָה י״ד","מֻקְצֶה – חֵלֶק ב׳"],["אֵיזֶה זוּג חֲפָצִים הוּא מֻקְצֶה בְּשַׁבָּת?",["עוּגָה מוּכָנָה וּשְׁעוֹן יַד שֶׁפּוֹעֵל הֵיטֵב","סֵפֶר תְּהִלִּים וְכַדּוּר מִשְׂחָק בַּחֶדֶר","מַטְבֵּעַ שֶׁיִּחֲדוּ לְשִׁמּוּשׁ מֻתָּר, וּבָשָׂר לֹא מְבֻשָּׁל","חֹל בְּאַרְגַּז חֹל וּבַקְבּוּק מַיִם קָרִים"],2,"מַטְבְּעוֹת מֻקְצֶה גַּם אִם יִחֲדוּ אוֹתָם לְשִׁמּוּשׁ מֻתָּר, וּבָשָׂר שֶׁצָּרִיךְ בִּשּׁוּל מֻקְצֶה לִפְנֵי הַבִּשּׁוּל.","פֶּרֶק נ״ג, הֲלָכוֹת י״ז-י״ח","מֻקְצֶה – חֵלֶק ב׳"],["עַל הַשֻּׁלְחָן יֵשׁ כַּמּוּת קְטַנָּה שֶׁל קְלִפּוֹת. אֵיךְ מְסַלְּקִים אוֹתָן?",["מְסַלְּקִים אוֹתָן בַּיָּדַיִם, כִּי זוֹ כַּמּוּת קְטַנָּה","אָסוּר לְהָזִיז אוֹתָן עַד מוֹצָאֵי שַׁבָּת","מְנַעֲרִים אֶת הַמַּפָּה בַּחוּץ מִיָּד","גּוֹרְרִים אוֹתָן בְּעֶזְרַת סַכִּין אוֹ מַזְלֵג"],3,"שְׁאֵרִיּוֹת עַל הַשֻּׁלְחָן גּוֹרְרִים בְּסַכִּין אוֹ מַזְלֵג. רַק כַּמּוּת גְּדוֹלָה שֶׁמַּמְאִיסָה אֶת הַמָּקוֹם מֻתָּר לְסַלֵּק בַּיָּדַיִם.","פֶּרֶק נ״ג, הֲלָכוֹת י״ט-כ׳","מֻקְצֶה – חֵלֶק ב׳"],["מָה דִּינוֹ שֶׁל שְׁעוֹן יַד בְּשַׁבָּת?",["כָּל שְׁעוֹן יַד הוּא מֻקְצֶה בְּכָל מַצָּב","שָׁעוֹן שֶׁפּוֹעֵל מֻתָּר, וְשָׁעוֹן מְקֻלְקָל הוּא מֻקְצֶה","שָׁעוֹן מְקֻלְקָל מֻתָּר, וְשָׁעוֹן שֶׁפּוֹעֵל אָסוּר","כָּל שָׁעוֹן מֻתָּר, גַּם אִם הוּא מְקֻלְקָל"],1,"שְׁעוֹן יַד שֶׁפּוֹעֵל אֵינוֹ מֻקְצֶה, וְאִם הוּא מְקֻלְקָל – מֻקְצֶה.","פֶּרֶק נ״ג, הֲלָכָה כ״א","מֻקְצֶה – חֵלֶק ב׳"],["פָּמוֹטוֹת יְקָרִים הָיוּ עַל שֻׁלְחָן בֵּין הַשְּׁמָשׁוֹת. תִּכְנְנוּ לְהָזִיז אוֹתָם וְשָׁכְחוּ. מָה מֻתָּר?",["לְהָרִים אֶת הַפָּמוֹטוֹת בַּיָּדַיִם וּלְהַעֲבִיר","לְהַזִּיז אֶת הַשֻּׁלְחָן עִם הַפָּמוֹטוֹת לַחֶדֶר","לְהַטּוֹת אֶת הַשֻּׁלְחָן כְּדֵי לְהַפִּיל אֶת הַמֻּקְצֶה","אֵין שׁוּם דֶּרֶךְ, הַשֻּׁלְחָן נִשְׁאָר מֻקְצֶה תָּמִיד"],2,"שֻׁלְחָן כָּזֶה הוּא בָּסִיס לְדָבָר הָאָסוּר, אֲבָל כְּשֶׁתִּכְנְנוּ לְהָזִיז וְשָׁכְחוּ – מֻתָּר לְהַטּוֹתוֹ, וְהוּא אֵינוֹ מֻקְצֶה.","פֶּרֶק נ״ג, הֲלָכוֹת כ״ב-כ״ג","מֻקְצֶה – חֵלֶק ב׳"],["מַדּוּעַ אָסוּר לְטַלְטֵל פָּמוֹט גַּם אַחֲרֵי שֶׁהַנֵּר כָּבָה?",["כִּי הַפָּמוֹט עָשׂוּי מִכֶּסֶף יָקָר מְאֹד","כִּי אוּלַי הַנֵּר יִדָּלֵק שׁוּב מֵעַצְמוֹ","כִּי אָסוּר לָגַעַת בְּשׁוּם כְּלִי מַתֶּכֶת","הַפָּמוֹט בָּסִיס לַנֵּר, וְהַנֵּר בָּסִיס לַשַּׁלְהֶבֶת"],3,"הַפָּמוֹט הוּא בָּסִיס לַנֵּר, וְהַנֵּר הוּא בָּסִיס לַשַּׁלְהֶבֶת.","פֶּרֶק נ״ג, הֲלָכָה כ״ד","מֻקְצֶה – חֵלֶק ב׳"],["מָה הַהֶבְדֵּל בֵּין נוֹלָד גָּמוּר לְנוֹלָד לֹא גָּמוּר בְּשַׁבָּת?",["גָּמוּר אָסוּר בְּשַׁבָּת, וְלֹא גָּמוּר מֻתָּר בְּשַׁבָּת","שְׁנֵיהֶם מֻתָּרִים בְּשַׁבָּת וַאֲסוּרִים רַק בְּיוֹם טוֹב","שְׁנֵיהֶם אֲסוּרִים בְּשַׁבָּת וּמֻתָּרִים בְּיוֹם טוֹב","גָּמוּר מֻתָּר בְּשַׁבָּת, וְלֹא גָּמוּר אָסוּר"],0,"נוֹלָד גָּמוּר אָסוּר בְּשַׁבָּת וּבְיוֹם טוֹב. נוֹלָד לֹא גָּמוּר מֻתָּר בְּשַׁבָּת וְאָסוּר בְּיוֹם טוֹב.","פֶּרֶק נ״ג, הֲלָכָה כ״ה","מֻקְצֶה – חֵלֶק ב׳"],["לְכָל הַדֵּעוֹת, אֵיפֹה מֻתָּר לָשִׂים קֻבִּיַּת קֶרַח בְּשַׁבָּת?",["בְּתוֹךְ כּוֹס שֶׁיֵּשׁ בָּהּ כְּבָר מַשְׁקֶה","בְּתוֹךְ כּוֹס רֵיקָה שֶׁאֵין בָּהּ כְּלוּם","רַק בְּתוֹךְ קְעָרָה גְּדוֹלָה עַל הַשַּׁיִשׁ","אֵין מָקוֹם, קֶרַח אָסוּר לְכָל הַדֵּעוֹת"],0,"בְּכוֹס עִם מַשְׁקֶה הַמַּיִם שֶׁמַּפְשִׁירִים אֵינָם נִכָּרִים, וְלָכֵן מֻתָּר לְכָל הַדֵּעוֹת.","פֶּרֶק נ״ג, הֲלָכָה כ״ו","מֻקְצֶה – חֵלֶק ב׳"],["מַדּוּעַ רַבִּים מַתִּירִים לְהַכְנִיס מַיִם לַמַּקְפִּיא בְּשַׁבָּת?",["כִּי מַיִם אֵינָם מֻקְצֶה בְּשׁוּם מַצָּב בָּעוֹלָם","כִּי הַמַּקְפִּיא פּוֹעֵל לְבַד בְּלִי שֶׁנִּגַּע בּוֹ","כִּי קֶרַח שֶׁנַּעֲשָׂה בְּשַׁבָּת הוּא נוֹלָד גָּמוּר","כִּי הַקֶּרַח יַפְשִׁיר מִיָּד כְּשֶׁיּוֹצִיאוּ אוֹתוֹ"],3,"הַקֶּרַח אֵינוֹ נֶחְשָׁב נוֹלָד, שֶׁהֲרֵי כְּשֶׁיּוֹצִיאוּ אוֹתוֹ יַפְשִׁיר מִיָּד וְיַחְזֹר לִהְיוֹת מַיִם.","פֶּרֶק נ״ג, הֲלָכָה כ״ז","מֻקְצֶה – חֵלֶק ב׳"],["מָה הָיְתָה הַמִּצְוָה הָרִאשׁוֹנָה שֶׁנִּצְטַוּוּ בָּהּ יִשְׂרָאֵל?",["לֶאֱכֹל מַצָּה בְּלֵיל הַפֶּסַח בְּאֶרֶץ מִצְרַיִם","לְקַדֵּשׁ אֶת הַחֹדֶשׁ עַל פִּי הַלְּבָנָה","לִשְׁמֹר אֶת יוֹם הַשַּׁבָּת בְּכָל שָׁבוּעַ","לְהָנִיחַ תְּפִלִּין בְּכָל יוֹם בַּבֹּקֶר"],1,"הַמִּצְוָה הָרִאשׁוֹנָה הִיא לְקַדֵּשׁ אֶת הַחֹדֶשׁ, כְּלוֹמַר לִקְבֹּעַ אֶת רֹאשׁ הַחֹדֶשׁ עַל פִּי רְאִיַּת הַלְּבָנָה: ״הַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים״.","פֶּרֶק נ״ד, הֲלָכָה א׳","רֹאשׁ חֹדֶשׁ"],["סִבּוּב הַיָּרֵחַ אוֹרֵךְ מְעַט יוֹתֵר מֵעֶשְׂרִים וְתִשְׁעָה וָחֵצִי יָמִים. כַּמָּה יָמִים יֵשׁ בְּחֹדֶשׁ עִבְרִי?",["תָּמִיד בְּדִיּוּק שְׁלוֹשִׁים וְאֶחָד יָמִים","עֶשְׂרִים וְתִשְׁעָה אוֹ שְׁלוֹשִׁים יָמִים","תָּמִיד עֶשְׂרִים וּשְׁמוֹנָה יָמִים בְּלִי שִׁנּוּי","עֶשְׂרִים וְתִשְׁעָה וָחֵצִי יָמִים בְּדִיּוּק"],1,"יֵשׁ חֳדָשִׁים חֲסֵרִים בְּנֵי 29 יָמִים וְחֳדָשִׁים מְלֵאִים בְּנֵי 30 יָמִים. אִם בָּאוּ עֵדִים בְּלֵיל הַשְּׁלוֹשִׁים, הַחֹדֶשׁ הַקּוֹדֵם חָסֵר; וְאִם לֹא בָּאוּ, הוּא מָלֵא.","פֶּרֶק נ״ד, הֲלָכוֹת ג׳-ד׳","רֹאשׁ חֹדֶשׁ"],["לָמָּה מוֹסִיפִים חֹדֶשׁ אֲדָר בְּשָׁנָה מְעֻבֶּרֶת?",["כְּדֵי שֶׁיִּהְיוּ יוֹתֵר יְמֵי פּוּרִים בַּשָּׁנָה","כְּדֵי שֶׁרֹאשׁ הַשָּׁנָה יָחוּל תָּמִיד בַּקַּיִץ","כְּדֵי שֶׁחַג הַפֶּסַח יָחוּל תָּמִיד בָּאָבִיב","כִּי כָּךְ רָאוּ עֵדִים אֶת הַמּוֹלָד"],2,"שְׁנַת הַלְּבָנָה (354 יָמִים) קְצָרָה מִשְּׁנַת הַחַמָּה (365 יָמִים) בְּ-11 יָמִים. לָכֵן בְּמַחְזוֹר שֶׁל 19 שָׁנִים יֵשׁ 7 שָׁנִים מְעֻבָּרוֹת, וּמוֹסִיפִים אֲדָר כְּדֵי שֶׁפֶּסַח יָחוּל בָּאָבִיב.","פֶּרֶק נ״ד, הֲלָכָה ה׳","רֹאשׁ חֹדֶשׁ"],["רֹאשׁ חֹדֶשׁ חָל בְּשַׁבָּת. מָה עוֹשִׂים בִּסְעוּדַת הַשַּׁבָּת?",["מְכִינִים מָנָה נוֹסֶפֶת לִכְבוֹד רֹאשׁ חֹדֶשׁ","אוֹכְלִים רַק מָנָה אַחַת קְטַנָּה בִּלְבַד","מְוַתְּרִים עַל הַסְּעוּדָה וְצָמִים כָּל הַיּוֹם","דּוֹחִים אֶת רֹאשׁ חֹדֶשׁ לְיוֹם רִאשׁוֹן"],0,"מִצְוָה לְהַרְבּוֹת מַאֲכָלִים בִּסְעוּדַת רֹאשׁ חֹדֶשׁ, וּכְשֶׁהוּא חָל בְּשַׁבָּת מְכִינִים מָנָה נוֹסֶפֶת בִּסְעוּדַת הַשַּׁבָּת לִכְבוֹדוֹ.","פֶּרֶק נ״ד, הֲלָכוֹת ו׳-ז׳","רֹאשׁ חֹדֶשׁ"],["אֵיךְ רָאוּי לְכַבֵּד אֶת רָאשֵׁי הֶחֳדָשִׁים?",["בִּלְבִישַׁת בִּגְדֵי עֲבוֹדָה יְשָׁנִים וּפְשׁוּטִים","בְּכִבּוּי כָּל הַנֵּרוֹת שֶׁבַּבַּיִת בָּעֶרֶב","בְּיוֹם תַּעֲנִית וּבְלִי שׁוּם סְעוּדָה","בִּלְבוּשׁ נָאֶה, וְיֵשׁ מַרְבִּים בְּהַדְלָקַת נֵרוֹת"],3,"רָאוּי לְכַבֵּד אֶת רָאשֵׁי הֶחֳדָשִׁים בִּלְבוּשׁ נָאֶה, וְיֵשׁ נוֹהֲגִים לְהַרְבּוֹת בְּהַדְלָקַת נֵרוֹת לִכְבוֹד רֹאשׁ חֹדֶשׁ.","פֶּרֶק נ״ד, הֲלָכָה ח׳","רֹאשׁ חֹדֶשׁ"],["שָׁכַח ״יַעֲלֶה וְיָבוֹא״ וְנִזְכַּר אַחֲרֵי שֶׁהִתְחִיל ״הַטּוֹב וְהַמֵּטִיב״. מָה דִּינוֹ?",["חוֹזֵר וּמְבָרֵךְ שׁוּב אֶת כָּל בִּרְכַּת הַמָּזוֹן","אֵינוֹ חוֹזֵר, וְאֵינוֹ צָרִיךְ לְהַשְׁלִים דָּבָר","אוֹכֵל שׁוּב לֶחֶם וּמְבָרֵךְ מֵחָדָשׁ","אוֹמֵר ״יַעֲלֶה וְיָבוֹא״ בְּסוֹף הַבְּרָכָה"],1,"אִם נִזְכַּר לִפְנֵי ״הַטּוֹב וְהַמֵּטִיב״ אוֹמֵר ״בָּרוּךְ שֶׁנָּתַן רָאשֵׁי חֳדָשִׁים לְעַמּוֹ יִשְׂרָאֵל לְזִכָּרוֹן״. אֲבָל אִם כְּבָר הִתְחִיל ״הַטּוֹב וְהַמֵּטִיב״ – אֵינוֹ חוֹזֵר.","פֶּרֶק נ״ד, הֲלָכָה י׳","רֹאשׁ חֹדֶשׁ"],["בְּאֵיזוֹ בְּרָכָה בַּתְּפִלָּה אוֹמְרִים ״יַעֲלֶה וְיָבוֹא״?",["בְּבִרְכַּת ״רְצֵה״, בְּעַרְבִית בְּשַׁחֲרִית וּבְמִנְחָה","בְּבִרְכַּת ״אָבוֹת״, רַק בִּתְפִלַּת שַׁחֲרִית","בְּבִרְכַּת ״שִׂים שָׁלוֹם״, רַק בְּמִנְחָה","בְּבִרְכַּת ״הַשָּׁנִים״, רַק בִּתְפִלַּת עַרְבִית"],0,"בְּעַרְבִית, בְּשַׁחֲרִית וּבְמִנְחָה אוֹמְרִים ״יַעֲלֶה וְיָבוֹא״ בְּבִרְכַּת ״רְצֵה״.","פֶּרֶק נ״ד, הֲלָכָה י״א","רֹאשׁ חֹדֶשׁ"],["מָה הַדִּין בְּמִי שֶׁשָּׁכַח ״יַעֲלֶה וְיָבוֹא״ בְּרֹאשׁ חֹדֶשׁ?",["בְּכָל שָׁלֹשׁ הַתְּפִלּוֹת אֵינוֹ צָרִיךְ לַחְזֹר כְּלָל","בְּכָל שָׁלֹשׁ הַתְּפִלּוֹת עָלָיו לַחְזֹר וּלְהִתְפַּלֵּל שׁוּב","בְּעַרְבִית אֵינוֹ חוֹזֵר, וּבְשַׁחֲרִית וּבְמִנְחָה חוֹזֵר","רַק בְּעַרְבִית חוֹזֵר, כִּי הַלַּיְלָה חָשׁוּב יוֹתֵר"],2,"בְּעַרְבִית אֵינוֹ חוֹזֵר, כִּי בֵּית הַדִּין אֵינוֹ מְקַדֵּשׁ אֶת הַחֹדֶשׁ בַּלַּיְלָה. בְּשַׁחֲרִית וּבְמִנְחָה עָלָיו לַחְזֹר לְפִי הַכְּלָלִים.","פֶּרֶק נ״ד, הֲלָכוֹת י״ב-י״ג","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["לְמָה רוֹמֶזֶת הַלְּבָנָה הַמִּתְחַדֶּשֶׁת בְּרֹאשׁ חֹדֶשׁ?",["הִיא רוֹמֶזֶת לְכָךְ שֶׁהַחֹדֶשׁ יִהְיֶה קַר","הִיא רוֹמֶזֶת לִזְמַן הַקָּצִיר שֶׁל הַשָּׂדוֹת","הִיא רוֹמֶזֶת שֶׁצָּרִיךְ לִישֹׁן מֻקְדָּם יוֹתֵר","הִיא רוֹמֶזֶת לְהִתְחַדְּשׁוּת עַם יִשְׂרָאֵל וְלִגְאֻלָּתוֹ"],3,"זֶה אֶחָד מֵהַטְּעָמִים לַאֲמִירַת הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ: הַלְּבָנָה הַמִּתְחַדֶּשֶׁת רוֹמֶזֶת לְהִתְחַדְּשׁוּת עַם יִשְׂרָאֵל וְלִגְאֻלָּתוֹ.","פֶּרֶק נ״ד, הֲלָכָה ט״ו","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["לָמָּה קוֹרְאִים אֶת הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ בְּדִלּוּג?",["כִּי קְרִיאַת הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ הִיא מִנְהָג","כִּי בְּרֹאשׁ חֹדֶשׁ אֵין זְמַן רַב לְהִתְפַּלֵּל","כִּי הַיְלָדִים צְרִיכִים לְהַסְפִּיק לְהַגִּיעַ לְבֵית הַסֵּפֶר","כִּי חֵלֶק מֵהַפְּרָקִים נֶאֱמָרִים רַק בַּלַּיְלָה"],0,"קְרִיאַת הַלֵּל בְּרֹאשׁ חֹדֶשׁ הִיא מִנְהָג, וְלָכֵן קוֹרְאִים אוֹתוֹ בְּדִלּוּג.","פֶּרֶק נ״ד, הֲלָכָה ט״ז","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["מָה נָהֲגוּ בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים בְּבִרְכַּת הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ?",["מְבָרְכִים רַק כְּשֶׁקּוֹרְאִים בְּיָחִיד, וְלֹא בְּצִבּוּר","מְבָרְכִים תָּמִיד, גַּם בְּצִבּוּר וְגַם בְּיָחִיד","מְבָרְכִים פַּעֲמַיִם, בַּתְּחִלָּה וּבַסּוֹף שֶׁל הַהַלֵּל","לֹא מְבָרְכִים כְּלָל, כִּי אֵין מְבָרְכִים עַל הַמִּנְהָג"],3,"בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים לֹא מְבָרְכִים, בֵּין בְּצִבּוּר וּבֵין בְּיָחִיד, כִּי אֵין מְבָרְכִים עַל הַמִּנְהָג. וּבְחֵלֶק מֵהַקְּהִלּוֹת שְׁלִיחַ הַצִּבּוּר מְבָרֵךְ.","פֶּרֶק נ״ד, הֲלָכָה י״ז","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["מָה נוֹהֲגִים בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים בְּבִרְכַּת הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ?",["אֵינָם מְבָרְכִים, לֹא בְּצִבּוּר וְלֹא בְּיָחִיד","רַק שְׁלִיחַ הַצִּבּוּר מְבָרֵךְ, וְהַיָּחִיד אֵינוֹ מְבָרֵךְ","מְבָרְכִים עַל הַהַלֵּל, בֵּין בְּצִבּוּר וּבֵין בְּיָחִיד","מְבָרְכִים רַק כְּשֶׁרֹאשׁ חֹדֶשׁ חָל בְּשַׁבָּת"],2,"בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים נוֹהֲגִים לְבָרֵךְ עַל הַהַלֵּל בְּרֹאשׁ חֹדֶשׁ, בֵּין בְּצִבּוּר וּבֵין בְּיָחִיד.","פֶּרֶק נ״ד, הֲלָכָה י״ח","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["מָה הַדִּין לְגַבֵּי נָשִׁים וַאֲמִירַת הַלֵּל בְּרֹאשׁ חֹדֶשׁ?",["פְּטוּרוֹת, אַךְ כַּיּוֹם נוֹהֲגוֹת לוֹמַר אֶת הַהַלֵּל","חַיָּבוֹת בְּדִיּוּק כְּמוֹ גְּבָרִים, כִּי זוֹ מִצְוָה","אָסוּר לָהֶן לוֹמַר הַלֵּל, לֹא בְּצִבּוּר וְלֹא בְּיָחִיד","אוֹמְרוֹת רַק אֶת הַפֶּרֶק הָרִאשׁוֹן שֶׁל הַהַלֵּל"],0,"נָשִׁים פְּטוּרוֹת כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ, אַךְ כַּיּוֹם נוֹהֲגוֹת לוֹמַר אֶת הַהַלֵּל, וְנָשִׁים אַשְׁכְּנַזִּיּוֹת שֶׁרוֹצוֹת לְבָרֵךְ – רַשָּׁאִיּוֹת.","פֶּרֶק נ״ד, הֲלָכָה י״ט","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["לָמָּה קוֹרְאִים אֶת הַהַלֵּל בַּעֲמִידָה?",["כִּי כָּךְ שׁוֹמְעִים טוֹב יוֹתֵר אֶת הַחַזָּן","כִּי הַהַלֵּל הוּא עֵדוּת עַל הַנִּסִּים, וְעֵדוּת בַּעֲמִידָה","כִּי הַהַלֵּל קָצָר וְלֹא קָשֶׁה לַעֲמֹד בּוֹ","כִּי בְּרֹאשׁ חֹדֶשׁ אָסוּר לָשֶׁבֶת בְּבֵית הַכְּנֶסֶת"],1,"אֲמִירַת הַהַלֵּל הִיא עֵדוּת עַל הַנִּסִּים, וּמִצְוַת עֵדוּת נַעֲשֵׂית בַּעֲמִידָה, כְּמוֹ שֶׁכָּתוּב: ״הַלְלוּ עַבְדֵי ה׳ שֶׁעֹמְדִים בְּבֵית ה׳״.","פֶּרֶק נ״ד, הֲלָכָה כ׳","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["כַּמָּה עוֹלִים קוֹרְאִים לַתּוֹרָה בְּרֹאשׁ חֹדֶשׁ, וּבְאֵיזוֹ פָּרָשָׁה?",["שְׁלֹשָׁה עוֹלִים, בְּפָרָשַׁת קְרִיאַת שְׁמַע שֶׁבַּתּוֹרָה","חֲמִשָּׁה עוֹלִים, בְּפָרָשַׁת בְּרִיאַת הָעוֹלָם","אַרְבָּעָה עוֹלִים, בְּפָרָשַׁת קָרְבַּן רֹאשׁ חֹדֶשׁ","שִׁבְעָה עוֹלִים, בְּפָרָשַׁת הַשָּׁבוּעַ שֶׁל אוֹתוֹ שָׁבוּעַ"],2,"קוֹרְאִים לְאַרְבָּעָה עוֹלִים בְּפָרָשַׁת קָרְבַּן רֹאשׁ חֹדֶשׁ (בְּמִדְבַּר כ״ח), וּמִצְוָה לְהִשְׁתַּדֵּל לַעֲלוֹת לַתּוֹרָה בְּרֹאשׁ חֹדֶשׁ.","פֶּרֶק נ״ד, הֲלָכָה כ״א","רֹאשׁ חֹדֶשׁ – הַלֵּל וּקְרִיאַת הַתּוֹרָה"],["מָה מְלַמֵּד אוֹתָנוּ חִדּוּשׁ הַלְּבָנָה עַל עַם יִשְׂרָאֵל?",["עַם יִשְׂרָאֵל צָרִיךְ לְהַפְסִיק לְהִסְתַּכֵּל עַל הַשָּׁמַיִם","הַלְּבָנָה מִתְחַדֶּשֶׁת רַק פַּעַם אַחַת בְּשָׁנָה","עַם יִשְׂרָאֵל יָכוֹל לְהִתְחַדֵּשׁ וּלְהִגָּאֵל בַּגְּאֻלָּה הַשְּׁלֵמָה","הַלְּבָנָה גְּדוֹלָה מִן הַשֶּׁמֶשׁ וְלָכֵן מְבָרְכִים אוֹתָהּ"],2,"בַּבְּרָכָה אוֹמְרִים שֶׁעֲמוּסֵי בֶטֶן ״עֲתִידִים לְהִתְחַדֵּשׁ כְּמוֹתָהּ״. וּכְמוֹ שֶׁבְּכֹחָהּ שֶׁל הַלְּבָנָה לְהִתְחַדֵּשׁ, כָּךְ בְּכֹחוֹ שֶׁל עַם יִשְׂרָאֵל לְהִגָּאֵל.","פֶּרֶק נ״ה, הֲלָכוֹת א׳-ב׳","בִּרְכַּת הַלְּבָנָה"],["לָמָּה נוֹהֲגִים לְבָרֵךְ אֶת בִּרְכַּת הַלְּבָנָה תַּחַת כִּפַּת הַשָּׁמַיִם?",["כִּי בְּתוֹךְ הַבַּיִת אָסוּר לוֹמַר שׁוּם בְּרָכָה","כִּי מְבָרְכִים אֶת הַלְּבָנָה עַצְמָהּ וְצָרִיךְ לִרְאוֹתָהּ","כִּי בַּחוּץ אֶפְשָׁר לָשִׁיר בְּקוֹל רָם יוֹתֵר","כִּי הַבְּרָכָה הִיא כְּקַבָּלַת פְּנֵי הַשְּׁכִינָה"],3,"הַבְּרָכָה הִיא כְּקַבָּלַת פְּנֵי הַשְּׁכִינָה, וְאֵין זֶה מְכֻבָּד לַעֲמֹד מִתַּחַת לַגַּג. וְזוֹכְרִים שֶׁמְּבָרְכִים אֶת ה׳ – וְלֹא אֶת הַלְּבָנָה.","פֶּרֶק נ״ה, הֲלָכָה ג׳","בִּרְכַּת הַלְּבָנָה"],["מָה הַסֵּדֶר הַנָּכוֹן בִּשְׁעַת בִּרְכַּת הַלְּבָנָה?",["מְבָרְכִים בִּישִׁיבָה וּמִסְתַּכְּלִים בַּלְּבָנָה כָּל הַבְּרָכָה","מִסְתַּכְּלִים בַּלְּבָנָה, וּמְבָרְכִים בַּעֲמִידָה בְּלִי לְהִסְתַּכֵּל בָּהּ","מְבָרְכִים בַּעֲמִידָה וּמִסְתַּכְּלִים בַּלְּבָנָה כָּל הַבְּרָכָה","מְבָרְכִים בְּעֵינַיִם סְגוּרוֹת וְרַק אַחַר כָּךְ מִסְתַּכְּלִים"],1,"קֹדֶם מִסְתַּכְּלִים בַּלְּבָנָה וְנֶהֱנִים מֵאוֹרָהּ, וְאַחַר כָּךְ מְבָרְכִים בַּעֲמִידָה וּבְרַגְלַיִם יְשָׁרוֹת, אַךְ לֹא מִסְתַּכְּלִים בָּהּ בִּשְׁעַת הַבְּרָכָה.","פֶּרֶק נ״ה, הֲלָכָה ד׳","בִּרְכַּת הַלְּבָנָה"],["לָמָּה אוֹמְרִים ״דָּוִד מֶלֶךְ יִשְׂרָאֵל חַי וְקַיָּם״ אַחֲרֵי הַבְּרָכָה?",["כִּי דָּוִד הַמֶּלֶךְ חִבֵּר אֶת נֻסַּח הַבְּרָכָה","כִּי דָּוִד הַמֶּלֶךְ נוֹלַד בְּלֵיל חִדּוּשׁ הַלְּבָנָה","כִּי מַלְכוּתוֹ נִמְשְׁלָה לַלְּבָנָה וַעֲתִידָה לְהִתְחַדֵּשׁ כְּמוֹתָהּ","כִּי כָּךְ נִפְרָדִים מִן הַלְּבָנָה עַד הַחֹדֶשׁ הַבָּא"],2,"מַלְכוּת דָּוִד נִמְשְׁלָה לַלְּבָנָה, וּכְמוֹ שֶׁהַלְּבָנָה מִתְחַדֶּשֶׁת – כָּךְ עֲתִידָה מַלְכוּתוֹ לְהִתְחַדֵּשׁ.","פֶּרֶק נ״ה, הֲלָכָה ה׳","בִּרְכַּת הַלְּבָנָה"],["מָתַי אֶפְשָׁר לְבָרֵךְ אֶת בִּרְכַּת הַלְּבָנָה?",["בַּלַּיְלָה כְּשֶׁהַלְּבָנָה זוֹרַחַת, וַאֲפִלּוּ אַחֲרֵי חֲצוֹת הַלַּיְלָה","רַק בַּבֹּקֶר, כְּשֶׁהַשֶּׁמֶשׁ זוֹרַחַת וְהַלְּבָנָה נֶעֱלֶמֶת","בַּלַּיְלָה, אֲבָל רַק עַד חֲצוֹת הַלַּיְלָה בִּלְבַד","בְּכָל שָׁעָה, גַּם בַּיּוֹם וְגַם בַּלַּיְלָה"],0,"מְבָרְכִים בַּלַּיְלָה, בְּעֵת שֶׁהַלְּבָנָה זוֹרַחַת וְנֶהֱנִים מֵאוֹרָהּ, וְאֶפְשָׁר כָּל הַלַּיְלָה – אֲפִלּוּ אַחַר חֲצוֹת.","פֶּרֶק נ״ה, הֲלָכָה ו׳","בִּרְכַּת הַלְּבָנָה"],["מֵאֵימָתַי מְבָרְכִים לְפִי מִנְהַג הַסְּפָרַדִּים וּלְפִי מִנְהַג רֹב הָאַשְׁכְּנַזִּים?",["סְפָרַדִּים אַחֲרֵי שְׁלוֹשָׁה יָמִים, אַשְׁכְּנַזִּים אַחֲרֵי שִׁבְעָה יָמִים","כֻּלָּם מְבָרְכִים כְּבָר בַּלַּיְלָה הָרִאשׁוֹן שֶׁל הַחֹדֶשׁ","כֻּלָּם מְחַכִּים עַד אֶמְצַע הַחֹדֶשׁ, יוֹם חֲמִשָּׁה עָשָׂר","סְפָרַדִּים אַחֲרֵי שִׁבְעָה יָמִים, אַשְׁכְּנַזִּים אַחֲרֵי שְׁלוֹשָׁה יָמִים"],3,"מִנְהַג קְהִלּוֹת הַסְּפָרַדִּים לְבָרֵךְ אַחֲרֵי שִׁבְעָה יָמִים מִן הַמּוֹלָד, וּמִנְהַג רֹב קְהִלּוֹת הָאַשְׁכְּנַזִּים כְּבָר אַחֲרֵי שְׁלוֹשָׁה יָמִים, כִּי אָז נֶהֱנִים מֵאוֹרָהּ.","פֶּרֶק נ״ה, הֲלָכָה ז׳","בִּרְכַּת הַלְּבָנָה"],["עַד מָתַי אֶפְשָׁר לְבָרֵךְ, וּמַדּוּעַ?",["עַד סוֹף הַחֹדֶשׁ, כִּי כָּל הַחֹדֶשׁ הַלְּבָנָה נִרְאֵית","עַד הַלַּיְלָה הַשִּׁשָּׁה עָשָׂר, כִּי עַד אָז הִיא גְּדֵלָה","רַק בַּלַּיְלָה הַשְּׁבִיעִי, כִּי אָז הַלְּבָנָה הֲכִי יָפָה","עַד רֹאשׁ חֹדֶשׁ הַבָּא, כִּי אָז מַתְחִיל חֹדֶשׁ חָדָשׁ"],1,"בְּמֶשֶׁךְ חֲמִשָּׁה עָשָׂר יָמִים הַלְּבָנָה הוֹלֶכֶת וּמִתְחַדֶּשֶׁת, וּמֵאָז הִיא פּוֹחֶתֶת. לָכֵן מְבָרְכִים עַד הַלַּיְלָה הַשִּׁשָּׁה עָשָׂר, לֹא כּוֹלֵל.","פֶּרֶק נ״ה, הֲלָכָה ח׳","בִּרְכַּת הַלְּבָנָה"],["לָמָּה נוֹהֲגִים לְקַדֵּשׁ אֶת הַלְּבָנָה בְּמוֹצָאֵי שַׁבָּת, וּמָה עוֹשִׂים בְּיוֹם חֹל?",["כִּי בְּשַׁבָּת אָסוּר לָצֵאת, וּבְחֹל מְבָרְכִים בְּבִגְדֵי עֲבוֹדָה","כִּי בְּמוֹצָאֵי שַׁבָּת יֵשׁ מִנְיָן, וּבְחֹל אָסוּר לְבָרֵךְ","כִּי לְבוּשִׁים בְּגָדִים נָאִים, וּבְחֹל רָאוּי לִלְבֹּשׁ בְּגָדִים נָאִים","כִּי הַלְּבָנָה גְּדוֹלָה בְּמוֹצָאֵי שַׁבָּת, וּבְחֹל הִיא קְטַנָּה"],2,"בְּמוֹצָאֵי שַׁבָּת אָנוּ לְבוּשִׁים בִּבְגָדִים נָאִים, וְגַם בְּיוֹם חֹל רָאוּי לִלְבֹּשׁ בְּגָדִים נָאִים. בְּתִשְׁרֵי מְבָרְכִים בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים, וּבְאָב בְּמוֹצָאֵי תִּשְׁעָה בְּאָב.","פֶּרֶק נ״ה, הֲלָכוֹת ט׳-י׳","בִּרְכַּת הַלְּבָנָה"],["מָה הַדִּין כְּשֶׁיֵּשׁ עָנָן דַּק עַל הַלְּבָנָה?",["יֵשׁ שֶׁאֵינָם מְבָרְכִים, וְיֵשׁ שֶׁמְּבָרְכִים אִם נֶהֱנִים מֵאוֹרָהּ","כֻּלָּם מַסְכִּימִים שֶׁמְּבָרְכִים גַּם כְּשֶׁאֵין רוֹאִים אוֹתָהּ כְּלָל","כֻּלָּם מַסְכִּימִים שֶׁאָסוּר לְבָרֵךְ עַד שֶׁיַּעֲבֹר הַחֹדֶשׁ","מְבָרְכִים רַק אִם הֶעָנָן מְכַסֶּה אֶת כָּל הַלְּבָנָה"],0,"יֵשׁ נוֹהֲגִים לְבָרֵךְ רַק כְּשֶׁאֵין עֲנָנִים כְּלָל, וְיֵשׁ שֶׁנּוֹהֲגִים לְבָרֵךְ גַּם עִם עֲנָנִים דַּקִּים, בִּתְנַאי שֶׁנִּתָּן לֵהָנוֹת מֵאוֹרָהּ.","פֶּרֶק נ״ה, הֲלָכָה י״א","בִּרְכַּת הַלְּבָנָה"],["מָה הַדִּין שֶׁל נָשִׁים וּקְטַנִּים בְּבִרְכַּת הַלְּבָנָה?",["נָשִׁים חַיָּבוֹת לְבָרֵךְ, וּקְטַנִּים אֵינָם צְרִיכִים לְהִתְחַנֵּךְ בָּהּ","נָשִׁים פְּטוּרוֹת וְלֹא נָהֲגוּ לְבָרֵךְ, וְטוֹב לְחַנֵּךְ קְטַנִּים","כֻּלָּם פְּטוּרִים, כִּי זוֹ בְּרָכָה רַק לִגְדוֹלֵי הַדּוֹר","נָשִׁים פְּטוּרוֹת, וְגַם אָסוּר לְלַמֵּד קְטַנִּים אֶת הַבְּרָכָה"],1,"נָשִׁים פְּטוּרוֹת, כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ, וְגַם אֵלּוּ הַנּוֹהֲגוֹת לְבָרֵךְ עַל מִצְווֹת כָּאֵלֶּה נָהֲגוּ שֶׁלֹּא לְבָרֵךְ עָלֶיהָ. וְטוֹב לְחַנֵּךְ אֶת הַקְּטַנִּים לְבָרֵךְ.","פֶּרֶק נ״ה, הֲלָכוֹת י״ב-י״ג","בִּרְכַּת הַלְּבָנָה"],["מָתַי קוֹרְאִים אֶת פָּרָשַׁת פָּרָה?",["בַּשַּׁבָּת שֶׁאַחֲרֵי פָּרָשַׁת הַחֹדֶשׁ, בְּחֹדֶשׁ נִיסָן","בְּשַׁבָּת רֹאשׁ חֹדֶשׁ אֲדָר, יַחַד עִם שְׁקָלִים","בַּשַּׁבָּת שֶׁבָּאָה מִיָּד לִפְנֵי פָּרָשַׁת הַחֹדֶשׁ","בַּשַּׁבָּת שֶׁבְּתוֹךְ שִׁבְעַת יְמֵי הַפֶּסַח"],2,"פָּרָשַׁת הַחֹדֶשׁ נִקְרֵאת בַּשַּׁבָּת שֶׁלִּפְנֵי רֹאשׁ חֹדֶשׁ נִיסָן אוֹ בְּשַׁבָּת רֹאשׁ חֹדֶשׁ נִיסָן, וּפָרָשַׁת פָּרָה – בַּשַּׁבָּת שֶׁלִּפְנֵיהָ.","פֶּרֶק נ״ו, הֲלָכָה א׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["מַדּוּעַ הַיָּמִים הָרִאשׁוֹנִים שֶׁל חֹדֶשׁ נִיסָן הֵם יְמֵי שִׂמְחָה?",["כִּי בָּהֶם נִבְנְתָה חוֹמַת יְרוּשָׁלַיִם מֵחָדָשׁ","כִּי הוּקַם הַמִּשְׁכָּן וְהַנְּשִׂיאִים הִקְרִיבוּ קָרְבְּנוֹתֵיהֶם","כִּי בָּהֶם נִתְּנָה הַתּוֹרָה לְעַם יִשְׂרָאֵל","כִּי בָּהֶם נִגְמַר הַחֹרֶף וּמַתְחִיל הָאָבִיב"],1,"בְּאֶחָד בְּנִיסָן הוּקַם הַמִּשְׁכָּן, וּשְׁנֵים עָשָׂר יוֹם הִקְרִיבוּ הַנְּשִׂיאִים. אַחַר כָּךְ עֶרֶב פֶּסַח, יְמֵי הַפֶּסַח וְאִסְרוּ חַג – וְכֵיוָן שֶׁרֹב הַחֹדֶשׁ בְּשִׂמְחָה, גַּם שְׁאָר הַיָּמִים יְמֵי שִׂמְחָה.","פֶּרֶק נ״ו, הֲלָכוֹת ב׳-ג׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["מָה מִן הַדְּבָרִים הַבָּאִים נָהוּג בְּחֹדֶשׁ נִיסָן?",["אוֹמְרִים תַּחֲנוּן אָרֹךְ בְּכָל יוֹם שֵׁנִי וַחֲמִישִׁי","מִתְעַנִּים בְּיוֹם רִאשׁוֹן שֶׁל הַחֹדֶשׁ כְּמוֹ בֶּאֱלוּל","מַסְפִּידִים כָּרָגִיל, אֲבָל לֹא אוֹמְרִים תַּחֲנוּן","לֹא אוֹמְרִים תַּחֲנוּן, לֹא מַסְפִּידִים וְלֹא מִתְעַנִּים"],3,"מִפְּנֵי שֶׁנִּיסָן כֻּלּוֹ יְמֵי שִׂמְחָה וּקְדֻשָּׁה – אֵין אוֹמְרִים בּוֹ תַּחֲנוּן, אֵין מַסְפִּידִים וְאֵין מִתְעַנִּים.","פֶּרֶק נ״ו, הֲלָכָה ד׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["לָמָּה נִקְרֵאת הַשַּׁבָּת שֶׁלִּפְנֵי פֶּסַח ״שַׁבָּת הַגָּדוֹל״?",["בִּגְלַל שֶׁהִיא הַשַּׁבָּת הָאֲרֻכָּה בְּיוֹתֵר בַּשָּׁנָה","בִּגְלַל שֶׁבָּהּ הִתְחִילָה מַכַּת הַבְּכוֹרוֹת בְּמִצְרַיִם","בִּגְלַל הַנֵּס הַגָּדוֹל שֶׁנַּעֲשָׂה בָּהּ בְּמִצְרַיִם","בִּגְלַל שֶׁבָּהּ קוֹרְאִים אֶת כָּל הַהַגָּדָה"],2,"בְּשַׁבָּת זוֹ לָקְחוּ יִשְׂרָאֵל שֶׂה לְקָרְבָּן, וְאַף שֶׁעָמְדוּ לִשְׁחֹט אֶת אֱלֹהֵי מִצְרַיִם – הַמִּצְרִים לֹא יָכְלוּ לַעֲשׂוֹת לָהֶם דָּבָר.","פֶּרֶק נ״ו, הֲלָכָה ו׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["בְּמָה עוֹסֶקֶת דְּרָשַׁת הָרַב בְּשַׁבָּת הַגָּדוֹל?",["רַק בְּהִלְכוֹת שַׁבָּת וּבְדִינֵי מֻקְצֶה","בְּסִפּוּר מְגִלַּת אֶסְתֵּר וּבְמִצְווֹת פּוּרִים","בְּהִלְכוֹת סֻכָּה וְאַרְבָּעָה מִינִים לְחַג הַסֻּכּוֹת","בְּהִלְכוֹת הַפֶּסַח, בִּגְדֻלַּת הֶחָג וּבְנִסֵּי יְצִיאַת מִצְרַיִם"],3,"בְּשַׁבָּת הַגָּדוֹל הָרַב דּוֹרֵשׁ בְּרֹב עַם בְּהִלְכוֹת חַג הַפֶּסַח, בִּגְדֻלַּת הֶחָג וּבְנִסֵּי יְצִיאַת מִצְרַיִם.","פֶּרֶק נ״ו, הֲלָכָה ז׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["עַל אֵילוּ עֵצִים מְבָרְכִים אֶת בִּרְכַּת הָאִילָנוֹת?",["עַל כָּל עֵץ יָרֹק, גַּם אִילָנוֹת סְרָק","עַל אִילָנוֹת פְּרִי מְלַבְלְבִים, וְלֹא עַל אִילָנוֹת סְרָק","רַק עַל עֲצֵי זַיִת וּתְאֵנָה בְּאֶרֶץ יִשְׂרָאֵל","עַל עֵצִים שֶׁהַפֵּרוֹת שֶׁלָּהֶם כְּבָר בְּשֵׁלִים"],1,"רוֹאִים בְּנִיסָן אִילָנוֹת פְּרִי מְלַבְלְבִים (פּוֹרְחִים) וּמְבָרְכִים ״שֶׁלֹּא חִסַּר בְּעוֹלָמוֹ כְּלוּם״. עַל אִילָנוֹת סְרָק אֵין מְבָרְכִים.","פֶּרֶק נ״ו, הֲלָכוֹת ח׳-ט׳","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["דָּנִי רוֹאֶה שְׁנֵי עֲצֵי תַּפּוּחַ שֶׁהַפְּרָחִים שֶׁלָּהֶם כְּבָר נָפְלוּ, וְרוֹאִים חֲנָטָה. מָה הַדִּין?",["לֹא מְבָרֵךְ, כִּי צָרִיךְ שְׁנֵי מִינִים שׁוֹנִים","לֹא מְבָרֵךְ, כִּי הַפְּרָחִים כְּבָר נָפְלוּ מֵהָעֵץ","בְּדִיעֲבַד מְבָרֵךְ, גַּם אִם הָעֵצִים מֵאוֹתוֹ מִין","מְבָרֵךְ רַק אִם יֵשׁ שָׁם עֲשָׂרָה עֵצִים"],2,"מְבָרְכִים עַל שְׁנֵי אִילָנוֹת, אֲפִלּוּ מֵאוֹתוֹ מִין. לְכַתְּחִלָּה מְבָרְכִים כְּשֶׁרוֹאִים פֶּרַח, וּבְדִיעֲבַד – גַּם בִּשְׁלַב הַחֲנָטָה.","פֶּרֶק נ״ו, הֲלָכוֹת י׳-י״א","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["הַצִּבּוּר קָבַע לְבָרֵךְ יַחַד, אֲבָל הוּא מְאַחֵר וְהַפְּרִיחָה עוֹמֶדֶת לְהִגָּמֵר. מָה יַעֲשֶׂה יוֹסִי?",["יַמְתִּין לַצִּבּוּר גַּם אִם הַפְּרִיחָה תִּגָּמֵר","יְוַתֵּר עַל הַבְּרָכָה הַשָּׁנָה לְגַמְרֵי","יְבָרֵךְ רַק אַחֲרֵי שֶׁהַפֵּרוֹת יַבְשִׁילוּ","יְבָרֵךְ לְבַדּוֹ וְלֹא יַמְתִּין לַצִּבּוּר"],3,"נוֹהֲגִים לְבָרֵךְ יַחַד בְּרֹב עַם, אַךְ יִזָּהֲרוּ שֶׁלֹּא לְאַחֵר. אִם הַצִּבּוּר מְאַחֵר – יְבָרֵךְ לְבַדּוֹ.","פֶּרֶק נ״ו, הֲלָכָה י״ב","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["יוֹסִי בֵּרֵךְ בִּרְכַּת הָאִילָנוֹת בְּנִיסָן, וְאָחִיו שָׁכַח. מָה נָכוֹן?",["יוֹסִי יְבָרֵךְ שׁוּב; וְאָחִיו כְּבָר לֹא יוּכַל לְבָרֵךְ הַשָּׁנָה","יוֹסִי לֹא יְבָרֵךְ שׁוּב; אָחִיו יְבָרֵךְ בְּאִיָּר בְּלִי שֵׁם וּמַלְכוּת","שְׁנֵיהֶם יְבָרְכוּ שׁוּב בְּאִיָּר בְּשֵׁם וּמַלְכוּת, כְּמוֹ בְּנִיסָן","אָחִיו יְחַכֶּה לְנִיסָן שֶׁל הַשָּׁנָה הַבָּאָה וִיבָרֵךְ פַּעֲמַיִם"],1,"מְבָרְכִים רַק פַּעַם אַחַת בְּשָׁנָה, וּמִי שֶׁלֹּא בֵּרֵךְ בְּנִיסָן – יְבָרֵךְ בְּאִיָּר לְלֹא הַזְכָּרַת שֵׁם וּמַלְכוּת.","פֶּרֶק נ״ו, הֲלָכוֹת י״ג-י״ד","דִּינֵי חֹדֶשׁ נִיסָן וּמִנְהָגָיו"],["מָה הַטַּעַם שֶׁצִּוָּה ה׳ לֶאֱכֹל מַצָּה וְלֹא לֶאֱכֹל חָמֵץ?",["כְּדֵי שֶׁנִּהְיֶה בְּרִיאִים יוֹתֵר בִּימֵי הָאָבִיב","כְּדֵי לִזְכֹּר אֶת קְרִיעַת יַם סוּף בִּלְבַד","כְּדֵי לִזְכֹּר אֶת יְצִיאַת מִצְרַיִם וְהַנִּסִּים","כְּדֵי לַחְסֹךְ קֶמַח לִקְרַאת הַקַּיִץ הַבָּא"],2,"כְּדֵי לִזְכֹּר אֶת יְצִיאַת מִצְרַיִם וְאֶת הַנִּסִּים הַגְּדוֹלִים שֶׁעָשָׂה עִמָּנוּ ה׳.","פֶּרֶק נ״ז, הֲלָכָה א׳","אִסּוּר חָמֵץ"],["מָצָא אָדָם חָמֵץ בְּאֶמְצַע הַפֶּסַח. מָה דִּינוֹ?",["מֻתָּר לִמְכֹּר אוֹתוֹ לְגוֹי וּלְהַרְוִיחַ כֶּסֶף","מֻתָּר לִשְׁמֹר אוֹתוֹ בַּמַּחְסָן עַד אַחֲרֵי הַחַג","מֻתָּר לָתֵת אוֹתוֹ לִבְהֵמָה שֶׁלּוֹ לֶאֱכֹל","עָלָיו לְבַעֵר אֶת הֶחָמֵץ מִן הָעוֹלָם"],3,"אָסוּר לֵהָנוֹת מֵחָמֵץ בְּפֶסַח; אֲפִלּוּ לִמְכֹּר לְגוֹי אָסוּר, כִּי נֶהֱנֶה מֵהָרֶוַח. עָלָיו לְבַעֵר אֶת הֶחָמֵץ מֵהָעוֹלָם.","פֶּרֶק נ״ז, הֲלָכָה א׳","אִסּוּר חָמֵץ"],["עַל אֵילוּ אִסּוּרִים עוֹבֵר מִי שֶׁמַּשְׁאִיר חָמֵץ בִּרְשׁוּתוֹ בְּפֶסַח?",["רַק עַל אִסּוּר אֲכִילַת חָמֵץ בְּפֶסַח","עַל ״בַּל יֵרָאֶה״ וְעַל ״בַּל יִמָּצֵא״","אֵינוֹ עוֹבֵר כְּלוּם אִם אֵינוֹ אוֹכֵל מִמֶּנּוּ","רַק עַל אִסּוּר מְכִירַת חָמֵץ לְגוֹי"],1,"הוּא עוֹבֵר עַל שְׁנֵי אִסּוּרִים: ״לֹא יֵרָאֶה לְךָ שְׂאֹר״ וּ״שְׂאֹר לֹא יִמָּצֵא בְּבָתֵּיכֶם״.","פֶּרֶק נ״ז, הֲלָכָה א׳","אִסּוּר חָמֵץ"],["מָה מֻבְטָח לְמִי שֶׁנִּזְהָר מֵחָמֵץ בְּפֶסַח אֲפִלּוּ בְּמַשֶּׁהוּ?",["בָּטוּחַ הוּא שֶׁתִּהְיֶה לוֹ שָׁנָה טוֹבָה","שֶׁיִּזְכֶּה לֶאֱכֹל מַצָּה טְעִימָה בְּכָל שָׁנָה","שֶׁלֹּא יִצְטָרֵךְ לְבַעֵר חָמֵץ בְּשָׁנָה הַבָּאָה","שֶׁיִּהְיֶה פָּטוּר מִכָּל מִצְווֹת הַחַג הַזֶּה"],0,"הַנִּזְהָר מֵחָמֵץ בְּפֶסַח אֲפִלּוּ בְּמַשֶּׁהוּ – בָּטוּחַ הוּא שֶׁתִּהְיֶה לוֹ שָׁנָה טוֹבָה.","פֶּרֶק נ״ז, הֲלָכָה ב׳","אִסּוּר חָמֵץ"],["מֵאֵיזֶה מָזוֹן נַעֲשֶׂה הֶחָמֵץ שֶׁאָסְרָה הַתּוֹרָה?",["מִכָּל פְּרִי אוֹ יָרָק שֶׁנִּשְׁאַר בַּחוּץ","מִבָּשָׂר וְחָלָב שֶׁבִּשְּׁלוּ אוֹתָם יַחַד","מֵחֲמֵשֶׁת מִינֵי דָּגָן שֶׁנָּגְעוּ בְּמַיִם וְהֶחְמִיצוּ","רַק מִלֶּחֶם שֶׁנֶּאֱפָה בַּתַּנּוּר שֶׁל הַבַּיִת"],2,"חָמֵץ הוּא מַאֲכָל אוֹ מַשְׁקֶה מֵאֶחָד מֵחֲמֵשֶׁת מִינֵי דָּגָן שֶׁנָּגְעוּ בְּמַיִם עַד שֶׁהֶחְמִיצוּ.","פֶּרֶק נ״ז, הֲלָכָה ג׳","אִסּוּר חָמֵץ"],["אֵיזוֹ רְשִׁימָה מוֹנָה אֶת חֲמֵשֶׁת מִינֵי דָּגָן?",["חִטָּה, אֹרֶז, תִּירָס, שִׁיפוֹן וְכֻסְמִין","חִטָּה, שְׂעוֹרָה, שִׁבֹּלֶת שׁוּעָל, שִׁיפוֹן וְכֻסְמִין","שְׂעוֹרָה, עֲדָשִׁים, אֹרֶז, חִטָּה וְתִירָס","שִׁבֹּלֶת שׁוּעָל, תַּפּוּחַ, חִטָּה וְאֹרֶז"],1,"חֲמֵשֶׁת מִינֵי דָּגָן הֵם: חִטָּה, שְׂעוֹרָה, שִׁבֹּלֶת שׁוּעָל, שִׁיפוֹן וְכֻסְמִין.","פֶּרֶק נ״ז, הֲלָכָה ג׳","אִסּוּר חָמֵץ"],["מָה לוֹמְדִים מֵהַפָּסוּק ״כָּל מַחְמֶצֶת לֹא תֹאכֵלוּ״?",["שֶׁרַק לֶחֶם שָׁלֵם אָסוּר, וְלֹא פֵּרוּרִים","שֶׁמַּשְׁקִים כְּמוֹ בִּירָה מֻתָּרִים בְּפֶסַח","שֶׁתַּעֲרֹבֶת חָמֵץ מֻתֶּרֶת אִם הֶחָמֵץ מְעַט","שֶׁגַּם מַאֲכָל שֶׁיֵּשׁ בּוֹ מְעַט חָמֵץ אָסוּר"],3,"לֹא רַק מַאֲכָל שֶׁעִקָּרוֹ חָמֵץ אָסוּר, אֶלָּא גַּם מַאֲכָל אוֹ מַשְׁקֶה שֶׁיֵּשׁ בּוֹ מְעַט חָמֵץ – תַּעֲרֹבֶת חָמֵץ.","פֶּרֶק נ״ז, הֲלָכָה ד׳","אִסּוּר חָמֵץ"],["לָמָּה צָרִיךְ כַּשְׁרוּת מְיֻחֶדֶת לְפֶסַח עַל מִצְרְכֵי הַמָּזוֹן?",["כְּדֵי שֶׁהַמָּזוֹן יִהְיֶה זוֹל יוֹתֵר בַּחַג","כִּי בְּפֶסַח אֵין צֹרֶךְ בִּכְלָל בְּכַשְׁרוּת רְגִילָה","כְּדֵי לָדַעַת שֶׁהִקְפִּידוּ שֶׁאֵין בָּהֶם תַּעֲרֹבֶת חָמֵץ","כְּדֵי שֶׁהָאֲרִיזָה תִּהְיֶה יָפָה לִכְבוֹד הֶחָג"],2,"הַכַּשְׁרוּת הַמְּיֻחֶדֶת לְפֶסַח מְלַמֶּדֶת אוֹתָנוּ שֶׁהִקְפִּידוּ שֶׁאֵין בַּמּוּצָר תַּעֲרֹבֶת חָמֵץ.","פֶּרֶק נ״ז, הֲלָכָה ה׳","אִסּוּר חָמֵץ"],["כֵּיצַד יִנְהַג אָדָם בְּדִין קִטְנִיּוֹת בְּפֶסַח?",["כֻּלָּם חַיָּבִים לִנְהֹג כְּמִנְהַג הָאַשְׁכְּנַזִּים","כָּל אֶחָד יִנְהַג כְּמִנְהַג מִשְׁפַּחְתּוֹ","כֻּלָּם חַיָּבִים לִנְהֹג כְּמִנְהַג הַסְּפָרַדִּים","כָּל אֶחָד בּוֹחֵר מָה שֶׁנּוֹחַ לוֹ"],1,"יֵשׁ חֲלֻקַּת מִנְהָגִים מְפֻרְסֶמֶת בֵּין הַסְּפָרַדִּים לָאַשְׁכְּנַזִּים, וְכָל אֶחָד יִנְהַג כְּמִנְהַג מִשְׁפַּחְתּוֹ.","פֶּרֶק נ״ז, הֲלָכָה ו׳","אִסּוּר חָמֵץ"],["מַהִי מִצְוַת הַשְׁבָּתַת הֶחָמֵץ, וְאֵיךְ מְקַיְּמִים אוֹתָהּ?",["מִצְוָה מִדְּרַבָּנָן, בַּאֲכִילַת כָּל הֶחָמֵץ עַד הַחַג","מִצְוַת עֲשֵׂה מִן הַתּוֹרָה, בְּבִטּוּל הֶחָמֵץ וּבְבִעוּרוֹ","מִצְוַת עֲשֵׂה מִן הַתּוֹרָה, בִּמְכִירַת הַבַּיִת כֻּלּוֹ","מִנְהָג טוֹב בִּלְבַד, בְּהַחְבָּאַת הֶחָמֵץ בָּאָרוֹן"],1,"זוֹ מִצְוַת עֲשֵׂה מִן הַתּוֹרָה (״תַּשְׁבִּיתוּ שְּׂאֹר מִבָּתֵּיכֶם״), וּמְקַיְּמִים אוֹתָהּ בְּבִטּוּל הֶחָמֵץ וּבְבִעוּרוֹ מֵהָעוֹלָם.","פֶּרֶק נ״ח, הֲלָכָה א׳-ב׳","בְּדִיקַת חָמֵץ"],["לָמָּה צָרִיךְ לְטַאטֵא וּלְנַקּוֹת אֶת הַבַּיִת לִפְנֵי הַבְּדִיקָה?",["כִּי אָסוּר לְהַדְלִיק נֵר בְּבַיִת מְלֻכְלָךְ","כְּדֵי שֶׁיִּהְיֶה מָקוֹם לְהַחְבִּיא אֶת הַפְּתִיתִים","כִּי כָּךְ נִפְטָרִים מִמִּצְוַת בְּדִיקַת חָמֵץ לְגַמְרֵי","כִּי אִי אֶפְשָׁר לִבְדֹּק הֵיטֵב בְּלִי נִקּוּי"],3,"נָהֲגוּ לְנַקּוֹת בִּיסוֹדִיּוּת לִקְרַאת פֶּסַח, כִּי אִי אֶפְשָׁר לִבְדֹּק הֵיטֵב לְלֹא נִקּוּי יְסוֹדִי.","פֶּרֶק נ״ח, הֲלָכָה ג׳-ד׳","בְּדִיקַת חָמֵץ"],["מָה הַדִּין כַּחֲצִי שָׁעָה לִפְנֵי לֵיל י״ד בְּנִיסָן?",["לֹא מַתְחִילִים מְלָאכָה וְלֹא אוֹכְלִים אֲכִילַת קֶבַע","מֻתָּר לְהַתְחִיל כָּל מְלָאכָה וְלֶאֱכֹל סְעוּדָה גְּדוֹלָה","אָסוּר לִשְׁתּוֹת מַיִם, אֲבָל מֻתָּר לְהַתְחִיל מְלָאכָה","צָרִיךְ לִשְׂרֹף אֶת כָּל הֶחָמֵץ שֶׁבַּבַּיִת מִיָּד"],0,"אֵין לְהַתְחִיל מְלָאכָה וְאָסוּר לֶאֱכֹל אֲכִילַת קֶבַע (יוֹתֵר מִשְּׁתֵּי פְּרוּסוֹת לֶחֶם), שֶׁמָּא יִשְׁכְּחוּ לִבְדֹּק.","פֶּרֶק נ״ח, הֲלָכָה ה׳","בְּדִיקַת חָמֵץ"],["מַדּוּעַ מֻתָּר שִׁעוּר קָבוּעַ בְּבֵית הַכְּנֶסֶת לִפְנֵי הַבְּדִיקָה?",["כִּי בְּבֵית הַכְּנֶסֶת אֵין חָמֵץ בִּכְלָל","כִּי לִמּוּד תּוֹרָה פּוֹטֵר מִבְּדִיקַת חָמֵץ","כִּי הַלּוֹמְדִים יַזְכִּירוּ זֶה לָזֶה לִבְדֹּק","כִּי הָרַב בּוֹדֵק בִּמְקוֹם כָּל הַלּוֹמְדִים"],2,"לִמּוּד בִּיחִידוּת אָסוּר שֶׁמָּא יִשְׁכַּח לִבְדֹּק, אֲבָל בְּשִׁעוּר קָבוּעַ בְּבֵית הַכְּנֶסֶת יַזְכִּירוּ זֶה לָזֶה.","פֶּרֶק נ״ח, הֲלָכָה ו׳","בְּדִיקַת חָמֵץ"],["מָה הַדִּין אִם הַבּוֹדֵק דִּבֵּר בֵּין הַבְּרָכָה לִתְחִלַּת הַבְּדִיקָה בִּדְבָרִים אֲחֵרִים?",["אֵינוֹ צָרִיךְ לַעֲשׂוֹת דָּבָר, וּמַמְשִׁיךְ כָּרָגִיל","עָלָיו לְבָרֵךְ שֵׁנִית לִפְנֵי שֶׁיַּתְחִיל לִבְדֹּק","צָרִיךְ לְחַכּוֹת עַד מָחָר וְלִבְדֹּק בַּבֹּקֶר","עָלָיו לְהַדְלִיק נֵר חָדָשׁ בְּלִי בְּרָכָה"],1,"אַחֲרֵי עַרְבִית בְּלֵיל י״ד מְבָרְכִים ״עַל בִּעוּר חָמֵץ״ וּמַתְחִילִים מִיָּד. אִם דִּבֵּר דְּבָרִים שֶׁאֵינָם קְשׁוּרִים לַבְּדִיקָה - מְבָרֵךְ שֵׁנִית.","פֶּרֶק נ״ח, הֲלָכָה ז׳-ח׳","בְּדִיקַת חָמֵץ"],["אֵיפֹה צָרִיךְ לִבְדֹּק חָמֵץ?",["רַק בַּמִּטְבָּח, כִּי שָׁם מְבַשְּׁלִים וְאוֹכְלִים","רַק בְּמָקוֹם שֶׁרוֹאִים בּוֹ פֵּרוּרִים גְּדוֹלִים","בְּכָל הַבַּיִת חוּץ מֵחַדְרֵי הַשֵּׁנָה וְהָאַמְבַּטְיָה","בַּחֹרִים, בַּסְּדָקִים, וּבְכָל מָקוֹם שֶׁאוּלַי הִכְנִיסוּ חָמֵץ"],3,"בּוֹדְקִים בַּחֹרִים וּבַסְּדָקִים וּבְכָל מָקוֹם שֶׁיֵּשׁ סִכּוּי שֶׁהִכְנִיסוּ אֵלָיו חָמֵץ, גַּם בְּחַדְרֵי שֵׁנָה.","פֶּרֶק נ״ח, הֲלָכָה ט׳","בְּדִיקַת חָמֵץ"],["מָה הַדִּין בִּמְכוֹנִית שֶׁרְגִילִים לֶאֱכֹל בָּהּ?",["חַיֶּבֶת בִּבְדִיקָה, כִּי הִיא בִּרְשׁוּתוֹ שֶׁל הָאָדָם","פְּטוּרָה, כִּי מְכוֹנִית אֵינָהּ חֵלֶק מֵהַבַּיִת","בּוֹדְקִים אוֹתָהּ רַק אַחֲרֵי חַג הַפֶּסַח","רַק הַנַּהָג בּוֹדֵק אוֹתָהּ, בְּלִי נֵר"],0,"כָּל אָדָם בּוֹדֵק אֶת כָּל הַמְּקוֹמוֹת שֶׁבִּרְשׁוּתוֹ - גַּם מַחְסָן שֶׁנִּכְנָסִים אֵלָיו עִם אֹכֶל, וּמְכוֹנִית שֶׁאוֹכְלִים בָּהּ.","פֶּרֶק נ״ח, הֲלָכָה י׳","בְּדִיקַת חָמֵץ"],["מִי אַחְרַאי שֶׁתִּהְיֶה בְּדִיקָה בְּבֵית הַכְּנֶסֶת וּבַחֲדַר הַמַּדְרֵגוֹת?",["הָרַב שֶׁל הָעִיר בִּלְבַד, בְּכָל הַמְּקוֹמוֹת","אַף אֶחָד, כִּי אֵלּוּ מְקוֹמוֹת שֶׁל הַצִּבּוּר","הַגַּבָּאִים בְּבֵית הַכְּנֶסֶת, וְוַעַד הַבַּיִת בַּבִּנְיָן","הַיֶּלֶד הַקָּטָן בְּיוֹתֵר שֶׁגָּר בַּבִּנְיָן"],2,"חוֹבַת הַבְּדִיקָה בְּבֵית הַכְּנֶסֶת עַל הַגַּבָּאִים, וּבִרְכוּשׁ מְשֻׁתָּף כְּמוֹ חֲדַר מַדְרֵגוֹת - וַעַד הַבַּיִת דּוֹאֵג לְכָךְ.","פֶּרֶק נ״ח, הֲלָכָה י״א-י״ב","בְּדִיקַת חָמֵץ"],["מָה הַדִּין אִם לֹא שָׂמוּ פְּתִיתִים, וְהַבּוֹדֵק לֹא מָצָא חָמֵץ?",["הַבְּרָכָה לְבַטָּלָה, וְצָרִיךְ לְבָרֵךְ שׁוּב מָחָר","צָרִיךְ לִקְנוֹת לֶחֶם וּלְהַתְחִיל אֶת הַבְּדִיקָה מֵחָדָשׁ","לֹא קִיֵּם אֶת הַמִּצְוָה, כִּי לֹא מָצָא כְּלוּם","הַבְּרָכָה אֵינָהּ לְבַטָּלָה, כִּי הַמִּצְוָה הִיא לִבְדֹּק"],3,"נוֹהֲגִים לְהָנִיחַ עֲשָׂרָה פְּתִיתִים, אֲבָל גַּם בְּלִי פְּתִיתִים אֵין הַבְּרָכָה לְבַטָּלָה, כִּי הַמִּצְוָה הִיא לִבְדֹּק.","פֶּרֶק נ״ח, הֲלָכָה ט״ו","בְּדִיקַת חָמֵץ"],["לָמָּה יֵשׁ לִשְׁמֹר הֵיטֵב אֶת הֶחָמֵץ שֶׁנִּשְׁאַר אַחֲרֵי הַבְּדִיקָה?",["כְּדֵי שֶׁלֹּא יִתְפַּזֵּר שׁוּב בְּכָל הַבַּיִת","כְּדֵי שֶׁיִּהְיֶה מַה לֶּאֱכֹל בְּחֹל הַמּוֹעֵד","כְּדֵי לְהַרְאוֹת אוֹתוֹ לָאוֹרְחִים בְּלֵיל הַסֵּדֶר","כְּדֵי לִמְכֹּר אוֹתוֹ בְּיֹקֶר אַחֲרֵי הַפֶּסַח"],0,"הֶחָמֵץ שֶׁנִּמְצָא בַּבְּדִיקָה אוֹ נִשְׁמַר לַסְּעוּדוֹת צָרִיךְ שְׁמִירָה, שֶׁלֹּא יִתְפַּזֵּר בַּבַּיִת שֶׁכְּבָר נִבְדַּק.","פֶּרֶק נ״ח, הֲלָכָה ט״ז","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["לָמָּה צָרִיךְ לוֹמַר אֶת בִּטּוּל הֶחָמֵץ בְּשָׂפָה שֶׁמְּבִינִים?",["כִּי זֶה קָצָר יוֹתֵר מֵהַנֻּסָּח הָאֲרָמִי","כִּי בַּאֲרָמִית אָסוּר לְדַבֵּר בְּעֶרֶב פֶּסַח","כִּי אִם לֹא מְבִינִים, אֵין עֵרֶךְ לַבִּטּוּל","כִּי כָּךְ הַיְּלָדִים יְכוֹלִים לְבַטֵּל בִּמְקוֹם הָאָב"],2,"מִיָּד אַחֲרֵי הַבְּדִיקָה מְבַטְּלִים אֶת הֶחָמֵץ. אִם לֹא מְבִינִים מָה אוֹמְרִים, אֵין עֵרֶךְ לַבִּטּוּל – וְלָכֵן יֵשׁ גַּם תַּרְגּוּם לְעִבְרִית: ״כָּל חָמֵץ וּשְׂאוֹר שֶׁבִּרְשׁוּתִי...״.","פֶּרֶק נ״ח, הֲלָכוֹת י״ז-י״ח","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["עַל מָה עַל הַמְּבַטֵּל לַחְשֹׁב בִּשְׁעַת הַבִּטּוּל?",["שֶׁיִּשְׁמֹר כָּל חָמֵץ שֶׁיִּמְצָא לְאַחַר הַפֶּסַח","שֶׁאִם יִמְצָא חָמֵץ, יַשְׁלִיכֶנּוּ מִיָּד לָאַשְׁפָּה","שֶׁיִּתֵּן כָּל חָמֵץ שֶׁיִּמְצָא לַשְּׁכֵנִים שֶׁלּוֹ","שֶׁהַבִּטּוּל מַסְפִּיק וְאֵין צֹרֶךְ לִשְׂרֹף כְּלָל"],1,"הַמְּבַטֵּל חוֹשֵׁב שֶׁאִם יִמְצָא חָמֵץ יַשְׁלִיכֶנּוּ מִיָּד לָאַשְׁפָּה כְּמוֹ לִכְלוּךְ. כָּךְ הוּא מַרְאֶה שֶׁאֵין לוֹ רָצוֹן בֶּחָמֵץ, וְאֵינוֹ עוֹבֵר עַל ״בַּל יֵרָאֶה״ וּ״בַל יִמָּצֵא״.","פֶּרֶק נ״ח, הֲלָכָה י״ט","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["לָמָּה לֹא מְבַטְּלִים בָּעֶרֶב אֶת הֶחָמֵץ שֶׁל סְעוּדַת הַבֹּקֶר?",["כִּי חָמֵץ שֶׁל אֹכֶל אֵינוֹ נִקְרָא חָמֵץ בִּכְלָל","כִּי הָרַב כְּבָר מָכַר אוֹתוֹ לַגּוֹי","כִּי מְבַטְּלִים רַק פֵּרוּרִים קְטַנִּים מְאוֹד","כִּי בִּרְצוֹנֵנוּ לֶאֱכֹל אוֹתוֹ עַד זְמַן הַשְּׂרֵפָה"],3,"אֶת הֶחָמֵץ שֶׁמְּתַכְנְנִים לֶאֱכֹל עַד זְמַן הַשְּׂרֵפָה לֹא מְבַטְּלִים, שֶׁהֲרֵי רוֹצִים לֶאֱכֹל אוֹתוֹ.","פֶּרֶק נ״ח, הֲלָכָה כ׳","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מָה צָרִיךְ לַעֲשׂוֹת לִפְנֵי סוֹף הַשָּׁעָה הָרְבִיעִית מֵהַזְּרִיחָה?",["לִשְׂרֹף אֶת כָּל הֶחָמֵץ וּלְבַטֵּל אוֹתוֹ","לְסַיֵּם לֶאֱכֹל חָמֵץ וּלְנַקּוֹת הֵיטֵב אֶת הַשִּׁנַּיִם","לִמְכֹּר אֶת הֶחָמֵץ לְגוֹי בְּעַצְמוֹ בְּלִי רַב","לִבְדֹּק אֶת הַבַּיִת בְּנֵר בַּפַּעַם הָרִאשׁוֹנָה"],1,"יֵשׁ לְסַיֵּם אֶת סְעוּדַת הַבֹּקֶר וּלְנַקּוֹת הֵיטֵב אֶת הַשִּׁנַּיִם לִפְנֵי סוֹף הַשָּׁעָה הָרְבִיעִית (זְמַנִּית), וְאַחֲרֶיהָ אָסוּר לֶאֱכֹל חָמֵץ.","פֶּרֶק נ״ח, הֲלָכָה כ״א","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מִי שֶׁאֵינוֹ יָכוֹל לִשְׂרֹף אֶת הֶחָמֵץ עַד הַשָּׁעָה הַחֲמִישִׁית – מָה עוֹד אֶפְשָׁר?",["לְהַחְבִּיא אוֹתוֹ בַּמְּקָרֵר עַד מוֹצָאֵי הַפֶּסַח","לְהַשְׁאִיר אוֹתוֹ בַּבַּיִת אַחֲרֵי הַשָּׁעָה הַחֲמִישִׁית","לְזָרְקוֹ לַיָּם אוֹ לְפוֹרֵר אוֹתוֹ לָרוּחַ","לָתֵת אוֹתוֹ לִיהוּדִי אַחֵר שֶׁיִּשְׁמֹר עָלָיו"],2,"מְבַעֲרִים עַד סוֹף הַשָּׁעָה הַחֲמִישִׁית. מִנְהַג רֹב יִשְׂרָאֵל לִשְׂרֹף, וּמִי שֶׁאֵינוֹ יָכוֹל – זוֹרֵק לַיָּם, מְפוֹרֵר לָרוּחַ אוֹ לָאַסְלָה, אוֹ שׁוֹפֵךְ עָלָיו חֹמֶר שֶׁפּוֹסֵל אוֹתוֹ מֵאֲכִילָה.","פֶּרֶק נ״ח, הֲלָכוֹת כ״ב-כ״ג","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מִצְוָה מִן הַמֻּבְחָר שֶׁבַּעַל הֶחָמֵץ יִשְׂרֹף בְּעַצְמוֹ. וְלָמָּה יֵשׁ נוֹהֲגִים לְצָרֵף לָאֵשׁ אֶת הַלּוּלָב?",["כְּדֵי לְקַיֵּם בַּלּוּלָב עוֹד מִצְוָה נוֹסֶפֶת","כְּדֵי שֶׁהָאֵשׁ תִּדְלַק מַהֵר וְחָזָק יוֹתֵר","כִּי אָסוּר לְהַשְׁאִיר לוּלָב בַּבַּיִת בְּפֶסַח","כִּי הַשָּׁלִיחַ צָרִיךְ סִימָן שֶׁהַשְּׂרֵפָה הִתְחִילָה"],0,"בַּעַל הֶחָמֵץ שׂוֹרֵף בְּעַצְמוֹ מִן הַמֻּבְחָר (וּמִי שֶׁקָּשֶׁה לוֹ – בְּשָׁלִיחַ). יֵשׁ נוֹהֲגִים לִשְׂרֹף עִם הֶחָמֵץ אֶת הַלּוּלָב, הַהֲדַסִּים, הָעֲרָבוֹת וַעֲרָבַת הוֹשַׁעְנָא רַבָּה, כְּדֵי לְקַיֵּם בָּהֶם מִצְוָה נוֹסֶפֶת.","פֶּרֶק נ״ח, הֲלָכוֹת כ״ד-כ״ה","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מָה מְבַטְּלִים בַּבִּטּוּל הַשֵּׁנִי, אַחֲרֵי הַשְּׂרֵפָה?",["רַק אֶת הֶחָמֵץ שֶׁנִּשְׂרַף זֶה עַתָּה בָּאֵשׁ","רַק אֶת הֶחָמֵץ שֶׁמָּכְרוּ לַגּוֹי עַל יְדֵי הָרַב","רַק אֶת הֶחָמֵץ שֶׁל הַשְּׁכֵנִים בַּבִּנְיָן","כָּל חָמֵץ שֶׁרְאִינוּהוּ וְשֶׁלֹּא רְאִינוּהוּ שֶׁנִּשְׁאַר בְּבַעֲלוּתֵנוּ"],3,"בַּבִּטּוּל הַשֵּׁנִי מְבַטְּלִים כָּל חָמֵץ שֶׁנִּשְׁאַר בְּבַעֲלוּתֵנוּ: ״שֶׁרְאִיתִיו וְשֶׁלֹּא רְאִיתִיו, שֶׁבִּעַרְתִּיו וְשֶׁלֹּא בִּעַרְתִּיו״.","פֶּרֶק נ״ח, הֲלָכָה כ״ו","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["לָמָּה מְמַנִּים אֶת רַב הָעִיר לִמְכֹּר אֶת הֶחָמֵץ לְגוֹי?",["כִּי רַק לְרַב מֻתָּר לְדַבֵּר עִם גּוֹי","כִּי לֹא כָּל אָדָם יוֹדֵעַ לִמְכֹּר כַּהֲלָכָה","כִּי הָרַב מְשַׁלֵּם לָנוּ אֶת כָּל הַכֶּסֶף","כִּי הַגּוֹי מְסָרֵב לִקְנוֹת מִסְּתָם אָדָם"],1,"מְכִירַת חָמֵץ הִיא מְכִירָה גְּמוּרָה, עַל פִּי הַהֲלָכָה וְעַל פִּי חֻקֵּי הַמְּדִינָה. לֹא כָּל אָדָם יוֹדֵעַ לִמְכֹּר כָּךְ, וְלָכֵן חוֹתְמִים עַל שְׁטָר שֶׁמְּמַנֶּה אֶת רַב הָעִיר לְשָׁלִיחַ.","פֶּרֶק נ״ח, הֲלָכוֹת כ״ז-כ״ח","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["הֶחָמֵץ שֶׁנִּמְכַּר סָגוּר בְּאָרוֹן מְסֻמָּן. מָתַי מֻתָּר לְהִשְׁתַּמֵּשׁ בּוֹ?",["מִיָּד בְּצֵאת הַחַג, עוֹד לִפְנֵי הַהַבְדָּלָה","כְּבָר בְּחֹל הַמּוֹעֵד, אִם הָאָרוֹן מְסֻמָּן","רַק אַחֲרֵי שָׁבוּעַ שָׁלֵם מִסּוֹף הַפֶּסַח","אַחֲרֵי הַפֶּסַח, כְּשֶׁמְּשַׁעֲרִים שֶׁהָרַבָּנוּת קָנְתָה בַּחֲזָרָה"],3,"אֶת הֶחָמֵץ הַמָּכוּר סוֹגְרִים וּמְסַמְּנִים כִּי הוּא שֶׁל הַגּוֹי. אַחַר הַפֶּסַח מַמְתִּינִים מְעַט עַד שֶׁאֶפְשָׁר לְשַׁעֵר שֶׁהָרַבָּנוּת קָנְתָה אוֹתוֹ בַּחֲזָרָה עֲבוּר כֻּלָּם.","פֶּרֶק נ״ח, הֲלָכוֹת כ״ט-ל׳","בִּטּוּל, שְׂרֵפָה וּמְכִירַת חָמֵץ"],["מַדּוּעַ צָרִיךְ לְהַכְשִׁיר לְפֶסַח סִיר שֶׁל כָּל הַשָּׁנָה?",["כִּי בְּדָפְנוֹתָיו בָּלוּעַ טַעַם חָמֵץ שֶׁיֵּצֵא לָאֹכֶל","כִּי הַסִּיר מִתְלַכְלֵךְ מִבַּחוּץ מֵאֵשׁ הַכִּירַיִם","כִּי בְּפֶסַח אָסוּר לְבַשֵּׁל בְּסִירִים בִּכְלָל","כִּי מִנְהָג לְהַחְלִיף אֶת צֶבַע הַסִּירִים בְּפֶסַח"],0,"בְּדָפְנוֹת הַכֵּלִים בָּלוּעַ טַעַם חָמֵץ, וְהָאֹכֶל יִבְלַע אוֹתוֹ וְיֵאָסֵר.","פֶּרֶק נ״ט, הֲלָכָה א׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["מָה פֵּרוּשׁ הַכְּלָל ״כְּבוֹלְעוֹ כָּךְ פּוֹלְטוֹ״?",["כְּלִי פּוֹלֵט אֶת הָאִסּוּר רַק אַחֲרֵי שָׁנָה שְׁלֵמָה","כָּל כְּלִי צָרִיךְ לִזְרֹק לִפְנֵי פֶּסַח","בְּאוֹתָהּ דֶּרֶךְ שֶׁבָּלַע הַכְּלִי, כָּךְ הוּא פּוֹלֵט","כְּלִי שֶׁבָּלַע חָמֵץ אֵינוֹ פּוֹלֵט לְעוֹלָם"],2,"בְּאוֹתָהּ דֶּרֶךְ שֶׁבָּהּ הַכְּלִי בָּלַע אֶת טַעַם הָאִסּוּר, הוּא גַּם יִפְלֹט אוֹתוֹ – כְּמוֹ שֶׁלִּמֵּד אֶלְעָזָר הַכֹּהֵן אַחֲרֵי מִלְחֶמֶת מִדְיָן.","פֶּרֶק נ״ט, הֲלָכָה ב׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["כְּלִי שֶׁיֵּשׁ לוֹ כַּמָּה שִׁמּוּשִׁים – כֵּיצַד נוֹהֲגִים לְכַתְּחִלָּה?",["מַכְשִׁירִים לְפִי הַשִּׁמּוּשׁ הֶחָמוּר יוֹתֵר שֶׁלּוֹ","מַכְשִׁירִים לְפִי הַשִּׁמּוּשׁ הַקַּל יוֹתֵר שֶׁלּוֹ","לֹא מַכְשִׁירִים אוֹתוֹ, כִּי אֵין לוֹ שִׁמּוּשׁ אֶחָד","מַכְשִׁירִים לְפִי הַשִּׁמּוּשׁ הָאַחֲרוֹן שֶׁנַּעֲשָׂה בּוֹ"],0,"יֵשׁ אוֹמְרִים לְפִי הַשִּׁמּוּשׁ הָעִקָּרִי, וְיֵשׁ אוֹמְרִים לְפִי הֶחָמוּר יוֹתֵר – וְכָךְ יֵשׁ לִנְהֹג לְכַתְּחִלָּה.","פֶּרֶק נ״ט, הֲלָכָה ה׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["קַעֲרַת סָלָט שֶׁלְּעוֹלָם לֹא שָׂמִים בָּהּ דָּבָר חַם – מָה דִּינָהּ?",["צָרִיךְ לְלַבֵּן אוֹתָהּ בָּאֵשׁ לִפְנֵי פֶּסַח","אָסוּר לְהִשְׁתַּמֵּשׁ בָּהּ בְּפֶסַח בְּשׁוּם אֹפֶן","מֻתֶּרֶת בְּפֶסַח לְאַחַר נִקּוּי יְסוֹדִי בְּמַיִם","צָרִיךְ לְהַגְעִיל אוֹתָהּ שָׁלֹשׁ פְּעָמִים"],2,"כֵּלִים לְמַאֲכָלִים קָרִים בִּלְבַד מֻתָּרִים בְּפֶסַח אַחֲרֵי נִקּוּי יְסוֹדִי בְּמַיִם.","פֶּרֶק נ״ט, הֲלָכָה ו׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["כְּלִי שֶׁרֹב שִׁמּוּשׁוֹ לְקַר, וְלִפְעָמִים לְחָמֵץ חַם – מָה הַדִּין?",["אֵין צֹרֶךְ לַעֲשׂוֹת בּוֹ שׁוּם דָּבָר","כֻּלָּם מַסְכִּימִים שֶׁמַּסְפִּיק לְנַגֵּב אוֹתוֹ בְּמַגֶּבֶת","כֻּלָּם מַסְכִּימִים שֶׁצָּרִיךְ לְלַבֵּן אוֹתוֹ בָּאֵשׁ","יֵשׁ אוֹמְרִים נִקּוּי יְסוֹדִי, וְיֵשׁ אוֹמְרִים הַגְעָלָה"],3,"יֵשׁ אוֹמְרִים שֶׁנִּתָּן לְהִסְתַּפֵּק בְּנִקּוּי יְסוֹדִי, וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ הַגְעָלָה.","פֶּרֶק נ״ט, הֲלָכָה ז׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["מַדּוּעַ נוֹהֲגִים לְהַגְעִיל גַּם כַּפִּיּוֹת וּמַזְלְגוֹת?",["כִּי מַכְנִיסִים אוֹתָם לַסִּיר בְּעוֹדוֹ עַל הָאֵשׁ","כִּי הֵם עֲשׂוּיִים מִמַּתֶּכֶת דַּקָּה מְאוֹד","כִּי נוֹגְעִים בָּהֶם בַּיָּדַיִם כָּל הַזְּמַן בָּאֲכִילָה","כִּי מְשַׁמְּשִׁים בָּהֶם רַק לְמַאֲכָלִים קָרִים"],0,"כֵּלִים שֶׁמְּבַשְּׁלִים בָּהֶם עִם מַיִם מַגְעִילִים, וְגַם כַּפִּיּוֹת וּמַזְלְגוֹת – כִּי פְּעָמִים רַבּוֹת מַכְנִיסִים אוֹתָם לַסִּיר שֶׁעַל הָאֵשׁ.","פֶּרֶק נ״ט, הֲלָכוֹת ח׳-ט׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["מַדּוּעַ צָרִיךְ לְהַגְעִיל גַּם אֶת מִכְסֵה הַסִּיר?",["כִּי הַמִּכְסֶה נִשְׁבָּר בְּקַלּוּת בְּלִי הַגְעָלָה","כִּי בְּפֶסַח מְבַשְּׁלִים רַק בְּסִיר מְכֻסֶּה","כִּי גַּם אֵלָיו מַגִּיעִים הָאֵדִים שֶׁל הַבִּשּׁוּל","כִּי הַמִּכְסֶה עָשׂוּי מֵחֹמֶר אַחֵר מֵהַסִּיר עַצְמוֹ"],2,"גַּם אֶל הַמִּכְסִים מַגִּיעִים הָאֵדִים שֶׁעוֹלִים בִּשְׁעַת הַבִּשּׁוּל, וְגַם הַיָּדִיּוֹת צְרִיכוֹת הַכְשָׁרָה.","פֶּרֶק נ״ט, הֲלָכָה י׳","הַכְשָׁרַת הַכֵּלִים לְפֶסַח"],["כַּמָּה זְמַן אֵין לְהִשְׁתַּמֵּשׁ בַּכְּלִי לִפְנֵי הַהַגְעָלָה?",["שָׁעָה אַחַת בִּלְבַד לִפְנֵי הַהַגְעָלָה","שָׁבוּעַ שָׁלֵם לִפְנֵי הַהַגְעָלָה בְּדִיּוּק","עֶשְׂרִים וְאַרְבַּע שָׁעוֹת לִפְנֵי הַהַגְעָלָה","אֵין צֹרֶךְ לְהַפְסִיק שִׁמּוּשׁ כְּלָל"],2,"אֵין לְהִשְׁתַּמֵּשׁ בַּכְּלִי בְּעֶשְׂרִים וְאַרְבַּע הַשָּׁעוֹת שֶׁלִּפְנֵי הַהַגְעָלָה, וְיֵשׁ מְהַדְּרִים לְהַפְסִיק שְׁלוֹשָׁה יָמִים לִפְנֵי כֵן.","פֶּרֶק נ״ט, הֲלָכָה י״א","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["לָמָּה צָרִיךְ לְהַגְעִיל כָּל כְּלִי בְּנִפְרָד בְּהַגְעָלָה צִבּוּרִית?",["כְּדֵי שֶׁהַתּוֹר יִהְיֶה אָרֹךְ יוֹתֵר","כִּי הַסִּיר קָטָן מִדַּי לִשְׁנֵי כֵּלִים","כְּדֵי לַחְסֹךְ בַּמַּיִם הָרוֹתְחִים שֶׁבַּסִּיר","יֵשׁ חֲשָׁשׁ לְכֵלִים שֶׁשִּׁמְּשׁוּ בַּיְּמָמָה הָאַחֲרוֹנָה"],3,"יֵשׁ חֲשָׁשׁ שֶׁיָּבִיאוּ כְּלֵי בָּשָׂר וְחָלָב שֶׁהִשְׁתַּמְּשׁוּ בָּהֶם בַּיְּמָמָה הָאַחֲרוֹנָה, לָכֵן מַגְעִילִים כָּל כְּלִי בְּנִפְרָד.","פֶּרֶק נ״ט, הֲלָכָה י״ב","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["מָה מַרְאֶה הַנִּסָּיוֹן לְגַבֵּי הַגְעָלָה בַּבַּיִת?",["אָסוּר לְהַגְעִיל כֵּלִים בַּבַּיִת בְּשׁוּם אֹפֶן","הַגְעָלָה בַּבַּיִת הִיא הַטּוֹבָה בְּיוֹתֵר","רַק רַב מֻמְחֶה רַשַּׁאי לְהַגְעִיל כֵּלִים","הַגְעָלָה בַּבַּיִת מַסְפִּיקָה רַק לְכַפִּיּוֹת"],1,"נִתָּן לְהַגְעִיל בַּבַּיִת תּוֹךְ הַקְפָּדָה עַל כָּל הַכְּלָלִים, וְהַנִּסָּיוֹן מַרְאֶה שֶׁזּוֹ הַהַגְעָלָה הָרְאוּיָה וְהַטּוֹבָה בְּיוֹתֵר.","פֶּרֶק נ״ט, הֲלָכָה י״ג","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["אֵילוּ כֵּלִים צְרִיכִים לִבּוּן חָמוּר?",["שִׁפּוּדִים וּרְשָׁתוֹת לִצְלִיַּת בָּשָׂר עַל הָאֵשׁ","כּוֹסוֹת שֶׁשּׁוֹתִים בָּהֶן מַיִם קָרִים תָּמִיד","צַלָּחוֹת שֶׁאוֹכְלִים בָּהֶן סָלָט קַר","סִירִים שֶׁמְּבַשְּׁלִים בָּהֶם מָרָק בְּמַיִם"],0,"כֵּלִים שֶׁמִּשְׁתַּמְּשִׁים בָּהֶם עַל יְדֵי הָאֵשׁ – שִׁפּוּדִים, אַסְכְּלָאוֹת (רְשָׁתוֹת) וְכֵלִים שֶׁאוֹפִים בָּהֶם בְּתַנּוּר – צְרִיכִים לִבּוּן חָמוּר.","פֶּרֶק נ״ט, הֲלָכָה י״ד","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["מַהוּ לִבּוּן חָמוּר?",["חַם עַד שֶׁאִי אֶפְשָׁר לָגַעַת בּוֹ בַּיָּד","פּוֹשְׁרִים קְצָת עַד שֶׁהַכְּלִי מַתְחִיל לְהִתְחַמֵּם","חַם עַד שֶׁנִּתָּזִים מִמֶּנּוּ נִיצוֹצוֹת אוֹ מַאֲדִים","מְחַמְּמִים בְּמַיִם רוֹתְחִים כַּמָּה שְׁנִיּוֹת בִּלְבַד"],2,"בְּלִבּוּן חָמוּר מְחַמְּמִים אֶת הַכְּלִי בְּאֵשׁ עַד שֶׁאִם יִגְּעוּ בּוֹ יִנָּתְזוּ נִיצוֹצוֹת, אוֹ שֶׁיַּאֲדִים מֵרֹב חֹם.","פֶּרֶק נ״ט, הֲלָכָה ט״ו","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["לָמָּה אֵין לְהַכְשִׁיר לְפֶסַח תַּבְנִית שֶׁל תַּנּוּר חַשְׁמַלִּי?",["כִּי תַּבְנִית חַשְׁמַלִּית אַף פַּעַם לֹא בּוֹלַעַת","חוֹשְׁשִׁים שֶׁלֹּא יְלַבְּנוּ כָּרָאוּי מִפַּחַד שֶׁתֵּהָרֵס","כִּי מֻתָּר לְהִשְׁתַּמֵּשׁ בָּהּ בְּלִי שׁוּם הַכְשָׁרָה","כִּי הַגְעָלָה בְּמַיִם קָרִים מַסְפִּיקָה לָהּ"],1,"הַתַּבְנִית צְרִיכָה לִבּוּן חָמוּר שֶׁעָלוּל לַהֲרֹס אוֹתָהּ, וְחוֹשְׁשִׁים שֶׁלֹּא יְלַבְּנוּ אוֹתָהּ כָּרָאוּי – לָכֵן אֵין לְהַכְשִׁירָהּ כְּלָל.","פֶּרֶק נ״ט, הֲלָכָה ט״ז","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["כְּלִי שֶׁמֵּעִקַּר הַדִּין מַסְפִּיקָה לוֹ הַגְעָלָה, אֲבָל קָשֶׁה לְנַקּוֹתוֹ – מָה עוֹשִׂים?",["חַיָּבִים לְלַבֵּן אוֹתוֹ בְּלִבּוּן חָמוּר","אֵין לְהַכְשִׁירוֹ לְפֶסַח בְּשׁוּם אֹפֶן","מַסְפִּיק לְלַבֵּן אוֹתוֹ בְּלִבּוּן קַל","מַסְפִּיק לְנַגֵּב אוֹתוֹ הֵיטֵב בְּמַגֶּבֶת"],2,"כֵּלִים שֶׁצְּרִיכִים לִבּוּן רַק מִפְּנֵי שֶׁקָּשֶׁה לְנַקּוֹתָם הֵיטֵב – מַסְפִּיק לְלַבֵּן אוֹתָם בְּלִבּוּן קַל.","פֶּרֶק נ״ט, הֲלָכָה י״ז","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["עַד מָתַי מְחַמְּמִים אֶת הַכְּלִי בְּלִבּוּן קַל?",["עַד שֶׁהַכְּלִי נַעֲשֶׂה פּוֹשֵׁר וְנָעִים לַמַּגָּע","עַד שֶׁנִּתָּזִים מִמֶּנּוּ נִיצוֹצוֹת בְּכָל מָקוֹם","עַד שֶׁהַמַּיִם בְּתוֹךְ הַכְּלִי מַתְחִילִים לִרְתֹּחַ","עַד שֶׁקַּשׁ אוֹ נְיָר בַּצַּד הַשֵּׁנִי נִשְׂרָף"],3,"בְּלִבּוּן קַל מְחַמְּמִים אֶת הַכְּלִי בְּאֵשׁ עַד שֶׁמֵּחֹם הָאֵשׁ יִשָּׂרֵף קַשׁ אוֹ נְיָר שֶׁבַּצַּד הַשֵּׁנִי שֶׁל הַכְּלִי.","פֶּרֶק נ״ט, הֲלָכָה י״ח","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["כְּלִי שֶׁיֵּשׁ סָפֵק אִם הוּא חַיָּב בְּלִבּוּן אוֹ שֶׁהַגְעָלָה מַסְפִּיקָה – מָה דִּינוֹ?",["אֶפְשָׁר לְהָקֵל וּלְהִסְתַּפֵּק בְּלִבּוּן קַל","חוֹבָה לְלַבֵּן אוֹתוֹ תָּמִיד בְּלִבּוּן חָמוּר","אֵין לְהַכְשִׁירוֹ לְפֶסַח כְּלָל וּלְעוֹלָם","מַסְפִּיק לִשְׁטֹף אוֹתוֹ בְּמַיִם קָרִים"],0,"בִּמְקוֹם סָפֵק נִתָּן לְהָקֵל וּלְהִסְתַּפֵּק בְּלִבּוּן קַל, וְאֵין חוֹבָה לְלַבֵּן בְּלִבּוּן חָמוּר.","פֶּרֶק נ״ט, הֲלָכָה י״ט","הַכְשָׁרַת הַכֵּלִים: הַגְעָלָה וְלִבּוּן"],["מָה נוֹהֲגִים לַעֲשׂוֹת בַּסַּכּוּ״ם לִפְנֵי פֶּסַח?",["שׁוֹטְפִים אוֹתָם בְּמַיִם קָרִים וּמְנַגְּבִים הֵיטֵב","עוֹטְפִים אוֹתָם בִּנְיַר כֶּסֶף כָּל הַחַג","מְנַקִּים הֵיטֵב וּמַגְעִילִים אוֹתָם בְּמַיִם רוֹתְחִים","מַשְׁאִירִים אוֹתָם בַּמְּקָרֵר יוֹם שָׁלֵם לִפְנֵי הַחַג"],2,"סַכִּינִים, כַּפּוֹת וּמַזְלְגוֹת – נוֹהֲגִים לְנַקּוֹתָם הֵיטֵב וּלְהַגְעִילָם בְּמַיִם רוֹתְחִים.","פֶּרֶק ס׳, הֲלָכָה א׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["כֵּיצַד מַכְשִׁירִים כִּירַיִם חַשְׁמַלִּיּוֹת?",["מְנַקִּים הֵיטֵב וּמְחַמְּמִים בְּחֹם גָּבוֹהַּ חֲצִי שָׁעָה","מְנַקִּים הֵיטֵב וּמְחַמְּמִים בְּחֹם נָמוּךְ דַּקָּה אַחַת","שׁוֹפְכִים עֲלֵיהֶן מַיִם קָרִים וּמְחַכִּים יוֹם שָׁלֵם","אֵין צֹרֶךְ לַעֲשׂוֹת דָּבָר, רַק לְנַגֵּב בְּמַגֶּבֶת"],0,"כִּירַיִם חַשְׁמַלִּיּוֹת: מְנַקִּים הֵיטֵב וּמְחַמְּמִים עַל הַחֹם הַגָּבוֹהַּ לְמֶשֶׁךְ חֲצִי שָׁעָה.","פֶּרֶק ס׳, הֲלָכָה ב׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["מָה עוֹשִׂים כְּדֵי לְהַכְשִׁיר פְּלָטָה חַשְׁמַלִּית?",["שׁוֹפְכִים עָלֶיהָ מַיִם רוֹתְחִים מִן הַקֻּמְקוּם","מַכְנִיסִים אוֹתָהּ לַמְּקָרֵר לְמֶשֶׁךְ לַיְלָה שָׁלֵם","מְנַגְּבִים אוֹתָהּ בְּמַגֶּבֶת יְבֵשָׁה וְזֶהוּ","מְנַקִּים הֵיטֵב וּמַפְעִילִים אוֹתָהּ עַד שִׂיא הַחֹם"],3,"יֵשׁ לְנַקּוֹת אֶת הַפְּלָטָה הֵיטֵב וּלְהַפְעִיל אוֹתָהּ עַד שֶׁתַּגִּיעַ לְשִׂיא הַחֹם. יֵשׁ נוֹהֲגִים לִשְׁפֹּךְ עָלֶיהָ גַּם חֹמֶר נִקּוּי.","פֶּרֶק ס׳, הֲלָכָה ג׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["כֵּיצַד רָצוּי לְהִשְׁתַּמֵּשׁ בַּפְּלָטָה בִּימֵי הַפֶּסַח?",["רַק אַחֲרֵי שֶׁשּׁוֹפְכִים עָלֶיהָ מַיִם קָרִים","כַּאֲשֶׁר הִיא מְכֻסָּה בִּנְיַר כֶּסֶף","כַּאֲשֶׁר הִיא מְכֻסָּה בְּמַגֶּבֶת רְטֻבָּה","רַק בַּלַּיְלָה וְלֹא בְּשׁוּם זְמַן אַחֵר"],1,"רָצוּי לְהִשְׁתַּמֵּשׁ בִּפְלָטָה בִּימֵי הַפֶּסַח כַּאֲשֶׁר הִיא מְכֻסָּה בִּנְיַר כֶּסֶף.","פֶּרֶק ס׳, הֲלָכָה ד׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["מַדּוּעַ אֵין לְהַכְשִׁיר פְּלָטָה בְּמַיִם רוֹתְחִים?",["מִפְּנֵי שֶׁהַמַּיִם מְלַכְלְכִים אֶת הַפְּלָטָה מְאוֹד","מִפְּנֵי שֶׁאָסוּר לְהַרְתִּיחַ מַיִם בְּעֶרֶב פֶּסַח","מִפְּנֵי שֶׁיֵּשׁ בָּזֶה סַכָּנָה לִשְׁפֹּךְ עָלֶיהָ מַיִם","מִפְּנֵי שֶׁהַפְּלָטָה כְּבָר כְּשֵׁרָה לְפֶסַח מֵעַצְמָהּ תָּמִיד"],2,"אֵין לִשְׁפֹּךְ מַיִם רוֹתְחִים עַל פְּלָטָה חַשְׁמַלִּית מִפְּנֵי שֶׁיֵּשׁ בָּזֶה סַכָּנָה, וְלָכֵן אֵין לְהַכְשִׁירָהּ בְּדֶרֶךְ זוֹ.","פֶּרֶק ס׳, הֲלָכָה ה׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["מָה נָכוֹן לְגַבֵּי מַדְּפֵי הַמְּקָרֵר?",["מְנַקִּים הֵיטֵב, וְאֵין צֹרֶךְ לְהַגְעִיל אוֹתָם","חַיָּבִים לְהַגְעִיל אוֹתָם בְּמַיִם רוֹתְחִים","מְלַבְּנִים אוֹתָם בָּאֵשׁ לִבּוּן קַל","קוֹנִים מַדָּפִים חֲדָשִׁים לִפְנֵי כָּל פֶּסַח"],0,"יֵשׁ לְנַקּוֹת הֵיטֵב אֶת כָּל הַמַּדָּפִים כְּדֵי שֶׁלֹּא יִשָּׁאֲרוּ פֵּרוּרֵי חָמֵץ, וְאֵין צֹרֶךְ לְהַכְשִׁירָם בְּהַגְעָלָה.","פֶּרֶק ס׳, הֲלָכָה ו׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["לָמָּה מַמְתִּינִים עֶשְׂרִים וְאַרְבַּע שָׁעוֹת לִפְנֵי הַכְשָׁרַת הַמִּיקְרוֹגַל?",["כְּדֵי שֶׁהַמִּיקְרוֹגַל יִתְקָרֵר וְלֹא יִשָּׂרֵף","כְּדֵי שֶׁהַחַשְׁמַל יַחֲזֹר לִפְעֹל כָּרָאוּי","כְּדֵי שֶׁהַמַּיִם בִּפְנִים יִתְיַבְּשׁוּ לְגַמְרֵי","כְּדֵי שֶׁהַטַּעַם הַבָּלוּעַ בַּדְּפָנוֹת יִפָּגֵם"],3,"מַמְתִּינִים עֶשְׂרִים וְאַרְבַּע שָׁעוֹת כְּדֵי שֶׁהַטַּעַם הַבָּלוּעַ בַּדְּפָנוֹת יִפָּגֵם, וְאַחַר כָּךְ מְחַמְּמִים בּוֹ צְלוֹחִית מַיִם שָׁלוֹשׁ דַּקּוֹת.","פֶּרֶק ס׳, הֲלָכָה ז׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["מַדּוּעַ יֵשׁ נוֹהֲגִים לְעָרוֹת מַיִם רוֹתְחִים עַל הַשֻּׁלְחָנוֹת?",["כִּי הַמַּיִם עוֹזְרִים לַשֻּׁלְחָן לִהְיוֹת חָזָק","כִּי כָּךְ הַשֻּׁלְחָן מַבְרִיק יוֹתֵר לִכְבוֹד הַחַג","כִּי לִפְעָמִים נִשְׁפָּךְ עֲלֵיהֶם מָרָק רוֹתֵחַ","כִּי אָסוּר לֶאֱכֹל עַל שֻׁלְחָן יָבֵשׁ"],2,"יֵשׁ נוֹהֲגִים לְעָרוֹת מַיִם רוֹתְחִים עַל הַשֻּׁלְחָנוֹת כִּי לִפְעָמִים נִשְׁפָּךְ מָרָק רוֹתֵחַ, אַךְ אִם הַדָּבָר יַזִּיק לַשֻּׁלְחָן אֶפְשָׁר לְהָקֵל.","פֶּרֶק ס׳, הֲלָכָה ח׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["מָה נָהֲגוּ לַעֲשׂוֹת עַל הַשֻּׁלְחָן כָּל יְמֵי הֶחָג?",["לְהַשְׁאִיר אוֹתוֹ חָשׂוּף בְּלִי שׁוּם כִּסּוּי","לִפְרֹשׂ מַפָּה שֶׁתַּחְצֹץ בֵּינוֹ לְבֵין הַכֵּלִים","לְהַגְעִיל אוֹתוֹ מֵחָדָשׁ בְּכָל בֹּקֶר","לְהַנִּיחַ עָלָיו רַק כֵּלִים חַד פַּעֲמִיִּים"],1,"נָהֲגוּ לִפְרֹשׂ עַל הַשֻּׁלְחָן מַפָּה שֶׁתַּחְצֹץ בֵּינוֹ לְבֵין הַכֵּלִים כָּל יְמֵי הֶחָג.","פֶּרֶק ס׳, הֲלָכָה ט׳","מַכְשִׁירִים אֶת הַמִּטְבָּח לְפֶסַח"],["מָה צָרִיךְ לַעֲשׂוֹת לְשֻׁלְחַן אֹכֶל שֶׁיֵּשׁ עָלָיו מַפָּה כָּל הַשָּׁנָה?",["לְלַבֵּן אוֹתוֹ בְּאֵשׁ חֲזָקָה מְאוֹד וּגְלוּיָה","לְנַקּוֹתוֹ הֵיטֵב שֶׁלֹּא יִשָּׁאֲרוּ פֵּרוּרֵי חָמֵץ","לְהַגְעִיל אוֹתוֹ בְּסִיר מַיִם רוֹתְחִים","לְכַסּוֹת אוֹתוֹ בְּעוֹד מַפָּה חֲדָשָׁה"],1,"שֻׁלְחָן כָּזֶה אֵינוֹ צָרִיךְ שׁוּם הֶכְשֵׁר, אַךְ צָרִיךְ לְנַקּוֹתוֹ הֵיטֵב מִפֵּרוּרֵי חָמֵץ.","פֶּרֶק ס׳, הֲלָכָה י׳","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["כֵּיצַד מַכְשִׁירִים מַפַּת שֻׁלְחָן מִנַּיְלוֹן?",["מְכַבְּסִים אוֹתָהּ פַּעֲמַיִם בְּמַיִם קָרִים","מְלַבְּנִים אוֹתָהּ עַל הָאֵשׁ כְּשָׁעָה","אֵין לְהַכְשִׁיר אוֹתָהּ וְקוֹנִים מַפָּה חֲדָשָׁה","מְנַקִּים הֵיטֵב וְשׁוֹפְכִים עָלֶיהָ מַיִם רוֹתְחִים"],3,"מַפּוֹת נַיְלוֹן מְנַקִּים הֵיטֵב וְשׁוֹפְכִים עֲלֵיהֶן מַיִם רוֹתְחִים.","פֶּרֶק ס׳, הֲלָכָה י״א","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["מַדּוּעַ לְפִי מִנְהַג הָאַשְׁכְּנַזִּים מַחֲבַת צְרִיכָה לִבּוּן קַל?",["כִּי לִפְעָמִים הַשֶּׁמֶן נִגְמָר וְהִיא בּוֹלַעַת","כִּי מְטַגְּנִים בָּהּ תָּמִיד בְּשֶׁמֶן רַב","כִּי הִיא עֲשׂוּיָה מֵחֶרֶס שֶׁנִּשְׁבָּר מַהֵר","כִּי מְבַשְּׁלִים בָּהּ רַק מַאֲכָלִים קָרִים"],0,"פְּעָמִים רַבּוֹת הַשֶּׁמֶן נִגְמָר, וְהַמַּחֲבַת בּוֹלַעַת אֶת טַעַם הַמַּאֲכָל יְשִׁירוֹת מֵחֹם הָאֵשׁ – לָכֵן צְרִיכָה לִבּוּן קַל.","פֶּרֶק ס׳, הֲלָכָה י״ב","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["מָה הַסֵּדֶר הַנָּכוֹן בְּהַכְשָׁרַת תַּנּוּר רָגִיל?",["חִמּוּם מִיָּד וְאַחֲרָיו נִקּוּי קַל בִּלְבַד","שְׁטִיפָה בְּמַיִם קָרִים וְהַמְתָּנָה שָׁבוּעַ שָׁלֵם","נִקּוּי, הַמְתָּנָה יְמָמָה וְחֹם מֵרַבִּי כְּשָׁעָה","נִקּוּי בִּלְבַד, בְּלִי לְהַדְלִיק אֶת הַתַּנּוּר"],2,"מְנַקִּים הֵיטֵב, מְחַכִּים עֶשְׂרִים וְאַרְבַּע שָׁעוֹת וּמַפְעִילִים בַּחֹם הַמֵּרַבִּי כְּשָׁעָה.","פֶּרֶק ס׳, הֲלָכָה י״ג","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["מָה עוֹשִׂים כְּדֵי לְהַכְשִׁיר תַּנּוּר פִּירוֹלִיטִי?",["מְנַקִּים הֵיטֵב וּמְחַכִּים שָׁלֹשׁ יְמָמוֹת שְׁלֵמוֹת","מַפְעִילִים אֶת תָּכְנִית הַנִּקּוּי בְּלִי נִקּוּי מֻקְדָּם","שׁוֹפְכִים עָלָיו מַיִם רוֹתְחִים מִכָּל הַצְּדָדִים","אֵין לְהַכְשִׁיר אוֹתוֹ כְּלָל, כְּמוֹ טֶפְלוֹן"],1,"תַּנּוּר פִּירוֹלִיטִי מְנַקֶּה אֶת עַצְמוֹ בְּחֹם שֶׁל כַּ-500 מַעֲלוֹת – מַפְעִילִים אֶת הַתָּכְנִית וְאֵין צֹרֶךְ לְנַקּוֹתוֹ קֹדֶם.","פֶּרֶק ס׳, הֲלָכָה י״ד","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["כֵּיצַד מַכְשִׁירִים כִּיּוֹר לְפֶסַח?",["מְלַבְּנִים אוֹתוֹ בְּאֵשׁ חֲזָקָה לְמֶשֶׁךְ שָׁעָה","מְכַסִּים אוֹתוֹ בְּמַפַּת בַּד כָּל הֶחָג","מַשְׁרִים אוֹתוֹ בְּמַיִם קָרִים שְׁלֹשָׁה יָמִים","מְנַקִּים הֵיטֵב וּמְעָרִים עָלָיו מַיִם רוֹתְחִים"],3,"יֵשׁ לְנַקּוֹת אֶת הַכִּיּוֹר הֵיטֵב וּלְעָרוֹת עָלָיו מַיִם רוֹתְחִים.","פֶּרֶק ס׳, הֲלָכָה ט״ו","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["מָה הַמִּנְהָג בִּכְלֵי חֶרֶס וּפוֹרְצֶלָן שֶׁל כָּל הַשָּׁנָה?",["מַכְשִׁירִים אוֹתָם בְּעֵרוּי מַיִם רוֹתְחִים הֵיטֵב","מִשְׁתַּמְּשִׁים בָּהֶם רַק לְמַאֲכָלִים קָרִים בִּלְבַד","לֹא מִשְׁתַּמְּשִׁים בָּהֶם בְּפֶסַח, אֲפִלּוּ לְקָרִים","מַשְׁרִים אוֹתָם בְּמַיִם שִׁבְעִים וּשְׁתַּיִם שָׁעוֹת"],2,"נוֹהֲגִים שֶׁלֹּא לְהִשְׁתַּמֵּשׁ בָּהֶם בְּפֶסַח כְּלָל, וַאֲפִלּוּ אִם מִשְׁתַּמְּשִׁים בָּהֶם רַק לִדְבָרִים קָרִים.","פֶּרֶק ס׳, הֲלָכָה ט״ז","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["לְפִי מִנְהַג הָאַשְׁכְּנַזִּים, כַּמָּה זְמַן מַשְׁרִים כְּלֵי זְכוּכִית שֶׁל דְּבָרִים קָרִים?",["שִׁבְעִים וּשְׁתַּיִם שָׁעוֹת, עִם שְׁתֵּי הַחְלָפוֹת","עֶשְׂרִים וְאַרְבַּע שָׁעוֹת, בְּלִי לְהַחְלִיף מַיִם","אַרְבָּעִים וּשְׁמוֹנֶה שָׁעוֹת, עִם הַחְלָפָה אַחַת","שָׁבוּעַ שָׁלֵם, וּמַחְלִיפִים מַיִם כָּל יוֹם"],0,"אַחֲרֵי נִקּוּי מַשְׁרִים שְׁלֹשָׁה פְּעָמִים עֶשְׂרִים וְאַרְבַּע שָׁעוֹת, וּמַחְלִיפִים אֶת הַמַּיִם בֵּינֵיהֶן – סַךְ הַכֹּל שִׁבְעִים וּשְׁתַּיִם שָׁעוֹת.","פֶּרֶק ס׳, הֲלָכָה י״ז","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["מָה מִנְהַג הָאַשְׁכְּנַזִּים בִּכְלֵי זְכוּכִית שֶׁל חָמֵץ רוֹתֵחַ?",["מַכְשִׁירִים אוֹתָם עַל יְדֵי נִקּוּי יְסוֹדִי","מַשְׁרִים אוֹתָם בְּמַיִם קָרִים שְׁלֹשָׁה יָמִים","מְלַבְּנִים אוֹתָם לִבּוּן קַל עַל הָאֵשׁ","לֹא נִתָּן לְהַכְשִׁיר אוֹתָם לְפֶסַח כְּלָל"],3,"מִנְהַג הָאַשְׁכְּנַזִּים (וְגַם חֵלֶק מִקְּהִלּוֹת הַסְּפָרַדִּים) – אֵין לְהַכְשִׁיר לְפֶסַח כְּלֵי זְכוּכִית שֶׁל חָמֵץ רוֹתֵחַ.","פֶּרֶק ס׳, הֲלָכָה י״ח","הַכְשָׁרַת כְּלֵי מִטְבָּח – חֵלֶק ב׳"],["מָה הַסִּבָּה הָרִאשׁוֹנָה שֶׁמַּשְׁכִּימִים לִתְפִלַּת שַׁחֲרִית בְּעֶרֶב פֶּסַח?",["כְּדֵי לְהַסְפִּיק לִשְׂרֹף אֶת הַמַּצּוֹת לִפְנֵי הַחַג","כְּדֵי לֶאֱכֹל הַרְבֵּה מַצָּה לִפְנֵי שֶׁהַיּוֹם מִתְחַמֵּם","כְּדֵי לְסַיֵּם אֲכִילַת חָמֵץ לִפְנֵי סוֹף הַשָּׁעָה הָרְבִיעִית","כִּי בְּעֶרֶב פֶּסַח אָסוּר לִישֹׁן אַחֲרֵי הַזְּרִיחָה"],2,"מִסּוֹף הַשָּׁעָה הָרְבִיעִית (זְמַנִּית) מַתְחִיל מִדִּבְרֵי חֲכָמִים אִסּוּר אֲכִילַת חָמֵץ, וְצָרִיךְ לְהַסְפִּיק לְסַיֵּם לִפְנֵי כֵן. וְגַם כְּדֵי שֶׁיִּהְיֶה זְמַן לְהָכִין לְלֵיל הַסֵּדֶר.","פֶּרֶק ס״א, הֲלָכָה א׳","עֶרֶב פֶּסַח"],["לָמָּה בְּחֵלֶק מֵהַקְּהִלּוֹת אֵין אוֹמְרִים \"מִזְמוֹר לְתוֹדָה\" בְּעֶרֶב פֶּסַח?",["כִּי בְּעֶרֶב פֶּסַח אֵין אוֹמְרִים שׁוּם מִזְמוֹר","כִּי עִם קָרְבַּן תּוֹדָה מְבִיאִים גַּם חַלּוֹת חָמֵץ","כִּי הַמִּזְמוֹר אָרֹךְ מִדַּי וּמְמַהֲרִים לַעֲבוֹדָה","כִּי אוֹמְרִים אוֹתוֹ רַק בְּלֵיל הַסֵּדֶר עַצְמוֹ"],1,"הַמִּזְמוֹר הוּא כְּנֶגֶד קָרְבַּן תּוֹדָה, וּבְעֶרֶב פֶּסַח לֹא מַקְרִיבִים קָרְבַּן תּוֹדָה, כִּי יַחַד אִתּוֹ מְבִיאִים גַּם חַלּוֹת חָמֵץ.","פֶּרֶק ס״א, הֲלָכָה ב׳","עֶרֶב פֶּסַח"],["זֵכֶר לְמָה מִתְעַנִּים הַבְּכוֹרוֹת בְּעֶרֶב פֶּסַח?",["זֵכֶר לַבְּכוֹרִים שֶׁהֵבִיאוּ לְבֵית הַמִּקְדָּשׁ בִּירוּשָׁלַיִם","כְּדֵי שֶׁיִּהְיוּ רְעֵבִים מְאוֹד לִסְעֻדַּת לֵיל הַסֵּדֶר","כִּי הַבְּכוֹר צָרִיךְ לִבְדֹּק חָמֵץ כָּל הַיּוֹם","זֵכֶר לַנֵּס שֶׁנִּצְּלוּ בְּכוֹרֵי יִשְׂרָאֵל בְּמַכַּת בְּכוֹרוֹת"],3,"הַבְּכוֹרוֹת, בֵּין בְּכוֹר מֵאָב וּבֵין בְּכוֹר מֵאֵם, מִתְעַנִּים זֵכֶר לַנֵּס שֶׁהִבְדִּיל ה׳ בֵּין בְּכוֹרֵי מִצְרַיִם לִבְכוֹרֵי יִשְׂרָאֵל בְּמַכַּת בְּכוֹרוֹת.","פֶּרֶק ס״א, הֲלָכָה ג׳","עֶרֶב פֶּסַח"],["הַבְּכוֹר עוֹד קָטָן, וְגַם אָבִיו הוּא בְּכוֹר. מִי מִתְעַנֶּה בִּמְקוֹם הַבֵּן?",["הָאֵם מִתְעַנָּה בִּמְקוֹם בְּנָהּ הַבְּכוֹר הַקָּטָן","הַיֶּלֶד הַקָּטָן מִתְעַנֶּה בְּעַצְמוֹ כָּל הַיּוֹם","אַף אֶחָד לֹא מִתְעַנֶּה בִּמְקוֹם הַיֶּלֶד","הָאָח הַגָּדוֹל מִתְעַנֶּה בִּמְקוֹם הַבְּכוֹר הַקָּטָן"],0,"עַד גִּיל מִצְווֹת מִתְעַנֶּה הָאָב בִּמְקוֹם הַבְּכוֹר, וְאִם הָאָב בְּכוֹר בְּעַצְמוֹ (וּמִתְעַנֶּה עַל עַצְמוֹ) תִּתְעַנֶּה הָאֵם.","פֶּרֶק ס״א, הֲלָכָה ד׳","עֶרֶב פֶּסַח"],["אֵיךְ פּוֹטְרִים הַבְּכוֹרוֹת בְּיָמֵינוּ אֶת עַצְמָם מֵהַתַּעֲנִית?",["נוֹתְנִים צְדָקָה לַעֲנִיִּים בִּמְקוֹם הַתַּעֲנִית","אוֹמְרִים פִּרְקֵי תְּהִלִּים מְיֻחָדִים בְּבֵית הַכְּנֶסֶת","מִשְׁתַּתְּפִים בְּסִיּוּם מַסֶּכֶת וְטוֹעֲמִים מִסְּעֻדַּת הַמִּצְוָה","מִתְעַנִּים רַק עַד חֲצוֹת הַיּוֹם וְלֹא יוֹתֵר"],2,"בְּיָמֵינוּ נוֹהֲגִים לְהָקֵל: מִשְׁתַּתְּפִים בְּסִיּוּם מַסֶּכֶת וְטוֹעֲמִים מִסְּעֻדַּת הַמִּצְוָה, וְכָךְ נִפְטָרִים מֵהַתַּעֲנִית.","פֶּרֶק ס״א, הֲלָכָה ה׳","עֶרֶב פֶּסַח"],["לָמָּה אָסְרוּ חֲכָמִים לֶאֱכֹל מַצָּה בְּעֶרֶב פֶּסַח?",["כִּי הַמַּצּוֹת עֲדַיִן לֹא נֶאֱפוּ עַד הָעֶרֶב","כְּדֵי שֶׁבַּלַּיְלָה יִהְיֶה נִכָּר שֶׁאוֹכְלִים לְשֵׁם מִצְוָה","כְּדֵי לִשְׁמֹר אֶת כָּל הַמַּצּוֹת לָאוֹרְחִים","כִּי מַצָּה שֶׁל עֶרֶב פֶּסַח נֶחְשֶׁבֶת חָמֵץ"],1,"הָאִסּוּר הוּא כְּדֵי שֶׁבְּלֵיל הַפֶּסַח יִהְיֶה נִכָּר שֶׁאוֹכְלִים אֶת הַמַּצָּה לְשֵׁם מִצְוָה.","פֶּרֶק ס״א, הֲלָכָה ז׳","עֶרֶב פֶּסַח"],["לָמָּה לַנּוֹהֲגִים לֶאֱכֹל מַצָּה עֲשִׁירָה מֻתָּר לְאָכְלָהּ גַּם בְּעֶרֶב פֶּסַח?",["כִּי הִיא מְתוּקָה וִילָדִים אוֹהֲבִים אוֹתָהּ מְאוֹד","כִּי לָשִׁים אוֹתָהּ רַק עִם מַיִם צוֹנְנִים","כִּי אוֹכְלִים אוֹתָהּ רַק אַחֲרֵי חַג הַפֶּסַח","כִּי אֵין יוֹצְאִים בָּהּ יְדֵי חוֹבַת מִצְוַת מַצָּה"],3,"הָאִסּוּר הוּא רַק עַל מַצָּה שֶׁאֶפְשָׁר לְקַיֵּם בָּהּ אֶת הַמִּצְוָה. בְּמַצָּה עֲשִׁירָה אֵין יוֹצְאִים יְדֵי חוֹבַת מִצְוַת אֲכִילַת מַצָּה.","פֶּרֶק ס״א, הֲלָכָה ח׳","עֶרֶב פֶּסַח"],["מֵאֵימָתַי יֵשׁ נוֹהֲגִים שֶׁלֹּא לֶאֱכֹל מַצָּה?",["מִיּוֹם פּוּרִים וְעַד חַג הַפֶּסַח","כְּבָר מִיּוֹם רֹאשׁ חֹדֶשׁ נִיסָן","רַק מֵחֲצוֹת הַלַּיְלָה שֶׁל בְּדִיקַת חָמֵץ","מִתְּחִלַּת חֹדֶשׁ אֲדָר שֶׁלִּפְנֵי הַפֶּסַח"],1,"יֵשׁ נוֹהֲגִים שֶׁלֹּא לֶאֱכֹל מַצָּה כְּבָר מֵרֹאשׁ חֹדֶשׁ נִיסָן.","פֶּרֶק ס״א, הֲלָכָה י׳","עֶרֶב פֶּסַח"],["לָמָּה אָסוּר לֶאֱכֹל מַצָּה עֲשִׁירָה מִתְּחִלַּת הַשָּׁעָה הָעֲשִׂירִית?",["כִּי מֵהַשָּׁעָה הָעֲשִׂירִית הִיא נַעֲשֵׂית חָמֵץ גָּמוּר","כִּי צָרִיךְ לָלֶכֶת לִתְפִלַּת מִנְחָה בְּבֵית הַכְּנֶסֶת","כְּדֵי לֶאֱכֹל אֶת הַמַּצָּה בְּלֵיל הַסֵּדֶר לְתֵאָבוֹן","כִּי אָז כְּבָר שׂוֹרְפִים אֶת כָּל הַמַּצּוֹת"],2,"גַּם לַנּוֹהֲגִים לֶאֱכֹל מַצָּה עֲשִׁירָה, אָסוּר לְאָכְלָהּ מִתְּחִלַּת הַשָּׁעָה הָעֲשִׂירִית (זְמַנִּית), כְּדֵי שֶׁבְּלֵיל הַסֵּדֶר יֹאכְלוּ אֶת הַמַּצָּה לְתֵאָבוֹן.","פֶּרֶק ס״א, הֲלָכָה י״א","עֶרֶב פֶּסַח"],["לְפִי הַמַּחְמִירִים, מִמָּתַי אֵין לֶאֱכֹל מַצָּה עֲשִׁירָה בְּעֶרֶב פֶּסַח?",["מִזְּמַן הַזְּרִיחָה שֶׁל בֹּקֶר עֶרֶב הַפֶּסַח","רַק מִשְּׁקִיעַת הַחַמָּה בְּעֶרֶב הַפֶּסַח","מִסּוֹף הַשָּׁעָה הָרְבִיעִית, יַחַד עִם הֶחָמֵץ","מִזְּמַן מִנְחָה גְּדוֹלָה, כַּחֲצִי שָׁעָה אַחֲרֵי חֲצוֹת"],3,"יֵשׁ מַחְמִירִים מִזְּמַן מִנְחָה גְּדוֹלָה (כַּחֲצִי שָׁעָה זְמַנִּית אַחֲרֵי חֲצוֹת הַיּוֹם), אֲבָל בִּשְׁעַת הַצֹּרֶךְ אֶפְשָׁר לְהָקֵל עַד תְּחִלַּת הַשָּׁעָה הָעֲשִׂירִית.","פֶּרֶק ס״א, הֲלָכָה י״ג","עֶרֶב פֶּסַח"],["מָה הַדִּין לַעֲשׂוֹת מְלָאכָה בְּעֶרֶב פֶּסַח לִפְנֵי חֲצוֹת הַיּוֹם?",["אָסוּר בְּכָל מָקוֹם לַעֲשׂוֹת שׁוּם מְלָאכָה כָּל הַיּוֹם","תָּלוּי בְּמִנְהַג הַמָּקוֹם, יֵשׁ שֶׁנָּהֲגוּ לַעֲשׂוֹת וְיֵשׁ שֶׁלֹּא","מֻתָּר בְּכָל מָקוֹם, וַאֲפִלּוּ אַחֲרֵי חֲצוֹת הַיּוֹם","מֻתָּר רַק לְמִי שֶׁסִּיֵּם אֶת בְּדִיקַת הֶחָמֵץ שֶׁלּוֹ"],1,"בְּחֵלֶק מֵהַמְּקוֹמוֹת נָהֲגוּ לַעֲשׂוֹת מְלָאכָה עַד חֲצוֹת, וּבְחֵלֶק נָהֲגוּ שֶׁלֹּא לַעֲשׂוֹת. סְחוֹרָה מֻתֶּרֶת בְּכָל מָקוֹם עַד חֲצוֹת.","פֶּרֶק ס״א, הֲלָכָה י״ד","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מִנַּיִן שֶׁאָסוּר לַעֲשׂוֹת מְלָאכָה בְּעֶרֶב פֶּסַח מֵחֲצוֹת הַיּוֹם?",["כִּי מֵחֲצוֹת חַיָּבִים לָשֶׁבֶת וְלִלְמֹד אֶת הַהַגָּדָה","כִּי מֵחֲצוֹת כְּבָר מַתְחִיל הֶחָג עַצְמוֹ","כִּי מֵחֲצוֹת צְרִיכִים לִשְׂרֹף אֶת כָּל הֶחָמֵץ","כִּי מֵחֲצוֹת מַתְחִילִים לְהַקְרִיב אֶת קָרְבַּן הַפֶּסַח"],3,"מֵחֲצוֹת יוֹם י״ד בְּנִיסָן מַקְרִיבִים אֶת קָרְבַּן הַפֶּסַח, וְלָכֵן אָסְרוּ חֲכָמִים מְלָאכָה כְּמוֹ בְּחֹל הַמּוֹעֵד. מְלָאכוֹת כְּמוֹ גְּזִיזַת צִפָּרְנַיִם וְצִחְצוּחַ נַעֲלַיִם מֻתָּרוֹת.","פֶּרֶק ס״א, הֲלָכָה ט״ו","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["עַל מִי מֻטֶּלֶת הַמִּצְוָה לְהַשְׁכִּיב אֶת הַיְּלָדִים לִישׁוֹן בַּצָּהֳרַיִם?",["עַל הָאָב, שֶׁחַיָּב בְּמִצְוַת וְהִגַּדְתָּ לְבִנְךָ","עַל הַמְּלַמֵּד, שֶׁמְּלַמֵּד אֶת הַיְּלָדִים בְּבֵית הַסֵּפֶר","עַל הַסַּבָּא, שֶׁעוֹרֵךְ אֶת הַסֵּדֶר לְכָל הַמִּשְׁפָּחָה","עַל הָרַב, שֶׁמַּכְרִיז עַל זְמַן הַמְּנוּחָה"],0,"הַמִּצְוָה מֻטֶּלֶת עַל הָאָב, שֶׁחַיָּב בְּמִצְוַת ״וְהִגַּדְתָּ לְבִנְךָ״, כְּדֵי שֶׁהַיְּלָדִים יִהְיוּ עֵרָנִיִּים לְסִפּוּר הַהַגָּדָה.","פֶּרֶק ס״א, הֲלָכָה ט״ז","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מָה פֵּרוּשׁ ״מַצָּה שְׁמוּרָה מִשְּׁעַת קְצִירָה״?",["שׁוֹמְרִים אֶת הַמַּצּוֹת בָּאָרוֹן הַסָּגוּר עַד לֵיל הַסֵּדֶר","קוֹצְרִים אֶת הַחִטִּים בְּיָדַיִם בִּלְבַד, בְּלִי שׁוּם מְכוֹנוֹת","מִזְּמַן הַקְּצִירָה הֵכִינוּ אֶת הַקֶּמַח לְשֵׁם מִצְוָה וְשָׁמְרוּ מֵרְטִיבוּת","אוֹפִים אֶת הַמַּצּוֹת מִיָּד בְּאוֹתוֹ יוֹם שֶׁקָּצְרוּ אֶת הַחִטִּים"],2,"כְּבָר מִזְּמַן הַקְּצִירָה הֵכִינוּ אֶת הַקֶּמַח לְשֵׁם מִצְוַת מַצָּה וְשָׁמְרוּ שֶׁהַחִטִּים לֹא יֵרָטְבוּ. מִי שֶׁאֵין לוֹ מַצָּה כָּזוֹ, יוֹצֵא גַּם בְּמַצָּה רְגִילָה.","פֶּרֶק ס״א, הֲלָכָה י״ז","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מַדּוּעַ הַמְּהַדְּרִים אוֹפִים מַצּוֹת בְּעֶרֶב פֶּסַח אַחֲרֵי חֲצוֹת?",["כִּי אָז הַתַּנּוּר כְּבָר חַם וּמוּכָן לַאֲפִיָּה","כִּי בַּבֹּקֶר עֲדַיִן אָסוּר לָגַעַת בְּקֶמַח","כִּי כָּךְ הַמַּצּוֹת נִשְׁאָרוֹת טְרִיּוֹת לְלֵיל הַסֵּדֶר","כִּי בִּזְמַן זֶה מַקְרִיבִים אֶת קָרְבַּן הַפֶּסַח"],3,"אַחֲרֵי חֲצוֹת הוּא הַזְּמַן שֶׁבּוֹ מַקְרִיבִים אֶת קָרְבַּן הַפֶּסַח בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם, וְלָכֵן הַמְּהַדְּרִים אוֹפִים אָז אֶת מַצּוֹת הַמִּצְוָה.","פֶּרֶק ס״א, הֲלָכָה י״ח","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מַדּוּעַ חוֹבָה לִבְדֹּק הֵיטֵב אֶת עֲלֵי הַחַסָּה לְמָרוֹר?",["כִּי עָלִים יְבֵשִׁים אֵינָם מְרִירִים מַסְפִּיק לְמִצְוַת מָרוֹר","כִּי יֵשׁ בָּהֶן תּוֹלָעִים יְרֻקּוֹת, וַאֲכִילַת תּוֹלָעִים אִסּוּר חָמוּר","כִּי צָרִיךְ לִסְפֹּר אֶת הָעָלִים לְפִי מִסְפַּר הַמְּסֻבִּים","כִּי עֲלֵי הַחַסָּה מְלֻכְלָכִים בְּאָבָק וּבְאַדְמָה שֶׁל הַשָּׂדֶה"],1,"בַּעֲלֵי הַחַסָּה (הַמָּרוֹר) מְצוּיוֹת תּוֹלָעִים יְרֻקּוֹת קְטַנּוֹת, וְאִסּוּר אֲכִילַת תּוֹלָעִים חָמוּר. לָכֵן בּוֹדְקִים לְאוֹר הַשֶּׁמֶשׁ, אוֹ קוֹנִים חַסָּה נְקִיָּה וְשׁוֹטְפִים הֵיטֵב.","פֶּרֶק ס״א, הֲלָכָה י״ט-כ׳","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["הַחֲרֹסֶת הִיא זֵכֶר לַטִּיט שֶׁבְּמִצְרַיִם. אִם שָׁכְחוּ לְהָכִין אוֹתָהּ לִפְנֵי פֶּסַח, מָה הַדִּין?",["אָסוּר לְהָכִין, וְעוֹשִׂים אֶת הַסֵּדֶר בְּלִי חֲרֹסֶת","מֻתָּר לְהָכִין גַּם בְּיוֹם טוֹב וְגַם בְּשַׁבָּת","מֻתָּר לְהָכִין בְּיוֹם טוֹב, אֲבָל לֹא בְּשַׁבָּת","מֻתָּר לְהָכִין רַק בְּשַׁבָּת, אֲבָל לֹא בְּיוֹם טוֹב"],2,"מְכִינִים חֲרֹסֶת מִתַּפּוּחִים, אֱגוֹזִים, רִמּוֹנִים וּשְׁקֵדִים, טְחוּנִים כְּמוֹ טִיט. מְכִינִים לִפְנֵי פֶּסַח, וְאִם שָׁכְחוּ מֻתָּר בְּיוֹם טוֹב אֲבָל לֹא בְּשַׁבָּת.","פֶּרֶק ס״א, הֲלָכָה כ״א-כ״ב","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["בִּזְמַן הַמִּקְדָּשׁ אָכְלוּ קֹדֶם מִקָּרְבַּן הַחֲגִיגָה (שֶׁהַבֵּיצָה הַמְּבֻשֶּׁלֶת זֵכֶר לוֹ). לָמָּה אֶת בְּשַׂר הַפֶּסַח אָכְלוּ לְבַסּוֹף?",["כְּדֵי לֶאֱכֹל אֶת בְּשַׂר הַפֶּסַח עַל הַשֹּׂבַע","כִּי בְּשַׂר הַפֶּסַח הָיָה צָרִיךְ עוֹד זְמַן צְלִיָּה","כִּי קָרְבַּן הַחֲגִיגָה הָיָה גָּדוֹל וְכָבֵד יוֹתֵר","כִּי הַכֹּהֲנִים הִקְרִיבוּ אֶת הַפֶּסַח בַּסּוֹף"],0,"אָכְלוּ קֹדֶם מִקָּרְבַּן הַחֲגִיגָה, וְאֶת הַפֶּסַח לְבַסּוֹף כְּדֵי לְאָכְלוֹ עַל הַשֹּׂבַע. הַיּוֹם שָׂמִים זְרוֹעַ צְלוּיָה (זֵכֶר לַפֶּסַח) וּבֵיצָה מְבֻשֶּׁלֶת (זֵכֶר לַחֲגִיגָה).","פֶּרֶק ס״א, הֲלָכָה כ״ג-כ״ד","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מַדּוּעַ יֵשׁ לִצְלוֹת אֶת הַזְּרוֹעַ כְּבָר בְּעֶרֶב פֶּסַח?",["כִּי הַזְּרוֹעַ צְרִיכָה לְהִתְקָרֵר הַרְבֵּה שָׁעוֹת לִפְנֵי הַסֵּדֶר","כִּי הַזְּרוֹעַ חַיֶּבֶת לִהְיוֹת קָרָה וִיבֵשָׁה לְגַמְרֵי בִּשְׁעַת הַסֵּדֶר","כִּי אֶת הַזְּרוֹעַ אוֹכְלִים כְּבָר בִּסְעֻדַּת הַצָּהֳרַיִם","כִּי אָסוּר לְבַשֵּׁל בְּיוֹם טוֹב מַאֲכָל שֶׁלֹּא לְצֹרֶךְ אֲכִילָה"],3,"אֶת הַזְּרוֹעַ אָסוּר לֶאֱכֹל בְּלֵיל פֶּסַח, וְאָסוּר לְבַשֵּׁל בְּיוֹם טוֹב מַאֲכָל שֶׁלֹּא לְצֹרֶךְ אֲכִילָה, לָכֵן צוֹלִים אוֹתָהּ בְּעֶרֶב פֶּסַח.","פֶּרֶק ס״א, הֲלָכָה כ״ה","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מָתַי צָרִיךְ לְהָכִין אֶת מֵי הַמֶּלַח לְטִבּוּל הַכַּרְפַּס?",["לִפְנֵי כְּנִיסַת הֶחָג, וּבִמְיֻחָד כְּשֶׁלֵּיל הַסֵּדֶר בְּשַׁבָּת","בְּאֶמְצַע הַסֵּדֶר, רֶגַע לִפְנֵי שֶׁטּוֹבְלִים אֶת הַכַּרְפַּס","בְּמוֹצָאֵי הֶחָג, לִקְרַאת הַסֵּדֶר שֶׁל הַשָּׁנָה הַבָּאָה","רַק אַחֲרֵי הַקִּדּוּשׁ, כְּשֶׁכָּל הַמִּשְׁפָּחָה יוֹשֶׁבֶת"],0,"צָרִיךְ לְהָכִין מֵי מֶלַח לִפְנֵי כְּנִיסַת הֶחָג, וּבִמְיֻחָד אִם לֵיל הַסֵּדֶר חָל בְּשַׁבָּת.","פֶּרֶק ס״א, הֲלָכָה כ״ו","עֶרֶב פֶּסַח: מִתְכּוֹנְנִים לְלֵיל הַסֵּדֶר"],["מָתַי דּוֹרְשִׁים אֶת דְּרָשַׁת שַׁבָּת הַגָּדוֹל בְּשָׁנָה שֶׁעֶרֶב פֶּסַח חָל בְּשַׁבָּת?",["בְּעֶרֶב פֶּסַח עַצְמוֹ, אַחֲרֵי סְעוּדַת הַשַּׁבָּת","בַּשַּׁבָּת שֶׁלְּפָנֶיהָ, בְּשִׁבְעָה בְּחֹדֶשׁ נִיסָן","בְּלֵיל הַסֵּדֶר, לִפְנֵי שֶׁמַּתְחִילִים אֶת הַהַגָּדָה","בְּחֹל הַמּוֹעֵד, כְּשֶׁכֻּלָּם פְּנוּיִים לִשְׁמֹעַ"],1,"מַקְדִּימִים אֶת הַדְּרָשָׁה לַשַּׁבָּת שֶׁלְּפָנֶיהָ, ז׳ בְּנִיסָן.","פֶּרֶק ס״ב, הֲלָכָה א׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["בְּאֵילוּ כֵּלִים מְכִינִים אֶת הָאֹכֶל לְשַׁבָּת זוֹ?",["בִּכְלֵי חָמֵץ, כִּי עֲדַיִן מֻתָּר לֶאֱכֹל חָמֵץ כָּל הַיּוֹם","בִּכְלֵי חָמֵץ, וּמְנַקִּים אוֹתָם הֵיטֵב בְּשַׁבָּת אַחֲרֵי הָאֹכֶל","בְּכָל כְּלִי שֶׁיֵּשׁ, כִּי בְּשַׁבָּת אֵין דִּינֵי חָמֵץ","בִּכְלֵי פֶּסַח, כִּי קָשֶׁה לְנַקּוֹת בְּשַׁבָּת כֵּלִים עִם חָמֵץ"],3,"מְכִינִים מַאֲכָלִים כְּשֵׁרִים לְפֶסַח בִּכְלֵי פֶּסַח, כִּי קָשֶׁה לְנַקּוֹת הֵיטֵב בְּשַׁבָּת כֵּלִים שֶׁדָּבוּק לָהֶם חָמֵץ.","פֶּרֶק ס״ב, הֲלָכָה ד׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["מָה עוֹשִׂים בְּחָמֵץ שֶׁנִּשְׁאַר בְּשַׁבָּת, וּמָה אוֹמְרִים אַחַר כָּךְ?",["שׂוֹרְפִים אוֹתוֹ בְּאֵשׁ בַּחֲצֵר, וְאוֹמְרִים הַגָּדָה שֶׁל פֶּסַח","מַחְבִּיאִים אוֹתוֹ בָּאָרוֹן עַד מוֹצָאֵי שַׁבָּת, וְלֹא אוֹמְרִים כְּלוּם","זוֹרְקִים לָאַסְלָה אוֹ לְפַח בָּרְחוֹב, וְאוֹמְרִים נֹסַח בִּטּוּל","מַשְׁאִירִים אוֹתוֹ עַל הַשֻּׁלְחָן, וּמְבָרְכִים עַל בְּדִיקַת חָמֵץ"],2,"נִפְטָרִים מִכָּל הֶחָמֵץ עַד סוֹף הַשָּׁעָה הַחֲמִישִׁית, וְאַחַר כָּךְ אוֹמְרִים אֶת נֹסַח הַבִּטּוּל שֶׁל אַחֲרֵי הַשְּׂרֵפָה.","פֶּרֶק ס״ב, הֲלָכָה ז׳-ח׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["מָה אוֹכְלִים בַּסְּעוּדָה הַשְּׁלִישִׁית שֶׁל שַׁבָּת זוֹ?",["לֶחֶם רָגִיל, כִּי עֲדַיִן שַׁבָּת וְחַיָּבִים לֶאֱכֹל פַּת","מַצָּה רְגִילָה, כִּי כְּבָר אָסוּר לֶאֱכֹל חָמֵץ בַּבַּיִת","לֹא אוֹכְלִים כְּלוּם, וְצָמִים עַד לֵיל הַסֵּדֶר בָּעֶרֶב","מַצָּה עֲשִׁירָה לַנּוֹהֲגִים בָּהּ, אוֹ פֵּרוֹת, יְרָקוֹת, בָּשָׂר וְדָגִים"],3,"אָסוּר כְּבָר חָמֵץ וְגַם מַצָּה רְגִילָה, לָכֵן אוֹכְלִים מַצָּה עֲשִׁירָה (לַנּוֹהֲגִים) אוֹ פֵּרוֹת וִירָקוֹת אוֹ בָּשָׂר וְדָגִים.","פֶּרֶק ס״ב, הֲלָכָה ט׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["עַד מָתַי יֵשׁ לֶאֱכֹל אֶת הַסְּעוּדָה הַשְּׁלִישִׁית, וְלָמָּה?",["לִפְנֵי הַשָּׁעָה הָעֲשִׂירִית, כְּדֵי לֶאֱכֹל מַצָּה בְּלֵיל הַסֵּדֶר לְתֵאָבוֹן","עַד צֵאת הַכּוֹכָבִים, כְּדֵי שֶׁלֹּא נִהְיֶה רְעֵבִים בַּסֵּדֶר","לִפְנֵי חֲצוֹת הַיּוֹם, כְּדֵי לְהַסְפִּיק לִשְׂרֹף אֶת כָּל הֶחָמֵץ","עַד הַשְּׁקִיעָה, כִּי אַחֲרֶיהָ מַתְחִיל כְּבָר לֵיל הַסֵּדֶר"],0,"אוֹכְלִים לִפְנֵי תְּחִלַּת הַשָּׁעָה הָעֲשִׂירִית (זְמַנִּית) מֵהַזְּרִיחָה, כְּדֵי לֶאֱכֹל אֶת הַמַּצָּה בַּסֵּדֶר לְתֵאָבוֹן.","פֶּרֶק ס״ב, הֲלָכָה י׳","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["מָתַי עוֹרְכִים אֶת שֻׁלְחַן לֵיל הַסֵּדֶר בְּשָׁנָה כָּזוֹ?",["בְּשַׁבָּת אַחַר הַצָּהֳרַיִם, כְּדֵי שֶׁיִּהְיֶה מוּכָן בַּזְּמַן","בְּשַׁבָּת בַּבֹּקֶר, מִיָּד אַחֲרֵי תְּפִלַּת שַׁחֲרִית בַּבַּיִת","בְּיוֹם שִׁשִּׁי, אוֹ מַמְתִּינִים עַד שֶׁתֵּצֵא הַשַּׁבָּת","בְּיוֹם חֲמִישִׁי, לִפְנֵי בְּדִיקַת הֶחָמֵץ בָּעֶרֶב"],2,"אָסוּר לְהָכִין מִשַּׁבָּת לְיוֹם טוֹב, וְלָכֵן מְסַדְּרִים אֶת הַשֻּׁלְחָן בְּיוֹם שִׁשִּׁי אוֹ מַמְתִּינִים לְצֵאת הַשַּׁבָּת.","פֶּרֶק ס״ב, הֲלָכָה י״א","עֶרֶב פֶּסַח שֶׁחָל בְּשַׁבָּת"],["מַהוּ לֵיל הַסֵּדֶר?",["לַיְלָה שֶׁבּוֹ מְסַפְּרִים בְּנִסֵּי ה׳ בִּיצִיאַת מִצְרַיִם","לַיְלָה שֶׁבּוֹ מְסַפְּרִים סִפּוּרִים עַל גִּבּוֹרֵי הַתַּנַ״ךְ","לַיְלָה שֶׁבּוֹ כָּל אֶחָד חוֹגֵג לְבַד בְּבֵיתוֹ","לַיְלָה רָגִיל שֶׁאֵין בּוֹ שׁוּם מִצְוָה מְיֻחֶדֶת"],0,"הַמִּשְׁפָּחוֹת מִתְכַּנְּסוֹת וּמְסַפְּרוֹת בִּיצִיאַת מִצְרַיִם – הַמְּאֹרָע שֶׁבּוֹ הָפַכְנוּ לְעַם ה׳.","פֶּרֶק ס״ג, הֲלָכָה א׳","לֵיל הַסֵּדֶר"],["מִצְוַת אֲכִילַת מָרוֹר בַּזְּמַן שֶׁאֵין מַקְרִיבִים קָרְבַּן פֶּסַח הִיא:",["מִן הַתּוֹרָה, בְּדִיּוּק כְּמוֹ אֲכִילַת הַמַּצָּה","מִנְהָג בִּלְבַד, וּמִי שֶׁרוֹצֶה מְוַתֵּר עָלָיו","מִדִּבְרֵי חֲכָמִים, כִּי אֵין מַקְרִיבִים קָרְבַּן פֶּסַח","אֵין צֹרֶךְ כְּלָל לֶאֱכֹל מָרוֹר בַּזְּמַן הַזֶּה"],2,"כְּשֶׁמַּקְרִיבִים קָרְבַּן פֶּסַח – הַמָּרוֹר מִן הַתּוֹרָה. הַיּוֹם – מִדִּבְרֵי חֲכָמִים. וְאַחַר כָּךְ כּוֹרְכִים מַצָּה וּמָרוֹר זֵכֶר לַמִּקְדָּשׁ כְּהִלֵּל.","פֶּרֶק ס״ג, הֲלָכָה ב׳","לֵיל הַסֵּדֶר"],["לְשֵׁם מָה עוֹשִׂים שִׁנּוּיִים בְּלֵיל הַסֵּדֶר, כְּמוֹ אֲכִילַת כַּרְפַּס?",["כְּדֵי שֶׁהַסְּעוּדָה תִּהְיֶה קְצָרָה וּמְהִירָה יוֹתֵר","כְּדֵי שֶׁהַבָּנִים יִרְאוּ וְיִשְׁאֲלוּ מַה נִּשְׁתַּנָּה","כִּי כָּךְ נָהֲגוּ רַק בְּבֵית הַמִּקְדָּשׁ","כְּדֵי שֶׁהַיְּלָדִים יֵלְכוּ לִישֹׁן מֻקְדָּם יוֹתֵר"],1,"הַשִּׁנּוּי מְעוֹרֵר אֶת סַקְרָנוּת הַיְּלָדִים. רָאוּי לְהוֹסִיף שִׁנּוּיִים כְּמוֹ פְּרָסִים וּמַמְתַּקִּים.","פֶּרֶק ס״ג, הֲלָכָה ג׳","לֵיל הַסֵּדֶר"],["לָמָּה כְּדַאי לְהוֹשִׁיב אֶת הַיְּלָדִים לְיַד אֲבִיהֶם?",["כְּדֵי שֶׁיְּקַיֵּם אֶת וְהִגַּדְתָּ לְבִנְךָ בְּצוּרָה מְהֻדֶּרֶת","כְּדֵי שֶׁיּוּכַל לִשְׁמֹר שֶׁהֵם לֹא יִרְעֲשׁוּ","כְּדֵי שֶׁיִּהְיֶה מָקוֹם פָּנוּי לָאוֹרְחִים בַּשֻּׁלְחָן","כִּי כָּךְ קַל יוֹתֵר לְחַלֵּק לָהֶם אֹכֶל"],0,"כְּשֶׁהַיְּלָדִים, גְּדוֹלִים וּקְטַנִּים, יוֹשְׁבִים לְיַד הָאָב – הוּא מְסַפֵּר לָהֶם בִּיצִיאַת מִצְרַיִם בְּצוּרָה מְהֻדֶּרֶת.","פֶּרֶק ס״ג, הֲלָכָה ד׳","לֵיל הַסֵּדֶר"],["לָמָּה עוֹרְכִים אֶת הַשֻּׁלְחָן וְאֶת הַקְּעָרָה מִבְּעוֹד יוֹם?",["כִּי בַּלַּיְלָה אָסוּר לָגַעַת בִּכְלֵי הַסֵּדֶר","כְּדֵי שֶׁהָאוֹרְחִים יִרְאוּ כַּמָּה הַשֻּׁלְחָן יָפֶה","כִּי כָּךְ נוֹהֲגִים רַק בַּעֲדוֹת מְסֻיָּמוֹת","כְּדֵי לְהַתְחִיל אֶת הַסֵּדֶר מִיָּד אַחֲרֵי עַרְבִית"],3,"מְכִינִים מֵרֹאשׁ כְּדֵי לְהַתְחִיל מִיָּד אַחֲרֵי תְּפִלַּת עַרְבִית. בְּסִדּוּר הַקְּעָרָה כָּל אֶחָד נוֹהֵג כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק ס״ג, הֲלָכָה ה׳","לֵיל הַסֵּדֶר"],["בֵּן שֶׁנִּמְצָא אֵצֶל אָבִיו בְּלֵיל הַסֵּדֶר – מָה דִּינוֹ בַּהֲסָבָה?",["פָּטוּר מֵהֲסָבָה מִשּׁוּם כְּבוֹד אָבִיו","מֵסֵב רַק בִּשְׁעַת אֲכִילַת הַמָּרוֹר","חַיָּב לֶאֱכֹל וְלִשְׁתּוֹת בַּהֲסָבָה לְצַד שְׂמֹאל","חַיָּב לְהָסֵב אֲבָל דַּוְקָא לְצַד יָמִין"],2,"בֵּן אֵצֶל אָבִיו חַיָּב בַּהֲסָבָה. מְסִבִּים לְצַד שְׂמֹאל דֶּרֶךְ חֵרוּת, כְּאִלּוּ יָצָאנוּ עַתָּה מִמִּצְרַיִם.","פֶּרֶק ס״ג, הֲלָכוֹת ו׳, ח׳","לֵיל הַסֵּדֶר"],["מָה נִפְסַק לְגַבֵּי נָשִׁים בְּלֵיל הַסֵּדֶר?",["פְּטוּרוֹת מִכָּל מִצְווֹת לֵיל הַסֵּדֶר לְגַמְרֵי","חַיָּבוֹת בְּאַרְבַּע כּוֹסוֹת, וּבַהֲסָבָה נוֹהֲגוֹת כְּמִנְהַג מִשְׁפַּחְתָּן","חַיָּבוֹת רַק בְּמַצָּה, וּפְטוּרוֹת מֵאַרְבַּע כּוֹסוֹת","שׁוֹתוֹת כּוֹס אַחַת בִּלְבַד בְּסוֹף הַסֵּדֶר"],1,"נָשִׁים חַיָּבוֹת בְּאַרְבַּע כּוֹסוֹת וּבְכָל מִצְווֹת הַלַּיְלָה. בַּהֲסָבָה יֵשׁ אוֹמְרִים שֶׁצְּרִיכָה וְיֵשׁ אוֹמְרִים שֶׁאֵינָהּ חַיֶּבֶת.","פֶּרֶק ס״ג, הֲלָכוֹת ז׳, י״ג","לֵיל הַסֵּדֶר"],["מָתַי שׁוֹתִים אֶת הַכּוֹס הַשְּׁלִישִׁית?",["שׁוֹתִים אוֹתָהּ מִיָּד לְאַחַר הַקִּדּוּשׁ","שׁוֹתִים אוֹתָהּ בְּסוֹף אֲמִירַת הַמַּגִּיד","שׁוֹתִים אוֹתָהּ לְאַחַר שֶׁגּוֹמְרִים לוֹמַר הַלֵּל","שׁוֹתִים אוֹתָהּ מִיָּד לְאַחַר בִּרְכַּת הַמָּזוֹן"],3,"שׁוֹתִים עַל סֵדֶר הַהַגָּדָה: קִדּוּשׁ, מַגִּיד, בִּרְכַּת הַמָּזוֹן, הַלֵּל. הַשּׁוֹתֶה בִּזְמַן אַחֵר לֹא יָצָא.","פֶּרֶק ס״ג, הֲלָכָה ט׳","לֵיל הַסֵּדֶר"],["מָה הַדִּין בִּשְׁתִיַּת כָּל כּוֹס מֵאַרְבַּע הַכּוֹסוֹת?",["שׁוֹתִים לְגִימָה קְטַנָּה, וְרַק יַיִן לָבָן כָּשֵׁר","מַסְפִּיק לְהָרִיחַ אֶת הַיַּיִן וּלְבָרֵךְ עָלָיו","שׁוֹתִים בְּבַת אַחַת לְפָחוֹת רֹב רְבִיעִית, וְאָדֹם מְהֻדָּר","שׁוֹתִים לְאַט בְּהַפְסָקוֹת, וְכָל יַיִן מְהֻדָּר בְּאוֹתָהּ מִדָּה"],2,"בַּכּוֹס לְפָחוֹת רְבִיעִית, שׁוֹתִים כֻּלָּהּ אוֹ רֹב רְבִיעִית בְּלִי הַפְסָקוֹת. מְהַדְּרִים בְּאָדֹם, אַךְ גַּם בְּלָבָן יוֹצְאִים.","פֶּרֶק ס״ג, הֲלָכוֹת י׳-י״ב","לֵיל הַסֵּדֶר"],["מָה נִפְסַק עַל יְלָדִים וַעֲנִיִּים בְּעִנְיַן אַרְבַּע כּוֹסוֹת?",["יְלָדִים וַעֲנִיִּים פְּטוּרִים לְגַמְרֵי מֵאַרְבַּע כּוֹסוֹת","יֶלֶד שׁוֹתֶה מִכּוֹס אָבִיו, וְעָנִי פָּטוּר מֵהַכּוֹסוֹת","רַק עֲשִׁירִים חַיָּבִים לִקְנוֹת יַיִן לְאַרְבַּע כּוֹסוֹת","יֶלֶד מְקַבֵּל כּוֹס מִשֶּׁלּוֹ, וְעָנִי לֹוֶה בִּשְׁבִיל יַיִן"],3,"יֶלֶד בְּגִיל חִנּוּךְ מְקַבֵּל כּוֹס מִשֶּׁלּוֹ. עָנִי יִמְכֹּר מַלְבּוּשׁוֹ אוֹ יִלְוֶה, וּמִצְוָה עַל הַצִּבּוּר לַעֲזֹר לוֹ.","פֶּרֶק ס״ג, הֲלָכוֹת י״ד-ט״ו","לֵיל הַסֵּדֶר"],["מָה הַסֵּדֶר הַנָּכוֹן בִּתְחִלַּת הַשִּׁיר?",["קַדֵּשׁ יַחַץ, כַּרְפַּס וּרְחַץ, מַגִּיד רָחְצָה","כַּרְפַּס קַדֵּשׁ, וּרְחַץ יַחַץ, מַגִּיד רָחְצָה","קַדֵּשׁ וּרְחַץ, כַּרְפַּס יַחַץ, מַגִּיד רָחְצָה","קַדֵּשׁ וּרְחַץ, מַגִּיד יַחַץ, כַּרְפַּס רָחְצָה"],2,"הַשִּׁיר: קַדֵּשׁ וּרְחַץ, כַּרְפַּס יַחַץ, מַגִּיד רָחְצָה, מוֹצִיא מַצָּה, מָרוֹר כּוֹרֵךְ, שֻׁלְחָן עוֹרֵךְ, צָפוּן בָּרֵךְ, הַלֵּל נִרְצָה.","פֶּרֶק ס״ד, הֲלָכָה א׳","סִימָנֵי הַסֵּדֶר"],["הַיְּלָדִים הַקְּטַנִּים עֲיֵפִים מְאוֹד. מָה הַדִּין?",["מְקַדְּשִׁים מִיָּד בִּשְׁקִיעָה כְּדֵי שֶׁלֹּא יֵרָדְמוּ","מְמַהֲרִים, אֲבָל לֹא מְקַדְּשִׁים לִפְנֵי צֵאת הַכּוֹכָבִים","מְדַלְּגִים עַל הַהַגָּדָה כֻּלָּהּ וְאוֹכְלִים מַהֵר","מְקַדְּשִׁים בַּצָּהֳרַיִם כְּדֵי לְהַקְדִּים אֶת הַסֵּדֶר"],1,"יֵשׁ לְמַהֵר לְהַתְחִיל כְּדֵי שֶׁהַיְּלָדִים לֹא יֵרָדְמוּ, אֲבָל אֵין לְקַדֵּשׁ לִפְנֵי צֵאת הַכּוֹכָבִים.","פֶּרֶק ס״ד, הֲלָכָה ב׳","סִימָנֵי הַסֵּדֶר"],["לָמָּה מוֹזְגִים לַמְּקַדֵּשׁ, וְהוּא אֵינוֹ מוֹזֵג לְעַצְמוֹ?",["דֶּרֶךְ חֵרוּת, כְּמוֹ מֶלֶךְ שֶׁמּוֹזְגִים לוֹ","כִּי אָסוּר לוֹ לָגַעַת בַּבַּקְבּוּק בְּחַג","כְּדֵי שֶׁהַיַּיִן לֹא יִשָּׁפֵךְ עַל הַמַּפָּה","כִּי הַכּוֹס כְּבֵדָה מִדַּי לְאָדָם אֶחָד"],0,"מוֹזְגִים לוֹ דֶּרֶךְ חֵרוּת, כְּמוֹ לְמֶלֶךְ. בְּכוֹס זוֹ מְכַוְּנִים לְמִצְוַת קִדּוּשׁ וּלְמִצְוַת אַרְבַּע כּוֹסוֹת.","פֶּרֶק ס״ד, הֲלָכָה ג׳","סִימָנֵי הַסֵּדֶר"],["מָה נָכוֹן בַּקִּדּוּשׁ שֶׁל לֵיל הַסֵּדֶר?",["״שֶׁהֶחֱיָנוּ״ רַק עַל הַיַּיִן, וְשׁוֹתִים בַּעֲמִידָה","״שֶׁהֶחֱיָנוּ״ עַל הַבֶּגֶד, וּמְבָרְכִים בְּרָכָה אַחֲרוֹנָה","לֹא אוֹמְרִים ״שֶׁהֶחֱיָנוּ״, וְשׁוֹתִים בְּלִי הֲסָבָה","״שֶׁהֶחֱיָנוּ״ פּוֹטֶרֶת אֶת הַמַּצָּה, וְשׁוֹתִים בַּהֲסָבָה"],3,"״שֶׁהֶחֱיָנוּ״ הִיא עַל הֶחָג, וּמְכַוְּנִים לִפְטֹר בָּהּ גַּם אֶת הַמַּצָּה וּשְׁאַר הַמִּצְווֹת. שׁוֹתִים בַּהֲסָבָה וְאֵין מְבָרְכִים בְּרָכָה אַחֲרוֹנָה.","פֶּרֶק ס״ד, הֲלָכוֹת ד׳-ה׳","סִימָנֵי הַסֵּדֶר"],["מָה עוֹשִׂים כְּשֶׁאוֹמְרִים ״הָא לַחְמָא עַנְיָא״?",["מַגְבִּיהִים אֶת הַקְּעָרָה וּמְגַלִּים אֶת הַמַּצּוֹת","מַנִּיחִים אֶת הַקְּעָרָה וּמְכַסִּים אֶת הַמַּצּוֹת","אוֹכְלִים מִן הַמַּצָּה הָעֶלְיוֹנָה בַּהֲסָבָה","שׁוֹתִים אֶת הַכּוֹס הַשְּׁנִיָּה בִּשְׁתִיקָה"],0,"מַגְבִּיהִים אֶת הַקְּעָרָה, מְגַלִּים אֶת הַמַּצּוֹת וְאוֹמְרִים בַּאֲרָמִית ״הָא לַחְמָא עַנְיָא״. יֵשׁ לְהַסְבִּיר לִבְנֵי הַבַּיִת בְּשָׂפָה הַמּוּבֶנֶת לָהֶם.","פֶּרֶק ס״ד, הֲלָכָה י״ב","סִימָנֵי הַסֵּדֶר"],["לָמָּה נוֹטְלִים יָדַיִם לִפְנֵי אֲכִילַת הַכַּרְפַּס?",["כִּי הַכַּרְפַּס הוּא לֶחֶם לְכָל דָּבָר","כִּי הַיָּדַיִם מְלֻכְלָכוֹת מֵהַיַּיִן שֶׁל הַקִּדּוּשׁ","כִּי מַטְבִּילִים אוֹתוֹ בְּמַשְׁקֶה לִפְנֵי הָאֲכִילָה","כִּי כָּךְ נוֹטְלִים לִפְנֵי כָּל פְּרִי"],2,"לִפְנֵי אֲכִילַת דָּבָר שֶׁמַּטְבִּילִים בְּמַשְׁקֶה צָרִיךְ לִטֹּל יָדַיִם. בְּלֵיל הַסֵּדֶר נָהֲגוּ בָּזֶה כֻּלָּם, גַּם מִי שֶׁמֵּקֵל בִּשְׁאָר הַשָּׁנָה.","פֶּרֶק ס״ד, הֲלָכָה ו׳","סִימָנֵי הַסֵּדֶר"],["בַּבַּיִת שֶׁל יוֹסִי אוֹכְלִים בְּ״כַּרְפַּס״ תַּפּוּחַ אֲדָמָה. הַאִם זֶה בְּסֵדֶר?",["כֵּן, הַמַּטָּרָה הִיא שֶׁהַיְּלָדִים יִשְׁאֲלוּ","לֹא, חַיָּבִים לֶאֱכֹל רַק סֶלֶרִי","לֹא, צָרִיךְ לֶאֱכֹל כַּזַּיִת שָׁלֵם מִסֶּלֶרִי","כֵּן, אֲבָל רַק אִם מְבָרְכִים ״הַמּוֹצִיא״"],0,"אוֹכְלִים פָּחוֹת מִכַּזַּיִת וּמְבָרְכִים ״הָאֲדָמָה״. הַכַּרְפַּס בָּא לְעוֹרֵר שְׁאֵלָה, וְאֵינוֹ מִצְוָה בִּפְנֵי עַצְמָהּ, וְלָכֵן רַבִּים אוֹכְלִים יְרָקוֹת אֲחֵרִים.","פֶּרֶק ס״ד, הֲלָכוֹת ז׳-ח׳","סִימָנֵי הַסֵּדֶר"],["מָה נָכוֹן בַּאֲכִילַת הַכַּרְפַּס?",["צָרִיךְ לְהָסֵב, וְהַבְּרָכָה אֵינָהּ פּוֹטֶרֶת דָּבָר","אֵין צָרִיךְ לְהָסֵב, וְהַבְּרָכָה פּוֹטֶרֶת אֶת הַמָּרוֹר","צָרִיךְ לְהָסֵב, וְהַבְּרָכָה פּוֹטֶרֶת גַּם אֶת הַמַּצָּה","אֵין צָרִיךְ לְהָסֵב, וּמְבָרְכִים שׁוּב עַל הַמָּרוֹר"],1,"בְּבִרְכַּת ״בּוֹרֵא פְּרִי הָאֲדָמָה״ מִתְכַּוְּנִים לִפְטֹר גַּם אֶת הַמָּרוֹר, וְאֵין צָרִיךְ לְהָסֵב בִּזְמַן אֲכִילַת הַכַּרְפַּס.","פֶּרֶק ס״ד, הֲלָכוֹת ט׳-י׳","סִימָנֵי הַסֵּדֶר"],["לָמָּה חוֹצִים אֶת הַמַּצָּה לִפְנֵי אֲמִירַת הַהַגָּדָה?",["כְּדֵי שֶׁיִּהְיֶה קַל יוֹתֵר לֶאֱכֹל אֶת הַמַּצָּה","כְּדֵי לְחַלֵּק לְכָל אֶחָד חֲתִיכָה לִפְנֵי הַסְּעוּדָה","כְּדֵי שֶׁהַמַּצָּה הָאֶמְצָעִית לֹא תִּשָּׁבֵר בְּסוֹף הַסֵּדֶר","כְּדֵי שֶׁ״הָא לַחְמָא עַנְיָא״ תֵּאָמֵר עַל מַצָּה פְּרוּסָה"],3,"חוֹצִים לִפְנֵי הַהַגָּדָה כְּדֵי שֶׁ״הָא לַחְמָא עַנְיָא״ תִּהְיֶה עַל מַצָּה פְּרוּסָה, כְּדַרְכּוֹ שֶׁל עָנִי. הַחֵלֶק הַגָּדוֹל נִשְׁמָר לָאֲפִיקוֹמָן.","פֶּרֶק ס״ד, הֲלָכָה י״א","סִימָנֵי הַסֵּדֶר"],["לָמָּה מוֹזְגִים כּוֹס שְׁנִיָּה כְּבָר בִּתְחִלַּת הַ״מַּגִּיד״?",["כְּדֵי לִשְׁתּוֹת אוֹתָהּ מִיָּד אַחֲרֵי הַקִּדּוּשׁ","כִּי כָּךְ עוֹשִׂים בְּכָל שַׁבָּת וְחַג","כְּדֵי שֶׁהַיְּלָדִים יִשְׁאֲלוּ וְיַגִּיעוּ לְ״מַה נִּשְׁתַּנָּה״","כְּדֵי שֶׁהַיַּיִן יִתְקָרֵר לִפְנֵי הַסְּעוּדָה"],2,"שׁוֹתִים אוֹתָהּ רַק בְּסוֹף הַ״מַּגִּיד״, אֲבָל מוֹזְגִים בַּתְּחִלָּה כְּדֵי שֶׁהַיְּלָדִים יִשְׁאֲלוּ לָמָּה שׁוֹתִים כּוֹס שְׁנִיָּה לִפְנֵי הַסְּעוּדָה, שֶׁלֹּא כְּמוֹ בְּשַׁבָּת וּבְחַגִּים אֲחֵרִים.","פֶּרֶק ס״ד, הֲלָכָה י״ג","סִימָנֵי הַסֵּדֶר"],["מַהִי הַסִּבָּה לְכָל הַשִּׁנּוּיִים שֶׁעוֹשִׂים בְּלֵיל הַסֵּדֶר?",["כְּדֵי שֶׁהַיְּלָדִים יִשָּׁאֲרוּ עֵרִים עַד סוֹף הַסֵּדֶר","כִּי עֲבָדִים הָיִינוּ וּבַלַּיְלָה הַזֶּה יָצָאנוּ","כִּי כָּךְ נָהֲגוּ הַמִּצְרִים בְּכָל לַיְלָה וְלַיְלָה","כְּדֵי לְהַרְאוֹת שֶׁהַשֻּׁלְחָן שֶׁלָּנוּ מְכֻבָּד וְיָפֶה"],1,"הַתְּשׁוּבָה לְ״מַה נִּשְׁתַּנָּה״ הִיא ״עֲבָדִים הָיִינוּ לְפַרְעֹה בְּמִצְרַיִם״, וּבְלַיְלָה זֶה יָצָאנוּ מִשָּׁם.","פֶּרֶק ס״ד, הֲלָכָה י״ד","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מַדּוּעַ מְכַסִּים אֶת הַמַּצּוֹת כְּשֶׁמַּגְבִּיהִים אֶת הַכּוֹס?",["כְּדֵי שֶׁהַמַּצּוֹת לֹא יִתְיַבְּשׁוּ בְּמֶשֶׁךְ הַהַגָּדָה","כְּדֵי שֶׁהַיְּלָדִים לֹא יֹאכְלוּ מֵהֶן לִפְנֵי הַזְּמַן הַנָּכוֹן","מִפְּנֵי בֹּשֶׁת הַפַּת, שֶׁהָיָה רָאוּי לְבָרֵךְ עֲלֵיהֶן קֹדֶם","כִּי אָסוּר לִרְאוֹת מַצָּה בִּזְמַן אֲמִירַת הַהַגָּדָה"],2,"הָיָה רָאוּי לְכַבֵּד אֶת הַמַּצּוֹת וּלְבָרֵךְ עֲלֵיהֶן לִפְנֵי הַיַּיִן; מִכֵּיוָן שֶׁלֹּא עוֹשִׂים כָּךְ, מְכַסִּים אוֹתָן – לְמָשָׁל בְּ״וְהִיא שֶׁעָמְדָה״ וּבִ״לְפִיכָךְ״.","פֶּרֶק ס״ד, הֲלָכָה ט״ו","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["לְפִי מִנְהַג הַסְּפָרַדִּים, כַּמָּה פְּעָמִים שׁוֹפְכִים מְעַט יַיִן מִן הַכּוֹס?",["שֵׁשׁ עֶשְׂרֵה פְּעָמִים בְּסַךְ הַכֹּל בְּמַהֲלַךְ הַהַגָּדָה","עֶשֶׂר פְּעָמִים בִּלְבַד, פַּעַם אַחַת לְכָל מַכָּה","שָׁלֹשׁ פְּעָמִים בִּלְבַד, בְּ״דָם וָאֵשׁ וְתִימְרוֹת עָשָׁן״","פַּעַם אַחַת בִּלְבַד, בְּסוֹף אֲמִירַת כָּל הַהַגָּדָה"],0,"שׁוֹפְכִים בְּ״דָם וָאֵשׁ וְתִימְרוֹת עָשָׁן״, בְּעֶשֶׂר הַמַּכּוֹת וּבְדְצַ״ךְ עֲדַ״שׁ בְּאַחַ״ב – שֵׁשׁ עֶשְׂרֵה פְּעָמִים. הָאַשְׁכְּנַזִּים מַטִּיפִים שֵׁשׁ עֶשְׂרֵה טִפּוֹת בְּאֶצְבַּע.","פֶּרֶק ס״ד, הֲלָכָה ט״ז","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מַדּוּעַ לֹא נוֹגְעִים בַּזְּרוֹעַ כְּשֶׁאוֹמְרִים ״פֶּסַח שֶׁהָיוּ אֲבוֹתֵינוּ אוֹכְלִים״?",["כִּי הַזְּרוֹעַ חַמָּה מְאוֹד וְעָלוּל לְהִכָּווֹת מִמֶּנָּה","כִּי הִיא שַׁיֶּכֶת רַק לְאַחַר אֲכִילַת הָאֲפִיקוֹמָן","כִּי זֶה נִרְאֶה כְּמַקְדִּישׁ אוֹתָהּ לְקָרְבַּן פֶּסַח","כִּי נוֹגְעִים בָּהּ רַק בִּזְמַן ״שֻׁלְחָן עוֹרֵךְ״"],2,"נְגִיעָה בַּזְּרוֹעַ עֲלוּלָה לְהֵרָאוֹת כְּאִלּוּ מַקְדִּישִׁים אוֹתָהּ לְקָרְבַּן פֶּסַח, לָכֵן רַק מִסְתַּכְּלִים עָלֶיהָ. אֶת הַמַּצָּה הַפְּרוּסָה וְאֶת הַמָּרוֹר מַגְבִּיהִים.","פֶּרֶק ס״ד, הֲלָכָה י״ז","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מָה עוֹשִׂים בְּסִיּוּם הַ״מַּגִּיד״?",["אוֹמְרִים אֶת כָּל הַהַלֵּל וְשׁוֹתִים אֶת הַכּוֹס הַשְּׁלִישִׁית","אוֹמְרִים שְׁנֵי מִזְמוֹרֵי הַלֵּל, מְבָרְכִים ״אֲשֶׁר גְּאָלָנוּ״ וְשׁוֹתִים","אוֹכְלִים מִיָּד אֶת הָאֲפִיקוֹמָן וּמְבָרְכִים בִּרְכַּת הַמָּזוֹן","שָׁרִים ״חַד גַּדְיָא״ וּמוֹזְגִים אֶת הַכּוֹס הַשְּׁנִיָּה"],1,"אוֹמְרִים שְׁנֵי מִזְמוֹרִים רִאשׁוֹנִים שֶׁל הַהַלֵּל, מְבָרְכִים ״אֲשֶׁר גְּאָלָנוּ״ וְשׁוֹתִים כּוֹס שְׁנִיָּה בַּהֲסָבָה. הַסְּפָרַדִּים אֵינָם מְבָרְכִים ״בּוֹרֵא פְּרִי הַגֶּפֶן״, וְהָאַשְׁכְּנַזִּים מְבָרְכִים.","פֶּרֶק ס״ד, הֲלָכָה י״ח","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מַדּוּעַ נוֹטְלִים יָדַיִם שׁוּב לִפְנֵי אֲכִילַת הַמַּצָּה?",["כִּי בִּזְמַן הַהַגָּדָה מַסִּיחִים אֶת הַדַּעַת מִנִּקְיוֹן הַיָּדַיִם","כִּי הַנְּטִילָה הָרִאשׁוֹנָה נַעַשְׂתָה רַק בְּיָד אַחַת","כִּי הַמַּיִם הָרִאשׁוֹנִים לֹא הָיוּ כְּשֵׁרִים לְפֶסַח בִּכְלָל","כִּי בְּלֵיל הַסֵּדֶר נוֹטְלִים יָדַיִם לִפְנֵי כָּל מַאֲכָל"],0,"בִּשְׁעַת קְרִיאַת הַהַגָּדָה מַסִּיחִים אֶת הַדַּעַת מִשְּׁמִירַת נִקְיוֹן הַיָּדַיִם, לָכֵן נוֹטְלִים שׁוּב, וְהַפַּעַם מְבָרְכִים ״עַל נְטִילַת יָדַיִם״.","פֶּרֶק ס״ד, הֲלָכָה י״ט","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["עַל אֵילוּ מַצּוֹת מְבָרְכִים ״עַל אֲכִילַת מַצָּה״?",["עַל הַמַּצָּה הַתַּחְתּוֹנָה בִּלְבַד, אַחֲרֵי שֶׁמַּנִּיחִים אֶת הַשְּׁאָר","עַל הָעֶלְיוֹנָה וְהַפְּרוּסָה, אַחֲרֵי שֶׁמַּנִּיחִים אֶת הַתַּחְתּוֹנָה","עַל שָׁלוֹשׁ הַמַּצּוֹת יַחַד, בְּלִי לְהַנִּיחַ אַף אַחַת","עַל הָאֲפִיקוֹמָן בִּלְבַד, שֶׁהוּא הַמַּצָּה הַחֲשׁוּבָה בְּיוֹתֵר"],1,"אַחֲרֵי ״הַמּוֹצִיא״ מַנִּיחִים אֶת הַתַּחְתּוֹנָה וּמְבָרְכִים עַל הָעֶלְיוֹנָה וְהַפְּרוּסָה, מְכַוְּנִים לַמִּצְוָה וּלְזֵכֶר הַיְּצִיאָה ״בְחִפָּזוֹן״, וְאוֹכְלִים כַּזַּיִת מִכָּל אַחַת בַּהֲסָבָה.","פֶּרֶק ס״ד, הֲלָכוֹת כ׳-כ״ב","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מַדּוּעַ מוֹסִיפִים לַמְּסֻבִּים מַצָּה מֵחֲבִילָה שֶׁעַל הַשֻּׁלְחָן?",["כִּי בְּדֶרֶךְ כְּלָל אֵין בַּמַּצּוֹת שֶׁבֵּרֵךְ כַּזַּיִת לְכֻלָּם","כִּי אָסוּר לֶאֱכֹל מִן הַמַּצּוֹת שֶׁעַל הַקְּעָרָה","כִּי הַמַּצּוֹת שֶׁבַּחֲבִילָה טְעִימוֹת יוֹתֵר וְרַכּוֹת יוֹתֵר","כִּי כָּל אֶחָד צָרִיךְ מַצָּה שֶׁלֹּא בֵּרְכוּ עָלֶיהָ"],0,"אֵין בַּמַּצּוֹת שֶׁעַל הַקְּעָרָה כַּזַּיִת לְכֻלָּם, לָכֵן נוֹתְנִים חֲתִיכָה קְטַנָּה מֵהֶן וּמוֹסִיפִים שְׁנֵי כְּזֵיתִים מֵהַחֲבִילָה. בְּשִׁעוּר כַּזַּיִת יֵשׁ דֵּעוֹת, וְכָל אֶחָד נוֹהֵג כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק ס״ד, הֲלָכוֹת כ״א-כ״ג","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["חַיָּל שֶׁהָיָה בִּפְעִילוּת מִבְצָעִית וְהִגִּיעַ אַחֲרֵי חֲצוֹת. מָה דִּינוֹ?",["פָּטוּר לְגַמְרֵי מֵאֲכִילַת מַצָּה וּמָרוֹר בַּשָּׁנָה הַזֹּאת","אוֹכֵל מַצָּה וּמְבָרֵךְ, אֲבָל אֵינוֹ אוֹכֵל מָרוֹר כְּלָל","אוֹכֵל רַק לְמָחֳרָת בַּבֹּקֶר, עִם כָּל הַבְּרָכוֹת","חַיָּב לֶאֱכֹל מַצָּה וּמָרוֹר, אַךְ בְּלִי לְבָרֵךְ עֲלֵיהֶם"],3,"גַּם אַחֲרֵי חֲצוֹת חַיָּב לֶאֱכֹל מַצָּה וּמָרוֹר, אַךְ לֹא יְבָרֵךְ ״עַל אֲכִילַת מַצָּה״ וְ״עַל אֲכִילַת מָרוֹר״. וּמֵהַבְּרָכָה עַד סוֹף הַ״כּוֹרֵךְ״ לֹא מְשׂוֹחֲחִים.","פֶּרֶק ס״ד, הֲלָכוֹת כ״ד-כ״ה","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מַדּוּעַ אוֹכְלִים אֶת הַמָּרוֹר בְּלִי הֲסָבָה?",["כִּי הַמָּרוֹר קָטָן מִדַּי וְאֵין צֹרֶךְ לְהָסֵב","כִּי מְבָרְכִים עָלָיו בִּרְכַּת ״בּוֹרֵא פְּרִי הָאֲדָמָה״","כִּי כְּבָר הֵסַבְנוּ מַסְפִּיק בַּאֲכִילַת הַמַּצָּה","כִּי הַמָּרוֹר הוּא זֵכֶר לָעַבְדוּת שֶׁל מִצְרַיִם"],3,"הֲסָבָה הִיא דֶּרֶךְ חֵרוּת, וְהַמָּרוֹר הוּא זֵכֶר לָעַבְדוּת, לָכֵן אוֹכְלִים אוֹתוֹ בְּלִי הֲסָבָה, אַחֲרֵי בִּרְכַּת ״עַל אֲכִילַת מָרוֹר״.","פֶּרֶק ס״ד, הֲלָכָה כ״ו","מַגִּיד, רָחְצָה, מוֹצִיא מַצָּה וּמָרוֹר"],["מֵאֵיזוֹ מַצָּה לוֹקְחִים לַ״כּוֹרֵךְ״, וְאֵיךְ אוֹכְלִים אוֹתוֹ?",["מֵהַמַּצָּה הָעֶלְיוֹנָה, טוֹבְלִים בְּמֶלַח וְאוֹכְלִים בַּעֲמִידָה","מֵהַמַּצָּה הַתַּחְתּוֹנָה, טוֹבְלִים בַּחֲרֹסֶת וְאוֹכְלִים בַּהֲסָבָה","מֵהָאֲפִיקוֹמָן, טוֹבְלִים בְּמֵי מֶלַח וְאוֹכְלִים בִּמְהִירוּת","מֵהַמַּצָּה הָאֶמְצָעִית, בְּלִי טְבִילָה וּבְלִי הֲסָבָה כְּלָל"],1,"נוֹטְלִים כַּזַּיִת מֵהַמַּצָּה הַתַּחְתּוֹנָה, כּוֹרְכִים עִם כַּזַּיִת מָרוֹר, טוֹבְלִים בַּחֲרֹסֶת וְאוֹכְלִים יַחַד בַּהֲסָבָה.","פֶּרֶק ס״ד, הֲלָכָה כ״ז","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מַדּוּעַ אֵין לֶאֱכֹל וְלִשְׁתּוֹת יוֹתֵר מִדַּי בִּסְעוּדַת הֶחָג?",["כְּדֵי שֶׁיִּשָּׁאֵר אֹכֶל לַיּוֹם הַשֵּׁנִי שֶׁל הֶחָג","כִּי אָסוּר לֶאֱכֹל בָּשָׂר בְּלֵיל הַסֵּדֶר","כְּדֵי שֶׁלֹּא נֹאכַל אֶת הָאֲפִיקוֹמָן בַּאֲכִילָה גַּסָּה","כְּדֵי לְהַסְפִּיק לִישֹׁן מֻקְדָּם אַחֲרֵי הַסֵּדֶר"],2,"אֲכִילָה גַּסָּה הִיא כְּשֶׁהָאוֹכֵל אֵינוֹ מִתְאַוֶּה כְּלָל לֶאֱכֹל, וְאָז לֹא מְקַיְּמִים אֶת הַמִּצְוָה בְּצוּרָה מְהֻדֶּרֶת.","פֶּרֶק ס״ד, הֲלָכָה כ״ח","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["זֵכֶר לְמָה אוֹכְלִים אֶת הָאֲפִיקוֹמָן בְּסוֹף הַסְּעוּדָה?",["זֵכֶר לַמָּן שֶׁיָּרַד לָנוּ בַּמִּדְבָּר","זֵכֶר לְעֶשֶׂר הַמַּכּוֹת שֶׁהָיוּ בְּמִצְרַיִם","זֵכֶר לִקְרִיעַת יַם סוּף בְּיַד מֹשֶׁה","זֵכֶר לְקָרְבַּן פֶּסַח שֶׁנֶּאֱכַל עַל הַשֹּׂבַע"],3,"הָאֲפִיקוֹמָן הוּא זֵכֶר לְקָרְבַּן פֶּסַח הַנֶּאֱכָל עַל הַשֹּׂבַע (וְיֵשׁ מַחְמִירִים לֶאֱכֹל שְׁנֵי כַּזֵּיתִים).","פֶּרֶק ס״ד, הֲלָכָה כ״ט","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה מֻתָּר לִשְׁתּוֹת אַחֲרֵי הָאֲפִיקוֹמָן (מִלְּבַד הַכּוֹסוֹת), וּמַדּוּעַ?",["מַיִם, כִּי אֵין בָּהֶם טַעַם","מִיץ תַּפּוּזִים, כִּי הוּא מָתוֹק וְטָעִים","חָלָב, כִּי הוּא מַשְׁקֶה בָּרִיא מְאוֹד","כָּל מַשְׁקֶה, כִּי אֵין שׁוּם הַגְבָּלָה"],0,"לֹא אוֹכְלִים כְּלוּם כְּדֵי שֶׁיִּשָּׁאֵר טַעַם הַמַּצָּה בַּפֶּה; מַיִם מֻתָּרִים כִּי אֵין בָּהֶם טַעַם.","פֶּרֶק ס״ד, הֲלָכָה ל׳","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה עוֹשִׂים עִם הַכּוֹס הַשְּׁלִישִׁית?",["אוֹמְרִים עָלֶיהָ קִדּוּשׁ וְשׁוֹתִים בַּעֲמִידָה","שׁוֹפְכִים אוֹתָהּ לַכִּיּוֹר בִּזְמַן הַמַּכּוֹת","מְבָרְכִים עָלֶיהָ בִּרְכַּת הַמָּזוֹן וְשׁוֹתִים בַּהֲסָבָה","מַשְׁאִירִים אוֹתָהּ מְלֵאָה לְאֵלִיָּהוּ הַנָּבִיא"],2,"מְבָרְכִים עַל הַכּוֹס הַשְּׁלִישִׁית בִּרְכַּת הַמָּזוֹן, אַחַר כָּךְ ״בּוֹרֵא פְּרִי הַגֶּפֶן״, וְשׁוֹתִים בַּהֲסָבָה.","פֶּרֶק ס״ד, הֲלָכָה ל״א-ל״ב","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה הַדִּין אִם שָׁכַח ״יַעֲלֶה וְיָבוֹא״ בְּבִרְכַּת הַמָּזוֹן שֶׁל הַסֵּדֶר?",["חוֹזֵר, כִּי חַיָּבִים לְהַזְכִּיר אוֹתוֹ","אֵינוֹ חוֹזֵר, כִּי זוֹ רַק תּוֹסֶפֶת","אוֹמֵר אוֹתוֹ אַחֲרֵי הַכּוֹס הָרְבִיעִית","מַשְׁלִים בַּאֲמִירַת פֶּרֶק תְּהִלִּים נוֹסָף"],0,"בְּבִרְכַּת הַמָּזוֹן יֵשׁ לְהַזְכִּיר ״יַעֲלֶה וְיָבוֹא״, וּמִי שֶׁשָּׁכַח – חוֹזֵר.","פֶּרֶק ס״ד, הֲלָכָה ל״ג","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מַדּוּעַ יֵשׁ נוֹהֲגִים לִפְתֹּחַ אֶת דֶּלֶת הַבַּיִת אַחֲרֵי הַכּוֹס הַשְּׁלִישִׁית?",["כְּדֵי לְהַכְנִיס אֲוִיר צַח לַבַּיִת","כְּדֵי לְהַזְמִין אֶת הַשְּׁכֵנִים לַסְּעוּדָה","כְּדֵי לְהוֹצִיא אֶת הֶחָמֵץ מֵהַבַּיִת","לְחִזּוּק הָאֱמוּנָה בְּגִלּוּי אֵלִיָּהוּ וּבַגְּאֻלָּה"],3,"פְּתִיחַת הַדֶּלֶת הִיא חִזּוּק הָאֱמוּנָה בְּגִלּוּי אֵלִיָּהוּ הַנָּבִיא וּבַגְּאֻלָּה הַשְּׁלֵמָה, וְאוֹמְרִים ״שְׁפֹךְ חֲמָתְךָ״ (תְּהִלִּים ע״ט, ו׳).","פֶּרֶק ס״ד, הֲלָכָה ל״ד","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["עַד מָתַי יֵשׁ לְהִשְׁתַּדֵּל לְסַיֵּם אֶת הַהַלֵּל וְהַכּוֹס הָרְבִיעִית?",["עַד שֶׁכָּל הַיְלָדִים בַּבַּיִת נִרְדָּמִים","לִפְנֵי חֲצוֹת הַלַּיְלָה, כְּפִי שֶׁכָּתוּב בַּהֲלָכָה","לִפְנֵי עֲלוֹת הַשַּׁחַר שֶׁל יוֹם הֶחָג","אֵין שׁוּם זְמַן, אֶפְשָׁר גַּם בַּבֹּקֶר"],1,"יֵשׁ לְהִשְׁתַּדֵּל לְסַיֵּם אֶת אֲמִירַת הַהַלֵּל וּשְׁתִיַּת הַכּוֹס הָרְבִיעִית לִפְנֵי חֲצוֹת הַלַּיְלָה.","פֶּרֶק ס״ד, הֲלָכָה ל״ה-ל״ו","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה נוֹהֲגִים לוֹמַר בְּסוֹף הַסֵּדֶר, אַחֲרֵי ״נִרְצָה״?",["״מָעוֹז צוּר״, ״הַנֵּרוֹת הַלָּלוּ״ וְ״עַל הַנִּסִּים״","״אֶחָד מִי יוֹדֵעַ״, ״חַד גַּדְיָא״ וְשִׁיר הַשִּׁירִים","״לְכָה דוֹדִי״, ״שָׁלוֹם עֲלֵיכֶם״ וְ״אֵשֶׁת חַיִל״","״אָבִינוּ מַלְכֵּנוּ״, ״וּנְתַנֶּה תֹּקֶף״ וְ״כָּל נִדְרֵי״"],1,"מִשְׁתַּדְּלִים לְקַיֵּם אֶת הַסֵּדֶר כְּכָל מִצְוָתוֹ וּמִתְפַּלְּלִים לַגְּאֻלָּה, וִידוּעִים הַמִּנְהָגִים לוֹמַר פִּיּוּטִים וְשִׁיר הַשִּׁירִים.","פֶּרֶק ס״ד, הֲלָכָה ל״ז-ל״ח","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָה חַיָּב אָדָם לַעֲשׂוֹת לְאַחַר סִיּוּם הַסֵּדֶר?",["לַעֲסֹק בִּיצִיאַת מִצְרַיִם עַד שֶׁתַּחְטְפֶנּוּ שֵׁינָה","לָלֶכֶת מִיָּד לִישֹׁן בְּלִי קְרִיאַת שְׁמַע","לְנַקּוֹת אֶת כָּל הַבַּיִת לִקְרַאת מָחָר","לֶאֱכֹל עוֹד כַּזַּיִת מַצָּה לִפְנֵי הַשֵּׁינָה"],0,"חַיָּב לַעֲסֹק בְּהִלְכוֹת הַפֶּסַח וּבִיצִיאַת מִצְרַיִם עַד שֶׁתַּחְטְפֶנּוּ שֵׁינָה, וְקוֹרְאִים קְרִיאַת שְׁמַע עַל הַמִּטָּה כְּבְכָל לַיְלָה.","פֶּרֶק ס״ד, הֲלָכָה ל״ט","כּוֹרֵךְ, צָפוּן, בָּרֵךְ, הַלֵּל וְנִרְצָה"],["מָתַי אוֹמֵר שְׁלִיחַ הַצִּבּוּר אֶת פִּיּוּטֵי ״תִּקּוּן הַטַּל״?",["לִפְנֵי תְּפִלַּת שַׁחֲרִית בַּיּוֹם הָאַחֲרוֹן שֶׁל פֶּסַח","אַחֲרֵי תְּפִלַּת מִנְחָה בְּלֵיל הַסֵּדֶר שֶׁל פֶּסַח","לִפְנֵי תְּפִלַּת מוּסָף בַּיּוֹם הָרִאשׁוֹן שֶׁל פֶּסַח","בִּתְפִלַּת עַרְבִית בְּמוֹצָאֵי חַג הַפֶּסַח בְּבֵית הַכְּנֶסֶת"],2,"לִפְנֵי מוּסָף בַּיּוֹם הָרִאשׁוֹן שֶׁל פֶּסַח אוֹמְרִים ״תִּקּוּן הַטַּל״, וּמִשָּׁם מַתְחִילִים ״מוֹרִיד הַטַּל״. יֵשׁ נוֹהֲגִים לוֹמַר אֶת הַפִּיּוּטִים בַּחֲזָרַת הַשַּׁ״ץ.","פֶּרֶק ס״ה, הֲלָכָה א׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מָה הַדִּין בְּ״יַעֲלֶה וְיָבוֹא״ בִּימֵי חֹל הַמּוֹעֵד?",["אוֹמְרִים רַק בִּתְפִלַּת מוּסָף שֶׁל חֹל הַמּוֹעֵד","אֵין אוֹמְרִים אוֹתוֹ כְּלָל בִּימֵי חֹל הַמּוֹעֵד","אוֹמְרִים בְּכָל הַתְּפִלּוֹת, וּמִי שֶׁשָּׁכַח אֵינוֹ חוֹזֵר","אוֹמְרִים בְּעַרְבִית, שַׁחֲרִית וּמִנְחָה, אֲבָל לֹא בְּמוּסָף"],3,"אוֹמְרִים ״יַעֲלֶה וְיָבוֹא״ בְּבִרְכַּת ״רְצֵה״ בְּעַרְבִית, שַׁחֲרִית וּמִנְחָה, וְלֹא בְּמוּסָף. מִי שֶׁטָּעָה וְלֹא אָמַר – חוֹזֵר.","פֶּרֶק ס״ה, הֲלָכָה ב׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מַדּוּעַ אֵין גּוֹמְרִים אֶת הַהַלֵּל בִּשְׁבִיעִי שֶׁל פֶּסַח?",["כִּי זֶה יוֹם קָצָר וְאֵין זְמַן לְהַאֲרִיךְ בַּתְּפִלָּה","כִּי טָבְעוּ בּוֹ הַמִּצְרִים, וּ״בִנְפֹל אוֹיִבְךָ אַל תִּשְׂמָח״","כִּי בְּיוֹם זֶה עוֹד לֹא יָצְאוּ מִמִּצְרַיִם","כִּי אוֹמְרִים אֶת הַהַלֵּל רַק בְּלֵיל הַסֵּדֶר בְּבַיִת"],1,"אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: ״מַעֲשֵׂי יָדַי טוֹבְעִים בַּיָּם וְאַתֶּם אוֹמְרִים שִׁירָה?״. וְלָכֵן גַּם בְּחֹל הַמּוֹעֵד לֹא גּוֹמְרִים, שֶׁלֹּא יִהְיֶה חָשׁוּב יוֹתֵר מֵהַיּוֹם הַשְּׁבִיעִי.","פֶּרֶק ס״ה, הֲלָכָה ג׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מָה נָכוֹן לְגַבֵּי שְׁבִיעִי שֶׁל פֶּסַח?",["הוּא יוֹם טוֹב, וְאֵין אוֹמְרִים ״שֶׁהֶחֱיָנוּ״ בַּקִּדּוּשׁ","הוּא יוֹם חֹל הַמּוֹעֵד, וְאֵין עוֹשִׂים בּוֹ קִדּוּשׁ","הוּא יוֹם טוֹב, וּמְבָרְכִים ״שֶׁהֶחֱיָנוּ״ עַל נֵס הַיָּם","הוּא יוֹם רִאשׁוֹן שֶׁל הַחַג וְאוֹכְלִים בּוֹ מָרוֹר"],0,"הַיּוֹם הַשְּׁבִיעִי וְהָאַחֲרוֹן שֶׁל פֶּסַח הוּא יוֹם טוֹב, וּבְלֵילוֹ אֵין אוֹמְרִים ״שֶׁהֶחֱיָנוּ״ בַּקִּדּוּשׁ.","פֶּרֶק ס״ה, הֲלָכוֹת ד׳-ה׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מָתַי נַעֲשָׂה נֵס קְרִיעַת יַם סוּף?",["בַּצָּהֳרַיִם שֶׁל הַיּוֹם הָרִאשׁוֹן שֶׁל חַג הַפֶּסַח","בִּשְׁעַת הַשְּׁקִיעָה, בְּסוֹף הַיּוֹם הַשְּׁבִיעִי","בְּאַשְׁמֹרֶת הַבֹּקֶר, הַחֵלֶק הַשְּׁלִישִׁי שֶׁל הַלַּיְלָה","בַּחֲצוֹת הַלַּיְלָה, מִיָּד אַחֲרֵי מַכַּת בְּכוֹרוֹת"],2,"הַנֵּס הָיָה בְּאַשְׁמֹרֶת הַבֹּקֶר, וְלָכֵן יֵשׁ שֶׁנָּהֲגוּ לָקוּם אָז וְלוֹמַר אֶת שִׁירַת הַיָּם – ״תִּקּוּן שְׁבִיעִי שֶׁל פֶּסַח״.","פֶּרֶק ס״ה, הֲלָכָה ו׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מַדּוּעַ נָהֲגוּ בַּמִּימוּנָה לְאָרֵחַ אִישׁ אֶת רֵעֵהוּ?",["כְּדֵי לְסַיֵּם אֶת כָּל הַמַּצּוֹת שֶׁנִּשְׁאֲרוּ","כְּדֵי לְהַרְבּוֹת שָׁלוֹם וְאַהֲבָה בְּעַם יִשְׂרָאֵל","כְּדֵי לְהִתְכּוֹנֵן יַחַד לְחַג הַשָּׁבוּעוֹת","כְּדֵי לִמְכֹּר זֶה לָזֶה אֶת הֶחָמֵץ"],1,"יְהוּדֵי מָרוֹקוֹ חוֹגְגִים אֶת הַמִּימוּנָה בְּמוֹצָאֵי הַפֶּסַח וּבְאִסְרוּ חַג, שָׁרִים, לוֹמְדִים עַל אֱמוּנַת יִשְׂרָאֵל וּמְאָרְחִים – לְהַרְבּוֹת שָׁלוֹם וְאַהֲבָה.","פֶּרֶק ס״ה, הֲלָכָה ז׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["כֵּיצַד מְשַׂמְּחִים אֶת הַנָּשִׁים בַּחַג?",["נוֹתְנִים לָהֶן קְלִיּוֹת, אֱגוֹזִים וּמִגְדָּנוֹת","הֵן פְּטוּרוֹת מִשִּׂמְחַת יוֹם טוֹב, וְאֵין צֹרֶךְ","מַגִּישִׁים לָהֶן הַרְבֵּה יַיִן עַד שֶׁיִּשְׂחֲקוּ","קוֹנִים לָהֶן בְּגָדִים וְתַכְשִׁיטִים נָאִים לִכְבוֹד הֶחָג"],3,"אָדָם חַיָּב לִהְיוֹת שָׂמֵחַ הוּא וְאִשְׁתּוֹ וּבָנָיו. לַנָּשִׁים קוֹנִים בְּגָדִים וְתַכְשִׁיטִים, וְלַקְּטַנִּים נוֹתְנִים מַמְתַּקִּים.","פֶּרֶק ס״ו, הֲלָכָה א׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מָה מִדַּת הַחֲסִידִים בְּעֵת שִׂמְחָתָם?",["מְשַׁבְּחִים אֶת ה׳ וּמִתְפַּלְּלִים לְעָבְדוֹ בְּלֵב שָׁלֵם","אוֹכְלִים וְשׁוֹתִים כָּל הַיּוֹם כֻּלּוֹ בְּלִי הַפְסָקָה","יוֹשְׁבִים בִּשְׁתִיקָה וְאֵינָם מְדַבְּרִים עִם אִישׁ","שׁוֹתִים יַיִן רַב כְּדֵי לִשְׂמֹחַ יוֹתֵר"],0,"הַחֲסִידִים מְשַׁבְּחִים אֶת ה׳ שֶׁשִּׂמְּחָם. וְגַם אֵין לֶאֱכֹל כָּל הַיּוֹם – ״חֶצְיוֹ לַה׳ וְחֶצְיוֹ לָכֶם״.","פֶּרֶק ס״ו, הֲלָכוֹת ב׳, ה׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מָה מִצְוָה גְּדוֹלָה לַעֲשׂוֹת לָעֲנִיִּים בַּחַג?",["לָתֵת לָהֶם צְדָקָה רַק אַחֲרֵי שֶׁיַּעֲבֹר הַחַג","לְהַשְׁאִיר לָהֶם אֶת שְׁאֵרִיּוֹת הַסְּעוּדָה","לְהַזְמִינָם לִסְעֹד עִמּוֹ בְּבֵיתוֹ בִּסְעוּדַת הַחַג","לְבַקֵּשׁ מֵהֶם לְהִתְפַּלֵּל עֲבוּרוֹ בְּבֵית הַכְּנֶסֶת"],2,"צָרִיךְ לִדְאֹג לַיָּתוֹם, לָאַלְמָנָה וְלָעֲנִיִּים, וּמִצְוָה גְּדוֹלָה לְהַזְמִינָם. בַּסְּעוּדָה מְבָרְכִים עַל שְׁתֵּי כִּכָּרוֹת וְשׁוֹתִים יַיִן, וְלֹא נָהֲגוּ סְעוּדָה שְׁלִישִׁית בְּיוֹם טוֹב שֶׁאֵינוֹ בְּשַׁבָּת.","פֶּרֶק ס״ו, הֲלָכוֹת ג׳-ד׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["מָה נָכוֹן לְגַבֵּי יוֹם טוֹב?",["בִּגְדֵי הַחַג יִהְיוּ פְּשׁוּטִים יוֹתֵר מִבִּגְדֵי שַׁבָּת","אָסוּר לְהַרְבּוֹת בּוֹ בְּדִבּוּר שֶׁל חֹל, כְּמוֹ בְּשַׁבָּת","מֻתָּר לְדַבֵּר בּוֹ עַל עִסְקֵי כֶּסֶף וּמִסְחָר","לוֹבְשִׁים בּוֹ בִּגְדֵי חֹל כְּדֵי לֹא לְהִתְגָּאוֹת"],1,"אָסוּר לְהַרְבּוֹת בְּדִבּוּר חֹל, וְקַל וָחֹמֶר שִׂיחַת מַשָּׂא וּמַתָּן. וּבִגְדֵי הַחַג יִהְיוּ טוֹבִים יוֹתֵר מִבִּגְדֵי הַשַּׁבָּת.","פֶּרֶק ס״ו, הֲלָכוֹת ו׳-ז׳","שְׁבִיעִי שֶׁל פֶּסַח וְשִׂמְחַת יוֹם טוֹב"],["בְּכַמָּה יָמִים טוֹבִים בַּשָּׁנָה אָסְרָה הַתּוֹרָה מְלֶאכֶת עֲבוֹדָה?",["חֲמִשָּׁה יָמִים, כִּי רֹאשׁ הַשָּׁנָה אֵינוֹ בִּכְלָל","שִׁבְעָה יָמִים, כִּי כָּל יְמֵי הַפֶּסַח נִכְלָלִים","שְׁמוֹנָה יָמִים, כִּי כָּל יְמֵי סֻכּוֹת נִכְלָלִים","שִׁשָּׁה יָמִים, וּמְלָאכָה לְצֹרֶךְ אֲכִילָה מֻתֶּרֶת בָּהֶם"],3,"שִׁשָּׁה יָמִים: רִאשׁוֹן וּשְׁבִיעִי שֶׁל פֶּסַח, שָׁבוּעוֹת, רֹאשׁ הַשָּׁנָה (וּמִדִּבְרֵי חֲכָמִים גַּם יוֹם ב׳), רִאשׁוֹן שֶׁל סֻכּוֹת וּשְׁמִינִי עֲצֶרֶת. מְלָאכָה לְצֹרֶךְ אֲכִילָה מֻתֶּרֶת, שֶׁנֶּאֱמַר ״אַךְ אֲשֶׁר יֵאָכֵל לְכָל נֶפֶשׁ״.","פֶּרֶק ס״ז, הֲלָכָה א׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["מָה הַהֶבְדֵּל בֵּין שַׁבָּת לְיוֹם טוֹב בְּעִנְיַן הַמְּלָאכוֹת?",["בְּיוֹם טוֹב מֻתָּרוֹת כָּל הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת","בְּיוֹם טוֹב מֻתָּר אֹכֶל נֶפֶשׁ, הוֹצָאָה וְהַבְעָרַת אֵשׁ","אֵין שׁוּם הֶבְדֵּל, הַכֹּל אָסוּר בְּדִיּוּק כְּמוֹ בְּשַׁבָּת","בְּיוֹם טוֹב מֻתָּרִים רַק כְּתִיבָה וְצִיּוּר לְשִׂמְחָה"],1,"כָּל הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת אֲסוּרוֹת גַּם בְּיוֹם טוֹב, חוּץ מִמְּלֶאכֶת אֹכֶל נֶפֶשׁ, וְכֵן מֻתָּר לְהוֹצִיא מֵרְשׁוּת לִרְשׁוּת וּלְהַבְעִיר אֵשׁ (בִּתְנָאִים).","פֶּרֶק ס״ז, הֲלָכָה ב׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["מַדּוּעַ אָסוּר לְהַצִּית גַּפְרוּר חָדָשׁ בְּיוֹם טוֹב?",["כִּי אֶפְשָׁר לְהָכִין אֵשׁ מֵעֶרֶב יוֹם טוֹב","כִּי גַּפְרוּרִים יְקָרִים וְחָבָל לְבַזְבֵּז אוֹתָם","כִּי אֵשׁ אֲסוּרָה לְגַמְרֵי בְּכָל יוֹם טוֹב","כִּי רַק מְבֻגָּרִים רַשָּׁאִים לְהַדְלִיק אֵשׁ בְּחַג"],0,"אָסוּר לְהַדְלִיק אֵשׁ חֲדָשָׁה, כִּי אֶפְשָׁר לְהָכִין אוֹתָהּ כְּבָר בְּעֶרֶב יוֹם טוֹב, וְכִי אָסוּר לְהוֹלִיד דָּבָר חָדָשׁ בְּיוֹם טוֹב. לָכֵן מַשְׁאִירִים נֵר דּוֹלֵק וּמַעֲבִירִים מִמֶּנּוּ אֵשׁ.","פֶּרֶק ס״ז, הֲלָכָה ג׳-ד׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["אֵיזֶה מִן הַמַּעֲשִׂים הַבָּאִים מֻתָּר בְּיוֹם טוֹב?",["לְהַדְלִיק אֶת הָאוֹר הַחַשְׁמַלִּי בַּסָּלוֹן לִכְבוֹד הֶחָג","לְכַבּוֹת אֶת הָאֵשׁ שֶׁהִבְעִירוּ לְצֹרֶךְ בִּשּׁוּל","לְהַנִּיחַ גַּפְרוּר בַּעֲדִינוּת כְּדֵי שֶׁיִּכְבֶּה מֵעַצְמוֹ","לִזְרֹק גַּפְרוּר דּוֹלֵק אַחֲרֵי שֶׁהִשְׁתַּמְּשׁוּ בּוֹ"],2,"אָסוּר לְכַבּוֹת אֵשׁ בְּיוֹם טוֹב, גַּם אִם הִבְעִירוּ אוֹתָהּ לְצֹרֶךְ אֲכִילָה, וְלָכֵן מַנִּיחִים אֶת הַגַּפְרוּר בַּעֲדִינוּת. וְכֵן אָסוּר לְהַדְלִיק תְּאוּרַת חַשְׁמַל אוֹ מַכְשִׁירִים חַשְׁמַלִּיִּים.","פֶּרֶק ס״ז, הֲלָכָה ה׳, י׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["אֵיךְ מֻתָּר לְהַדְלִיק כִּירַיִם שֶׁל גָּז בְּיוֹם טוֹב?",["בְּעֶזְרַת מַצָּת חַשְׁמַלִּי שֶׁנִּמְצָא בַּכִּירַיִם","בְּעֶזְרַת מַצִּית קָטָן שֶׁל כִּיס","בְּעֶזְרַת גַּפְרוּר חָדָשׁ שֶׁמַּצִּיתִים מֵהַקֻּפְסָה","בְּגַפְרוּר שֶׁהֻצַּת מִנֵּר שֶׁדָּלַק מֵעֶרֶב יוֹם טוֹב"],3,"אָסוּר לְהַדְלִיק אֶת כִּירֵי הַגָּז בְּמַצִּית אוֹ בְּמַצָּת חַשְׁמַלִּי, אֲבָל מֻתָּר בְּגַפְרוּר שֶׁהֻצַּת מִנֵּר שֶׁדָּלַק מֵעֶרֶב יוֹם טוֹב.","פֶּרֶק ס״ז, הֲלָכָה ו׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["הָאֵשׁ חֲזָקָה וְהַתַּבְשִׁיל עָלוּל לְהִשָּׂרֵף. מָה עוֹשִׂים קֹדֶם?",["מַנְמִיכִים מִיָּד אֶת הָאֵשׁ, בְּלִי לְחַפֵּשׂ פִּתְרוֹן אַחֵר","מַעֲבִירִים אֶת הַסִּיר לְלֶהָבָה חַלָּשָׁה יוֹתֵר","מְכַבִּים אֶת הָאֵשׁ וּמַדְלִיקִים אוֹתָהּ שׁוּב","מַשְׁאִירִים, כִּי אָסוּר לָגַעַת בַּסִּיר בְּיוֹם טוֹב"],1,"קֹדֶם מַעֲבִירִים אֶת הַסִּיר לְלֶהָבָה חַלָּשָׁה יוֹתֵר. רַק בִּשְׁעַת הַדְּחָק, כְּשֶׁאֵין אֶפְשָׁרוּת כָּזוֹ, מֻתָּר לְהַנְמִיךְ אֶת הָאֵשׁ.","פֶּרֶק ס״ז, הֲלָכָה ז׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["אֵין בַּבַּיִת שָׁעוֹן לְכִבּוּי גָּז, וְיֵשׁ צֹרֶךְ גָּדוֹל לְכַבּוֹת. מָה מֻתָּר?",["לְסוֹבֵב אֶת בֶּרֶז הַגָּז בְּסוֹף הַבִּשּׁוּל","לִשְׁפֹּךְ כּוֹס מַיִם יְשִׁירוֹת עַל הָאֵשׁ","סִיר מָלֵא מַיִם שֶׁיִּגְלְשׁוּ, וּמִשְׁתַּמְּשִׁים בַּמַּיִם לְתֵה","לְהַשְׁאִיר אֶת הָאֵשׁ דּוֹלֶקֶת עַד צֵאת הֶחָג"],2,"אָסוּר לְכַבּוֹת בְּסִבּוּב הַבֶּרֶז; לַמְּהַדְּרִין יֵשׁ שָׁעוֹן לְכִבּוּי גָּז. כְּשֶׁאֵין שָׁעוֹן וְיֵשׁ צֹרֶךְ גָּדוֹל, מַנִּיחִים סִיר מָלֵא מַיִם עַד הַקָּצֶה, הַמַּיִם גּוֹלְשִׁים וּמְכַבִּים, וּמִשְׁתַּמְּשִׁים בַּמַּיִם לְתֵה אוֹ קָפֶה כְּדֵי שֶׁהַבִּשּׁוּל לֹא יִהְיֶה שֶׁלֹּא לְצֹרֶךְ.","פֶּרֶק ס״ז, הֲלָכָה ח׳-ט׳","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["הַאִם מֻתָּר לְבַשֵּׁל בְּיוֹם טוֹב לְצֹרֶךְ יוֹם הַמָּחֳרָת?",["לֹא, וּלְשַׁבָּת רַק אִם עָשׂוּ עֵרוּב תַּבְשִׁילִין","כֵּן, בִּתְנַאי שֶׁמְּבַשְּׁלִים רַק בְּלֵיל יוֹם טוֹב","כֵּן, בֵּין שְׁנֵי יְמֵי רֹאשׁ הַשָּׁנָה מֻתָּר","לֹא, וַאֲפִלּוּ לְשַׁבָּת אֵין שׁוּם הֶתֵּר"],0,"אָסוּר לְבַשֵּׁל בְּיוֹם טוֹב לְצֹרֶךְ יוֹם הַמָּחֳרָת, אֲפִלּוּ מִיּוֹם רִאשׁוֹן שֶׁל רֹאשׁ הַשָּׁנָה לַשֵּׁנִי. מִיּוֹם טוֹב שֶׁחָל בְּשִׁשִּׁי מֻתָּר לְבַשֵּׁל לְשַׁבָּת רַק אִם עָשׂוּ עֵרוּב תַּבְשִׁילִין.","פֶּרֶק ס״ז, הֲלָכָה י״א-י״ב","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["אֵיזֶה מִשְׁפָּט נָכוֹן עַל מְלָאכוֹת הָאֹכֶל בְּיוֹם טוֹב?",["מֻתָּר לִקְצֹר וְלִבְצֹר, כִּי הֵן מְלָאכוֹת אֹכֶל נֶפֶשׁ","מֻתָּר לַחְתֹּךְ סָלָט דַּק, אֲבָל רַק לְצֹרֶךְ אוֹתוֹ יוֹם","מְגָרְדִים גְּבִינָה תָּמִיד בְּלִי שִׁנּוּי, גַּם בְּלִי סִבָּה","יְרָקוֹת חוֹתְכִים רַק בְּשִׁנּוּי, וּגְבִינָה אָסוּר לְגָרֵד"],1,"מֻתָּר לַחְתֹּךְ יְרָקוֹת דַּק דַּק בְּלִי שִׁנּוּי, רַק לְצֹרֶךְ אוֹתוֹ יוֹם. גְּבִינָה מְגָרְדִים בְּשִׁנּוּי קַל, וְאִם הַשִּׁנּוּי פּוֹגֵם בַּטַּעַם – גַּם בְּלִי שִׁנּוּי. קְצִירָה, טְחִינָה, בְּצִירָה וּסְחִיטָה נֶאֶסְרוּ, כִּי יִטְרְחוּ הַרְבֵּה וְיִמָּנְעוּ מִשִּׂמְחַת יוֹם טוֹב.","פֶּרֶק ס״ז, הֲלָכָה י״ג-י״ד","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["מָה נָכוֹן לְגַבֵּי שְׁחִיטָה וְהוֹצָאָה בְּיוֹם טוֹב?",["נוֹהֲגִים לִשְׁחֹט עוֹפוֹת, וְהוֹצָאָה אֲסוּרָה בְּלִי עֵרוּב","שְׁחִיטָה אֲסוּרָה מִן הַתּוֹרָה, וְהוֹצָאָה מֻתֶּרֶת","שְׁנֵיהֶם מֻתָּרִים לְגַמְרֵי, וְכָךְ נוֹהֲגִים בְּכָל מָקוֹם","נִמְנָעִים מִשְּׁחִיטָה, וּמֻתָּר לְהוֹצִיא גַּם בְּלִי עֵרוּב"],3,"מֵעִקַּר הַדִּין מֻתָּר לִשְׁחֹט בְּיוֹם טוֹב, אֲבָל פָּשַׁט הַמִּנְהָג בְּכָל קְהִלּוֹת יִשְׂרָאֵל לְהִמָּנַע, אֲפִלּוּ מִשְּׁחִיטַת עוֹפוֹת. הוֹצָאָה מֵרְשׁוּת לִרְשׁוּת מֻתֶּרֶת גַּם בְּלִי עֵרוּב, כְּדֵי לְהַרְבּוֹת שִׂמְחַת יוֹם טוֹב.","פֶּרֶק ס״ז, הֲלָכָה ט״ו-ט״ז","אִסּוּר מְלָאכָה בְּיָמִים טוֹבִים"],["מִי חַיָּב לִשְׂמֹחַ בִּימֵי חֹל הַמּוֹעֵד?",["רַק הָאָב, וּשְׁאָר בְּנֵי הַבַּיִת פְּטוּרִים מִשִּׂמְחָה","הָאָדָם, אִשְׁתּוֹ, בָּנָיו, בְּנוֹתָיו וְכָל הַנִּלְוִים אֵלָיו","רַק הַיְּלָדִים הַקְּטַנִּים שֶׁאֵינָם הוֹלְכִים לַעֲבוֹדָה","רַק מִי שֶׁאֵינוֹ עוֹבֵד בִּימֵי חֹל הַמּוֹעֵד"],1,"חַיָּב כָּל אָדָם לִהְיוֹת שָׂמֵחַ, הוּא, בָּנָיו, אִשְׁתּוֹ, בְּנֵי בֵּיתוֹ וְכָל הַנִּלְוִים אֵלָיו, שֶׁנֶּאֱמַר: ״וְשָׂמַחְתָּ בְּחַגֶּךָ אַתָּה וּבִנְךָ וּבִתֶּךָ״.","פֶּרֶק ס״ח, הֲלָכָה א׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["כַּמָּה סְעוּדוֹת עַל הַפַּת מִצְוָה לִקְבֹּעַ בְּכָל יוֹם שֶׁל חֹל הַמּוֹעֵד?",["שָׁלוֹשׁ סְעוּדוֹת, בְּדִיּוּק כְּמוֹ בְּשַׁבָּת קֹדֶשׁ","סְעוּדָה אַחַת בַּבֹּקֶר בִּלְבַד, וְלֹא יוֹתֵר","אֵין שׁוּם מִצְוָה, כִּי אֵלֶּה יְמֵי חֹל","אַחַת בַּלַּיְלָה וְאַחַת בַּיּוֹם, וְטוֹב לִשְׁתּוֹת יַיִן"],3,"מִצְוָה לִקְבֹּעַ בִּימֵי חֹל הַמּוֹעֵד סְעוּדָה עַל הַפַּת, אַחַת בַּלַּיְלָה וְאַחַת בַּיּוֹם, וְטוֹב לִשְׁתּוֹת יַיִן בִּסְעוּדוֹת הַמּוֹעֵד.","פֶּרֶק ס״ח, הֲלָכָה ב׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["מָה אוֹמֵר הַקָּבָּ״ה כְּשֶׁאֵין מִתְאַסְּפִים לַעֲסֹק בַּתּוֹרָה בַּמּוֹעֲדוֹת?",["אֵלּוּ אֵינָם מוֹעֲדַי אֶלָּא מוֹעֲדֵיכֶם","אֵין זֶה מְשַׁנֶּה, הַמּוֹעֵד נִשְׁאָר כְּרָגִיל","הַמּוֹעֲדִים מִתְבַּטְּלִים וְאֵין צֹרֶךְ לַחְגֹּג אוֹתָם","אֵלֶּה הֵם מוֹעֲדַי, גַּם בְּלִי לִמּוּד"],0,"כְּשֶׁמִּתְאַסְּפִים בְּבָתֵּי כְּנֵסִיּוֹת לַעֲסֹק בַּתּוֹרָה אוֹמֵר הַקָּבָּ״ה: ״אֵלֶּה הֵם מוֹעֲדָי״, וְאִם לָאו – ״אֵלּוּ אֵינָם מוֹעֲדַי אֶלָּא מוֹעֲדֵיכֶם״.","פֶּרֶק ס״ח, הֲלָכָה ג׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["מַדּוּעַ בְּחֹל הַמּוֹעֵד חֵלֶק מֵהַמְּלָאכוֹת אֲסוּרוֹת וְחֵלֶק מֻתָּרוֹת?",["כִּי כָּל אֶחָד בּוֹחֵר לְבַד מָה נוֹחַ לוֹ","כִּי בַּבֹּקֶר אָסוּר לַעֲבֹד וּבָעֶרֶב מֻתָּר לַעֲבֹד","כִּי הַיָּמִים הָאֵלֶּה הֵם גַּם חֹל וְגַם מוֹעֵד","כִּי רַק מְלָאכוֹת קָשׁוֹת אֲסוּרוֹת, וְקַלּוֹת מֻתָּרוֹת תָּמִיד"],2,"יְמֵי חֹל הַמּוֹעֵד הֵם גַּם ״חֹל״ וְגַם ״מוֹעֵד״, וְלָכֵן נֶאֶסְרָה בָּהֶם רַק עֲשִׂיַּת חֵלֶק מֵהַמְּלָאכוֹת.","פֶּרֶק ס״ח, הֲלָכָה ד׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["פּוֹעֵל שֶׁבְּלִי עֲבוֹדָתוֹ לֹא יִהְיֶה לוֹ כֶּסֶף לִקְנוֹת אֹכֶל. מָה דִּינוֹ?",["אָסוּר לוֹ לַעֲבֹד, כִּי זֶה חֹל הַמּוֹעֵד","מֻתָּר לוֹ לַעֲבֹד כְּדֵי שֶׁיִּהְיֶה לוֹ אֹכֶל","יָכוֹל לַעֲבֹד רַק אִם הוּא בַּעַל מִקְצוֹעַ","יַעֲבֹד רַק אַחֲרֵי שֶׁיִּגָּמֵר הַחַג כֻּלּוֹ"],1,"״פּוֹעֵל שֶׁאֵין לוֹ מָה לֶאֱכֹל״ – מְלָאכָה שֶׁהִיא לְצֹרֶךְ פַּרְנָסָתוֹ וּבִלְעָדֶיהָ לֹא יִהְיֶה לוֹ כֶּסֶף לְאֹכֶל, מֻתָּר לַעֲשׂוֹתָהּ.","פֶּרֶק ס״ח, הֲלָכָה ה׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["מָה מֻתָּר לְכַבֵּס בְּחֹל הַמּוֹעֵד כְּשֶׁזְּקוּקִים לָהֶם?",["רַק בִּגְדֵי שַׁבָּת שֶׁל מְבֻגָּרִים בִּלְבַד","כָּל הַבְּגָדִים, גַּם אִם יֵשׁ הַרְבֵּה נְקִיִּים","שׁוּם דָּבָר, הַכְּבִיסָה אֲסוּרָה לְגַמְרֵי בְּלִי יוֹצֵא","מַגָּבוֹת, גַּרְבַּיִם וּבִגְדֵי יְלָדִים קְטַנִּים שֶׁמִּתְלַכְלְכִים הַרְבֵּה"],3,"מֻתָּר לְכַבֵּס בְּגָדִים שֶׁמִּתְלַכְלְכִים הַרְבֵּה כְּמוֹ מַגָּבוֹת, גַּרְבַּיִם וּבִגְדֵי יְלָדִים קְטַנִּים, וְכֵן מִי שֶׁאֵין לוֹ בְּגָדִים נְקִיִּים.","פֶּרֶק ס״ח, הֲלָכָה ז׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["דָּנִי רוֹצֶה לְגַהֵץ חֻלְצָה בְּחֹל הַמּוֹעֵד. מָה הַדִּין?",["אָסוּר, כִּי גִּהוּץ הוּא כְּמוֹ כִּבּוּס","מֻתָּר לְגַהֵץ בְּגָדִים בְּחֹל הַמּוֹעֵד","מֻתָּר רַק אִם הַחֻלְצָה שַׁיֶּכֶת לְיֶלֶד קָטָן","אָסוּר, אֶלָּא אִם כֵּן הוּא בַּעַל מִקְצוֹעַ"],1,"מֻתָּר לְגַהֵץ בְּגָדִים בְּחֹל הַמּוֹעֵד.","פֶּרֶק ס״ח, הֲלָכָה ח׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["לָמָּה אָסְרוּ חֲכָמִים לְכַבֵּס וּלְהִסְתַּפֵּר בְּחֹל הַמּוֹעֵד?",["כִּי הַמַּיִם וְהַמִּסְפָּרוֹת סְגוּרִים בְּכָל יְמֵי הַחַג","כִּי אֵלֶּה מְלָאכוֹת קָשׁוֹת מְאוֹד שֶׁמְּעַיְּפוֹת אֶת הָאָדָם","שֶׁלֹּא יִדְחוּ לַמּוֹעֵד וְיִכָּנְסוּ אֵלָיו מְלֻכְלָכִים וּמְגֻדְּלֵי שֵׂעָר","כִּי צָרִיךְ לַחְסֹךְ כֶּסֶף לִסְעוּדוֹת הַחַג"],2,"חֲכָמִים חָשְׁשׁוּ שֶׁאֲנָשִׁים יִדְחוּ אֶת הַכִּבּוּס וְהַתִּסְפֹּרֶת לְחֹל הַמּוֹעֵד שֶׁבּוֹ הֵם פְּנוּיִים, וִיבַזּוּ אֶת הַמּוֹעֵד בְּכָךְ שֶׁיִּכָּנְסוּ אֵלָיו מְלֻכְלָכִים וּמְגֻדְּלֵי שֵׂעָר.","פֶּרֶק ס״ח, הֲלָכָה ט׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["לְפִי מִנְהַג רֹב קְהִלּוֹת הַסְּפָרַדִּים, מָה עוֹשִׂים בְּצִפָּרְנַיִם בְּחֹל הַמּוֹעֵד?",["אָסוּר לִגְזֹז אוֹתָן עַד אַחֲרֵי הַחַג","גּוֹזְזִים רַק אֵצֶל בַּעַל מִקְצוֹעַ מֻסְמָךְ","גּוֹזְזִים רַק אִם גָּזְזוּ גַּם לִפְנֵי הַמּוֹעֵד","גּוֹזְזִים אוֹתָן כָּרָגִיל, כְּמוֹ בִּשְׁאָר הַיָּמִים"],3,"בְּרֹב קְהִלּוֹת הַסְּפָרַדִּים נוֹהֲגִים לִגְזֹז צִפָּרְנַיִם בְּחֹל הַמּוֹעֵד כָּרָגִיל. הַחֻמְרָה שֶׁל ״רַק מִי שֶׁגָּזַז לִפְנֵי הַמּוֹעֵד״ הִיא מִנְהַג הָאַשְׁכְּנַזִּים.","פֶּרֶק ס״ח, הֲלָכָה י׳","חֹל הַמּוֹעֵד – חֵלֶק א׳"],["רְאוּבֵן שׁוֹאֵל: הַאִם מֻתָּר לִנְסֹעַ בְּרֶכֶב בְּחֹל הַמּוֹעֵד?",["אָסוּר לִנְסֹעַ, כִּי זוֹ מְלָאכָה גְּמוּרָה","מֻתָּר רַק לִנְסִיעָה לְבֵית הַכְּנֶסֶת","כֵּן, מֻתָּר לִנְסֹעַ בְּרֶכֶב בְּחֹל הַמּוֹעֵד","מֻתָּר רַק בְּרֶגֶל, לֹא בְּרֶכֶב"],2,"מֻתָּר לִנְסֹעַ בְּרֶכֶב בְּחֹל הַמּוֹעֵד.","פֶּרֶק ס״ח, הֲלָכָה י״א","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["שִׁמְעוֹן רוֹצֶה לְתַקֵּן אֶת הָרֶכֶב בַּמּוֹעֵד. מָה הַדִּין?",["מֻתָּר כָּל תִּקּוּן, גַּם בַּמּוּסָךְ","תִּקּוּן פָּשׁוּט לְצֹרֶךְ הַמּוֹעֵד מֻתָּר","אָסוּר כָּל תִּקּוּן, אֲפִלּוּ פָּשׁוּט מְאֹד","מֻתָּר רַק תִּקּוּן לְאַחַר הַחַג"],1,"תִּקּוּן פָּשׁוּט לִנְסִיעוֹת הַמּוֹעֵד מֻתָּר; אָסוּר לְצֹרֶךְ אַחֲרֵי הַחַג אוֹ תִּקּוּן שֶׁדּוֹרֵשׁ מוּסָךְ.","פֶּרֶק ס״ח, הֲלָכָה י״ב","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["לֵוִי שׁוֹאֵל: מֻתָּר לַעֲבֹר לְדִירָה נָאָה יוֹתֵר בַּמּוֹעֵד?",["מֻתָּר, כִּי הַדִּירָה הַחֲדָשָׁה נָאָה","מֻתָּר רַק בְּיוֹם הָאַחֲרוֹן שֶׁל הַחַג","מֻתָּר אִם הַמַּעֲבָר נַעֲשֶׂה בַּלַּיְלָה","אֵין לַעֲבֹר, אֲפִלּוּ לְדִירָה נָאָה יוֹתֵר"],3,"אֵין לַעֲבֹר דִּירָה בְּחֹל הַמּוֹעֵד, אֲפִלּוּ מִפְּשׁוּטָה לְנָאָה.","פֶּרֶק ס״ח, הֲלָכָה י״ג","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["יְהוּדָה סוֹחֵר. מָתַי מֻתָּר לוֹ לִמְכֹּר בַּמּוֹעֵד?",["כְּשֶׁיַּפְסִיד מֵהַקֶּרֶן, כִּי זֶה דָּבָר הָאָבֵד","תָּמִיד, כִּי מִסְחָר אֵינוֹ מְלָאכָה","כְּשֶׁיַּרְוִיחַ הַרְבֵּה יוֹתֵר כֶּסֶף מֵהַמְּכִירָה","רַק לִקְנוֹת מֻתָּר, לֹא לִמְכֹּר"],0,"מִסְחָר אָסוּר, אֲבָל אִם יַפְסִיד מֵהַקֶּרֶן מֻתָּר – זֶה דָּבָר הָאָבֵד.","פֶּרֶק ס״ח, הֲלָכָה י״ד","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["מוֹכֵר חוֹשֵׁשׁ לְהַפְסִיד לָקוֹחוֹת קְבוּעִים אִם לֹא יִפְתַּח. מָה יַעֲשֶׂה?",["יִפְתַּח אֶת הַחֲנוּת כָּרָגִיל בְּלִי לִשְׁאֹל","יִשְׁאַל שְׁאֵלַת חָכָם כֵּיצַד לִנְהֹג","יִסְגֹּר וְלֹא יִדְאַג לַלָּקוֹחוֹת כְּלָל","יִפְתַּח רַק בַּלַּיְלָה בְּלִי שֶׁיִּרְאוּ"],1,"כְּשֶׁיֵּשׁ חֲשַׁשׁ לְנֶזֶק גָּדוֹל לִטְוָח אָרֹךְ – יִשְׁאַל שְׁאֵלַת חָכָם.","פֶּרֶק ס״ח, הֲלָכָה ט״ו","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["עוֹבֵד שָׂכִיר זַכַּאי לִימֵי חֻפְשָׁה. מָה עָלָיו לַעֲשׂוֹת?",["יְנַצֵּל אוֹתָם רַק אַחֲרֵי הַחַגִּים","יְוַתֵּר עַל יְמֵי הַחֻפְשָׁה לְגַמְרֵי","יַעֲשֶׂה מַאֲמָץ לְנַצֵּל אוֹתָם בְּחֹל הַמּוֹעֵד","יַעֲבֹד בְּחֹל הַמּוֹעֵד בְּלִי שׁוּם שְׁאֵלָה"],2,"יַעֲשֶׂה מַאֲמָץ לְנַצֵּל אֶת הַחֻפְשָׁה בַּמּוֹעֵד, וְאִם אִי אֶפְשָׁר – יִשְׁאַל חָכָם.","פֶּרֶק ס״ח, הֲלָכָה ט״ז","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["בַּעַל מַכֹּלֶת שׁוֹאֵל: מֻתָּר לִמְכֹּר בָּשָׂר וִירָקוֹת בַּמּוֹעֵד?",["אָסוּר, כִּי כָּל מִסְחָר אָסוּר בַּמּוֹעֵד","מֻתָּר רַק לִמְכֹּר לֶחֶם, לֹא בָּשָׂר","מֻתָּר רַק אִם יַפְסִיד מֵהַקֶּרֶן","מֻתָּר לִמְכֹּר מִצְרְכֵי מָזוֹן כְּמוֹ אֵלֶּה"],3,"מֻתָּר לִמְכֹּר מִצְרְכֵי מָזוֹן כְּמוֹ יְרָקוֹת, דָּגִים וּבָשָׂר.","פֶּרֶק ס״ח, הֲלָכָה י״ז","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["בְּבֵית נַפְתָּלִי נִפְרְצָה הַגָּדֵר. מָה הַדִּין?",["אָסוּר לְתַקֵּן, כִּי כָּל בִּנְיָן אָסוּר","מֻתָּר לִבְנוֹת גַּם חֶדֶר חָדָשׁ","עֲבוֹדָה דְּחוּפָה כָּזוֹ מֻתֶּרֶת בִּתְנָאִים מְסֻיָּמִים","מֻתָּר רַק אִם הַגָּדֵר קְטַנָּה"],2,"בִּנְיָן אָסוּר, אֲבָל עֲבוֹדוֹת דְּחוּפוֹת כְּפִרְצָה בַּגָּדֵר מֻתָּרוֹת בְּמִקְרִים וּבִתְנָאִים מְסֻיָּמִים.","פֶּרֶק ס״ח, הֲלָכָה י״ח","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["לְגָד נָפַל כַּפְתּוֹר מֵהַחֻלְצָה. מָה הַדִּין?",["מֻתָּר לִתְפֹּר, כִּי זֶה תִּקּוּן פָּשׁוּט","אָסוּר, כִּי כָּל תְּפִירָה הִיא מְלָאכָה","מֻתָּר רַק אֵצֶל חַיָּט מִקְצוֹעִי","יַמְתִּין עִם הַתִּקּוּן עַד לַחֹדֶשׁ הַבָּא"],0,"תִּקּוּן פָּשׁוּט כְּמוֹ תְּפִירַת כַּפְתּוֹר מֻתָּר; תִּקּוּן מִקְצוֹעִי אָסוּר.","פֶּרֶק ס״ח, הֲלָכָה י״ט","חֹל הַמּוֹעֵד – חֵלֶק ב׳"],["מַדּוּעַ תִּקְּנוּ חֲכָמִים אֶת עֵרוּב הַתַּבְשִׁילִין?",["כְּדֵי שֶׁיֹּאכְלוּ יוֹתֵר אֹכֶל בְּיוֹם טוֹב","כְּדֵי לְהַרְבּוֹת בְּרָכוֹת בְּעֶרֶב יוֹם טוֹב","כְּדֵי שֶׁלֹּא יִטְעוּ לְבַשֵּׁל בְּיוֹם טוֹב לְחֹל","כְּדֵי שֶׁהָאֹכֶל יִהְיֶה טָעִים יוֹתֵר בְּשַׁבָּת"],2,"חֲכָמִים חָשְׁשׁוּ שֶׁמִּי שֶׁמְּבַשֵּׁל בְּיוֹם טוֹב לְשַׁבָּת יִטְעֶה לַחְשֹׁב שֶׁמֻּתָּר לְבַשֵּׁל גַּם לְחֹל. כְּשֶׁרַק מִי שֶׁעֵרֵב מְבַשֵּׁל – לֹא יִטְעוּ.","פֶּרֶק ס״ט, הֲלָכָה א׳","עֵרוּב תַּבְשִׁילִין"],["מָה הַטַּעַם הַנּוֹסָף לְתַקָּנַת הָעֵרוּב?",["שֶׁיִּזְכְּרוּ אֶת הַשַּׁבָּת וְיִטְרְחוּ גַּם עֲבוּרָהּ","שֶׁיַּזְמִינוּ אוֹרְחִים רַבִּים לִסְעוּדַת הֶחָג","שֶׁיָּנוּחוּ הַרְבֵּה וְלֹא יְבַשְּׁלוּ כְּלָל בַּחַג","שֶׁיְּלַמְּדוּ אֶת הַיְּלָדִים לְבַשֵּׁל מַאֲכָלִים חֲדָשִׁים"],0,"כְּשֶׁמְּכִינִים אֶת צָרְכֵי הֶחָג, הָעֵרוּב מַזְכִּיר שֶׁלְּמָחֳרָת מַגִּיעָה הַשַּׁבָּת, וְטוֹרְחִים גַּם עֲבוּר הַשַּׁבָּת.","פֶּרֶק ס״ט, הֲלָכָה ב׳","עֵרוּב תַּבְשִׁילִין"],["מָה נוֹהֲגִים כַּיּוֹם לָקַחַת לָעֵרוּב?",["פְּרוּסַת לֶחֶם קְטַנָּה וְכוֹס מַיִם קָרִים","תַּפּוּחַ אֲדָמָה חַי וּמְעַט מֶלַח גַּס","עוּגָה מְתוּקָה וּבַקְבּוּק מִיץ עֲנָבִים קַר","כִּכָּר שְׁלֵמָה וּבֵיצָה מְבֻשֶּׁלֶת אוֹ חֲתִיכַת בָּשָׂר"],3,"הָעֵרוּב בְּפַת וּבְתַבְשִׁיל כְּשִׁעוּר כַּזַּיִת. כַּיּוֹם נוֹהֲגִים בְּכִכָּר שְׁלֵמָה מִשּׁוּם הִדּוּר מִצְוָה, וּבְבָשָׂר אוֹ דָּג אוֹ בֵּיצָה מְבֻשֶּׁלֶת.","פֶּרֶק ס״ט, הֲלָכָה ג׳","עֵרוּב תַּבְשִׁילִין"],["מָה מוֹסִיפִים לוֹמַר אַחֲרֵי בִּרְכַּת הָעֵרוּב?",["שֶׁהָעֵרוּב הַזֶּה יַעֲזֹר לָנוּ לְהַצְלִיחַ בַּלִּמּוּדִים הַשָּׁנָה","שֶׁבָּעֵרוּב הַזֶּה יְהֵא מֻתָּר לָנוּ לְבַשֵּׁל לְשַׁבָּת","שֶׁבָּעֵרוּב הַזֶּה יְהֵא מֻתָּר לָנוּ לִנְסֹעַ בַּחַג","שֶׁנִּזְכֶּה לֶאֱכֹל אֶת הָעֵרוּב בְּמוֹצָאֵי הַחַג"],1,"אוֹמְרִים: ״בָּעֵרוּב הַזֶּה יְהֵא מֻתָּר לָנוּ לֶאֱפוֹת וּלְבַשֵּׁל וּלְהַטְמִין וּלְהַדְלִיק נֵר וְלַעֲשׂוֹת כָּל צְרָכֵינוּ מִיּוֹם טוֹב לְשַׁבָּת״.","פֶּרֶק ס״ט, הֲלָכָה ד׳","עֵרוּב תַּבְשִׁילִין"],["רְאוּבֵן שָׁכַח לְעָרֵב, וְעַכְשָׁו כְּבָר בֵּין הַשְּׁמָשׁוֹת. מָה יַעֲשֶׂה?",["יְעָרֵב מָחָר בְּיוֹם טוֹב לִפְנֵי הַבִּשּׁוּל","יְעָרֵב עַכְשָׁו, אֲבָל בְּלִי לְבָרֵךְ כְּלָל","יְעָרֵב עַכְשָׁו בִּבְרָכָה, כִּי עֲדַיִן אֶפְשָׁר","לֹא יְעָרֵב, כִּי כְּבָר מְאֻחָר מִדַּי"],2,"אֶת הָעֵרוּב עוֹשִׂים בְּעֶרֶב יוֹם טוֹב עַד הַשְּׁקִיעָה, וּמִי שֶׁשָּׁכַח – יָכוֹל לְעָרֵב בִּבְרָכָה גַּם בְּבֵין הַשְּׁמָשׁוֹת.","פֶּרֶק ס״ט, הֲלָכָה ה׳","עֵרוּב תַּבְשִׁילִין"],["שִׁמְעוֹן אֵינוֹ יוֹדֵעַ לְעָרֵב. עַל מָה הוּא יָכוֹל לִסְמֹךְ?",["עַל הָעֵרוּב שֶׁעָשָׂה בַּשָּׁנָה שֶׁעָבְרָה בְּבֵיתוֹ","עַל הָעֵרוּב שֶׁל חָבֵר מִכִּתָּה בְּעִיר אַחֶרֶת","עַל הָעֵרוּב שֶׁרַב הָעִיר עָשָׂה לְכָל בְּנֵי הָעִיר","עַל זֶה שֶׁיִּתְפַּלֵּל בְּכַוָּנָה בְּיוֹם טוֹב בַּבֹּקֶר"],2,"רַב הָעִיר מְעָרֵב עֲבוּר כָּל בְּנֵי הָעִיר: אָדָם אַחֵר מַגְבִּיהַּ אֶת הַתַּבְשִׁיל לִזְכּוֹת בּוֹ לְכֻלָּם. לְכַתְּחִלָּה כָּל אֶחָד מְעָרֵב בְּעַצְמוֹ, אֲבָל מִי שֶׁאֵינוֹ יוֹדֵעַ לְעָרֵב סוֹמֵךְ עַל עֵרוּב הָרַב.","פֶּרֶק ס״ט, הֲלָכָה ז׳","עֵרוּב תַּבְשִׁילִין"],["בְּמָקוֹם שֶׁאֵין בּוֹ רַב מְעָרֵב, הָעֵרוּב שֶׁל דָּוִד נֶאֱכַל לִפְנֵי הַבִּשּׁוּל. מָה הַדִּין?",["יָכוֹל לְבַשֵּׁל, כִּי כְּבָר עָשָׂה עֵרוּב קֹדֶם","אֵינוֹ יָכוֹל לְבַשֵּׁל בְּיוֹם טוֹב עֲבוּר הַשַּׁבָּת","יָכוֹל לְבַשֵּׁל רַק מַאֲכָלִים קַלִּים וּפְשׁוּטִים","יַעֲשֶׂה עֵרוּב חָדָשׁ מִן הָאֹכֶל שֶׁל הַחַג"],1,"מִי שֶׁגָּר בְּמָקוֹם שֶׁאֵין בּוֹ רַב שֶׁמְּעָרֵב, וְעֵרוּבוֹ נֶאֱכַל אוֹ אָבַד לִפְנֵי שֶׁהִסְפִּיק לְבַשֵּׁל לְשַׁבָּת – אֵינוֹ יָכוֹל לְבַשֵּׁל בְּיוֹם טוֹב עֲבוּר הַשַּׁבָּת.","פֶּרֶק ס״ט, הֲלָכָה ח׳","עֵרוּב תַּבְשִׁילִין"],["מָתַי טוֹב לֶאֱכֹל אֶת הָעֵרוּב, וּמַדּוּעַ?",["בְּעֶרֶב יוֹם טוֹב, מִיָּד אַחֲרֵי הַבְּרָכָה שֶׁעָלָיו","אָסוּר לְעוֹלָם לֶאֱכֹל אוֹתוֹ, וְזוֹרְקִים אוֹתוֹ","בְּמוֹצָאֵי שַׁבָּת, בִּסְעוּדַת מְלַוֶּה מַלְכָּה הַחֲגִיגִית","בִּסְעוּדָה שְׁלִישִׁית, וְכָךְ מְקַיְּמִים בּוֹ שְׁתֵּי מִצְווֹת"],3,"מֻתָּר לֶאֱכֹל אֶת הָעֵרוּב בְּיוֹם טוֹב אַחֲרֵי הֲכָנַת צָרְכֵי הַשַּׁבָּת, אֲבָל טוֹב לְאָכְלוֹ בִּסְעוּדָה שְׁלִישִׁית: כָּךְ נַעֲשׂוֹת בּוֹ שְׁתֵּי מִצְווֹת – עֵרוּב תַּבְשִׁילִין וּסְעוּדָה שְׁלִישִׁית.","פֶּרֶק ס״ט, הֲלָכָה ט׳","עֵרוּב תַּבְשִׁילִין"],["מָתַי יֵשׁ לְהִשְׁתַּדֵּל לְסַיֵּם אֶת הַבִּשּׁוּל לְשַׁבָּת?",["בְּיוֹם טוֹב, כַּמָּה שֶׁיּוֹתֵר מֻקְדָּם","בְּיוֹם טוֹב, מַמָּשׁ לִפְנֵי הַשְּׁקִיעָה","בְּלֵיל שַׁבָּת, אַחֲרֵי הַדְלָקַת הַנֵּרוֹת","בְּשַׁבָּת בַּבֹּקֶר, מִיָּד לִפְנֵי הַתְּפִלָּה"],0,"יֵשׁ לְהִשְׁתַּדֵּל לְסַיֵּם אֶת הַבִּשּׁוּל בְּיוֹם טוֹב לְשַׁבָּת כַּמָּה שֶׁיּוֹתֵר מֻקְדָּם.","פֶּרֶק ס״ט, הֲלָכָה י׳","עֵרוּב תַּבְשִׁילִין"],["בְּיָמֵינוּ, שֶׁאֵין מַקְרִיבִים אֶת הָעֹמֶר, מָתַי מֻתָּר לֶאֱכֹל מִתְּבוּאָה חֲדָשָׁה?",["כְּבָר בְּלֵיל הַסֵּדֶר, בְּלֵיל ט״ו בְּנִיסָן","רַק אַחֲרֵי חַג הַשָּׁבוּעוֹת שֶׁל אוֹתָהּ שָׁנָה","רַק אַחֲרֵי סוֹף יוֹם ט״ז בְּנִיסָן","מִיָּד בְּבֹקֶר ט״ז בְּנִיסָן, גַּם מִדְּרַבָּנָן"],2,"מֵהַתּוֹרָה מֻתָּר כְּבָר בְּבֹקֶר ט״ז בְּנִיסָן, אַךְ חֲכָמִים גָּזְרוּ שֶׁלֹּא לֶאֱכֹל עַד סוֹף יוֹם ט״ז בְּנִיסָן.","פֶּרֶק ע׳, הֲלָכָה א׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["מַדּוּעַ אֵין חֲשַׁשׁ חָדָשׁ בְּמוּצָרִים מִדְּגָנִים שֶׁגָּדְלוּ בָּאָרֶץ?",["כִּי אִסּוּר חָדָשׁ נוֹהֵג רַק בְּחוּץ לָאָרֶץ","כִּי הַדְּגָנִים בָּאָרֶץ אֵינָם מַבְשִׁילִים לִפְנֵי פֶּסַח","כִּי אִסּוּר חָדָשׁ אֵינוֹ נוֹהֵג בִּזְמַנֵּנוּ כְּלָל","כִּי כָּל הַתְּבוּאָה בָּאָרֶץ שַׁיֶּכֶת לְגוֹיִים"],1,"הַדְּגָנִים אֵינָם מַבְשִׁילִים בָּאָרֶץ לִפְנֵי פֶּסַח, וְלָכֵן אֵין בָּהֶם חֲשַׁשׁ. אֲבָל אִסּוּר חָדָשׁ נוֹהֵג גַּם בְּחוּץ לָאָרֶץ וְגַם בִּתְבוּאַת גּוֹי, וְלָכֵן בְּמוּצָרִים מְיֻבָּאִים בֵּין חֶשְׁוָן לְפֶסַח יֵשׁ לָשִׂים לֵב.","פֶּרֶק ע׳, הֲלָכוֹת ב׳-ג׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["מָה סוֹפְרִים בִּסְפִירַת הָעֹמֶר?",["רַק אֶת הַשָּׁבוּעוֹת, בְּכָל מוֹצָאֵי שַׁבָּת","רַק אֶת הַיָּמִים, בְּלִי לְהַזְכִּיר שָׁבוּעוֹת","רַק אֶת הַיָּמִים שֶׁנִּשְׁאֲרוּ עַד שָׁבוּעוֹת","גַּם אֶת הַשָּׁבוּעוֹת וְגַם אֶת הַיָּמִים"],3,"סוֹפְרִים שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת וְגַם חֲמִשִּׁים יוֹם, וּבַיּוֹם הַחֲמִשִּׁים מַקְרִיבִים מִנְחַת שְׁתֵּי הַלֶּחֶם.","פֶּרֶק ע׳, הֲלָכוֹת ד׳-ה׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["לְפִי נֹסַח הַסְּפָרַדִּים, הֵיכָן נֶאֱמֶרֶת הַמִּלָּה ״לָעֹמֶר״?",["מִיָּד אַחֲרֵי מִסְפַּר הַיָּמִים, לִפְנֵי הַשָּׁבוּעוֹת","בְּסוֹף הַסְּפִירָה, אַחֲרֵי הַשָּׁבוּעוֹת וְהַיָּמִים","בִּתְחִלַּת הַסְּפִירָה, לִפְנֵי הַמִּלָּה ״הַיּוֹם״","אֵינָם אוֹמְרִים אֶת הַמִּלָּה ״לָעֹמֶר״ כְּלָל"],0,"נֹסַח הַסְּפָרַדִּים: ״הַיּוֹם ___ יָמִים לָעֹמֶר, שֶׁהֵם ___ שָׁבוּעוֹת וְ___ יָמִים״. הָאַשְׁכְּנַזִּים אוֹמְרִים ״לָעֹמֶר״ (אוֹ ״בָּעֹמֶר״) בַּסּוֹף.","פֶּרֶק ע׳, הֲלָכָה ו׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["מִי שֶׁסָּפַר בֵּין הַשְּׁקִיעָה לְצֵאת הַכּוֹכָבִים, מָה יַעֲשֶׂה?",["יַחְזֹר וְיִסְפֹּר אַחֲרֵי צֵאת הַכּוֹכָבִים עִם בְּרָכָה","יָצָא יְדֵי חוֹבָה וְאֵינוֹ צָרִיךְ לַחְזֹר","יַחְזֹר וְיִסְפֹּר אַחֲרֵי צֵאת הַכּוֹכָבִים בְּלִי בְּרָכָה","יִסְפֹּר שׁוּב רַק לְמָחֳרָת בַּבֹּקֶר בִּבְרָכָה"],2,"סוֹפְרִים אַחֲרֵי צֵאת הַכּוֹכָבִים. מִי שֶׁטָּעָה וְסָפַר קֹדֶם, חוֹזֵר וְסוֹפֵר אַחַר כָּךְ לְלֹא בְּרָכָה. וְרָצוּי לִסְפֹּר מִיָּד בְּצֵאת הַכּוֹכָבִים כְּדֵי שֶׁהַשַּׁבָּתוֹת יִהְיוּ תְּמִימוֹת.","פֶּרֶק ע׳, הֲלָכוֹת ז׳-ח׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["דָּוִד סָפַר אֶת הָעֹמֶר כְּשֶׁהוּא יוֹשֵׁב. מָה הַדִּין?",["לֹא יָצָא, וְעָלָיו לַחְזֹר וְלִסְפֹּר בַּעֲמִידָה","יָצָא יְדֵי חוֹבָה, אַךְ לְכַתְּחִלָּה סוֹפְרִים בַּעֲמִידָה","יָצָא, וְכָךְ הוּא הַמִּנְהָג הַטּוֹב לְכַתְּחִלָּה","לֹא יָצָא, וְיִסְפֹּר שׁוּב מָחָר פַּעֲמַיִם"],1,"מִצְוָה עַל כָּל אָדָם לִסְפֹּר בְּעַצְמוֹ וּבַעֲמִידָה, וּמִי שֶׁסָּפַר בִּישִׁיבָה יָצָא יְדֵי חוֹבָה.","פֶּרֶק ע׳, הֲלָכָה ט׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["מִי שֶׁסָּפַר בְּעִבְרִית וְלֹא הֵבִין מָה אָמַר, מָה הַדִּין?",["יָצָא, כִּי לְשׁוֹן הַקֹּדֶשׁ מוֹעִילָה גַּם בְּלִי הֲבָנָה","לֹא יָצָא, וְיַחְזֹר לִסְפֹּר שׁוּב עִם בְּרָכָה","יָצָא, אֲבָל מָחָר יִסְפֹּר בְּשָׂפָה אַחֶרֶת","לֹא יָצָא, וְיַחְזֹר לִסְפֹּר בְּלֹא בְּרָכָה"],3,"אִי אֶפְשָׁר לִסְפֹּר בְּלִי לְהָבִין, וְלָכֵן לֹא יָצָא וְיַחְזֹר לִסְפֹּר בְּלֹא בְּרָכָה, בְּשָׂפָה שֶׁהוּא מֵבִין.","פֶּרֶק ע׳, הֲלָכָה י׳","בֵּין פֶּסַח לַעֲצֶרֶת"],["בְּלֵיל לַ״ג בָּעֹמֶר אָמַר לַחֲבֵרוֹ ״הַיּוֹם לַ״ג בָּעֹמֶר״. מָה הַדִּין?",["לֹא יְבָרֵךְ, כִּי כְּבָר יָצָא יְדֵי חוֹבַת הַסְּפִירָה","צָרִיךְ לִשְׁמֹעַ אֶת הַבְּרָכָה מֵאָדָם אַחֵר בְּבֵית הַכְּנֶסֶת","יָכוֹל לִסְפֹּר אַחַר כָּךְ בִּבְרָכָה, כִּי הִתְכַּוֵּן לְיוֹם טוֹב","לֹא יִסְפֹּר כְּלָל עַד סוֹף יְמֵי הָעֹמֶר"],2,"בְּדֶרֶךְ כְּלָל אַחֲרֵי הַשְּׁקִיעָה עוֹנִים ״אֶתְמוֹל הָיָה כָּךְ וְכָךְ״. אֲבָל בְּלַ״ג בָּעֹמֶר הַכַּוָּנָה לְשֵׁם הַיּוֹם הַטּוֹב וְלֹא לִסְפִירָה, וְלָכֵן יָכוֹל לִסְפֹּר אַחַר כָּךְ בִּבְרָכָה.","פֶּרֶק ע׳, הֲלָכָה י״א","בֵּין פֶּסַח לַעֲצֶרֶת"],["מַדּוּעַ נָשִׁים פְּטוּרוֹת מִסְּפִירַת הָעֹמֶר?",["כִּי הַסְּפִירָה נַעֲשֵׂית רַק בְּבֵית הַכְּנֶסֶת","כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ","כִּי זוֹ מִצְוָה שֶׁנּוֹהֶגֶת רַק בְּבֵית הַמִּקְדָּשׁ","כִּי אָסוּר לָהֶן לְבָרֵךְ עַל שׁוּם מִצְוָה"],1,"סְפִירַת הָעֹמֶר הִיא מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ, וְלָכֵן נָשִׁים פְּטוּרוֹת. אִם רוֹצוֹת לִסְפֹּר רַשָּׁאִיּוֹת, וּלְמִנְהַג הָאַשְׁכְּנַזִּים אַף רַשָּׁאִיּוֹת לְבָרֵךְ.","פֶּרֶק ע׳, הֲלָכָה י״ב","בֵּין פֶּסַח לַעֲצֶרֶת"],["שָׁכַח לִסְפֹּר גַּם בַּלַּיְלָה וְגַם בַּיּוֹם שֶׁאַחֲרָיו. מָה יַעֲשֶׂה?",["יַפְסִיק לִסְפֹּר, כִּי הִפְסִיד אֶת כָּל הַמִּצְוָה","יַמְשִׁיךְ לִסְפֹּר בִּבְרָכָה כָּרָגִיל בְּכָל הַלֵּילוֹת","יַתְחִיל אֶת הַסְּפִירָה מֵהַהַתְחָלָה, מִיּוֹם אֶחָד","יַמְשִׁיךְ לִסְפֹּר בְּלִי בְּרָכָה, וְיִשְׁמַע בְּרָכָה מֵאַחֵר"],3,"חַיָּב לְהַמְשִׁיךְ לִסְפֹּר, אַךְ מִפְּנֵי שֶׁ״סְּפֵק בְּרָכוֹת לְהָקֵל״ לֹא יְבָרֵךְ, וְיִשְׁתַּדֵּל לִשְׁמֹעַ אֶת הַבְּרָכָה מֵאַחֵר. וּמִי שֶׁסָּפַר מִסְפָּר מֻטְעֶה, דִּינוֹ כְּמִי שֶׁלֹּא סָפַר כְּלָל.","פֶּרֶק ע׳, הֲלָכוֹת י״ג-י״ד","בֵּין פֶּסַח לַעֲצֶרֶת"],["דָּנִי אֵינוֹ זוֹכֵר אִם סָפַר אֶתְמוֹל אֶת הָעֹמֶר. מָה יַעֲשֶׂה?",["יַפְסִיק לִסְפֹּר לְגַמְרֵי עַד סוֹף הָעֹמֶר","יִסְפֹּר מֵעַכְשָׁיו רַק בְּלִי בְּרָכָה בִּכְלָל","יַמְשִׁיךְ לִסְפֹּר בִּשְׁאַר הַיָּמִים בִּבְרָכָה","יַתְחִיל לִסְפֹּר מֵהַהַתְחָלָה מִיּוֹם רִאשׁוֹן"],2,"מִי שֶׁאֵינוֹ זוֹכֵר אִם סָפַר בְּיוֹם מְסֻיָּם, יָכוֹל לְהַמְשִׁיךְ וְלִסְפֹּר בִּשְׁאַר הַיָּמִים בִּבְרָכָה.","פֶּרֶק ע׳, הֲלָכָה ט״ו׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["מָתַי נוֹהֲגִים הַסְּפָרַדִּים לַעֲרֹךְ חֲתֻנּוֹת אַחֲרֵי פֶּסַח?",["כְּבָר בְּלֵיל לַ״ג בָּעֹמֶר, בְּשִׂמְחָה גְּדוֹלָה","מִיּוֹם ל״ד בָּעֹמֶר וָאֵילָךְ, כְּמוֹ בִּשְׁאָר הַשָּׁנָה","רַק אַחֲרֵי חַג הַשָּׁבוּעוֹת, כְּשֶׁנִּגְמֶרֶת הַסְּפִירָה","מֵרֹאשׁ חֹדֶשׁ אִיָּר וְעַד סוֹף הַחֹדֶשׁ"],1,"מִנְהַג הַסְּפָרַדִּים שֶׁלֹּא לְהִתְחַתֵּן מִפֶּסַח עַד לַ״ג בָּעֹמֶר, כִּי אָז מֵתוּ תַּלְמִידֵי רַבִּי עֲקִיבָא, אֲבָל מֻתָּר לְהִתְאָרֵס. מִיּוֹם ל״ד עוֹרְכִים חֲתֻנּוֹת. בְּרֹב קְהִלּוֹת הָאַשְׁכְּנַזִּים - כְּבָר בְּלֵיל לַ״ג בָּעֹמֶר.","פֶּרֶק ע׳, הֲלָכָה ט״ז׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["לַ״ג בָּעֹמֶר חָל בְּיוֹם שִׁשִּׁי. מָה דִּין תִּסְפֹּרֶת לְפִי מִנְהַג הַסְּפָרַדִּים?",["אָסוּר, וּמְחַכִּים עַד יוֹם רִאשׁוֹן בַּבֹּקֶר","מֻתָּר רַק לִילָדִים קְטַנִּים, לֹא לִמְבֻגָּרִים","מִסְתַּפְּרִים רַק בְּמוֹצָאֵי שַׁבָּת אַחֲרֵי הַבְדָּלָה","מֻתָּר לְהִסְתַּפֵּר בּוֹ מִפְּנֵי כְּבוֹד הַשַּׁבָּת"],3,"הַסְּפָרַדִּים מִסְתַּפְּרִים רַק בְּיוֹם ל״ד בַּבֹּקֶר, אֲבָל כְּשֶׁלַּ״ג בָּעֹמֶר בְּיוֹם שִׁשִּׁי מֻתָּר לְהִסְתַּפֵּר מִפְּנֵי כְּבוֹד הַשַּׁבָּת. וְכָל אָדָם יִנְהַג כְּמִנְהַג מִשְׁפַּחְתּוֹ.","פֶּרֶק ע׳, הֲלָכָה י״ז׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["מִי יָכוֹל הָיָה לְהַקְרִיב קָרְבַּן פֶּסַח בְּי״ד בְּאִיָּר?",["מִי שֶׁהָיָה טָמֵא אוֹ רָחוֹק מֵהַמִּקְדָּשׁ בְּנִיסָן","מִי שֶׁשָּׁכַח לִקְנוֹת כֶּבֶשׂ בַּזְּמַן הַנָּכוֹן","כָּל מִי שֶׁרָצָה לְהַקְרִיב קָרְבָּן נוֹסָף","רַק הַכֹּהֲנִים שֶׁעָבְדוּ בַּמִּקְדָּשׁ כָּל יְמֵי הַחַג"],0,"י״ד בְּאִיָּר הוּא פֶּסַח שֵׁנִי: מִי שֶׁהָיָה טָמֵא אוֹ רָחוֹק וְלֹא הִקְרִיב בְּי״ד בְּנִיסָן, הִקְרִיב בּוֹ. גַּם הַיּוֹם יֵשׁ בּוֹ קְצָת קְדֻשָּׁה וְשִׂמְחָה, וְיֵשׁ נוֹהֲגִים לֶאֱכֹל מַצָּה.","פֶּרֶק ע׳, הֲלָכוֹת י״ח-י״ט","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["מַדּוּעַ יוֹם פְּטִירַת רַשְׁבִּ״י נִקְרָא ׳הִלּוּלָא׳?",["כִּי בּוֹ מַדְלִיקִים אֲבוּקוֹת גְּדוֹלוֹת עַל הֶהָרִים","כִּי בּוֹ נִצַּח בַּר כּוֹכְבָא אֶת הָרוֹמָאִים","כִּי שְׂמֵחִים עַל דִּבְרֵי הַתּוֹרָה שֶׁהִשְׁאִיר לָנוּ","כִּי בּוֹ סִיְּמוּ לִלְמֹד אֶת כָּל הַזֹּהַר"],2,"׳הִלּוּלָא׳ תַּרְגּוּמוֹ שִׂמְחָה, כִּי בְּיוֹם זֶה שְׂמֵחִים עַל דִּבְרֵי הַתּוֹרָה שֶׁהִשְׁאִיר לָנוּ. עוֹד טְעָמִים: יֵשׁ אוֹמְרִים שֶׁבּוֹ סָמַךְ רַבִּי עֲקִיבָא אֶת תַּלְמִידָיו, וְיֵשׁ אוֹמְרִים שֶׁבּוֹ נִצַּח בַּר כּוֹכְבָא.","פֶּרֶק ע׳, הֲלָכָה כ׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["לַ״ג בָּעֹמֶר חָל בְּיוֹם רִאשׁוֹן. מָתַי מַדְלִיקִים מְדוּרוֹת?",["בְּמוֹצָאֵי שַׁבָּת, מִיָּד אַחֲרֵי צֵאת הַכּוֹכָבִים","בְּיוֹם רִאשׁוֹן בָּעֶרֶב, כְּדֵי לִמְנֹעַ חִלּוּל שַׁבָּת","בְּיוֹם שִׁשִּׁי בַּצָּהֳרַיִם, לִפְנֵי כְּנִיסַת הַשַּׁבָּת","בְּשַׁבָּת בַּבֹּקֶר, כְּדֵי לִשְׂמֹחַ בּוֹ כָּל הַיּוֹם"],1,"הָרַבָּנוּת הָרָאשִׁית הִתְקִינָה שֶׁכְּשֶׁלַּ״ג בָּעֹמֶר חָל בְּיוֹם רִאשׁוֹן, מַדְלִיקִים בְּיוֹם רִאשׁוֹן בָּעֶרֶב וְלֹא בְּמוֹצָאֵי שַׁבָּת, כְּדֵי לִמְנֹעַ חִלּוּל שַׁבָּת. הַמִּנְהָג הִתְחִיל מֵהָאֲבוּקוֹת בְּמֵירוֹן.","פֶּרֶק ע׳, הֲלָכוֹת כ״א-כ״ב","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["יוֹם ה׳ בְּאִיָּר חָל בְּשַׁבָּת. מָה עוֹשִׂים עִם יוֹם הָעַצְמָאוּת?",["חוֹגְגִים אוֹתוֹ בְּשַׁבָּת כָּרָגִיל עִם זִקּוּקִים","מְבַטְּלִים אוֹתוֹ לְגַמְרֵי בְּאוֹתָהּ שָׁנָה","דּוֹחִים אוֹתוֹ לְחֹדֶשׁ סִיוָן שֶׁאַחֲרָיו","מַקְדִּימִים אוֹתוֹ כְּדֵי לִמְנֹעַ חִלּוּל שַׁבָּת"],3,"כְּשֶׁה׳ בְּאִיָּר חָל בְּשִׁשִּׁי, שַׁבָּת אוֹ שֵׁנִי, מַקְדִּימִים אוֹ מְאַחֲרִים אֶת יוֹם הָעַצְמָאוּת כְּדֵי לִמְנֹעַ חִלּוּל שַׁבָּת. זֶהוּ יוֹם הַלֵּל וְהוֹדָיָה עַל הֲקָמַת הַמְּדִינָה וְקִבּוּץ הַגָּלֻיּוֹת.","פֶּרֶק ע׳, הֲלָכוֹת כ״ג-כ״ד","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["עַל מָה מוֹדִים לַה׳ בְּיוֹם כ״ח בְּאִיָּר?",["עַל הַנִּסִּים הַגְּדוֹלִים בְּמִלְחֶמֶת שֵׁשֶׁת הַיָּמִים","עַל הַנִּצָּחוֹן שֶׁל בַּר כּוֹכְבָא בָּרוֹמָאִים","עַל יְצִיאַת מִצְרַיִם וְקָרְבַּן הַפֶּסַח הַשֵּׁנִי","עַל הַכְרָזַת הַמְּדִינָה בִּשְׁנַת תַּשַׁ״ח"],0,"כ״ח בְּאִיָּר, יוֹם שִׁחְרוּר יְרוּשָׁלַיִם, נִקְבַּע לְיוֹם הַלֵּל וְהוֹדָיָה עַל הַנִּסִּים הַגְּדוֹלִים בְּמִלְחֶמֶת שֵׁשֶׁת הַיָּמִים, וּמִתְפַּלְּלִים לִגְאֻלָּה שְׁלֵמָה.","פֶּרֶק ע׳, הֲלָכָה כ״ה׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["אֵיךְ אוֹמְרִים הַלֵּל בְּיוֹם הָעַצְמָאוּת לְפִי הַדַּעָה הָרִאשׁוֹנָה?",["חֲצִי הַלֵּל בְּלִי בְּרָכָה בִּתְפִלַּת מִנְחָה","הַלֵּל שָׁלֵם רַק בַּלַּיְלָה אַחֲרֵי עַרְבִית","הַלֵּל שָׁלֵם בִּבְרָכָה בִּתְפִלַּת שַׁחֲרִית","לֹא אוֹמְרִים הַלֵּל כְּלָל בְּיוֹם זֶה"],2,"בְּיוֹם הָעַצְמָאוּת וּבְיוֹם שִׁחְרוּר יְרוּשָׁלַיִם אוֹמְרִים הַלֵּל שָׁלֵם בִּבְרָכָה בְּשַׁחֲרִית, וְיֵשׁ אוֹמְרִים הַלֵּל לְלֹא בְּרָכָה.","פֶּרֶק ע׳, הֲלָכָה כ״ו׳","בֵּין פֶּסַח לַעֲצֶרֶת (ב)"],["מַדּוּעַ נִקְרָא חַג הַשָּׁבוּעוֹת ״יוֹם הַבִּכּוּרִים״?",["כִּי בּוֹ קוֹטְפִים אֶת הַפְּרִי הָרִאשׁוֹן בַּשָּׂדֶה","כִּי בּוֹ נוֹלַד הַבֵּן הַבְּכוֹר שֶׁל אַבְרָהָם אָבִינוּ","כִּי קָרְבַּן שְׁתֵּי הַלֶּחֶם שֶׁמַּקְרִיבִים בּוֹ נִקְרָא בִּכּוּרִים","כִּי בּוֹ אוֹכְלִים פֵּרוֹת רִאשׁוֹנִים לִפְנֵי כֻּלָּם"],2,"קָרְבַּן שְׁתֵּי הַלֶּחֶם שֶׁמַּקְרִיבִים בְּיוֹם זֶה נִקְרָא בִּכּוּרִים, וְעוֹד – לְמָחֳרַת הַחַג מַתְחִילִים לְהָבִיא בִּכּוּרִים מִשִּׁבְעַת הַמִּינִים.","פֶּרֶק ע״א, הֲלָכָה א׳","חַג הַשָּׁבוּעוֹת"],["מַדּוּעַ נָהֲגוּ שֶׁלֹּא לְהִתְפַּלֵּל עַרְבִית שֶׁל שָׁבוּעוֹת לִפְנֵי צֵאת הַכּוֹכָבִים?",["כְּדֵי שֶׁשֶּׁבַע הַשַּׁבָּתוֹת שֶׁסּוֹפְרִים יִהְיוּ תְּמִימוֹת וּשְׁלֵמוֹת","כְּדֵי שֶׁיִּהְיֶה זְמַן לֶאֱכֹל סְעֻדָּה גְּדוֹלָה לִפְנֵי הַתְּפִלָּה","כִּי אָסוּר מֵעִקַּר הַדִּין לְהִתְפַּלֵּל לִפְנֵי הַלַּיְלָה","כְּדֵי לְהַסְפִּיק לִקְרֹא אֶת כָּל מְגִלַּת רוּת"],0,"כָּתוּב ״שֶׁבַע שַׁבָּתוֹת תְּמִימֹת״ – הַשַּׁבָּתוֹת צְרִיכוֹת לִהְיוֹת שְׁלֵמוֹת. מֵעִקַּר הַדִּין מֻתָּר לְהִתְפַּלֵּל קֹדֶם, אַךְ אֵין לְקַדֵּשׁ לִפְנֵי צֵאת הַכּוֹכָבִים.","פֶּרֶק ע״א, הֲלָכָה ב׳","חַג הַשָּׁבוּעוֹת"],["מָה הַטַּעַם לַמִּנְהָג לִהְיוֹת עֵרִים כָּל לֵיל שָׁבוּעוֹת?",["כְּדֵי לִשְׁמֹר עַל בֵּית הַכְּנֶסֶת מִפְּנֵי גַּנָּבִים","כִּי בַּלַּיְלָה הַזֶּה אָסוּר לִישֹׁן מִן הַתּוֹרָה","כְּדֵי לִרְאוֹת אֶת הַזְּרִיחָה מֵרֹאשׁ הָהָר","לְתַקֵּן שֶׁיִּשְׂרָאֵל יָשְׁנוּ בַּלַּיְלָה שֶׁלִּפְנֵי מַתַּן תּוֹרָה"],3,"בַּמִּדְרָשׁ מְבֹאָר שֶׁיִּשְׂרָאֵל יָשְׁנוּ לִפְנֵי מַתַּן תּוֹרָה וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֻצְרַךְ לְהָעִיר אוֹתָם, וּבַלִּמּוּד כָּל הַלַּיְלָה מְתַקְּנִים פְּגָם זֶה.","פֶּרֶק ע״א, הֲלָכָה ג׳","חַג הַשָּׁבוּעוֹת"],["מִי שֶׁלָּמַד כָּל הַלַּיְלָה – עַל מָה רָאוּי שֶׁיַּקְפִּיד?",["לֶאֱכֹל אֲרוּחַת בֹּקֶר לִפְנֵי שֶׁמַּתְחִילִים אֶת הַתְּפִלָּה","לְהִתְאַמֵּץ לִהְיוֹת עֵרָנִי בִּתְפִלַּת שַׁחֲרִית שֶׁאַחֲרֵי הַלִּמּוּד","לְקַצֵּר אֶת תְּפִלַּת שַׁחֲרִית כְּדֵי לָלֶכֶת לִישֹׁן","לְהִתְפַּלֵּל שַׁחֲרִית לְבַד בַּבַּיִת וְלֹא בְּבֵית הַכְּנֶסֶת"],1,"רָאוּי לְהִתְאַמֵּץ לִהְיוֹת עֵרָנִיִּים בִּתְפִלַּת שַׁחֲרִית, וּמִי שֶׁיּוֹדֵעַ שֶׁלֹּא יוּכַל – עָדִיף שֶׁיֵּלֵךְ לִישֹׁן וְיִתְפַּלֵּל בַּבֹּקֶר כָּרָאוּי.","פֶּרֶק ע״א, הֲלָכָה ד׳","חַג הַשָּׁבוּעוֹת"],["מַדּוּעַ עוֹמְדִים בְּחֵלֶק מֵהַקְּהִלּוֹת בִּקְרִיאַת עֲשֶׂרֶת הַדִּבְּרוֹת?",["כִּי כָּךְ מְכַבְּדִים אֶת הַחַזָּן שֶׁקּוֹרֵא בַּתּוֹרָה","כִּי אֵין מַסְפִּיק כִּסְאוֹת בְּבֵית הַכְּנֶסֶת בַּחַג","כְּדֵי שֶׁיִּהְיֶה כְּמוֹ בְּמַעֲמַד מַתַּן תּוֹרָה","כִּי הַקְּרִיאָה בְּשָׁבוּעוֹת אֲרֻכָּה מִשְּׁאָר הַחַגִּים"],2,"בְּחֵלֶק מֵהַקְּהִלּוֹת נָהֲגוּ לַעֲמֹד בִּשְׁעַת קְרִיאַת עֲשֶׂרֶת הַדִּבְּרוֹת, כְּמוֹ בְּמַעֲמַד מַתַּן תּוֹרָה.","פֶּרֶק ע״א, הֲלָכָה ה׳","חַג הַשָּׁבוּעוֹת"],["מָה נָכוֹן לְגַבֵּי יוֹם חַג הַשָּׁבוּעוֹת?",["שׂוֹמְחִים בְּמַאֲכָל וּמִשְׁתֶּה וּמוֹסִיפִים גַּם בְּלִמּוּד הַתּוֹרָה","צָרִיךְ לְהִתְעַנּוֹת כָּל הַיּוֹם כְּדֵי לְהִתְכּוֹנֵן לַתּוֹרָה","אוֹכְלִים וְשׂוֹמְחִים כָּל הַיּוֹם וְלֹא לוֹמְדִים כְּלָל","לוֹמְדִים כָּל הַיּוֹם וְאֵין אוֹכְלִים סְעֻדַּת חַג"],0,"מִצְוָה לִשְׂמֹחַ בְּמַאֲכָל וּבְמִשְׁתֶּה בְּיוֹם שֶׁנִּתְּנָה בּוֹ תּוֹרָה, וְעִם זֶה יֵשׁ לְהִתְאַמֵּץ לְהוֹסִיף בְּלִמּוּד הַתּוֹרָה.","פֶּרֶק ע״א, הֲלָכוֹת ו׳, ח׳","חַג הַשָּׁבוּעוֹת"],["מָה אֶחָד הַטְּעָמִים לַמִּנְהָג לֶאֱכֹל מַאַכְלֵי חָלָב בְּשָׁבוּעוֹת?",["כִּי בְּשָׁבוּעוֹת אָסוּר לֶאֱכֹל בָּשָׂר מִן הַתּוֹרָה","כִּי עֲדַיִן לֹא לָמְדוּ כֵּיצַד לִשְׁחֹט שְׁחִיטָה כְּשֵׁרָה","כִּי בִּזְמַן הַקָּצִיר אֵין בְּהֵמוֹת בַּשָּׂדוֹת כְּלָל","כִּי חָלָב מְחַזֵּק אֶת הַגּוּף לַלִּמּוּד בַּלַּיְלָה"],1,"אַחֲרֵי מַתַּן תּוֹרָה נִצְטַוּוּ לִשְׁחֹט לִפְנֵי הָאֲכִילָה, וְעוֹד לֹא לָמְדוּ אֵיךְ – לָכֵן אָכְלוּ מַאַכְלֵי חָלָב. וְעוֹד: הַתּוֹרָה נִמְשְׁלָה לְחָלָב.","פֶּרֶק ע״א, הֲלָכָה ז׳","חַג הַשָּׁבוּעוֹת"],["מָה הַקֶּשֶׁר בֵּין דָּוִד הַמֶּלֶךְ לְחַג הַשָּׁבוּעוֹת?",["בְּשָׁבוּעוֹת נִמְשַׁח דָּוִד לְמֶלֶךְ עַל יְדֵי שְׁמוּאֵל","בְּשָׁבוּעוֹת נִצַּח דָּוִד אֶת גָּלְיָת הַפְּלִשְׁתִּי","בְּשָׁבוּעוֹת בָּנָה דָּוִד אֶת בֵּית הַמִּקְדָּשׁ","זֶה יוֹם פְּטִירָתוֹ, וּמְגִלַּת רוּת מְסַפֶּרֶת עַל יִחוּסוֹ"],3,"שָׁבוּעוֹת הוּא יוֹם הַהִלּוּלָא שֶׁל דָּוִד הַמֶּלֶךְ וְלָכֵן לוֹמְדִים תְּהִלִּים, וּבִמְגִלַּת רוּת נִזְכַּר יִחוּסוֹ. וְעוֹד, רוּת נִכְנְסָה תַּחַת כַּנְפֵי הַשְּׁכִינָה כְּמוֹ יִשְׂרָאֵל בְּיוֹם זֶה.","פֶּרֶק ע״א, הֲלָכוֹת ט׳, י׳","חַג הַשָּׁבוּעוֹת"],["מַדּוּעַ אֵין מִתְעַנִּים וְאֵין מַסְפִּידִים בְּאִסְרוּ חַג?",["כִּי בְּאִסְרוּ חַג קוֹרְאִים תָּמִיד אֶת מְגִלַּת רוּת","כִּי בְּאִסְרוּ חַג נִתְּנָה הַתּוֹרָה לְיִשְׂרָאֵל","כִּי בִּזְמַן הַמִּקְדָּשׁ יֵשׁ קְדֻשָּׁה בְּיוֹם אִסְרוּ חַג","כִּי הוּא עֲדַיִן חֵלֶק מִיְּמֵי הַחַג עַצְמוֹ"],2,"כְּשֶׁהַחַג חָל בְּשַׁבָּת מַקְרִיבִים אֶת עוֹלַת הָרְאִיָּה לְמָחֳרָתוֹ, וּמִכֵּיוָן שֶׁבִּזְמַן הַמִּקְדָּשׁ יֵשׁ קְדֻשָּׁה בְּאִסְרוּ חַג – גַּם הַיּוֹם אֵין מִתְעַנִּים וְאֵין מַסְפִּידִים בּוֹ.","פֶּרֶק ע״א, הֲלָכוֹת י״א, י״ג","חַג הַשָּׁבוּעוֹת"],["מָה פֵּרוּשׁ הַשֵּׁם ״אִסְרוּ חַג״?",["קוֹשְׁרִים אֶת הַחַג לִימֵי הַחֹל שֶׁאַחֲרָיו","אוֹסְרִים לַעֲבֹד בַּיּוֹם שֶׁאַחֲרֵי הַחַג","אוֹסְרִים לֶאֱכֹל וְלִשְׁתּוֹת בַּיּוֹם שֶׁאַחֲרֵי הַחַג","סוֹגְרִים אֶת בֵּית הַכְּנֶסֶת אַחֲרֵי הַחַג"],0,"״עֲשׂוּ אִסּוּר לַחַג״ – אוֹסְרִים (קוֹשְׁרִים) אֶת הַחַג לִימֵי הַחֹל. וְאָמְרוּ חֲכָמִים: הָעוֹשֶׂה אִסּוּר לַחַג בַּאֲכִילָה וּשְׁתִיָּה – כְּאִלּוּ בָּנָה מִזְבֵּחַ וְהִקְרִיב עָלָיו קָרְבָּן.","פֶּרֶק ע״א, הֲלָכוֹת י״ב, י״ד","חַג הַשָּׁבוּעוֹת"],["אֵיזֶה דָּבָר קָרָה בְּשִׁבְעָה עָשָׂר בְּתַמּוּז?",["נִרְצַח גְּדַלְיָה בֶּן אֲחִיקָם הַמַּנְהִיג","נִגְזַר עַל דּוֹר הַמִּדְבָּר אַרְבָּעִים שָׁנָה","נִשְׁתַּבְּרוּ לוּחוֹת הַבְּרִית שֶׁל עַם יִשְׂרָאֵל","חָרְבָה הָעִיר בֵּיתָר שֶׁל בַּר כּוֹכְבָא"],2,"בְּי״ז בְּתַמּוּז נִשְׁתַּבְּרוּ הַלּוּחוֹת, בָּטַל הַתָּמִיד, הֻבְקְעָה הַחוֹמָה, נִשְׂרַף סֵפֶר הַתּוֹרָה וְהָעֳמַד צֶלֶם בַּהֵיכָל. בֵּיתָר וְגֵזֶרַת הַמִּדְבָּר הֵם בְּתִשְׁעָה בְּאָב.","פֶּרֶק ע״ב, הֲלָכָה א׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["עַד מָתַי נִהְיֶה מְחֻיָּבִים בְּצוֹמוֹת הַחֻרְבָּן?",["עַד שֶׁתָּקוּם מְדִינָה יְהוּדִית בְּאֶרֶץ יִשְׂרָאֵל","עַד שֶׁכָּל הַיְּהוּדִים יַחְזְרוּ לִירוּשָׁלַיִם","עַד שֶׁיַּעַבְרוּ אֶלֶף שָׁנִים מִן הַחֻרְבָּן","עַד שֶׁיָּבוֹא מָשִׁיחַ וּבֵית הַמִּקְדָּשׁ יִבָּנֶה"],3,"גַּם בְּיָמֵינוּ מְחֻיָּבִים בַּצּוֹמוֹת, עַד שֶׁיָּבוֹא מְשִׁיחַ צִדְקֵנוּ וּבֵית הַמִּקְדָּשׁ יִבָּנֶה, וְאָז יֵהָפְכוּ לִימֵי שִׂמְחָה.","פֶּרֶק ע״ב, הֲלָכָה ב׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["מָה הַטַּעַם שֶׁמִּתְעַנִּים בְּיָמִים אֵלּוּ?",["כְּדֵי לְעוֹרֵר אֶת הַלְּבָבוֹת לִתְשׁוּבָה","כְּדֵי לְהַרְגִּישׁ אֵיךְ מַרְגִּישִׁים הָרְעֵבִים","כְּדֵי לְהַרְאוֹת לַגּוֹיִם שֶׁאָנוּ חֲזָקִים","כְּדֵי לְהַעֲנִישׁ אֶת עַצְמֵנוּ עַל חֲטָאִים"],0,"מִתְעַנִּים מִפְּנֵי הַצָּרוֹת שֶׁאֵרְעוּ, כְּדֵי לְעוֹרֵר אֶת הַלְּבָבוֹת לִתְשׁוּבָה, וְכָךְ נִזְכֶּה לִגְאֻלָּה וְלִימֵי שִׂמְחָה.","פֶּרֶק ע״ב, הֲלָכָה ג׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["מָה נָכוֹן לְגַבֵּי צוֹם עֲשָׂרָה בְּטֵבֵת?",["אָסוּר בִּרְחִיצָה וּמַתְחִילִים לְהִתְעַנּוֹת בָּעֶרֶב","מֻתָּר בִּרְחִיצָה וּמַתְחִילִים לְהִתְעַנּוֹת בַּבֹּקֶר","אָסוּר בִּנְעִילַת הַסַּנְדָּל כְּמוֹ תִּשְׁעָה בְּאָב","אֵין צָמִים בּוֹ כְּלָל בְּיָמֵינוּ"],1,"צוֹם גְּדַלְיָה, עֲשָׂרָה בְּטֵבֵת וְי״ז בְּתַמּוּז מֻתָּרִים בִּרְחִיצָה, סִיכָה וּנְעִילַת הַסַּנְדָּל, וּמַתְחִילִים לְהִתְעַנּוֹת בָּהֶם בַּבֹּקֶר בִּלְבַד.","פֶּרֶק ע״ב, הֲלָכָה ד׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["מָה קוֹרֶה כְּכָל שֶׁמִּתְקָרְבִים לְתִשְׁעָה בְּאָב?",["מְקִלִּים יוֹתֵר וְיוֹתֵר בְּמִנְהֲגֵי הָאֲבֵלוּת","מַתְחִילִים לִשְׂמֹחַ וְלִרְקֹד לִקְרַאת הַגְּאֻלָּה","אֵין שׁוּם שִׁנּוּי בַּמִּנְהָגִים שֶׁל הַיָּמִים","מוֹסִיפִים מִנְהֲגֵי אֲבֵלוּת חֲמוּרִים יוֹתֵר"],3,"בִּימֵי בֵּין הַמְּצָרִים נוֹהֲגִים מִנְהֲגֵי אֲבֵלוּת, וּכְכָל שֶׁמִּתְקָרְבִים לְתִשְׁעָה בְּאָב מוֹסִיפִים מִנְהָגִים חֲמוּרִים יוֹתֵר.","פֶּרֶק ע״ב, הֲלָכָה ה׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["לָמָּה טוֹב שֶׁלֹּא לְבָרֵךְ שֶׁהֶחֱיָנוּ בְּבֵין הַמְּצָרִים?",["כִּי אָסוּר לֶאֱכֹל פֵּרוֹת בְּיָמִים אֵלּוּ","כִּי הַבְּרָכָה נֶאֱמֶרֶת רַק בְּחַגִּים","כִּי אֵיךְ יְבָרֵךְ שֶׁזָּכָה לְהַגִּיעַ לַזְּמַן הַזֶּה","כִּי אֵין פֵּרוֹת חֲדָשִׁים בַּקַּיִץ"],2,"בְּבִרְכַּת שֶׁהֶחֱיָנוּ מוֹדִים שֶׁהִגַּעְנוּ לַזְּמַן הַזֶּה, וְאֵין זֶה מַתְאִים לִימֵי צַעַר. אֲבָל פְּרִי שֶׁלֹּא יִמָּצֵא אַחֲרֵי תִּשְׁעָה בְּאָב מֻתָּר לֶאֱכֹל וּלְבָרֵךְ עָלָיו.","פֶּרֶק ע״ב, הֲלָכָה ו׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["מָה נָכוֹן לְגַבֵּי בִּרְכַּת שֶׁהֶחֱיָנוּ בִּימֵי בֵּין הַמְּצָרִים?",["אָסוּר לְכֻלָּם, גַּם בִּבְרִית מִילָה","אִשָּׁה מְעֻבֶּרֶת רַשָּׁאִית, וּבִבְרִית מִילָה מְבָרְכִים","רַק בְּפִדְיוֹן הַבֵּן, וְלֹא עַל פְּרִי","מְבָרְכִים רַק עַל בֶּגֶד חָדָשׁ"],1,"אִשָּׁה מְעֻבֶּרֶת, חוֹלֶה וְקָטָן שֶׁאֵינוֹ מֵבִין רַשָּׁאִים לֶאֱכֹל פְּרִי חָדָשׁ וּלְבָרֵךְ שֶׁהֶחֱיָנוּ. וּבִבְרִית מִילָה וּבְפִדְיוֹן הַבֵּן מְבָרְכִים שֶׁהֶחֱיָנוּ.","פֶּרֶק ע״ב, הֲלָכָה ז׳-ח׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["מָה נוֹהֲגִים בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים בִּימֵי בֵּין הַמְּצָרִים?",["צָמִים בְּכָל יוֹם שֵׁנִי וַחֲמִישִׁי","לֹא לוֹמְדִים תּוֹרָה בְּכָל הַשָּׁבוּעוֹת","רוֹקְדִים בִּמְחוֹלוֹת כְּדֵי לְהִתְחַזֵּק בְּשִׂמְחָה","לֹא מִסְתַּפְּרִים וְלֹא מִתְגַּלְּחִים כָּל הַיָּמִים"],3,"בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים לֹא מִסְתַּפְּרִים וְלֹא מִתְגַּלְּחִים כָּל יְמֵי בֵּין הַמְּצָרִים. רִקּוּדִים וּמְחוֹלוֹת נֶאֶסְרוּ, וְיֵשׁ מַחְמִירִים שֶׁלֹּא לִשְׁמֹעַ כְּלֵי זֶמֶר.","פֶּרֶק ע״ב, הֲלָכָה ט׳-י׳","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["מָה נוֹהֲגִים לְגַבֵּי חֲתֻנּוֹת בִּימֵי בֵּין הַמְּצָרִים?",["מִתְחַתְּנִים רַק בְּלִי כְּלֵי זֶמֶר","אֵין שׁוּם הַגְבָּלָה עַל חֲתֻנּוֹת","נוֹהֲגִים שֶׁלֹּא לְהִתְחַתֵּן בְּיָמִים אֵלּוּ","מִתְחַתְּנִים רַק בְּיוֹם שִׁשִּׁי בַּבֹּקֶר"],2,"נוֹהֲגִים שֶׁלֹּא לְהִתְחַתֵּן כָּל יְמֵי בֵּין הַמְּצָרִים.","פֶּרֶק ע״ב, הֲלָכָה י״א","תַּעֲנִיּוֹת הַחֻרְבָּן וּבֵין הַמְּצָרִים"],["הִתְחִילוּ לִבְנוֹת בַּיִת לִפְנֵי רֹאשׁ חֹדֶשׁ אָב, וַעֲצִירָה תִּגְרֹם הֶפְסֵד כַּסְפִּי גָּדוֹל. מָה הַדִּין?",["מֻתָּר לְהַמְשִׁיךְ לִבְנוֹת כְּדֵי שֶׁלֹּא יִגָּרֵם הֶפְסֵד","חַיָּבִים לַעֲצֹר מִיָּד עַד אַחֲרֵי תִּשְׁעָה בְּאָב","מֻתָּר רַק אִם הַבִּנְיָן הוּא בֵּית חַתְנוּת","אָסוּר, אֲבָל מֻתָּר לִפְתֹּחַ עֵסֶק חָדָשׁ"],0,"אִם הִתְחִילוּ כְּבָר לִבְנוֹת וְיִגָּרֵם הֶפְסֵד כַּסְפִּי גָּדוֹל, מֻתָּר לְהַמְשִׁיךְ. וּלְצֹרֶךְ מִצְוָה הַכֹּל מֻתָּר.","פֶּרֶק ע״ב, הֲלָכוֹת י״ב-י״ג","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["לָמָּה נִקְרֵאת הַשַּׁבָּת שֶׁלִּפְנֵי תִּשְׁעָה בְּאָב שַׁבַּת ״חֲזוֹן״?",["עַל שֵׁם הַפָּסוּק הָרִאשׁוֹן בַּפָּרָשָׁה שֶׁל אוֹתוֹ שָׁבוּעַ","עַל שֵׁם הַמִּלִּים הַפּוֹתְחוֹת אֶת הַהַפְטָרָה שֶׁקּוֹרְאִים","כִּי בְּשַׁבָּת זוֹ רוֹאִים חֲזוֹן בַּשָּׁמַיִם בַּלַּיְלָה","עַל שֵׁם הַנָּבִיא יִרְמְיָהוּ שֶׁנִּקְרָא חוֹזֶה"],1,"הַהַפְטָרָה פּוֹתַחַת בַּמִּלִּים ״חֲזוֹן יְשַׁעְיָהוּ בֶן אָמוֹץ״ (יְשַׁעְיָהוּ א׳, א׳).","פֶּרֶק ע״ב, הֲלָכָה י״ד","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["תִּשְׁעָה בְּאָב חָל בְּיוֹם חֲמִישִׁי. כַּמָּה יָמִים נוֹהֲגִים דִּינֵי הַשָּׁבוּעַ?",["חֲמִשָּׁה יָמִים, מִמּוֹצָאֵי שַׁבָּת עַד אַחֲרֵי הַתַּעֲנִית","רַק בְּיוֹם תִּשְׁעָה בְּאָב עַצְמוֹ וְלֹא לְפָנָיו","שִׁבְעָה יָמִים שְׁלֵמִים, מִיּוֹם חֲמִישִׁי שֶׁלִּפְנֵי כֵן","שְׁלוֹשָׁה יָמִים, מִיּוֹם שֵׁנִי עַד הַתַּעֲנִית"],0,"הַשָּׁבוּעַ הוּא מִמּוֹצָאֵי שַׁבַּת חֲזוֹן עַד אַחֲרֵי הַתַּעֲנִית, וְלָכֵן כְּשֶׁהִיא בְּיוֹם חֲמִישִׁי, הַדִּינִים נוֹהֲגִים חֲמִשָּׁה יָמִים.","פֶּרֶק ע״ב, הֲלָכָה ט״ו","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["דָּן רוֹצֶה לִקְנוֹת חֻלְצָה חֲדָשָׁה בַּשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב, וְלִלְבֹּשׁ אוֹתָהּ אַחֲרֵי. מָה הַדִּין?",["מֻתָּר, כִּי הוּא יִלְבַּשׁ אוֹתָהּ רַק אַחֲרֵי הַתַּעֲנִית","מֻתָּר לִקְנוֹת, אֲבָל רַק אִם הִיא בְּצֶבַע שָׁחוֹר","אָסוּר, גַּם אִם יִלְבַּשׁ אוֹתָהּ רַק אַחֲרֵי תִּשְׁעָה בְּאָב","מֻתָּר לִקְנוֹת וְגַם לִלְבֹּשׁ, כִּי זֶה רַק חֻלְצָה"],2,"אָסוּר לִקְנוֹת בְּגָדִים חֲדָשִׁים בַּשָּׁבוּעַ הַזֶּה, אֲפִלּוּ אִם הַכַּוָּנָה לִלְבֹּשׁ אוֹתָם רַק אַחֲרֵי תִּשְׁעָה בְּאָב.","פֶּרֶק ע״ב, הֲלָכָה ט״ז","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["מַדּוּעַ אָסוּר לִלְבֹּשׁ בְּגָדִים מְכֻבָּסִים בַּשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב?",["כִּי הַבְּגָדִים הַמְּכֻבָּסִים יְקָרִים וְחָבָל לְלַכְלֵךְ אוֹתָם","שֶׁלֹּא נִשְׂמַח מֵהָרַעֲנַנּוּת וְנַסִּיחַ דַּעְתֵּנוּ מֵהָאֲבֵלוּת","כִּי בַּיָּמִים הָאֵלֶּה אֵין מַיִם לְכַבֵּס בְּגָדִים","כִּי צָרִיךְ לִשְׁמֹר אוֹתָם לִכְבוֹד שַׁבַּת נַחֲמוּ"],1,"הַטַּעַם הוּא שֶׁלֹּא נִשְׂמַח מִתְּחוּשַׁת הָרַעֲנַנּוּת שֶׁל הַבֶּגֶד הַמְּכֻבָּס וְנַסִּיחַ אֶת דַּעְתֵּנוּ מֵהָאֲבֵלוּת. גַּם לְכַבֵּס אָסוּר, אֲפִלּוּ כְּשֶׁיֵּשׁ רַק בֶּגֶד אֶחָד.","פֶּרֶק ע״ב, הֲלָכוֹת י״ז-י״ח","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["לְפִי מִנְהַג קְהִלּוֹת הָאַשְׁכְּנַזִּים, מָתַי מַחְמִירִים בְּדִינֵי הַבְּגָדִים וְהַכְּבִיסָה?",["מִשִּׁבְעָה עָשָׂר בְּתַמּוּז, כְּמוֹ בְּתִסְפֹּרֶת","מֵרֹאשׁ חֹדֶשׁ אָב וְעַד אַחֲרֵי הַתַּעֲנִית","רַק מִשַּׁבַּת חֲזוֹן עַצְמָהּ וְעַד הַתַּעֲנִית","מִשְּׁמוֹנָה בְּאָב בַּבֹּקֶר וְעַד מוֹצָאֵי הַתַּעֲנִית"],1,"מִנְהַג קְהִלּוֹת הָאַשְׁכְּנַזִּים וְחֵלֶק מִקְּהִלּוֹת הַסְּפָרַדִּים לְהַחְמִיר מֵרֹאשׁ חֹדֶשׁ אָב וְעַד אַחֲרֵי הַתַּעֲנִית.","פֶּרֶק ע״ב, הֲלָכָה י״ט","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["בְּאֶרֶץ יִשְׂרָאֵל חַם, וְאִי אֶפְשָׁר בְּלִי לְהַחְלִיף בְּגָדִים. מָה עוֹשִׂים?",["לוֹבְשִׁים אֶת הַבְּגָדִים שָׁעָה קַלָּה לִפְנֵי זְמַן הָאִסּוּר","מֻתָּר לְכַבֵּס בַּשָּׁבוּעַ הַזֶּה, כִּי בְּאֶרֶץ יִשְׂרָאֵל חַם","מֻתָּר לִלְבֹּשׁ רַק בְּגָדִים חֲדָשִׁים שֶׁלֹּא כֻּבְּסוּ","אָסוּר לְהַחְלִיף בְּגָדִים כְּלָל עַד אַחֲרֵי הַתַּעֲנִית"],0,"לוֹבְשִׁים אֶת הַבְּגָדִים הַדְּרוּשִׁים לְשָׁעָה קַלָּה לִפְנֵי תְּחִלַּת זְמַן הָאִסּוּר, וְאָז מֻתָּר לִלְבֹּשׁ אוֹתָם בִּימֵי הָאֲבֵלוּת.","פֶּרֶק ע״ב, הֲלָכָה כ׳","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["הַאִם מֻתָּר לְכַבֵּס בִּגְדֵי יְלָדִים קְטַנִּים בַּיָּמִים הָאֵלֶּה?",["אָסוּר לְכַבֵּס, אֲפִלּוּ בִּגְדֵי תִּינוֹקוֹת קְטַנִּים","נוֹהֲגִים לְהָקֵל, כִּי הֵם מִתְלַכְלְכִים בִּתְדִירוּת גְּבוֹהָה","מֻתָּר רַק אִם אֵין לַתִּינוֹק שׁוּם בֶּגֶד","מֻתָּר רַק בְּיוֹם שִׁשִּׁי לִכְבוֹד הַשַּׁבָּת"],1,"גַּם בִּגְדֵי יְלָדִים אָסוּר לְכַבֵּס, אַךְ נוֹהֲגִים לְהָקֵל בְּבִגְדֵי יְלָדִים קְטַנִּים שֶׁמִּתְלַכְלְכִים בִּתְדִירוּת גְּבוֹהָה.","פֶּרֶק ע״ב, הֲלָכָה כ״א","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["שַׂעֲרוֹת הַשָּׂפָם שֶׁל סַבָּא מַפְרִיעוֹת לוֹ לֶאֱכֹל, בַּשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב. מָה הַדִּין?",["אָסוּר לְגַלֵּחַ שׁוּם שַׂעֲרָה עַד אַחֲרֵי הַתַּעֲנִית","מֻתָּר לְהִסְתַּפֵּר אִם הַשֵּׂעָר אָרֹךְ מְאוֹד","מֻתָּר רַק לְסַפֵּר יְלָדִים קְטַנִּים, לֹא גְּדוֹלִים","מֻתָּר לְגַלֵּחַ אֶת הַשָּׂפָם אִם הוּא מַפְרִיעַ לֶאֱכֹל"],3,"אָסוּר לְהִסְתַּפֵּר וּלְהִתְגַּלֵּחַ, אַךְ מֻתָּר לְגַלֵּחַ שַׂעֲרוֹת שָׂפָם אוֹ זָקָן הַמַּפְרִיעוֹת לָאֲכִילָה. וְאָסוּר לַגְּדוֹלִים לְסַפֵּר אֶת הַקְּטַנִּים.","פֶּרֶק ע״ב, הֲלָכָה כ״ב","הַשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב"],["מָה הַטַּעַם שֶׁיֵּשׁ מַחְמִירִים בְּבָשָׂר וְיַיִן כְּבָר מִי״ז בְּתַמּוּז?",["כִּי בּוֹ מַתְחִילִים לִקְרֹא אֶת מְגִלַּת אֵיכָה בַּבַּיִת","כִּי בּוֹ נוֹהֲגִים לְהִתְעַנּוֹת שְׁלוֹשָׁה יָמִים רְצוּפִים","כִּי בּוֹ בָּטְלוּ קָרְבַּן הַתָּמִיד וְנִסּוּךְ הַיַּיִן","כִּי בּוֹ נִבְנָה בֵּית הַמִּקְדָּשׁ הַשֵּׁנִי בִּירוּשָׁלַיִם"],2,"יֵשׁ שֶׁמַּחְמִירִים מִי״ז בְּתַמּוּז, מִפְּנֵי שֶׁבּוֹ בָּטְלוּ קָרְבַּן הַתָּמִיד וְנִסּוּךְ הַיַּיִן. וְכָל אֶחָד יִנְהַג כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק ע״ב, הֲלָכָה כ״ג","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["מָה הַדִּין בְּמַיִם שֶׁל מְרַק עוֹף בַּיָּמִים הָאֵלּוּ?",["כֻּלָּם מַתִּירִים, כִּי אֵין בַּמָּרָק חֲתִיכוֹת בָּשָׂר כְּלָל","יֵשׁ מַתִּירִים וְיֵשׁ אוֹסְרִים, וְכָל אֶחָד כְּמִנְהַג אֲבוֹתָיו","כֻּלָּם אוֹסְרִים, וַאֲפִלּוּ קְטַנִּים אֲסוּרִים לִטְעֹם מִמֶּנּוּ","מֻתָּר רַק אִם מוֹסִיפִים לַמָּרָק הַרְבֵּה יְרָקוֹת"],1,"יֵשׁ אוֹמְרִים שֶׁמֻּתָּר לֶאֱכֹל תַּבְשִׁיל שֶׁהִתְבַּשֵּׁל עִם בָּשָׂר, וְיֵשׁ אוֹמְרִים שֶׁגַּם תַּבְשִׁיל כָּזֶה כָּלוּל בָּאִסּוּר, וְכָל אֶחָד יִנְהַג כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק ע״ב, הֲלָכָה כ״ה","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["מָה עוֹשִׂים עִם יֵין הַהַבְדָּלָה בִּימֵי הָאִסּוּר?",["מֻתָּר לִשְׁתּוֹתוֹ, וְיֵשׁ נוֹתְנִים אוֹתוֹ לִילָדִים קְטַנִּים","שׁוֹפְכִים אוֹתוֹ, כִּי אָסוּר לִשְׁתּוֹת יַיִן בְּיָמִים אֵלּוּ","מַבְדִּילִים בְּלִי כּוֹס כְּלָל, רַק בִּבְרָכַת הַנֵּר","שׁוֹמְרִים אוֹתוֹ בַּמְּקָרֵר עַד אַחֲרֵי תִּשְׁעָה בְּאָב"],0,"מֻתָּר לִשְׁתּוֹת אֶת הַיַּיִן שֶׁל הַהַבְדָּלָה, וְיֵשׁ נוֹהֲגִים לָתֵת לִילָדִים קְטַנִּים לִשְׁתּוֹת אוֹתוֹ.","פֶּרֶק ע״ב, הֲלָכָה כ״ו","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["מִי מֻתָּר לוֹ לֶאֱכֹל בָּשָׂר בִּסְעוּדַת בְּרִית מִילָה?",["רַק אֲבִי הַתִּינוֹק וְהַמּוֹהֵל, וְלֹא שְׁאָר הָאוֹרְחִים","רַק הַסַּנְדָּק, כִּי הוּא מַחֲזִיק אֶת הַתִּינוֹק","כָּל הַמִּשְׁתַּתְּפִים בַּסְּעוּדָה, כִּי הִיא סְעוּדַת מִצְוָה","אַף אֶחָד, כִּי גַּם בִּבְרִית אָסוּר לֶאֱכֹל בָּשָׂר"],2,"מֻתָּר לְכָל הַמִּשְׁתַּתְּפִים בִּסְעוּדַת מִצְוָה (כִּסְעוּדַת בְּרִית מִילָה, פִּדְיוֹן הַבֵּן וְסִיּוּם מַסֶּכֶת) לֶאֱכֹל בָּשָׂר וְלִשְׁתּוֹת יַיִן.","פֶּרֶק ע״ב, הֲלָכָה כ״ז","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["חוֹלֶה שֶׁצָּרִיךְ לֶאֱכֹל בָּשָׂר – מָה עָדִיף שֶׁיֹּאכַל?",["בְּשַׂר בְּהֵמָה, כִּי הוּא מְחַזֵּק יוֹתֵר","רַק מְרַק בָּשָׂר, בְּלִי חֲתִיכוֹת בָּשָׂר","דָּגִים בִּלְבַד, וּלְעוֹלָם לֹא שׁוּם בָּשָׂר","בְּשַׂר עוֹף, וְלֹא בְּשַׂר בְּהֵמָה"],3,"חוֹלֶה, וְכֵן מִי שֶׁמִּסִּבּוֹת בְּרִיאוּתִיּוֹת צָרִיךְ לֶאֱכֹל בָּשָׂר – עָדִיף שֶׁיֹּאכַל בְּשַׂר עוֹף וְלֹא בְּשַׂר בְּהֵמָה.","פֶּרֶק ע״ב, הֲלָכָה כ״ח","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["מִי יָכוֹל לְהִתְרַחֵץ בְּמַיִם פּוֹשְׁרִים בִּימֵי אִסּוּר הָרְחִיצָה?",["יֶלֶד שֶׁרוֹצֶה לְהִתְקָרֵר בַּיּוֹם הַחַם","פּוֹעֵל שֶׁעוֹבֵד עֲבוֹדָה גּוּפָנִית וּמַזִּיעַ","מִי שֶׁאוֹהֵב לְהִתְפַּנֵּק בְּמַקְלַחַת אֲרֻכָּה","כָּל מִי שֶׁמַּרְגִּישׁ קְצָת מְשֻׁעְמָם"],1,"הָרְחִיצָה שֶׁנֶּאֶסְרָה הִיא רְחִיצָה לְתַעֲנוּג, וְלָכֵן פּוֹעֲלִים שֶׁעוֹבְדִים וּמְזִיעִים, וּמִי שֶׁרָגִיל לְהִתְרַחֵץ כָּל יוֹם לְנִקָּיוֹן אוֹ לִרְפוּאָה – יְכוֹלִים לְהִתְרַחֵץ בְּמַיִם פּוֹשְׁרִים. וְלִכְבוֹד שַׁבָּת מֻתָּר גַּם בְּמַיִם חַמִּים.","פֶּרֶק ע״ב, הֲלָכָה כ״ט-ל׳","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["שְׂחִיָּה בַּבְּרֵכָה לְשֵׁם הֲנָאָה וּבִלּוּי – מֵאֵימָתַי הִיא אֲסוּרָה?",["רַק בְּיוֹם תִּשְׁעָה בְּאָב עַצְמוֹ","רַק בַּשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב","מֵרֹאשׁ חֹדֶשׁ אָב, לְפִי כָּל הַמִּנְהָגִים","מִט״ו בְּאָב וְעַד רֹאשׁ הַשָּׁנָה"],2,"שְׂחִיָּה שֶׁמַּטְּרָתָהּ הֲנָאָה וּבִלּוּי אֲסוּרָה מֵרֹאשׁ חֹדֶשׁ. שְׂחִיָּה לִשְׁמִירַת הַבְּרִיאוּת – לַסְּפָרַדִּים אֲסוּרָה בַּשָּׁבוּעַ שֶׁחָל בּוֹ תִּשְׁעָה בְּאָב, וְלָאַשְׁכְּנַזִּים מֵרֹאשׁ חֹדֶשׁ.","פֶּרֶק ע״ב, הֲלָכָה ל״א","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["אֵיזוֹ הַפְטָרָה קוֹרְאִים בַּשַּׁבָּת הַסְּמוּכָה לְתִשְׁעָה בְּאָב?",["״נַחֲמוּ נַחֲמוּ עַמִּי״, בְּמַנְגִּינָה שְׂמֵחָה בִּמְיֻחָד","״שִׁירַת דְּבוֹרָה״, כִּי הִיא מְסַפֶּרֶת עַל נִצָּחוֹן","אֵין קוֹרְאִים כְּלָל הַפְטָרָה בְּשַׁבָּת זוֹ","״חֲזוֹן יְשַׁעְיָהוּ״, וְאַשְׁכְּנַזִּים קוֹרְאִים אוֹתָהּ בְּמַנְגִּינַת אֵיכָה"],3,"בִּשְׁלוֹשׁ הַשַּׁבָּתוֹת שֶׁבֵּין י״ז בְּתַמּוּז לְתִשְׁעָה בְּאָב קוֹרְאִים הַפְטָרוֹת הַחֻרְבָּן. בַּשַּׁבָּת הַסְּמוּכָה מַפְטִירִים בְּ״חֲזוֹן יְשַׁעְיָהוּ״, וּבִקְהִלּוֹת הָאַשְׁכְּנַזִּים בְּמַנְגִּינַת אֵיכָה. וְלוֹבְשִׁים בָּהּ בִּגְדֵי שַׁבָּת כָּרָגִיל.","פֶּרֶק ע״ב, הֲלָכָה ל״ב-ל״ג","תִּשְׁעַת הַיָּמִים וְשַׁבְּתוֹת בֵּין הַמְּצָרִים"],["מָה מֻתָּר לֶאֱכֹל בַּסְּעוּדָה הַמַּפְסֶקֶת בְּלִי הַגְבָּלָה?",["פֵּרוֹת, יְרָקוֹת וּגְבִינוֹת שֶׁאֵינָם מְבֻשָּׁלִים","כָּל תַּבְשִׁיל חַם שֶׁיֵּשׁ בַּבַּיִת","שְׁנֵי תַּבְשִׁילִים לְפָחוֹת וּבָשָׂר מְבֻשָּׁל","רַק לֶחֶם יָבֵשׁ וּמַיִם קָרִים"],0,"בַּסְּעוּדָה הַמַּפְסֶקֶת אוֹכְלִים רַק תַּבְשִׁיל אֶחָד, אֲבָל מַאֲכָלִים שֶׁאֵינָם מְבֻשָּׁלִים, כְּמוֹ פֵּרוֹת, יְרָקוֹת וּגְבִינוֹת, מֻתָּרִים בְּלִי הַגְבָּלָה.","פֶּרֶק ע״ג, הֲלָכָה א׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["לָמָּה לֹא יוֹשְׁבִים שְׁלוֹשָׁה יַחַד בַּסְּעוּדָה הַמַּפְסֶקֶת?",["כְּדֵי שֶׁיִּהְיֶה מָקוֹם לְכֻלָּם לָשֶׁבֶת","כְּדֵי שֶׁלֹּא יִתְחַיְּבוּ בְּבִרְכַּת זִמּוּן","כִּי אָסוּר לְדַבֵּר בִּזְמַן הָאֲבֵלוּת","כִּי הַשֻּׁלְחָן קָטָן מִדַּי לִשְׁלוֹשָׁה"],1,"מַקְפִּידִים שֶׁלֹּא יֵשְׁבוּ שְׁלוֹשָׁה בְּאוֹתוֹ מָקוֹם כְּדֵי שֶׁלֹּא יִתְחַיְּבוּ בְּזִמּוּן, וְכָל אֶחָד מְבָרֵךְ לְעַצְמוֹ.","פֶּרֶק ע״ג, הֲלָכָה ב׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["אֵיזוֹ סְעוּדָה נֶחְשֶׁבֶת לַסְּעוּדָה הַמַּפְסֶקֶת?",["כָּל סְעוּדָה שֶׁאוֹכְלִים בְּעֶרֶב תִּשְׁעָה בְּאָב","סְעוּדָה שֶׁלִּפְנֵי חֲצוֹת הַיּוֹם בְּעֶרֶב הַצּוֹם","סְעוּדָה אַחֲרֵי חֲצוֹת שֶׁאֵין אַחֲרֶיהָ סְעוּדָה","רַק סְעוּדַת הַבֹּקֶר שֶׁל יוֹם שְׁמִינִי"],2,"רַק סְעוּדָה שֶׁאַחֲרֵי חֲצוֹת הַיּוֹם וְאֵין אַחֲרֶיהָ עוֹד סְעוּדָה הִיא הַמַּפְסֶקֶת. אִם מְתַכְנְנִים סְעוּדָה נוֹסֶפֶת, אוֹכְלִים כָּרָגִיל.","פֶּרֶק ע״ג, הֲלָכָה ג׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["מִמָּתַי נוֹהֲגִים לִלְמֹד רַק דְּבָרִים הַמֻּתָּרִים בְּתִשְׁעָה בְּאָב?",["מִתְּחִלַּת חֹדֶשׁ אָב, מֵרֹאשׁ הַחֹדֶשׁ","רַק מִשְּׁקִיעַת הַחַמָּה בְּעֶרֶב הַצּוֹם","רַק בַּבֹּקֶר שֶׁל תִּשְׁעָה בְּאָב עַצְמוֹ","לְאַחַר חֲצוֹת הַיּוֹם שֶׁל שְׁמִינִי בְּאָב"],3,"לְאַחַר חֲצוֹת יוֹם שְׁמִינִי בְּאָב נָהֲגוּ לִלְמֹד רַק דְּבָרִים שֶׁמֻּתָּר לִלְמֹד בְּתִשְׁעָה בְּאָב עַצְמוֹ.","פֶּרֶק ע״ג, הֲלָכָה ד׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["בַּמֶּה תִּשְׁעָה בְּאָב חָמוּר מִשְּׁאָר תַּעֲנִיּוֹת הַחֻרְבָּן?",["יֵשׁ בּוֹ חֲמִשָּׁה עִנּוּיִים וְלֹא רַק אֲכִילָה","אָסוּר בּוֹ לְדַבֵּר עִם אֲנָשִׁים כְּלָל","צָמִים בּוֹ יוֹמַיִם שְׁלֵמִים בְּרֶצֶף","אָסוּר בּוֹ לָצֵאת מִן הַבַּיִת"],0,"בְּתִשְׁעָה בְּאָב יֵשׁ חֲמִשָּׁה עִנּוּיִים: אֲכִילָה וּשְׁתִיָּה, רְחִיצָה, סִיכָה, נְעִילַת הַסַּנְדָּל וְתַשְׁמִישׁ הַמִּטָּה.","פֶּרֶק ע״ג, הֲלָכָה ה׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["יוֹלֶדֶת שֶׁעָבַר שָׁבוּעַ מֵהַלֵּדָה – לְפִי הַ״יֵּשׁ אוֹמְרִים״ בַּסֵּפֶר, מָה דִּינָהּ?",["אֲסוּרָה לָצוּם עַד סוֹף הַחֹדֶשׁ","חַיֶּבֶת לָצוּם כְּמוֹ כָּל אִשָּׁה","רַשָּׁאִית לָצוּם אִם הִיא מַרְגִּישָׁה חֲזָקָה","צָמָה רַק עַד חֲצוֹת הַיּוֹם"],2,"יוֹלֶדֶת עַד חֹדֶשׁ פְּטוּרָה מֵהַתַּעֲנִית, וְיֵשׁ אוֹמְרִים שֶׁאַחֲרֵי שָׁבוּעַ, אִם הִיא מַרְגִּישָׁה חֲזָקָה מַסְפִּיק, רַשָּׁאִית לָצוּם.","פֶּרֶק ע״ג, הֲלָכָה ו׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["חוֹלֶה שֶׁאֵין בּוֹ סַכָּנָה – מָה הַמִּנְהָג בְּתִשְׁעָה בְּאָב?",["פָּטוּר, וְאוֹכֵל כָּרָגִיל כָּל הַיּוֹם","מִתְעַנֶּה כְּפִי יְכָלְתּוֹ בְּלִי לְהַזִּיק לְגוּפוֹ","חַיָּב לָצוּם כָּל הַיּוֹם, וּבְלִי תְּרוּפוֹת","צָם רַק אִם רוֹפֵא מַרְשֶׁה לוֹ"],1,"חוֹלִים פְּטוּרִים מֵעִקַּר הַדִּין, אֲבָל הַמִּנְהָג שֶׁיִּתְעַנּוּ כְּפִי יְכָלְתָּם בְּלִי לְהַזִּיק לְגוּפָם. זְקֵנִים וּתְשׁוּשִׁים שֶׁהַצּוֹם מְצַעֵר אוֹתָם מְאֹד אֵינָם מִתְעַנִּים כְּלָל, וּמֻתָּר לָהֶם לִבְלֹעַ תְּרוּפוֹת.","פֶּרֶק ע״ג, הֲלָכָה ז׳-ח׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["מָה הַדִּין בִּמְעֻבָּרוֹת וּמְנִיקוֹת בְּתִשְׁעָה בְּאָב?",["פְּטוּרוֹת לְגַמְרֵי מֵהַתַּעֲנִית, כְּמוֹ הַקְּטַנִּים","צָמוֹת רַק מִסְפַּר שָׁעוֹת כְּמוֹ הַיְּלָדִים","צָמוֹת עַד חֲצוֹת הַיּוֹם וְאַחַר כָּךְ אוֹכְלוֹת","צְרִיכוֹת לְהִתְעַנּוֹת, וּבַחֲשַׁשׁ סַכָּנָה יִתְיַעֲצוּ עִם תַּלְמִיד חָכָם"],3,"מְעֻבָּרוֹת וּמְנִיקוֹת צְרִיכוֹת לְהִתְעַנּוֹת, וְאִם יֵשׁ חֲשַׁשׁ סַכָּנָה יִתְיַעֲצוּ עִם תַּלְמִיד חָכָם. קְטַנִּים פְּטוּרִים, וּמְחַנְּכִים אוֹתָם לְהִתְעַנּוֹת מִסְפַּר שָׁעוֹת.","פֶּרֶק ע״ג, הֲלָכָה ט׳-י׳","תַּעֲנִית תִּשְׁעָה בְּאָב"],["מָתַי מֻתָּר לִרְחֹץ בְּתִשְׁעָה בְּאָב?",["כְּשֶׁחַם מְאֹד בַּחוּץ וְרוֹצִים לְהִתְרַעְנֵן","רַק אֶת הַפָּנִים, בְּכָל זְמַן","כַּאֲשֶׁר הַמַּטָּרָה הִיא לְהָסִיר לִכְלוּךְ","אַחֲרֵי חֲצוֹת הַיּוֹם, כְּדֵי לְהַרְגִּישׁ טוֹב"],2,"אָסוּר לִרְחֹץ, אֲפִלּוּ רַק יָדַיִם אוֹ פָּנִים, וּבְנְטִילַת הַבֹּקֶר נוֹטְלִים עַד קִשְׁרֵי הָאֶצְבָּעוֹת. אֲבָל כְּדֵי לְהָסִיר לִכְלוּךְ מֻתָּר לִרְחֹץ.","פֶּרֶק ע״ג, הֲלָכָה י״א-י״ג","תַּעֲנִית תִּשְׁעָה בְּאָב"],["מָה נָכוֹן בְּתִשְׁעָה בְּאָב?",["נַעֲלֵי עוֹר מֻתָּרוֹת, וְיוֹשְׁבִים כָּרָגִיל כָּל הַיּוֹם","כָּל נַעַל אֲסוּרָה, וְיוֹשְׁבִים נָמוּךְ עַד הַלַּיְלָה","סַנְדְּלֵי עוֹר מֻתָּרִים, וְיוֹשְׁבִים נָמוּךְ רַק בַּבֹּקֶר","נַעֲלֵי גּוּמִי מֻתָּרוֹת, וְיוֹשְׁבִים נָמוּךְ עַד חֲצוֹת"],3,"אָסוּר לִנְעֹל נַעֲלֵי עוֹר, וּמֻתָּר לִנְעֹל גּוּמִי אוֹ בַּד. מֵהַסְּעוּדָה הַמַּפְסֶקֶת וְעַד חֲצוֹת יוֹם תִּשְׁעָה בְּאָב יוֹשְׁבִים עַל הַקַּרְקַע אוֹ עַל כִּסֵּא נָמוּךְ, כְּמוֹ אֲבֵלִים.","פֶּרֶק ע״ג, הֲלָכָה י״ד-ט״ו","תַּעֲנִית תִּשְׁעָה בְּאָב"],["מִי שֶׁשָּׁאֲלוּ בִּשְׁלוֹמוֹ בְּתִשְׁעָה בְּאָב, מַה יַּעֲשֶׂה?",["מֵשִׁיב בְּשָׂפָה רָפָה וּבְכֹבֶד רֹאשׁ","מֵשִׁיב בְּקוֹל רָם וּבְשִׂמְחָה גְּדוֹלָה","אָסוּר לוֹ לְהָשִׁיב שׁוּם תְּשׁוּבָה","מֵשִׁיב רַק אַחֲרֵי חֲצוֹת הַיּוֹם"],0,"אֵין שׁוֹאֲלִים שָׁלוֹם בְּתִשְׁעָה בְּאָב, אֲבָל מִי שֶׁשָּׁאֲלוּ בִּשְׁלוֹמוֹ מֵשִׁיב בְּשָׂפָה רָפָה וּבְכֹבֶד רֹאשׁ.","פֶּרֶק ע״ג, הֲלָכָה ט״ז","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["מָה נֶאֱמַר עַל הָעוֹשֶׂה מְלָאכָה בְּתִשְׁעָה בְּאָב?",["מְקַבֵּל שָׂכָר כָּפוּל עַל עֲבוֹדָתוֹ","חַיָּב לְהִתְעַנּוֹת יוֹם נוֹסָף אַחֲרָיו","אֵינוֹ רוֹאֶה סִימַן בְּרָכָה מֵאוֹתָהּ מְלָאכָה","צָרִיךְ לָתֵת אֶת כָּל הָרֶוַח לִצְדָקָה"],2,"בְּמָקוֹם שֶׁנָּהֲגוּ לַעֲבֹד הַדָּבָר מֻתָּר, אַךְ הָעוֹשֶׂה מְלָאכָה אֵינוֹ רוֹאֶה סִימַן בְּרָכָה. וּמִי שֶׁחַיָּב לָלֶכֶת לָעֲבוֹדָה – יִשְׁאַל חָכָם.","פֶּרֶק ע״ג, הֲלָכָה י״ז","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["מַדּוּעַ אָסוּר לִלְמֹד תּוֹרָה בְּתִשְׁעָה בְּאָב?",["מִפְּנֵי שֶׁהַסְּפָרִים נִשְׂרְפוּ בְּבֵית הַמִּקְדָּשׁ","מִפְּנֵי שֶׁלִּמּוּד הַתּוֹרָה מְשַׂמֵּחַ אֶת הַלֵּב","מִפְּנֵי שֶׁצְּרִיכִים לָנוּחַ מֵהַתַּעֲנִית כָּל הַיּוֹם","מִפְּנֵי שֶׁבָּתֵּי הַכְּנֶסֶת סְגוּרִים בַּיּוֹם הַזֶּה"],1,"לִמּוּד תּוֹרָה מְשַׂמֵּחַ, שֶׁנֶּאֱמַר ״פִּקּוּדֵי ה׳ יְשָׁרִים, מְשַׂמְּחֵי לֵב״. מֻתָּר לִלְמֹד דְּבָרִים הַקְּשׁוּרִים לַתַּעֲנִית אוֹ לַחֻרְבָּן.","פֶּרֶק ע״ג, הֲלָכָה י״ח","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["מָה נָכוֹן לְגַבֵּי תְּפִלּוֹת תִּשְׁעָה בְּאָב?",["אֵיכָה בַּלַּיְלָה, וְאַשְׁכְּנַזִּים מְנִיחִים תְּפִלִּין בְּמִנְחָה","אֵיכָה בַּבֹּקֶר, וְכֻלָּם מְנִיחִים תְּפִלִּין בְּשַׁחֲרִית","קִינוֹת רַק בַּלַּיְלָה, וְאֵין מְנִיחִים תְּפִלִּין כְּלָל","אֵיכָה בְּמִנְחָה, וְאַשְׁכְּנַזִּים מְנִיחִים תְּפִלִּין בַּלַּיְלָה"],0,"אַחֲרֵי עַרְבִית קוֹרְאִים אֵיכָה וְאוֹמְרִים קִינוֹת, וּבַבֹּקֶר קִינוֹת אַחֲרֵי קְרִיאַת הַתּוֹרָה. הָאַשְׁכְּנַזִּים וְחֵלֶק מֵהַסְּפָרַדִּים מְנִיחִים טַלִּית וּתְפִלִּין בְּמִנְחָה, וְחֵלֶק מֵהַסְּפָרַדִּים בְּשַׁחֲרִית.","פֶּרֶק ע״ג, הֲלָכוֹת י״ט-כ׳","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["בְּתִשְׁעָה בְּאָב שֶׁחָל בְּשַׁבָּת, מָה אוֹכְלִים בַּסְּעוּדָה הַמַּפְסֶקֶת?",["רַק לֶחֶם וּבֵיצָה קָשָׁה עִם אֵפֶר","רַק מַאֲכָלִים קָרִים, בְּלִי בָּשָׂר וּבְלִי יַיִן","בָּשָׂר וְיַיִן, וּמַפְסִיקִים לִפְנֵי שְׁקִיעַת הַחַמָּה","בָּשָׂר וְיַיִן, וּמֻתָּר לֶאֱכֹל עַד חֲצוֹת"],2,"הַסְּעוּדָה הַמַּפְסֶקֶת הִיא סְעוּדָה שְׁלִישִׁית, וּמֻתָּר בָּהּ בָּשָׂר וְיַיִן אֲפִלּוּ כִּסְעוּדַת שְׁלֹמֹה, אַךְ מַפְסִיקִים לִפְנֵי הַשְּׁקִיעָה.","פֶּרֶק ע״ג, הֲלָכָה כ״א","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["מָה עוֹשִׂים בְּמוֹצָאֵי שַׁבָּת שֶׁהוּא לֵיל תִּשְׁעָה בְּאָב?",["מַבְדִּילִים עַל כּוֹס יַיִן וּמְבָרְכִים עַל הַבְּשָׂמִים","חוֹלְצִים נַעֲלֵי עוֹר, וּמְבָרְכִים בּוֹרֵא מְאוֹרֵי הָאֵשׁ","נִשְׁאָרִים בְּבִגְדֵי שַׁבָּת וּמְבָרְכִים עַל הַבְּשָׂמִים","אוֹכְלִים סְעוּדָה וְאַחַר כָּךְ חוֹלְצִים אֶת הַנַּעֲלַיִם"],1,"אוֹמְרִים ״הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל״, חוֹלְצִים נַעֲלֵי עוֹר וּמַחְלִיפִים בְּגָדִים. בְּעַרְבִית אוֹמְרִים ״אַתָּה חוֹנַנְתָּנוּ״, וְאַחֲרֶיהָ מְבָרְכִים עַל הַנֵּר.","פֶּרֶק ע״ג, הֲלָכוֹת כ״ב-כ״ג","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["בְּמוֹצָאֵי הַתַּעֲנִית (שֶׁנִּדְחֲתָה), אֵיךְ מַבְדִּילִים?",["עַל הַכּוֹס, הַנֵּר וְהַבְּשָׂמִים כְּמוֹ בְּכָל שָׁבוּעַ","עַל הַנֵּר בִּלְבַד, בְּלִי כּוֹס וּבְלִי בְּשָׂמִים","אֵין מַבְדִּילִים כְּלָל, כִּי כְּבָר הִבְדִּילוּ בִּתְפִלָּה","עַל הַכּוֹס, בְּלִי בְּרָכָה עַל הַנֵּר וְהַבְּשָׂמִים"],3,"מַבְדִּילִים עַל הַכּוֹס (וּמֻתָּר לִשְׁתּוֹת יַיִן אוֹ מִיץ עֲנָבִים), אַךְ אֵין מְבָרְכִים עַל הַנֵּר וְעַל הַבְּשָׂמִים.","פֶּרֶק ע״ג, הֲלָכָה כ״ד","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["מַדּוּעַ נָהֲגוּ שֶׁלֹּא לֶאֱכֹל בָּשָׂר בָּעֲשִׂירִי בְּאָב?",["כִּי הַבָּבְלִים כָּבְשׁוּ אֶת יְרוּשָׁלַיִם בַּיּוֹם הָעֲשִׂירִי","כִּי בְּיוֹם זֶה הִתְחִילוּ לִבְנוֹת מֵחָדָשׁ אֶת הַמִּקְדָּשׁ","כִּי בֵּית הַמִּקְדָּשׁ נִשְׂרַף בְּמֶשֶׁךְ כָּל הַיּוֹם הָעֲשִׂירִי","כִּי זֶהוּ יוֹם תַּעֲנִית נוֹסָף שֶׁל כָּל עַם יִשְׂרָאֵל"],2,"בַּשְּׁבִיעִי בְּאָב כָּבְשׁוּ הַבָּבְלִים אֶת הַמִּקְדָּשׁ, בְּתִשְׁעָה בְּאָב לִפְנוֹת עֶרֶב הִצִּיתוּ בּוֹ אֵשׁ, וְהוּא נִשְׂרַף כָּל יוֹם עֲשִׂירִי בְּאָב.","פֶּרֶק ע״ג, הֲלָכוֹת כ״ה-כ״ו","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["לְגַבֵּי שְׁאַר מִנְהֲגֵי הָאֲבֵלוּת בָּעֲשִׂירִי בְּאָב, מָה נָכוֹן?",["כֻּלָּם אֲסוּרִים לְכָל הַדֵּעוֹת עַד מוֹצָאֵי הַשַּׁבָּת הַבָּאָה","כָּל אֶחָד לְפִי מִנְהַג אֲבוֹתָיו, וּבְיוֹם שִׁשִּׁי מֻתָּר מֵהַבֹּקֶר","כֻּלָּם מֻתָּרִים מִיָּד, וּבְיוֹם שִׁשִּׁי אֲסוּרִים עַד הַלַּיְלָה","כָּל אֶחָד לְפִי מִנְהָגוֹ, וּבְיוֹם שִׁשִּׁי אָסוּר לְבַשֵּׁל"],1,"יֵשׁ מַחְמִירִים בִּשְׁאַר מִנְהֲגֵי הָאֲבֵלוּת, וְכָל אֶחָד יִנְהַג לְפִי מִנְהֲגֵי אֲבוֹתָיו. כְּשֶׁעֲשִׂירִי בְּאָב חָל בְּיוֹם שִׁשִּׁי וְיֵשׁ חֲשָׁשׁ לַהֲכָנוֹת שַׁבָּת – הַכֹּל מֻתָּר מִבֹּקֶר עֲשִׂירִי בְּאָב.","פֶּרֶק ע״ג, הֲלָכוֹת כ״ז-כ״ח","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["תִּשְׁעָה בְּאָב שֶׁחָל בְּשַׁבָּת וְנִדְחָה, מָתַי מֻתָּר בָּשָׂר וְיַיִן?",["מִיָּד בְּמוֹצָאֵי הַתַּעֲנִית, בְּלַיְלָה שֶׁל אַחַד עָשָׂר","רַק מֵחֲצוֹת יוֹם אַחַד עָשָׂר בְּאָב","רַק לְאַחַר שָׁבוּעַ שָׁלֵם מִסּוֹף הַתַּעֲנִית","מִיָּד בְּבֹקֶר אַחַד עָשָׂר בְּאָב"],3,"מֻתָּר לֶאֱכֹל בָּשָׂר וְלִשְׁתּוֹת יַיִן מִיָּד בְּבֹקֶר אַחַד עָשָׂר בְּאָב, וּשְׁאַר מִנְהֲגֵי הָאֲבֵלוּת מִסְתַּיְּמִים מִיָּד בְּמוֹצָאֵי הַתַּעֲנִית.","פֶּרֶק ע״ג, הֲלָכָה כ״ט","תַּעֲנִית תִּשְׁעָה בְּאָב – חֵלֶק ב׳"],["לְשֵׁם מָה עָלָה מֹשֶׁה לְהַר סִינַי בְּא׳ בֶּאֱלוּל?",["לִבְנוֹת אֶת הַמִּשְׁכָּן בְּרֹאשׁ הָהָר הַגָּבוֹהַּ","לְבַקֵּשׁ מְחִילָה לְיִשְׂרָאֵל וּלְקַבֵּל לוּחוֹת שְׁנִיִּים","לִלְמֹד אֶת הִלְכוֹת הַשַּׁבָּת לִפְנֵי רֹאשׁ הַשָּׁנָה","לְהָבִיא אֶת הָעֵגֶל וּלְהַחְבִּיא אוֹתוֹ שָׁם"],1,"מֹשֶׁה עָלָה לְאַרְבָּעִים יָמִים, עַד י׳ בְּתִשְׁרֵי, לְבַקֵּשׁ מְחִילָה וּלְקַבֵּל לוּחוֹת שְׁנִיִּים. לָכֵן יָמִים אֵלּוּ הֵם יְמֵי תְּשׁוּבָה וּסְלִיחָה.","פֶּרֶק ע״ד, הֲלָכָה א׳","חֹדֶשׁ אֱלוּל"],["מָה רוֹמֵז קוֹל הַשּׁוֹפָר בְּחֹדֶשׁ אֱלוּל?",["שֶׁצָּרִיךְ לְהִתְכּוֹנֵן לְטִיּוּל גָּדוֹל בַּחֻפְשָׁה","שֶׁמַּתְחִילִים לְהָכִין אֶת הַסֻּכָּה בֶּחָצֵר","הִתְעוֹרְרוּת בִּתְשׁוּבָה וְשִׁפּוּר הַמַּעֲשִׂים שֶׁלָּנוּ","שֶׁהִגִּיעַ זְמַן לְהַתְחִיל אֶת שְׁנַת הַלִּמּוּדִים"],2,"קוֹל הַשּׁוֹפָר רוֹמֵז לְהִתְעוֹרְרוּת בִּתְשׁוּבָה וּלְשִׁפּוּר הַמַּעֲשִׂים. וְעוֹד: כְּשֶׁעָלָה מֹשֶׁה לָהָר עָבַר קוֹל שׁוֹפָר בַּמַּחֲנֶה.","פֶּרֶק ע״ד, הֲלָכָה ב׳","חֹדֶשׁ אֱלוּל"],["מָה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה עַל סֵדֶר י״ג הַמִּדּוֹת?",["שֶׁאוֹמְרִים אוֹתָן בְּלַחַשׁ רַק בְּיוֹם הַכִּפּוּרִים","שֶׁיֹּאמְרוּ אוֹתָן רַק פַּעַם אַחַת בְּכָל שָׁנָה","שֶׁרַק כֹּהֲנִים בְּבֵית הַמִּקְדָּשׁ יְכוֹלִים לְאָמְרָן","כְּשֶׁיִּשְׂרָאֵל יַעֲשׂוּ כַּסֵּדֶר הַזֶּה, אֲנִי מוֹחֵל לָהֶם"],3,"״כָּל זְמַן שֶׁיִּשְׂרָאֵל חוֹטְאִין, יַעֲשׂוּ לְפָנַי כַּסֵּדֶר הַזֶּה וַאֲנִי מוֹחֵל לָהֶם״ – כְּלוֹמַר יֹאמְרוּ אֶת הַמִּדּוֹת וְגַם יִתְנַהֲגוּ לְפִיהֶן.","פֶּרֶק ע״ד, הֲלָכָה ג׳","חֹדֶשׁ אֱלוּל"],["מָה עוֹשֶׂה מִי שֶׁאֵין לוֹ מִנְיָן וְרוֹצֶה לוֹמַר אֶת י״ג הַמִּדּוֹת?",["צָרִיךְ לְהַמְתִּין עַד שֶׁיַּגִּיעַ יוֹם הַכִּפּוּרִים","אוֹמֵר אוֹתָן רַק בְּשַׁבָּת לִפְנֵי הַסְּעוּדָה","יָכוֹל לוֹמַר אוֹתָן כְּקוֹרֵא בַּתּוֹרָה, בְּנִגּוּן וּבִטְעָמִים","אוֹמֵר אוֹתָן כִּתְפִלָּה רְגִילָה, בְּדִיּוּק כְּמוֹ בְּמִנְיָן"],2,"כִּתְפִלָּה – רַק בְּמִנְיָן. יָחִיד יָכוֹל לְאָמְרָן כְּקוֹרֵא בַּתּוֹרָה, אַךְ עַל פִּי הַקַּבָּלָה רָאוּי לְהִמָּנַע לְגַמְרֵי.","פֶּרֶק ע״ד, הֲלָכָה ו׳","חֹדֶשׁ אֱלוּל"],["הַסְּפָרַדִּים אוֹמְרִים סְלִיחוֹת בְּאַשְׁמֹרֶת הַבֹּקֶר וְתוֹקְעִים בָּהֶן. מָה עוֹשִׂים אִם הַתְּקִיעוֹת מַפְרִיעוֹת לַשְּׁכֵנִים?",["תּוֹקְעִים בְּכָל זֹאת, כִּי זֶה מִנְהָג","עוֹבְרִים לִתְקֹעַ בְּשָׁעָה שְׁתֵּים עֶשְׂרֵה בַּלַּיְלָה","מְבַטְּלִים אֶת הַתְּקִיעוֹת לְכָל חֹדֶשׁ אֱלוּל","מְבַטְּלִים אוֹתָן וְתוֹקְעִים אַחֲרֵי תְּפִלַּת שַׁחֲרִית"],3,"מִב׳ בֶּאֱלוּל עַד יוֹם הַכִּפּוּרִים תּוֹקְעִים בְּי״ג הַמִּדּוֹת וּבַקַּדִּישׁ. אִם זֶה מַפְרִיעַ לַשְּׁכֵנִים – רָאוּי לְבַטֵּל וְלִתְקֹעַ אַחֲרֵי שַׁחֲרִית.","פֶּרֶק ע״ד, הֲלָכוֹת ז׳-ח׳","חֹדֶשׁ אֱלוּל"],["בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים תּוֹקְעִים מֵרֹאשׁ חֹדֶשׁ עַד כ״ח בֶּאֱלוּל. וּמָתַי מַתְחִילִים לוֹמַר סְלִיחוֹת?",["בְּיוֹם כ״ח בֶּאֱלוּל, כְּשֶׁמַּפְסִיקִים לִתְקֹעַ בַּשּׁוֹפָר","בְּמוֹצָאֵי הַשַּׁבָּת שֶׁלִּפְנֵי רֹאשׁ הַשָּׁנָה, אַחַר חֲצוֹת","בְּרֹאשׁ חֹדֶשׁ אֱלוּל, מִיָּד אַחֲרֵי תְּפִלַּת שַׁחֲרִית","בְּט״ו בְּאָב, בִּשְׁעַת הַצָּהֳרַיִם בְּבֵית הַכְּנֶסֶת"],1,"מַתְחִילִים אַחַר חֲצוֹת בְּמוֹצָאֵי הַשַּׁבָּת שֶׁלִּפְנֵי ר״ה (וְאִם ר״ה בְּיוֹם ב׳ אוֹ ג׳ – בַּשַּׁבָּת הַקּוֹדֶמֶת). לִפְנֵי חֲצוֹת אֵין לוֹמַר סְלִיחוֹת; מִי שֶׁלֹּא יָכוֹל – יֹאמַר בַּבֹּקֶר.","פֶּרֶק ע״ד, הֲלָכוֹת ט׳-י״א׳","חֹדֶשׁ אֱלוּל"],["מָה רוֹמְזוֹת הַמִּלִּים ״ה׳ אוֹרִי וְיִשְׁעִי״ לְפִי הַמִּדְרָשׁ?",["אוֹרִי בְּפֶסַח, וְיִשְׁעִי בְּחַג הַשָּׁבוּעוֹת","אוֹרִי בַּחֲנֻכָּה, וְיִשְׁעִי בְּפוּרִים שֶׁל אוֹתָהּ שָׁנָה","אוֹרִי בְּרֹאשׁ הַשָּׁנָה, וְיִשְׁעִי בְּיוֹם הַכִּפּוּרִים","אוֹרִי בְּסֻכּוֹת, וְיִשְׁעִי בְּשִׂמְחַת תּוֹרָה"],2,"״אוֹרִי״ – בְּרֹאשׁ הַשָּׁנָה, יוֹם הַדִּין, ״וְיִשְׁעִי״ – בְּיוֹם הַכִּפּוּרִים שֶׁה׳ יוֹשִׁיעֵנוּ וְיִמְחַל לָנוּ. הָאַשְׁכְּנַזִּים אוֹמְרִים אֶת הַמִּזְמוֹר עַד הוֹשַׁעְנָא רַבָּה.","פֶּרֶק ע״ד, הֲלָכָה י״ג׳","חֹדֶשׁ אֱלוּל"],["אֶת מִי בּוֹחֲרִים לִשְׁלִיחַ צִבּוּר בַּסְּלִיחוֹת וּבַיָּמִים הַנּוֹרָאִים?",["הֶהָגוּן וְהַגָּדוֹל בַּתּוֹרָה, מֵעַל גִּיל שְׁלוֹשִׁים וְנָשׂוּי","מִי שֶׁקּוֹלוֹ הֲכִי חָזָק וְיָפֶה בְּכָל הָעִיר","הַיֶּלֶד הַצָּעִיר בְּיוֹתֵר שֶׁיּוֹדֵעַ לִקְרֹא הֵיטֵב","מִי שֶׁהִגִּיעַ רִאשׁוֹן לְבֵית הַכְּנֶסֶת בַּבֹּקֶר"],0,"בּוֹחֲרִים אֶת הֶהָגוּן וְהַגָּדוֹל בַּתּוֹרָה וּבְמַעֲשִׂים טוֹבִים, מֵעַל שְׁלוֹשִׁים וְנָשׂוּי. אִם אֵין – כָּל אֶחָד כָּשֵׁר, וּבִלְבַד שֶׁיִּהְיֶה רָצוּי לַקָּהָל.","פֶּרֶק ע״ד, הֲלָכָה י״ב׳","חֹדֶשׁ אֱלוּל"],["אֵילוּ מִנְהָגִים נוֹהֲגִים בְּחֹדֶשׁ אֱלוּל?",["מַדְלִיקִים נֵרוֹת וְאוֹכְלִים מַצָּה בְּכָל לַיְלָה","בּוֹנִים סֻכָּה וְקוֹנִים אַרְבָּעָה מִינִים חֲדָשִׁים","שׁוֹמְעִים מְגִלָּה וְשׁוֹלְחִים מִשְׁלוֹחַ מָנוֹת לַחֲבֵרִים","מְבָרְכִים ״לְשָׁנָה טוֹבָה״ וּבוֹדְקִים תְּפִלִּין וּמְזוּזוֹת"],3,"בְּמִכְתָּב מְבָרְכִים ״לְשָׁנָה טוֹבָה תִּכָּתֵב וְתֵחָתֵם״. הַנּוֹהֲגִים לִבְדֹּק תְּפִלִּין וּמְזוּזוֹת מוֹסְרִים אוֹתָן לְסוֹפֵר מֻמְחֶה וִירֵא שָׁמַיִם, שֶׁלֹּא יִגָּרֵם נֶזֶק.","פֶּרֶק ע״ד, הֲלָכוֹת י״ד׳-ט״ו׳","חֹדֶשׁ אֱלוּל"],["מָה עוֹשִׂים בְּהַתָּרַת הַנְּדָרִים שֶׁל עֶרֶב רֹאשׁ הַשָּׁנָה?",["מַתִּירִים רַק אֶת הַנְּדָרִים שֶׁנִּדְרוּ הַיּוֹם בַּבֹּקֶר","מְבַטְּלִים רַק נְדָרִים שֶׁיִּנָּדְרוּ בַּשָּׁנָה הַבָּאָה בִּלְבַד","מַתִּירִים נִדְרֵי הֶעָבָר וּמְבַטְּלִים מֵרֹאשׁ נִדְרֵי הֶעָתִיד","מַתִּירִים רַק שְׁבוּעוֹת שֶׁנִּשְׁבְּעוּ בְּבֵית הַדִּין"],2,"בְּהַתָּרַת הַנְּדָרִים מַתִּירִים אֶת נִדְרֵי הֶעָבָר וְגַם מְבַטְּלִים מֵרֹאשׁ אֶת כָּל נִדְרֵי הֶעָתִיד.","פֶּרֶק ע״ה, הֲלָכָה א׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["מָה עוֹד כָּלוּל בַּהַתָּרָה, מִלְּבַד נְדָרִים וּשְׁבוּעוֹת?",["רַק חֲפָצִים שֶׁאָדָם שָׁאַל מֵחֲבֵרוֹ וְלֹא הֶחֱזִיר","אִסּוּרִים שֶׁאָדָם אָסַר עַל עַצְמוֹ וּמִנְהָגִים טוֹבִים","חֻבּוֹת כֶּסֶף שֶׁאָדָם חַיָּב לַחֲנוּת הַשְּׁכוּנָה","הַבְטָחוֹת שֶׁהַהוֹרִים הִבְטִיחוּ לַיְּלָדִים בְּמַתָּנָה"],1,"בַּהַתָּרָה כְּלוּלִים גַּם אִסּוּרִים שֶׁאָדָם אָסַר עַל עַצְמוֹ, וְקַבָּלוֹת וּמִנְהָגִים טוֹבִים שֶׁקִּבֵּל עַל עַצְמוֹ.","פֶּרֶק ע״ה, הֲלָכָה א׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["דָּנִי נִשְׁבַּע כִּי חֲבֵרוֹ הִשְׁבִּיעַ אוֹתוֹ. הַאִם הַתָּרַת הַנְּדָרִים מוֹעִילָה לוֹ?",["כֵּן, הִיא מוֹעִילָה לְכָל שְׁבוּעָה שֶׁיֵּשׁ בָּעוֹלָם","כֵּן, אִם הֶחָבֵר עוֹמֵד לְיָדוֹ בִּזְמַן הַהַתָּרָה","לֹא, כִּי בְּעֶרֶב רֹאשׁ הַשָּׁנָה אֵין הַתָּרָה","לֹא, הִיא מוֹעִילָה רַק לְמַה שֶּׁנִּשְׁבַּע לְעַצְמוֹ"],3,"הַתָּרַת נְדָרִים מוֹעִילָה רַק לְנֶדֶר אוֹ שְׁבוּעָה שֶׁאָדָם נָדַר לְעַצְמוֹ. מִי שֶׁחֲבֵרוֹ הִשְׁבִּיעַ אוֹתוֹ – אֵין הַבִּטּוּל מוֹעִיל לוֹ.","פֶּרֶק ע״ה, הֲלָכָה ב׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["יוֹסִי זוֹכֵר הֵיטֵב שֶׁנָּדַר נֶדֶר. מָה עָלָיו לַעֲשׂוֹת?",["לִפְנוֹת לְחָכָם וְלִשְׁאֹל אוֹתוֹ כֵּיצַד לִנְהֹג","לִסְמֹךְ עַל הַתָּרַת הַנְּדָרִים שֶׁל עֶרֶב רֹאשׁ הַשָּׁנָה","לִשְׁכֹּחַ מִן הַנֶּדֶר וְלֹא לַחְשֹׁב עָלָיו עוֹד","לְסַפֵּר לַחֲבֵרָיו בַּכִּתָּה וְהֵם יַחְלִיטוּ בִּשְׁבִילוֹ"],0,"הַהַתָּרָה מוֹעִילָה בְּעִקָּר לִנְדָרִים שֶׁנִּשְׁכְּחוּ. מִי שֶׁזּוֹכֵר הֵיטֵב יִפְנֶה לְחָכָם, כִּי יֵשׁ בִּנְדָרִים דִּינִים סְבוּכִים.","פֶּרֶק ע״ה, הֲלָכָה ב׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["לָמָּה לֹא תּוֹקְעִים בַּשּׁוֹפָר בְּעֶרֶב רֹאשׁ הַשָּׁנָה?",["כְּדֵי שֶׁהַשּׁוֹפָר יָנוּחַ וְלֹא יִסָּדֵק לִפְנֵי הֶחָג","כִּי בְּחֹדֶשׁ אֱלוּל אָסוּר לִתְקֹעַ בַּשּׁוֹפָר כְּלָל","כְּדֵי לְהַפְסִיק בֵּין תְּקִיעוֹת הָרְשׁוּת לִתְקִיעוֹת הַחוֹבָה","כְּדֵי שֶׁהַתּוֹקֵעַ יַסְפִּיק לְהִתְאַמֵּן בַּבַּיִת לְבַד"],2,"לֹא תּוֹקְעִים בְּעֶרֶב רֹאשׁ הַשָּׁנָה כְּדֵי לְהַפְסִיק בֵּין תְּקִיעוֹת הָרְשׁוּת שֶׁל חֹדֶשׁ אֱלוּל לִתְקִיעוֹת הַחוֹבָה שֶׁל רֹאשׁ הַשָּׁנָה.","פֶּרֶק ע״ה, הֲלָכָה ג׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["לָמָּה מִשְׁתַּדְּלִים לְהִסְתַּפֵּר בְּעֶרֶב רֹאשׁ הַשָּׁנָה?",["כִּי בְּרֹאשׁ הַשָּׁנָה עַצְמוֹ אֵין מַסְפֵּרוֹת פְּתוּחוֹת","לְהַרְאוֹת שֶׁאָנוּ בְּטוּחִים שֶׁדִּינֵנוּ יֵצֵא לְחַיִּים טוֹבִים","כְּדֵי שֶׁלֹּא יִהְיֶה חַם בַּתְּפִלּוֹת הָאֲרֻכּוֹת","כִּי כָּךְ נוֹהֲגִים לִפְנֵי כָּל יוֹם הֻלֶּדֶת"],1,"מִסְתַּפְּרִים כְּדֵי לְהַרְאוֹת אֶת בִּטְחוֹנֵנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹצִיא אֶת דִּינֵנוּ לָאוֹר, לְחַיִּים טוֹבִים וּלְשָׁלוֹם.","פֶּרֶק ע״ה, הֲלָכָה ד׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["לָמָּה מִתְפַּלְּלִים מִנְחָה שֶׁל עֶרֶב רֹאשׁ הַשָּׁנָה בְּכַוָּנָה רַבָּה?",["כִּי הִיא הַתְּפִלָּה הָאֲרֻכָּה בְּיוֹתֵר בְּכָל הַשָּׁנָה","כִּי בָּהּ תּוֹקְעִים בַּשּׁוֹפָר מֵאָה תְּקִיעוֹת","כִּי אוֹמְרִים אוֹתָהּ רַק פַּעַם אַחַת בַּחַיִּים","כִּי הִיא הַתְּפִלָּה הָאַחֲרוֹנָה שֶׁל הַשָּׁנָה"],3,"מִנְחָה שֶׁל עֶרֶב רֹאשׁ הַשָּׁנָה הִיא הַתְּפִלָּה הָאַחֲרוֹנָה שֶׁל הַשָּׁנָה, וְהִיא עוֹמֶדֶת בְּפִתְחוֹ שֶׁל הַיּוֹם הַגָּדוֹל.","פֶּרֶק ע״ה, הֲלָכָה ה׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["רֹאשׁ הַשָּׁנָה חָל בַּחֲמִישִׁי וְשִׁשִּׁי. מָתַי עוֹשִׂים עֵרוּב תַּבְשִׁילִין?",["בְּיוֹם רְבִיעִי, כְּדֵי שֶׁנּוּכַל לְבַשֵּׁל בְּשִׁשִּׁי לַשַּׁבָּת","בְּיוֹם שִׁשִּׁי בַּבֹּקֶר, מִיָּד אַחֲרֵי תְּפִלַּת שַׁחֲרִית","בְּמוֹצָאֵי שַׁבָּת, אַחֲרֵי שֶׁהֶחָג כְּבָר נִגְמַר","אֵין צֹרֶךְ, כִּי מֻתָּר תָּמִיד לְבַשֵּׁל בֶּחָג לַשַּׁבָּת"],0,"כְּשֶׁרֹאשׁ הַשָּׁנָה חָל בַּחֲמִישִׁי וְשִׁשִּׁי, עוֹשִׂים עֵרוּב תַּבְשִׁילִין בְּיוֹם רְבִיעִי, כְּדֵי שֶׁאֶפְשָׁר יִהְיֶה לְבַשֵּׁל בְּשִׁשִּׁי לִכְבוֹד הַשַּׁבָּת.","פֶּרֶק ע״ה, הֲלָכָה ו׳","עֶרֶב רֹאשׁ הַשָּׁנָה"],["מָה אוֹמֶרֶת הַתּוֹרָה עַל הַיּוֹם הָרִאשׁוֹן בְּתִשְׁרֵי?",["יוֹם רָגִיל שֶׁמֻּתָּר בּוֹ לַעֲשׂוֹת כָּל מְלָאכָה","יוֹם צוֹם שֶׁבּוֹ קוֹרְאִים אֶת מְגִלַּת אֶסְתֵּר","יוֹם טוֹב שֶׁאָסוּר בִּמְלָאכָה וּמִצְוָה לִתְקֹעַ בְּשׁוֹפָר","יוֹם שֶׁבּוֹ נוֹטְלִים לוּלָב וְיוֹשְׁבִים בַּסֻּכָּה"],2,"״כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ, יוֹם תְּרוּעָה יִהְיֶה לָכֶם״.","פֶּרֶק ע״ו, הֲלָכָה א׳","לֵיל רֹאשׁ הַשָּׁנָה"],["רֹאשׁ הַשָּׁנָה הוּא יוֹם דִּין. לָמָּה אָסוּר בִּמְלָאכָה גַּם בְּב׳ בְּתִשְׁרֵי?",["כִּי בַּתּוֹרָה כָּתוּב שֶׁרֹאשׁ הַשָּׁנָה שְׁנֵי יָמִים","כִּי בּוֹ חָל תָּמִיד יוֹם הַכִּפּוּרִים","כִּי הוּא יוֹם שֶׁל צוֹם גְּדַלְיָה","כִּי מִדִּבְרֵי חֲכָמִים גַּם הוּא רֹאשׁ הַשָּׁנָה"],3,"בְּרֹאשׁ הַשָּׁנָה כָּל בָּאֵי הָעוֹלָם עוֹבְרִין לְפָנָיו כִּבְנֵי מָרוֹן. מֵהַתּוֹרָה – רַק א׳ בְּתִשְׁרֵי, וּמִדִּבְרֵי חֲכָמִים – גַּם ב׳ בְּתִשְׁרֵי.","פֶּרֶק ע״ו, הֲלָכוֹת ב׳-ג׳","לֵיל רֹאשׁ הַשָּׁנָה"],["לָמָּה מִשְׁתַּדְּלִים לֹא לִכְעֹס בְּלֵיל רֹאשׁ הַשָּׁנָה?",["כִּי בְּרֹאשׁ הַשָּׁנָה אָסוּר לְדַבֵּר בִּכְלָל","כִּי הַתְחָלָה בְּסִימָן טוֹב מְבִיאָה הֶמְשֵׁךְ טוֹב","כִּי כַּעַס מֻתָּר רַק בִּימֵי חֹל","כִּי הַשְּׁכֵנִים עֲלוּלִים לִשְׁמֹעַ אֶת הַצְּעָקוֹת"],1,"הַתְחָלָה בְּסִימָן טוֹב נוֹתֶנֶת תִּקְוָה לְהֶמְשֵׁךְ מֻצְלָח – גַּם כְּשֶׁהָאָדָם עוֹשֶׂה אוֹתָהּ בְּמוֹ יָדָיו.","פֶּרֶק ע״ו, הֲלָכָה ד׳","לֵיל רֹאשׁ הַשָּׁנָה"],["עַד מָתַי יֵשׁ נוֹהֲגִים לֶאֱכֹל פַּת עִם דְּבַשׁ?",["רַק בַּלַּיְלָה הָרִאשׁוֹן שֶׁל רֹאשׁ הַשָּׁנָה","עַד חַג הַפֶּסַח שֶׁבְּסוֹף הַחֹרֶף","בְּכָל הַשַּׁבָּתוֹת וְהַחַגִּים עַד שִׂמְחַת תּוֹרָה","בְּכָל יְמֵי הַשָּׁנָה בְּלִי שׁוּם הֶפְסֵק"],2,"יֵשׁ נוֹהֲגִים לְהַמְשִׁיךְ לֶאֱכֹל אֶת הַפַּת עִם סֻכָּר אוֹ דְּבַשׁ עַד שִׂמְחַת תּוֹרָה. וְכָל אֶחָד יִנְהַג כְּמִנְהַג אֲבוֹתָיו.","פֶּרֶק ע״ו, הֲלָכוֹת ה׳-ו׳","לֵיל רֹאשׁ הַשָּׁנָה"],["מָה מְבַקְּשִׁים כְּשֶׁאוֹכְלִים תָּמָר (תְּמָרֵי)?",["שֶׁנִּהְיֶה לְרֹאשׁ וְלֹא לְזָנָב בְּכָל הַשָּׁנָה","שֶׁיִּתַּמּוּ אוֹיְבֵינוּ, כִּי הַשֵּׁם תָּמָר דּוֹמֶה לְ׳יִתַּמּוּ׳","שֶׁתִּהְיֶה לָנוּ שָׁנָה מְתוּקָה כְּמוֹ דְּבַשׁ","שֶׁנִּפְרֶה וְנִרְבֶּה כְּמוֹ הַדָּגִים בַּיָּם"],1,"תְּמָרֵי – ״שֶׁיִּתַּמּוּ אוֹיְבֵינוּ״, מִן הַסִּימָנִים הַמֻּזְכָּרִים בַּגְּמָרָא.","פֶּרֶק ע״ו, הֲלָכָה ז׳","לֵיל רֹאשׁ הַשָּׁנָה"],["לָמָּה אֵין מְבָרְכִים עַל שְׁאָר הַסִּימָנִים מֵהַיְּרָקוֹת?",["כִּי עַל יְרָקוֹת לְעוֹלָם לֹא מְבָרְכִים בִּכְלָל","כִּי בִּרְכַּת הַקִּדּוּשׁ פּוֹטֶרֶת אֶת כָּל הַמַּאֲכָלִים","כִּי אָסוּר לְבָרֵךְ בְּרָכוֹת בְּיוֹם טוֹב","כִּי בִּרְכַּת הַמּוֹצִיא פּוֹטֶרֶת אֶת יַרְקוֹת הַסְּעוּדָה"],3,"הַיְּרָקוֹת בָּאִים מֵחֲמַת הַסְּעוּדָה, וּבִרְכַּת ״הַמּוֹצִיא״ פּוֹטֶרֶת אוֹתָם.","פֶּרֶק ע״ו, הֲלָכָה ח׳","לֵיל רֹאשׁ הַשָּׁנָה"],["אֵיזוֹ בְּרָכָה אַחֲרוֹנָה אוֹמְרִים עַל הַסִּימָנִים?",["בִּרְכַּת הַמָּזוֹן פּוֹטֶרֶת גַּם אוֹתָם","מְבָרְכִים בּוֹרֵא נְפָשׁוֹת עַל כָּל סִימָן","מְבָרְכִים עַל הָעֵץ מִיָּד אַחֲרֵי הַתָּמָר","אֵין צֹרֶךְ בְּשׁוּם בְּרָכָה, גַּם לֹא בִּרְכַּת הַמָּזוֹן"],0,"בִּרְכַּת הַמָּזוֹן פּוֹטֶרֶת גַּם אֶת הַסִּימָנִים מִבְּרָכָה אַחֲרוֹנָה.","פֶּרֶק ע״ו, הֲלָכָה ט׳","לֵיל רֹאשׁ הַשָּׁנָה"],["לָמָּה עָדִיף לְבָרֵךְ לִפְנֵי שֶׁאוֹמְרִים ״יְהִי רָצוֹן״?",["כִּי שֶׁבַח ה׳ קוֹדֵם לְבַקָּשַׁת צָרְכֵי הָאָדָם","כִּי אָסוּר לְהַגִּיד יְהִי רָצוֹן בְּלִי לֶאֱכֹל","כִּי כָּךְ אֶפְשָׁר לְסַיֵּם אֶת הַסְּעוּדָה מַהֵר","כִּי יְהִי רָצוֹן נֶאֱמָר רַק בְּבֵית הַכְּנֶסֶת"],0,"בִּרְכַּת בּוֹרֵא פְּרִי הָעֵץ הִיא שִׁבְחוֹ שֶׁל ה׳, וְ״יְהִי רָצוֹן״ הִיא צֹרֶךְ הָאָדָם – כְּמוֹ בַּתְּפִלָּה, שֶׁמַּקְדִּימִים שֶׁבַח לַבַּקָּשׁוֹת.","פֶּרֶק ע״ו, הֲלָכָה י׳","לֵיל רֹאשׁ הַשָּׁנָה"],["מָה אָסוּר לַעֲשׂוֹת בַּיּוֹם הָרִאשׁוֹן לִכְבוֹד הַיּוֹם הַשֵּׁנִי?",["מֻתָּר לְבַשֵּׁל, אֲבָל אָסוּר לַעֲרֹךְ אֶת הַשֻּׁלְחָן","אֲפִלּוּ לַעֲרֹךְ אֶת הַשֻּׁלְחָן לַסְּעוּדָה שֶׁל הַלַּיְלָה","אָסוּר רַק לִשְׁטֹף כֵּלִים, וְכָל הַשְּׁאָר מֻתָּר","שׁוּם דָּבָר, כִּי שְׁנֵי הַיָּמִים הֵם יוֹם אֶחָד"],1,"אָסוּר לְהָכִין מֵהַיּוֹם הָרִאשׁוֹן לַשֵּׁנִי, אֲפִלּוּ לַעֲרֹךְ שֻׁלְחָן, וְכָל שֶׁכֵּן לְבַשֵּׁל אוֹ לְחַמֵּם.","פֶּרֶק ע״ו, הֲלָכָה י״א","לֵיל רֹאשׁ הַשָּׁנָה"],["מָה הַדִּין לְמִי שֶׁאֵין לוֹ פְּרִי חָדָשׁ בַּלַּיְלָה הַשֵּׁנִי?",["הוּא לֹא מְבָרֵךְ שֶׁהֶחֱיָנוּ בִּכְלָל בַּלַּיְלָה הַזֶּה","הוּא מְבָרֵךְ שֶׁהֶחֱיָנוּ רַק לְמָחֳרָת בַּבֹּקֶר","הוּא צָרִיךְ לָצֵאת לִקְנוֹת פְּרִי בְּיוֹם טוֹב","גַּם הוּא מְבָרֵךְ שֶׁהֶחֱיָנוּ בְּקִדּוּשׁ הַלַּיְלָה הַשֵּׁנִי"],3,"גַּם מִי שֶׁאֵין לוֹ פְּרִי חָדָשׁ אוֹ בֶּגֶד חָדָשׁ מְבָרֵךְ שֶׁהֶחֱיָנוּ. וְיֵשׁ נוֹהֲגִים לֶאֱכֹל אֶת הַסִּימָנִים גַּם בַּלַּיְלָה הַשֵּׁנִי.","פֶּרֶק ע״ו, הֲלָכוֹת י״ב-י״ג","לֵיל רֹאשׁ הַשָּׁנָה"],["מָה מְקוֹר מִצְוַת שְׁמִיעַת הַשּׁוֹפָר, וּמָה דִּינוֹ שֶׁל הַיּוֹם הַשֵּׁנִי?",["מִנְהַג הַקְּהִלּוֹת, וּבַיּוֹם הַשֵּׁנִי אֵין תּוֹקְעִים כְּלָל","פָּסוּק בַּתּוֹרָה, וּבַיּוֹם הַשֵּׁנִי הַמִּצְוָה הִיא מִדְּרַבָּנָן","פָּסוּק בַּתּוֹרָה, וְגַם הַיּוֹם הַשֵּׁנִי הוּא מִן הַתּוֹרָה","תַּקָּנַת נְבִיאִים, וְהַיּוֹם הַשֵּׁנִי חָמוּר יוֹתֵר מֵהָרִאשׁוֹן"],1,"״יוֹם תְּרוּעָה יִהְיֶה לָכֶם״ – מִצְוַת עֲשֵׂה מֵהַתּוֹרָה; בַּיּוֹם הַשֵּׁנִי הַתְּקִיעָה מִדְּרַבָּנָן.","פֶּרֶק ע״ז, הֲלָכוֹת א׳-ב׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["רֹאשׁ הַשָּׁנָה חָל בְּשַׁבָּת. מָה עוֹשִׂים עִם הַשּׁוֹפָר?",["תּוֹקְעִים בַּשַּׁבָּת כָּרָגִיל, כִּי זוֹ מִצְוָה מֵהַתּוֹרָה","לֹא תּוֹקְעִים בִּכְלָל בְּשָׁנָה זוֹ, גַּם לֹא בַּיּוֹם הַשֵּׁנִי","לֹא תּוֹקְעִים בַּשַּׁבָּת, וְתוֹקְעִים רַק בַּיּוֹם הַשֵּׁנִי","תּוֹקְעִים רַק בְּמוֹצָאֵי שַׁבָּת אַחֲרֵי הַהַבְדָּלָה"],2,"חֲכָמִים תִּקְּנוּ שֶׁלֹּא לִתְקֹעַ בַּיּוֹם הָרִאשׁוֹן כְּשֶׁהוּא שַׁבָּת, וְתוֹקְעִים רַק בַּיּוֹם הַשֵּׁנִי.","פֶּרֶק ע״ז, הֲלָכָה ג׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["לְפִי הָרַמְבָּ״ם, אֵיזֶה רֶמֶז יֵשׁ בִּתְקִיעַת הַשּׁוֹפָר?",["עוּרוּ מִשְּׁנַתְכֶם, חַפְּשׂוּ בְּמַעֲשֵׂיכֶם וְחִזְרוּ בִּתְשׁוּבָה","שִׂמְחוּ בַּחַג, כִּי הַשָּׁנָה הַחֲדָשָׁה כְּבָר הִתְחִילָה","הִתְאַסְּפוּ לְבֵית הַכְּנֶסֶת, כִּי הַתְּפִלָּה עוֹמֶדֶת לְהַתְחִיל","הִזָּהֲרוּ, כִּי אוֹיְבִים מִתְקָרְבִים אֶל הָעִיר"],0,"הַתְּקִיעָה הִיא גְּזֵרַת הַכָּתוּב, אֲבָל יֵשׁ בָּהּ רֶמֶז: ״עוּרוּ יְשֵׁנִים מִשְּׁנַתְכֶם... וְחִזְרוּ בִּתְשׁוּבָה!״","פֶּרֶק ע״ז, הֲלָכָה ד׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["לְפִי רַב סְעַדְיָה גָּאוֹן, מַהוּ אֶחָד הַטְּעָמִים לִתְקִיעַת הַשּׁוֹפָר?",["כְּדֵי לְהַזְכִּיר אֶת יְצִיאַת מִצְרַיִם וְאֶת קְרִיעַת הַיָּם","כְּדֵי לְהַבְרִיחַ חַיּוֹת רָעוֹת מִן הַשָּׂדוֹת בַּחֹרֶף","כְּדֵי לְהוֹדִיעַ לַחַקְלָאִים שֶׁהִגִּיעַ זְמַן הַבָּצִיר","כְּדֵי לְהַמְלִיךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ מֶלֶךְ"],3,"כְּשֵׁם שֶׁמַּמְלִיכִים מְלָכִים בַּחֲצוֹצְרוֹת וְקוֹל שׁוֹפָר, כָּךְ מַמְלִיכִים אֶת ה׳ בְּרֹאשׁ הַשָּׁנָה. עוֹד טְעָמִים: עֲקֵדַת יִצְחָק, מַעֲמַד הַר סִינַי וּבְשׂוֹרַת הַגְּאֻלָּה.","פֶּרֶק ע״ז, הֲלָכָה ה׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["מִי חַיָּב לִלְמֹד הֵיטֵב אֶת הִלְכוֹת תְּקִיעַת הַשּׁוֹפָר?",["רַק הָרַב, וְהַתּוֹקֵעַ אֵינוֹ צָרִיךְ לָדַעַת דָּבָר","הַתּוֹקֵעַ, וּבִמְיֻחָד מִי שֶׁתּוֹקֵעַ כְּדֵי לְהוֹצִיא אֶת הָרַבִּים","רַק מִי שֶׁתּוֹקֵעַ לְעַצְמוֹ בְּבֵיתוֹ, וְלֹא תּוֹקֵעַ הַצִּבּוּר","אַף אֶחָד, כִּי אֵין טָעֻיּוֹת בִּתְקִיעַת שׁוֹפָר"],1,"הַתּוֹקֵעַ, וּבִמְיֻחָד הַמּוֹצִיא אֶת הָרַבִּים, חַיָּב לִהְיוֹת בָּקִי כְּדֵי לָדַעַת מָה לַעֲשׂוֹת בְּכָל טָעוּת.","פֶּרֶק ע״ז, הֲלָכָה ו׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["מַדּוּעַ קֶרֶן שֶׁל פָּרָה פְּסוּלָה לְשׁוֹפָר?",["הִיא עֲשׂוּיָה מֵעֶצֶם אַחַת בִּלְבַד, בְּלִי שְׁתֵּי שְׁכָבוֹת","פָּרָה הִיא בַּעַל חַיִּים טָמֵא שֶׁאָסוּר לְאָכְלוֹ","הִיא מַזְכִּירָה אֶת חֵטְא הָעֵגֶל, וְקָטֵגוֹר אֵינוֹ נַעֲשֶׂה סָנֵגוֹר","הַקֶּרֶן שֶׁלָּהּ קְטַנָּה מִדַּי וְאִי אֶפְשָׁר לִתְקֹעַ בָּהּ כְּלָל"],2,"קֶרֶן פָּרָה פְּסוּלָה אַף עַל פִּי שֶׁיֵּשׁ בָּהּ שְׁתֵּי שְׁכָבוֹת, כִּי הִיא מַזְכִּירָה אֶת חֵטְא הָעֵגֶל.","פֶּרֶק ע״ז, הֲלָכָה ז׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["אֵיזֶה שׁוֹפָר הוּא הַמְּהֻדָּר בְּיוֹתֵר, וּמָה עוֹשִׂים אִם נִסְדַּק?",["שׁוֹפָר יָשָׁר וְאָרֹךְ; וְאִם נִסְדַּק, מַדְבִּיקִים אוֹתוֹ בְּדֶבֶק","קֶרֶן פָּרָה גְּדוֹלָה; וְאִם נִסְדְּקָה, מַמְשִׁיכִים לִתְקֹעַ בָּהּ","שׁוֹפָר חָדָשׁ מֵהַחֲנוּת; וְסָדוּק תָּמִיד כָּשֵׁר לְכַתְּחִלָּה","שׁוֹפָר אַיִל כָּפוּף; וְאִם נִסְדַּק, שׁוֹאֲלִים שְׁאֵלַת חָכָם"],3,"מִן הַמֻּבְחָר קֶרֶן אַיִל – זֵכֶר לָעֲקֵדָה, וְכָפוּף – לִכְפֹּף אֶת הַלֵּב. שׁוֹפָר שֶׁנִּסְדַּק אוֹ נִקַּב – שׁוֹאֲלִים חָכָם.","פֶּרֶק ע״ז, הֲלָכוֹת ח׳-ט׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["מָה קוֹרְאִים בַּתּוֹרָה בִּשְׁנֵי יְמֵי רֹאשׁ הַשָּׁנָה?",["בָּרִאשׁוֹן פְּקִידַת שָׂרָה, וּבַשֵּׁנִי אֶת עֲקֵדַת יִצְחָק","בָּרִאשׁוֹן עֲקֵדַת יִצְחָק, וּבַשֵּׁנִי אֶת פְּקִידַת שָׂרָה","בִּשְׁנֵי הַיָּמִים קוֹרְאִים אֶת עֲשֶׂרֶת הַדִּבְּרוֹת","בָּרִאשׁוֹן בְּרִיאַת הָעוֹלָם, וּבַשֵּׁנִי אֶת סִפּוּר יוֹסֵף"],0,"בָּרִאשׁוֹן ״וַה׳ פָּקַד אֶת שָׂרָה״ וְהַפְטָרַת חַנָּה; בַּשֵּׁנִי עֲקֵדַת יִצְחָק וְהַפְטָרַת ״מָצָא חֵן בַּמִּדְבָּר״ מִיִּרְמְיָהוּ.","פֶּרֶק ע״ז, הֲלָכָה י׳","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["לִפְנֵי הַתְּקִיעוֹת הָרִאשׁוֹנוֹת (תַּשְׁרַ״ת, תַּשַׁ״ת, תַּרַ״ת), מָה מְבָרֵךְ בַּעַל הַתּוֹקֵעַ?",["לִתְקֹעַ בַּשּׁוֹפָר, וְאֵין מְבָרְכִים שֶׁהֶחֱיָנוּ כְּלָל","עַל מִקְרָא מְגִלָּה, וְהַצִּבּוּר אֵינוֹ צָרִיךְ לְהִתְכַּוֵּן","לִשְׁמֹעַ קוֹל שׁוֹפָר, וְגַם אֶת בִּרְכַּת שֶׁהֶחֱיָנוּ","רַק שֶׁהֶחֱיָנוּ, כִּי אֵין בְּרָכָה עַל מִצְוַת שׁוֹפָר"],2,"מְבָרְכִים ״לִשְׁמֹעַ קוֹל שׁוֹפָר״ וְ״שֶׁהֶחֱיָנוּ״, וְהַצִּבּוּר מִתְכַּוֵּן לָצֵאת. אַחַר כָּךְ תּוֹקְעִים צֵרוּפֵי תְּקִיעָה, שְׁבָרִים וּתְרוּעָה, וְכָל עֵדָה נוֹהֶגֶת כְּמִנְהָגָהּ.","פֶּרֶק ע״ז, הֲלָכוֹת י״א-י״ב","קוֹל הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה"],["לָמָּה בְּחֵלֶק מֵהַקְּהִלּוֹת מַכְרִיזִים לִפְנֵי כָּל תְּקִיעָה אֵיזֶה קוֹל יִשָּׁמַע?",["כְּדֵי שֶׁהַיְּלָדִים יִתְעוֹרְרוּ וְיָבוֹאוּ לְבֵית הַכְּנֶסֶת","כְּדֵי לָתֵת לַתּוֹקֵעַ זְמַן לָנוּחַ בֵּין תְּקִיעוֹת","כְּדֵי לִמְנֹעַ בִּלְבּוּל בֵּין הַקּוֹלוֹת שֶׁל הַשּׁוֹפָר","כִּי אָסוּר לִתְקֹעַ בְּלִי שֶׁמִּישֶׁהוּ מְבָרֵךְ קֹדֶם"],2,"הַמַּכְרִיז אוֹמֵר לִפְנֵי כָּל תְּקִיעָה אֵיזֶה קוֹל עוֹמְדִים לְהַשְׁמִיעַ, כְּדֵי לִמְנֹעַ בִּלְבּוּל.","פֶּרֶק ע״ז, הֲלָכָה י״ג","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["הַיּוֹם הַשֵּׁנִי שֶׁל רֹאשׁ הַשָּׁנָה, וְהַיּוֹם הָרִאשׁוֹן לֹא הָיָה שַׁבָּת. מָה נָכוֹן לְגַבֵּי ״שֶׁהֶחֱיָנוּ״ לִפְנֵי הַתְּקִיעוֹת?",["סְפָרַדִּים מְבָרְכִים, וְאַשְׁכְּנַזִּים אֵינָם מְבָרְכִים","אַשְׁכְּנַזִּים מְבָרְכִים, וּסְפָרַדִּים אֵינָם מְבָרְכִים","כֻּלָּם מְבָרְכִים, כְּמוֹ בַּיּוֹם הָרִאשׁוֹן שֶׁל הֶחָג","אַף אֶחָד לֹא מְבָרֵךְ בַּיּוֹם הַשֵּׁנִי"],1,"הָאַשְׁכְּנַזִּים מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ גַּם בַּיּוֹם הַשֵּׁנִי. הַסְּפָרַדִּים אֵינָם מְבָרְכִים, אֶלָּא אִם כֵּן הַיּוֹם הָרִאשׁוֹן הָיָה שַׁבָּת.","פֶּרֶק ע״ז, הֲלָכָה י״ד","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["מִדּוּעַ אֵין לְדַבֵּר עַד סוֹף הַתְּקִיעוֹת שֶׁלְּאַחַר חֲזָרַת שְׁלִיחַ הַצִּבּוּר?",["כִּי הַדִּבּוּר מְעַיֵּף אֶת הַתּוֹקֵעַ בַּשּׁוֹפָר","כִּי בְּרֹאשׁ הַשָּׁנָה אָסוּר לְדַבֵּר כָּל הַיּוֹם","כִּי צָרִיךְ לִשְׁמֹר אֶת הַקּוֹל לְשִׁירַת הַפִּיּוּטִים","כִּי הַבְּרָכוֹת שֶׁבַּהַתְחָלָה חָלוֹת עַל כָּל הַתְּקִיעוֹת"],3,"הַבְּרָכוֹת שֶׁלִּפְנֵי הַתְּקִיעוֹת הָרִאשׁוֹנוֹת חָלוֹת עַל כָּל הַתְּקִיעוֹת שֶׁבַּהֶמְשֵׁךְ. וּבִשְׁעַת הַתְּקִיעוֹת עַצְמָן אֵין לְשׂוֹחֵחַ כְּלָל וְאַף לֹא לְהַשְׁמִיעַ קוֹל מַפְרִיעַ.","פֶּרֶק ע״ז, הֲלָכָה ט״ו","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["רְאוּבֵן כְּבָר שָׁמַע שׁוֹפָר, וְהוֹלֵךְ לִתְקֹעַ לְשִׁמְעוֹן הַחוֹלֶה. שִׁמְעוֹן לֹא יוֹדֵעַ לְבָרֵךְ. מָה עוֹשִׂים?",["רְאוּבֵן הַתּוֹקֵעַ יָכוֹל לְבָרֵךְ עֲבוּר שִׁמְעוֹן","תּוֹקְעִים בְּלִי בְּרָכָה, כִּי רְאוּבֵן כְּבָר יָצָא","שִׁמְעוֹן לֹא יָכוֹל לִשְׁמֹעַ שׁוֹפָר הַשָּׁנָה בִּכְלָל","מְחַכִּים עַד שֶׁיָּבוֹא רַב שֶׁיְּבָרֵךְ לְבַד"],0,"בְּדֶרֶךְ כְּלָל הַשּׁוֹמֵעַ מְבָרֵךְ. אֲבָל אִם הוּא אֵינוֹ יוֹדֵעַ לְבָרֵךְ בְּעַצְמוֹ, הַתּוֹקֵעַ יָכוֹל לְבָרֵךְ עֲבוּרוֹ.","פֶּרֶק ע״ז, הֲלָכָה ט״ז","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["אֶת מָה מְבַסֶּסֶת בִּרְכַּת ״שׁוֹפָרוֹת״ בִּתְפִלַּת מוּסָף?",["אֶת הָאֱמוּנָה בִּמְצִיאוּת ה׳ וּמַלְכוּתוֹ בָּעוֹלָם","אֶת הָאֱמוּנָה שֶׁה׳ זוֹכֵר אֶת הָעוֹלָם וּמַשְׁגִּיחַ","אֶת הָאֱמוּנָה בְּמַתַּן תּוֹרָה וּבִגְאֻלַּת יִשְׂרָאֵל","אֶת הַחוֹבָה לִשְׁמֹעַ מֵאָה קוֹלוֹת בְּכָל יוֹם"],2,"״מַלְכֻיּוֹת״ – מְצִיאוּת ה׳ וּמַלְכוּתוֹ; ״זִכְרוֹנוֹת״ – ה׳ זוֹכֵר וּמַשְׁגִּיחַ; ״שׁוֹפָרוֹת״ – מַתַּן תּוֹרָה וּגְאֻלַּת יִשְׂרָאֵל.","פֶּרֶק ע״ז, הֲלָכָה י״ז","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["כַּמָּה פְּסוּקִים אוֹמְרִים בְּכָל אַחַת מִשָּׁלוֹשׁ הַבְּרָכוֹת, וּמָה עוֹשִׂים בְּסִיּוּמָהּ?",["שְׁלוֹשָׁה פְּסוּקִים, וּבַסּוֹף אוֹמְרִים ״שֶׁהֶחֱיָנוּ״ בְּקוֹל","עֲשָׂרָה פְּסוּקִים אוֹ יוֹתֵר, וּבַסּוֹף תּוֹקְעִים בַּשּׁוֹפָר","אַרְבָּעָה פְּסוּקִים מֵהַתּוֹרָה בִּלְבַד, בְּלִי תְּקִיעָה","פָּסוּק אֶחָד מֵהַכְּתוּבִים, וּבַסּוֹף פּוֹסְעִים שָׁלוֹשׁ פְּסִיעוֹת"],1,"עֲשָׂרָה פְּסוּקִים: אַרְבָּעָה מֵהַתּוֹרָה, שְׁלוֹשָׁה מֵהַנְּבִיאִים וּשְׁלוֹשָׁה מֵהַכְּתוּבִים, וּבְסִיּוּם הַבְּרָכָה תּוֹקְעִים. יֵשׁ קְהִלּוֹת שֶׁתּוֹקְעוֹת גַּם בְּלַחַשׁ וְגַם בַּחֲזָרָה, וְיֵשׁ שֶׁרַק בַּחֲזָרָה.","פֶּרֶק ע״ז, הֲלָכוֹת י״ח-י״ט","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["מָה עוֹשִׂים לְאַחַר חֲזָרַת שְׁלִיחַ הַצִּבּוּר בִּתְפִלַּת מוּסָף?",["מַפְסִיקִים לִתְקֹעַ, כִּי כְּבָר תָּקְעוּ שְׁלֹשִׁים קוֹלוֹת","תּוֹקְעִים תְּקִיעָה אַחַת אֲרֻכָּה בִּלְבַד וְהוֹלְכִים","חוֹזְרִים עַל כָּל תְּפִלַּת מוּסָף פַּעַם שְׁנִיָּה","תּוֹקְעִים עוֹד תְּקִיעוֹת עַד שֶׁמַּגִּיעִים לְמֵאָה קוֹלוֹת"],3,"לְאַחַר הַחֲזָרָה תּוֹקְעִים עוֹד תְּקִיעוֹת, וּבְסַךְ הַכֹּל מַגִּיעִים לְמֵאָה קוֹלוֹת.","פֶּרֶק ע״ז, הֲלָכָה כ׳","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["נָשִׁים פְּטוּרוֹת מִשּׁוֹפָר. לְמִנְהַג הַסְּפָרַדִּים, תּוֹקְעִים בַּבַּיִת תְּקִיעוֹת שֶׁמְּיֻעָדוֹת לְנָשִׁים בִּלְבַד. הַאִם מְבָרְכִים?",["הַתּוֹקֵעַ חַיָּב לְבָרֵךְ בְּרָכָה מְיֻחֶדֶת לְנָשִׁים","מְבָרְכִים רַק אִם יֵשׁ מִנְיָן שֶׁל עֲשָׂרָה","לֹא מְבָרְכִים, כִּי הַתְּקִיעוֹת מְיֻעָדוֹת לְנָשִׁים בִּלְבַד","אֵין לִשְׁמֹעַ בִּכְלָל, כִּי נָשִׁים פְּטוּרוֹת"],2,"נָשִׁים פְּטוּרוֹת כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ, אַךְ נָהֲגוּ לִשְׁמֹעַ. לְמִנְהַג הַסְּפָרַדִּים לֹא מְבָרְכִים עַל תְּקִיעוֹת לְנָשִׁים בִּלְבַד; לְמִנְהַג הָאַשְׁכְּנַזִּים הַנָּשִׁים מְבָרְכוֹת בְּעַצְמָן.","פֶּרֶק ע״ז, הֲלָכוֹת כ״א-כ״ב","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["הַיּוֹם הָרִאשׁוֹן שֶׁל רֹאשׁ הַשָּׁנָה חָל בְּשַׁבָּת, וְיֵשׁ עֵרוּב. מָתַי אוֹמְרִים תַּשְׁלִיךְ לְיַד הַמַּיִם?",["אַשְׁכְּנַזִּים בַּיּוֹם הָרִאשׁוֹן, וּסְפָרַדִּים דּוֹחִים לַיּוֹם הַשֵּׁנִי","סְפָרַדִּים בַּיּוֹם הָרִאשׁוֹן, וְאַשְׁכְּנַזִּים דּוֹחִים לַיּוֹם הַשֵּׁנִי","כֻּלָּם אוֹמְרִים רַק אַחֲרֵי צֵאת רֹאשׁ הַשָּׁנָה","לֹא אוֹמְרִים תַּשְׁלִיךְ כְּלָל בְּשָׁנָה כָּזוֹ"],1,"תַּשְׁלִיךְ נֶאֱמָר בְּדֶרֶךְ כְּלָל בַּיּוֹם הָרִאשׁוֹן אַחַר מִנְחָה לְיַד מַיִם. בְּשַׁבָּת – הַסְּפָרַדִּים אוֹמְרִים בַּיּוֹם הָרִאשׁוֹן וְהָאַשְׁכְּנַזִּים בַּשֵּׁנִי; וְאִם אֵין עֵרוּב, גַּם הַסְּפָרַדִּים בַּשֵּׁנִי.","פֶּרֶק ע״ז, הֲלָכוֹת כ״ג-כ״ד","שׁוֹפָר, מוּסָף וְתַשְׁלִיךְ"],["מִי מְצֻוֶּה לָשׁוּב בִּתְשׁוּבָה לְפִי הַהֲלָכָה?",["רַק מִי שֶׁעָבַר עַל מִצְוַת לֹא תַּעֲשֶׂה","מִי שֶׁעָבַר עַל מִצְוַת עֲשֵׂה אוֹ לֹא תַּעֲשֶׂה","רַק מִי שֶׁעָשָׂה מַעֲשֶׂה רַע לַחֲבֵרוֹ בְּכַוָּנָה","רַק מִי שֶׁהָיָה רָשָׁע כָּל יָמָיו מַמָּשׁ"],1,"כָּל מִי שֶׁעָבַר עַל מִצְוָה, בֵּין עֲשֵׂה וּבֵין לֹא תַּעֲשֶׂה, מְצֻוֶּה לָשׁוּב – וְגַם עַל מִדּוֹת רָעוֹת כְּכַעַס וְגַאֲוָה.","פֶּרֶק ע״ח, הֲלָכוֹת א׳-ב׳","מִצְוַת הַתְּשׁוּבָה"],["בְּוִדּוּי הַתְּשׁוּבָה, אֵיזֶה מִשְׁפָּט מְבַטֵּא אֶת הַחֲרָטָה?",["אֲנִי שָׂמֵחַ מְאֹד בְּמַעֲשַׂי שֶׁעָשִׂיתִי","אֲנִי אֶחְזֹר עַל מַעֲשֶׂה זֶה מָחָר","לֹא חָטָאתִי וְלֹא עָשִׂיתִי שׁוּם דָּבָר","הֲרֵי אֲנִי מִתְבַּיֵּשׁ בְּמַעֲשַׂי שֶׁעָשִׂיתִי לְפָנֶיךָ"],3,"בַּוִּדּוּי אוֹמְרִים: ״וַהֲרֵי אֲנִי מִתְבַּיֵּשׁ בְּמַעֲשַׂי״ – זוֹ הַחֲרָטָה, וְאַחֲרֶיהָ הַקַּבָּלָה לֶעָתִיד.","פֶּרֶק ע״ח, הֲלָכָה ג׳","מִצְוַת הַתְּשׁוּבָה"],["מָה מְכַפֵּר עָלֵינוּ בַּזְּמַן שֶׁאֵין בֵּית הַמִּקְדָּשׁ קַיָּם?",["רַק קָרְבָּנוֹת שֶׁמַּקְרִיבִים עַל הַמִּזְבֵּחַ","שׁוּם דָּבָר אֵינוֹ מְכַפֵּר עַד שֶׁיִּבָּנֶה","הַתְּשׁוּבָה, שֶׁמְּכַפֶּרֶת עַל כָּל הָעֲבֵרוֹת","רַק תְּפִלָּה אַחַת בְּיוֹם רֹאשׁ הַשָּׁנָה"],2,"בְּלִי קָרְבָּנוֹת יֵשׁ לָנוּ אֶת הַתְּשׁוּבָה שֶׁמְּכַפֶּרֶת עַל כָּל הָעֲבֵרוֹת, וּלְבַעַל תְּשׁוּבָה אֵין מַזְכִּירִים דָּבָר מֵרִשְׁעוֹ.","פֶּרֶק ע״ח, הֲלָכָה ד׳","מִצְוַת הַתְּשׁוּבָה"],["מַדּוּעַ גְּדוֹלָה מַעֲלַת הַתְּשׁוּבָה?",["כִּי הִיא מְקָרֶבֶת אֶת הָאָדָם לַה׳","כִּי הִיא פּוֹטֶרֶת אוֹתָנוּ מִכָּל הַמִּצְווֹת","כִּי הִיא נַעֲשֵׂית רַק פַּעַם אַחַת בַּחַיִּים","כִּי הִיא מַרְחִיקָה אֶת הַחוֹטֵא מִן הָאֲנָשִׁים"],0,"הַתְּשׁוּבָה מְקָרֶבֶת אֶת הָאָדָם לַה׳ וּמְקָרֶבֶת אֶת הָרְחוֹקִים.","פֶּרֶק ע״ח, הֲלָכָה ה׳","מִצְוַת הַתְּשׁוּבָה"],["מַדּוּעַ מַרְבִּים בִּצְדָקָה בֵּין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים?",["כִּי בְּרֹאשׁ הַשָּׁנָה אָסוּר לָתֵת צְדָקָה","כִּי תְּשׁוּבָה מוֹעִילָה רַק בַּיָּמִים הָאֵלּוּ","כִּי בְּיוֹם הַכִּפּוּרִים כְּבָר אֵין דִּין כְּלָל","כִּי חֲתִימַת הַדִּין נַעֲשֵׂית רַק בְּיוֹם הַכִּפּוּרִים"],3,"הַדִּין נִכְתָּב בְּרֹאשׁ הַשָּׁנָה וְנֶחְתָּם בְּיוֹם הַכִּפּוּרִים, וּמַרְבִּים זְכֻיּוֹת כְּדֵי לְהֵחָתֵם לְחַיִּים טוֹבִים. הַתְּשׁוּבָה מוֹעִילָה כָּל הַשָּׁנָה, וּבַיָּמִים הָאֵלּוּ מִתְקַבֶּלֶת מִיָּד.","פֶּרֶק ע״ח, הֲלָכוֹת ו׳-ז׳","מִצְוַת הַתְּשׁוּבָה"],["מִי שֶׁשָּׁב רַק בְּזִקְנוּתוֹ, כְּשֶׁאֵין לוֹ כֹּחַ לַחְטֹא – מָה דִּינוֹ?",["תְּשׁוּבָתוֹ אֵינָהּ מוֹעִילָה כְּלָל, כִּי אִחֵר","נֶחְשָׁב בַּעַל תְּשׁוּבָה, אַף שֶׁאֵינָהּ תְּשׁוּבָה מְעֻלָּה","זוֹ הַתְּשׁוּבָה הַגְּמוּרָה וְהַמְּעֻלָּה בְּיוֹתֵר","עָלָיו לְחַכּוֹת לְיוֹם הַכִּפּוּרִים הַבָּא"],1,"אֵין זוֹ תְּשׁוּבָה מְעֻלָּה, אֲבָל הוּא נֶחְשָׁב בַּעַל תְּשׁוּבָה. תְּשׁוּבָה גְּמוּרָה הִיא כְּשֶׁפּוֹרְשִׁים מֵחֵטְא כְּשֶׁיֵּשׁ הִזְדַּמְּנוּת.","פֶּרֶק ע״ח, הֲלָכָה ח׳","מִצְוַת הַתְּשׁוּבָה"],["מִי שֶׁבִּיֵּשׁ אֶת חֲבֵרוֹ – מָתַי יוֹם הַכִּפּוּרִים מְכַפֵּר לוֹ?",["מִיָּד, גַּם אִם לֹא דִּבֵּר עִם חֲבֵרוֹ","רַק אִם יִתְעַנֶּה יוֹם נוֹסָף אַחֲרָיו","אַחֲרֵי שֶׁיְּפַיֵּס אֶת חֲבֵרוֹ וִיתַקֵּן אֶת מַעֲשָׂיו","אַף פַּעַם, חֵטְא כָּזֶה אֵין לוֹ כַּפָּרָה"],2,"יוֹם הַכִּפּוּרִים אֵינוֹ מְכַפֵּר עַד שֶׁיְּפַיֵּס אֶת חֲבֵרוֹ, וְאַחַר כָּךְ יִתְוַדֶּה לִפְנֵי ה׳ וִיקַבֵּל שֶׁלֹּא יָשׁוּב לְחֵטְא זֶה.","פֶּרֶק ע״ח, הֲלָכָה ט׳","מִצְוַת הַתְּשׁוּבָה"],["חָבֵר מְבַקֵּשׁ מִמְּךָ מְחִילָה. כֵּיצַד עָלֶיךָ לְהִתְנַהֵג?",["לְסָרֵב בַּפַּעַם הָרִאשׁוֹנָה כְּדֵי שֶׁיִּלְמַד לֶקַח","לִהְיוֹת רַחְמָן וְלִסְלֹחַ לוֹ בְּלֵב שָׁלֵם","לִסְלֹחַ בַּפֶּה, אֲבָל לִשְׁמֹר כַּעַס בַּלֵּב","לִסְלֹחַ רַק אִם יִתֵּן לְךָ מַתָּנָה"],1,"מִי שֶׁמְּבַקְּשִׁים מִמֶּנּוּ מְחִילָה – עָלָיו לִהְיוֹת רַחְמָן וְלִסְלֹחַ בְּלֵב שָׁלֵם.","פֶּרֶק ע״ח, הֲלָכָה י׳","מִצְוַת הַתְּשׁוּבָה"],["מָה הַדִּין אִם הַנִּפְגָּע הוּא רַבּוֹ שֶׁל מְבַקֵּשׁ הַמְּחִילָה?",["מְנַסֶּה שָׁלוֹשׁ פְּעָמִים כְּמוֹ אֵצֶל כָּל אָדָם","מְבַקֵּשׁ פַּעַם אַחַת בִּלְבַד וְדַי בְּכָךְ","אֵין צֹרֶךְ לְבַקֵּשׁ מְחִילָה מֵרַב כְּלָל","חַיָּב לְנַסּוֹת לְפַיֵּס אוֹתוֹ אֲפִלּוּ אֶלֶף פְּעָמִים"],3,"אֵצֶל חָבֵר שׁוֹלְחִים שְׁלוֹשָׁה אֲנָשִׁים עַד שָׁלוֹשׁ פְּעָמִים, וְאִם לֹא מָחַל – הוּא הַחוֹטֵא. אֲבָל רַבּוֹ – חַיָּב לְפַיֵּס אֲפִלּוּ אֶלֶף פְּעָמִים.","פֶּרֶק ע״ח, הֲלָכָה י״א","מִצְוַת הַתְּשׁוּבָה"],["מַדּוּעַ מַזְכִּירִים ״חַיִּים״ בְּכָל הַתּוֹסָפוֹת שֶׁל הַיָּמִים הָאֵלֶּה?",["כִּי בְּיָמִים אֵלּוּ אָנוּ נִכְתָּבִים לְחַיִּים","כִּי זוֹ תְּפִלָּה מְיֻחֶדֶת לַחוֹלִים בִּלְבַד","כִּי כָּךְ נוֹהֲגִים רַק בְּחֹדֶשׁ אֱלוּל","כִּי הַמִּלָּה חַיִּים קְצָרָה וְקַלָּה לִזְכֹּר"],0,"בְּכָל הַבַּקָּשׁוֹת אָנוּ מַזְכִּירִים אֶת הַחַיִּים, שֶׁכֵּן בְּיָמִים אֵלּוּ אָנוּ נִכְתָּבִים לְחַיִּים.","פֶּרֶק ע״ט, הֲלָכָה א׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מִי שֶׁשָּׁכַח ״בְּסֵפֶר חַיִּים״ וְנִזְכַּר לִפְנֵי שֶׁאָמַר אֶת שֵׁם ה׳ – מָה דִּינוֹ?",["חוֹזֵר לְרֹאשׁ כָּל הַתְּפִלָּה מֵהַתְחָלָה","אָסוּר לוֹ לַחְזֹר וּמַמְשִׁיךְ כָּרָגִיל","יָכוֹל לַחְזֹר וְלוֹמַר אֶת הַתּוֹסֶפֶת","יַגִּיד אֶת הַתּוֹסֶפֶת בַּתְּפִלָּה הַבָּאָה"],2,"אִם נִזְכַּר לִפְנֵי שֶׁהִזְכִּיר אֶת שֵׁם ה׳ – יָכוֹל לַחְזֹר. אִם כְּבָר הִזְכִּיר – אָסוּר לוֹ לַחְזֹר.","פֶּרֶק ע״ט, הֲלָכָה א׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["אֵיזֶה שִׁנּוּי קָטָן עוֹשִׂים בְּסִיּוּם הָעֲמִידָה וּבְסִיּוּם הַקַּדִּישׁ?",["מוֹסִיפִים אֶת הָאוֹת ה׳ וְאוֹמְרִים עוֹשֶׂה הַשָּׁלוֹם","מוֹסִיפִים פַּעַם נוֹסֶפֶת אֶת הַמִּלִּים עוֹשֶׂה שָׁלוֹם","מְדַלְּגִים עַל עוֹשֶׂה שָׁלוֹם וּמְסַיְּמִים בְּאָמֵן","אוֹמְרִים מֵשִׂים שָׁלוֹם בִּמְקוֹם עוֹשֶׂה שָׁלוֹם"],0,"בְּסִיּוּם הָעֲמִידָה וּבְסִיּוּם הַקַּדִּישׁ אוֹמְרִים ״עוֹשֶׂה הַשָּׁלוֹם״ בִּמְקוֹם ״עוֹשֶׂה שָׁלוֹם״.","פֶּרֶק ע״ט, הֲלָכוֹת ב׳, י״ב","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["אֵילוּ בְּרָכוֹת מְשַׁנּוֹת אֶת סִיּוּמָן לְ״הַמֶּלֶךְ״ בִּימוֹת הַחֹל שֶׁל עֲשֶׂרֶת יְמֵי תְּשׁוּבָה?",["בִּרְכַּת אָבוֹת וּבִרְכַּת שִׂים שָׁלוֹם בִּלְבַד","בִּרְכַּת הוֹדָאָה וּבִרְכַּת רְפָאֵנוּ שֶׁל הַחוֹלִים","קְדֻשַּׁת הַשֵּׁם וּבִרְכַּת הֲשָׁבַת הַמִּשְׁפָּט","בִּרְכַּת הַמִּינִים וּבִרְכַּת שׁוֹמֵעַ תְּפִלָּה"],2,"בִּקְדֻשַּׁת הַשֵּׁם אוֹמְרִים ״הַמֶּלֶךְ הַקָּדוֹשׁ״, מִפְּנֵי שֶׁבַּיָּמִים אֵלּוּ נִכֶּרֶת מַלְכוּת ה׳. בִּימוֹת הַחֹל אוֹמְרִים בַּהֲשָׁבַת הַמִּשְׁפָּט ״הַמֶּלֶךְ הַמִּשְׁפָּט״.","פֶּרֶק ע״ט, הֲלָכוֹת ג׳, ז׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מַדּוּעַ מִי שֶׁטָּעָה בְּ״הַמֶּלֶךְ הַקָּדוֹשׁ״ וְלֹא תִּקֵּן בַּזְּמַן חוֹזֵר לְרֹאשׁ הַתְּפִלָּה?",["כִּי אָסוּר לְהַתְחִיל בְּרָכָה בְּאֶמְצַע הַתְּפִלָּה","כִּי כָּל טָעוּת בַּתְּפִלָּה מְחַיֶּבֶת לַחְזֹר לָרֹאשׁ","כִּי בַּיָּמִים הָאֵלֶּה צָרִיךְ לְהִתְפַּלֵּל פַּעֲמַיִם","כִּי שָׁלוֹשׁ הַבְּרָכוֹת הָרִאשׁוֹנוֹת נֶחְשָׁבוֹת כִּבְרָכָה אַחַת"],3,"שָׁלוֹשׁ הַבְּרָכוֹת הָרִאשׁוֹנוֹת נֶחְשָׁבוֹת כִּבְרָכָה אַחַת. אֲבָל מִי שֶׁתִּקֵּן תּוֹךְ כְּדֵי דִּבּוּר – אֵינוֹ צָרִיךְ לַחְזֹר.","פֶּרֶק ע״ט, הֲלָכוֹת ד׳, ה׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מַדּוּעַ מִי שֶׁאֵינוֹ זוֹכֵר מָה אָמַר – דִּינוֹ כְּמִי שֶׁטָּעָה?",["כִּי מִי שֶׁשּׁוֹכֵחַ צָרִיךְ תָּמִיד לְהַחְמִיר","כִּי סָבִיר שֶׁאָמַר מַה שֶּׁהוּא רָגִיל לוֹמַר","כִּי אָסוּר לִסְמֹךְ עַל הַזִּכָּרוֹן בִּתְפִלָּה","כִּי כָּךְ נוֹהֲגִים רַק בְּיוֹם הַכִּפּוּרִים עַצְמוֹ"],1,"סָבִיר לְהָנִיחַ שֶׁאָמַר אֶת מַה שֶּׁהוּא רָגִיל לוֹמַר כָּל הַשָּׁנָה – גַּם בְּ״הַמֶּלֶךְ הַקָּדוֹשׁ״ וְגַם בְּ״הַמֶּלֶךְ הַמִּשְׁפָּט״.","פֶּרֶק ע״ט, הֲלָכוֹת ו׳, י׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["סְפָרַדִּי שֶׁאָמַר ״מֶלֶךְ אוֹהֵב צְדָקָה וּמִשְׁפָּט״ וְהִמְשִׁיךְ לְבִרְכַּת הַמִּינִים – מָה דִּינוֹ?",["אֵינוֹ חוֹזֵר כִּי הִזְכִּיר אֶת הַמִּלָּה מֶלֶךְ","חוֹזֵר לְבִרְכַּת הָשִׁיבָה שׁוֹפְטֵינוּ וּמַמְשִׁיךְ מִשָּׁם","חוֹזֵר תָּמִיד לְבִרְכַּת אָבוֹת שֶׁבְּרֹאשׁ הַתְּפִלָּה","אוֹמֵר הַמֶּלֶךְ הַמִּשְׁפָּט בְּסוֹף הַתְּפִלָּה"],1,"לְמִנְהַג רֹב הַסְּפָרַדִּים חוֹזֵר לְ״הָשִׁיבָה שׁוֹפְטֵינוּ״, וְאִם סִיֵּם אֶת הַתְּפִלָּה חוֹזֵר לָרֹאשׁ. לְמִנְהַג הָאַשְׁכְּנַזִּים אֵינוֹ חוֹזֵר. וְאִם תִּקֵּן תּוֹךְ כְּדֵי דִּבּוּר – אֵינוֹ צָרִיךְ לַחְזֹר.","פֶּרֶק ע״ט, הֲלָכוֹת ח׳, ט׳","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מָה מְשַׁנִּים הָאַשְׁכְּנַזִּים בַּקַּדִּישׁ בַּעֲשֶׂרֶת יְמֵי תְּשׁוּבָה?",["מוֹסִיפִים אָבִינוּ מַלְכֵּנוּ בְּאֶמְצַע הַקַּדִּישׁ","אוֹמְרִים אֶת הַקַּדִּישׁ פַּעֲמַיִם בְּכָל תְּפִלָּה","אוֹמְרִים לְעֵלָּא וּלְעֵלָּא בִּמְקוֹם לְעֵלָּא מִן","מְדַלְּגִים עַל אֲמִירַת הַקַּדִּישׁ בַּיָּמִים אֵלּוּ"],2,"מִנְהַג הָאַשְׁכְּנַזִּים לוֹמַר ״לְעֵלָּא וּלְעֵלָּא מִכָּל בִּרְכָתָא״ בִּמְקוֹם ״לְעֵלָּא מִן כָּל בִּרְכָתָא״.","פֶּרֶק ע״ט, הֲלָכָה י״א","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מָתַי נוֹהֲגִים לְהוֹסִיף ״אָבִינוּ מַלְכֵּנוּ״ בַּעֲשֶׂרֶת יְמֵי תְּשׁוּבָה?",["אַחֲרֵי חֲזָרַת הַשַּׁ״ץ בְּשַׁחֲרִית וּבְמִנְחָה","לִפְנֵי קְרִיאַת שְׁמַע בְּכָל תְּפִלַּת עַרְבִית","רַק בְּלֵיל רֹאשׁ הַשָּׁנָה אַחֲרֵי הַסְּעוּדָה","בְּאֶמְצַע תְּפִלַּת הָעֲמִידָה בְּבִרְכַּת אָבוֹת"],0,"לְאַחַר חֲזָרַת הַשַּׁ״ץ בִּתְפִלַּת שַׁחֲרִית וּבִתְפִלַּת מִנְחָה נוֹהֲגִים לְהוֹסִיף ״אָבִינוּ מַלְכֵּנוּ״.","פֶּרֶק ע״ט, הֲלָכָה י״ג","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["אֵיזֶה מִזְמוֹר רַבִּים מוֹסִיפִים אַחֲרֵי ״יִשְׁתַּבַּח״?",["מִזְמוֹר כ״ג בִּתְהִלִּים, ה׳ רוֹעִי לֹא אֶחְסָר","שִׁירַת הַיָּם שֶׁל מֹשֶׁה וּבְנֵי יִשְׂרָאֵל","פֶּרֶק רִאשׁוֹן מִתּוֹךְ מְגִלַּת אֶסְתֵּר","מִזְמוֹר ק״ל בִּתְהִלִּים, שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים"],3,"רַבִּים מוֹסִיפִים אֶת מִזְמוֹר ק״ל בִּתְהִלִּים, ״שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים״, לְאַחַר בִּרְכַּת ״יִשְׁתַּבַּח״.","פֶּרֶק ע״ט, הֲלָכָה י״ד","תְּפִלּוֹת עֲשֶׂרֶת יְמֵי תְּשׁוּבָה"],["מִמָּה לָמְדוּ חֲכָמִים שֶׁיֵּשׁ מִצְוָה לֶאֱכֹל בְּעֶרֶב יוֹם הַכִּפּוּרִים?",["מִן הַמִּצְוָה לֶאֱכֹל שָׁלֹשׁ סְעוּדוֹת בְּכָל שַׁבָּת","מִפְּנֵי שֶׁבְּעֶרֶב יוֹם הַכִּפּוּרִים אֵין אוֹמְרִים תַּחֲנוּן","הַפָּסוּק אוֹמֵר לְהִתְעַנּוֹת בַּתִּשְׁעָה, וְהַצּוֹם הוּא בָּעֲשָׂרָה","מִסִּפּוּר עַל מֶלֶךְ שֶׁעָרַךְ סְעוּדָה גְּדוֹלָה לַשָּׂרִים"],2,"הַפָּסוּק אוֹמֵר \"וְעִנִּיתֶם... בְּתִשְׁעָה לַחֹדֶשׁ\", וַהֲלֹא מִתְעַנִּים בָּעֲשָׂרָה! אֶלָּא שֶׁהָאוֹכֵל בַּתְּשִׁיעִי – כְּאִלּוּ הִתְעַנָּה תְּשִׁיעִי וַעֲשִׂירִי.","פֶּרֶק פ׳, הֲלָכָה א׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מַהוּ הַטַּעַם ״הֶהָפוּךְ״ לַאֲכִילָה הַמְּרֻבָּה בְּעֶרֶב יוֹם הַכִּפּוּרִים?",["כְּדֵי שֶׁלֹּא נַרְגִּישׁ רָעֵב כְּלָל בְּיוֹם הַכִּפּוּרִים","כְּדֵי לִגְמֹר אֶת כָּל הָאֹכֶל שֶׁנִּשְׁאַר בַּבַּיִת","כְּדֵי שֶׁיִּהְיֶה לָנוּ כֹּחַ לָלֶכֶת לְבֵית הַכְּנֶסֶת","קָשֶׁה יוֹתֵר לָצוּם אַחֲרֵי אֲכִילָה מְרֻבָּה, וְכָךְ הָעִנּוּי כָּפוּל"],3,"קָשֶׁה יוֹתֵר לָצוּם אַחֲרֵי שֶׁהַגּוּף הִתְרַגֵּל לְאֹכֶל רַב, וְלָכֵן הַצּוֹם נֶחְשָׁב כִּשְׁנֵי יְמֵי עִנּוּי. טַעַם נוֹסָף: יוֹם הַכִּפּוּרִים הוּא יוֹם שִׂמְחָה, וְעוֹרְכִים סְעוּדַת חַג.","פֶּרֶק פ׳, הֲלָכָה ב׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מַדּוּעַ מִתְוַדִּים כְּבָר בִּתְפִלַּת מִנְחָה לִפְנֵי הַסְּעוּדָה הַמַּפְסֶקֶת?",["כִּי בְּיוֹם הַכִּפּוּרִים עַצְמוֹ אָסוּר לוֹמַר וִדּוּי כְּלָל","שֶׁאִם תִּקְרֶה תַּקָּלָה בַּסְּעוּדָה, לְפָחוֹת אָמַר וִדּוּי פַּעַם אַחַת","כְּדֵי שֶׁהָאֹכֶל בַּסְּעוּדָה יִהְיֶה טָעִים יוֹתֵר מִן הָרָגִיל","כִּי תְּפִלַּת מִנְחָה הִיא הַתְּפִלָּה הַחֲשׁוּבָה בְּיוֹתֵר בַּשָּׁנָה"],1,"אִם חָלִילָה תִּקְרֶה לָאָדָם תַּקָּלָה בַּסְּעוּדָה וְלֹא יוּכַל לְהִתְפַּלֵּל בְּיוֹם הַכִּפּוּרִים – לְפָחוֹת אָמַר וִדּוּי פַּעַם אַחַת.","פֶּרֶק פ׳, הֲלָכָה ג׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מָה נָכוֹן לְגַבֵּי הַסְּעוּדוֹת בְּעֶרֶב יוֹם הַכִּפּוּרִים?",["טוֹבְלִים אֶת פְּרוּסַת הַמּוֹצִיא בְּסֻכָּר אוֹ בִּדְבַשׁ","בַּסְּעוּדָה הַמַּפְסֶקֶת אוֹכְלִים מַאֲכָלִים כְּבֵדִים וּמְשַׂבְּעִים בְּמִיוּחָד","טוֹבְלִים אֶת פְּרוּסַת הַמּוֹצִיא בְּמֶלַח הַרְבֵּה פְּעָמִים","אוֹכְלִים רַק לֶחֶם וּמַיִם, בְּלִי שׁוּם תַּבְשִׁיל"],0,"נוֹהֲגִים לִטְבֹּל אֶת הַמּוֹצִיא בְּסֻכָּר אוֹ בִּדְבַשׁ בְּכָל סְעוּדוֹת הַיּוֹם. וּבַסְּעוּדָה הַמַּפְסֶקֶת אוֹכְלִים מַאֲכָלִים קַלִּים לְעִכּוּל, כְּדֵי שֶׁלֹּא נִהְיֶה שְׂבֵעִים וּמִתְגָּאִים בַּתְּפִלָּה.","פֶּרֶק פ׳, הֲלָכָה ד׳-ה׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מַדּוּעַ מְסַיְּמִים אֶת הַסְּעוּדָה הַמַּפְסֶקֶת כַּמָּה דַּקּוֹת לִפְנֵי הַשְּׁקִיעָה?",["כְּדֵי לְהַסְפִּיק לִשְׁטֹף אֶת כָּל הַכֵּלִים","כִּי אַחֲרֵי הַשְּׁקִיעָה כְּבָר אֵין אוֹר בַּבַּיִת","כִּי חוֹבָה לְהוֹסִיף מֵהַחֹל עַל הַקֹּדֶשׁ","כְּדֵי לְהַגִּיעַ רִאשׁוֹנִים לְבֵית הַכְּנֶסֶת לִפְנֵי כֻּלָּם"],2,"חוֹבָה לְהוֹסִיף מֵהַחֹל עַל הַקֹּדֶשׁ. זְמַן תְּחִלַּת הַתַּעֲנִית שֶׁבְּלוּחוֹת הַשָּׁנָה כְּבָר כּוֹלֵל תּוֹסֶפֶת זוֹ.","פֶּרֶק פ׳, הֲלָכָה ו׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מַה צְּרִיכִים לַעֲשׂוֹת הַהוֹרִים אִם הַיְּלָדִים לֹא בִּקְּשׁוּ מֵהֶם מְחִילָה?",["לְחַכּוֹת עַד שֶׁהַיְּלָדִים יָבוֹאוּ וִיבַקְּשׁוּ מְחִילָה בְּעַצְמָם","לִמְחֹל רַק בַּלֵּב, בְּלִי לוֹמַר שׁוּם מִלָּה","לֹא לִמְחֹל, כִּי רַק הַיְּלָדִים חַיָּבִים לְבַקֵּשׁ","לִמְחֹל לָהֶם לִפְנִים מִשּׁוּרַת הַדִּין וְלוֹמַר זֹאת בַּפֶּה"],3,"עַל הַיְּלָדִים לְבַקֵּשׁ מְחִילָה מֵהַהוֹרִים, וְאִם לֹא בִּקְּשׁוּ – הַהוֹרִים מוֹחֲלִים לִפְנִים מִשּׁוּרַת הַדִּין וְאוֹמְרִים בַּפֶּה: \"אֲנִי מוֹחֵל מְחִילָה גְּמוּרָה...\".","פֶּרֶק פ׳, הֲלָכָה ז׳-ח׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מַה עוֹשִׂים בִּבְשַׂר הַכַּפָּרוֹת לְפִי הַמִּנְהָג?",["אוֹכְלִים אוֹתוֹ בְּעַצְמֵנוּ בִּסְעוּדַת מוֹצָאֵי יוֹם הַכִּפּוּרִים","נוֹתְנִים אוֹתוֹ לָעֲנִיִּים לַאֲכִילָה בְּעֶרֶב יוֹם הַכִּפּוּרִים וּבְמוֹצָאָיו","שׁוֹמְרִים אוֹתוֹ בַּמְּקָרֵר עַד חַג הַסֻּכּוֹת הַקָּרוֹב","מוֹכְרִים אוֹתוֹ בַּשּׁוּק וְקוֹנִים בַּכֶּסֶף נֵרוֹת לְבֵית הַכְּנֶסֶת"],1,"אֶת הַבָּשָׂר נוֹתְנִים לָעֲנִיִּים כְּדֵי שֶׁיִּהְיֶה לָהֶם מָה לֶאֱכֹל בְּעֶרֶב יוֹם הַכִּפּוּרִים וּבְמוֹצָאֵי הַתַּעֲנִית.","פֶּרֶק פ׳, הֲלָכָה ט׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מַדּוּעַ נָהֲגוּ רַבִּים לִטְבֹּל בַּמִּקְוֶה בְּעֶרֶב יוֹם הַכִּפּוּרִים?",["כְּדֵי לְטַהֵר אֶת עַצְמָם לִפְנֵי הַיּוֹם הַקָּדוֹשׁ","כְּדֵי לְהִתְקָרֵר בַּמַּיִם לִפְנֵי הַצּוֹם הָאָרֹךְ","כִּי אָסוּר לָגֶשֶׁת לְבֵית הַכְּנֶסֶת בְּלִי טְבִילָה","כְּדֵי לִלְמֹד לִשְׂחוֹת לִכְבוֹד הַחַג"],0,"רַבִּים נָהֲגוּ לִטְבֹּל בַּמִּקְוֶה כְּדֵי לְטַהֵר אֶת עַצְמָם לִפְנֵי הַיּוֹם הַקָּדוֹשׁ.","פֶּרֶק פ׳, הֲלָכָה י׳","עֶרֶב יוֹם הַכִּפּוּרִים"],["מַדּוּעַ יֵשׁ שֶׁנָּהֲגוּ לִלְבֹּשׁ בְּגָדִים לְבָנִים בְּיוֹם הַכִּפּוּרִים?",["כִּי בְּגָדִים לְבָנִים נוֹחִים יוֹתֵר בִּימוֹת הַקַּיִץ","כְּדֵי שֶׁיִּהְיֶה קַל לִרְאוֹת אִם הִתְלַכְלְכוּ","כִּי בְּיוֹם זֶה אָנוּ דּוֹמִים לְמַלְאֲכֵי הַשָּׁרֵת","כִּי אָסוּר לִלְבֹּשׁ בְּגָדִים צִבְעוֹנִיִּים בְּבֵית הַכְּנֶסֶת"],2,"מַלְאֲכֵי הַשָּׁרֵת אֵינָם אוֹכְלִים וְאֵינָם שׁוֹתִים, וּבְיוֹם זֶה אָנוּ דּוֹמִים לָהֶם. וּבִכְלָל מְכַבְּדִים אֶת הַיּוֹם בִּכְסוּת נְקִיָּה וּבְמַפּוֹת נָאוֹת, כְּמוֹ בְּשַׁבָּת.","פֶּרֶק פ׳, הֲלָכָה י״א-י״ב","עֶרֶב יוֹם הַכִּפּוּרִים"],["אֵיזוֹ בְּרָכָה מְבָרְכִים עַל הַנֵּרוֹת כְּשֶׁיּוֹם הַכִּפּוּרִים חָל בְּשַׁבָּת?",["לְהַדְלִיק נֵר שֶׁל יוֹם טוֹב בִּלְבַד","לְהַדְלִיק נֵר שֶׁל שַׁבָּת וְיוֹם הַכִּפּוּרִים","אֵין מַדְלִיקִים נֵרוֹת כְּלָל בְּיוֹם הַכִּפּוּרִים","לְהַדְלִיק נֵר שֶׁל שַׁבָּת בִּלְבַד, בְּלִי יוֹם הַכִּפּוּרִים"],1,"בְּכָל שָׁנָה מְבָרְכִים \"לְהַדְלִיק נֵר שֶׁל יוֹם הַכִּפּוּרִים\", וְכְשֶׁחָל בְּשַׁבָּת – \"לְהַדְלִיק נֵר שֶׁל שַׁבָּת וְיוֹם הַכִּפּוּרִים\".","פֶּרֶק פ׳, הֲלָכָה י״ג","עֶרֶב יוֹם הַכִּפּוּרִים"],["מָתַי מַתְחִיל יוֹם הַכִּפּוּרִים, וְכַמָּה עִנּוּיִים יֵשׁ בּוֹ?",["מֵהָעֶרֶב, וְיֵשׁ בּוֹ חֲמִשָּׁה עִנּוּיִים שׁוֹנִים","מֵהַבֹּקֶר, וְיֵשׁ בּוֹ שְׁלוֹשָׁה עִנּוּיִים בִּלְבַד","מֵהָעֶרֶב, וְיֵשׁ בּוֹ רַק עִנּוּי אֶחָד","מֵהַצָּהֳרַיִם, וְיֵשׁ בּוֹ עֲשָׂרָה עִנּוּיִים שׁוֹנִים"],0,"״מֵעֶרֶב עַד עֶרֶב תִּשְׁבְּתוּ שַׁבַּתְּכֶם״ - הַיּוֹם מַתְחִיל מֵהָעֶרֶב. וְהָעִנּוּי כּוֹלֵל חֲמִשָּׁה אִסּוּרִים: אֲכִילָה וּשְׁתִיָּה, רְחִיצָה, סִיכָה, נְעִילַת הַסַּנְדָּל וְתַשְׁמִישׁ הַמִּטָּה.","פֶּרֶק פ״א, הֲלָכוֹת א׳-ב׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["מַדּוּעַ יוֹם הַכִּפּוּרִים הוּא יוֹם שִׂמְחָה לַמְרוֹת הַתַּעֲנִית?",["כִּי אוֹכְלִים בּוֹ סְעוּדָה גְּדוֹלָה וַחֲגִיגִית","כִּי ה׳ מְכַפֵּר בּוֹ עַל הַחֲטָאִים","כִּי אֵין בּוֹ תְּפִלּוֹת אֲרֻכּוֹת בִּכְלָל","כִּי זֶה הַיּוֹם הָאַחֲרוֹן שֶׁל הַשָּׁנָה"],1,"״כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם מִכֹּל חַטֹּאתֵיכֶם״ - וְלָכֵן אָמְרוּ חֲכָמִים שֶׁלֹּא הָיוּ יָמִים טוֹבִים לְיִשְׂרָאֵל כְּמוֹתוֹ.","פֶּרֶק פ״א, הֲלָכָה ג׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["מָה הַדִּין לַעֲשׂוֹת מְלָאכָה בְּיוֹם הַכִּפּוּרִים?",["מֻתָּר, כִּי זֶה יוֹם חֹל רָגִיל","מֻתָּר לַעֲשׂוֹת רַק מְלָאכוֹת קַלּוֹת וּקְטַנּוֹת","אָסוּר, אֲבָל רַק בִּשְׁעוֹת הַבֹּקֶר","אָסוּר לַעֲשׂוֹת מְלָאכָה, כְּמוֹ בְּשַׁבָּת"],3,"״וְכָל מְלָאכָה לֹא תַעֲשׂוּ בְּעֶצֶם הַיּוֹם הַזֶּה״ - מִכָּאן שֶׁבְּיוֹם הַכִּפּוּרִים אָסוּר לַעֲשׂוֹת מְלָאכָה, כְּמוֹ בְּשַׁבָּת.","פֶּרֶק פ״א, הֲלָכָה ד׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["דָּנִי קָם בַּבֹּקֶר שֶׁל יוֹם הַכִּפּוּרִים. אֵיךְ יִטֹּל אֶת יָדָיו?",["יִטֹּל כָּרָגִיל עַד שׁוֹרֶשׁ כַּף הַיָּד","רַק עַד סוֹף קִשְׁרֵי הָאֶצְבָּעוֹת","יִרְחַץ אֶת כָּל הַיָּד עַד הַמַּרְפֵּק","לֹא יִטֹּל אֶת יָדָיו כְּלָל"],1,"בְּיוֹם הַכִּפּוּרִים אָסוּר לִרְחֹץ אֲפִלּוּ אֵיבָר אֶחָד, וְלָכֵן בַּבֹּקֶר וְאַחֲרֵי הַשֵּׁרוּתִים נוֹטְלִים רַק עַד סוֹף קִשְׁרֵי הָאֶצְבָּעוֹת.","פֶּרֶק פ״א, הֲלָכוֹת ה׳-ו׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["מָה מִן הַבָּאִים מֻתָּר לַעֲשׂוֹת בְּיוֹם הַכִּפּוּרִים?",["לִמְרֹחַ קְרֵם לָחוּת עַל מָקוֹם קָטָן","לִרְחֹץ אֶת הַפָּנִים לְשֵׁם רַעֲנוּת","לִשְׁטֹף מֵהַגּוּף לִכְלוּךְ אוֹ רֵיחַ רַע","לִמְרֹחַ שֶׁמֶן עַל הַיָּדַיִם הַיְּבֵשׁוֹת"],2,"שְׁטִיפָה לְהָסָרַת לִכְלוּךְ אוֹ רֵיחַ רַע מֻתֶּרֶת כִּי אֵינָהּ לְשֵׁם תַּעֲנוּג. אֲבָל סִיכָה - מְרִיחַת שֶׁמֶן אוֹ קְרֵם - אֲסוּרָה אֲפִלּוּ עַל מָקוֹם קָטָן.","פֶּרֶק פ״א, הֲלָכוֹת ז׳-ח׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["אֵילוּ נַעֲלַיִם מֻתָּר לִנְעֹל בְּיוֹם הַכִּפּוּרִים?",["נַעֲלַיִם מֵעוֹר, אִם הֵן נוֹחוֹת","סַנְדָּלִים מֵעוֹר, אֲבָל לֹא נַעֲלַיִם","רַק נַעֲלַיִם חֲדָשׁוֹת שֶׁלֹּא נִנְעֲלוּ","נַעֲלַיִם מִגּוּמִי, בַּד אוֹ חֳמָרִים אֲחֵרִים"],3,"אָסוּר לִנְעֹל סַנְדָּלִים אוֹ נַעֲלַיִם מֵעוֹר, אֲבָל מֻתָּר לִנְעֹל נַעֲלַיִם מִגּוּמִי, בַּד אוֹ חֳמָרִים אֲחֵרִים.","פֶּרֶק פ״א, הֲלָכָה ט׳","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["יֶלֶד בֶּן תֵּשַׁע - מָה עָלָיו לַעֲשׂוֹת בְּיוֹם הַכִּפּוּרִים?",["לְהִתְעַנּוֹת תַּעֲנִית שָׁעוֹת, לְפִי כֹּחוֹ","לֹא לְהִתְעַנּוֹת כְּלָל, גַּם אִם רוֹצֶה","לְהִתְעַנּוֹת אֶת כָּל הַיּוֹם כְּמוֹ גָּדוֹל","לְהִתְעַנּוֹת רַק מִן הַבֹּקֶר עַד הָעֶרֶב"],0,"יְלָדִים שֶׁמָּלְאוּ לָהֶם תֵּשַׁע מִתְעַנִּים ״תַּעֲנִית שָׁעוֹת״ - מְאַחֲרִים אֶת הָאֲרוּחָה בְּשָׁעָה, לְפִי כֹּחָם. מִתַּחַת לְגִיל תֵּשַׁע לֹא מִתְעַנִּים כְּלָל.","פֶּרֶק פ״א, הֲלָכוֹת י׳-י״א","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["יַלְדָּה בַּת שְׁתֵּים עֶשְׂרֵה - הַאִם עָלֶיהָ לְהִתְעַנּוֹת בְּיוֹם הַכִּפּוּרִים?",["לֹא, הִיא מִתְעַנָּה רַק תַּעֲנִית שָׁעוֹת","כֵּן, הִיא כִּגְדוֹלָה וְחַיֶּבֶת בְּתַעֲנִית","רַק עַד חֲצוֹת, וְאַחַר כָּךְ אוֹכֶלֶת","לֹא, רַק בֶּן שְׁלוֹשׁ עֶשְׂרֵה חַיָּב"],1,"יַלְדָּה בַּת שְׁתֵּים עֶשְׂרֵה וְיֶלֶד בֶּן שְׁלוֹשׁ עֶשְׂרֵה הֵם כִּגְדוֹלִים לְכָל הַמִּצְווֹת וְחַיָּבִים בְּתַעֲנִית. בְּגִיל אַחַת עֶשְׂרֵה יֵשׁ מַחְלֹקֶת אִם מַשְׁלִימִים.","פֶּרֶק פ״א, הֲלָכוֹת י״ב-י״ג","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["מַדּוּעַ פִּקּוּחַ נֶפֶשׁ דּוֹחֶה אֶת תַּעֲנִית יוֹם הַכִּפּוּרִים?",["כִּי הַתַּעֲנִית הִיא רַק מִנְהָג וְלֹא חוֹבָה","כִּי מִי שֶׁחוֹלֶה פָּטוּר מִכָּל הַמִּצְווֹת לְעוֹלָם","כִּי ה׳ נָתַן מִצְווֹת כְּדֵי שֶׁנִּחְיֶה בָּהֶן","כִּי אָסוּר לְהִתְעַנּוֹת יוֹתֵר מֵחֲצִי יוֹם"],2,"״וָחַי בָּהֶם״ - הַמִּצְווֹת נִתְּנוּ כְּדֵי שֶׁנִּחְיֶה בָּהֶן. לָכֵן מִי שֶׁיֵּשׁ סַכָּנָה לְחַיָּיו חַיָּב לֶאֱכֹל, וְחוֹבָה לְהַזְעִיק עֶזְרָה. רַק שָׁלוֹשׁ עֲבֵרוֹת אֵינָן נִדְחוֹת.","פֶּרֶק פ״א, הֲלָכָה י״ד","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["אִשָּׁה בְּהֵרָיוֹן אוֹ מֵינִיקָה, שֶׁאֵין בָּהּ סַכָּנָה - מָה דִּינָהּ בְּיוֹם הַכִּפּוּרִים?",["פְּטוּרָה מִן הַתַּעֲנִית לְגַמְרֵי, וְאוֹכֶלֶת כָּרָגִיל","מִתְעַנָּה רַק עַד חֲצוֹת הַיּוֹם","צְרִיכָה לְהִתְעַנּוֹת, וְאִם יֵשׁ סַכָּנָה תֹּאכַל","אוֹכֶלֶת רַק בְּשִׁעוּרִים קְטַנִּים כָּל הַיּוֹם"],2,"חוֹלִים שֶׁאֵין בָּהֶם סַכָּנָה, נָשִׁים בְּהֵרָיוֹן וּמֵינִיקוֹת צְרִיכִים לְהִתְעַנּוֹת, וְעָדִיף שֶׁיִּשְׁכְּבוּ בְּמִטָּתָם. אִם יֵשׁ חֲשַׁשׁ סַכָּנָה - יֹאכְלוּ, וּמַאֲכִילִים לְשִׁעוּרִים לְפִי הוֹרָאַת תַּלְמִיד חָכָם וְרוֹפֵא.","פֶּרֶק פ״א, הֲלָכוֹת ט״ו-ט״ז","תַּעֲנִית יוֹם הַכִּפּוּרִים"],["מַה קּוֹרְאִים בַּתּוֹרָה בְּיוֹם הַכִּפּוּרִים, בִּמְקוֹם עֲבוֹדַת הַכֹּהֵן הַגָּדוֹל?",["אֶת פָּרָשַׁת עֲבוֹדַת הַכֹּהֵן הַגָּדוֹל מִסֵּפֶר וַיִּקְרָא","אֶת פָּרָשַׁת קְרִיעַת יַם סוּף מִסֵּפֶר שְׁמוֹת","אֶת פָּרָשַׁת בְּרִיאַת הָעוֹלָם מִסֵּפֶר בְּרֵאשִׁית","אֶת פָּרָשַׁת הַמְּרַגְּלִים מִסֵּפֶר בְּמִדְבַּר בִּלְבַד"],0,"קוֹרְאִים מִסֵּפֶר וַיִּקְרָא (פֶּרֶק ט״ז), וְאוֹמְרִים בְּמוּסָף פִּיּוּטִים עַל סֵדֶר הָעֲבוֹדָה. כְּדַאי לִלְמֹד אוֹתוֹ הֵיטֵב כְּדֵי לְהָבִין מָה אוֹמְרִים.","פֶּרֶק פ״ב, הֲלָכָה א׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["לְפִי הַמִּדְרָשׁ, מָה מְכַפֵּר עָלֵינוּ כְּשֶׁאֵין בֵּית מִקְדָּשׁ?",["קָרְבָּנוֹת שֶׁמַּקְרִיבִים בְּבָתֵּי הַכְּנֶסֶת בְּכָל מָקוֹם","הַתְּפִלָּה, שֶׁחֲבִיבָה לִפְנֵי ה׳ כְּמוֹ הַשָּׂעִיר","נִגּוּנִים יָפִים וַאֲרֻכִּים שֶׁל הַחַזָּן בִּלְבַד","צוֹם אָרֹךְ שֶׁל שְׁלוֹשָׁה יָמִים רְצוּפִים"],1,"״וּמִדְבָּרֵךְ נָאוֶה״ – דִּבּוּר הַתְּפִלָּה נָאֶה לִפְנֵי ה׳ כְּמוֹ הַשָּׂעִיר הַמִּשְׁתַּלֵּחַ. וְהָעִקָּר אֵינוֹ הַנִּגּוּן אֶלָּא כַּוָּנַת הַלֵּב.","פֶּרֶק פ״ב, הֲלָכָה ב׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["לָמָּה מַקְפִּידִים לְהִתְעַטֵּף בְּטַלִּית לִפְנֵי הַשְּׁקִיעָה?",["כְּדֵי שֶׁהַטַּלִּית לֹא תִּתְלַכְלֵךְ בַּדֶּרֶךְ לַבַּיִת","כְּדֵי לְהַסְפִּיק לֶאֱכֹל לִפְנֵי הַצּוֹם","כְּדֵי שֶׁיִּהְיֶה אֶפְשָׁר לְבָרֵךְ עַל הַטַּלִּית","כְּדֵי שֶׁנַּגִּיעַ רִאשׁוֹנִים לְבֵית הַכְּנֶסֶת"],2,"אַחֲרֵי הַשְּׁקִיעָה כְּבָר אִי אֶפְשָׁר לְבָרֵךְ עַל הַטַּלִּית, לָכֵן מִתְעַטְּפִים לִפְנֵיהָ.","פֶּרֶק פ״ב, הֲלָכָה ג׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["מַה מְּיֻחָד בַּפִּיּוּט ״לְךָ אֵ-לִי״?",["חִבֵּר אוֹתוֹ רַבִּי יְהוּדָה הַלֵּוִי, וְהוּא כֻּלּוֹ וִדּוּי","חִבֵּר אוֹתוֹ הָרַמְבַּ״ם, וְהוּא כֻּלּוֹ שִׁירֵי שִׂמְחָה","אוֹמְרִים אוֹתוֹ רַק בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים בַּבַּיִת","הוּא נֶאֱמָר רַק בְּבָתֵּי כְּנֶסֶת שֶׁל הָאַשְׁכְּנַזִּים"],0,"הַסְּפָרַדִּים פּוֹתְחִים בּוֹ כְּדֵי לְהִכָּנֵס לַיּוֹם בִּתְשׁוּבָה. הָאַשְׁכְּנַזִּים אוֹמְרִים מֵאוֹתוֹ טַעַם ״תְּפִלָּה זַכָּה״.","פֶּרֶק פ״ב, הֲלָכָה ד׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["מַדּוּעַ אוֹמְרִים ״כָּל נִדְרֵי״ לִפְנֵי תְּפִלּוֹת הַיּוֹם?",["כִּי זוֹ הַתְּפִלָּה הַקְּצָרָה בְּיוֹתֵר בְּכָל הַמַּחְזוֹר","כִּי מִי שֶׁיֵּשׁ בּוֹ עֲווֹן נְדָרִים, תְּפִלָּתוֹ אֵינָהּ נִשְׁמַעַת","כִּי כָּךְ מַתְחִילִים כָּל תְּפִלַּת עַרְבִית בְּכָל הַשָּׁנָה","כְּדֵי לְבָרֵךְ ״שֶׁהֶחֱיָנוּ״ עַל הַטַּלִּית לִפְנֵי שֶׁיַּחְשִׁיךְ לְגַמְרֵי"],1,"״כָּל נִדְרֵי״ מַתִּירָה נִדְרֵי עָבָר וּמְבַטֶּלֶת נְדָרִים שֶׁל הַשָּׁנָה הַבָּאָה. בְּסִיּוּמָהּ מְבָרְכִים ״שֶׁהֶחֱיָנוּ״ עַל שֶׁזָּכִינוּ לְהַגִּיעַ לְיוֹם הַכִּפּוּרִים.","פֶּרֶק פ״ב, הֲלָכוֹת ה׳-ו׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["כְּשֶׁיּוֹם הַכִּפּוּרִים חָל בְּשַׁבָּת, מָה מוֹסִיפִים בְּעַרְבִית?",["קִדּוּשׁ עַל הַיַּיִן וּשְׁתִיַּת כּוֹס קְטַנָּה מִמֶּנּוּ","אֲמִירַת הַלֵּל שָׁלֵם עִם בְּרָכָה בַּצִּבּוּר","תְּקִיעוֹת שׁוֹפָר כְּמוֹ בְּרֹאשׁ הַשָּׁנָה בְּדִיּוּק","קַבָּלַת שַׁבָּת מְקֻצֶּרֶת, ״וַיְכֻלּוּ״ וּבִרְכַּת ״מֵעֵין שֶׁבַע״"],3,"אַחֲרֵי כָּל נִדְרֵי אוֹמְרִים קַבָּלַת שַׁבָּת מְקֻצֶּרֶת, וְאַחֲרֵי הָעֲמִידָה ״וַיְכֻלּוּ״ וּ״מֵעֵין שֶׁבַע״.","פֶּרֶק פ״ב, הֲלָכָה ז׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["מַדּוּעַ אוֹמְרִים ״בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ״ בְּקוֹל רָם?",["כִּי בְּיוֹם זֶה יִשְׂרָאֵל דּוֹמִים לַמַּלְאָכִים","כְּדֵי שֶׁהַיְלָדִים הַקְּטַנִּים יִשְׁמְעוּ וְיִלְמְדוּ","כִּי בְּיוֹם זֶה אָסוּר לְהִתְפַּלֵּל בְּלַחַשׁ","כְּדֵי לְהָעִיר אֶת מִי שֶׁנִּרְדַּם"],0,"הַמַּלְאָכִים אוֹמְרִים מִלִּים אֵלּוּ בְּקוֹל רָם. יֵשׁ מְקוֹמוֹת שֶׁכָּל הַצִּבּוּר קוֹרֵא קְרִיאַת שְׁמַע יַחַד בְּקוֹל רָם, וּמִנְהָג יָפֶה הוּא.","פֶּרֶק פ״ב, הֲלָכָה ח׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["בְּאֵילוּ תְּפִלּוֹת מִתְוַדִּים בְּיוֹם הַכִּפּוּרִים עַצְמוֹ?",["רַק בִּתְפִלַּת נְעִילָה, בְּסוֹף הַיּוֹם","רַק בְּמִנְחָה שֶׁל עֶרֶב יוֹם הַכִּפּוּרִים","בְּכָל אַחַת מֵחָמֵשׁ הַתְּפִלּוֹת שֶׁל הַיּוֹם","רַק בְּעַרְבִית וּבְשַׁחֲרִית, וְלֹא יוֹתֵר"],2,"מִתְוַדִּים בְּעַרְבִית, שַׁחֲרִית, מוּסָף, מִנְחָה וּנְעִילָה. אֲבָל הַוִּדּוּי לֹא מוֹעִיל בְּלִי חֲרָטָה וְקַבָּלָה לֹא לַחְזֹר עַל הַחֵטְא.","פֶּרֶק פ״ב, הֲלָכָה ט׳","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["מַה עוֹשִׂים בִּזְמַן אֲמִירַת הַוִּדּוּי?",["יוֹשְׁבִים בְּשֶׁקֶט וְעוֹצְמִים אֶת הָעֵינַיִם","עוֹמְדִים, וּמַכִּים מְעַט עַל הַלֵּב בְּכָל חֵטְא","עוֹמְדִים וּמוֹחֲאִים כַּפַּיִם בְּשִׂמְחָה גְּדוֹלָה מְאוֹד","כּוֹרְעִים עַל הַבִּרְכַּיִם וּמַשְׁתַּחֲוִים עַד הָרִצְפָּה"],1,"אוֹמְרִים אֶת הַוִּדּוּי בַּעֲמִידָה, וּמַכִּים עַל הַלֵּב כְּאִלּוּ אוֹמְרִים לוֹ: אַתָּה גָּרַמְתָּ לָנוּ לַחְטֹא.","פֶּרֶק פ״ב, הֲלָכוֹת י׳-י״א","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["מִתְוַדִּים גַּם עַל חֲטָאִים שֶׁכְּבָר שַׁבְנוּ מֵהֶם, וְגַם עַל חֲטָאִים שֶׁלֹּא עָשִׂינוּ. לָמָּה עַל אֵלֶּה שֶׁלֹּא עָשִׂינוּ?",["כִּי כָּל יִשְׂרָאֵל עֲרֵבִים זֶה לָזֶה","כִּי אָסוּר לְדַלֵּג עַל שׁוּם מִלָּה בַּסִּדּוּר","כְּדֵי שֶׁהַתְּפִלָּה תִּהְיֶה אֲרֻכָּה יוֹתֵר","כְּדֵי לְהִתְאַמֵּן לִקְרַאת הַשָּׁנָה הַבָּאָה"],0,"כָּל יִשְׂרָאֵל עֲרֵבִים זֶה לָזֶה, וְלָכֵן הַוִּדּוּי בִּלְשׁוֹן רַבִּים; וְגַם כְּדֵי שֶׁמִּי שֶׁחָטָא לֹא יִתְבַּיֵּשׁ. וְעַל חֲטָאִים שֶׁשַּׁבְנוּ מֵהֶם מְשֻׁבָּח לַחְזֹר וּלְהִתְוַדּוֹת: ״וְחַטָּאתִי נֶגְדִּי תָמִיד״.","פֶּרֶק פ״ב, הֲלָכוֹת י״ב-י״ג","תְּפִלּוֹת יוֹם הַכִּפּוּרִים"],["מָה לוֹמְדִים מִסֵּפֶר יוֹנָה שֶׁמַּפְטִירִים בּוֹ בְּמִנְחָה?",["שֶׁאִי אֶפְשָׁר לִבְרֹחַ מֵה׳, וְשֶׁהַתְּשׁוּבָה קוֹרַעַת גְּזַר דִּין","שֶׁצָּרִיךְ לְהַרְבּוֹת בְּמַסָּעוֹת בַּיָּם כְּדֵי לְהִתְקָרֵב לַה׳","שֶׁאָסוּר לָשׁוּב בִּתְשׁוּבָה אַחֲרֵי שֶׁנִּגְזַר כְּבָר הַדִּין","שֶׁנִּינְוֵה הָיְתָה הָעִיר הַגְּדוֹלָה בְּיוֹתֵר בָּעוֹלָם כֻּלּוֹ"],0,"מִסֵּפֶר יוֹנָה לוֹמְדִים שֶׁאִי אֶפְשָׁר לִבְרֹחַ מִלִּפְנֵי ה׳, וְאֶת כֹּחָהּ שֶׁל הַתְּשׁוּבָה שֶׁיְּכוֹלָה לִקְרֹעַ אֶת גְּזַר הַדִּין.","פֶּרֶק פ״ב, הֲלָכָה י״ד","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מַדּוּעַ רָאוּי לְהִתְאַמֵּץ מְאֹד דַּוְקָא בִּתְפִלַּת נְעִילָה?",["כִּי הִיא הַתְּפִלָּה הָאֲרֻכָּה בְּיוֹתֵר שֶׁל כָּל הַשָּׁנָה","כִּי הִיא נֶאֱמֶרֶת בַּבֹּקֶר כְּשֶׁכֻּלָּם עֲדַיִן עֵרִים וּרְעֵנִים","כִּי הִיא בְּסִיּוּם הַיּוֹם, וְהַכֹּל הוֹלֵךְ אַחַר הַחִתּוּם","כִּי רַק מִי שֶׁהַצּוֹם קַל לוֹ חַיָּב לְהִתְפַּלֵּל"],2,"נְעִילָה הִיא בִּנְעִילַת הַיּוֹם, וְהַכֹּל הוֹלֵךְ אַחַר הַחִתּוּם. לָכֵן גַּם מִי שֶׁהַתַּעֲנִית קָשָׁה לוֹ מִתְאַמֵּץ כְּכָל יְכָלְתּוֹ.","פֶּרֶק פ״ב, הֲלָכָה ט״ו-ט״ז","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מַדּוּעַ אוֹמְרִים בִּנְעִילָה ״חָתְמֵנוּ״ בִּמְקוֹם ״כָּתְבֵנוּ״?",["כִּי כָּךְ נוֹהֲגִים רַק בַּשָּׁנָה שֶׁיּוֹם הַכִּפּוּרִים בְּשַׁבָּת","כִּי זֶהוּ הַזְּמַן שֶׁבּוֹ נֶחְתָּם הַדִּין שֶׁל כָּל אָדָם","כִּי הַמִּלָּה ״כָּתְבֵנוּ״ קָשָׁה מְאֹד לְבַטֵּא אַחֲרֵי יוֹם צוֹם","כִּי ״חָתְמֵנוּ״ הִיא מִלָּה עַתִּיקָה יוֹתֵר מִ״כָּתְבֵנוּ״"],1,"בִּנְעִילָה אוֹמְרִים ״חָתְמֵנוּ״ וַ״חֲתֹם״, מִפְּנֵי שֶׁזֶּהוּ זְמַן חֲתִימַת הַדִּין.","פֶּרֶק פ״ב, הֲלָכָה י״ז","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["בִּרְכַּת כֹּהֲנִים שֶׁל נְעִילָה כֹּה חֲבִיבָה, שֶׁבִּירוּשָׁלַיִם אַף מְבַשְּׂמִים אֶת מֵי הַנְּטִילָה. וּמָה אִם כְּבָר שָׁקְעָה הַחַמָּה?",["מְבַטְּלִים אֶת הַבְּרָכָה, כִּי אַחֲרֵי הַשְּׁקִיעָה אֵין מְבָרְכִים לְעוֹלָם","הַחַזָּן לְבַדּוֹ אוֹמֵר אֶת הַבְּרָכָה בִּמְקוֹם הַכֹּהֲנִים","דּוֹחִים אֶת בִּרְכַּת הַכֹּהֲנִים לִתְפִלַּת עַרְבִית שֶׁל מוֹצָאֵי הַיּוֹם","כְּדַאי לִסְמֹךְ עַל הַמַּתִּירִים, וְהַכֹּהֲנִים נוֹשְׂאִים כַּפַּיִם"],3,"לְכַתְּחִלָּה מִזְדָּרְזִים לְהַגִּיעַ לִפְנֵי הַשְּׁקִיעָה. אִם כְּבָר שָׁקְעָה, כְּדַאי לִסְמֹךְ עַל הַסּוֹבְרִים שֶׁאֶפְשָׁר לָשֵׂאת כַּפַּיִם, וְלֹא לְבַטֵּל אֶת הַבְּרָכָה.","פֶּרֶק פ״ב, הֲלָכָה י״ח-י״ט","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מָה הַסֵּדֶר בְּסוֹף תְּפִלַּת נְעִילָה?",["שְׁמַע יִשְׂרָאֵל, בָּרוּךְ שֵׁם, שֶׁבַע פְּעָמִים ״ה׳ הוּא הָאֱ-לֹהִים״, וְתוֹקְעִים","תּוֹקְעִים בַּשּׁוֹפָר קֹדֶם, וְאַחַר כָּךְ אוֹמְרִים שְׁמַע יִשְׂרָאֵל","אוֹמְרִים ״ה׳ הוּא הָאֱ-לֹהִים״ פַּעַם אַחַת בִּלְבַד, בְּלִי שׁוֹפָר","קוֹרְאִים בַּתּוֹרָה וּמַפְטִירִים שׁוּב בְּסֵפֶר יוֹנָה כֻּלּוֹ"],0,"אוֹמְרִים שְׁמַע יִשְׂרָאֵל, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ, וְשֶׁבַע פְּעָמִים ״ה׳ הוּא הָאֱ-לֹהִים״, וְאַחַר כָּךְ תּוֹקְעִים בַּשּׁוֹפָר.","פֶּרֶק פ״ב, הֲלָכָה כ׳","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מַדּוּעַ מְסַיְּמִים בַּפָּסוּק ״לֵךְ אֱכֹל בְּשִׂמְחָה לַחְמֶךָ״?",["כִּי סוֹף סוֹף מֻתָּר לֶאֱכֹל, וְהַבֶּטֶן כְּבָר רְעֵבָה מְאֹד","מִתּוֹךְ אֱמוּנָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קִבֵּל אֶת תְּפִלּוֹתֵינוּ","כְּדֵי לְהַזְכִּיר לְכֻלָּם לְהָכִין סְעוּדָה גְּדוֹלָה לַחַג","כִּי זֶה הַפָּסוּק הָאַחֲרוֹן שֶׁבְּסֵפֶר קֹהֶלֶת"],1,"מִתּוֹךְ אֱמוּנָה שֶׁה׳ קִבֵּל אֶת מַעֲשֵׂינוּ וּתְפִלּוֹתֵינוּ – ״כִּי כְבָר רָצָה הָאֱ-לֹהִים אֶת מַעֲשֶׂיךָ״.","פֶּרֶק פ״ב, הֲלָכָה כ״א","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מַדּוּעַ מְקַדְּשִׁים אֶת הַלְּבָנָה בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים?",["כִּי הַלְּבָנָה נִרְאֵית רַק בְּלַיְלָה זֶה שֶׁל הַחֹדֶשׁ","כִּי מוֹצָאֵי יוֹם הַכִּפּוּרִים הוּא זְמַן שֶׁל שִׂמְחָה","כִּי אָסוּר לֶאֱכֹל עַד שֶׁמְּקַדְּשִׁים אֶת הַלְּבָנָה","כִּי כָּךְ מַשְׁלִימִים אֶת חֲמֵשׁ תְּפִלּוֹת הַיּוֹם הַקָּדוֹשׁ"],1,"נוֹהֲגִים לְקַדֵּשׁ אֶת הַלְּבָנָה אַחֲרֵי עַרְבִית, מִפְּנֵי שֶׁמּוֹצָאֵי יוֹם הַכִּפּוּרִים הוּא זְמַן שִׂמְחָה.","פֶּרֶק פ״ב, הֲלָכָה כ״ב","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מַה מְּיֻחָד בְּהַבְדָּלָה שֶׁל מוֹצָאֵי יוֹם הַכִּפּוּרִים (כְּשֶׁאֵינוֹ חָל בְּשַׁבָּת)?",["מְבָרְכִים עַל נֵר שֶׁשָּׁבַת, וְאֵין מְבָרְכִים עַל בְּשָׂמִים","מְבָרְכִים עַל בְּשָׂמִים בִּלְבַד, בְּלִי יַיִן וּבְלִי נֵר","אֵין מַבְדִּילִים כְּלָל, וּמִיָּד מַתְחִילִים לֶאֱכֹל","מְבָרְכִים עַל נֵר חָדָשׁ שֶׁהֻדְלַק עַכְשָׁו מִגַּפְרוּר"],0,"מְבָרְכִים עַל הַגֶּפֶן וְעַל נֵר שֶׁשָּׁבַת, בְּלִי בְּשָׂמִים. אַחַר כָּךְ אוֹכְלִים וּשְׂמֵחִים מִתּוֹךְ בִּטָּחוֹן שֶׁה׳ רָצָה אֶת מַעֲשֵׂינוּ.","פֶּרֶק פ״ב, הֲלָכָה כ״ג-כ״ד","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מַדּוּעַ מַתְחִילִים לִבְנוֹת סֻכָּה כְּבָר בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים?",["כִּי אַחַר כָּךְ לֹא יִשָּׁאֵר זְמַן לִבְנוֹת","כִּי הַשְּׁכֵנִים עֲלוּלִים לִתְפֹּס אֶת הַמָּקוֹם בֶּחָצֵר","כִּי בְּיוֹם שֶׁאַחֲרֵי הַצּוֹם אָסוּר לַעֲשׂוֹת מְלָאכָה","כְּדֵי לָצֵאת מִמִּצְוָה אַחַת אֶל מִצְוָה אַחֶרֶת"],3,"נוֹהֲגִים לְהַתְחִיל לִבְנוֹת אֶת הַסֻּכָּה בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים, כְּדֵי לָצֵאת מִמִּצְוָה לְמִצְוָה.","פֶּרֶק פ״ב, הֲלָכָה כ״ה","נְעִילָה וּמוֹצָאֵי יוֹם הַכִּפּוּרִים"],["מָה אָמַר רַבִּי אֱלִיעֶזֶר עַל הַסֻּכּוֹת בַּמִּדְבָּר?",["הֵן הָיוּ סֻכּוֹת מַמָּשׁ שֶׁל עֵצִים וַעֲנָפִים","הֵם יָשְׁבוּ בְּאֹהָלִים גְּדוֹלִים שֶׁל עוֹר","הַכַּוָּנָה הִיא לְעַנְנֵי הַכָּבוֹד שֶׁל ה׳","הֵם יָשְׁבוּ בִּמְעָרוֹת שֶׁבֶּהָרֵי הַמִּדְבָּר"],2,"רַבִּי אֱלִיעֶזֶר אוֹמֵר: עַנְנֵי הַכָּבוֹד. רַבִּי עֲקִיבָא אוֹמֵר: סֻכּוֹת מַמָּשׁ.","פֶּרֶק פ״ג, הֲלָכָה א׳","בְּנִיַּת הַסֻּכָּה"],["לָמָּה מִצְוַת הַסֻּכָּה חֲבִיבָה כָּל כָּךְ?",["כִּי הִיא נִמְשֶׁכֶת שִׁבְעָה יָמִים שְׁלֵמִים בְּכָל שָׁנָה","כִּי מְקַיְּמִים אוֹתָהּ בְּכָל הַגּוּף, בְּצֵל הָאֱמוּנָה","כִּי בּוֹנִים אוֹתָהּ בְּעֵצִים יָפִים וּבְקִשּׁוּטִים רַבִּים","כִּי אוֹכְלִים בָּהּ מַאֲכָלִים טְעִימִים עִם הַמִּשְׁפָּחָה"],1,"הָאָדָם מְקַיֵּם אֶת הַמִּצְוָה בְּכָל גּוּפוֹ וּמִתְקַדֵּשׁ בְּ״צִלָּא דִּמְהֵימְנוּתָא״, צֵל הָאֱמוּנָה.","פֶּרֶק פ״ג, הֲלָכָה ב׳","בְּנִיַּת הַסֻּכָּה"],["יוֹסִי רוֹצֶה לִבְנוֹת סֻכָּה מִתַּחַת לְמִרְפֶּסֶת מְקֹרָה. מָה הַדִּין?",["מֻתָּר, אִם הַמִּרְפֶּסֶת גְּבוֹהָה מְאֹד מֵעַל הַסְּכָךְ","מֻתָּר, אִם מַנִּיחִים הַרְבֵּה סְכָךְ עָבֶה מְאֹד","מֻתָּר, רַק אִם יֵשׁ בַּסֻּכָּה אַרְבַּע דְּפָנוֹת","אָסוּר, הַסֻּכָּה צְרִיכָה לִהְיוֹת תַּחַת כִּפַּת הַשָּׁמַיִם"],3,"אֵין לַעֲשׂוֹת סֻכָּה מִתַּחַת לְבַיִת, מִרְפֶּסֶת מְקֹרָה אוֹ עַנְפֵי עֵץ.","פֶּרֶק פ״ג, הֲלָכָה ג׳","בְּנִיַּת הַסֻּכָּה"],["דָּנִי הִנִּיחַ קֹדֶם סְכָךְ וְאַחַר כָּךְ בָּנָה דְּפָנוֹת. מָה יַעֲשֶׂה?",["יַגְבִּיהַּ אֶת הַסְּכָךְ וְיַנִּיחֶנּוּ שׁוּב לְשֵׁם מִצְוָה","אֵין צֹרֶךְ לַעֲשׂוֹת דָּבָר, הַסֻּכָּה כְּשֵׁרָה לְגַמְרֵי","יִפְרֹק אֶת כָּל הַסֻּכָּה וְיִבְנֶה סֻכָּה חֲדָשָׁה","יוֹסִיף עוֹד דֹּפֶן רְבִיעִית מִסָּבִיב לַסֻּכָּה"],0,"״תַּעֲשֶׂה – וְלֹא מִן הֶעָשׂוּי״: הַסֻּכָּה פְּסוּלָה, וְהַתִּקּוּן הוּא לְהַגְבִּיהַּ אֶת הַסְּכָךְ וּלְהַחְזִירוֹ לְשֵׁם מִצְוַת סֻכָּה.","פֶּרֶק פ״ג, הֲלָכָה ד׳-ה׳","בְּנִיַּת הַסֻּכָּה"],["אֵיזוֹ דֹּפֶן אָסוּר לַעֲשׂוֹת לַסֻּכָּה?",["דֹּפֶן שֶׁהַשֶּׁמֶשׁ חוֹדֶרֶת דַּרְכָּהּ אֶל תּוֹךְ הַסֻּכָּה","דֹּפֶן מֵעָלִים שֶׁיִּתְיַבְּשׁוּ וְלֹא יִשָּׁאֵר מֵהֶם מְחִצָּה","דֹּפֶן מִפְּלַסְטִיק אוֹ מִבַּרְזֶל אוֹ מִכָּל חֹמֶר","דֹּפֶן מִקְּרָשִׁים שֶׁל עֵץ צְבוּעִים בְּצֶבַע"],1,"דְּפָנוֹת כְּשֵׁרוֹת מִכָּל חֹמֶר, גַּם אִם הַשֶּׁמֶשׁ חוֹדֶרֶת. אֲבָל לֹא מִדָּבָר שֶׁרֵיחוֹ רַע אוֹ שֶׁיִּתְיַבֵּשׁ וְלֹא יִשָּׁאֵר שִׁעוּר מְחִצָּה.","פֶּרֶק פ״ג, הֲלָכָה ו׳","בְּנִיַּת הַסֻּכָּה"],["מַהוּ הַגֹּבַהּ הַקָּטָן בְּיוֹתֵר שֶׁל דֹּפֶן הַסֻּכָּה?",["שְׁלוֹשָׁה טְפָחִים, שֶׁהֵם עֶשְׂרִים וְאַרְבָּעָה סֶנְטִימֶטֶר","שְׁנֵי מֶטֶר לְפָחוֹת, כְּמוֹ גֹּבַהּ שֶׁל בַּיִת","עֲשָׂרָה טְפָחִים, שֶׁהֵם שְׁמוֹנִים סֶנְטִימֶטֶר","עַד הַסְּכָךְ מַמָּשׁ, בְּלִי שׁוּם רֶוַח"],2,"לְפָחוֹת עֲשָׂרָה טְפָחִים (80 ס״מ), וּלְהִדּוּר מֶטֶר. אֵין חוֹבָה שֶׁהַדְּפָנוֹת יַגִּיעוּ עַד הַסְּכָךְ.","פֶּרֶק פ״ג, הֲלָכָה ז׳","בְּנִיַּת הַסֻּכָּה"],["אֵיךְ אֶפְשָׁר לַעֲשׂוֹת דֹּפֶן מֵחֲבָלִים מְתוּחִים?",["שֶׁהָרֶוַח בֵּין חֶבֶל לְחֶבֶל יִהְיֶה מֶטֶר שָׁלֵם","אִי אֶפְשָׁר, דֹּפֶן חַיֶּבֶת לִהְיוֹת מִקִּיר אָטוּם","צָרִיךְ לִמְתֹּחַ חֶבֶל אֶחָד בִּלְבַד בְּרֹאשׁ הַדֹּפֶן","שֶׁהָרֶוַח בֵּין חֶבֶל לְחֶבֶל יִהְיֶה פָּחוֹת מִשְּׁלוֹשָׁה טְפָחִים"],3,"זֶהוּ דִּין ״לָבוּד״: רֶוַח שֶׁל פָּחוֹת מִשְּׁלוֹשָׁה טְפָחִים נֶחְשָׁב מְחֻבָּר, וְהַחֶבֶל הָעֶלְיוֹן לְפָחוֹת בְּגֹבַהּ 80 ס״מ.","פֶּרֶק פ״ג, הֲלָכָה ח׳","בְּנִיַּת הַסֻּכָּה"],["דֹּפֶן מֻגְבַּהַת שְׁלוֹשָׁה טְפָחִים מֵהָאֲדָמָה. מָה דִּינָהּ?",["כְּשֵׁרָה, כִּי הַחֵלֶק הָעֶלְיוֹן שֶׁלָּהּ גָּבוֹהַּ מְאֹד","פְּסוּלָה, כִּי גְּדָיִים יְכוֹלִים לַעֲבֹר מִתַּחְתֶּיהָ","כְּשֵׁרָה, אִם הִיא עֲשׂוּיָה מֵעֵץ חָזָק וְעָבֶה","פְּסוּלָה, כִּי הִיא צְרִיכָה לְהַגִּיעַ עַד הַסְּכָךְ"],1,"מְחִצָּה שֶׁהַגְּדָיִים יְכוֹלִים לַעֲבֹר מִתַּחְתֶּיהָ אֵינָהּ נֶחְשֶׁבֶת מְחִצָּה, גַּם אִם הִיא גְּבוֹהָה.","פֶּרֶק פ״ג, הֲלָכָה ט׳","בְּנִיַּת הַסֻּכָּה"],["מָה עָדִיף לַעֲשׂוֹת כְּשֶׁהַדֹּפֶן עֲשׂוּיָה מִיְּרִיעַת בַּד?",["לִמְתֹּחַ אֶת הַבַּד וּלְהוֹסִיף מַקְּלוֹת אוֹ חֲבָלִים מְתוּחִים","לְהַשְׁאִיר אֶת הַבַּד רָפוּי כְּדֵי שֶׁיָּזוּז בָּרוּחַ","לְהַחְלִיף אֶת הַבַּד בַּעֲנָפִים יְרֻקִּים שֶׁל עֵץ","לְהַנִּיחַ אֶת הַבַּד עַל הַסְּכָךְ שֶׁל הַסֻּכָּה"],0,"הַדְּפָנוֹת צְרִיכוֹת לַעֲמֹד בְּרוּחַ מְצוּיָה. נֶחְלְקוּ הַפּוֹסְקִים עַל בַּד מִתְנַדְנֵד, לָכֵן עָדִיף לְהוֹסִיף מַקְּלוֹת אוֹ חֲבָלִים, וּבְכָל מִקְרֶה לִמְתֹּחַ וְלִקְשֹׁר.","פֶּרֶק פ״ג, הֲלָכָה י׳-י״א","בְּנִיַּת הַסֻּכָּה"],["מָה הֵם שְׁלוֹשֶׁת הַתְּנָאִים שֶׁל סְכָךְ כָּשֵׁר?",["מְחֻבָּר לָאֲדָמָה, יָרֹק, וְנוֹתֵן תָּמִיד הַרְבֵּה צֵל","עָשׂוּי מִבַּרְזֶל, יָפֶה, וְאֵינוֹ נִרְטָב בַּגֶּשֶׁם","גָּדֵל מִן הָאָרֶץ, תָּלוּשׁ, וְאֵינוֹ מְקַבֵּל טֻמְאָה","קָנוּי בַּחֲנוּת, חָדָשׁ, וְאֵינוֹ כָּבֵד מִדַּי לְהָרִים"],2,"סְכָךְ כָּשֵׁר: גִּדּוּלוֹ מִן הָאָרֶץ, תָּלוּשׁ, וְאֵינוֹ מְקַבֵּל טֻמְאָה – כְּמוֹ עַנְפֵי עֵצִים, קְרָשִׁים פְּשׁוּטִים אוֹ מַחְצָלוֹת קָנִים.","פֶּרֶק פ״ג, הֲלָכָה י״ב","סְכָךְ וְנוֹי סֻכָּה"],["אֵיזֶה סְכָךְ אֵין לְסַכֵּךְ בּוֹ אֶת הַסֻּכָּה?",["סְכָךְ שֶׁנִּקְנָה לִקְרַאת הַחַג בַּחֲנוּת הַקְּרוֹבָה","עַנְפֵי עֵצִים יְרֻקִּים שֶׁנִּכְרְתוּ אֶתְמוֹל מֵהָעֵץ","מַחְצְלוֹת קָנִים שֶׁנִּמְכָּרוֹת לִקְרַאת חַג הַסֻּכּוֹת","סְכָךְ שֶׁרֵיחוֹ רַע אוֹ שֶׁעָלָיו נוֹשְׁרִים"],3,"סְכָךְ שֶׁרֵיחוֹ רַע אוֹ שֶׁעָלָיו נוֹשְׁרִים – אֵין לְסַכֵּךְ בּוֹ אֶת הַסֻּכָּה.","פֶּרֶק פ״ג, הֲלָכָה י״ג","סְכָךְ וְנוֹי סֻכָּה"],["אֵיזֶה מִשְׁפָּט נָכוֹן לְגַבֵּי הַמַּעֲמִידִים וְהַחִבּוּרִים שֶׁל הַסְּכָךְ?",["מַנִּיחִים סְכָךְ יָשָׁר עַל הַבַּרְזֶל, וְאָסוּר לִקְשֹׁר בַּחֲבָלִים","מַנִּיחִים קְרָשֵׁי עֵץ עַל הַבַּרְזֶל, וּמֻתָּר לִקְשֹׁר בַּחֲבָלִים","מַנִּיחִים שְׂמִיכוֹת יְשָׁנוֹת עַל הַבַּרְזֶל, וְחוֹבָה לִקְשֹׁר בְּמַסְמְרִים","אָסוּר לִבְנוֹת לְעוֹלָם סֻכָּה עִם מִסְגֶּרֶת בַּרְזֶל בִּכְלָל"],1,"אֵין לְהַעֲמִיד סְכָךְ עַל דָּבָר הַמְּקַבֵּל טֻמְאָה, לָכֵן מַנִּיחִים קְרָשֵׁי עֵץ עַל הַבַּרְזִלִּים. מֻתָּר לְחַבֵּר אֶת עֲצֵי הַסְּכָךְ בַּחֲבָלִים אוֹ בְּמַסְמְרִים שֶׁלֹּא יָעוּפוּ, וְיֵשׁ מַחְמִירִים.","פֶּרֶק פ״ג, הֲלָכָה י״ד-ט״ו","סְכָךְ וְנוֹי סֻכָּה"],["מָה פֵּרוּשׁ ״צִלָּתָהּ מְרֻבָּה מֵחַמָּתָהּ״?",["הַשֶּׁמֶשׁ בַּסֻּכָּה מְרֻבָּה מֵהַצֵּל שֶׁנּוֹצָר מֵהַסְּכָךְ","הַסֻּכָּה צְרִיכָה לִהְיוֹת חַמָּה יוֹתֵר מֵהַבַּיִת","הַצֵּל בַּסֻּכָּה מְרֻבֶּה מֵהַשֶּׁמֶשׁ שֶׁנִּכְנֶסֶת דֶּרֶךְ הַסְּכָךְ","בַּסֻּכָּה יוֹשְׁבִים רַק בַּצֵּל וְלֹא בַּשֶּׁמֶשׁ"],2,"עַל יְדֵי הַסְּכָךְ הַצֵּל בַּסֻּכָּה צָרִיךְ לִהְיוֹת מְרֻבֶּה מֵהַשֶּׁמֶשׁ. אִם הַמַּצָּב הָפוּךְ – הַסֻּכָּה פְּסוּלָה.","פֶּרֶק פ״ג, הֲלָכָה ט״ז","סְכָךְ וְנוֹי סֻכָּה"],["לְמָה שׁוֹאֲפִים לְכַתְּחִלָּה כְּשֶׁמְּסַכְּכִים אֶת הַסֻּכָּה?",["שֶׁהַסְּכָךְ יִהְיֶה צָפוּף מְאֹד כְּמוֹ גַּג","שֶׁהַגְּשָׁמִים לֹא יַחְדְּרוּ דֶּרֶךְ הַסְּכָךְ","שֶׁהַשֶּׁמֶשׁ תִּכָּנֵס לַסֻּכָּה יוֹתֵר מֵהַצֵּל","שֶׁהַכּוֹכָבִים הַגְּדוֹלִים יֵרָאוּ דֶּרֶךְ הַסְּכָךְ"],3,"לְכַתְּחִלָּה אֵין לְסַכֵּךְ צָפוּף מְאֹד, כְּדֵי שֶׁהַכּוֹכָבִים הַגְּדוֹלִים יֵרָאוּ. בְּדִיעֲבַד כְּשֵׁרָה גַּם בְּלִי זֶה, וְאִם אֲפִלּוּ גְּשָׁמִים אֵינָם חוֹדְרִים – יֵשׁ פּוֹסְלִים.","פֶּרֶק פ״ג, הֲלָכָה י״ז","סְכָךְ וְנוֹי סֻכָּה"],["מֵאֵיזֶה פָּסוּק לָמְדוּ חֲכָמִים לְקַשֵּׁט אֶת הַסֻּכָּה?",["מִ״בַּסֻּכּוֹת תֵּשְׁבוּ״ שֶׁצָּרִיךְ לָשֶׁבֶת בַּסֻּכָּה שִׁבְעָה יָמִים","מִ״וְּשָׂמַחְתָּ בְּחַגֶּךָ״ שֶׁצָּרִיךְ לִשְׂמֹחַ בְּכָל יְמֵי הֶחָג","מִ״שָּׁמוֹר אֶת יוֹם הַשַּׁבָּת״ שֶׁצָּרִיךְ לְכַבֵּד אֶת הַשַּׁבָּת","מִ״זֶּה אֵ-לִי וְאַנְוֵהוּ״ לְקַיֵּם מִצְווֹת בְּצוּרָה נָאָה"],3,"כָּתוּב ״זֶה אֵ-לִי וְאַנְוֵהוּ״, וַחֲכָמִים לָמְדוּ שֶׁיֵּשׁ לְקַיֵּם מִצְווֹת ה׳ בְּצוּרָה נָאָה, וְלָכֵן מְקַשְּׁטִים אֶת הַסֻּכָּה.","פֶּרֶק פ״ג, הֲלָכָה י״ח","סְכָךְ וְנוֹי סֻכָּה"],["קִשּׁוּט שֶׁתָּלוּי תַּחַת הַסְּכָךְ – מָתַי מֻתָּר לָשֶׁבֶת תַּחְתָּיו?",["רַק כְּשֶׁהוּא רָחוֹק מֵהַסְּכָךְ יוֹתֵר מֵאַרְבָּעָה טְפָחִים","כְּשֶׁהוּא קָרוֹב לַסְּכָךְ פָּחוֹת מֵאַרְבָּעָה טְפָחִים","תָּמִיד, לֹא מְשַׁנֶּה כַּמָּה הוּא רָחוֹק","אַף פַּעַם, כִּי קִשּׁוּטִים הֵם סְכָךְ פָּסוּל"],1,"קִשּׁוּטִים הֵם סְכָךְ פָּסוּל, אֲבָל אִם הֵם קְרוֹבִים לַסְּכָךְ פָּחוֹת מֵאַרְבָּעָה טְפָחִים (32 ס״מ) – הֵם בְּטֵלִים לַסְּכָךְ.","פֶּרֶק פ״ג, הֲלָכָה י״ט","סְכָךְ וְנוֹי סֻכָּה"],["יוֹרֵד גֶּשֶׁם בַּחַג, וְהַקִּשּׁוּטִים עֲלוּלִים לְהִתְקַלְקֵל. מָה מֻתָּר?",["לְהוֹרִיד אוֹתָם וְלִתְלוֹת שׁוּב אַחֲרֵי שֶׁהַגֶּשֶׁם יִפָּסֵק","לְהוֹרִיד אוֹתָם וּלְשַׂחֵק בָּהֶם בַּבַּיִת עַד מוֹצָאֵי הֶחָג","שׁוּם דָּבָר, אָסוּר לָגַעַת בַּקִּשּׁוּטִים בְּשׁוּם מַצָּב","לְהוֹרִיד אוֹתָם וּלְחַלֵּק אוֹתָם לַחֲבֵרִים בְּמַתָּנָה"],0,"כָּל שְׁמוֹנַת יְמֵי הֶחָג אָסוּר לְהִשְׁתַּמֵּשׁ בַּעֲצֵי הַסֻּכָּה וּבְקִשּׁוּטֶיהָ, אֲבָל בְּגֶשֶׁם מֻתָּר לְטַלְטֵל קִשּׁוּטִים כְּדֵי לִתְלוֹתָם שׁוּב.","פֶּרֶק פ״ג, הֲלָכָה כ׳-כ״א","סְכָךְ וְנוֹי סֻכָּה"],["מָה צָרִיךְ לַעֲשׂוֹת מִי שֶׁרוֹצֶה לֶאֱכֹל בַּחַג מִפֵּרוֹת הַסֻּכָּה?",["לְבָרֵךְ בְּרָכָה מְיֻחֶדֶת לִפְנֵי שֶׁמּוֹרִידִים אֶת הַפְּרִי","לְחַכּוֹת שֶׁהַפְּרִי יִפֹּל מֵעַצְמוֹ מִן הַסְּכָךְ","לוֹמַר בִּשְׁעַת הַתְּלִיָּה שֶׁהוּא תּוֹלֶה בִּתְנַאי","לִשְׁאֹל אֶת רְשׁוּת כָּל בְּנֵי הַמִּשְׁפָּחָה"],2,"צָרִיךְ לוֹמַר בְּשָׁעָה שֶׁתּוֹלֶה: ״אֲנִי תּוֹלֶה אֶת הַקִּשּׁוּטִים וְהַפֵּרוֹת בִּתְנַאי שֶׁאוּכַל לְהִשְׁתַּמֵּשׁ בָּהֶם כְּשֶׁאֶרְצֶה״. גַּם אִם נָפְלוּ מֵעַצְמָם – בְּלִי תְּנַאי אֲסוּרִים.","פֶּרֶק פ״ג, הֲלָכָה כ״ב","סְכָךְ וְנוֹי סֻכָּה"],["מָה דָּרְשׁוּ חֲכָמִים עַל הַמִּלָּה ״תֵּשְׁבוּ״?",["תֵּשְׁבוּ כְּעֵין תָּדוּרוּ, לָכֵן אוֹכְלִים וִישֵׁנִים בָּהּ","שֶׁיּוֹשְׁבִים בַּסֻּכָּה רַק בִּזְמַן הַקִּדּוּשׁ בַּלַּיְלָה","שֶׁצָּרִיךְ לָשֶׁבֶת בַּסֻּכָּה רַק בַּיּוֹם הָרִאשׁוֹן","שֶׁהַסֻּכָּה מְיֹעֶדֶת רַק לְאוֹרְחִים וְלֹא לַמִּשְׁפָּחָה"],0,"״תֵּשְׁבוּ – כְּעֵין תָּדוּרוּ״: הַסֻּכָּה הוֹפֶכֶת לְבֵיתֵנוּ, וְלָכֵן אוֹכְלִים וְשׁוֹתִים בָּהּ, וְאָסוּר לִישֹׁן מִחוּץ לָהּ אֲפִלּוּ שְׁנַת עֲרַאי.","פֶּרֶק פ״ד, הֲלָכָה א׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["מִי הֵם הָאֻשְׁפִּיזִין שֶׁמַּזְמִינִים לַסֻּכָּה?",["כָּל הַשְּׁכֵנִים שֶׁגָּרִים בַּבִּנְיָן וּבָרְחוֹב שֶׁלָּנוּ","שְׁנֵים עָשָׂר שִׁבְטֵי יִשְׂרָאֵל, שֵׁבֶט בְּכָל עֶרֶב","אַבְרָהָם, יִצְחָק, יַעֲקֹב, מֹשֶׁה, אַהֲרֹן, יוֹסֵף וְדָוִד","הַנְּבִיאִים יְשַׁעְיָהוּ וְיִרְמְיָהוּ, וְאֵלִיָּהוּ הַנָּבִיא"],2,"נוֹהֲגִים לְהַזְמִין שִׁבְעָה אֻשְׁפִּיזִין. בְּכָל לַיְלָה אֶחָד מֵהֶם הוּא הָעִקָּרִי, וְעִמּוֹ מַזְמִינִים אֶת הַשְּׁאָר.","פֶּרֶק פ״ד, הֲלָכָה ט׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["אֵיזֶה דִּבּוּר מַתְאִים בְּמִיּוּחָד לַסֻּכָּה?",["שִׂיחוֹת עַל קְנִיּוֹת וְעַל מְחִירִים בַּשּׁוּק","סִפּוּרִים עַל אֲנָשִׁים אֲחֵרִים וּמַה שֶּׁעָשׂוּ","חֲדָשׁוֹת וּפוֹלִיטִיקָה מִן הָעִתּוֹן שֶׁל הַבֹּקֶר","דִּבְרֵי תּוֹרָה וּקְדֻשָּׁה, וְגַם שִׂיחַת חֲבֵרִים"],3,"בַּסֻּכָּה עוֹסְקִים בְּדִבְרֵי תּוֹרָה וּקְדֻשָּׁה, וְגַם שִׂיחַת חֲבֵרִים מְשׂוֹחֲחִים בָּהּ. נִמְנָעִים מִדִּבְרֵי חֹל, וְכָל שֶׁכֵּן מִלָּשׁוֹן הָרַע.","פֶּרֶק פ״ד, הֲלָכָה ג׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["לָמָּה אָסוּר לֶאֱכֹל אֲרוּחָה גְּדוֹלָה בְּעֶרֶב סֻכּוֹת מֵחֲצוֹת?",["כְּדֵי שֶׁנֹּאכַל בַּסֻּכָּה לְתֵאָבוֹן בְּלֵיל הַחַג","כִּי עֶרֶב סֻכּוֹת הוּא יוֹם צוֹם קָבוּעַ","כְּדֵי שֶׁיִּהְיֶה זְמַן לִבְנוֹת אֶת הַסֻּכָּה","כִּי אָסוּר לֶאֱכֹל לִפְנֵי שֶׁקּוֹנִים אַרְבָּעָה מִינִים"],0,"מִצְוָה מֵהַתּוֹרָה לֶאֱכֹל פַּת בַּסֻּכָּה בְּלֵיל ט״ו בְּתִשְׁרֵי, וְרוֹצִים לֶאֱכֹל אוֹתָהּ לְתֵאָבוֹן. מְעַט פֵּרוֹת אוֹ יְרָקוֹת – מֻתָּר.","פֶּרֶק פ״ד, הֲלָכָה ד׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["מַדּוּעַ מַרְבִּים בִּצְדָקָה לָעֲנִיִּים בְּעֶרֶב סֻכּוֹת?",["כְּדֵי שֶׁיּוּכְלוּ לִבְנוֹת סֻכָּה גְּדוֹלָה מְאוֹד","כְּדֵי לְשַׂמֵּחַ אוֹתָם בַּחַג, ״וְשָׂמַחְתָּ בְּחַגֶּךָ״","כִּי בְּסֻכּוֹת אָסוּר לָתֵת צְדָקָה בִּכְלָל","כְּדֵי שֶׁהָעֲנִיִּים יָבוֹאוּ לְהִתְפַּלֵּל אִתָּנוּ"],1,"לְפִי חַכְמֵי הַקַּבָּלָה וְחַכְמֵי הַהֲלָכָה מַרְבִּים בִּצְדָקָה כְּדֵי לְשַׂמֵּחַ אֶת הָעֲנִיִּים, כְּמוֹ שֶׁנֶּאֱמַר: ״וְהַגֵּר וְהַיָּתוֹם וְהָאַלְמָנָה״.","פֶּרֶק פ״ד, הֲלָכָה ה׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["עַל מָה מִתְיַחֶסֶת בִּרְכַּת ״שֶׁהֶחֱיָנוּ״ בְּקִדּוּשׁ לֵיל סֻכּוֹת?",["רַק עַל הַיַּיִן שֶׁבַּכּוֹס שֶׁל הַקִּדּוּשׁ","רַק עַל הָאַרְבָּעָה מִינִים שֶׁנִּטֹּל מָחָר","גַּם לְקִדּוּשׁ הַיּוֹם וְגַם לִישִׁיבָה בַּסֻּכָּה","רַק עַל הַבְּגָדִים הַחֲדָשִׁים שֶׁל הַחַג"],2,"סֵדֶר הַקִּדּוּשׁ: יַיִן, קִדּוּשׁ הַיּוֹם, ״לֵישֵׁב בַּסֻּכָּה״, ״שֶׁהֶחֱיָנוּ״. ״שֶׁהֶחֱיָנוּ״ מִתְיַחֶסֶת לְקִדּוּשׁ הַיּוֹם וּלְמִצְוַת הַסֻּכָּה.","פֶּרֶק פ״ד, הֲלָכָה ו׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["מִי שֶׁשָּׁכַח לְבָרֵךְ ״שֶׁהֶחֱיָנוּ״ בַּלַּיְלָה הָרִאשׁוֹן – מָה יַעֲשֶׂה?",["הִפְסִיד, וְאֵין לוֹ יוֹתֵר שׁוּם אֶפְשָׁרוּת לְבָרֵךְ","יָכוֹל לְבָרֵךְ כָּל שִׁבְעַת הַיָּמִים, גַּם מִחוּץ לַסֻּכָּה","יְבָרֵךְ רַק בַּלַּיְלָה הַשֵּׁנִי וְרַק בְּתוֹךְ הַסֻּכָּה","יְבָרֵךְ בְּשִׂמְחַת תּוֹרָה אַחֲרֵי הַהַקָּפוֹת"],1,"מִי שֶׁלֹּא בֵּרֵךְ ״שֶׁהֶחֱיָנוּ״ בַּלַּיְלָה הָרִאשׁוֹן – יָכוֹל לְבָרֵךְ כָּל שִׁבְעַת יְמֵי הַחַג, אֲפִלּוּ מִחוּץ לַסֻּכָּה.","פֶּרֶק פ״ד, הֲלָכָה ז׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["כַּמָּה פַּת לְפָחוֹת אוֹכְלִים בַּסֻּכָּה בַּלַּיְלָה הָרִאשׁוֹן?",["חַלָּה שְׁלֵמָה, וְאָסוּר לְהַשְׁאִיר מִמֶּנָּה פֵּרוּר","פֵּרוּר קָטָן, כְּדֵי לָצֵאת יְדֵי חוֹבָה","שְׁלוֹשָׁה כִּכָּרוֹת לֶחֶם, כְּמוֹ שָׁלוֹשׁ סְעוּדוֹת","כַּזַּיִת, וְרָאוּי לְהַדֵּר לֶאֱכֹל כַּבֵּיצָה"],3,"אוֹכְלִים לְפָחוֹת כַּזַּיִת פַּת (כִּפְרוּסַת לֶחֶם), וְרָאוּי לְהַדֵּר כַּבֵּיצָה (כִּשְׁתֵּי פְּרוּסוֹת דַּקּוֹת), בְּתוֹךְ שְׁמוֹנֶה דַּקּוֹת.","פֶּרֶק פ״ד, הֲלָכָה ח׳","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["בְּחֹל הַמּוֹעֵד רוֹצִים לֶאֱכֹל סְעוּדַת קֶבַע. מָה עוֹשִׂים?",["אוֹכְלִים בַּבַּיִת, כִּי רַק בַּלַּיְלָה הָרִאשׁוֹן חַיָּבִים","אוֹכְלִים בַּסֻּכָּה וּמְבָרְכִים לִפְנֵי כֵן ״לֵישֵׁב בַּסֻּכָּה״","אוֹכְלִים בַּחוּץ וּמְבָרְכִים ״שֶׁהֶחֱיָנוּ״ פַּעַם נוֹסֶפֶת","אוֹכְלִים מִחוּץ לַסֻּכָּה, אִם רַק מְבָרְכִים בַּסֻּכָּה"],1,"אָסוּר לֶאֱכֹל אֲכִילַת קֶבַע מִחוּץ לַסֻּכָּה. בְּרֹב הַקְּהִלּוֹת מְבָרְכִים ״לֵישֵׁב בַּסֻּכָּה״ לִפְנֵי אֲכִילַת קֶבַע, וּפוֹטְרִים גַּם יְשִׁיבָה וְשֵׁנָה עַד הַסְּעוּדָה הַבָּאָה.","פֶּרֶק פ״ד, הֲלָכָה י״א","לֵיל חַג הַסֻּכּוֹת וּמִצְוַת יְשִׁיבַת סֻכָּה"],["מַדּוּעַ נָשִׁים פְּטוּרוֹת מִמִּצְוַת סֻכָּה?",["כִּי הַסֻּכָּה קְטַנָּה מִדַּי לְכָל הַמִּשְׁפָּחָה","כִּי זוֹ מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ","כִּי הֵן עֲסוּקוֹת תָּמִיד בְּבִשּׁוּל הַסְּעוּדוֹת","כִּי אֵין לָהֶן שָׂכָר עַל הַיְּשִׁיבָה בַּסֻּכָּה"],1,"נָשִׁים פְּטוּרוֹת כִּי סֻכָּה הִיא מִצְוַת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָהּ. וְאִם הֵן יוֹשְׁבוֹת בַּסֻּכָּה – יֵשׁ לָהֶן שָׂכָר.","פֶּרֶק פ״ה, הֲלָכָה א׳","מִי חַיָּב בַּסֻּכָּה?"],["מֵאֵיזֶה גִּיל יֶלֶד חַיָּב בַּסֻּכָּה, וּמַדּוּעַ?",["מִגִּיל שָׁלוֹשׁ, כִּי כָּךְ כָּתוּב בַּתּוֹרָה","רַק מִגִּיל בַּר מִצְוָה, וְלֹא לִפְנֵי כֵן","מִגִּיל עֶשֶׂר, כְּדֵי שֶׁיַּעֲזֹר בִּבְנִיַּת הַסֻּכָּה","מִגִּיל חָמֵשׁ אוֹ שֵׁשׁ, כְּדֵי לְחַנְּכוֹ בְּמִצְווֹת"],3,"יֶלֶד קָטָן מִגִּיל חָמֵשׁ-שֵׁשׁ חַיָּב בַּסֻּכָּה מִדִּבְרֵי סוֹפְרִים (חֲכָמִים), כְּדֵי לְחַנְּכוֹ בְּמִצְווֹת.","פֶּרֶק פ״ה, הֲלָכָה ב׳","מִי חַיָּב בַּסֻּכָּה?"],["מָה לָמְדוּ חֲכָמִים מִן הַדְּרָשָׁה ״תֵּשְׁבוּ – כְּעֵין תָּדוּרוּ״?",["שֶׁהַמִּצְטַעֵר בַּסֻּכָּה פָּטוּר מִן הַסֻּכָּה","שֶׁאָסוּר לָצֵאת מֵהַסֻּכָּה כָּל שִׁבְעַת הַיָּמִים","שֶׁצָּרִיךְ לִבְנוֹת סֻכָּה מֵאֲבָנִים כְּמוֹ בַּיִת","שֶׁמֻּתָּר לֶאֱכֹל סְעוּדַת קֶבַע מִחוּץ לַסֻּכָּה"],0,"בְּשִׁבְעַת הַיָּמִים הַסֻּכָּה הִיא בֵּיתוֹ שֶׁל הָאָדָם. כְּמוֹ שֶׁאָדָם לֹא נִשְׁאָר בְּבֵיתוֹ אִם הַדָּבָר גּוֹרֵם לוֹ צַעַר, כָּךְ ״הַמִּצְטַעֵר פָּטוּר מִן הַסֻּכָּה״.","פֶּרֶק פ״ה, הֲלָכָה ג׳","מִי חַיָּב בַּסֻּכָּה?"],["בַּלַּיְלָה הָרִאשׁוֹן שֶׁל סֻכּוֹת כָּבָה הָאוֹר אוֹ יָרַד גֶּשֶׁם. מָה עוֹשִׂים?",["הוֹלְכִים מִיָּד לֶאֱכֹל בְּסֻכַּת הַשָּׁכֵן","מְקַדְּשִׁים וְאוֹכְלִים כַּזַּיִת פַּת בַּסֻּכָּה","אוֹכְלִים בַּבַּיִת וְלֹא נִכְנָסִים לַסֻּכָּה כְּלָל","מְחַכִּים בַּבַּיִת עַד הַבֹּקֶר וְאָז אוֹכְלִים"],1,"בַּלַּיְלָה הָרִאשׁוֹן חוֹבָה לֶאֱכֹל כַּזַּיִת בַּסֻּכָּה אֲפִלּוּ בַּחֲשֵׁכָה, וְחַיָּבִים לְקַדֵּשׁ בָּהּ וְלֶאֱכֹל כַּזַּיִת פַּת גַּם אִם יוֹרְדִים גְּשָׁמִים. בִּשְׁאָר הַלֵּילוֹת מִי שֶׁכָּבָה לוֹ הָאוֹר פָּטוּר.","פֶּרֶק פ״ה, הֲלָכָה ד׳, ז׳","מִי חַיָּב בַּסֻּכָּה?"],["הַאִם מֻתָּר לִבְנוֹת סֻכָּה בְּמָקוֹם שֶׁיֵּשׁ בּוֹ רֵיחַ רַע תָּמִיד?",["כֵּן, כִּי הַמִּצְטַעֵר פָּטוּר וְאֵין בְּעָיָה","כֵּן, אִם שָׂמִים בַּסֻּכָּה פְּרָחִים רֵיחָנִיִּים","לֹא, כִּי יָדוּעַ מֵרֹאשׁ שֶׁלֹּא יוּכְלוּ לְקַיֵּם הַמִּצְוָה","רַק אִם הַסֻּכָּה קְטַנָּה מְאוֹד"],2,"אֵין לִבְנוֹת סֻכָּה בְּמָקוֹם שֶׁיָּדוּעַ מֵרֹאשׁ שֶׁיִּגָּרֵם צַעַר. רַק אִם הַסֻּכָּה כְּבָר נִבְנְתָה וְאַחַר כָּךְ הִתְבָּרֵר שֶׁיֵּשׁ שָׁם דָּבָר מְצַעֵר – פְּטוּרִים.","פֶּרֶק פ״ה, הֲלָכָה ה׳","מִי חַיָּב בַּסֻּכָּה?"],["גֶּשֶׁם חָזָק נִכְנָס לַסֻּכָּה בְּאֶמְצַע הַסְּעוּדָה וּמְקַלְקֵל אֶת הָאֹכֶל. מָה הַדִּין?",["חַיָּבִים לְהַמְשִׁיךְ לֶאֱכֹל בַּסֻּכָּה עַד הַסּוֹף","נִכְנָסִים לַבַּיִת, וְאִם הַגֶּשֶׁם פָּסַק מְסַיְּמִים שָׁם","נִכְנָסִים לַבַּיִת, וְחַיָּבִים לַחְזֹר כְּשֶׁהַגֶּשֶׁם פּוֹסֵק","מְכַסִּים אֶת הַסְּכָךְ בִּשְׂמִיכָה וּמַמְשִׁיכִים"],1,"מֻתָּר לְהִכָּנֵס לֶאֱכֹל בַּבַּיִת, וְאַף אִם פָּסְקוּ הַגְּשָׁמִים מֻתָּר לְסַיֵּם שָׁם. גֶּשֶׁם בַּחַג הוּא סִימַן קְלָלָה, וְיוֹצְאִים בְּהַכְנָעָה כְּעֶבֶד שֶׁרַבּוֹ שָׁפַךְ אֶת הַכּוֹס עַל פָּנָיו.","פֶּרֶק פ״ה, הֲלָכָה ו׳","מִי חַיָּב בַּסֻּכָּה?"],["נַעַר יָשַׁן בַּסֻּכָּה וְהִתְחִיל לָרֶדֶת גֶּשֶׁם קַל. מָה הַדִּין?",["מֻתָּר לְהִכָּנֵס מִיָּד, וְאֵין חוֹבָה לַחְזֹר עַד שֶׁמִּתְעוֹרְרִים","רַק גֶּשֶׁם חָזָק מַתִּיר לְהִכָּנֵס הַבַּיְתָה","נִכְנָסִים, וּכְשֶׁהַגֶּשֶׁם פּוֹסֵק חוֹזְרִים מִיָּד לַסֻּכָּה","צָרִיךְ לְהִשָּׁאֵר בַּסֻּכָּה עַד שֶׁיַּעֲלֶה הַשַּׁחַר"],0,"גַּם כַּמּוּת קְטַנָּה שֶׁל גֶּשֶׁם מַקְשָׁה מְאֹד עַל הַשֵּׁנָה, לָכֵן מֻתָּר לְהִכָּנֵס מִיָּד, וְאַף אִם פָּסְקוּ הַגְּשָׁמִים אֵין חוֹבָה לַחְזֹר עַד שֶׁמִּתְעוֹרְרִים.","פֶּרֶק פ״ה, הֲלָכָה ח׳","מִי חַיָּב בַּסֻּכָּה?"],["מָתַי מִי שֶׁמְּטַפֵּל בְּחוֹלֶה פָּטוּר מִן הַסֻּכָּה?",["בְּכָל שִׁבְעַת יְמֵי הַחַג, בְּלִי הֶבְדֵּל","רַק בַּלַּיְלָה, כְּשֶׁהַחוֹלֶה יָשֵׁן בַּמִּטָּה","רַק בַּזְּמַן שֶׁהַחוֹלֶה צָרִיךְ אוֹתוֹ","אַף פַּעַם, כִּי רַק הַחוֹלֶה עַצְמוֹ פָּטוּר"],2,"חוֹלִים וּמְשַׁמְּשֵׁיהֶם פְּטוּרִים: הַחוֹלֶה – כִּי גַּם אֶת בֵּיתוֹ הָיָה עוֹזֵב לְמַעַן בְּרִיאוּתוֹ, וְהַמְּטַפֵּל – כִּי הָעוֹסֵק בְּמִצְוָה פָּטוּר מִן הַמִּצְוָה. הַמְּשַׁמֵּשׁ פָּטוּר רַק בִּזְמַן שֶׁהַחוֹלֶה צָרִיךְ אוֹתוֹ.","פֶּרֶק פ״ה, הֲלָכָה ט׳-י׳","מִי חַיָּב בַּסֻּכָּה?"],["רוֹפְאִים בְּבֵית חוֹלִים וְחַיָּלִים בְּתַפְקִיד – מָה דִּינָם בַּסֻּכָּה?",["חַיָּבִים לְגַמְרֵי, כִּי הַסֻּכָּה חֲשׁוּבָה יוֹתֵר","פְּטוּרִים לְגַמְרֵי בְּכָל יְמֵי הַחַג, גַּם בַּחֻפְשָׁה","פְּטוּרִים בִּזְמַן הַתַּפְקִיד, כִּי הֵם עוֹסְקִים בְּמִצְוָה","פְּטוּרִים רַק אִם הֵם גָּרִים רָחוֹק"],2,"רוֹפְאִים וְאַחִים פְּטוּרִים בְּמֶשֶׁךְ הַמִּשְׁמֶרֶת, אֲבָל אִם הַחוֹלִים לֹא צְרִיכִים אֶת כֻּלָּם בְּבַת אַחַת – אוֹכְלִים בַּסֻּכָּה בְּתוֹרוֹת. שׁוֹטְרִים וְחַיָּלִים בְּתַפְקִיד פְּטוּרִים, וּמִשֶּׁסִּיְּמוּ וְהֵם בַּבָּסִיס – חַיָּבִים.","פֶּרֶק פ״ה, הֲלָכָה י״א-י״ב","מִי חַיָּב בַּסֻּכָּה?"],["מִשְׁפָּחָה יוֹצֵאת לְטִיּוּל בְּחֹל הַמּוֹעֵד. מָה כְּדַאי לְתַכְנֵן?",["לֶאֱכֹל אֲרוּחוֹת גְּדוֹלוֹת בְּכָל מָקוֹם בַּדֶּרֶךְ","לְהִשָּׁאֵר כָּל הַלַּיְלָה בַּטֶּבַע בְּלִי סֻכָּה","לְבַטֵּל אֶת הַטִּיּוּל, כִּי אָסוּר לִנְסֹעַ בַּחַג","לֶאֱכֹל וְלִישֹׁן בַּסֻּכָּה, וּבַדֶּרֶךְ רַק פֵּרוֹת וּמְעַט מְזוֹנוֹת"],3,"הוֹלְכֵי דְּרָכִים פְּטוּרִים, וְאֵין חוֹבָה לִדְחוֹת נְסִיעָה, אַךְ רָאוּי לֹא לִקְבֹּעַ נְסִיעוֹת לַחַג. הַמְּטַיֵּל יְתַכְנֵן לֶאֱכֹל וְלִישֹׁן בַּסֻּכָּה. וְיֵשׁ אוֹמְרִים שֶׁמְּטַיְּלִים פְּטוּרִים, אֲבָל גַּם לְדַעְתָּם רָאוּי לְהִתְאַמֵּץ לִזְכּוֹת בַּמִּצְוָה.","פֶּרֶק פ״ה, הֲלָכָה י״ג-ט״ו","מִי חַיָּב בַּסֻּכָּה?"],["לְפִי הָרַמְבַּ״ן, מַדּוּעַ שְׂמֵחִים בְּלוּלָב וְאֶתְרוֹג שִׁבְעַת יָמִים?",["כִּי זֶה זֵכֶר לִקְרִיעַת יַם סוּף בַּחֹדֶשׁ הַזֶּה","כִּי בַּחַג הַזֶּה מְבַקְּשִׁים סְלִיחָה עַל כָּל הָעֲווֹנוֹת","כִּי ה׳ בֵּרֵךְ אוֹתָנוּ בְּכָל הַתְּבוּאָה וּמַעֲשֵׂה הַיָּדַיִם","כִּי בַּחַג הַזֶּה קִבַּלְנוּ אֶת הַתּוֹרָה בְּהַר סִינַי"],2,"הָרַמְבַּ״ן כּוֹתֵב שֶׁזֶּה זְמַן שִׂמְחָה שֶׁבֵּרֵךְ ה׳ אוֹתְךָ בְּכָל תְּבוּאָתְךָ וּבְכָל מַעֲשֵׂה יָדֶיךָ, וְהָיִיתָ אַךְ שָׂמֵחַ.","פֶּרֶק פ״ו, הֲלָכָה א׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["מָה בּוֹדְקִים מַשְׁגִּיחֵי הַכַּשְׁרוּת בְּדוּכָנֵי אַרְבַּעַת הַמִּינִים?",["רַק אֶת הַמְּחִיר שֶׁל אַרְבַּעַת הַמִּינִים בַּדּוּכָן","גַּם מַרְאֶה, גַּם גֶּזֶל וְעָרְלָה, וְגַם תְּרוּמוֹת וּמַעַשְׂרוֹת","רַק אֶת הַצֶּבַע הַחִיצוֹנִי שֶׁל הָאֶתְרוֹג וְלֹא יוֹתֵר","רַק שֶׁהַלּוּלָב אָרֹךְ מַסְפִּיק, וְלֹא שׁוּם דָּבָר אַחֵר"],1,"הַמַּשְׁגִּיחִים בּוֹדְקִים אֶת הַמַּרְאֶה, חֲשַׁשׁ גֶּזֶל וַחֲשַׁשׁ עָרְלָה, הַפְרָשַׁת תְּרוּמוֹת וּמַעַשְׂרוֹת, מְיַדְּעִים עַל קְדֻשַּׁת שְׁבִיעִית, וּבוֹדְקִים שֶׁהָאֶתְרוֹג לֹא מֻרְכָּב.","פֶּרֶק פ״ו, הֲלָכָה ב׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["לָמָּה רָאוּי שֶׁכָּל אָדָם יִלְמַד אֶת הִלְכוֹת אַרְבַּעַת הַמִּינִים?",["כְּדֵי שֶׁלֹּא נִצְטָרֵךְ לִקְנוֹת אוֹתָם בְּדוּכָן מֻשְׁגָּח לְעוֹלָם","כְּדֵי שֶׁנּוּכַל לִמְכֹּר אַרְבָּעָה מִינִים לַחֲבֵרִים בַּחַג","כְּדֵי לִפְסֹק לְבַד בְּלִי לִשְׁאֹל אַף פַּעַם תַּלְמִיד חָכָם","כְּדֵי לָדַעַת אִם נִפְסְלוּ, וְלִשְׁאֹל תַּלְמִיד חָכָם בְּעֵת הַצֹּרֶךְ"],3,"הַלִּמּוּד עוֹזֵר לְהַבְחִין אִם אַרְבַּעַת הַמִּינִים נִפְסְלוּ, וּבְמִקְרֵה הַצֹּרֶךְ לָדַעַת לִשְׁאֹל תַּלְמִיד חָכָם.","פֶּרֶק פ״ו, הֲלָכָה ג׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["מָה צָרִיךְ לְהַקְפִּיד בְּעִנְיַן הֶעָלֶה הַמֶּרְכָּזִי הָעֶלְיוֹן שֶׁל הַלּוּלָב?",["צָרִיךְ שֶׁלֹּא יִפָּתַח וְלֹא יִקָּטֵם, וְנוֹהֲגִים לִקְשֹׁר אֶת הָעָלִים","מֻתָּר לִפְתֹּחַ וְלַחְתֹּךְ אוֹתוֹ, וְזֶה אֲפִלּוּ מְהַדֵּר אֶת הַלּוּלָב","כְּדַאי לַחְתֹּךְ אֶת רֹאשׁוֹ כְּדֵי שֶׁהַלּוּלָב יִהְיֶה יָשָׁר יוֹתֵר","אֵין שׁוּם הֶבְדֵּל בֵּין הֶעָלֶה הַמֶּרְכָּזִי לַשְּׁאָר"],0,"מַקְפִּידִים שֶׁהֶעָלֶה הַמֶּרְכָּזִי לֹא יִפָּתַח כְּלָל וְשֶׁרֹאשׁוֹ לֹא יִקָּטֵם. בְּדִיעֲבַד, אִם נִפְתַּח קְצָת – כָּשֵׁר; אִם נִפְתַּח רֻבּוֹ – פָּסוּל לְפִי חֵלֶק מֵהַדֵּעוֹת.","פֶּרֶק פ״ו, הֲלָכוֹת ד׳-ה׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["מָה דִּינוֹ שֶׁל לוּלָב הֶעָקוּם לְכִוּוּן הַצַּד שֶׁבּוֹ הַשִּׁדְרָה?",["פָּסוּל, כִּי כָּל עֲקִימָה פּוֹסֶלֶת אֶת הַלּוּלָב לְגַמְרֵי","כָּשֵׁר רַק אִם קוֹשְׁרִים אוֹתוֹ לַהֲדַסִּים וְלָעֲרָבוֹת","כָּשֵׁר, כִּי זוֹ דֶּרֶךְ גִּדּוּלוֹ הַטִּבְעִית עַל הָעֵץ","פָּסוּל, כִּי הוּא נִרְאֶה כְּמוֹ מַגָּל חַד"],2,"לוּלָב הֶעָקוּם לְכִוּוּן הַשִּׁדְרָה כָּשֵׁר, כִּי כָּךְ הוּא גָּדֵל עַל הָעֵץ. רַק עָקוּם לַצְּדָדִים אוֹ לַצַּד הָרָחוֹק מֵהַשִּׁדְרָה עַד שֶׁנַּעֲשָׂה כְּמַגָּל – פָּסוּל.","פֶּרֶק פ״ו, הֲלָכָה ו׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["אֵיזֶה הֲדַס נִקְרָא ״עָבֹת״ וְכָשֵׁר לַמִּצְוָה?",["שְׁנֵי עָלִים בְּגֹבַהּ שָׁוֶה וְעָלֶה שְׁלִישִׁי בִּמְקוֹם אַחֵר","עָלֶה אֶחָד בְּכָל גֹּבַהּ, וְהֶעָנָף נִרְאֶה בֵּינֵיהֶם","הֲדַס עָבֶה מְאוֹד, גַּם אִם אֵין עָלָיו עָלִים","שְׁלוֹשָׁה עָלִים בְּגֹבַהּ שָׁוֶה, וְהָעָלִים מְכַסִּים אֶת הֶעָנָף"],3,"הֲדַס עָבֹת הוּא מְשֻׁלָּשׁ – שְׁלוֹשָׁה עָלִים יוֹצְאִים בְּגֹבַהּ שָׁוֶה, וְהָעָלִים מְכַסִּים אֶת הֶעָנָף. אִם רַק שְׁנַיִם בְּגֹבַהּ שָׁוֶה – פָּסוּל.","פֶּרֶק פ״ו, הֲלָכוֹת ח׳-ט׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["מָה הַדִּין בַּהֲדַס שֶׁנִּקְטַם (נֶחְתַּךְ) רֹאשׁוֹ?",["שָׁנוּי בְּמַחְלֹקֶת, וּבִשְׁעַת הַדְּחָק הַהֲדַס כָּשֵׁר","פָּסוּל לְגַמְרֵי וְאָסוּר לְהִשְׁתַּמֵּשׁ בּוֹ בְּשׁוּם מַצָּב","כָּשֵׁר לְכַתְּחִלָּה, וְזֶה אֲפִלּוּ הִדּוּר מִצְוָה","כָּשֵׁר רַק אִם מַדְבִּיקִים אֶת הָרֹאשׁ בַּחֲזָרָה"],0,"הֲדַס שֶׁנִּקְטַם רֹאשׁוֹ – הַדָּבָר שָׁנוּי בְּמַחְלֹקֶת, וּבִשְׁעַת הַדְּחָק הוּא כָּשֵׁר.","פֶּרֶק פ״ו, הֲלָכָה י׳","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["מָה אֹרֶךְ הַהֲדַס, וּמַהוּ הַהִדּוּר בּוֹ?",["אַרְבָּעָה טְפָחִים, וּמַסְפִּיק שֶׁטֶּפַח אֶחָד יִהְיֶה מְשֻׁלָּשׁ","טֶפַח אֶחָד, וְאֵין צֹרֶךְ שֶׁיִּהְיֶה מְשֻׁלָּשׁ בִּכְלָל","אֵין אֹרֶךְ קָבוּעַ, וְהָעִקָּר שֶׁיֵּשׁ בּוֹ רֵיחַ","שְׁלוֹשָׁה טְפָחִים, וּלְהִדּוּר שֶׁכָּל הַטְּפָחִים יִהְיוּ מְשֻׁלָּשִׁים"],3,"הַהֲדַס לְפָחוֹת שְׁלוֹשָׁה טְפָחִים (24 ס״מ, וְיֵשׁ אוֹמְרִים 30 ס״מ). לְהִדּוּר – כֻּלָּם מְשֻׁלָּשִׁים, וּבְדִיעֲבַד אִם רֻבָּם מְשֻׁלָּשִׁים – כָּשֵׁר.","פֶּרֶק פ״ו, הֲלָכָה י״ב","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["אֵיךְ שׁוֹמְרִים עַל הַהֲדַס כְּדֵי שֶׁיִּשָּׁאֵר כָּשֵׁר?",["לְיַבֵּשׁ אוֹתוֹ בַּשֶּׁמֶשׁ כְּדֵי שֶׁיַּחֲזִיק מַעֲמָד יוֹתֵר","לִשְׁמֹר אוֹתוֹ לַח, וּלְהִזָּהֵר שֶׁעָלָיו לֹא יִנְשְׁרוּ בָּאֲגִידָה","לְהוֹרִיד מִמֶּנּוּ עָלִים כְּדֵי שֶׁיִּהְיֶה קַל לֶאֱגֹד","אֵין צֹרֶךְ לִשְׁמֹר עָלָיו, גַּם הֲדַס יָבֵשׁ כָּשֵׁר"],1,"הֲדַס יָבֵשׁ פָּסוּל, וְלָכֵן שׁוֹמְרִים אוֹתוֹ בִּתְנָאִים מַתְאִימִים; וּכְשֶׁאוֹגְדִים אֶת אַרְבַּעַת הַמִּינִים נִזְהָרִים שֶׁלֹּא יִנְשְׁרוּ עָלָיו.","פֶּרֶק פ״ו, הֲלָכוֹת י״א, י״ג","אַרְבַּעַת הַמִּינִים – לוּלָב וַהֲדַס"],["מַדּוּעַ אָסוּר לִקְטֹף הֲדַסִּים וַעֲרָבוֹת בְּלִי רְשׁוּת?",["כִּי עֲרָבוֹת מֵהַגִּנָּה אֵינָן נֶחְשָׁבוֹת עַרְבֵי נַחַל","כִּי מֻתָּר לִקְטֹף רַק אַחֲרֵי חַג הַסֻּכּוֹת","כִּי הֲדַס וַעֲרָבָה גְּזוּלִים פְּסוּלִים לַמִּצְוָה","כִּי עָלִים שֶׁנִּקְטְפוּ בַּיָּד נוֹבְלִים מַהֵר מְאֹד"],2,"הֲדַס גָּזוּל וַעֲרָבָה גְּזוּלָה פְּסוּלִים, וְלָכֵן אֵין לִקְטֹף בְּלִי רְשׁוּת מְפֹרֶשֶׁת מֵהַמֻּסְמָכִים, וְקוֹנִים רַק מֵאָדָם נֶאֱמָן.","פֶּרֶק פ״ו, הֲלָכוֹת י״ד, י״ח","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["מַהֵם סִימָנֵי הָעֲרָבָה שֶׁנָּתְנוּ חֲכָמִים?",["עָלֶה עָגֹל, שָׂפָה מְשֻׁנֶּנֶת וְקָנֶה בְּצֶבַע יָרֹק","עָלֶה אָרֹךְ, שָׂפָה מְשֻׁנֶּנֶת וְקָנֶה בְּצֶבַע לָבָן","עָלֶה עָגֹל, שָׂפָה חֲלָקָה וְקָנֶה בְּצֶבַע חוּם","עָלֶה אָרֹךְ, שָׂפָה חֲלָקָה וְקָנֶה בְּצֶבַע אָדֹם"],3,"הֶעָלֶה מָשׁוּךְ כְּנַחַל (אָרֹךְ), פִּיהָ חָלָק, וְהַקָּנֶה אָדֹם. וּמִפְּנֵי שֶׁיֵּשׁ זַנִּים שׁוֹנִים וְעֵצִים דּוֹמִים כְּמוֹ הַצַּפְצָפָה – מַרְאִים לְמֻמְחֶה אוֹ קוֹנִים עִם הַשְׁגָּחָה.","פֶּרֶק פ״ו, הֲלָכָה ט״ו","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["מַה הַשִּׁעוּר הַמִּינִימָלִי שֶׁל אֹרֶךְ הָעֲרָבָה?",["לְפָחוֹת טֶפַח אֶחָד, כִּשְׁמוֹנָה סַנְטִימֶטֶר בִּלְבַד","לְפָחוֹת שְׁלוֹשָׁה טְפָחִים, כְּעֶשְׂרִים וְאַרְבָּעָה סַנְטִימֶטֶר","לְפָחוֹת עֲשָׂרָה טְפָחִים, כְּמוֹ גֹּבַהּ הַסֻּכָּה","אֵין שִׁעוּר, כָּל עָנָף קָטָן כָּשֵׁר"],1,"אֹרֶךְ הָעֲרָבָה לְפָחוֹת שְׁלוֹשָׁה טְפָחִים – עֶשְׂרִים וְאַרְבָּעָה ס״מ, וְיֵשׁ אוֹמְרִים שְׁלוֹשִׁים ס״מ.","פֶּרֶק פ״ו, הֲלָכָה ט״ז","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["מָה צָרִיךְ לִבְדֹּק בַּבֹּקֶר לִפְנֵי הַבְּרָכָה עַל הָעֲרָבָה?",["שֶׁהִיא גְּבוֹהָה יוֹתֵר מֵהַלּוּלָב וּמֵהַהֲדַסִּים","שֶׁכָּל הֶעָלִים שֶׁלָּהּ פּוֹנִים לְכִוּוּן מִזְרָח","שֶׁהִיא אֵינָהּ יְבֵשָׁה וְשֶׁלֹּא נָשְׁרוּ רֹב עָלֶיהָ","שֶׁהִיא קְשׁוּרָה בְּחוּט אָדֹם לְיַד הָאֶתְרוֹג"],2,"עֲרָבָה יְבֵשָׁה, שֶׁנָּשְׁרוּ רֹב עָלֶיהָ אוֹ שֶׁנִּקְטַם רֹאשָׁהּ – פְּסוּלָה, וְלָכֵן בּוֹדְקִים אוֹתָהּ הֵיטֵב בַּבֹּקֶר.","פֶּרֶק פ״ו, הֲלָכָה י״ז","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["לָמָּה יֵשׁ לִקְנוֹת אֶתְרוֹג עִם הֶכְשֵׁר?",["כִּי לֹא כָּל אָדָם בָּקִי, וּמֻרְכָּב פָּסוּל","כִּי אֶתְרוֹג בְּלִי הֶכְשֵׁר אָסוּר בַּאֲכִילָה","כִּי הַהֶכְשֵׁר מַבְטִיחַ שֶׁהָאֶתְרוֹג גָּדוֹל מְאֹד","כִּי רַק אֶתְרוֹג מֻרְכָּב עַל לִימוֹן כָּשֵׁר"],0,"דִּינֵי הָאֶתְרוֹג רַבִּים וְלֹא כָּל אָדָם בָּקִי בָּהֶם, וּלְדַעַת רֹב הַפּוֹסְקִים אֶתְרוֹג מֻרְכָּב (עַל לִימוֹן אוֹ חֻשְׁחָשׁ) פָּסוּל.","פֶּרֶק פ״ו, הֲלָכוֹת י״ט, כ׳","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["מָה הַדִּין בְּגֹדֶל הָאֶתְרוֹג?",["לְפָחוֹת כַּבֵּיצָה, אֲבָל גָּדוֹל מִדַּי פָּסוּל","בְּדִיּוּק כְּמוֹ אֱגוֹז, לֹא קָטָן וְלֹא גָּדוֹל","כָּל גֹּדֶל כָּשֵׁר, אֲפִלּוּ קָטָן כְּמוֹ זַיִת","לְפָחוֹת כַּבֵּיצָה, וַאֲפִלּוּ גָּדוֹל מְאֹד הוּא כָּשֵׁר"],3,"גֹּדֶל הָאֶתְרוֹג לְפָחוֹת כַּבֵּיצָה, וְהוּא כָּשֵׁר אֲפִלּוּ אִם הוּא גָּדוֹל כָּל כָּךְ שֶׁצָּרִיךְ לֶאֱחֹז אוֹתוֹ בִּשְׁתֵּי יָדַיִם.","פֶּרֶק פ״ו, הֲלָכוֹת כ״א, כ״ב","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["מִי שֶׁקָּנָה אֶתְרוֹג עִם פִּטָּם, וְהַפִּטָּם נָפַל – מָה עָלָיו לַעֲשׂוֹת?",["לְהַדְבִּיק אֶת הַפִּטָּם בַּחֲזָרָה בְּדֶבֶק חָזָק","לִשְׁאֹל תַּלְמִיד חָכָם מַה דִּינוֹ שֶׁל הָאֶתְרוֹג","לְהַמְשִׁיךְ לְבָרֵךְ כִּי כָּל אֶתְרוֹג כָּזֶה כָּשֵׁר","לִזְרֹק מִיָּד אֶת הָאֶתְרוֹג וְלִקְנוֹת חָדָשׁ"],1,"אִם הַפִּטָּם אוֹ חֵלֶק מִמֶּנּוּ נָפַל מֵאֶתְרוֹג שֶׁנִּקְנָה עִם פִּטָּם – שׁוֹאֲלִים תַּלְמִיד חָכָם מַה דִּינוֹ.","פֶּרֶק פ״ו, הֲלָכָה כ״ג","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["נִטַּל כָּל הָעֹקֶץ וְנֶחְסַר מְעַט מִבְּשַׂר הָאֶתְרוֹג. מַה דִּינוֹ?",["פָּסוּל בַּיּוֹם הָרִאשׁוֹן, וּבִשְׁאַר הַיָּמִים כָּשֵׁר","כָּשֵׁר בַּיּוֹם הָרִאשׁוֹן, וּבִשְׁאַר הַיָּמִים פָּסוּל","פָּסוּל בְּכָל שִׁבְעַת יְמֵי חַג הַסֻּכּוֹת","כָּשֵׁר תָּמִיד, כִּי הָעֹקֶץ אֵינוֹ חֵלֶק מֵהָאֶתְרוֹג"],0,"הָעֹקֶץ הוּא קְצֵה הֶעָנָף שֶׁמְּחַבֵּר אֶת הָאֶתְרוֹג לָעֵץ. אִם נִטַּל כֻּלּוֹ וְנֶחְסַר מִבְּשַׂר הָאֶתְרוֹג – פָּסוּל בַּיּוֹם הָרִאשׁוֹן בִּלְבַד.","פֶּרֶק פ״ו, הֲלָכָה כ״ד","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["אֶתְרוֹג נִפְגַּע מִקּוֹץ, וְיֵשׁ סָפֵק אִם נֶחְסַר מִמֶּנּוּ חֵלֶק. מַה דִּינוֹ?",["פָּסוּל בַּיּוֹם הָרִאשׁוֹן וְכָשֵׁר בִּשְׁאַר הַיָּמִים","פָּסוּל בְּכָל הַיָּמִים כִּי אוּלַי חָסֵר","כָּשֵׁר גַּם בַּיּוֹם הָרִאשׁוֹן שֶׁל חַג הַסֻּכּוֹת","כָּשֵׁר רַק אִם מְכַסִּים אֶת הַמָּקוֹם"],2,"אֶתְרוֹג שֶׁנִּקַּב וְנֶחְסַר פָּסוּל בַּיּוֹם הָרִאשׁוֹן, אֲבָל אִם נִפְגַּע מִקּוֹץ וְיֵשׁ סָפֵק אִם נֶחְסַר – כָּשֵׁר גַּם בַּיּוֹם הָרִאשׁוֹן.","פֶּרֶק פ״ו, הֲלָכָה כ״ה","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["כְּתָמִים צְהֻבִּים, אֲפֹרִים אוֹ חוּמִים עַל הָאֶתְרוֹג – מַה דִּינָם?",["פּוֹסְלִים, כִּי הֵם סִימָן שֶׁהָאֶתְרוֹג מֻרְכָּב","פּוֹסְלִים רַק בַּיּוֹם הָרִאשׁוֹן שֶׁל הַחַג","צָרִיךְ לְקַלֵּף אוֹתָם לִפְנֵי שֶׁמְּבָרְכִים","אֵינָם פּוֹסְלִים, וּבְדֶרֶךְ כְּלָל נִגְרָמִים מִמַּגַּע עָלִים"],3,"כְּתָמִים כָּאֵלֶּה (״בְּלָאטְלֶעךְ״) אֵינָם פּוֹסְלִים. אֲבָל חֲזָזִית אוֹ נְקֻדּוֹת שְׁחֹרוֹת אוֹ לְבָנוֹת שֶׁאִי אֶפְשָׁר לְקַלֵּף – שׁוֹאֲלִים תַּלְמִיד חָכָם.","פֶּרֶק פ״ו, הֲלָכָה כ״ו","אַרְבַּעַת הַמִּינִים – עֲרָבָה וְאֶתְרוֹג"],["בִּזְמַן שֶׁאֵין בֵּית מִקְדָּשׁ, מָתַי נוֹטְלִים לוּלָב בְּכָל הָאָרֶץ?",["רַק בַּיּוֹם הָרִאשׁוֹן שֶׁל הַחַג, גַּם בְּשַׁבָּת","רַק בְּבֵית הַכְּנֶסֶת, בַּיּוֹם הָרִאשׁוֹן בִּלְבַד","בְּכָל שִׁבְעַת יְמֵי הַחַג, חוּץ מִשַּׁבָּת","בְּכָל שְׁמוֹנַת הַיָּמִים, כּוֹלֵל שְׁמִינִי עֲצֶרֶת"],2,"רַבָּן יוֹחָנָן בֶּן זַכַּאי תִּקֵּן לִטֹּל בְּכָל שִׁבְעַת יְמֵי הַחַג זֵכֶר לַמִּקְדָּשׁ, אַךְ בְּשַׁבָּת אֵין נוֹטְלִים אֲפִלּוּ בַּיּוֹם הָרִאשׁוֹן.","פֶּרֶק פ״ז, הֲלָכָה א׳","נְטִילַת לוּלָב"],["לָמָּה הַמִּצְוָה נִקְרֵאת ״נְטִילַת לוּלָב״?",["כִּי הַלּוּלָב הוּא הַיָּקָר בְּיוֹתֵר מִכָּל הַמִּינִים","כִּי הַלּוּלָב הוּא הַגָּבוֹהַּ מִבֵּין אַרְבַּעַת הַמִּינִים","כִּי הַלּוּלָב נִזְכָּר רִאשׁוֹן בַּפָּסוּק שֶׁבַּתּוֹרָה","כִּי רַק אֶת הַלּוּלָב מְנַעְנְעִים בִּשְׁעַת הַהַלֵּל"],1,"הַלּוּלָב הוּא הַגָּבוֹהַּ מִבֵּין אַרְבַּעַת הַמִּינִים, וְלָכֵן גַּם מְבָרְכִים ״עַל נְטִילַת לוּלָב״.","פֶּרֶק פ״ז, הֲלָכָה ב׳","נְטִילַת לוּלָב"],["מָה הַמִּנְהָג הַנָּפוֹץ בְּמִסְפַּר הַהֲדַסִּים וְהָעֲרָבוֹת?",["שְׁנֵי עַנְפֵי הֲדַס וּשְׁלוֹשָׁה עַנְפֵי עֲרָבָה","עֲנַף הֲדַס אֶחָד וַעֲנַף עֲרָבָה אַחַת בִּלְבַד","אַרְבָּעָה עַנְפֵי הֲדַס וְאַרְבָּעָה עַנְפֵי עֲרָבָה","שְׁלוֹשָׁה עַנְפֵי הֲדַס וּשְׁנֵי עַנְפֵי עֲרָבָה"],3,"הַמִּנְהָג הַנָּפוֹץ: לוּלָב אֶחָד, שְׁלוֹשָׁה הֲדַסִּים, שְׁתֵּי עֲרָבוֹת וְאֶתְרוֹג אֶחָד. יֵשׁ מוֹסִיפִים הֲדַסִּים לְנוֹי.","פֶּרֶק פ״ז, הֲלָכָה ג׳","נְטִילַת לוּלָב"],["מָתַי רָאוּי לֶאֱגֹד אֶת הַלּוּלָב, הַהֲדַסִּים וְהָעֲרָבוֹת?",["לִפְנֵי כְּנִיסַת הַחַג, כְּדֵי לִקְשֹׁר אוֹתָם הֵיטֵב","בַּבֹּקֶר שֶׁל הַחַג, מִיָּד לִפְנֵי הַבְּרָכָה","רַק אַחֲרֵי שֶׁגּוֹמְרִים אֶת תְּפִלַּת הַהַלֵּל","בְּיוֹם כִּפּוּר, בְּאֶמְצַע תְּפִלַּת נְעִילָה"],0,"רָאוּי לֶאֱגֹד לִפְנֵי כְּנִיסַת הַחַג, כְּדֵי שֶׁנִּתָּן יִהְיֶה לִקְשֹׁר אוֹתָם זֶה לָזֶה הֵיטֵב.","פֶּרֶק פ״ז, הֲלָכָה ד׳","נְטִילַת לוּלָב"],["יֵשׁ נוֹהֲגִים לָשִׂים אֶת שְׁלֹשֶׁת הַהֲדַסִּים יַחַד. הֵיכָן?",["מִשְּׂמֹאל לַלּוּלָב, וְאֶת הָעֲרָבוֹת מִיָּמִין לוֹ","מִיָּמִין לַלּוּלָב, וְאֶת הָעֲרָבוֹת מִשְּׂמֹאל לוֹ","כֻּלָּם מֵאֲחוֹרֵי הַלּוּלָב, צְמוּדִים לָעֲרָבוֹת","מֵעַל רֹאשׁ הַלּוּלָב, כְּדֵי שֶׁיִּהְיוּ גְּבוֹהִים"],1,"יֵשׁ נוֹהֲגִים: הֲדַסִּים מִיָּמִין וַעֲרָבוֹת מִשְּׂמֹאל. וְיֵשׁ נוֹהֲגִים: הֲדַס וַעֲרָבָה מִיָּמִין, הֲדַס בָּאֶמְצַע, וַהֲדַס וַעֲרָבָה מִשְּׂמֹאל.","פֶּרֶק פ״ז, הֲלָכָה ה׳","נְטִילַת לוּלָב"],["אֵיזֶה מִשְׁפָּט נָכוֹן עַל אֲגִידַת הַלּוּלָב?",["מֻתָּר לִקְשֹׁר רַק בַּעֲלֵי לוּלָב וְלֹא בְּחוּט אַחֵר","מִי שֶׁיֵּשׁ לוֹ אוֹגְדָן חַיָּב גַּם לִקְשֹׁר מַמָּשׁ","הַהֲדַסִּים צְרִיכִים לִהְיוֹת גְּבוֹהִים מֵהַלּוּלָב בְּטֶפַח","שִׁדְרַת הַלּוּלָב גְּבוֹהָה לְפָחוֹת טֶפַח מֵעַל הַהֲדַסִּים"],3,"הַשִּׁדְרָה צְרִיכָה לִהְיוֹת גְּבוֹהָה טֶפַח מֵעַל הַהֲדַסִּים וְהָעֲרָבוֹת. עִם אוֹגְדָן אֵין חוֹבָה לִקְשֹׁר מַמָּשׁ, וּמֻתָּר לִקְשֹׁר גַּם בְּחוּט אַחֵר.","פֶּרֶק פ״ז, הֲלָכוֹת ו׳-ח׳","נְטִילַת לוּלָב"],["מִי שֶׁיּוֹצֵא לַדֶּרֶךְ וְלֹא יוּכַל לִטֹּל לוּלָב אַחֲרֵי הַזְּרִיחָה – מָה יַעֲשֶׂה?",["יִטֹּל לוּלָב בַּלַּיְלָה שֶׁלִּפְנֵי הַיְצִיאָה","פָּטוּר לְגַמְרֵי מִנְּטִילַת לוּלָב בְּאוֹתוֹ יוֹם","יִטֹּל לוּלָב כְּבָר מֵעֲלוֹת הַשַּׁחַר","יִטֹּל לוּלָב בַּלַּיְלָה כְּשֶׁיַּחְזֹר הַבַּיְתָה"],2,"זְמַן הַמִּצְוָה בַּיּוֹם וְלֹא בַּלַּיְלָה, וְהַנּוֹטֵל בַּלַּיְלָה לֹא יָצָא. אֲבָל מִי שֶׁיּוֹצֵא לַדֶּרֶךְ יָכוֹל לִטֹּל מֵעֲלוֹת הַשַּׁחַר.","פֶּרֶק פ״ז, הֲלָכוֹת ט׳-י׳","נְטִילַת לוּלָב"],["הֵיכָן מְבָרְכִים עַל הַלּוּלָב?",["רַק בְּבֵית הַכְּנֶסֶת, אַחֲרֵי שֶׁגּוֹמְרִים אֶת הַהַלֵּל","יֵשׁ בַּסֻּכָּה וְיֵשׁ בְּבֵית הַכְּנֶסֶת, כְּמִנְהַג אֲבוֹתָיו","רַק בַּסֻּכָּה, וְאָסוּר לְהָבִיא לוּלָב לְבֵית הַכְּנֶסֶת","רַק בַּשּׁוּק, בִּשְׁעַת קְנִיַּת אַרְבַּעַת הַמִּינִים"],1,"יֵשׁ נוֹהֲגִים לְבָרֵךְ בַּסֻּכָּה וְאַחַר כָּךְ לָלֶכֶת עִם הַלּוּלָב לְבֵית הַכְּנֶסֶת, וְיֵשׁ נוֹהֲגִים לְבָרֵךְ בְּבֵית הַכְּנֶסֶת לִפְנֵי הַהַלֵּל.","פֶּרֶק פ״ז, הֲלָכָה י״א","נְטִילַת לוּלָב"],["לָמָּה לֹא מַחְזִיקִים אֶת אַרְבַּעַת הַמִּינִים כִּדְרָכָם לִפְנֵי הַבְּרָכָה?",["כִּי מְבָרְכִים לִפְנֵי שֶׁמְּקַיְּמִים אֶת הַמִּצְוָה","כִּי אָסוּר לְהַחֲזִיק אֶתְרוֹג בְּיַד שְׂמֹאל","כִּי הַלּוּלָב עָלוּל לִשָּׁבֵר בִּשְׁעַת הַבְּרָכָה","כִּי צָרִיךְ קֹדֶם לְנַעְנֵעַ וְאַחַר כָּךְ לְבָרֵךְ"],0,"מְבָרְכִים ״עוֹבֵר לַעֲשִׂיָּתָן״. מִי שֶׁמַּחְזִיק אֶת כָּל הַמִּינִים כְּבָר יָצָא, וְלָכֵן מַשְׁאִירִים אֶתְרוֹג עַל הַשֻּׁלְחָן אוֹ מַחְזִיקִים אוֹתוֹ הָפוּךְ.","פֶּרֶק פ״ז, הֲלָכָה י״ב","נְטִילַת לוּלָב"],["לָמָּה מַחְזִיקִים אֶת הַלּוּלָב בַּמָּקוֹם שֶׁבּוֹ הוּא אָגוּד?",["כְּדֵי שֶׁהַלּוּלָב לֹא יִתְלַכְלֵךְ מִן הַיָּד","כִּי כָּךְ קַל יוֹתֵר לְהַגְבִּיהַּ אוֹתוֹ","כְּדֵי שֶׁהֶעָלִים יִשָּׁאֲרוּ יְשָׁרִים וְיָפִים","כְּדֵי שֶׁיִּהְיוּ שְׁלֹשֶׁת הַמִּינִים בְּיַד הַנּוֹטֵל"],3,"בַּמָּקוֹם הָאָגוּד נִמְצָאִים הַלּוּלָב, הַהֲדַסִּים וְהָעֲרָבוֹת יַחַד, וְכָךְ שְׁלָשְׁתָּם בְּיַד הַנּוֹטֵל.","פֶּרֶק פ״ז, הֲלָכָה י״ג","נְטִילַת לוּלָב – חֵלֶק ב׳"],["בְּאֵיזוֹ יָד מַחְזִיק אִטֵּר אֶת הַלּוּלָב?",["אִטֵּר פָּטוּר לְגַמְרֵי מִמִּצְוַת נְטִילַת לוּלָב","יֵשׁ מַחֲלֹקֶת, וְכָל אִטֵּר נוֹהֵג כְּמִנְהַג מִשְׁפַּחְתּוֹ","אִטֵּר חַיָּב לְהַחְזִיק אֶת שְׁנֵיהֶם בְּיַד יָמִין","כָּל אִטֵּר בּוֹחֵר בְּכָל יוֹם יָד אַחֶרֶת"],1,"יֵשׁ אוֹמְרִים שֶׁאִטֵּר יַחְזִיק לוּלָב בִּשְׂמֹאל וְאֶתְרוֹג בְּיָמִין, וְיֵשׁ אוֹמְרִים לוּלָב בְּיָמִין וְאֶתְרוֹג בִּשְׂמֹאל. כָּל אִטֵּר יְבָרֵר אֶת מִנְהַג מִשְׁפַּחְתּוֹ.","פֶּרֶק פ״ז, הֲלָכָה י״ד","נְטִילַת לוּלָב – חֵלֶק ב׳"],["מָתַי הוּא עִקַּר מִצְוַת הַלּוּלָב בְּחַג הַסֻּכּוֹת?",["בִּשְׁעַת קְרִיאַת הַתּוֹרָה בְּבֵית הַכְּנֶסֶת","בַּלַּיְלָה, לִפְנֵי סְעוּדַת הַחַג בַּסֻּכָּה","בִּשְׁעַת אֲמִירַת הַהַלֵּל בִּתְפִלַּת שַׁחֲרִית","בְּסוֹף הַיּוֹם, אַחֲרֵי תְּפִלַּת מִנְחָה"],2,"בְּכָל יְמֵי הַחַג גּוֹמְרִים אֶת הַהַלֵּל בְּשַׁחֲרִית, וְעִקַּר מִצְוַת הַלּוּלָב הוּא בִּשְׁעַת אֲמִירַת הַהַלֵּל. אֶת הַנִּעְנוּעִים לָמְדוּ חֲכָמִים מֵהֲנָפוֹת הַקָּרְבָּנוֹת, וְהֵם מְעוֹרְרִים חַסְדֵי ה׳ לַעֲצֹר רוּחוֹת וּטְלָלִים רָעִים.","פֶּרֶק פ״ז, הֲלָכָה ט״ו","נְטִילַת לוּלָב – חֵלֶק ב׳"],["מְנַעְנְעִים בְּ״הוֹדוּ לַה׳ כִּי טוֹב״. מַדּוּעַ לֹא מְנַעְנְעִים בִּשְׁעַת אֲמִירַת שֵׁם ה׳?",["כִּי הַלּוּלָב עָלוּל לְהִשָּׁבֵר בְּאֶמְצַע הַפָּסוּק","כִּי מוּתָר לְנַעְנֵעַ רַק בְּסוֹף הַתְּפִלָּה כֻּלָּהּ","כִּי הַחַזָּן מְבַקֵּשׁ שֶׁיִּהְיֶה שֶׁקֶט בְּבֵית הַכְּנֶסֶת","כִּי צָרִיךְ לַעֲמֹד וּלְכַוֵּן בַּאֲמִירַת שֵׁם ה׳"],3,"מְנַעְנְעִים בְּ״הוֹדוּ לַה׳ כִּי טוֹב״ וּבְ״אָנָּא ה׳ הוֹשִׁיעָה נָּא״, אַךְ בְּשֵׁם ה׳ עוֹצְרִים, כִּי צָרִיךְ לַעֲמֹד וּלְכַוֵּן.","פֶּרֶק פ״ז, הֲלָכוֹת ט״ז, כ״א","נְטִילַת לוּלָב – חֵלֶק ב׳"],["כֵּיצַד מְנַעְנְעִים לְכָל כִּוּוּן?",["מְסוֹבְבִים אֶת הַלּוּלָב בְּמַעְגָּל גָּדוֹל מֵעַל הָרֹאשׁ","זוֹרְקִים אֶת הַלּוּלָב לְמַעְלָה וְתוֹפְסִים אוֹתוֹ שׁוּב","מַצְמִידִים אֶתְרוֹג, מוֹלִיכִים קָדִימָה וּמַחְזִירִים, שָׁלוֹשׁ פְּעָמִים","מְנַעְנְעִים פַּעַם אַחַת בִּלְבַד, כְּשֶׁהָאֶתְרוֹג רָחוֹק"],2,"מַצְמִידִים אֶת הָאֶתְרוֹג לַלּוּלָב, אוֹחֲזִים קָרוֹב לַגּוּף, מוֹלִיכִים קָדִימָה וּמַחְזִירִים אֶל הַגּוּף – שָׁלוֹשׁ פְּעָמִים לְכָל כִּוּוּן.","פֶּרֶק פ״ז, הֲלָכוֹת י״ז, י״ט","נְטִילַת לוּלָב – חֵלֶק ב׳"],["מָה סֵדֶר הַנִּעְנוּעִים לְפִי מִנְהַג הַסְּפָרַדִּים, עַל פִּי הָאֲרִ״י זַ״ל?",["מִזְרָח, דָּרוֹם, מַעֲרָב, צָפוֹן, מַעְלָה, מַטָּה","דָּרוֹם, צָפוֹן, מִזְרָח, מַעְלָה, מַטָּה, מַעֲרָב","צָפוֹן, דָּרוֹם, מַעֲרָב, מִזְרָח, מַטָּה, מַעְלָה","מַעְלָה, מַטָּה, מִזְרָח, מַעֲרָב, צָפוֹן, דָּרוֹם"],1,"מִנְהַג הַסְּפָרַדִּים וְחֵלֶק מֵהָאַשְׁכְּנַזִּים: דָּרוֹם, צָפוֹן, מִזְרָח, מַעְלָה, מַטָּה, מַעֲרָב. בְּחֵלֶק מִקְּהִלּוֹת הָאַשְׁכְּנַזִּים: מִזְרָח, דָּרוֹם, מַעֲרָב, צָפוֹן, מַעְלָה, מַטָּה.","פֶּרֶק פ״ז, הֲלָכָה י״ח","נְטִילַת לוּלָב – חֵלֶק ב׳"],["מָה פֵּרוּשׁ ״לְכַסְכֵּס״ בַּלּוּלָב?",["לִיצֹר רַחַשׁ קַל בֶּעָלִים שֶׁבְּרֹאשׁ הַלּוּלָב","לִקְשֹׁר אֶת הַלּוּלָב בְּחוּט שֶׁל עָלִים","לִבְדֹּק שֶׁאֵין סְדָקִים בַּעֲלֵי הַהֲדַסִּים","לְהַכּוֹת בַּלּוּלָב עַל הָרִצְפָּה חָמֵשׁ פְּעָמִים"],0,"בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים נוֹהֲגִים לְכַסְכֵּס – לִיצֹר בַּנִּעְנוּעִים רַחַשׁ קַל בֶּעָלִים שֶׁבְּרֹאשׁ הַלּוּלָב.","פֶּרֶק פ״ז, הֲלָכָה כ׳","נְטִילַת לוּלָב – חֵלֶק ב׳"],["קָטָן שֶׁכְּבָר הוֹלֵךְ לְהִתְפַּלֵּל בְּבֵית הַכְּנֶסֶת – מָה נָכוֹן שֶׁאָבִיו יַעֲשֶׂה?",["יִקְנֶה לוֹ אַרְבָּעָה מִינִים מִשֶּׁלּוֹ כְּדֵי שֶׁיְּנַעְנֵעַ","יִתֵּן לוֹ לְהַחְזִיק רַק אֶתְרוֹג בְּלִי לוּלָב","יַשְׁאִיר אוֹתוֹ בַּבַּיִת עַד שֶׁיִּגְדַּל","יְבַקֵּשׁ מִמֶּנּוּ לְהַבִּיט בַּמִּתְפַּלְּלִים מִן הַצַּד"],0,"קָטָן שֶׁיּוֹדֵעַ לְנַעְנֵעַ – אָבִיו חַיָּב לְחַנְּכוֹ. אִם הוּא הוֹלֵךְ לְבֵית הַכְּנֶסֶת, נָכוֹן לִקְנוֹת לוֹ אַרְבָּעָה מִינִים מִשֶּׁלּוֹ כְּדֵי שֶׁיְּנַעְנֵעַ בַּמְּקוֹמוֹת שֶׁתִּקְּנוּ חֲכָמִים.","פֶּרֶק פ״ז, הֲלָכָה כ״ג","נְטִילַת לוּלָב – חֵלֶק ב׳"],["לָמָּה אָמְרָה הַתּוֹרָה לְנַסֵּךְ מַיִם בְּחַג הַסֻּכּוֹת?",["כְּדֵי לְנַקּוֹת אֶת הַמִּזְבֵּחַ מִן הַדָּם","כִּי בַּחַג הַזֶּה הַיַּיִן נִגְמַר","כְּדֵי שֶׁיִּתְבָּרְכוּ לָנוּ גִּשְׁמֵי הַשָּׁנָה","כְּדֵי לְקָרֵר אֶת הַכֹּהֲנִים בַּחֹם"],2,"רַבִּי עֲקִיבָא אָמַר: ״נַסְּכוּ לְפָנַי מַיִם בֶּחָג – כְּדֵי שֶׁיִּתְבָּרְכוּ לָכֶם גִּשְׁמֵי שָׁנָה״.","פֶּרֶק פ״ח, הֲלָכָה א׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["מָתַי עָרְכוּ אֶת שִׂמְחַת בֵּית הַשּׁוֹאֵבָה בְּבֵית הַמִּקְדָּשׁ?",["בְּכָל לַיְלָה מִלֵּילוֹת חֹל הַמּוֹעֵד","רַק בְּלֵיל הַחַג הָרִאשׁוֹן שֶׁל סֻכּוֹת","בְּכָל בֹּקֶר שֶׁל חֹדֶשׁ אֱלוּל","רַק בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים בְּבֵית הַמִּקְדָּשׁ"],0,"בְּכָל לַיְלָה מִלֵּילוֹת חֹל הַמּוֹעֵד הָיְתָה שִׂמְחָה גְּדוֹלָה עִם כְּלֵי נְגִינָה, עַד הַבֹּקֶר.","פֶּרֶק פ״ח, הֲלָכָה ב׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["מָה מְיֻחָד בְּיוֹם הוֹשַׁעְנָא רַבָּה לְדַעַת חַכְמֵי הַקַּבָּלָה?",["זֶהוּ הַיּוֹם שֶׁבּוֹ מַתְחִילִים לִבְנוֹת סֻכָּה","זֶהוּ יוֹם סִיּוּם הַדִּין שֶׁהֵחֵל בְּרֹאשׁ הַשָּׁנָה","זֶהוּ יוֹם הַצּוֹם הַגָּדוֹל שֶׁל חֹדֶשׁ תִּשְׁרֵי","זֶהוּ הַיּוֹם שֶׁבּוֹ קוֹרְאִים אֶת מְגִלַּת אֶסְתֵּר"],1,"לְדַעַת חַכְמֵי הָאֱמֶת, הוֹשַׁעְנָא רַבָּה הוּא יוֹם סִיּוּם הַדִּין שֶׁהֵחֵל בְּרֹאשׁ הַשָּׁנָה.","פֶּרֶק פ״ח, הֲלָכָה ג׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["כַּמָּה פְּעָמִים הִקִּיפוּ אֶת הַמִּזְבֵּחַ בַּיּוֹם הַשְּׁבִיעִי שֶׁל סֻכּוֹת?",["פַּעַם אַחַת בִּלְבַד, כְּמוֹ בִּשְׁאָר הַיָּמִים","שָׁלֹשׁ פְּעָמִים, כְּנֶגֶד שְׁלֹשֶׁת הָאָבוֹת","עֶשֶׂר פְּעָמִים, כְּנֶגֶד עֲשֶׂרֶת הַדִּבְּרוֹת","שֶׁבַע פְּעָמִים, וּבִשְׁאָר הַיָּמִים פַּעַם אַחַת"],3,"בְּכָל יוֹם מַקִּיפִים פַּעַם אַחַת, וּבַיּוֹם הַשְּׁבִיעִי שֶׁבַע פְּעָמִים, וְאוֹמְרִים ״אָנָּא ה׳ הוֹשִׁיעָה נָּא״.","פֶּרֶק פ״ח, הֲלָכָה ד׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["לָמָּה מַקִּיפִים הַיּוֹם אֶת הַבִּימָה בְּבֵית הַכְּנֶסֶת?",["כְּדֵי לִבְדֹּק שֶׁהַבִּימָה יַצִּיבָה וַחֲזָקָה","כְּדֵי שֶׁכָּל הַקָּהָל יִרְאֶה אֶת הַלּוּלָב","זֵכֶר לַמִּקְדָּשׁ, שֶׁשָּׁם הִקִּיפוּ אֶת הַמִּזְבֵּחַ","כִּי כָּךְ מִתְאַמְּנִים לְשִׂמְחַת תּוֹרָה בְּרִקּוּדִים"],2,"כְּשֶׁאֵין בֵּית הַמִּקְדָּשׁ מַקִּיפִים אֶת הַבִּימָה וְאוֹמְרִים הוֹשַׁעְנוֹת, זֵכֶר לַמִּקְדָּשׁ.","פֶּרֶק פ״ח, הֲלָכָה ה׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["הַאִם מְבָרְכִים כְּשֶׁחוֹבְטִים עֲרָבָה בְּהוֹשַׁעְנָא רַבָּה?",["מְבָרְכִים ״עַל נְטִילַת עֲרָבָה״ לִפְנֵי הַחֲבָטָה","לֹא מְבָרְכִים, כִּי זֶהוּ מִנְהַג נְבִיאִים","מְבָרְכִים שֶׁהֶחֱיָנוּ בְּכָל פַּעַם שֶׁחוֹבְטִים","מְבָרְכִים רַק אִם חוֹבְטִים בְּתוֹךְ הַסֻּכָּה"],1,"הַחֲבָטָה הִיא מִנְהַג שֶׁהִנְהִיגוּ הַנְּבִיאִים, וְלָכֵן אֵין מְבָרְכִים עָלֶיהָ.","פֶּרֶק פ״ח, הֲלָכָה ו׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["כֵּיצַד עוֹשִׂים אֶת חִבּוּט הָעֲרָבוֹת?",["חוֹבְטִים עָנָף אֶחָד שֶׁבַע פְּעָמִים עַל הַבִּימָה","חוֹבְטִים שְׁלֹשָׁה עֲנָפִים פַּעַם אַחַת עַל הַקִּיר","חוֹבְטִים חֲמִשָּׁה עֲנָפִים חָמֵשׁ פְּעָמִים עַל הַקַּרְקַע","חוֹבְטִים אֶת כָּל הַלּוּלָב עַד שֶׁנִּשְׁבָּר לְגַמְרֵי"],2,"לוֹקְחִים חֲמִשָּׁה עַנְפֵי עֲרָבָה וְחוֹבְטִים אוֹתָם חָמֵשׁ פְּעָמִים עַל הַקַּרְקַע.","פֶּרֶק פ״ח, הֲלָכָה ז׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["לָמָּה יֵשׁ שׁוֹרְפִים אֶת הַלּוּלָב וְהָעֲרָבָה בַּתַּנּוּר שֶׁל הַמַּצּוֹת?",["כִּי הָעֲרָבָה מְבִיאָה לַמַּצּוֹת טַעַם טוֹב","כִּי אָסוּר לְהַחְזִיק עֲרָבָה בַּבַּיִת בַּפֶּסַח","כִּי כָּךְ הַתַּנּוּר נִהְיֶה חַם יוֹתֵר מַהֵר","כִּי רָאוּי לַעֲשׂוֹת בּוֹ מִצְוָה נוֹסֶפֶת"],3,"דָּבָר שֶׁנֶּעֶשְׂתָה בּוֹ מִצְוָה אַחַת רָאוּי שֶׁתֵּעָשֶׂה בּוֹ גַּם מִצְוָה אַחֶרֶת.","פֶּרֶק פ״ח, הֲלָכָה ח׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["מָה אוֹמְרִים כְּשֶׁיּוֹצְאִים מִן הַסֻּכָּה בַּפַּעַם הָאַחֲרוֹנָה?",["יְהִי רָצוֹן שֶׁנִּזְכֶּה לֵישֵׁב בְּסֻכָּה שֶׁל לִוְיָתָן","לְהִתְרָאוֹת סֻכָּה, נִפָּגֵשׁ שׁוּב בַּשָּׁנָה הַבָּאָה","בָּרוּךְ אַתָּה ה׳ שֶׁהֶחֱיָנוּ וְקִיְּמָנוּ","יְהִי רָצוֹן שֶׁנִּבְנֶה סֻכָּה גְּדוֹלָה יוֹתֵר"],0,"בְּיוֹם הוֹשַׁעְנָא רַבָּה, בַּיְּצִיאָה הָאַחֲרוֹנָה, אוֹמְרִים: ״יְהִי רָצוֹן שֶׁנִּזְכֶּה לֵישֵׁב בְּסֻכָּה שֶׁל לִוְיָתָן״.","פֶּרֶק פ״ח, הֲלָכָה ט׳","נִסּוּךְ הַמַּיִם וַהוֹשַׁעְנוֹת"],["מַדּוּעַ אֵין יוֹשְׁבִים בַּסֻּכָּה בִּשְׁמִינִי עֲצֶרֶת?",["כִּי בְּדֶרֶךְ כְּלָל יוֹרֵד בּוֹ גֶּשֶׁם","כִּי כְּבָר פֵּרְקוּ אֶת כָּל הַסֻּכּוֹת","כִּי הוּא חַג בִּפְנֵי עַצְמוֹ, נִפְרָד","כִּי חַג הַסֻּכּוֹת נִמְשָׁךְ שְׁמוֹנָה יָמִים"],2,"אַף שֶׁשְּׁמִינִי עֲצֶרֶת מַשְׁלִים לִימֵי הַסֻּכּוֹת, הוּא רֶגֶל בִּפְנֵי עַצְמוֹ, וְאֵין יוֹשְׁבִים בּוֹ בַּסֻּכָּה.","פֶּרֶק פ״ט, הֲלָכָה א׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["לָמָּה נִקְרָא שְׁמִינִי עֲצֶרֶת גַּם ״שִׂמְחַת תּוֹרָה״?",["כִּי בּוֹ נִתְּנָה הַתּוֹרָה לְעַם יִשְׂרָאֵל בְּהַר סִינַי","כִּי בּוֹ כּוֹתְבִים סֵפֶר תּוֹרָה חָדָשׁ לְכָל קְהִלָּה","כִּי בּוֹ לוֹמְדִים תּוֹרָה כָּל הַלַּיְלָה עַד הַבֹּקֶר","כִּי מְסַיְּמִים בּוֹ אֶת קְרִיאַת הַתּוֹרָה וּמַתְחִילִים מֵחָדָשׁ"],3,"חֲכָמִים תִּקְּנוּ לְסַיֵּם בּוֹ אֶת קְרִיאַת הַתּוֹרָה וּלְהַתְחִיל מֵחָדָשׁ, וְחוֹגְגִים בְּשִׂמְחָה וּבְרִקּוּדִים.","פֶּרֶק פ״ט, הֲלָכָה ב׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָה אוֹמְרִים בִּקְהִלּוֹת הָאַשְׁכְּנַזִּים בַּקִּדּוּשׁ שֶׁל שְׁמִינִי עֲצֶרֶת?",["אֶת יוֹם שְׁמִינִי חַג הָעֲצֶרֶת הַזֶּה","אֶת יוֹם שְׁמִינִי עֲצֶרֶת הַחַג הַזֶּה","אֶת יוֹם חַג הַסֻּכּוֹת הַזֶּה","אֶת יוֹם שִׂמְחַת תּוֹרָה הַזֶּה"],1,"הָאַשְׁכְּנַזִּים אוֹמְרִים ״אֶת יוֹם שְׁמִינִי עֲצֶרֶת הַחַג הַזֶּה״, וְהַסְּפָרַדִּים אוֹמְרִים ״אֶת יוֹם שְׁמִינִי חַג הָעֲצֶרֶת הַזֶּה״.","פֶּרֶק פ״ט, הֲלָכָה ג׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מַדּוּעַ מוֹסִיפִים ״שֶׁהֶחֱיָנוּ״ בַּקִּדּוּשׁ שֶׁל שְׁמִינִי עֲצֶרֶת?",["מִפְּנֵי שֶׁהוּא רֶגֶל בִּפְנֵי עַצְמוֹ","מִפְּנֵי שֶׁמַּתְחִילִים בּוֹ לְהִתְפַּלֵּל עַל גֶּשֶׁם","מִפְּנֵי שֶׁמְּסַיְּמִים בּוֹ אֶת קְרִיאַת הַתּוֹרָה","מִפְּנֵי שֶׁיּוֹצְאִים בּוֹ מִן הַסֻּכָּה"],0,"מוֹסִיפִים ״שֶׁהֶחֱיָנוּ״ מִפְּנֵי שֶׁשְּׁמִינִי עֲצֶרֶת הוּא רֶגֶל בִּפְנֵי עַצְמוֹ.","פֶּרֶק פ״ט, הֲלָכָה ד׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָתַי עוֹרְכִים אֶת הַהַקָּפוֹת לְפִי חֵלֶק מֵהַקְּהִלּוֹת?",["רַק בְּלֵיל הַחַג, אַחֲרֵי סְעוּדַת הַחַג","רַק אַחֲרֵי תְּפִלַּת מִנְחָה שֶׁל הַחַג","אַחֲרֵי עַרְבִית וְאַחֲרֵי שַׁחֲרִית, לִפְנֵי קְרִיאַת הַתּוֹרָה","לִפְנֵי תְּפִלַּת עַרְבִית, כְּשֶׁהַשֶּׁמֶשׁ שׁוֹקַעַת"],2,"בְּחֵלֶק מֵהַקְּהִלּוֹת עוֹרְכִים הַקָּפוֹת אַחֲרֵי עַרְבִית וְאַחֲרֵי שַׁחֲרִית (לִפְנֵי קְרִיאַת הַתּוֹרָה), וּבְחֵלֶק אַחֲרֵי עַרְבִית, מוּסָף וּמִנְחָה.","פֶּרֶק פ״ט, הֲלָכָה ה׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָה עוֹשִׂים בְּשִׂמְחַת תּוֹרָה עִם יְלָדִים שֶׁאֵינָם יוֹדְעִים לְבָרֵךְ?",["מְחַכִּים שֶׁיִּגְדְּלוּ וְלֹא מַעֲלִים אוֹתָם בִּכְלָל","מַכְנִיסִים אוֹתָם מִתַּחַת לַטַּלִּית וּמְבָרְכִים אוֹתָם בִּפְסוּקִים","נוֹתְנִים לָהֶם לְהַחֲזִיק אֶת סֵפֶר הַתּוֹרָה בִּלְבַד","מְלַמְּדִים אוֹתָם לִקְרֹא בַּתּוֹרָה בְּעַצְמָם בְּקוֹל"],1,"מַכְנִיסִים אוֹתָם מִתַּחַת לַטַּלִּית, אַחַד הָעוֹלִים קוֹרֵא עֲבוּרָם, וְאַחַר כָּךְ מְבָרְכִים אוֹתָם בִּפְסוּקִים.","פֶּרֶק פ״ט, הֲלָכָה ו׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָה קוֹרֶה מִיָּד אַחֲרֵי עֲלִיַּת ״חֲתַן תּוֹרָה״?",["קוֹרְאִים לַחֲתַן בְּרֵאשִׁית וּמַתְחִילִים אֶת הַתּוֹרָה מֵחָדָשׁ","מַחְזִירִים אֶת כָּל סִפְרֵי הַתּוֹרָה לָאָרוֹן","יוֹצְאִים לַהַקָּפוֹת שְׁנִיּוֹת בָּרְחוֹב עִם כְּלֵי נְגִינָה","מַתְחִילִים מִיָּד תְּפִלַּת מִנְחָה שֶׁל הַחַג"],0,"מִיָּד אַחֲרֵי חֲתַן תּוֹרָה קוֹרְאִים לַ״חֲתַן בְּרֵאשִׁית״ וּמַתְחִילִים אֶת קְרִיאַת הַתּוֹרָה מֵחָדָשׁ.","פֶּרֶק פ״ט, הֲלָכָה ז׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָתַי מַתְחִילִים לוֹמַר ״מַשִּׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם״?",["בִּתְפִלַּת עַרְבִית שֶׁל לֵיל שְׁמִינִי עֲצֶרֶת","בִּתְפִלַּת שַׁחֲרִית שֶׁל יוֹם רֹאשׁ הַשָּׁנָה","בְּמוֹצָאֵי שִׂמְחַת תּוֹרָה, אַחֲרֵי הַהַקָּפוֹת","בִּתְפִלַּת מוּסָף שֶׁל יוֹם שְׁמִינִי עֲצֶרֶת"],3,"בְּמוּסָף שֶׁל שְׁמִינִי עֲצֶרֶת מַתְחִילִים לוֹמַר ״מַשִּׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם״, וּבְרֹב הַקְּהִלּוֹת אוֹמְרִים לְפָנָיו ״תְּפִלַּת גֶּשֶׁם״.","פֶּרֶק פ״ט, הֲלָכָה ח׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָה נָכוֹן לְגַבֵּי ״הַקָּפוֹת שְׁנִיּוֹת״?",["עוֹרְכִים אוֹתָן בְּעֶרֶב הַחַג לִפְנֵי הַדְלָקַת נֵרוֹת","עוֹרְכִים אוֹתָן בְּשֶׁקֶט גָּמוּר, בְּלִי שִׁירָה בִּכְלָל","עוֹרְכִים אוֹתָן בְּמוֹצָאֵי הַחַג בְּשִׁירָה וּבִכְלֵי נְגִינָה","עוֹרְכִים אוֹתָן רַק בְּחֹל הַמּוֹעֵד שֶׁל סֻכּוֹת"],2,"בְּמוֹצָאֵי הַחַג עוֹרְכִים הַקָּפוֹת שְׁנִיּוֹת, וּמַרְבִּים בָּהֶן בְּשִׁירָה וּבְזִמְרָה בִּכְלֵי נְגִינָה, בְּרֹב פְּאֵר וְהָדָר.","פֶּרֶק פ״ט, הֲלָכָה ט׳","שְׁמִינִי עֲצֶרֶת וְשִׂמְחַת תּוֹרָה"],["מָה עָשׂוּ מַלְכֵי יָוָן לְיִשְׂרָאֵל בִּימֵי בַּיִת שֵׁנִי?",["גָּזְרוּ שֶׁכָּל יִשְׂרָאֵל יַעַבְדוּ רַק בַּשָּׂדוֹת","בָּנוּ לְיִשְׂרָאֵל בֵּית מִקְדָּשׁ חָדָשׁ וְגָדוֹל","לֹא נָתְנוּ לָהֶם לַעֲסֹק בַּתּוֹרָה וּבַמִּצְווֹת","הֶעֱמִידוּ מֶלֶךְ מִן הַכֹּהֲנִים בְּתוֹךְ יְרוּשָׁלַיִם"],2,"מַלְכֵי יָוָן בִּטְּלוּ אֶת דָּתָם שֶׁל יִשְׂרָאֵל, וְלֹא נָתְנוּ לָהֶם לַעֲסֹק בַּתּוֹרָה וּבַמִּצְווֹת. אֶת הַמֶּלֶךְ מִן הַכֹּהֲנִים הֶעֱמִידוּ בְּנֵי חַשְׁמוֹנַאי.","פֶּרֶק צ׳, הֲלָכָה א׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["לְכַמָּה יָמִים הִסְפִּיק הַשֶּׁמֶן שֶׁבַּפַּךְ, וְכַמָּה יָמִים דָּלַק?",["הִסְפִּיק לְיוֹם אֶחָד, וְדָלַק שְׁמוֹנָה יָמִים","הִסְפִּיק לִשְׁמוֹנָה יָמִים, וְדָלַק יוֹם אֶחָד","הִסְפִּיק לְשִׁבְעָה יָמִים, וְדָלַק שְׁמוֹנָה יָמִים","הִסְפִּיק לִשְׁנֵי יָמִים, וְדָלַק עֲשָׂרָה יָמִים"],0,"הַשֶּׁמֶן הִסְפִּיק לְיוֹם אֶחָד בִּלְבַד, וְנַעֲשָׂה נֵס וְדָלַק שְׁמוֹנָה יָמִים, עַד שֶׁהוֹצִיאוּ שֶׁמֶן טָהוֹר חָדָשׁ.","פֶּרֶק צ׳, הֲלָכָה ב׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["מַדּוּעַ צָרִיךְ לְהַקְפִּיד כָּל כָּךְ בְּמִצְוַת נֵר חֲנֻכָּה?",["מִפְּנֵי שֶׁהִיא מִצְוָה שֶׁל כָּל הַשָּׁנָה","מִפְּנֵי שֶׁהַנֵּרוֹת יָפִים וּמְקַשְּׁטִים אֶת הַבַּיִת","מִפְּנֵי שֶׁהִיא מְאִירָה לָנוּ אֶת הַחֹשֶׁךְ","כִּי מְפַרְסְמִים בָּהּ אֶת הַנֵּס וּמוֹדִים לָאֵ-ל"],3,"הַמִּצְוָה חֲבִיבָה מְאֹד, וּמַקְפִּידִים בָּהּ כְּדֵי לְפַרְסֵם אֶת הַנֵּס וּלְהוֹסִיף בְּשֶׁבַח וְהוֹדָיָה לָאֵ-ל.","פֶּרֶק צ׳, הֲלָכָה ג׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["מָתַי נוֹהֲגִים לְהַדְלִיק נֵר חֲנֻכָּה בִּקְהִלּוֹת הַסְּפָרַדִּים?",["מִיָּד בַּבֹּקֶר, כְּשֶׁהַשֶּׁמֶשׁ זוֹרַחַת בַּמִּזְרָח","בִּזְמַן צֵאת הַכּוֹכָבִים, בִּתְחִלַּת הַלַּיְלָה","בַּחֲצוֹת הַיּוֹם, כְּשֶׁהַשֶּׁמֶשׁ בְּאֶמְצַע הַשָּׁמַיִם","בַּחֲצוֹת הַלַּיְלָה, כְּשֶׁכֻּלָּם כְּבָר יְשֵׁנִים"],1,"הַסְּפָרַדִּים וְחֵלֶק מֵהָאַשְׁכְּנַזִּים מַדְלִיקִים בְּצֵאת הַכּוֹכָבִים, וְחֵלֶק מֵהָאַשְׁכְּנַזִּים סָמוּךְ לַשְּׁקִיעָה.","פֶּרֶק צ׳, הֲלָכָה ד׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["מִי שֶׁמַּדְלִיק נֵר חֲנֻכָּה בְּשָׁעָה מְאֻחֶרֶת, עַל מָה עָלָיו לְהַקְפִּיד?",["לְהַדְלִיק רַק נֵר אֶחָד בִּמְקוֹם כָּל הַנֵּרוֹת","לְהַדְלִיק בְּלִי שׁוּם בְּרָכָה, וְרַק בְּשֶׁקֶט גָּמוּר","לְהַדְלִיק דַּוְקָא כְּשֶׁכָּל בְּנֵי הַבַּיִת מְקֻבָּצִים יַחַד","לְהַדְלִיק בַּחֶדֶר הַפְּנִימִי כְּשֶׁאַף אֶחָד אֵינוֹ רוֹאֶה"],2,"בִּזְמַנֵּנוּ הַהַדְלָקָה הִיא גַּם לִבְנֵי הַבַּיִת, וְלָכֵן הַמַּדְלִיק מְאֻחָר יַדְלִיק כְּשֶׁכֻּלָּם מְקֻבָּצִים וִיקַיֵּם פִּרְסוּם הַנֵּס.","פֶּרֶק צ׳, הֲלָכוֹת ה׳-ו׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["מִי שֶׁחָזַר מְאֻחָר וְכָל בְּנֵי הַבַּיִת כְּבָר יְשֵׁנִים, מָה יַעֲשֶׂה?",["לֹא יַדְלִיק כְּלָל, וְיַשְׁלִים אֶת הַהַדְלָקָה מָחָר","יַדְלִיק בְּלִי בְּרָכָה, וְיֵשׁ אוֹמְרִים שֶׁיְּבָרֵךְ","יָעִיר אֶת כָּל הַשְּׁכֵנִים כְּדֵי שֶׁיִּרְאוּ","יַדְלִיק בִּבְרָכָה רַק בַּבֹּקֶר שֶׁל מָחֳרָת"],1,"אִם כֻּלָּם יְשֵׁנִים יַדְלִיק בְּלִי בְּרָכָה, וְיֵשׁ אוֹמְרִים שֶׁיְּבָרֵךְ. וּבִשְׁעַת הַצֹּרֶךְ אֶפְשָׁר לְהַקְדִּים מִפְּלַג הַמִּנְחָה.","פֶּרֶק צ׳, הֲלָכוֹת ז׳-ח׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["לָמָּה מַנִּיחִים אֶת נֵרוֹת הַחֲנֻכָּה מִצַּד שְׂמֹאל שֶׁל הַפֶּתַח?",["כְּדֵי שֶׁהָרוּחַ לֹא תְּכַבֶּה אוֹתָם בְּקַלּוּת","כִּי צַד שְׂמֹאל קָרוֹב יוֹתֵר לַמִּטְבָּח","כְּדֵי שֶׁהַיְּלָדִים הַקְּטַנִּים לֹא יַגִּיעוּ אֲלֵיהֶם","כְּדֵי שֶׁהַמַּדְלִיק יִהְיֶה מֻקָּף בְּמִצְווֹת סָבִיב"],3,"מְזוּזָה מִיָּמִין וְנֵר חֲנֻכָּה מִשְּׂמֹאל, וְכָךְ הַמַּדְלִיק מֻקָּף בְּמִצְווֹת. נֶגֶד הָרוּחַ שָׂמִים קֻפְסַת זְכוּכִית.","פֶּרֶק צ׳, הֲלָכוֹת ט׳-י׳","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["מִי שֶׁגָּר בְּקוֹמָה עֶלְיוֹנָה וְאֵין לוֹ פֶּתַח לָרְחוֹב, הֵיכָן יַנִּיחַ?",["בְּחַלּוֹן אוֹ בְּמִרְפֶּסֶת הַפּוֹנִים לָרְחוֹב","בַּחֲדַר הַמַּדְרֵגוֹת שֶׁל הַבִּנְיָן, לְמַטָּה","עַל הַגַּג הַגָּבוֹהַּ בְּיוֹתֵר שֶׁל הַבִּנְיָן","בְּתוֹךְ אָרוֹן סָגוּר בַּחֲדַר הַשֵּׁנָה"],0,"מִי שֶׁגָּר בַּעֲלִיָּה מַנִּיחַ בְּחַלּוֹן אוֹ בְּמִרְפֶּסֶת לָרְחוֹב. בְּפֶתַח רָגִיל מַנִּיחִים בֵּין שְׁלוֹשָׁה לַעֲשָׂרָה טְפָחִים, וּמִי שֶׁהִנִּיחַ גָּבוֹהַּ יוֹתֵר יָצָא.","פֶּרֶק צ׳, הֲלָכוֹת י״א-י״ב","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["בִּשְׁעַת סַכָּנָה מַנִּיחִים אֶת הַנֵּרוֹת עַל הַשֻּׁלְחָן. לְמִי מְפַרְסְמִים אֶת הַנֵּס?",["לְכָל הָעוֹבְרִים וְהַשָּׁבִים בָּרְחוֹב הַסָּמוּךְ","לְאַנְשֵׁי הַמַּלְכוּת שֶׁגָּזְרוּ אֶת הַגְּזֵרָה","לִבְנֵי הַבַּיִת שֶׁיּוֹשְׁבִים סְבִיב הַשֻּׁלְחָן","לַשְּׁכֵנִים שֶׁגָּרִים בַּבִּנְיָן הַגָּבוֹהַּ שֶׁמִּמּוּל"],2,"כְּשֶׁהַמַּלְכוּת גּוֹזֶרֶת גְּזֵרוֹת, מַנִּיחִים אֶת הַנֵּרוֹת עַל הַשֻּׁלְחָן וּמְפַרְסְמִים אֶת הַנֵּס לִבְנֵי הַבַּיִת.","פֶּרֶק צ׳, הֲלָכָה י״ג","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["לְפִי מִנְהַג הַסְּפָרַדִּים, אֵילוּ נֵרוֹת מַדְלִיקִים הַיְּלָדִים שֶׁבְּגִיל חִנּוּךְ?",["אֶת נֵר הַחִיּוּב הֶחָדָשׁ שֶׁל אוֹתוֹ יוֹם","אֶת שְׁאָר הַנֵּרוֹת, חוּץ מִנֵּר הַחִיּוּב","חֲנֻכִּיָּה שְׁלֵמָה מִשֶּׁלָּהֶם, כָּל אֶחָד לְעַצְמוֹ","שׁוּם נֵר, רַק מִסְתַּכְּלִים עַל הַהַדְלָקָה"],1,"בַּעַל הַבַּיִת מַדְלִיק אֶת נֵר הַחִיּוּב, וְהַיְּלָדִים בְּגִיל חִנּוּךְ אֶת שְׁאָר הַנֵּרוֹת. אֵצֶל הָאַשְׁכְּנַזִּים כָּל אֶחָד מַדְלִיק בְּעַצְמוֹ.","פֶּרֶק צ׳, הֲלָכוֹת י״ד-ט״ו","חֲנֻכָּה – הַנֵּס וְהַדְלָקַת הַנֵּרוֹת"],["מֵאֵיזֶה נֵר מַתְחִילִים לְהַדְלִיק בַּלֵּילוֹת שֶׁאַחֲרֵי הַלַּיְלָה הָרִאשׁוֹן?",["מֵהַנֵּר הַיְּמָנִי בְּיוֹתֵר, וּפוֹנִים שְׂמֹאלָה","מֵהַנֵּר הֶחָדָשׁ שֶׁנּוֹסַף מִשְּׂמֹאל, וּפוֹנִים יָמִינָה","מֵהַנֵּר הָאֶמְצָעִי, וּמִשָּׁם לִשְׁנֵי הַצְּדָדִים","מֵאֵיזֶה נֵר שֶׁרוֹצִים, אֵין לָזֶה סֵדֶר"],1,"בְּכָל לַיְלָה מוֹסִיפִים נֵר מִשְּׂמֹאל וּמַתְחִילִים מִמֶּנּוּ, כְּדֵי שֶׁאַחֲרֵי הַנֵּר הֶחָדָשׁ יִפְנֶה הַמַּדְלִיק יָמִינָה.","פֶּרֶק צ׳, הֲלָכָה י״ח","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["מַדּוּעַ נָשִׁים חַיָּבוֹת בְּנֵר חֲנֻכָּה, אַף שֶׁהַזְּמַן גְּרָמוֹ?",["מִפְּנֵי שֶׁהֵן נִמְצָאוֹת בַּבַּיִת בִּשְׁעַת הַהַדְלָקָה","מִפְּנֵי שֶׁכָּל מִצְווֹת הַחַגִּים שָׁווֹת לְכֻלָּם","מִפְּנֵי שֶׁהֵן מְכִינוֹת אֶת הַשֶּׁמֶן וְהַפְּתִילוֹת","מִפְּנֵי שֶׁאַף הֵן הָיוּ בְּאוֹתוֹ הַנֵּס"],3,"נָשִׁים חַיָּבוֹת מִפְּנֵי שֶׁאַף הֵן הָיוּ בְּאוֹתוֹ הַנֵּס, וְלָכֵן אִשָּׁה יְכוֹלָה לְהוֹצִיא יְדֵי חוֹבָה אֶת בַּעֲלָהּ וִילָדֶיהָ.","פֶּרֶק צ׳, הֲלָכָה י״ט","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["מָה נֶאֱמַר עַל עֲשִׂיַּת מְלָאכָה בִּזְמַן שֶׁהַנֵּרוֹת דּוֹלְקִים?",["נָשִׁים נוֹהֲגוֹת לְהִמָּנַע מִמְּלָאכָה חֲצִי שָׁעָה","מֻתָּר לְכֻלָּם לַעֲשׂוֹת כָּל מְלָאכָה בְּלִי הַגְבָּלָה","אָסוּר לַעֲשׂוֹת מְלָאכָה עַד סוֹף הַלַּיְלָה","רַק יְלָדִים נִמְנָעִים מִמְּלָאכָה כָּל עוֹד דּוֹלְקִים"],0,"הַנָּשִׁים נוֹהֲגוֹת שֶׁלֹּא לַעֲשׂוֹת מְלָאכָה בְּעוֹד הַנֵּרוֹת דּוֹלְקִים, וְיֵשׁ אוֹמְרִים שֶׁגַּם אֲנָשִׁים. זְמַן הָאִסּוּר – חֲצִי שָׁעָה.","פֶּרֶק צ׳, הֲלָכָה כ׳","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["לְפִי מִנְהַג הָאַשְׁכְּנַזִּים, מָה דִּין קָטָן שֶׁהִגִּיעַ לְגִיל חִנּוּךְ?",["מַדְלִיק בְּלִי בְּרָכָה, וְרַק מַבִּיט בַּנֵּרוֹת","מַדְלִיק וּמְבָרֵךְ, וְיָכוֹל לְהוֹצִיא אֶת כָּל הַגְּדוֹלִים","מַדְלִיק וּמְבָרֵךְ, אֲבָל אֵינוֹ מוֹצִיא אֶת הַגְּדוֹלִים","אֵינוֹ מַדְלִיק כְּלָל עַד שֶׁיַּגִּיעַ לְבַר מִצְוָה"],2,"לְפִי מִנְהַג הָאַשְׁכְּנַזִּים כָּל אֶחָד מִבְּנֵי הַבַּיִת מַדְלִיק לְעַצְמוֹ. קָטָן בְּגִיל חִנּוּךְ מַדְלִיק וּמְבָרֵךְ, אֲבָל אֵינוֹ מוֹצִיא אֶת הַגְּדוֹלִים.","פֶּרֶק צ׳, הֲלָכָה כ״א","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["בַּעַל הַבַּיִת חוֹלֶה וְשׁוֹכֵב בְּמִטָּתוֹ. כֵּיצַד תִּתְקַיֵּם הַמִּצְוָה?",["יַדְלִיק לְיַד מִטָּתוֹ וְאַחַר כָּךְ יַעֲבִירוּ לַחַלּוֹן","יְמַנֶּה שָׁלִיחַ שֶׁיַּדְלִיק עֲבוּרוֹ בִּמְקוֹם הַנָּחַת הַנֵּרוֹת","יִפָּטֵר מֵהַמִּצְוָה עַד שֶׁיַּבְרִיא מֵחָלְיוֹ לְגַמְרֵי","יַדְלִיקוּ בַּחֶדֶר שֶׁלּוֹ וְיַשְׁאִירוּ אֶת הַנֵּרוֹת שָׁם"],1,"מַדְלִיקִים בַּמָּקוֹם שֶׁבּוֹ הַנֵּרוֹת מֻנָּחִים וְאֵין לַהֲזִיזָם. לָכֵן חוֹלֶה יְמַנֶּה שָׁלִיחַ שֶׁיַּדְלִיק עֲבוּרוֹ בִּמְקוֹם הַנָּחָתָם.","פֶּרֶק צ׳, הֲלָכוֹת כ״ב–כ״ג","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["מָה נִכְתַּב עַל סוּגֵי הַשְּׁמָנִים וְהַנֵּרוֹת לַחֲנֻכָּה?",["רַק שֶׁמֶן זַיִת כָּשֵׁר, וְכָל שְׁאָר הַשְּׁמָנִים פְּסוּלִים","נֵרוֹת חַשְׁמַלִּיִּים מֻבְחָרִים, כִּי אוֹרָם חָזָק וּבָטוּחַ","נֵר שַׁעֲוָה פָּסוּל, כִּי אֵין בּוֹ שֶׁמֶן כְּלָל","שֶׁמֶן זַיִת מֻבְחָר, וּבְנֵרוֹת חַשְׁמַלִּיִּים אֵין יוֹצְאִים"],3,"מִצְוָה מִן הַמֻּבְחָר בְּשֶׁמֶן זַיִת, וְגַם שְׁאָר הַשְּׁמָנִים וְהַפְּתִילוֹת כְּשֵׁרִים, וְיֵשׁ נוֹהֲגִים בְּנֵר שַׁעֲוָה. בְּנֵרוֹת חַשְׁמַלִּיִּים אֵין יוֹצְאִים יְדֵי חוֹבָה.","פֶּרֶק צ׳, הֲלָכוֹת כ״ד–כ״ה","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["לָמָּה נוֹהֲגִים לְהַדְלִיק נֵר נוֹסָף הַנִּקְרָא שַׁמָּשׁ?",["כְּדֵי שֶׁשִּׁמּוּשׁ בְּטָעוּת בָּאוֹר יִהְיֶה לְאוֹר הַשַּׁמָּשׁ","כְּדֵי שֶׁיִּהְיֶה אוֹר חָזָק לִלְמֹד תּוֹרָה לְיַד הַנֵּרוֹת","כְּדֵי לְהַרְבּוֹת בְּנֵרוֹת הַמִּצְוָה עַל פִּי הַדִּין","כִּי אָסוּר לְהַדְלִיק נֵר חֲנֻכָּה בְּגַפְרוּר"],0,"אָסוּר לְהִשְׁתַּמֵּשׁ בְּאוֹר נֵרוֹת חֲנֻכָּה, אֲפִלּוּ לְלִמּוּד תּוֹרָה. הַשַּׁמָּשׁ מֻנָּח רָחוֹק אוֹ בְּגֹבַהּ אַחֵר, כְּדֵי שֶׁשִּׁמּוּשׁ בְּטָעוּת יִהְיֶה לְאוֹרוֹ.","פֶּרֶק צ׳, הֲלָכָה כ״ו","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["נֵרוֹת חֲנֻכָּה כָּבוּ מֵעַצְמָם בַּחֲצִי הַשָּׁעָה הָרִאשׁוֹנָה. מָה הַדִּין?",["חַיָּב לְהַדְלִיק שֵׁנִית וּלְבָרֵךְ שׁוּב אֶת כָּל הַבְּרָכוֹת","יַדְלִיק לְמָחֳרָת נֵר נוֹסָף בִּמְקוֹם הַנֵּר שֶׁכָּבָה","אֵינוֹ חַיָּב לְהַדְלִיק שֵׁנִית, אַךְ רָאוּי לְהַדְלִיק אִם אֶפְשָׁר","אָסוּר לוֹ לְהַדְלִיק אוֹתָם שׁוּב בְּשׁוּם אֹפֶן בַּלַּיְלָה"],2,"״הַדְלָקָה עוֹשָׂה מִצְוָה״ – הַהַדְלָקָה עַצְמָהּ הִיא הַמִּצְוָה, וְלָכֵן ״אֵינוֹ זָקוּק לָהּ״, אַךְ רָאוּי לְהַדְלִיק שֵׁנִית. אִם הִדְלִיק בְּמָקוֹם שֶׁיֵּשׁ בּוֹ רוּחַ – חוֹזֵר וּמַדְלִיק בְּלִי בְּרָכָה.","פֶּרֶק צ׳, הֲלָכָה כ״ז","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["מָה נָכוֹן לְגַבֵּי הַדְלָקַת נֵרוֹת בְּבֵית הַכְּנֶסֶת?",["מִי שֶׁהִדְלִיק בְּבֵית הַכְּנֶסֶת פָּטוּר מֵהַדְלָקָה בַּבַּיִת","מְבָרְכִים עֲלֵיהֶם, אַךְ צָרִיךְ לְהַדְלִיק שׁוּב בַּבַּיִת","מַנִּיחִים אוֹתָם תָּמִיד בַּקִּיר הַצְּפוֹנִי שֶׁל בֵּית הַכְּנֶסֶת","מַדְלִיקִים אוֹתָם רַק בַּבֹּקֶר, לִפְנֵי פְּסוּקֵי דְּזִמְרָה"],1,"מַדְלִיקִים בֵּין מִנְחָה לְעַרְבִית וּמְבָרְכִים כְּדֵי לְפַרְסֵם אֶת הַנֵּס, אַךְ אֵין יוֹצְאִים בָּזֶה – וְצָרִיךְ לְהַדְלִיק בַּבַּיִת. בִּירוּשָׁלַיִם מַדְלִיקִים גַּם בַּבֹּקֶר בְּלִי בְּרָכָה, וְהַנֵּרוֹת בַּקִּיר הַדְּרוֹמִי כְּמוֹ בַּמִּקְדָּשׁ.","פֶּרֶק צ׳, הֲלָכוֹת כ״ח–ל׳","נֵרוֹת חֲנֻכָּה – בְּרָכוֹת וְדִינִים"],["בְּעֶרֶב שַׁבָּת מַדְלִיקִים נֵר חֲנֻכָּה לִפְנֵי נֵרוֹת שַׁבָּת. וּבְמוֹצָאֵי שַׁבָּת, בַּבַּיִת – מָה עוֹשִׂים קֹדֶם?",["מַדְלִיקִים נֵר חֲנֻכָּה קֹדֶם, וְאַחַר כָּךְ מַבְדִּילִים","מַבְדִּילִים עַל נֵר הַחֲנֻכָּה עַצְמוֹ בְּלִי נֵר אַחֵר","מַבְדִּילִים קֹדֶם, וְאַחַר כָּךְ מַדְלִיקִים נֵר חֲנֻכָּה","מְחַכִּים לְמָחָר וּמַדְלִיקִים אֶת הַנֵּרוֹת בַּבֹּקֶר"],2,"בְּעֶרֶב שַׁבָּת שָׂמִים הַרְבֵּה שֶׁמֶן שֶׁיִּדְלֹק עַד חֲצִי שָׁעָה אַחֲרֵי צֵאת הַכּוֹכָבִים. בְּמוֹצָאֵי שַׁבָּת בַּבַּיִת מַבְדִּילִים תְּחִלָּה, וּבְבֵית הַכְּנֶסֶת מַדְלִיקִים תְּחִלָּה. אָסוּר לְהַבְדִּיל עַל נֵר חֲנֻכָּה, כִּי אָסוּר לֵהָנוֹת מֵאוֹרוֹ.","פֶּרֶק צ׳, הֲלָכָה ל״ב-ל״ג","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["אָדָם נָשׂוּי אֵינוֹ בְּבֵיתוֹ בַּחֲנֻכָּה, וְאִשְׁתּוֹ נִמְצֵאת בַּבַּיִת. מָה הַדִּין?",["הָאִשָּׁה מַדְלִיקָה בַּבַּיִת, וְהוּא יוֹצֵא יְדֵי חוֹבָתוֹ","הַבַּעַל חַיָּב לַחֲזֹר הַבַּיְתָה כְּדֵי לְהַדְלִיק","אַף אֶחָד לֹא מַדְלִיק בַּבַּיִת עַד שֶׁיַּחֲזֹר","הָאִשָּׁה מַדְלִיקָה, אֲבָל הוּא לֹא יוֹצֵא בָּזֶה"],0,"הָאִשָּׁה מַדְלִיקָה בַּבַּיִת וְהוּא יוֹצֵא בָּזֶה יְדֵי חוֹבָתוֹ. וְכֵן יְלָדִים שֶׁגָּרִים אֵצֶל הוֹרֵיהֶם יוֹצְאִים בְּהַדְלָקָה שֶׁבְּבֵיתָם.","פֶּרֶק צ׳, הֲלָכָה ל״ד","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["אוֹרֵחַ בְּבַיִת פְּרָטִי נוֹתֵן לְבַעַל הַבַּיִת מְעַט כֶּסֶף וְנַעֲשֶׂה שֻׁתָּף בַּנֵּרוֹת. וּמָה יַעֲשֶׂה מִי שֶׁמִּתְאָרֵחַ בְּמָלוֹן שֶׁאָסוּר בּוֹ לְהַדְלִיק בַּחֲדָרִים?",["פָּטוּר מֵהַדְלָקָה, כִּי הוּא אֵינוֹ בְּבֵיתוֹ","יַדְלִיק בַּחֲדַר הָאֹכֶל, אֲבָל בְּלִי בְּרָכָה","יַדְלִיק בְּחַדְרוֹ בְּסֵתֶר, אַף שֶׁאָסוּר שָׁם","יַדְלִיק בַּחֲדַר הָאֹכֶל אוֹ בַּמְּבוֹאָה בִּבְרָכָה"],3,"מִי שֶׁמִּתְאָרֵחַ בְּמָקוֹם שֶׁלֹּא מַדְלִיקִים בּוֹ, כְּמוֹ מָלוֹן – חַיָּב לְהַדְלִיק. אִם מֻתָּר בַּחֲדָרִים – בְּחַדְרוֹ בִּבְרָכָה, וְאִם אָסוּר – בַּחֲדַר הָאֹכֶל אוֹ בַּמְּבוֹאָה בִּבְרָכָה.","פֶּרֶק צ׳, הֲלָכָה ל״ה-ל״ו","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["מִי שֶׁשָּׁכַח ״עַל הַנִּסִּים״ בְּ״מוֹדִים״, וְנִזְכַּר לִפְנֵי שֶׁאָמַר שֵׁם ה׳ בְּסִיּוּם הַבְּרָכָה – מָה יַעֲשֶׂה?",["אֵינוֹ חוֹזֵר כְּלָל, וּמַמְשִׁיךְ אֶת הַתְּפִלָּה כָּרָגִיל","חוֹזֵר וְאוֹמֵר עַל הַנִּסִּים, כִּי עוֹד לֹא סִיֵּם","חוֹזֵר לִתְחִלַּת הַתְּפִלָּה וּמִתְפַּלֵּל אוֹתָהּ מֵחָדָשׁ","מְסַיֵּם אֶת הַבְּרָכָה וְאוֹמֵר עַל הַנִּסִּים אַחֲרֶיהָ"],1,"מִי שֶׁשָּׁכַח אֵינוֹ צָרִיךְ לַחְזֹר, אַךְ אִם נִזְכַּר לִפְנֵי שֶׁהִזְכִּיר אֶת שֵׁם ה׳ בְּסִיּוּם הַבְּרָכָה – חוֹזֵר.","פֶּרֶק צ׳, הֲלָכָה ל״ז","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["מִי שֶׁשָּׁכַח ״עַל הַנִּסִּים״ בַּתְּפִלָּה אוֹמֵר ״הָרַחֲמָן״ לִפְנֵי ״יִהְיוּ לְרָצוֹן״. וּמָה עוֹשֶׂה מִי שֶׁשָּׁכַח בְּבִרְכַּת הַמָּזוֹן?",["חוֹזֵר לִתְחִלַּת בִּרְכַּת הַמָּזוֹן וּמְבָרֵךְ שׁוּב","אוֹמֵר אֶת עַל הַנִּסִּים בְּסוֹף הַסְּעוּדָה הַבָּאָה","לֹא אוֹמֵר כְּלוּם, כִּי אֵין בָּהּ עַל הַנִּסִּים","מוֹסִיף בְּהָרַחֲמָן: הָרַחֲמָן הוּא יַעֲשֶׂה לָנוּ נִסִּים"],3,"גַּם בְּבִרְכַּת הַמָּזוֹן אוֹמְרִים עַל הַנִּסִּים, וּמִי שֶׁשָּׁכַח מוֹסִיף בְּ״הָרַחֲמָן״: ״הָרַחֲמָן הוּא יַעֲשֶׂה לָנוּ נִסִּים...״.","פֶּרֶק צ׳, הֲלָכָה ל״ח-ל״ט","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["בְּשַׁחֲרִית שֶׁל חֲנֻכָּה אוֹמְרִים הַלֵּל שָׁלֵם בִּבְרָכָה. וּמָה קוֹרְאִים בַּתּוֹרָה בְּכָל יוֹם?",["פָּרָשַׁת יְצִיאַת מִצְרַיִם וּקְרִיעַת יַם סוּף","פָּרָשַׁת חֲנֻכַּת הַמִּזְבֵּחַ וְקָרְבְּנוֹת הַנְּשִׂיאִים","אֶת סִפּוּר מַתַּן תּוֹרָה בְּהַר סִינַי","אֶת פָּרָשַׁת הַשָּׁבוּעַ בִּלְבַד, כְּמוֹ בְּכָל יוֹם"],1,"בְּכָל יוֹם קוֹרְאִים בְּפָרָשַׁת חֲנֻכַּת הַמִּזְבֵּחַ וְקָרְבְּנוֹת הַנְּשִׂיאִים (בְּמִדְבַּר פֶּרֶק ז).","פֶּרֶק צ׳, הֲלָכָה מ׳-מ״א","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["הַאִם חַיָּבִים לִקְבֹּעַ סְעוּדָה בַּחֲנֻכָּה?",["חוֹבָה גְּמוּרָה לֶאֱכֹל סְעוּדָה גְּדוֹלָה בְּכָל לַיְלָה וָלַיְלָה","אֵין חוֹבָה, וְעִם זְמִירוֹת וְדִבְרֵי תּוֹרָה הִיא מִצְוָה","אָסוּר לַעֲשׂוֹת סְעוּדוֹת בַּחֲנֻכָּה, כִּי אֵלּוּ יְמֵי הוֹדָאָה","מֻתָּר לֶאֱכֹל, אֲבָל אָסוּר לָשִׁיר זְמִירוֹת בַּסְּעוּדָה"],1,"אֵין חוֹבָה לִקְבֹּעַ סְעוּדָה, אַךְ אִם אוֹמְרִים בָּהּ זְמִירוֹת וְדִבְרֵי תּוֹרָה – הִיא נֶחְשֶׁבֶת סְעוּדַת מִצְוָה.","פֶּרֶק צ׳, הֲלָכָה מ״ב","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["בִּמְסִבַּת חֲנֻכָּה מַדְלִיקִים נֵרוֹת. מָתַי אֶפְשָׁר לְהַדְלִיק אוֹתָם בִּבְרָכָה?",["תָּמִיד, כִּי כָּל הַדְלָקָה שֶׁל חֲנֻכָּה הִיא מִצְוָה","רַק אִם יֵשׁ בַּמְּסִבָּה יוֹתֵר מִמֵּאָה אֲנָשִׁים","רַק אִם הַמְּסִבָּה נֶעֱרֶכֶת בְּבֵית הַסֵּפֶר","רַק אִם מִתְפַּלְּלִים שָׁם תְּפִלַּת עַרְבִית"],3,"אֵין מְבָרְכִים עַל נֵרוֹת בִּמְסִבּוֹת חֲנֻכָּה, אֲבָל אִם מִתְפַּלְּלִים שָׁם עַרְבִית – נִתָּן לְהַדְלִיק בִּבְרָכָה.","פֶּרֶק צ׳, הֲלָכָה מ״ג","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["מַה הַדִּין לְגַבֵּי הֶסְפֵּד וְתַעֲנִית בִּימֵי הַחֲנֻכָּה?",["מֻתָּר לְהִתְעַנּוֹת, אֲבָל אָסוּר לְהַסְפִּיד בַּחֲנֻכָּה","אָסוּר לְהַסְפִּיד וְאָסוּר לְהִתְעַנּוֹת בִּימֵי הַחֲנֻכָּה","מֻתָּר לְהַסְפִּיד, אֲבָל אָסוּר לְהִתְעַנּוֹת בַּחֲנֻכָּה","מֻתָּר גַּם לְהַסְפִּיד וְגַם לְהִתְעַנּוֹת כָּרָגִיל"],1,"בִּימֵי הַחֲנֻכָּה אָסוּר לְהַסְפִּיד וְאָסוּר לְהִתְעַנּוֹת.","פֶּרֶק צ׳, הֲלָכָה מ״ד","חֲנֻכָּה – שַׁבָּת, אוֹרְחִים וְעַל הַנִּסִּים"],["מַדּוּעַ קָבְעוּ חֲכָמִים אֶת רֹאשׁ הַשָּׁנָה לָאִילָנוֹת בְּט״וּ בִּשְׁבָט?",["כִּי בּוֹ נִבְרְאוּ כָּל הָעֵצִים בָּעוֹלָם","כִּי בּוֹ קוֹטְפִים אֶת כָּל הַפֵּרוֹת","רֹב הַגְּשָׁמִים יָרְדוּ וְהָאִילָנוֹת מַתְחִילִים לְהִתְחַדֵּשׁ","כִּי בּוֹ נִגְמָר הַחֹרֶף לְגַמְרֵי בָּאָרֶץ"],2,"עַד ט״וּ בִּשְׁבָט יוֹרְדִים רֹב הַגְּשָׁמִים, וְהָאִילָנוֹת מַתְחִילִים לְהִתְחַדֵּשׁ וּלְהוֹצִיא עָלִים וּפְרָחִים.","פֶּרֶק צ״א, הֲלָכָה א׳","ט״וּ בִּשְׁבָט"],["פְּרִי שֶׁחָנַט לִפְנֵי ט״וּ בִּשְׁבָט – לְאֵיזוֹ שָׁנָה הוּא שַׁיָּךְ?",["שַׁיָּךְ לַשָּׁנָה הַבָּאָה לְעִנְיַן תְּרוּמוֹת וּמַעַשְׂרוֹת","שַׁיָּךְ לַשָּׁנָה הַקּוֹדֶמֶת לְעִנְיַן תְּרוּמוֹת וּמַעַשְׂרוֹת","פָּטוּר לְגַמְרֵי מִתְּרוּמוֹת וּמִמַּעַשְׂרוֹת לְעוֹלָם","שַׁיָּךְ לִשְׁתֵּי הַשָּׁנִים יַחַד בְּשָׁוֶה"],1,"פֵּרוֹת שֶׁחָנְטוּ לִפְנֵי ט״וּ בִּשְׁבָט שַׁיָּכִים לַשָּׁנָה הַקּוֹדֶמֶת, וְאָסוּר לְהַפְרִישׁ מֵהֶם עַל פֵּרוֹת הַשָּׁנָה הַבָּאָה.","פֶּרֶק צ״א, הֲלָכָה א׳","ט״וּ בִּשְׁבָט"],["מַדּוּעַ עוֹד חָשׁוּב לָדַעַת לְאֵיזוֹ שָׁנָה שַׁיָּךְ הַפְּרִי?",["כִּי בְּכָל שָׁנָה צָרִיךְ לִנְטֹעַ עֵץ חָדָשׁ בַּגִּנָּה","כִּי בְּכָל שָׁנָה מְבָרְכִים עַל הַפֵּרוֹת בְּרָכָה אַחֶרֶת","כִּי בְּכָל שָׁנָה אוֹכְלִים רַק פְּרִי אֶחָד מְיֻחָד","כִּי יֵשׁ שָׁנִים שֶׁל מַעֲשֵׂר שֵׁנִי וְשֶׁל מַעְשַׂר עָנִי"],3,"בְּחֵלֶק מֵהַשָּׁנִים מַפְרִישִׁים מַעֲשֵׂר שֵׁנִי וּבְחֶלְקָן מַעְשַׂר עָנִי, לָכֵן צָרִיךְ לָדַעַת לְאֵיזוֹ שָׁנָה שַׁיָּךְ הַפְּרִי.","פֶּרֶק צ״א, הֲלָכָה א׳","ט״וּ בִּשְׁבָט"],["לְאֵיזֶה אִסּוּר נוֹסָף חֲשׁוּבָה קְבִיעַת רֹאשׁ הַשָּׁנָה לָאִילָנוֹת?",["אִסּוּר עָרְלָה שֶׁל פֵּרוֹת הָעֵץ","אִסּוּר לֶאֱכֹל בָּשָׂר עִם חָלָב","מִצְוַת נְטִילַת יָדַיִם לִפְנֵי הָאֹכֶל","מִצְוַת הַדְלָקַת נֵרוֹת בְּעֶרֶב שַׁבָּת"],0,"חֲשִׁיבוּת נוֹסֶפֶת לִקְבִיעַת הַשָּׁנָה הִיא לְעִנְיַן אִסּוּר עָרְלָה, שֶׁנִּלְמַד בְּפֶרֶק ק״ג.","פֶּרֶק צ״א, הֲלָכָה א׳","ט״וּ בִּשְׁבָט"],["מָה נוֹהֲגִים בְּט״וּ בִּשְׁבָט מִפְּנֵי שֶׁהוּא רֹאשׁ הַשָּׁנָה לָאִילָנוֹת?",["צָמִים כָּל הַיּוֹם וְאוֹמְרִים סְלִיחוֹת","אוֹמְרִים הַלֵּל שָׁלֵם עִם בְּרָכָה","אֵין אוֹמְרִים תַּחֲנוּן וְשׂוֹמְחִים בּוֹ קְצָת","תּוֹקְעִים בַּשּׁוֹפָר כְּמוֹ בְּרֹאשׁ הַשָּׁנָה"],2,"נָהֲגוּ לִשְׂמֹחַ בּוֹ קְצָת, וְאֵין אוֹמְרִים בּוֹ תַּחֲנוּן.","פֶּרֶק צ״א, הֲלָכָה ב׳","ט״וּ בִּשְׁבָט"],["מִי הִנְהִיג לְהַרְבּוֹת בַּאֲכִילַת פֵּרוֹת בְּט״וּ בִּשְׁבָט?",["הַמְּקֻבָּלִים, לִפְנֵי כַּמָּה מֵאוֹת שָׁנִים","מֹשֶׁה רַבֵּנוּ, בַּמִּדְבָּר לִפְנֵי הַכְּנִיסָה לָאָרֶץ","דָּוִד הַמֶּלֶךְ, בִּימֵי בֵּית הַמִּקְדָּשׁ","אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה בִּזְמַן הַמִּשְׁנָה"],0,"לִפְנֵי כַּמָּה מֵאוֹת שָׁנִים הִנְהִיגוּ הַמְּקֻבָּלִים לְהַרְבּוֹת בַּאֲכִילַת פֵּרוֹת, בְּמִיֻחָד מִשִּׁבְעַת הַמִּינִים.","פֶּרֶק צ״א, הֲלָכָה ג׳","ט״וּ בִּשְׁבָט"],["מָה מְסֻפָּר עַל רַבִּי אֶלְעָזָר?",["נָטַע עֵץ חָדָשׁ בְּכָל שָׁנָה בְּט״וּ בִּשְׁבָט","נָתַן אֶת כָּל פֵּרוֹתָיו לָעֲנִיִּים בְּיוֹם אֶחָד","צָם בְּכָל ט״וּ בִּשְׁבָט וְלֹא אָכַל פֵּרוֹת","חָסַךְ כֶּסֶף כְּדֵי לֶאֱכֹל מִכָּל פְּרִי פַּעַם בְּשָׁנָה"],3,"רַבִּי אֶלְעָזָר הָיָה חוֹסֵךְ כֶּסֶף כְּדֵי שֶׁיּוּכַל לֶאֱכֹל מִכָּל פְּרִי פַּעַם אַחַת בְּשָׁנָה – וְכָךְ לְשַׁבֵּחַ אֶת הַבּוֹרֵא עַל כָּל פְּרִי.","פֶּרֶק צ״א, הֲלָכָה ד׳","ט״וּ בִּשְׁבָט"],["הֵיכָן בַּסֵּפֶר מְפֹרָט סֵדֶר הַקְּדִימוּת בְּבִרְכוֹת הַפֵּרוֹת?",["סֵדֶר הַקְּדִימוּת מְפֹרָט בְּפֶרֶק ק״ג בַּסֵּפֶר","סֵדֶר הַקְּדִימוּת מְפֹרָט בְּפֶרֶק כ״ז בַּסֵּפֶר","סֵדֶר הַקְּדִימוּת מְפֹרָט בְּפֶרֶק ק״ד בַּסֵּפֶר","סֵדֶר הַקְּדִימוּת מְפֹרָט בְּפֶרֶק צ״א בַּסֵּפֶר"],1,"סֵדֶר הַקְּדִימוּת בְּבִרְכוֹת הַפֵּרוֹת הַשּׁוֹנִים מְפֹרָט בְּפֶרֶק כ״ז.","פֶּרֶק צ״א, הֲלָכָה ה׳","ט״וּ בִּשְׁבָט"]]};